INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'gardnerella-vaginalis-real-time-pcr'), 'Detection of Gardnerella vaginalis DNA by real-time PCR', 'Određivanje DNK bakterije Gardnerella vaginalis metodom PCR u realnom vremenu', 'Одређивање ДНК бактерије Gardnerella vaginalis методом ПЦР у реалном времену', 'Определение ДНК бактерии Gardnerella vaginalis методом ПЦР в реальном времени', 'Nachweis von Gardnerella-vaginalis-DNA mittels Real-Time-PCR', 'Gardnerella vaginalis bakterisinin DNA''sının gerçek zamanlı PCR yöntemiyle saptanması', 'A swab is taken from the vagina or urethra and the sample is processed in the laboratory', 'Uzima se bris iz vagine ili uretre, a uzorak se obrađuje u laboratoriji', 'Узима се брис из вагине или уретре, а узорак се обрађује у лабораторији', 'Берут мазок из влагалища или уретры, образец исследуют в лаборатории', 'Es wird ein Abstrich aus der Scheide oder der Harnröhre entnommen, die Probe wird im Labor untersucht', 'Vajinadan veya üretradan sürüntü alınır, örnek laboratuvarda incelenir', 'Discharge with an odour, itching and discomfort, examination before gynaecological procedures, pregnancy planning, follow-up after treatment', 'Sekret sa neprijatnim mirisom, svrab i nelagodnost, pregled prije ginekoloških zahvata, planiranje trudnoće, kontrola poslije liječenja', 'Секрет са непријатним мирисом, свраб и нелагодност, преглед прије гинеколошких захвата, планирање трудноће, контрола послије лијечења', 'Выделения с запахом, зуд и дискомфорт, обследование перед гинекологическими вмешательствами, планирование беременности, контроль после лечения', 'Ausfluss mit Geruch, Juckreiz und Beschwerden, Untersuchung vor gynäkologischen Eingriffen, Kinderwunsch, Kontrolle nach der Behandlung', 'Kokulu akıntı, kaşıntı ve rahatsızlık hissi, jinekolojik girişim öncesi değerlendirme, gebelik planlaması, tedavi sonrası kontrol', 'Women should be tested outside menstruation, for one day avoid intercourse, douching and vaginal products; do not urinate for 2–3 hours before a urethral swab', 'Žene se testiraju van menstruacije, dan ranije izbjegavati odnose, ispiranja i vaginalne preparate; ne mokriti 2–3 sata prije uzimanja brisa iz uretre', 'Жене се тестирају ван менструације, дан раније избјегавати односе, испирања и вагиналне препарате; не мокрити 2–3 сата прије узимања бриса из уретре', 'Женщинам сдавать вне менструации, за сутки исключить интимные контакты, спринцевания и вагинальные средства; не мочиться 2–3 часа до взятия мазка из уретры', 'Frauen außerhalb der Menstruation testen lassen, einen Tag vorher auf Geschlechtsverkehr, Spülungen und Vaginalpräparate verzichten; vor einem Harnröhrenabstrich 2–3 Stunden nicht urinieren', 'Kadınlarda adet dönemi dışında yapılır, bir gün önce cinsel ilişki, vajinal duş ve vajinal ürünlerden kaçınılır; üretra sürüntüsünden 2–3 saat önce idrara çıkılmamalıdır', 'Detection of the DNA may be related to a change in the vaginal microflora, and the bacterium is also found in small amounts without any complaints. The need for treatment is decided by a doctor', 'Nalaz DNK može biti povezan sa promjenom sastava vaginalne flore, a bakterija se u malom broju nalazi i bez tegoba. Potrebu za liječenjem procjenjuje ljekar', 'Налаз ДНК може бити повезан са промјеном састава вагиналне флоре, а бактерија се у малом броју налази и без тегоба. Потребу за лијечењем процјењује љекар', 'Обнаружение ДНК может быть связано с изменением состава микрофлоры влагалища, при этом бактерия в небольшом количестве встречается и без жалоб. Необходимость лечения определяет врач', 'Der Nachweis der DNA kann mit einer Veränderung der Scheidenflora zusammenhängen, das Bakterium kommt in geringer Menge auch ohne Beschwerden vor. Über die Behandlungsbedürftigkeit entscheidet der Arzt', 'DNA saptanması vajinal floranın değişmesiyle ilişkili olabilir, bakteri az miktarda şikayeti olmayan kişilerde de bulunur. Tedavi gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

