INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mycoplasma-genitalium-real-time-pcr'), 'Detection of Mycoplasma genitalium DNA by real-time PCR', 'Određivanje DNK bakterije Mycoplasma genitalium metodom PCR u realnom vremenu', 'Одређивање ДНК бактерије Mycoplasma genitalium методом ПЦР у реалном времену', 'Определение ДНК бактерии Mycoplasma genitalium методом ПЦР в реальном времени', 'Nachweis von Mycoplasma-genitalium-DNA mittels Real-Time-PCR', 'Mycoplasma genitalium bakterisinin DNA''sının gerçek zamanlı PCR yöntemiyle saptanması', 'A swab is taken from the urethra or cervical canal, or a first-catch urine sample is collected, and the sample is processed in the laboratory', 'Uzima se bris iz uretre ili cervikalnog kanala ili prva porcija mokraće, a uzorak se obrađuje u laboratoriji', 'Узима се брис из уретре или цервикалног канала или прва порција мокраће, а узорак се обрађује у лабораторији', 'Берут мазок из уретры или цервикального канала либо собирают первую порцию мочи, образец исследуют в лаборатории', 'Es wird ein Abstrich aus der Harnröhre oder dem Gebärmutterhalskanal entnommen oder Erststrahlurin gesammelt, die Probe wird im Labor untersucht', 'Üretradan veya servikal kanaldan sürüntü alınır ya da ilk idrar örneği toplanır, örnek laboratuvarda incelenir', 'Discharge, burning when urinating, discomfort in the lower abdomen, examination of partners, follow-up after treatment', 'Sekret, pečenje pri mokrenju, nelagodnost u donjem dijelu stomaka, ispitivanje partnera, kontrola poslije liječenja', 'Секрет, печење при мокрењу, нелагодност у доњем дијелу стомака, испитивање партнера, контрола послије лијечења', 'Выделения, жжение при мочеиспускании, дискомфорт внизу живота, обследование партнёров, контроль после лечения', 'Ausfluss, Brennen beim Wasserlassen, Beschwerden im Unterbauch, Untersuchung von Partnern, Kontrolle nach der Behandlung', 'Akıntı, idrar yaparken yanma, alt karın bölgesinde rahatsızlık, partner taraması, tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before a swab, for one day avoid intercourse and topical products; women should be tested outside menstruation', 'Ne mokriti 2–3 sata prije uzimanja brisa, dan ranije izbjegavati odnose i lokalne preparate; žene se testiraju van menstruacije', 'Не мокрити 2–3 сата прије узимања бриса, дан раније избјегавати односе и локалне препарате; жене се тестирају ван менструације', 'Не мочиться 2–3 часа до взятия мазка, за сутки исключить интимные контакты и местные средства; женщинам сдавать вне менструации', 'Vor einem Abstrich 2–3 Stunden nicht urinieren, einen Tag vorher auf Geschlechtsverkehr und lokale Präparate verzichten; Frauen außerhalb der Menstruation testen lassen', 'Sürüntüden 2–3 saat önce idrara çıkılmamalı, bir gün önce cinsel ilişki ve bölgesel ürünlerden kaçınılmalıdır; kadınlarda adet dönemi dışında yapılır', 'Detection of the DNA means the microorganism is present in the sample taken. Decisions about treatment and about examining a partner are made by a doctor', 'Nalaz DNK znači da je uzročnik prisutan u ispitivanom materijalu. Odluku o liječenju i o pregledu partnera donosi ljekar', 'Налаз ДНК значи да је узрочник присутан у испитиваном материјалу. Одлуку о лијечењу и о прегледу партнера доноси љекар', 'Обнаружение ДНК означает, что возбудитель присутствует в исследованном материале. Решение о лечении и об обследовании партнёра принимает врач', 'Der Nachweis der DNA bedeutet, dass der Erreger im untersuchten Material vorhanden ist. Über die Behandlung und die Untersuchung des Partners entscheidet der Arzt', 'DNA saptanması, etkenin incelenen örnekte bulunduğu anlamına gelir. Tedavi ve partnerin incelenmesi konusundaki kararı hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mycoplasma-hominis-real-time-pcr'), 'Detection of Mycoplasma hominis DNA by real-time PCR', 'Određivanje DNK bakterije Mycoplasma hominis metodom PCR u realnom vremenu', 'Одређивање ДНК бактерије Mycoplasma hominis методом ПЦР у реалном времену', 'Определение ДНК бактерии Mycoplasma hominis методом ПЦР в реальном времени', 'Nachweis von Mycoplasma-hominis-DNA mittels Real-Time-PCR', 'Mycoplasma hominis bakterisinin DNA''sının gerçek zamanlı PCR yöntemiyle saptanması', 'A swab is taken from the vagina, cervical canal or urethra and the sample is processed in the laboratory', 'Uzima se bris iz vagine, cervikalnog kanala ili uretre, a uzorak se obrađuje u laboratoriji', 'Узима се брис из вагине, цервикалног канала или уретре, а узорак се обрађује у лабораторији', 'Берут мазок из влагалища, цервикального канала или уретры, образец исследуют в лаборатории', 'Es wird ein Abstrich aus der Scheide, dem Gebärmutterhalskanal oder der Harnröhre entnommen, die Probe wird im Labor untersucht', 'Vajinadan, servikal kanaldan veya üretradan sürüntü alınır, örnek laboratuvarda incelenir', 'Evaluation of inflammatory conditions of the urogenital tract, preparation for gynaecological procedures, pregnancy planning, disturbed microflora', 'Ispitivanje kod zapaljenskih stanja mokraćno-polnog sistema, priprema za ginekološke zahvate, planiranje trudnoće, poremećaj mikroflore', 'Испитивање код запаљенских стања мокраћно-полног система, припрема за гинеколошке захвате, планирање трудноће, поремећај микрофлоре', 'Обследование при воспалительных состояниях мочеполовой системы, подготовка к гинекологическим вмешательствам, планирование беременности, нарушение микрофлоры', 'Abklärung entzündlicher Veränderungen im Urogenitalbereich, Vorbereitung auf gynäkologische Eingriffe, Kinderwunsch, gestörte Scheidenflora', 'Ürogenital sistemdeki iltihabi durumların araştırılması, jinekolojik girişim öncesi hazırlık, gebelik planlaması, flora bozukluğu', 'Women should be tested outside menstruation, for one day avoid intercourse, douching and topical products; do not urinate for 2–3 hours before a urethral swab', 'Žene se testiraju van menstruacije, dan ranije izbjegavati odnose, ispiranja i lokalne preparate; ne mokriti 2–3 sata prije uzimanja brisa iz uretre', 'Жене се тестирају ван менструације, дан раније избјегавати односе, испирања и локалне препарате; не мокрити 2–3 сата прије узимања бриса из уретре', 'Женщинам сдавать вне менструации, за сутки исключить интимные контакты, спринцевания и местные средства; не мочиться 2–3 часа до взятия мазка из уретры', 'Frauen außerhalb der Menstruation testen lassen, einen Tag vorher auf Geschlechtsverkehr, Spülungen und lokale Präparate verzichten; vor einem Harnröhrenabstrich 2–3 Stunden nicht urinieren', 'Kadınlarda adet dönemi dışında yapılır, bir gün önce cinsel ilişki, vajinal duş ve bölgesel ürünlerden kaçınılır; üretra sürüntüsünden 2–3 saat önce idrara çıkılmamalıdır', 'Detection of the DNA may be related both to an inflammatory process and to carriage without any complaints, so the result is assessed together with symptoms and other tests. Further steps are decided by a doctor', 'Nalaz DNK može biti povezan i sa zapaljenskim procesom i sa kliconoštvom bez tegoba, pa se rezultat procjenjuje zajedno sa simptomima i drugim analizama. Dalju taktiku određuje ljekar', 'Налаз ДНК може бити повезан и са запаљенским процесом и са клицоноштвом без тегоба, па се резултат процјењује заједно са симптомима и другим анализама. Даљу тактику одређује љекар', 'Обнаружение ДНК может быть связано как с воспалительным процессом, так и с носительством без жалоб, поэтому результат оценивают вместе с симптомами и другими анализами. Дальнейшую тактику определяет врач', 'Der Nachweis der DNA kann sowohl mit einem entzündlichen Prozess als auch mit einer Besiedlung ohne Beschwerden zusammenhängen, daher wird das Ergebnis zusammen mit den Beschwerden und weiteren Untersuchungen beurteilt. Das weitere Vorgehen bestimmt der Arzt', 'DNA saptanması hem iltihabi bir süreçle hem de şikayeti olmayan taşıyıcılıkla ilişkili olabilir, bu nedenle sonuç belirtiler ve diğer testlerle birlikte değerlendirilir. Sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'parvovirus-b19-igg'), 'Blood test for IgG class antibodies against parvovirus B19, the cause of erythema infectiosum', 'Analiza krvi na antitijela klase IgG na parvovirus B19, uzročnika infektivnog eritema', 'Анализа крви на антитијела класе IgG на парвовирус Б19, узрочника инфективног еритема', 'Анализ крови на антитела класса IgG к парвовирусу B19, возбудителю инфекционной эритемы', 'Bluttest auf Antikörper der Klasse IgG gegen Parvovirus B19, den Erreger der Ringelröteln', 'Eritema enfeksiyozum etkeni parvovirus B19''a karşı IgG sınıfı antikorlar için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert wenige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing past contact with the virus, evaluation in pregnancy after contact with a child who is ill, rash and joint pain, work-up of anaemia of unclear cause', 'Procjena ranijeg kontakta sa virusom, ispitivanje u trudnoći poslije kontakta sa oboljelim djetetom, osip i bolovi u zglobovima, ispitivanje anemije nejasnog uzroka', 'Процјена ранијег контакта са вирусом, испитивање у трудноћи послије контакта са обољелим дјететом, осип и болови у зглобовима, испитивање анемије нејасног узрока', 'Оценка перенесённого ранее контакта с вирусом, обследование при беременности после контакта с заболевшим ребёнком, сыпь и боли в суставах, обследование при анемии неясной причины', 'Beurteilung eines früheren Kontakts mit dem Virus, Abklärung in der Schwangerschaft nach Kontakt mit einem erkrankten Kind, Hautausschlag und Gelenkschmerzen, Abklärung einer Blutarmut unklarer Ursache', 'Virüsle geçmişteki temasın değerlendirilmesi, gebelikte hasta bir çocukla temas sonrası inceleme, döküntü ve eklem ağrıları, nedeni belirsiz kansızlığın araştırılması', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of IgG usually points to contact with the virus in the past. The need for additional tests, especially during pregnancy, is decided by a doctor', 'Prisustvo IgG obično ukazuje na raniji kontakt sa virusom. Potrebu za dodatnim analizama, naročito u trudnoći, procjenjuje ljekar', 'Присуство IgG обично указује на ранији контакт са вирусом. Потребу за додатним анализама, нарочито у трудноћи, процјењује љекар', 'Наличие IgG обычно указывает на контакт с вирусом в прошлом. Необходимость дополнительных анализов, особенно при беременности, определяет врач', 'Nachweisbare IgG sprechen in der Regel für einen früheren Kontakt mit dem Virus. Über weitere Untersuchungen, besonders in der Schwangerschaft, entscheidet der Arzt', 'IgG varlığı genellikle virüsle geçmişte temas edildiğini gösterir. Ek testlerin gerekip gerekmediğine, özellikle gebelikte, hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'trichomonas-vaginalis-real-time-pcr'), 'Detection of Trichomonas vaginalis DNA by real-time PCR', 'Određivanje DNK parazita Trichomonas vaginalis metodom PCR u realnom vremenu', 'Одређивање ДНК паразита Trichomonas vaginalis методом ПЦР у реалном времену', 'Определение ДНК простейшего Trichomonas vaginalis методом ПЦР в реальном времени', 'Nachweis von Trichomonas-vaginalis-DNA mittels Real-Time-PCR', 'Trichomonas vaginalis parazitinin DNA''sının gerçek zamanlı PCR yöntemiyle saptanması', 'A swab is taken from the vagina or urethra or a urine sample is collected, and the sample is processed in the laboratory', 'Uzima se bris iz vagine ili uretre ili uzorak mokraće, a materijal se obrađuje u laboratoriji', 'Узима се брис из вагине или уретре или узорак мокраће, а материјал се обрађује у лабораторији', 'Берут мазок из влагалища или уретры либо собирают порцию мочи, образец исследуют в лаборатории', 'Es wird ein Abstrich aus der Scheide oder der Harnröhre entnommen oder eine Urinprobe gesammelt, die Probe wird im Labor untersucht', 'Vajinadan veya üretradan sürüntü alınır ya da idrar örneği toplanır, örnek laboratuvarda incelenir', 'Discharge, itching and burning, discomfort when urinating, examination of partners, routine check of the urogenital tract', 'Sekret, svrab i pečenje, nelagodnost pri mokrenju, ispitivanje partnera, preventivna provjera mokraćno-polnog sistema', 'Секрет, свраб и печење, нелагодност при мокрењу, испитивање партнера, превентивна провјера мокраћно-полног система', 'Выделения, зуд и жжение, дискомфорт при мочеиспускании, обследование партнёров, профилактическая проверка мочеполовой системы', 'Ausfluss, Juckreiz und Brennen, Beschwerden beim Wasserlassen, Untersuchung von Partnern, routinemäßige Kontrolle des Urogenitalbereichs', 'Akıntı, kaşıntı ve yanma, idrar yaparken rahatsızlık, partner taraması, ürogenital sistemin rutin kontrolü', 'Do not urinate for 2–3 hours before a swab, for one day avoid intercourse, douching and topical products; women should be tested outside menstruation', 'Ne mokriti 2–3 sata prije uzimanja brisa, dan ranije izbjegavati odnose, ispiranja i lokalne preparate; žene se testiraju van menstruacije', 'Не мокрити 2–3 сата прије узимања бриса, дан раније избјегавати односе, испирања и локалне препарате; жене се тестирају ван менструације', 'Не мочиться 2–3 часа до взятия мазка, за сутки исключить интимные контакты, спринцевания и местные средства; женщинам сдавать вне менструации', 'Vor einem Abstrich 2–3 Stunden nicht urinieren, einen Tag vorher auf Geschlechtsverkehr, Spülungen und lokale Präparate verzichten; Frauen außerhalb der Menstruation testen lassen', 'Sürüntüden 2–3 saat önce idrara çıkılmamalı, bir gün önce cinsel ilişki, vajinal duş ve bölgesel ürünlerden kaçınılmalıdır; kadınlarda adet dönemi dışında yapılır', 'Detection of the DNA means the microorganism is present in the sample taken. Further steps, including examination of a partner, are decided by a doctor', 'Nalaz DNK znači da je uzročnik prisutan u ispitivanom materijalu. Dalje korake, uključujući pregled partnera, određuje ljekar', 'Налаз ДНК значи да је узрочник присутан у испитиваном материјалу. Даље кораке, укључујући преглед партнера, одређује љекар', 'Обнаружение ДНК означает, что возбудитель присутствует в исследованном материале. Дальнейшие шаги, включая обследование партнёра, определяет врач', 'Der Nachweis der DNA bedeutet, dass der Erreger im untersuchten Material vorhanden ist. Das weitere Vorgehen, einschließlich der Untersuchung des Partners, bestimmt der Arzt', 'DNA saptanması, etkenin incelenen örnekte bulunduğu anlamına gelir. Partnerin incelenmesi dahil sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ureaplasma-urealyticum-pcr'), 'Molecular test that detects DNA of the bacterium Ureaplasma urealyticum in a urogenital sample', 'Molekularni test koji otkriva DNK bakterije Ureaplasma urealyticum u urogenitalnom uzorku', 'Молекуларни тест који открива ДНК бактерије Ureaplasma urealyticum у урогениталном узорку', 'Молекулярный тест, выявляющий ДНК бактерии Ureaplasma urealyticum в урогенитальном материале', 'Molekularer Test, der DNA des Bakteriums Ureaplasma urealyticum in einer urogenitalen Probe nachweist', 'Ürogenital örnekte Ureaplasma urealyticum bakterisinin DNA molekülünü arayan moleküler test', 'Swab from the urethra or cervical canal, or a first-morning urine portion, followed by PCR analysis in the laboratory', 'Bris uretre ili cervikalnog kanala ili prvi jutarnji mlaz mokraće, nakon čega slijedi PCR analiza u laboratoriji', 'Брис уретре или цервикалног канала или први јутарњи млаз мокраће, након чега слиједи ПЦР анализа у лабораторији', 'Мазок из уретры или цервикального канала либо первая порция утренней мочи, далее исследование методом ПЦР в лаборатории', 'Abstrich aus Harnröhre oder Gebärmutterhalskanal oder erster Morgenurin, anschließend PCR-Analyse im Labor', 'Üretra veya servikal kanaldan sürüntü ya da sabah ilk idrar örneği alınır, ardından laboratuvarda PCR ile incelenir', 'Discharge, discomfort when urinating, pregnancy planning, infertility work-up, examination of a partner, follow-up after treatment', 'Sekret, nelagoda pri mokrenju, planiranje trudnoće, obrada zbog neplodnosti, pregled partnera, kontrola poslije terapije', 'Секрет, нелагода при мокрењу, планирање трудноће, обрада због неплодности, преглед партнера, контрола послије терапије', 'Выделения, дискомфорт при мочеиспускании, планирование беременности, обследование при бесплодии, обследование партнёра, контроль после лечения', 'Ausfluss, Beschwerden beim Wasserlassen, Kinderwunsch, Abklärung bei unerfülltem Kinderwunsch, Untersuchung des Partners, Kontrolle nach einer Behandlung', 'Akıntı, idrar yaparken rahatsızlık, gebelik planlaması, kısırlık araştırması, eşin incelenmesi, tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the swab or urine sample, women outside menstruation days; the interval after antibacterial medicines is set by the doctor', 'Ne mokriti 2–3 sata prije uzimanja brisa ili mokraće, žene van dana menstruacije; rok poslije uzimanja antibakterijskih lijekova određuje ljekar', 'Не мокрити 2–3 сата прије узимања бриса или мокраће, жене ван дана менструације; рок послије узимања антибактеријских лијекова одређује љекар', 'Не мочиться 2–3 часа перед сдачей мазка или мочи, женщинам — вне дней менструации; сроки после приёма антибактериальных препаратов уточняет врач', '2–3 Stunden vor dem Abstrich oder der Urinprobe nicht Wasser lassen, Frauen außerhalb der Menstruationstage; den Abstand zu antibakteriellen Medikamenten legt der Arzt fest', 'Sürüntü veya idrar örneğinden 2–3 saat önce idrara çıkılmamalı, kadınlarda adet günleri dışında alınmalıdır; antibakteriyel ilaçlardan sonraki bekleme süresini hekim belirler', 'Detection of DNA means the microorganism is present in the sample, and it also occurs without any complaints. The clinical significance of the result and the need to examine a partner are assessed by a doctor', 'Nalaz DNK znači da je mikroorganizam prisutan u uzorku, a nalazi se i bez tegoba. Klinički značaj nalaza i potrebu pregleda partnera procjenjuje ljekar', 'Налаз ДНК значи да је микроорганизам присутан у узорку, а налази се и без тегоба. Клинички значај налаза и потребу прегледа партнера процјењује љекар', 'Обнаружение ДНК означает присутствие микроорганизма в пробе, который встречается и без жалоб. Клиническое значение результата и необходимость обследования партнёра оценивает врач', 'Ein DNA-Nachweis bedeutet, dass der Erreger in der Probe vorhanden ist, er kommt auch ohne Beschwerden vor. Die klinische Bedeutung und die Notwendigkeit einer Partneruntersuchung beurteilt der Arzt', 'DNA saptanması mikroorganizmanın örnekte bulunduğunu gösterir ve şikayet olmadan da görülebilir. Sonucun klinik önemini ve eşin incelenmesi gerekip gerekmediğini hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'varicella-zoster-virus-igg'), 'Blood test for IgG class antibodies to the varicella zoster virus', 'Analiza krvi na antitijela klase IgG na virus varičele i herpesa zostera', 'Анализа крви на антитијела класе IgG на вирус варичеле и херпеса зостера', 'Анализ крови на антитела класса IgG к вирусу ветряной оспы и опоясывающего лишая', 'Bluttest auf Antikörper der Klasse IgG gegen das Varizella-Zoster-Virus', 'Suçiçeği ve zona etkeni virüse karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Assessment of immune status before vaccination, pregnancy planning, examination of healthcare workers, contact with an ill person, preparation for immunosuppressive therapy', 'Procjena imunskog statusa prije vakcinacije, planiranje trudnoće, pregled zdravstvenih radnika, kontakt sa oboljelim, priprema za imunosupresivnu terapiju', 'Процјена имунског статуса прије вакцинације, планирање трудноће, преглед здравствених радника, контакт са обољелим, припрема за имуносупресивну терапију', 'Оценка иммунного статуса перед вакцинацией, планирование беременности, обследование медицинских работников, контакт с заболевшим, подготовка к иммуносупрессивной терапии', 'Beurteilung des Immunstatus vor einer Impfung, Kinderwunsch, Untersuchung von medizinischem Personal, Kontakt zu einer erkrankten Person, Vorbereitung auf eine immunsuppressive Therapie', 'Aşı öncesi bağışıklık durumunun değerlendirilmesi, gebelik planlaması, sağlık çalışanlarının taranması, hasta biriyle temas, bağışıklığı baskılayan tedavi öncesi hazırlık', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence or absence of IgG may be related to an earlier contact with the virus or to vaccination. Conclusions about immune status are made by a doctor taking the history into account', 'Prisustvo ili odsustvo IgG može biti povezano sa ranijim kontaktom sa virusom ili sa vakcinacijom. Zaključak o imunskom statusu donosi ljekar uzimajući u obzir anamnezu', 'Присуство или одсуство IgG може бити повезано са ранијим контактом са вирусом или са вакцинацијом. Закључак о имунском статусу доноси љекар узимајући у обзир анамнезу', 'Наличие или отсутствие IgG может быть связано с перенесённым ранее контактом с вирусом или с вакцинацией. Вывод об иммунном статусе делает врач с учётом анамнеза', 'Das Vorhandensein oder Fehlen von IgG kann mit einem früheren Kontakt mit dem Virus oder mit einer Impfung zusammenhängen. Die Einschätzung des Immunstatus trifft der Arzt unter Berücksichtigung der Vorgeschichte', 'IgG bulunması veya bulunmaması virüsle daha önceki temas ya da aşılanma ile ilişkili olabilir. Bağışıklık durumu hakkındaki değerlendirmeyi, öyküyü de dikkate alarak hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'varicella-zoster-virus-igm'), 'Blood test for IgM class antibodies to the varicella zoster virus, which appear after a recent contact with the virus', 'Analiza krvi na antitijela klase IgM na virus varičele i zostera, koja se javljaju pri nedavnom kontaktu sa virusom', 'Анализа крви на антитијела класе IgM на вирус варичеле и зостера, која се јављају при недавном контакту са вирусом', 'Анализ крови на антитела класса IgM к вирусу ветряной оспы и опоясывающего лишая, которые появляются при недавнем контакте с вирусом', 'Bluttest auf Antikörper der Klasse IgM gegen das Varizella-Zoster-Virus, die bei einem kürzlichen Kontakt mit dem Virus auftreten', 'Suçiçeği ve zona etkeni virüse karşı, yakın zamanlı temasta ortaya çıkan IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Rash of unclear origin, suspected recent infection, work-up of shingles, contact with an ill person during pregnancy', 'Osip nejasnog porijekla, sumnja na nedavnu infekciju, obrada kod herpesa zostera, kontakt sa oboljelim u trudnoći', 'Осип нејасног поријекла, сумња на недавну инфекцију, обрада код херпеса зостера, контакт са обољелим у трудноћи', 'Сыпь неясного происхождения, подозрение на недавнее заражение, обследование при опоясывающем лишае, контакт с заболевшим во время беременности', 'Hautausschlag unklarer Ursache, Verdacht auf eine kürzliche Infektion, Abklärung bei Gürtelrose, Kontakt zu einer erkrankten Person in der Schwangerschaft', 'Nedeni belirsiz döküntü, yakın zamanda geçirilmiş enfeksiyon şüphesi, zona araştırması, gebelikte hasta biriyle temas', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The result may be related to a recent contact with the virus or to its reactivation, and cross-reactions also occur. It is interpreted by a doctor together with IgG and the clinical picture', 'Nalaz može biti povezan sa nedavnim kontaktom sa virusom ili sa njegovom reaktivacijom, a moguće su i unakrsne reakcije. Nalaz tumači ljekar zajedno sa IgG i kliničkom slikom', 'Налаз може бити повезан са недавним контактом са вирусом или са његовом реактивацијом, а могуће су и унакрсне реакције. Налаз тумачи љекар заједно са IgG и клиничком сликом', 'Результат может быть связан с недавним контактом с вирусом или с его реактивацией, встречаются и перекрёстные реакции. Оценивает результат врач вместе с IgG и клинической картиной', 'Das Ergebnis kann mit einem kürzlichen Kontakt mit dem Virus oder einer Reaktivierung zusammenhängen, auch Kreuzreaktionen kommen vor. Die Beurteilung erfolgt durch den Arzt zusammen mit IgG und dem klinischen Bild', 'Sonuç virüsle yakın zamanlı temas veya virüsün yeniden etkinleşmesi ile ilişkili olabilir, çapraz reaksiyonlar da görülebilir. Değerlendirmeyi IgG ve klinik tabloyla birlikte hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-sars-cov'), 'Blood test for antibodies to the SARS-CoV-2 coronavirus', 'Analiza krvi na antitijela na koronavirus SARS-CoV-2', 'Анализа крви на антитијела на коронавирус SARS-CoV-2', 'Анализ крови на антитела к коронавирусу SARS-CoV-2', 'Bluttest auf Antikörper gegen das Coronavirus SARS-CoV-2', 'SARS-CoV-2 koronavirüsüne karşı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Assessment of past contact with the virus, situation after an illness or vaccination, epidemiological examinations', 'Procjena ranijeg kontakta sa virusom, stanje poslije preboljele infekcije ili vakcinacije, epidemiološka ispitivanja', 'Процјена ранијег контакта са вирусом, стање послије пребољеле инфекције или вакцинације, епидемиолошка испитивања', 'Оценка контакта с вирусом в прошлом, ситуация после перенесённого заболевания или вакцинации, эпидемиологические обследования', 'Beurteilung eines früheren Kontakts mit dem Virus, Situation nach durchgemachter Erkrankung oder Impfung, epidemiologische Untersuchungen', 'Virüsle geçmişteki temasın değerlendirilmesi, hastalık veya aşı sonrası durum, salgın araştırmaları', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of antibodies may be related to a past infection or to vaccination and does not on its own measure the degree of protection. The result is interpreted by a doctor', 'Prisustvo antitijela može biti povezano sa preboljelom infekcijom ili sa vakcinacijom i samo po sebi ne mjeri stepen zaštite. Nalaz tumači ljekar', 'Присуство антитијела може бити повезано са пребољелом инфекцијом или са вакцинацијом и само по себи не мјери степен заштите. Налаз тумачи љекар', 'Наличие антител может быть связано с перенесённой инфекцией или с вакцинацией и само по себе не измеряет степень защиты. Трактует результат врач', 'Das Vorhandensein von Antikörpern kann mit einer durchgemachten Infektion oder einer Impfung zusammenhängen und misst für sich allein nicht den Grad des Schutzes. Das Ergebnis beurteilt der Arzt', 'Antikor bulunması geçirilmiş enfeksiyon veya aşılanma ile ilişkili olabilir ve tek başına korunma düzeyini ölçmez. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'campylobacter-culture'), 'Stool culture for Campylobacter, one of the common causes of intestinal infections', 'Bakteriološka kultura stolice na kampilobakter, jedan od čestih uzroka crijevnih infekcija', 'Бактериолошка култура столице на кампилобактер, један од честих узрока цријевних инфекција', 'Бактериологический посев кала на кампилобактер, одну из частых причин кишечных инфекций', 'Stuhlkultur auf Campylobacter, einen der häufigen Erreger von Darminfektionen', 'Bağırsak enfeksiyonlarının sık nedenlerinden biri olan Campylobacter için dışkı kültürü', 'The stool sample is cultured on selective media under special incubation conditions, the result takes several days', 'Uzorak stolice se zasijava na selektivne podloge u posebnim uslovima inkubacije, nalaz se čeka nekoliko dana', 'Узорак столице се засијава на селективне подлоге у посебним условима инкубације, налаз се чека неколико дана', 'Образец кала высевают на селективные среды в особых условиях инкубации, результат готовится несколько дней', 'Die Stuhlprobe wird auf Selektivnährböden unter besonderen Bebrütungsbedingungen angezüchtet, das Ergebnis dauert mehrere Tage', 'Dışkı örneği özel inkübasyon koşullarında seçici besiyerlerine ekilir, sonuç birkaç gün sürer', 'Prolonged diarrhoea, bowel complaints after travel or after eating undercooked poultry, examination during outbreaks, occupational health certificates', 'Dugotrajni proliv, crijevne tegobe poslije putovanja ili nedovoljno termički obrađenog pilećeg mesa, ispitivanje kod epidemija, sanitarni pregled', 'Дуготрајни пролив, цријевне тегобе послије путовања или недовољно термички обрађеног пилећег меса, испитивање код епидемија, санитарни преглед', 'Длительная диарея, кишечные жалобы после поездки или употребления недостаточно термически обработанной птицы, обследование при вспышках, оформление санитарной книжки', 'Anhaltender Durchfall, Darmbeschwerden nach einer Reise oder nach nicht ausreichend gegartem Geflügel, Untersuchung bei Ausbrüchen, Gesundheitszeugnis für die Arbeit', 'Uzun süren ishal, seyahat sonrası veya yeterince pişmemiş tavuk sonrası bağırsak şikayetleri, salgın araştırmaları, portör muayenesi', 'Collect the stool in a container from the laboratory, before starting antibacterial therapy or at the time indicated by the doctor, and deliver the sample the same day', 'Stolicu sakupiti u posudu iz laboratorije, prije početka antibakterijske terapije ili u roku koji odredi ljekar, i dostaviti je istog dana', 'Столицу сакупити у посуду из лабораторије, прије почетка антибактеријске терапије или у року који одреди љекар, и доставити је истог дана', 'Кал собирают в контейнер из лаборатории, до начала антибактериальной терапии либо в сроки, которые укажет врач, и доставляют в лабораторию в тот же день', 'Stuhl im Behälter aus dem Labor sammeln, vor Beginn einer antibakteriellen Therapie oder zu dem vom Arzt genannten Zeitpunkt, und die Probe am selben Tag abgeben', 'Dışkı laboratuvardan alınan kaba, antibakteriyel tedaviye başlamadan önce ya da hekimin belirttiği sürede toplanmalı ve aynı gün laboratuvara ulaştırılmalıdır', 'Growth of the bacterium in the culture may be related to an intestinal infection, while absence of growth does not rule it out. Further management is decided by a doctor', 'Porast bakterije u kulturi može biti povezan sa crijevnom infekcijom, dok izostanak porasta ne isključuje infekciju. Dalji postupak određuje ljekar', 'Пораст бактерије у култури може бити повезан са цријевном инфекцијом, док изостанак пораста не искључује инфекцију. Даљи поступак одређује љекар', 'Рост бактерии в посеве может быть связан с кишечной инфекцией, а отсутствие роста её не исключает. Дальнейшую тактику определяет врач', 'Ein Wachstum des Erregers in der Kultur kann mit einer Darminfektion zusammenhängen, ein fehlendes Wachstum schließt sie nicht aus. Das weitere Vorgehen legt der Arzt fest', 'Kültürde bakteri üremesi bağırsak enfeksiyonu ile ilişkili olabilir, üreme olmaması ise enfeksiyonu dışlamaz. İzlenecek yolu hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chlamydia-trachomatis-real-time-pcr'), 'Molecular test that detects DNA of the bacterium Chlamydia trachomatis by real-time PCR', 'Molekularni test koji otkriva DNK bakterije Chlamydia trachomatis metodom PCR u realnom vremenu', 'Молекуларни тест који открива ДНК бактерије Chlamydia trachomatis методом ПЦР у реалном времену', 'Молекулярный тест, выявляющий ДНК бактерии Chlamydia trachomatis методом ПЦР в реальном времени', 'Molekularer Test, der DNA des Bakteriums Chlamydia trachomatis mittels Real-Time-PCR nachweist', 'Chlamydia trachomatis bakterisini gerçek zamanlı PCR yöntemiyle saptayan moleküler test', 'Swab from the urethra or cervical canal, or a first urine portion, the analysis is run in the laboratory in a closed system', 'Bris uretre ili cervikalnog kanala ili prvi mlaz mokraće, analiza se radi u laboratoriji u zatvorenom sistemu', 'Брис уретре или цервикалног канала или први млаз мокраће, анализа се ради у лабораторији у затвореном систему', 'Мазок из уретры или цервикального канала либо первая порция мочи, анализ выполняется в лаборатории в закрытой системе', 'Abstrich aus Harnröhre oder Gebärmutterhalskanal oder erste Urinportion, die Analyse erfolgt im Labor in einem geschlossenen System', 'Üretra veya servikal kanaldan sürüntü ya da ilk idrar örneği alınır, analiz laboratuvarda kapalı sistemde yapılır', 'Discharge, lower abdominal pain, discomfort when urinating, screening when planning a pregnancy, infertility work-up, examination of a partner', 'Sekret, bol u donjem dijelu trbuha, nelagoda pri mokrenju, skrining pri planiranju trudnoće, obrada zbog neplodnosti, pregled partnera', 'Секрет, бол у доњем дијелу трбуха, нелагода при мокрењу, скрининг при планирању трудноће, обрада због неплодности, преглед партнера', 'Выделения, боль внизу живота, дискомфорт при мочеиспускании, скрининг при планировании беременности, обследование при бесплодии, обследование партнёра', 'Ausfluss, Schmerzen im Unterbauch, Beschwerden beim Wasserlassen, Screening bei Kinderwunsch, Abklärung bei unerfülltem Kinderwunsch, Untersuchung des Partners', 'Akıntı, karın alt bölgesinde ağrı, idrar yaparken rahatsızlık, gebelik planlarken tarama, kısırlık araştırması, eşin incelenmesi', 'Do not urinate for 2–3 hours before the sample, women outside menstruation days and without prior douching; the interval after antibacterial medicines is set by the doctor', 'Ne mokriti 2–3 sata prije uzimanja uzorka, žene van dana menstruacije i bez prethodnog ispiranja; razmak poslije antibakterijskih lijekova određuje ljekar', 'Не мокрити 2–3 сата прије узимања узорка, жене ван дана менструације и без претходног испирања; размак послије антибактеријских лијекова одређује љекар', 'Не мочиться 2–3 часа перед сдачей, женщинам — вне дней менструации и без предварительного спринцевания; интервал после антибактериальных препаратов уточняет врач', '2–3 Stunden vor der Probenentnahme nicht Wasser lassen, Frauen außerhalb der Menstruationstage und ohne vorherige Spülung; den Abstand zu antibakteriellen Medikamenten legt der Arzt fest', 'Örnek vermeden 2–3 saat önce idrara çıkılmamalı, kadınlarda adet günleri dışında ve öncesinde vajinal duş yapılmadan alınmalıdır; antibakteriyel ilaçlardan sonraki aralığı hekim belirler', 'Detection of DNA means the bacterium is present in the sample. Further examination, including that of a partner, and follow-up are prescribed by a doctor', 'Nalaz DNK znači da je bakterija prisutna u uzorku. Dalju obradu, uključujući pregled partnera, i kontrolu određuje ljekar', 'Налаз ДНК значи да је бактерија присутна у узорку. Даљу обраду, укључујући преглед партнера, и контролу одређује љекар', 'Обнаружение ДНК означает присутствие бактерии в пробе. Дальнейшее обследование, в том числе партнёра, и контроль назначает врач', 'Ein DNA-Nachweis bedeutet, dass das Bakterium in der Probe vorhanden ist. Die weitere Abklärung, auch des Partners, und die Kontrolle legt der Arzt fest', 'DNA saptanması bakterinin örnekte bulunduğunu gösterir. Eşin incelenmesi dahil ileri tetkikleri ve kontrolü hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'echinococcus-igg-elisa'), 'Blood test for IgG class antibodies to Echinococcus using the ELISA method', 'Analiza krvi na antitijela klase IgG na ehinokok ELISA metodom', 'Анализа крви на антитијела класе IgG на ехинокок ELISA методом', 'Анализ крови на антитела класса IgG к эхинококку методом ELISA', 'Bluttest auf Antikörper der Klasse IgG gegen Echinokokken mittels ELISA', 'Ekinokok parazitine karşı IgG sınıfı antikorları ELISA yöntemiyle ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'A cystic lesion in the liver or lungs found on ultrasound or CT, contact with dogs and livestock in endemic areas, persistently elevated eosinophils', 'Cistična promjena u jetri ili plućima viđena na ultrazvuku ili CT, kontakt sa psima i stokom u endemskim područjima, dugotrajno povišeni eozinofili', 'Цистична промјена у јетри или плућима виђена на ултразвуку или CT, контакт са псима и стоком у ендемским подручјима, дуготрајно повишени еозинофили', 'Кистозное образование в печени или лёгких, выявленное при УЗИ или КТ, контакт с собаками и скотом в эндемичных районах, длительно повышенные эозинофилы', 'Zystische Veränderung in Leber oder Lunge im Ultraschall oder CT, Kontakt mit Hunden und Nutztieren in Endemiegebieten, anhaltend erhöhte Eosinophile', 'Ultrason veya BT ile karaciğer ya da akciğerde saptanan kistik oluşum, endemik bölgelerde köpek ve çiftlik hayvanlarıyla temas, uzun süre yüksek seyreden eozinofiller', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The result may be related to contact with the parasite, and cross-reactions with other helminth infections are possible. It is assessed by a doctor together with imaging findings', 'Nalaz može biti povezan sa kontaktom sa parazitom, a moguće su i unakrsne reakcije sa drugim parazitozama. Nalaz procjenjuje ljekar zajedno sa nalazima snimanja', 'Налаз може бити повезан са контактом са паразитом, а могуће су и унакрсне реакције са другим паразитозама. Налаз процјењује љекар заједно са налазима снимања', 'Результат может быть связан с контактом с паразитом, возможны перекрёстные реакции с другими гельминтозами. Оценивает результат врач вместе с данными визуализации', 'Das Ergebnis kann mit einem Kontakt mit dem Parasiten zusammenhängen, Kreuzreaktionen mit anderen Wurmerkrankungen sind möglich. Die Beurteilung erfolgt durch den Arzt zusammen mit den Bildbefunden', 'Sonuç parazitle temas ile ilişkili olabilir, diğer parazit hastalıklarıyla çapraz reaksiyon görülebilir. Görüntüleme bulgularıyla birlikte hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hbsab'), 'Blood test for antibodies to the hepatitis B surface antigen (anti-HBs)', 'Analiza krvi na antitijela na površinski antigen virusa hepatitisa B (anti-HBs)', 'Анализа крви на антитијела на површински антиген вируса хепатитиса Б (анти-HBs)', 'Анализ крови на антитела к поверхностному антигену вируса гепатита B (anti-HBs)', 'Bluttest auf Antikörper gegen das Hepatitis-B-Oberflächenantigen (Anti-HBs)', 'Hepatit B yüzey antijenine karşı antikorları (anti-HBs) ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Checking immune status after vaccination, examination of healthcare workers and students, planning vaccination, assessment of the situation after a contact', 'Provjera imunskog statusa poslije vakcinacije, pregled zdravstvenih radnika i studenata, planiranje vakcinacije, procjena stanja poslije kontakta', 'Провјера имунског статуса послије вакцинације, преглед здравствених радника и студената, планирање вакцинације, процјена стања послије контакта', 'Проверка иммунного статуса после вакцинации, обследование медицинских работников и студентов, планирование вакцинации, оценка ситуации после контакта', 'Überprüfung des Immunstatus nach einer Impfung, Untersuchung von medizinischem Personal und Studierenden, Impfplanung, Beurteilung der Situation nach einem Kontakt', 'Aşı sonrası bağışıklık durumunun kontrolü, sağlık çalışanlarının ve öğrencilerin incelenmesi, aşı planlaması, temas sonrası durumun değerlendirilmesi', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The antibody level may be related to a completed vaccination or to an earlier contact with the virus. Conclusions about protection and the need for a booster are made by a doctor', 'Nivo antitijela može biti povezan sa sprovedenom vakcinacijom ili sa ranijim kontaktom sa virusom. Zaključak o zaštiti i potrebi revakcinacije donosi ljekar', 'Ниво антитијела може бити повезан са спроведеном вакцинацијом или са ранијим контактом са вирусом. Закључак о заштити и потреби ревакцинације доноси љекар', 'Уровень антител может быть связан с проведённой вакцинацией или с перенесённым ранее контактом с вирусом. Вывод о защите и необходимости ревакцинации делает врач', 'Die Höhe der Antikörper kann mit einer durchgeführten Impfung oder mit einem früheren Kontakt mit dem Virus zusammenhängen. Über den Schutz und eine Auffrischimpfung entscheidet der Arzt', 'Antikor düzeyi yapılmış aşılanma veya virüsle daha önceki temas ile ilişkili olabilir. Korunma durumu ve pekiştirme aşısı gereği hakkındaki kararı hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'helicobacter-pylori-igg'), 'Blood test for IgG class antibodies to the bacterium Helicobacter pylori', 'Analiza krvi na antitijela klase IgG na bakteriju Helicobacter pylori', 'Анализа крви на антитијела класе IgG на бактерију Helicobacter pylori', 'Анализ крови на антитела класса IgG к бактерии Helicobacter pylori', 'Bluttest auf Antikörper der Klasse IgG gegen das Bakterium Helicobacter pylori', 'Helicobacter pylori bakterisine karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Pain and heaviness in the upper abdomen, heartburn, work-up for gastritis and peptic ulcer disease, cases of the infection in the family', 'Bol i težina u gornjem dijelu trbuha, žgaravica, obrada kod gastritisa i čira, slučajevi infekcije u porodici', 'Бол и тежина у горњем дијелу трбуха, жгаравица, обрада код гастритиса и чира, случајеви инфекције у породици', 'Боль и тяжесть в верхней части живота, изжога, обследование при гастрите и язвенной болезни, случаи инфекции в семье', 'Schmerzen und Völlegefühl im Oberbauch, Sodbrennen, Abklärung bei Gastritis und Magengeschwür, Fälle der Infektion in der Familie', 'Karnın üst bölümünde ağrı ve dolgunluk, mide yanması, gastrit ve ülser araştırması, ailede görülen enfeksiyon', 'Usually no special preparation is required, the sample is most often taken in the morning on an empty stomach', 'Obično nije potrebna posebna priprema, krv se najčešće uzima ujutru našte', 'Обично није потребна посебна припрема, крв се најчешће узима ујутру наште', 'Специальной подготовки обычно не требуется, чаще кровь сдают утром натощак', 'In der Regel keine besondere Vorbereitung nötig, die Entnahme erfolgt meist morgens nüchtern', 'Genellikle özel bir hazırlık gerekmez, kan çoğunlukla sabah aç karnına alınır', 'The presence of IgG may be related to either a current or an earlier contact with the bacterium and does not on its own confirm an active infection. The need for confirmatory tests is determined by a doctor', 'Prisustvo IgG može biti povezano i sa aktuelnim i sa ranijim kontaktom sa bakterijom i samo po sebi ne potvrđuje aktivnu infekciju. Potrebu za dodatnim testovima procjenjuje ljekar', 'Присуство IgG може бити повезано и са актуелним и са ранијим контактом са бактеријом и само по себи не потврђује активну инфекцију. Потребу за додатним тестовима процјењује љекар', 'Наличие IgG может быть связано как с текущим, так и с перенесённым ранее контактом с бактерией и само по себе не подтверждает активную инфекцию. Необходимость уточняющих тестов определяет врач', 'Der Nachweis von IgG kann sowohl mit einem aktuellen als auch mit einem früheren Kontakt mit dem Bakterium zusammenhängen und bestätigt für sich allein keine aktive Infektion. Über weitere klärende Tests entscheidet der Arzt', 'IgG bulunması bakteriyle hem güncel hem de daha önceki temas ile ilişkili olabilir ve tek başına aktif enfeksiyonu doğrulamaz. Doğrulayıcı testlerin gerekliliğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'herpes-simplex-i-igg'), 'Blood test for IgG class antibodies to herpes simplex virus type 1, which is more often linked with sores on the lips', 'Analiza krvi na antitijela klase IgG na virus herpes simpleks tip 1, koji je češće povezan sa promjenama na usnama', 'Анализа крви на антитијела класе IgG на вирус херпес симплекс тип 1, који је чешће повезан са промјенама на уснама', 'Анализ крови на антитела класса IgG к вирусу простого герпеса 1 типа, который чаще связан с высыпаниями на губах', 'Bluttest auf Antikörper der Klasse IgG gegen Herpes-simplex-Virus Typ 1, das häufiger mit Bläschen an den Lippen verbunden ist', 'Daha çok dudaktaki uçuklarla ilişkili herpes simpleks virüs tip 1''e karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Assessment of an earlier contact with the virus, recurring sores on the lips and face, pregnancy planning, preparation for treatment that lowers immunity', 'Procjena ranijeg kontakta sa virusom, ponavljane promjene na usnama i licu, planiranje trudnoće, priprema za terapiju koja smanjuje imunitet', 'Процјена ранијег контакта са вирусом, понављане промјене на уснама и лицу, планирање трудноће, припрема за терапију која смањује имунитет', 'Оценка перенесённого ранее контакта с вирусом, повторяющиеся высыпания на губах и лице, планирование беременности, подготовка к терапии, снижающей иммунитет', 'Beurteilung eines früheren Kontakts mit dem Virus, wiederkehrende Bläschen an Lippen und Gesicht, Kinderwunsch, Vorbereitung auf eine Therapie, die die Abwehr schwächt', 'Virüsle daha önceki temasın değerlendirilmesi, dudak ve yüzde tekrarlayan döküntüler, gebelik planlaması, bağışıklığı azaltan tedavi öncesi hazırlık', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of IgG usually reflects a contact with the virus in the past and is common in adults. What the result means in a particular situation is determined by a doctor', 'Prisustvo IgG obično odražava raniji kontakt sa virusom i često se nalazi kod odraslih. Značaj nalaza u konkretnoj situaciji procjenjuje ljekar', 'Присуство IgG обично одражава ранији контакт са вирусом и често се налази код одраслих. Значај налаза у конкретној ситуацији процјењује љекар', 'Наличие IgG обычно отражает контакт с вирусом в прошлом и широко встречается у взрослых. Значение результата в конкретной ситуации определяет врач', 'Der Nachweis von IgG spiegelt meist einen Kontakt mit dem Virus in der Vergangenheit wider und ist bei Erwachsenen häufig. Was das Ergebnis im Einzelfall bedeutet, beurteilt der Arzt', 'IgG bulunması genellikle virüsle geçmişte kurulmuş bir teması yansıtır ve erişkinlerde sık görülür. Sonucun kişiye özel anlamını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'herpes-simplex-ii-igg'), 'Blood test for IgG class antibodies to herpes simplex virus type 2, which is more often linked with genital localisation', 'Analiza krvi na antitijela klase IgG na virus herpes simpleks tip 2, koji je češće povezan sa genitalnom lokalizacijom', 'Анализа крви на антитијела класе IgG на вирус херпес симплекс тип 2, који је чешће повезан са гениталном локализацијом', 'Анализ крови на антитела класса IgG к вирусу простого герпеса 2 типа, который чаще связан с генитальной локализацией', 'Bluttest auf Antikörper der Klasse IgG gegen Herpes-simplex-Virus Typ 2, das häufiger mit einer genitalen Lokalisation verbunden ist', 'Daha çok genital bölgeyle ilişkili herpes simpleks virüs tip 2''ye karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Assessment of an earlier contact with the virus, recurring lesions in the genital area, planning and management of pregnancy, examination of a couple', 'Procjena ranijeg kontakta sa virusom, ponavljane promjene u genitalnoj regiji, planiranje i vođenje trudnoće, pregled para', 'Процјена ранијег контакта са вирусом, понављане промјене у гениталној регији, планирање и вођење трудноће, преглед пара', 'Оценка перенесённого ранее контакта с вирусом, повторяющиеся высыпания в генитальной области, планирование и ведение беременности, обследование пары', 'Beurteilung eines früheren Kontakts mit dem Virus, wiederkehrende Veränderungen im Genitalbereich, Planung und Betreuung einer Schwangerschaft, Untersuchung des Paares', 'Virüsle daha önceki temasın değerlendirilmesi, genital bölgede tekrarlayan lezyonlar, gebelik planlaması ve takibi, çiftin birlikte incelenmesi', 'No special preparation required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The presence of IgG indicates a contact with the virus in the past and does not show when it happened. Interpretation in a particular situation, including during pregnancy, is given by a doctor', 'Prisustvo IgG govori o ranijem kontaktu sa virusom i ne pokazuje kada je do njega došlo. Tumačenje u konkretnoj situaciji, uključujući trudnoću, daje ljekar', 'Присуство IgG говори о ранијем контакту са вирусом и не показује када је до њега дошло. Тумачење у конкретној ситуацији, укључујући трудноћу, даје љекар', 'Наличие IgG говорит о контакте с вирусом в прошлом и не указывает на время заражения. Трактовку в конкретной ситуации, в том числе при беременности, даёт врач', 'Der Nachweis von IgG weist auf einen früheren Kontakt mit dem Virus hin und sagt nichts über den Zeitpunkt aus. Die Einordnung im Einzelfall, auch in der Schwangerschaft, nimmt der Arzt vor', 'IgG bulunması virüsle geçmişte temas kurulduğunu gösterir, bunun ne zaman olduğunu belirtmez. Gebelik dahil kişiye özel yorumu hekim yapar')
