INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'influenza-a-plus-b-iht'), 'Rapid immunochromatographic test that detects influenza A and B virus antigens', 'Brzi imunohromatografski test koji otkriva antigene virusa gripa A i B', 'Брзи имунохроматографски тест који открива антигене вируса грипа А и Б', 'Быстрый иммунохроматографический тест, определяющий антигены вирусов гриппа A и B', 'Immunchromatographischer Schnelltest, der Antigene der Influenzaviren A und B nachweist', 'İnfluenza A ve B virüsü antijenlerini saptayan hızlı immünokromatografik test', 'A nasal or nasopharyngeal swab, the test cassette gives a result in about 15 minutes', 'Bris nosa ili nazofarinksa, test kaseta daje rezultat za oko 15 minuta', 'Брис носа или назофаринкса, тест касета даје резултат за око 15 минута', 'Мазок из носа или носоглотки, тест-кассета даёт результат примерно за 15 минут', 'Abstrich aus Nase oder Nasenrachen, die Testkassette liefert das Ergebnis in etwa 15 Minuten', 'Burun veya nazofarenks sürüntüsü alınır, test kaseti sonucu yaklaşık 15 dakikada verir', 'Acute onset of illness with high fever during the flu season, telling influenza apart from other respiratory infections, examination in closed communities, patients from risk groups', 'Naglo započeta bolest sa visokom temperaturom u sezoni gripa, razlikovanje gripa od drugih respiratornih infekcija, ispitivanje u kolektivima, pacijenti iz rizičnih grupa', 'Нагло започета болест са високом температуром у сезони грипа, разликовање грипа од других респираторних инфекција, испитивање у колективима, пацијенти из ризичних група', 'Острое начало болезни с высокой температурой в сезон гриппа, различение гриппа и других респираторных инфекций, обследование в закрытых коллективах, пациенты из групп риска', 'Plötzlicher Krankheitsbeginn mit hohem Fieber in der Grippesaison, Abgrenzung der Grippe von anderen Atemwegsinfekten, Untersuchung in Gemeinschaftseinrichtungen, Patienten aus Risikogruppen', 'Grip mevsiminde yüksek ateşle ani başlayan hastalık, gribin diğer solunum yolu enfeksiyonlarından ayrılması, toplu yaşam alanlarında inceleme, risk grubundaki hastalar', 'The test is most informative in the first days of illness; before the swab do not rinse the nose or use nasal sprays unless the doctor says otherwise', 'Test je najinformativniji u prvim danima bolesti; prije brisa ne ispirati nos i ne koristiti sprejeve za nos, osim ako ljekar ne kaže drugačije', 'Тест је најинформативнији у првим данима болести; прије бриса не испирати нос и не користити спрејеве за нос, осим ако љекар не каже другачије', 'Тест информативнее в первые дни болезни; перед мазком не промывать нос и не использовать назальные спреи, если врач не сказал иначе', 'Der Test ist in den ersten Krankheitstagen am aussagekräftigsten; vor dem Abstrich die Nase nicht spülen und keine Nasensprays verwenden, sofern der Arzt nichts anderes sagt', 'Test hastalığın ilk günlerinde daha bilgi vericidir; sürüntüden önce burun yıkanmamalı ve hekim aksini söylemedikçe burun spreyi kullanılmamalıdır', 'A positive result may be related to a current influenza A or B infection, while a negative one does not rule it out. The decision on further examination is made by a doctor', 'Pozitivan nalaz može biti povezan sa aktuelnom infekcijom virusom gripa A ili B, dok negativan ne isključuje bolest. Odluku o daljoj obradi donosi ljekar', 'Позитиван налаз може бити повезан са актуелном инфекцијом вирусом грипа А или Б, док негативан не искључује болест. Одлуку о даљој обради доноси љекар', 'Положительный результат может быть связан с текущей инфекцией вирусом гриппа A или B, отрицательный её не исключает. Решение о дальнейшем обследовании принимает врач', 'Ein positives Ergebnis kann mit einer aktuellen Infektion durch Influenza A oder B zusammenhängen, ein negatives schließt sie nicht aus. Über das weitere Vorgehen entscheidet der Arzt', 'Pozitif sonuç güncel influenza A veya B enfeksiyonu ile ilişkili olabilir, negatif sonuç ise hastalığı dışlamaz. İleri inceleme kararını hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'neisseria-gonorrhoeae-real-time-pcr'), 'Molecular test that detects DNA of the bacterium Neisseria gonorrhoeae by real-time PCR', 'Molekularni test koji otkriva DNK bakterije Neisseria gonorrhoeae metodom PCR u realnom vremenu', 'Молекуларни тест који открива ДНК бактерије Neisseria gonorrhoeae методом ПЦР у реалном времену', 'Молекулярный тест, выявляющий ДНК бактерии Neisseria gonorrhoeae методом ПЦР в реальном времени', 'Molekularer Test, der DNA des Bakteriums Neisseria gonorrhoeae mittels Real-Time-PCR nachweist', 'Neisseria gonorrhoeae bakterisini gerçek zamanlı PCR yöntemiyle saptayan moleküler test', 'Swab from the urethra, cervical canal, throat or rectum, or a urine portion, the analysis is performed in the laboratory', 'Bris uretre, cervikalnog kanala, ždrijela ili rektuma ili uzorak mokraće, analizu radi laboratorija', 'Брис уретре, цервикалног канала, ждријела или ректума или узорак мокраће, анализу ради лабораторија', 'Мазок из уретры, цервикального канала, глотки или прямой кишки либо порция мочи, анализ выполняет лаборатория', 'Abstrich aus Harnröhre, Gebärmutterhalskanal, Rachen oder Enddarm oder eine Urinprobe, die Analyse führt das Labor durch', 'Üretra, servikal kanal, boğaz veya rektumdan sürüntü ya da idrar örneği alınır, analiz laboratuvarda yapılır', 'Discharge, burning when urinating, preventive check-up, examination of a partner, preparation for gynaecological or urological procedures, follow-up after treatment', 'Sekret, peckanje pri mokrenju, preventivni pregled, pregled partnera, priprema za ginekološke ili urološke zahvate, kontrola poslije terapije', 'Секрет, пецкање при мокрењу, превентивни преглед, преглед партнера, припрема за гинеколошке или уролошке захвате, контрола послије терапије', 'Выделения, жжение при мочеиспускании, профилактическое обследование, обследование партнёра, подготовка к гинекологическим или урологическим вмешательствам, контроль после лечения', 'Ausfluss, Brennen beim Wasserlassen, Vorsorgeuntersuchung, Untersuchung des Partners, Vorbereitung auf gynäkologische oder urologische Eingriffe, Kontrolle nach einer Behandlung', 'Akıntı, idrar yaparken yanma, koruyucu inceleme, eşin incelenmesi, jinekolojik veya ürolojik girişim öncesi hazırlık, tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the sample, women outside menstruation days; the timing after antibacterial medicines is set by the doctor', 'Ne mokriti 2–3 sata prije uzimanja uzorka, žene van dana menstruacije; rok poslije antibakterijskih lijekova određuje ljekar', 'Не мокрити 2–3 сата прије узимања узорка, жене ван дана менструације; рок послије антибактеријских лијекова одређује љекар', 'Не мочиться 2–3 часа перед сдачей, женщинам — вне дней менструации; сроки после антибактериальных препаратов уточняет врач', '2–3 Stunden vor der Probenentnahme nicht Wasser lassen, Frauen außerhalb der Menstruationstage; den Abstand zu antibakteriellen Medikamenten legt der Arzt fest', 'Örnek vermeden 2–3 saat önce idrara çıkılmamalı, kadınlarda adet günleri dışında alınmalıdır; antibakteriyel ilaçlardan sonraki süreyi hekim belirler', 'Detection of DNA means the bacterium is present in the sample. Further examination, treatment and examination of a partner are prescribed by a doctor', 'Nalaz DNK znači da je bakterija prisutna u uzorku. Dalju obradu, terapiju i pregled partnera određuje ljekar', 'Налаз ДНК значи да је бактерија присутна у узорку. Даљу обраду, терапију и преглед партнера одређује љекар', 'Обнаружение ДНК означает присутствие бактерии в пробе. Дальнейшее обследование, лечение и обследование партнёра назначает врач', 'Ein DNA-Nachweis bedeutet, dass das Bakterium in der Probe vorhanden ist. Weitere Abklärung, Behandlung und die Untersuchung des Partners veranlasst der Arzt', 'DNA saptanması bakterinin örnekte bulunduğunu gösterir. İleri tetkikleri, tedaviyi ve eşin incelenmesini hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'quantiferon'), 'Blood test that measures the response of immune cells to antigens of the tuberculosis mycobacterium (an IGRA test)', 'Analiza krvi koja procjenjuje reakciju imunskih ćelija na antigene bacila tuberkuloze (IGRA test)', 'Анализа крви која процјењује реакцију имунских ћелија на антигене бацила туберкулозе (IGRA тест)', 'Анализ крови, оценивающий реакцию иммунных клеток на антигены микобактерии туберкулёза (тест IGRA)', 'Bluttest, der die Reaktion der Immunzellen auf Antigene des Tuberkulosebakteriums misst (IGRA-Test)', 'Bağışıklık hücrelerinin tüberküloz basili antijenlerine verdiği yanıtı ölçen kan testi (IGRA testi)', 'Venous blood is drawn into special tubes that are mixed and delivered to the laboratory promptly, the draw itself takes a few minutes', 'Uzimanje venske krvi u posebne epruvete koje se promiješaju i brzo šalju u laboratoriju, samo uzimanje traje nekoliko minuta', 'Узимање венске крви у посебне епрувете које се промијешају и брзо шаљу у лабораторију, само узимање траје неколико минута', 'Забор венозной крови в специальные пробирки, которые перемешивают и быстро передают в лабораторию, сам забор занимает несколько минут', 'Venöses Blut wird in spezielle Röhrchen abgenommen, die gemischt und zügig ins Labor gebracht werden, die Entnahme selbst dauert einige Minuten', 'Venöz kan özel tüplere alınır, tüpler karıştırılıp kısa sürede laboratuvara ulaştırılır, kan alımı birkaç dakika sürer', 'Screening for latent tuberculosis infection, examination before immunosuppressive and biological therapy, contact with a person ill with tuberculosis, examination of healthcare workers, requirements for employment and paperwork', 'Skrining na latentnu tuberkuloznu infekciju, pregled prije imunosupresivne i biološke terapije, kontakt sa oboljelim od tuberkuloze, pregled zdravstvenih radnika, zahtjevi pri zapošljavanju i sređivanju dokumenata', 'Скрининг на латентну туберкулозну инфекцију, преглед прије имуносупресивне и биолошке терапије, контакт са обољелим од туберкулозе, преглед здравствених радника, захтјеви при запошљавању и сређивању докумената', 'Скрининг на латентную туберкулёзную инфекцию, обследование перед иммуносупрессивной и биологической терапией, контакт с больным туберкулёзом, обследование медицинских работников, требования при трудоустройстве и оформлении документов', 'Screening auf eine latente Tuberkuloseinfektion, Untersuchung vor immunsuppressiver und biologischer Therapie, Kontakt zu einer an Tuberkulose erkrankten Person, Untersuchung von medizinischem Personal, Anforderungen bei Anstellung und Behördengängen', 'Latent tüberküloz enfeksiyonu taraması, bağışıklığı baskılayan ve biyolojik tedavi öncesi inceleme, tüberkülozlu biriyle temas, sağlık çalışanlarının taranması, işe giriş ve resmi belge gereklilikleri', 'No special preparation required, but the appointment time is agreed with the laboratory: the tubes must be processed within a few hours', 'Nije potrebna posebna priprema, ali se termin dogovara sa laboratorijom: epruvete moraju biti obrađene u roku od nekoliko sati', 'Није потребна посебна припрема, али се термин договара са лабораторијом: епрувете морају бити обрађене у року од неколико сати', 'Специальной подготовки не требуется, но время сдачи согласуют с лабораторией: пробирки должны быть обработаны в течение нескольких часов', 'Keine besondere Vorbereitung nötig, der Termin wird jedoch mit dem Labor abgestimmt: die Röhrchen müssen innerhalb weniger Stunden verarbeitet werden', 'Özel bir hazırlık gerekmez, ancak randevu saati laboratuvarla birlikte belirlenir: tüplerin birkaç saat içinde işlenmesi gerekir', 'A positive result may be related to contact with the tuberculosis mycobacterium and does not distinguish latent infection from active disease. Further examination, including a chest image, is ordered by a doctor', 'Pozitivan nalaz može biti povezan sa kontaktom sa bacilom tuberkuloze i ne razlikuje latentnu infekciju od aktivne bolesti. Dalju obradu, uključujući snimak pluća, određuje ljekar', 'Позитиван налаз може бити повезан са контактом са бацилом туберкулозе и не разликује латентну инфекцију од активне болести. Даљу обраду, укључујући снимак плућа, одређује љекар', 'Положительный результат может быть связан с контактом с микобактерией туберкулёза и не различает латентную инфекцию и активное заболевание. Дальнейшее обследование, включая снимок лёгких, назначает врач', 'Ein positives Ergebnis kann mit einem Kontakt mit dem Tuberkulosebakterium zusammenhängen und unterscheidet nicht zwischen latenter Infektion und aktiver Erkrankung. Die weitere Abklärung, einschließlich einer Lungenaufnahme, veranlasst der Arzt', 'Pozitif sonuç tüberküloz basili ile temas ile ilişkili olabilir ve latent enfeksiyonu aktif hastalıktan ayırmaz. Akciğer görüntülemesi dahil ileri incelemeleri hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cervical-swab-bacteria'), 'Bacteriological examination of material from the cervical canal to identify bacterial flora', 'Bakteriološko ispitivanje materijala iz cervikalnog kanala radi utvrđivanja bakterijske flore', 'Бактериолошко испитивање материјала из цервикалног канала ради утврђивања бактеријске флоре', 'Бактериологическое исследование материала из канала шейки матки для выявления бактериальной флоры', 'Bakteriologische Untersuchung von Material aus dem Gebärmutterhalskanal zum Nachweis der bakteriellen Flora', 'Bakteriyel florayı belirlemek için servikal kanaldan alınan örneğin bakteriyolojik incelemesi', 'The doctor inserts a speculum and collects secretions from the cervical canal with a sterile swab, takes a few minutes', 'Ljekar postavlja ginekološki spekulum i sterilnim štapićem uzima sekret iz cervikalnog kanala, traje nekoliko minuta', 'Љекар поставља гинеколошки спекулум и стерилним штапићем узима секрет из цервикалног канала, траје неколико минута', 'Врач вводит гинекологическое зеркало и стерильным тампоном берёт отделяемое из цервикального канала, занимает несколько минут', 'Der Arzt führt ein Spekulum ein und entnimmt mit einem sterilen Tupfer Sekret aus dem Zervikalkanal, dauert wenige Minuten', 'Hekim spekulum yerleştirir ve steril çubukla servikal kanaldan salgı alır, işlem birkaç dakika sürer', 'Discharge, itching or discomfort, pregnancy planning, preparation for gynaecological procedures, follow-up after treatment, preventive examination', 'Pojačan sekret, svrab ili nelagodnost, planiranje trudnoće, priprema za ginekološke zahvate, kontrola poslije liječenja, preventivni pregled', 'Појачан секрет, свраб или нелагодност, планирање трудноће, припрема за гинеколошке захвате, контрола послије лијечења, превентивни преглед', 'Выделения, зуд или дискомфорт, планирование беременности, подготовка к гинекологическим вмешательствам, контроль после лечения, профилактический осмотр', 'Ausfluss, Juckreiz oder Beschwerden, Kinderwunsch, Vorbereitung auf gynäkologische Eingriffe, Kontrolle nach einer Behandlung, Vorsorgeuntersuchung', 'Akıntı, kaşıntı veya rahatsızlık hissi, gebelik planlaması, jinekolojik girişimlere hazırlık, tedavi sonrası kontrol, koruyucu muayene', 'Taken outside menstrual bleeding; for one day before avoid sexual intercourse, douching, vaginal suppositories and creams; tell the doctor about any recent antibiotics', 'Uzima se van menstrualnog krvarenja; dan ranije izbjegavati seksualne odnose, ispiranja, vaginalete i kreme; obavijestiti ljekara o nedavnom uzimanju antibiotika', 'Узима се ван менструалног крварења; дан раније избјегавати сексуалне односе, испирања, вагиналете и креме; обавијестити љекара о недавном узимању антибиотика', 'Забор вне менструального кровотечения; за сутки исключить половые контакты, спринцевания, вагинальные свечи и кремы; о недавнем приёме антибиотиков сообщить врачу', 'Entnahme außerhalb der Menstruationsblutung; einen Tag zuvor auf Geschlechtsverkehr, Spülungen sowie Vaginalzäpfchen und -cremes verzichten; kürzlich eingenommene Antibiotika dem Arzt mitteilen', 'Adet kanaması dışında alınır; bir gün öncesinden cinsel ilişki, vajinal duş, vajinal fitil ve kremlerden kaçınılmalı; yakın zamanda antibiyotik kullanıldıysa hekime bildirilmelidir', 'Growth of bacteria may be related to a disturbed balance of the microflora, an inflammatory process or symptom-free carriage. The significance of the finding and antibiotic susceptibility are assessed by a doctor', 'Porast bakterija može biti povezan sa poremećajem sastava mikroflore, upalnim procesom ili nosilaštvom bez tegoba. Značaj nalaza i osjetljivost na antibiotike procjenjuje ljekar', 'Пораст бактерија може бити повезан са поремећајем састава микрофлоре, упалним процесом или носилаштвом без тегоба. Значај налаза и осјетљивост на антибиотике процјењује љекар', 'Рост бактерий может быть связан с нарушением состава микрофлоры, воспалительным процессом или бессимптомным носительством. Значимость находки и чувствительность к антибиотикам оценивает врач', 'Ein Nachweis von Bakterien kann mit einer gestörten Zusammensetzung der Mikroflora, einem entzündlichen Prozess oder einer beschwerdefreien Besiedlung zusammenhängen. Die Bedeutung des Befunds und die Antibiotikaempfindlichkeit beurteilt der Arzt', 'Bakteri üremesi mikroflora dengesindeki bozulmayla, iltihabi bir süreçle veya belirtisiz taşıyıcılıkla ilişkili olabilir. Bulgunun önemini ve antibiyotik duyarlılığını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'glans-swab-bacteria'), 'Bacteriological examination of secretions from the skin of the glans penis', 'Bakteriološko ispitivanje sekreta sa kože glansa penisa', 'Бактериолошко испитивање секрета са коже гланса пениса', 'Бактериологическое исследование отделяемого с кожи головки полового члена', 'Bakteriologische Untersuchung des Sekrets von der Haut der Eichel', 'Penis başının derisinden alınan salgının bakteriyolojik incelemesi', 'A sterile swab is wiped over the surface of the glans and the material is cultured on nutrient media, collection takes about a minute', 'Sterilnim štapićem prelazi se preko površine glansa, materijal se zasijava na hranljive podloge, uzimanje traje oko minut', 'Стерилним штапићем прелази се преко површине гланса, материјал се засијава на хранљиве подлоге, узимање траје око минут', 'Стерильным тампоном проводят по поверхности головки, материал засевают на питательные среды, забор занимает около минуты', 'Mit einem sterilen Tupfer wird über die Oberfläche der Eichel gestrichen, das Material wird auf Nährböden angezüchtet, die Entnahme dauert etwa eine Minute', 'Steril çubuk glans yüzeyinde gezdirilir, örnek besiyerine ekilir, alım yaklaşık bir dakika sürer', 'Redness, itching, coating or discharge around the glans, discomfort when urinating, recurring inflammation, follow-up after treatment', 'Crvenilo, svrab, naslage ili sekret u predjelu glansa, nelagodnost pri mokrenju, ponavljane upale, kontrola poslije liječenja', 'Црвенило, свраб, наслаге или секрет у предјелу гланса, нелагодност при мокрењу, понављане упале, контрола послије лијечења', 'Покраснение, зуд, налёт или выделения в области головки, дискомфорт при мочеиспускании, повторяющиеся воспаления, контроль после лечения', 'Rötung, Juckreiz, Belag oder Ausfluss im Bereich der Eichel, Beschwerden beim Wasserlassen, wiederkehrende Entzündungen, Kontrolle nach einer Behandlung', 'Glans bölgesinde kızarıklık, kaşıntı, beyaz tabaka veya akıntı, idrar yaparken rahatsızlık, tekrarlayan iltihaplar, tedavi sonrası kontrol', 'Do not apply ointments or antiseptics to the area and do not wash it immediately before the sample is taken; tell the doctor about any antibiotics you are taking', 'Ne nanositi masti i antiseptike na to područje i ne prati ga neposredno prije uzimanja uzorka; obavijestiti ljekara o uzimanju antibiotika', 'Не наносити масти и антисептике на то подручје и не прати га непосредно прије узимања узорка; обавијестити љекара о узимању антибиотика', 'Не наносить на область мази и антисептики и не мыть её непосредственно перед забором; о приёме антибиотиков сообщить врачу', 'Vor der Entnahme keine Salben oder Antiseptika auftragen und die Stelle nicht unmittelbar davor waschen; eingenommene Antibiotika dem Arzt mitteilen', 'Bölgeye merhem ve antiseptik uygulanmamalı, örnek alınmadan hemen önce yıkanmamalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of bacteria may be related to inflammation of the skin of the glans, hygiene conditions or accompanying conditions, and also occurs in people without complaints. The significance of the finding and antibiotic susceptibility are assessed by a doctor', 'Porast bakterija može biti povezan sa upalom kože glansa, uslovima higijene ili pratećim stanjima, a nalazi se i kod osoba bez tegoba. Značaj nalaza i osjetljivost na antibiotike procjenjuje ljekar', 'Пораст бактерија може бити повезан са упалом коже гланса, условима хигијене или пратећим стањима, а налази се и код особа без тегоба. Значај налаза и осјетљивост на антибиотике процјењује љекар', 'Рост бактерий может быть связан с воспалением кожи головки, особенностями гигиены или сопутствующими состояниями, а также встречается у людей без жалоб. Значимость находки и чувствительность к антибиотикам оценивает врач', 'Ein Nachweis von Bakterien kann mit einer Entzündung der Eichelhaut, den Hygienebedingungen oder Begleiterkrankungen zusammenhängen und kommt auch bei Menschen ohne Beschwerden vor. Die Bedeutung des Befunds und die Antibiotikaempfindlichkeit beurteilt der Arzt', 'Bakteri üremesi glans derisinin iltihabıyla, hijyen koşullarıyla veya eşlik eden durumlarla ilişkili olabilir ve şikayeti olmayan kişilerde de görülür. Bulgunun önemini ve antibiyotik duyarlılığını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'glans-swab-fungi'), 'Mycological examination of material from the skin of the glans penis for yeast-like fungi', 'Mikološko ispitivanje materijala sa kože glansa penisa na kvasnice', 'Миколошко испитивање материјала са коже гланса пениса на кваснице', 'Микологическое исследование материала с кожи головки полового члена на дрожжеподобные грибы', 'Mykologische Untersuchung von Material der Eichelhaut auf Hefepilze', 'Penis başı derisinden alınan örnekte maya mantarlarının araştırılması', 'A sterile swab collects coating and secretions from the surface of the glans, which are cultured on a medium for fungi', 'Sterilnim štapićem uzimaju se naslage i sekret sa površine glansa i zasijavaju na podlogu za gljivice', 'Стерилним штапићем узимају се наслаге и секрет са површине гланса и засијавају на подлогу за гљивице', 'Стерильным тампоном берут налёт и отделяемое с поверхности головки и засевают на среду для грибов', 'Mit einem sterilen Tupfer werden Belag und Sekret von der Oberfläche der Eichel entnommen und auf einem Pilznährboden angezüchtet', 'Steril çubukla glans yüzeyindeki tabaka ve salgı alınır ve mantar besiyerine ekilir', 'Itching, burning, redness, white coating, recurring complaints, follow-up after a course of treatment', 'Svrab, peckanje, crvenilo, bijele naslage, ponavljane tegobe, kontrola poslije završenog liječenja', 'Свраб, пецкање, црвенило, бијеле наслаге, понављане тегобе, контрола послије завршеног лијечења', 'Зуд, жжение, покраснение, белый налёт, повторяющиеся жалобы, контроль после курса лечения', 'Juckreiz, Brennen, Rötung, weißer Belag, wiederkehrende Beschwerden, Kontrolle nach einer Behandlung', 'Kaşıntı, yanma, kızarıklık, beyaz tabaka, tekrarlayan şikayetler, tedavi sonrası kontrol', 'Do not use antifungal creams for several days before the test and do not wash the area immediately before the procedure; the exact interval is specified by the doctor', 'Nekoliko dana prije uzimanja ne koristiti antimikotske kreme, područje ne prati neposredno prije zahvata; tačan razmak određuje ljekar', 'Неколико дана прије узимања не користити антимикотске креме, подручје не прати непосредно прије захвата; тачан размак одређује љекар', 'За несколько дней до забора не применять противогрибковые кремы, область не мыть непосредственно перед процедурой; точный интервал уточняет врач', 'Einige Tage vor der Entnahme keine Antipilzcremes anwenden und die Stelle nicht unmittelbar vor der Untersuchung waschen; den genauen Abstand legt der Arzt fest', 'Örnekten birkaç gün önce antifungal kremler kullanılmamalı, bölge işlemden hemen önce yıkanmamalıdır; süreyi hekim belirler', 'Detection of fungi may be related to changes in the local microflora, moisture and skin irritation, or accompanying conditions including disorders of carbohydrate metabolism. The result is interpreted by a doctor', 'Nalaz gljivica može biti povezan sa promjenom lokalne mikroflore, vlagom i nadražajem kože ili pratećim stanjima, uključujući poremećaje metabolizma ugljenih hidrata. Nalaz tumači ljekar', 'Налаз гљивица може бити повезан са промјеном локалне микрофлоре, влагом и надражајем коже или пратећим стањима, укључујући поремећаје метаболизма угљених хидрата. Налаз тумачи љекар', 'Обнаружение грибов может быть связано с изменением местной микрофлоры, влажностью и раздражением кожи или сопутствующими состояниями, включая нарушения углеводного обмена. Результат трактует врач', 'Ein Pilznachweis kann mit Veränderungen der lokalen Mikroflora, Feuchtigkeit und Hautreizung oder Begleiterkrankungen einschließlich Störungen des Kohlenhydratstoffwechsels zusammenhängen. Den Befund beurteilt der Arzt', 'Mantar saptanması yerel mikrofloranın değişmesiyle, nem ve deri tahrişiyle ya da karbonhidrat metabolizması bozuklukları dahil eşlik eden durumlarla ilişkili olabilir. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'nose-swab-bacteria'), 'Bacteriological examination of secretions from the nasal mucosa', 'Bakteriološko ispitivanje sekreta sa sluznice nosa', 'Бактериолошко испитивање секрета са слузнице носа', 'Бактериологическое исследование отделяемого слизистой носа', 'Bakteriologische Untersuchung des Sekrets der Nasenschleimhaut', 'Burun içinden alınan salgının bakteriyolojik incelemesi', 'A sterile swab is inserted into the nostril and wiped over the mucosa, the procedure takes less than a minute and is usually painless', 'Sterilni štapić se uvodi u nosni hodnik i prelazi preko sluznice, postupak traje manje od minuta i obično je bezbolan', 'Стерилни штапић се уводи у носни ходник и прелази преко слузнице, поступак траје мање од минута и обично је безболан', 'Стерильный тампон вводят в носовой ход и проводят по слизистой, процедура занимает меньше минуты и обычно безболезненна', 'Ein steriler Tupfer wird in den Nasengang eingeführt und über die Schleimhaut gestrichen, der Vorgang dauert weniger als eine Minute und ist meist schmerzfrei', 'Steril çubuk burun deliğine yerleştirilip mukoza üzerinde gezdirilir, işlem bir dakikadan kısa sürer ve genellikle ağrısızdır', 'Prolonged runny nose, purulent discharge, sinusitis, examination before surgery or hospital admission, carrier screening for healthcare and food industry workers', 'Dugotrajna sekrecija iz nosa, gnojav sekret, sinusitis, ispitivanje prije operacije ili prijema u bolnicu, provjera nosilaštva kod zdravstvenih radnika i radnika u proizvodnji hrane', 'Дуготрајна секреција из носа, гнојав секрет, синуситис, испитивање прије операције или пријема у болницу, провјера носилаштва код здравствених радника и радника у производњи хране', 'Затяжной насморк, гнойные выделения, синусит, обследование перед операцией или госпитализацией, проверка носительства у медицинских работников и работников пищевой сферы', 'Anhaltender Schnupfen, eitriges Sekret, Nasennebenhöhlenentzündung, Untersuchung vor Operationen oder Krankenhausaufnahme, Trägerprüfung bei Beschäftigten im Gesundheitswesen und in der Lebensmittelbranche', 'Uzun süren burun akıntısı, iltihaplı akıntı, sinüzit, ameliyat veya hastaneye yatış öncesi inceleme, sağlık ve gıda sektörü çalışanlarında taşıyıcılık taraması', 'On the day of the test do not use nasal drops, sprays or ointments and do not rinse the nose; tell the doctor about any antibiotics you are taking', 'Na dan uzimanja ne koristiti kapi, sprejeve i masti za nos i ne ispirati nos; obavijestiti ljekara o uzimanju antibiotika', 'На дан узимања не користити капи, спрејеве и масти за нос и не испирати нос; обавијестити љекара о узимању антибиотика', 'В день забора не использовать капли, спреи и мази для носа, нос не промывать; о приёме антибиотиков сообщить врачу', 'Am Tag der Entnahme keine Nasentropfen, -sprays oder -salben verwenden und die Nase nicht spülen; eingenommene Antibiotika dem Arzt mitteilen', 'Örnek alınacağı gün burun damlası, sprey ve merhem kullanılmamalı, burun yıkanmamalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of micro-organisms may reflect symptom-free carriage or the involvement of bacteria in inflammation. The significance of the result and antibiotic susceptibility are determined by a doctor', 'Porast mikroorganizama može odražavati nosilaštvo bez tegoba, ali i učešće bakterija u upali. Značaj nalaza i osjetljivost na antibiotike određuje ljekar', 'Пораст микроорганизама може одражавати носилаштво без тегоба, али и учешће бактерија у упали. Значај налаза и осјетљивост на антибиотике одређује љекар', 'Рост микроорганизмов может отражать как бессимптомное носительство, так и участие бактерий в воспалении. Значимость результата и чувствительность к антибиотикам определяет врач', 'Der Nachweis von Mikroorganismen kann eine beschwerdefreie Besiedlung widerspiegeln, aber auch eine Beteiligung von Bakterien an einer Entzündung. Die Bedeutung des Ergebnisses und die Antibiotikaempfindlichkeit bestimmt der Arzt', 'Mikroorganizma üremesi belirtisiz taşıyıcılığı da, bakterilerin iltihaba katılımını da yansıtabilir. Sonucun önemini ve antibiyotik duyarlılığını hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'nose-swab-fungi'), 'Examination of nasal mucosa secretions for the presence of fungi', 'Ispitivanje sekreta sa sluznice nosa na prisustvo gljivica', 'Испитивање секрета са слузнице носа на присуство гљивица', 'Исследование отделяемого слизистой носа на наличие грибов', 'Untersuchung des Sekrets der Nasenschleimhaut auf Pilze', 'Burun içinden alınan salgıda mantar varlığının araştırılması', 'A sterile swab collects material from the nasal passage and it is cultured on a medium for fungi, collection takes less than a minute', 'Sterilnim štapićem uzima se materijal iz nosnog hodnika i zasijava na hranljivu podlogu za gljivice, uzimanje traje manje od minuta', 'Стерилним штапићем узима се материјал из носног ходника и засијава на хранљиву подлогу за гљивице, узимање траје мање од минута', 'Стерильным тампоном берут материал из носового хода и засевают на питательную среду для грибов, забор занимает меньше минуты', 'Mit einem sterilen Tupfer wird Material aus dem Nasengang entnommen und auf einem Pilznährboden angezüchtet, die Entnahme dauert weniger als eine Minute', 'Steril çubukla burun yolundan örnek alınır ve mantar besiyerine ekilir, alım bir dakikadan kısa sürer', 'Long-lasting congestion and discharge that does not improve with usual treatment, chronic sinusitis, conditions with reduced immunity, monitoring after antibacterial therapy', 'Dugotrajna zapušenost i sekrecija bez poboljšanja uz uobičajeno liječenje, hronični sinusitis, stanja sa smanjenim imunitetom, praćenje poslije antibiotske terapije', 'Дуготрајна запушеност и секреција без побољшања уз уобичајено лијечење, хронични синуситис, стања са смањеним имунитетом, праћење послије антибиотске терапије', 'Длительная заложенность и выделения без улучшения на обычном лечении, хронический синусит, состояния со сниженным иммунитетом, наблюдение после антибактериальной терапии', 'Anhaltende Verstopfung und Sekretion ohne Besserung unter der üblichen Behandlung, chronische Nasennebenhöhlenentzündung, Zustände mit geschwächter Immunabwehr, Verlaufskontrolle nach antibakterieller Therapie', 'Alışılmış tedaviye rağmen geçmeyen tıkanıklık ve akıntı, kronik sinüzit, bağışıklığın azaldığı durumlar, antibiyotik tedavisi sonrası izlem', 'On the day of the test do not use nasal sprays, drops or ointments and do not rinse the nose; tell the doctor about any recent antifungal medicines', 'Na dan uzimanja ne koristiti nazalne sprejeve, kapi i masti i ne ispirati nos; obavijestiti ljekara o nedavnom uzimanju antimikotskih lijekova', 'На дан узимања не користити назалне спрејеве, капи и масти и не испирати нос; обавијестити љекара о недавном узимању антимикотских лијекова', 'В день забора не использовать назальные спреи, капли и мази, нос не промывать; о недавнем приёме противогрибковых средств сообщить врачу', 'Am Tag der Entnahme keine Nasensprays, -tropfen oder -salben verwenden und die Nase nicht spülen; kürzlich eingenommene Antipilzmittel dem Arzt mitteilen', 'Örnek alınacağı gün burun spreyi, damla ve merhem kullanılmamalı, burun yıkanmamalıdır; yakın zamanda antifungal ilaç kullanıldıysa hekime bildirilmelidir', 'Detection of fungi may reflect their usual presence on the mucosa or their involvement in an inflammatory process, especially when immunity is reduced. The result is assessed by a doctor', 'Nalaz gljivica može odražavati njihovo uobičajeno prisustvo na sluznici, ali i učešće u upalnom procesu, naročito kod smanjenog imuniteta. Nalaz procjenjuje ljekar', 'Налаз гљивица може одражавати њихово уобичајено присуство на слузници, али и учешће у упалном процесу, нарочито код смањеног имунитета. Налаз процјењује љекар', 'Находка грибов может отражать как их обычное присутствие на слизистой, так и участие в воспалительном процессе, особенно при сниженном иммунитете. Результат оценивает врач', 'Ein Pilznachweis kann das übliche Vorkommen auf der Schleimhaut widerspiegeln, aber auch eine Beteiligung an einem entzündlichen Prozess, vor allem bei geschwächter Immunabwehr. Den Befund beurteilt der Arzt', 'Mantar saptanması mukozadaki olağan varlığı kadar, özellikle bağışıklığın azaldığı durumlarda iltihabi sürece katılımı da yansıtabilir. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'oral-cavity-swab-bacteria'), 'Bacteriological examination of material from the mucosa of the oral cavity', 'Bakteriološko ispitivanje materijala sa sluznice usne duplje', 'Бактериолошко испитивање материјала са слузнице усне дупље', 'Бактериологическое исследование материала со слизистой полости рта', 'Bakteriologische Untersuchung von Material der Mundschleimhaut', 'Ağız içi mukozasından alınan örneğin bakteriyolojik incelemesi', 'A sterile swab is wiped over the mucosa of the cheeks, gums and palate and the material is cultured on nutrient media', 'Sterilnim štapićem prelazi se preko sluznice obraza, desni i nepca, materijal se zasijava na hranljive podloge', 'Стерилним штапићем прелази се преко слузнице образа, десни и непца, материјал се засијава на хранљиве подлоге', 'Стерильным тампоном проводят по слизистой щёк, дёсен и нёба, материал засевают на питательные среды', 'Mit einem sterilen Tupfer wird über die Schleimhaut von Wangen, Zahnfleisch und Gaumen gestrichen, das Material wird auf Nährböden angezüchtet', 'Steril çubuk yanak, diş eti ve damak mukozasında gezdirilir, örnek besiyerlerine ekilir', 'Inflammation of the mucosa and gums, coating and small ulcers in the mouth, persistent bad breath, preparation for dental procedures, follow-up after treatment', 'Upala sluznice i desni, naslage i ranice u ustima, uporan neprijatan zadah, priprema za stomatološke zahvate, kontrola poslije liječenja', 'Упала слузнице и десни, наслаге и ранице у устима, упоран непријатан задах, припрема за стоматолошке захвате, контрола послије лијечења', 'Воспаление слизистой и дёсен, налёт и язвочки во рту, стойкий неприятный запах, подготовка к стоматологическим вмешательствам, контроль после лечения', 'Entzündung der Schleimhaut und des Zahnfleischs, Belag und kleine Wunden im Mund, anhaltender Mundgeruch, Vorbereitung auf zahnärztliche Eingriffe, Kontrolle nach einer Behandlung', 'Mukoza ve diş eti iltihabı, ağızda tabaka ve küçük yaralar, geçmeyen ağız kokusu, diş hekimliği girişimlerine hazırlık, tedavi sonrası kontrol', 'Taken in the morning before eating: do not brush your teeth, rinse your mouth, drink or smoke for 2–3 hours before the procedure', 'Uzima se ujutru prije jela: ne prati zube, ne ispirati usta, ne piti i ne pušiti 2–3 sata prije zahvata', 'Узима се ујутру прије јела: не прати зубе, не испирати уста, не пити и не пушити 2–3 сата прије захвата', 'Забор утром до еды: не чистить зубы, не полоскать рот, не пить и не курить за 2–3 часа до процедуры', 'Entnahme morgens vor dem Essen: 2–3 Stunden vorher nicht Zähne putzen, nicht spülen, nicht trinken und nicht rauchen', 'Sabah aç karnına alınır: işlemden 2–3 saat önce diş fırçalanmamalı, ağız çalkalanmamalı, bir şey içilmemeli ve sigara kullanılmamalıdır', 'Growth of bacteria may be related to inflammation of the mucosa, the condition of teeth and gums, or a temporary change of the microflora after treatment. The meaning of the finding is assessed by a doctor', 'Porast bakterija može biti povezan sa upalom sluznice, stanjem zuba i desni ili privremenom promjenom mikroflore poslije liječenja. Značenje nalaza procjenjuje ljekar', 'Пораст бактерија може бити повезан са упалом слузнице, стањем зуба и десни или привременом промјеном микрофлоре послије лијечења. Значење налаза процјењује љекар', 'Рост бактерий может быть связан с воспалением слизистой, состоянием зубов и дёсен или временным изменением микрофлоры после лечения. Значение находки оценивает врач', 'Ein Nachweis von Bakterien kann mit einer Schleimhautentzündung, dem Zustand von Zähnen und Zahnfleisch oder einer vorübergehenden Veränderung der Mikroflora nach einer Behandlung zusammenhängen. Die Bedeutung des Befunds beurteilt der Arzt', 'Bakteri üremesi mukoza iltihabıyla, diş ve diş eti durumuyla ya da tedavi sonrası mikrofloranın geçici değişimiyle ilişkili olabilir. Bulgunun anlamını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'prepuce-swab-bacteria'), 'Bacteriological examination of secretions from the inner surface of the foreskin', 'Bakteriološko ispitivanje sekreta sa unutrašnje površine prepucijuma', 'Бактериолошко испитивање секрета са унутрашње површине препуцијума', 'Бактериологическое исследование отделяемого с внутренней поверхности крайней плоти', 'Bakteriologische Untersuchung des Sekrets von der Innenseite der Vorhaut', 'Prepusyumun iç yüzeyinden alınan salgının bakteriyolojik incelemesi', 'The foreskin is gently retracted and a sterile swab collects material from the preputial sac, takes about a minute', 'Prepucijum se pažljivo povuče unazad i sterilnim štapićem se uzima materijal iz prepucijalne kese, traje oko minut', 'Препуцијум се пажљиво повуче уназад и стерилним штапићем се узима материјал из препуцијалне кесе, траје око минут', 'Крайнюю плоть аккуратно отводят и стерильным тампоном берут материал из препуциального мешка, занимает около минуты', 'Die Vorhaut wird vorsichtig zurückgezogen und mit einem sterilen Tupfer Material aus dem Vorhautsack entnommen, dauert etwa eine Minute', 'Sünnet derisi dikkatlice geri çekilir ve steril çubukla prepusyum boşluğundan örnek alınır, yaklaşık bir dakika sürer', 'Redness and swelling of the foreskin, coating and unpleasant odour, pain on retraction, recurring inflammation, follow-up after treatment', 'Crvenilo i otok prepucijuma, naslage i neprijatan miris, bol pri povlačenju, ponavljane upale, kontrola poslije liječenja', 'Црвенило и оток препуцијума, наслаге и непријатан мирис, бол при повлачењу, понављане упале, контрола послије лијечења', 'Покраснение и отёк крайней плоти, налёт и неприятный запах, боль при отведении, повторяющиеся воспаления, контроль после лечения', 'Rötung und Schwellung der Vorhaut, Belag und unangenehmer Geruch, Schmerzen beim Zurückziehen, wiederkehrende Entzündungen, Kontrolle nach einer Behandlung', 'Sünnet derisinde kızarıklık ve şişlik, tabaka ve kötü koku, geri çekerken ağrı, tekrarlayan iltihaplar, tedavi sonrası kontrol', 'Do not wash the area and do not use antiseptics or ointments immediately before the sample is taken; tell the doctor about any antibiotics you are taking', 'Ne prati područje i ne koristiti antiseptike i masti neposredno prije uzimanja uzorka; obavijestiti ljekara o uzimanju antibiotika', 'Не прати подручје и не користити антисептике и масти непосредно прије узимања узорка; обавијестити љекара о узимању антибиотика', 'Не мыть область и не применять антисептики и мази непосредственно перед забором; о приёме антибиотиков сообщить врачу', 'Die Stelle unmittelbar vor der Entnahme nicht waschen und keine Antiseptika oder Salben anwenden; eingenommene Antibiotika dem Arzt mitteilen', 'Örnek alınmadan hemen önce bölge yıkanmamalı, antiseptik ve merhem kullanılmamalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of bacteria may be related to inflammation of the foreskin, difficult hygiene with a narrow preputial ring, or accompanying conditions. Further steps are decided by a doctor', 'Porast bakterija može biti povezan sa upalom prepucijuma, otežanom higijenom kod uskog prepucijalnog prstena ili pratećim stanjima. Dalje korake određuje ljekar', 'Пораст бактерија може бити повезан са упалом препуцијума, отежаном хигијеном код уског препуцијалног прстена или пратећим стањима. Даље кораке одређује љекар', 'Рост бактерий может быть связан с воспалением крайней плоти, затруднённой гигиеной при узком препуциальном кольце или сопутствующими состояниями. Дальнейшие шаги определяет врач', 'Ein Nachweis von Bakterien kann mit einer Entzündung der Vorhaut, erschwerter Hygiene bei enger Vorhaut oder Begleiterkrankungen zusammenhängen. Das weitere Vorgehen legt der Arzt fest', 'Bakteri üremesi sünnet derisi iltihabıyla, dar prepusyum halkası nedeniyle güçleşen hijyenle veya eşlik eden durumlarla ilişkili olabilir. Sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'prepuce-swab-fungi'), 'Examination of material from the inner surface of the foreskin for yeast-like fungi', 'Ispitivanje materijala sa unutrašnje površine prepucijuma na kvasnice', 'Испитивање материјала са унутрашње површине препуцијума на кваснице', 'Исследование материала с внутренней поверхности крайней плоти на дрожжеподобные грибы', 'Untersuchung von Material der Vorhautinnenseite auf Hefepilze', 'Prepusyumun iç yüzeyinden alınan örnekte maya mantarlarının araştırılması', 'The foreskin is retracted, a sterile swab collects coating and secretions, and the material is cultured on a medium for fungi', 'Prepucijum se povuče unazad, sterilnim štapićem se skupljaju naslage i sekret, materijal se zasijava na podlogu za gljivice', 'Препуцијум се повуче уназад, стерилним штапићем се скупљају наслаге и секрет, материјал се засијава на подлогу за гљивице', 'Крайнюю плоть отводят, стерильным тампоном собирают налёт и отделяемое, материал засевают на среду для грибов', 'Die Vorhaut wird zurückgezogen, mit einem sterilen Tupfer werden Belag und Sekret entnommen und auf einem Pilznährboden angezüchtet', 'Sünnet derisi geri çekilir, steril çubukla tabaka ve salgı toplanır, örnek mantar besiyerine ekilir', 'Itching, white curd-like coating, redness, burning, recurring inflammation, follow-up after a course of treatment', 'Svrab, bijele sirevite naslage, crvenilo, peckanje, ponavljane upale, kontrola poslije završenog liječenja', 'Свраб, бијеле сиревите наслаге, црвенило, пецкање, понављане упале, контрола послије завршеног лијечења', 'Зуд, белый творожистый налёт, покраснение, жжение, повторяющиеся воспаления, контроль после курса лечения', 'Juckreiz, weißlich-krümeliger Belag, Rötung, Brennen, wiederkehrende Entzündungen, Kontrolle nach einer Behandlung', 'Kaşıntı, beyaz kesilmiş süt görünümünde tabaka, kızarıklık, yanma, tekrarlayan iltihaplar, tedavi sonrası kontrol', 'Do not use antifungal creams for several days before the test and do not wash the area immediately before the procedure; the interval is specified by the doctor', 'Nekoliko dana prije uzimanja ne koristiti antimikotske kreme, područje ne prati neposredno prije zahvata; razmak određuje ljekar', 'Неколико дана прије узимања не користити антимикотске креме, подручје не прати непосредно прије захвата; размак одређује љекар', 'За несколько дней до забора не применять противогрибковые кремы, область не мыть непосредственно перед процедурой; интервал уточняет врач', 'Einige Tage vor der Entnahme keine Antipilzcremes anwenden und die Stelle nicht unmittelbar vor der Untersuchung waschen; den Abstand legt der Arzt fest', 'Örnekten birkaç gün önce antifungal krem kullanılmamalı, bölge işlemden hemen önce yıkanmamalıdır; süreyi hekim belirler', 'Fungi are often found without any complaints: moisture is retained longer under the foreskin, and growth increases with skin irritation or a narrow foreskin. The doctor decides what the finding means', 'Gljivice se često nalaze i bez tegoba: ispod prepucijuma se duže zadržava vlaga, a rast je izraženiji uz nadražaj kože ili uzak prepucijum. Značaj nalaza procjenjuje ljekar', 'Гљивице се често налазе и без тегоба: испод препуцијума се дуже задржава влага, а раст је израженији уз надражај коже или узак препуцијум. Значај налаза процјењује љекар', 'Грибы нередко находят и без жалоб: под крайней плотью дольше сохраняется влага, и рост усиливается при раздражении кожи или узкой крайней плоти. Значение находки определяет врач', 'Pilze werden häufig auch ohne Beschwerden gefunden: unter der Vorhaut bleibt Feuchtigkeit länger bestehen, und das Wachstum nimmt bei Hautreizung oder enger Vorhaut zu. Was der Befund bedeutet, entscheidet der Arzt', 'Mantarlar çoğu zaman şikâyet olmadan da bulunur: sünnet derisinin altında nem daha uzun süre kalır ve ciltte tahriş ya da dar sünnet derisi varsa üreme artar. Bulgunun anlamını hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'skin-swab-bacteria'), 'Bacteriological examination of discharge from an affected area of skin', 'Bakteriološko ispitivanje sekreta sa promijenjenog dijela kože', 'Бактериолошко испитивање секрета са промијењеног дијела коже', 'Бактериологическое исследование отделяемого с поражённого участка кожи', 'Bakteriologische Untersuchung von Sekret aus einer betroffenen Hautstelle', 'Etkilenen deri bölgesinden alınan akıntının bakteriyolojik incelemesi', 'A sterile swab is wiped over the surface of the lesion, wound or blister content and the material is cultured on nutrient media', 'Sterilnim štapićem prelazi se preko površine promjene, rane ili sadržaja mjehurića, materijal se zasijava na hranljive podloge', 'Стерилним штапићем прелази се преко површине промјене, ране или садржаја мјехурића, материјал се засијава на хранљиве подлоге', 'Стерильным тампоном проводят по поверхности очага, раны или содержимого пузырька, материал засевают на питательные среды', 'Mit einem sterilen Tupfer wird über die Oberfläche des Herdes, der Wunde oder den Blaseninhalt gestrichen, das Material wird auf Nährböden angezüchtet', 'Steril çubuk lezyon, yara yüzeyi veya kabarcık içeriği üzerinde gezdirilir, örnek besiyerlerine ekilir', 'Pustules, weeping and slow-healing sores, inflammation around stitches, boils, signs of an infected burn or bite, follow-up after treatment', 'Gnojne promjene, vlažne i sporo zarastajuće ranice, upala oko šavova, čirevi, znaci infekcije opekotine ili ujeda, kontrola poslije liječenja', 'Гнојне промјене, влажне и споро зарастајуће ранице, упала око шавова, чиреви, знаци инфекције опекотине или уједа, контрола послије лијечења', 'Гнойнички, мокнущие и долго не заживающие ранки, воспаление вокруг швов, фурункулы, признаки инфицирования ожога или укуса, контроль после лечения', 'Eitrige Hautveränderungen, nässende und schlecht heilende Wunden, Entzündung um Nähte, Furunkel, Anzeichen einer infizierten Verbrennung oder Bisswunde, Kontrolle nach einer Behandlung', 'İrinli kabarcıklar, sulanan ve geç iyileşen yaralar, dikiş çevresinde iltihap, çıban, yanık veya ısırık yerinde enfeksiyon belirtileri, tedavi sonrası kontrol', 'Do not apply ointments, creams or antiseptics to the area and do not wash it immediately before the sample is taken; tell the doctor about any antibiotics you are taking', 'Ne nanositi masti, kreme i antiseptike na to mjesto i ne prati ga neposredno prije uzimanja uzorka; obavijestiti ljekara o uzimanju antibiotika', 'Не наносити масти, креме и антисептике на то мјесто и не прати га непосредно прије узимања узорка; обавијестити љекара о узимању антибиотика', 'Не наносить на участок мази, кремы и антисептики и не мыть его непосредственно перед забором; о приёме антибиотиков сообщить врачу', 'Keine Salben, Cremes oder Antiseptika auf die Stelle auftragen und sie nicht unmittelbar vor der Entnahme waschen; eingenommene Antibiotika dem Arzt mitteilen', 'Bölgeye merhem, krem ve antiseptik uygulanmamalı, örnek alınmadan hemen önce yıkanmamalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of bacteria may reflect infection of the lesion or the presence of the usual skin flora. The significance of the finding and antibiotic susceptibility are assessed by a doctor', 'Porast bakterija može odražavati infekciju promjene ili prisustvo uobičajene kožne flore. Značaj nalaza i osjetljivost na antibiotike procjenjuje ljekar', 'Пораст бактерија може одражавати инфекцију промјене или присуство уобичајене кожне флоре. Значај налаза и осјетљивост на антибиотике процјењује љекар', 'Рост бактерий может отражать инфицирование очага или присутствие обычной кожной флоры. Значимость находки и чувствительность к антибиотикам оценивает врач', 'Ein Nachweis von Bakterien kann eine Infektion des Herdes oder das Vorhandensein der üblichen Hautflora widerspiegeln. Die Bedeutung des Befunds und die Antibiotikaempfindlichkeit beurteilt der Arzt', 'Bakteri üremesi lezyonun enfekte olduğunu da, derinin olağan florasının varlığını da yansıtabilir. Bulgunun önemini ve antibiyotik duyarlılığını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'skin-swab-fungi'), 'Examination of material from an affected area of skin for fungi', 'Ispitivanje materijala sa promijenjenog dijela kože na gljivice', 'Испитивање материјала са промијењеног дијела коже на гљивице', 'Исследование материала с поражённого участка кожи на грибы', 'Untersuchung von Material einer betroffenen Hautstelle auf Pilze', 'Etkilenen deri bölgesinden alınan örnekte mantar araştırması', 'Skin scales are taken from the edge of the lesion or a sterile swab is used, the material is examined under a microscope and cultured on a medium for fungi', 'Sa ivice promjene uzimaju se ljuspice kože ili se prelazi sterilnim štapićem, materijal se gleda pod mikroskopom i zasijava na podlogu za gljivice', 'Са ивице промјене узимају се љуспице коже или се прелази стерилним штапићем, материјал се гледа под микроскопом и засијава на подлогу за гљивице', 'С края очага берут чешуйки кожи или проводят стерильным тампоном, материал смотрят под микроскопом и засевают на среду для грибов', 'Am Rand des Herdes werden Hautschuppen entnommen oder ein steriler Tupfer verwendet, das Material wird mikroskopisch untersucht und auf einem Pilznährboden angezüchtet', 'Lezyonun kenarından deri pulları kazınır veya steril çubuk kullanılır, örnek mikroskopta incelenir ve mantar besiyerine ekilir', 'Scaly patches with a clear border, itching, skin changes between the toes and in skin folds, patches on the scalp, follow-up after treatment', 'Ljuskave promjene sa jasnom ivicom, svrab, promjene kože među prstima i u pregibima, žarišta na vlasištu, kontrola poslije liječenja', 'Љускаве промјене са јасном ивицом, свраб, промјене коже међу прстима и у прегибима, жаришта на власишту, контрола послије лијечења', 'Шелушащиеся пятна с чётким краем, зуд, изменения кожи между пальцами и в складках, очаги на волосистой части головы, контроль после лечения', 'Schuppende Flecken mit deutlichem Rand, Juckreiz, Hautveränderungen zwischen den Zehen und in Hautfalten, Herde auf der Kopfhaut, Kontrolle nach einer Behandlung', 'Sınırı belirgin pullanan lekeler, kaşıntı, parmak araları ve kıvrım bölgelerinde deri değişiklikleri, saçlı deride odaklar, tedavi sonrası kontrol', 'Do not use antifungal creams for several days before the test and do not wash the area immediately before the procedure; the exact interval is specified by the doctor', 'Nekoliko dana prije uzimanja ne koristiti antimikotske kreme i ne prati to mjesto neposredno prije zahvata; tačan razmak određuje ljekar', 'Неколико дана прије узимања не користити антимикотске креме и не прати то мјесто непосредно прије захвата; тачан размак одређује љекар', 'За несколько дней до забора не применять противогрибковые кремы и не мыть участок непосредственно перед процедурой; конкретный интервал уточняет врач', 'Einige Tage vor der Entnahme keine Antipilzcremes anwenden und die Stelle nicht unmittelbar vor der Untersuchung waschen; den genauen Abstand legt der Arzt fest', 'Örnekten birkaç gün önce antifungal krem kullanılmamalı, bölge işlemden hemen önce yıkanmamalıdır; süreyi hekim belirler', 'Detection of fungi may be related to a fungal skin condition, and also to surface contamination of the sample. The culture and microscopy results are interpreted by a dermatologist', 'Nalaz gljivica može biti povezan sa gljivičnom promjenom kože, ali i sa površinskim zagađenjem uzorka. Rezultat kulture i mikroskopije tumači ljekar dermatolog', 'Налаз гљивица може бити повезан са гљивичном промјеном коже, али и са површинским загађењем узорка. Резултат културе и микроскопије тумачи љекар дерматолог', 'Обнаружение грибов может быть связано с грибковым поражением кожи, а также с поверхностным загрязнением материала. Результат посева и микроскопии интерпретирует врач-дерматолог', 'Ein Pilznachweis kann mit einer Pilzerkrankung der Haut, aber auch mit einer oberflächlichen Verunreinigung des Materials zusammenhängen. Kultur- und Mikroskopiebefund beurteilt der Hautarzt', 'Mantar saptanması derinin mantar hastalığıyla olduğu kadar örneğin yüzeysel kirlenmesiyle de ilişkili olabilir. Kültür ve mikroskopi sonucunu dermatoloji uzmanı yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'stool-fungi'), 'Examination of stool for yeast-like and mould fungi', 'Ispitivanje stolice na kvasnice i plijesni', 'Испитивање столице на кваснице и плијесни', 'Исследование кала на дрожжеподобные и плесневые грибы', 'Untersuchung des Stuhls auf Hefe- und Schimmelpilze', 'Dışkıda maya ve küf mantarlarının araştırılması', 'The patient collects a small portion of stool into a sterile container and the laboratory cultures the material on a medium for fungi', 'Pacijent sam sakuplja manju količinu stolice u sterilnu posudu, a u laboratoriji se materijal zasijava na hranljivu podlogu za gljivice', 'Пацијент сам сакупља мању количину столице у стерилну посуду, а у лабораторији се материјал засијава на хранљиву подлогу за гљивице', 'Пациент сам собирает небольшую порцию кала в стерильный контейнер, в лаборатории материал засевают на питательную среду для грибов', 'Der Patient sammelt selbst eine kleine Stuhlprobe in einem sterilen Behälter, im Labor wird das Material auf einem Pilznährboden angezüchtet', 'Hasta küçük bir gaita örneğini steril kaba kendisi toplar, laboratuvarda örnek mantar besiyerine ekilir', 'Long-lasting bowel disturbances and bloating, complaints after a course of antibiotics, conditions with reduced immunity, monitoring as prescribed by a doctor', 'Dugotrajne promjene stolice i nadutost, tegobe poslije terapije antibioticima, stanja sa smanjenim imunitetom, praćenje po preporuci ljekara', 'Дуготрајне промјене столице и надутост, тегобе послије терапије антибиотицима, стања са смањеним имунитетом, праћење по препоруци љекара', 'Длительные нарушения стула и вздутие, жалобы после курса антибиотиков, состояния со сниженным иммунитетом, наблюдение по назначению врача', 'Anhaltende Stuhlveränderungen und Blähungen, Beschwerden nach einer Antibiotikatherapie, Zustände mit geschwächter Immunabwehr, Verlaufskontrolle auf ärztliche Anordnung', 'Uzun süren dışkılama düzensizlikleri ve şişkinlik, antibiyotik tedavisi sonrası şikayetler, bağışıklığın azaldığı durumlar, hekim önerisiyle izlem', 'Collect stool into a sterile container without urine or water mixed in, avoid laxatives and enemas the day before, and deliver the sample within the time the laboratory specifies', 'Stolicu sakupiti u sterilnu posudu bez primjese mokraće i vode, dan ranije ne koristiti laksative i klizme, uzorak dostaviti u laboratoriju u roku koji ona navodi', 'Столицу сакупити у стерилну посуду без примјесе мокраће и воде, дан раније не користити лаксативе и клизме, узорак доставити у лабораторију у року који она наводи', 'Собрать кал в стерильный контейнер без примеси мочи и воды, накануне не использовать слабительные и клизмы, доставить материал в лабораторию в указанные ею сроки', 'Stuhl in einem sterilen Behälter ohne Beimengung von Urin oder Wasser sammeln, am Vortag keine Abführmittel und Einläufe anwenden und die Probe innerhalb der vom Labor genannten Frist abgeben', 'Gaita, idrar ve su karışmadan steril kaba toplanmalı, bir gün öncesinden müshil ve lavman kullanılmamalı, örnek laboratuvarın belirttiği süre içinde teslim edilmelidir', 'Growth of fungi may reflect their usual presence in the bowel or a change of the microflora, for example after antibacterial therapy. The significance of the result is assessed by a doctor', 'Porast gljivica može odražavati njihovo uobičajeno prisustvo u crijevima, ali i promjenu mikroflore, na primjer poslije antibiotske terapije. Značaj nalaza procjenjuje ljekar', 'Пораст гљивица може одражавати њихово уобичајено присуство у цријевима, али и промјену микрофлоре, на примјер послије антибиотске терапије. Значај налаза процјењује љекар', 'Рост грибов может отражать как их обычное присутствие в кишечнике, так и изменение микрофлоры, например после антибактериальной терапии. Значимость результата оценивает врач', 'Ein Pilzwachstum kann das übliche Vorkommen im Darm widerspiegeln, aber auch eine Veränderung der Mikroflora, zum Beispiel nach einer antibakteriellen Therapie. Die Bedeutung des Ergebnisses beurteilt der Arzt', 'Mantar üremesi bağırsaktaki olağan varlığı kadar, örneğin antibiyotik tedavisi sonrası mikrofloranın değişmesini de yansıtabilir. Sonucun önemini hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'throat-swab-fungi'), 'Examination of material from the pharyngeal mucosa and tonsils for fungi', 'Ispitivanje materijala sa sluznice ždrijela i krajnika na gljivice', 'Испитивање материјала са слузнице ждријела и крајника на гљивице', 'Исследование материала со слизистой глотки и миндалин на грибы', 'Untersuchung von Material der Rachenschleimhaut und der Mandeln auf Pilze', 'Yutak mukozası ve bademciklerden alınan örnekte mantar araştırması', 'A sterile swab is wiped over the back wall of the throat and the tonsils and the material is cultured on a medium for fungi, takes less than a minute', 'Sterilnim štapićem prelazi se preko zadnjeg zida ždrijela i krajnika, materijal se zasijava na podlogu za gljivice, traje manje od minuta', 'Стерилним штапићем прелази се преко задњег зида ждријела и крајника, материјал се засијава на подлогу за гљивице, траје мање од минута', 'Стерильным тампоном проводят по задней стенке глотки и миндалинам, материал засевают на среду для грибов, занимает меньше минуты', 'Mit einem sterilen Tupfer wird über Rachenhinterwand und Mandeln gestrichen und das Material auf einem Pilznährboden angezüchtet, dauert weniger als eine Minute', 'Steril çubuk yutağın arka duvarı ve bademcikler üzerinde gezdirilir, örnek mantar besiyerine ekilir, işlem bir dakikadan kısa sürer', 'White coating in the mouth and on the tonsils, burning and discomfort in the throat, prolonged complaints after antibiotics or inhaled medicines, conditions with reduced immunity', 'Bijele naslage u ustima i na krajnicima, peckanje i nelagodnost u grlu, dugotrajne tegobe poslije antibiotika ili inhalacionih lijekova, stanja sa smanjenim imunitetom', 'Бијеле наслаге у устима и на крајницима, пецкање и нелагодност у грлу, дуготрајне тегобе послије антибиотика или инхалационих лијекова, стања са смањеним имунитетом', 'Белый налёт во рту и на миндалинах, жжение и дискомфорт в горле, длительные жалобы после антибиотиков или ингаляционных препаратов, состояния со сниженным иммунитетом', 'Weißer Belag im Mund und auf den Mandeln, Brennen und Missempfindungen im Hals, anhaltende Beschwerden nach Antibiotika oder Inhalationsmitteln, Zustände mit geschwächter Immunabwehr', 'Ağızda ve bademciklerde beyaz tabaka, boğazda yanma ve rahatsızlık, antibiyotik veya inhaler ilaç kullanımı sonrası uzayan şikayetler, bağışıklığın azaldığı durumlar', 'Taken in the morning before eating: do not brush your teeth, gargle, drink or use sprays for 2–3 hours before the procedure', 'Uzima se ujutru prije jela: ne prati zube, ne ispirati grlo, ne piti i ne koristiti sprejeve 2–3 sata prije zahvata', 'Узима се ујутру прије јела: не прати зубе, не испирати грло, не пити и не користити спрејеве 2–3 сата прије захвата', 'Забор утром до еды: не чистить зубы, не полоскать горло, не пить и не использовать спреи за 2–3 часа до процедуры', 'Entnahme morgens vor dem Essen: 2–3 Stunden vorher nicht Zähne putzen, nicht gurgeln, nicht trinken und keine Sprays anwenden', 'Sabah aç karnına alınır: işlemden 2–3 saat önce diş fırçalanmamalı, gargara yapılmamalı, bir şey içilmemeli ve sprey kullanılmamalıdır', 'Detection of fungi may be related to a change of the mucosal microflora, the use of certain medicines, or reduced immunity. The result is assessed by a doctor', 'Nalaz gljivica može biti povezan sa promjenom mikroflore sluznice, primjenom pojedinih lijekova ili smanjenim imunitetom. Nalaz procjenjuje ljekar', 'Налаз гљивица може бити повезан са промјеном микрофлоре слузнице, примјеном појединих лијекова или смањеним имунитетом. Налаз процјењује љекар', 'Обнаружение грибов может быть связано с изменением микрофлоры слизистой, применением некоторых препаратов или сниженным иммунитетом. Результат оценивает врач', 'Ein Pilznachweis kann mit einer Veränderung der Schleimhautflora, der Anwendung bestimmter Medikamente oder einer geschwächten Immunabwehr zusammenhängen. Den Befund beurteilt der Arzt', 'Mantar saptanması mukoza florasının değişmesiyle, bazı ilaçların kullanımıyla veya bağışıklığın azalmasıyla ilişkili olabilir. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'tongue-swab-bacteria'), 'Bacteriological examination of coating and secretions from the surface of the tongue', 'Bakteriološko ispitivanje naslaga i sekreta sa površine jezika', 'Бактериолошко испитивање наслага и секрета са површине језика', 'Бактериологическое исследование налёта и отделяемого с поверхности языка', 'Bakteriologische Untersuchung von Belag und Sekret der Zungenoberfläche', 'Dilin yüzeyindeki tabaka ve salgının bakteriyolojik incelemesi', 'A sterile swab is wiped over the back of the tongue and the material is cultured on nutrient media', 'Sterilnim štapićem prelazi se preko gornje strane jezika, materijal se zasijava na hranljive podloge', 'Стерилним штапићем прелази се преко горње стране језика, материјал се засијава на хранљиве подлоге', 'Стерильным тампоном проводят по спинке языка, материал засевают на питательные среды', 'Mit einem sterilen Tupfer wird über den Zungenrücken gestrichen, das Material wird auf Nährböden angezüchtet', 'Steril çubuk dilin sırt kısmında gezdirilir, örnek besiyerlerine ekilir', 'Persistent coating on the tongue, burning and altered taste, inflammation of the oral mucosa, bad breath, follow-up after treatment', 'Uporne naslage na jeziku, peckanje i promjena ukusa, upala sluznice usta, neprijatan zadah, kontrola poslije liječenja', 'Упорне наслаге на језику, пецкање и промјена укуса, упала слузнице уста, непријатан задах, контрола послије лијечења', 'Стойкий налёт на языке, жжение и изменение вкуса, воспаление слизистой рта, неприятный запах, контроль после лечения', 'Hartnäckiger Zungenbelag, Brennen und Geschmacksveränderungen, Entzündung der Mundschleimhaut, Mundgeruch, Kontrolle nach einer Behandlung', 'Dilde geçmeyen tabaka, yanma ve tat değişikliği, ağız mukozası iltihabı, ağız kokusu, tedavi sonrası kontrol', 'Taken in the morning before eating: do not brush your teeth, use mouthwash, drink or smoke for 2–3 hours before the procedure', 'Uzima se ujutru prije jela: ne prati zube, ne koristiti vodicu za ispiranje usta, ne piti i ne pušiti 2–3 sata prije zahvata', 'Узима се ујутру прије јела: не прати зубе, не користити водицу за испирање уста, не пити и не пушити 2–3 сата прије захвата', 'Забор утром до еды: не чистить зубы, не пользоваться ополаскивателем, не пить и не курить за 2–3 часа до процедуры', 'Entnahme morgens vor dem Essen: 2–3 Stunden vorher nicht Zähne putzen, keine Mundspülung verwenden, nicht trinken und nicht rauchen', 'Sabah aç karnına alınır: işlemden 2–3 saat önce diş fırçalanmamalı, ağız suyu kullanılmamalı, bir şey içilmemeli ve sigara kullanılmamalıdır', 'Growth of bacteria may be related to inflammation of the mucosa, the condition of the teeth and oral hygiene, or a temporary change of the microflora. The meaning of the finding is determined by a doctor', 'Porast bakterija može biti povezan sa upalom sluznice, stanjem zuba i higijenom usne duplje ili privremenom promjenom mikroflore. Značenje nalaza određuje ljekar', 'Пораст бактерија може бити повезан са упалом слузнице, стањем зуба и хигијеном усне дупље или привременом промјеном микрофлоре. Значење налаза одређује љекар', 'Рост бактерий может быть связан с воспалением слизистой, состоянием зубов и гигиеной полости рта или временным изменением микрофлоры. Значение находки определяет врач', 'Ein Nachweis von Bakterien kann mit einer Schleimhautentzündung, dem Zustand der Zähne und der Mundhygiene oder einer vorübergehenden Veränderung der Mikroflora zusammenhängen. Die Bedeutung des Befunds bestimmt der Arzt', 'Bakteri üremesi mukoza iltihabıyla, diş durumu ve ağız hijyeniyle ya da mikrofloranın geçici değişimiyle ilişkili olabilir. Bulgunun anlamını hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urethral-swab-bacteria'), 'Bacteriological examination of discharge from the urethra', 'Bakteriološko ispitivanje sekreta mokraćne cijevi', 'Бактериолошко испитивање секрета мокраћне цијеви', 'Бактериологическое исследование отделяемого мочеиспускательного канала', 'Bakteriologische Untersuchung des Sekrets der Harnröhre', 'İdrar kanalı salgısının bakteriyolojik incelemesi', 'A thin sterile probe is inserted a short way into the opening of the urethra, collection takes a few seconds and may be uncomfortable', 'Tanka sterilna sonda se uvodi plitko u spoljašnji otvor uretre, uzimanje traje nekoliko sekundi i može biti neprijatno', 'Танка стерилна сонда се уводи плитко у спољашњи отвор уретре, узимање траје неколико секунди и може бити непријатно', 'Тонкий стерильный зонд вводят в наружное отверстие уретры на небольшую глубину, забор занимает несколько секунд и может быть неприятным', 'Eine dünne sterile Sonde wird ein kurzes Stück in die Harnröhrenöffnung eingeführt, die Entnahme dauert wenige Sekunden und kann unangenehm sein', 'İnce steril bir çubuk üretranın dış ağzından kısa bir mesafe ilerletilir, alım birkaç saniye sürer ve rahatsızlık verebilir', 'Discharge from the urethra, burning and pain when urinating, frequent urge to urinate, examination when planning a pregnancy or before procedures, follow-up after treatment', 'Sekret iz uretre, peckanje i bol pri mokrenju, učestali nagon za mokrenjem, ispitivanje pri planiranju trudnoće ili prije zahvata, kontrola poslije liječenja', 'Секрет из уретре, пецкање и бол при мокрењу, учестали нагон за мокрењем, испитивање при планирању трудноће или прије захвата, контрола послије лијечења', 'Выделения из уретры, жжение и боль при мочеиспускании, учащённые позывы, обследование при планировании беременности или перед вмешательствами, контроль после лечения', 'Ausfluss aus der Harnröhre, Brennen und Schmerzen beim Wasserlassen, häufiger Harndrang, Untersuchung bei Kinderwunsch oder vor Eingriffen, Kontrolle nach einer Behandlung', 'Üretradan akıntı, idrar yaparken yanma ve ağrı, sık idrara çıkma isteği, gebelik planlaması veya girişim öncesi inceleme, tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the test, avoid sexual intercourse and local antiseptics the day before; tell the doctor about any antibiotics you are taking', 'Ne mokriti 2–3 sata prije uzimanja, dan ranije izbjegavati seksualne odnose i lokalne antiseptike; obavijestiti ljekara o uzimanju antibiotika', 'Не мокрити 2–3 сата прије узимања, дан раније избјегавати сексуалне односе и локалне антисептике; обавијестити љекара о узимању антибиотика', 'Не мочиться 2–3 часа до забора, накануне исключить половые контакты и местные антисептики; о приёме антибиотиков сообщить врачу', '2–3 Stunden vor der Entnahme nicht Wasser lassen, am Vortag auf Geschlechtsverkehr und örtliche Antiseptika verzichten; eingenommene Antibiotika dem Arzt mitteilen', 'Örnekten önce 2–3 saat idrara çıkılmamalı, bir gün öncesinden cinsel ilişki ve bölgesel antiseptiklerden kaçınılmalıdır; kullanılan antibiyotikler hekime bildirilmelidir', 'Growth of bacteria may be related to inflammation of the urethra or to the presence of the usual flora of the outer part. The significance of the result and antibiotic susceptibility are assessed by a doctor', 'Porast bakterija može biti povezan sa upalom mokraćne cijevi ili sa prisustvom uobičajene flore spoljašnjeg dijela. Značaj nalaza i osjetljivost na antibiotike procjenjuje ljekar', 'Пораст бактерија може бити повезан са упалом мокраћне цијеви или са присуством уобичајене флоре спољашњег дијела. Значај налаза и осјетљивост на антибиотике процјењује љекар', 'Рост бактерий может быть связан с воспалением мочеиспускательного канала или с присутствием обычной флоры наружных отделов. Значимость результата и чувствительность к антибиотикам оценивает врач', 'Ein Nachweis von Bakterien kann mit einer Entzündung der Harnröhre oder mit der üblichen Flora des äußeren Abschnitts zusammenhängen. Die Bedeutung des Ergebnisses und die Antibiotikaempfindlichkeit beurteilt der Arzt', 'Bakteri üremesi üretra iltihabıyla ya da dış bölümün olağan florasının varlığıyla ilişkili olabilir. Sonucun önemini ve antibiyotik duyarlılığını hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urethral-swab-fungi'), 'Examination of discharge from the urethra for yeast-like fungi', 'Ispitivanje sekreta mokraćne cijevi na kvasnice', 'Испитивање секрета мокраћне цијеви на кваснице', 'Исследование отделяемого мочеиспускательного канала на дрожжеподобные грибы', 'Untersuchung des Harnröhrensekrets auf Hefepilze', 'İdrar kanalı salgısında maya mantarlarının araştırılması', 'A thin sterile probe collects material from the opening of the urethra and it is cultured on a medium for fungi', 'Tankom sterilnom sondom uzima se materijal iz spoljašnjeg otvora uretre i zasijava na podlogu za gljivice', 'Танком стерилном сондом узима се материјал из спољашњег отвора уретре и засијава на подлогу за гљивице', 'Тонким стерильным зондом берут материал из наружного отверстия уретры и засевают его на среду для грибов', 'Mit einer dünnen sterilen Sonde wird Material aus der Harnröhrenöffnung entnommen und auf einem Pilznährboden angezüchtet', 'İnce steril bir çubukla üretranın dış ağzından örnek alınır ve mantar besiyerine ekilir', 'Burning and itching when urinating, whitish discharge, recurring complaints, follow-up after a course of treatment', 'Peckanje i svrab pri mokrenju, bjelkast sekret, ponavljane tegobe, kontrola poslije završenog liječenja', 'Пецкање и свраб при мокрењу, бјелкаст секрет, понављане тегобе, контрола послије завршеног лијечења', 'Жжение и зуд при мочеиспускании, белёсые выделения, повторяющиеся жалобы, контроль после курса лечения', 'Brennen und Juckreiz beim Wasserlassen, weißlicher Ausfluss, wiederkehrende Beschwerden, Kontrolle nach einer Behandlung', 'İdrar yaparken yanma ve kaşıntı, beyazımsı akıntı, tekrarlayan şikayetler, tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the test and avoid sexual intercourse and local antifungal products the day before', 'Ne mokriti 2–3 sata prije uzimanja, dan ranije izbjegavati seksualne odnose i lokalne antimikotske preparate', 'Не мокрити 2–3 сата прије узимања, дан раније избјегавати сексуалне односе и локалне антимикотске препарате', 'Не мочиться 2–3 часа до забора, накануне исключить половые контакты и местные противогрибковые средства', '2–3 Stunden vor der Entnahme nicht Wasser lassen und am Vortag auf Geschlechtsverkehr sowie örtliche Antipilzmittel verzichten', 'Örnekten önce 2–3 saat idrara çıkılmamalı, bir gün öncesinden cinsel ilişki ve bölgesel antifungal ürünlerden kaçınılmalıdır', 'Detection of fungi may be related to a change of the local microflora, recent use of antibiotics, or accompanying conditions. The result is interpreted by a doctor', 'Nalaz gljivica može biti povezan sa promjenom lokalne mikroflore, nedavnim uzimanjem antibiotika ili pratećim stanjima. Nalaz tumači ljekar', 'Налаз гљивица може бити повезан са промјеном локалне микрофлоре, недавним узимањем антибиотика или пратећим стањима. Налаз тумачи љекар', 'Обнаружение грибов может быть связано с изменением местной микрофлоры, недавним приёмом антибиотиков или сопутствующими состояниями. Результат трактует врач', 'Ein Pilznachweis kann mit einer Veränderung der lokalen Mikroflora, einer kürzlichen Antibiotikaeinnahme oder Begleiterkrankungen zusammenhängen. Den Befund beurteilt der Arzt', 'Mantar saptanması yerel mikrofloranın değişmesiyle, yakın zamanda antibiyotik kullanımıyla veya eşlik eden durumlarla ilişkili olabilir. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vaginal-swab-bacteria'), 'Microbiological culture of vaginal discharge for bacterial flora', 'Mikrobiološka kultura vaginalnog sekreta na bakterijsku floru', 'Микробиолошка култура вагиналног секрета на бактеријску флору', 'Микробиологический посев отделяемого влагалища на бактериальную флору', 'Mikrobiologische Kultur des Vaginalsekrets auf Bakterienflora', 'Vajinal akıntının bakteri florası için mikrobiyolojik kültürü', 'The doctor collects material from the vaginal wall with a sterile swab, the procedure takes a couple of minutes', 'Ljekar uzima uzorak sterilnim štapićem sa zida vagine, postupak traje nekoliko minuta', 'Љекар узима узорак стерилним штапићем са зида вагине, поступак траје неколико минута', 'Врач берёт материал стерильным тампоном со стенки влагалища, процедура занимает пару минут', 'Der Arzt entnimmt das Material mit einem sterilen Tupfer von der Scheidenwand, der Abstrich dauert wenige Minuten', 'Hekim steril bir çubukla vajen duvarından örnek alır, işlem birkaç dakika sürer', 'Discharge, itching or burning, pregnancy planning and follow-up during pregnancy, check after treatment, preparation for gynaecological procedures', 'Pojačan sekret, svrab ili peckanje, planiranje trudnoće i praćenje u trudnoći, kontrola poslije liječenja, priprema za ginekološke zahvate', 'Појачан секрет, свраб или пецкање, планирање трудноће и праћење у трудноћи, контрола послије лијечења, припрема за гинеколошке захвате', 'Выделения, зуд или жжение, планирование беременности и наблюдение при беременности, контроль после лечения, подготовка к гинекологическим вмешательствам', 'Ausfluss, Juckreiz oder Brennen, Kinderwunsch und Kontrolle in der Schwangerschaft, Kontrolle nach einer Behandlung, Vorbereitung auf gynäkologische Eingriffe', 'Akıntı, kaşıntı veya yanma, gebelik planlaması ve gebelikte izlem, tedavi sonrası kontrol, jinekolojik girişimlere hazırlık', 'For a few days before, avoid vaginal suppositories, creams and douching, do not take the sample during menstruation, avoid intercourse the day before; exact intervals are confirmed by the doctor', 'Nekoliko dana prije ne koristiti vaginalete, kreme i ispiranja, uzorak se ne uzima tokom menstruacije, izbjegavati odnose dan ranije; tačne razmake određuje ljekar', 'Неколико дана прије не користити вагиналете, креме и испирања, узорак се не узима током менструације, избјегавати односе дан раније; тачне размаке одређује љекар', 'За несколько дней не использовать вагинальные свечи, кремы и спринцевания, не сдавать во время менструации, воздержаться от половых контактов накануне; точные сроки уточняет врач', 'Einige Tage vorher keine Vaginalzäpfchen, Cremes oder Spülungen verwenden, nicht während der Menstruation abnehmen, am Vortag auf Geschlechtsverkehr verzichten; genaue Abstände legt der Arzt fest', 'Birkaç gün önce vajinal fitil, krem ve vajinal duş uygulanmamalı, örnek adet döneminde alınmamalı, bir gün önce cinsel ilişkiden kaçınılmalı; kesin süreleri hekim belirler', 'Growth of bacteria and a change in the composition of the flora may be related to inflammation or to an imbalance of the vaginal microflora. The meaning of the result and the need for treatment are determined by the doctor', 'Porast bakterija i promjena sastava flore mogu biti povezani sa upalom ili sa poremećajem ravnoteže vaginalne mikroflore. Značenje nalaza i potrebu za liječenjem procjenjuje ljekar', 'Пораст бактерија и промјена састава флоре могу бити повезани са упалом или са поремећајем равнотеже вагиналне микрофлоре. Значење налаза и потребу за лијечењем процјењује љекар', 'Рост бактерий и изменение состава флоры могут быть связаны с воспалением или нарушением баланса микрофлоры. Значение результата и необходимость лечения определяет врач', 'Ein Wachstum von Bakterien und eine veränderte Zusammensetzung der Flora können mit einer Entzündung oder einem gestörten Gleichgewicht der Scheidenflora zusammenhängen. Die Bedeutung des Befundes und die Notwendigkeit einer Behandlung beurteilt der Arzt', 'Bakteri üremesi ve flora bileşimindeki değişiklik, iltihapla veya vajinal mikroflora dengesinin bozulmasıyla ilişkili olabilir. Sonucun anlamını ve tedavi gerekip gerekmediğini hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vaginal-swab-fungi'), 'Culture of vaginal discharge for yeast fungi, primarily of the Candida genus', 'Kultura vaginalnog sekreta na kvasnice, prije svega roda Candida', 'Култура вагиналног секрета на кваснице, прије свега рода Candida', 'Посев отделяемого влагалища на дрожжевые грибы, прежде всего рода Candida', 'Kultur des Vaginalsekrets auf Hefepilze, vor allem der Gattung Candida', 'Vajinal akıntının maya mantarları, öncelikle Candida için kültürü', 'Material is taken from the vaginal wall with a sterile swab and plated on a medium for fungi', 'Uzorak se uzima sterilnim štapićem sa zida vagine i zasijava na podlogu za gljivice', 'Узорак се узима стерилним штапићем са зида вагине и засијава на подлогу за гљивице', 'Материал берут стерильным тампоном со стенки влагалища и засевают на питательную среду для грибов', 'Das Material wird mit einem sterilen Tupfer von der Scheidenwand entnommen und auf einen Pilznährboden aufgebracht', 'Örnek steril çubukla vajen duvarından alınır ve mantar besiyerine ekilir', 'Thick curd-like discharge, itching and burning, recurring complaints, check after antifungal treatment, complaints while taking antibiotics', 'Gust sirast sekret, svrab i peckanje, tegobe koje se ponavljaju, kontrola poslije antimikotične terapije, tegobe tokom uzimanja antibiotika', 'Густ сираст секрет, свраб и пецкање, тегобе које се понављају, контрола послије антимикотичне терапије, тегобе током узимања антибиотика', 'Густые творожистые выделения, зуд и жжение, повторяющиеся жалобы, контроль после противогрибкового лечения, жалобы на фоне приёма антибиотиков', 'Dicker, quarkartiger Ausfluss, Juckreiz und Brennen, wiederkehrende Beschwerden, Kontrolle nach antimykotischer Behandlung, Beschwerden unter Antibiotikatherapie', 'Koyu peynirimsi akıntı, kaşıntı ve yanma, tekrarlayan şikayetler, antifungal tedavi sonrası kontrol, antibiyotik kullanırken ortaya çıkan şikayetler', 'For a few days before, avoid vaginal suppositories, creams and douching, do not take the sample during menstruation, avoid intercourse the day before', 'Nekoliko dana prije ne koristiti vaginalete i kreme, ne ispirati vaginu, uzorak se ne uzima tokom menstruacije, izbjegavati odnose dan ranije', 'Неколико дана прије не користити вагиналете и креме, не испирати вагину, узорак се не узима током менструације, избјегавати односе дан раније', 'За несколько дней не использовать вагинальные свечи и кремы, не спринцеваться, не сдавать во время менструации, воздержаться от половых контактов накануне', 'Einige Tage vorher keine Vaginalzäpfchen und Cremes verwenden, keine Spülungen, nicht während der Menstruation abnehmen, am Vortag auf Geschlechtsverkehr verzichten', 'Birkaç gün önce vajinal fitil ve krem kullanılmamalı, vajinal duş yapılmamalı, örnek adet döneminde alınmamalı, bir gün önce cinsel ilişkiden kaçınılmalı', 'Growth of fungi may be related to an overgrowth of yeast flora, including during antibiotic therapy, in pregnancy or with reduced immunity. Whether treatment is needed is decided by the doctor', 'Porast gljivica može biti povezan sa prekomjernim razmnožavanjem kvasnica, između ostalog uz antibiotike, u trudnoći ili kod snižene imunosti. Da li je liječenje potrebno, odlučuje ljekar', 'Пораст гљивица може бити повезан са прекомјерним размножавањем квасница, између осталог уз антибиотике, у трудноћи или код снижене имуности. Да ли је лијечење потребно, одлучује љекар', 'Рост грибов может быть связан с избыточным размножением дрожжевой флоры, в том числе на фоне антибиотиков, беременности или снижения иммунитета. Нужно ли лечение, определяет врач', 'Ein Pilzwachstum kann mit einer Vermehrung der Hefeflora zusammenhängen, unter anderem unter Antibiotika, in der Schwangerschaft oder bei geschwächter Abwehr. Ob eine Behandlung nötig ist, entscheidet der Arzt', 'Mantar üremesi, antibiyotik kullanımı, gebelik veya bağışıklığın azalması gibi durumlarda maya florasının çoğalmasıyla ilişkili olabilir. Tedavi gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vulvar-swab-bacteria'), 'Culture of material from the external genital area for bacterial flora', 'Kultura uzorka sa spoljašnjih genitalija na bakterijsku floru', 'Култура узорка са спољашњих гениталија на бактеријску флору', 'Посев материала с наружных половых органов на бактериальную флору', 'Kultur eines Abstrichs vom äußeren Genitalbereich auf Bakterienflora', 'Dış genital bölgeden alınan örneğin bakteri florası için kültürü', 'Material is taken with a sterile swab from the skin and mucosa of the vulva, without entering the vagina, and takes a couple of minutes', 'Uzorak se uzima sterilnim štapićem sa kože i sluznice vulve, bez ulaska u vaginu, i traje nekoliko minuta', 'Узорак се узима стерилним штапићем са коже и слузнице вулве, без уласка у вагину, и траје неколико минута', 'Материал берут стерильным тампоном с кожи и слизистой вульвы, без введения во влагалище, занимает пару минут', 'Das Material wird mit einem sterilen Tupfer von Haut und Schleimhaut der Vulva entnommen, ohne in die Scheide vorzugehen, und dauert wenige Minuten', 'Örnek steril çubukla vulva derisi ve mukozasından, vajene girilmeden alınır ve birkaç dakika sürer', 'Redness, swelling and itching of the external genitals, rashes, fissures and weeping, complaints in girls before the onset of sexual activity, check after treatment', 'Crvenilo, oticanje i svrab spoljašnjih genitalija, osip, ragade i vlaženje, tegobe kod djevojčica prije početka seksualnog života, kontrola poslije liječenja', 'Црвенило, отицање и свраб спољашњих гениталија, осип, рагаде и влажење, тегобе код дјевојчица прије почетка сексуалног живота, контрола послије лијечења', 'Покраснение, отёк и зуд наружных половых органов, высыпания, трещины и мокнутие, жалобы у девочек до начала половой жизни, контроль после лечения', 'Rötung, Schwellung und Juckreiz im äußeren Genitalbereich, Hautausschlag, Einrisse und Nässen, Beschwerden bei Mädchen vor Beginn der Sexualität, Kontrolle nach einer Behandlung', 'Dış genital bölgede kızarıklık, şişlik ve kaşıntı, döküntü, çatlak ve sulanma, cinsel yaşamı başlamamış kız çocuklarındaki şikayetler, tedavi sonrası kontrol', 'Do not apply ointments, antiseptics or powders before the visit and do not wash with soap right before the sample is taken; tell the doctor about any antibiotics taken', 'Prije uzimanja ne nanositi masti, antiseptike i puder, ne prati se sapunom neposredno prije pregleda; obavijestiti ljekara o antibioticima koji se uzimaju', 'Прије узимања не наносити масти, антисептике и пудер, не прати се сапуном непосредно прије прегледа; обавијестити љекара о антибиотицима који се узимају', 'Перед забором не наносить мази, антисептики и присыпки, не подмываться с мылом непосредственно перед приёмом; о принимаемых антибиотиках сообщить врачу', 'Vor der Entnahme keine Salben, Antiseptika oder Puder auftragen und sich unmittelbar davor nicht mit Seife waschen; eingenommene Antibiotika dem Arzt mitteilen', 'Örnek alınmadan önce merhem, antiseptik veya pudra uygulanmamalı ve hemen öncesinde sabunla yıkanmamalı; kullanılan antibiyotikler hekime bildirilmeli', 'Growth of bacteria may be related to inflammation of the vulvar skin and mucosa or to the normal flora of this area. The doctor evaluates the result together with the examination', 'Porast bakterija može biti povezan sa upalom kože i sluznice vulve ili sa uobičajenom florom tog područja. Značenje nalaza ljekar procjenjuje zajedno sa pregledom', 'Пораст бактерија може бити повезан са упалом коже и слузнице вулве или са уобичајеном флором тог подручја. Значење налаза љекар процјењује заједно са прегледом', 'Рост бактерий может быть связан с воспалением кожи и слизистой вульвы или с обычной флорой этой области. Значение результата вместе с осмотром оценивает врач', 'Ein Bakterienwachstum kann mit einer Entzündung von Haut und Schleimhaut der Vulva oder mit der üblichen Flora dieses Bereichs zusammenhängen. Der Arzt beurteilt den Befund zusammen mit der Untersuchung', 'Bakteri üremesi vulva deri ve mukozasındaki iltihapla ya da bu bölgenin olağan florasıyla ilişkili olabilir. Sonucu hekim muayeneyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vulvar-swab-fungi'), 'Culture of material from the skin and mucosa of the vulva for yeast fungi', 'Kultura uzorka sa kože i sluznice vulve na kvasnice', 'Култура узорка са коже и слузнице вулве на кваснице', 'Посев материала с кожи и слизистой вульвы на дрожжевые грибы', 'Kultur eines Abstrichs von Haut und Schleimhaut der Vulva auf Hefepilze', 'Vulva derisi ve mukozasından alınan örneğin maya mantarları için kültürü', 'A sterile swab collects material from the vulvar surface and the skin folds, then it is plated on a medium for fungi', 'Sterilnim štapićem uzima se uzorak sa površine vulve i iz nabora, a zatim se zasijava na podlogu za gljivice', 'Стерилним штапићем узима се узорак са површине вулве и из набора, а затим се засијава на подлогу за гљивице', 'Стерильным тампоном берут материал с поверхности вульвы и из складок, затем засевают на среду для грибов', 'Mit einem sterilen Tupfer wird Material von der Vulvaoberfläche und aus den Hautfalten entnommen und auf einen Pilznährboden aufgebracht', 'Steril çubukla vulva yüzeyinden ve kıvrımlardan örnek alınır, ardından mantar besiyerine ekilir', 'Itching and burning of the external genitals, redness and whitish coating in the folds, intertrigo, recurring complaints, complaints during antibiotic therapy or with diabetes mellitus', 'Svrab i peckanje spoljašnjih genitalija, crvenilo i bjelkaste naslage u naborima, intertrigo, tegobe koje se ponavljaju, tegobe uz antibiotike ili šećernu bolest', 'Свраб и пецкање спољашњих гениталија, црвенило и бјелкасте наслаге у наборима, интертриго, тегобе које се понављају, тегобе уз антибиотике или шећерну болест', 'Зуд и жжение наружных половых органов, покраснение и белесый налёт в складках, опрелости, повторяющиеся жалобы, жалобы на фоне антибиотиков или сахарного диабета', 'Juckreiz und Brennen im äußeren Genitalbereich, Rötung und weißliche Beläge in den Falten, Wundsein der Hautfalten, wiederkehrende Beschwerden, Beschwerden unter Antibiotika oder bei Diabetes mellitus', 'Dış genital bölgede kaşıntı ve yanma, kıvrımlarda kızarıklık ve beyazımsı örtü, pişik, tekrarlayan şikayetler, antibiyotik kullanımı veya diyabet sırasındaki şikayetler', 'Do not use antifungal creams or antiseptics before the sample is taken and do not wash with soap right before the visit', 'Prije uzimanja ne koristiti antimikotične kreme i antiseptike, ne prati se sapunom neposredno prije pregleda', 'Прије узимања не користити антимикотичне креме и антисептике, не прати се сапуном непосредно прије прегледа', 'Не использовать противогрибковые кремы и антисептики перед забором, не подмываться с мылом непосредственно перед приёмом', 'Vor der Entnahme keine Antipilzcremes und Antiseptika verwenden und sich unmittelbar davor nicht mit Seife waschen', 'Örnek alınmadan önce antifungal krem ve antiseptik kullanılmamalı, hemen öncesinde sabunla yıkanmamalı', 'Growth of fungi may be related to fungal involvement of the vulvar skin and mucosa or to carriage of yeast flora. Whether treatment is needed is decided by the doctor based on the examination and the complaints', 'Porast gljivica može biti povezan sa gljivičnom promjenom kože i sluznice vulve ili sa nošenjem kvasnica. Da li je liječenje potrebno, ljekar procjenjuje na osnovu pregleda i tegoba', 'Пораст гљивица може бити повезан са гљивичном промјеном коже и слузнице вулве или са ношењем квасница. Да ли је лијечење потребно, љекар процјењује на основу прегледа и тегоба', 'Рост грибов может быть связан с грибковым поражением кожи и слизистой вульвы или с носительством дрожжевой флоры. Нужно ли лечение, определяет врач по осмотру и жалобам', 'Ein Pilzwachstum kann mit einer Pilzbesiedlung von Haut und Schleimhaut der Vulva oder mit einer Besiedlung ohne Beschwerden zusammenhängen. Ob behandelt wird, entscheidet der Arzt nach Untersuchung und Beschwerden', 'Mantar üremesi vulva deri ve mukozasındaki mantar tutulumu ya da maya florası taşıyıcılığı ile ilişkili olabilir. Tedavi kararını hekim muayene ve şikayetlere göre verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cervical-swab-fungi'), 'Culture of material from the cervical canal for yeast fungi', 'Kultura uzorka iz kanala grlića materice na kvasnice', 'Култура узорка из канала грлића материце на кваснице', 'Посев материала из канала шейки матки на дрожжевые грибы', 'Kultur von Material aus dem Gebärmutterhalskanal auf Hefepilze', 'Rahim ağzı kanalından alınan örneğin maya mantarları için kültürü', 'The gynaecologist inserts a speculum and collects material from the cervical canal with a brush or a swab, the visit takes a few minutes', 'Ginekolog postavlja spekulum i četkicom ili štapićem uzima uzorak iz cervikalnog kanala, pregled traje nekoliko minuta', 'Гинеколог поставља спекулум и четкицом или штапићем узима узорак из цервикалног канала, преглед траје неколико минута', 'Гинеколог вводит зеркало и берёт материал щёточкой или тампоном из цервикального канала, осмотр занимает несколько минут', 'Der Gynäkologe führt ein Spekulum ein und entnimmt mit Bürstchen oder Tupfer Material aus dem Zervikalkanal, die Untersuchung dauert wenige Minuten', 'Jinekolog spekulum yerleştirir ve fırça ya da çubukla servikal kanaldan örnek alır, muayene birkaç dakika sürer', 'Persistent or recurring discharge, itching, follow-up during pregnancy, check after antifungal therapy, work-up before procedures on the cervix', 'Uporan ili povratan sekret, svrab, praćenje u trudnoći, kontrola poslije antimikotične terapije, obrada prije zahvata na grliću materice', 'Упоран или повратан секрет, свраб, праћење у трудноћи, контрола послије антимикотичне терапије, обрада прије захвата на грлићу материце', 'Стойкие или повторяющиеся выделения, зуд, наблюдение при беременности, контроль после противогрибковой терапии, обследование перед вмешательствами на шейке матки', 'Anhaltender oder wiederkehrender Ausfluss, Juckreiz, Kontrolle in der Schwangerschaft, Kontrolle nach antimykotischer Therapie, Abklärung vor Eingriffen am Gebärmutterhals', 'Sürekli veya tekrarlayan akıntı, kaşıntı, gebelikte izlem, antifungal tedavi sonrası kontrol, rahim ağzına yönelik girişimler öncesi değerlendirme', 'Not taken during menstruation; avoid vaginal medications, douching and intercourse for one to two days before', 'Ne uzima se tokom menstruacije; jedan do dva dana ranije izbjegavati vaginalne preparate, ispiranja i seksualne odnose', 'Не узима се током менструације; један до два дана раније избјегавати вагиналне препарате, испирања и сексуалне односе', 'Не сдают во время менструации; за один-два дня исключить вагинальные препараты, спринцевания и половые контакты', 'Nicht während der Menstruation; ein bis zwei Tage vorher keine Vaginalpräparate, keine Spülungen und keinen Geschlechtsverkehr', 'Adet döneminde alınmaz; bir iki gün önce vajinal ilaçlar, vajinal duş ve cinsel ilişkiden kaçınılmalı', 'Detection of fungi may be related to their overgrowth in the genital tract or to symptom-free carriage. The meaning of the result and the next steps are determined by the gynaecologist', 'Nalaz gljivica može biti povezan sa njihovim prekomjernim rastom u genitalnom traktu ili sa nošenjem bez tegoba. Značenje nalaza i dalje korake određuje ginekolog', 'Налаз гљивица може бити повезан са њиховим прекомјерним растом у гениталном тракту или са ношењем без тегоба. Значење налаза и даље кораке одређује гинеколог', 'Обнаружение грибов может быть связано с их избыточным ростом в половых путях или с бессимптомным носительством. Значение результата и дальнейшие шаги определяет гинеколог', 'Der Nachweis von Pilzen kann mit deren vermehrtem Wachstum im Genitaltrakt oder mit einer beschwerdefreien Besiedlung zusammenhängen. Bedeutung des Befundes und weiteres Vorgehen legt der Gynäkologe fest', 'Mantar saptanması, genital yolda aşırı çoğalma ya da belirtisiz taşıyıcılıkla ilişkili olabilir. Sonucun anlamını ve sonraki adımları jinekolog belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'oral-cavity-fungi'), 'Culture of material from the oral mucosa for yeast fungi', 'Kultura brisa sluznice usne duplje na kvasnice', 'Култура бриса слузнице усне дупље на кваснице', 'Посев материала со слизистой рта на дрожжевые грибы', 'Kultur eines Abstrichs der Mundschleimhaut auf Hefepilze', 'Ağız mukozasından alınan örneğin maya mantarları için kültürü', 'A sterile swab is taken from the mucosa of the cheeks, the palate and the gums, it takes less than a minute', 'Bris se uzima sterilnim štapićem sa sluznice obraza, nepca i desni, traje manje od minuta', 'Брис се узима стерилним штапићем са слузнице образа, непца и десни, траје мање од минута', 'Мазок берут стерильным тампоном со слизистой щёк, нёба и дёсен, занимает меньше минуты', 'Der Abstrich wird mit einem sterilen Tupfer von Wangenschleimhaut, Gaumen und Zahnfleisch genommen und dauert weniger als eine Minute', 'Steril çubukla yanak, damak ve diş eti mukozasından sürüntü alınır, bir dakikadan kısa sürer', 'White coating in the mouth, burning and dryness, discomfort under a removable denture, complaints during antibiotics or inhaled corticosteroids, work-up in infants', 'Bijele naslage u ustima, peckanje i suvoća, nelagoda ispod pokretne proteze, tegobe uz antibiotike ili inhalacione kortikosteroide, obrada kod odojčadi', 'Бијеле наслаге у устима, пецкање и сувоћа, нелагода испод покретне протезе, тегобе уз антибиотике или инхалационе кортикостероиде, обрада код одојчади', 'Белый налёт во рту, жжение и сухость, неприятные ощущения под съёмным протезом, жалобы на фоне антибиотиков или ингаляционных гормонов, обследование грудных детей', 'Weißliche Beläge im Mund, Brennen und Trockenheit, Beschwerden unter einer herausnehmbaren Prothese, Beschwerden unter Antibiotika oder inhalativen Kortikosteroiden, Abklärung bei Säuglingen', 'Ağızda beyaz örtü, yanma ve kuruluk, hareketli protez altında rahatsızlık, antibiyotik veya inhaler kortikosteroid kullanımı sırasındaki şikayetler, süt çocuklarında değerlendirme', 'In the morning before eating, drinking and brushing teeth, without antiseptic mouth rinses and without smoking before the sample', 'Ujutru prije jela, pića i pranja zuba, bez ispiranja usta antisepticima i bez pušenja prije uzimanja uzorka', 'Ујутру прије јела, пића и прања зуба, без испирања уста антисептицима и без пушења прије узимања узорка', 'Утром до еды, питья и чистки зубов, не полоскать рот антисептиками и не курить перед забором', 'Morgens vor dem Essen, Trinken und Zähneputzen, ohne antiseptische Mundspülungen und ohne Rauchen vor der Entnahme', 'Sabah yemek, içecek ve diş fırçalamadan önce, antiseptik gargara yapılmadan ve sigara içilmeden örnek verilmeli', 'Growth of fungi may be related to their overgrowth on the oral mucosa or to carriage without symptoms. The doctor evaluates the result together with the examination of the mouth', 'Porast gljivica može biti povezan sa njihovim prekomjernim razmnožavanjem na sluznici usta ili sa nošenjem bez tegoba. Značenje nalaza ljekar procjenjuje zajedno sa pregledom usne duplje', 'Пораст гљивица може бити повезан са њиховим прекомјерним размножавањем на слузници уста или са ношењем без тегоба. Значење налаза љекар процјењује заједно са прегледом усне дупље', 'Рост грибов может быть связан с их избыточным размножением на слизистой рта или с носительством. Значение результата оценивает врач вместе с осмотром полости рта', 'Ein Pilzwachstum kann mit einer Vermehrung auf der Mundschleimhaut oder mit einer Besiedlung ohne Beschwerden zusammenhängen. Der Arzt beurteilt den Befund zusammen mit der Untersuchung der Mundhöhle', 'Mantar üremesi ağız mukozasında aşırı çoğalma ya da belirtisiz taşıyıcılıkla ilişkili olabilir. Sonucu hekim ağız içi muayenesiyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'throat-swab-bacteria'), 'Culture of material from the tonsils and the back of the throat for bacterial flora', 'Kultura brisa krajnika i zadnjeg zida ždrijela na bakterijsku floru', 'Култура бриса крајника и задњег зида ждријела на бактеријску флору', 'Посев материала с миндалин и задней стенки глотки на бактериальную флору', 'Kultur eines Abstrichs von Mandeln und Rachenhinterwand auf Bakterienflora', 'Bademcikler ve arka boğaz duvarından alınan örneğin bakteri florası için kültürü', 'A swab is passed over the tonsils and the posterior pharyngeal wall, it takes a few seconds', 'Štapićem se prelazi preko krajnika i zadnjeg zida ždrijela, uzimanje traje nekoliko sekundi', 'Штапићем се прелази преко крајника и задњег зида ждријела, узимање траје неколико секунди', 'Тампоном проводят по миндалинам и задней стенке глотки, забор занимает несколько секунд', 'Mit dem Tupfer wird über Mandeln und Rachenhinterwand gestrichen, die Entnahme dauert wenige Sekunden', 'Çubuk bademcikler ve arka boğaz duvarı üzerinden geçirilir, alım birkaç saniye sürer', 'Sore throat, coating on the tonsils, prolonged or recurring tonsillitis, checking for carriage, work-up before planned surgery, health certificates for food industry and childcare staff', 'Bol u grlu, naslage na krajnicima, produžen ili povratan tonzilitis, provjera kliconoštva, obrada prije planirane operacije, sanitarni pregledi za rad sa hranom i u vrtićima', 'Бол у грлу, наслаге на крајницима, продужен или повратан тонзилитис, провјера клицоноштва, обрада прије планиране операције, санитарни прегледи за рад са храном и у вртићима', 'Боль в горле, налёты на миндалинах, затяжной или повторяющийся тонзиллит, проверка носительства, обследование перед плановой операцией, санитарные осмотры для работы с пищей и в детских учреждениях', 'Halsschmerzen, Beläge auf den Mandeln, langwierige oder wiederkehrende Mandelentzündung, Abklärung einer Keimträgerschaft, Vorbereitung auf geplante Operationen, Untersuchungen für Lebensmittelberufe und Kinderbetreuung', 'Boğaz ağrısı, bademciklerde örtü, uzamış veya tekrarlayan bademcik iltihabı, taşıyıcılık kontrolü, planlı ameliyat öncesi değerlendirme, gıda ve çocuk bakımı alanında çalışanların sağlık kontrolleri', 'In the morning on an empty stomach, before brushing teeth, without gargling, throat sprays or lozenges; antibiotics only as agreed with the doctor', 'Ujutru natašte, prije pranja zuba, bez ispiranja grla, sprejeva i pastila; antibiotike uzimati samo u dogovoru sa ljekarom', 'Ујутру наташте, прије прања зуба, без испирања грла, спрејева и пастила; антибиотике узимати само у договору са љекаром', 'Утром натощак, до чистки зубов, без полоскания горла, спреев и пастилок; антибиотики принимать только по согласованию с врачом', 'Morgens nüchtern, vor dem Zähneputzen, ohne Gurgeln, Rachensprays und Lutschtabletten; Antibiotika nur nach Rücksprache mit dem Arzt', 'Sabah aç karnına, diş fırçalamadan önce, gargara, boğaz spreyi ve pastil kullanmadan; antibiyotikler yalnızca hekimle görüşerek', 'Detection of bacteria may indicate an infection as well as symptom-free carriage. Whether and how to treat is decided by the doctor based on the clinical picture and the antibiogram', 'Nalaz bakterija može ukazivati na infekciju, ali i na kliconoštvo bez tegoba. Da li i kako liječiti, odlučuje ljekar na osnovu kliničke slike i antibiograma', 'Налаз бактерија може указивати на инфекцију, али и на клицоноштво без тегоба. Да ли и како лијечити, одлучује љекар на основу клиничке слике и антибиограма', 'Обнаружение бактерий может говорить как об инфекции, так и о бессимптомном носительстве. Нужно ли лечение и какое, решает врач по клинической картине и антибиотикограмме', 'Der Nachweis von Bakterien kann für eine Infektion, aber auch für eine beschwerdefreie Keimträgerschaft sprechen. Ob und wie behandelt wird, entscheidet der Arzt anhand des klinischen Bildes und des Antibiogramms', 'Bakteri saptanması enfeksiyonu da belirtisiz taşıyıcılığı da gösterebilir. Tedavi gerekip gerekmediğine ve nasıl olacağına hekim klinik tablo ve antibiyograma göre karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'tongue-swab-fungi'), 'Culture of material from the surface of the tongue for yeast fungi', 'Kultura brisa sa površine jezika na kvasnice', 'Култура бриса са површине језика на кваснице', 'Посев материала с поверхности языка на дрожжевые грибы', 'Kultur eines Abstrichs von der Zungenoberfläche auf Hefepilze', 'Dil yüzeyinden alınan örneğin maya mantarları için kültürü', 'A swab is passed over the back of the tongue and any coating on it, the procedure takes a few seconds', 'Štapićem se prelazi preko površine jezika i naslaga na njemu, postupak traje nekoliko sekundi', 'Штапићем се прелази преко површине језика и наслага на њему, поступак траје неколико секунди', 'Тампоном проводят по спинке языка и налёту на ней, процедура занимает несколько секунд', 'Mit dem Tupfer wird über den Zungenrücken und vorhandene Beläge gestrichen, das dauert wenige Sekunden', 'Çubuk dil sırtı ve üzerindeki örtü boyunca geçirilir, işlem birkaç saniye sürer', 'White or curd-like coating on the tongue, burning and altered taste, dry mouth, complaints during antibiotics, with dentures or with inhalers', 'Bijele ili siraste naslage na jeziku, peckanje i promjena ukusa, suva usta, tegobe uz antibiotike, zubne proteze ili inhalatore', 'Бијеле или сирасте наслаге на језику, пецкање и промјена укуса, сува уста, тегобе уз антибиотике, зубне протезе или инхалаторе', 'Белый или творожистый налёт на языке, жжение и изменение вкуса, сухость во рту, жалобы на фоне антибиотиков, зубных протезов или ингаляторов', 'Weißer oder quarkartiger Belag auf der Zunge, Brennen und Geschmacksveränderung, Mundtrockenheit, Beschwerden unter Antibiotika, mit Zahnersatz oder Inhalatoren', 'Dilde beyaz veya peynirimsi örtü, yanma ve tat değişikliği, ağız kuruluğu, antibiyotik kullanımı, protez veya inhaler kullananlardaki şikayetler', 'Before eating, drinking and brushing teeth, without antiseptic rinses and without cleaning the tongue with a scraper', 'Prije jela, pića i pranja zuba, bez ispiranja antisepticima i bez čišćenja jezika strugačem', 'Прије јела, пића и прања зуба, без испирања антисептицима и без чишћења језика стругачем', 'До еды, питья и чистки зубов, без полосканий антисептиками и без чистки языка скребком', 'Vor dem Essen, Trinken und Zähneputzen, ohne antiseptische Spülungen und ohne Reinigung der Zunge mit einem Schaber', 'Yemek, içecek ve diş fırçalamadan önce, antiseptik gargara yapılmadan ve dil kazıyıcı kullanılmadan', 'Growth of fungi may be related to their overgrowth on the tongue or to carriage, including in smokers and denture wearers. The interpretation is given by the doctor taking the examination into account', 'Porast gljivica može biti povezan sa njihovim prekomjernim razmnožavanjem na jeziku ili sa nošenjem, i kod pušača i kod nosilaca proteza. Tumačenje daje ljekar uz pregled', 'Пораст гљивица може бити повезан са њиховим прекомјерним размножавањем на језику или са ношењем, и код пушача и код носилаца протеза. Тумачење даје љекар уз преглед', 'Рост грибов может быть связан с их избыточным размножением на языке или с носительством, в том числе у курильщиков и носителей протезов. Трактовку даёт врач с учётом осмотра', 'Ein Pilzwachstum kann mit einer Vermehrung auf der Zunge oder mit einer Besiedlung zusammenhängen, auch bei Rauchern und Prothesenträgern. Die Deutung erfolgt durch den Arzt unter Berücksichtigung der Untersuchung', 'Mantar üremesi dilde aşırı çoğalma ya da taşıyıcılıkla ilişkili olabilir, bu sigara içenlerde ve protez kullananlarda da görülür. Yorumu hekim muayeneyle birlikte yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urine-culture'), 'Bacteriological testing of urine with determination of antibiotic sensitivity', 'Zasijavanje urina radi otkrivanja bakterija i određivanja njihove osjetljivosti na antibiotike', 'Засијавање урина ради откривања бактерија и одређивања њихове осјетљивости на антибиотике', 'Бактериологическое исследование мочи с определением чувствительности бактерий к антибиотикам', 'Bakteriologische Untersuchung des Urins mit Bestimmung der Antibiotikaempfindlichkeit', 'İdrarda bakteri saptamak ve antibiyotik duyarlılığını belirlemek için yapılan bakteriyolojik inceleme', 'The patient collects a midstream portion of morning urine into a sterile container, the laboratory plates the sample on a nutrient medium', 'Pacijent sam sakuplja srednji mlaz jutarnjeg urina u sterilnu posudu, a laboratorija uzorak zasijava na hranljivu podlogu', 'Пацијент сам сакупља средњи млаз јутарњег урина у стерилну посуду, а лабораторија узорак засијава на хранљиву подлогу', 'Пациент сам собирает среднюю порцию утренней мочи в стерильный контейнер, лаборатория засевает материал на питательную среду', 'Der Patient fängt selbst den Mittelstrahl des Morgenurins in einem sterilen Gefäß auf, das Labor bringt die Probe auf einen Nährboden', 'Hasta sabah idrarının orta kısmını steril kaba kendisi toplar, laboratuvar örneği besiyerine eker', 'Burning and frequent urination, pain in the lower abdomen or in the lower back, recurring urinary tract infections, follow-up during pregnancy, check after treatment', 'Peckanje i često mokrenje, bol u donjem dijelu trbuha ili u krstima, ponavljane infekcije mokraćnih puteva, praćenje u trudnoći, kontrola poslije liječenja', 'Пецкање и често мокрење, бол у доњем дијелу трбуха или у крстима, понављане инфекције мокраћних путева, праћење у трудноћи, контрола послије лијечења', 'Жжение и частое мочеиспускание, боль внизу живота или в пояснице, повторяющиеся инфекции мочевых путей, наблюдение при беременности, контроль после лечения', 'Brennen und häufiges Wasserlassen, Schmerzen im Unterbauch oder in der Flanke, wiederkehrende Harnwegsinfekte, Kontrolle in der Schwangerschaft, Kontrolle nach einer Behandlung', 'İdrarda yanma ve sık idrara çıkma, alt karın veya bel ağrısı, tekrarlayan idrar yolu enfeksiyonları, gebelikte izlem, tedavi sonrası kontrol', 'Collect the midstream morning portion into a sterile container after washing the external genitals, before starting antibiotics or as instructed by the doctor, and deliver it to the laboratory as soon as possible', 'Sakupiti srednji mlaz jutarnjeg urina u sterilnu posudu poslije pranja spoljašnjih genitalija, prije početka antibiotika ili po uputstvu ljekara, i dostaviti u laboratoriju što prije', 'Сакупити средњи млаз јутарњег урина у стерилну посуду послије прања спољашњих гениталија, прије почетка антибиотика или по упутству љекара, и доставити у лабораторију што прије', 'Собрать среднюю порцию утренней мочи после туалета наружных половых органов в стерильный контейнер, до начала приёма антибиотиков или по указанию врача, и доставить в лабораторию как можно быстрее', 'Den Mittelstrahl des Morgenurins nach Reinigung des Genitalbereichs in einem sterilen Gefäß auffangen, vor Beginn einer Antibiotikatherapie oder nach ärztlicher Anweisung, und möglichst rasch ins Labor bringen', 'Dış genital bölge temizlendikten sonra sabah idrarının orta kısmı steril kaba toplanmalı, antibiyotiğe başlamadan önce veya hekimin önerdiği şekilde verilmeli ve laboratuvara en kısa sürede ulaştırılmalı', 'Growth of bacteria may be related to a urinary tract infection and also to errors in collecting the sample. The result together with the antibiogram is assessed by the doctor', 'Porast bakterija može biti povezan sa infekcijom mokraćnih puteva, ali i sa greškama pri sakupljanju uzorka. Nalaz zajedno sa antibiogramom procjenjuje ljekar', 'Пораст бактерија може бити повезан са инфекцијом мокраћних путева, али и са грешкама при сакупљању узорка. Налаз заједно са антибиограмом процјењује љекар', 'Рост бактерий может быть связан с инфекцией мочевых путей, а также с погрешностями сбора материала. Результат вместе с антибиотикограммой оценивает врач', 'Ein Bakterienwachstum kann mit einem Harnwegsinfekt, aber auch mit Fehlern bei der Probengewinnung zusammenhängen. Befund und Antibiogramm beurteilt der Arzt', 'Bakteri üremesi idrar yolu enfeksiyonuyla olduğu kadar örnek toplama hatalarıyla da ilişkili olabilir. Sonucu antibiyogramla birlikte hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'amine-test'), 'Quick bedside test on vaginal discharge: the odour is assessed after adding an alkaline solution', 'Brzi test vaginalnog sekreta: miris se procjenjuje poslije dodavanja alkalnog rastvora', 'Брзи тест вагиналног секрета: мирис се процјењује послије додавања алкалног раствора', 'Быстрая проба отделяемого влагалища: запах оценивают после добавления щелочного раствора', 'Schnelltest des Vaginalsekrets: der Geruch wird nach Zugabe einer alkalischen Lösung beurteilt', 'Vajinal akıntıya uygulanan hızlı test: alkali çözelti eklendikten sonra koku değerlendirilir', 'A drop of discharge is mixed with KOH solution and the odour is assessed immediately, it takes less than a minute', 'Kap sekreta se pomiješa sa rastvorom KOH i miris se odmah procjenjuje, traje manje od minuta', 'Кап секрета се помијеша са раствором KOH и мирис се одмах процјењује, траје мање од минута', 'Каплю отделяемого смешивают с раствором KOH и сразу оценивают запах, занимает меньше минуты', 'Ein Tropfen Sekret wird mit KOH-Lösung vermischt und der Geruch sofort beurteilt, das dauert weniger als eine Minute', 'Bir damla akıntı KOH çözeltisiyle karıştırılır ve koku hemen değerlendirilir, bir dakikadan kısa sürer', 'Discharge with an odour, work-up of a suspected change in the vaginal flora, usually together with a smear and a pH test', 'Sekret sa mirisom, obrada kod sumnje na promjenu vaginalne flore, obično uz nativni bris i pH test', 'Секрет са мирисом, обрада код сумње на промјену вагиналне флоре, обично уз нативни брис и пХ тест', 'Выделения с запахом, обследование при подозрении на изменение микрофлоры влагалища, обычно вместе с мазком и pH-тестом', 'Ausfluss mit Geruch, Abklärung bei Verdacht auf eine veränderte Scheidenflora, meist zusammen mit Nativpräparat und pH-Test', 'Kokulu akıntı, vajinal florada değişiklik düşünüldüğünde yapılan değerlendirme, genellikle sürüntü ve pH testiyle birlikte', 'Not done during menstruation; avoid douching, vaginal medications and intercourse the day before', 'Ne radi se tokom menstruacije; dan ranije izbjegavati ispiranja, vaginalne preparate i seksualne odnose', 'Не ради се током менструације; дан раније избјегавати испирања, вагиналне препарате и сексуалне односе', 'Не проводят во время менструации; накануне исключить спринцевания, вагинальные препараты и половые контакты', 'Nicht während der Menstruation; am Vortag keine Spülungen, keine Vaginalpräparate und keinen Geschlechtsverkehr', 'Adet döneminde yapılmaz; bir gün önce vajinal duş, vajinal ilaç ve cinsel ilişkiden kaçınılmalı', 'A positive test may be related to a change in the composition of the vaginal flora. It is only one of several signs, and the conclusion is drawn by the doctor together with the smear and other tests', 'Pozitivan test može biti povezan sa promjenom sastava vaginalne flore. To je samo jedan od znakova, a zaključak donosi ljekar zajedno sa brisom i drugim testovima', 'Позитиван тест може бити повезан са промјеном састава вагиналне флоре. То је само један од знакова, а закључак доноси љекар заједно са брисом и другим тестовима', 'Положительная проба может быть связана с изменением состава микрофлоры влагалища. Это лишь один из признаков, итог оценивает врач вместе с мазком и другими тестами', 'Ein positiver Test kann mit einer veränderten Zusammensetzung der Scheidenflora zusammenhängen. Er ist nur eines von mehreren Zeichen, die Gesamtbeurteilung nimmt der Arzt zusammen mit dem Abstrich und weiteren Tests vor', 'Testin pozitif olması vajinal flora bileşimindeki değişiklikle ilişkili olabilir. Bu yalnızca bulgulardan biridir, sonucu hekim sürüntü ve diğer testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'blood-culture'), 'Test that detects bacteria which have entered the bloodstream by growing them in culture bottles', 'Zasijavanje krvi radi otkrivanja bakterija dospjelih u krvotok', 'Засијавање крви ради откривања бактерија доспјелих у крвоток', 'Посев крови для выявления бактерий, попавших в кровоток', 'Nachweis von Bakterien, die in die Blutbahn gelangt sind, durch Anzucht in Kulturflaschen', 'Kan dolaşımına geçmiş bakterileri besiyerli şişelerde üreterek saptayan inceleme', 'Blood is drawn from a vein after careful skin disinfection and put straight into bottles with culture medium, usually from two separate punctures', 'Krv se vadi iz vene poslije pažljive dezinfekcije kože i odmah unosi u bočice sa hranljivom podlogom, obično iz dva odvojena uboda', 'Крв се вади из вене послије пажљиве дезинфекције коже и одмах уноси у бочице са хранљивом подлогом, обично из два одвојена убода', 'Кровь берут из вены после тщательной обработки кожи и сразу вносят во флаконы с питательной средой, обычно из двух отдельных проколов', 'Blut wird nach sorgfältiger Hautdesinfektion aus einer Vene entnommen und sofort in Flaschen mit Nährmedium gegeben, meist aus zwei getrennten Punktionen', 'Kan, deri dikkatle dezenfekte edildikten sonra damardan alınır ve doğrudan besiyerli şişelere konur, genellikle iki ayrı girişimle', 'High fever and chills of unclear origin, suspected severe infection, fever in a patient with a catheter or an implant, monitoring in hospital', 'Visoka temperatura i drhtavica nejasnog porijekla, sumnja na tešku infekciju, temperatura kod pacijenta sa kateterom ili ugrađenim materijalom, praćenje u bolnici', 'Висока температура и дрхтавица нејасног поријекла, сумња на тешку инфекцију, температура код пацијента са катетером или уграђеним материјалом, праћење у болници', 'Высокая температура и озноб неясного происхождения, подозрение на тяжёлую инфекцию, лихорадка у пациента с катетером или имплантом, наблюдение в стационаре', 'Hohes Fieber und Schüttelfrost unklarer Ursache, Verdacht auf eine schwere Infektion, Fieber bei Patienten mit Katheter oder Implantat, Überwachung im Krankenhaus', 'Nedeni belirsiz yüksek ateş ve titreme, ağır enfeksiyon düşünülmesi, kateteri veya implantı olan hastada ateş, hastanede izlem', 'No special preparation; the sample is usually taken before antibiotics are started or just before the next dose, most often as the temperature rises', 'Nema posebne pripreme; uzorak se nastoji uzeti prije uvođenja antibiotika ili neposredno prije sljedeće doze, najčešće pri porastu temperature', 'Нема посебне припреме; узорак се настоји узети прије увођења антибиотика или непосредно прије сљедеће дозе, најчешће при порасту температуре', 'Специальной подготовки нет; кровь стараются взять до начала антибиотиков или перед очередной дозой, чаще на подъёме температуры', 'Keine besondere Vorbereitung; die Probe wird möglichst vor Beginn einer Antibiotikatherapie oder kurz vor der nächsten Gabe entnommen, meist beim Fieberanstieg', 'Özel bir hazırlık gerekmez; örnek genellikle antibiyotiğe başlamadan önce veya bir sonraki dozdan hemen önce, çoğunlukla ateş yükselirken alınır', 'Growth of bacteria may indicate that a pathogen has entered the blood, but it may also result from contamination of the sample with skin flora. The result and the antibiogram are assessed by the doctor', 'Porast bakterija može značiti da je uzročnik dospio u krv, ali može biti i posljedica kontaminacije uzorka kožnom florom. Nalaz i antibiogram procjenjuje ljekar', 'Пораст бактерија може значити да је узрочник доспио у крв, али може бити и посљедица контаминације узорка кожном флором. Налаз и антибиограм процјењује љекар', 'Рост бактерий может говорить о попадании возбудителя в кровь, а может быть следствием загрязнения пробы кожной флорой. Результат и антибиотикограмму оценивает врач', 'Ein Bakterienwachstum kann bedeuten, dass ein Erreger ins Blut gelangt ist, kann aber auch durch eine Verunreinigung der Probe mit Hautflora entstehen. Befund und Antibiogramm beurteilt der Arzt', 'Bakteri üremesi etkenin kana geçtiğini gösterebileceği gibi örneğin deri florasıyla kirlenmesinden de kaynaklanabilir. Sonucu ve antibiyogramı hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ear-swab-fungi'), 'Culture of material from the external ear canal for yeast and mould fungi', 'Kultura uzorka iz spoljašnjeg slušnog kanala na kvasnice i plijesni', 'Култура узорка из спољашњег слушног канала на кваснице и плијесни', 'Посев материала из наружного слухового прохода на дрожжевые и плесневые грибы', 'Kultur eines Abstrichs aus dem äußeren Gehörgang auf Hefe- und Schimmelpilze', 'Dış kulak yolundan alınan örneğin maya ve küf mantarları için kültürü', 'The doctor takes material from the ear canal with a thin sterile swab, it takes a couple of minutes', 'Ljekar tankim sterilnim štapićem uzima uzorak iz spoljašnjeg slušnog kanala, traje nekoliko minuta', 'Љекар танким стерилним штапићем узима узорак из спољашњег слушног канала, траје неколико минута', 'Врач берёт материал тонким стерильным тампоном из наружного слухового прохода, занимает пару минут', 'Der Arzt entnimmt mit einem dünnen sterilen Tupfer Material aus dem äußeren Gehörgang, das dauert wenige Minuten', 'Hekim ince steril bir çubukla dış kulak yolundan örnek alır, işlem birkaç dakika sürer', 'Itching and a blocked feeling in the ear, discharge, long-lasting inflammation of the outer ear that does not respond to treatment, complaints after swimming or in users of hearing aids and earphones', 'Svrab i osjećaj zapušenosti uha, sekrecija, dugotrajna upala spoljašnjeg uha bez odgovora na terapiju, tegobe poslije kupanja ili kod korisnika slušnih aparata i slušalica', 'Свраб и осјећај запушености уха, секреција, дуготрајна упала спољашњег уха без одговора на терапију, тегобе послије купања или код корисника слушних апарата и слушалица', 'Зуд и заложенность уха, выделения, длительное воспаление наружного уха без эффекта от лечения, жалобы после купания или у пользователей слуховых аппаратов и наушников', 'Juckreiz und Verstopfungsgefühl im Ohr, Sekretion, langwierige Entzündung des äußeren Ohrs ohne Besserung unter Therapie, Beschwerden nach dem Schwimmen oder bei Trägern von Hörgeräten und Kopfhörern', 'Kulakta kaşıntı ve tıkanıklık hissi, akıntı, tedaviye yanıt vermeyen uzun süreli dış kulak iltihabı, yüzme sonrası veya işitme cihazı ve kulaklık kullananlardaki şikayetler', 'Do not use ear drops and do not clean the ear before the sample; if drops have already been used, tell the doctor', 'Prije uzimanja uzorka ne ukapavati kapi i ne čistiti uho; ako su kapi već korišćene, obavijestiti ljekara', 'Прије узимања узорка не укапавати капи и не чистити ухо; ако су капи већ коришћене, обавијестити љекара', 'Перед забором не закапывать капли и не чистить ухо; если капли уже применялись, сообщить врачу', 'Vor der Entnahme keine Ohrentropfen anwenden und das Ohr nicht reinigen; wurden bereits Tropfen verwendet, den Arzt informieren', 'Örnek alınmadan önce kulak damlası damlatılmamalı ve kulak temizlenmemeli; damla kullanıldıysa hekime bildirilmeli', 'Growth of fungi may be related to a fungal inflammation of the external ear or to carriage. How to interpret the result is decided by the ENT doctor', 'Porast gljivica može biti povezan sa gljivičnom upalom spoljašnjeg uha ili sa nošenjem bez tegoba. Kako tumačiti nalaz, odlučuje ORL ljekar', 'Пораст гљивица може бити повезан са гљивичном упалом спољашњег уха или са ношењем без тегоба. Како тумачити налаз, одлучује ОРЛ љекар', 'Рост грибов может быть связан с грибковым воспалением наружного уха или с носительством. Как трактовать результат, решает ЛОР-врач', 'Ein Pilzwachstum kann mit einer Pilzentzündung des äußeren Ohrs oder mit einer Besiedlung ohne Beschwerden zusammenhängen. Wie der Befund zu deuten ist, entscheidet der HNO-Arzt', 'Mantar üremesi dış kulak mantar iltihabı ya da belirtisiz taşıyıcılıkla ilişkili olabilir. Sonucun nasıl yorumlanacağına KBB hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'eye-swab-chlamydia'), 'Testing of material from the conjunctiva for Chlamydia trachomatis', 'Ispitivanje uzorka sa konjunktive na Chlamydia trachomatis', 'Испитивање узорка са коњунктиве на Chlamydia trachomatis', 'Исследование материала с конъюнктивы на Chlamydia trachomatis', 'Untersuchung eines Abstrichs von der Bindehaut auf Chlamydia trachomatis', 'Konjonktivadan alınan örnekte Chlamydia trachomatis araştırılması', 'Material is collected with a swab or a brush from the inner surface of the eyelid, the procedure takes a couple of minutes', 'Uzorak se uzima štapićem ili četkicom sa unutrašnje strane kapka, postupak traje nekoliko minuta', 'Узорак се узима штапићем или четкицом са унутрашње стране капка, поступак траје неколико минута', 'Материал берут тампоном или щёточкой с внутренней поверхности века, процедура занимает пару минут', 'Das Material wird mit Tupfer oder Bürstchen von der Innenseite des Lids entnommen, die Entnahme dauert wenige Minuten', 'Örnek göz kapağının iç yüzünden çubuk veya fırçayla alınır, işlem birkaç dakika sürer', 'Prolonged conjunctivitis that does not respond to usual treatment, conjunctivitis in newborns, testing on referral from an ophthalmologist', 'Dugotrajan konjunktivitis koji ne reaguje na uobičajenu terapiju, konjunktivitis kod novorođenčadi, ispitivanje po uputu oftalmologa', 'Дуготрајан коњунктивитис који не реагује на уобичајену терапију, коњунктивитис код новорођенчади, испитивање по упуту офталмолога', 'Затяжной конъюнктивит, не отвечающий на обычное лечение, конъюнктивит у новорождённых, обследование по направлению офтальмолога', 'Langwierige Bindehautentzündung ohne Besserung unter üblicher Therapie, Bindehautentzündung bei Neugeborenen, Untersuchung auf Überweisung des Augenarztes', 'Olağan tedaviye yanıt vermeyen uzamış konjonktivit, yenidoğanda konjonktivit, göz hekiminin yönlendirmesiyle yapılan inceleme', 'Do not use eye drops or ointments before the sample and avoid eye make-up; the interval after antibiotics is specified by the doctor', 'Prije uzimanja uzorka ne ukapavati kapi i ne nanositi masti, izbjegavati šminku za oči; razmak poslije antibiotika određuje ljekar', 'Прије узимања узорка не укапавати капи и не наносити масти, избјегавати шминку за очи; размак послије антибиотика одређује љекар', 'Перед забором не закапывать глазные капли и не наносить мази, не пользоваться косметикой для глаз; паузу после антибиотиков уточняет врач', 'Vor der Entnahme keine Augentropfen und Salben anwenden, kein Augen-Make-up; den Abstand zu einer Antibiotikatherapie legt der Arzt fest', 'Örnek alınmadan önce göz damlası ve merhem kullanılmamalı, göz makyajından kaçınılmalı; antibiyotik sonrası beklenecek süreyi hekim belirler', 'Detection of the pathogen means that chlamydia was found in the sample and calls for a discussion of the next steps with the doctor. A negative result does not always rule out infection, the assessment is made together with the clinical picture', 'Nalaz uzročnika znači da su u uzorku nađene hlamidije i zahtijeva dogovor o daljim koracima sa ljekarom. Negativan nalaz ne isključuje uvijek infekciju, procjena se donosi zajedno sa kliničkom slikom', 'Налаз узрочника значи да су у узорку нађене хламидије и захтијева договор о даљим корацима са љекаром. Негативан налаз не искључује увијек инфекцију, процјена се доноси заједно са клиничком сликом', 'Обнаружение возбудителя означает, что в материале найдены хламидии, и требует обсуждения дальнейших шагов с врачом. Отрицательный результат не всегда исключает инфекцию, оценка проводится вместе с клинической картиной', 'Der Nachweis des Erregers bedeutet, dass im Material Chlamydien gefunden wurden, und erfordert die Besprechung der weiteren Schritte mit dem Arzt. Ein negativer Befund schließt eine Infektion nicht immer aus, die Beurteilung erfolgt zusammen mit dem klinischen Bild', 'Etkenin saptanması örnekte klamidya bulunduğu anlamına gelir ve sonraki adımların hekimle görüşülmesini gerektirir. Negatif sonuç enfeksiyonu her zaman dışlamaz, değerlendirme klinik tabloyla birlikte yapılır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'pap-papanicolaou-test'), 'Cytological examination of cells from the cervix as part of screening', 'Citološki pregled ćelija grlića materice u sklopu skrininga', 'Цитолошки преглед ћелија грлића материце у склопу скрининга', 'Цитологическое исследование клеток шейки матки в рамках скрининга', 'Zytologische Untersuchung von Zellen des Gebärmutterhalses im Rahmen der Vorsorge', 'Tarama kapsamında rahim ağzı hücrelerinin sitolojik incelemesi', 'The gynaecologist inserts a speculum and collects cells from the surface of the cervix and from the cervical canal with a brush, the visit takes a few minutes', 'Ginekolog postavlja spekulum i četkicom uzima ćelije sa površine grlića i iz cervikalnog kanala, pregled traje nekoliko minuta', 'Гинеколог поставља спекулум и четкицом узима ћелије са површине грлића и из цервикалног канала, преглед траје неколико минута', 'Гинеколог вводит зеркало и берёт клетки с поверхности шейки матки и из цервикального канала щёточкой, осмотр занимает несколько минут', 'Der Gynäkologe führt ein Spekulum ein und entnimmt mit einem Bürstchen Zellen von der Oberfläche des Muttermunds und aus dem Zervikalkanal, die Untersuchung dauert wenige Minuten', 'Jinekolog spekulum yerleştirir ve fırçayla rahim ağzı yüzeyinden ve servikal kanaldan hücre alır, muayene birkaç dakika sürer', 'Routine screening according to age and schedule, follow-up after changes found in previous smears, work-up before certain gynaecological procedures', 'Redovan skrining prema uzrastu i rasporedu, praćenje poslije ranije uočenih promjena u brisu, obrada prije pojedinih ginekoloških zahvata', 'Редован скрининг према узрасту и распореду, праћење послије раније уочених промјена у брису, обрада прије појединих гинеколошких захвата', 'Плановый скрининг по возрасту и графику, наблюдение после ранее выявленных изменений в мазке, обследование перед отдельными гинекологическими вмешательствами', 'Reguläre Vorsorge entsprechend Alter und Intervall, Kontrolle nach auffälligen Vorbefunden, Abklärung vor bestimmten gynäkologischen Eingriffen', 'Yaşa ve programa göre düzenli tarama, önceki sonuçlarda değişiklik saptananlarda izlem, bazı jinekolojik girişimler öncesi değerlendirme', 'Not taken during menstruation; avoid vaginal medications, douching and intercourse for one to two days before', 'Ne uzima se tokom menstruacije; jedan do dva dana ranije izbjegavati vaginalne preparate, ispiranja i seksualne odnose', 'Не узима се током менструације; један до два дана раније избјегавати вагиналне препарате, испирања и сексуалне односе', 'Не сдают во время менструации; за один-два дня исключить вагинальные препараты, спринцевания и половые контакты', 'Nicht während der Menstruation; ein bis zwei Tage vorher keine Vaginalpräparate, keine Spülungen und keinen Geschlechtsverkehr', 'Adet döneminde alınmaz; bir iki gün önce vajinal ilaç, vajinal duş ve cinsel ilişkiden kaçınılmalı', 'Changes in the cells may be related to inflammation, hormonal influences or to changes in the epithelium that require follow-up. The result is reported using a standard classification, and the gynaecologist decides on further steps and on the timing of a repeat test', 'Promjene ćelija mogu biti povezane sa upalom, hormonskim uticajima ili sa promjenama epitela koje traže praćenje. Nalaz se opisuje standardnom klasifikacijom, a dalji postupak i rok ponovnog pregleda određuje ginekolog', 'Промјене ћелија могу бити повезане са упалом, хормонским утицајима или са промјенама епитела које траже праћење. Налаз се описује стандардном класификацијом, а даљи поступак и рок поновног прегледа одређује гинеколог', 'Изменения клеток могут быть связаны с воспалением, гормональными влияниями или с изменениями эпителия, требующими наблюдения. Результат описывают по стандартной классификации, дальнейшую тактику и срок повторного обследования определяет гинеколог', 'Zellveränderungen können mit einer Entzündung, hormonellen Einflüssen oder mit Veränderungen des Epithels zusammenhängen, die eine Kontrolle erfordern. Der Befund wird nach einer Standardklassifikation beschrieben, das weitere Vorgehen und den Zeitpunkt der Kontrolle legt der Gynäkologe fest', 'Hücrelerdeki değişiklikler iltihap, hormonal etkenler veya izlem gerektiren epitel değişiklikleriyle ilişkili olabilir. Sonuç standart bir sınıflandırmayla bildirilir, sonraki adımlara ve kontrol zamanına jinekolog karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'rapid-strep-a'), 'Antigen test that detects group A beta-haemolytic streptococcus in a throat swab within minutes', 'Otkrivanje antigena beta-hemolitičkog streptokoka grupe A u brisu grla, uz nalaz za nekoliko minuta', 'Откривање антигена бета-хемолитичког стрептокока групе А у брису грла, уз налаз за неколико минута', 'Экспресс-выявление антигена бета-гемолитического стрептококка группы A в мазке из горла', 'Nachweis von Antigen der Streptokokken der Gruppe A im Rachenabstrich mit Ergebnis nach wenigen Minuten', 'Boğaz sürüntüsünde A grubu beta-hemolitik streptokok antijeninin dakikalar içinde saptanması', 'A swab is taken from the tonsils and the result is usually ready in the office within several minutes', 'Štapićem se uzima uzorak sa krajnika, a rezultat je obično gotov u ordinaciji za nekoliko minuta', 'Штапићем се узима узорак са крајника, а резултат је обично готов у ординацији за неколико минута', 'Тампоном берут материал с миндалин, результат обычно готов в кабинете в течение нескольких минут', 'Mit einem Tupfer wird Material von den Mandeln entnommen, das Ergebnis liegt meist innerhalb weniger Minuten in der Praxis vor', 'Bademciklerden çubukla örnek alınır, sonuç genellikle muayenehanede birkaç dakika içinde çıkar', 'Acute sore throat with fever, coating on the tonsils, testing in children and close contacts, when the doctor is deciding whether a culture is needed', 'Akutna upala grla sa temperaturom, naslage na krajnicima, testiranje djece i bliskih kontakata, kada ljekar odlučuje da li je potrebna kultura', 'Акутна упала грла са температуром, наслаге на крајницима, тестирање дјеце и блиских контаката, када љекар одлучује да ли је потребна култура', 'Острая боль в горле с температурой, налёты на миндалинах, обследование детей и близких контактов, решение врача о необходимости посева', 'Akute Halsschmerzen mit Fieber, Beläge auf den Mandeln, Testung bei Kindern und engen Kontaktpersonen, wenn der Arzt über die Notwendigkeit einer Kultur entscheidet', 'Ateşle birlikte akut boğaz ağrısı, bademciklerde örtü, çocuklarda ve yakın temaslılarda test, hekimin kültür gerekip gerekmediğine karar vermesi', 'No gargling, throat sprays or antiseptic lozenges before the test, preferably before eating and drinking', 'Prije testa ne ispirati grlo, ne koristiti sprejeve i antiseptičke pastile, po mogućnosti prije jela i pića', 'Прије теста не испирати грло, не користити спрејеве и антисептичке пастиле, по могућности прије јела и пића', 'Перед тестом не полоскать горло, не использовать спреи и антисептические пастилки, желательно до еды и питья', 'Vor dem Test nicht gurgeln, keine Rachensprays und antiseptischen Lutschtabletten verwenden, möglichst vor dem Essen und Trinken', 'Testten önce gargara yapılmamalı, boğaz spreyi ve antiseptik pastil kullanılmamalı, tercihen yemek ve içecekten önce', 'A positive result shows that group A streptococcal antigen is present, a negative one does not always rule out infection and is sometimes followed by a culture. The decision on treatment is made by the doctor', 'Pozitivan rezultat pokazuje da je prisutan antigen streptokoka grupe A, negativan ne isključuje uvijek infekciju i ponekad se dopunjava kulturom. Odluku o liječenju donosi ljekar', 'Позитиван резултат показује да је присутан антиген стрептокока групе А, негативан не искључује увијек инфекцију и понекад се допуњава културом. Одлуку о лијечењу доноси љекар', 'Положительный результат показывает, что антиген стрептококка группы A присутствует, отрицательный не всегда исключает инфекцию и иногда дополняется посевом. Решение о лечении принимает врач', 'Ein positives Ergebnis zeigt, dass Antigen von Streptokokken der Gruppe A vorhanden ist, ein negatives schließt eine Infektion nicht immer aus und wird manchmal durch eine Kultur ergänzt. Über die Behandlung entscheidet der Arzt', 'Pozitif sonuç A grubu streptokok antijeninin bulunduğunu gösterir, negatif sonuç enfeksiyonu her zaman dışlamaz ve bazen kültürle tamamlanır. Tedavi kararını hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'stool-culture'), 'Bacterial culture of stool to detect causative agents of intestinal infections', 'Bakteriološka kultura stolice radi otkrivanja uzročnika crijevnih infekcija', 'Бактериолошка култура столице ради откривања узрочника цријевних инфекција', 'Бактериологический посев кала для выявления возбудителей кишечных инфекций', 'Bakteriologische Stuhlkultur zum Nachweis von Erregern von Darminfektionen', 'Bağırsak enfeksiyonu etkenlerini saptamak için yapılan gaita kültürü', 'A small stool sample is collected in a sterile container, plated on culture media in the laboratory, and any growth is tested for antibiotic susceptibility', 'Mala količina stolice sakuplja se u sterilnu posudu, u laboratoriji se zasijava na hranljive podloge, a kod porasta se radi antibiogram', 'Мала количина столице сакупља се у стерилну посуду, у лабораторији се засијава на хранљиве подлоге, а код пораста се ради антибиограм', 'Небольшую порцию кала собирают в стерильный контейнер, в лаборатории её засевают на питательные среды и при росте определяют чувствительность к антибиотикам', 'Eine kleine Stuhlmenge wird in ein steriles Gefäß gegeben, im Labor auf Nährböden ausgestrichen und bei Wachstum auf Antibiotikaempfindlichkeit geprüft', 'Az miktarda dışkı steril kaba alınır, laboratuvarda besiyerlerine ekilir ve üreme olursa antibiyogram yapılır', 'Prolonged diarrhoea, suspected intestinal infection, follow-up after an infection, occupational screening of food handlers and childcare staff', 'Dugotrajni proliv, sumnja na crijevnu infekciju, kontrola nakon preboljele infekcije, sistematski pregledi radnika u prehrani i vrtićima', 'Дуготрајни пролив, сумња на цријевну инфекцију, контрола након пребољеле инфекције, систематски прегледи радника у прехрани и вртићима', 'Длительная диарея, подозрение на кишечную инфекцию, контроль после перенесённой инфекции, профосмотр работников пищевой сферы и детских учреждений', 'Anhaltender Durchfall, Verdacht auf eine Darminfektion, Kontrolle nach durchgemachter Infektion, Untersuchung von Beschäftigten in Lebensmittelbetrieben und Kitas', 'Uzun süren ishal, bağırsak enfeksiyonu şüphesi, geçirilmiş enfeksiyon sonrası kontrol, gıda sektörü ve kreş çalışanlarının taraması', 'Collect stool into a sterile container from a pharmacy, ideally before starting antibiotics; urine and toilet water must not get into the sample', 'Stolica se sakuplja u sterilnu posudu iz apoteke, po mogućnosti prije početka uzimanja antibiotika; u uzorak ne smiju dospjeti mokraća ni voda', 'Столица се сакупља у стерилну посуду из апотеке, по могућности прије почетка узимања антибиотика; у узорак не смију доспјети мокраћа ни вода', 'Кал собирают в стерильный контейнер из аптеки, по возможности до начала приёма антибиотиков; в образец не должна попадать моча или вода из унитаза', 'Stuhl in ein steriles Gefäß aus der Apotheke geben, möglichst vor Beginn einer Antibiotikatherapie; Urin und Toilettenwasser dürfen nicht in die Probe gelangen', 'Dışkı eczaneden alınan steril kaba konur, mümkünse antibiyotik başlanmadan önce verilir; örneğe idrar veya tuvalet suyu karışmamalıdır', 'Growth of pathogenic bacteria may be related to an intestinal infection or to symptom-free carriage, while normal gut flora does not always explain the complaints. The result is assessed by a doctor together with the symptoms', 'Porast patogenih bakterija može biti povezan sa crijevnom infekcijom ili sa kliconoštvom bez tegoba, a uobičajena crijevna flora ne objašnjava uvijek tegobe. Nalaz zajedno sa simptomima procjenjuje ljekar', 'Пораст патогених бактерија може бити повезан са цријевном инфекцијом или са клицоноштвом без тегоба, а уобичајена цријевна флора не објашњава увијек тегобе. Налаз заједно са симптомима процјењује љекар', 'Рост патогенных бактерий может быть связан с кишечной инфекцией или с бессимптомным носительством, а обычная флора кишечника не всегда объясняет жалобы. Результат вместе с симптомами оценивает врач', 'Das Wachstum krankmachender Bakterien kann mit einer Darminfektion oder mit beschwerdefreier Besiedlung zusammenhängen, während die normale Darmflora die Beschwerden nicht immer erklärt. Der Befund wird zusammen mit den Symptomen vom Arzt beurteilt', 'Hastalık yapan bakterilerin üremesi bağırsak enfeksiyonu veya belirtisiz taşıyıcılıkla ilişkili olabilir, olağan bağırsak florası ise şikayetleri her zaman açıklamaz. Sonucu belirtilerle birlikte hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'trichomonas-test'), 'Laboratory test of urogenital material for the protozoan Trichomonas vaginalis', 'Laboratorijsko ispitivanje urogenitalnog materijala na praživotinju Trichomonas vaginalis', 'Лабораторијско испитивање урогениталног материјала на праживотињу Trichomonas vaginalis', 'Лабораторное исследование урогенитального материала на простейшее Trichomonas vaginalis', 'Laboruntersuchung von Urogenitalmaterial auf den Einzeller Trichomonas vaginalis', 'Ürogenital örnekte Trichomonas vaginalis adlı tek hücreli parazitin araştırılması', 'A swab is taken from the vagina or urethra and examined under the microscope, cultured, or tested by PCR', 'Uzima se bris vagine ili uretre, materijal se pregleda pod mikroskopom, zasijava na podlogu ili ispituje metodom PCR', 'Узима се брис вагине или уретре, материјал се прегледа под микроскопом, засијава на подлогу или испитује методом ПЦР', 'Берут мазок из влагалища или уретры, материал смотрят под микроскопом, засевают на среду или исследуют методом PCR', 'Ein Abstrich aus Scheide oder Harnröhre wird mikroskopiert, kulturell angelegt oder mittels PCR untersucht', 'Vajina veya üretradan sürüntü alınır, örnek mikroskopta incelenir, besiyerine ekilir ya da PCR yöntemiyle çalışılır', 'Discharge, itching or burning in the genital area, examination referred by a gynaecologist or urologist, testing of a sexual partner, pregnancy planning', 'Sekret, svrab ili peckanje u predjelu genitalija, pregled po uputu ginekologa ili urologa, ispitivanje polnog partnera, priprema za trudnoću', 'Секрет, свраб или пецкање у предјелу гениталија, преглед по упуту гинеколога или уролога, испитивање полног партнера, припрема за трудноћу', 'Выделения, зуд или жжение в области половых органов, обследование по направлению гинеколога либо уролога, обследование полового партнёра, подготовка к беременности', 'Ausfluss, Juckreiz oder Brennen im Genitalbereich, Untersuchung auf Überweisung von Gynäkologe oder Urologe, Untersuchung des Sexualpartners, Kinderwunsch', 'Genital bölgede akıntı, kaşıntı veya yanma, kadın hastalıkları ya da üroloji hekiminin yönlendirmesi, cinsel eşin incelenmesi, gebelik hazırlığı', 'Women outside menstruation, men should not urinate for about two hours before sampling; tell the doctor in advance about antibiotics or vaginal suppositories being used', 'Kod žena van menstruacije, kod muškaraca bez mokrenja oko dva sata prije uzimanja; ljekaru unaprijed reći o uzimanju antibiotika i o vaginaletama', 'Код жена ван менструације, код мушкараца без мокрења око два сата прије узимања; љекару унапријед рећи о узимању антибиотика и о вагиналетама', 'Женщинам — вне менструации, мужчинам — не мочиться около двух часов до взятия; заранее сообщить врачу о приёме антибактериальных препаратов и об использовании вагинальных свечей', 'Bei Frauen außerhalb der Menstruation, bei Männern etwa zwei Stunden vor der Entnahme nicht Wasser lassen; Antibiotika und Vaginalzäpfchen dem Arzt vorher mitteilen', 'Kadınlarda adet dönemi dışında, erkeklerde örnek alınmadan yaklaşık iki saat önce idrara çıkılmamalıdır; kullanılan antibiyotikler ve vajinal fitiller hekime önceden bildirilmelidir', 'Detection of the organism means the next steps should be discussed with a doctor, while a negative result with persisting complaints does not always rule out other causes. The conclusion is drawn by the treating doctor', 'Nalaz uzročnika znači da dalje korake treba dogovoriti sa ljekarom, a negativan nalaz uz tegobe koje traju ne isključuje uvijek druge uzroke. Zaključak donosi ljekar koji liječi', 'Налаз узрочника значи да даље кораке треба договорити са љекаром, а негативан налаз уз тегобе које трају не искључује увијек друге узроке. Закључак доноси љекар који лијечи', 'Обнаружение возбудителя означает, что дальнейшие шаги нужно обсудить с врачом, а отрицательный результат при сохраняющихся жалобах не всегда исключает другие причины. Выводы делает лечащий врач', 'Ein Erregernachweis bedeutet, dass das weitere Vorgehen mit dem Arzt zu besprechen ist, ein negatives Ergebnis bei anhaltenden Beschwerden schließt andere Ursachen nicht immer aus. Die Bewertung nimmt der behandelnde Arzt vor', 'Etkenin saptanması sonraki adımların hekimle konuşulması gerektiğini gösterir, şikayet sürerken çıkan olumsuz sonuç ise diğer nedenleri her zaman dışlamaz. Değerlendirmeyi tedaviyi yürüten hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'umbilicus-swab-bacteria'), 'Culture of material from the umbilical wound or navel fold for bacterial flora', 'Kultura materijala sa pupčane ranice ili nabora pupka na bakterijsku floru', 'Култура материјала са пупчане ранице или набора пупка на бактеријску флору', 'Посев материала с пупочной ранки или пупочной складки на бактериальную флору', 'Kultur von Material aus der Nabelwunde oder der Nabelfalte auf Bakterienflora', 'Göbek yarasından veya göbek kıvrımından alınan örneğin bakteri kültürü', 'A sterile swab is wiped over the skin of the navel and around it, the material is plated on culture media and any growth is tested for antibiotic susceptibility', 'Sterilnim štapićem prelazi se preko kože pupka i okoline, materijal se zasijava na hranljive podloge, a kod porasta se radi antibiogram', 'Стерилним штапићем прелази се преко коже пупка и околине, материјал се засијава на хранљиве подлоге, а код пораста се ради антибиограм', 'Стерильным тампоном проводят по коже пупка и вокруг него, материал засевают на питательные среды и при росте определяют чувствительность к антибиотикам', 'Mit einem sterilen Tupfer wird über die Haut des Nabels und die Umgebung gestrichen, das Material wird auf Nährböden ausgestrichen und bei Wachstum auf Antibiotikaempfindlichkeit geprüft', 'Steril bir eküvyon göbek ve çevresindeki deri üzerinde gezdirilir, örnek besiyerlerine ekilir ve üreme olursa antibiyogram yapılır', 'Redness, swelling or discharge around the navel, slow healing of the umbilical stump in a newborn, work-up before antibiotic treatment is prescribed', 'Crvenilo, otok ili sekret oko pupka, sporo zarastanje pupčane ranice kod novorođenčeta, ispitivanje prije uvođenja antibiotske terapije', 'Црвенило, оток или секрет око пупка, споро зарастање пупчане ранице код новорођенчета, испитивање прије увођења антибиотске терапије', 'Покраснение, отёк или выделения в области пупка, медленное заживление пупочной ранки у новорождённого, обследование перед назначением антибактериальной терапии', 'Rötung, Schwellung oder Sekret am Nabel, langsame Heilung der Nabelwunde beim Neugeborenen, Abklärung vor Beginn einer Antibiotikatherapie', 'Göbek çevresinde kızarıklık, şişlik veya akıntı, yenidoğanda göbek yarasının geç kapanması, antibiyotik tedavisi öncesi değerlendirme', 'No special preparation is needed; do not apply antiseptics, ointments or powders to the navel before sampling', 'Posebna priprema nije potrebna; pupak prije uzimanja ne tretirati antisepticima, mastima ni puderima', 'Посебна припрема није потребна; пупак прије узимања не третирати антисептицима, мастима ни пудерима', 'Специальная подготовка не нужна; перед взятием пупок не обрабатывать антисептиками, мазями и присыпками', 'Keine besondere Vorbereitung nötig; der Nabel sollte vor der Entnahme nicht mit Antiseptika, Salben oder Puder behandelt werden', 'Özel bir hazırlık gerekmez; örnek alınmadan önce göbeğe antiseptik, merhem veya pudra uygulanmamalıdır', 'Bacterial growth may be related to inflammation of the umbilical wound or to skin colonisation without inflammation. Whether treatment is needed is decided by the doctor after examination', 'Porast bakterija može biti povezan sa upalom pupčane ranice ili sa kolonizacijom kože bez upale. Da li je liječenje potrebno, odlučuje ljekar nakon pregleda', 'Пораст бактерија може бити повезан са упалом пупчане ранице или са колонизацијом коже без упале. Да ли је лијечење потребно, одлучује љекар након прегледа', 'Рост бактерий может быть связан с воспалением пупочной ранки или с колонизацией кожи без воспаления. Нужно ли лечение, решает врач по осмотру', 'Bakterienwachstum kann mit einer Entzündung der Nabelwunde oder mit einer Besiedlung der Haut ohne Entzündung zusammenhängen. Ob eine Behandlung nötig ist, entscheidet der Arzt nach der Untersuchung', 'Bakteri üremesi göbek yarasındaki iltihapla ya da iltihap olmadan deride kolonizasyonla ilişkili olabilir. Tedavi gerekip gerekmediğine muayene sonrası hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bacteriological-examination-ear-swab'), 'Culture of discharge from the external ear canal for bacterial flora', 'Kultura sekreta iz spoljašnjeg ušnog kanala na bakterijsku floru', 'Култура секрета из спољашњег ушног канала на бактеријску флору', 'Посев отделяемого из наружного слухового прохода на бактериальную флору', 'Kultur von Sekret aus dem äußeren Gehörgang auf Bakterienflora', 'Dış kulak yolundaki akıntının bakteri kültürü', 'The doctor takes material from the ear with a sterile swab, the laboratory plates it on culture media and tests any growth for antibiotic susceptibility', 'Ljekar uzima materijal iz uha sterilnim štapićem, u laboratoriji se zasijava na podloge, a kod porasta se radi antibiogram', 'Љекар узима материјал из уха стерилним штапићем, у лабораторији се засијава на подлоге, а код пораста се ради антибиограм', 'Врач берёт материал из уха стерильным тампоном, в лаборатории его засевают на среды и при росте определяют чувствительность к антибиотикам', 'Der Arzt entnimmt das Material mit einem sterilen Tupfer aus dem Ohr, im Labor wird es auf Nährböden ausgestrichen und bei Wachstum auf Antibiotikaempfindlichkeit geprüft', 'Hekim kulaktan steril eküvyonla örnek alır, laboratuvarda besiyerlerine ekilir ve üreme olursa antibiyogram yapılır', 'Ear pain and discharge, protracted external otitis, lack of response to prescribed treatment, recurrent ear inflammation', 'Bol i sekrecija iz uha, dugotrajna upala spoljašnjeg uha, izostanak efekta propisane terapije, ponavljane upale uha', 'Бол и секреција из уха, дуготрајна упала спољашњег уха, изостанак ефекта прописане терапије, понављане упале уха', 'Боль и выделения из уха, затяжной наружный отит, отсутствие эффекта от назначенного лечения, повторяющиеся воспаления уха', 'Ohrenschmerzen und Sekretion, langwierige Entzündung des äußeren Gehörgangs, fehlendes Ansprechen auf die verordnete Behandlung, wiederkehrende Ohrentzündungen', 'Kulak ağrısı ve akıntı, uzayan dış kulak iltihabı, verilen tedaviye yanıt alınamaması, tekrarlayan kulak iltihapları', 'Do not use ear drops or wash the ear before sampling; when to stop topical products is advised by the ENT doctor', 'Prije uzimanja ne kapati kapi za uho i ne prati uho; kada prekinuti lokalnu terapiju kaže otorinolaringolog', 'Прије узимања не капати капи за ухо и не прати ухо; када прекинути локалну терапију каже оториноларинголог', 'Перед взятием не закапывать ушные капли и не мыть ухо; сроки отмены местных средств уточняет оториноларинголог', 'Vor der Entnahme keine Ohrentropfen anwenden und das Ohr nicht spülen; wann örtliche Mittel abzusetzen sind, sagt der HNO-Arzt', 'Örnek alınmadan önce kulak damlası kullanılmamalı ve kulak yıkanmamalıdır; yerel ilaçların ne zaman kesileceğini kulak burun boğaz hekimi söyler', 'Bacterial growth may be related to inflammation of the outer or middle ear, while some findings belong to the normal skin flora. The ENT doctor compares the result with the examination', 'Porast bakterija može biti povezan sa upalom spoljašnjeg ili srednjeg uha, a dio nalaza pripada uobičajenoj flori kože. Nalaz sa pregledom poredi otorinolaringolog', 'Пораст бактерија може бити повезан са упалом спољашњег или средњег уха, а дио налаза припада уобичајеној флори коже. Налаз са прегледом пореди оториноларинголог', 'Рост бактерий может быть связан с воспалением наружного или среднего уха, а часть находок относится к обычной флоре кожи. Результат сопоставляет с осмотром оториноларинголог', 'Bakterienwachstum kann mit einer Entzündung des äußeren oder mittleren Ohres zusammenhängen, ein Teil der Befunde gehört zur normalen Hautflora. Der HNO-Arzt setzt den Befund mit der Untersuchung in Beziehung', 'Bakteri üremesi dış veya orta kulak iltihabıyla ilişkili olabilir, bulguların bir bölümü ise derinin olağan florasına aittir. Sonucu muayene bulgularıyla kulak burun boğaz hekimi karşılaştırır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'breast-swab-bacteria'), 'Culture of nipple discharge or breast fluid for bacterial flora', 'Kultura sekreta bradavice ili sadržaja dojke na bakterijsku floru', 'Култура секрета брадавице или садржаја дојке на бактеријску флору', 'Посев отделяемого соска или содержимого молочной железы на бактериальную флору', 'Kultur von Sekret der Brustwarze oder Brustdrüsenflüssigkeit auf Bakterienflora', 'Meme başı akıntısının veya meme içeriğinin bakteri kültürü', 'A sterile swab collects discharge from the nipple or material from a fistula tract, and the laboratory plates it on culture media', 'Sterilnim štapićem uzima se sekret sa bradavice ili materijal iz fistuloznog kanala, u laboratoriji se zasijava na hranljive podloge', 'Стерилним штапићем узима се секрет са брадавице или материјал из фистулозног канала, у лабораторији се засијава на хранљиве подлоге', 'Стерильным тампоном берут отделяемое соска либо материал из свищевого хода, в лаборатории его засевают на питательные среды', 'Mit einem sterilen Tupfer wird Sekret von der Brustwarze oder Material aus einem Fistelgang entnommen und im Labor auf Nährböden ausgestrichen', 'Steril eküvyonla meme başındaki akıntı ya da fistül ağzından gelen materyal alınır ve laboratuvarda besiyerlerine ekilir', 'Pain, redness and a lump in the breast during breastfeeding, protracted mastitis, nipple discharge, follow-up after treatment as prescribed by the doctor', 'Bol, crvenilo i čvor u dojci tokom dojenja, dugotrajni mastitis, sekrecija iz bradavice, kontrola poslije liječenja po savjetu ljekara', 'Бол, црвенило и чвор у дојци током дојења, дуготрајни маститис, секреција из брадавице, контрола послије лијечења по савјету љекара', 'Боль, покраснение и уплотнение груди при кормлении, затяжной мастит, выделения из соска, контроль по назначению врача после лечения', 'Schmerzen, Rötung und Verhärtung der Brust beim Stillen, langwierige Mastitis, Sekretion aus der Brustwarze, Kontrolle nach Behandlung auf ärztliche Anordnung', 'Emzirme döneminde memede ağrı, kızarıklık ve sertlik, uzayan mastit, meme başı akıntısı, hekimin isteğiyle tedavi sonrası kontrol', 'Do not apply antiseptics or creams to the nipple before sampling; during breastfeeding the first drops of milk are expressed and not used for culture', 'Prije uzimanja bradavicu ne tretirati antisepticima ni kremama; kod dojenja prve kapi mlijeka se izmuzu i ne koriste za kulturu', 'Прије узимања брадавицу не третирати антисептицима ни кремама; код дојења прве капи млијека се измузу и не користе за културу', 'Перед взятием сосок не обрабатывать антисептиками и кремами; при грудном вскармливании первые капли молока сцеживают и для посева не используют', 'Vor der Entnahme keine Antiseptika oder Cremes auf die Brustwarze auftragen; beim Stillen werden die ersten Milchtropfen abgepumpt und nicht für die Kultur verwendet', 'Örnek alınmadan önce meme başına antiseptik ve krem uygulanmamalıdır; emziren annelerde ilk süt damlaları sağılıp kültür için kullanılmaz', 'Bacterial growth may be related to inflammation of the breast tissue or to the normal flora of the nipple skin. Whether treatment is needed is decided by the doctor based on examination and symptoms', 'Porast bakterija može biti povezan sa upalom tkiva dojke ili sa uobičajenom florom kože bradavice. Da li je liječenje potrebno, procjenjuje ljekar na osnovu pregleda i tegoba', 'Пораст бактерија може бити повезан са упалом ткива дојке или са уобичајеном флором коже брадавице. Да ли је лијечење потребно, процјењује љекар на основу прегледа и тегоба', 'Рост бактерий может быть связан с воспалением ткани железы или с обычной флорой кожи соска. Нужно ли лечение, определяет врач по осмотру и жалобам', 'Bakterienwachstum kann mit einer Entzündung des Drüsengewebes oder mit der normalen Hautflora der Brustwarze zusammenhängen. Ob eine Behandlung nötig ist, entscheidet der Arzt anhand von Untersuchung und Beschwerden', 'Bakteri üremesi meme dokusundaki iltihapla ya da meme başı derisinin olağan florasıyla ilişkili olabilir. Tedavi gerekip gerekmediğine muayene ve şikayetlere göre hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'clostridium-difficile-toxin-a-and-b'), 'Stool test for toxins A and B of the bacterium Clostridium difficile', 'Ispitivanje stolice na toksine A i B bakterije Clostridium difficile', 'Испитивање столице на токсине А и Б бактерије Clostridium difficile', 'Исследование кала на токсины A и B бактерии Clostridium difficile', 'Stuhluntersuchung auf die Toxine A und B des Bakteriums Clostridium difficile', 'Dışkıda Clostridium difficile bakterisinin A ve B toksinlerinin araştırılması', 'A stool portion is collected in a sterile container and the toxins are detected in the laboratory by an immunoassay', 'Uzorak stolice sakuplja se u sterilnu posudu, a toksini se u laboratoriji dokazuju imunohemijskom metodom', 'Узорак столице сакупља се у стерилну посуду, а токсини се у лабораторији доказују имунохемијском методом', 'Порцию кала собирают в стерильный контейнер, в лаборатории токсины выявляют иммунохимическим методом', 'Eine Stuhlportion wird in ein steriles Gefäß gegeben, im Labor werden die Toxine mit einem immunchemischen Verfahren nachgewiesen', 'Steril kaba alınan dışkı örneğinde toksinler laboratuvarda immünokimyasal yöntemle saptanır', 'Diarrhoea during or after antibiotic treatment, loose stools after a hospital stay, repeated episodes of diarrhoea in elderly patients', 'Proliv tokom ili poslije uzimanja antibiotika, tečne stolice nakon bolničkog liječenja, ponovljene epizode proliva kod starijih pacijenata', 'Пролив током или послије узимања антибиотика, течне столице након болничког лијечења, поновљене епизоде пролива код старијих пацијената', 'Диарея на фоне или после приёма антибиотиков, расстройство стула после стационарного лечения, повторные эпизоды диареи у пожилых пациентов', 'Durchfall während oder nach einer Antibiotikatherapie, dünne Stühle nach einem Krankenhausaufenthalt, wiederholte Durchfallepisoden bei älteren Patienten', 'Antibiyotik kullanımı sırasında veya sonrasında ishal, hastane yatışı sonrası sulu dışkılama, yaşlı hastalarda yinelenen ishal atakları', 'No special preparation is needed; a liquid or unformed stool sample is submitted and delivered to the laboratory as quickly as possible', 'Posebna priprema nije potrebna; predaje se tečan ili neoformljen uzorak i dostavlja u laboratoriju što prije', 'Посебна припрема није потребна; предаје се течан или неоформљен узорак и доставља у лабораторију што прије', 'Специальная подготовка не нужна; сдают образец жидкой или неоформленной консистенции и доставляют его в лабораторию как можно быстрее', 'Keine besondere Vorbereitung nötig; abgegeben wird eine flüssige oder ungeformte Probe, die möglichst rasch ins Labor gebracht wird', 'Özel bir hazırlık gerekmez; sulu ya da şekilsiz örnek verilir ve laboratuvara mümkün olduğunca hızlı ulaştırılır', 'Detection of the toxins may be related to antibiotic-associated bowel damage, and the result is meaningful only together with the symptoms. The approach is decided by the doctor', 'Nalaz toksina može biti povezan sa oštećenjem crijeva nakon antibiotika, a značenje dobija tek uz kliničke tegobe. Dalji postupak određuje ljekar', 'Налаз токсина може бити повезан са оштећењем цријева након антибиотика, а значење добија тек уз клиничке тегобе. Даљи поступак одређује љекар', 'Обнаружение токсинов может быть связано с антибиотик-ассоциированным поражением кишечника, при этом результат имеет значение только вместе с симптомами. Тактику определяет врач', 'Ein Toxinnachweis kann mit einer antibiotikaassoziierten Darmschädigung zusammenhängen, aussagekräftig ist er nur zusammen mit den Beschwerden. Das weitere Vorgehen legt der Arzt fest', 'Toksinlerin saptanması antibiyotiğe bağlı bağırsak hasarıyla ilişkili olabilir, sonuç ancak belirtilerle birlikte anlam taşır. İzlenecek yolu hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'endocervical-swab-for-gonorrhea'), 'Sampling from the cervical canal to detect the causative agent of gonorrhoea', 'Uzimanje materijala iz kanala grlića materice radi dokazivanja uzročnika gonoreje', 'Узимање материјала из канала грлића материце ради доказивања узрочника гонореје', 'Взятие материала из канала шейки матки для выявления возбудителя гонореи', 'Materialentnahme aus dem Gebärmutterhalskanal zum Nachweis des Gonorrhoe-Erregers', 'Gonore etkenini saptamak için rahim ağzı kanalından örnek alınması', 'The gynaecologist inserts a speculum and takes material from the cervical canal with a sterile swab, which is examined by microscopy, culture or PCR', 'Ginekolog postavlja spekulum i sterilnim štapićem uzima materijal iz cervikalnog kanala, a nalaz se radi mikroskopijom, kulturom ili metodom PCR', 'Гинеколог поставља спекулум и стерилним штапићем узима материјал из цервикалног канала, а налаз се ради микроскопијом, културом или методом ПЦР', 'Гинеколог вводит зеркало и стерильным тампоном берёт материал из цервикального канала, исследование проводят микроскопией, посевом или методом PCR', 'Der Gynäkologe führt ein Spekulum ein und entnimmt mit einem sterilen Tupfer Material aus dem Zervikalkanal, das mikroskopisch, kulturell oder mittels PCR untersucht wird', 'Kadın hastalıkları hekimi spekulum yerleştirip steril eküvyonla servikal kanaldan örnek alır, örnek mikroskopi, kültür veya PCR yöntemiyle incelenir', 'Discharge and lower abdominal discomfort, examination referred by a gynaecologist, pregnancy planning, testing of a sexual partner, routine screening', 'Sekret i nelagodnost u donjem dijelu trbuha, pregled po uputu ginekologa, planiranje trudnoće, ispitivanje polnog partnera, preventivna kontrola', 'Секрет и нелагодност у доњем дијелу трбуха, преглед по упуту гинеколога, планирање трудноће, испитивање полног партнера, превентивна контрола', 'Выделения и дискомфорт внизу живота, обследование по направлению гинеколога, планирование беременности, обследование полового партнёра, профилактический контроль', 'Ausfluss und Unterbauchbeschwerden, Untersuchung auf Überweisung des Gynäkologen, Kinderwunsch, Untersuchung des Sexualpartners, Vorsorgekontrolle', 'Akıntı ve alt karın bölgesinde rahatsızlık, kadın hastalıkları hekiminin yönlendirmesi, gebelik planlaması, cinsel eşin incelenmesi, koruyucu kontrol', 'Outside menstruation; for a day before sampling avoid vaginal suppositories, douching and sexual contact, and tell the doctor about any antibiotics taken', 'Van menstruacije, dan prije uzimanja bez vaginaleta, ispiranja i polnih odnosa; o uzimanju antibiotika obavijestiti ljekara', 'Ван менструације, дан прије узимања без вагиналета, испирања и полних односа; о узимању антибиотика обавијестити љекара', 'Вне менструации, за сутки до взятия отказаться от вагинальных свечей, спринцеваний и половых контактов; о приёме антибиотиков сообщить врачу', 'Außerhalb der Menstruation, einen Tag vorher auf Vaginalzäpfchen, Spülungen und Geschlechtsverkehr verzichten; eingenommene Antibiotika dem Arzt mitteilen', 'Adet dönemi dışında yapılır, örnekten bir gün önce vajinal fitil, duş ve cinsel ilişkiden kaçınılır; kullanılan antibiyotikler hekime bildirilir', 'Detection of the organism means the next steps should be discussed with a doctor, while a negative result with ongoing complaints does not exclude other causes of inflammation. The gynaecologist interprets the result', 'Nalaz uzročnika znači da dalje korake treba dogovoriti sa ljekarom, a negativan nalaz uz tegobe ne isključuje druge uzroke upale. Nalaz tumači ginekolog', 'Налаз узрочника значи да даље кораке треба договорити са љекаром, а негативан налаз уз тегобе не искључује друге узроке упале. Налаз тумачи гинеколог', 'Обнаружение возбудителя означает, что дальнейшие шаги нужно обсудить с врачом, а отрицательный результат при жалобах не исключает других причин воспаления. Трактует результат гинеколог', 'Ein Erregernachweis bedeutet, dass das weitere Vorgehen mit dem Arzt zu besprechen ist, ein negatives Ergebnis bei Beschwerden schließt andere Entzündungsursachen nicht aus. Die Deutung übernimmt der Gynäkologe', 'Etkenin saptanması sonraki adımların hekimle konuşulması gerektiğini gösterir, şikayet sürerken çıkan olumsuz sonuç ise başka iltihap nedenlerini dışlamaz. Sonucu kadın hastalıkları hekimi yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'perianal-swab'), 'Sampling from the skin folds around the anus for laboratory examination', 'Uzimanje materijala sa kožnih nabora oko čmara za laboratorijsko ispitivanje', 'Узимање материјала са кожних набора око чмара за лабораторијско испитивање', 'Взятие материала с кожных складок вокруг заднего прохода для лабораторного исследования', 'Materialentnahme aus den Hautfalten rund um den After für die Laboruntersuchung', 'Anüs çevresindeki deri kıvrımlarından laboratuvar incelemesi için örnek alınması', 'Material is collected from the skin around the anus with a sterile swab or adhesive tape, then examined under the microscope or plated on culture media', 'Sterilnim štapićem ili ljepljivom trakom sakuplja se materijal sa kože oko analnog otvora, a zatim se pregleda pod mikroskopom ili zasijava na podloge', 'Стерилним штапићем или љепљивом траком сакупља се материјал са коже око аналног отвора, а затим се прегледа под микроскопом или засијава на подлоге', 'Стерильным тампоном или липкой лентой собирают материал с кожи вокруг ануса, затем его смотрят под микроскопом или засевают на среды', 'Mit einem sterilen Tupfer oder Klebestreifen wird Material von der Haut um den After gewonnen und anschließend mikroskopiert oder auf Nährböden ausgestrichen', 'Steril eküvyon veya yapışkan bantla anüs çevresindeki deriden örnek toplanır, ardından mikroskopta incelenir ya da besiyerine ekilir', 'Itching around the anus, especially at night, suspected pinworm infection in children, clearance for kindergarten, swimming pool or hospital admission, microbiological work-up ordered by a doctor', 'Svrab oko čmara, naročito noću, sumnja na enterobijazu kod djece, upis u vrtić, bazen ili prijem u bolnicu, mikrobiološko ispitivanje po savjetu ljekara', 'Свраб око чмара, нарочито ноћу, сумња на ентеробијазу код дјеце, упис у вртић, базен или пријем у болницу, микробиолошко испитивање по савјету љекара', 'Зуд в области заднего прохода, особенно ночной, подозрение на энтеробиоз у детей, оформление в детский сад, бассейн или стационар, микробиологическое обследование по назначению врача', 'Juckreiz am After, besonders nachts, Verdacht auf Madenwürmer bei Kindern, Nachweis für Kindergarten, Schwimmbad oder Klinikaufnahme, mikrobiologische Abklärung auf ärztliche Anordnung', 'Özellikle geceleri olan makat çevresi kaşıntısı, çocuklarda kıl kurdu şüphesi, kreş, havuz veya hastane kaydı için istenen belge, hekimin istediği mikrobiyolojik inceleme', 'The sample is taken in the morning, before washing and before a bowel movement; avoid ointments, suppositories and antiseptics the day before', 'Materijal se uzima ujutru, prije pranja i prije stolice; dan ranije ne koristiti masti, supozitorije i antiseptike', 'Материјал се узима ујутру, прије прања и прије столице; дан раније не користити масти, супозиторије и антисептике', 'Материал берут утром, до подмывания и до стула; накануне не использовать мази, свечи и антисептики', 'Die Entnahme erfolgt morgens, vor der Reinigung und vor dem Stuhlgang; am Vortag keine Salben, Zäpfchen und Antiseptika verwenden', 'Örnek sabah, yıkanmadan ve dışkılamadan önce alınır; bir gün öncesinden merhem, fitil ve antiseptik kullanılmamalıdır', 'Findings may be related to parasitic or bacterial colonisation, and a single negative result does not always rule it out. Whether the test should be repeated is decided by the doctor', 'Nalaz može biti povezan sa parazitskom ili bakterijskom kolonizacijom, a jedan negativan nalaz je ne isključuje uvijek. Da li ispitivanje treba ponoviti, odlučuje ljekar', 'Налаз може бити повезан са паразитском или бактеријском колонизацијом, а један негативан налаз је не искључује увијек. Да ли испитивање треба поновити, одлучује љекар', 'Находки могут быть связаны с паразитарной или бактериальной колонизацией, а однократный отрицательный результат её не всегда исключает. Нужно ли повторить исследование, решает врач', 'Die Befunde können mit einer parasitären oder bakteriellen Besiedlung zusammenhängen, ein einzelnes negatives Ergebnis schließt sie nicht immer aus. Ob die Untersuchung zu wiederholen ist, entscheidet der Arzt', 'Bulgular parazit veya bakteri kolonizasyonuyla ilişkili olabilir, tek bir olumsuz sonuç bunu her zaman dışlamaz. İncelemenin yinelenip yinelenmeyeceğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'right-eye-swab-bacteria'), 'Culture of discharge from the conjunctiva of the right eye for bacterial flora', 'Kultura sekreta konjunktive desnog oka na bakterijsku floru', 'Култура секрета коњунктиве десног ока на бактеријску флору', 'Посев отделяемого конъюнктивы правого глаза на бактериальную флору', 'Kultur von Sekret der Bindehaut des rechten Auges auf Bakterienflora', 'Sağ gözün konjonktivasındaki akıntının bakteri kültürü', 'A sterile swab collects discharge from the inner surface of the lower lid of the right eye, and the material is plated on culture media', 'Sterilnim štapićem uzima se sekret sa unutrašnje strane donjeg kapka desnog oka, a materijal se zasijava na hranljive podloge', 'Стерилним штапићем узима се секрет са унутрашње стране доњег капка десног ока, а материјал се засијава на хранљиве подлоге', 'Стерильным тампоном берут отделяемое с внутренней поверхности нижнего века правого глаза, материал засевают на питательные среды', 'Mit einem sterilen Tupfer wird Sekret von der Innenseite des Unterlids des rechten Auges entnommen und auf Nährböden ausgestrichen', 'Steril eküvyonla sağ gözün alt kapağının iç yüzündeki akıntı alınır ve besiyerlerine ekilir', 'Redness, lid swelling and purulent discharge of the right eye, protracted conjunctivitis, no response to prescribed drops, eye inflammation in a newborn', 'Crvenilo, otok kapaka i gnojni sekret desnog oka, dugotrajni konjunktivitis, izostanak efekta propisanih kapi, upala oka kod novorođenčeta', 'Црвенило, оток капака и гнојни секрет десног ока, дуготрајни коњунктивитис, изостанак ефекта прописаних капи, упала ока код новорођенчета', 'Покраснение, отёк век и гнойное отделяемое правого глаза, затяжной конъюнктивит, отсутствие эффекта от назначенных капель, воспаление глаза у новорождённого', 'Rötung, Lidschwellung und eitriges Sekret des rechten Auges, langwierige Bindehautentzündung, fehlendes Ansprechen auf verordnete Tropfen, Augenentzündung beim Neugeborenen', 'Sağ gözde kızarıklık, kapak şişliği ve iltihaplı akıntı, uzayan konjonktivit, verilen damlalara yanıt alınamaması, yenidoğanda göz iltihabı', 'Do not rinse the eye or use drops before sampling, remove eye make-up in advance and take out contact lenses', 'Prije uzimanja oko ne ispirati i ne kapati kapi, šminku sa kapaka ukloniti ranije, a kontaktna sočiva izvaditi', 'Прије узимања око не испирати и не капати капи, шминку са капака уклонити раније, а контактна сочива извадити', 'Перед взятием глаз не промывать и не закапывать капли, косметику с век смыть заранее; контактные линзы снять', 'Vor der Entnahme das Auge nicht spülen und keine Tropfen anwenden, Augen-Make-up vorher entfernen und Kontaktlinsen herausnehmen', 'Örnek alınmadan önce göz yıkanmamalı ve damla damlatılmamalı, göz makyajı önceden temizlenmeli, kontakt lens çıkarılmalıdır', 'Bacterial growth may be related to inflammation of the conjunctiva or to the normal flora of the eyelid skin. The ophthalmologist compares the result with the examination', 'Porast bakterija može biti povezan sa upalom konjunktive ili sa uobičajenom florom kože kapaka. Nalaz sa pregledom poredi oftalmolog', 'Пораст бактерија може бити повезан са упалом коњунктиве или са уобичајеном флором коже капака. Налаз са прегледом пореди офталмолог', 'Рост бактерий может быть связан с воспалением конъюнктивы или с обычной флорой кожи век. Результат сопоставляет с осмотром офтальмолог', 'Bakterienwachstum kann mit einer Bindehautentzündung oder mit der normalen Hautflora der Lider zusammenhängen. Der Augenarzt setzt den Befund mit der Untersuchung in Beziehung', 'Bakteri üremesi konjonktiva iltihabıyla ya da göz kapağı derisinin olağan florasıyla ilişkili olabilir. Sonucu muayene bulgularıyla göz hekimi karşılaştırır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'sperm-culture-bacteria'), 'Bacterial culture of semen to detect bacteria in the male genital tract', 'Bakteriološka kultura ejakulata radi otkrivanja bakterija u muškim polnim putevima', 'Бактериолошка култура ејакулата ради откривања бактерија у мушким полним путевима', 'Бактериологический посев эякулята для выявления бактерий в мужских половых путях', 'Bakteriologische Kultur des Ejakulats zum Nachweis von Bakterien im männlichen Genitaltrakt', 'Erkek genital yollarında bakteri aramak için yapılan meni kültürü', 'Semen is obtained by masturbation into a sterile container, plated on culture media, and any growth is tested for antibiotic susceptibility', 'Ejakulat se dobija masturbacijom u sterilnu posudu, zasijava se na hranljive podloge, a kod porasta se radi antibiogram', 'Ејакулат се добија мастурбацијом у стерилну посуду, засијава се на хранљиве подлоге, а код пораста се ради антибиограм', 'Эякулят получают путём мастурбации в стерильный контейнер, материал засевают на питательные среды и при росте определяют чувствительность к антибиотикам', 'Das Ejakulat wird durch Masturbation in ein steriles Gefäß gewonnen, auf Nährböden ausgestrichen und bei Wachstum auf Antibiotikaempfindlichkeit geprüft', 'Meni mastürbasyonla steril kaba alınır, besiyerlerine ekilir ve üreme olursa antibiyogram yapılır', 'Suspected inflammation of the prostate or epididymis, burning and discomfort on urination, infertility work-up, follow-up after treatment as directed by a urologist', 'Sumnja na upalu prostate ili pasjemenika, peckanje i nelagodnost pri mokrenju, ispitivanje kod neplodnosti, kontrola poslije liječenja po savjetu urologa', 'Сумња на упалу простате или пасјеменика, пецкање и нелагодност при мокрењу, испитивање код неплодности, контрола послије лијечења по савјету уролога', 'Подозрение на воспаление предстательной железы или придатка яичка, жжение и дискомфорт при мочеиспускании, обследование при бесплодии, контроль после лечения по назначению уролога', 'Verdacht auf Entzündung der Prostata oder des Nebenhodens, Brennen und Beschwerden beim Wasserlassen, Abklärung bei unerfülltem Kinderwunsch, Kontrolle nach Behandlung auf urologische Anordnung', 'Prostat veya epididim iltihabı şüphesi, idrar yaparken yanma ve rahatsızlık, kısırlık araştırması, üroloji hekiminin isteğiyle tedavi sonrası kontrol', 'Sexual abstinence of 2–5 days, urinate before collection and wash hands and genitals with soap; collect only into a sterile container, without a condom or lubricant', 'Polna uzdržanost 2–5 dana, prije uzimanja pomokriti se i oprati ruke i spoljašnje polne organe sapunom; uzorak sakupljati samo u sterilnu posudu, bez kondoma i lubrikanta', 'Полна уздржаност 2–5 дана, прије узимања помокрити се и опрати руке и спољашње полне органе сапуном; узорак сакупљати само у стерилну посуду, без кондома и лубриканта', 'Половое воздержание 2–5 дней, перед сбором помочиться, вымыть руки и наружные половые органы с мылом; материал собирать только в стерильный контейнер, без презерватива и смазки', 'Sexuelle Karenz von 2–5 Tagen, vor der Gewinnung Wasser lassen sowie Hände und äußere Genitalien mit Seife waschen; Auffangen nur in ein steriles Gefäß, ohne Kondom und Gleitmittel', '2–5 gün cinsel perhiz, örnek vermeden önce idrara çıkmak ve elleri ile dış genital bölgeyi sabunla yıkamak gerekir; örnek yalnızca steril kaba, prezervatif ve kayganlaştırıcı kullanmadan alınır', 'Bacterial growth may be related to an inflammatory process in the urogenital tract or to skin flora entering the sample during collection. The significance of the finding is assessed by the urologist', 'Porast bakterija može biti povezan sa upalnim procesom u mokraćnim i polnim putevima ili sa florom kože koja je dospjela u uzorak. Značaj nalaza procjenjuje urolog', 'Пораст бактерија може бити повезан са упалним процесом у мокраћним и полним путевима или са флором коже која је доспјела у узорак. Значај налаза процјењује уролог', 'Рост бактерий может быть связан с воспалительным процессом в мочеполовых путях либо с попаданием флоры кожи при сборе. Значимость находки оценивает уролог', 'Bakterienwachstum kann mit einem entzündlichen Prozess im Urogenitaltrakt oder mit Hautflora zusammenhängen, die bei der Gewinnung in die Probe gelangt ist. Die Bedeutung des Befundes beurteilt der Urologe', 'Bakteri üremesi idrar ve genital yollardaki iltihapla ya da örnek alınırken bulaşan deri florasıyla ilişkili olabilir. Bulgunun önemini üroloji hekimi değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'sputum-bacteria'), 'Bacterial culture of sputum from the lower airways', 'Bakteriološka kultura ispljuvka iz donjih disajnih puteva', 'Бактериолошка култура испљувка из доњих дисајних путева', 'Бактериологический посев мокроты из нижних дыхательных путей', 'Bakteriologische Kultur von Auswurf aus den unteren Atemwegen', 'Alt solunum yollarından alınan balgamın bakteri kültürü', 'The patient coughs sputum into a sterile container, the laboratory plates it on culture media and tests any growth for antibiotic susceptibility', 'Pacijent iskašljava sputum u sterilnu posudu, u laboratoriji se zasijava na podloge, a kod porasta se radi antibiogram', 'Пацијент искашљава спутум у стерилну посуду, у лабораторији се засијава на подлоге, а код пораста се ради антибиограм', 'Пациент откашливает мокроту в стерильный контейнер, в лаборатории её засевают на среды и при росте определяют чувствительность к антибиотикам', 'Der Patient hustet Sputum in ein steriles Gefäß, im Labor wird es auf Nährböden ausgestrichen und bei Wachstum auf Antibiotikaempfindlichkeit geprüft', 'Hasta balgamı steril kaba öksürerek çıkarır, laboratuvarda besiyerlerine ekilir ve üreme olursa antibiyogram yapılır', 'Prolonged productive cough, pneumonia, exacerbation of chronic bronchitis and COPD, lack of response to prescribed treatment', 'Dugotrajan kašalj sa iskašljavanjem, upala pluća, pogoršanje hroničnog bronhitisa i HOBP, izostanak efekta propisane terapije', 'Дуготрајан кашаљ са искашљавањем, упала плућа, погоршање хроничног бронхитиса и ХОБП, изостанак ефекта прописане терапије', 'Затяжной кашель с мокротой, пневмония, обострение хронического бронхита и ХОБЛ, отсутствие эффекта от назначенного лечения', 'Anhaltender Husten mit Auswurf, Lungenentzündung, Verschlechterung von chronischer Bronchitis und COPD, fehlendes Ansprechen auf die verordnete Behandlung', 'Balgamlı uzun süren öksürük, zatürre, kronik bronşit ve KOAH alevlenmesi, verilen tedaviye yanıt alınamaması', 'Sputum is collected in the morning before eating, after brushing the teeth and rinsing the mouth with water, coughing it up from deep in the airways rather than spitting saliva', 'Sputum se sakuplja ujutru natašte, poslije pranja zuba i ispiranja usta vodom, iskašljavanjem iz dubine disajnih puteva, a ne pljuvanjem pljuvačke', 'Спутум се сакупља ујутру наташте, послије прања зуба и испирања уста водом, искашљавањем из дубине дисајних путева, а не пљувањем пљувачке', 'Мокроту собирают утром натощак, после чистки зубов и полоскания рта водой, откашливая её из глубины дыхательных путей, а не сплёвывая слюну', 'Der Auswurf wird morgens nüchtern gewonnen, nach dem Zähneputzen und Ausspülen des Mundes mit Wasser, tief aus den Atemwegen abgehustet und nicht als Speichel ausgespuckt', 'Balgam sabah aç karnına, dişler fırçalanıp ağız suyla çalkalandıktan sonra, tükürük değil solunum yollarının derininden öksürükle çıkarılan materyal olarak toplanır', 'Bacterial growth may be related to an airway infection or to mouth flora that entered the sample. The result is assessed by a doctor together with the clinical picture', 'Porast bakterija može biti povezan sa infekcijom disajnih puteva ili sa florom usne duplje koja je dospjela u uzorak. Nalaz uz kliničku sliku procjenjuje ljekar', 'Пораст бактерија може бити повезан са инфекцијом дисајних путева или са флором усне дупље која је доспјела у узорак. Налаз уз клиничку слику процјењује љекар', 'Рост бактерий может быть связан с инфекцией дыхательных путей или с флорой полости рта, попавшей в образец. Результат вместе с клинической картиной оценивает врач', 'Bakterienwachstum kann mit einer Atemwegsinfektion oder mit Mundflora zusammenhängen, die in die Probe gelangt ist. Der Befund wird zusammen mit dem klinischen Bild vom Arzt beurteilt', 'Bakteri üremesi solunum yolu enfeksiyonuyla ya da örneğe karışan ağız florasıyla ilişkili olabilir. Sonucu klinik tabloyla birlikte hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'sputum-fungi'), 'Mycological examination of sputum, a culture for yeasts and moulds', 'Mikološko ispitivanje ispljuvka, kultura na kvasnice i plijesni', 'Миколошко испитивање испљувка, култура на кваснице и плијесни', 'Микологическое исследование мокроты — посев на дрожжевые и плесневые грибы', 'Mykologische Untersuchung des Auswurfs, eine Kultur auf Hefe- und Schimmelpilze', 'Balgamın mantar yönünden incelenmesi, maya ve küf mantarları için kültür', 'Sputum coughed into a sterile container is plated on special fungal media, and growth is assessed over a longer period than in bacterial culture', 'Sputum iskašljan u sterilnu posudu zasijava se na posebne podloge za gljivice, a porast se prati duže nego kod bakteriološke kulture', 'Спутум искашљан у стерилну посуду засијава се на посебне подлоге за гљивице, а пораст се прати дуже него код бактериолошке културе', 'Откашлянную в стерильный контейнер мокроту засевают на специальные среды для грибов, рост оценивают дольше, чем при бактериальном посеве', 'In ein steriles Gefäß abgehusteter Auswurf wird auf spezielle Pilznährböden ausgestrichen, das Wachstum wird länger beobachtet als bei der Bakterienkultur', 'Steril kaba öksürülerek alınan balgam mantarlara özgü besiyerlerine ekilir, üreme bakteri kültürüne göre daha uzun sürede değerlendirilir', 'Prolonged cough without response to antibacterial treatment, long-term use of antibiotics or inhaled steroids, work-up in reduced immunity, monitoring as directed by a pulmonologist', 'Dugotrajan kašalj bez odgovora na antibiotsku terapiju, dugotrajno uzimanje antibiotika ili inhalacionih kortikosteroida, ispitivanje kod oslabljenog imuniteta, kontrola po savjetu pulmologa', 'Дуготрајан кашаљ без одговора на антибиотску терапију, дуготрајно узимање антибиотика или инхалационих кортикостероида, испитивање код ослабљеног имунитета, контрола по савјету пулмолога', 'Затяжной кашель без ответа на антибактериальное лечение, длительный приём антибиотиков или ингаляционных гормонов, обследование при сниженном иммунитете, контроль по назначению пульмонолога', 'Anhaltender Husten ohne Ansprechen auf antibakterielle Behandlung, längere Einnahme von Antibiotika oder inhalativen Kortikosteroiden, Abklärung bei geschwächter Immunabwehr, Kontrolle auf Anordnung des Pneumologen', 'Antibiyotik tedavisine yanıt vermeyen uzun süreli öksürük, uzun süreli antibiyotik veya soluma yoluyla kortizon kullanımı, bağışıklığı düşük kişilerde inceleme, göğüs hastalıkları hekiminin istediği kontrol', 'Collected in the morning before eating, after brushing the teeth and rinsing the mouth with water, so that sputum from the lungs rather than saliva reaches the container', 'Uzorak se sakuplja ujutru natašte, poslije pranja zuba i ispiranja usta vodom, tako da u posudu dospije ispljuvak iz pluća, a ne pljuvačka', 'Узорак се сакупља ујутру наташте, послије прања зуба и испирања уста водом, тако да у посуду доспије испљувак из плућа, а не пљувачка', 'Собирают утром натощак, после чистки зубов и полоскания рта водой, чтобы в контейнер попала мокрота из лёгких, а не слюна', 'Gewinnung morgens nüchtern, nach dem Zähneputzen und Ausspülen des Mundes mit Wasser, damit Auswurf aus der Lunge und nicht Speichel in das Gefäß gelangt', 'Örnek sabah aç karnına, dişler fırçalanıp ağız suyla çalkalandıktan sonra alınır, böylece kaba tükürük değil akciğerden gelen balgam toplanır', 'Fungal growth may reflect colonisation of the mucous membranes or involvement of fungi in inflammation, and the two can be told apart only alongside symptoms and other tests. The conclusion is drawn by a doctor', 'Porast gljivica može značiti kolonizaciju sluznica, ali i učešće gljivica u upali, a razlikovanje je moguće samo uz simptome i druge nalaze. Zaključak donosi ljekar', 'Пораст гљивица може значити колонизацију слузница, али и учешће гљивица у упали, а разликовање је могуће само уз симптоме и друге налазе. Закључак доноси љекар', 'Рост грибов может отражать как колонизацию слизистых, так и участие грибов в воспалении, различить это можно только с учётом симптомов и других обследований. Вывод делает врач', 'Pilzwachstum kann eine Besiedlung der Schleimhäute oder eine Beteiligung von Pilzen an der Entzündung widerspiegeln, unterscheiden lässt sich das nur zusammen mit Symptomen und weiteren Untersuchungen. Die Bewertung nimmt der Arzt vor', 'Mantar üremesi mukozalarda kolonizasyonu da, iltihaba mantarların katıldığını da gösterebilir, ikisi ancak belirtiler ve diğer tetkiklerle birlikte ayırt edilir. Değerlendirmeyi hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'wound-swab-bacteria'), 'Culture of wound discharge for bacterial flora with antibiotic susceptibility testing', 'Kultura sekreta rane na bakterijsku floru sa antibiogramom', 'Култура секрета ране на бактеријску флору са антибиограмом', 'Посев отделяемого раны на бактериальную флору с определением чувствительности к антибиотикам', 'Kultur von Wundsekret auf Bakterienflora mit Antibiogramm', 'Yara akıntısının bakteri kültürü ve antibiyogramı', 'A sterile swab collects discharge from the base and edges of the wound after the surface coating is removed, and the material is plated on culture media', 'Sterilnim štapićem uzima se sekret sa dna i ivica rane nakon uklanjanja površinskih naslaga, a materijal se zasijava na hranljive podloge', 'Стерилним штапићем узима се секрет са дна и ивица ране након уклањања површинских наслага, а материјал се засијава на хранљиве подлоге', 'Стерильным тампоном берут отделяемое со дна и краёв раны после удаления поверхностного налёта, материал засевают на питательные среды', 'Mit einem sterilen Tupfer wird Sekret vom Wundgrund und den Wundrändern entnommen, nachdem der oberflächliche Belag entfernt wurde, und auf Nährböden ausgestrichen', 'Yüzeydeki tabaka temizlendikten sonra steril eküvyonla yaranın tabanından ve kenarlarından akıntı alınır ve besiyerlerine ekilir', 'Purulent discharge, redness and swelling around the wound, slow-healing and post-operative wounds, trophic ulcers, selection of an antibiotic by the doctor', 'Gnojni sekret, crvenilo i otok oko rane, rane koje dugo ne zarastaju i postoperativne rane, potkoljenični ulkusi, izbor antibiotika od strane ljekara', 'Гнојни секрет, црвенило и оток око ране, ране које дуго не зарастају и постоперативне ране, поткољенични улкуси, избор антибиотика од стране љекара', 'Гнойное отделяемое, покраснение и отёк вокруг раны, длительно незаживающие и послеоперационные раны, трофические язвы, подбор антибиотика врачом', 'Eitriges Sekret, Rötung und Schwellung um die Wunde, schlecht heilende und postoperative Wunden, Unterschenkelgeschwüre, Auswahl eines Antibiotikums durch den Arzt', 'İltihaplı akıntı, yara çevresinde kızarıklık ve şişlik, geç iyileşen ve ameliyat sonrası yaralar, bacak ülserleri, hekimin antibiyotik seçimi', 'Do not apply antiseptics to the wound before sampling; the dressing is removed immediately before the procedure', 'Prije uzimanja ranu ne tretirati antisepticima, a zavoj se skida neposredno prije postupka', 'Прије узимања рану не третирати антисептицима, а завој се скида непосредно прије поступка', 'Перед взятием рану не обрабатывать антисептиками, повязку снимают непосредственно перед процедурой', 'Die Wunde vor der Entnahme nicht mit Antiseptika behandeln, der Verband wird unmittelbar vor dem Eingriff entfernt', 'Örnek alınmadan önce yaraya antiseptik uygulanmamalı, pansuman işlemden hemen önce açılmalıdır', 'Bacterial growth may be related to wound infection or to colonisation without signs of inflammation. Whether and which treatment is needed is decided by the doctor based on the wound and the symptoms', 'Porast bakterija može biti povezan sa infekcijom rane ili sa kolonizacijom bez znakova upale. Da li je i kakvo liječenje potrebno, određuje ljekar prema izgledu rane i tegobama', 'Пораст бактерија може бити повезан са инфекцијом ране или са колонизацијом без знакова упале. Да ли је и какво лијечење потребно, одређује љекар према изгледу ране и тегобама', 'Рост бактерий может быть связан с инфицированием раны или с колонизацией без признаков воспаления. Нужно ли лечение и какое, определяет врач по виду раны и жалобам', 'Bakterienwachstum kann mit einer Wundinfektion oder mit einer Besiedlung ohne Entzündungszeichen zusammenhängen. Ob und welche Behandlung nötig ist, entscheidet der Arzt anhand von Wundbild und Beschwerden', 'Bakteri üremesi yara enfeksiyonuyla ya da iltihap belirtisi olmadan kolonizasyonla ilişkili olabilir. Tedavi gerekip gerekmediğine ve türüne, yaranın görünümü ve şikayetlere göre hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'wound-swab-fungi'), 'Examination of wound discharge for yeasts and moulds', 'Ispitivanje sekreta rane na kvasnice i plijesni', 'Испитивање секрета ране на кваснице и плијесни', 'Исследование отделяемого раны на дрожжевые и плесневые грибы', 'Untersuchung von Wundsekret auf Hefe- und Schimmelpilze', 'Yara akıntısının maya ve küf mantarları yönünden incelenmesi', 'Material is taken from the wound with a sterile swab and plated on special fungal media, with growth assessed over a longer period than in bacterial culture', 'Materijal sa rane uzima se sterilnim štapićem i zasijava na posebne podloge za gljivice, a porast se prati duže nego kod bakteriološke kulture', 'Материјал са ране узима се стерилним штапићем и засијава на посебне подлоге за гљивице, а пораст се прати дуже него код бактериолошке културе', 'Материал с раны берут стерильным тампоном и засевают на специальные среды для грибов, рост оценивают в течение более длительного времени, чем при бактериальном посеве', 'Das Material wird mit einem sterilen Tupfer aus der Wunde entnommen und auf spezielle Pilznährböden ausgestrichen, das Wachstum wird länger beobachtet als bei der Bakterienkultur', 'Yaradan steril eküvyonla alınan örnek mantarlara özgü besiyerlerine ekilir, üreme bakteri kültürüne göre daha uzun sürede değerlendirilir', 'Slow-healing wounds, no response to antibacterial treatment, wounds in patients with diabetes or reduced immunity, burn surfaces', 'Rane koje dugo ne zarastaju, izostanak efekta antibiotske terapije, rane kod pacijenata sa dijabetesom i oslabljenim imunitetom, opekotinske površine', 'Ране које дуго не зарастају, изостанак ефекта антибиотске терапије, ране код пацијената са дијабетесом и ослабљеним имунитетом, опекотинске површине', 'Длительно незаживающие раны, отсутствие эффекта от антибактериального лечения, раны у пациентов с диабетом и сниженным иммунитетом, ожоговые поверхности', 'Schlecht heilende Wunden, fehlendes Ansprechen auf antibakterielle Behandlung, Wunden bei Patienten mit Diabetes oder geschwächter Immunabwehr, Brandwunden', 'Geç iyileşen yaralar, antibiyotik tedavisine yanıt alınamaması, şeker hastalığı veya bağışıklık düşüklüğü olan hastalardaki yaralar, yanık yüzeyleri', 'Do not treat the wound with antiseptics or antifungal products before sampling; the dressing is removed immediately before the procedure', 'Ranu prije uzimanja ne tretirati antisepticima ni antimikoticima, a zavoj se skida neposredno prije postupka', 'Рану прије узимања не третирати антисептицима ни антимикотицима, а завој се скида непосредно прије поступка', 'Рану перед взятием не обрабатывать антисептиками и противогрибковыми средствами, повязку снимают непосредственно перед процедурой', 'Die Wunde vor der Entnahme nicht mit Antiseptika oder Antimykotika behandeln, der Verband wird unmittelbar vor dem Eingriff entfernt', 'Örnek alınmadan önce yaraya antiseptik ve mantar ilacı uygulanmamalı, pansuman işlemden hemen önce açılmalıdır', 'Detection of fungi may reflect superficial colonisation or their involvement in wound inflammation. The significance of the finding is assessed by the treating doctor', 'Nalaz gljivica može značiti površinsku kolonizaciju, ali i njihovo učešće u upali rane. Značaj nalaza procjenjuje ljekar koji liječi', 'Налаз гљивица може значити површинску колонизацију, али и њихово учешће у упали ране. Значај налаза процјењује љекар који лијечи', 'Обнаружение грибов может отражать как поверхностную колонизацию, так и их участие в воспалении раны. Значение находки оценивает лечащий врач', 'Ein Pilznachweis kann eine oberflächliche Besiedlung oder eine Beteiligung an der Wundentzündung widerspiegeln. Die Bedeutung des Befundes beurteilt der behandelnde Arzt', 'Mantar saptanması yüzeysel kolonizasyonu da, mantarların yara iltihabına katıldığını da gösterebilir. Bulgunun önemini tedaviyi yürüten hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'c-peptide'), 'Indicator of the body''s own insulin production by the pancreas', 'Pokazatelj sopstvene proizvodnje insulina u pankreasu', 'Показатељ сопствене производње инсулина у панкреасу', 'Показатель собственной выработки инсулина поджелудочной железой', 'Kennwert für die eigene Insulinproduktion der Bauchspeicheldrüse', 'Pankreasın kendi insülin üretimini gösteren bir değer', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing remaining insulin production in diabetes mellitus, clarifying the type of diabetes, episodes of low blood sugar of unclear origin', 'Procjena preostale proizvodnje insulina kod šećerne bolesti, razjašnjenje tipa dijabetesa, epizode niskog šećera u krvi nejasnog porijekla', 'Процјена преостале производње инсулина код шећерне болести, разјашњење типа дијабетеса, епизоде ниског шећера у крви нејасног поријекла', 'Оценка остаточной выработки инсулина при сахарном диабете, уточнение типа диабета, эпизоды низкого сахара крови неясного происхождения', 'Beurteilung der verbliebenen Insulinproduktion bei Diabetes mellitus, Abklärung des Diabetestyps, Episoden von niedrigem Blutzucker unklarer Ursache', 'Diyabette kalan insülin üretiminin değerlendirilmesi, diyabet tipinin netleştirilmesi, nedeni belirsiz düşük kan şekeri atakları', 'Usually taken in the morning on an empty stomach, often together with glucose; if you take medications affecting blood sugar, the doctor specifies how to schedule the test', 'Obično se uzima ujutru natašte, često zajedno sa glukozom; ako se uzimaju lijekovi koji utiču na šećer u krvi, način davanja uzorka određuje ljekar', 'Обично се узима ујутру наташте, често заједно са глукозом; ако се узимају лијекови који утичу на шећер у крви, начин давања узорка одређује љекар', 'Обычно сдаётся утром натощак, часто вместе с глюкозой; если принимаются препараты, влияющие на сахар крови, порядок сдачи уточняет врач', 'Wird meist morgens nüchtern abgenommen, oft zusammen mit Glukose; bei Einnahme blutzuckerwirksamer Medikamente legt der Arzt das Vorgehen fest', 'Genellikle sabah aç karnına, çoğu zaman glukozla birlikte alınır; kan şekerini etkileyen ilaç kullanılıyorsa testin nasıl yapılacağını hekim belirler', 'Changes may be related to the function of the pancreatic beta cells, the glucose level at the time of sampling, or kidney function. A doctor evaluates it together with glucose and the clinical picture', 'Promjene mogu biti povezane sa radom beta ćelija pankreasa, nivoom glukoze u trenutku uzimanja uzorka ili funkcijom bubrega. Ljekar procjenjuje nalaz zajedno sa glukozom i kliničkom slikom', 'Промјене могу бити повезане са радом бета ћелија панкреаса, нивоом глукозе у тренутку узимања узорка или функцијом бубрега. Љекар процјењује налаз заједно са глукозом и клиничком сликом', 'Изменения могут быть связаны с работой бета-клеток поджелудочной железы, уровнем глюкозы в момент забора или функцией почек. Оценивает врач вместе с глюкозой и клинической картиной', 'Veränderungen können mit der Funktion der Betazellen der Bauchspeicheldrüse, dem Glukosewert zum Zeitpunkt der Entnahme oder der Nierenfunktion zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit dem Glukosewert und dem klinischen Bild', 'Değişiklikler pankreastaki beta hücrelerinin çalışmasıyla, örnek alındığı andaki glukoz düzeyiyle veya böbrek fonksiyonuyla ilişkili olabilir. Hekim sonucu glukoz ve klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'fsh'), 'Blood test for a pituitary hormone that drives egg maturation in women and sperm production in men', 'Analiza krvi na hormon hipofize koji upravlja sazrijevanjem jajnih ćelija kod žena i stvaranjem spermatozoida kod muškaraca', 'Анализа крви на хормон хипофизе који управља сазријевањем јајних ћелија код жена и стварањем сперматозоида код мушкараца', 'Анализ крови на гормон гипофиза, который управляет созреванием яйцеклеток у женщин и выработкой сперматозоидов у мужчин', 'Bluttest auf ein Hypophysenhormon, das die Eizellreifung bei Frauen und die Spermienbildung bei Männern steuert', 'Kadınlarda yumurta olgunlaşmasını, erkeklerde sperm üretimini yöneten bir hipofiz hormonu için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing causes of menstrual cycle disorders, work-up for difficulties conceiving, evaluation of ovarian and testicular function, clarifying the menopausal period', 'Procjena uzroka poremećaja menstrualnog ciklusa, ispitivanje kod teškoća sa začećem, procjena rada jajnika i testisa, razjašnjenje perioda menopauze', 'Процјена узрока поремећаја менструалног циклуса, испитивање код тешкоћа са зачећем, процјена рада јајника и тестиса, разјашњење периода менопаузе', 'Оценка причин нарушений менструального цикла, обследование при трудностях с зачатием, оценка работы яичников и яичек, уточнение периода менопаузы', 'Abklärung von Ursachen für Menstruationsstörungen, Untersuchung bei unerfülltem Kinderwunsch, Beurteilung der Eierstock- und Hodenfunktion, Einordnung der Wechseljahre', 'Adet döngüsü bozukluklarının nedenlerinin araştırılması, gebe kalma güçlüğünde inceleme, yumurtalık ve testis fonksiyonunun değerlendirilmesi, menopoz döneminin netleştirilmesi', 'In women of reproductive age the test is tied to a day of the menstrual cycle, which the doctor sets; in men there is no cycle timing and no special preparation is usually required', 'Kod žena reproduktivne dobi analiza je vezana za dan menstrualnog ciklusa, a konkretan dan određuje ljekar; kod muškaraca nema vezanosti za ciklus i obično nije potrebna posebna priprema', 'Код жена репродуктивне доби анализа је везана за дан менструалног циклуса, а конкретан дан одређује љекар; код мушкараца нема везаности за циклус и обично није потребна посебна припрема', 'У женщин репродуктивного возраста анализ привязан к дню менструального цикла, конкретный день назначает врач; у мужчин привязки к циклу нет и специальной подготовки обычно не требуется', 'Bei Frauen im gebärfähigen Alter ist die Untersuchung an einen Zyklustag gebunden, den der Arzt festlegt; bei Männern besteht keine Zyklusbindung und in der Regel ist keine besondere Vorbereitung nötig', 'Üreme çağındaki kadınlarda test adet döngüsünün belirli bir gününe bağlıdır ve bu günü hekim belirler; erkeklerde döngü bağlantısı yoktur ve genellikle özel hazırlık gerekmez', 'A deviation on its own is not a diagnosis: the result is assessed by a doctor together with the cycle phase and the other values of the hormone profile', 'Odstupanje samo po sebi nije dijagnoza: nalaz procjenjuje ljekar zajedno sa fazom ciklusa i ostalim pokazateljima hormonskog profila', 'Одступање само по себи није дијагноза: налаз процјењује љекар заједно са фазом циклуса и осталим показатељима хормонског профила', 'Отклонение само по себе не диагноз: результат оценивается врачом вместе с фазой цикла и остальными показателями гормонального профиля', 'Eine Abweichung allein ist keine Diagnose: Der Befund wird vom Arzt zusammen mit der Zyklusphase und den übrigen Werten des Hormonprofils beurteilt', 'Tek başına bir sapma tanı anlamına gelmez: sonucu hekim, döngü evresi ve hormon profilinin diğer değerleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'lh'), 'Blood test for a pituitary hormone that triggers ovulation in women and testosterone production in men', 'Analiza krvi na hormon hipofize koji pokreće ovulaciju kod žena i stvaranje testosterona kod muškaraca', 'Анализа крви на хормон хипофизе који покреће овулацију код жена и стварање тестостерона код мушкараца', 'Анализ крови на гормон гипофиза, который запускает овуляцию у женщин и выработку тестостерона у мужчин', 'Bluttest auf ein Hypophysenhormon, das den Eisprung bei Frauen und die Testosteronbildung bei Männern auslöst', 'Kadınlarda yumurtlamayı, erkeklerde testosteron üretimini tetikleyen bir hipofiz hormonu için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Work-up of menstrual cycle disorders, timing of ovulation, evaluation of difficulties conceiving, assessment of gonadal function', 'Ispitivanje poremećaja menstrualnog ciklusa, određivanje vremena ovulacije, obrada kod teškoća sa začećem, procjena rada polnih žlijezda', 'Испитивање поремећаја менструалног циклуса, одређивање времена овулације, обрада код тешкоћа са зачећем, процјена рада полних жлијезда', 'Обследование при нарушениях менструального цикла, определение времени овуляции, обследование при трудностях с зачатием, оценка работы половых желёз', 'Abklärung von Zyklusstörungen, Bestimmung des Eisprungzeitpunkts, Untersuchung bei unerfülltem Kinderwunsch, Beurteilung der Keimdrüsenfunktion', 'Adet döngüsü bozukluklarının incelenmesi, yumurtlama zamanının belirlenmesi, gebe kalma güçlüğünde değerlendirme, üreme bezlerinin işlevinin değerlendirilmesi', 'In women of reproductive age the doctor sets the cycle day for the test and may order samples on several consecutive days; men only need to be calm before the draw', 'Kod žena reproduktivne dobi dan ciklusa za analizu određuje ljekar, ponekad se uzorak uzima nekoliko dana zaredom; muškarcima je dovoljno mirno stanje prije vađenja krvi', 'Код жена репродуктивне доби дан циклуса за анализу одређује љекар, понекад се узорак узима неколико дана заредом; мушкарцима је довољно мирно стање прије вађења крви', 'У женщин репродуктивного возраста день цикла для сдачи определяет врач, иногда анализ повторяют несколько дней подряд; мужчинам достаточно спокойного состояния перед забором', 'Bei Frauen im gebärfähigen Alter legt der Arzt den Zyklustag fest, mitunter wird an mehreren aufeinanderfolgenden Tagen Blut abgenommen; bei Männern genügt ein ruhiger Zustand vor der Entnahme', 'Üreme çağındaki kadınlarda test günü hekim tarafından belirlenir, bazen birkaç gün üst üste örnek alınır; erkeklerde kan alınmadan önce sakin olmak yeterlidir', 'A single result is not a diagnosis on its own: the doctor assesses it together with the cycle phase and the other hormones', 'Pojedinačan nalaz sam po sebi nije dijagnoza: ljekar ga procjenjuje zajedno sa fazom ciklusa i ostalim hormonima', 'Појединачан налаз сам по себи није дијагноза: љекар га процјењује заједно са фазом циклуса и осталим хормонима', 'Отдельный результат сам по себе не диагноз: врач оценивает его вместе с фазой цикла и остальными гормонами', 'Ein einzelner Wert ist für sich genommen keine Diagnose: Der Arzt beurteilt ihn zusammen mit der Zyklusphase und den übrigen Hormonen', 'Tek bir sonuç başlı başına tanı değildir: hekim bunu döngü evresi ve diğer hormonlarla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'progesterone'), 'Blood test for the hormone responsible for the second phase of the menstrual cycle and for maintaining pregnancy', 'Analiza krvi na hormon koji je odgovoran za drugu fazu menstrualnog ciklusa i održavanje trudnoće', 'Анализа крви на хормон који је одговоран за другу фазу менструалног циклуса и одржавање трудноће', 'Анализ крови на гормон, который отвечает за вторую фазу менструального цикла и поддержание беременности', 'Bluttest auf das Hormon, das für die zweite Phase des Menstruationszyklus und den Erhalt der Schwangerschaft zuständig ist', 'Adet döngüsünün ikinci evresinden ve gebeliğin sürdürülmesinden sorumlu hormon için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Confirming that ovulation has occurred, work-up of cycle disorders and difficulties conceiving, monitoring during pregnancy as prescribed by a doctor', 'Potvrda da je došlo do ovulacije, obrada poremećaja ciklusa i teškoća sa začećem, praćenje u trudnoći po preporuci ljekara', 'Потврда да је дошло до овулације, обрада поремећаја циклуса и тешкоћа са зачећем, праћење у трудноћи по препоруци љекара', 'Подтверждение произошедшей овуляции, обследование при нарушениях цикла и трудностях с зачатием, наблюдение при беременности по назначению врача', 'Bestätigung eines stattgefundenen Eisprungs, Abklärung von Zyklusstörungen und unerfülltem Kinderwunsch, Verlaufskontrolle in der Schwangerschaft nach ärztlicher Anordnung', 'Yumurtlamanın gerçekleştiğinin doğrulanması, döngü bozuklukları ve gebe kalma güçlüğünün araştırılması, hekim önerisiyle gebelikte izlem', 'In women of reproductive age blood is taken on a cycle day belonging to the second phase of the cycle, and the doctor sets that day; no other special preparation is usually required', 'Kod žena reproduktivne dobi krv se uzima u danu ciklusa koji pripada drugoj fazi, a taj dan određuje ljekar; druga posebna priprema obično nije potrebna', 'Код жена репродуктивне доби крв се узима у дану циклуса који припада другој фази, а тај дан одређује љекар; друга посебна припрема обично није потребна', 'У женщин репродуктивного возраста кровь сдаётся в день цикла, относящийся к его второй фазе, и этот день назначает врач; другой специальной подготовки обычно не требуется', 'Bei Frauen im gebärfähigen Alter wird das Blut an einem Zyklustag der zweiten Zyklusphase abgenommen, den der Arzt festlegt; eine weitere besondere Vorbereitung ist meist nicht nötig', 'Üreme çağındaki kadınlarda kan, döngünün ikinci evresine denk gelen ve hekimin belirlediği bir günde alınır; bunun dışında genellikle özel hazırlık gerekmez', 'The result alone is not a diagnosis: the doctor assesses it together with the cycle phase and the other values', 'Nalaz sam po sebi nije dijagnoza: ljekar ga procjenjuje zajedno sa fazom ciklusa i ostalim pokazateljima', 'Налаз сам по себи није дијагноза: љекар га процјењује заједно са фазом циклуса и осталим показатељима', 'Сам по себе результат не диагноз: врач оценивает его вместе с фазой цикла и остальными показателями', 'Der Wert allein ist keine Diagnose: Der Arzt beurteilt ihn zusammen mit der Zyklusphase und den übrigen Werten', 'Sonuç tek başına tanı değildir: hekim bunu döngü evresi ve diğer göstergelerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'insulin'), 'Blood test for the pancreatic hormone that regulates how tissues take up glucose', 'Analiza krvi na hormon pankreasa koji reguliše iskorišćavanje glukoze u tkivima', 'Анализа крви на хормон панкреаса који регулише искоришћавање глукозе у ткивима', 'Анализ крови на гормон поджелудочной железы, который регулирует усвоение глюкозы тканями', 'Bluttest auf das Hormon der Bauchspeicheldrüse, das die Glukoseaufnahme in die Gewebe steuert', 'Dokuların glukozu kullanmasını düzenleyen pankreas hormonu için kan testi', 'Venous blood draw, usually together with a glucose sample', 'Uzimanje venske krvi, obično zajedno sa uzorkom za glukozu', 'Узимање венске крви, обично заједно са узорком за глукозу', 'Забор венозной крови, обычно вместе с пробой на глюкозу', 'Entnahme von venösem Blut, meist zusammen mit einer Probe für Glukose', 'Venöz kan alımı, genellikle glukoz örneğiyle birlikte', 'Assessing carbohydrate metabolism, work-up in excess weight, episodes of weakness after meals, suspected reduced tissue sensitivity to insulin', 'Procjena metabolizma ugljenih hidrata, ispitivanje kod prekomjerne tjelesne težine, kod slabosti poslije obroka, kod sumnje na smanjenu osjetljivost tkiva na insulin', 'Процјена метаболизма угљених хидрата, испитивање код прекомјерне тјелесне тежине, код слабости послије оброка, код сумње на смањену осјетљивост ткива на инсулин', 'Оценка углеводного обмена, обследование при избыточном весе, при эпизодах слабости после еды, при подозрении на сниженную чувствительность тканей к инсулину', 'Beurteilung des Kohlenhydratstoffwechsels, Abklärung bei Übergewicht, bei Schwäche nach dem Essen, bei Verdacht auf verminderte Insulinempfindlichkeit der Gewebe', 'Karbonhidrat metabolizmasının değerlendirilmesi, fazla kiloda inceleme, yemek sonrası halsizlik ataklarında, dokuların insüline duyarlılığının azaldığı şüphesinde', 'Fasting for 8–12 hours, only water allowed; taken in the morning, tell the doctor about any glucose-lowering medications', 'Natašte 8–12 sati, dozvoljena je samo voda; uzorak se uzima ujutru, a o uzimanju lijekova za snižavanje šećera treba obavijestiti ljekara', 'Наташте 8–12 сати, дозвољена је само вода; узорак се узима ујутру, а о узимању лијекова за снижавање шећера треба обавијестити љекара', 'Натощак 8–12 часов, разрешена только вода; сдаётся утром, о приёме сахароснижающих препаратов нужно сообщить врачу', 'Nüchtern seit 8–12 Stunden, nur Wasser erlaubt; Abnahme morgens, die Einnahme blutzuckersenkender Medikamente sollte dem Arzt mitgeteilt werden', '8–12 saat aç karnına, sadece su içilebilir; örnek sabah alınır, kan şekerini düşüren ilaç kullanılıyorsa hekime bildirilmelidir', 'Changes may be related to tissue sensitivity to insulin, food eaten the day before, body weight, or certain medications. A doctor evaluates it together with the glucose level', 'Promjene mogu biti povezane sa osjetljivošću tkiva na insulin, ishranom dan ranije, tjelesnom težinom ili uzimanjem određenih lijekova. Ljekar procjenjuje nalaz zajedno sa nivoom glukoze', 'Промјене могу бити повезане са осјетљивошћу ткива на инсулин, исхраном дан раније, тјелесном тежином или узимањем одређених лијекова. Љекар процјењује налаз заједно са нивоом глукозе', 'Изменения могут быть связаны с чувствительностью тканей к инсулину, питанием накануне, весом или приёмом некоторых препаратов. Оценивает врач вместе с уровнем глюкозы', 'Veränderungen können mit der Insulinempfindlichkeit der Gewebe, der Ernährung am Vortag, dem Körpergewicht oder der Einnahme bestimmter Medikamente zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit dem Glukosewert', 'Değişiklikler dokuların insüline duyarlılığıyla, bir önceki günkü beslenmeyle, kiloyla veya bazı ilaçların kullanımıyla ilişkili olabilir. Hekim sonucu glukoz düzeyiyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-mullerian-hormone'), 'Blood test for the hormone that reflects the pool of follicles in the ovaries', 'Analiza krvi na hormon koji odražava zalihu folikula u jajnicima', 'Анализа крви на хормон који одражава залиху фоликула у јајницима', 'Анализ крови на гормон, который отражает запас фолликулов в яичниках', 'Bluttest auf das Hormon, das den Vorrat an Follikeln in den Eierstöcken widerspiegelt', 'Yumurtalıklardaki folikül rezervini yansıtan hormon için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing ovarian reserve, planning pregnancy and IVF programmes, work-up of cycle disorders, evaluation before ovarian procedures', 'Procjena ovarijalne rezerve, planiranje trudnoće i postupaka vantjelesne oplodnje, ispitivanje poremećaja ciklusa, procjena prije zahvata na jajnicima', 'Процјена оваријалне резерве, планирање трудноће и поступака вантјелесне оплодње, испитивање поремећаја циклуса, процјена прије захвата на јајницима', 'Оценка овариального резерва, планирование беременности и программ ЭКО, обследование при нарушениях цикла, оценка перед вмешательствами на яичниках', 'Beurteilung der Eierstockreserve, Planung einer Schwangerschaft und von IVF-Behandlungen, Abklärung von Zyklusstörungen, Einschätzung vor Eingriffen an den Eierstöcken', 'Yumurtalık rezervinin değerlendirilmesi, gebelik ve tüp bebek planlaması, döngü bozukluklarının incelenmesi, yumurtalık girişimleri öncesi değerlendirme', 'No special preparation is usually required, the level depends little on the cycle day; tell the doctor about any hormonal contraceptives you take', 'Posebna priprema obično nije potrebna, nivo malo zavisi od dana ciklusa; o uzimanju hormonske kontracepcije treba obavijestiti ljekara', 'Посебна припрема обично није потребна, ниво мало зависи од дана циклуса; о узимању хормонске контрацепције треба обавијестити љекара', 'Специальной подготовки обычно не требуется, уровень мало зависит от дня цикла; о приёме гормональных контрацептивов нужно сообщить врачу', 'In der Regel ist keine besondere Vorbereitung nötig, der Wert hängt kaum vom Zyklustag ab; die Einnahme hormoneller Verhütungsmittel sollte dem Arzt mitgeteilt werden', 'Genellikle özel hazırlık gerekmez, düzey döngü gününe az bağlıdır; hormonal doğum kontrol yöntemi kullanılıyorsa hekime bildirilmelidir', 'Changes may be related to age, individual ovarian characteristics, or previous procedures. A doctor evaluates it together with the rest of the work-up', 'Promjene mogu biti povezane sa godinama, individualnim osobinama jajnika ili ranijim zahvatima. Ljekar procjenjuje nalaz zajedno sa ostalim podacima ispitivanja', 'Промјене могу бити повезане са годинама, индивидуалним особинама јајника или ранијим захватима. Љекар процјењује налаз заједно са осталим подацима испитивања', 'Изменения могут быть связаны с возрастом, индивидуальными особенностями яичников или перенесёнными вмешательствами. Оценивает врач вместе с остальными данными обследования', 'Veränderungen können mit dem Alter, individuellen Eigenschaften der Eierstöcke oder früheren Eingriffen zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit den übrigen Untersuchungsbefunden', 'Değişiklikler yaşla, yumurtalıkların bireysel özellikleriyle veya geçirilmiş girişimlerle ilişkili olabilir. Hekim sonucu incelemenin diğer verileriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'calcitonin'), 'Blood test for a thyroid hormone involved in calcium metabolism', 'Analiza krvi na hormon štitne žlijezde koji učestvuje u metabolizmu kalcijuma', 'Анализа крви на хормон штитне жлијезде који учествује у метаболизму калцијума', 'Анализ крови на гормон щитовидной железы, участвующий в обмене кальция', 'Bluttest auf ein Schilddrüsenhormon, das am Kalziumstoffwechsel beteiligt ist', 'Kalsiyum metabolizmasında rol oynayan bir tiroid hormonu için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Work-up of thyroid nodules, follow-up after treatment of thyroid conditions, examination as prescribed by an endocrinologist', 'Ispitivanje kod čvorova na štitnoj žlijezdi, praćenje poslije liječenja oboljenja štitne žlijezde, pregled po uputu endokrinologa', 'Испитивање код чворова на штитној жлијезди, праћење послије лијечења обољења штитне жлијезде, преглед по упуту ендокринолога', 'Обследование при узловых образованиях щитовидной железы, наблюдение после лечения заболеваний щитовидной железы, обследование по назначению эндокринолога', 'Abklärung von Schilddrüsenknoten, Verlaufskontrolle nach Behandlung von Schilddrüsenerkrankungen, Untersuchung nach Anordnung des Endokrinologen', 'Tiroid nodüllerinin araştırılması, tiroid hastalıklarının tedavisi sonrası izlem, endokrinoloji uzmanının isteğiyle inceleme', 'Usually taken in the morning on an empty stomach; tell the doctor about medications you take, especially those affecting the stomach and calcium metabolism', 'Obično se uzima ujutru natašte; o lijekovima koji se uzimaju, naročito onima koji djeluju na želudac i na metabolizam kalcijuma, treba obavijestiti ljekara', 'Обично се узима ујутру наташте; о лијековима који се узимају, нарочито онима који дјелују на желудац и на метаболизам калцијума, треба обавијестити љекара', 'Обычно сдаётся утром натощак; о принимаемых препаратах, особенно влияющих на желудок и на обмен кальция, нужно сообщить врачу', 'Wird meist morgens nüchtern abgenommen; eingenommene Medikamente, insbesondere solche mit Wirkung auf Magen und Kalziumstoffwechsel, sollten dem Arzt mitgeteilt werden', 'Genellikle sabah aç karnına alınır; kullanılan ilaçlar, özellikle mideyi ve kalsiyum metabolizmasını etkileyenler hekime bildirilmelidir', 'Changes may be related to features of the thyroid gland, kidney function, certain medications, or the method used by a particular laboratory. An endocrinologist evaluates the result and may repeat the test', 'Promjene mogu biti povezane sa osobinama štitne žlijezde, funkcijom bubrega, uzimanjem određenih lijekova ili metodom konkretne laboratorije. Nalaz procjenjuje endokrinolog, a po potrebi se analiza ponavlja', 'Промјене могу бити повезане са особинама штитне жлијезде, функцијом бубрега, узимањем одређених лијекова или методом конкретне лабораторије. Налаз процјењује ендокринолог, а по потреби се анализа понавља', 'Изменения могут быть связаны с особенностями щитовидной железы, функцией почек, приёмом некоторых препаратов или методом конкретной лаборатории. Результат оценивает эндокринолог, при необходимости анализ повторяют', 'Veränderungen können mit Besonderheiten der Schilddrüse, der Nierenfunktion, der Einnahme bestimmter Medikamente oder der Methode des jeweiligen Labors zusammenhängen. Der Endokrinologe beurteilt den Befund und wiederholt die Untersuchung bei Bedarf', 'Değişiklikler tiroid bezinin özellikleriyle, böbrek fonksiyonuyla, bazı ilaçların kullanımıyla veya laboratuvarın kullandığı yöntemle ilişkili olabilir. Sonucu endokrinoloji uzmanı değerlendirir, gerektiğinde test tekrarlanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'dhea-s'), 'Blood test for an androgen produced mainly by the adrenal glands', 'Analiza krvi na androgen koji uglavnom stvaraju nadbubrežne žlijezde', 'Анализа крви на андроген који углавном стварају надбубрежне жлијезде', 'Анализ крови на андроген, который вырабатывается преимущественно надпочечниками', 'Bluttest auf ein Androgen, das überwiegend in den Nebennieren gebildet wird', 'Başlıca böbreküstü bezlerinde üretilen bir androjen için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing adrenal function, work-up of excess hair growth, acne, cycle disorders, clarifying the source of excess male sex hormones', 'Procjena rada nadbubrežnih žlijezda, ispitivanje kod pojačane maljavosti, akni, poremećaja ciklusa, utvrđivanje izvora viška muških polnih hormona', 'Процјена рада надбубрежних жлијезда, испитивање код појачане маљавости, акни, поремећаја циклуса, утврђивање извора вишка мушких полних хормона', 'Оценка работы надпочечников, обследование при избыточном оволосении, акне, нарушениях цикла, уточнение источника избытка мужских половых гормонов', 'Beurteilung der Nebennierenfunktion, Abklärung von vermehrter Behaarung, Akne, Zyklusstörungen, Eingrenzung der Quelle überschüssiger männlicher Sexualhormone', 'Böbreküstü bezi işlevinin değerlendirilmesi, aşırı tüylenme, akne, döngü bozukluklarının incelenmesi, fazla erkeklik hormonunun kaynağının belirlenmesi', 'No special preparation is usually required, the level changes little during the day and is not tied to the cycle day; tell the doctor about any hormonal medications', 'Posebna priprema obično nije potrebna, nivo se malo mijenja tokom dana i nije vezan za dan ciklusa; o uzimanju hormonske terapije treba obavijestiti ljekara', 'Посебна припрема обично није потребна, ниво се мало мијења током дана и није везан за дан циклуса; о узимању хормонске терапије треба обавијестити љекара', 'Специальной подготовки обычно не требуется, уровень мало меняется в течение суток и не привязан ко дню цикла; о приёме гормональных препаратов нужно сообщить врачу', 'In der Regel ist keine besondere Vorbereitung nötig, der Wert schwankt im Tagesverlauf kaum und ist nicht an den Zyklustag gebunden; hormonelle Medikamente sollten dem Arzt mitgeteilt werden', 'Genellikle özel hazırlık gerekmez, düzey gün içinde az değişir ve döngü gününe bağlı değildir; hormon ilacı kullanılıyorsa hekime bildirilmelidir', 'Changes may be related to adrenal function, age, or certain medications. A doctor interprets it together with the other hormones', 'Promjene mogu biti povezane sa radom nadbubrežnih žlijezda, godinama ili uzimanjem određenih lijekova. Tumačenje daje ljekar zajedno sa ostalim hormonima', 'Промјене могу бити повезане са радом надбубрежних жлијезда, годинама или узимањем одређених лијекова. Тумачење даје љекар заједно са осталим хормонима', 'Изменения могут быть связаны с работой надпочечников, возрастом или приёмом некоторых препаратов. Интерпретирует врач вместе с остальными гормонами', 'Veränderungen können mit der Nebennierenfunktion, dem Alter oder der Einnahme bestimmter Medikamente zusammenhängen. Die Interpretation erfolgt durch den Arzt zusammen mit den übrigen Hormonen', 'Değişiklikler böbreküstü bezlerinin çalışmasıyla, yaşla veya bazı ilaçların kullanımıyla ilişkili olabilir. Hekim sonucu diğer hormonlarla birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'inhibin-b'), 'Blood test for a hormone that reflects ovarian function in women and sperm maturation in men', 'Analiza krvi na hormon koji odražava rad jajnika kod žena i sazrijevanje spermatozoida kod muškaraca', 'Анализа крви на хормон који одражава рад јајника код жена и сазријевање сперматозоида код мушкараца', 'Анализ крови на гормон, который отражает работу яичников у женщин и созревание сперматозоидов у мужчин', 'Bluttest auf ein Hormon, das die Eierstockfunktion bei Frauen und die Spermienreifung bei Männern widerspiegelt', 'Kadınlarda yumurtalık işlevini, erkeklerde sperm olgunlaşmasını yansıtan hormon için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing reproductive potential together with other hormones, work-up of difficulties conceiving, in men with changes in the semen analysis', 'Procjena reproduktivnog potencijala zajedno sa drugim hormonima, ispitivanje kod teškoća sa začećem, kod muškaraca uz izmijenjen nalaz spermograma', 'Процјена репродуктивног потенцијала заједно са другим хормонима, испитивање код тешкоћа са зачећем, код мушкараца уз измијењен налаз спермограма', 'Оценка репродуктивного потенциала вместе с другими гормонами, обследование при трудностях с зачатием, у мужчин — при изменениях в спермограмме', 'Einschätzung des Fortpflanzungspotenzials zusammen mit anderen Hormonen, Abklärung bei unerfülltem Kinderwunsch, bei Männern bei verändertem Spermiogramm', 'Diğer hormonlarla birlikte üreme potansiyelinin değerlendirilmesi, gebe kalma güçlüğünün araştırılması, erkeklerde sperm tahlilindeki değişikliklerde', 'In women the test is usually tied to a particular cycle day set by the doctor; in men there is no cycle timing and the sample is usually taken in the morning', 'Kod žena je analiza obično vezana za određeni dan ciklusa koji određuje ljekar; kod muškaraca nema vezanosti za ciklus i uzorak se najčešće uzima ujutru', 'Код жена је анализа обично везана за одређени дан циклуса који одређује љекар; код мушкараца нема везаности за циклус и узорак се најчешће узима ујутру', 'У женщин анализ обычно привязан к определённому дню цикла, который назначает врач; у мужчин привязки к циклу нет, забор чаще проводится утром', 'Bei Frauen ist die Untersuchung meist an einen bestimmten Zyklustag gebunden, den der Arzt festlegt; bei Männern besteht keine Zyklusbindung, die Entnahme erfolgt meist morgens', 'Kadınlarda test genellikle hekimin belirlediği bir döngü gününe bağlıdır; erkeklerde döngü bağlantısı yoktur ve örnek çoğunlukla sabah alınır', 'The result alone is not a diagnosis: the doctor assesses it together with the cycle phase and the other values of the reproductive profile', 'Nalaz sam po sebi nije dijagnoza: ljekar ga procjenjuje zajedno sa fazom ciklusa i ostalim pokazateljima reproduktivnog profila', 'Налаз сам по себи није дијагноза: љекар га процјењује заједно са фазом циклуса и осталим показатељима репродуктивног профила', 'Результат сам по себе не диагноз: врач оценивает его вместе с фазой цикла и остальными показателями репродуктивного профиля', 'Der Wert allein ist keine Diagnose: Der Arzt beurteilt ihn zusammen mit der Zyklusphase und den übrigen Werten des Fortpflanzungsprofils', 'Sonuç tek başına tanı değildir: hekim bunu döngü evresi ve üreme profilinin diğer değerleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'shbg'), 'Blood test for the protein that carries sex hormones and determines how much of them is available to tissues', 'Analiza krvi na bjelančevinu koja prenosi polne hormone i određuje koliki je njihov dio dostupan tkivima', 'Анализа крви на бјеланчевину која преноси полне хормоне и одређује колики је њихов дио доступан ткивима', 'Анализ крови на белок, который переносит половые гормоны и определяет, какая их часть доступна тканям', 'Bluttest auf das Eiweiß, das Sexualhormone transportiert und bestimmt, welcher Anteil davon den Geweben zur Verfügung steht', 'Cinsiyet hormonlarını taşıyan ve bunların ne kadarının dokular için kullanılabilir olduğunu belirleyen protein için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Clarifying a testosterone result, work-up of cycle disorders, excess hair growth, reduced libido, assessing hormonal status in metabolic disorders', 'Razjašnjenje nalaza testosterona, ispitivanje kod poremećaja ciklusa, pojačane maljavosti, smanjenog libida, procjena hormonskog statusa kod poremećaja metabolizma', 'Разјашњење налаза тестостерона, испитивање код поремећаја циклуса, појачане маљавости, смањеног либида, процјена хормонског статуса код поремећаја метаболизма', 'Уточнение результата анализа на тестостерон, обследование при нарушениях цикла, избыточном оволосении, снижении либидо, оценка гормонального фона при нарушениях обмена веществ', 'Einordnung eines Testosteronwerts, Abklärung von Zyklusstörungen, vermehrter Behaarung, vermindertem Libido, Beurteilung des Hormonstatus bei Stoffwechselstörungen', 'Testosteron sonucunun netleştirilmesi, döngü bozuklukları, aşırı tüylenme, libido azalmasının incelenmesi, metabolizma bozukluklarında hormonal durumun değerlendirilmesi', 'Usually taken in the morning together with testosterone; no special preparation is needed, but tell the doctor about any hormonal medications', 'Obično se uzima ujutru zajedno sa testosteronom; posebna priprema nije potrebna, ali o uzimanju hormonske terapije treba obavijestiti ljekara', 'Обично се узима ујутру заједно са тестостероном; посебна припрема није потребна, али о узимању хормонске терапије треба обавијестити љекара', 'Обычно сдаётся утром вместе с тестостероном; специальной подготовки не требуется, но о приёме гормональных препаратов нужно сообщить врачу', 'Wird meist morgens zusammen mit Testosteron abgenommen; eine besondere Vorbereitung ist nicht nötig, hormonelle Medikamente sollten dem Arzt mitgeteilt werden', 'Genellikle sabah testosteronla birlikte alınır; özel bir hazırlık gerekmez, ancak hormon ilacı kullanılıyorsa hekime bildirilmelidir', 'Changes may be related to hormonal status, liver and thyroid function, body weight, or the use of estrogens. A doctor evaluates it together with the sex hormone levels', 'Promjene mogu biti povezane sa hormonskim statusom, radom jetre i štitne žlijezde, tjelesnom težinom ili uzimanjem estrogena. Ljekar procjenjuje nalaz zajedno sa nivoom polnih hormona', 'Промјене могу бити повезане са хормонским статусом, радом јетре и штитне жлијезде, тјелесном тежином или узимањем естрогена. Љекар процјењује налаз заједно са нивоом полних хормона', 'Изменения могут быть связаны с гормональным фоном, работой печени и щитовидной железы, весом или приёмом эстрогенов. Оценивает врач вместе с уровнем половых гормонов', 'Veränderungen können mit dem Hormonstatus, der Leber- und Schilddrüsenfunktion, dem Körpergewicht oder der Einnahme von Östrogenen zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit den Sexualhormonwerten', 'Değişiklikler hormonal durumla, karaciğer ve tiroid işleviyle, kiloyla veya östrojen kullanımıyla ilişkili olabilir. Hekim sonucu cinsiyet hormonu düzeyleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 't3'), 'Blood test for total triiodothyronine, a thyroid hormone including the protein-bound fraction', 'Analiza krvi na ukupni trijodtironin, hormon štitne žlijezde zajedno sa dijelom vezanim za bjelančevine', 'Анализа крви на укупни тријодтиронин, хормон штитне жлијезде заједно са дијелом везаним за бјеланчевине', 'Анализ крови на общий трийодтиронин, гормон щитовидной железы вместе со связанной с белками частью', 'Bluttest auf Gesamt-Trijodthyronin, ein Schilddrüsenhormon einschließlich des eiweißgebundenen Anteils', 'Proteine bağlı kısım dahil olmak üzere total triiyodotironin adlı tiroid hormonu için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing thyroid function together with TSH, monitoring treatment of thyroid conditions, in case of palpitations, sweating, weight changes', 'Procjena rada štitne žlijezde zajedno sa TSH, kontrola liječenja oboljenja štitne žlijezde, kod lupanja srca, znojenja, promjene tjelesne težine', 'Процјена рада штитне жлијезде заједно са TSH, контрола лијечења обољења штитне жлијезде, код лупања срца, знојења, промјене тјелесне тежине', 'Оценка работы щитовидной железы вместе с TSH, контроль лечения заболеваний щитовидной железы, при жалобах на сердцебиение, потливость, изменения веса', 'Beurteilung der Schilddrüsenfunktion zusammen mit TSH, Kontrolle der Behandlung von Schilddrüsenerkrankungen, bei Herzklopfen, Schwitzen, Gewichtsveränderungen', 'TSH ile birlikte tiroid işlevinin değerlendirilmesi, tiroid hastalıklarının tedavisinin izlenmesi, çarpıntı, terleme, kilo değişikliği şikayetlerinde', 'Usually taken in the morning; tell the doctor about thyroid medications and biotin supplements, as they affect the result', 'Obično se uzima ujutru; o uzimanju lijekova za štitnu žlijezdu i dodataka sa biotinom treba obavijestiti ljekara, jer utiču na nalaz', 'Обично се узима ујутру; о узимању лијекова за штитну жлијезду и додатака са биотином треба обавијестити љекара, јер утичу на налаз', 'Обычно сдаётся утром; о приёме препаратов для щитовидной железы и добавок с биотином нужно сообщить врачу, так как они влияют на результат', 'Wird meist morgens abgenommen; Schilddrüsenmedikamente und Biotinpräparate sollten dem Arzt mitgeteilt werden, da sie den Wert beeinflussen', 'Genellikle sabah alınır; tiroid ilaçları ve biotin içeren takviyeler sonucu etkilediğinden hekime bildirilmelidir', 'Changes may be related to thyroid function, the amount of carrier proteins in the blood, pregnancy, or certain medications. A doctor interprets it together with TSH', 'Promjene mogu biti povezane sa radom štitne žlijezde, količinom bjelančevina nosača u krvi, trudnoćom ili uzimanjem određenih lijekova. Tumačenje daje ljekar zajedno sa TSH', 'Промјене могу бити повезане са радом штитне жлијезде, количином бјеланчевина носача у крви, трудноћом или узимањем одређених лијекова. Тумачење даје љекар заједно са TSH', 'Изменения могут быть связаны с работой щитовидной железы, количеством белков-переносчиков в крови, беременностью или приёмом некоторых препаратов. Интерпретирует врач вместе с TSH', 'Veränderungen können mit der Schilddrüsenfunktion, der Menge der Transporteiweiße im Blut, einer Schwangerschaft oder der Einnahme bestimmter Medikamente zusammenhängen. Die Interpretation erfolgt durch den Arzt zusammen mit TSH', 'Değişiklikler tiroid bezinin çalışmasıyla, kandaki taşıyıcı protein miktarıyla, gebelikle veya bazı ilaçların kullanımıyla ilişkili olabilir. Hekim sonucu TSH ile birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 't4'), 'Blood test for total thyroxine, the main thyroid hormone including the protein-bound fraction', 'Analiza krvi na ukupni tiroksin, osnovni hormon štitne žlijezde zajedno sa dijelom vezanim za bjelančevine', 'Анализа крви на укупни тироксин, основни хормон штитне жлијезде заједно са дијелом везаним за бјеланчевине', 'Анализ крови на общий тироксин, основной гормон щитовидной железы вместе со связанной с белками частью', 'Bluttest auf Gesamt-Thyroxin, das wichtigste Schilddrüsenhormon einschließlich des eiweißgebundenen Anteils', 'Proteine bağlı kısım dahil olmak üzere temel tiroid hormonu olan total tiroksin için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing thyroid function together with TSH, monitoring replacement therapy, in case of fatigue, feeling cold, changes in weight or skin condition', 'Procjena rada štitne žlijezde zajedno sa TSH, kontrola nadomjesne terapije, kod umora, osjećaja hladnoće, promjene tjelesne težine i stanja kože', 'Процјена рада штитне жлијезде заједно са TSH, контрола надомјесне терапије, код умора, осјећаја хладноће, промјене тјелесне тежине и стања коже', 'Оценка работы щитовидной железы вместе с TSH, контроль заместительной терапии, при утомляемости, зябкости, изменениях веса и состояния кожи', 'Beurteilung der Schilddrüsenfunktion zusammen mit TSH, Kontrolle einer Substitutionstherapie, bei Müdigkeit, Frösteln, Gewichts- und Hautveränderungen', 'TSH ile birlikte tiroid işlevinin değerlendirilmesi, replasman tedavisinin izlenmesi, yorgunluk, üşüme, kilo ve cilt değişikliklerinde', 'Usually taken in the morning; if thyroid medications are prescribed, the doctor specifies how to take them on the day of the test', 'Obično se uzima ujutru; ako su propisani lijekovi za štitnu žlijezdu, način njihovog uzimanja na dan analize određuje ljekar', 'Обично се узима ујутру; ако су прописани лијекови за штитну жлијезду, начин њиховог узимања на дан анализе одређује љекар', 'Обычно сдаётся утром; если назначены препараты щитовидной железы, порядок их приёма в день анализа уточняет врач', 'Wird meist morgens abgenommen; bei verordneten Schilddrüsenmedikamenten legt der Arzt fest, wie sie am Untersuchungstag einzunehmen sind', 'Genellikle sabah alınır; tiroid ilacı kullanılıyorsa test günü nasıl alınacağını hekim belirler', 'Changes may be related to thyroid function, the amount of carrier proteins, pregnancy, or certain medications. A doctor evaluates it together with TSH and the clinical picture', 'Promjene mogu biti povezane sa radom štitne žlijezde, količinom bjelančevina nosača, trudnoćom ili uzimanjem određenih lijekova. Ljekar procjenjuje nalaz zajedno sa TSH i kliničkom slikom', 'Промјене могу бити повезане са радом штитне жлијезде, количином бјеланчевина носача, трудноћом или узимањем одређених лијекова. Љекар процјењује налаз заједно са TSH и клиничком сликом', 'Изменения могут быть связаны с работой щитовидной железы, количеством белков-переносчиков, беременностью или приёмом некоторых препаратов. Оценивает врач вместе с TSH и клинической картиной', 'Veränderungen können mit der Schilddrüsenfunktion, der Menge der Transporteiweiße, einer Schwangerschaft oder der Einnahme bestimmter Medikamente zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit TSH und dem klinischen Bild', 'Değişiklikler tiroid bezinin çalışmasıyla, taşıyıcı protein miktarıyla, gebelikle veya bazı ilaçların kullanımıyla ilişkili olabilir. Hekim sonucu TSH ve klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'thyroglobulin'), 'Blood test for a protein produced only by thyroid tissue', 'Analiza krvi na bjelančevinu koju stvara isključivo tkivo štitne žlijezde', 'Анализа крви на бјеланчевину коју ствара искључиво ткиво штитне жлијезде', 'Анализ крови на белок, который вырабатывает только ткань щитовидной железы', 'Bluttest auf ein Eiweiß, das ausschließlich von Schilddrüsengewebe gebildet wird', 'Yalnızca tiroid dokusu tarafından üretilen bir protein için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Follow-up after treatment of thyroid conditions, examination as prescribed by an endocrinologist, usually together with thyroglobulin antibodies', 'Praćenje poslije liječenja oboljenja štitne žlijezde, pregled po uputu endokrinologa, obično zajedno sa antitijelima na tireoglobulin', 'Праћење послије лијечења обољења штитне жлијезде, преглед по упуту ендокринолога, обично заједно са антитијелима на тиреоглобулин', 'Наблюдение после лечения заболеваний щитовидной железы, обследование по назначению эндокринолога, обычно вместе с антителами к тиреоглобулину', 'Verlaufskontrolle nach Behandlung von Schilddrüsenerkrankungen, Untersuchung nach Anordnung des Endokrinologen, meist zusammen mit Thyreoglobulin-Antikörpern', 'Tiroid hastalıklarının tedavisi sonrası izlem, endokrinoloji uzmanının isteğiyle inceleme, genellikle tiroglobulin antikorlarıyla birlikte', 'No special preparation is usually required; it is important to tell the doctor about previous thyroid surgery and the medications you take', 'Posebna priprema obično nije potrebna; važno je obavijestiti ljekara o ranijim operacijama štitne žlijezde i o lijekovima koji se uzimaju', 'Посебна припрема обично није потребна; важно је обавијестити љекара о ранијим операцијама штитне жлијезде и о лијековима који се узимају', 'Специальной подготовки обычно не требуется; важно сообщить врачу о перенесённых операциях на щитовидной железе и о принимаемых препаратах', 'In der Regel ist keine besondere Vorbereitung nötig; wichtig ist, dem Arzt frühere Schilddrüsenoperationen und eingenommene Medikamente mitzuteilen', 'Genellikle özel hazırlık gerekmez; geçirilmiş tiroid ameliyatlarının ve kullanılan ilaçların hekime bildirilmesi önemlidir', 'The result depends on the amount of remaining thyroid tissue, the presence of antibodies, and the laboratory method. It is therefore assessed only by a doctor, over time and together with other investigations', 'Nalaz zavisi od količine preostalog tkiva žlijezde, prisustva antitijela i metode laboratorije. Zato ga procjenjuje samo ljekar, kroz praćenje i zajedno sa drugim ispitivanjima', 'Налаз зависи од количине преосталог ткива жлијезде, присуства антитијела и методе лабораторије. Зато га процјењује само љекар, кроз праћење и заједно са другим испитивањима', 'Результат зависит от объёма сохранившейся ткани железы, наличия антител и метода лаборатории. Поэтому его оценивает только врач, в динамике и вместе с другими исследованиями', 'Der Wert hängt von der Menge des verbliebenen Schilddrüsengewebes, dem Vorhandensein von Antikörpern und der Labormethode ab. Er wird deshalb nur vom Arzt im Verlauf und zusammen mit anderen Untersuchungen beurteilt', 'Sonuç, kalan tiroid dokusunun miktarına, antikorların varlığına ve laboratuvarın yöntemine bağlıdır. Bu nedenle yalnızca hekim tarafından, zaman içindeki seyir ve diğer incelemelerle birlikte değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = '17-hydroxyprogesterone'), 'Blood test for an intermediate substance formed during the production of adrenal hormones', 'Analiza krvi na međuproizvod koji nastaje pri stvaranju hormona nadbubrežnih žlijezda', 'Анализа крви на међупроизвод који настаје при стварању хормона надбубрежних жлијезда', 'Анализ крови на промежуточное вещество, которое образуется при выработке гормонов надпочечников', 'Bluttest auf eine Zwischenstufe, die bei der Bildung der Nebennierenhormone entsteht', 'Böbreküstü bezi hormonlarının üretimi sırasında oluşan bir ara madde için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Work-up of excess hair growth, cycle disorders and difficulties conceiving, clarifying causes of hormonal changes in children and adults', 'Ispitivanje kod pojačane maljavosti, poremećaja ciklusa i teškoća sa začećem, razjašnjenje uzroka hormonskih promjena kod djece i odraslih', 'Испитивање код појачане маљавости, поремећаја циклуса и тешкоћа са зачећем, разјашњење узрока хормонских промјена код дјеце и одраслих', 'Обследование при избыточном оволосении, нарушениях цикла и трудностях с зачатием, уточнение причин гормональных изменений у детей и взрослых', 'Abklärung von vermehrter Behaarung, Zyklusstörungen und unerfülltem Kinderwunsch, Klärung von Ursachen hormoneller Veränderungen bei Kindern und Erwachsenen', 'Aşırı tüylenme, döngü bozuklukları ve gebe kalma güçlüğünün araştırılması, çocuk ve erişkinlerde hormonal değişikliklerin nedenlerinin netleştirilmesi', 'The sample is usually taken in the morning, as the level changes during the day; in women of reproductive age the doctor sets the cycle day for the test', 'Uzorak se obično uzima ujutru, jer se nivo mijenja tokom dana; kod žena reproduktivne dobi dan ciklusa za analizu određuje ljekar', 'Узорак се обично узима ујутру, јер се ниво мијења током дана; код жена репродуктивне доби дан циклуса за анализу одређује љекар', 'Забор обычно проводится утром, так как уровень меняется в течение суток; у женщин репродуктивного возраста день цикла для сдачи назначает врач', 'Die Entnahme erfolgt meist morgens, da der Wert im Tagesverlauf schwankt; bei Frauen im gebärfähigen Alter legt der Arzt den Zyklustag fest', 'Düzey gün içinde değiştiğinden örnek genellikle sabah alınır; üreme çağındaki kadınlarda test günü hekim tarafından belirlenir', 'Changes may be related to adrenal function, the time of sampling, or the cycle phase. A doctor evaluates the result together with the other hormones and may repeat the test', 'Promjene mogu biti povezane sa radom nadbubrežnih žlijezda, vremenom uzimanja uzorka ili fazom ciklusa. Nalaz procjenjuje ljekar zajedno sa ostalim hormonima, a po potrebi se analiza ponavlja', 'Промјене могу бити повезане са радом надбубрежних жлијезда, временом узимања узорка или фазом циклуса. Налаз процјењује љекар заједно са осталим хормонима, а по потреби се анализа понавља', 'Изменения могут быть связаны с работой надпочечников, временем забора или фазой цикла. Результат оценивает врач вместе с остальными гормонами, при необходимости анализ повторяют', 'Veränderungen können mit der Nebennierenfunktion, dem Zeitpunkt der Entnahme oder der Zyklusphase zusammenhängen. Der Arzt beurteilt den Befund zusammen mit den übrigen Hormonen und wiederholt die Untersuchung bei Bedarf', 'Değişiklikler böbreküstü bezlerinin çalışmasıyla, örneğin alındığı saatle veya döngü evresiyle ilişkili olabilir. Hekim sonucu diğer hormonlarla birlikte değerlendirir, gerektiğinde test tekrarlanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'acth'), 'Blood test for the pituitary hormone that controls cortisol production by the adrenal glands', 'Analiza krvi na hormon hipofize koji upravlja stvaranjem kortizola u nadbubrežnim žlijezdama', 'Анализа крви на хормон хипофизе који управља стварањем кортизола у надбубрежним жлијездама', 'Анализ крови на гормон гипофиза, который управляет выработкой кортизола надпочечниками', 'Bluttest auf das Hypophysenhormon, das die Cortisolbildung in den Nebennieren steuert', 'Böbreküstü bezlerinde kortizol üretimini yöneten hipofiz hormonu için kan testi', 'Venous blood draw into a separate tube, the sample is delivered to the laboratory quickly and under the required storage conditions', 'Uzimanje venske krvi u posebnu epruvetu, uzorak se brzo dostavlja u laboratoriju uz propisane uslove čuvanja', 'Узимање венске крви у посебну епрувету, узорак се брзо доставља у лабораторију уз прописане услове чувања', 'Забор венозной крови в отдельную пробирку, пробу быстро доставляют в лабораторию с соблюдением условий хранения', 'Entnahme von venösem Blut in ein eigenes Röhrchen, die Probe wird rasch und unter den erforderlichen Lagerbedingungen ins Labor gebracht', 'Ayrı bir tüpe venöz kan alınır, örnek gerekli saklama koşullarında hızlıca laboratuvara ulaştırılır', 'Assessing pituitary and adrenal function, clarifying causes of changes in cortisol levels, follow-up as prescribed by an endocrinologist', 'Procjena rada hipofize i nadbubrežnih žlijezda, razjašnjenje uzroka promjena nivoa kortizola, praćenje po uputu endokrinologa', 'Процјена рада хипофизе и надбубрежних жлијезда, разјашњење узрока промјена нивоа кортизола, праћење по упуту ендокринолога', 'Оценка работы гипофиза и надпочечников, уточнение причин изменений уровня кортизола, наблюдение по назначению эндокринолога', 'Beurteilung der Hypophysen- und Nebennierenfunktion, Klärung von Ursachen veränderter Cortisolwerte, Verlaufskontrolle nach Anordnung des Endokrinologen', 'Hipofiz ve böbreküstü bezlerinin işlevinin değerlendirilmesi, kortizol düzeyindeki değişikliklerin nedeninin netleştirilmesi, endokrinoloji uzmanının isteğiyle izlem', 'The sample is taken in the morning at specific hours, as the level changes during the day; it is advisable to avoid stress and heavy physical exertion the day before', 'Uzorak se uzima ujutru u određeno vrijeme, jer se nivo mijenja tokom dana; dan ranije je poželjno izbjegavati stres i teže fizičko naprezanje', 'Узорак се узима ујутру у одређено вријеме, јер се ниво мијења током дана; дан раније је пожељно избјегавати стрес и теже физичко напрезање', 'Забор проводится утром в определённые часы, так как уровень меняется в течение суток; накануне желательно избегать стресса и тяжёлой физической нагрузки', 'Die Entnahme erfolgt morgens zu bestimmten Zeiten, da der Wert im Tagesverlauf schwankt; am Vortag sollten Stress und starke körperliche Belastung möglichst vermieden werden', 'Düzey gün içinde değiştiğinden örnek sabah belirli saatlerde alınır; bir önceki gün stresten ve ağır fiziksel efordan kaçınılması önerilir', 'Changes may be related to pituitary or adrenal function, the time of sampling, stress, or the use of hormonal medications. A doctor evaluates it together with the cortisol level', 'Promjene mogu biti povezane sa radom hipofize ili nadbubrežnih žlijezda, vremenom uzimanja uzorka, stresom ili uzimanjem hormonske terapije. Ljekar procjenjuje nalaz zajedno sa nivoom kortizola', 'Промјене могу бити повезане са радом хипофизе или надбубрежних жлијезда, временом узимања узорка, стресом или узимањем хормонске терапије. Љекар процјењује налаз заједно са нивоом кортизола', 'Изменения могут быть связаны с работой гипофиза или надпочечников, временем забора, стрессом или приёмом гормональных препаратов. Оценивает врач вместе с уровнем кортизола', 'Veränderungen können mit der Funktion von Hypophyse oder Nebennieren, dem Entnahmezeitpunkt, Stress oder der Einnahme hormoneller Medikamente zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit dem Cortisolwert', 'Değişiklikler hipofiz veya böbreküstü bezlerinin çalışmasıyla, örneğin alındığı saatle, stresle veya hormon ilacı kullanımıyla ilişkili olabilir. Hekim sonucu kortizol düzeyiyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'androstenedione'), 'Blood test for a precursor of male and female sex hormones', 'Analiza krvi na preteču muških i ženskih polnih hormona', 'Анализа крви на претечу мушких и женских полних хормона', 'Анализ крови на предшественник мужских и женских половых гормонов', 'Bluttest auf eine Vorstufe der männlichen und weiblichen Sexualhormone', 'Erkek ve kadın cinsiyet hormonlarının bir öncülü için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Work-up of excess hair growth, acne, cycle disorders, identifying the source of excess androgens together with other hormones', 'Ispitivanje kod pojačane maljavosti, akni, poremećaja ciklusa, utvrđivanje izvora viška androgena zajedno sa drugim hormonima', 'Испитивање код појачане маљавости, акни, поремећаја циклуса, утврђивање извора вишка андрогена заједно са другим хормонима', 'Обследование при избыточном оволосении, акне, нарушениях цикла, уточнение источника избытка андрогенов вместе с другими гормонами', 'Abklärung von vermehrter Behaarung, Akne, Zyklusstörungen, Eingrenzung der Quelle überschüssiger Androgene zusammen mit anderen Hormonen', 'Aşırı tüylenme, akne, döngü bozukluklarının incelenmesi, diğer hormonlarla birlikte fazla androjenin kaynağının belirlenmesi', 'Usually taken in the morning, as the level changes during the day; in women of reproductive age the doctor sets the cycle day for the test', 'Obično se uzima ujutru, jer se nivo mijenja tokom dana; kod žena reproduktivne dobi dan ciklusa za analizu određuje ljekar', 'Обично се узима ујутру, јер се ниво мијења током дана; код жена репродуктивне доби дан циклуса за анализу одређује љекар', 'Обычно сдаётся утром, так как уровень меняется в течение суток; у женщин репродуктивного возраста день цикла для сдачи определяет врач', 'Wird meist morgens abgenommen, da der Wert im Tagesverlauf schwankt; bei Frauen im gebärfähigen Alter legt der Arzt den Zyklustag fest', 'Düzey gün içinde değiştiğinden genellikle sabah alınır; üreme çağındaki kadınlarda test günü hekim tarafından belirlenir', 'Changes may be related to ovarian or adrenal function, the cycle phase, or the use of hormonal medications. A doctor evaluates it together with the other values', 'Promjene mogu biti povezane sa radom jajnika ili nadbubrežnih žlijezda, fazom ciklusa ili uzimanjem hormonske terapije. Ljekar procjenjuje nalaz zajedno sa ostalim pokazateljima', 'Промјене могу бити повезане са радом јајника или надбубрежних жлијезда, фазом циклуса или узимањем хормонске терапије. Љекар процјењује налаз заједно са осталим показатељима', 'Изменения могут быть связаны с работой яичников или надпочечников, фазой цикла или приёмом гормональных препаратов. Оценивает врач вместе с остальными показателями', 'Veränderungen können mit der Funktion der Eierstöcke oder Nebennieren, der Zyklusphase oder der Einnahme hormoneller Medikamente zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit den übrigen Werten', 'Değişiklikler yumurtalıkların veya böbreküstü bezlerinin çalışmasıyla, döngü evresiyle ya da hormon ilacı kullanımıyla ilişkili olabilir. Hekim sonucu diğer göstergelerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'free-testosterone'), 'Blood test for the fraction of testosterone not bound to proteins and available to tissues', 'Analiza krvi na dio testosterona koji nije vezan za bjelančevine i dostupan je tkivima', 'Анализа крви на дио тестостерона који није везан за бјеланчевине и доступан је ткивима', 'Анализ крови на не связанную с белками часть тестостерона, доступную тканям', 'Bluttest auf den nicht an Eiweiße gebundenen Anteil des Testosterons, der den Geweben zur Verfügung steht', 'Testosteronun proteine bağlı olmayan ve dokular için kullanılabilir olan kısmı için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Clarifying hormonal status when total testosterone is not informative enough, work-up of reduced libido and fatigue in men, of excess hair growth and cycle disorders in women', 'Razjašnjenje hormonskog statusa kada ukupni testosteron nije dovoljno informativan, ispitivanje kod smanjenog libida i umora kod muškaraca, kod pojačane maljavosti i poremećaja ciklusa kod žena', 'Разјашњење хормонског статуса када укупни тестостерон није довољно информативан, испитивање код смањеног либида и умора код мушкараца, код појачане маљавости и поремећаја циклуса код жена', 'Уточнение гормонального статуса, когда общий тестостерон малоинформативен, обследование при снижении либидо и утомляемости у мужчин, при избыточном оволосении и нарушениях цикла у женщин', 'Klärung des Hormonstatus, wenn das Gesamttestosteron wenig aussagt, Abklärung von vermindertem Libido und Müdigkeit bei Männern, von vermehrter Behaarung und Zyklusstörungen bei Frauen', 'Total testosteronun yeterli bilgi vermediği durumlarda hormonal durumun netleştirilmesi, erkeklerde libido azalması ve yorgunluğun, kadınlarda aşırı tüylenme ve döngü bozukluklarının incelenmesi', 'Usually taken in the morning, as the level changes during the day; often together with total testosterone and SHBG', 'Obično se uzima ujutru, jer se nivo mijenja tokom dana; često zajedno sa ukupnim testosteronom i SHBG', 'Обично се узима ујутру, јер се ниво мијења током дана; често заједно са укупним тестостероном и SHBG', 'Обычно сдаётся утром, так как уровень меняется в течение суток; часто вместе с общим тестостероном и SHBG', 'Wird meist morgens abgenommen, da der Wert im Tagesverlauf schwankt; oft zusammen mit Gesamttestosteron und SHBG', 'Düzey gün içinde değiştiğinden genellikle sabah alınır; çoğu zaman total testosteron ve SHBG ile birlikte', 'Changes may be related to hormonal status, age, body weight, the amount of carrier proteins, or certain medications. A doctor interprets it together with total testosterone', 'Promjene mogu biti povezane sa hormonskim statusom, godinama, tjelesnom težinom, količinom bjelančevina nosača ili uzimanjem određenih lijekova. Tumačenje daje ljekar zajedno sa ukupnim testosteronom', 'Промјене могу бити повезане са хормонским статусом, годинама, тјелесном тежином, количином бјеланчевина носача или узимањем одређених лијекова. Тумачење даје љекар заједно са укупним тестостероном', 'Изменения могут быть связаны с гормональным фоном, возрастом, весом, количеством белков-переносчиков или приёмом некоторых препаратов. Интерпретирует врач вместе с общим тестостероном', 'Veränderungen können mit dem Hormonstatus, dem Alter, dem Körpergewicht, der Menge der Transporteiweiße oder der Einnahme bestimmter Medikamente zusammenhängen. Die Interpretation erfolgt durch den Arzt zusammen mit dem Gesamttestosteron', 'Değişiklikler hormonal durumla, yaşla, kiloyla, taşıyıcı protein miktarıyla veya bazı ilaçların kullanımıyla ilişkili olabilir. Hekim sonucu total testosteronla birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'pth'), 'Blood test for the parathyroid hormone that regulates calcium and phosphorus metabolism', 'Analiza krvi na hormon paratireoidnih žlijezda koji reguliše metabolizam kalcijuma i fosfora', 'Анализа крви на хормон паратиреоидних жлијезда који регулише метаболизам калцијума и фосфора', 'Анализ крови на гормон паращитовидных желёз, который регулирует обмен кальция и фосфора', 'Bluttest auf das Hormon der Nebenschilddrüsen, das den Kalzium- und Phosphatstoffwechsel steuert', 'Kalsiyum ve fosfor metabolizmasını düzenleyen paratiroid bezi hormonu için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Work-up of changes in calcium levels, osteoporosis, kidney stones, chronic kidney disease, follow-up as prescribed by an endocrinologist', 'Ispitivanje kod promjena nivoa kalcijuma, kod osteoporoze, kamena u bubregu, kod hronične bolesti bubrega, praćenje po uputu endokrinologa', 'Испитивање код промјена нивоа калцијума, код остеопорозе, камена у бубрегу, код хроничне болести бубрега, праћење по упуту ендокринолога', 'Обследование при изменениях уровня кальция, при остеопорозе, мочекаменной болезни, при хронической болезни почек, наблюдение по назначению эндокринолога', 'Abklärung veränderter Kalziumwerte, bei Osteoporose, Nierensteinen, chronischer Nierenerkrankung, Verlaufskontrolle nach Anordnung des Endokrinologen', 'Kalsiyum düzeyindeki değişikliklerin, osteoporozun, böbrek taşının, kronik böbrek hastalığının araştırılması, endokrinoloji uzmanının isteğiyle izlem', 'Usually taken in the morning, most often together with calcium and vitamin D; tell the doctor about calcium and vitamin D supplements you take', 'Obično se uzima ujutru, najčešće zajedno sa kalcijumom i vitaminom D; o uzimanju preparata kalcijuma i vitamina D treba obavijestiti ljekara', 'Обично се узима ујутру, најчешће заједно са калцијумом и витамином Д; о узимању препарата калцијума и витамина Д треба обавијестити љекара', 'Обычно сдаётся утром, чаще вместе с кальцием и витамином D; о приёме препаратов кальция и витамина D нужно сообщить врачу', 'Wird meist morgens abgenommen, häufig zusammen mit Kalzium und Vitamin D; die Einnahme von Kalzium- und Vitamin-D-Präparaten sollte dem Arzt mitgeteilt werden', 'Genellikle sabah, çoğunlukla kalsiyum ve D vitamini ile birlikte alınır; kalsiyum ve D vitamini takviyesi kullanılıyorsa hekime bildirilmelidir', 'Changes may be related to parathyroid function, calcium and vitamin D levels, or kidney function. A doctor evaluates it only together with these values', 'Promjene mogu biti povezane sa radom paratireoidnih žlijezda, nivoom kalcijuma i vitamina D, funkcijom bubrega. Ljekar nalaz procjenjuje isključivo zajedno sa tim pokazateljima', 'Промјене могу бити повезане са радом паратиреоидних жлијезда, нивоом калцијума и витамина Д, функцијом бубрега. Љекар налаз процјењује искључиво заједно са тим показатељима', 'Изменения могут быть связаны с работой паращитовидных желёз, уровнем кальция и витамина D, функцией почек. Оценивает врач только вместе с этими показателями', 'Veränderungen können mit der Funktion der Nebenschilddrüsen, dem Kalzium- und Vitamin-D-Spiegel oder der Nierenfunktion zusammenhängen. Der Arzt beurteilt den Befund nur zusammen mit diesen Werten', 'Değişiklikler paratiroid bezlerinin çalışmasıyla, kalsiyum ve D vitamini düzeyiyle veya böbrek fonksiyonuyla ilişkili olabilir. Hekim sonucu yalnızca bu göstergelerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'free-estriol'), 'Blood test for a hormone produced during pregnancy by the placenta and the fetus', 'Analiza krvi na hormon koji tokom trudnoće stvaraju posteljica i organizam ploda', 'Анализа крви на хормон који током трудноће стварају постељица и организам плода', 'Анализ крови на гормон, который во время беременности вырабатывается плацентой и организмом плода', 'Bluttest auf ein Hormon, das während der Schwangerschaft von der Plazenta und vom Kind gebildet wird', 'Gebelik sırasında plasenta ve bebek tarafından üretilen bir hormon için kan testi', 'Venous blood draw from the pregnant woman, takes a few minutes', 'Uzimanje venske krvi trudnice, traje nekoliko minuta', 'Узимање венске крви труднице, траје неколико минута', 'Забор венозной крови у беременной, занимает несколько минут', 'Entnahme von venösem Blut bei der Schwangeren, dauert einige Minuten', 'Gebeden venöz kan alımı, birkaç dakika sürer', 'Part of the biochemical screening in the second trimester of pregnancy, ordered by a doctor at a specific stage of pregnancy', 'Dio je biohemijskog skrininga u drugom tromjesečju trudnoće, a ljekar ga određuje u tačno određenoj nedjelji trudnoće', 'Дио је биохемијског скрининга у другом тромјесечју трудноће, а љекар га одређује у тачно одређеној недјељи трудноће', 'Входит в биохимический скрининг второго триместра беременности, назначается врачом в определённый срок беременности', 'Teil des biochemischen Screenings im zweiten Schwangerschaftsdrittel, wird vom Arzt zu einem bestimmten Schwangerschaftszeitpunkt angeordnet', 'Gebeliğin ikinci üç ayındaki biyokimyasal taramanın bir parçasıdır, hekim tarafından gebeliğin belirli bir döneminde istenir', 'No special preparation is usually required; it is important to know the exact stage of pregnancy, which the doctor confirms by ultrasound', 'Posebna priprema obično nije potrebna; važno je tačno znati gestacijsku starost, koju ljekar potvrđuje ultrazvukom', 'Посебна припрема обично није потребна; важно је тачно знати гестацијску старост, коју љекар потврђује ултразвуком', 'Специальной подготовки обычно не требуется; важно точно знать срок беременности, его подтверждает врач по данным УЗИ', 'In der Regel ist keine besondere Vorbereitung nötig; wichtig ist das genaue Schwangerschaftsalter, das der Arzt per Ultraschall bestätigt', 'Genellikle özel hazırlık gerekmez; gebelik haftasının tam olarak bilinmesi önemlidir, bunu hekim ultrasonla doğrular', 'The value on its own has no independent meaning. It is assessed by a doctor only together with the other screening values and the stage of pregnancy', 'Pojedinačan pokazatelj sam za sebe nema značaj. Procjenjuje ga ljekar isključivo zajedno sa ostalim pokazateljima skrininga i gestacijskom starošću', 'Појединачан показатељ сам за себе нема значај. Процјењује га љекар искључиво заједно са осталим показатељима скрининга и гестацијском старошћу', 'Отдельный показатель самостоятельного значения не имеет. Он оценивается врачом только в комплексе с остальными показателями скрининга и сроком беременности', 'Der einzelne Wert hat für sich genommen keine Aussagekraft. Er wird vom Arzt ausschließlich zusammen mit den übrigen Screeningwerten und dem Schwangerschaftsalter beurteilt', 'Tek bir gösterge başlı başına anlam taşımaz. Hekim bunu yalnızca taramanın diğer göstergeleri ve gebelik haftasıyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ck'), 'Blood test for a muscle enzyme that reflects the condition of skeletal muscle and heart muscle', 'Analiza krvi na enzim mišićnog tkiva koji odražava stanje skeletnih mišića i srčanog mišića', 'Анализа крви на ензим мишићног ткива који одражава стање скелетних мишића и срчаног мишића', 'Анализ крови на фермент мышечной ткани, отражающий состояние скелетных мышц и сердечной мышцы', 'Bluttest auf ein Muskelenzym, das den Zustand der Skelett- und Herzmuskulatur widerspiegelt', 'İskelet kaslarının ve kalp kasının durumunu yansıtan kas enzimini ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Muscle pain and weakness, suspected muscle damage, monitoring during treatment with medications that affect muscles, assessment after injuries', 'Bolovi u mišićima i mišićna slabost, sumnja na oštećenje mišića, praćenje tokom uzimanja lijekova koji djeluju na mišiće, procjena stanja nakon povreda', 'Болови у мишићима и мишићна слабост, сумња на оштећење мишића, праћење током узимања лијекова који дјелују на мишиће, процјена стања након повреда', 'Боли в мышцах и мышечная слабость, подозрение на повреждение мышц, контроль при приёме препаратов, влияющих на мышцы, оценка состояния после травм', 'Muskelschmerzen und Muskelschwäche, Verdacht auf Muskelschädigung, Kontrolle unter Medikamenten, die die Muskulatur beeinflussen, Beurteilung nach Verletzungen', 'Kas ağrısı ve güçsüzlük, kas hasarı şüphesi, kasları etkileyen ilaçların kullanımı sırasında izlem, yaralanma sonrası değerlendirme', 'Taken in the morning, preferably fasting; avoid intense physical exercise for a day before and discuss intramuscular injections with the doctor', 'Uzima se ujutru, po mogućnosti natašte; dan ranije izbjegavati intenzivan fizički napor, a intramuskularne injekcije dogovoriti sa ljekarom', 'Узима се ујутру, по могућности наташте; дан раније избјегавати интензиван физички напор, а интрамускуларне ињекције договорити са љекаром', 'Сдают утром, желательно натощак; за сутки исключить интенсивную физическую нагрузку, внутримышечные инъекции обсудить с врачом', 'Morgens, möglichst nüchtern; am Vortag intensive körperliche Belastung meiden, intramuskuläre Injektionen mit dem Arzt abstimmen', 'Sabah, tercihen aç karnına alınır; bir gün önce yoğun fiziksel egzersizden kaçınılmalı, kas içi enjeksiyonlar hekimle görüşülmelidir', 'An increase may be related to skeletal muscle damage after exertion or injury and, less often, to the heart muscle or to certain medications. The result is assessed by a doctor together with other indicators', 'Povišene vrijednosti mogu biti povezane sa oštećenjem skeletnih mišića poslije napora ili povrede, rjeđe sa srčanim mišićem ili uzimanjem pojedinih lijekova. Nalaz procjenjuje ljekar zajedno sa ostalim pokazateljima', 'Повишене вриједности могу бити повезане са оштећењем скелетних мишића послије напора или повреде, рјеђе са срчаним мишићем или узимањем појединих лијекова. Налаз процјењује љекар заједно са осталим показатељима', 'Повышение может быть связано с повреждением скелетных мышц после нагрузки или травмы, реже — с сердечной мышцей или приёмом некоторых препаратов. Результат оценивает врач вместе с другими показателями', 'Erhöhte Werte können mit einer Schädigung der Skelettmuskulatur nach Belastung oder Verletzung, seltener mit dem Herzmuskel oder bestimmten Medikamenten zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit weiteren Werten', 'Yüksek değerler efor veya yaralanma sonrası iskelet kası hasarıyla, daha seyrek olarak kalp kasıyla ya da bazı ilaçlarla ilişkili olabilir. Sonucu diğer göstergelerle birlikte hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ck-mb'), 'Blood test for the cardiac fraction of creatine kinase', 'Analiza krvi na srčanu frakciju kreatin kinaze', 'Анализа крви на срчану фракцију креатин киназе', 'Анализ крови на сердечную фракцию креатинкиназы', 'Bluttest auf die herzspezifische Fraktion der Kreatinkinase', 'Kreatin kinazın kalp kaynaklı fraksiyonunu ölçen kan testi', 'Venous blood draw, repeated after a few hours if needed', 'Uzimanje venske krvi, po potrebi ponovo nakon nekoliko sati', 'Узимање венске крви, по потреби поново након неколико сати', 'Забор венозной крови, при необходимости повторно через несколько часов', 'Entnahme von venösem Blut, bei Bedarf Wiederholung nach einigen Stunden', 'Venöz kan alımı, gerekirse birkaç saat sonra tekrarlanır', 'Chest pain, suspected damage to the heart muscle, follow-up after cardiac procedures', 'Bol u grudima, sumnja na oštećenje srčanog mišića, praćenje poslije kardioloških zahvata', 'Бол у грудима, сумња на оштећење срчаног мишића, праћење послије кардиолошких захвата', 'Боль в грудной клетке, подозрение на повреждение сердечной мышцы, наблюдение после кардиологических вмешательств', 'Brustschmerzen, Verdacht auf eine Schädigung des Herzmuskels, Verlaufskontrolle nach kardiologischen Eingriffen', 'Göğüs ağrısı, kalp kası hasarı şüphesi, kardiyolojik girişimler sonrası izlem', 'No special preparation is required; in urgent situations blood is taken at any time, for a planned test in the morning on an empty stomach', 'Posebna priprema nije potrebna; u hitnim situacijama krv se uzima u bilo koje doba, a planirano ujutru natašte', 'Посебна припрема није потребна; у хитним ситуацијама крв се узима у било које доба, а планирано ујутру наташте', 'Специальной подготовки не требуется; в неотложной ситуации кровь берут в любое время, при плановой сдаче — утром натощак', 'Keine besondere Vorbereitung nötig; in Notfallsituationen jederzeit, bei geplanter Untersuchung morgens nüchtern', 'Özel hazırlık gerekmez; acil durumlarda her saatte, planlı testte sabah aç karnına alınır', 'An increase may be related to damage to the heart muscle and also to skeletal muscle. The result is assessed by a doctor together with the ECG and other tests', 'Povišene vrijednosti mogu biti povezane sa oštećenjem srčanog mišića, ali i skeletnih mišića. Nalaz tumači ljekar zajedno sa EKG-om i drugim analizama', 'Повишене вриједности могу бити повезане са оштећењем срчаног мишића, али и скелетних мишића. Налаз тумачи љекар заједно са ЕКГ-ом и другим анализама', 'Повышение может быть связано с повреждением сердечной мышцы, а также скелетных мышц. Результат оценивает врач вместе с ЭКГ и другими анализами', 'Erhöhte Werte können mit einer Schädigung des Herzmuskels, aber auch der Skelettmuskulatur zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit EKG und weiteren Untersuchungen', 'Yüksek değerler kalp kası hasarıyla, ayrıca iskelet kası hasarıyla ilişkili olabilir. Sonucu EKG ve diğer tetkiklerle birlikte hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'creatinine-clearance'), 'Calculated measure of kidney filtration based on creatinine in blood and in a 24-hour urine sample', 'Izračunati pokazatelj filtracione funkcije bubrega na osnovu kreatinina u krvi i u 24-časovnom urinu', 'Израчунати показатељ филтрационе функције бубрега на основу креатинина у крви и у 24-часовном урину', 'Расчётный показатель фильтрационной работы почек по креатинину в крови и суточной моче', 'Berechneter Wert der Nierenfiltration aus dem Kreatinin in Blut und 24-Stunden-Urin', 'Kandaki ve 24 saatlik idrardaki kreatinine dayanarak hesaplanan böbrek filtrasyon göstergesi', 'Urine is collected over 24 hours and a single venous blood sample is taken during the same period', 'Urin se sakuplja tokom 24 sata, a u istom periodu se jednom uzima venska krv', 'Урин се сакупља током 24 сата, а у истом периоду се једном узима венска крв', 'Сбор мочи за 24 часа и однократный забор венозной крови в тот же период', 'Urin wird über 24 Stunden gesammelt, im selben Zeitraum erfolgt eine einmalige venöse Blutentnahme', 'İdrar 24 saat boyunca biriktirilir, aynı dönemde bir kez venöz kan alınır', 'Assessment of kidney function, follow-up in chronic kidney disease, choosing and monitoring medications cleared by the kidneys, work-up before certain procedures', 'Procjena rada bubrega, praćenje kod hronične bubrežne bolesti, uvođenje i kontrola terapije lijekovima koji se izlučuju preko bubrega, priprema za pojedine zahvate', 'Процјена рада бубрега, праћење код хроничне бубрежне болести, увођење и контрола терапије лијековима који се излучују преко бубрега, припрема за поједине захвате', 'Оценка функции почек, наблюдение при хронической болезни почек, подбор и контроль терапии препаратами, которые выводятся почками, обследование перед некоторыми процедурами', 'Beurteilung der Nierenfunktion, Verlaufskontrolle bei chronischer Nierenerkrankung, Auswahl und Kontrolle von Medikamenten, die über die Nieren ausgeschieden werden, Abklärung vor bestimmten Eingriffen', 'Böbrek fonksiyonunun değerlendirilmesi, kronik böbrek hastalığında izlem, böbrekten atılan ilaçların seçimi ve takibi, bazı girişimler öncesi inceleme', 'Collect urine for exactly 24 hours into the container provided by the laboratory, excluding the first morning portion; avoid heavy exercise on the collection day and report your height and weight', 'Urin se sakuplja tačno 24 sata u posudu koju daje laboratorija, prva jutarnja porcija se ne sakuplja; na dan sakupljanja izbjegavati veliki fizički napor i prijaviti visinu i tjelesnu težinu', 'Урин се сакупља тачно 24 сата у посуду коју даје лабораторија, прва јутарња порција се не сакупља; на дан сакупљања избјегавати велики физички напор и пријавити висину и тјелесну тежину', 'Мочу собирают ровно сутки в выданную лабораторией ёмкость, первую утреннюю порцию не включают; в день сбора избегать больших нагрузок, сообщить рост и вес', 'Urin genau 24 Stunden im Gefäß des Labors sammeln, die erste Morgenportion nicht mitsammeln; am Sammeltag starke körperliche Belastung meiden und Größe sowie Gewicht angeben', 'İdrar, laboratuvarın verdiği kapta tam 24 saat biriktirilir, ilk sabah idrarı alınmaz; toplama günü ağır egzersizden kaçınılmalı, boy ve kilo bildirilmelidir', 'Deviations may be related to reduced filtration capacity of the kidneys, dehydration, dietary habits or incomplete urine collection. Interpretation is done by a doctor', 'Odstupanja mogu biti povezana sa smanjenom filtracionom sposobnošću bubrega, dehidratacijom, navikama u ishrani ili nepotpunim sakupljanjem urina. Nalaz tumači ljekar', 'Одступања могу бити повезана са смањеном филтрационом способношћу бубрега, дехидратацијом, навикама у исхрани или непотпуним сакупљањем урина. Налаз тумачи љекар', 'Отклонения могут быть связаны со снижением фильтрационной способности почек, обезвоживанием, особенностями питания или неполным сбором мочи. Интерпретирует результат врач', 'Abweichungen können mit einer verminderten Filtrationsleistung der Nieren, Flüssigkeitsmangel, Ernährungsgewohnheiten oder unvollständiger Urinsammlung zusammenhängen. Die Interpretation erfolgt durch den Arzt', 'Sapmalar böbreklerin filtrasyon kapasitesinin azalmasıyla, sıvı kaybıyla, beslenme alışkanlıklarıyla veya idrarın eksik toplanmasıyla ilişkili olabilir. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ldh'), 'Blood test for an enzyme present in almost all tissues that enters the blood when cells are damaged', 'Analiza krvi na enzim koji se nalazi u gotovo svim tkivima i dospijeva u krv pri oštećenju ćelija', 'Анализа крви на ензим који се налази у готово свим ткивима и доспијева у крв при оштећењу ћелија', 'Анализ крови на фермент, который есть почти во всех тканях и попадает в кровь при повреждении клеток', 'Bluttest auf ein Enzym, das in fast allen Geweben vorkommt und bei Zellschädigung ins Blut gelangt', 'Neredeyse tüm dokularda bulunan ve hücreler zarar gördüğünde kana geçen bir enzimi ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'General assessment of tissue damage, work-up of anemia, follow-up in some liver and blood disorders, addition to other biochemical tests', 'Opšta procjena oštećenja tkiva, ispitivanje anemije, praćenje kod pojedinih oboljenja jetre i krvi, dopuna drugim biohemijskim analizama', 'Општа процјена оштећења ткива, испитивање анемије, праћење код појединих обољења јетре и крви, допуна другим биохемијским анализама', 'Общая оценка повреждения тканей, обследование при анемии, наблюдение при некоторых заболеваниях печени и крови, дополнение к другим биохимическим анализам', 'Allgemeine Beurteilung von Gewebeschäden, Abklärung einer Anämie, Verlaufskontrolle bei bestimmten Leber- und Bluterkrankungen, Ergänzung zu anderen biochemischen Werten', 'Doku hasarının genel değerlendirilmesi, anemi araştırması, bazı karaciğer ve kan hastalıklarında izlem, diğer biyokimya testlerine ek olarak', 'Taken in the morning on an empty stomach; avoid intense physical exercise the day before', 'Uzima se ujutru natašte; dan ranije izbjegavati intenzivan fizički napor', 'Узима се ујутру наташте; дан раније избјегавати интензиван физички напор', 'Сдают утром натощак; накануне избегать интенсивной физической нагрузки', 'Morgens nüchtern; am Vortag intensive körperliche Belastung meiden', 'Sabah aç karnına alınır; bir önceki gün yoğun fiziksel egzersizden kaçınılmalıdır', 'An increase may be related to cell breakdown in very different tissues — blood, liver, muscle — and does not point to a particular organ. The cause is clarified by a doctor with additional tests', 'Povišene vrijednosti mogu biti povezane sa razgradnjom ćelija u različitim tkivima — krvi, jetri, mišićima — i ne upućuju na konkretan organ. Uzrok ljekar utvrđuje dodatnim ispitivanjima', 'Повишене вриједности могу бити повезане са разградњом ћелија у различитим ткивима — крви, јетри, мишићима — и не упућују на конкретан орган. Узрок љекар утврђује додатним испитивањима', 'Повышение может быть связано с разрушением клеток самых разных тканей — крови, печени, мышц — и не указывает на конкретный орган. Причину уточняет врач дополнительными исследованиями', 'Erhöhte Werte können mit dem Zerfall von Zellen ganz unterschiedlicher Gewebe — Blut, Leber, Muskulatur — zusammenhängen und weisen nicht auf ein bestimmtes Organ hin. Die Ursache klärt der Arzt mit weiteren Untersuchungen', 'Yüksek değerler kan, karaciğer, kas gibi çok farklı dokularda hücre yıkımıyla ilişkili olabilir ve tek bir organa işaret etmez. Nedenini hekim ek tetkiklerle belirler')
