INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urea-clearance'), 'Measure of urea removal by the kidneys, calculated from blood and a 24-hour urine sample', 'Pokazatelj izlučivanja ureje preko bubrega, izračunat iz krvi i 24-časovnog urina', 'Показатељ излучивања уреје преко бубрега, израчунат из крви и 24-часовног урина', 'Показатель выведения мочевины почками, рассчитываемый по крови и суточной моче', 'Kennwert der Harnstoffausscheidung durch die Nieren, berechnet aus Blut und 24-Stunden-Urin', 'Kan ve 24 saatlik idrardan hesaplanan, böbreklerin üreyi atma yeteneğini gösteren ölçüm', 'Urine collection over 24 hours together with a venous blood draw', 'Sakupljanje urina tokom 24 sata uz uzimanje venske krvi', 'Сакупљање урина током 24 сата уз узимање венске крви', 'Сбор мочи за 24 часа вместе с забором венозной крови', 'Urinsammlung über 24 Stunden zusammen mit einer venösen Blutentnahme', '24 saat boyunca idrar biriktirilmesi ve venöz kan alınması', 'Additional assessment of kidney excretory function, follow-up in chronic kidney disease, clarifying the results of other kidney tests', 'Dodatna procjena izlučne funkcije bubrega, praćenje kod hronične bubrežne bolesti, pojašnjenje nalaza drugih bubrežnih proba', 'Додатна процјена излучне функције бубрега, праћење код хроничне бубрежне болести, појашњење налаза других бубрежних проба', 'Дополнительная оценка выделительной функции почек, наблюдение при хронической болезни почек, уточнение результатов других почечных проб', 'Ergänzende Beurteilung der Ausscheidungsfunktion der Nieren, Verlaufskontrolle bei chronischer Nierenerkrankung, Präzisierung anderer Nierenwerte', 'Böbreklerin atım işlevinin ek değerlendirmesi, kronik böbrek hastalığında izlem, diğer böbrek testlerinin sonuçlarının netleştirilmesi', 'Collect all urine for 24 hours into the laboratory container and keep it cool; discuss fluid intake and diet during the collection days with your doctor', 'Sav urin se 24 sata sakuplja u posudu iz laboratorije i čuva na hladnom; unos tečnosti i ishranu tokom dana sakupljanja dogovoriti sa ljekarom', 'Сав урин се 24 сата сакупља у посуду из лабораторије и чува на хладном; унос течности и исхрану током дана сакупљања договорити са љекаром', 'Сутки собирать всю мочу в ёмкость из лаборатории и хранить её в прохладном месте; питьевой режим и питание в дни сбора обсудить с врачом', 'Den gesamten Urin 24 Stunden im Laborgefäß sammeln und kühl aufbewahren; Trinkmenge und Ernährung an den Sammeltagen mit dem Arzt besprechen', 'Tüm idrar 24 saat boyunca laboratuvar kabında biriktirilir ve serin yerde saklanır; toplama günlerindeki sıvı alımı ve beslenme hekimle görüşülmelidir', 'Deviations may be related to kidney function, the amount of fluid consumed, the protein content of the diet or errors in urine collection. A doctor assesses the value together with creatinine', 'Odstupanja mogu biti povezana sa radom bubrega, količinom unijete tečnosti, količinom bjelančevina u ishrani ili greškama pri sakupljanju urina. Ljekar nalaz procjenjuje zajedno sa kreatininom', 'Одступања могу бити повезана са радом бубрега, количином унијете течности, количином бјеланчевина у исхрани или грешкама при сакупљању урина. Љекар налаз процјењује заједно са креатинином', 'Отклонения могут быть связаны с работой почек, объёмом выпитой жидкости, количеством белка в питании или ошибками сбора мочи. Врач оценивает показатель вместе с креатинином', 'Abweichungen können mit der Nierenfunktion, der Trinkmenge, dem Eiweißanteil der Ernährung oder Fehlern bei der Urinsammlung zusammenhängen. Der Arzt beurteilt den Wert zusammen mit dem Kreatinin', 'Sapmalar böbrek fonksiyonu, alınan sıvı miktarı, beslenmedeki protein miktarı veya idrar toplamadaki hatalarla ilişkili olabilir. Hekim sonucu kreatininle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'direct-bilirubin'), 'Blood test for the bilirubin fraction already processed (conjugated) by the liver', 'Analiza krvi na frakciju bilirubina koju je jetra već vezala (konjugovala)', 'Анализа крви на фракцију билирубина коју је јетра већ везала (коњуговала)', 'Анализ крови на связанную печенью фракцию билирубина', 'Bluttest auf den Bilirubinanteil, den die Leber bereits umgewandelt (konjugiert) hat', 'Karaciğer tarafından bağlanmış (konjuge) bilirubin fraksiyonunu ölçen kan testi', 'Venous blood draw, usually on an empty stomach', 'Uzimanje venske krvi, obično natašte', 'Узимање венске крви, обично наташте', 'Забор венозной крови, обычно натощак', 'Entnahme von venösem Blut, in der Regel nüchtern', 'Genellikle aç karnına venöz kan alımı', 'Clarifying the cause of jaundice, assessment of liver function and bile flow, follow-up in liver and biliary tract disease', 'Utvrđivanje uzroka žutice, procjena rada jetre i otjecanja žuči, praćenje oboljenja jetre i žučnih puteva', 'Утврђивање узрока жутице, процјена рада јетре и отјецања жучи, праћење обољења јетре и жучних путева', 'Уточнение причины желтухи, оценка работы печени и оттока жёлчи, наблюдение при заболеваниях печени и жёлчных путей', 'Abklärung der Ursache einer Gelbsucht, Beurteilung der Leberfunktion und des Galleabflusses, Verlaufskontrolle bei Leber- und Gallenwegserkrankungen', 'Sarılığın nedeninin araştırılması, karaciğer işlevi ve safra akışının değerlendirilmesi, karaciğer ve safra yolu hastalıklarında izlem', 'Fasting for 4–8 hours, only water allowed; avoid fatty food and alcohol the day before', 'Natašte 4–8 sati, dozvoljena samo voda; dan ranije izbjegavati masnu hranu i alkohol', 'Наташте 4–8 сати, дозвољена само вода; дан раније избјегавати масну храну и алкохол', 'Натощак 4–8 часов, разрешена только вода; накануне избегать жирной пищи и алкоголя', '4–8 Stunden nüchtern, nur Wasser erlaubt; am Vortag fettreiche Speisen und Alkohol meiden', '4–8 saat aç karnına, sadece su içilebilir; bir önceki gün yağlı yiyecek ve alkolden kaçınılmalıdır', 'An increase is more often related to impaired bile flow or to liver cell function, whereas total bilirubin changes for other reasons as well. A doctor interprets the ratio of the fractions', 'Povišene vrijednosti češće su povezane sa otežanim otjecanjem žuči ili radom ćelija jetre, dok se ukupni bilirubin mijenja i iz drugih razloga. Odnos frakcija tumači ljekar', 'Повишене вриједности чешће су повезане са отежаним отјецањем жучи или радом ћелија јетре, док се укупни билирубин мијења и из других разлога. Однос фракција тумачи љекар', 'Повышение чаще связано с затруднённым оттоком жёлчи или работой клеток печени, тогда как общий билирубин меняется и по другим причинам. Соотношение фракций трактует врач', 'Erhöhte Werte hängen häufiger mit einem gestörten Galleabfluss oder der Funktion der Leberzellen zusammen, während sich das Gesamtbilirubin auch aus anderen Gründen ändert. Das Verhältnis der Fraktionen beurteilt der Arzt', 'Yüksek değerler daha çok safra akışının bozulması veya karaciğer hücrelerinin işleviyle ilişkilidir, total bilirubin ise başka nedenlerle de değişir. Fraksiyonların oranını hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'tibc'), 'Blood test showing how much iron the serum proteins are able to bind in total', 'Analiza krvi koja pokazuje koliko gvožđa bjelančevine seruma ukupno mogu da vežu', 'Анализа крви која показује колико гвожђа бјеланчевине серума укупно могу да вежу', 'Анализ крови, показывающий, сколько железа способны связать белки сыворотки в целом', 'Bluttest, der zeigt, wie viel Eisen die Serumproteine insgesamt binden können', 'Serum proteinlerinin toplamda ne kadar demir bağlayabildiğini gösteren kan testi', 'Venous blood draw, usually together with iron and other markers of iron metabolism', 'Uzimanje venske krvi, obično zajedno sa gvožđem i drugim pokazateljima metabolizma gvožđa', 'Узимање венске крви, обично заједно са гвожђем и другим показатељима метаболизма гвожђа', 'Забор венозной крови, обычно вместе с железом и другими показателями обмена железа', 'Entnahme von venösem Blut, meist zusammen mit Eisen und weiteren Eisenwerten', 'Genellikle demir ve diğer demir metabolizması göstergeleriyle birlikte venöz kan alımı', 'Work-up of anemia, assessment of iron stores and iron metabolism, monitoring during iron supplementation', 'Ispitivanje anemije, procjena zaliha i prometa gvožđa, kontrola tokom terapije preparatima gvožđa', 'Испитивање анемије, процјена залиха и промета гвожђа, контрола током терапије препаратима гвожђа', 'Обследование при анемии, оценка запасов и обмена железа, контроль на фоне терапии препаратами железа', 'Abklärung einer Anämie, Beurteilung von Eisenspeichern und Eisenstoffwechsel, Kontrolle unter Eisentherapie', 'Anemi araştırması, demir depolarının ve metabolizmasının değerlendirilmesi, demir tedavisi sırasında izlem', 'Strictly fasting in the morning; iron supplements the day before only after agreement with the doctor', 'Strogo natašte, ujutru; preparate gvožđa dan ranije uzimati samo uz dogovor sa ljekarom', 'Строго наташте, ујутру; препарате гвожђа дан раније узимати само уз договор са љекаром', 'Строго натощак утром; препараты железа накануне принимать только по согласованию с врачом', 'Streng nüchtern am Morgen; Eisenpräparate am Vortag nur nach Rücksprache mit dem Arzt', 'Sabah, kesinlikle aç karnına; demir preparatları bir gün önce yalnızca hekimle görüşerek alınmalıdır', 'Changes may be related to iron deficiency or excess, inflammation, diet or pregnancy. The value is interpreted only together with iron and ferritin, and the conclusion is drawn by a doctor', 'Promjene mogu biti povezane sa nedostatkom ili viškom gvožđa, upalom, ishranom ili trudnoćom. Vrijednost se tumači samo zajedno sa gvožđem i feritinom, a zaključak donosi ljekar', 'Промјене могу бити повезане са недостатком или вишком гвожђа, упалом, исхраном или трудноћом. Вриједност се тумачи само заједно са гвожђем и феритином, а закључак доноси љекар', 'Изменения могут быть связаны с дефицитом или избытком железа, воспалением, питанием или беременностью. Показатель трактуется только вместе с железом и ферритином, вывод делает врач', 'Veränderungen können mit Eisenmangel oder Eisenüberschuss, Entzündungen, Ernährung oder einer Schwangerschaft zusammenhängen. Der Wert wird nur zusammen mit Eisen und Ferritin beurteilt, die Schlussfolgerung zieht der Arzt', 'Değişiklikler demir eksikliği veya fazlalığı, iltihap, beslenme ya da gebelikle ilişkili olabilir. Değer yalnızca demir ve ferritinle birlikte yorumlanır, sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'uibc'), 'Blood test for the part of the iron-binding capacity that is not yet occupied by iron', 'Analiza krvi na onaj dio kapaciteta vezivanja gvožđa koji još nije popunjen gvožđem', 'Анализа крви на онај дио капацитета везивања гвожђа који још није попуњен гвожђем', 'Анализ крови на ту часть железосвязывающей способности, которая ещё не занята железом', 'Bluttest auf den Teil der Eisenbindungskapazität, der noch nicht mit Eisen besetzt ist', 'Demir bağlama kapasitesinin henüz demirle dolmamış bölümünü ölçen kan testi', 'Venous blood draw, usually together with serum iron; adding the two gives the total capacity', 'Uzimanje venske krvi, obično uz gvožđe u serumu; sabiranjem se dobija ukupni kapacitet', 'Узимање венске крви, обично уз гвожђе у серуму; сабирањем се добија укупни капацитет', 'Забор венозной крови, обычно вместе с сывороточным железом; сумма двух показателей даёт общую способность', 'Entnahme von venösem Blut, meist zusammen mit dem Serumeisen; die Summe ergibt die totale Kapazität', 'Genellikle serum demiriyle birlikte venöz kan alımı; ikisinin toplamı total kapasiteyi verir', 'Clarifying iron metabolism in anemia, calculating transferrin saturation, monitoring during iron treatment', 'Pojašnjenje prometa gvožđa kod anemije, izračunavanje zasićenja transferina, praćenje tokom terapije gvožđem', 'Појашњење промета гвожђа код анемије, израчунавање засићења трансферина, праћење током терапије гвожђем', 'Уточнение обмена железа при анемии, расчёт насыщения трансферрина, наблюдение при лечении препаратами железа', 'Genauere Abklärung des Eisenstoffwechsels bei Anämie, Berechnung der Transferrinsättigung, Kontrolle unter Eisentherapie', 'Anemide demir metabolizmasının netleştirilmesi, transferrin satürasyonunun hesaplanması, demir tedavisi sırasında izlem', 'Taken in the morning on an empty stomach; tell the doctor in advance about iron supplements and vitamins', 'Uzima se ujutru natašte; o uzimanju preparata gvožđa i vitamina unaprijed obavijestiti ljekara', 'Узима се ујутру наташте; о узимању препарата гвожђа и витамина унапријед обавијестити љекара', 'Сдают утром натощак; о приёме препаратов железа и витаминов сообщить врачу заранее', 'Morgens nüchtern; die Einnahme von Eisenpräparaten und Vitaminen dem Arzt vorab mitteilen', 'Sabah aç karnına alınır; demir preparatı ve vitamin kullanımı hekime önceden bildirilmelidir', 'Deviations may be related to iron deficiency or excess in the body and to inflammatory processes. The value is not interpreted apart from iron and total iron-binding capacity, and this is done by a doctor', 'Odstupanja mogu biti povezana sa nedostatkom ili viškom gvožđa u organizmu i sa upalnim procesima. Vrijednost se ne tumači odvojeno od gvožđa i ukupnog kapaciteta vezivanja, to radi ljekar', 'Одступања могу бити повезана са недостатком или вишком гвожђа у организму и са упалним процесима. Вриједност се не тумачи одвојено од гвожђа и укупног капацитета везивања, то ради љекар', 'Отклонения могут быть связаны с недостатком или избытком железа в организме и с воспалительными процессами. Отдельно от железа и общей железосвязывающей способности показатель не трактуется, этим занимается врач', 'Abweichungen können mit Eisenmangel oder Eisenüberschuss sowie mit Entzündungsprozessen zusammenhängen. Der Wert wird nicht getrennt von Eisen und totaler Eisenbindungskapazität beurteilt, das übernimmt der Arzt', 'Sapmalar vücutta demir eksikliği veya fazlalığıyla ve iltihabi süreçlerle ilişkili olabilir. Değer, demir ve total demir bağlama kapasitesinden ayrı yorumlanmaz, bunu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'albumin'), 'Blood test for the main plasma protein produced by the liver', 'Analiza krvi na glavnu bjelančevinu plazme koju stvara jetra', 'Анализа крви на главну бјеланчевину плазме коју ствара јетра', 'Анализ крови на основной белок плазмы, который вырабатывает печень', 'Bluttest auf das wichtigste Plasmaprotein, das die Leber bildet', 'Karaciğerin ürettiği başlıca plazma proteinini ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessment of liver and kidney function, work-up of edema, monitoring nutrition and general status in chronic disease, preparation for surgery', 'Procjena rada jetre i bubrega, ispitivanje otoka, praćenje uhranjenosti i opšteg stanja kod hroničnih bolesti, priprema za operaciju', 'Процјена рада јетре и бубрега, испитивање отока, праћење ухрањености и општег стања код хроничних болести, припрема за операцију', 'Оценка работы печени и почек, обследование при отёках, наблюдение за питанием и общим состоянием при хронических болезнях, подготовка к операции', 'Beurteilung der Leber- und Nierenfunktion, Abklärung von Ödemen, Kontrolle von Ernährungszustand und Allgemeinbefinden bei chronischen Erkrankungen, Vorbereitung auf Operationen', 'Karaciğer ve böbrek işlevinin değerlendirilmesi, ödem araştırması, kronik hastalıklarda beslenme ve genel durumun izlenmesi, ameliyat öncesi hazırlık', 'Taken in the morning on an empty stomach; dehydration and a long tourniquet time distort the result, so keep your usual fluid intake the day before', 'Uzima se ujutru natašte; dehidratacija i dugo stajanje poveske mijenjaju nalaz, pa dan ranije zadržati uobičajen unos tečnosti', 'Узима се ујутру наташте; дехидратација и дуго стајање повеске мијењају налаз, па дан раније задржати уобичајен унос течности', 'Сдают утром натощак; обезвоживание и долгое наложение жгута искажают результат, поэтому накануне важен обычный питьевой режим', 'Morgens nüchtern; Flüssigkeitsmangel und langes Stauen verfälschen den Wert, daher am Vortag die gewohnte Trinkmenge beibehalten', 'Sabah aç karnına alınır; sıvı kaybı ve turnikenin uzun süre bağlı kalması sonucu bozar, bu nedenle bir önceki gün olağan sıvı alımı sürdürülmelidir', 'Changes may be related to liver function, protein loss through the kidneys or bowel, nutrition, inflammation or the amount of fluid in the body. The cause is determined by a doctor', 'Promjene mogu biti povezane sa radom jetre, gubitkom bjelančevina preko bubrega ili crijeva, ishranom, upalom ili količinom tečnosti u organizmu. Uzrok utvrđuje ljekar', 'Промјене могу бити повезане са радом јетре, губитком бјеланчевина преко бубрега или цријева, исхраном, упалом или количином течности у организму. Узрок утврђује љекар', 'Изменения могут быть связаны с работой печени, потерями белка через почки или кишечник, питанием, воспалением или количеством жидкости в организме. Причину определяет врач', 'Veränderungen können mit der Leberfunktion, Eiweißverlusten über Nieren oder Darm, der Ernährung, Entzündungen oder dem Flüssigkeitshaushalt zusammenhängen. Die Ursache bestimmt der Arzt', 'Değişiklikler karaciğer işlevi, böbrek veya bağırsak yoluyla protein kaybı, beslenme, iltihap ya da vücuttaki sıvı miktarıyla ilişkili olabilir. Nedeni hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'amylase'), 'Blood test for the enzyme that breaks down carbohydrates, produced by the pancreas and the salivary glands', 'Analiza krvi na enzim koji razgrađuje ugljene hidrate, a stvaraju ga pankreas i pljuvačne žlijezde', 'Анализа крви на ензим који разграђује угљене хидрате, а стварају га панкреас и пљувачне жлијезде', 'Анализ крови на фермент, расщепляющий углеводы; его вырабатывают поджелудочная и слюнные железы', 'Bluttest auf das kohlenhydratspaltende Enzym, das von Bauchspeicheldrüse und Speicheldrüsen gebildet wird', 'Pankreas ve tükürük bezlerinin ürettiği, karbonhidratları parçalayan enzimi ölçen kan testi', 'Venous blood draw; when needed the enzyme is also measured in urine', 'Uzimanje venske krvi; po potrebi se enzim određuje i u urinu', 'Узимање венске крви; по потреби се ензим одређује и у урину', 'Забор венозной крови; при необходимости фермент определяют и в моче', 'Entnahme von venösem Blut; bei Bedarf wird das Enzym auch im Urin bestimmt', 'Venöz kan alımı; gerektiğinde enzim idrarda da ölçülür', 'Pain in the upper abdomen, suspected inflammation of the pancreas, follow-up in salivary gland disorders', 'Bol u gornjem dijelu trbuha, sumnja na upalu pankreasa, praćenje oboljenja pljuvačnih žlijezda', 'Бол у горњем дијелу трбуха, сумња на упалу панкреаса, праћење обољења пљувачних жлијезда', 'Боль в верхней части живота, подозрение на воспаление поджелудочной железы, наблюдение при заболеваниях слюнных желёз', 'Schmerzen im Oberbauch, Verdacht auf eine Entzündung der Bauchspeicheldrüse, Verlaufskontrolle bei Speicheldrüsenerkrankungen', 'Üst karın ağrısı, pankreas iltihabı şüphesi, tükürük bezi hastalıklarında izlem', 'Fasting for 8–12 hours, only water allowed; avoid alcohol and fatty food the day before', 'Natašte 8–12 sati, dozvoljena samo voda; dan ranije izbjegavati alkohol i masnu hranu', 'Наташте 8–12 сати, дозвољена само вода; дан раније избјегавати алкохол и масну храну', 'Натощак 8–12 часов, разрешена только вода; накануне исключить алкоголь и жирную пищу', '8–12 Stunden nüchtern, nur Wasser erlaubt; am Vortag Alkohol und fettreiche Speisen meiden', '8–12 saat aç karnına, sadece su içilebilir; bir önceki gün alkol ve yağlı yiyeceklerden kaçınılmalıdır', 'An increase may be related to the pancreas, the salivary glands or other processes in the abdomen. What lies behind the change is determined by a doctor from the symptoms and additional tests', 'Povišene vrijednosti mogu biti povezane sa pankreasom, pljuvačnim žlijezdama ili drugim zbivanjima u trbuhu. Šta stoji iza promjene, utvrđuje ljekar na osnovu tegoba i dodatnih pretraga', 'Повишене вриједности могу бити повезане са панкреасом, пљувачним жлијездама или другим збивањима у трбуху. Шта стоји иза промјене, утврђује љекар на основу тегоба и додатних претрага', 'Повышение может быть связано с поджелудочной железой, слюнными железами или другими процессами в брюшной полости. Что стоит за изменением, определяет врач по жалобам и дополнительным исследованиям', 'Erhöhte Werte können mit der Bauchspeicheldrüse, den Speicheldrüsen oder anderen Vorgängen im Bauchraum zusammenhängen. Was dahintersteckt, klärt der Arzt anhand der Beschwerden und weiterer Untersuchungen', 'Yüksek değerler pankreas, tükürük bezleri veya karın içindeki başka süreçlerle ilişkili olabilir. Değişikliğin nedenini hekim şikayetlere ve ek tetkiklere göre belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'homocysteine'), 'Blood test for an amino acid whose metabolism depends on B vitamins', 'Analiza krvi na aminokiselinu čiji metabolizam zavisi od vitamina B grupe', 'Анализа крви на аминокиселину чији метаболизам зависи од витамина Б групе', 'Анализ крови на аминокислоту, обмен которой зависит от витаминов группы B', 'Bluttest auf eine Aminosäure, deren Stoffwechsel von B-Vitaminen abhängt', 'Metabolizması B grubu vitaminlere bağlı olan bir amino asidi ölçen kan testi', 'Venous blood draw; the sample must reach the laboratory quickly, so the appointment is arranged around laboratory hours', 'Uzimanje venske krvi; uzorak brzo mora stići u laboratoriju, pa se termin usklađuje sa njenim radnim vremenom', 'Узимање венске крви; узорак брзо мора стићи у лабораторију, па се термин усклађује са њеним радним временом', 'Забор венозной крови; пробирку быстро доставляют в лабораторию, поэтому время сдачи согласуют с её графиком', 'Entnahme von venösem Blut; die Probe muss rasch ins Labor, daher richtet sich der Termin nach den Laborzeiten', 'Venöz kan alımı; örnek laboratuvara hızla ulaşmalıdır, bu nedenle randevu laboratuvarın çalışma saatlerine göre ayarlanır', 'Assessment of cardiovascular risk factors, work-up of vitamin B12 and folate deficiency, follow-up in certain inherited metabolic disorders, pregnancy planning', 'Procjena kardiovaskularnih faktora rizika, ispitivanje nedostatka vitamina B12 i folne kiseline, praćenje pojedinih nasljednih poremećaja metabolizma, planiranje trudnoće', 'Процјена кардиоваскуларних фактора ризика, испитивање недостатка витамина Б12 и фолне киселине, праћење појединих насљедних поремећаја метаболизма, планирање трудноће', 'Оценка сердечно-сосудистых факторов риска, обследование при дефиците витамина B12 и фолиевой кислоты, наблюдение при некоторых наследственных нарушениях обмена, планирование беременности', 'Beurteilung kardiovaskulärer Risikofaktoren, Abklärung eines Vitamin-B12- oder Folsäuremangels, Verlaufskontrolle bei bestimmten angeborenen Stoffwechselstörungen, Planung einer Schwangerschaft', 'Kalp ve damar risk etkenlerinin değerlendirilmesi, B12 vitamini ve folik asit eksikliğinin araştırılması, bazı kalıtsal metabolizma bozukluklarında izlem, gebelik planlaması', 'Strictly fasting for 10–12 hours, only water allowed; tell the doctor about any B-vitamin supplements', 'Strogo natašte 10–12 sati, dozvoljena samo voda; o uzimanju vitamina B grupe obavijestiti ljekara', 'Строго наташте 10–12 сати, дозвољена само вода; о узимању витамина Б групе обавијестити љекара', 'Строго натощак 10–12 часов, разрешена только вода; о приёме витаминов группы B сообщить врачу', 'Streng nüchtern 10–12 Stunden, nur Wasser erlaubt; die Einnahme von B-Vitaminen dem Arzt mitteilen', '10–12 saat kesinlikle aç karnına, sadece su içilebilir; B grubu vitamin kullanımı hekime bildirilmelidir', 'An increase may be related to a lack of vitamin B12, B6 or folate, kidney function, certain medications or inherited features of metabolism. The result is interpreted by a doctor', 'Povišene vrijednosti mogu biti povezane sa nedostatkom vitamina B12, B6 ili folne kiseline, radom bubrega, uzimanjem nekih lijekova ili nasljednim osobinama metabolizma. Nalaz tumači ljekar', 'Повишене вриједности могу бити повезане са недостатком витамина Б12, Б6 или фолне киселине, радом бубрега, узимањем неких лијекова или насљедним особинама метаболизма. Налаз тумачи љекар', 'Повышение может быть связано с недостатком витаминов B12, B6 или фолиевой кислоты, работой почек, приёмом некоторых препаратов или наследственными особенностями обмена. Трактует результат врач', 'Erhöhte Werte können mit einem Mangel an Vitamin B12, B6 oder Folsäure, der Nierenfunktion, bestimmten Medikamenten oder angeborenen Stoffwechselbesonderheiten zusammenhängen. Die Interpretation erfolgt durch den Arzt', 'Yüksek değerler B12, B6 vitamini veya folik asit eksikliği, böbrek işlevi, bazı ilaçlar ya da kalıtsal metabolizma özellikleriyle ilişkili olabilir. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'lipase'), 'Blood test for the pancreatic enzyme that breaks down fats', 'Analiza krvi na enzim pankreasa koji razgrađuje masti', 'Анализа крви на ензим панкреаса који разграђује масти', 'Анализ крови на фермент поджелудочной железы, расщепляющий жиры', 'Bluttest auf das fettspaltende Enzym der Bauchspeicheldrüse', 'Pankreasın yağları parçalayan enzimini ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Abdominal pain, suspected inflammation of the pancreas, follow-up in chronic pancreatic disease', 'Bol u trbuhu, sumnja na upalu pankreasa, praćenje hroničnih oboljenja pankreasa', 'Бол у трбуху, сумња на упалу панкреаса, праћење хроничних обољења панкреаса', 'Боль в животе, подозрение на воспаление поджелудочной железы, наблюдение при хронических заболеваниях поджелудочной железы', 'Bauchschmerzen, Verdacht auf eine Entzündung der Bauchspeicheldrüse, Verlaufskontrolle bei chronischen Erkrankungen der Bauchspeicheldrüse', 'Karın ağrısı, pankreas iltihabı şüphesi, kronik pankreas hastalıklarında izlem', 'Fasting for 8–12 hours, only water allowed; avoid alcohol and fatty food the day before', 'Natašte 8–12 sati, dozvoljena samo voda; dan ranije izbjegavati alkohol i masnu hranu', 'Наташте 8–12 сати, дозвољена само вода; дан раније избјегавати алкохол и масну храну', 'Натощак 8–12 часов, разрешена только вода; накануне исключить алкоголь и жирную пищу', '8–12 Stunden nüchtern, nur Wasser erlaubt; am Vortag Alkohol und fettreiche Speisen meiden', '8–12 saat aç karnına, sadece su içilebilir; bir önceki gün alkol ve yağlı yiyeceklerden kaçınılmalıdır', 'An increase is more often related to the pancreas and lasts longer than a change in amylase; kidney and bowel disease also have an effect. The result is assessed by a doctor', 'Povišene vrijednosti češće su povezane sa pankreasom i zadržavaju se duže nego promjena amilaze; uticaj imaju i bolesti bubrega i crijeva. Nalaz procjenjuje ljekar', 'Повишене вриједности чешће су повезане са панкреасом и задржавају се дуже него промјена амилазе; утицај имају и болести бубрега и цријева. Налаз процјењује љекар', 'Повышение чаще связано с поджелудочной железой и держится дольше, чем изменение амилазы; влияют также болезни почек и кишечника. Результат оценивает врач', 'Erhöhte Werte hängen häufiger mit der Bauchspeicheldrüse zusammen und halten länger an als eine Veränderung der Amylase; auch Nieren- und Darmerkrankungen wirken sich aus. Die Beurteilung erfolgt durch den Arzt', 'Yüksek değerler daha çok pankreasla ilişkilidir ve amilazdaki değişiklikten daha uzun sürer; böbrek ve bağırsak hastalıkları da etkili olur. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'transferrin'), 'Blood test for the protein that carries iron through the bloodstream', 'Analiza krvi na bjelančevinu koja prenosi gvožđe kroz krvotok', 'Анализа крви на бјеланчевину која преноси гвожђе кроз крвоток', 'Анализ крови на белок, который переносит железо по кровотоку', 'Bluttest auf das Protein, das Eisen im Blutkreislauf transportiert', 'Demiri kan dolaşımında taşıyan proteini ölçen kan testi', 'Venous blood draw, usually together with iron and ferritin', 'Uzimanje venske krvi, obično zajedno sa gvožđem i feritinom', 'Узимање венске крви, обично заједно са гвожђем и феритином', 'Забор венозной крови, обычно вместе с железом и ферритином', 'Entnahme von venösem Blut, meist zusammen mit Eisen und Ferritin', 'Genellikle demir ve ferritinle birlikte venöz kan alımı', 'Work-up of anemia, assessment of iron metabolism and stores, calculation of transferrin saturation, follow-up in liver disease', 'Ispitivanje anemije, procjena prometa i zaliha gvožđa, izračunavanje zasićenja transferina gvožđem, praćenje oboljenja jetre', 'Испитивање анемије, процјена промета и залиха гвожђа, израчунавање засићења трансферина гвожђем, праћење обољења јетре', 'Обследование при анемии, оценка обмена и запасов железа, расчёт насыщения трансферрина железом, наблюдение при заболеваниях печени', 'Abklärung einer Anämie, Beurteilung von Eisenstoffwechsel und Eisenspeichern, Berechnung der Transferrinsättigung, Verlaufskontrolle bei Lebererkrankungen', 'Anemi araştırması, demir metabolizmasının ve depolarının değerlendirilmesi, transferrin satürasyonunun hesaplanması, karaciğer hastalıklarında izlem', 'Taken in the morning on an empty stomach; iron supplements before the test only after agreement with the doctor', 'Uzima se ujutru natašte; preparate gvožđa prije analize uzimati samo uz dogovor sa ljekarom', 'Узима се ујутру наташте; препарате гвожђа прије анализе узимати само уз договор са љекаром', 'Сдают утром натощак; препараты железа перед анализом принимать только по согласованию с врачом', 'Morgens nüchtern; Eisenpräparate vor der Untersuchung nur nach Rücksprache mit dem Arzt', 'Sabah aç karnına alınır; demir preparatları test öncesinde yalnızca hekimle görüşerek alınmalıdır', 'Changes may be related to iron deficiency or excess, liver function, inflammation, pregnancy or hormonal medication. The doctor draws the conclusion from the whole group of values', 'Promjene mogu biti povezane sa nedostatkom ili viškom gvožđa, radom jetre, upalom, trudnoćom ili uzimanjem hormonskih lijekova. Zaključak ljekar donosi na osnovu cijele grupe pokazatelja', 'Промјене могу бити повезане са недостатком или вишком гвожђа, радом јетре, упалом, трудноћом или узимањем хормонских лијекова. Закључак љекар доноси на основу цијеле групе показатеља', 'Изменения могут быть связаны с дефицитом или избытком железа, работой печени, воспалением, беременностью или приёмом гормональных препаратов. Вывод врач делает по всей группе показателей', 'Veränderungen können mit Eisenmangel oder Eisenüberschuss, der Leberfunktion, Entzündungen, einer Schwangerschaft oder Hormonpräparaten zusammenhängen. Die Schlussfolgerung zieht der Arzt aus der gesamten Wertegruppe', 'Değişiklikler demir eksikliği veya fazlalığı, karaciğer işlevi, iltihap, gebelik ya da hormon ilaçlarıyla ilişkili olabilir. Hekim sonucu göstergelerin tümüne bakarak değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'osteocalcin'), 'Blood test for a protein produced by bone cells when new bone tissue is formed', 'Analiza krvi na bjelančevinu koju stvaraju koštane ćelije pri izgradnji novog koštanog tkiva', 'Анализа крви на бјеланчевину коју стварају коштане ћелије при изградњи новог коштаног ткива', 'Анализ крови на белок, который вырабатывают костные клетки при образовании новой костной ткани', 'Bluttest auf ein Protein, das Knochenzellen beim Aufbau neuen Knochengewebes bilden', 'Yeni kemik dokusu oluşurken kemik hücrelerinin ürettiği bir proteini ölçen kan testi', 'Venous blood draw in the morning, takes a few minutes', 'Uzimanje venske krvi ujutru, traje nekoliko minuta', 'Узимање венске крви ујутру, траје неколико минута', 'Забор венозной крови утром, занимает несколько минут', 'Entnahme von venösem Blut am Morgen, dauert einige Minuten', 'Sabah venöz kan alımı, birkaç dakika sürer', 'Assessment of bone turnover, follow-up in osteoporosis and monitoring of its treatment, work-up of calcium and vitamin D metabolism disorders', 'Procjena koštanog metabolizma, praćenje osteoporoze i kontrola njenog liječenja, ispitivanje poremećaja metabolizma kalcijuma i vitamina D', 'Процјена коштаног метаболизма, праћење остеопорозе и контрола њеног лијечења, испитивање поремећаја метаболизма калцијума и витамина Д', 'Оценка костного обмена, наблюдение при остеопорозе и контроль его лечения, обследование при нарушениях обмена кальция и витамина D', 'Beurteilung des Knochenstoffwechsels, Verlaufskontrolle bei Osteoporose und deren Therapiekontrolle, Abklärung von Störungen des Kalzium- und Vitamin-D-Stoffwechsels', 'Kemik metabolizmasının değerlendirilmesi, osteoporozda izlem ve tedavinin takibi, kalsiyum ve D vitamini metabolizması bozukluklarının araştırılması', 'Strictly in the morning on an empty stomach, as the value changes noticeably during the day; tell the doctor about bone medication and vitamin D supplements', 'Strogo ujutru natašte, jer se vrijednost primjetno mijenja tokom dana; o uzimanju lijekova za kosti i vitamina D obavijestiti ljekara', 'Строго ујутру наташте, јер се вриједност примјетно мијења током дана; о узимању лијекова за кости и витамина Д обавијестити љекара', 'Строго утром натощак, так как показатель заметно меняется в течение суток; о приёме препаратов для костей и витамина D сообщить врачу', 'Streng morgens nüchtern, da sich der Wert im Tagesverlauf deutlich ändert; Knochenmedikamente und Vitamin-D-Präparate dem Arzt mitteilen', 'Değer gün içinde belirgin şekilde değiştiğinden kesinlikle sabah aç karnına alınır; kemik ilaçları ve D vitamini kullanımı hekime bildirilmelidir', 'Changes may be related to the rate of bone renewal, parathyroid function, vitamin D metabolism or ongoing treatment. The doctor assesses the result together with densitometry and other tests', 'Promjene mogu biti povezane sa brzinom obnavljanja koštanog tkiva, radom paratireoidnih žlijezda, metabolizmom vitamina D ili terapijom koja se sprovodi. Nalaz ljekar procjenjuje zajedno sa denzitometrijom i drugim analizama', 'Промјене могу бити повезане са брзином обнављања коштаног ткива, радом паратиреоидних жлијезда, метаболизмом витамина Д или терапијом која се спроводи. Налаз љекар процјењује заједно са дензитометријом и другим анализама', 'Изменения могут быть связаны со скоростью обновления костной ткани, работой паращитовидных желёз, обменом витамина D или проводимой терапией. Результат врач оценивает вместе с денситометрией и другими анализами', 'Veränderungen können mit der Geschwindigkeit des Knochenumbaus, der Funktion der Nebenschilddrüsen, dem Vitamin-D-Stoffwechsel oder der laufenden Therapie zusammenhängen. Der Arzt beurteilt den Wert zusammen mit der Knochendichtemessung und weiteren Untersuchungen', 'Değişiklikler kemik yenilenme hızı, paratiroid bezlerinin çalışması, D vitamini metabolizması ya da uygulanan tedaviyle ilişkili olabilir. Hekim sonucu kemik yoğunluğu ölçümü ve diğer tetkiklerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ace'), 'Blood test for an enzyme involved in the regulation of blood pressure and water-salt balance', 'Analiza krvi na enzim koji učestvuje u regulaciji krvnog pritiska i ravnoteže vode i soli', 'Анализа крви на ензим који учествује у регулацији крвног притиска и равнотеже воде и соли', 'Анализ крови на фермент, участвующий в регуляции артериального давления и водно-солевого обмена', 'Bluttest auf ein Enzym, das an der Regulation von Blutdruck und Wasser-Salz-Haushalt beteiligt ist', 'Kan basıncının ve su-tuz dengesinin düzenlenmesinde rol alan bir enzimi ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Work-up and follow-up of granulomatous diseases, primarily sarcoidosis, assessment of disease activity over time', 'Ispitivanje i praćenje granulomatoznih bolesti, prije svega sarkoidoze, procjena aktivnosti procesa tokom vremena', 'Испитивање и праћење грануломатозних болести, прије свега саркоидозе, процјена активности процеса током времена', 'Обследование и наблюдение при гранулематозных заболеваниях, прежде всего саркоидозе, оценка активности процесса в динамике', 'Abklärung und Verlaufskontrolle granulomatöser Erkrankungen, vor allem der Sarkoidose, Beurteilung der Aktivität im Verlauf', 'Granülomatöz hastalıkların, başta sarkoidoz olmak üzere, araştırılması ve izlenmesi, hastalık aktivitesinin zaman içinde değerlendirilmesi', 'Taken in the morning on an empty stomach; always tell the doctor and the laboratory about ACE inhibitor medication — it changes the result', 'Uzima se ujutru natašte; o uzimanju lijekova iz grupe ACE inhibitora obavezno obavijestiti ljekara i laboratoriju, jer mijenjaju nalaz', 'Узима се ујутру наташте; о узимању лијекова из групе ACE инхибитора обавезно обавијестити љекара и лабораторију, јер мијењају налаз', 'Сдают утром натощак; о приёме препаратов из группы ингибиторов АПФ обязательно сообщить врачу и лаборатории — они меняют результат', 'Morgens nüchtern; die Einnahme von ACE-Hemmern unbedingt dem Arzt und dem Labor mitteilen, da sie den Wert verändern', 'Sabah aç karnına alınır; ACE inhibitörü grubu ilaç kullanımı sonucu değiştirdiğinden hekime ve laboratuvara mutlaka bildirilmelidir', 'Changes may be related to the activity of granulomatous inflammation, liver or thyroid disease, or medication. The value is not used apart from the clinical picture and is interpreted by a doctor', 'Promjene mogu biti povezane sa aktivnošću granulomatozne upale, oboljenjima jetre i štitne žlijezde ili uzimanjem lijekova. Vrijednost se ne koristi odvojeno od kliničke slike, tumači je ljekar', 'Промјене могу бити повезане са активношћу грануломатозне упале, обољењима јетре и штитне жлијезде или узимањем лијекова. Вриједност се не користи одвојено од клиничке слике, тумачи је љекар', 'Изменения могут быть связаны с активностью гранулематозного воспаления, заболеваниями печени и щитовидной железы или приёмом лекарств. Отдельно от клинической картины показатель не используется, трактует его врач', 'Veränderungen können mit der Aktivität einer granulomatösen Entzündung, Leber- oder Schilddrüsenerkrankungen oder Medikamenten zusammenhängen. Der Wert wird nicht losgelöst vom klinischen Bild verwendet und vom Arzt beurteilt', 'Değişiklikler granülomatöz iltihabın aktivitesi, karaciğer ve tiroid hastalıkları ya da ilaç kullanımıyla ilişkili olabilir. Değer klinik tablodan ayrı kullanılmaz, yorumu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'beta-crosslaps'), 'Blood test for a breakdown product of bone collagen — a marker of how fast bone is being resorbed', 'Analiza krvi na proizvod razgradnje koštanog kolagena — pokazatelj brzine razgradnje kosti', 'Анализа крви на производ разградње коштаног колагена — показатељ брзине разградње кости', 'Анализ крови на продукт распада костного коллагена — маркер скорости рассасывания кости', 'Bluttest auf ein Abbauprodukt des Knochenkollagens — ein Marker für die Geschwindigkeit des Knochenabbaus', 'Kemik kollajeninin yıkım ürününü, yani kemik yıkım hızının bir göstergesini ölçen kan testi', 'Venous blood draw strictly in the morning hours, as the value fluctuates markedly during the day', 'Uzimanje venske krvi isključivo u jutarnjim satima, jer vrijednost izrazito varira tokom dana', 'Узимање венске крви искључиво у јутарњим сатима, јер вриједност изразито варира током дана', 'Забор венозной крови строго в утренние часы, так как показатель сильно колеблется в течение суток', 'Entnahme von venösem Blut ausschließlich in den Morgenstunden, da der Wert im Tagesverlauf stark schwankt', 'Değer gün içinde belirgin şekilde dalgalandığından yalnızca sabah saatlerinde venöz kan alımı', 'Assessment of bone turnover in osteoporosis, monitoring the effect of prescribed therapy, work-up of calcium metabolism disorders', 'Procjena koštanog metabolizma kod osteoporoze, praćenje djelovanja propisane terapije, ispitivanje poremećaja metabolizma kalcijuma', 'Процјена коштаног метаболизма код остеопорозе, праћење дјеловања прописане терапије, испитивање поремећаја метаболизма калцијума', 'Оценка костного обмена при остеопорозе, контроль эффективности назначенной терапии, обследование при нарушениях обмена кальция', 'Beurteilung des Knochenstoffwechsels bei Osteoporose, Kontrolle der Wirkung einer verordneten Therapie, Abklärung von Störungen des Kalziumstoffwechsels', 'Osteoporozda kemik metabolizmasının değerlendirilmesi, uygulanan tedavinin etkisinin izlenmesi, kalsiyum metabolizması bozukluklarının araştırılması', 'In the morning on an empty stomach, as food lowers the value; for repeat tests the same time of day is kept', 'Ujutru natašte, jer obrok snižava vrijednost; kod ponovljenih analiza zadržava se isto doba dana', 'Ујутру наташте, јер оброк снижава вриједност; код поновљених анализа задржава се исто доба дана', 'Утром натощак, приём пищи снижает значение; при повторных анализах стараются сохранять одно и то же время сдачи', 'Morgens nüchtern, da Nahrungsaufnahme den Wert senkt; bei Verlaufskontrollen wird dieselbe Tageszeit beibehalten', 'Sabah aç karnına, çünkü yemek değeri düşürür; tekrarlanan testlerde aynı saat tercih edilir', 'Changes may be related to faster or slower bone renewal, hormonal changes or the response to treatment. The doctor assesses the result together with densitometry', 'Promjene mogu biti povezane sa ubrzanim ili usporenim obnavljanjem koštanog tkiva, hormonskim promjenama ili odgovorom na liječenje. Nalaz ljekar procjenjuje zajedno sa denzitometrijom', 'Промјене могу бити повезане са убрзаним или успореним обнављањем коштаног ткива, хормонским промјенама или одговором на лијечење. Налаз љекар процјењује заједно са дензитометријом', 'Изменения могут быть связаны с ускоренным или замедленным обновлением костной ткани, гормональными перестройками или ответом на лечение. Результат врач оценивает вместе с денситометрией', 'Veränderungen können mit einem beschleunigten oder verlangsamten Knochenumbau, hormonellen Umstellungen oder dem Ansprechen auf die Behandlung zusammenhängen. Der Arzt beurteilt den Wert zusammen mit der Knochendichtemessung', 'Değişiklikler kemik yenilenmesinin hızlanması veya yavaşlaması, hormonal değişimler ya da tedaviye yanıtla ilişkili olabilir. Hekim sonucu kemik yoğunluğu ölçümüyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'fructosamine'), 'Blood test for glycated serum proteins, reflecting the average blood sugar level over the past 2–3 weeks', 'Analiza krvi na glikovane bjelančevine seruma, koje odražavaju prosječan nivo šećera tokom posljednje 2–3 sedmice', 'Анализа крви на гликоване бјеланчевине серума, које одражавају просјечан ниво шећера током посљедње 2–3 седмице', 'Анализ крови на гликированные белки сыворотки, отражающие средний уровень сахара за последние 2–3 недели', 'Bluttest auf glykierte Serumproteine, die den durchschnittlichen Blutzuckerspiegel der letzten 2–3 Wochen widerspiegeln', 'Son 2–3 haftadaki ortalama kan şekeri düzeyini yansıtan glike serum proteinlerini ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Short-term monitoring of diabetes, situations where HbA1c is of limited use — pregnancy, a recent change of therapy, blood disorders', 'Kratkoročna kontrola šećerne bolesti, situacije u kojima je HbA1c manje upotrebljiv — trudnoća, nedavna promjena terapije, bolesti krvi', 'Краткорочна контрола шећерне болести, ситуације у којима је HbA1c мање употребљив — трудноћа, недавна промјена терапије, болести крви', 'Контроль сахарного диабета за короткий период, ситуации, когда HbA1c малоинформативен — беременность, недавняя смена терапии, заболевания крови', 'Kurzfristige Kontrolle eines Diabetes, Situationen mit eingeschränkter Aussagekraft des HbA1c — Schwangerschaft, kürzlich geänderte Therapie, Bluterkrankungen', 'Diyabetin kısa dönemli takibi, HbA1c''nin yeterli bilgi vermediği durumlar: gebelik, tedavinin yakın zamanda değişmesi, kan hastalıkları', 'Special preparation is usually not required, but the sample is most often taken in the morning on an empty stomach; check the conditions with the referring doctor', 'Posebna priprema obično nije potrebna, ali se najčešće uzima ujutru natašte; uslove provjeriti kod ljekara koji je uputio na analizu', 'Посебна припрема обично није потребна, али се најчешће узима ујутру наташте; услове провјерити код љекара који је упутио на анализу', 'Специальная подготовка обычно не требуется, но чаще сдают утром натощак; условия уточните у направившего врача', 'Eine besondere Vorbereitung ist meist nicht nötig, die Abnahme erfolgt aber überwiegend morgens nüchtern; die Bedingungen beim überweisenden Arzt erfragen', 'Genellikle özel hazırlık gerekmez, ancak çoğunlukla sabah aç karnına alınır; koşulları yönlendiren hekime danışın', 'Changes may be related to glucose levels in the preceding weeks and also to the protein content of the blood and to liver or kidney disease. The result is assessed by a doctor', 'Promjene mogu biti povezane sa nivoom glukoze u prethodnim sedmicama, ali i sa količinom bjelančevina u krvi te oboljenjima jetre ili bubrega. Nalaz procjenjuje ljekar', 'Промјене могу бити повезане са нивоом глукозе у претходним седмицама, али и са количином бјеланчевина у крви те обољењима јетре или бубрега. Налаз процјењује љекар', 'Изменения могут быть связаны с уровнем глюкозы в предшествующие недели, а также с содержанием белка в крови и заболеваниями печени или почек. Результат оценивает врач', 'Veränderungen können mit den Glukosewerten der vergangenen Wochen sowie mit dem Eiweißgehalt des Blutes und Leber- oder Nierenerkrankungen zusammenhängen. Die Beurteilung erfolgt durch den Arzt', 'Değişiklikler önceki haftalardaki glukoz düzeyiyle, ayrıca kandaki protein miktarı ve karaciğer veya böbrek hastalıklarıyla ilişkili olabilir. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'pancreatic-amylase'), 'Blood test for the pancreatic fraction of amylase — the part of the enzyme produced specifically by the pancreas', 'Analiza krvi na pankreasnu frakciju amilaze — onaj dio enzima koji stvara upravo pankreas', 'Анализа крви на панкреасну фракцију амилазе — онај дио ензима који ствара управо панкреас', 'Анализ крови на панкреатическую фракцию амилазы — ту часть фермента, которую вырабатывает именно поджелудочная железа', 'Bluttest auf die Pankreasfraktion der Amylase — jenen Anteil des Enzyms, der gezielt von der Bauchspeicheldrüse gebildet wird', 'Amilazın doğrudan pankreas tarafından üretilen fraksiyonunu ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Entnahme von venösem Blut, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Pain in the upper abdomen, clarifying a total amylase result, work-up and follow-up of pancreatic disease', 'Bol u gornjem dijelu trbuha, pojašnjenje nalaza ukupne amilaze, ispitivanje i praćenje oboljenja pankreasa', 'Бол у горњем дијелу трбуха, појашњење налаза укупне амилазе, испитивање и праћење обољења панкреаса', 'Боль в верхней части живота, уточнение результата общей амилазы, обследование и наблюдение при заболеваниях поджелудочной железы', 'Schmerzen im Oberbauch, Präzisierung eines Gesamtamylase-Ergebnisses, Abklärung und Verlaufskontrolle von Erkrankungen der Bauchspeicheldrüse', 'Üst karın ağrısı, total amilaz sonucunun netleştirilmesi, pankreas hastalıklarının araştırılması ve izlenmesi', 'Fasting for 8–12 hours, only water allowed; avoid alcohol and fatty food the day before', 'Natašte 8–12 sati, dozvoljena samo voda; dan ranije izbjegavati alkohol i masnu hranu', 'Наташте 8–12 сати, дозвољена само вода; дан раније избјегавати алкохол и масну храну', 'Натощак 8–12 часов, разрешена только вода; накануне исключить алкоголь и жирную пищу', '8–12 Stunden nüchtern, nur Wasser erlaubt; am Vortag Alkohol und fettreiche Speisen meiden', '8–12 saat aç karnına, sadece su içilebilir; bir önceki gün alkol ve yağlı yiyeceklerden kaçınılmalıdır', 'An increase is more often related to the pancreas, unlike total amylase, which is also affected by the salivary glands; kidney function plays a role as well. The conclusion is drawn by a doctor', 'Povišene vrijednosti češće su povezane sa pankreasom, za razliku od ukupne amilaze na koju utiču i pljuvačne žlijezde; značaj ima i rad bubrega. Zaključak donosi ljekar', 'Повишене вриједности чешће су повезане са панкреасом, за разлику од укупне амилазе на коју утичу и пљувачне жлијезде; значај има и рад бубрега. Закључак доноси љекар', 'Повышение чаще связано с поджелудочной железой, в отличие от общей амилазы, на которую влияют и слюнные железы; сказывается также работа почек. Вывод делает врач', 'Erhöhte Werte hängen häufiger mit der Bauchspeicheldrüse zusammen als die Gesamtamylase, die auch von den Speicheldrüsen beeinflusst wird; auch die Nierenfunktion spielt eine Rolle. Die Schlussfolgerung zieht der Arzt', 'Yüksek değerler, tükürük bezlerinden de etkilenen total amilazın aksine daha çok pankreasla ilişkilidir; böbrek işlevi de rol oynar. Sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-thyroglobulin-antibodies'), 'Blood test for antibodies to thyroglobulin (Anti-Tg), one of the markers used when the thyroid gland is examined', 'Analiza krvi na antitijela na tireoglobulin (Anti-Tg), jedan od markera pri pregledu štitne žlijezde', 'Анализа крви на антитијела на тиреоглобулин (Anti-Tg), један од маркера при прегледу штитне жлијезде', 'Анализ крови на антитела к тиреоглобулину (Anti-Tg) — один из маркеров при обследовании щитовидной железы', 'Bluttest auf Antikörper gegen Thyreoglobulin (Anti-Tg), einer der Marker bei der Untersuchung der Schilddrüse', 'Tiroid bezi değerlendirilirken kullanılan belirteçlerden biri olan tiroglobulin antikorları (Anti-Tg) için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Thyroid evaluation when hormone levels or gland structure change, follow-up after treatment of thyroid disease, pregnancy planning', 'Pregled štitne žlijezde pri promjeni hormona ili strukture tkiva, praćenje nakon liječenja oboljenja štitne žlijezde, planiranje trudnoće', 'Преглед штитне жлијезде при промјени хормона или структуре ткива, праћење након лијечења обољења штитне жлијезде, планирање трудноће', 'Обследование щитовидной железы при изменении гормонов или структуры ткани, наблюдение после лечения заболеваний щитовидной железы, планирование беременности', 'Abklärung der Schilddrüse bei veränderten Hormonwerten oder verändertem Gewebe, Verlaufskontrolle nach Behandlung von Schilddrüsenerkrankungen, Schwangerschaftsplanung', 'Hormon düzeyleri veya bez dokusu değiştiğinde tiroid değerlendirmesi, tiroid hastalıklarının tedavisi sonrası izlem, gebelik planlaması', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A positive result by itself does not mean a disease: such antibodies also occur in healthy people and in other conditions. The doctor decides what the result means together with hormone levels, ultrasound and the clinical picture', 'Pozitivan nalaz sam po sebi ne znači bolest: takva antitijela se sreću i kod zdravih osoba i kod drugih stanja. Značaj rezultata utvrđuje ljekar zajedno sa nivoom hormona, ultrazvukom i kliničkom slikom', 'Позитиван налаз сам по себи не значи болест: таква антитијела се срећу и код здравих особа и код других стања. Значај резултата утврђује љекар заједно са нивоом хормона, ултразвуком и клиничком сликом', 'Положительный результат сам по себе не означает болезнь: такие антитела встречаются и у здоровых людей, и при других состояниях. Значение результата определяет врач вместе с уровнем гормонов, УЗИ и клинической картиной', 'Ein positiver Befund allein bedeutet keine Erkrankung: solche Antikörper kommen auch bei Gesunden und bei anderen Zuständen vor. Was das Ergebnis bedeutet, entscheidet der Arzt zusammen mit Hormonwerten, Ultraschall und klinischem Bild', 'Pozitif sonuç tek başına hastalık anlamına gelmez: bu antikorlar sağlıklı kişilerde ve başka durumlarda da görülebilir. Sonucun anlamını hekim hormon düzeyleri, ultrason ve klinik tabloyla birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'waaler-rose-test'), 'Agglutination blood test used to detect rheumatoid factor when joints are being evaluated', 'Aglutinacioni test krvi kojim se otkriva reumatoidni faktor pri pregledu zglobova', 'Аглутинациони тест крви којим се открива реуматоидни фактор при прегледу зглобова', 'Агглютинационный тест крови, которым выявляют ревматоидный фактор при обследовании суставов', 'Agglutinationstest im Blut, mit dem der Rheumafaktor bei der Abklärung von Gelenkbeschwerden nachgewiesen wird', 'Eklem değerlendirmesinde romatoid faktörü saptamak için kullanılan aglütinasyon esaslı kan testi', 'Venous blood draw; in the laboratory the serum is mixed with antibody-coated red cells and the reaction is read, the draw itself takes a few minutes', 'Uzimanje venske krvi, u laboratoriji se serum miješa sa eritrocitima obloženim antitijelima i prati se reakcija, samo uzimanje traje nekoliko minuta', 'Узимање венске крви, у лабораторији се серум мијеша са еритроцитима обложеним антитијелима и прати се реакција, само узимање траје неколико минута', 'Забор венозной крови, в лаборатории сыворотку смешивают с покрытыми антителами эритроцитами и оценивают реакцию; сам забор занимает несколько минут', 'Blutentnahme aus einer Vene, im Labor wird das Serum mit antikörperbeladenen Erythrozyten vermischt und die Reaktion abgelesen, die Entnahme selbst dauert wenige Minuten', 'Damardan kan alınır, laboratuvarda serum antikorla kaplı alyuvarlarla karıştırılıp reaksiyon değerlendirilir, kan alma işlemi birkaç dakika sürer', 'Joint pain, stiffness and swelling, evaluation when a rheumatic condition is suspected, clarification of other rheumatology test results', 'Bolovi, ukočenost i otok zglobova, pregled pri sumnji na reumatske bolesti, razjašnjenje nalaza drugih reumatoloških testova', 'Болови, укоченост и оток зглобова, преглед при сумњи на реуматске болести, разјашњење налаза других реуматолошких тестова', 'Боли, скованность и припухлость суставов, обследование при подозрении на ревматические заболевания, уточнение результатов других ревмопроб', 'Gelenkschmerzen, Steifigkeit und Schwellungen, Abklärung bei Verdacht auf rheumatische Erkrankungen, Ergänzung zu anderen Rheumawerten', 'Eklem ağrısı, tutukluk ve şişlik, romatizmal hastalık şüphesinde değerlendirme, diğer romatoloji testlerinin sonuçlarının netleştirilmesi', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A positive reaction by itself is not a diagnosis: it also occurs in healthy people, more often at an older age, and in other inflammatory or infectious conditions. The doctor assesses the result together with symptoms, examination and other tests', 'Pozitivna reakcija sama po sebi nije dijagnoza: sreće se i kod zdravih osoba, češće starijih, i kod drugih upalnih i infektivnih stanja. Nalaz procjenjuje ljekar zajedno sa tegobama, pregledom i drugim analizama', 'Позитивна реакција сама по себи није дијагноза: среће се и код здравих особа, чешће старијих, и код других упалних и инфективних стања. Налаз процјењује љекар заједно са тегобама, прегледом и другим анализама', 'Положительная реакция сама по себе не диагноз: она бывает и у здоровых людей, чаще старшего возраста, и при других воспалительных и инфекционных состояниях. Результат оценивает врач вместе с жалобами, осмотром и другими анализами', 'Eine positive Reaktion ist für sich genommen keine Diagnose: sie kommt auch bei Gesunden vor, häufiger im höheren Alter, sowie bei anderen entzündlichen und infektiösen Zuständen. Der Arzt beurteilt das Ergebnis zusammen mit Beschwerden, Untersuchung und weiteren Werten', 'Pozitif reaksiyon tek başına tanı değildir: sağlıklı kişilerde, özellikle ileri yaşta, ve başka iltihabi veya enfeksiyöz durumlarda da görülebilir. Sonucu hekim şikayetler, muayene ve diğer testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'transglutaminase-iga-antibodies'), 'Blood test for IgA antibodies to tissue transglutaminase, the main screening marker when gluten intolerance (coeliac disease) is investigated', 'Analiza krvi na antitijela klase IgA na tkivnu transglutaminazu, osnovni skrining marker pri ispitivanju netolerancije na gluten (celijakije)', 'Анализа крви на антитијела класе IgA на ткивну трансглутаминазу, основни скрининг маркер при испитивању нетолеранције на глутен (целијакије)', 'Анализ крови на антитела класса IgA к тканевой трансглутаминазе — основной скрининговый маркер при обследовании на непереносимость глютена (целиакию)', 'Bluttest auf IgA-Antikörper gegen Gewebetransglutaminase, der wichtigste Suchtest bei der Abklärung einer Glutenunverträglichkeit (Zöliakie)', 'Gluten intoleransının (çölyak hastalığının) araştırılmasında temel tarama belirteci olan doku transglutaminazına karşı IgA antikorları için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Long-lasting diarrhoea, bloating, weight loss, anaemia of unclear origin, growth delay in children, screening of relatives of people with coeliac disease', 'Dugotrajan proliv, nadutost, gubitak tjelesne težine, anemija nejasnog uzroka, zaostajanje u rastu kod djece, ispitivanje srodnika osoba sa celijakijom', 'Дуготрајан пролив, надутост, губитак тјелесне тежине, анемија нејасног узрока, заостајање у расту код дјеце, испитивање сродника особа са целијакијом', 'Длительная диарея, вздутие, потеря веса, анемия неясного происхождения, задержка роста у детей, обследование родственников людей с целиакией', 'Anhaltender Durchfall, Blähungen, Gewichtsverlust, Anämie unklarer Ursache, Wachstumsverzögerung bei Kindern, Abklärung bei Angehörigen von Menschen mit Zöliakie', 'Uzun süren ishal, şişkinlik, kilo kaybı, nedeni belirsiz kansızlık, çocuklarda büyüme geriliği, çölyaklı kişilerin yakınlarının taranması', 'No special preparation required; it is important not to remove gluten-containing foods from the diet before the test, the timing is agreed with the doctor', 'Nije potrebna posebna priprema; važno je da se hrana sa glutenom ne izbacuje iz ishrane prije analize, dogovor se pravi sa ljekarom', 'Није потребна посебна припрема; важно је да се храна са глутеном не избацује из исхране прије анализе, договор се прави са љекаром', 'Специальной подготовки не требуется; важно не убирать продукты с глютеном из питания перед сдачей, порядок обсуждают с врачом', 'Keine besondere Vorbereitung erforderlich; wichtig ist, glutenhaltige Lebensmittel vor dem Test nicht wegzulassen, den Zeitpunkt bespricht man mit dem Arzt', 'Özel bir hazırlık gerekmez; test öncesinde gluten içeren besinlerin diyetten çıkarılmaması önemlidir, zamanlama hekimle kararlaştırılır', 'A positive result by itself does not mean a disease: the antibodies also occur in other conditions and the result is affected by the total IgA level. The doctor decides what the test means together with symptoms and further work-up', 'Pozitivan nalaz sam po sebi ne znači bolest: antitijela se javljaju i kod drugih stanja, a na rezultat utiče nivo ukupnog IgA. Šta analiza znači, utvrđuje ljekar zajedno sa tegobama i daljim ispitivanjem', 'Позитиван налаз сам по себи не значи болест: антитијела се јављају и код других стања, а на резултат утиче ниво укупног IgA. Шта анализа значи, утврђује љекар заједно са тегобама и даљим испитивањем', 'Положительный результат сам по себе не означает болезнь: антитела встречаются и при других состояниях, а на результат влияет уровень общего IgA. Что означает анализ, определяет врач вместе с симптомами и дальнейшим обследованием', 'Ein positiver Befund allein bedeutet keine Erkrankung: die Antikörper kommen auch bei anderen Zuständen vor, und das Gesamt-IgA beeinflusst das Ergebnis. Was der Test bedeutet, entscheidet der Arzt zusammen mit den Beschwerden und der weiteren Abklärung', 'Pozitif sonuç tek başına hastalık anlamına gelmez: bu antikorlar başka durumlarda da görülebilir ve sonucu toplam IgA düzeyi etkiler. Testin anlamını hekim şikayetler ve ileri incelemelerle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'transglutaminase-igg-antibodies'), 'Blood test for IgG antibodies to tissue transglutaminase, the variant of the gluten test used when total IgA is low', 'Analiza krvi na antitijela klase IgG na tkivnu transglutaminazu, varijanta glutenskog testa koja se koristi kada je ukupni IgA snižen', 'Анализа крви на антитијела класе IgG на ткивну трансглутаминазу, варијанта глутенског теста која се користи када је укупни IgA снижен', 'Анализ крови на антитела класса IgG к тканевой трансглутаминазе — вариант глютенового теста, который используют при сниженном уровне общего IgA', 'Bluttest auf IgG-Antikörper gegen Gewebetransglutaminase, die Variante des Glutentests bei erniedrigtem Gesamt-IgA', 'Toplam IgA düşük olduğunda kullanılan, doku transglutaminazına karşı IgG antikorlarını ölçen gluten testi çeşidi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Investigation of gluten intolerance in people with IgA deficiency, clarification of IgA test results, evaluation of children and relatives of people with coeliac disease', 'Ispitivanje netolerancije na gluten kod nedostatka IgA, razjašnjenje nalaza IgA testova, ispitivanje djece i srodnika osoba sa celijakijom', 'Испитивање нетолеранције на глутен код недостатка IgA, разјашњење налаза IgA тестова, испитивање дјеце и сродника особа са целијакијом', 'Обследование на непереносимость глютена при дефиците IgA, уточнение результатов IgA-тестов, обследование детей и родственников людей с целиакией', 'Abklärung einer Glutenunverträglichkeit bei IgA-Mangel, Klärung von IgA-Testergebnissen, Untersuchung von Kindern und Angehörigen von Menschen mit Zöliakie', 'IgA eksikliği olanlarda gluten intoleransının araştırılması, IgA testi sonuçlarının netleştirilmesi, çocukların ve çölyaklı kişilerin yakınlarının değerlendirilmesi', 'No special preparation required; gluten is not removed from the diet before the test, the arrangement is discussed with the doctor', 'Nije potrebna posebna priprema; gluten se prije analize ne izbacuje iz ishrane, dogovor se pravi sa ljekarom', 'Није потребна посебна припрема; глутен се прије анализе не избацује из исхране, договор се прави са љекаром', 'Специальной подготовки не требуется; глютен из питания перед сдачей не исключают, порядок обсуждают с врачом', 'Keine besondere Vorbereitung erforderlich; Gluten wird vor dem Test nicht vom Speiseplan gestrichen, das Vorgehen bespricht man mit dem Arzt', 'Özel bir hazırlık gerekmez; test öncesi gluten diyetten çıkarılmaz, ayrıntılar hekimle konuşulur', 'A positive result on its own is not a diagnosis: such antibodies are also found in people without symptoms and in other bowel and liver conditions. The doctor decides what it means based on the whole set of tests and symptoms', 'Pozitivan nalaz sam po sebi nije dijagnoza: takva antitijela se nalaze i kod osoba bez tegoba i kod drugih bolesti crijeva i jetre. Šta nalaz znači, odlučuje ljekar na osnovu svih analiza i tegoba', 'Позитиван налаз сам по себи није дијагноза: таква антитијела се налазе и код особа без тегоба и код других болести цријева и јетре. Шта налаз значи, одлучује љекар на основу свих анализа и тегоба', 'Положительный результат сам по себе не диагноз: такие антитела находят и у людей без жалоб, и при других заболеваниях кишечника и печени. Что он означает, решает врач по совокупности анализов и симптомов', 'Ein positiver Befund ist für sich genommen keine Diagnose: solche Antikörper finden sich auch bei Menschen ohne Beschwerden und bei anderen Darm- und Lebererkrankungen. Was er bedeutet, entscheidet der Arzt anhand aller Werte und Beschwerden', 'Pozitif sonuç tek başına tanı değildir: bu antikorlar şikayeti olmayan kişilerde ve başka bağırsak ve karaciğer hastalıklarında da bulunabilir. Anlamını hekim tüm testler ve şikayetlerle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-ccp-antibodies'), 'Blood test for antibodies to cyclic citrullinated peptide (Anti-CCP), a marker used when joints are evaluated', 'Analiza krvi na antitijela na ciklični citrulinisani peptid (Anti-CCP), marker koji se koristi pri pregledu zglobova', 'Анализа крви на антитијела на циклични цитрулинисани пептид (Anti-CCP), маркер који се користи при прегледу зглобова', 'Анализ крови на антитела к циклическому цитруллинированному пептиду (Anti-CCP) — маркер, используемый при обследовании суставов', 'Bluttest auf Antikörper gegen cyclisches citrulliniertes Peptid (Anti-CCP), ein Marker bei der Abklärung von Gelenkbeschwerden', 'Eklemlerin değerlendirilmesinde kullanılan siklik sitrülline peptit antikorları (Anti-CCP) için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Long-lasting joint pain and swelling, morning stiffness, assessment alongside rheumatoid factor and inflammation markers', 'Dugotrajni bolovi i otok zglobova, jutarnja ukočenost, ispitivanje uz reumatoidni faktor i pokazatelje upale', 'Дуготрајни болови и оток зглобова, јутарња укоченост, испитивање уз реуматоидни фактор и показатеље упале', 'Длительные боли и припухлость суставов, утренняя скованность, обследование вместе с ревматоидным фактором и показателями воспаления', 'Länger bestehende Gelenkschmerzen und Schwellungen, Morgensteifigkeit, Abklärung zusammen mit Rheumafaktor und Entzündungswerten', 'Uzun süren eklem ağrısı ve şişliği, sabah tutukluğu, romatoid faktör ve iltihap göstergeleriyle birlikte değerlendirme', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A positive result by itself does not mean a disease: the antibodies are sometimes found in people without symptoms and in other conditions. The rheumatologist determines what the result means together with the examination, imaging and other tests', 'Pozitivan nalaz sam po sebi ne znači bolest: antitijela se ponekad nalaze i kod osoba bez tegoba i kod drugih stanja. Značaj rezultata utvrđuje reumatolog zajedno sa pregledom, snimcima i drugim analizama', 'Позитиван налаз сам по себи не значи болест: антитијела се понекад налазе и код особа без тегоба и код других стања. Значај резултата утврђује реуматолог заједно са прегледом, снимцима и другим анализама', 'Положительный результат сам по себе не означает болезнь: антитела иногда обнаруживают у людей без жалоб и при других состояниях. Значение результата определяет ревматолог вместе с осмотром, снимками и другими анализами', 'Ein positiver Befund allein bedeutet keine Erkrankung: die Antikörper finden sich mitunter auch bei Menschen ohne Beschwerden und bei anderen Zuständen. Was das Ergebnis bedeutet, entscheidet der Rheumatologe zusammen mit Untersuchung, Bildgebung und weiteren Werten', 'Pozitif sonuç tek başına hastalık anlamına gelmez: bu antikorlar bazen şikayeti olmayan kişilerde ve başka durumlarda da bulunur. Sonucun anlamını romatolog muayene, görüntüleme ve diğer testlerle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'gliadin-iga-antibodies'), 'Blood test for IgA antibodies to gliadin, a gluten protein, used when gluten intolerance is investigated', 'Analiza krvi na antitijela klase IgA na glijadin, bjelančevinu glutena, koja se radi pri ispitivanju netolerancije na gluten', 'Анализа крви на антитијела класе IgA на глијадин, бјеланчевину глутена, која се ради при испитивању нетолеранције на глутен', 'Анализ крови на антитела класса IgA к глиадину — белку глютена, определяется при обследовании на непереносимость глютена', 'Bluttest auf IgA-Antikörper gegen Gliadin, ein Eiweiß des Glutens, bei der Abklärung einer Glutenunverträglichkeit', 'Gluten intoleransının araştırılmasında bakılan, bir gluten proteini olan gliadine karşı IgA antikorları için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Bloating, changes in stool and weight loss on a gluten-containing diet, evaluation of young children, addition to transglutaminase tests', 'Nadutost, promjene stolice i gubitak tjelesne težine uz ishranu sa glutenom, ispitivanje male djece, dopuna testovima na transglutaminazu', 'Надутост, промјене столице и губитак тјелесне тежине уз исхрану са глутеном, испитивање мале дјеце, допуна тестовима на трансглутаминазу', 'Вздутие, нарушения стула и потеря веса на питании с глютеном, обследование детей раннего возраста, дополнение к тестам на трансглутаминазу', 'Blähungen, veränderter Stuhlgang und Gewichtsverlust bei glutenhaltiger Ernährung, Untersuchung von Kleinkindern, Ergänzung zu den Transglutaminase-Tests', 'Gluten içeren beslenmede şişkinlik, dışkılama değişiklikleri ve kilo kaybı, küçük çocukların değerlendirilmesi, transglutaminaz testlerine ek olarak', 'No special preparation required; gluten-containing foods are not removed from the diet before the test', 'Nije potrebna posebna priprema; hrana sa glutenom se prije analize ne izbacuje iz ishrane', 'Није потребна посебна припрема; храна са глутеном се прије анализе не избацује из исхране', 'Специальной подготовки не требуется; продукты с глютеном перед сдачей из питания не убирают', 'Keine besondere Vorbereitung erforderlich; glutenhaltige Lebensmittel werden vor dem Test nicht weggelassen', 'Özel bir hazırlık gerekmez; test öncesinde gluten içeren besinler diyetten çıkarılmaz', 'A positive result by itself does not mean coeliac disease: these antibodies are less specific and also occur in healthy people and in other bowel conditions. The doctor assesses the result together with other tests and symptoms', 'Pozitivan nalaz sam po sebi ne znači celijakiju: ova antitijela su manje specifična i sreću se kod zdravih osoba i kod drugih bolesti crijeva. Nalaz procjenjuje ljekar zajedno sa drugim testovima i tegobama', 'Позитиван налаз сам по себи не значи целијакију: ова антитијела су мање специфична и срећу се код здравих особа и код других болести цријева. Налаз процјењује љекар заједно са другим тестовима и тегобама', 'Положительный результат сам по себе не означает целиакию: эти антитела менее специфичны и встречаются у здоровых людей и при других болезнях кишечника. Результат оценивает врач вместе с другими тестами и симптомами', 'Ein positiver Befund allein bedeutet keine Zöliakie: diese Antikörper sind weniger spezifisch und kommen auch bei Gesunden und bei anderen Darmerkrankungen vor. Der Arzt beurteilt das Ergebnis zusammen mit weiteren Tests und Beschwerden', 'Pozitif sonuç tek başına çölyak anlamına gelmez: bu antikorlar daha az özgüldür ve sağlıklı kişilerde ile başka bağırsak hastalıklarında da görülür. Sonucu hekim diğer testler ve şikayetlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'gliadin-igg-antibodies'), 'Blood test for IgG antibodies to gliadin, a variant of the gluten test that is useful when total IgA is low', 'Analiza krvi na antitijela klase IgG na glijadin, varijanta glutenskog testa korisna kada je ukupni IgA snižen', 'Анализа крви на антитијела класе IgG на глијадин, варијанта глутенског теста корисна када је укупни IgA снижен', 'Анализ крови на антитела класса IgG к глиадину — вариант глютенового теста, полезный при сниженном уровне общего IgA', 'Bluttest auf IgG-Antikörper gegen Gliadin, eine Variante des Glutentests, die bei erniedrigtem Gesamt-IgA hilfreich ist', 'Toplam IgA düşük olduğunda yararlı olan, gliadine karşı IgG antikorlarını ölçen gluten testi çeşidi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Investigation of gluten intolerance in IgA deficiency, long-lasting bowel complaints, follow-up in children alongside other markers', 'Ispitivanje netolerancije na gluten kod nedostatka IgA, dugotrajne crijevne tegobe, praćenje djece uz druge markere', 'Испитивање нетолеранције на глутен код недостатка IgA, дуготрајне цријевне тегобе, праћење дјеце уз друге маркере', 'Обследование на непереносимость глютена при дефиците IgA, длительные кишечные жалобы, наблюдение детей вместе с другими маркерами', 'Abklärung einer Glutenunverträglichkeit bei IgA-Mangel, anhaltende Darmbeschwerden, Verlaufskontrolle bei Kindern zusammen mit anderen Markern', 'IgA eksikliğinde gluten intoleransının araştırılması, uzun süren bağırsak şikayetleri, çocuklarda diğer belirteçlerle birlikte izlem', 'No special preparation required; the usual gluten-containing diet is kept before the test', 'Nije potrebna posebna priprema; uobičajena ishrana sa glutenom se prije analize zadržava', 'Није потребна посебна припрема; уобичајена исхрана са глутеном се прије анализе задржава', 'Специальной подготовки не требуется; питание с глютеном перед сдачей сохраняют в обычном виде', 'Keine besondere Vorbereitung erforderlich; die gewohnte glutenhaltige Ernährung wird vor dem Test beibehalten', 'Özel bir hazırlık gerekmez; test öncesinde her zamanki gluten içeren beslenme sürdürülür', 'A positive result by itself is not a diagnosis: IgG antibodies to gliadin are often found in people without coeliac disease, including healthy ones. The doctor determines the meaning based on the whole set of tests, symptoms and further work-up', 'Pozitivan nalaz sam po sebi nije dijagnoza: IgG antitijela na glijadin se često nalaze i kod osoba bez celijakije, uključujući zdrave. Značaj rezultata utvrđuje ljekar na osnovu svih analiza, tegoba i daljeg ispitivanja', 'Позитиван налаз сам по себи није дијагноза: IgG антитијела на глијадин се често налазе и код особа без целијакије, укључујући здраве. Значај резултата утврђује љекар на основу свих анализа, тегоба и даљег испитивања', 'Положительный результат сам по себе не диагноз: антитела IgG к глиадину нередко находят у людей без целиакии, в том числе здоровых. Значение результата определяет врач по совокупности анализов, жалоб и дальнейшего обследования', 'Ein positiver Befund allein ist keine Diagnose: IgG-Antikörper gegen Gliadin finden sich häufig auch bei Menschen ohne Zöliakie, darunter Gesunde. Die Bedeutung bestimmt der Arzt anhand aller Werte, Beschwerden und der weiteren Abklärung', 'Pozitif sonuç tek başına tanı değildir: gliadine karşı IgG antikorları çölyak hastalığı olmayan kişilerde, sağlıklı olanlar dahil, sıkça bulunur. Sonucun anlamını hekim tüm testler, şikayetler ve ileri incelemelerle belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'lupus-cells'), 'Microscopic blood examination that looks for specific cells (LE cells) appearing in some autoimmune processes', 'Mikroskopski pregled krvi u kojem se traže posebne ćelije (LE ćelije) koje se javljaju kod nekih autoimunih procesa', 'Микроскопски преглед крви у којем се траже посебне ћелије (LE ћелије) које се јављају код неких аутоимуних процеса', 'Микроскопическое исследование крови, при котором ищут особые клетки (LE-клетки), появляющиеся при некоторых аутоиммунных процессах', 'Mikroskopische Blutuntersuchung, bei der nach besonderen Zellen (LE-Zellen) gesucht wird, die bei manchen Autoimmunprozessen auftreten', 'Bazı otoimmün süreçlerde ortaya çıkan özel hücrelerin (LE hücreleri) arandığı mikroskobik kan incelemesi', 'Venous blood draw, after which the sample is processed in the laboratory and examined under a microscope, the draw itself takes a few minutes', 'Uzimanje venske krvi, zatim se uzorak obrađuje u laboratoriji i pregleda pod mikroskopom, samo uzimanje traje nekoliko minuta', 'Узимање венске крви, затим се узорак обрађује у лабораторији и прегледа под микроскопом, само узимање траје неколико минута', 'Забор венозной крови, затем образец обрабатывают в лаборатории и просматривают под микроскопом; сам забор занимает несколько минут', 'Blutentnahme aus einer Vene, anschließend wird die Probe im Labor aufbereitet und unter dem Mikroskop betrachtet, die Entnahme selbst dauert wenige Minuten', 'Damardan kan alınır, ardından örnek laboratuvarda hazırlanıp mikroskopta incelenir, kan alma işlemi birkaç dakika sürer', 'Evaluation when a systemic autoimmune condition is suspected, joint and skin complaints combined with fever, addition to antibody tests', 'Ispitivanje pri sumnji na sistemske autoimune bolesti, spoj zglobnih i kožnih tegoba sa povišenom temperaturom, dopuna testovima na antitijela', 'Испитивање при сумњи на системске аутоимуне болести, спој зглобних и кожних тегоба са повишеном температуром, допуна тестовима на антитијела', 'Обследование при подозрении на системные аутоиммунные заболевания, сочетание суставных и кожных жалоб с лихорадкой, дополнение к тестам на антитела', 'Abklärung bei Verdacht auf systemische Autoimmunerkrankungen, Gelenk- und Hautbeschwerden zusammen mit Fieber, Ergänzung zu Antikörpertests', 'Sistemik otoimmün hastalık şüphesinde değerlendirme, ateşle birlikte eklem ve cilt şikayetleri, antikor testlerine ek olarak', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'Finding such cells by itself does not mean a particular disease, and their absence does not rule one out: the method is old and less sensitive than modern antibody tests. The doctor assesses the result together with the clinical picture and other tests', 'Nalaz takvih ćelija sam po sebi ne znači određenu bolest, a njihovo odsustvo je ne isključuje: metoda je starija i manje osjetljiva od savremenih testova na antitijela. Nalaz procjenjuje ljekar zajedno sa kliničkom slikom i drugim analizama', 'Налаз таквих ћелија сам по себи не значи одређену болест, а њихово одсуство је не искључује: метода је старија и мање осјетљива од савремених тестова на антитијела. Налаз процјењује љекар заједно са клиничком сликом и другим анализама', 'Находка таких клеток сама по себе не означает конкретную болезнь, а их отсутствие её не исключает: метод старый и менее чувствительный, чем современные тесты на антитела. Результат оценивает врач вместе с клинической картиной и другими анализами', 'Der Nachweis solcher Zellen bedeutet für sich genommen keine bestimmte Erkrankung, und ihr Fehlen schließt eine solche nicht aus: die Methode ist älter und weniger empfindlich als moderne Antikörpertests. Der Arzt beurteilt das Ergebnis zusammen mit dem klinischen Bild und weiteren Werten', 'Bu hücrelerin görülmesi tek başına belirli bir hastalık anlamına gelmez, görülmemesi de hastalığı dışlamaz: yöntem eskidir ve güncel antikor testlerine göre daha az duyarlıdır. Sonucu hekim klinik tablo ve diğer testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ana-antinuclear-antibodies'), 'Blood test for antibodies to cell nucleus components (ANA), a screening test when systemic autoimmune conditions are investigated', 'Analiza krvi na antitijela na sastojke ćelijskog jedra (ANA), skrining test pri ispitivanju sistemskih autoimunih bolesti', 'Анализа крви на антитијела на састојке ћелијског једра (ANA), скрининг тест при испитивању системских аутоимуних болести', 'Анализ крови на антитела к компонентам клеточного ядра (ANA) — скрининговый тест при обследовании на системные аутоиммунные заболевания', 'Bluttest auf Antikörper gegen Zellkernbestandteile (ANA), ein Suchtest bei der Abklärung systemischer Autoimmunerkrankungen', 'Sistemik otoimmün hastalıkların araştırılmasında tarama testi olarak kullanılan, hücre çekirdeği bileşenlerine karşı antikorlar (ANA) için kan testi', 'Venous blood draw; the laboratory reports the titre and the fluorescence pattern, the draw itself takes a few minutes', 'Uzimanje venske krvi, u laboratoriji se određuju titar i tip fluorescencije, samo uzimanje traje nekoliko minuta', 'Узимање венске крви, у лабораторији се одређују титар и тип флуоресценције, само узимање траје неколико минута', 'Забор венозной крови; в лаборатории определяют титр и тип свечения, сам забор занимает несколько минут', 'Blutentnahme aus einer Vene, im Labor werden Titer und Fluoreszenzmuster bestimmt, die Entnahme selbst dauert wenige Minuten', 'Damardan kan alınır, laboratuvarda titre ve boyanma paterni belirlenir, kan alma işlemi birkaç dakika sürer', 'Prolonged fever of unclear origin, joint pain, skin rashes, increased sensitivity to sunlight, evaluation when a connective tissue disease is suspected', 'Dugotrajna povišena temperatura nejasnog uzroka, bolovi u zglobovima, promjene na koži, pojačana osjetljivost na sunce, ispitivanje pri sumnji na sistemske bolesti vezivnog tkiva', 'Дуготрајна повишена температура нејасног узрока, болови у зглобовима, промјене на кожи, појачана осјетљивост на сунце, испитивање при сумњи на системске болести везивног ткива', 'Длительная лихорадка неясного происхождения, боли в суставах, кожные высыпания, повышенная чувствительность к солнцу, обследование при подозрении на системные болезни соединительной ткани', 'Länger bestehendes Fieber unklarer Ursache, Gelenkschmerzen, Hautausschläge, erhöhte Lichtempfindlichkeit, Abklärung bei Verdacht auf Kollagenosen', 'Nedeni belirsiz uzun süreli ateş, eklem ağrıları, ciltte döküntüler, güneşe karşı artmış duyarlılık, bağ dokusu hastalığı şüphesinde değerlendirme', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A positive result by itself does not mean a disease: ANA in low titre occur in healthy people, more often with age, and also with infections, thyroid conditions and some medications. The doctor assesses the titre and the pattern together with the clinical picture and confirmatory tests', 'Pozitivan nalaz sam po sebi ne znači bolest: ANA u niskom titru se nalaze i kod zdravih osoba, češće sa godinama, kao i kod infekcija, bolesti štitne žlijezde i uz neke lijekove. Titar i tip fluorescencije procjenjuje ljekar zajedno sa kliničkom slikom i dodatnim testovima', 'Позитиван налаз сам по себи не значи болест: ANA у ниском титру се налазе и код здравих особа, чешће са годинама, као и код инфекција, болести штитне жлијезде и уз неке лијекове. Титар и тип флуоресценције процјењује љекар заједно са клиничком сликом и додатним тестовима', 'Положительный результат сам по себе не означает болезнь: ANA в низком титре встречаются у здоровых людей, чаще с возрастом, а также при инфекциях, болезнях щитовидной железы и на фоне некоторых лекарств. Титр и тип свечения оценивает врач вместе с клинической картиной и уточняющими тестами', 'Ein positiver Befund allein bedeutet keine Erkrankung: ANA in niedrigem Titer kommen bei Gesunden vor, häufiger mit zunehmendem Alter, ebenso bei Infektionen, Schilddrüsenerkrankungen und unter bestimmten Medikamenten. Titer und Muster beurteilt der Arzt zusammen mit dem klinischen Bild und ergänzenden Tests', 'Pozitif sonuç tek başına hastalık anlamına gelmez: düşük titrede ANA sağlıklı kişilerde, özellikle yaşla birlikte, ayrıca enfeksiyonlarda, tiroid hastalıklarında ve bazı ilaçların kullanımında görülebilir. Titreyi ve paterni hekim klinik tablo ve doğrulayıcı testlerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ovarian-antibodies'), 'Blood test for antibodies to ovarian tissue, a supporting test when cycle disorders and difficulties conceiving are investigated', 'Analiza krvi na antitijela na tkivo jajnika, pomoćni test pri ispitivanju poremećaja ciklusa i teškoća sa začećem', 'Анализа крви на антитијела на ткиво јајника, помоћни тест при испитивању поремећаја циклуса и тешкоћа са зачећем', 'Анализ крови на антитела к тканям яичника — вспомогательный тест при обследовании по поводу нарушений цикла и трудностей с зачатием', 'Bluttest auf Antikörper gegen Eierstockgewebe, ein ergänzender Test bei der Abklärung von Zyklusstörungen und unerfülltem Kinderwunsch', 'Adet düzensizlikleri ve gebe kalmada zorlukların araştırılmasında yardımcı olarak kullanılan, yumurtalık dokusuna karşı antikorlar için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Irregular cycle, early decline of ovarian function, long unsuccessful attempts to conceive, assessment before assisted reproduction programmes', 'Neredovan ciklus, rano slabljenje funkcije jajnika, dugotrajni neuspješni pokušaji začeća, ispitivanje prije programa potpomognute oplodnje', 'Нередован циклус, рано слабљење функције јајника, дуготрајни неуспјешни покушаји зачећа, испитивање прије програма потпомогнуте оплодње', 'Нерегулярный цикл, раннее снижение функции яичников, длительные неудачные попытки зачатия, обследование перед программами вспомогательной репродукции', 'Unregelmäßiger Zyklus, frühes Nachlassen der Eierstockfunktion, länger bestehender unerfüllter Kinderwunsch, Abklärung vor Kinderwunschbehandlungen', 'Düzensiz adet döngüsü, yumurtalık işlevinin erken azalması, uzun süredir gebelik elde edilememesi, yardımcı üreme programları öncesi değerlendirme', 'No special preparation required; the referring doctor specifies the cycle day for the sample', 'Nije potrebna posebna priprema; dan ciklusa za uzimanje uzorka određuje ljekar koji je uputio na analizu', 'Није потребна посебна припрема; дан циклуса за узимање узорка одређује љекар који је упутио на анализу', 'Специальной подготовки не требуется; день цикла для забора уточняет направивший врач', 'Keine besondere Vorbereitung erforderlich; den Zyklustag für die Entnahme gibt der überweisende Arzt vor', 'Özel bir hazırlık gerekmez; örneğin alınacağı döngü gününü yönlendiren hekim belirtir', 'A positive result by itself does not mean a disease and does not predict the outcome of treatment: such antibodies also occur in healthy women and laboratory methods differ. The gynaecologist or fertility specialist considers the result together with hormone levels, ultrasound and medical history', 'Pozitivan nalaz sam po sebi ne znači bolest i ne predviđa ishod liječenja: takva antitijela se sreću i kod zdravih žena, a metode se razlikuju među laboratorijama. Nalaz u obzir uzima ginekolog ili specijalista za plodnost zajedno sa hormonima, ultrazvukom i istorijom bolesti', 'Позитиван налаз сам по себи не значи болест и не предвиђа исход лијечења: таква антитијела се срећу и код здравих жена, а методе се разликују међу лабораторијама. Налаз у обзир узима гинеколог или специјалиста за плодност заједно са хормонима, ултразвуком и историјом болести', 'Положительный результат сам по себе не означает болезнь и не предсказывает исход лечения: такие антитела встречаются и у здоровых женщин, а методики в лабораториях различаются. Результат учитывает гинеколог или репродуктолог вместе с гормонами, УЗИ и историей', 'Ein positiver Befund allein bedeutet keine Erkrankung und sagt den Behandlungserfolg nicht voraus: solche Antikörper kommen auch bei gesunden Frauen vor, und die Labormethoden unterscheiden sich. Der Gynäkologe oder Kinderwunschspezialist berücksichtigt das Ergebnis zusammen mit Hormonwerten, Ultraschall und Vorgeschichte', 'Pozitif sonuç tek başına hastalık anlamına gelmez ve tedavinin sonucunu öngörmez: bu antikorlar sağlıklı kadınlarda da görülebilir ve laboratuvar yöntemleri farklılık gösterir. Sonucu kadın hastalıkları veya üreme sağlığı uzmanı hormonlar, ultrason ve öyküyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-tshr'), 'Blood test for antibodies to the thyroid-stimulating hormone (TSH) receptor on thyroid cells', 'Analiza krvi na antitijela na receptor tireostimulišućeg hormona (TSH) na ćelijama štitne žlijezde', 'Анализа крви на антитијела на рецептор тиреостимулишућег хормона (TSH) на ћелијама штитне жлијезде', 'Анализ крови на антитела к рецептору тиреотропного гормона (TSH) на клетках щитовидной железы', 'Bluttest auf Antikörper gegen den Rezeptor des schilddrüsenstimulierenden Hormons (TSH) auf den Schilddrüsenzellen', 'Tiroid hücrelerindeki tiroid uyarıcı hormon (TSH) reseptörüne karşı antikorlar için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Evaluation of increased thyroid activity, eye complaints related to the thyroid, assessment during pregnancy in women with thyroid conditions', 'Ispitivanje pojačane funkcije štitne žlijezde, očne tegobe povezane sa štitnom žlijezdom, ispitivanje u trudnoći kod žena sa oboljenjima štitne žlijezde', 'Испитивање појачане функције штитне жлијезде, очне тегобе повезане са штитном жлијездом, испитивање у трудноћи код жена са обољењима штитне жлијезде', 'Обследование при повышенной функции щитовидной железы, глазные жалобы, связанные со щитовидной железой, обследование при беременности у женщин с заболеваниями щитовидной железы', 'Abklärung einer gesteigerten Schilddrüsenfunktion, Augenbeschwerden im Zusammenhang mit der Schilddrüse, Untersuchung in der Schwangerschaft bei Frauen mit Schilddrüsenerkrankungen', 'Tiroid işlevinin artmış olduğu durumların değerlendirilmesi, tiroidle ilişkili göz şikayetleri, tiroid hastalığı olan kadınlarda gebelikte değerlendirme', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'Detecting the antibodies by itself is not a diagnosis: the result is meaningful only alongside hormone levels, ultrasound and symptoms, and the antibodies also occur outside active disease. The endocrinologist determines what the result means', 'Nalaz antitijela sam po sebi nije dijagnoza: rezultat ima smisla samo uz nivo hormona, ultrazvuk i tegobe, a antitijela se sreću i van aktivne bolesti. Značaj rezultata utvrđuje endokrinolog', 'Налаз антитијела сам по себи није дијагноза: резултат има смисла само уз ниво хормона, ултразвук и тегобе, а антитијела се срећу и ван активне болести. Значај резултата утврђује ендокринолог', 'Обнаружение антител само по себе не равно диагнозу: результат имеет смысл только рядом с уровнем гормонов, УЗИ и жалобами, а антитела встречаются и вне активной болезни. Значение результата определяет эндокринолог', 'Der Nachweis der Antikörper ist für sich genommen keine Diagnose: das Ergebnis ist nur zusammen mit Hormonwerten, Ultraschall und Beschwerden aussagekräftig, und die Antikörper kommen auch außerhalb einer aktiven Erkrankung vor. Was es bedeutet, entscheidet der Endokrinologe', 'Antikorun saptanması tek başına tanı değildir: sonuç ancak hormon düzeyleri, ultrason ve şikayetlerle birlikte anlam taşır, ayrıca antikorlar aktif hastalık dışında da bulunabilir. Sonucun anlamını endokrinolog belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'calcium-in-urine'), 'Measurement of the amount of calcium the kidneys remove with urine', 'Mjerenje količine kalcijuma koju bubrezi izlučuju mokraćom', 'Мјерење количине калцијума коју бубрези излучују мокраћом', 'Измерение количества кальция, которое почки выводят с мочой', 'Messung der Kalziummenge, die die Nieren mit dem Urin ausscheiden', 'Böbreklerin idrarla attığı kalsiyum miktarının ölçümü', 'Most often a 24-hour collection is examined, with all urine passed during the day gathered in one container, sometimes a single portion is enough', 'Najčešće se ispituje 24-časovni uzorak, gdje se sva mokraća tokom dana sakuplja u jednu posudu, a ponekad je dovoljan i jednokratni uzorak', 'Најчешће се испитује 24-часовни узорак, гдје се сва мокраћа током дана сакупља у једну посуду, а понекад је довољан и једнократни узорак', 'Чаще исследуется суточный сбор: вся моча за день собирается в одну ёмкость, иногда достаточно разовой порции', 'Meist wird Sammelurin über 24 Stunden untersucht, bei dem der gesamte Urin eines Tages in einem Behälter gesammelt wird, manchmal genügt eine Einzelprobe', 'Genellikle gün boyunca çıkarılan tüm idrarın tek kapta toplandığı 24 saatlik örnek incelenir, bazen tek seferlik örnek de yeterlidir', 'Kidney stones and recurrent stone formation, disorders of calcium metabolism, parathyroid gland conditions, monitoring while taking vitamin D or calcium supplements, reduced bone density', 'Kamen u bubregu i ponavljano stvaranje kamenaca, poremećaji metabolizma kalcijuma, bolesti paratireoidnih žlijezda, kontrola tokom uzimanja vitamina D i preparata kalcijuma, smanjena gustina kostiju', 'Камен у бубрегу и понављано стварање каменаца, поремећаји метаболизма калцијума, болести паратиреоидних жлијезда, контрола током узимања витамина Д и препарата калцијума, смањена густина костију', 'Мочекаменная болезнь и повторное образование камней, нарушения обмена кальция, заболевания паращитовидных желёз, контроль при приёме витамина D и препаратов кальция, снижение плотности костей', 'Nierensteine und wiederkehrende Steinbildung, Störungen des Kalziumstoffwechsels, Erkrankungen der Nebenschilddrüsen, Kontrolle bei Einnahme von Vitamin D und Kalziumpräparaten, verminderte Knochendichte', 'Böbrek taşı ve tekrarlayan taş oluşumu, kalsiyum metabolizması bozuklukları, paratiroid bezi hastalıkları, D vitamini ve kalsiyum takviyesi kullanımında izlem, kemik yoğunluğunda azalma', 'For a 24-hour collection the first morning portion is discarded, then all urine is collected until the next morning and the container is kept cool; vitamin D, calcium supplements and diuretics are discussed with the doctor in advance, drinking habits stay as usual', 'Kod 24-časovnog sakupljanja prva jutarnja porcija se baca, zatim se sakuplja sva mokraća do sljedećeg jutra, a posuda se drži na hladnom; uzimanje vitamina D, kalcijuma i diuretika unaprijed dogovoriti sa ljekarom, unos tečnosti ostaje uobičajen', 'Код 24-часовног сакупљања прва јутарња порција се баца, затим се сакупља сва мокраћа до сљедећег јутра, а посуда се држи на хладном; узимање витамина Д, калцијума и диуретика унапријед договорити са љекаром, унос течности остаје уобичајен', 'При суточном сборе первая утренняя порция сливается, дальше собирается вся моча до утра следующего дня, ёмкость хранится в холоде; приём витамина D, кальция и мочегонных заранее обсуждают с врачом, питьевой режим обычный', 'Beim Sammeln über 24 Stunden wird die erste Morgenportion verworfen, danach wird der gesamte Urin bis zum nächsten Morgen gesammelt und der Behälter kühl aufbewahrt; Vitamin D, Kalziumpräparate und Entwässerungsmittel vorher mit dem Arzt besprechen, die Trinkmenge bleibt wie gewohnt', '24 saatlik toplamada ilk sabah idrarı atılır, ardından ertesi sabaha kadar tüm idrar toplanır ve kap serin yerde tutulur; D vitamini, kalsiyum ve idrar söktürücü ilaçlar önceden hekimle görüşülür, sıvı alımı her zamanki gibi sürer', 'Deviations may be related to diet, calcium and vitamin D metabolism, parathyroid or kidney function, or certain medications. The result is assessed by a doctor together with blood calcium', 'Odstupanja mogu biti povezana sa ishranom, metabolizmom kalcijuma i vitamina D, radom paratireoidnih žlijezda ili bubrega, kao i sa nekim lijekovima. Nalaz ljekar procjenjuje zajedno sa kalcijumom u krvi', 'Одступања могу бити повезана са исхраном, метаболизмом калцијума и витамина Д, радом паратиреоидних жлијезда или бубрега, као и са неким лијековима. Налаз љекар процјењује заједно са калцијумом у крви', 'Отклонения могут быть связаны с питанием, обменом кальция и витамина D, работой паращитовидных желёз или почек, а также с приёмом некоторых препаратов. Результат врач оценивает вместе с кальцием крови', 'Abweichungen können mit der Ernährung, dem Kalzium- und Vitamin-D-Stoffwechsel, der Funktion der Nebenschilddrüsen oder der Nieren sowie mit bestimmten Medikamenten zusammenhängen. Der Befund wird vom Arzt zusammen mit dem Kalzium im Blut beurteilt', 'Sapmalar beslenme, kalsiyum ve D vitamini metabolizması, paratiroid bezleri veya böbrek işleviyle ya da bazı ilaçlarla ilişkili olabilir. Sonucu hekim kandaki kalsiyumla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'creatinine-in-urine'), 'Measurement of creatinine, a breakdown product of muscle tissue that is removed by the kidneys', 'Mjerenje kreatinina, produkta razgradnje mišićnog tkiva koji se izlučuje preko bubrega', 'Мјерење креатинина, продукта разградње мишићног ткива који се излучује преко бубрега', 'Измерение креатинина — продукта распада мышечной ткани, который выводится почками', 'Bestimmung von Kreatinin, einem Abbauprodukt der Muskulatur, das über die Nieren ausgeschieden wird', 'Kas dokusunun yıkım ürünü olan ve böbreklerle atılan kreatininin ölçümü', 'Either a single portion or a 24-hour collection is analysed: the single portion serves to express other values per creatinine, the 24-hour one to calculate clearance', 'Ispituje se jednokratni uzorak ili 24-časovno sakupljanje: jednokratni služi za preračunavanje drugih parametara na kreatinin, a dnevni za izračunavanje klirensa', 'Испитује се једнократни узорак или 24-часовно сакупљање: једнократни служи за прерачунавање других параметара на креатинин, а дневни за израчунавање клиренса', 'Исследуется разовая порция или суточный сбор: разовая нужна для пересчёта других показателей на креатинин, суточная — для расчёта клиренса', 'Untersucht wird entweder eine Einzelprobe oder Sammelurin über 24 Stunden: die Einzelprobe dient dem Bezug anderer Werte auf Kreatinin, der Sammelurin der Berechnung der Clearance', 'Tek seferlik örnek ya da 24 saatlik toplama incelenir: tek örnek diğer değerlerin kreatinine oranlanmasında, günlük toplama ise klirens hesabında kullanılır', 'Assessment of kidney filtration, creatinine clearance calculation, expressing protein, albumin and electrolytes in a spot sample, follow-up in chronic kidney disease', 'Procjena filtracione funkcije bubrega, izračunavanje klirensa kreatinina, preračunavanje proteina, albumina i elektrolita u jednokratnom uzorku, praćenje hronične bubrežne bolesti', 'Процјена филтрационе функције бубрега, израчунавање клиренса креатинина, прерачунавање протеина, албумина и електролита у једнократном узорку, праћење хроничне бубрежне болести', 'Оценка фильтрационной функции почек, расчёт клиренса креатинина, пересчёт белка, альбумина и электролитов в разовой порции, наблюдение при хронической болезни почек', 'Beurteilung der Nierenfiltration, Berechnung der Kreatinin-Clearance, Bezug von Eiweiß, Albumin und Elektrolyten in der Einzelprobe, Verlaufskontrolle bei chronischer Nierenerkrankung', 'Böbrek süzme işlevinin değerlendirilmesi, kreatinin klirensi hesabı, tek örnekte protein, albümin ve elektrolitlerin oranlanması, kronik böbrek hastalığında izlem', 'For a single portion usual hygiene and a clean container are enough; for a 24-hour collection all urine of the day goes into one container kept cool, and intense exercise and large amounts of meat are avoided the day before', 'Za jednokratni uzorak dovoljni su uobičajena higijena i čista posuda; kod 24-časovnog sakupljanja sva mokraća ide u jednu posudu koja se drži na hladnom, a dan prije izbjegavaju se veći fizički napori i velika količina mesa', 'За једнократни узорак довољни су уобичајена хигијена и чиста посуда; код 24-часовног сакупљања сва мокраћа иде у једну посуду која се држи на хладном, а дан прије избјегавају се већи физички напори и велика количина меса', 'Для разовой порции достаточно обычной гигиены и чистого контейнера; при суточном сборе вся моча за день идёт в одну ёмкость, которая хранится в холоде, а накануне избегают интенсивных нагрузок и большого количества мяса', 'Für die Einzelprobe genügen übliche Hygiene und ein sauberer Behälter; beim Sammelurin wird der gesamte Urin des Tages in einem kühl gelagerten Behälter gesammelt, am Vortag starke körperliche Belastung und große Fleischmengen meiden', 'Tek örnek için olağan hijyen ve temiz bir kap yeterlidir; 24 saatlik toplamada günün tüm idrarı serin yerde saklanan tek kaba toplanır, bir gün önce yoğun egzersizden ve fazla etten kaçınılır', 'Deviations may be related to muscle mass, diet, fluid intake or kidney function. The doctor assesses the result together with blood creatinine and the urine volume', 'Odstupanja mogu biti povezana sa mišićnom masom, ishranom, unosom tečnosti ili radom bubrega. Ljekar nalaz procjenjuje zajedno sa kreatininom u krvi i zapreminom mokraće', 'Одступања могу бити повезана са мишићном масом, исхраном, уносом течности или радом бубрега. Љекар налаз процјењује заједно са креатинином у крви и запремином мокраће', 'Отклонения могут быть связаны с мышечной массой, питанием, питьевым режимом или работой почек. Врач оценивает результат вместе с креатинином крови и объёмом мочи', 'Abweichungen können mit der Muskelmasse, der Ernährung, der Trinkmenge oder der Nierenfunktion zusammenhängen. Der Arzt beurteilt den Wert zusammen mit dem Kreatinin im Blut und der Urinmenge', 'Sapmalar kas kütlesi, beslenme, sıvı alımı veya böbrek işleviyle ilişkili olabilir. Hekim sonucu kandaki kreatinin ve idrar hacmiyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'phosphorus-in-urine'), 'Measurement of the amount of phosphate the kidneys excrete with urine', 'Mjerenje količine fosfata koju bubrezi izlučuju mokraćom', 'Мјерење количине фосфата коју бубрези излучују мокраћом', 'Измерение количества фосфатов, которые почки выводят с мочой', 'Messung der Phosphatmenge, die die Nieren mit dem Urin ausscheiden', 'Böbreklerin idrarla attığı fosfat miktarının ölçümü', 'Usually a 24-hour collection is examined, less often a single morning portion, and the collection is done at home', 'Obično se ispituje 24-časovno sakupljanje, rjeđe jednokratni jutarnji uzorak, a sakupljanje se obavlja kod kuće', 'Обично се испитује 24-часовно сакупљање, рјеђе једнократни јутарњи узорак, а сакупљање се обавља код куће', 'Обычно исследуется суточный сбор мочи, реже — разовая утренняя порция; сбор пациент проводит дома', 'Meist wird Sammelurin über 24 Stunden untersucht, seltener eine einzelne Morgenprobe, gesammelt wird zu Hause', 'Genellikle 24 saatlik toplama, daha seyrek olarak tek seferlik sabah örneği incelenir, toplama evde yapılır', 'Kidney stones, disorders of calcium and phosphate balance, parathyroid conditions, kidney diseases with electrolyte loss, follow-up in vitamin D deficiency', 'Kamen u bubregu, poremećaji ravnoteže kalcijuma i fosfora, bolesti paratireoidnih žlijezda, bubrežne bolesti sa gubitkom elektrolita, praćenje kod nedostatka vitamina D', 'Камен у бубрегу, поремећаји равнотеже калцијума и фосфора, болести паратиреоидних жлијезда, бубрежне болести са губитком електролита, праћење код недостатка витамина Д', 'Мочекаменная болезнь, нарушения фосфорно-кальциевого обмена, заболевания паращитовидных желёз, болезни почек с потерей электролитов, наблюдение при дефиците витамина D', 'Nierensteine, Störungen des Kalzium-Phosphat-Haushalts, Erkrankungen der Nebenschilddrüsen, Nierenerkrankungen mit Elektrolytverlust, Kontrolle bei Vitamin-D-Mangel', 'Böbrek taşı, kalsiyum-fosfor dengesi bozuklukları, paratiroid hastalıkları, elektrolit kaybına yol açan böbrek hastalıkları, D vitamini eksikliğinde izlem', 'For the 24-hour collection the first morning portion is not collected, all further urine is gathered until the same hour the next morning and kept cool; vitamin D, phosphate binders and antacids are discussed with the doctor in advance', 'Kod 24-časovnog sakupljanja prva jutarnja porcija se ne sakuplja, sva naredna mokraća skuplja se do istog sata narednog jutra i drži na hladnom; uzimanje vitamina D, preparata za vezivanje fosfata i antacida unaprijed dogovoriti sa ljekarom', 'Код 24-часовног сакупљања прва јутарња порција се не сакупља, сва наредна мокраћа скупља се до истог сата наредног јутра и држи на хладном; узимање витамина Д, препарата за везивање фосфата и антацида унапријед договорити са љекаром', 'При суточном сборе первую утреннюю порцию не собирают, всю последующую мочу собирают до того же часа следующего утра и держат в прохладе; приём витамина D, фосфатсвязывающих средств и антацидов заранее обсуждают с врачом', 'Beim Sammeln über 24 Stunden wird die erste Morgenportion nicht gesammelt, der weitere Urin bis zur gleichen Stunde am nächsten Morgen aufgefangen und kühl gelagert; Vitamin D, Phosphatbinder und Säureblocker vorher mit dem Arzt besprechen', '24 saatlik toplamada ilk sabah idrarı toplanmaz, sonraki tüm idrar ertesi sabah aynı saate kadar biriktirilir ve serin yerde saklanır; D vitamini, fosfat bağlayıcılar ve mide ilaçları önceden hekimle görüşülür', 'Changes may be related to diet, calcium and phosphate metabolism, parathyroid function or the kidney tubules. The result has to be read together with blood phosphate and calcium, which is done by a doctor', 'Promjene mogu biti povezane sa ishranom, metabolizmom kalcijuma i fosfora, radom paratireoidnih žlijezda ili bubrežnih tubula. Nalaz se tumači zajedno sa fosforom i kalcijumom u krvi, a to radi ljekar', 'Промјене могу бити повезане са исхраном, метаболизмом калцијума и фосфора, радом паратиреоидних жлијезда или бубрежних тубула. Налаз се тумачи заједно са фосфором и калцијумом у крви, а то ради љекар', 'Изменения могут быть связаны с питанием, обменом кальция и фосфора, работой паращитовидных желёз или канальцев почек. Результат читают вместе с фосфором и кальцием крови, это делает врач', 'Veränderungen können mit der Ernährung, dem Kalzium-Phosphat-Stoffwechsel, den Nebenschilddrüsen oder den Nierentubuli zusammenhängen. Der Wert muss zusammen mit Phosphat und Kalzium im Blut gelesen werden, das übernimmt der Arzt', 'Değişiklikler beslenme, kalsiyum-fosfor metabolizması, paratiroid bezleri veya böbrek tübülleriyle ilişkili olabilir. Sonuç kandaki fosfor ve kalsiyumla birlikte yorumlanmalıdır, bunu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'uric-acid-in-urine'), 'Measurement of how much uric acid leaves the body with urine over a defined period', 'Mjerenje količine mokraćne kiseline koja se mokraćom izluči u određenom periodu', 'Мјерење количине мокраћне киселине која се мокраћом излучи у одређеном периоду', 'Измерение количества мочевой кислоты, которое выводится с мочой за определённое время', 'Messung, wie viel Harnsäure in einem festgelegten Zeitraum mit dem Urin ausgeschieden wird', 'Belirli bir sürede idrarla atılan ürik asit miktarının ölçümü', 'The standard approach is a 24-hour collection into one container, and if the doctor decides so a single portion is analysed and expressed per creatinine', 'Standardno se radi 24-časovno sakupljanje u jednu posudu, a po odluci ljekara ispituje se jednokratni uzorak sa preračunavanjem na kreatinin', 'Стандардно се ради 24-часовно сакупљање у једну посуду, а по одлуци љекара испитује се једнократни узорак са прерачунавањем на креатинин', 'Стандартно проводится суточный сбор мочи в одну ёмкость, по решению врача исследуется разовая порция с пересчётом на креатинин', 'Üblich ist das Sammeln über 24 Stunden in einem Behälter, nach ärztlicher Entscheidung wird eine Einzelprobe untersucht und auf Kreatinin bezogen', 'Standart yöntem tek kapta 24 saatlik toplamadır, hekim uygun görürse tek seferlik örnek alınıp kreatinine oranlanır', 'Gout, urate stones, recurrent kidney stone disease, assessment of purine metabolism, work-up of elevated uric acid in blood', 'Giht, uratni kamenci, ponavljana bolest kamena u bubregu, procjena metabolizma purina, obrada povišene mokraćne kiseline u krvi', 'Гихт, уратни каменци, понављана болест камена у бубрегу, процјена метаболизма пурина, обрада повишене мокраћне киселине у крви', 'Подагра, уратные камни, повторная мочекаменная болезнь, оценка обмена пуринов, обследование при повышенной мочевой кислоте в крови', 'Gicht, Harnsäuresteine, wiederkehrendes Nierensteinleiden, Beurteilung des Purinstoffwechsels, Abklärung erhöhter Harnsäure im Blut', 'Gut hastalığı, ürat taşları, tekrarlayan böbrek taşı hastalığı, pürin metabolizmasının değerlendirilmesi, kanda yüksek ürik asidin araştırılması', 'For two or three days before the collection keep the usual diet agreed with the doctor, without an excess of meat, offal and alcohol; the collection starts after the first morning portion has been discarded and ends with the first portion of the next morning', 'Dva do tri dana prije sakupljanja zadržati uobičajenu ishranu dogovorenu sa ljekarom, bez viška mesa, iznutrica i alkohola; sakupljanje počinje nakon što se prva jutarnja porcija baci, a završava se prvom porcijom narednog jutra', 'Два до три дана прије сакупљања задржати уобичајену исхрану договорену са љекаром, без вишка меса, изнутрица и алкохола; сакупљање почиње након што се прва јутарња порција баци, а завршава се првом порцијом наредног јутра', 'За два-три дня до сбора сохраняют обычный, согласованный с врачом рацион без избытка мяса, субпродуктов и алкоголя; сбор начинается после того, как первая утренняя порция слита, и заканчивается первой порцией следующего утра', 'Zwei bis drei Tage vor dem Sammeln die gewohnte, mit dem Arzt abgesprochene Ernährung beibehalten, ohne Übermaß an Fleisch, Innereien und Alkohol; das Sammeln beginnt nach dem Verwerfen der ersten Morgenportion und endet mit der ersten Portion am nächsten Morgen', 'Toplamadan iki üç gün önce hekimle kararlaştırılan olağan beslenme sürdürülür, aşırı et, sakatat ve alkolden kaçınılır; toplama ilk sabah idrarı atıldıktan sonra başlar ve ertesi sabahın ilk idrarıyla biter', 'Deviations may be related to diet, purine metabolism, some medications or kidney function. What the value means is decided by a doctor together with blood uric acid', 'Odstupanja mogu biti povezana sa ishranom, metabolizmom purina, nekim lijekovima ili radom bubrega. Značenje nalaza ljekar utvrđuje zajedno sa mokraćnom kiselinom u krvi', 'Одступања могу бити повезана са исхраном, метаболизмом пурина, неким лијековима или радом бубрега. Значење налаза љекар утврђује заједно са мокраћном киселином у крви', 'Отклонения могут быть связаны с питанием, обменом пуринов, приёмом некоторых препаратов или работой почек. Значение результата врач определяет вместе с мочевой кислотой крови', 'Abweichungen können mit der Ernährung, dem Purinstoffwechsel, bestimmten Medikamenten oder der Nierenfunktion zusammenhängen. Die Bedeutung des Werts bestimmt der Arzt zusammen mit der Harnsäure im Blut', 'Sapmalar beslenme, pürin metabolizması, bazı ilaçlar veya böbrek işleviyle ilişkili olabilir. Sonucun anlamını hekim kandaki ürik asitle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protein-in-urine'), 'Detection and measurement of protein in a single urine sample', 'Otkrivanje i mjerenje proteina u jednokratnom uzorku mokraće', 'Откривање и мјерење протеина у једнократном узорку мокраће', 'Определение наличия и концентрации белка в разовой порции мочи', 'Nachweis und Bestimmung von Eiweiß in einer einzelnen Urinprobe', 'Tek seferlik idrar örneğinde proteinin saptanması ve ölçülmesi', 'One portion of urine is passed into a container and the laboratory checks whether protein is present and in what concentration, which takes a couple of minutes', 'Pacijent daje jednu porciju mokraće u posudu, a laboratorija utvrđuje da li ima proteina i u kojoj koncentraciji, što traje nekoliko minuta', 'Пацијент даје једну порцију мокраће у посуду, а лабораторија утврђује да ли има протеина и у којој концентрацији, што траје неколико минута', 'Пациент сдаёт одну порцию мочи в контейнер, лаборатория проверяет, есть ли белок и в какой концентрации; занимает пару минут', 'Eine Urinportion wird in einen Behälter gegeben, das Labor prüft, ob und wie viel Eiweiß enthalten ist, das dauert wenige Minuten', 'Hastanın kaba verdiği tek idrar örneğinde laboratuvar protein olup olmadığını ve derişimini belirler, işlem birkaç dakika sürer', 'Preventive examination, swelling, foamy or discoloured urine, high blood pressure, monitoring during pregnancy, follow-up of kidney conditions', 'Preventivni pregled, otoci, pjenušava ili promijenjena boja mokraće, povišen krvni pritisak, kontrola u trudnoći, praćenje bubrežnih bolesti', 'Превентивни преглед, отоци, пјенушава или промијењена боја мокраће, повишен крвни притисак, контрола у трудноћи, праћење бубрежних болести', 'Профилактический осмотр, отёки, пенистая или изменившая цвет моча, повышенное давление, контроль при беременности, наблюдение при болезнях почек', 'Vorsorgeuntersuchung, Ödeme, schäumender oder verfärbter Urin, hoher Blutdruck, Kontrolle in der Schwangerschaft, Verlaufskontrolle bei Nierenerkrankungen', 'Koruyucu muayene, ödem, köpüklü veya rengi değişmiş idrar, yüksek tansiyon, gebelikte izlem, böbrek hastalıklarının takibi', 'Morning portion after hygiene of the external genitals, midstream into a sterile container; avoid heavy physical exertion the day before and postpone the test during menstruation', 'Jutarnja porcija poslije higijene spoljašnjih genitalija, srednji mlaz u sterilnu posudu; dan prije izbjegavati veće fizičke napore, a tokom menstruacije analizu odložiti', 'Јутарња порција послије хигијене спољашњих гениталија, средњи млаз у стерилну посуду; дан прије избјегавати веће физичке напоре, а током менструације анализу одложити', 'Утренняя порция после гигиены наружных половых органов, средняя струя в стерильный контейнер; накануне избегать тяжёлых физических нагрузок, во время менструации сдачу лучше отложить', 'Morgenportion nach Reinigung des Intimbereichs, Mittelstrahl in einen sterilen Behälter; am Vortag starke körperliche Belastung meiden, während der Menstruation den Test verschieben', 'Genital bölge temizliğinden sonra sabah idrarı, orta akım steril kaba alınır; bir gün önce ağır fiziksel efordan kaçınılır, adet döneminde test ertelenir', 'Protein in urine may be related to exertion, fever, dehydration or to processes in the kidneys and urinary tract. A single finding calls for a repeat test, and the decision is made by a doctor', 'Prisustvo proteina može biti povezano sa naporom, povišenom tjelesnom temperaturom, dehidratacijom ili sa procesima u bubrezima i mokraćnim putevima. Jedan nalaz traži ponavljanje analize, a odluku donosi ljekar', 'Присуство протеина може бити повезано са напором, повишеном тјелесном температуром, дехидратацијом или са процесима у бубрезима и мокраћним путевима. Један налаз тражи понављање анализе, а одлуку доноси љекар', 'Появление белка может быть связано с нагрузкой, повышенной температурой, обезвоживанием или с процессами в почках и мочевых путях. Однократная находка требует повторного анализа, решение принимает врач', 'Eiweiß im Urin kann mit Belastung, Fieber, Flüssigkeitsmangel oder mit Vorgängen in Nieren und Harnwegen zusammenhängen. Ein einzelner Befund erfordert eine Kontrolle, darüber entscheidet der Arzt', 'İdrarda protein bulunması efor, ateş, sıvı kaybı ya da böbrek ve idrar yollarındaki süreçlerle ilişkili olabilir. Tek bir sonuç tekrar test gerektirir, kararı hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'microalbumin-in-urine'), 'Detection of small amounts of albumin that a routine protein test does not pick up', 'Otkrivanje malih količina albumina koje obična analiza proteina ne registruje', 'Откривање малих количина албумина које обична анализа протеина не региструје', 'Выявление небольших количеств альбумина, которые обычный тест на белок не улавливает', 'Nachweis kleiner Albuminmengen, die ein üblicher Eiweißtest nicht erfasst', 'Standart protein testinin yakalayamadığı küçük miktarlardaki albüminin saptanması', 'Most often the first morning portion is analysed together with creatinine so that the ratio can be calculated, less often a 24-hour collection is used', 'Najčešće se ispituje prva jutarnja porcija uz istovremeno određivanje kreatinina radi izračunavanja odnosa, rjeđe se koristi 24-časovno sakupljanje', 'Најчешће се испитује прва јутарња порција уз истовремено одређивање креатинина ради израчунавања односа, рјеђе се користи 24-часовно сакупљање', 'Чаще исследуется первая утренняя порция с одновременным определением креатинина для расчёта соотношения, реже используется суточный сбор', 'Meist wird die erste Morgenportion zusammen mit Kreatinin untersucht, um das Verhältnis zu berechnen, seltener kommt Sammelurin über 24 Stunden zum Einsatz', 'Çoğunlukla ilk sabah idrarı, oran hesaplanabilsin diye kreatininle birlikte incelenir, daha seyrek olarak 24 saatlik toplama kullanılır', 'Regular monitoring in diabetes mellitus and arterial hypertension, follow-up in chronic kidney disease, cardiovascular risk assessment', 'Redovna kontrola kod šećerne bolesti i povišenog krvnog pritiska, praćenje hronične bubrežne bolesti, procjena kardiovaskularnog rizika', 'Редовна контрола код шећерне болести и повишеног крвног притиска, праћење хроничне бубрежне болести, процјена кардиоваскуларног ризика', 'Регулярный контроль при сахарном диабете и артериальной гипертензии, наблюдение при хронической болезни почек, оценка сердечно-сосудистого риска', 'Regelmäßige Kontrolle bei Diabetes mellitus und Bluthochdruck, Verlaufskontrolle bei chronischer Nierenerkrankung, Einschätzung des Herz-Kreislauf-Risikos', 'Diyabet ve yüksek tansiyonda düzenli kontrol, kronik böbrek hastalığında izlem, kalp-damar riskinin değerlendirilmesi', 'First morning portion after hygiene; avoid intense exercise for a day before, and do not take the test during fever, a urinary tract infection or menstruation', 'Prva jutarnja porcija poslije higijene; dan prije izbjegavati intenzivne napore, a analizu ne raditi kod povišene tjelesne temperature, infekcije mokraćnih puteva i tokom menstruacije', 'Прва јутарња порција послије хигијене; дан прије избјегавати интензивне напоре, а анализу не радити код повишене тјелесне температуре, инфекције мокраћних путева и током менструације', 'Первая утренняя порция после гигиены; за сутки избегать интенсивных нагрузок, анализ не сдают при повышенной температуре, инфекции мочевых путей и во время менструации', 'Erste Morgenportion nach der Hygiene; am Tag davor starke Anstrengung meiden, bei Fieber, Harnwegsinfekt und während der Menstruation nicht durchführen', 'Hijyen sonrası ilk sabah idrarı; bir gün önce yoğun egzersizden kaçınılır, ateş, idrar yolu enfeksiyonu ve adet döneminde test yapılmaz', 'Increased albumin excretion may be related to the state of the kidney filters, high blood pressure, high blood sugar or temporary causes. Conclusions require a repeat test and assessment by a doctor', 'Povećano izlučivanje albumina može biti povezano sa stanjem bubrežnih filtera, visokim pritiskom, povišenim šećerom u krvi ili privremenim uzrocima. Za zaključak su potrebni ponovljena analiza i procjena ljekara', 'Повећано излучивање албумина може бити повезано са стањем бубрежних филтера, високим притиском, повишеним шећером у крви или привременим узроцима. За закључак су потребни поновљена анализа и процјена љекара', 'Повышенное выделение альбумина может быть связано с состоянием почечных фильтров, высоким давлением, повышенным сахаром крови или временными причинами. Для выводов нужен повторный анализ и оценка врача', 'Eine erhöhte Albuminausscheidung kann mit dem Zustand der Nierenfilter, hohem Blutdruck, hohem Blutzucker oder vorübergehenden Ursachen zusammenhängen. Für Schlussfolgerungen sind eine Kontrolle und die Beurteilung durch den Arzt nötig', 'Albümin atılımının artması böbrek süzgeçlerinin durumu, yüksek tansiyon, yüksek kan şekeri ya da geçici nedenlerle ilişkili olabilir. Sonuç çıkarmak için testin tekrarı ve hekim değerlendirmesi gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'spermogram'), 'Laboratory analysis of semen: volume, number, motility and shape of sperm cells', 'Laboratorijska analiza ejakulata: zapremina, broj, pokretljivost i oblik spermatozoida', 'Лабораторијска анализа ејакулата: запремина, број, покретљивост и облик сперматозоида', 'Лабораторное исследование эякулята: объём, количество, подвижность и строение сперматозоидов', 'Laboruntersuchung des Ejakulats: Menge, Anzahl, Beweglichkeit und Form der Samenzellen', 'Meninin laboratuvar incelemesi: hacim, sperm sayısı, hareketlilik ve şekil', 'The sample is produced by masturbation into a sterile container in a separate room at the clinic and is examined within about an hour', 'Uzorak se dobija masturbacijom u sterilnu posudu u posebnoj prostoriji klinike i obrađuje se u roku od otprilike jednog sata', 'Узорак се добија мастурбацијом у стерилну посуду у посебној просторији клинике и обрађује се у року од отприлике једног сата', 'Образец получают путём мастурбации в отдельной комнате клиники в стерильный контейнер, исследование начинают примерно в течение часа', 'Die Probe wird durch Masturbation in einem separaten Raum der Klinik in einen sterilen Becher gewonnen und innerhalb etwa einer Stunde untersucht', 'Örnek klinikte ayrı bir odada mastürbasyonla steril kaba alınır ve yaklaşık bir saat içinde incelenir', 'Work-up of a couple with difficulty conceiving, assessment of male fertility, follow-up after surgery or treatment such as varicocele or inflammation, check after vasectomy, preparation for assisted reproduction', 'Obrada para sa teškoćama u začeću, procjena muške plodnosti, kontrola poslije operacija i liječenja (varikokela, upale), provjera poslije vazektomije, priprema za postupke vantjelesne oplodnje', 'Обрада пара са тешкоћама у зачећу, процјена мушке плодности, контрола послије операција и лијечења (варикокела, упале), провјера послије вазектомије, припрема за поступке вантјелесне оплодње', 'Обследование пары при трудностях с зачатием, оценка мужской фертильности, контроль после операций и лечения (варикоцеле, воспаления), проверка после вазэктомии, подготовка к программам вспомогательной репродукции', 'Abklärung eines Paares mit unerfülltem Kinderwunsch, Beurteilung der männlichen Fruchtbarkeit, Kontrolle nach Operationen und Behandlungen wie Varikozele oder Entzündungen, Kontrolle nach Vasektomie, Vorbereitung auf eine künstliche Befruchtung', 'Gebe kalmakta güçlük çeken çiftlerin araştırılması, erkek doğurganlığının değerlendirilmesi, varikosel veya iltihap tedavisi ve ameliyat sonrası kontrol, vazektomi sonrası kontrol, yardımcı üreme tedavilerine hazırlık', 'Sexual abstinence of two to five days (the clinic states the exact period), avoid alcohol and overheating such as sauna or hot baths for several days, do not attend during an acute illness with fever or shortly after a course of antibiotics', 'Polna apstinencija od dva do pet dana (tačan period određuje klinika), nekoliko dana izbjegavati alkohol i pregrijavanje (sauna, vruća kupka), ne dolaziti tokom akutne bolesti sa povišenom temperaturom ni ubrzo poslije terapije antibioticima', 'Полна апстиненција од два до пет дана (тачан период одређује клиника), неколико дана избјегавати алкохол и прегријавање (сауна, врућа купка), не долазити током акутне болести са повишеном температуром ни убрзо послије терапије антибиотицима', 'Половое воздержание от двух до пяти дней (точный срок называет клиника), несколько дней избегать алкоголя и перегрева (сауна, горячая ванна), не сдавать во время острого заболевания с температурой и вскоре после курса антибиотиков', 'Sexuelle Karenz von zwei bis fünf Tagen (den genauen Zeitraum nennt die Klinik), einige Tage vorher Alkohol und Überhitzung wie Sauna oder heiße Bäder meiden, nicht während einer akuten fieberhaften Erkrankung oder kurz nach einer Antibiotikatherapie', 'İki ila beş gün cinsel perhiz (kesin süreyi klinik belirtir), birkaç gün alkolden ve sauna, sıcak banyo gibi aşırı ısınmadan kaçınma, ateşli akut hastalık sırasında ve antibiyotik kürünün hemen ardından test yapılmaz', 'Deviations may be related to temporary factors such as illness, stress, overheating or recent fever, or to the state of the reproductive system. Conclusions are not drawn from one sample, a repeat test and a consultation with a urologist or andrologist are arranged', 'Odstupanja mogu biti povezana sa privremenim faktorima (bolest, stres, pregrijavanje, nedavno povišena temperatura) ili sa stanjem reproduktivnog sistema. Zaključak se ne donosi na osnovu jednog nalaza, već se radi ponovna analiza i pregled urologa ili androloga', 'Одступања могу бити повезана са привременим факторима (болест, стрес, прегријавање, недавно повишена температура) или са стањем репродуктивног система. Закључак се не доноси на основу једног налаза, већ се ради поновна анализа и преглед уролога или андролога', 'Отклонения могут быть связаны с временными факторами (болезнь, стресс, перегрев, недавняя лихорадка) или с состоянием репродуктивной системы. По одному анализу выводы не делают, назначают повтор и консультацию уролога или андролога', 'Abweichungen können mit vorübergehenden Faktoren wie Krankheit, Stress, Überhitzung oder kürzlichem Fieber oder mit dem Zustand des Fortpflanzungssystems zusammenhängen. Aus einer einzelnen Untersuchung werden keine Schlüsse gezogen, es folgen eine Wiederholung und ein Gespräch beim Urologen oder Andrologen', 'Sapmalar hastalık, stres, aşırı ısınma, yakın zamanda geçirilmiş ateş gibi geçici etkenlerle ya da üreme sisteminin durumuyla ilişkili olabilir. Tek bir sonuçla yorum yapılmaz, test tekrarlanır ve üroloji veya androloji görüşü alınır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'amylase-in-urine'), 'Measurement of the activity of an enzyme of the pancreas and salivary glands that is excreted with urine', 'Mjerenje aktivnosti enzima gušterače i pljuvačnih žlijezda koji se izlučuje mokraćom', 'Мјерење активности ензима гуштераче и пљувачних жлијезда који се излучује мокраћом', 'Измерение активности фермента поджелудочной железы и слюнных желёз, который выводится с мочой', 'Bestimmung der Aktivität eines Enzyms der Bauchspeicheldrüse und der Speicheldrüsen, das mit dem Urin ausgeschieden wird', 'Pankreas ve tükürük bezlerine ait olup idrarla atılan bir enzimin etkinliğinin ölçümü', 'A single urine portion is analysed, and sometimes a timed collection over several hours or a full day is used to assess how much enzyme is excreted', 'Ispituje se jednokratni uzorak mokraće, a ponekad se radi sakupljanje kroz nekoliko sati ili tokom dana radi procjene izlučivanja enzima', 'Испитује се једнократни узорак мокраће, а понекад се ради сакупљање кроз неколико сати или током дана ради процјене излучивања ензима', 'Исследуется разовая порция мочи, иногда делают сбор за несколько часов или за сутки, чтобы оценить выведение фермента', 'Untersucht wird eine einzelne Urinportion, manchmal wird über mehrere Stunden oder einen Tag gesammelt, um die ausgeschiedene Enzymmenge zu beurteilen', 'Tek seferlik idrar örneği incelenir, bazen enzim atılımını değerlendirmek için birkaç saatlik ya da günlük toplama yapılır', 'Pain in the upper abdomen, suspected inflammation of the pancreas, follow-up over time, work-up of salivary gland conditions', 'Bol u gornjem dijelu trbuha, sumnja na upalu gušterače, praćenje toka, obrada oboljenja pljuvačnih žlijezda', 'Бол у горњем дијелу трбуха, сумња на упалу гуштераче, праћење тока, обрада обољења пљувачних жлијезда', 'Боль в верхней части живота, подозрение на воспаление поджелудочной железы, наблюдение в динамике, обследование при болезнях слюнных желёз', 'Schmerzen im Oberbauch, Verdacht auf eine Entzündung der Bauchspeicheldrüse, Verlaufskontrolle, Abklärung von Speicheldrüsenerkrankungen', 'Üst karın ağrısı, pankreas iltihabı şüphesi, seyrin izlenmesi, tükürük bezi hastalıklarının araştırılması', 'No special preparation is needed; the urine is collected in a clean container, and medications or alcohol taken the day before should be mentioned to the doctor', 'Posebna priprema nije potrebna; mokraća se skuplja u čistu posudu, a o lijekovima i alkoholu uzetim dan prije treba obavijestiti ljekara', 'Посебна припрема није потребна; мокраћа се скупља у чисту посуду, а о лијековима и алкохолу узетим дан прије треба обавијестити љекара', 'Специальная подготовка не нужна; моча собирается в чистый контейнер, о принимаемых препаратах и алкоголе накануне стоит сообщить врачу', 'Eine besondere Vorbereitung ist nicht nötig; der Urin wird in einem sauberen Behälter aufgefangen, Medikamente und Alkohol vom Vortag sollten dem Arzt mitgeteilt werden', 'Özel bir hazırlık gerekmez; idrar temiz bir kaba alınır, bir gün önce kullanılan ilaçlar ve alkol hekime bildirilmelidir', 'A change in activity may be related to the pancreas, the salivary glands, kidney function or certain medications. The result is read together with blood amylase and the clinical picture, which is done by a doctor', 'Promjena aktivnosti može biti povezana sa stanjem gušterače, pljuvačnih žlijezda, radom bubrega ili sa uzimanjem nekih lijekova. Nalaz se tumači zajedno sa amilazom u krvi i kliničkom slikom, a to radi ljekar', 'Промјена активности може бити повезана са стањем гуштераче, пљувачних жлијезда, радом бубрега или са узимањем неких лијекова. Налаз се тумачи заједно са амилазом у крви и клиничком сликом, а то ради љекар', 'Изменение активности может быть связано с состоянием поджелудочной железы, слюнных желёз, работой почек или с приёмом некоторых препаратов. Результат читают вместе с амилазой крови и клинической картиной, это делает врач', 'Eine veränderte Aktivität kann mit der Bauchspeicheldrüse, den Speicheldrüsen, der Nierenfunktion oder bestimmten Medikamenten zusammenhängen. Der Wert wird zusammen mit der Amylase im Blut und dem Beschwerdebild vom Arzt beurteilt', 'Etkinlikteki değişiklik pankreas, tükürük bezleri, böbrek işlevi veya bazı ilaçlarla ilişkili olabilir. Sonuç kandaki amilaz ve klinik tabloyla birlikte hekim tarafından yorumlanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protein-in-24h-urine'), 'Measurement of the total amount of protein lost with urine over a full day', 'Mjerenje ukupne količine proteina koja se mokraćom izgubi tokom cijelog dana', 'Мјерење укупне количине протеина која се мокраћом изгуби током цијелог дана', 'Измерение общего количества белка, которое теряется с мочой за целые сутки', 'Bestimmung der gesamten Eiweißmenge, die im Verlauf eines Tages mit dem Urin verloren geht', 'Bir gün boyunca idrarla kaybedilen toplam protein miktarının ölçümü', 'Urine is collected into one graduated container for 24 hours, and the measured total volume plus a sample from the mixed collection go to the laboratory', 'Mokraća se 24 sata skuplja u jednu graduisanu posudu, a u laboratoriju se nose izmjerena ukupna zapremina i uzorak iz promiješanog sakupljenog materijala', 'Мокраћа се 24 сата скупља у једну градуисану посуду, а у лабораторију се носе измјерена укупна запремина и узорак из промијешаног сакупљеног материјала', 'Мочу собирают в одну градуированную ёмкость в течение 24 часов, в лабораторию сдают измеренный общий объём и порцию из перемешанного сбора', 'Der Urin wird 24 Stunden in einem Messbehälter gesammelt, ins Labor kommen das gemessene Gesamtvolumen und eine Probe aus dem durchmischten Sammelurin', 'İdrar 24 saat boyunca dereceli tek bir kapta toplanır, laboratuvara ölçülen toplam hacim ve karıştırılmış toplamadan alınan örnek götürülür', 'Clarifying protein found in a single portion, follow-up of kidney disease, monitoring of high blood pressure in pregnancy, tracking change during treatment', 'Provjera proteina nađenih u jednokratnom uzorku, praćenje bubrežnih bolesti, kontrola povišenog pritiska u trudnoći, praćenje promjene tokom liječenja', 'Провјера протеина нађених у једнократном узорку, праћење бубрежних болести, контрола повишеног притиска у трудноћи, праћење промјене током лијечења', 'Уточнение белка, найденного в разовой порции, наблюдение при болезнях почек, контроль повышенного давления при беременности, отслеживание динамики на фоне лечения', 'Abklärung von Eiweiß aus einer Einzelprobe, Verlaufskontrolle bei Nierenerkrankungen, Überwachung bei Bluthochdruck in der Schwangerschaft, Beurteilung des Verlaufs unter Therapie', 'Tek örnekte bulunan proteinin doğrulanması, böbrek hastalıklarının takibi, gebelikte yüksek tansiyonun izlenmesi, tedavi sırasında değişimin izlenmesi', 'The collection starts after the first morning portion has been discarded and ends with the first portion of the following morning, which is included; the container is kept in a cool place, drinking stays as usual and hard exercise on the collection day is better avoided', 'Sakupljanje počinje nakon što se prva jutarnja porcija baci, a završava prvom porcijom narednog jutra koja se uključuje; posuda se drži na hladnom, unos tečnosti je uobičajen, a veće fizičke napore na dan sakupljanja bolje je izbjegavati', 'Сакупљање почиње након што се прва јутарња порција баци, а завршава првом порцијом наредног јутра која се укључује; посуда се држи на хладном, унос течности је уобичајен, а веће физичке напоре на дан сакупљања боље је избјегавати', 'Сбор начинают после того, как первая утренняя порция слита, и заканчивают первой порцией следующего утра, которую включают в сбор; ёмкость держат в прохладном месте, питьевой режим обычный, тяжёлых нагрузок в день сбора лучше избегать', 'Das Sammeln beginnt nach dem Verwerfen der ersten Morgenportion und endet mit der ersten Portion am nächsten Morgen, die mitgesammelt wird; der Behälter wird kühl gelagert, die Trinkmenge bleibt gewohnt, starke Belastung am Sammeltag besser vermeiden', 'Toplama ilk sabah idrarı atıldıktan sonra başlar ve ertesi sabahın ilk idrarı da eklenerek biter; kap serin yerde tutulur, sıvı alımı olağan sürer, toplama gününde ağır egzersizden kaçınmak daha iyidir', 'An increased daily protein loss may be related to the state of the kidney filters, high blood pressure or systemic conditions. The amount and its cause are assessed by a doctor together with blood tests', 'Povećan dnevni gubitak proteina može biti povezan sa stanjem bubrežnih filtera, visokim pritiskom ili sistemskim bolestima. Količinu i uzrok ljekar procjenjuje zajedno sa analizama krvi', 'Повећан дневни губитак протеина може бити повезан са стањем бубрежних филтера, високим притиском или системским болестима. Количину и узрок љекар процјењује заједно са анализама крви', 'Повышенная суточная потеря белка может быть связана с состоянием почечных фильтров, высоким давлением или системными заболеваниями. Величину и причину врач оценивает вместе с анализами крови', 'Ein erhöhter täglicher Eiweißverlust kann mit dem Zustand der Nierenfilter, hohem Blutdruck oder systemischen Erkrankungen zusammenhängen. Menge und Ursache beurteilt der Arzt zusammen mit Blutwerten', 'Günlük protein kaybının artması böbrek süzgeçlerinin durumu, yüksek tansiyon veya sistemik hastalıklarla ilişkili olabilir. Miktarı ve nedenini hekim kan testleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bilirubin-in-urine'), 'Detection of a bile pigment that is practically absent from the urine of a healthy person', 'Otkrivanje žučnog pigmenta kojeg u mokraći zdrave osobe praktično nema', 'Откривање жучног пигмента којег у мокраћи здраве особе практично нема', 'Обнаружение жёлчного пигмента, которого в моче здорового человека практически нет', 'Nachweis eines Gallenfarbstoffs, der im Urin eines gesunden Menschen praktisch nicht vorkommt', 'Sağlıklı kişinin idrarında neredeyse bulunmayan bir safra pigmentinin saptanması', 'A fresh single portion is tested with a reagent strip as part of the routine urinalysis and confirmed by a separate method if needed', 'Svjež jednokratni uzorak ispituje se test-trakom u okviru opšte analize mokraće, a po potrebi se potvrđuje posebnom metodom', 'Свјеж једнократни узорак испитује се тест-траком у оквиру опште анализе мокраће, а по потреби се потврђује посебном методом', 'Свежую разовую порцию проверяют тест-полоской в составе общего анализа мочи, при необходимости подтверждают отдельным методом', 'Eine frische Einzelprobe wird im Rahmen der Urinuntersuchung mit einem Teststreifen geprüft und bei Bedarf mit einem gesonderten Verfahren bestätigt', 'Taze tek örnek, tam idrar tetkiki kapsamında test çubuğuyla incelenir, gerekirse ayrı bir yöntemle doğrulanır', 'Yellowing of the skin and eyes, dark urine, work-up of liver and bile duct conditions, monitoring during treatment that puts a load on the liver', 'Žuta prebojenost kože i očiju, tamna mokraća, obrada bolesti jetre i žučnih puteva, kontrola tokom terapije koja opterećuje jetru', 'Жута пребојеност коже и очију, тамна мокраћа, обрада болести јетре и жучних путева, контрола током терапије која оптерећује јетру', 'Желтушность кожи и глаз, тёмная моча, обследование при болезнях печени и жёлчных путей, контроль при лечении, дающем нагрузку на печень', 'Gelbfärbung von Haut und Augen, dunkler Urin, Abklärung von Leber- und Gallenwegserkrankungen, Kontrolle bei leberbelastender Therapie', 'Ciltte ve gözlerde sararma, koyu renkli idrar, karaciğer ve safra yolu hastalıklarının araştırılması, karaciğeri zorlayan tedavilerde izlem', 'A fresh portion after hygiene, the container is closed and delivered quickly, and the sample is kept away from light because bilirubin breaks down during storage in the light', 'Svjež uzorak poslije higijene, posuda se zatvara i brzo nosi u laboratoriju, a uzorak se čuva od svjetlosti jer se bilirubin razgrađuje stajanjem na svjetlu', 'Свјеж узорак послије хигијене, посуда се затвара и брзо носи у лабораторију, а узорак се чува од свјетлости јер се билирубин разграђује стајањем на свјетлу', 'Свежая порция после гигиены, контейнер закрывают и быстро доставляют в лабораторию, образец берегут от света — билирубин разрушается при хранении на свету', 'Frische Probe nach der Hygiene, der Behälter wird verschlossen und zügig abgegeben, die Probe vor Licht schützen, da Bilirubin bei Lichteinwirkung zerfällt', 'Hijyen sonrası taze örnek, kap kapatılır ve hızla laboratuvara ulaştırılır, örnek ışıktan korunur çünkü bilirubin ışıkta bekleyince bozulur', 'The appearance of bilirubin may be related to liver function or to the flow of bile. It is a reason for further examination, and the doctor decides what that should be', 'Pojava bilirubina može biti povezana sa radom jetre ili sa otjecanjem žuči. To je razlog za dalju obradu, a njen smjer određuje ljekar', 'Појава билирубина може бити повезана са радом јетре или са отјецањем жучи. То је разлог за даљу обраду, а њен смјер одређује љекар', 'Появление билирубина может быть связано с работой печени или с оттоком жёлчи. Это повод для дальнейшего обследования, его направление определяет врач', 'Auftretendes Bilirubin kann mit der Leberfunktion oder dem Gallenabfluss zusammenhängen. Das ist ein Anlass für weitere Abklärung, deren Richtung der Arzt festlegt', 'İdrarda bilirubin görülmesi karaciğerin işleyişi veya safra akışıyla ilişkili olabilir. Bu, ileri incelemeyi gerektirir, yönünü hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urea-in-urine'), 'Measurement of urea, the end product of protein metabolism that the kidneys remove', 'Mjerenje uree, krajnjeg produkta metabolizma bjelančevina koji izlučuju bubrezi', 'Мјерење урее, крајњег продукта метаболизма бјеланчевина који излучују бубрези', 'Измерение мочевины — конечного продукта белкового обмена, который выводят почки', 'Bestimmung von Harnstoff, dem Endprodukt des Eiweißstoffwechsels, das über die Nieren ausgeschieden wird', 'Protein metabolizmasının son ürünü olan ve böbreklerle atılan ürenin ölçümü', 'Usually a 24-hour collection is analysed, which shows the total nitrogen output, less often a single portion is used', 'Obično se analizira 24-časovno sakupljanje, koje pokazuje ukupno izlučivanje azota, rjeđe se koristi jednokratni uzorak', 'Обично се анализира 24-часовно сакупљање, које показује укупно излучивање азота, рјеђе се користи једнократни узорак', 'Обычно анализируют суточный сбор, показывающий общее выведение азота, реже используют разовую порцию', 'Meist wird Sammelurin über 24 Stunden untersucht, der die gesamte Stickstoffausscheidung zeigt, seltener genügt eine Einzelprobe', 'Genellikle toplam azot atılımını gösteren 24 saatlik toplama incelenir, daha seyrek olarak tek seferlik örnek kullanılır', 'Assessment of the excretory function of the kidneys, monitoring of protein metabolism, follow-up in kidney and liver disease, nitrogen balance calculation during therapeutic nutrition', 'Procjena izlučne funkcije bubrega, praćenje metabolizma bjelančevina, kontrola kod bolesti bubrega i jetre, izračunavanje azotnog bilansa kod posebne ishrane', 'Процјена излучне функције бубрега, праћење метаболизма бјеланчевина, контрола код болести бубрега и јетре, израчунавање азотног биланса код посебне исхране', 'Оценка выделительной функции почек, контроль белкового обмена, наблюдение при болезнях почек и печени, расчёт азотистого баланса при лечебном питании', 'Beurteilung der Ausscheidungsfunktion der Nieren, Kontrolle des Eiweißstoffwechsels, Verlauf bei Nieren- und Lebererkrankungen, Berechnung der Stickstoffbilanz bei besonderer Ernährungstherapie', 'Böbreklerin atım işlevinin değerlendirilmesi, protein metabolizmasının izlenmesi, böbrek ve karaciğer hastalıklarında takip, özel beslenme tedavisinde azot dengesi hesabı', 'For the 24-hour collection the first morning portion is not included, all further urine is gathered until the next morning; eating stays as usual during the collection days, there is no need to change the amount of protein, and the container is kept cool', 'Kod 24-časovnog sakupljanja prva jutarnja porcija se ne uključuje, sva naredna mokraća skuplja se do narednog jutra; ishrana tokom dana sakupljanja ostaje uobičajena, količinu bjelančevina nije potrebno mijenjati, a posuda se drži na hladnom', 'Код 24-часовног сакупљања прва јутарња порција се не укључује, сва наредна мокраћа скупља се до наредног јутра; исхрана током дана сакупљања остаје уобичајена, количину бјеланчевина није потребно мијењати, а посуда се држи на хладном', 'При суточном сборе первую утреннюю порцию не включают, всю последующую мочу собирают до следующего утра; питание в дни сбора остаётся обычным, количество белка менять не нужно, ёмкость держат в прохладе', 'Beim Sammeln über 24 Stunden wird die erste Morgenportion nicht mitgesammelt, der weitere Urin bis zum nächsten Morgen aufgefangen; die Ernährung bleibt an den Sammeltagen gewohnt, die Eiweißmenge muss nicht geändert werden, der Behälter wird kühl gelagert', '24 saatlik toplamada ilk sabah idrarı dahil edilmez, sonraki tüm idrar ertesi sabaha kadar biriktirilir; toplama günlerinde beslenme olağan sürer, protein miktarını değiştirmek gerekmez, kap serin yerde saklanır', 'Deviations may be related to the amount of protein in the diet, fluid intake, kidney or liver function. The value is interpreted together with blood urea, which is done by a doctor', 'Odstupanja mogu biti povezana sa količinom bjelančevina u ishrani, unosom tečnosti, radom bubrega ili jetre. Nalaz se tumači zajedno sa ureom u krvi, a to radi ljekar', 'Одступања могу бити повезана са количином бјеланчевина у исхрани, уносом течности, радом бубрега или јетре. Налаз се тумачи заједно са уреом у крви, а то ради љекар', 'Отклонения могут быть связаны с количеством белка в питании, объёмом выпитой жидкости, работой почек или печени. Результат интерпретируют вместе с мочевиной крови, это делает врач', 'Abweichungen können mit der Eiweißmenge in der Nahrung, der Trinkmenge, der Nieren- oder Leberfunktion zusammenhängen. Der Wert wird zusammen mit dem Harnstoff im Blut vom Arzt beurteilt', 'Sapmalar beslenmedeki protein miktarı, sıvı alımı, böbrek veya karaciğer işleviyle ilişkili olabilir. Sonuç kandaki üreyle birlikte hekim tarafından yorumlanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urobilinogen-in-urine'), 'Measurement of a substance formed from bilirubin in the intestine, part of which returns to the blood and is excreted by the kidneys', 'Određivanje materije koja nastaje od bilirubina u crijevima, a dijelom se vraća u krv i izlučuje preko bubrega', 'Одређивање материје која настаје од билирубина у цријевима, а дијелом се враћа у крв и излучује преко бубрега', 'Определение вещества, которое образуется из билирубина в кишечнике, частично возвращается в кровь и выводится почками', 'Bestimmung eines Stoffes, der im Darm aus Bilirubin entsteht, teilweise ins Blut zurückkehrt und über die Nieren ausgeschieden wird', 'Bağırsakta bilirubinden oluşan, bir kısmı kana geri dönüp böbreklerle atılan maddenin ölçümü', 'A fresh single portion is checked with a reagent strip, usually together with the other parameters of a routine urinalysis', 'Svjež jednokratni uzorak provjerava se test-trakom, obično uz ostale parametre opšte analize mokraće', 'Свјеж једнократни узорак провјерава се тест-траком, обично уз остале параметре опште анализе мокраће', 'Свежую разовую порцию проверяют тест-полоской, обычно вместе с остальными показателями общего анализа мочи', 'Eine frische Einzelprobe wird mit einem Teststreifen geprüft, meist gemeinsam mit den übrigen Werten der Urinuntersuchung', 'Taze tek örnek, genellikle tam idrar tetkikinin diğer değerleriyle birlikte test çubuğuyla incelenir', 'Work-up of liver disease, conditions with increased breakdown of red blood cells, complaints of yellow skin, changes in the colour of urine or stool', 'Obrada bolesti jetre, stanja sa pojačanom razgradnjom crvenih krvnih zrnaca, tegobe sa žutom prebojenošću kože, promjena boje mokraće ili stolice', 'Обрада болести јетре, стања са појачаном разградњом црвених крвних зрнаца, тегобе са жутом пребојеношћу коже, промјена боје мокраће или столице', 'Обследование при болезнях печени, состояния с усиленным распадом эритроцитов, жалобы на желтушность кожи, изменение цвета мочи или кала', 'Abklärung von Lebererkrankungen, Zustände mit vermehrtem Abbau roter Blutkörperchen, Beschwerden mit gelblicher Haut, Veränderungen der Farbe von Urin oder Stuhl', 'Karaciğer hastalıklarının araştırılması, alyuvarların hızlı yıkıldığı durumlar, ciltte sararma şikayeti, idrar veya dışkı renginde değişiklik', 'A fresh portion, preferably the morning one, after hygiene; it should be examined quickly and kept in the dark, since urobilinogen breaks down in the light', 'Svjež uzorak, najbolje jutarnji, poslije higijene; treba ga brzo obraditi i čuvati u mraku jer se urobilinogen razgrađuje na svjetlu', 'Свјеж узорак, најбоље јутарњи, послије хигијене; треба га брзо обрадити и чувати у мраку јер се уробилиноген разграђује на свјетлу', 'Свежая порция, лучше утренняя, после гигиены; исследовать нужно быстро и хранить образец в темноте, так как уробилиноген разрушается на свету', 'Frische Probe, am besten der Morgenurin, nach der Hygiene; sie sollte rasch untersucht und dunkel aufbewahrt werden, da Urobilinogen im Licht zerfällt', 'Hijyen sonrası taze, tercihen sabah örneği; ürobilinojen ışıkta bozulduğu için örnek hızla incelenmeli ve karanlıkta saklanmalıdır', 'Deviations may be related to liver function, the bile ducts, faster breakdown of red blood cells or certain medications. The result is assessed together with bilirubin in blood and urine, which is done by a doctor', 'Odstupanja mogu biti povezana sa radom jetre, žučnim putevima, bržom razgradnjom crvenih krvnih zrnaca ili sa nekim lijekovima. Nalaz se procjenjuje zajedno sa bilirubinom u krvi i mokraći, a to radi ljekar', 'Одступања могу бити повезана са радом јетре, жучним путевима, бржом разградњом црвених крвних зрнаца или са неким лијековима. Налаз се процјењује заједно са билирубином у крви и мокраћи, а то ради љекар', 'Отклонения могут быть связаны с работой печени, состоянием жёлчных путей, ускоренным распадом эритроцитов или с приёмом некоторых препаратов. Результат оценивают вместе с билирубином крови и мочи, это делает врач', 'Abweichungen können mit der Leberfunktion, den Gallenwegen, einem schnelleren Abbau roter Blutkörperchen oder bestimmten Medikamenten zusammenhängen. Der Wert wird zusammen mit Bilirubin in Blut und Urin vom Arzt beurteilt', 'Sapmalar karaciğer işlevi, safra yolları, alyuvarların daha hızlı yıkımı veya bazı ilaçlarla ilişkili olabilir. Sonuç kandaki ve idrardaki bilirubinle birlikte hekim tarafından değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ca-125'), 'Blood test for the glycoprotein CA 125, used as a tumour marker when monitoring the condition of the ovaries and pelvic organs', 'Analiza krvi na glikoprotein CA 125, koji se koristi kao tumorski marker pri praćenju stanja jajnika i organa male karlice', 'Анализа крви на гликопротеин CA 125, који се користи као туморски маркер при праћењу стања јајника и органа мале карлице', 'Анализ крови на гликопротеин CA 125, который используют как онкомаркер при наблюдении за состоянием яичников и органов малого таза', 'Bluttest auf das Glykoprotein CA 125, das als Tumormarker bei der Verlaufsbeobachtung der Eierstöcke und der Beckenorgane verwendet wird', 'Yumurtalıkların ve pelvis organlarının durumunun izlenmesinde tümör belirteci olarak kullanılan CA 125 glikoproteini için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Toplardamardan kan alınması, birkaç dakika sürer', 'Ordered by a doctor when a pelvic mass is being examined, follow-up monitoring of patients already receiving treatment, control after completed treatment', 'Po uputu ljekara pri pregledu promjena u maloj karlici, praćenje pacijenata koji već primaju terapiju, kontrola poslije završenog liječenja', 'По упуту љекара при прегледу промјена у малој карлици, праћење пацијената који већ примају терапију, контрола послије завршеног лијечења', 'По назначению врача при обследовании образований в малом тазу, динамическое наблюдение пациентов, уже получающих лечение, контроль после завершённого лечения', 'Auf ärztliche Anordnung bei der Abklärung von Raumforderungen im Becken, Verlaufskontrolle bei Patientinnen, die bereits behandelt werden, Kontrolle nach abgeschlossener Behandlung', 'Pelviste saptanan oluşumların değerlendirilmesinde hekim isteğiyle, tedavi almakta olan hastaların izleminde, tamamlanan tedaviden sonraki kontrollerde', 'No special preparation is usually required; the doctor may ask for the sample to be taken outside the days of menstruation', 'Posebna priprema obično nije potrebna; ljekar može tražiti da se krv uzme van dana menstruacije', 'Посебна припрема обично није потребна; љекар може тражити да се крв узме ван дана менструације', 'Специальной подготовки обычно не требуется; врач может попросить сдать кровь вне дней менструации', 'In der Regel ist keine besondere Vorbereitung nötig; der Arzt kann darum bitten, die Blutentnahme außerhalb der Menstruationstage durchzuführen', 'Genellikle özel bir hazırlık gerekmez; hekim, kanın adet günleri dışında alınmasını isteyebilir', 'An increase also occurs with benign conditions — endometriosis, fibroids, inflammation of the pelvic organs, liver disease, during menstruation and pregnancy — and on its own it does not mean an oncological disease. Only a doctor determines what the result means, comparing it with the examination and ultrasound', 'Povećanje se javlja i kod benignih stanja — endometrioze, mioma, upale organa male karlice, bolesti jetre, tokom menstruacije i trudnoće — i samo po sebi ne znači onkološko oboljenje. Značenje nalaza određuje isključivo ljekar, upoređujući ga sa pregledom i ultrazvukom', 'Повећање се јавља и код бенигних стања — ендометриозе, миома, упале органа мале карлице, болести јетре, током менструације и трудноће — и само по себи не значи онколошко обољење. Значење налаза одређује искључиво љекар, упоређујући га са прегледом и ултразвуком', 'Повышение бывает при доброкачественных состояниях — эндометриозе, миоме, воспалении органов малого таза, заболеваниях печени, во время менструации и беременности — и само по себе не означает онкологического заболевания. Значение результата определяет только врач, сопоставляя его с осмотром и УЗИ', 'Ein Anstieg kommt auch bei gutartigen Zuständen vor — Endometriose, Myomen, Entzündungen der Beckenorgane, Lebererkrankungen, während der Menstruation und in der Schwangerschaft — und bedeutet für sich genommen keine onkologische Erkrankung. Was der Wert bedeutet, entscheidet allein der Arzt im Zusammenhang mit Untersuchung und Ultraschall', 'Yükselme endometriozis, miyom, pelvik iltihaplanma, karaciğer hastalıkları gibi iyi huylu durumlarda, adet döneminde ve gebelikte de görülür ve tek başına onkolojik bir hastalık anlamına gelmez. Sonucun anlamını yalnızca hekim, muayene ve ultrason bulgularıyla birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ca-15-3'), 'Blood test for the tumour marker CA 15-3, used mainly when monitoring the condition of the breast', 'Analiza krvi na tumorski marker CA 15-3, koji se prvenstveno koristi pri praćenju stanja dojke', 'Анализа крви на туморски маркер CA 15-3, који се првенствено користи при праћењу стања дојке', 'Анализ крови на онкомаркер CA 15-3, который применяют преимущественно при наблюдении за состоянием молочных желёз', 'Bluttest auf den Tumormarker CA 15-3, der vor allem bei der Verlaufsbeobachtung der Brustdrüse eingesetzt wird', 'Başlıca meme dokusunun durumunun izlenmesinde kullanılan CA 15-3 tümör belirteci için kan testi', 'Venous blood draw, the procedure takes a few minutes', 'Uzimanje venske krvi, postupak traje nekoliko minuta', 'Узимање венске крви, поступак траје неколико минута', 'Забор венозной крови, процедура занимает несколько минут', 'Venöse Blutentnahme, der Vorgang dauert wenige Minuten', 'Venöz kan alımı, işlem birkaç dakika sürer', 'Ordered by a doctor for follow-up monitoring of patients already receiving treatment and for subsequent control; it is not used as a screening test in healthy people', 'Po uputu ljekara radi praćenja pacijenata koji već primaju terapiju i kasnijih kontrola; ne koristi se kao skrining kod zdravih osoba', 'По упуту љекара ради праћења пацијената који већ примају терапију и каснијих контрола; не користи се као скрининг код здравих особа', 'По назначению врача для динамического наблюдения пациентов, уже получающих лечение, и последующего контроля; как скрининговый тест у здоровых людей не используется', 'Auf ärztliche Anordnung zur Verlaufskontrolle bei Patientinnen, die bereits behandelt werden, und zur weiteren Nachsorge; als Screening bei Gesunden wird er nicht eingesetzt', 'Tedavi almakta olan hastaların izlemi ve sonraki kontroller için hekim isteğiyle; sağlıklı kişilerde tarama testi olarak kullanılmaz', 'No special preparation is required; for repeat tests it is better to use the same laboratory each time', 'Posebna priprema nije potrebna; kod ponovljenih analiza poželjno je birati istu laboratoriju', 'Посебна припрема није потребна; код поновљених анализа пожељно је бирати исту лабораторију', 'Специальной подготовки не требуется; при повторных анализах желательно сдавать кровь в одной и той же лаборатории', 'Eine besondere Vorbereitung ist nicht nötig; bei Verlaufskontrollen sollte möglichst immer dasselbe Labor genutzt werden', 'Özel bir hazırlık gerekmez; tekrarlanan ölçümlerde aynı laboratuvarın tercih edilmesi uygundur', 'A moderate increase occurs with benign breast changes, liver disease, autoimmune and inflammatory processes, during pregnancy and breastfeeding, and on its own it does not mean an oncological disease. Only the treating doctor assesses the result, usually from the trend of several measurements', 'Umjereno povećanje javlja se kod benignih promjena dojke, bolesti jetre, autoimunih i upalnih procesa, u trudnoći i tokom dojenja i samo po sebi ne znači onkološko oboljenje. Nalaz tumači isključivo ljekar, najčešće prema kretanju više mjerenja', 'Умјерено повећање јавља се код бенигних промјена дојке, болести јетре, аутоимуних и упалних процеса, у трудноћи и током дојења и само по себи не значи онколошко обољење. Налаз тумачи искључиво љекар, најчешће према кретању више мјерења', 'Умеренное повышение встречается при доброкачественных изменениях молочных желёз, заболеваниях печени, аутоиммунных и воспалительных процессах, при беременности и кормлении грудью и само по себе не означает онкологического заболевания. Оценивает результат только лечащий врач, обычно по динамике нескольких измерений', 'Ein mäßiger Anstieg kommt bei gutartigen Veränderungen der Brust, Lebererkrankungen, autoimmunen und entzündlichen Prozessen sowie in Schwangerschaft und Stillzeit vor und bedeutet für sich genommen keine onkologische Erkrankung. Den Wert beurteilt ausschließlich der behandelnde Arzt, meist anhand des Verlaufs mehrerer Messungen', 'Ölçülü yükselmeler memenin iyi huylu değişikliklerinde, karaciğer hastalıklarında, otoimmün ve iltihabi süreçlerde, gebelikte ve emzirme döneminde de görülür ve tek başına onkolojik bir hastalık anlamına gelmez. Sonucu yalnızca tedaviyi yürüten hekim, genellikle birkaç ölçümün seyrine bakarak değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ca-19-9'), 'Blood test for the carbohydrate antigen CA 19-9, used as a tumour marker when monitoring the pancreas and the bile ducts', 'Analiza krvi na ugljenohidratni antigen CA 19-9, koji se koristi kao tumorski marker pri praćenju pankreasa i žučnih puteva', 'Анализа крви на угљенохидратни антиген CA 19-9, који се користи као туморски маркер при праћењу панкреаса и жучних путева', 'Анализ крови на углеводный антиген CA 19-9, который используют как онкомаркер при наблюдении за поджелудочной железой и желчевыводящими путями', 'Bluttest auf das Kohlenhydrat-Antigen CA 19-9, das als Tumormarker bei der Verlaufsbeobachtung von Bauchspeicheldrüse und Gallenwegen verwendet wird', 'Pankreas ve safra yollarının izlenmesinde tümör belirteci olarak kullanılan CA 19-9 karbonhidrat antijeni için kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert wenige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Ordered by a doctor when the digestive organs are being examined, follow-up monitoring during treatment and afterwards', 'Po uputu ljekara pri pregledu organa za varenje, praćenje tokom liječenja i poslije njega', 'По упуту љекара при прегледу органа за варење, праћење током лијечења и послије њега', 'По назначению врача при обследовании органов пищеварения, динамическое наблюдение в процессе лечения и после него', 'Auf ärztliche Anordnung bei der Abklärung der Verdauungsorgane, Verlaufskontrolle während und nach einer Behandlung', 'Sindirim organlarının değerlendirilmesinde hekim isteğiyle, tedavi sırasında ve sonrasında izlem amacıyla', 'No special preparation is usually required; the laboratory may ask for a morning sample on an empty stomach', 'Posebna priprema obično nije potrebna; laboratorija može tražiti da se krv uzme ujutru natašte', 'Посебна припрема обично није потребна; лабораторија може тражити да се крв узме ујутру наташте', 'Специальной подготовки обычно не требуется; лаборатория может попросить сдать кровь утром натощак', 'In der Regel ist keine besondere Vorbereitung nötig; das Labor kann eine morgendliche Blutentnahme nüchtern verlangen', 'Genellikle özel hazırlık gerekmez; laboratuvar sabah aç karnına kan alınmasını isteyebilir', 'An increase is more often due to benign causes — inflammation of the pancreas, impaired bile flow, gallstones, liver disease, diabetes mellitus — and on its own it does not mean an oncological disease. Some people do not produce this antigen because of an inherited trait, so their result stays low regardless of their condition; only a doctor interprets it', 'Povećanje je češće posljedica benignih uzroka — upale pankreasa, otežanog oticanja žuči, kamenaca u žučnoj kesi, bolesti jetre, šećerne bolesti — i samo po sebi ne znači onkološko oboljenje. Kod dijela ljudi ovaj antigen se nasljedno ne stvara, pa nalaz ostaje nizak bez obzira na stanje; tumači ga isključivo ljekar', 'Повећање је чешће посљедица бенигних узрока — упале панкреаса, отежаног отицања жучи, каменаца у жучној кеси, болести јетре, шећерне болести — и само по себи не значи онколошко обољење. Код дијела људи овај антиген се насљедно не ствара, па налаз остаје низак без обзира на стање; тумачи га искључиво љекар', 'Повышение чаще связано с доброкачественными причинами — воспалением поджелудочной железы, нарушением оттока желчи, камнями в желчном пузыре, заболеваниями печени, сахарным диабетом — и само по себе не означает онкологического заболевания. У части людей этот антиген не вырабатывается из-за наследственной особенности, поэтому результат бывает низким независимо от состояния; трактует его только врач', 'Ein Anstieg hat häufiger gutartige Ursachen — Entzündung der Bauchspeicheldrüse, gestörten Gallenabfluss, Gallensteine, Lebererkrankungen, Diabetes mellitus — und bedeutet für sich genommen keine onkologische Erkrankung. Ein Teil der Menschen bildet dieses Antigen erblich bedingt nicht, sodass der Wert unabhängig vom Zustand niedrig bleibt; die Beurteilung übernimmt ausschließlich der Arzt', 'Yükselme çoğunlukla pankreas iltihabı, safra akışının bozulması, safra kesesi taşları, karaciğer hastalıkları, diyabet gibi iyi huylu nedenlere bağlıdır ve tek başına onkolojik bir hastalık anlamına gelmez. Bazı kişilerde bu antijen kalıtsal olarak üretilmez, bu nedenle sonuç durumdan bağımsız olarak düşük çıkabilir; değerlendirmeyi yalnızca hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cea'), 'Blood test for a protein produced in fetal tissue that is present in small amounts in adults; it is used as a tumour marker when monitoring the digestive organs', 'Analiza krvi na bjelančevinu koja se stvara u tkivima ploda, a kod odraslih se nalazi u malim količinama; koristi se kao tumorski marker pri praćenju organa za varenje', 'Анализа крви на бјеланчевину која се ствара у ткивима плода, а код одраслих се налази у малим количинама; користи се као туморски маркер при праћењу органа за варење', 'Анализ крови на белок, который вырабатывается в тканях плода и у взрослых определяется в небольшом количестве; применяется как онкомаркер при наблюдении за органами пищеварения', 'Bluttest auf ein Eiweiß, das im fetalen Gewebe gebildet wird und bei Erwachsenen nur in geringer Menge vorkommt; es dient als Tumormarker bei der Verlaufsbeobachtung der Verdauungsorgane', 'Fetal dokularda üretilen ve erişkinlerde az miktarda bulunan bir protein için kan testi; sindirim organlarının izleminde tümör belirteci olarak kullanılır', 'Venous blood draw, the whole procedure takes a few minutes', 'Uzimanje venske krvi, cijeli postupak traje nekoliko minuta', 'Узимање венске крви, цијели поступак траје неколико минута', 'Забор венозной крови, вся процедура занимает несколько минут', 'Venöse Blutentnahme, der gesamte Vorgang dauert wenige Minuten', 'Venöz kan alımı, işlemin tamamı birkaç dakika sürer', 'Ordered by a doctor when the gastrointestinal tract is being examined, follow-up monitoring of patients already receiving treatment, regular control afterwards', 'Po uputu ljekara pri pregledu probavnog trakta, praćenje pacijenata koji već primaju terapiju, redovne kontrole kasnije', 'По упуту љекара при прегледу пробавног тракта, праћење пацијената који већ примају терапију, редовне контроле касније', 'По назначению врача при обследовании желудочно-кишечного тракта, динамическое наблюдение пациентов, уже получающих лечение, регулярный контроль в дальнейшем', 'Auf ärztliche Anordnung bei der Abklärung des Magen-Darm-Trakts, Verlaufskontrolle bei Patienten, die bereits behandelt werden, regelmäßige Kontrollen danach', 'Sindirim sisteminin değerlendirilmesinde hekim isteğiyle, tedavi almakta olan hastaların izleminde, sonrasındaki düzenli kontrollerde', 'No special preparation is required; the doctor should know whether the patient smokes, as smoking affects the result', 'Posebna priprema nije potrebna; ljekaru je važno da zna da li pacijent puši, jer pušenje utiče na nalaz', 'Посебна припрема није потребна; љекару је важно да зна да ли пацијент пуши, јер пушење утиче на налаз', 'Специальной подготовки не требуется; врачу важно знать, курит ли пациент, — курение влияет на результат', 'Eine besondere Vorbereitung ist nicht nötig; der Arzt sollte wissen, ob der Patient raucht, denn Rauchen beeinflusst den Wert', 'Özel bir hazırlık gerekmez; sigara kullanımı sonucu etkilediği için hekimin bunu bilmesi önemlidir', 'An increase occurs in smokers and with benign conditions — inflammatory bowel disease, peptic ulcer, polyps, diseases of the liver, lungs and thyroid — and on its own it does not mean an oncological disease. The doctor assesses the result, usually by its trend rather than by a single measurement', 'Povećanje se javlja kod pušača i kod benignih stanja — upalnih bolesti crijeva, čira, polipa, bolesti jetre, pluća i štitne žlijezde — i samo po sebi ne znači onkološko oboljenje. Nalaz procjenjuje ljekar, češće prema kretanju vrijednosti nego prema jednom mjerenju', 'Повећање се јавља код пушача и код бенигних стања — упалних болести цријева, чира, полипа, болести јетре, плућа и штитне жлијезде — и само по себи не значи онколошко обољење. Налаз процјењује љекар, чешће према кретању вриједности него према једном мјерењу', 'Повышение встречается у курящих и при доброкачественных состояниях — воспалительных заболеваниях кишечника, язвенной болезни, полипах, заболеваниях печени, лёгких и щитовидной железы — и само по себе не означает онкологического заболевания. Результат оценивает врач, чаще по изменению в динамике, а не по одному измерению', 'Ein Anstieg kommt bei Rauchern und bei gutartigen Zuständen vor — chronisch-entzündlichen Darmerkrankungen, Magengeschwüren, Polypen, Erkrankungen von Leber, Lunge und Schilddrüse — und bedeutet für sich genommen keine onkologische Erkrankung. Der Arzt beurteilt den Wert meist anhand des Verlaufs und nicht anhand einer einzelnen Messung', 'Yükselme sigara içenlerde ve iltihabi bağırsak hastalıkları, ülser, polipler, karaciğer, akciğer ve tiroid hastalıkları gibi iyi huylu durumlarda da görülür; tek başına onkolojik bir hastalık anlamına gelmez. Hekim sonucu genellikle tek bir ölçüme değil, değerlerin seyrine bakarak değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'free-psa'), 'Blood test for the fraction of prostate-specific antigen that is not bound to plasma proteins; it is assessed together with total PSA as a ratio', 'Analiza krvi na onaj dio prostata-specifičnog antigena koji nije vezan za bjelančevine plazme; procjenjuje se zajedno sa ukupnim PSA, kao njihov odnos', 'Анализа крви на онај дио простата-специфичног антигена који није везан за бјеланчевине плазме; процјењује се заједно са укупним PSA, као њихов однос', 'Анализ крови на ту часть простат-специфического антигена, которая не связана с белками плазмы; оценивается вместе с общим PSA в виде их соотношения', 'Bluttest auf den Anteil des prostataspezifischen Antigens, der nicht an Plasmaeiweiße gebunden ist; er wird zusammen mit dem Gesamt-PSA als Verhältnis beurteilt', 'Prostata özgü antijenin plazma proteinlerine bağlı olmayan bölümünü ölçen kan testi; toplam PSA ile birlikte oran olarak değerlendirilir', 'Venous blood draw, usually from the same sample as total PSA', 'Uzimanje venske krvi, obično iz istog uzorka kao i ukupni PSA', 'Узимање венске крви, обично из истог узорка као и укупни PSA', 'Забор венозной крови, обычно из той же пробы, что и общий PSA', 'Venöse Blutentnahme, meist aus derselben Probe wie das Gesamt-PSA', 'Venöz kan alımı, genellikle toplam PSA ile aynı örnekten yapılır', 'Ordered by a urologist when a total PSA result needs clarification, follow-up monitoring of the prostate over time', 'Po uputu urologa kada nalaz ukupnog PSA treba dodatno razjasniti, praćenje stanja prostate tokom vremena', 'По упуту уролога када налаз укупног PSA треба додатно разјаснити, праћење стања простате током времена', 'По назначению уролога, когда нужно уточнить результат общего PSA, наблюдение за состоянием простаты в динамике', 'Auf Anordnung des Urologen, wenn ein Gesamt-PSA-Wert genauer eingeordnet werden soll, Verlaufsbeobachtung der Prostata', 'Toplam PSA sonucunun netleştirilmesi gerektiğinde ürolog isteğiyle, prostat durumunun zaman içinde izlenmesinde', 'Avoid ejaculation, cycling and intense physical activity for a few days beforehand; the sample is taken before a digital rectal examination or several days after it', 'Nekoliko dana ranije uzdržati se od ejakulacije, vožnje bicikla i jakog fizičkog napora; krv se uzima prije digitorektalnog pregleda ili nekoliko dana poslije njega', 'Неколико дана раније уздржати се од ејакулације, вожње бицикла и јаког физичког напора; крв се узима прије дигиторекталног прегледа или неколико дана послије њега', 'За несколько дней воздержаться от эякуляции, езды на велосипеде и интенсивных нагрузок; кровь сдают до пальцевого ректального исследования или спустя несколько дней после него', 'Einige Tage vorher auf Ejakulation, Radfahren und starke körperliche Belastung verzichten; die Blutentnahme erfolgt vor einer digital-rektalen Untersuchung oder einige Tage danach', 'Birkaç gün önceden ejakülasyondan, bisiklet kullanımından ve yoğun fiziksel aktiviteden kaçınılmalı; kan, parmakla rektal muayeneden önce veya birkaç gün sonra alınmalıdır', 'The ratio of free to total PSA changes with benign prostatic hyperplasia, inflammation of the prostate and after medical procedures, and on its own it does not mean an oncological disease. The urologist interprets the result together with total PSA and the findings of the examination', 'Odnos slobodnog i ukupnog PSA mijenja se kod benigno uvećane prostate, upale prostate i poslije medicinskih zahvata i sam po sebi ne znači onkološko oboljenje. Nalaz tumači urolog zajedno sa ukupnim PSA i nalazom pregleda', 'Однос слободног и укупног PSA мијења се код бенигно увећане простате, упале простате и послије медицинских захвата и сам по себи не значи онколошко обољење. Налаз тумачи уролог заједно са укупним PSA и налазом прегледа', 'Соотношение свободного и общего PSA меняется при доброкачественной гиперплазии простаты, воспалении простаты, после медицинских манипуляций и само по себе не означает онкологического заболевания. Результат интерпретирует уролог вместе с общим PSA и данными осмотра', 'Das Verhältnis von freiem zu Gesamt-PSA verändert sich bei gutartiger Prostatavergrößerung, bei Entzündung der Prostata und nach medizinischen Eingriffen und bedeutet für sich genommen keine onkologische Erkrankung. Der Urologe deutet den Wert zusammen mit dem Gesamt-PSA und dem Untersuchungsbefund', 'Serbest PSA''nın toplam PSA''ya oranı iyi huylu prostat büyümesinde, prostat iltihabında ve tıbbi işlemlerden sonra değişir; tek başına onkolojik bir hastalık anlamına gelmez. Sonucu ürolog, toplam PSA ve muayene bulgularıyla birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ca-72-4'), 'Blood test for the glycoprotein tumour marker CA 72-4, used mainly when monitoring the condition of the stomach and the ovaries', 'Analiza krvi na glikoproteinski tumorski marker CA 72-4, koji se prvenstveno koristi pri praćenju stanja želuca i jajnika', 'Анализа крви на гликопротеински туморски маркер CA 72-4, који се првенствено користи при праћењу стања желуца и јајника', 'Анализ крови на гликопротеиновый онкомаркер CA 72-4, который применяют преимущественно при наблюдении за состоянием желудка и яичников', 'Bluttest auf den Glykoprotein-Tumormarker CA 72-4, der vor allem bei der Verlaufsbeobachtung von Magen und Eierstöcken eingesetzt wird', 'Başlıca mide ve yumurtalıkların durumunun izlenmesinde kullanılan CA 72-4 glikoprotein tümör belirteci için kan testi', 'Venous blood draw, the procedure is short', 'Uzimanje venske krvi, postupak je kratak', 'Узимање венске крви, поступак је кратак', 'Забор венозной крови, процедура короткая', 'Venöse Blutentnahme, der Vorgang ist kurz', 'Venöz kan alımı, işlem kısa sürer', 'Ordered by a doctor when the gastrointestinal tract is being examined, follow-up monitoring during treatment, usually alongside other markers', 'Po uputu ljekara pri pregledu probavnog trakta, praćenje tokom liječenja, obično uz druge markere', 'По упуту љекара при прегледу пробавног тракта, праћење током лијечења, обично уз друге маркере', 'По назначению врача при обследовании желудочно-кишечного тракта, динамическое наблюдение в процессе лечения, обычно вместе с другими маркерами', 'Auf ärztliche Anordnung bei der Abklärung des Magen-Darm-Trakts, Verlaufskontrolle während einer Behandlung, meist zusammen mit anderen Markern', 'Sindirim sisteminin değerlendirilmesinde hekim isteğiyle, tedavi sırasında izlemde, genellikle diğer belirteçlerle birlikte', 'No special preparation is required; tell the doctor about all medicines being taken, as some of them affect the result', 'Posebna priprema nije potrebna; ljekaru treba reći koje lijekove pacijent uzima, jer neki od njih utiču na nalaz', 'Посебна припрема није потребна; љекару треба рећи које лијекове пацијент узима, јер неки од њих утичу на налаз', 'Специальной подготовки не требуется; стоит сообщить врачу обо всех принимаемых препаратах, некоторые из них влияют на результат', 'Eine besondere Vorbereitung ist nicht nötig; dem Arzt sollten alle eingenommenen Medikamente genannt werden, da einige den Wert beeinflussen', 'Özel bir hazırlık gerekmez; bazı ilaçlar sonucu etkilediği için kullanılan tüm ilaçlar hekime bildirilmelidir', 'An increase occurs with benign diseases of the stomach, pancreas, liver and ovaries, with inflammatory processes and while taking certain medicines, so on its own it does not mean an oncological disease. The conclusion is drawn by the doctor, comparing the marker with other investigations', 'Povećanje se javlja kod benignih bolesti želuca, pankreasa, jetre i jajnika, kod upalnih procesa i uz uzimanje pojedinih lijekova, pa samo po sebi ne znači onkološko oboljenje. Zaključak donosi ljekar, upoređujući marker sa ostalim pregledima', 'Повећање се јавља код бенигних болести желуца, панкреаса, јетре и јајника, код упалних процеса и уз узимање појединих лијекова, па само по себи не значи онколошко обољење. Закључак доноси љекар, упоређујући маркер са осталим прегледима', 'Повышение встречается при доброкачественных заболеваниях желудка, поджелудочной железы, печени и яичников, при воспалительных процессах и на фоне приёма некоторых лекарств, поэтому само по себе не означает онкологического заболевания. Вывод делает врач, сопоставляя маркер с другими обследованиями', 'Ein Anstieg kommt bei gutartigen Erkrankungen von Magen, Bauchspeicheldrüse, Leber und Eierstöcken, bei entzündlichen Prozessen und unter bestimmten Medikamenten vor und bedeutet daher für sich genommen keine onkologische Erkrankung. Die Einordnung nimmt der Arzt im Vergleich mit weiteren Untersuchungen vor', 'Yükselme mide, pankreas, karaciğer ve yumurtalıkların iyi huylu hastalıklarında, iltihabi süreçlerde ve bazı ilaçların kullanımı sırasında da görülür; bu nedenle tek başına onkolojik bir hastalık anlamına gelmez. Değerlendirmeyi, belirteci diğer tetkiklerle karşılaştırarak hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cyfra-21-1'), 'Blood test for a fragment of cytokeratin 19, a protein of epithelial cells; it is used as a tumour marker when monitoring the condition of the lungs', 'Analiza krvi na fragment citokeratina 19, bjelančevine epitelnih ćelija; koristi se kao tumorski marker pri praćenju stanja pluća', 'Анализа крви на фрагмент цитокератина 19, бјеланчевине епителних ћелија; користи се као туморски маркер при праћењу стања плућа', 'Анализ крови на фрагмент цитокератина 19 — белка эпителиальных клеток; используется как онкомаркер при наблюдении за состоянием лёгких', 'Bluttest auf ein Fragment von Cytokeratin 19, einem Eiweiß der Epithelzellen; es dient als Tumormarker bei der Verlaufsbeobachtung der Lunge', 'Epitel hücrelerinin proteini olan sitokeratin 19''un bir parçasını ölçen kan testi; akciğerlerin durumunun izlenmesinde tümör belirteci olarak kullanılır', 'Blood draw from a vein in the arm, takes a few minutes', 'Uzimanje venske krvi iz vene na ruci, traje nekoliko minuta', 'Узимање венске крви из вене на руци, траје неколико минута', 'Забор венозной крови из вены руки, занимает несколько минут', 'Blutentnahme aus einer Armvene, dauert wenige Minuten', 'Koldaki toplardamardan kan alınması, birkaç dakika sürer', 'Ordered by a doctor when the chest organs are being examined, follow-up monitoring of patients already receiving treatment', 'Po uputu ljekara pri pregledu organa grudnog koša, praćenje pacijenata koji već primaju terapiju', 'По упуту љекара при прегледу органа грудног коша, праћење пацијената који већ примају терапију', 'По назначению врача при обследовании органов грудной клетки, динамическое наблюдение пациентов, уже получающих лечение', 'Auf ärztliche Anordnung bei der Abklärung der Brustorgane, Verlaufskontrolle bei Patienten, die bereits behandelt werden', 'Göğüs bölgesi organlarının değerlendirilmesinde hekim isteğiyle, tedavi almakta olan hastaların izleminde', 'No special preparation is required, there are usually no restrictions on food', 'Posebna priprema nije potrebna, obično nema ograničenja u ishrani', 'Посебна припрема није потребна, обично нема ограничења у исхрани', 'Специальной подготовки не требуется, ограничений по еде обычно нет', 'Eine besondere Vorbereitung ist nicht nötig, Einschränkungen beim Essen bestehen in der Regel nicht', 'Özel bir hazırlık gerekmez, genellikle beslenmeyle ilgili bir kısıtlama yoktur', 'An increase occurs with benign diseases of the lungs and pleura, chronic inflammation and impaired kidney and liver function, and on its own it does not mean an oncological disease. The doctor assesses the result together with an X-ray or computed tomography', 'Povećanje se javlja kod benignih bolesti pluća i plućne maramice, hroničnih upala, oslabljene funkcije bubrega i jetre i samo po sebi ne znači onkološko oboljenje. Nalaz procjenjuje ljekar zajedno sa rendgenskim snimkom ili kompjuterizovanom tomografijom', 'Повећање се јавља код бенигних болести плућа и плућне марамице, хроничних упала, ослабљене функције бубрега и јетре и само по себи не значи онколошко обољење. Налаз процјењује љекар заједно са рендгенским снимком или компјутеризованом томографијом', 'Повышение бывает при доброкачественных заболеваниях лёгких и плевры, хронических воспалениях, нарушении функции почек и печени и само по себе не означает онкологического заболевания. Результат оценивает врач вместе с рентгеном или компьютерной томографией', 'Ein Anstieg kommt bei gutartigen Erkrankungen von Lunge und Rippenfell, bei chronischen Entzündungen sowie bei eingeschränkter Nieren- und Leberfunktion vor und bedeutet für sich genommen keine onkologische Erkrankung. Der Arzt beurteilt den Wert zusammen mit Röntgenbild oder Computertomografie', 'Yükselme akciğer ve akciğer zarının iyi huylu hastalıklarında, kronik iltihaplarda, böbrek ve karaciğer işlevlerinin bozulmasında da görülür ve tek başına onkolojik bir hastalık anlamına gelmez. Hekim sonucu röntgen veya bilgisayarlı tomografi bulgularıyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'he4'), 'Blood test for the HE4 protein, used when ovarian masses are being examined, most often together with CA 125', 'Analiza krvi na bjelančevinu HE4, koja se koristi pri pregledu promjena na jajnicima, najčešće zajedno sa CA 125', 'Анализа крви на бјеланчевину HE4, која се користи при прегледу промјена на јајницима, најчешће заједно са CA 125', 'Анализ крови на белок HE4, который используют при обследовании образований в яичниках, чаще вместе с CA 125', 'Bluttest auf das Eiweiß HE4, das bei der Abklärung von Veränderungen an den Eierstöcken eingesetzt wird, meist zusammen mit CA 125', 'Yumurtalıklardaki oluşumların değerlendirilmesinde, çoğunlukla CA 125 ile birlikte kullanılan HE4 proteini için kan testi', 'Venous blood draw, usually from the same sample as CA 125', 'Uzimanje venske krvi, obično iz istog uzorka kao i CA 125', 'Узимање венске крви, обично из истог узорка као и CA 125', 'Забор венозной крови, обычно из той же пробы, что и CA 125', 'Venöse Blutentnahme, meist aus derselben Probe wie CA 125', 'Venöz kan alımı, genellikle CA 125 ile aynı örnekten yapılır', 'Ordered by a gynaecologist when a pelvic mass is being examined, follow-up monitoring, calculation of the ROMA index', 'Po uputu ginekologa pri pregledu promjena u maloj karlici, praćenje tokom vremena, izračunavanje ROMA indeksa', 'По упуту гинеколога при прегледу промјена у малој карлици, праћење током времена, израчунавање ROMA индекса', 'По назначению гинеколога при обследовании образований в малом тазу, динамическое наблюдение, расчёт индекса ROMA', 'Auf Anordnung des Gynäkologen bei der Abklärung von Raumforderungen im Becken, Verlaufsbeobachtung, Berechnung des ROMA-Index', 'Pelviste saptanan oluşumların değerlendirilmesinde jinekolog isteğiyle, zaman içinde izlemde, ROMA indeksinin hesaplanmasında', 'No special preparation is required; the doctor should be told about kidney disease and smoking, as both affect the result', 'Posebna priprema nije potrebna; ljekaru treba reći za bolesti bubrega i za pušenje, jer utiču na nalaz', 'Посебна припрема није потребна; љекару треба рећи за болести бубрега и за пушење, јер утичу на налаз', 'Специальной подготовки не требуется; врачу стоит сообщить о заболеваниях почек и о курении — они влияют на результат', 'Eine besondere Vorbereitung ist nicht nötig; Nierenerkrankungen und Rauchen sollten dem Arzt mitgeteilt werden, da sie den Wert beeinflussen', 'Özel bir hazırlık gerekmez; böbrek hastalıkları ve sigara kullanımı sonucu etkilediğinden hekime bildirilmelidir', 'The level rises with reduced kidney function, with some lung diseases, in smokers and with age, so on its own the result does not mean an oncological disease. The gynaecologist assesses it together with CA 125, ultrasound and the clinical picture', 'Vrijednost raste kod slabije funkcije bubrega, kod nekih bolesti pluća, kod pušača i sa godinama, pa nalaz sam po sebi ne znači onkološko oboljenje. Procjenjuje ga ginekolog zajedno sa CA 125, ultrazvukom i kliničkom slikom', 'Вриједност расте код слабије функције бубрега, код неких болести плућа, код пушача и са годинама, па налаз сам по себи не значи онколошко обољење. Процјењује га гинеколог заједно са CA 125, ултразвуком и клиничком сликом', 'Уровень повышается при снижении функции почек, некоторых заболеваниях лёгких, у курящих и с возрастом, поэтому сам по себе результат не означает онкологического заболевания. Оценивает его гинеколог вместе с CA 125, УЗИ и клинической картиной', 'Der Wert steigt bei eingeschränkter Nierenfunktion, bei manchen Lungenerkrankungen, bei Rauchern und mit zunehmendem Alter, daher bedeutet er für sich genommen keine onkologische Erkrankung. Beurteilt wird er vom Gynäkologen zusammen mit CA 125, Ultraschall und dem klinischen Bild', 'Değer böbrek işlevinin azalmasında, bazı akciğer hastalıklarında, sigara içenlerde ve yaşla birlikte yükselir; bu nedenle sonuç tek başına onkolojik bir hastalık anlamına gelmez. Jinekolog sonucu CA 125, ultrason ve klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'nse'), 'Blood test for an enzyme of nerve and neuroendocrine cells, used as a tumour marker in selected clinical situations', 'Analiza krvi na enzim nervnih i neuroendokrinih ćelija, koji se u pojedinim kliničkim situacijama koristi kao tumorski marker', 'Анализа крви на ензим нервних и неуроендокриних ћелија, који се у појединим клиничким ситуацијама користи као туморски маркер', 'Анализ крови на фермент нервных и нейроэндокринных клеток, который применяют как онкомаркер в отдельных клинических ситуациях', 'Bluttest auf ein Enzym der Nerven- und neuroendokrinen Zellen, das in bestimmten klinischen Situationen als Tumormarker dient', 'Sinir ve nöroendokrin hücrelerin bir enzimini ölçen kan testi; belirli klinik durumlarda tümör belirteci olarak kullanılır', 'Venous blood draw; the sample is taken carefully, without prolonged use of the tourniquet, and sent to the laboratory quickly', 'Uzimanje venske krvi; uzorak se uzima pažljivo, bez dugog stezanja podvezom, i brzo šalje u laboratoriju', 'Узимање венске крви; узорак се узима пажљиво, без дугог стезања подвезом, и брзо шаље у лабораторију', 'Забор венозной крови; пробу берут аккуратно, без длительного сдавливания жгутом, и быстро передают в лабораторию', 'Venöse Blutentnahme; die Probe wird vorsichtig und ohne langes Stauen entnommen und rasch ins Labor gebracht', 'Venöz kan alımı; kan, turnike uzun süre bağlı tutulmadan dikkatle alınır ve hızla laboratuvara iletilir', 'Ordered by a doctor when neuroendocrine conditions and lung diseases are being monitored, control during treatment', 'Po uputu ljekara pri praćenju neuroendokrinih stanja i bolesti pluća, kontrola tokom liječenja', 'По упуту љекара при праћењу неуроендокриних стања и болести плућа, контрола током лијечења', 'По назначению врача при наблюдении за нейроэндокринными состояниями и заболеваниями лёгких, контроль в процессе лечения', 'Auf ärztliche Anordnung bei der Verlaufsbeobachtung neuroendokriner Zustände und von Lungenerkrankungen, Kontrolle während der Behandlung', 'Nöroendokrin durumların ve akciğer hastalıklarının izleminde hekim isteğiyle, tedavi sırasında kontrol amacıyla', 'No special preparation is required; it matters that the laboratory processes the sample quickly, as the reliability of the result depends on it', 'Posebna priprema nije potrebna; važno je da laboratorija brzo obradi uzorak, jer od toga zavisi pouzdanost nalaza', 'Посебна припрема није потребна; важно је да лабораторија брзо обради узорак, јер од тога зависи поузданост налаза', 'Специальной подготовки не требуется; важно, чтобы лаборатория обработала пробу быстро — от этого зависит достоверность результата', 'Eine besondere Vorbereitung ist nicht nötig; wichtig ist, dass das Labor die Probe zügig verarbeitet, davon hängt die Verlässlichkeit des Werts ab', 'Özel bir hazırlık gerekmez; sonucun güvenilirliği alınan kanın hızla işlenmesine bağlı olduğu için bu önemlidir', 'An elevated result is often technical, caused by breakdown of red blood cells in the tube; an increase also occurs with diseases of the lungs, kidneys and liver, so on its own it does not mean an oncological disease. What the result means is decided by the doctor, and in case of doubt the test is repeated', 'Povišen nalaz je nerijetko tehničke prirode, zbog raspadanja crvenih krvnih zrnaca u epruveti; povećanje se javlja i kod bolesti pluća, bubrega i jetre, pa samo po sebi ne znači onkološko oboljenje. Značenje nalaza određuje ljekar, a u slučaju sumnje analiza se ponavlja', 'Повишен налаз је неријетко техничке природе, због распадања црвених крвних зрнаца у епрувети; повећање се јавља и код болести плућа, бубрега и јетре, па само по себи не значи онколошко обољење. Значење налаза одређује љекар, а у случају сумње анализа се понавља', 'Завышенный результат нередко оказывается техническим, из-за разрушения эритроцитов в пробирке; повышение встречается также при заболеваниях лёгких, почек и печени, поэтому само по себе оно не означает онкологического заболевания. Значение результата определяет врач, при сомнении анализ пересдают', 'Ein erhöhter Wert ist häufig technisch bedingt, durch den Zerfall roter Blutkörperchen im Röhrchen; ein Anstieg kommt außerdem bei Erkrankungen von Lunge, Nieren und Leber vor und bedeutet daher für sich genommen keine onkologische Erkrankung. Was der Wert bedeutet, entscheidet der Arzt, im Zweifelsfall wird die Untersuchung wiederholt', 'Yüksek sonuç çoğu zaman tüpteki alyuvarların parçalanmasına bağlı teknik bir durumdur; yükselme ayrıca akciğer, böbrek ve karaciğer hastalıklarında da görülür, bu nedenle tek başına onkolojik bir hastalık anlamına gelmez. Sonucun anlamını hekim belirler, kuşku varsa test tekrarlanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chromogranin-a'), 'Blood test for a protein released by neuroendocrine cells; it is used when neuroendocrine diseases are being monitored', 'Analiza krvi na bjelančevinu koju luče neuroendokrine ćelije; koristi se pri praćenju neuroendokrinih bolesti', 'Анализа крви на бјеланчевину коју луче неуроендокрине ћелије; користи се при праћењу неуроендокриних болести', 'Анализ крови на белок, который выделяют нейроэндокринные клетки; используется при наблюдении за нейроэндокринными заболеваниями', 'Bluttest auf ein Eiweiß, das von neuroendokrinen Zellen freigesetzt wird; es dient der Verlaufsbeobachtung neuroendokriner Erkrankungen', 'Nöroendokrin hücrelerin salgıladığı bir proteini ölçen kan testi; nöroendokrin hastalıkların izleminde kullanılır', 'Venous blood draw, usually in the morning, takes a few minutes', 'Uzimanje venske krvi, najčešće ujutru, traje nekoliko minuta', 'Узимање венске крви, најчешће ујутру, траје неколико минута', 'Забор венозной крови, чаще утром, занимает несколько минут', 'Venöse Blutentnahme, meist morgens, dauert wenige Minuten', 'Venöz kan alımı, çoğunlukla sabah yapılır ve birkaç dakika sürer', 'Ordered by an endocrinologist or gastroenterologist when neuroendocrine diseases are being investigated and for follow-up monitoring during treatment', 'Po uputu endokrinologa ili gastroenterologa pri ispitivanju neuroendokrinih bolesti i praćenju tokom liječenja', 'По упуту ендокринолога или гастроентеролога при испитивању неуроендокриних болести и праћењу током лијечења', 'По назначению эндокринолога или гастроэнтеролога при обследовании нейроэндокринных заболеваний и динамическом наблюдении в процессе лечения', 'Auf Anordnung des Endokrinologen oder Gastroenterologen bei der Abklärung neuroendokriner Erkrankungen und zur Verlaufskontrolle während der Behandlung', 'Nöroendokrin hastalıkların araştırılmasında ve tedavi sırasındaki izlemde endokrinolog ya da gastroenterolog isteğiyle', 'The sample is taken on an empty stomach; medicines that reduce stomach acid noticeably raise the value — only the doctor decides whether to pause them, treatment must not be interrupted on one''s own', 'Krv se uzima natašte; lijekovi koji smanjuju želudačnu kiselinu osjetno povećavaju vrijednost — o njihovom privremenom prekidu odlučuje isključivo ljekar, terapija se ne smije prekidati samoinicijativno', 'Крв се узима наташте; лијекови који смањују желудачну киселину осјетно повећавају вриједност — о њиховом привременом прекиду одлучује искључиво љекар, терапија се не смије прекидати самоиницијативно', 'Кровь сдают натощак; препараты, снижающие кислотность желудка, заметно повышают показатель — вопрос об их временной отмене решает только врач, самостоятельно прерывать лечение нельзя', 'Die Blutentnahme erfolgt nüchtern; Medikamente, die die Magensäure senken, erhöhen den Wert deutlich — über ein vorübergehendes Pausieren entscheidet allein der Arzt, eigenmächtig darf die Therapie nicht unterbrochen werden', 'Kan aç karnına alınır; mide asidini azaltan ilaçlar değeri belirgin şekilde yükseltir — bunların geçici olarak bırakılmasına yalnızca hekim karar verir, tedavi kendi başına kesilmemelidir', 'An increase is most often related to heartburn medicines, atrophic gastritis, reduced kidney function, heart failure and chronic inflammation, and on its own it does not mean an oncological disease. The doctor assesses the result taking into account the medicines taken and other investigations', 'Povećanje je najčešće povezano sa lijekovima protiv gorušice, atrofičnim gastritisom, slabijom funkcijom bubrega, srčanom slabošću i hroničnim upalama i samo po sebi ne znači onkološko oboljenje. Nalaz procjenjuje ljekar uzimajući u obzir lijekove koje pacijent koristi i ostale preglede', 'Повећање је најчешће повезано са лијековима против горушице, атрофичним гастритисом, слабијом функцијом бубрега, срчаном слабошћу и хроничним упалама и само по себи не значи онколошко обољење. Налаз процјењује љекар узимајући у обзир лијекове које пацијент користи и остале прегледе', 'Повышение чаще всего связано с приёмом препаратов от изжоги, атрофическим гастритом, снижением функции почек, сердечной недостаточностью и хроническими воспалениями и само по себе не означает онкологического заболевания. Результат оценивает врач с учётом принимаемых лекарств и других обследований', 'Ein Anstieg hängt am häufigsten mit Medikamenten gegen Sodbrennen, atrophischer Gastritis, eingeschränkter Nierenfunktion, Herzschwäche und chronischen Entzündungen zusammen und bedeutet für sich genommen keine onkologische Erkrankung. Der Arzt beurteilt den Wert unter Berücksichtigung der eingenommenen Medikamente und weiterer Untersuchungen', 'Yükselme çoğunlukla mide yanmasına karşı kullanılan ilaçlar, atrofik gastrit, böbrek işlevinin azalması, kalp yetmezliği ve kronik iltihaplarla ilişkilidir ve tek başına onkolojik bir hastalık anlamına gelmez. Hekim sonucu, kullanılan ilaçları ve diğer tetkikleri göz önünde bulundurarak değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'roma-index'), 'A calculated value that combines the results of CA 125 and HE4 taking the woman''s menopausal status into account', 'Izračunata vrijednost koja objedinjuje nalaze CA 125 i HE4 uz uzimanje u obzir menopauzalnog statusa žene', 'Израчуната вриједност која обједињује налазе CA 125 и HE4 уз узимање у обзир менопаузалног статуса жене', 'Расчётный показатель, который объединяет результаты CA 125 и HE4 с учётом менопаузального статуса женщины', 'Ein berechneter Wert, der die Ergebnisse von CA 125 und HE4 unter Berücksichtigung des Menopausenstatus der Frau zusammenführt', 'CA 125 ve HE4 sonuçlarını kadının menopoz durumunu da hesaba katarak birleştiren hesaplanmış bir değer', 'No separate blood draw is needed: the laboratory calculates the value from two tests run on one sample', 'Zasebno vađenje krvi nije potrebno: laboratorija vrijednost izračunava iz dvije analize iz istog uzorka', 'Засебно вађење крви није потребно: лабораторија вриједност израчунава из двије анализе из истог узорка', 'Отдельный забор крови не нужен: показатель рассчитывает лаборатория по двум анализам из одной пробы', 'Eine gesonderte Blutentnahme ist nicht nötig: das Labor berechnet den Wert aus zwei Untersuchungen derselben Probe', 'Ayrı bir kan alımı gerekmez: laboratuvar değeri aynı örnekten yapılan iki testten hesaplar', 'Ordered by a gynaecologist when ovarian masses are being examined and the further monitoring plan has to be decided', 'Po uputu ginekologa pri pregledu promjena na jajnicima, kada treba odrediti dalji plan praćenja', 'По упуту гинеколога при прегледу промјена на јајницима, када треба одредити даљи план праћења', 'По назначению гинеколога при обследовании образований в яичниках, когда нужно определить дальнейшую тактику наблюдения', 'Auf Anordnung des Gynäkologen bei der Abklärung von Veränderungen an den Eierstöcken, wenn das weitere Vorgehen festgelegt werden soll', 'Yumurtalıklardaki oluşumların değerlendirilmesinde, izlem planının belirlenmesi gerektiğinde jinekolog isteğiyle', 'The preparation is the same as for CA 125 and HE4; the referral must state the menopausal status, without it the calculation cannot be made', 'Priprema je ista kao za CA 125 i HE4; na uputu se obavezno navodi menopauzalni status, bez njega se izračun ne radi', 'Припрема је иста као за CA 125 и HE4; на упуту се обавезно наводи менопаузални статус, без њега се израчун не ради', 'Подготовка та же, что для CA 125 и HE4; в направлении обязательно указывают менопаузальный статус, без него расчёт не выполняется', 'Die Vorbereitung entspricht der für CA 125 und HE4; auf der Überweisung muss der Menopausenstatus angegeben sein, ohne ihn ist die Berechnung nicht möglich', 'Hazırlık CA 125 ve HE4 ile aynıdır; istem belgesinde menopoz durumunun belirtilmesi zorunludur, aksi hâlde hesaplama yapılamaz', 'The value is not a diagnosis and does not replace examination and ultrasound: it is affected by the same benign conditions as CA 125 and HE4. Only the gynaecologist interprets the result together with the rest of the examination findings', 'Vrijednost nije dijagnoza i ne zamjenjuje pregled i ultrazvuk: na nju utiču ista benigna stanja kao na CA 125 i HE4. Nalaz tumači isključivo ginekolog, zajedno sa ostalim nalazima pregleda', 'Вриједност није дијагноза и не замјењује преглед и ултразвук: на њу утичу иста бенигна стања као на CA 125 и HE4. Налаз тумачи искључиво гинеколог, заједно са осталим налазима прегледа', 'Показатель не является диагнозом и не заменяет осмотр и УЗИ: на него влияют те же доброкачественные состояния, что на CA 125 и HE4. Результат интерпретирует только гинеколог в комплексе с остальными данными обследования', 'Der Wert ist keine Diagnose und ersetzt weder Untersuchung noch Ultraschall: Ihn beeinflussen dieselben gutartigen Zustände wie CA 125 und HE4. Die Deutung nimmt ausschließlich der Gynäkologe im Zusammenhang mit den übrigen Befunden vor', 'Bu değer bir tanı değildir ve muayene ile ultrasonun yerini tutmaz: CA 125 ve HE4''ü etkileyen aynı iyi huylu durumlardan etkilenir. Sonucu yalnızca jinekolog, diğer inceleme bulgularıyla birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'iga'), 'Blood test for class A immunoglobulin, the antibodies that protect the mucous membranes of the airways and the gut', 'Analiza krvi na imunoglobulin klase A, antitijela koja štite sluznice disajnih puteva i crijeva', 'Анализа крви на имуноглобулин класе А, антитијела која штите слузнице дисајних путева и цријева', 'Анализ крови на иммуноглобулин класса A — антитела, которые защищают слизистые дыхательных путей и кишечника', 'Bluttest auf Immunglobulin der Klasse A, die Antikörper, die die Schleimhäute von Atemwegen und Darm schützen', 'Solunum yollarının ve bağırsağın mukozasını koruyan A sınıfı immünoglobulin için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Frequent respiratory and intestinal infections, evaluation for weak mucosal immune defence, check before interpreting coeliac disease serology, immune panel', 'Česte infekcije disajnih puteva i crijeva, ispitivanje pri sumnji na slabu imunu zaštitu sluznica, provjera prije tumačenja serologije na celijakiju, imunogram', 'Честе инфекције дисајних путева и цријева, испитивање при сумњи на слабу имуну заштиту слузница, провјера прије тумачења серологије на целијакију, имунограм', 'Частые инфекции дыхательных путей и кишечника, обследование при подозрении на слабую иммунную защиту слизистых, проверка перед трактовкой серологии на целиакию, иммунограмма', 'Häufige Atemwegs- und Darminfekte, Abklärung bei Verdacht auf eine schwache Schleimhautabwehr, Kontrolle vor der Beurteilung der Zöliakie-Serologie, Immunstatus', 'Sık solunum yolu ve bağırsak enfeksiyonları, mukoza bağışıklığının zayıflığı şüphesi, çölyak serolojisinin yorumlanmasından önce kontrol, bağışıklık paneli', 'No special preparation is required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Eine besondere Vorbereitung ist nicht nötig, das Blut wird meist morgens entnommen', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A low level may be related to a congenital or acquired IgA deficiency and affects the interpretation of other tests based on this antibody class, a high level to chronic mucosal inflammation or liver disease. The result is assessed by a doctor together with IgG and IgM', 'Snižen nivo može biti povezan sa urođenim ili stečenim nedostatkom IgA i utiče na tumačenje drugih testova zasnovanih na ovoj klasi antitijela, povišen sa hroničnim zapaljenjem sluznica ili oboljenjem jetre. Rezultat procjenjuje ljekar zajedno sa IgG i IgM', 'Снижен ниво може бити повезан са урођеним или стеченим недостатком IgA и утиче на тумачење других тестова заснованих на овој класи антитијела, повишен са хроничним запаљењем слузница или обољењем јетре. Резултат процјењује љекар заједно са IgG и IgM', 'Снижение может быть связано с врождённым или приобретённым дефицитом IgA и влияет на трактовку других анализов, построенных на антителах этого класса, повышение — с хроническим воспалением слизистых или заболеванием печени. Результат оценивает врач вместе с IgG и IgM', 'Ein niedriger Wert kann mit einem angeborenen oder erworbenen IgA-Mangel zusammenhängen und beeinflusst die Beurteilung anderer Tests, die auf dieser Antikörperklasse beruhen, ein hoher Wert mit einer chronischen Schleimhautentzündung oder einer Lebererkrankung. Der Arzt beurteilt das Ergebnis zusammen mit IgG und IgM', 'Düşük değer doğuştan veya sonradan gelişen IgA eksikliğiyle ilişkili olabilir ve bu antikor sınıfına dayanan diğer testlerin yorumunu etkiler, yüksek değer ise kronik mukoza iltihabı veya karaciğer hastalığıyla ilişkili olabilir. Sonucu hekim IgG ve IgM ile birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'igg'), 'Blood test for class G immunoglobulin, the main antibodies of the blood that persist for a long time and provide lasting immunity', 'Analiza krvi na imunoglobulin klase G, glavna antitijela u krvi koja se dugo zadržavaju i obezbjeđuju dugotrajan imunitet', 'Анализа крви на имуноглобулин класе Г, главна антитијела у крви која се дуго задржавају и обезбјеђују дуготрајан имунитет', 'Анализ крови на иммуноглобулин класса G — основные антитела крови, которые сохраняются долго и обеспечивают длительный иммунитет', 'Bluttest auf Immunglobulin der Klasse G, die wichtigsten Antikörper im Blut, die lange bestehen bleiben und für den dauerhaften Immunschutz sorgen', 'Kanda uzun süre kalan ve kalıcı bağışıklığı sağlayan başlıca antikorlar olan G sınıfı immünoglobulin için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Recurrent and prolonged infections, evaluation for insufficient antibody production, monitoring during immunoglobulin replacement therapy, chronic inflammation and liver disease', 'Ponavljane i dugotrajne infekcije, ispitivanje pri sumnji na nedovoljno stvaranje antitijela, kontrola tokom nadoknadne terapije imunoglobulinima, hronično zapaljenje i oboljenja jetre', 'Понављане и дуготрајне инфекције, испитивање при сумњи на недовољно стварање антитијела, контрола током надокнадне терапије имуноглобулинима, хронично запаљење и обољења јетре', 'Повторяющиеся и затяжные инфекции, обследование при подозрении на недостаточную выработку антител, контроль на фоне заместительной терапии иммуноглобулинами, хроническое воспаление и заболевания печени', 'Wiederkehrende und langwierige Infekte, Abklärung bei Verdacht auf eine unzureichende Antikörperbildung, Verlaufskontrolle unter Immunglobulin-Substitution, chronische Entzündungen und Lebererkrankungen', 'Tekrarlayan ve uzayan enfeksiyonlar, yetersiz antikor üretimi şüphesi, immünoglobulin replasman tedavisi sırasında izlem, kronik iltihap ve karaciğer hastalıkları', 'No special preparation is required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Eine besondere Vorbereitung ist nicht nötig, das Blut wird meist morgens entnommen', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A low level may be related to insufficient antibody production or to losses through the kidneys and gut, a high level to a long-standing inflammatory or infectious process. The level changes slowly, so a repeat test after months shows the doctor a steady trend rather than short-term fluctuation', 'Snižen nivo može biti povezan sa nedovoljnim stvaranjem antitijela ili njihovim gubitkom preko bubrega i crijeva, povišen sa dugotrajnim zapaljenjskim ili infektivnim procesom. Nivo se mijenja sporo, pa ponovljeno mjerenje poslije nekoliko mjeseci ljekaru pokazuje trajniju tendenciju, a ne trenutna kolebanja', 'Снижен ниво може бити повезан са недовољним стварањем антитијела или њиховим губитком преко бубрега и цријева, повишен са дуготрајним запаљењским или инфективним процесом. Ниво се мијења споро, па поновљено мјерење послије неколико мјесеци љекару показује трајнију тенденцију, а не тренутна колебања', 'Снижение может быть связано с недостаточной выработкой антител или их потерей через почки и кишечник, повышение — с длительным воспалительным или инфекционным процессом. Уровень меняется медленно, поэтому повторное измерение через месяцы показывает врачу устойчивую тенденцию, а не сиюминутные колебания', 'Ein niedriger Wert kann mit einer unzureichenden Antikörperbildung oder mit Verlusten über Nieren und Darm zusammenhängen, ein hoher Wert mit einem lang bestehenden Entzündungs- oder Infektionsprozess. Der Wert ändert sich langsam, daher zeigt eine Kontrolle nach Monaten dem Arzt eine dauerhafte Tendenz und keine kurzfristigen Schwankungen', 'Düşük değer antikor üretiminin yetersizliğiyle ya da böbrek ve bağırsak yoluyla kaybıyla, yüksek değer uzun süren iltihabi veya enfeksiyöz bir süreçle ilişkili olabilir. Değer yavaş değiştiğinden aylar sonra yapılan tekrar ölçüm hekime anlık dalgalanmayı değil kalıcı eğilimi gösterir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'igm'), 'Blood test for class M immunoglobulin, the antibodies the body produces first when it meets a pathogen anew', 'Analiza krvi na imunoglobulin klase M, antitijela koja organizam stvara prva pri novom susretu sa uzročnikom', 'Анализа крви на имуноглобулин класе М, антитијела која организам ствара прва при новом сусрету са узрочником', 'Анализ крови на иммуноглобулин класса M — антитела, которые организм вырабатывает первыми при новой встрече с возбудителем', 'Bluttest auf Immunglobulin der Klasse M, die Antikörper, die der Körper bei einem neuen Kontakt mit einem Erreger als Erste bildet', 'Vücudun bir etkenle yeni karşılaşmasında ilk olarak ürettiği antikorlar olan M sınıfı immünoglobulin için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Assessment of the early phase of the immune response, recurrent infections in children and adults, evaluation for impaired antibody maturation, immune panel together with IgA and IgG', 'Procjena rane faze imunog odgovora, ponavljane infekcije kod djece i odraslih, ispitivanje pri sumnji na poremećaj sazrijevanja antitijela, imunogram zajedno sa IgA i IgG', 'Процјена ране фазе имуног одговора, понављане инфекције код дјеце и одраслих, испитивање при сумњи на поремећај сазријевања антитијела, имунограм заједно са IgA и IgG', 'Оценка ранней фазы иммунного ответа, повторяющиеся инфекции у детей и взрослых, обследование при подозрении на нарушение созревания антител, иммунограмма вместе с IgA и IgG', 'Beurteilung der frühen Phase der Immunantwort, wiederkehrende Infekte bei Kindern und Erwachsenen, Abklärung bei Verdacht auf eine gestörte Antikörperreifung, Immunstatus zusammen mit IgA und IgG', 'Bağışıklık yanıtının erken evresinin değerlendirilmesi, çocuklarda ve erişkinlerde tekrarlayan enfeksiyonlar, antikor olgunlaşmasında bozukluk şüphesi, IgA ve IgG ile birlikte bağışıklık paneli', 'No special preparation is required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Eine besondere Vorbereitung ist nicht nötig, das Blut wird meist morgens entnommen', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'A high level may be related to a recent or ongoing infection, a low level to insufficient antibody production. A repeat test paired with IgG helps the doctor tell a fresh immune response from an older one', 'Povišen nivo može biti povezan sa skorašnjom ili aktuelnom infekcijom, snižen sa nedovoljnim stvaranjem antitijela. Ponovljeno mjerenje u paru sa IgG pomaže ljekaru da razlikuje svjež imuni odgovor od ranijeg', 'Повишен ниво може бити повезан са скорашњом или актуелном инфекцијом, снижен са недовољним стварањем антитијела. Поновљено мјерење у пару са IgG помаже љекару да разликује свјеж имуни одговор од ранијег', 'Повышение может быть связано с недавним или текущим инфекционным процессом, снижение — с недостаточной выработкой антител. Повторное измерение в паре с IgG помогает врачу отличить свежий иммунный ответ от давнего', 'Ein hoher Wert kann mit einer kürzlichen oder aktuellen Infektion zusammenhängen, ein niedriger mit einer unzureichenden Antikörperbildung. Eine Wiederholung zusammen mit IgG hilft dem Arzt, eine frische Immunantwort von einer länger zurückliegenden zu unterscheiden', 'Yüksek değer yakın zamandaki veya süregelen bir enfeksiyonla, düşük değer yetersiz antikor üretimiyle ilişkili olabilir. IgG ile birlikte yapılan tekrar ölçüm hekime yeni bir bağışıklık yanıtını eskisinden ayırt etmede yardımcı olur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ige'), 'Blood test for total class E immunoglobulin, the antibodies involved in allergic reactions and in the response to parasites', 'Analiza krvi na ukupni imunoglobulin klase E, antitijela koja učestvuju u alergijskim reakcijama i u odgovoru na parazite', 'Анализа крви на укупни имуноглобулин класе Е, антитијела која учествују у алергијским реакцијама и у одговору на паразите', 'Анализ крови на общий иммуноглобулин класса E — антитела, участвующие в аллергических реакциях и в ответе на паразитов', 'Bluttest auf Gesamt-Immunglobulin der Klasse E, die Antikörper, die an allergischen Reaktionen und an der Abwehr von Parasiten beteiligt sind', 'Alerjik reaksiyonlarda ve parazitlere karşı yanıtta rol alan antikorlar olan total E sınıfı immünoglobulin için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Suspected allergy, atopic dermatitis, bronchial asthma, urticaria, year-round or seasonal rhinitis, work-up before choosing allergy tests, suspected parasitic infestation', 'Sumnja na alergiju, atopijski dermatitis, astma, koprivnjača, cjelogodišnja ili sezonska kijavica, priprema za izbor alergoloških testova, sumnja na parazitarnu infekciju', 'Сумња на алергију, атопијски дерматитис, астма, копривњача, цјелогодишња или сезонска кијавица, припрема за избор алерголошких тестова, сумња на паразитарну инфекцију', 'Подозрение на аллергию, атопический дерматит, бронхиальная астма, крапивница, круглогодичный или сезонный насморк, обследование перед подбором аллергологических тестов, подозрение на паразитарную инвазию', 'Verdacht auf eine Allergie, Neurodermitis, Asthma bronchiale, Nesselsucht, ganzjähriger oder saisonaler Schnupfen, Abklärung vor der Auswahl von Allergietests, Verdacht auf Parasitenbefall', 'Alerji şüphesi, atopik dermatit, bronş astımı, ürtiker, yıl boyu süren veya mevsimsel nezle, alerji testlerinin seçiminden önce değerlendirme, parazit şüphesi', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Eine besondere Vorbereitung ist nicht nötig', 'Özel bir hazırlık gerekmez', 'A raised total IgE may be related to an allergic predisposition or to a parasitic infestation, but it does not show which allergen the person reacts to, which requires specific IgE tests or skin tests. An allergist assesses the result together with the symptoms', 'Povišen ukupni IgE može biti povezan sa alergijskom sklonošću organizma ili sa parazitarnom infekcijom, ali ne pokazuje na koji tačno alergen osoba reaguje, za to su potrebni specifični IgE ili kožni testovi. Rezultat zajedno sa tegobama procjenjuje alergolog', 'Повишен укупни IgE може бити повезан са алергијском склоношћу организма или са паразитарном инфекцијом, али не показује на који тачно алерген особа реагује, за то су потребни специфични IgE или кожни тестови. Резултат заједно са тегобама процјењује алерголог', 'Повышение общего IgE может быть связано с аллергической настроенностью организма или с паразитарной инвазией, но не показывает, на какой именно аллерген реагирует человек, для этого нужны специфические IgE или кожные пробы. Результат вместе с жалобами оценивает аллерголог', 'Ein erhöhtes Gesamt-IgE kann mit einer allergischen Veranlagung oder mit einem Parasitenbefall zusammenhängen, zeigt aber nicht, auf welches Allergen der Körper reagiert, dafür sind spezifische IgE-Tests oder Hauttests nötig. Der Allergologe beurteilt das Ergebnis zusammen mit den Beschwerden', 'Yüksek total IgE alerjik yatkınlıkla veya parazit enfeksiyonuyla ilişkili olabilir, ancak kişinin hangi alerjene tepki verdiğini göstermez, bunun için spesifik IgE veya deri testleri gerekir. Sonucu şikayetlerle birlikte alerji uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'c3-complement'), 'Blood test for the complement protein C3, a part of innate immunity that is consumed during active inflammation', 'Analiza krvi na protein sistema komplementa C3, dio urođenog imuniteta koji se troši tokom aktivnog zapaljenja', 'Анализа крви на протеин система комплемента Ц3, дио урођеног имунитета који се троши током активног запаљења', 'Анализ крови на белок системы комплемента C3 — часть врождённого иммунитета, которая расходуется при активном воспалении', 'Bluttest auf das Komplementprotein C3, einen Teil der angeborenen Immunabwehr, der bei aktiver Entzündung verbraucht wird', 'Aktif iltihap sırasında tüketilen ve doğuştan gelen bağışıklığın bir parçası olan kompleman proteini C3 için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Work-up of autoimmune diseases, kidney disease with abnormal urine findings, recurrent bacterial infections, following the activity of a known autoimmune process', 'Ispitivanje autoimunih bolesti, bubrežna oboljenja sa promjenama u mokraći, ponavljane bakterijske infekcije, praćenje aktivnosti poznatog autoimunog procesa', 'Испитивање аутоимуних болести, бубрежна обољења са промјенама у мокраћи, понављане бактеријске инфекције, праћење активности познатог аутоимуног процеса', 'Обследование при аутоиммунных заболеваниях, болезни почек с изменениями в моче, повторяющиеся бактериальные инфекции, наблюдение за активностью известного аутоиммунного процесса', 'Abklärung von Autoimmunerkrankungen, Nierenerkrankungen mit auffälligem Urinbefund, wiederkehrende bakterielle Infekte, Verlaufskontrolle der Aktivität eines bekannten Autoimmunprozesses', 'Otoimmün hastalıkların değerlendirilmesi, idrar bulguları bozuk olan böbrek hastalıkları, tekrarlayan bakteriyel enfeksiyonlar, bilinen bir otoimmün sürecin etkinliğinin izlenmesi', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Eine besondere Vorbereitung ist nicht nötig', 'Özel bir hazırlık gerekmez', 'A low level may be related to active consumption of complement in an autoimmune or kidney process, a high level to acute inflammation, since C3 is also an acute-phase protein. Doctors use repeat measurements to follow how active the process is over time', 'Snižen nivo može biti povezan sa pojačanim trošenjem komplementa u autoimunom ili bubrežnom procesu, povišen sa akutnim zapaljenjem, jer je C3 i protein akutne faze. Ponovljena mjerenja ljekar koristi da prati koliko je proces aktivan tokom vremena', 'Снижен ниво може бити повезан са појачаним трошењем комплемента у аутоимуном или бубрежном процесу, повишен са акутним запаљењем, јер је Ц3 и протеин акутне фазе. Поновљена мјерења љекар користи да прати колико је процес активан током времена', 'Снижение может быть связано с активным расходом комплемента при аутоиммунном или почечном процессе, повышение — с острым воспалением, так как C3 ещё и белок острой фазы. Повторные измерения врач использует, чтобы следить за активностью процесса в динамике', 'Ein niedriger Wert kann mit einem verstärkten Verbrauch des Komplements bei einem Autoimmun- oder Nierenprozess zusammenhängen, ein hoher Wert mit einer akuten Entzündung, da C3 auch ein Akute-Phase-Protein ist. Wiederholte Messungen nutzt der Arzt, um die Aktivität des Prozesses im Verlauf zu verfolgen', 'Düşük değer otoimmün veya böbrek kaynaklı bir süreçte komplemanın artan tüketimiyle, yüksek değer ise C3 aynı zamanda bir akut faz proteini olduğundan akut iltihapla ilişkili olabilir. Hekim tekrarlanan ölçümleri sürecin ne kadar etkin olduğunu zaman içinde izlemek için kullanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'c4-complement'), 'Blood test for the complement protein C4, a component of the classical activation pathway', 'Analiza krvi na protein sistema komplementa C4, sastavni dio njegovog klasičnog puta aktivacije', 'Анализа крви на протеин система комплемента Ц4, саставни дио његовог класичног пута активације', 'Анализ крови на белок системы комплемента C4 — компонент её классического пути активации', 'Bluttest auf das Komplementprotein C4, einen Bestandteil des klassischen Aktivierungswegs', 'Kompleman sisteminin klasik aktivasyon yolunun bir bileşeni olan C4 proteini için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Recurrent swellings without hives, work-up of autoimmune diseases and vasculitis, addition to the C3 result', 'Ponavljani otoci bez koprivnjače, ispitivanje autoimunih bolesti i vaskulitisa, dopuna nalazu C3', 'Понављани отоци без копривњаче, испитивање аутоимуних болести и васкулитиса, допуна налазу Ц3', 'Повторяющиеся отёки без крапивницы, обследование при аутоиммунных заболеваниях и васкулитах, дополнение к результату C3', 'Wiederkehrende Schwellungen ohne Quaddeln, Abklärung von Autoimmunerkrankungen und Vaskulitiden, Ergänzung zum C3-Befund', 'Kurdeşen olmadan tekrarlayan şişlikler, otoimmün hastalıkların ve vaskülitlerin değerlendirilmesi, C3 sonucunun tamamlanması', 'No special preparation is required', 'Nije potrebna posebna priprema', 'Није потребна посебна припрема', 'Специальной подготовки не требуется', 'Eine besondere Vorbereitung ist nicht nötig', 'Özel bir hazırlık gerekmez', 'A persistently low level may be related to an inherited deficiency of this protein or to activation of the classical complement pathway in an autoimmune process. Comparing C4 with C3 helps the doctor see which activation pathway is involved', 'Trajno snižen nivo može biti povezan sa nasljednim nedostatkom ovog proteina ili sa aktivacijom klasičnog puta komplementa u autoimunom procesu. Poređenje C4 sa C3 pomaže ljekaru da sagleda koji je put aktivacije uključen', 'Трајно снижен ниво може бити повезан са насљедним недостатком овог протеина или са активацијом класичног пута комплемента у аутоимуном процесу. Поређење Ц4 са Ц3 помаже љекару да сагледа који је пут активације укључен', 'Стойко низкий уровень может быть связан с наследственным недостатком этого белка или с активацией классического пути комплемента при аутоиммунном процессе. Сопоставление C4 с C3 помогает врачу понять, какой путь активации задействован', 'Ein dauerhaft niedriger Wert kann mit einem erblichen Mangel dieses Proteins oder mit der Aktivierung des klassischen Komplementwegs bei einem Autoimmunprozess zusammenhängen. Der Vergleich von C4 mit C3 hilft dem Arzt zu erkennen, welcher Aktivierungsweg beteiligt ist', 'Sürekli düşük değer bu proteinin kalıtsal eksikliğiyle veya otoimmün süreçte klasik kompleman yolunun etkinleşmesiyle ilişkili olabilir. C4 değerinin C3 ile karşılaştırılması hekime hangi aktivasyon yolunun devrede olduğunu görmede yardımcı olur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'spermatozoa-antibodies-asa'), 'Test for antisperm antibodies (ASA), an immune factor that can interfere with fertilisation', 'Ispitivanje antitijela na spermatozoide (ASA), imunog faktora koji može ometati oplodnju', 'Испитивање антитијела на сперматозоиде (ASA), имуног фактора који може ометати оплодњу', 'Анализ на антитела к сперматозоидам (ASA) — иммунный фактор, который может мешать оплодотворению', 'Untersuchung auf Spermien-Antikörper (ASA), einen Immunfaktor, der die Befruchtung stören kann', 'Döllenmeyi engelleyebilen bir bağışıklık etkeni olan sperm antikorları (ASA) incelemesi', 'Examination of venous blood or of a semen sample, collection takes a few minutes', 'Analiza venske krvi ili uzorka sjemena, uzimanje traje nekoliko minuta', 'Анализа венске крви или узорка сјемена, узимање траје неколико минута', 'Исследование венозной крови или образца спермы, забор занимает несколько минут', 'Untersuchung von venösem Blut oder einer Samenprobe, die Gewinnung dauert wenige Minuten', 'Damardan alınan kanın veya semen örneğinin incelenmesi, örnek alımı birkaç dakika sürer', 'Work-up of a couple with difficulty conceiving, clumping of sperm on a semen analysis, past testicular injury or inflammation, surgery on the genital tract including vasectomy', 'Ispitivanje para kod otežanog začeća, slijepljivanje spermatozoida u spermogramu, ranija povreda ili zapaljenje testisa, operacije na polnim putevima uključujući vazektomiju', 'Испитивање пара код отежаног зачећа, слијепљивање сперматозоида у спермограму, ранија повреда или запаљење тестиса, операције на полним путевима укључујући вазектомију', 'Обследование пары при трудностях с зачатием, склеивание сперматозоидов в спермограмме, перенесённая травма или воспаление яичка, операции на половых путях, включая вазэктомию', 'Abklärung bei einem Paar mit unerfülltem Kinderwunsch, Verklumpung der Spermien im Spermiogramm, frühere Hodenverletzung oder Hodenentzündung, Operationen am Genitaltrakt einschließlich Vasektomie', 'Gebe kalmakta güçlük çeken çiftlerin değerlendirilmesi, spermiyogramda spermlerin kümeleşmesi, geçirilmiş testis travması veya iltihabı, vazektomi dahil genital yol ameliyatları', 'For a semen sample, sexual abstinence of 2 to 7 days, the blood test needs no preparation', 'Za uzorak sjemena potrebna je polna apstinencija od 2 do 7 dana, za analizu krvi priprema nije potrebna', 'За узорак сјемена потребна је полна апстиненција од 2 до 7 дана, за анализу крви припрема није потребна', 'Для образца спермы половое воздержание от 2 до 7 дней, для анализа крови подготовка не нужна', 'Für die Samenprobe sexuelle Karenz von 2 bis 7 Tagen, für die Blutentnahme ist keine Vorbereitung nötig', 'Semen örneği için 2 ila 7 gün cinsel perhiz gerekir, kan testi için hazırlık gerekmez', 'Finding such antibodies may be related to an immune factor in reduced fertility and is considered only together with the semen analysis and the assessment of both partners. Further steps are decided by a urologist or a fertility specialist', 'Nalaz ovih antitijela može biti povezan sa imunim faktorom smanjene plodnosti i razmatra se samo zajedno sa spermogramom i pregledom oba partnera. Dalji postupak određuje urolog ili specijalista za reprodukciju', 'Налаз ових антитијела може бити повезан са имуним фактором смањене плодности и разматра се само заједно са спермограмом и прегледом оба партнера. Даљи поступак одређује уролог или специјалиста за репродукцију', 'Обнаружение таких антител может быть связано с иммунным фактором снижения фертильности и рассматривается только вместе со спермограммой и обследованием обоих партнёров. Дальнейшую тактику определяет уролог или врач-репродуктолог', 'Der Nachweis solcher Antikörper kann mit einem immunologischen Faktor einer verminderten Fruchtbarkeit zusammenhängen und wird nur zusammen mit dem Spermiogramm und der Untersuchung beider Partner bewertet. Das weitere Vorgehen legt der Urologe oder der Reproduktionsmediziner fest', 'Bu antikorların saptanması doğurganlığın azalmasında bağışıklık etkeniyle ilişkili olabilir ve yalnızca spermiyogram ve her iki eşin değerlendirilmesiyle birlikte ele alınır. Sonraki adımları üroloji uzmanı veya üreme sağlığı uzmanı belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bleeding-time'), 'A simple test showing how long it takes for bleeding from a small skin puncture to stop', 'Jednostavna proba koja pokazuje za koliko se zaustavlja krvarenje iz malog uboda kože', 'Једноставна проба која показује за колико се зауставља крварење из малог убода коже', 'Простая проба, показывающая, за какое время останавливается кровотечение из небольшого прокола кожи', 'Ein einfacher Test, der zeigt, wie lange die Blutung aus einem kleinen Hautstich bis zum Stillstand braucht', 'Küçük bir cilt deliğinden gelen kanamanın ne kadar sürede durduğunu gösteren basit bir test', 'A nurse makes a small puncture on the finger or forearm and times the moment the bleeding stops, taking a few minutes', 'Medicinska sestra napravi mali ubod na prstu ili podlaktici i štopericom bilježi trenutak prestanka krvarenja, traje nekoliko minuta', 'Медицинска сестра направи мали убод на прсту или подлактици и штоперицом биљежи тренутак престанка крварења, траје неколико минута', 'Медсестра делает небольшой прокол кожи пальца или предплечья и с секундомером отмечает момент остановки кровотечения, занимает несколько минут', 'Eine Pflegekraft setzt einen kleinen Stich an Finger oder Unterarm und stoppt die Zeit bis zum Ende der Blutung, dauert wenige Minuten', 'Hemşire parmakta veya ön kolda küçük bir delik açar ve kanamanın durduğu anı kronometreyle kaydeder, birkaç dakika sürer', 'Work-up before minor procedures, tendency to bruising and bleeding gums, assessment of primary hemostasis', 'Obrada prije manjih zahvata, sklonost modricama i krvarenju desni, procjena primarne hemostaze', 'Обрада прије мањих захвата, склоност модрицама и крварењу десни, процјена примарне хемостазе', 'Обследование перед небольшими вмешательствами, склонность к синякам и кровоточивости дёсен, оценка первичного гемостаза', 'Abklärung vor kleineren Eingriffen, Neigung zu blauen Flecken und Zahnfleischbluten, Beurteilung der primären Hämostase', 'Küçük girişimler öncesi inceleme, kolay morarma ve diş eti kanaması, birincil hemostazın değerlendirilmesi', 'No special preparation required; inform the doctor and the laboratory in advance about anticoagulants, aspirin and other medications affecting clotting, as only the doctor decides whether to pause them', 'Nije potrebna posebna priprema; o antikoagulansima, aspirinu i drugim lijekovima koji utiču na zgrušavanje unaprijed obavijestite ljekara i laboratoriju, a odluku o pauzi u terapiji donosi isključivo ljekar', 'Није потребна посебна припрема; о антикоагулансима, аспирину и другим лијековима који утичу на згрушавање унапријед обавијестите љекара и лабораторију, а одлуку о паузи у терапији доноси искључиво љекар', 'Специальной подготовки не требуется; о приёме антикоагулянтов, аспирина и других влияющих на свёртывание препаратов заранее сообщите врачу и лаборатории, решение о паузе в приёме принимает только врач', 'Keine besondere Vorbereitung erforderlich; informieren Sie Arzt und Labor vorab über Antikoagulanzien, Aspirin und andere gerinnungswirksame Medikamente, über ein Pausieren entscheidet ausschließlich der Arzt', 'Özel bir hazırlık gerektirmez; antikoagülan, aspirin ve pıhtılaşmayı etkileyen diğer ilaçlar hakkında hekimi ve laboratuvarı önceden bilgilendirin, bunlara ara verilip verilmeyeceğine yalnızca hekim karar verir', 'A prolonged time may be related to platelet function, medication use, or the condition of the vessel wall. The meaning of the result is assessed by a doctor together with other clotting values', 'Produženo vrijeme može biti povezano sa radom trombocita, uzimanjem lijekova ili stanjem zida krvnih sudova. Značaj nalaza procjenjuje ljekar zajedno sa ostalim pokazateljima zgrušavanja', 'Продужено вријеме може бити повезано са радом тромбоцита, узимањем лијекова или стањем зида крвних судова. Значај налаза процјењује љекар заједно са осталим показатељима згрушавања', 'Удлинение времени может быть связано с особенностями работы тромбоцитов, приёмом препаратов или состоянием сосудистой стенки. Значение результата оценивает врач вместе с другими показателями свёртывания', 'Eine verlängerte Zeit kann mit der Funktion der Blutplättchen, der Einnahme von Medikamenten oder dem Zustand der Gefäßwand zusammenhängen. Die Bedeutung des Ergebnisses beurteilt der Arzt zusammen mit weiteren Gerinnungswerten', 'Sürenin uzaması trombositlerin işleyişi, ilaç kullanımı veya damar duvarının durumuyla ilişkili olabilir. Sonucun anlamını hekim diğer pıhtılaşma göstergeleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'coagulation-time'), 'A basic test assessing how long a drawn blood sample takes to form a clot in a tube', 'Osnovna proba koja procjenjuje za koliko uzeta krv stvori ugrušak u epruveti', 'Основна проба која процјењује за колико узета крв створи угрушак у епрувети', 'Базовая проба, оценивающая, за какое время взятая кровь образует сгусток в пробирке', 'Ein grundlegender Test, der beurteilt, wie lange eine entnommene Blutprobe im Röhrchen bis zur Gerinnselbildung braucht', 'Alınan kanın tüp içinde ne kadar sürede pıhtı oluşturduğunu değerlendiren temel bir test', 'Blood is drawn and the formation of a clot in the tube is observed at a controlled temperature, taking a few minutes', 'Uzima se krv i prati se stvaranje ugruška u epruveti na kontrolisanoj temperaturi, traje nekoliko minuta', 'Узима се крв и прати се стварање угрушка у епрувети на контролисаној температури, траје неколико минута', 'Забор крови и наблюдение за образованием сгустка в пробирке при контролируемой температуре, занимает несколько минут', 'Es wird Blut entnommen und die Gerinnselbildung im Röhrchen bei kontrollierter Temperatur beobachtet, dauert wenige Minuten', 'Kan alınır ve kontrollü sıcaklıkta tüpte pıhtı oluşumu izlenir, birkaç dakika sürer', 'Rough assessment of clotting before procedures, work-up for bleeding tendency, supplement to other coagulation tests', 'Okvirna procjena zgrušavanja prije zahvata, obrada kod sklonosti krvarenju, dopuna drugim koagulacionim testovima', 'Оквирна процјена згрушавања прије захвата, обрада код склоности крварењу, допуна другим коагулационим тестовима', 'Ориентировочная оценка свёртывания перед вмешательствами, обследование при кровоточивости, дополнение к другим коагуляционным тестам', 'Grobe Einschätzung der Gerinnung vor Eingriffen, Abklärung bei Blutungsneigung, Ergänzung zu anderen Gerinnungstests', 'Girişim öncesi pıhtılaşmanın kaba değerlendirmesi, kanamaya eğilimde inceleme, diğer koagülasyon testlerinin tamamlayıcısı', 'No special preparation required; tell the doctor and the laboratory about anticoagulants and other medications affecting clotting, and do not stop them on your own', 'Nije potrebna posebna priprema; o antikoagulansima i drugim lijekovima koji utiču na zgrušavanje obavijestite ljekara i laboratoriju, njihovo prekidanje na svoju ruku nije dozvoljeno', 'Није потребна посебна припрема; о антикоагулансима и другим лијековима који утичу на згрушавање обавијестите љекара и лабораторију, њихово прекидање на своју руку није дозвољено', 'Специальной подготовки не требуется; о приёме антикоагулянтов и других влияющих на свёртывание препаратов предупредите врача и лабораторию, самостоятельно отменять их нельзя', 'Keine besondere Vorbereitung erforderlich; informieren Sie Arzt und Labor über Antikoagulanzien und andere gerinnungswirksame Medikamente und setzen Sie diese nicht eigenmächtig ab', 'Özel bir hazırlık gerektirmez; antikoagülanlar ve pıhtılaşmayı etkileyen diğer ilaçlar hakkında hekimi ve laboratuvarı bilgilendirin, bu ilaçları kendi başınıza bırakmayın', 'Deviations may be related to medication use, a lack of clotting factors, or the conditions of sample collection. The result is interpreted by a doctor, usually together with more precise tests', 'Odstupanja mogu biti povezana sa uzimanjem lijekova, nedostatkom faktora zgrušavanja ili uslovima uzimanja uzorka. Nalaz tumači ljekar, obično uz preciznije testove', 'Одступања могу бити повезана са узимањем лијекова, недостатком фактора згрушавања или условима узимања узорка. Налаз тумачи љекар, обично уз прецизније тестове', 'Отклонения могут быть связаны с приёмом препаратов, недостатком факторов свёртывания или условиями забора материала. Результат трактует врач, обычно вместе с более точными тестами', 'Abweichungen können mit der Einnahme von Medikamenten, einem Mangel an Gerinnungsfaktoren oder den Bedingungen der Probenentnahme zusammenhängen. Das Ergebnis interpretiert der Arzt, meist zusammen mit genaueren Tests', 'Sapmalar ilaç kullanımı, pıhtılaşma faktörlerinin eksikliği veya örnek alma koşullarıyla ilişkili olabilir. Sonucu hekim, genellikle daha kesin testlerle birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'antithrombin-iii'), 'A blood test for a natural protein that restrains excessive clotting', 'Analiza krvi na prirodni protein koji sprječava pretjerano zgrušavanje', 'Анализа крви на природни протеин који спрјечава претјерано згрушавање', 'Анализ крови на естественный белок, сдерживающий избыточное свёртывание', 'Bluttest auf ein körpereigenes Eiweiß, das eine übermäßige Gerinnung bremst', 'Aşırı pıhtılaşmayı frenleyen doğal bir proteini ölçen kan testi', 'Venous blood draw into a citrate tube', 'Uzimanje venske krvi u epruvetu sa citratom', 'Узимање венске крви у епрувету са цитратом', 'Забор венозной крови в пробирку с цитратом', 'Entnahme von venösem Blut in ein Citratröhrchen', 'Sitratlı tüpe venöz kan alımı', 'Work-up for recurrent thrombosis, thrombosis at a young age, family tendency to thrombosis, pregnancy planning as directed by a doctor', 'Obrada kod ponovljenih tromboza, tromboze u mlađem životnom dobu, porodične sklonosti trombozama, planiranje trudnoće po uputu ljekara', 'Обрада код поновљених тромбоза, тромбозе у млађем животном добу, породичне склоности тромбозама, планирање трудноће по упуту љекара', 'Обследование при повторных тромбозах, тромбозе в молодом возрасте, семейной склонности к тромбозам, планирование беременности по назначению врача', 'Abklärung bei wiederholten Thrombosen, Thrombose in jungen Jahren, familiärer Thromboseneigung, Schwangerschaftsplanung auf ärztliche Anweisung', 'Tekrarlayan tromboz, genç yaşta tromboz, ailede tromboz eğilimi, hekim yönlendirmesiyle gebelik planlaması', 'The sample is taken outside an acute thrombosis episode; heparin, warfarin and other anticoagulants must be reported to the doctor and the laboratory, and only the doctor decides on any pause in treatment', 'Uzorak se uzima van akutne epizode tromboze; o heparinu, varfarinu i drugim antikoagulansima obavezno se obavještavaju ljekar i laboratorija, a o pauzi u terapiji odlučuje ljekar', 'Узорак се узима ван акутне епизоде тромбозе; о хепарину, варфарину и другим антикоагулансима обавезно се обавјештавају љекар и лабораторија, а о паузи у терапији одлучује љекар', 'Кровь сдают вне острого эпизода тромбоза; о приёме гепарина, варфарина и других антикоагулянтов обязательно сообщают врачу и лаборатории, а решение о паузе в лечении принимает врач', 'Die Probe wird außerhalb eines akuten Thromboseereignisses entnommen; Heparin, Warfarin und andere Antikoagulanzien sind Arzt und Labor mitzuteilen, über eine Pause der Behandlung entscheidet allein der Arzt', 'Örnek akut tromboz dönemi dışında alınır; heparin, varfarin ve diğer antikoagülanlar hekime ve laboratuvara mutlaka bildirilir, tedaviye ara verilip verilmeyeceğine yalnızca hekim karar verir', 'A reduced value may be related to inherited features, liver disease, protein loss, or the influence of medications. The result is assessed by a doctor, usually as part of a thrombophilia panel', 'Sniženje vrijednosti može biti povezano sa nasljednim osobinama, oboljenjima jetre, gubitkom bjelančevina ili uticajem lijekova. Nalaz procjenjuje ljekar, obično u sklopu panela za trombofiliju', 'Снижење вриједности може бити повезано са насљедним особинама, обољењима јетре, губитком бјеланчевина или утицајем лијекова. Налаз процјењује љекар, обично у склопу панела за тромбофилију', 'Снижение показателя может быть связано с наследственными особенностями, болезнями печени, потерей белка или влиянием лекарств. Результат оценивает врач, обычно в составе панели на тромбофилию', 'Ein erniedrigter Wert kann mit erblichen Besonderheiten, Lebererkrankungen, Eiweißverlust oder dem Einfluss von Medikamenten zusammenhängen. Das Ergebnis beurteilt der Arzt, meist im Rahmen einer Thrombophilie-Abklärung', 'Değerin düşük olması kalıtsal özellikler, karaciğer hastalıkları, protein kaybı veya ilaç etkisiyle ilişkili olabilir. Sonucu hekim, genellikle trombofili paneli kapsamında değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'lupus-anticoagulant'), 'A blood test for antibodies that interfere with phospholipid-dependent clotting reactions in the tube', 'Ispitivanje krvi na antitijela koja ometaju fosfolipid-zavisne reakcije zgrušavanja u epruveti', 'Испитивање крви на антитијела која ометају фосфолипид-зависне реакције згрушавања у епрувети', 'Исследование крови на антитела, влияющие на фосфолипид-зависимые реакции свёртывания в пробирке', 'Blutuntersuchung auf Antikörper, die phospholipidabhängige Gerinnungsreaktionen im Reagenzglas stören', 'Tüp içinde fosfolipide bağlı pıhtılaşma tepkimelerini bozan antikorları araştıran kan tetkiki', 'Venous blood draw; the test is performed as a set of coagulation assays, and a positive result is usually repeated after some time', 'Uzimanje venske krvi, ispitivanje se radi setom koagulacionih testova, a pozitivan nalaz se obično ponavlja nakon izvjesnog vremena', 'Узимање венске крви, испитивање се ради сетом коагулационих тестова, а позитиван налаз се обично понавља након извјесног времена', 'Забор венозной крови, исследование выполняется набором коагуляционных тестов, положительный результат обычно повторяют спустя некоторое время', 'Entnahme von venösem Blut; die Untersuchung besteht aus mehreren Gerinnungstests, ein positiver Befund wird in der Regel nach einiger Zeit wiederholt', 'Venöz kan alınır, inceleme bir dizi koagülasyon testiyle yapılır ve pozitif sonuç genellikle bir süre sonra yinelenir', 'Work-up for thrombosis, recurrent pregnancy loss, autoimmune diseases as directed by a doctor, unexplained prolongation of clotting tests', 'Obrada kod tromboza, ponovljenih gubitaka trudnoće, autoimunih oboljenja po uputu ljekara, neobjašnjenog produženja koagulacionih testova', 'Обрада код тромбоза, поновљених губитака трудноће, аутоимуних обољења по упуту љекара, необјашњеног продужења коагулационих тестова', 'Обследование при тромбозах, повторных потерях беременности, аутоиммунных заболеваниях по назначению врача, необъяснимом удлинении коагуляционных тестов', 'Abklärung bei Thrombosen, wiederholten Fehlgeburten, Autoimmunerkrankungen auf ärztliche Anweisung, ungeklärter Verlängerung von Gerinnungstests', 'Tromboz, yinelenen gebelik kayıpları, hekim yönlendirmesiyle otoimmün hastalıklar, koagülasyon testlerinde açıklanamayan uzama', 'No special preparation required; anticoagulants and heparin affect the result, so they are reported to the doctor and the laboratory in advance, and the doctor decides on the timing of the test', 'Nije potrebna posebna priprema; antikoagulansi i heparin utiču na nalaz, pa se o njima unaprijed obavještavaju ljekar i laboratorija, a termin vađenja određuje ljekar', 'Није потребна посебна припрема; антикоагуланси и хепарин утичу на налаз, па се о њима унапријед обавјештавају љекар и лабораторија, а термин вађења одређује љекар', 'Специальной подготовки не требуется; антикоагулянты и гепарин влияют на результат, поэтому о них заранее сообщают врачу и лаборатории, а срок сдачи определяет врач', 'Keine besondere Vorbereitung erforderlich; Antikoagulanzien und Heparin beeinflussen den Befund und werden Arzt und Labor vorab mitgeteilt, den Zeitpunkt der Blutentnahme legt der Arzt fest', 'Özel bir hazırlık gerektirmez; antikoagülanlar ve heparin sonucu etkiler, bu nedenle hekime ve laboratuvara önceden bildirilir, kan alma zamanını hekim belirler', 'A positive result may be related to antiphospholipid antibodies, a recent infection, or the influence of medications, and is not a diagnosis in itself. Confirmation requires repeat testing and assessment by a doctor', 'Pozitivan nalaz može biti povezan sa antifosfolipidnim antitijelima, nedavnom infekcijom ili uticajem lijekova i sam po sebi nije dijagnoza. Potvrda zahtijeva ponovljeno ispitivanje i procjenu ljekara', 'Позитиван налаз може бити повезан са антифосфолипидним антитијелима, недавном инфекцијом или утицајем лијекова и сам по себи није дијагноза. Потврда захтијева поновљено испитивање и процјену љекара', 'Положительный результат может быть связан с антифосфолипидными антителами, недавней инфекцией или влиянием лекарств и сам по себе не является диагнозом. Подтверждение требует повторного исследования и оценки врача', 'Ein positiver Befund kann mit Antiphospholipid-Antikörpern, einer kürzlichen Infektion oder dem Einfluss von Medikamenten zusammenhängen und ist für sich genommen keine Diagnose. Die Bestätigung erfordert eine Wiederholung und die Beurteilung durch den Arzt', 'Pozitif sonuç antifosfolipid antikorlarıyla, yakın zamanda geçirilen bir enfeksiyonla veya ilaç etkisiyle ilişkili olabilir ve tek başına tanı değildir. Doğrulama için testin yinelenmesi ve hekim değerlendirmesi gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protein-c'), 'A blood test for one of the natural regulatory proteins of clotting produced by the liver', 'Analiza krvi na jedan od prirodnih proteina regulatora zgrušavanja koje stvara jetra', 'Анализа крви на један од природних протеина регулатора згрушавања које ствара јетра', 'Анализ крови на один из естественных белков-регуляторов свёртывания, вырабатываемых печенью', 'Bluttest auf eines der natürlichen, in der Leber gebildeten Regulatorproteine der Gerinnung', 'Karaciğerde üretilen ve pıhtılaşmayı düzenleyen doğal proteinlerden birini ölçen kan testi', 'Venous blood draw into a citrate tube', 'Uzimanje venske krvi u citratnu epruvetu', 'Узимање венске крви у цитратну епрувету', 'Забор венозной крови в цитратную пробирку', 'Entnahme von venösem Blut in ein Citratröhrchen', 'Sitratlı tüpe venöz kan alımı', 'Work-up for venous thrombosis, family tendency to thrombosis, treatment planning as directed by a doctor', 'Obrada kod venskih tromboza, porodične sklonosti trombozama, planiranje terapije po uputu ljekara', 'Обрада код венских тромбоза, породичне склоности тромбозама, планирање терапије по упуту љекара', 'Обследование при венозных тромбозах, семейной склонности к тромбозам, планирование терапии по назначению врача', 'Abklärung bei Venenthrombosen, familiärer Thromboseneigung, Therapieplanung auf ärztliche Anweisung', 'Ven trombozu, ailede tromboz eğilimi, hekim yönlendirmesiyle tedavi planlaması', 'Taken outside an acute thrombosis; warfarin and other anticoagulants are reported to the doctor and the laboratory, and the doctor sets the timing of the test relative to therapy', 'Vadi se van akutne tromboze; o varfarinu i drugim antikoagulansima obavještavaju se ljekar i laboratorija, a vrijeme vađenja u odnosu na terapiju određuje ljekar', 'Вади се ван акутне тромбозе; о варфарину и другим антикоагулансима обавјештавају се љекар и лабораторија, а вријеме вађења у односу на терапију одређује љекар', 'Сдают вне острого тромбоза; о приёме варфарина и других антикоагулянтов предупреждают врача и лабораторию, а срок сдачи относительно терапии назначает врач', 'Die Entnahme erfolgt außerhalb einer akuten Thrombose; Warfarin und andere Antikoagulanzien werden Arzt und Labor mitgeteilt, den Zeitpunkt im Verhältnis zur Therapie bestimmt der Arzt', 'Akut tromboz dönemi dışında alınır; varfarin ve diğer antikoagülanlar hekime ve laboratuvara bildirilir, testin tedaviye göre zamanlamasını hekim belirler', 'A reduced value may be related to inherited deficiency, liver disease, lack of vitamin K, or medication use. The result is interpreted by a doctor together with other thrombophilia tests', 'Sniženje može biti povezano sa nasljednim nedostatkom, oboljenjima jetre, manjkom vitamina K ili uzimanjem lijekova. Nalaz tumači ljekar zajedno sa ostalim testovima na trombofiliju', 'Снижење може бити повезано са насљедним недостатком, обољењима јетре, мањком витамина К или узимањем лијекова. Налаз тумачи љекар заједно са осталим тестовима на тромбофилију', 'Снижение может быть связано с наследственным дефицитом, заболеваниями печени, нехваткой витамина K или приёмом препаратов. Результат интерпретирует врач вместе с другими тестами на тромбофилию', 'Ein erniedrigter Wert kann mit einem angeborenen Mangel, Lebererkrankungen, Vitamin-K-Mangel oder der Einnahme von Medikamenten zusammenhängen. Das Ergebnis interpretiert der Arzt zusammen mit weiteren Thrombophilie-Tests', 'Düşük değer kalıtsal eksiklik, karaciğer hastalıkları, K vitamini azlığı veya ilaç kullanımıyla ilişkili olabilir. Sonucu hekim diğer trombofili testleriyle birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protein-s'), 'A blood test for the cofactor protein of the protein C system, involved in restraining clotting', 'Analiza krvi na pomoćni protein sistema proteina C koji učestvuje u kočenju zgrušavanja', 'Анализа крви на помоћни протеин система протеина Ц који учествује у кочењу згрушавања', 'Анализ крови на белок-помощник системы протеина C, участвующий в торможении свёртывания', 'Bluttest auf das Kofaktor-Eiweiß des Protein-C-Systems, das an der Hemmung der Gerinnung beteiligt ist', 'Pıhtılaşmanın frenlenmesinde görev alan, protein C sisteminin yardımcı proteinini ölçen kan testi', 'Venous blood draw into a citrate tube; the laboratory may measure the free and the total fraction', 'Uzimanje venske krvi u citratnu epruvetu, laboratorija može određivati slobodnu i ukupnu frakciju', 'Узимање венске крви у цитратну епрувету, лабораторија може одређивати слободну и укупну фракцију', 'Забор венозной крови в цитратную пробирку, лаборатория может определять свободную и общую фракции', 'Entnahme von venösem Blut in ein Citratröhrchen, das Labor kann die freie und die Gesamtfraktion bestimmen', 'Sitratlı tüpe venöz kan alımı, laboratuvar serbest ve toplam fraksiyonu ölçebilir', 'Work-up for venous thrombosis, thrombosis at unusual sites, thrombosis in close relatives as directed by a doctor', 'Obrada kod venskih tromboza, tromboza neuobičajene lokalizacije, tromboza kod bliskih srodnika po uputu ljekara', 'Обрада код венских тромбоза, тромбоза неуобичајене локализације, тромбоза код блиских сродника по упуту љекара', 'Обследование при венозных тромбозах, тромбозах необычной локализации, тромбозах у близких родственников по назначению врача', 'Abklärung bei Venenthrombosen, Thrombosen an ungewöhnlicher Stelle, Thrombosen bei nahen Verwandten auf ärztliche Anweisung', 'Ven trombozu, alışılmadık bölgelerde tromboz, hekim yönlendirmesiyle yakın akrabalarda görülen tromboz', 'Taken outside an acute thrombosis and, where possible, outside pregnancy; hormonal contraception and anticoagulants are reported to the doctor and the laboratory, and medications must not be stopped on your own', 'Vadi se van akutne tromboze i po mogućnosti van trudnoće; o hormonskoj kontracepciji i antikoagulansima obavještavaju se ljekar i laboratorija, a lijekovi se ne prekidaju na svoju ruku', 'Вади се ван акутне тромбозе и по могућности ван трудноће; о хормонској контрацепцији и антикоагулансима обавјештавају се љекар и лабораторија, а лијекови се не прекидају на своју руку', 'Сдают вне острого тромбоза и по возможности вне беременности; о гормональной контрацепции и антикоагулянтах сообщают врачу и лаборатории, самостоятельно отменять препараты нельзя', 'Die Entnahme erfolgt außerhalb einer akuten Thrombose und möglichst außerhalb einer Schwangerschaft; hormonelle Verhütung und Antikoagulanzien werden Arzt und Labor mitgeteilt, Medikamente dürfen nicht eigenmächtig abgesetzt werden', 'Akut tromboz dışında ve mümkünse gebelik dışında alınır; hormonal doğum kontrol yöntemleri ve antikoagülanlar hekime ve laboratuvara bildirilir, ilaçlar kendi başınıza bırakılmamalıdır', 'A reduced value may be related to inherited features, pregnancy, hormonal medication, or liver disease. The conclusion is made by a doctor, often after a repeat test', 'Sniženje može biti povezano sa nasljednim osobinama, trudnoćom, uzimanjem hormonskih lijekova ili oboljenjima jetre. Zaključak donosi ljekar, često nakon ponovljenog ispitivanja', 'Снижење може бити повезано са насљедним особинама, трудноћом, узимањем хормонских лијекова или обољењима јетре. Закључак доноси љекар, често након поновљеног испитивања', 'Снижение может быть связано с наследственными особенностями, беременностью, приёмом гормональных препаратов или болезнями печени. Итог оценивает врач, часто после повторного исследования', 'Ein erniedrigter Wert kann mit erblichen Besonderheiten, einer Schwangerschaft, hormonellen Medikamenten oder Lebererkrankungen zusammenhängen. Die Beurteilung trifft der Arzt, häufig nach einer Wiederholung', 'Düşük değer kalıtsal özellikler, gebelik, hormonal ilaç kullanımı veya karaciğer hastalıklarıyla ilişkili olabilir. Sonucu hekim, çoğu zaman tekrar testten sonra değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'phosphorus'), 'Blood test for inorganic phosphate — a mineral involved in bone and energy metabolism', 'Analiza krvi na neorganski fosfat, mineral koji učestvuje u metabolizmu kostiju i energije', 'Анализа крви на неоргански фосфат, минерал који учествује у метаболизму костију и енергије', 'Анализ крови на неорганический фосфат — минерал, участвующий в обмене костной ткани и энергии', 'Bluttest auf anorganisches Phosphat, einen Mineralstoff des Knochen- und Energiestoffwechsels', 'Kemik ve enerji metabolizmasında rol alan bir mineral olan inorganik fosfatı ölçen kan testi', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Venöz kan alımı', 'Assessment of bone and mineral metabolism, kidney disease, disturbances of calcium and vitamin D levels, follow-up of chronic conditions as directed by a doctor', 'Procjena koštanog i mineralnog metabolizma, bubrežna oboljenja, poremećaji nivoa kalcijuma i vitamina D, praćenje hroničnih bolesti po uputu ljekara', 'Процјена коштаног и минералног метаболизма, бубрежна обољења, поремећаји нивоа калцијума и витамина Д, праћење хроничних болести по упуту љекара', 'Оценка костного и минерального обмена, заболевания почек, нарушения уровня кальция и витамина D, наблюдение при хронических болезнях по назначению врача', 'Beurteilung des Knochen- und Mineralstoffwechsels, Nierenerkrankungen, Störungen des Kalzium- und Vitamin-D-Spiegels, Verlaufskontrolle chronischer Erkrankungen auf ärztliche Anweisung', 'Kemik ve mineral metabolizmasının değerlendirilmesi, böbrek hastalıkları, kalsiyum ve D vitamini düzeyi bozuklukları, hekim yönlendirmesiyle kronik hastalık takibi', 'In the morning on an empty stomach, water allowed; supplements with phosphates and vitamin D are taken the day before only in agreement with the doctor', 'Ujutru natašte, dozvoljena je voda; dodaci sa fosfatima i vitaminom D uzimaju se dan ranije samo uz dogovor sa ljekarom', 'Ујутру наташте, дозвољена је вода; додаци са фосфатима и витамином Д узимају се дан раније само уз договор са љекаром', 'Утром натощак, разрешена вода; добавки с фосфатами и витамином D накануне принимают только по согласованию с врачом', 'Morgens nüchtern, Wasser ist erlaubt; Präparate mit Phosphat und Vitamin D am Vortag nur in Absprache mit dem Arzt einnehmen', 'Sabah aç karnına, su içilebilir; fosfat ve D vitamini içeren takviyeler bir gün önce yalnızca hekimle görüşerek alınır', 'Changes may be related to kidney function, calcium metabolism, parathyroid function, or diet. The meaning of the result is determined by a doctor together with calcium and other values', 'Promjene mogu biti povezane sa radom bubrega, metabolizmom kalcijuma, funkcijom paratireoidnih žlijezda ili ishranom. Značenje nalaza određuje ljekar uz kalcijum i druge pokazatelje', 'Промјене могу бити повезане са радом бубрега, метаболизмом калцијума, функцијом паратиреоидних жлијезда или исхраном. Значење налаза одређује љекар уз калцијум и друге показатеље', 'Изменения могут быть связаны с работой почек, обменом кальция, функцией паращитовидных желёз или питанием. Значение результата определяет врач в сочетании с кальцием и другими показателями', 'Veränderungen können mit der Nierenfunktion, dem Kalziumstoffwechsel, der Funktion der Nebenschilddrüsen oder der Ernährung zusammenhängen. Die Bedeutung des Ergebnisses bestimmt der Arzt zusammen mit Kalzium und weiteren Werten', 'Değişiklikler böbrek işlevi, kalsiyum metabolizması, paratiroid bezlerinin çalışması veya beslenmeyle ilişkili olabilir. Sonucun anlamını hekim kalsiyum ve diğer değerlerle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ionized-calcium'), 'Blood test for the free, biologically active portion of calcium that is not bound to proteins', 'Analiza krvi na slobodni, biološki aktivni dio kalcijuma koji nije vezan za bjelančevine', 'Анализа крви на слободни, биолошки активни дио калцијума који није везан за бјеланчевине', 'Анализ крови на свободную, биологически активную часть кальция, не связанную с белками', 'Bluttest auf den freien, biologisch aktiven Anteil des Kalziums, der nicht an Eiweiße gebunden ist', 'Kalsiyumun proteine bağlı olmayan, serbest ve biyolojik olarak etkin bölümünü ölçen kan testi', 'Venous or arterial blood draw with prompt delivery to the laboratory, often performed together with blood gas analysis', 'Uzimanje venske ili arterijske krvi uz brzu dostavu u laboratoriju, često se radi zajedno sa gasnim analizama krvi', 'Узимање венске или артеријске крви уз брзу доставу у лабораторију, често се ради заједно са гасним анализама крви', 'Забор венозной или артериальной крови с быстрой доставкой в лабораторию, часто выполняется вместе с анализом газов крови', 'Entnahme von venösem oder arteriellem Blut mit rascher Zustellung ins Labor, häufig zusammen mit der Blutgasanalyse', 'Venöz veya arteriyel kan alınır ve hızla laboratuvara ulaştırılır, sıklıkla kan gazı analiziyle birlikte yapılır', 'Clarification of calcium metabolism disorders, parathyroid disease, kidney failure, monitoring in intensive care', 'Razjašnjenje poremećaja metabolizma kalcijuma, oboljenja paratireoidnih žlijezda, bubrežna slabost, praćenje stanja u intenzivnoj njezi', 'Разјашњење поремећаја метаболизма калцијума, обољења паратиреоидних жлијезда, бубрежна слабост, праћење стања у интензивној њези', 'Уточнение нарушений кальциевого обмена, заболевания паращитовидных желёз, почечная недостаточность, наблюдение за состоянием при интенсивной терапии', 'Klärung von Störungen des Kalziumstoffwechsels, Erkrankungen der Nebenschilddrüsen, Niereninsuffizienz, Überwachung in der Intensivmedizin', 'Kalsiyum metabolizması bozukluklarının netleştirilmesi, paratiroid hastalıkları, böbrek yetmezliği, yoğun bakımda izlem', 'In the morning on an empty stomach, without prolonged fist clenching or tourniquet use; calcium and vitamin D supplements are reported to the laboratory', 'Ujutru natašte, bez dužeg stiskanja šake i podveze; o preparatima kalcijuma i vitamina D obavještava se laboratorija', 'Ујутру наташте, без дужег стискања шаке и подвезе; о препаратима калцијума и витамина Д обавјештава се лабораторија', 'Утром натощак, без длительного сжимания кулака и жгута; о приёме препаратов кальция и витамина D сообщают лаборатории', 'Morgens nüchtern, ohne längeres Faustschließen und Abbinden; Kalzium- und Vitamin-D-Präparate werden dem Labor mitgeteilt', 'Sabah aç karnına, yumruk uzun süre sıkılmadan ve turnike uzun tutulmadan; kalsiyum ve D vitamini takviyeleri laboratuvara bildirilir', 'Deviations may be related to parathyroid and kidney function, vitamin D level, or the acid-base state of the blood. The assessment is made by a doctor taking total calcium and albumin into account', 'Odstupanja mogu biti povezana sa funkcijom paratireoidnih žlijezda i bubrega, nivoom vitamina D ili acido-baznim stanjem krvi. Procjenu vrši ljekar uz ukupni kalcijum i albumin', 'Одступања могу бити повезана са функцијом паратиреоидних жлијезда и бубрега, нивоом витамина Д или ацидо-базним стањем крви. Процјену врши љекар уз укупни калцијум и албумин', 'Отклонения могут быть связаны с функцией паращитовидных желёз и почек, уровнем витамина D или кислотно-щелочным состоянием крови. Оценку проводит врач с учётом общего кальция и альбумина', 'Abweichungen können mit der Funktion der Nebenschilddrüsen und der Nieren, dem Vitamin-D-Spiegel oder dem Säure-Basen-Status des Blutes zusammenhängen. Die Beurteilung erfolgt durch den Arzt unter Berücksichtigung von Gesamtkalzium und Albumin', 'Sapmalar paratiroid ve böbrek işlevi, D vitamini düzeyi veya kanın asit-baz durumuyla ilişkili olabilir. Değerlendirmeyi hekim, total kalsiyum ve albümini de dikkate alarak yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'magnesium'), 'Blood test for magnesium — a mineral important for muscle and nerve function and heart rhythm', 'Analiza krvi na magnezijum, mineral važan za rad mišića, nerava i srčanog ritma', 'Анализа крви на магнезијум, минерал важан за рад мишића, нерава и срчаног ритма', 'Анализ крови на магний — минерал, важный для работы мышц, нервов и сердечного ритма', 'Bluttest auf Magnesium, einen Mineralstoff für Muskel- und Nervenfunktion sowie den Herzrhythmus', 'Kas ve sinir işlevi ile kalp ritmi için önemli bir mineral olan magnezyumu ölçen kan testi', 'Venous blood draw', 'Uzimanje venske krvi', 'Узимање венске крви', 'Забор венозной крови', 'Entnahme von venösem Blut', 'Venöz kan alımı', 'Cramps and muscle twitching, heart rhythm disturbances, long-term diuretic use, kidney and bowel disease, monitoring during tube feeding', 'Grčevi i trzanje mišića, poremećaji srčanog ritma, dugotrajno uzimanje diuretika, oboljenja bubrega i crijeva, praćenje kod ishrane preko sonde', 'Грчеви и трзање мишића, поремећаји срчаног ритма, дуготрајно узимање диуретика, обољења бубрега и цријева, праћење код исхране преко сонде', 'Судороги и подёргивания мышц, нарушения сердечного ритма, длительный приём мочегонных, заболевания почек и кишечника, контроль при питании через зонд', 'Krämpfe und Muskelzucken, Herzrhythmusstörungen, langfristige Einnahme von Diuretika, Nieren- und Darmerkrankungen, Kontrolle bei Sondenernährung', 'Kramplar ve kas seğirmeleri, kalp ritmi bozuklukları, uzun süreli diüretik kullanımı, böbrek ve bağırsak hastalıkları, sonda ile beslenmede izlem', 'In the morning on an empty stomach; magnesium supplements and laxatives taken the day before should be mentioned to the doctor, as they change the result', 'Ujutru natašte; o preparatima magnezijuma i laksativima uzetim dan ranije treba reći ljekaru jer mijenjaju nalaz', 'Ујутру наташте; о препаратима магнезијума и лаксативима узетим дан раније треба рећи љекару јер мијењају налаз', 'Утром натощак; о препаратах магния и слабительных, принятых накануне, нужно сказать врачу, так как они меняют результат', 'Morgens nüchtern; am Vortag eingenommene Magnesiumpräparate und Abführmittel sollten dem Arzt mitgeteilt werden, da sie das Ergebnis verändern', 'Sabah aç karnına; bir gün önce alınan magnezyum takviyeleri ve müshiller sonucu değiştirdiği için hekime söylenmelidir', 'Deviations may be related to diet, losses through the kidneys or bowel, or medication use. The interpretation is given by a doctor together with potassium and calcium', 'Odstupanja mogu biti povezana sa ishranom, gubicima preko bubrega ili crijeva i uzimanjem lijekova. Tumačenje daje ljekar zajedno sa kalijumom i kalcijumom', 'Одступања могу бити повезана са исхраном, губицима преко бубрега или цријева и узимањем лијекова. Тумачење даје љекар заједно са калијумом и калцијумом', 'Отклонения могут быть связаны с питанием, потерями через почки или кишечник, приёмом лекарств. Трактовку даёт врач вместе с калием и кальцием', 'Abweichungen können mit der Ernährung, Verlusten über Nieren oder Darm sowie der Einnahme von Medikamenten zusammenhängen. Die Interpretation nimmt der Arzt zusammen mit Kalium und Kalzium vor', 'Sapmalar beslenme, böbrek veya bağırsak yoluyla kayıplar ya da ilaç kullanımıyla ilişkili olabilir. Yorumu hekim potasyum ve kalsiyumla birlikte yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chloride'), 'Blood test for chloride — the main negatively charged electrolyte of the fluid outside the cells', 'Analiza krvi na hloride, glavni negativno naelektrisani elektrolit tečnosti izvan ćelija', 'Анализа крви на хлориде, главни негативно наелектрисани електролит течности изван ћелија', 'Анализ крови на хлориды — основной отрицательно заряженный электролит внеклеточной жидкости', 'Bluttest auf Chlorid, das wichtigste negativ geladene Elektrolyt der Flüssigkeit außerhalb der Zellen', 'Hücre dışı sıvının başlıca negatif yüklü elektroliti olan klorürü ölçen kan testi', 'Venous blood draw, most often together with sodium and potassium', 'Uzimanje venske krvi, najčešće zajedno sa natrijumom i kalijumom', 'Узимање венске крви, најчешће заједно са натријумом и калијумом', 'Забор венозной крови, чаще всего вместе с натрием и калием', 'Entnahme von venösem Blut, meist zusammen mit Natrium und Kalium', 'Venöz kan alımı, çoğunlukla sodyum ve potasyumla birlikte', 'Assessment of water and salt balance, dehydration, vomiting and diarrhea, kidney disease, work-up of acid-base disturbances', 'Procjena vodeno-solne ravnoteže, dehidracija, povraćanje i proljev, bubrežna oboljenja, obrada poremećaja acido-bazne ravnoteže', 'Процјена водено-солне равнотеже, дехидрација, повраћање и прољев, бубрежна обољења, обрада поремећаја ацидо-базне равнотеже', 'Оценка водно-солевого баланса, обезвоживание, рвота и диарея, заболевания почек, разбор нарушений кислотно-щелочного равновесия', 'Beurteilung des Wasser- und Salzhaushalts, Austrocknung, Erbrechen und Durchfall, Nierenerkrankungen, Abklärung von Säure-Basen-Störungen', 'Su-tuz dengesinin değerlendirilmesi, sıvı kaybı, kusma ve ishal, böbrek hastalıkları, asit-baz bozukluklarının incelenmesi', 'No special preparation required, a morning draw is preferable; diuretics and intravenous fluids are reported to the doctor', 'Nije potrebna posebna priprema, poželjno je jutarnje vađenje; o diureticima i infuzijama obavještava se ljekar', 'Није потребна посебна припрема, пожељно је јутарње вађење; о диуретицима и инфузијама обавјештава се љекар', 'Специальной подготовки не требуется, предпочтителен утренний забор; о мочегонных и капельницах сообщают врачу', 'Keine besondere Vorbereitung erforderlich, eine Entnahme am Morgen ist vorzuziehen; Diuretika und Infusionen werden dem Arzt mitgeteilt', 'Özel bir hazırlık gerektirmez, sabah alınması tercih edilir; diüretikler ve damar içi sıvılar hekime bildirilir', 'Changes may be related to fluid loss, renal and respiratory regulation mechanisms, or medication use. The result is assessed together with sodium and bicarbonate, and the conclusion is made by a doctor', 'Promjene mogu biti povezane sa gubitkom tečnosti, bubrežnim i disajnim mehanizmima regulacije ili uzimanjem lijekova. Nalaz se procjenjuje uz natrijum i bikarbonate, a zaključak donosi ljekar', 'Промјене могу бити повезане са губитком течности, бубрежним и дисајним механизмима регулације или узимањем лијекова. Налаз се процјењује уз натријум и бикарбонате, а закључак доноси љекар', 'Изменения могут быть связаны с потерей жидкости, почечными и дыхательными механизмами регуляции, приёмом препаратов. Результат оценивают вместе с натрием и бикарбонатами, вывод делает врач', 'Veränderungen können mit Flüssigkeitsverlusten, Regulationsmechanismen von Nieren und Lunge oder der Einnahme von Medikamenten zusammenhängen. Der Wert wird zusammen mit Natrium und Bikarbonat beurteilt, die Schlussfolgerung zieht der Arzt', 'Değişiklikler sıvı kaybı, böbrek ve solunum yoluyla düzenleme mekanizmaları veya ilaç kullanımıyla ilişkili olabilir. Sonuç sodyum ve bikarbonatla birlikte değerlendirilir, kararı hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bicarbonates'), 'A blood value reflecting the alkaline reserve and the role of the kidneys in maintaining acid-base balance', 'Pokazatelj u krvi koji odražava alkalnu rezervu i ulogu bubrega u održavanju acido-bazne ravnoteže', 'Показатељ у крви који одражава алкалну резерву и улогу бубрега у одржавању ацидо-базне равнотеже', 'Показатель крови, отражающий щелочной резерв и участие почек в поддержании кислотно-щелочного равновесия', 'Ein Blutwert, der die alkalische Reserve und die Rolle der Nieren im Säure-Basen-Haushalt widerspiegelt', 'Alkali rezervi ve böbreklerin asit-baz dengesindeki rolünü yansıtan bir kan değeri', 'Measured in venous or arterial blood, often as part of a blood gas analysis, with the sample delivered to the laboratory immediately', 'Određuje se u venskoj ili arterijskoj krvi, često u sklopu gasnih analiza, a uzorak se odmah dostavlja u laboratoriju', 'Одређује се у венској или артеријској крви, често у склопу гасних анализа, а узорак се одмах доставља у лабораторију', 'Определяется в венозной или артериальной крови, часто в составе анализа газов крови, образец доставляют в лабораторию сразу', 'Bestimmung in venösem oder arteriellem Blut, häufig im Rahmen der Blutgasanalyse, die Probe wird sofort ins Labor gebracht', 'Venöz veya arteriyel kanda, çoğu zaman kan gazı analizinin bir parçası olarak ölçülür, örnek hemen laboratuvara ulaştırılır', 'Work-up of acid-base disturbances, severe dehydration, kidney and lung disease, monitoring during flare-ups of chronic conditions', 'Obrada poremećaja acido-bazne ravnoteže, teška dehidracija, oboljenja bubrega i pluća, praćenje kod pogoršanja hroničnih bolesti', 'Обрада поремећаја ацидо-базне равнотеже, тешка дехидрација, обољења бубрега и плућа, праћење код погоршања хроничних болести', 'Разбор нарушений кислотно-щелочного равновесия, тяжёлое обезвоживание, заболевания почек и лёгких, наблюдение при обострении хронических болезней', 'Abklärung von Säure-Basen-Störungen, schwere Austrocknung, Nieren- und Lungenerkrankungen, Überwachung bei Verschlechterung chronischer Erkrankungen', 'Asit-baz bozukluklarının incelenmesi, ağır sıvı kaybı, böbrek ve akciğer hastalıkları, kronik hastalıkların alevlenmesinde izlem', 'No special preparation required; before the draw it is important to sit calmly and not to hold your breath', 'Nije potrebna posebna priprema; prije vađenja je važno mirno sjediti i ne zadržavati dah', 'Није потребна посебна припрема; прије вађења је важно мирно сједити и не задржавати дах', 'Специальной подготовки не требуется; перед забором важно спокойно посидеть и не задерживать дыхание', 'Keine besondere Vorbereitung erforderlich; vor der Entnahme ruhig sitzen und die Luft nicht anhalten', 'Özel bir hazırlık gerektirmez; kan alınmadan önce sakin oturmak ve nefes tutmamak önemlidir', 'Deviations may be related to breathing disorders, kidney function, vomiting, or fluid loss. The result is assessed together with pH and blood gases, and interpreted by a doctor', 'Odstupanja mogu biti povezana sa disajnim poremećajima, radom bubrega, povraćanjem ili gubitkom tečnosti. Nalaz se procjenjuje uz pH i gasne analize, a tumači ga ljekar', 'Одступања могу бити повезана са дисајним поремећајима, радом бубрега, повраћањем или губитком течности. Налаз се процјењује уз пХ и гасне анализе, а тумачи га љекар', 'Отклонения могут быть связаны с дыхательными нарушениями, работой почек, рвотой или потерей жидкости. Результат оценивают вместе с pH и газами крови, интерпретацию проводит врач', 'Abweichungen können mit Atemstörungen, der Nierenfunktion, Erbrechen oder Flüssigkeitsverlust zusammenhängen. Der Wert wird zusammen mit pH und Blutgasen beurteilt, die Interpretation erfolgt durch den Arzt', 'Sapmalar solunum bozuklukları, böbrek işlevi, kusma veya sıvı kaybıyla ilişkili olabilir. Sonuç pH ve kan gazlarıyla birlikte değerlendirilir, yorumu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'leukocyte-formula'), 'A count of the proportions of the different types of white blood cells in the sample', 'Brojanje udjela različitih vrsta bijelih krvnih ćelija u uzorku', 'Бројање удјела различитих врста бијелих крвних ћелија у узорку', 'Подсчёт долей разных видов белых клеток крови в образце', 'Auszählung der Anteile der verschiedenen Arten weißer Blutkörperchen in der Probe', 'Örnekteki farklı akyuvar türlerinin oranlarının sayımı', 'Venous or capillary blood draw, counted on an analyzer, with a laboratory technician reviewing the smear under a microscope when needed', 'Uzimanje venske ili kapilarne krvi, brojanje na analizatoru, a po potrebi laborant pregleda razmaz pod mikroskopom', 'Узимање венске или капиларне крви, бројање на анализатору, а по потреби лаборант прегледа размаз под микроскопом', 'Забор венозной или капиллярной крови, подсчёт на анализаторе, при необходимости лаборант просматривает мазок под микроскопом', 'Entnahme von venösem oder kapillarem Blut, Auszählung am Analysegerät, bei Bedarf begutachtet eine Fachkraft den Ausstrich unter dem Mikroskop', 'Venöz veya kapiller kan alınır, sayım cihazda yapılır, gerektiğinde laboratuvar uzmanı yaymayı mikroskopta inceler', 'Clarifying the picture in infections, prolonged fever, inflammatory and allergic conditions, monitoring during treatment', 'Razjašnjenje slike kod infekcija, dugotrajne temperature, upalnih i alergijskih stanja, praćenje tokom liječenja', 'Разјашњење слике код инфекција, дуготрајне температуре, упалних и алергијских стања, праћење током лијечења', 'Уточнение картины при инфекциях, длительной температуре, воспалительных и аллергических состояниях, наблюдение в ходе лечения', 'Genauere Einordnung bei Infektionen, anhaltendem Fieber, entzündlichen und allergischen Zuständen, Verlaufskontrolle während einer Behandlung', 'Enfeksiyonlarda, uzun süren ateşte, iltihabi ve alerjik durumlarda tablonun netleştirilmesi, tedavi sırasında izlem', 'No special preparation required, a morning draw before physical exertion is preferable', 'Nije potrebna posebna priprema, poželjno je vađenje ujutru prije fizičkog napora', 'Није потребна посебна припрема, пожељно је вађење ујутру прије физичког напора', 'Специальной подготовки не требуется, предпочтителен забор утром до физической нагрузки', 'Keine besondere Vorbereitung erforderlich, eine Entnahme am Morgen vor körperlicher Belastung ist vorzuziehen', 'Özel bir hazırlık gerektirmez, sabah ve fiziksel zorlanmadan önce alınması tercih edilir', 'Shifts in the ratio of the cells may be related to bacterial or viral infection, allergy, parasites, medication use, and other causes. The picture is assessed by a doctor together with the symptoms and the rest of the blood values', 'Pomjeranje odnosa ćelija može biti povezano sa bakterijskom ili virusnom infekcijom, alergijom, parazitima, uzimanjem lijekova i drugim uzrocima. Sliku procjenjuje ljekar uz tegobe i ostale pokazatelje krvi', 'Помјерање односа ћелија може бити повезано са бактеријском или вирусном инфекцијом, алергијом, паразитима, узимањем лијекова и другим узроцима. Слику процјењује љекар уз тегобе и остале показатеље крви', 'Сдвиги в соотношении клеток могут быть связаны с бактериальной или вирусной инфекцией, аллергией, паразитами, приёмом препаратов и другими причинами. Картину оценивает врач вместе с жалобами и остальными показателями крови', 'Verschiebungen im Verhältnis der Zellen können mit bakteriellen oder viralen Infektionen, Allergien, Parasiten, Medikamenten und anderen Ursachen zusammenhängen. Das Bild beurteilt der Arzt zusammen mit den Beschwerden und den übrigen Blutwerten', 'Hücre oranlarındaki kaymalar bakteriyel veya viral enfeksiyon, alerji, parazitler, ilaç kullanımı ve başka nedenlerle ilişkili olabilir. Tabloyu hekim şikayetler ve diğer kan değerleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'erythrocyte-resistance'), 'A laboratory test showing how resistant red blood cells are to breaking down in salt solutions of different concentrations', 'Laboratorijska proba koja pokazuje otpornost eritrocita na razgradnju u slanim rastvorima različite koncentracije', 'Лабораторијска проба која показује отпорност еритроцита на разградњу у сланим растворима различите концентрације', 'Лабораторная проба, показывающая устойчивость эритроцитов к разрушению в солевых растворах разной концентрации', 'Ein Labortest, der zeigt, wie widerstandsfähig rote Blutkörperchen gegenüber dem Zerfall in Salzlösungen unterschiedlicher Konzentration sind', 'Alyuvarların farklı yoğunluktaki tuz çözeltilerinde parçalanmaya ne kadar dayanıklı olduğunu gösteren laboratuvar testi', 'Blood is placed in a series of solutions with decreasing salt concentration, and the point where red cell breakdown begins and where it is complete is recorded', 'Krv se stavlja u niz rastvora sa opadajućom koncentracijom soli i bilježi se u kojem počinje i u kojem se završava razgradnja eritrocita', 'Крв се ставља у низ раствора са опадајућом концентрацијом соли и биљежи се у којем почиње и у којем се завршава разградња еритроцита', 'Кровь помещают в серию растворов с убывающей концентрацией соли и отмечают, в каком из них разрушение эритроцитов начинается и в каком завершается', 'Das Blut wird in eine Reihe von Lösungen mit abnehmender Salzkonzentration gegeben, und es wird festgehalten, wo der Zerfall der roten Blutkörperchen beginnt und wo er abgeschlossen ist', 'Kan, tuz yoğunluğu giderek azalan bir dizi çözeltiye konur ve alyuvar parçalanmasının nerede başlayıp nerede tamamlandığı kaydedilir', 'Work-up for suspected inherited features of the red cell membrane, clarifying the cause of anemia as directed by a hematologist', 'Obrada kod sumnje na nasljedne osobine opne eritrocita, razjašnjenje uzroka anemije po uputu hematologa', 'Обрада код сумње на насљедне особине опне еритроцита, разјашњење узрока анемије по упуту хематолога', 'Обследование при подозрении на наследственные особенности оболочки эритроцитов, уточнение причины анемии по назначению гематолога', 'Abklärung bei Verdacht auf erbliche Besonderheiten der Erythrozytenmembran, Klärung der Ursache einer Anämie auf Anweisung eines Hämatologen', 'Alyuvar zarının kalıtsal özelliklerinden şüphelenildiğinde inceleme, hematolog yönlendirmesiyle anemi nedeninin netleştirilmesi', 'No special preparation required; a recent blood transfusion and iron supplements should be reported to the doctor', 'Nije potrebna posebna priprema; o nedavnoj transfuziji krvi i uzimanju preparata gvožđa treba obavijestiti ljekara', 'Није потребна посебна припрема; о недавној трансфузији крви и узимању препарата гвожђа треба обавијестити љекара', 'Специальной подготовки не требуется; о недавнем переливании крови и приёме препаратов железа нужно сообщить врачу', 'Keine besondere Vorbereitung erforderlich; eine kürzliche Bluttransfusion und Eisenpräparate sind dem Arzt mitzuteilen', 'Özel bir hazırlık gerektirmez; yakın zamanda yapılan kan nakli ve demir preparatları hekime bildirilmelidir', 'A change in the resistance of red blood cells may be related to inherited features of their membrane or to other forms of anemia. The result is interpreted by a doctor together with the blood count and the blood smear', 'Promjena otpornosti eritrocita može biti povezana sa nasljednim osobinama njihove opne ili sa drugim oblicima anemije. Nalaz tumači ljekar uz kompletnu krvnu sliku i razmaz krvi', 'Промјена отпорности еритроцита може бити повезана са насљедним особинама њихове опне или са другим облицима анемије. Налаз тумачи љекар уз комплетну крвну слику и размаз крви', 'Изменение устойчивости эритроцитов может быть связано с наследственными особенностями их оболочки или с другими формами анемии. Результат интерпретирует врач вместе с общим анализом крови и мазком', 'Eine veränderte Widerstandsfähigkeit der roten Blutkörperchen kann mit erblichen Besonderheiten ihrer Membran oder mit anderen Formen der Anämie zusammenhängen. Das Ergebnis interpretiert der Arzt zusammen mit dem Blutbild und dem Blutausstrich', 'Alyuvarların direncindeki değişim, hücre zarının kalıtsal özellikleriyle veya başka anemi biçimleriyle ilişkili olabilir. Sonucu hekim tam kan sayımı ve kan yaymasıyla birlikte yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'reticulocytes'), 'A count of young red blood cells that have recently left the bone marrow', 'Brojanje mladih eritrocita koji su nedavno napustili koštanu srž', 'Бројање младих еритроцита који су недавно напустили коштану срж', 'Подсчёт молодых эритроцитов, недавно вышедших из костного мозга', 'Auszählung junger roter Blutkörperchen, die das Knochenmark erst kürzlich verlassen haben', 'Kemik iliğinden yakın zamanda ayrılmış genç alyuvarların sayımı', 'Venous or capillary blood draw, counted on an analyzer or in a stained smear', 'Uzimanje venske ili kapilarne krvi, brojanje na analizatoru ili u obojenom razmazu', 'Узимање венске или капиларне крви, бројање на анализатору или у обојеном размазу', 'Забор венозной или капиллярной крови, подсчёт на анализаторе или в окрашенном мазке', 'Entnahme von venösem oder kapillarem Blut, Auszählung am Analysegerät oder im gefärbten Ausstrich', 'Venöz veya kapiller kan alınır, sayım cihazda veya boyalı yaymada yapılır', 'Clarifying the cause of anemia, assessing the response to iron or vitamin B12 treatment, follow-up after blood loss and in bone marrow disorders', 'Razjašnjenje uzroka anemije, procjena odgovora na terapiju gvožđem ili vitaminom B12, praćenje nakon gubitka krvi i kod oboljenja koštane srži', 'Разјашњење узрока анемије, процјена одговора на терапију гвожђем или витамином Б12, праћење након губитка крви и код обољења коштане сржи', 'Уточнение причины анемии, оценка ответа на лечение препаратами железа или витамином B12, наблюдение после кровопотери и при болезнях костного мозга', 'Klärung der Ursache einer Anämie, Beurteilung des Ansprechens auf eine Behandlung mit Eisen oder Vitamin B12, Verlaufskontrolle nach Blutverlust und bei Knochenmarkerkrankungen', 'Anemi nedeninin netleştirilmesi, demir veya B12 vitamini tedavisine yanıtın değerlendirilmesi, kan kaybı sonrası ve kemik iliği hastalıklarında izlem', 'No special preparation required; a started anemia treatment and a recent blood transfusion are reported to the doctor', 'Nije potrebna posebna priprema; o započetoj terapiji anemije i nedavnoj transfuziji obavještava se ljekar', 'Није потребна посебна припрема; о започетој терапији анемије и недавној трансфузији обавјештава се љекар', 'Специальной подготовки не требуется; о начатом лечении анемии и недавнем переливании крови сообщают врачу', 'Keine besondere Vorbereitung erforderlich; eine begonnene Anämiebehandlung und eine kürzliche Bluttransfusion sind dem Arzt mitzuteilen', 'Özel bir hazırlık gerektirmez; başlanan anemi tedavisi ve yakın zamanda yapılan kan nakli hekime bildirilir', 'A higher or lower share of young red blood cells may be related to bone marrow activity, a lack of iron or vitamins, or the loss or breakdown of blood cells. The meaning of the result is determined by a doctor', 'Povećanje ili smanjenje udjela mladih eritrocita može biti povezano sa aktivnošću koštane srži, manjkom gvožđa ili vitamina, gubitkom ili razgradnjom krvnih ćelija. Smisao nalaza određuje ljekar', 'Повећање или смањење удјела младих еритроцита може бити повезано са активношћу коштане сржи, мањком гвожђа или витамина, губитком или разградњом крвних ћелија. Смисао налаза одређује љекар', 'Повышение или снижение доли молодых эритроцитов может быть связано с активностью костного мозга, нехваткой железа или витаминов, потерей или разрушением клеток крови. Смысл результата определяет врач', 'Ein höherer oder niedrigerer Anteil junger roter Blutkörperchen kann mit der Aktivität des Knochenmarks, einem Mangel an Eisen oder Vitaminen oder dem Verlust bzw. Abbau von Blutzellen zusammenhängen. Die Bedeutung des Ergebnisses bestimmt der Arzt', 'Genç alyuvar oranının artması veya azalması kemik iliğinin etkinliği, demir ya da vitamin azlığı, kan hücrelerinin kaybı veya yıkımıyla ilişkili olabilir. Sonucun anlamını hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'complete-blood-count-with-leukocyte-formula'), 'An extended version of the blood count in which the counting of white cell types is added to the main values', 'Prošireni oblik krvne slike u kojem je osnovnim pokazateljima dodato brojanje vrsta leukocita', 'Проширени облик крвне слике у којем је основним показатељима додато бројање врста леукоцита', 'Расширенный вариант общего анализа крови, где к основным показателям добавлен подсчёт видов лейкоцитов', 'Eine erweiterte Form des Blutbildes, bei der zu den Grundwerten die Auszählung der Leukozytenarten hinzukommt', 'Temel değerlere akyuvar türlerinin sayımının eklendiği, genişletilmiş kan sayımı', 'A single venous or capillary blood draw from which the laboratory obtains both the cell values and the distribution of white cells', 'Jedno vađenje venske ili kapilarne krvi iz kojeg laboratorija dobija i ćelijske pokazatelje i raspodjelu leukocita', 'Једно вађење венске или капиларне крви из којег лабораторија добија и ћелијске показатеље и расподјелу леукоцита', 'Один забор венозной или капиллярной крови, из которого лаборатория получает и клеточные показатели, и распределение лейкоцитов', 'Eine einzige Entnahme von venösem oder kapillarem Blut, aus der das Labor sowohl die Zellwerte als auch die Verteilung der weißen Blutkörperchen bestimmt', 'Tek bir venöz veya kapiller kan alımıyla laboratuvar hem hücre değerlerini hem de akyuvar dağılımını elde eder', 'Initial work-up for complaints, suspected infection or inflammation, routine check-ups, preparation for surgery, follow-up during therapy', 'Prva obrada kod tegoba, sumnja na infekciju ili upalu, sistematski pregled, priprema za operaciju, praćenje tokom terapije', 'Прва обрада код тегоба, сумња на инфекцију или упалу, систематски преглед, припрема за операцију, праћење током терапије', 'Первичное обследование при жалобах, подозрение на инфекцию или воспаление, диспансеризация, подготовка к операции, наблюдение во время терапии', 'Erstabklärung bei Beschwerden, Verdacht auf Infektion oder Entzündung, Vorsorgeuntersuchung, Vorbereitung auf eine Operation, Verlaufskontrolle während einer Therapie', 'Şikayetlerde ilk inceleme, enfeksiyon veya iltihap şüphesi, genel kontrol, ameliyata hazırlık, tedavi sırasında izlem', 'No special preparation required, the sample is usually taken in the morning, and intense exertion the day before is better postponed', 'Nije potrebna posebna priprema, uzorak se najčešće uzima ujutru, a jači fizički napor dan ranije bolje je odložiti', 'Није потребна посебна припрема, узорак се најчешће узима ујутру, а јачи физички напор дан раније боље је одложити', 'Специальной подготовки не требуется, чаще сдают утром, а интенсивные нагрузки накануне лучше отложить', 'Keine besondere Vorbereitung erforderlich, die Entnahme erfolgt meist morgens, starke körperliche Belastung am Vortag sollte verschoben werden', 'Özel bir hazırlık gerektirmez, örnek genellikle sabah alınır, bir gün önce ağır fiziksel zorlanmayı ertelemek daha iyidir', 'A combination of changes in the cell values and in the white cell ratio may be related to infection, inflammation, anemia, or a response to treatment. Which values matter is decided by a doctor based on the whole picture', 'Kombinacija promjena ćelijskih pokazatelja i odnosa leukocita može biti povezana sa infekcijom, upalom, anemijom ili odgovorom na liječenje. Koji su pokazatelji značajni, odlučuje ljekar prema cjelokupnoj slici', 'Комбинација промјена ћелијских показатеља и односа леукоцита може бити повезана са инфекцијом, упалом, анемијом или одговором на лијечење. Који су показатељи значајни, одлучује љекар према цјелокупној слици', 'Сочетание изменений клеточных показателей и соотношения лейкоцитов может быть связано с инфекцией, воспалением, анемией или ответом на лечение. Какие именно показатели значимы, решает врач по всей картине', 'Eine Kombination aus veränderten Zellwerten und einem verschobenen Leukozytenverhältnis kann mit einer Infektion, Entzündung, Anämie oder einer Reaktion auf die Behandlung zusammenhängen. Welche Werte bedeutsam sind, entscheidet der Arzt anhand des Gesamtbildes', 'Hücre değerlerindeki değişikliklerin ve akyuvar oranlarındaki kaymaların birlikteliği enfeksiyon, iltihap, anemi veya tedaviye yanıtla ilişkili olabilir. Hangi değerlerin önemli olduğuna hekim bütün tabloya bakarak karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'platelets'), 'A count of the blood platelets responsible for the initial stopping of bleeding', 'Brojanje krvnih pločica koje su odgovorne za početno zaustavljanje krvarenja', 'Бројање крвних плочица које су одговорне за почетно заустављање крварења', 'Подсчёт количества кровяных пластинок, отвечающих за первичную остановку кровотечения', 'Auszählung der Blutplättchen, die für das erste Stillen einer Blutung zuständig sind', 'Kanamanın ilk durdurulmasından sorumlu kan pulcuklarının sayımı', 'Venous or capillary blood draw, counted on an analyzer; if the result is unusual, the laboratory additionally checks the smear', 'Uzimanje venske ili kapilarne krvi, brojanje na analizatoru, a kod neobičnog nalaza laboratorija dodatno provjerava razmaz', 'Узимање венске или капиларне крви, бројање на анализатору, а код необичног налаза лабораторија додатно провјерава размаз', 'Забор венозной или капиллярной крови, подсчёт на анализаторе, при необычном результате лаборатория дополнительно проверяет мазок', 'Entnahme von venösem oder kapillarem Blut, Auszählung am Analysegerät; bei einem ungewöhnlichen Ergebnis prüft das Labor zusätzlich den Ausstrich', 'Venöz veya kapiller kan alınır ve cihazda sayılır; sonuç alışılmadıksa laboratuvar ayrıca yaymayı kontrol eder', 'Bleeding gums and easy bruising, preparation for surgery, monitoring during certain medications, follow-up in blood disorders', 'Krvarenje desni i lako stvaranje modrica, priprema za operaciju, kontrola tokom uzimanja pojedinih lijekova, praćenje kod bolesti krvi', 'Крварење десни и лако стварање модрица, припрема за операцију, контрола током узимања појединих лијекова, праћење код болести крви', 'Кровоточивость дёсен и лёгкое образование синяков, подготовка к операции, контроль при приёме некоторых препаратов, наблюдение при заболеваниях крови', 'Zahnfleischbluten und leichte Blutergüsse, Vorbereitung auf eine Operation, Kontrolle bei bestimmten Medikamenten, Verlaufskontrolle bei Bluterkrankungen', 'Diş eti kanaması ve kolay morarma, ameliyata hazırlık, bazı ilaçların kullanımı sırasında kontrol, kan hastalıklarında izlem', 'No special preparation required; blood is drawn without prolonged tourniquet use, otherwise the result may be distorted', 'Nije potrebna posebna priprema; krv se vadi bez dužeg stezanja vene, jer se nalaz inače može izmijeniti', 'Није потребна посебна припрема; крв се вади без дужег стезања вене, јер се налаз иначе може измијенити', 'Специальной подготовки не требуется; кровь берут без длительного пережатия вены, иначе результат может исказиться', 'Keine besondere Vorbereitung erforderlich; die Entnahme erfolgt ohne längeres Abbinden der Vene, da das Ergebnis sonst verfälscht werden kann', 'Özel bir hazırlık gerektirmez; kan, turnike uzun süre tutulmadan alınır, aksi halde sonuç yanıltıcı olabilir', 'Deviations may be related to infection, inflammation, medication use, bone marrow disorders, or features of the sample, such as cells clumping in the tube. The significance is assessed by a doctor, who may order a repeat test', 'Odstupanja mogu biti povezana sa infekcijom, upalom, uzimanjem lijekova, oboljenjima koštane srži ili osobinama uzorka, na primjer slijepljivanjem ćelija u epruveti. Značaj procjenjuje ljekar, po potrebi uz ponovljenu analizu', 'Одступања могу бити повезана са инфекцијом, упалом, узимањем лијекова, обољењима коштане сржи или особинама узорка, на примјер слијепљивањем ћелија у епрувети. Значај процјењује љекар, по потреби уз поновљену анализу', 'Отклонения могут быть связаны с инфекцией, воспалением, приёмом лекарств, заболеваниями костного мозга или особенностями образца, например слипанием клеток в пробирке. Значимость оценивает врач, при необходимости назначая повторный анализ', 'Abweichungen können mit einer Infektion, Entzündung, Medikamenteneinnahme, Knochenmarkerkrankungen oder Eigenschaften der Probe zusammenhängen, etwa dem Verklumpen der Zellen im Röhrchen. Die Bedeutung beurteilt der Arzt und ordnet bei Bedarf eine Wiederholung an', 'Sapmalar enfeksiyon, iltihap, ilaç kullanımı, kemik iliği hastalıkları veya örneğe özgü durumlarla, örneğin hücrelerin tüpte kümelenmesiyle ilişkili olabilir. Önemini hekim değerlendirir, gerekirse testi yineletir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'oral-glucose-tolerance-test'), 'A challenge test showing how the body handles the absorption of sugar', 'Test opterećenja koji pokazuje kako organizam podnosi unos šećera', 'Тест оптерећења који показује како организам подноси унос шећера', 'Нагрузочная проба, показывающая, как организм справляется с усвоением сахара', 'Ein Belastungstest, der zeigt, wie der Körper mit der Aufnahme von Zucker zurechtkommt', 'Vücudun şekeri ne ölçüde iyi kullandığını gösteren bir yükleme testi', 'Blood is first drawn fasting, then the patient drinks a glucose solution prepared by the laboratory, after which blood is drawn again at set intervals; the whole test takes about two hours, which must be spent at the laboratory', 'Prvo se vadi krv natašte, zatim pacijent popije rastvor glukoze koji priprema laboratorija, a krv se ponovo vadi u zadatim razmacima; cijeli postupak traje oko dva sata koje treba provesti u laboratoriji', 'Прво се вади крв наташте, затим пацијент попије раствор глукозе који припрема лабораторија, а крв се поново вади у задатим размацима; цијели поступак траје око два сата које треба провести у лабораторији', 'Сначала берут кровь натощак, затем пациент выпивает подготовленный лабораторией раствор глюкозы, после чего кровь берут повторно через заданные промежутки; вся проба занимает около двух часов, которые нужно провести в лаборатории', 'Zuerst wird nüchtern Blut abgenommen, dann trinkt die Patientin oder der Patient eine vom Labor vorbereitete Glukoselösung, danach wird in festgelegten Abständen erneut Blut abgenommen; der gesamte Ablauf dauert etwa zwei Stunden, die im Labor verbracht werden', 'Önce aç karnına kan alınır, ardından hasta laboratuvarın hazırladığı glikoz çözeltisini içer ve belirlenen aralıklarla yeniden kan alınır; tüm işlem yaklaşık iki saat sürer ve bu süre laboratuvarda geçirilir', 'Screening for carbohydrate metabolism disorders, testing during pregnancy as directed by a doctor, borderline fasting glucose results', 'Skrining poremećaja metabolizma ugljenih hidrata, ispitivanje trudnica po uputu ljekara, granični nalazi glukoze natašte', 'Скрининг поремећаја метаболизма угљених хидрата, испитивање трудница по упуту љекара, гранични налази глукозе наташте', 'Скрининг нарушений углеводного обмена, обследование беременных по назначению врача, пограничные результаты глюкозы натощак', 'Screening auf Störungen des Kohlenhydratstoffwechsels, Untersuchung in der Schwangerschaft auf ärztliche Anweisung, grenzwertige Nüchternwerte der Glukose', 'Karbonhidrat metabolizması bozukluklarının taranması, hekim yönlendirmesiyle gebelikte inceleme, sınırda açlık glikoz sonuçları', 'Fasting for 8–12 hours, water allowed; usual diet without strict restrictions the day before, and on the day of the test no eating, smoking or physical activity, while during an acute illness the test is postponed', 'Natašte 8–12 sati, dozvoljena je voda; dan ranije uobičajena ishrana bez strogih dijeta, a na dan testa se ne jede, ne puši i ne vježba, dok se tokom akutne bolesti test odlaže', 'Наташте 8–12 сати, дозвољена је вода; дан раније уобичајена исхрана без строгих дијета, а на дан теста се не једе, не пуши и не вјежба, док се током акутне болести тест одлаже', 'Натощак 8–12 часов, разрешена вода; накануне обычное питание без строгих диет, в день пробы нельзя есть, курить и активно двигаться, при остром заболевании пробу переносят', '8–12 Stunden nüchtern, Wasser ist erlaubt; am Vortag normale Ernährung ohne strenge Diät, am Testtag nicht essen, nicht rauchen und sich nicht körperlich anstrengen, bei einer akuten Erkrankung wird der Test verschoben', '8–12 saat açlık, su içilebilir; bir gün önce katı diyet yapmadan olağan beslenme, test günü yememek, sigara içmemek ve fiziksel olarak zorlanmamak, akut hastalık sırasında test ertelenir', 'The result may be related to features of carbohydrate metabolism, a recent illness, certain medications, or pregnancy. The conclusion is made by a doctor, usually taking a repeat test into account', 'Nalaz može biti povezan sa osobinama metabolizma ugljenih hidrata, nedavnom bolešću, uzimanjem pojedinih lijekova ili trudnoćom. Zaključak donosi ljekar, obično uz ponovljeno ispitivanje', 'Налаз може бити повезан са особинама метаболизма угљених хидрата, недавном болешћу, узимањем појединих лијекова или трудноћом. Закључак доноси љекар, обично уз поновљено испитивање', 'Результат может быть связан с особенностями углеводного обмена, недавней болезнью, приёмом некоторых препаратов или беременностью. Вывод делает врач, обычно с учётом повторного исследования', 'Das Ergebnis kann mit Besonderheiten des Kohlenhydratstoffwechsels, einer kürzlichen Erkrankung, bestimmten Medikamenten oder einer Schwangerschaft zusammenhängen. Die Schlussfolgerung zieht der Arzt, meist unter Berücksichtigung einer Wiederholung', 'Sonuç karbonhidrat metabolizmasının özellikleri, yakın zamanda geçirilen bir hastalık, bazı ilaçlar veya gebelikle ilişkili olabilir. Kararı hekim, genellikle testin tekrarını da dikkate alarak verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-cervical-biopsy'), 'Microscopic examination of a piece of cervical tissue obtained by biopsy', 'Mikroskopski pregled djelića tkiva grlića materice uzetog biopsijom', 'Микроскопски преглед дјелића ткива грлића материце узетог биопсијом', 'Микроскопическое исследование кусочка ткани шейки матки, взятого при биопсии', 'Mikroskopische Untersuchung eines bei der Biopsie entnommenen Gewebestücks des Gebärmutterhalses', 'Biyopsiyle alınan rahim ağzı dokusunun mikroskopla incelenmesi', 'The sample is fixed, embedded in paraffin, cut into thin sections, stained and examined under a microscope; the biopsy itself is performed separately by a gynaecologist', 'Uzorak se fiksira, ukalupljuje u parafin, reže na tanke presjeke, boji i pregleda pod mikroskopom; samu biopsiju ginekolog radi zasebno', 'Узорак се фиксира, укалупљује у парафин, реже на танке пресјеке, боји и прегледа под микроскопом; саму биопсију гинеколог ради засебно', 'Материал фиксируют, заливают в парафин, режут на тонкие срезы, окрашивают и изучают под микроскопом; саму биопсию гинеколог выполняет отдельно', 'Das Material wird fixiert, in Paraffin eingebettet, in dünne Schnitte geschnitten, gefärbt und unter dem Mikroskop beurteilt; die Biopsie selbst nimmt die Frauenärztin oder der Frauenarzt gesondert vor', 'Örnek tespit edilir, parafine gömülür, ince kesitler alınır, boyanır ve mikroskopta değerlendirilir; biyopsi işlemini kadın doğum hekimi ayrıca yapar', 'Changes seen at colposcopy, an abnormal cytology smear, persistently detected high-risk HPV, follow-up after treatment of the cervix', 'Promjene uočene na kolposkopiji, odstupanja u citološkom brisu, uporno prisustvo HPV visokog rizika, kontrola poslije liječenja grlića materice', 'Промјене уочене на колпоскопији, одступања у цитолошком брису, упорно присуство HPV високог ризика, контрола послије лијечења грлића материце', 'Изменения, замеченные при кольпоскопии, отклонения в цитологическом мазке, стойкое выявление ВПЧ высокого риска, контроль после лечения шейки матки', 'Auffälligkeiten bei der Kolposkopie, abweichender zytologischer Abstrich, anhaltender Nachweis von Hochrisiko-HPV, Kontrolle nach Behandlung am Gebärmutterhals', 'Kolposkopide görülen değişiklikler, sitolojik yaymada sapma, yüksek riskli HPV''nin sürekli saptanması, rahim ağzı tedavisi sonrası kontrol', 'Preparation applies to the biopsy procedure and is discussed with the gynaecologist; the laboratory stage requires nothing from the patient', 'Priprema se odnosi na sam zahvat biopsije i dogovara se sa ginekologom; za laboratorijski dio pacijentkinja ne radi ništa', 'Припрема се односи на сам захват биопсије и договара се са гинекологом; за лабораторијски дио пацијенткиња не ради ништа', 'Подготовка относится к процедуре биопсии и обсуждается с гинекологом; на лабораторном этапе от пациентки ничего не требуется', 'Die Vorbereitung betrifft den Eingriff selbst und wird mit der Frauenärztin oder dem Frauenarzt besprochen; für den Laborteil ist nichts zu tun', 'Hazırlık biyopsi işlemiyle ilgilidir ve kadın doğum hekimiyle konuşulur; laboratuvar aşamasında hastadan bir şey istenmez', 'The report describes the nature of the tissue changes, from inflammatory to those needing follow-up or treatment. What this means in a particular case and what comes next is decided by the gynaecologist', 'Nalaz opisuje prirodu promjena u tkivu, od upalnih do onih koje traže praćenje ili liječenje. Šta to znači u konkretnom slučaju i koji su sljedeći koraci, određuje ginekolog', 'Налаз описује природу промјена у ткиву, од упалних до оних које траже праћење или лијечење. Шта то значи у конкретном случају и који су сљедећи кораци, одређује гинеколог', 'Заключение описывает характер изменений в ткани — от воспалительных до требующих наблюдения или лечения. Что это значит в конкретном случае и какие шаги нужны дальше, определяет гинеколог', 'Der Befund beschreibt die Art der Gewebeveränderungen, von entzündlich bis hin zu solchen, die Kontrolle oder Behandlung erfordern. Was das im Einzelfall bedeutet und wie es weitergeht, entscheidet die Frauenärztin oder der Frauenarzt', 'Rapor, dokudaki değişikliklerin niteliğini iltihabi olandan izlem ya da tedavi gerektirene kadar tanımlar. Bunun o kişide ne anlama geldiğine ve sonraki adımlara kadın doğum hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-liver-biopsy'), 'Microscopic examination of a core of liver tissue obtained by needle biopsy', 'Mikroskopski pregled isječka tkiva jetre dobijenog punkcionom biopsijom', 'Микроскопски преглед исјечка ткива јетре добијеног пункционом биопсијом', 'Микроскопическое исследование столбика ткани печени, полученного при пункционной биопсии', 'Mikroskopische Untersuchung eines durch Punktionsbiopsie gewonnenen Lebergewebszylinders', 'İğne biyopsisiyle alınan karaciğer doku örneğinin mikroskopla incelenmesi', 'The material is fixed, embedded in paraffin, cut into thin sections and stained, including special stains that show connective tissue; the puncture itself is performed separately by a doctor, usually under ultrasound guidance', 'Uzorak se fiksira, ukalupljuje u parafin, reže na tanke presjeke i boji, uz posebna bojenja za procjenu vezivnog tkiva; samu punkciju ljekar radi zasebno, najčešće pod kontrolom ultrazvuka', 'Узорак се фиксира, укалупљује у парафин, реже на танке пресјеке и боји, уз посебна бојења за процјену везивног ткива; саму пункцију љекар ради засебно, најчешће под контролом ултразвука', 'Материал фиксируют, заливают в парафин, режут на тонкие срезы и окрашивают, в том числе специальными красителями для оценки соединительной ткани; саму пункцию врач выполняет отдельно, обычно под контролем УЗИ', 'Das Material wird fixiert, in Paraffin eingebettet, in dünne Schnitte geschnitten und gefärbt, auch mit Spezialfärbungen zur Beurteilung des Bindegewebes; die Punktion selbst führt der Arzt gesondert durch, meist unter Ultraschallkontrolle', 'Örnek tespit edilir, parafine gömülür, ince kesitler alınır ve bağ dokusunu gösteren özel boyalar dahil olmak üzere boyanır; biyopsi işlemini hekim genellikle ultrason eşliğinde ayrıca yapar', 'Persistently elevated liver values without a clear cause, chronic viral hepatitis, assessment of fibrosis and fatty change, clarifying the cause of chronic liver damage, follow-up after transplantation', 'Uporno povišeni jetreni pokazatelji bez jasnog uzroka, hronični virusni hepatitisi, procjena stepena fibroze i masne promjene, razjašnjenje uzroka hroničnog oštećenja jetre, praćenje poslije transplantacije', 'Упорно повишени јетрени показатељи без јасног узрока, хронични вирусни хепатитиси, процјена степена фиброзе и масне промјене, разјашњење узрока хроничног оштећења јетре, праћење послије трансплантације', 'Стойкое повышение печёночных показателей без ясной причины, хронические вирусные гепатиты, оценка выраженности фиброза и жирового перерождения, уточнение причины хронического поражения печени, наблюдение после трансплантации', 'Dauerhaft erhöhte Leberwerte ohne klare Ursache, chronische Virushepatitiden, Beurteilung von Fibrose und Verfettung, Abklärung einer chronischen Leberschädigung, Verlaufskontrolle nach Transplantation', 'Nedeni belirsiz sürekli yüksek karaciğer değerleri, kronik viral hepatitler, fibroz ve yağlanma derecesinin değerlendirilmesi, kronik karaciğer hasarının nedeninin araştırılması, nakil sonrası izlem', 'Preparation concerns the puncture: clotting parameters are checked beforehand, and only the doctor decides whether blood-thinning medicines are paused', 'Priprema se odnosi na samu punkciju: unaprijed se rade parametri koagulacije, a o privremenom prekidu lijekova koji razrjeđuju krv odlučuje isključivo ljekar', 'Припрема се односи на саму пункцију: унапријед се раде параметри коагулације, а о привременом прекиду лијекова који разрјеђују крв одлучује искључиво љекар', 'Подготовка относится к самой пункции: заранее сдают показатели свёртывания крови, а вопрос о временной отмене препаратов, разжижающих кровь, решает только врач', 'Die Vorbereitung betrifft die Punktion: Gerinnungswerte werden vorab bestimmt, über ein vorübergehendes Pausieren blutverdünnender Medikamente entscheidet ausschließlich der Arzt', 'Hazırlık biyopsi işlemiyle ilgilidir: önceden pıhtılaşma testleri yapılır, kan sulandırıcı ilaçlara ara verilip verilmeyeceğine yalnızca hekim karar verir', 'The report describes the extent and nature of the changes in liver tissue. The treating doctor matches it with laboratory results and the clinical picture and decides on further management', 'Nalaz opisuje stepen i prirodu promjena u tkivu jetre. Sa analizama i kliničkom slikom poredi ga i dalji postupak određuje ljekar koji vodi liječenje', 'Налаз описује степен и природу промјена у ткиву јетре. Са анализама и клиничком сликом пореди га и даљи поступак одређује љекар који води лијечење', 'Заключение описывает степень и характер изменений ткани печени. Сопоставляет его с анализами и клинической картиной и определяет дальнейшую тактику лечащий врач', 'Der Befund beschreibt Ausmaß und Art der Veränderungen im Lebergewebe. Die behandelnde Ärztin oder der behandelnde Arzt ordnet ihn den Laborwerten und dem klinischen Bild zu und legt das weitere Vorgehen fest', 'Rapor karaciğer dokusundaki değişikliklerin derecesini ve niteliğini tanımlar. Sonucu laboratuvar bulguları ve klinik tabloyla birleştirip izlenecek yolu tedaviyi yürüten hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-vulvar-biopsy'), 'Microscopic examination of a sample of vulvar skin and mucosa taken by biopsy', 'Mikroskopski pregled isječka kože i sluznice vulve uzetog biopsijom', 'Микроскопски преглед исјечка коже и слузнице вулве узетог биопсијом', 'Микроскопическое исследование участка кожи и слизистой вульвы, взятого при биопсии', 'Mikroskopische Untersuchung einer per Biopsie entnommenen Probe von Haut und Schleimhaut der Vulva', 'Biyopsiyle alınan vulva derisi ve mukozası örneğinin mikroskopla incelenmesi', 'A small tissue fragment taken by the gynaecologist under local anaesthesia is fixed, embedded in paraffin, sectioned, stained and examined under a microscope', 'Mali komadić tkiva koji ginekolog uzme u lokalnoj anesteziji fiksira se, ukalupljuje u parafin, reže na presjeke, boji i pregleda pod mikroskopom', 'Мали комадић ткива који гинеколог узме у локалној анестезији фиксира се, укалупљује у парафин, реже на пресјеке, боји и прегледа под микроскопом', 'Небольшой фрагмент ткани, взятый гинекологом под местным обезболиванием, фиксируют, заливают в парафин, режут на срезы, окрашивают и изучают под микроскопом', 'Das unter örtlicher Betäubung entnommene kleine Gewebestück wird fixiert, in Paraffin eingebettet, geschnitten, gefärbt und unter dem Mikroskop beurteilt', 'Kadın doğum hekiminin lokal anesteziyle aldığı küçük doku parçası tespit edilir, parafine gömülür, kesitlenir, boyanır ve mikroskopta incelenir', 'Long-lasting itching and burning of the vulva, changes in skin colour and texture, persistent patches and nodules, non-healing sores, clarifying the nature of chronic skin changes, follow-up after treatment', 'Dugotrajan svrab i peckanje u predjelu vulve, promjene boje i čvrstine kože, uporne mrlje i kvržice, ranice koje ne zarastaju, razjašnjenje prirode hroničnih promjena na koži, kontrola poslije liječenja', 'Дуготрајан свраб и пецкање у предјелу вулве, промјене боје и чврстине коже, упорне мрље и квржице, ранице које не зарастају, разјашњење природе хроничних промјена на кожи, контрола послије лијечења', 'Длительный зуд и жжение в области вульвы, изменения цвета и плотности кожи, стойкие пятна и узелки, незаживающие ранки, уточнение природы хронических кожных изменений, контроль после лечения', 'Anhaltender Juckreiz und Brennen im Vulvabereich, Veränderungen von Hautfarbe und Hautbeschaffenheit, hartnäckige Flecken und Knötchen, nicht heilende Stellen, Abklärung chronischer Hautveränderungen, Kontrolle nach Behandlung', 'Vulva bölgesinde uzun süreli kaşıntı ve yanma, deri renginde ve dokusunda değişiklik, geçmeyen lekeler ve kabartılar, iyileşmeyen yaralar, kronik deri değişikliklerinin nedeninin araştırılması, tedavi sonrası kontrol', 'Preparation concerns the biopsy procedure: on that day avoid creams and antiseptic hygiene products, the gynaecologist explains the rest', 'Priprema se odnosi na sam zahvat: na dan biopsije ne koristiti kreme i antiseptična higijenska sredstva, ostalo dogovara ginekolog', 'Припрема се односи на сам захват: на дан биопсије не користити креме и антисептична хигијенска средства, остало договара гинеколог', 'Подготовка касается процедуры биопсии: в день вмешательства не пользоваться кремами и антисептическими средствами гигиены, остальное уточняет гинеколог', 'Die Vorbereitung betrifft den Eingriff: am Tag der Biopsie keine Cremes und keine antiseptischen Pflegeprodukte verwenden, alles Weitere bespricht die Frauenärztin oder der Frauenarzt', 'Hazırlık işlemle ilgilidir: biyopsi günü krem ve antiseptik hijyen ürünleri kullanılmaz, gerisini kadın doğum hekimi anlatır', 'The report describes the nature of the changes, inflammatory, dystrophic or requiring further follow-up and treatment. The gynaecologist interprets the result and decides on the next steps', 'Nalaz opisuje prirodu promjena, upalne, distrofične ili one koje traže dalje praćenje i liječenje. Rezultat tumači i sljedeće korake određuje ginekolog', 'Налаз описује природу промјена, упалне, дистрофичне или оне које траже даље праћење и лијечење. Резултат тумачи и сљедеће кораке одређује гинеколог', 'Заключение описывает характер изменений — воспалительные, дистрофические или требующие дальнейшего наблюдения и лечения. Трактует результат и назначает следующие шаги гинеколог', 'Der Befund beschreibt die Art der Veränderungen, entzündlich, dystrophisch oder weiter kontrollbedürftig. Die Deutung und das weitere Vorgehen legt die Frauenärztin oder der Frauenarzt fest', 'Rapor değişikliklerin niteliğini iltihabi, distrofik ya da izlem ve tedavi gerektiren olarak tanımlar. Sonucu yorumlayıp sonraki adımları kadın doğum hekimi belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protia-allergy-q64-inhalation-panel-64-allergens'), 'A panel of specific IgE against 64 inhaled allergens: tree, grass and weed pollen, house dust mites, moulds, animal dander and hair', 'Panel specifičnih IgE na 64 inhalaciona alergena: polen drveća, trava i korova, grinje kućne prašine, plijesni, epitel i dlaka životinja', 'Панел специфичних IgE на 64 инхалациона алергена: полен дрвећа, трава и корова, гриње кућне прашине, плијесни, епител и длака животиња', 'Панель специфических IgE к 64 вдыхаемым аллергенам: пыльца деревьев, трав и сорняков, клещи домашней пыли, плесневые грибы, эпителий и шерсть животных', 'Panel spezifischer IgE gegen 64 Inhalationsallergene: Baum-, Gras- und Kräuterpollen, Hausstaubmilben, Schimmelpilze, Tierepithelien und Tierhaare', 'Ağaç, çayır ve yabani ot polenleri, ev tozu akarları, küfler, hayvan epiteli ve tüyü gibi 64 solunum alerjenine karşı özgül IgE paneli', 'A single venous blood draw, the laboratory determines the whole set of parameters from one sample', 'Jedno vađenje venske krvi, laboratorija iz istog uzorka određuje čitav skup pokazatelja', 'Једно вађење венске крви, лабораторија из истог узорка одређује читав скуп показатеља', 'Однократный забор венозной крови, из одной пробы лаборатория определяет сразу весь набор показателей', 'Eine einzige venöse Blutentnahme, aus derselben Probe bestimmt das Labor den gesamten Parametersatz', 'Tek seferde venöz kan alınır, laboratuvar aynı örnekten tüm parametreleri çalışır', 'Seasonal or year-round runny nose, sneezing, blocked nose, itchy eyes, suspected allergic asthma, looking for the trigger of flare-ups, situations where skin testing is not advisable', 'Sezonska ili cjelogodišnja kijavica, kijanje, zapušen nos, svrab očiju, sumnja na alergijsku astmu, traženje uzroka pogoršanja, situacije kada kožni testovi nisu poželjni', 'Сезонска или цјелогодишња кијавица, кијање, запушен нос, свраб очију, сумња на алергијску астму, тражење узрока погоршања, ситуације када кожни тестови нису пожељни', 'Сезонный или круглогодичный насморк, чихание, заложенность носа, зуд глаз, подозрение на аллергическую астму, поиск причины обострений, ситуации, когда кожные пробы нежелательны', 'Saisonaler oder ganzjähriger Schnupfen, Niesen, verstopfte Nase, juckende Augen, Verdacht auf allergisches Asthma, Suche nach dem Auslöser von Beschwerdeschüben, Situationen, in denen Hauttests nicht infrage kommen', 'Mevsimsel ya da yıl boyu süren burun akıntısı, hapşırma, burun tıkanıklığı, göz kaşıntısı, alerjik astım şüphesi, alevlenmelerin nedeninin aranması, deri testinin uygun olmadığı durumlar', 'No special preparation is needed and antihistamines do not have to be stopped, they do not affect a blood test', 'Posebna priprema nije potrebna, antihistaminike nije potrebno prekidati jer ne utiču na nalaz iz krvi', 'Посебна припрема није потребна, антихистаминике није потребно прекидати јер не утичу на налаз из крви', 'Специальной подготовки не требуется, антигистаминные препараты отменять не нужно — на анализ крови они не влияют', 'Keine besondere Vorbereitung nötig, Antihistaminika müssen nicht abgesetzt werden, sie beeinflussen den Bluttest nicht', 'Özel hazırlık gerekmez, antihistaminiklerin kesilmesine gerek yoktur, kan testini etkilemezler', 'Detected specific IgE indicates sensitisation to an allergen and by itself is not the same as an allergy. An allergist compares the set of results with the symptoms and living conditions', 'Nalaz specifičnih IgE govori o senzibilizaciji na alergen i sam po sebi ne znači alergiju. Skup pokazatelja sa tegobama i uslovima života poredi ljekar alergolog', 'Налаз специфичних IgE говори о сензибилизацији на алерген и сам по себи не значи алергију. Скуп показатеља са тегобама и условима живота пореди љекар алерголог', 'Выявление специфических IgE говорит о сенсибилизации к аллергену и само по себе не равно аллергии. Сопоставляет набор показателей с симптомами и условиями жизни врач-аллерголог', 'Nachweisbare spezifische IgE zeigen eine Sensibilisierung gegenüber einem Allergen an und bedeuten für sich genommen noch keine Allergie. Die Zusammenschau mit Beschwerden und Lebensumständen nimmt die Allergologin oder der Allergologe vor', 'Özgül IgE saptanması alerjene duyarlanmayı gösterir, tek başına alerji anlamına gelmez. Sonuç kümesini şikayetler ve yaşam koşullarıyla birlikte alerji uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protia-allergy-q64-nutritive-panel-72-allergens'), 'A panel of specific IgE against 72 food allergens: milk and egg, cereals, nuts, fish and seafood, vegetables, fruit, spices', 'Panel specifičnih IgE na 72 nutritivna alergena: mlijeko i jaje, žitarice, orašasti plodovi, riba i morski plodovi, povrće, voće, začini', 'Панел специфичних IgE на 72 нутритивна алергена: млијеко и јаје, житарице, орашасти плодови, риба и морски плодови, поврће, воће, зачини', 'Панель специфических IgE к 72 пищевым аллергенам: молоко и яйцо, злаки, орехи, рыба и морепродукты, овощи, фрукты, специи', 'Panel spezifischer IgE gegen 72 Nahrungsmittelallergene: Milch und Ei, Getreide, Nüsse, Fisch und Meeresfrüchte, Gemüse, Obst, Gewürze', 'Süt ve yumurta, tahıllar, sert kabuklu yemişler, balık ve deniz ürünleri, sebze, meyve ve baharatlar gibi 72 besin alerjenine karşı özgül IgE paneli', 'The whole list of parameters is determined from a single venous blood sample, no repeat visits are needed', 'Iz jednog uzorka venske krvi određuje se cijeli spisak pokazatelja, bez ponovnih dolazaka', 'Из једног узорка венске крви одређује се цијели списак показатеља, без поновних долазака', 'Из одной пробы венозной крови определяют весь список показателей, повторные визиты не нужны', 'Aus einer einzigen venösen Blutprobe wird die gesamte Liste der Parameter bestimmt, weitere Termine entfallen', 'Tek bir venöz kan örneğinden tüm parametreler çalışılır, tekrar gelmek gerekmez', 'Hives, swelling, itching and rashes after meals, flare-ups of atopic dermatitis, stomach and bowel complaints after certain foods, planning a diet together with a doctor', 'Koprivnjača, otoci, svrab i osip poslije jela, pogoršanja atopijskog dermatitisa, tegobe želuca i crijeva poslije određenih namirnica, planiranje ishrane zajedno sa ljekarom', 'Копривњача, отоци, свраб и осип послије јела, погоршања атопијског дерматитиса, тегобе желуца и цријева послије одређених намирница, планирање исхране заједно са љекаром', 'Крапивница, отёки, зуд и высыпания после еды, обострения атопического дерматита, жалобы со стороны желудка и кишечника после определённых продуктов, подбор рациона вместе с врачом', 'Nesselsucht, Schwellungen, Juckreiz und Hautausschlag nach dem Essen, Schübe einer Neurodermitis, Magen-Darm-Beschwerden nach bestimmten Lebensmitteln, Ernährungsplanung gemeinsam mit dem Arzt', 'Yemek sonrası kurdeşen, şişlik, kaşıntı ve döküntü, atopik dermatit alevlenmeleri, belirli besinlerden sonra mide ve bağırsak şikayetleri, hekimle birlikte beslenme planlaması', 'No special preparation is required and there is no need to avoid suspected foods beforehand, the test detects antibodies rather than a reaction to a recent meal', 'Posebna priprema nije potrebna, sumnjive namirnice nije potrebno izbjegavati prije vađenja krvi jer test otkriva antitijela, a ne reakciju na skorašnji obrok', 'Посебна припрема није потребна, сумњиве намирнице није потребно избјегавати прије вађења крви јер тест открива антитијела, а не реакцију на скорашњи оброк', 'Специальной подготовки не требуется, исключать подозрительные продукты перед сдачей не нужно — тест выявляет антитела, а не реакцию на недавнюю еду', 'Keine besondere Vorbereitung nötig, verdächtige Lebensmittel müssen vorher nicht gemieden werden, der Test weist Antikörper nach und nicht die Reaktion auf eine kürzliche Mahlzeit', 'Özel hazırlık gerekmez, şüpheli besinleri önceden kesmeye gerek yoktur, test yakın zamanda yenen yemeğe verilen tepkiyi değil antikorları gösterir', 'Detected IgE point to sensitisation, but tolerance of a food is judged only together with the history of reactions and, if needed, a trial diet supervised by an allergist', 'Nađena IgE ukazuju na senzibilizaciju, ali se podnošljivost namirnice procjenjuje samo uz istoriju reakcija i po potrebi probnu ishranu pod nadzorom alergologa', 'Нађена IgE указују на сензибилизацију, али се подношљивост намирнице процјењује само уз историју реакција и по потреби пробну исхрану под надзором алерголога', 'Найденные IgE указывают на сенсибилизацию, но переносимость продукта оценивают только вместе с историей реакций, при необходимости — пробной диетой под наблюдением врача-аллерголога', 'Nachgewiesene IgE sprechen für eine Sensibilisierung, die Verträglichkeit eines Lebensmittels wird jedoch nur zusammen mit der Vorgeschichte der Reaktionen und gegebenenfalls einer ärztlich begleiteten Probediät beurteilt', 'Saptanan IgE duyarlanmayı gösterir, ancak bir besinin tolere edilip edilmediği yalnızca tepki öyküsüyle ve gerekirse alerji uzmanı gözetiminde deneme diyetiyle değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protia-allergy-q64s-combined-panel-63-allergens'), 'A combined panel of specific IgE against 63 allergens, covering both inhaled and food items in one test', 'Kombinovani panel specifičnih IgE na 63 alergena, u jednom pregledu i inhalacione i nutritivne stavke', 'Комбиновани панел специфичних IgE на 63 алергена, у једном прегледу и инхалационе и нутритивне ставке', 'Комбинированная панель специфических IgE к 63 аллергенам — в одном исследовании и вдыхаемые, и пищевые позиции', 'Kombiniertes Panel spezifischer IgE gegen 63 Allergene, in einer Untersuchung sowohl Inhalations- als auch Nahrungsmittelallergene', 'Tek incelemede hem solunum hem besin alerjenlerini kapsayan, 63 alerjene karşı özgül IgE kombine paneli', 'One venous blood sample, the parameters are measured in parallel on a single test system', 'Jedan uzorak venske krvi, pokazatelji se određuju uporedo na jednom test-sistemu', 'Један узорак венске крви, показатељи се одређују упоредо на једном тест-систему', 'Одна проба венозной крови, показатели определяются параллельно на единой тест-системе', 'Eine venöse Blutprobe, die Parameter werden parallel auf einem Testsystem bestimmt', 'Tek bir venöz kan örneği alınır, parametreler tek test sisteminde eş zamanlı çalışılır', 'Complaints that are hard to trace to a single source: rhinitis together with skin rash, year-round symptoms without clear seasonality, first work-up for suspected allergy', 'Tegobe koje je teško vezati za jedan izvor: kijavica zajedno sa osipom, cjelogodišnji simptomi bez jasne sezonalnosti, prva obrada kod sumnje na alergiju', 'Тегобе које је тешко везати за један извор: кијавица заједно са осипом, цјелогодишњи симптоми без јасне сезоналности, прва обрада код сумње на алергију', 'Жалобы, которые трудно связать с одним источником: сочетание насморка и высыпаний, круглогодичные симптомы без явной сезонности, первичное обследование при подозрении на аллергию', 'Beschwerden, die sich schwer auf eine Quelle zurückführen lassen: Schnupfen zusammen mit Hautausschlag, ganzjährige Symptome ohne klare Saison, Erstabklärung bei Allergieverdacht', 'Tek bir kaynağa bağlanması güç şikayetler: burun akıntısının döküntüyle birlikte olması, mevsim ayrımı olmayan yıl boyu süren belirtiler, alerji şüphesinde ilk değerlendirme', 'No special preparation is needed, meals and antihistamines do not affect the result', 'Posebna priprema nije potrebna, obrok i antihistaminici ne utiču na nalaz', 'Посебна припрема није потребна, оброк и антихистаминици не утичу на налаз', 'Специальной подготовки не требуется, приём пищи и антигистаминных препаратов на результат не влияет', 'Keine besondere Vorbereitung nötig, Mahlzeiten und Antihistaminika beeinflussen das Ergebnis nicht', 'Özel hazırlık gerekmez, yemek ve antihistaminikler sonucu etkilemez', 'The panel shows which allergen groups there is sensitisation to. Which of the findings actually matter for a particular person is decided by an allergist based on symptoms, adding further tests if necessary', 'Panel pokazuje na koje grupe alergena postoji senzibilizacija. Koje su od nađenih stavki zaista značajne za konkretnu osobu, prema tegobama procjenjuje alergolog i po potrebi dopunjava obradu', 'Панел показује на које групе алергена постоји сензибилизација. Које су од нађених ставки заиста значајне за конкретну особу, према тегобама процјењује алерголог и по потреби допуњава обраду', 'Панель показывает, к каким группам аллергенов есть сенсибилизация. Какие из найденных позиций действительно значимы для конкретного человека, решает врач-аллерголог по симптомам, при необходимости дополняя обследование', 'Das Panel zeigt, gegenüber welchen Allergengruppen eine Sensibilisierung besteht. Welche Befunde für die einzelne Person tatsächlich bedeutsam sind, entscheidet die Allergologin oder der Allergologe anhand der Beschwerden und ergänzt bei Bedarf weitere Untersuchungen', 'Panel hangi alerjen gruplarına duyarlanma olduğunu gösterir. Bulunanlardan hangilerinin o kişi için gerçekten önemli olduğuna alerji uzmanı şikayetlere göre karar verir, gerekirse incelemeyi genişletir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protia-allergy-q96m-combined-panel-107-allergens'), 'An extended combined panel of specific IgE against 107 allergens, the widest set in this line, inhaled and food items together', 'Prošireni kombinovani panel specifičnih IgE na 107 alergena, najširi skup u ovoj liniji, inhalacione i nutritivne stavke zajedno', 'Проширени комбиновани панел специфичних IgE на 107 алергена, најшири скуп у овој линији, инхалационе и нутритивне ставке заједно', 'Расширенная комбинированная панель специфических IgE к 107 аллергенам — самый широкий набор в этой линейке, вдыхаемые и пищевые позиции вместе', 'Erweitertes kombiniertes Panel spezifischer IgE gegen 107 Allergene, der umfangreichste Satz dieser Reihe, Inhalations- und Nahrungsmittelallergene zusammen', 'Bu serinin en geniş kapsamlı seçeneği olan, solunum ve besin alerjenlerini birlikte içeren 107 alerjene karşı özgül IgE kombine paneli', 'A single venous blood draw, the whole panel is run from one sample with no extra visits', 'Jedno vađenje venske krvi, cijeli panel se radi iz istog uzorka bez dodatnih dolazaka', 'Једно вађење венске крви, цијели панел се ради из истог узорка без додатних долазака', 'Однократный забор венозной крови, вся панель выполняется из одной пробы без дополнительных визитов', 'Eine einzige venöse Blutentnahme, das gesamte Panel wird aus einer Probe ohne weitere Termine bearbeitet', 'Tek seferde venöz kan alınır, panelin tamamı aynı örnekten çalışılır, ek randevu gerekmez', 'Multiple or changing complaints, an unsuccessful search for the trigger with narrower panels, planning treatment with an allergist, work-up before specific immunotherapy at the doctor''s discretion', 'Brojne ili promjenljive tegobe, neuspješno traženje uzroka užim panelima, planiranje liječenja kod alergologa, obrada prije specifične imunoterapije po odluci ljekara', 'Бројне или промјенљиве тегобе, неуспјешно тражење узрока ужим панелима, планирање лијечења код алерголога, обрада прије специфичне имунотерапије по одлуци љекара', 'Множественные или меняющиеся жалобы, безуспешный поиск причины по узким панелям, планирование лечения у аллерголога, обследование перед специфической иммунотерапией по решению врача', 'Vielfältige oder wechselnde Beschwerden, erfolglose Ursachensuche mit kleineren Panels, Therapieplanung beim Allergologen, Abklärung vor einer spezifischen Immuntherapie nach ärztlicher Entscheidung', 'Çok sayıda ya da değişken şikayet, dar panellerle nedenin bulunamaması, alerji uzmanıyla tedavi planlaması, hekim kararıyla özgül immünoterapi öncesi değerlendirme', 'No special preparation is required, the sample can be taken at any time of day', 'Posebna priprema nije potrebna, krv se može dati u bilo koje doba dana', 'Посебна припрема није потребна, крв се може дати у било које доба дана', 'Специальной подготовки не требуется, сдать кровь можно в любое время дня', 'Keine besondere Vorbereitung nötig, die Blutentnahme ist zu jeder Tageszeit möglich', 'Özel hazırlık gerekmez, kan günün herhangi bir saatinde alınabilir', 'The wider the panel, the more often results appear that have no clinical meaning, since sensitisation is not the same as an allergy. An allergist selects the relevant findings and plans the next steps', 'Što je panel širi, to se češće nađu pokazatelji bez kliničkog značaja jer senzibilizacija nije isto što i alergija. Značajne stavke izdvaja i dalje korake planira alergolog', 'Што је панел шири, то се чешће нађу показатељи без клиничког значаја јер сензибилизација није исто што и алергија. Значајне ставке издваја и даље кораке планира алерголог', 'Чем шире панель, тем чаще находятся показатели без клинического значения: сенсибилизация не равна аллергии. Значимые позиции отбирает и дальнейшие шаги планирует врач-аллерголог', 'Je breiter das Panel, desto häufiger finden sich Werte ohne klinische Bedeutung, denn eine Sensibilisierung ist nicht gleich einer Allergie. Welche Befunde relevant sind und wie es weitergeht, entscheidet die Allergologin oder der Allergologe', 'Panel genişledikçe klinik karşılığı olmayan sonuçlar daha sık çıkar, çünkü duyarlanma alerjiyle aynı şey değildir. Anlamlı bulguları seçip sonraki adımları alerji uzmanı planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bordetella-pertussis-pcr'), 'A molecular test that detects the DNA of Bordetella pertussis, the bacterium causing whooping cough', 'Molekularni test koji otkriva DNK bakterije Bordetella pertussis, uzročnika velikog kašlja', 'Молекуларни тест који открива ДНК бактерије Bordetella pertussis, узрочника великог кашља', 'Молекулярный тест, выявляющий ДНК бактерии Bordetella pertussis — возбудителя коклюша', 'Molekularer Test zum Nachweis der DNA von Bordetella pertussis, dem Erreger des Keuchhustens', 'Boğmaca etkeni Bordetella pertussis bakterisinin DNA''sını saptayan moleküler test', 'A thin swab is taken from the nasopharynx, sampling itself takes less than a minute, the DNA is detected by PCR in the laboratory', 'Bris tankim štapićem iz nazofarinksa, samo uzimanje traje kraće od minuta, DNK se određuje metodom PCR u laboratoriji', 'Брис танким штапићем из назофаринкса, само узимање траје краће од минута, ДНК се одређује методом ПЦР у лабораторији', 'Мазок тонким тампоном из носоглотки, сам забор занимает меньше минуты, ДНК определяют методом ПЦР в лаборатории', 'Abstrich mit einem dünnen Tupfer aus dem Nasenrachenraum, die Entnahme dauert weniger als eine Minute, die DNA wird im Labor mittels PCR bestimmt', 'Genizden ince çubukla sürüntü alınır, örnek alma bir dakikadan kısa sürer, DNA laboratuvarda PCR yöntemiyle belirlenir', 'Prolonged coughing fits, a cough lasting more than two weeks, especially in children and teenagers, cough after contact with someone with whooping cough, testing of household contacts', 'Dugotrajan kašalj u napadima, kašalj duži od dvije sedmice, naročito kod djece i adolescenata, kašalj poslije kontakta sa oboljelim od velikog kašlja, obrada kontakata u porodici', 'Дуготрајан кашаљ у нападима, кашаљ дужи од двије седмице, нарочито код дјеце и адолесцената, кашаљ послије контакта са обољелим од великог кашља, обрада контаката у породици', 'Затяжной приступообразный кашель, кашель дольше двух недель, особенно у детей и подростков, кашель после контакта с больным коклюшем, обследование контактных в семье', 'Anhaltende Hustenanfälle, Husten über mehr als zwei Wochen, besonders bei Kindern und Jugendlichen, Husten nach Kontakt zu einer erkrankten Person, Abklärung von Kontaktpersonen im Haushalt', 'Nöbetler halinde süren uzun öksürük, iki haftadan uzun süren öksürük, özellikle çocuk ve ergenlerde, boğmacalı biriyle temas sonrası öksürük, ev içi temaslıların incelenmesi', 'For about an hour before the swab do not eat, drink or rinse the throat and do not use nasal sprays or drops; the interval after starting antibiotics is set by the doctor', 'Otprilike sat prije brisa ne jesti, ne piti i ne ispirati grlo, ne koristiti sprejeve i kapi za nos; razmak poslije početka antibiotika određuje ljekar', 'Отприлике сат прије бриса не јести, не пити и не испирати грло, не користити спрејеве и капи за нос; размак послије почетка антибиотика одређује љекар', 'Примерно за час до мазка не есть, не пить и не полоскать горло, не пользоваться спреями и каплями в нос; интервал после начала антибиотиков уточняет врач', 'Etwa eine Stunde vor dem Abstrich nicht essen, trinken oder gurgeln und keine Nasensprays oder Nasentropfen verwenden; den Abstand nach Beginn einer Antibiotikatherapie legt der Arzt fest', 'Sürüntüden yaklaşık bir saat önce yememek, içmemek ve gargara yapmamak, burun spreyi ve damlası kullanmamak gerekir; antibiyotik başlandıysa bekleme süresini hekim belirler', 'Detected DNA means the bacterium is present in the sample. Late in the illness and after antibiotics the test can be negative even with whooping cough, so the result is interpreted by a doctor together with the clinical picture', 'Nalaz DNK znači da je bakterija prisutna u uzorku. U kasnijoj fazi bolesti i poslije antibiotika test može biti negativan i kod velikog kašlja, pa rezultat tumači ljekar uz kliničku sliku', 'Налаз ДНК значи да је бактерија присутна у узорку. У каснијој фази болести и послије антибиотика тест може бити негативан и код великог кашља, па резултат тумачи љекар уз клиничку слику', 'Обнаружение ДНК означает присутствие бактерии в пробе. На поздних сроках болезни и после антибиотиков тест может быть отрицательным даже при коклюше, поэтому результат оценивает врач вместе с картиной заболевания', 'Nachgewiesene DNA bedeutet, dass der Erreger in der Probe vorhanden ist. Im späten Krankheitsverlauf und nach Antibiotika kann der Test trotz Keuchhusten negativ ausfallen, daher beurteilt der Arzt das Ergebnis zusammen mit dem klinischen Bild', 'DNA saptanması bakterinin örnekte bulunduğunu gösterir. Hastalığın geç döneminde ve antibiyotik sonrası test boğmaca varken bile negatif çıkabilir, bu nedenle sonucu hekim klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chlamydia-trachomatis-pcr-urine'), 'A molecular test for Chlamydia trachomatis DNA in urine, an option that avoids taking a swab', 'Molekularni test na DNK bakterije Chlamydia trachomatis iz mokraće, varijanta bez uzimanja brisa', 'Молекуларни тест на ДНК бактерије Chlamydia trachomatis из мокраће, варијанта без узимања бриса', 'Молекулярный тест на ДНК бактерии Chlamydia trachomatis в моче — вариант без взятия мазка', 'Molekularer Test auf DNA von Chlamydia trachomatis im Urin, eine Variante ohne Abstrich', 'İdrarda Chlamydia trachomatis DNA''sını arayan, sürüntü almayı gerektirmeyen moleküler test', 'The patient collects the first portion of urine into a sterile container, the DNA is then detected by PCR', 'Pacijent sam sakuplja prvi mlaz mokraće u sterilnu posudu, DNK se zatim određuje metodom PCR', 'Пацијент сам сакупља први млаз мокраће у стерилну посуду, ДНК се затим одређује методом ПЦР', 'Пациент самостоятельно собирает первую порцию мочи в стерильный контейнер, дальше ДНК определяют методом ПЦР', 'Die Patientin oder der Patient fängt die erste Urinportion in einem sterilen Becher auf, anschließend wird die DNA mittels PCR bestimmt', 'Hasta ilk idrar akımını steril kaba kendisi toplar, ardından DNA PCR yöntemiyle belirlenir', 'Discomfort or burning on urination, discharge, screening after a change of partner and when planning a pregnancy, testing of a partner, follow-up after treatment as prescribed', 'Nelagoda i peckanje pri mokrenju, sekret, skrining pri promjeni partnera i pri planiranju trudnoće, pregled partnera, kontrola poslije liječenja po nalogu ljekara', 'Нелагода и пецкање при мокрењу, секрет, скрининг при промјени партнера и при планирању трудноће, преглед партнера, контрола послије лијечења по налогу љекара', 'Дискомфорт и жжение при мочеиспускании, выделения, скрининг при смене партнёра и при планировании беременности, обследование партнёра, контроль после лечения по назначению врача', 'Beschwerden oder Brennen beim Wasserlassen, Ausfluss, Screening bei Partnerwechsel und bei Kinderwunsch, Untersuchung des Partners, Kontrolle nach Behandlung auf ärztliche Anordnung', 'İdrar yaparken rahatsızlık ve yanma, akıntı, partner değişiminde ve gebelik planlamasında tarama, partnerin incelenmesi, hekim önerisiyle tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before collection, collect exactly the first portion of the stream, do not use antiseptics for hygiene beforehand; the interval after antibiotics is set by the doctor', 'Ne mokriti 2–3 sata prije sakupljanja, uzeti baš prvi mlaz, ne koristiti antiseptike pri higijeni; razmak poslije antibiotika određuje ljekar', 'Не мокрити 2–3 сата прије сакупљања, узети баш први млаз, не користити антисептике при хигијени; размак послије антибиотика одређује љекар', 'Не мочиться 2–3 часа до сбора, собрать именно первую порцию струи, не использовать антисептики при гигиене; сроки после приёма антибиотиков уточняет врач', '2–3 Stunden vor der Gewinnung nicht Wasser lassen, genau die erste Portion des Strahls auffangen, vorher keine Antiseptika zur Reinigung verwenden; den Abstand nach einer Antibiotikatherapie legt der Arzt fest', 'Toplamadan 2–3 saat önce idrara çıkmamak, akımın tam ilk bölümünü almak, temizlikte antiseptik kullanmamak gerekir; antibiyotik sonrası bekleme süresini hekim belirler', 'Detected DNA means the bacterium is present in the sample. A negative urine result does not always rule out infection at another site, so the need for a swab and the next steps are decided by the doctor', 'Nalaz DNK znači da je bakterija prisutna u uzorku. Negativan nalaz iz mokraće ne isključuje uvijek infekciju na drugom mjestu, pa potrebu za brisom i dalje korake određuje ljekar', 'Налаз ДНК значи да је бактерија присутна у узорку. Негативан налаз из мокраће не искључује увијек инфекцију на другом мјесту, па потребу за брисом и даље кораке одређује љекар', 'Обнаружение ДНК означает присутствие бактерии в пробе. Отрицательный результат из мочи не всегда исключает инфекцию другой локализации, поэтому необходимость мазка и дальнейшую тактику определяет врач', 'Nachgewiesene DNA bedeutet, dass der Erreger in der Probe vorhanden ist. Ein negativer Urinbefund schließt eine Infektion an anderer Stelle nicht immer aus, über einen Abstrich und das weitere Vorgehen entscheidet der Arzt', 'DNA saptanması bakterinin örnekte bulunduğunu gösterir. İdrarda negatif sonuç başka bölgedeki enfeksiyonu her zaman dışlamaz, sürüntü gerekip gerekmediğine ve sonraki adımlara hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'sars-cov-2-pcr'), 'A molecular test detecting SARS-CoV-2 viral RNA by real-time PCR', 'Molekularni test koji otkriva RNK virusa SARS-CoV-2 metodom PCR u realnom vremenu', 'Молекуларни тест који открива РНК вируса SARS-CoV-2 методом ПЦР у реалном времену', 'Молекулярный тест, выявляющий РНК вируса SARS-CoV-2 методом ПЦР в реальном времени', 'Molekularer Test zum Nachweis der RNA des Virus SARS-CoV-2 mittels Real-Time-PCR', 'SARS-CoV-2 virüsünün RNA''sını gerçek zamanlı PCR yöntemiyle saptayan moleküler test', 'A swab from the nasopharynx and throat with a single-use swab, sampling takes about a minute, the sample is then processed in the laboratory', 'Bris iz nazofarinksa i ždrijela jednokratnim štapićem, uzimanje traje oko minut, uzorak se zatim obrađuje u laboratoriji', 'Брис из назофаринкса и ждријела једнократним штапићем, узимање траје око минут, узорак се затим обрађује у лабораторији', 'Мазок из носоглотки и ротоглотки одноразовым тампоном, забор занимает около минуты, дальше пробу исследуют в лаборатории', 'Abstrich aus Nasenrachenraum und Rachen mit einem Einwegtupfer, die Entnahme dauert etwa eine Minute, danach wird die Probe im Labor untersucht', 'Tek kullanımlık çubukla genizden ve boğazdan sürüntü alınır, işlem yaklaşık bir dakika sürer, örnek sonra laboratuvarda çalışılır', 'Symptoms of a respiratory infection, contact with an infected person, checking before a planned hospital admission or procedure, requirements of a particular institution or destination country', 'Simptomi respiratorne infekcije, kontakt sa oboljelim, provjera prije planiranog prijema u bolnicu ili zahvata, zahtjevi konkretne ustanove ili zemlje u koju se putuje', 'Симптоми респираторне инфекције, контакт са обољелим, провјера прије планираног пријема у болницу или захвата, захтјеви конкретне установе или земље у коју се путује', 'Симптомы респираторной инфекции, контакт с заболевшим, обследование перед плановой госпитализацией или вмешательством, требования конкретного учреждения или страны назначения', 'Symptome eines Atemwegsinfekts, Kontakt zu einer erkrankten Person, Untersuchung vor geplanter Aufnahme oder einem Eingriff, Vorgaben einer bestimmten Einrichtung oder des Ziellandes', 'Solunum yolu enfeksiyonu belirtileri, hasta biriyle temas, planlı hastane yatışı veya işlem öncesi kontrol, ilgili kurumun ya da gidilecek ülkenin istediği koşullar', 'One to two hours before the swab do not eat, drink, brush teeth, rinse the mouth or use nasal sprays and drops', 'Sat do dva prije brisa ne jesti, ne piti, ne prati zube, ne ispirati usta i ne koristiti sprejeve i kapi za nos', 'Сат до два прије бриса не јести, не пити, не прати зубе, не испирати уста и не користити спрејеве и капи за нос', 'За час-два до мазка не есть, не пить, не чистить зубы, не полоскать рот и не использовать спреи и капли в нос', 'Ein bis zwei Stunden vor dem Abstrich nicht essen, trinken, Zähne putzen, den Mund spülen oder Nasensprays und Nasentropfen verwenden', 'Sürüntüden bir iki saat önce yememek, içmemek, diş fırçalamamak, ağzı çalkalamamak ve burun spreyi ya da damlası kullanmamak gerekir', 'A positive result means viral RNA was found in the sample, a negative one does not rule out infection very early in the illness or after incorrect sampling. Decisions about treatment and isolation are made by a doctor', 'Pozitivan nalaz znači da je RNK virusa nađena u uzorku, negativan ne isključuje infekciju na samom početku bolesti ili kod loše uzetog uzorka. Odluku o liječenju i izolaciji donosi ljekar', 'Позитиван налаз значи да је РНК вируса нађена у узорку, негативан не искључује инфекцију на самом почетку болести или код лоше узетог узорка. Одлуку о лијечењу и изолацији доноси љекар', 'Положительный результат означает, что РНК вируса найдена в пробе; отрицательный не исключает инфекцию в самом начале болезни или при неправильном заборе. Решение о лечении и изоляции принимает врач', 'Ein positives Ergebnis bedeutet, dass Virus-RNA in der Probe nachgewiesen wurde, ein negatives schließt eine Infektion ganz zu Beginn der Erkrankung oder bei fehlerhafter Entnahme nicht aus. Über Behandlung und Isolation entscheidet der Arzt', 'Pozitif sonuç virüs RNA''sının örnekte bulunduğunu gösterir, negatif sonuç hastalığın ilk gününde ya da örnek hatalı alındığında enfeksiyonu dışlamaz. Tedavi ve izolasyon kararını hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'fecal-occult-blood'), 'A stool test for traces of blood that are not visible to the eye', 'Analiza stolice na tragove krvi koji se ne vide golim okom', 'Анализа столице на трагове крви који се не виде голим оком', 'Анализ кала на следы крови, не видимые глазом', 'Stuhltest auf Blutspuren, die mit bloßem Auge nicht sichtbar sind', 'Gaitada gözle görülmeyen kan izlerini arayan test', 'At home the patient collects a small stool sample into a container with a spatula and brings it to the laboratory; modern immunochemical tests react only to human haemoglobin', 'Pacijent kod kuće sakupi mali uzorak stolice u posudu sa lopaticom i donese ga u laboratoriju; savremeni imunohemijski testovi reaguju samo na ljudski hemoglobin', 'Пацијент код куће сакупи мали узорак столице у посуду са лопатицом и донесе га у лабораторију; савремени имунохемијски тестови реагују само на људски хемоглобин', 'Пациент дома собирает небольшую пробу кала в контейнер с лопаточкой и приносит в лабораторию; современные иммунохимические тесты реагируют только на человеческий гемоглобин', 'Zu Hause entnimmt die Patientin oder der Patient mit einem Spatel eine kleine Stuhlprobe in ein Röhrchen und bringt sie ins Labor; moderne immunchemische Tests reagieren nur auf menschliches Hämoglobin', 'Hasta evde spatulalı kaba küçük bir gaita örneği alır ve laboratuvara getirir; güncel immünkimyasal testler yalnızca insan hemoglobinine tepki verir', 'Preventive bowel screening programmes, anaemia of unclear origin, persistent changes in stool, abdominal pain, monitoring as prescribed by a doctor', 'Preventivni programi pregleda crijeva, anemija nejasnog uzroka, uporne promjene stolice, bolovi u trbuhu, praćenje po nalogu ljekara', 'Превентивни програми прегледа цријева, анемија нејасног узрока, упорне промјене столице, болови у трбуху, праћење по налогу љекара', 'Профилактические программы обследования кишечника, анемия неясного происхождения, стойкие изменения стула, боли в животе, наблюдение по назначению врача', 'Vorsorgeprogramme zur Darmuntersuchung, Blutarmut unklarer Ursache, anhaltende Stuhlveränderungen, Bauchschmerzen, Verlaufskontrolle auf ärztliche Anordnung', 'Koruyucu bağırsak tarama programları, nedeni belirsiz kansızlık, dışkıda süregelen değişiklikler, karın ağrısı, hekim önerisiyle izlem', 'An immunochemical test usually needs no diet; do not collect the sample during menstruation, during a haemorrhoid flare-up or with bleeding gums, and never take it from toilet water', 'Za imunohemijski test dijeta obično nije potrebna; uzorak ne uzimati u dane menstruacije, kod pogoršanja hemoroida i krvarenja desni, niti iz vode u šolji', 'За имунохемијски тест дијета обично није потребна; узорак не узимати у дане менструације, код погоршања хемороида и крварења десни, нити из воде у шољи', 'Для иммунохимического теста диета обычно не нужна; не собирать пробу в дни менструации, при обострении геморроя и кровоточивости дёсен, не брать материал из воды в унитазе', 'Für den immunchemischen Test ist meist keine Diät nötig; die Probe nicht während der Menstruation, bei akuten Hämorrhoiden oder Zahnfleischbluten und nie aus dem Toilettenwasser entnehmen', 'İmmünkimyasal test için genellikle diyet gerekmez; örneği adet günlerinde, hemoroit alevlenmesinde ve diş eti kanaması varken almamak, klozetteki sudan hiç almamak gerekir', 'Blood in the sample may be related to bleeding at any level of the digestive tract, including haemorrhoids and fissures. Further investigation, most often an examination of the bowel, is arranged by the doctor', 'Nalaz krvi može biti povezan sa krvarenjem na bilo kom nivou probavnog trakta, uključujući hemoroide i fisure. Dopunsku obradu, najčešće pregled crijeva, određuje ljekar', 'Налаз крви може бити повезан са крварењем на било ком нивоу пробавног тракта, укључујући хемороиде и фисуре. Допунску обраду, најчешће преглед цријева, одређује љекар', 'Обнаружение крови может быть связано с кровоточивостью на любом уровне пищеварительного тракта, включая геморрой и трещины. Уточняющее обследование, чаще всего осмотр кишечника, назначает врач', 'Nachgewiesenes Blut kann mit einer Blutung auf jeder Ebene des Verdauungstrakts zusammenhängen, auch mit Hämorrhoiden oder Einrissen. Die weiterführende Abklärung, meist eine Darmuntersuchung, veranlasst der Arzt', 'Kan bulunması hemoroit ve çatlaklar dahil sindirim yolunun herhangi bir düzeyindeki kanamayla ilişkili olabilir. Çoğunlukla bağırsak incelemesi olan ileri tetkiki hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'calprotectin'), 'A neutrophil protein measured in stool as an indicator of inflammation in the bowel', 'Bjelančevina iz neutrofila koja se mjeri u stolici kao pokazatelj upale u crijevima', 'Бјеланчевина из неутрофила која се мјери у столици као показатељ упале у цријевима', 'Белок из нейтрофилов, который определяют в кале как показатель воспаления в кишечнике', 'Ein Protein aus neutrophilen Granulozyten, das im Stuhl als Hinweis auf eine Entzündung im Darm bestimmt wird', 'Bağırsaktaki iltihabın göstergesi olarak gaitada ölçülen, nötrofillerden kaynaklanan bir protein', 'A small stool sample is collected into a container and analysed in the laboratory; no blood draw is needed for this test', 'Mali uzorak stolice u posudi, analiza se radi u laboratoriji; vađenje krvi za ovaj nalaz nije potrebno', 'Мали узорак столице у посуди, анализа се ради у лабораторији; вађење крви за овај налаз није потребно', 'Небольшая проба кала в контейнере, анализ выполняется в лаборатории; кровь для этого исследования брать не нужно', 'Eine kleine Stuhlprobe wird in ein Röhrchen gegeben und im Labor untersucht; eine Blutentnahme ist dafür nicht nötig', 'Küçük bir gaita örneği kaba alınır ve laboratuvarda çalışılır; bu tetkik için kan alınması gerekmez', 'Prolonged diarrhoea, abdominal pain, distinguishing inflammatory from functional causes of complaints, monitoring chronic inflammatory bowel disease, assessing the effect of prescribed treatment', 'Dugotrajni proliv, bol u trbuhu, razlikovanje upalnih od funkcionalnih uzroka tegoba, praćenje hroničnih upalnih bolesti crijeva, procjena djelovanja propisane terapije', 'Дуготрајни пролив, бол у трбуху, разликовање упалних од функционалних узрока тегоба, праћење хроничних упалних болести цријева, процјена дјеловања прописане терапије', 'Длительная диарея, боль в животе, различение воспалительных и функциональных причин жалоб, наблюдение за течением хронических воспалительных заболеваний кишечника, оценка эффекта назначенного лечения', 'Anhaltender Durchfall, Bauchschmerzen, Unterscheidung entzündlicher von funktionellen Ursachen der Beschwerden, Verlaufskontrolle chronisch entzündlicher Darmerkrankungen, Beurteilung des Therapieerfolgs', 'Uzun süren ishal, karın ağrısı, şikayetlerin iltihabi mi işlevsel mi olduğunun ayrımı, kronik iltihabi bağırsak hastalıklarının izlemi, verilen tedavinin etkisinin değerlendirilmesi', 'No special diet is required; tell the doctor about non-steroidal anti-inflammatory drugs as they can affect the result, and never take the sample from toilet water', 'Posebna dijeta nije potrebna; obavijestiti ljekara o uzimanju nesteroidnih antiinflamatornih lijekova jer mogu uticati na nalaz, uzorak ne uzimati iz vode u šolji', 'Посебна дијета није потребна; обавијестити љекара о узимању нестероидних антиинфламаторних лијекова јер могу утицати на налаз, узорак не узимати из воде у шољи', 'Специальной диеты не требуется; сообщите врачу о приёме нестероидных противовоспалительных препаратов — они могут влиять на результат, материал не берут из воды в унитазе', 'Keine besondere Diät nötig; die Einnahme nicht steroidaler Entzündungshemmer dem Arzt mitteilen, da sie das Ergebnis beeinflussen kann, und die Probe nie aus dem Toilettenwasser entnehmen', 'Özel diyet gerekmez; steroid olmayan ağrı kesici kullanımı sonucu etkileyebileceğinden hekime bildirilmeli, örnek klozetteki sudan alınmamalıdır', 'An elevated value may be related to inflammation in the bowel, an intestinal infection or certain medicines. Whether an endoscopic examination is needed is decided by the doctor', 'Povišena vrijednost može biti povezana sa upalom u crijevima, crijevnom infekcijom ili uzimanjem pojedinih lijekova. Da li je potrebna endoskopska obrada, odlučuje ljekar', 'Повишена вриједност може бити повезана са упалом у цријевима, цријевном инфекцијом или узимањем појединих лијекова. Да ли је потребна ендоскопска обрада, одлучује љекар', 'Повышение может быть связано с воспалением в кишечнике, кишечной инфекцией или приёмом некоторых препаратов. Нужно ли эндоскопическое обследование, решает врач', 'Ein erhöhter Wert kann mit einer Entzündung im Darm, einer Darminfektion oder bestimmten Medikamenten zusammenhängen. Ob eine endoskopische Abklärung nötig ist, entscheidet der Arzt', 'Yüksek değer bağırsaktaki iltihapla, bağırsak enfeksiyonuyla ya da bazı ilaçların kullanımıyla ilişkili olabilir. Endoskopik incelemenin gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'afp'), 'A protein produced by the fetal liver; in adults it is measured in blood as one of the monitoring parameters, and in pregnancy it belongs to a screening set', 'Bjelančevina koju stvara jetra ploda; kod odraslih se mjeri u krvi kao jedan od pokazatelja praćenja, a u trudnoći ulazi u sklop skrininga', 'Бјеланчевина коју ствара јетра плода; код одраслих се мјери у крви као један од показатеља праћења, а у трудноћи улази у склоп скрининга', 'Белок, который вырабатывает печень плода; у взрослых его определяют в крови как один из показателей наблюдения, а при беременности он входит в комплекс скрининга', 'Ein Eiweiß, das die Leber des Ungeborenen bildet; bei Erwachsenen wird es im Blut als Verlaufsparameter bestimmt, in der Schwangerschaft gehört es zu einem Screening-Satz', 'Bebeğin karaciğerinde üretilen bir protein; yetişkinlerde izlem parametrelerinden biri olarak kanda ölçülür, gebelikte ise tarama setinin parçasıdır', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Second-trimester prenatal screening as part of a set of parameters, monitoring in chronic liver disease, follow-up over time as prescribed by a doctor', 'Prenatalni skrining u drugom tromjesečju kao dio skupa pokazatelja, praćenje kod hroničnih bolesti jetre, praćenje kroz vrijeme po nalogu ljekara', 'Пренатални скрининг у другом тромјесечју као дио скупа показатеља, праћење код хроничних болести јетре, праћење кроз вријеме по налогу љекара', 'Пренатальный скрининг второго триместра в составе набора показателей, наблюдение при хронических заболеваниях печени, динамическое наблюдение по назначению врача', 'Pränatales Screening im zweiten Trimester als Teil eines Parametersatzes, Verlaufskontrolle bei chronischen Lebererkrankungen, Kontrolle im Zeitverlauf auf ärztliche Anordnung', 'İkinci üç aylık dönemde parametre setinin parçası olarak prenatal tarama, kronik karaciğer hastalıklarında izlem, hekim önerisiyle zaman içinde takip', 'Usually no special preparation is needed; in pregnancy the exact gestational age must be stated, without it the result is not assessed', 'Posebna priprema obično nije potrebna; u trudnoći je nužno tačno navesti gestacijsku starost, bez toga se nalaz ne procjenjuje', 'Посебна припрема обично није потребна; у трудноћи је нужно тачно навести гестацијску старост, без тога се налаз не процјењује', 'Специальной подготовки обычно не требуется; при беременности нужно точно указать срок — без него результат не оценивают', 'Meist ist keine besondere Vorbereitung nötig; in der Schwangerschaft muss die Schwangerschaftswoche genau angegeben werden, sonst ist der Wert nicht beurteilbar', 'Genellikle özel hazırlık gerekmez; gebelikte gebelik haftasının tam olarak bildirilmesi gerekir, aksi halde sonuç değerlendirilmez', 'The value is not interpreted on its own: in pregnancy it is assessed only together with the other screening parameters and the gestational age, outside pregnancy over time and alongside other investigations. Conclusions are drawn by a doctor', 'Pokazatelj se ne tumači sam za sebe: u trudnoći se procjenjuje isključivo zajedno sa ostalim pokazateljima skrininga i gestacijskom starošću, van trudnoće kroz vrijeme i uz druge nalaze. Zaključak donosi ljekar', 'Показатељ се не тумачи сам за себе: у трудноћи се процјењује искључиво заједно са осталим показатељима скрининга и гестацијском старошћу, ван трудноће кроз вријеме и уз друге налазе. Закључак доноси љекар', 'Показатель не трактуется сам по себе: при беременности его оценивают только вместе с остальными показателями скрининга и сроком, вне беременности — в динамике и вместе с другими исследованиями. Выводы делает врач', 'Der Wert wird nicht für sich allein gedeutet: in der Schwangerschaft nur zusammen mit den übrigen Screening-Parametern und der Schwangerschaftswoche, außerhalb der Schwangerschaft im Verlauf und zusammen mit anderen Untersuchungen. Die Bewertung nimmt der Arzt vor', 'Değer tek başına yorumlanmaz: gebelikte yalnızca diğer tarama parametreleri ve gebelik haftasıyla birlikte, gebelik dışında ise zaman içindeki seyriyle ve diğer tetkiklerle birlikte değerlendirilir. Yorumu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'interleukin-6'), 'A cytokine used to assess how active the body''s inflammatory response is', 'Citokin po kojem se procjenjuje aktivnost upalnog odgovora organizma', 'Цитокин по којем се процјењује активност упалног одговора организма', 'Цитокин, по которому оценивают активность воспалительного ответа организма', 'Ein Zytokin, mit dem die Aktivität der Entzündungsreaktion des Körpers beurteilt wird', 'Vücudun iltihap yanıtının ne kadar etkin olduğunu değerlendirmeye yarayan bir sitokin', 'Venous blood draw into a separate tube, the assay is run in the laboratory', 'Uzimanje venske krvi u zasebnu epruvetu, analiza se radi u laboratoriji', 'Узимање венске крви у засебну епрувету, анализа се ради у лабораторији', 'Забор венозной крови в отдельную пробирку, исследование выполняется в лаборатории', 'Venöse Blutentnahme in ein eigenes Röhrchen, die Bestimmung erfolgt im Labor', 'Ayrı bir tüpe venöz kan alınır, çalışma laboratuvarda yapılır', 'Assessing the intensity of inflammation in severe infections, monitoring in hospital, rheumatic and autoimmune diseases, as an addition to other inflammatory markers, monitoring during prescribed therapy', 'Procjena jačine upale kod teških infekcija, praćenje u bolnici, reumatske i autoimune bolesti, dopuna drugim pokazateljima upale, kontrola tokom propisane terapije', 'Процјена јачине упале код тешких инфекција, праћење у болници, реуматске и аутоимуне болести, допуна другим показатељима упале, контрола током прописане терапије', 'Оценка выраженности воспаления при тяжёлых инфекциях, наблюдение в стационаре, ревматические и аутоиммунные заболевания, дополнение к другим маркерам воспаления, контроль на фоне назначенной терапии', 'Beurteilung der Entzündungsstärke bei schweren Infektionen, Überwachung im Krankenhaus, rheumatische und autoimmune Erkrankungen, Ergänzung zu anderen Entzündungsmarkern, Kontrolle unter laufender Therapie', 'Ağır enfeksiyonlarda iltihabın şiddetinin değerlendirilmesi, hastanede izlem, romatizmal ve otoimmün hastalıklar, diğer iltihap belirteçlerine ek olarak, verilen tedavi sırasında takip', 'Strict fasting is usually not required; about 15 minutes of rest before the draw is advisable and intense physical exercise should be avoided the day before', 'Strogo gladovanje obično nije potrebno; poželjno je petnaestak minuta mirovanja prije vađenja krvi, a dan ranije izbjegavati jake fizičke napore', 'Строго гладовање обично није потребно; пожељно је петнаестак минута мировања прије вађења крви, а дан раније избјегавати јаке физичке напоре', 'Строгого голодания обычно не требуется; перед забором желательно 15 минут покоя, накануне избегать интенсивных физических нагрузок', 'Striktes Nüchternsein ist meist nicht nötig; etwa 15 Minuten Ruhe vor der Entnahme sind sinnvoll, am Vortag starke körperliche Belastung meiden', 'Genellikle sıkı açlık gerekmez; kan alınmadan önce yaklaşık 15 dakika dinlenmek iyi olur, bir gün önce yoğun fiziksel efordan kaçınılmalıdır', 'An increase may be related to active inflammation of any origin, such as infection, injury or a flare of a chronic disease. The marker is not interpreted in isolation, the doctor assesses it together with the rest of the findings', 'Povišena vrijednost može biti povezana sa aktivnom upalom bilo kog porijekla, infekcijom, povredom ili pogoršanjem hronične bolesti. Pokazatelj se ne tumači izdvojeno, ljekar ga procjenjuje uz ostale nalaze', 'Повишена вриједност може бити повезана са активном упалом било ког поријекла, инфекцијом, повредом или погоршањем хроничне болести. Показатељ се не тумачи издвојено, љекар га процјењује уз остале налазе', 'Повышение может быть связано с активным воспалением любой природы — инфекцией, травмой, обострением хронического заболевания. Изолированно показатель не трактуется, врач оценивает его вместе с остальными данными', 'Ein Anstieg kann mit einer aktiven Entzündung jeder Ursache zusammenhängen, etwa Infektion, Verletzung oder Schub einer chronischen Erkrankung. Der Wert wird nicht isoliert gedeutet, der Arzt beurteilt ihn zusammen mit den übrigen Befunden', 'Yükseklik enfeksiyon, yaralanma ya da kronik bir hastalığın alevlenmesi gibi her türden etkin iltihapla ilişkili olabilir. Belirteç tek başına yorumlanmaz, hekim diğer bulgularla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ogtt-3-point'), 'A glucose load test: glucose is measured fasting and then 60 and 120 minutes after drinking a glucose solution', 'Test opterećenja šećerom: glukoza se mjeri našte, pa 60 i 120 minuta poslije ispijanja rastvora glukoze', 'Тест оптерећења шећером: глукоза се мјери наште, па 60 и 120 минута послије испијања раствора глукозе', 'Тест с сахарной нагрузкой: уровень глюкозы измеряют натощак, затем через 60 и 120 минут после приёма раствора глюкозы', 'Belastungstest mit Zucker: Glukose wird nüchtern sowie 60 und 120 Minuten nach dem Trinken einer Glukoselösung gemessen', 'Şeker yükleme testi: glukoz açken, ardından glukoz çözeltisi içildikten 60 ve 120 dakika sonra ölçülür', 'The first sample is taken fasting, the patient then drinks the solution prepared by the laboratory and stays at the clinic for two more hours, during which blood is drawn twice more', 'Prvo vađenje krvi je našte, zatim pacijent popije rastvor koji priprema laboratorija i ostaje u ustanovi još dva sata, tokom kojih se krv vadi još dva puta', 'Прво вађење крви је наште, затим пацијент попије раствор који припрема лабораторија и остаје у установи још два сата, током којих се крв вади још два пута', 'Первый забор крови натощак, затем пациент выпивает подготовленный лабораторией раствор и остаётся в клинике ещё на два часа, за это время кровь берут ещё дважды', 'Die erste Blutentnahme erfolgt nüchtern, danach trinkt die Patientin oder der Patient die vom Labor vorbereitete Lösung und bleibt zwei weitere Stunden in der Einrichtung, in denen noch zweimal Blut abgenommen wird', 'İlk kan açken alınır, sonra hasta laboratuvarın hazırladığı çözeltiyi içer ve iki saat daha kurumda kalır, bu süre içinde iki kez daha kan alınır', 'A borderline fasting glucose result, screening for gestational diabetes during pregnancy, assessment of carbohydrate metabolism disorders, excess weight and other risk factors on a doctor''s referral', 'Granična vrijednost glukoze našte, skrining gestacijskog dijabetesa tokom trudnoće, procjena poremećaja metabolizma ugljenih hidrata, prekomjerna težina i drugi faktori rizika po uputu ljekara', 'Гранична вриједност глукозе наште, скрининг гестацијског дијабетеса током трудноће, процјена поремећаја метаболизма угљених хидрата, прекомјерна тежина и други фактори ризика по упуту љекара', 'Пограничный результат глюкозы натощак, скрининг гестационного диабета во время беременности, оценка нарушений углеводного обмена, избыточный вес и другие факторы риска по направлению врача', 'Grenzwertiger Nüchternblutzucker, Screening auf Schwangerschaftsdiabetes während der Schwangerschaft, Abklärung von Störungen des Kohlenhydratstoffwechsels, Übergewicht und weitere Risikofaktoren nach ärztlicher Überweisung', 'Sınırda açlık glukoz sonucu, gebelik sırasında gebelik şekeri taraması, karbonhidrat metabolizması bozukluklarının değerlendirilmesi, hekim yönlendirmesiyle fazla kilo ve diğer risk etkenleri', 'Fasting for 8–12 hours, only water allowed; do not restrict carbohydrates in the three days before, and during the test do not eat, smoke or walk around, telling the staff at once if you feel unwell', 'Natašte 8–12 sati, dozvoljena samo voda; tri dana prije testa ne ograničavati unos ugljenih hidrata, tokom testa ne jesti, ne pušiti i ne hodati, a kod lošeg osjećaja odmah obavijestiti osoblje', 'Наташте 8–12 сати, дозвољена само вода; три дана прије теста не ограничавати унос угљених хидрата, током теста не јести, не пушити и не ходати, а код лошег осјећаја одмах обавијестити особље', 'Натощак 8–12 часов, разрешена только вода; за три дня до теста не ограничивать углеводы в питании, во время теста не есть, не курить и не ходить, при плохом самочувствии сразу сказать персоналу', 'Nüchtern seit 8–12 Stunden, nur Wasser erlaubt; in den drei Tagen davor Kohlenhydrate nicht einschränken, während des Tests nicht essen, nicht rauchen und nicht umhergehen, bei Unwohlsein sofort das Personal informieren', '8–12 saat açlık, sadece su içilebilir; testten önceki üç gün karbonhidratı kısıtlamamak, test sırasında yememek, sigara içmemek ve dolaşmamak, kötü hissedildiğinde hemen personele söylemek gerekir', 'Deviations at any of the three time points may be related to a carbohydrate metabolism disorder or to temporary factors such as a recent illness, stress or medicines. The conclusion is made by a doctor, who may order a repeat test', 'Odstupanja u bilo kojoj od tri tačke mogu biti povezana sa poremećajem metabolizma ugljenih hidrata ili sa privremenim faktorima, skorašnjom bolešću, stresom, lijekovima. Zaključak donosi ljekar i po potrebi određuje ponovni test', 'Одступања у било којој од три тачке могу бити повезана са поремећајем метаболизма угљених хидрата или са привременим факторима, скорашњом болешћу, стресом, лијековима. Закључак доноси љекар и по потреби одређује поновни тест', 'Отклонения в любой из трёх точек могут быть связаны с нарушением углеводного обмена или с временными факторами — недавней болезнью, стрессом, приёмом лекарств. Заключение делает врач и при необходимости назначает повторный тест', 'Abweichungen an einem der drei Messpunkte können mit einer Störung des Kohlenhydratstoffwechsels oder mit vorübergehenden Faktoren wie einer kürzlichen Erkrankung, Stress oder Medikamenten zusammenhängen. Die Beurteilung erfolgt durch den Arzt, der bei Bedarf eine Wiederholung veranlasst', 'Üç ölçümün herhangi birindeki sapma karbonhidrat metabolizması bozukluğuyla ya da yakın zamandaki hastalık, stres, ilaç gibi geçici etkenlerle ilişkili olabilir. Sonucu hekim değerlendirir, gerekirse testi yineletir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'valproic-acid'), 'Measurement of the valproic acid concentration in the blood of patients to whom this medicine has been prescribed', 'Mjerenje koncentracije valproične kiseline u krvi kod pacijenata kojima je ovaj lijek propisan', 'Мјерење концентрације валпроичне киселине у крви код пацијената којима је овај лијек прописан', 'Измерение концентрации вальпроевой кислоты в крови у пациентов, которым этот препарат назначен', 'Messung der Valproinsäure-Konzentration im Blut bei Patientinnen und Patienten, denen dieses Medikament verordnet wurde', 'Bu ilacın reçete edildiği hastalarda kandaki valproik asit düzeyinin ölçülmesi', 'Venous blood draw; the timing relative to the dose is set by the treating doctor, the sample is most often taken before the next dose', 'Uzimanje venske krvi; vrijeme vađenja u odnosu na uzimanje terapije određuje ljekar koji vodi liječenje, uzorak se najčešće uzima prije naredne doze', 'Узимање венске крви; вријеме вађења у односу на узимање терапије одређује љекар који води лијечење, узорак се најчешће узима прије наредне дозе', 'Забор венозной крови; время забора относительно приёма препарата задаёт лечащий врач, чаще всего кровь берут перед очередным приёмом', 'Venöse Blutentnahme; den Zeitpunkt im Verhältnis zur Einnahme legt die behandelnde Ärztin oder der behandelnde Arzt fest, meist wird vor der nächsten Gabe Blut entnommen', 'Venöz kan alınır; kanın ilaca göre hangi saatte alınacağını tedaviyi yürüten hekim belirler, örnek çoğunlukla bir sonraki dozdan önce alınır', 'Monitoring prescribed therapy, a change in how the patient feels during treatment, suspicion of insufficient effect or of unwanted reactions, concomitant liver or kidney disease, use of other medicines at the same time, pregnancy at the doctor''s discretion', 'Kontrola propisane terapije, promjena stanja tokom liječenja, sumnja na nedovoljan učinak ili na neželjene reakcije, prateće bolesti jetre i bubrega, istovremeno uzimanje drugih lijekova, trudnoća po odluci ljekara', 'Контрола прописане терапије, промјена стања током лијечења, сумња на недовољан учинак или на нежељене реакције, пратеће болести јетре и бубрега, истовремено узимање других лијекова, трудноћа по одлуци љекара', 'Контроль назначенной терапии, изменение самочувствия на фоне лечения, подозрение на недостаточный эффект или на нежелательные реакции, сопутствующие заболевания печени и почек, одновременный приём других препаратов, беременность по решению врача', 'Kontrolle der verordneten Therapie, Veränderung des Befindens unter Behandlung, Verdacht auf unzureichende Wirkung oder auf unerwünschte Reaktionen, begleitende Leber- oder Nierenerkrankungen, gleichzeitige Einnahme weiterer Medikamente, Schwangerschaft nach ärztlicher Entscheidung', 'Verilen tedavinin takibi, tedavi sırasında genel durumdaki değişiklik, etkinin yetersiz olduğu ya da istenmeyen tepkiler geliştiği kuşkusu, eşlik eden karaciğer ve böbrek hastalıkları, aynı anda başka ilaç kullanımı, hekim kararıyla gebelik', 'Do not change the dosing schedule on your own: a dose is skipped or moved before the test only on the doctor''s instruction; bring details of the medicine and the time of the last intake', 'Raspored uzimanja ne mijenjati na svoju ruku: doza se prije analize preskače ili pomjera isključivo po uputstvu ljekara; ponijeti podatke o terapiji i vremenu posljednjeg uzimanja', 'Распоред узимања не мијењати на своју руку: доза се прије анализе прескаче или помјера искључиво по упутству љекара; понијети податке о терапији и времену посљедњег узимања', 'Схему приёма самостоятельно не менять: пропустить или перенести дозу перед анализом можно только по указанию врача; при себе иметь сведения о препарате и времени последнего приёма', 'Das Einnahmeschema nicht eigenmächtig ändern: eine Dosis wird vor der Untersuchung nur auf ärztliche Anweisung ausgelassen oder verschoben; Angaben zum Medikament und zur Zeit der letzten Einnahme mitbringen', 'İlaç düzenini kendi başınıza değiştirmeyin: testten önce doz yalnızca hekimin talimatıyla atlanır ya da ertelenir; ilaç bilgisini ve son alım saatini yanınızda getirin', 'The result means nothing on its own, it is compared with the prescribed treatment schedule, the patient''s condition and other tests by the treating doctor only', 'Rezultat sam po sebi ništa ne znači, sa propisanom shemom liječenja, stanjem pacijenta i drugim nalazima poredi ga isključivo ljekar koji vodi liječenje', 'Резултат сам по себи ништа не значи, са прописаном схемом лијечења, стањем пацијента и другим налазима пореди га искључиво љекар који води лијечење', 'Результат сам по себе ничего не означает — его сопоставляет с назначенной схемой лечения, самочувствием и другими анализами только лечащий врач', 'Der Wert allein sagt nichts aus, er wird ausschließlich von der behandelnden Ärztin oder dem behandelnden Arzt mit dem verordneten Therapieschema, dem Befinden und weiteren Befunden abgeglichen', 'Sonuç tek başına bir anlam taşımaz, yalnızca tedaviyi yürüten hekim onu verilen tedavi şemasıyla, hastanın durumuyla ve diğer tetkiklerle karşılaştırır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'adenovirus-respiratory-test'), 'Test of a nasal or nasopharyngeal swab for adenovirus, one of the common causes of respiratory infections', 'Test brisa nosa ili nazofarinksa na adenovirus, jedan od čestih uzročnika respiratornih infekcija', 'Тест бриса носа или назофаринкса на аденовирус, један од честих узрочника респираторних инфекција', 'Тест мазка из носа или носоглотки на аденовирус, один из частых возбудителей респираторных инфекций', 'Test eines Nasen- oder Nasenrachenabstrichs auf Adenoviren, einen der häufigen Erreger von Atemwegsinfektionen', 'Solunum yolu enfeksiyonlarının sık nedenlerinden biri olan adenovirüs için burun veya nazofarenks sürüntü testi', 'A thin sterile swab collects material from the nasal passage, and the laboratory tests it for viral antigens or DNA', 'Tankim sterilnim štapićem uzima se materijal iz nosnog hodnika, a laboratorija ga ispituje na antigene ili DNK virusa', 'Танким стерилним штапићем узима се материјал из носног ходника, а лабораторија га испитује на антигене или ДНК вируса', 'Тонким стерильным тампоном берут материал из носового хода, в лаборатории его исследуют на антигены или ДНК вируса', 'Mit einem dünnen sterilen Tupfer wird Material aus dem Nasengang entnommen und im Labor auf Virusantigene oder DNA untersucht', 'İnce steril bir çubukla burun boşluğundan örnek alınır, laboratuvarda virüs antijenleri veya DNA''sı araştırılır', 'Acute respiratory infection with fever, runny nose and sore throat, respiratory complaints combined with conjunctivitis, testing in children, clarifying the cause during an outbreak in a group', 'Akutna respiratorna infekcija sa povišenom temperaturom, curenjem nosa i bolom u grlu, respiratorne tegobe uz konjunktivitis, ispitivanje kod djece, utvrđivanje uzroka tokom epidemije u kolektivu', 'Акутна респираторна инфекција са повишеном температуром, цурењем носа и болом у грлу, респираторне тегобе уз коњунктивитис, испитивање код дјеце, утврђивање узрока током епидемије у колективу', 'Острая респираторная инфекция с лихорадкой, насморком и болью в горле, сочетание респираторных жалоб с конъюнктивитом, обследование детей, уточнение причины при вспышке в коллективе', 'Akute Atemwegsinfektion mit Fieber, Schnupfen und Halsschmerzen, Atemwegsbeschwerden zusammen mit einer Bindehautentzündung, Untersuchung bei Kindern, Klärung der Ursache bei einem Ausbruch in einer Gemeinschaftseinrichtung', 'Ateş, burun akıntısı ve boğaz ağrısıyla seyreden akut solunum yolu enfeksiyonu, konjonktivitin eşlik ettiği solunum şikayetleri, çocuklarda inceleme, toplu yaşam alanlarındaki salgınlarda nedenin belirlenmesi', 'Do not rinse the nose or use drops and sprays for several hours before the swab; tell the doctor about any treatment already started', 'Nekoliko sati prije uzimanja uzorka ne ispirati nos i ne koristiti kapi ni sprejeve; o već započetoj terapiji obavijestiti ljekara', 'Неколико сати прије узимања узорка не испирати нос и не користити капи ни спрејеве; о већ започетој терапији обавијестити љекара', 'За несколько часов до забора не промывать нос и не использовать капли и спреи; о начатом лечении сообщить врачу', 'Einige Stunden vor der Entnahme die Nase nicht spülen und keine Tropfen oder Sprays verwenden; über bereits begonnene Behandlungen den Arzt informieren', 'Örnek alınmadan birkaç saat önce burun yıkanmamalı, damla ve sprey kullanılmamalıdır; başlanmış tedavi hekime bildirilmelidir', 'A positive result may be related to a current adenovirus infection, while a negative one does not rule out another pathogen. Follow-up and treatment are decided by the doctor', 'Pozitivan nalaz može biti povezan sa aktuelnom adenovirusnom infekcijom, dok negativan ne isključuje drugog uzročnika. Praćenje i liječenje određuje ljekar', 'Позитиван налаз може бити повезан са актуелном аденовирусном инфекцијом, док негативан не искључује другог узрочника. Праћење и лијечење одређује љекар', 'Положительный результат может быть связан с текущей аденовирусной инфекцией, отрицательный не исключает другого возбудителя. Тактику наблюдения и лечения определяет врач', 'Ein positives Ergebnis kann mit einer aktuellen Adenovirus-Infektion zusammenhängen, ein negatives schließt einen anderen Erreger nicht aus. Über Kontrolle und Behandlung entscheidet der Arzt', 'Pozitif sonuç güncel bir adenovirüs enfeksiyonuyla ilişkili olabilir, negatif sonuç başka bir etkeni dışlamaz. İzlem ve tedaviyi hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'azf-y-chromosome-deletions'), 'Molecular genetic test of the AZF regions on the Y chromosome, which are involved in sperm production', 'Molekularno-genetičko ispitivanje AZF regiona na Y hromozomu, koji učestvuju u stvaranju spermatozoida', 'Молекуларно-генетичко испитивање AZF региона на Y хромозому, који учествују у стварању сперматозоида', 'Молекулярно-генетическое исследование участков AZF на Y-хромосоме, которые связаны с образованием сперматозоидов', 'Molekulargenetische Untersuchung der AZF-Regionen auf dem Y-Chromosom, die an der Spermienbildung beteiligt sind', 'Y kromozomunda sperm yapımıyla ilişkili AZF bölgelerinin moleküler genetik incelemesi', 'A venous blood sample is taken, DNA is extracted and PCR checks for microdeletions in the AZFa, AZFb and AZFc regions', 'Uzima se venska krv, iz nje se izdvaja DNK i metodom PCR provjerava se postojanje mikrodelecija u regionima AZFa, AZFb i AZFc', 'Узима се венска крв, из ње се издваја ДНК и методом ПЦР провјерава се постојање микроделеција у регионима AZFa, AZFb и AZFc', 'Забор венозной крови, из которой выделяют ДНК и методом PCR проверяют наличие микроделеций в участках AZFa, AZFb и AZFc', 'Es wird venöses Blut entnommen, daraus DNA gewonnen und mittels PCR auf Mikrodeletionen in den Regionen AZFa, AZFb und AZFc geprüft', 'Toplardamardan kan alınır, DNA ayrıştırılır ve PCR yöntemiyle AZFa, AZFb ve AZFc bölgelerindeki mikrodelesyonlar araştırılır', 'Work-up for male infertility, markedly reduced sperm count or absence of sperm in the semen analysis, preparation for assisted reproduction programmes as referred by a doctor', 'Obrada zbog muške neplodnosti, izrazito smanjen broj spermatozoida ili njihovo odsustvo u spermogramu, priprema za postupke potpomognute oplodnje po uputu ljekara', 'Обрада због мушке неплодности, изразито смањен број сперматозоида или њихово одсуство у спермограму, припрема за поступке потпомогнуте оплодње по упуту љекара', 'Обследование при мужском бесплодии, резко сниженное количество сперматозоидов или их отсутствие в спермограмме, подготовка к программам вспомогательной репродукции по направлению врача', 'Abklärung bei männlicher Unfruchtbarkeit, deutlich verminderte Spermienzahl oder fehlende Spermien im Spermiogramm, Vorbereitung auf Verfahren der assistierten Reproduktion auf ärztliche Überweisung', 'Erkek kısırlığının araştırılması, spermiyogramda sperm sayısının belirgin azalması veya hiç sperm bulunmaması, hekim yönlendirmesiyle yardımcı üreme tekniklerine hazırlık', 'No special preparation is needed and fasting is not required; it helps to bring previous semen analysis and hormone results', 'Posebna priprema nije potrebna i ne uzima se natašte; korisno je ponijeti ranije nalaze spermograma i hormona', 'Посебна припрема није потребна и не узима се наташте; корисно је понијети раније налазе спермограма и хормона', 'Специальная подготовка не нужна, сдавать натощак не требуется; с собой полезно взять результаты спермограммы и гормональных анализов', 'Keine besondere Vorbereitung nötig, nüchtern sein ist nicht erforderlich; frühere Spermiogramm- und Hormonbefunde mitbringen', 'Özel hazırlık gerekmez, aç karnına gelmek zorunlu değildir; önceki spermiyogram ve hormon sonuçlarını getirmek yararlıdır', 'The result describes a variant of a chromosome region, not a diagnosis or a prognosis: genetic variants are also found in people without complaints. A clinical geneticist together with an andrologist interprets the finding taking the personal and family history into account', 'Nalaz opisuje varijantu regiona hromozoma, a ne dijagnozu ni prognozu: genetičke varijante se nalaze i kod osoba bez tegoba. Značenje nalaza procjenjuje ljekar genetičar zajedno sa andrologom, uz ličnu i porodičnu anamnezu', 'Налаз описује варијанту региона хромозома, а не дијагнозу ни прогнозу: генетичке варијанте се налазе и код особа без тегоба. Значење налаза процјењује љекар генетичар заједно са андрологом, уз личну и породичну анамнезу', 'Результат описывает вариант строения участка хромосомы, а не диагноз и не прогноз: генетические варианты встречаются и у людей без жалоб. Значение находки оценивает врач-генетик вместе с андрологом и с учётом личного и семейного анамнеза', 'Das Ergebnis beschreibt eine Variante des Chromosomenabschnitts, keine Diagnose und keine Prognose: genetische Varianten kommen auch bei Menschen ohne Beschwerden vor. Die Bedeutung beurteilt ein Facharzt für Humangenetik gemeinsam mit dem Andrologen unter Berücksichtigung der persönlichen und der Familienanamnese', 'Sonuç, kromozom bölgesinin bir varyantını tanımlar; tanı ya da kesin bir öngörü değildir, genetik varyantlar şikayeti olmayan kişilerde de bulunur. Bulgunun anlamını, kişisel ve aile öyküsüyle birlikte tıbbi genetik uzmanı ve androloji hekimi değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'brca1-brca2-genetic-test'), 'Molecular genetic test for inherited variants of the BRCA1 and BRCA2 genes, which take part in repairing cell DNA', 'Molekularno-genetičko ispitivanje nasljednih varijanti gena BRCA1 i BRCA2, koji učestvuju u popravci DNK u ćeliji', 'Молекуларно-генетичко испитивање насљедних варијанти гена BRCA1 и BRCA2, који учествују у поправци ДНК у ћелији', 'Молекулярно-генетическое исследование наследуемых вариантов генов BRCA1 и BRCA2, которые участвуют в восстановлении ДНК клетки', 'Molekulargenetische Untersuchung auf vererbte Varianten der Gene BRCA1 und BRCA2, die an der Reparatur der Zell-DNA beteiligt sind', 'Hücrede DNA onarımında görev alan BRCA1 ve BRCA2 genlerinin kalıtsal varyantlarını araştıran moleküler genetik test', 'A venous blood sample or a buccal swab is taken and the DNA is examined by sequencing in a specialised laboratory; the report takes longer than for routine tests', 'Uzima se venska krv ili bris sluznice obraza, a DNK se sekvencioniranjem ispituje u specijalizovanoj laboratoriji; nalaz se čeka duže nego kod uobičajenih analiza', 'Узима се венска крв или брис слузнице образа, а ДНК се секвенционирањем испитује у специјализованој лабораторији; налаз се чека дуже него код уобичајених анализа', 'Забор венозной крови или мазка со слизистой щеки, ДНК исследуют секвенированием в специализированной лаборатории, результат готовится дольше, чем обычные анализы', 'Entnahme von venösem Blut oder eines Wangenschleimhautabstrichs, die DNA wird in einem spezialisierten Labor sequenziert; der Befund dauert länger als bei Routineuntersuchungen', 'Toplardamardan kan veya yanak içinden sürüntü alınır, DNA özel bir laboratuvarda dizileme yöntemiyle incelenir; sonuç rutin testlerden daha uzun sürede çıkar', 'Tumours of the breast, ovary, pancreas or prostate in close relatives, a known family gene variant, testing referred by an oncologist or a clinical geneticist, planning the scope of follow-up', 'Tumori dojke, jajnika, pankreasa ili prostate kod bliskih srodnika, poznata porodična varijanta gena, ispitivanje po uputu onkologa ili ljekara genetičara, planiranje obima praćenja', 'Тумори дојке, јајника, панкреаса или простате код блиских сродника, позната породична варијанта гена, испитивање по упуту онколога или љекара генетичара, планирање обима праћења', 'Опухоли молочной железы, яичников, поджелудочной железы или простаты у близких родственников, известный семейный вариант гена, обследование по направлению онколога или врача-генетика, планирование объёма наблюдения', 'Tumoren der Brust, der Eierstöcke, der Bauchspeicheldrüse oder der Prostata bei nahen Verwandten, eine bekannte Genvariante in der Familie, Untersuchung auf Überweisung des Onkologen oder Humangenetikers, Planung des Umfangs der Nachsorge', 'Yakın akrabalarda meme, yumurtalık, pankreas veya prostat tümörü öyküsü, ailede bilinen bir gen varyantı, onkolog ya da tıbbi genetik uzmanının yönlendirmesi, izlem planının belirlenmesi', 'No special preparation; bring information about illnesses in the family, and genetic counselling is recommended both before the test and after the result', 'Posebna priprema nije potrebna; korisno je ponijeti podatke o bolestima u porodici, a genetičko savjetovanje se preporučuje i prije testa i poslije dobijanja nalaza', 'Посебна припрема није потребна; корисно је понијети податке о болестима у породици, а генетичко савјетовање се препоручује и прије теста и послије добијања налаза', 'Специальной подготовки нет; с собой полезны сведения о заболеваниях в семье, а консультация врача-генетика рекомендуется и до сдачи, и после получения результата', 'Keine besondere Vorbereitung; Angaben zu Erkrankungen in der Familie mitbringen, eine genetische Beratung vor dem Test und nach dem Befund wird empfohlen', 'Özel bir hazırlık gerekmez; ailedeki hastalıklara ilişkin bilgileri getirmek, test öncesinde ve sonuç sonrasında genetik danışmanlık almak önerilir', 'The result is a gene variant, not a diagnosis: such variants also occur in healthy people, and their absence does not replace routine follow-up. A clinical geneticist interprets the result together with the personal and family history', 'Nalaz je varijanta gena, a ne dijagnoza: takve varijante se nalaze i kod zdravih osoba, a njihovo odsustvo ne zamjenjuje redovno praćenje. Značenje nalaza procjenjuje ljekar genetičar zajedno sa ličnom i porodičnom anamnezom', 'Налаз је варијанта гена, а не дијагноза: такве варијанте се налазе и код здравих особа, а њихово одсуство не замјењује редовно праћење. Значење налаза процјењује љекар генетичар заједно са личном и породичном анамнезом', 'Результат — это вариант гена, а не диагноз: такие варианты встречаются и у здоровых людей, а их отсутствие не отменяет обычного наблюдения. Значение результата оценивает врач-генетик вместе с личным и семейным анамнезом', 'Das Ergebnis ist eine Genvariante und keine Diagnose: solche Varianten kommen auch bei Gesunden vor, und ihr Fehlen ersetzt die übliche Vorsorge nicht. Die Bedeutung beurteilt der Humangenetiker gemeinsam mit der persönlichen und der Familienanamnese', 'Sonuç bir gen varyantıdır, tanı değildir: bu varyantlar sağlıklı kişilerde de bulunur, bulunmaması ise olağan izlemin yerine geçmez. Sonucun anlamını kişisel ve aile öyküsüyle birlikte tıbbi genetik uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'breast-swab-fungi'), 'Mycological examination of nipple discharge and the surrounding skin for yeast fungi', 'Mikološko ispitivanje sekreta bradavice i okolne kože na kvasnice', 'Миколошко испитивање секрета брадавице и околне коже на кваснице', 'Микологическое исследование отделяемого соска и кожи вокруг него на дрожжевые грибы', 'Mykologische Untersuchung von Brustwarzensekret und der umgebenden Haut auf Hefepilze', 'Meme başı akıntısı ve çevresindeki deriden maya mantarlarının araştırıldığı mikolojik inceleme', 'A sterile swab is passed over the nipple and areola, the material is cultured on a fungal medium and the species is identified if growth occurs', 'Sterilnim štapićem prelazi se preko bradavice i areole, materijal se zasijava na podlogu za gljivice, a pri porastu se određuje vrsta', 'Стерилним штапићем прелази се преко брадавице и ареоле, материјал се засијава на подлогу за гљивице, а при порасту се одређује врста', 'Стерильным тампоном проводят по соску и ареоле, материал засевают на среду для грибов и при росте определяют вид', 'Mit einem sterilen Tupfer wird über Brustwarze und Warzenhof gestrichen, das Material wird auf einem Pilznährboden angezüchtet und bei Wachstum die Art bestimmt', 'Steril bir çubuk meme başı ve areola üzerinde gezdirilir, örnek mantar besiyerine ekilir, üreme olursa tür belirlenir', 'Burning and painful nipples during breastfeeding, persistent redness and flaking of the areola, itching, complaints after a course of antibiotics, symptoms that persist despite treatment', 'Žarenje i bolne bradavice tokom dojenja, uporno crvenilo i ljuštenje areole, svrab, tegobe poslije terapije antibioticima, simptomi koji traju uprkos liječenju', 'Жарење и болне брадавице током дојења, упорно црвенило и љуштење ареоле, свраб, тегобе послије терапије антибиотицима, симптоми који трају упркос лијечењу', 'Жжение и болезненность сосков при кормлении, стойкое покраснение и шелушение ареолы, зуд, жалобы после курса антибиотиков, симптомы, которые сохраняются несмотря на лечение', 'Brennende und schmerzende Brustwarzen beim Stillen, anhaltende Rötung und Schuppung des Warzenhofs, Juckreiz, Beschwerden nach einer Antibiotikatherapie, trotz Behandlung fortbestehende Symptome', 'Emzirme sırasında meme başında yanma ve ağrı, areolada geçmeyen kızarıklık ve pullanma, kaşıntı, antibiyotik kürü sonrası şikayetler, tedaviye rağmen süren belirtiler', 'Before the swab do not wash the breast with soap and do not apply creams, ointments or nipple care products; antifungal medicines are paused only in agreement with the doctor', 'Prije uzimanja uzorka dojku ne prati sapunom i ne nanositi kreme, masti ni sredstva za zaštitu bradavica; antimikotike prekinuti samo u dogovoru sa ljekarom', 'Прије узимања узорка дојку не прати сапуном и не наносити креме, масти ни средства за заштиту брадавица; антимикотике прекинути само у договору са љекаром', 'Перед забором грудь не мыть с мылом и не наносить кремы, мази и средства для защиты сосков; противогрибковые препараты отменяют только по согласованию с врачом', 'Vor der Entnahme die Brust nicht mit Seife waschen und keine Cremes, Salben oder Brustwarzenpflege auftragen; Antimykotika nur in Absprache mit dem Arzt pausieren', 'Örnek alınmadan önce meme sabunla yıkanmamalı, krem, merhem veya meme başı bakım ürünü sürülmemelidir; mantar ilaçlarına yalnızca hekimle görüşerek ara verilir', 'Growth of yeast fungi may be related to a fungal problem of the nipple skin or to their usual presence on the skin. The doctor assesses the result together with the examination and complaints, including during breastfeeding', 'Porast kvasnica može biti povezan sa gljivičnom promjenom kože bradavice ili sa njihovim uobičajenim prisustvom na koži. Nalaz procjenjuje ljekar uz pregled i tegobe, uključujući i period dojenja', 'Пораст квасница може бити повезан са гљивичном промјеном коже брадавице или са њиховим уобичајеним присуством на кожи. Налаз процјењује љекар уз преглед и тегобе, укључујући и период дојења', 'Рост дрожжевых грибов может быть связан с грибковым поражением кожи соска или с их обычным присутствием на коже. Результат оценивает врач вместе с осмотром и жалобами, в том числе в период грудного вскармливания', 'Ein Wachstum von Hefepilzen kann mit einer Pilzbesiedlung der Brustwarzenhaut oder mit ihrem üblichen Vorkommen auf der Haut zusammenhängen. Der Arzt beurteilt den Befund zusammen mit Untersuchung und Beschwerden, auch in der Stillzeit', 'Maya mantarlarının üremesi meme başı derisindeki mantar sorunuyla ya da bu mantarların deride olağan bulunuşuyla ilişkili olabilir. Sonucu, muayene ve şikayetlerle birlikte, emzirme dönemi de gözetilerek hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'campylobacter-stool-test'), 'Testing of a stool sample for Campylobacter, a bacterium that often causes acute intestinal infections', 'Ispitivanje uzorka stolice na kampilobakter, bakteriju koja često izaziva akutne crijevne infekcije', 'Испитивање узорка столице на кампилобактер, бактерију која често изазива акутне цријевне инфекције', 'Исследование образца кала на кампилобактер, бактерию, которая часто вызывает острые кишечные инфекции', 'Untersuchung einer Stuhlprobe auf Campylobacter, ein Bakterium, das häufig akute Darminfektionen verursacht', 'Akut bağırsak enfeksiyonlarının sık nedenlerinden Campylobacter bakterisi için dışkı örneğinin incelenmesi', 'The patient collects a small portion of stool in a container and the laboratory looks for the pathogen or its antigens; the method used and the turnaround time depend on the laboratory', 'Pacijent sakuplja mali uzorak stolice u posudu, a laboratorija traži uzročnika ili njegove antigene; primijenjena metoda i rok nalaza zavise od laboratorije', 'Пацијент сакупља мали узорак столице у посуду, а лабораторија тражи узрочника или његове антигене; примијењена метода и рок налаза зависе од лабораторије', 'Пациент собирает небольшую порцию кала в контейнер, лаборатория ищет возбудителя или его антигены; применяемый метод и срок готовности зависят от лаборатории', 'Der Patient sammelt eine kleine Stuhlmenge in einem Behälter, das Labor sucht nach dem Erreger oder seinen Antigenen; Methode und Bearbeitungszeit hängen vom Labor ab', 'Hasta kaba az miktarda dışkı alır, laboratuvar etkeni veya antijenlerini araştırır; kullanılan yöntem ve sonuç süresi laboratuvara göre değişir', 'Acute diarrhoea with abdominal pain and fever, complaints after travel or after undercooked poultry and raw milk, testing during an outbreak, prolonged bowel upset', 'Akutni proliv sa bolom u trbuhu i povišenom temperaturom, tegobe poslije putovanja ili nedovoljno pečenog živinskog mesa i sirovog mlijeka, ispitivanje tokom epidemije, dugotrajne promjene stolice', 'Акутни пролив са болом у трбуху и повишеном температуром, тегобе послије путовања или недовољно печеног живинског меса и сировог млијека, испитивање током епидемије, дуготрајне промјене столице', 'Острая диарея с болью в животе и температурой, жалобы после поездки или употребления недостаточно прожаренного мяса птицы и сырого молока, обследование при вспышке, затяжное расстройство стула', 'Akuter Durchfall mit Bauchschmerzen und Fieber, Beschwerden nach einer Reise oder nach nicht durchgegartem Geflügel und Rohmilch, Untersuchung bei einem Ausbruch, anhaltende Stuhlveränderungen', 'Karın ağrısı ve ateşle seyreden akut ishal, seyahat sonrası ya da az pişmiş kanatlı eti ve çiğ süt sonrası şikayetler, salgın araştırması, uzun süren dışkı düzensizliği', 'Collect the stool in a clean container without urine, if possible before starting antibiotics, and deliver it to the laboratory on the same day', 'Stolicu sakupiti u čistu posudu bez primjese urina, po mogućnosti prije početka antibiotika, i dostaviti je u laboratoriju istog dana', 'Столицу сакупити у чисту посуду без примјесе урина, по могућности прије почетка антибиотика, и доставити је у лабораторију истог дана', 'Кал собирают в чистый контейнер без примеси мочи, по возможности до начала антибиотиков, и доставляют в лабораторию в тот же день', 'Den Stuhl in einem sauberen Behälter ohne Urinbeimengung sammeln, möglichst vor Beginn einer Antibiotikatherapie, und noch am selben Tag ins Labor bringen', 'Dışkı, idrar karışmadan temiz bir kaba alınmalı, mümkünse antibiyotik başlanmadan önce toplanmalı ve aynı gün laboratuvara ulaştırılmalıdır', 'A positive result may be related to an intestinal infection caused by this bacterium, while a negative one does not rule it out if complaints persist. Further work-up and treatment are prescribed by the doctor', 'Pozitivan nalaz može biti povezan sa crijevnom infekcijom koju izaziva ova bakterija, a negativan je ne isključuje ako tegobe traju. Dalju obradu i liječenje određuje ljekar', 'Позитиван налаз може бити повезан са цријевном инфекцијом коју изазива ова бактерија, а негативан је не искључује ако тегобе трају. Даљу обраду и лијечење одређује љекар', 'Положительный результат может быть связан с кишечной инфекцией, вызванной этой бактерией, отрицательный её не исключает при сохраняющихся жалобах. Дальнейшее обследование и лечение назначает врач', 'Ein positives Ergebnis kann mit einer durch dieses Bakterium verursachten Darminfektion zusammenhängen, ein negatives schließt sie bei fortbestehenden Beschwerden nicht aus. Weitere Abklärung und Behandlung ordnet der Arzt an', 'Pozitif sonuç bu bakterinin yol açtığı bağırsak enfeksiyonuyla ilişkili olabilir, negatif sonuç şikayetler sürüyorsa bunu dışlamaz. İleri incelemeyi ve tedaviyi hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'candida-culture'), 'Culture of a sample for yeasts of the Candida genus with identification of the species', 'Kultura uzorka na kvasnice roda Candida sa određivanjem vrste', 'Култура узорка на кваснице рода Candida са одређивањем врсте', 'Посев материала на дрожжевые грибы рода Candida с определением вида', 'Anzucht einer Probe auf Hefepilze der Gattung Candida mit Bestimmung der Art', 'Örneğin Candida cinsi mayalar için kültüre alınması ve tür tayini', 'A swab or other material is placed on a fungal culture medium, the colonies are identified if growth occurs, and the report is usually ready after a few days', 'Bris ili drugi materijal zasijava se na podlogu za gljivice, pri porastu se kolonije identifikuju, a nalaz je obično gotov poslije nekoliko dana', 'Брис или други материјал засијава се на подлогу за гљивице, при порасту се колоније идентификују, а налаз је обично готов послије неколико дана', 'Мазок или другой материал засевают на питательную среду для грибов, при росте колонии идентифицируют, результат обычно готов через несколько дней', 'Ein Abstrich oder anderes Material wird auf einen Pilznährboden aufgebracht, bei Wachstum werden die Kolonien identifiziert, der Befund liegt meist nach einigen Tagen vor', 'Sürüntü veya başka bir örnek mantar besiyerine ekilir, üreme olursa koloniler tanımlanır, sonuç genellikle birkaç gün içinde çıkar', 'White coating on mucous membranes, itching and curd-like discharge, nappy rash and skin changes in folds, complaints during antibiotic therapy or with reduced immunity, follow-up as prescribed by a doctor', 'Bijele naslage na sluznicama, svrab i sirast sekret, promjene kože u pregibima i pelenski osip, tegobe tokom terapije antibioticima ili kod oslabljenog imuniteta, kontrola po savjetu ljekara', 'Бијеле наслаге на слузницама, свраб и сираст секрет, промјене коже у прегибима и пеленски осип, тегобе током терапије антибиотицима или код ослабљеног имунитета, контрола по савјету љекара', 'Белый налёт на слизистых, зуд и творожистые выделения, опрелости и изменения кожи в складках, жалобы на фоне антибиотиков или сниженного иммунитета, контроль по назначению врача', 'Weiße Beläge auf Schleimhäuten, Juckreiz und quarkartiger Ausfluss, Hautveränderungen in Falten und Windeldermatitis, Beschwerden unter Antibiotika oder bei geschwächter Abwehr, Kontrolle auf ärztliche Anordnung', 'Mukozalarda beyaz tabaka, kaşıntı ve peynirimsi akıntı, kıvrım bölgelerinde deri değişiklikleri ve bez pişiği, antibiyotik tedavisi sırasında ya da bağışıklığın zayıfladığı durumlarda şikayetler, hekimin istediği kontrol', 'Do not treat the sampling site with antiseptics and do not use antifungal creams, pessaries or tablets before the test; the exact interval is set by the doctor', 'Mjesto uzimanja ne tretirati antisepticima i prije ispitivanja ne koristiti antimikotske kreme, vagitorije ni tablete; tačan razmak određuje ljekar', 'Мјесто узимања не третирати антисептицима и прије испитивања не користити антимикотске креме, вагиторије ни таблете; тачан размак одређује љекар', 'Место забора не обрабатывать антисептиками, перед исследованием не применять противогрибковые кремы, свечи и таблетки; конкретный интервал указывает врач', 'Die Entnahmestelle nicht mit Antiseptika behandeln und vor der Untersuchung keine Antimykotika als Creme, Zäpfchen oder Tablette anwenden; den genauen Abstand legt der Arzt fest', 'Örnek alınacak bölge antiseptikle temizlenmemeli, incelemeden önce mantar kremi, vajinal fitil veya tablet kullanılmamalıdır; süreyi hekim belirler', 'Growth of Candida may reflect inflammation caused by the fungus or its usual presence on mucous membranes. The doctor assesses how relevant the finding is and whether treatment is needed', 'Porast kvasnica roda Candida može odražavati upalu koju izazivaju gljivice, ali i njihovo uobičajeno prisustvo na sluznicama. Značaj nalaza i potrebu za liječenjem procjenjuje ljekar', 'Пораст квасница рода Candida може одражавати упалу коју изазивају гљивице, али и њихово уобичајено присуство на слузницама. Значај налаза и потребу за лијечењем процјењује љекар', 'Рост Candida может отражать как воспаление, вызванное грибами, так и обычное носительство на слизистых. Значимость находки и необходимость лечения оценивает врач', 'Ein Wachstum von Candida kann eine durch Pilze verursachte Entzündung widerspiegeln, aber auch das übliche Vorkommen auf Schleimhäuten. Wie bedeutsam der Befund ist und ob eine Behandlung nötig ist, beurteilt der Arzt', 'Candida üremesi mantarın yol açtığı bir iltihabı gösterebileceği gibi, mukozalardaki olağan varlığını da yansıtabilir. Bulgunun önemini ve tedavi gerekip gerekmediğini hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cbc-with-crp'), 'Combination of a complete blood count and C-reactive protein, an acute-phase marker of inflammation, from a single draw', 'Kombinacija kompletne krvne slike i C-reaktivnog proteina, pokazatelja akutne faze upale, iz jednog vađenja', 'Комбинација комплетне крвне слике и Ц-реактивног протеина, показатеља акутне фазе упале, из једног вађења', 'Комбинация общего анализа крови и C-реактивного белка, показателя острой фазы воспаления, из одного забора', 'Kombination aus großem Blutbild und C-reaktivem Protein, einem Entzündungsmarker der Akutphase, aus einer einzigen Blutentnahme', 'Tam kan sayımı ile akut faz iltihap göstergesi C-reaktif proteinin tek kan alımında birlikte yapılması', 'One venous or capillary blood collection from which the laboratory obtains both the cell parameters and the CRP level', 'Jedno vađenje venske ili kapilarne krvi iz kojeg laboratorija dobija i ćelijske pokazatelje i vrijednost CRP', 'Једно вађење венске или капиларне крви из којег лабораторија добија и ћелијске показатеље и вриједност CRP', 'Одно взятие венозной или капиллярной крови, из которого лаборатория получает и клеточные показатели, и уровень CRP', 'Eine Entnahme von venösem oder kapillarem Blut, aus der das Labor sowohl die Zellwerte als auch den CRP-Wert bestimmt', 'Toplardamardan veya parmak ucundan tek bir kan alınır, laboratuvar bundan hem hücre değerlerini hem de CRP düzeyini çalışır', 'Fever without an obvious cause, assessment of an acute infection, the doctor''s judgement about the nature of inflammation, monitoring during treatment, examination of a child with high temperature', 'Povišena temperatura bez jasnog uzroka, procjena akutne infekcije, ljekarska ocjena karaktera upale, praćenje tokom liječenja, pregled djeteta sa visokom temperaturom', 'Повишена температура без јасног узрока, процјена акутне инфекције, љекарска оцјена карактера упале, праћење током лијечења, преглед дјетета са високом температуром', 'Лихорадка без явной причины, оценка острой инфекции, решение врача о характере воспаления, контроль на фоне лечения, обследование ребёнка с высокой температурой', 'Fieber ohne erkennbare Ursache, Einschätzung einer akuten Infektion, ärztliche Beurteilung der Art der Entzündung, Verlaufskontrolle unter Therapie, Untersuchung eines Kindes mit hohem Fieber', 'Nedeni belirsiz ateş, akut enfeksiyonun değerlendirilmesi, iltihabın niteliği konusunda hekimin karar vermesi, tedavi sırasında izlem, yüksek ateşli çocuğun incelenmesi', 'No special preparation is needed, the sample is usually taken in the morning; mention current medicines and recent vaccinations to the doctor', 'Posebna priprema nije potrebna, uzorak se najčešće uzima ujutru; ljekaru treba reći koje lijekove uzimate i da li je nedavno primljena vakcina', 'Посебна припрема није потребна, узорак се најчешће узима ујутру; љекару треба рећи које лијекове узимате и да ли је недавно примљена вакцина', 'Специальной подготовки не требуется, чаще сдают утром; о принимаемых препаратах и недавних прививках стоит сказать врачу', 'Keine besondere Vorbereitung nötig, die Entnahme erfolgt meist morgens; eingenommene Medikamente und kürzliche Impfungen sollten dem Arzt mitgeteilt werden', 'Özel hazırlık gerekmez, örnek genellikle sabah alınır; kullanılan ilaçlar ve yakın zamanda yapılan aşılar hekime bildirilmelidir', 'A combination of changes in cell parameters and the CRP level may be related to infection, inflammation, injury or recovery after them. What such a picture means in a particular case is decided by the doctor from the complaints and the examination', 'Promjene ćelijskih pokazatelja zajedno sa vrijednošću CRP mogu biti povezane sa infekcijom, upalom, povredom ili oporavkom poslije njih. Šta takva slika znači u konkretnom slučaju, procjenjuje ljekar na osnovu tegoba i pregleda', 'Промјене ћелијских показатеља заједно са вриједношћу CRP могу бити повезане са инфекцијом, упалом, повредом или опоравком послије њих. Шта таква слика значи у конкретном случају, процјењује љекар на основу тегоба и прегледа', 'Сочетание изменений клеточных показателей и уровня CRP может быть связано с инфекцией, воспалением, травмой или восстановлением после них. Что означает такая картина в конкретном случае, решает врач по жалобам и осмотру', 'Veränderungen der Zellwerte zusammen mit dem CRP-Wert können mit einer Infektion, Entzündung, Verletzung oder der Erholung danach zusammenhängen. Was dieses Bild im Einzelfall bedeutet, entscheidet der Arzt anhand von Beschwerden und Untersuchung', 'Hücre değerlerindeki değişikliklerin CRP düzeyiyle birlikteliği enfeksiyon, iltihap, yaralanma veya bunlardan sonraki iyileşme dönemiyle ilişkili olabilir. Bu tablonun ne anlama geldiğine hekim, şikayetler ve muayeneyle birlikte karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chlamydia-genital-swab'), 'Examination of a swab from the genital mucosa for Chlamydia trachomatis', 'Ispitivanje brisa sluznice genitalnog trakta na Chlamydia trachomatis', 'Испитивање бриса слузнице гениталног тракта на Chlamydia trachomatis', 'Исследование мазка со слизистой половых путей на Chlamydia trachomatis', 'Untersuchung eines Abstrichs von der Genitalschleimhaut auf Chlamydia trachomatis', 'Genital mukozadan alınan sürüntüde Chlamydia trachomatis araştırılması', 'The doctor collects material with a thin probe from the cervical canal in women or from the urethra in men; it takes a couple of minutes', 'Ljekar tankom sondom uzima materijal iz cervikalnog kanala kod žena ili iz uretre kod muškaraca, postupak traje nekoliko minuta', 'Љекар танком сондом узима материјал из цервикалног канала код жена или из уретре код мушкараца, поступак траје неколико минута', 'Врач берёт материал тонким зондом из цервикального канала у женщин или из уретры у мужчин, процедура занимает пару минут', 'Der Arzt entnimmt mit einer dünnen Sonde Material aus dem Gebärmutterhalskanal bei Frauen oder aus der Harnröhre bei Männern, das dauert wenige Minuten', 'Hekim ince bir eküvyonla kadınlarda serviks kanalından, erkeklerde üretradan örnek alır, işlem birkaç dakika sürer', 'Unusual discharge, discomfort when urinating, lower abdominal pain, examination of partners, preparation for pregnancy and work-up for infertility, routine preventive check-up', 'Neuobičajen sekret, nelagoda pri mokrenju, bol u donjem dijelu trbuha, pregled partnera, priprema za trudnoću i obrada zbog neplodnosti, redovni preventivni pregled', 'Неуобичајен секрет, нелагода при мокрењу, бол у доњем дијелу трбуха, преглед партнера, припрема за трудноћу и обрада због неплодности, редовни превентивни преглед', 'Необычные выделения, дискомфорт при мочеиспускании, боль внизу живота, обследование партнёров, подготовка к беременности и обследование при бесплодии, плановый профилактический осмотр', 'Ungewöhnlicher Ausfluss, Beschwerden beim Wasserlassen, Unterbauchschmerzen, Untersuchung von Partnern, Vorbereitung auf eine Schwangerschaft und Abklärung bei Kinderwunsch, routinemäßige Vorsorge', 'Olağandışı akıntı, idrar yaparken rahatsızlık, kasık ağrısı, eşlerin incelenmesi, gebelik hazırlığı ve kısırlık araştırması, rutin koruyucu kontrol', 'Do not urinate for two to three hours before the swab; women should come outside menstruation and avoid vaginal products and douching the day before; the interval after antibiotics is set by the doctor', 'Ne mokriti dva do tri sata prije uzimanja uzorka, žene dolaze van dana menstruacije i dan ranije ne koriste vaginalna sredstva ni ispiranje; razmak poslije antibiotika određuje ljekar', 'Не мокрити два до три сата прије узимања узорка, жене долазе ван дана менструације и дан раније не користе вагинална средства ни испирање; размак послије антибиотика одређује љекар', 'Не мочиться за два-три часа до забора, женщинам приходить вне дней менструации и накануне не использовать вагинальные средства и спринцевания; паузу после антибиотиков определяет врач', 'Zwei bis drei Stunden vor der Entnahme nicht Wasser lassen, Frauen kommen außerhalb der Menstruation und verzichten am Vortag auf Vaginalpräparate und Spülungen; den Abstand nach Antibiotika legt der Arzt fest', 'Örnek alınmadan iki üç saat önce idrara çıkılmamalı, kadınlar adet dışı günlerde gelmeli ve bir gün önce vajinal ürün ile duş kullanmamalıdır; antibiyotik sonrası beklenecek süreyi hekim belirler', 'Detection means that the bacterium was found in the sample; a negative result does not always rule out infection when complaints persist. Further steps, including examination of the partner and follow-up, are decided by the doctor', 'Nalaz uzročnika znači da je bakterija nađena u uzorku, a negativan rezultat ne isključuje uvijek infekciju ako tegobe traju. Dalje korake, uključujući pregled partnera i kontrolu, određuje ljekar', 'Налаз узрочника значи да је бактерија нађена у узорку, а негативан резултат не искључује увијек инфекцију ако тегобе трају. Даље кораке, укључујући преглед партнера и контролу, одређује љекар', 'Обнаружение возбудителя означает, что бактерия найдена в пробе; отрицательный результат не всегда исключает инфекцию при сохраняющихся жалобах. Дальнейшие шаги, включая обследование партнёра и контроль, определяет врач', 'Ein Nachweis bedeutet, dass das Bakterium in der Probe gefunden wurde; ein negatives Ergebnis schließt bei anhaltenden Beschwerden eine Infektion nicht immer aus. Über das weitere Vorgehen, auch über die Untersuchung des Partners, entscheidet der Arzt', 'Etkenin saptanması bakterinin örnekte bulunduğu anlamına gelir; negatif sonuç, şikayetler sürüyorsa enfeksiyonu her zaman dışlamaz. Eşin incelenmesi ve kontrol dahil sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'clostridium-difficile-toxin-ab'), 'Detection of toxins A and B produced by the bacterium Clostridium difficile in a stool sample', 'Dokazivanje toksina A i B koje stvara bakterija Clostridium difficile u uzorku stolice', 'Доказивање токсина А и Б које ствара бактерија Clostridium difficile у узорку столице', 'Определение токсинов A и B, которые вырабатывает бактерия Clostridium difficile, в образце стула', 'Nachweis der von dem Bakterium Clostridium difficile gebildeten Toxine A und B in einer Stuhlprobe', 'Dışkı örneğinde Clostridium difficile bakterisinin ürettiği A ve B toksinlerinin saptanması', 'A small sample of liquid or unformed stool is collected in a container and the laboratory tests it for both toxins at once', 'Mali uzorak tečne ili neoformljene stolice sakuplja se u posudu, a laboratorija ga ispituje odjednom na oba toksina', 'Мали узорак течне или неоформљене столице сакупља се у посуду, а лабораторија га испитује одједном на оба токсина', 'Небольшой образец жидкого или неоформленного стула собирают в контейнер, лаборатория исследует его тест-системой сразу на оба токсина', 'Eine kleine Menge flüssigen oder ungeformten Stuhls wird in einem Behälter gesammelt und im Labor in einem Ansatz auf beide Toxine untersucht', 'Az miktarda sulu veya şekilsiz dışkı bir kaba alınır, laboratuvarda tek işlemde her iki toksin birlikte araştırılır', 'Watery diarrhoea during a course of antibiotics or in the weeks after it, bowel upset after a hospital stay, a repeat episode after a previous one', 'Vodenasti proliv tokom terapije antibioticima ili u nedjeljama poslije nje, promjene stolice nakon boravka u bolnici, ponovljena epizoda poslije ranije preboljele', 'Воденасти пролив током терапије антибиотицима или у недјељама послије ње, промјене столице након боравка у болници, поновљена епизода послије раније пребољеле', 'Водянистая диарея во время курса антибиотиков или в ближайшие недели после него, расстройство стула после пребывания в стационаре, повторный эпизод после ранее перенесённого', 'Wässriger Durchfall während einer Antibiotikatherapie oder in den Wochen danach, Stuhlveränderungen nach einem Krankenhausaufenthalt, erneute Episode nach einer früheren', 'Antibiyotik kürü sırasında veya sonraki haftalarda ortaya çıkan sulu ishal, hastane yatışı sonrası dışkı düzensizliği, daha önce geçirilmiş bir atağın yinelemesi', 'No preparation is needed, but a fresh liquid stool sample is required: formed stool is not suitable, and the sample should reach the laboratory on the day of collection', 'Priprema nije potrebna, ali je potreban svjež uzorak tečne stolice: oformljena stolica nije pogodna, a uzorak treba da stigne u laboratoriju istog dana', 'Припрема није потребна, али је потребан свјеж узорак течне столице: оформљена столица није погодна, а узорак треба да стигне у лабораторију истог дана', 'Подготовки не требуется, но нужен свежий образец жидкого стула: оформленный кал для исследования не подходит, доставить материал лучше в день сбора', 'Eine Vorbereitung ist nicht nötig, es wird aber eine frische flüssige Stuhlprobe benötigt: geformter Stuhl eignet sich nicht, die Probe sollte am Tag der Gewinnung ins Labor gelangen', 'Hazırlık gerekmez, ancak taze ve sulu dışkı örneği gerekir: şekilli dışkı uygun değildir, örnek alındığı gün laboratuvara ulaşmalıdır', 'Detection of the toxins may be related to involvement of the large bowel by this bacterium, while carriage without complaints also occurs, so the result is read together with the symptoms. The doctor decides on the next steps', 'Nalaz toksina može biti povezan sa zahvaćenošću debelog crijeva ovom bakterijom, pri čemu postoji i nošenje bez tegoba, pa se rezultat čita zajedno sa simptomima. O daljim koracima odlučuje ljekar', 'Налаз токсина може бити повезан са захваћеношћу дебелог цријева овом бактеријом, при чему постоји и ношење без тегоба, па се резултат чита заједно са симптомима. О даљим корацима одлучује љекар', 'Выявление токсинов может быть связано с поражением толстой кишки этой бактерией, при этом встречается и носительство без жалоб, поэтому результат читают вместе с симптомами. Дальнейшие действия определяет врач', 'Der Nachweis der Toxine kann mit einer Beteiligung des Dickdarms durch dieses Bakterium zusammenhängen, es gibt aber auch eine Besiedlung ohne Beschwerden, daher wird der Befund zusammen mit den Symptomen gelesen. Über das weitere Vorgehen entscheidet der Arzt', 'Toksinlerin saptanması kalın bağırsağın bu bakteriden etkilenmesiyle ilişkili olabilir; şikayetsiz taşıyıcılık da görüldüğünden sonuç belirtilerle birlikte okunur. Sonraki adımlara hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'dermatomycosis-nmp'), 'Direct microscopy of a native preparation of nail, hair or skin material for fungal elements', 'Direktna mikroskopija nativnog preparata materijala nokta, dlake ili kože na elemente gljivica', 'Директна микроскопија нативног препарата материјала нокта, длаке или коже на елементе гљивица', 'Прямое микроскопическое исследование нативного препарата из ногтя, волоса или кожи на элементы грибов', 'Direkte Mikroskopie eines Nativpräparats aus Nagel-, Haar- oder Hautmaterial auf Pilzelemente', 'Tırnak, kıl veya deriden alınan örneğin nativ preparatta mantar elemanları için doğrudan mikroskobik incelenmesi', 'Scrapings from the lesion, a nail clipping or plucked hairs are treated with an alkaline solution and examined under the microscope, giving an answer faster than a culture', 'Sastrugani materijal sa promjene, odsječak nokta ili iščupane dlake obrađuju se alkalnim rastvorom i gledaju pod mikroskopom, pa je odgovor brži nego kod kulture', 'Састругани материјал са промјене, одсјечак нокта или ишчупане длаке обрађују се алкалним раствором и гледају под микроскопом, па је одговор бржи него код културе', 'Соскоб с очага, срез ногтя или выдернутые волосы обрабатывают щёлочью и смотрят под микроскопом, ответ получают быстрее, чем при посеве', 'Schuppen vom Herd, ein Nagelspan oder ausgezupfte Haare werden mit Lauge aufbereitet und unter dem Mikroskop betrachtet, das Ergebnis liegt schneller vor als bei einer Kultur', 'Lezyon kenarından kazınan pullar, tırnak parçası veya çekilen kıllar alkali çözeltiyle hazırlanıp mikroskopta incelenir, sonuç kültüre göre daha hızlı alınır', 'Thickened and discoloured nails, flaking patches on the skin, areas of hair loss with scaling, examination before treatment is chosen and monitoring during it', 'Zadebljali i promijenjeni nokti, ljuskave promjene na koži, područja ispadanja dlake sa ljuštenjem, ispitivanje prije odabira terapije i kontrola tokom nje', 'Задебљали и промијењени нокти, љускаве промјене на кожи, подручја испадања длаке са љуштењем, испитивање прије одабира терапије и контрола током ње', 'Утолщение и изменение цвета ногтей, шелушащиеся очаги на коже, участки выпадения волос с шелушением, обследование перед назначением лечения и контроль в его процессе', 'Verdickte und verfärbte Nägel, schuppende Herde auf der Haut, Bereiche mit Haarausfall und Schuppung, Untersuchung vor der Wahl der Behandlung und Kontrolle während der Behandlung', 'Kalınlaşmış ve rengi değişmiş tırnaklar, deride pullanan lekeler, pullanmayla birlikte saç dökülen alanlar, tedavi seçimi öncesi inceleme ve tedavi sırasında kontrol', 'For several days before sampling do not apply antifungal creams or medicated nail lacquers, do not cut or file the nails and do not wash the area right before the procedure; the exact interval is given by the dermatologist', 'Nekoliko dana prije uzimanja ne nanositi antimikotske kreme ni ljekovite lakove, nokte ne sjeći i ne turpijati, a to područje ne prati neposredno prije zahvata; tačan razmak određuje dermatolog', 'Неколико дана прије узимања не наносити антимикотске креме ни љековите лакове, нокте не сјећи и не турпијати, а то подручје не прати непосредно прије захвата; тачан размак одређује дерматолог', 'За несколько дней до забора не наносить противогрибковые кремы и лечебные лаки, ногти не подстригать и не подпиливать, участок не мыть непосредственно перед процедурой; точный интервал укажет дерматолог', 'Einige Tage vor der Entnahme keine Antimykotika-Cremes oder medizinischen Nagellacke auftragen, die Nägel nicht schneiden oder feilen und die Stelle nicht unmittelbar vorher waschen; den genauen Abstand nennt der Hautarzt', 'Örnek alınmadan birkaç gün önce mantar kremi ve tedavi edici tırnak cilası sürülmemeli, tırnaklar kesilip törpülenmemeli, bölge işlemden hemen önce yıkanmamalıdır; süreyi dermatolog belirler', 'Finding hyphae or spores may be related to a fungal infection, but microscopy does not identify the species, a culture is needed for that. The dermatologist assesses the result together with the examination', 'Nalaz hifa ili spora može biti povezan sa gljivičnom infekcijom, ali mikroskopija ne određuje vrstu gljivice, za to je potrebna kultura. Rezultat uz pregled tumači dermatolog', 'Налаз хифа или спора може бити повезан са гљивичном инфекцијом, али микроскопија не одређује врсту гљивице, за то је потребна култура. Резултат уз преглед тумачи дерматолог', 'Обнаружение нитей мицелия или спор может быть связано с грибковым поражением, но микроскопия не определяет вид гриба, для этого нужен посев. Результат вместе с осмотром оценивает дерматолог', 'Der Nachweis von Pilzfäden oder Sporen kann mit einem Pilzbefall zusammenhängen, die Mikroskopie bestimmt jedoch nicht die Pilzart, dafür ist eine Kultur nötig. Der Hautarzt beurteilt den Befund zusammen mit der Untersuchung', 'Hif veya spor görülmesi mantar enfeksiyonuyla ilişkili olabilir, ancak mikroskopi mantarın türünü belirlemez, bunun için kültür gerekir. Sonucu muayeneyle birlikte dermatolog değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'dermatophytes-culture'), 'Culture of skin, nail or hair material on a medium for dermatophytes with identification of the fungal species', 'Kultura materijala kože, noktiju ili dlake na podlozi za dermatofite sa određivanjem vrste gljivice', 'Култура материјала коже, ноктију или длаке на подлози за дерматофите са одређивањем врсте гљивице', 'Посев материала кожи, ногтей или волос на среду для дерматофитов с определением вида гриба', 'Anzucht von Haut-, Nagel- oder Haarmaterial auf einem Nährboden für Dermatophyten mit Bestimmung der Pilzart', 'Deri, tırnak veya kıl örneğinin dermatofitler için besiyerine ekilmesi ve mantar türünün belirlenmesi', 'The material is placed on a nutrient medium and incubated, so the final report comes after a few weeks', 'Materijal se zasijava na hranljivu podlogu i inkubira, pa konačan nalaz stiže poslije nekoliko nedjelja', 'Материјал се засијава на хранљиву подлогу и инкубира, па коначан налаз стиже послије неколико недјеља', 'Материал засевают на питательную среду и наблюдают рост в термостате, поэтому окончательный ответ приходит через несколько недель', 'Das Material wird auf einen Nährboden gebracht und bebrütet, der endgültige Befund liegt daher erst nach einigen Wochen vor', 'Örnek besiyerine ekilir ve etüvde bekletilir, bu nedenle kesin sonuç birkaç hafta sonra çıkar', 'Confirmation of a fungal infection after microscopy, the doctor''s choice of approach in long-standing nail changes, lesions returning after treatment, scalp lesions in children and contact with animals', 'Potvrda gljivične infekcije poslije mikroskopije, izbor pristupa kod dugotrajnih promjena noktiju, ponovna pojava promjena poslije liječenja, promjene na vlasištu kod djece i kontakt sa životinjama', 'Потврда гљивичне инфекције послије микроскопије, избор приступа код дуготрајних промјена ноктију, поновна појава промјена послије лијечења, промјене на власишту код дјеце и контакт са животињама', 'Подтверждение грибкового поражения после микроскопии, выбор тактики врачом при длительных изменениях ногтей, повторное появление очагов после лечения, очаги на волосистой части головы у детей и контакт с животными', 'Bestätigung eines Pilzbefalls nach der Mikroskopie, ärztliche Entscheidung über das Vorgehen bei lang bestehenden Nagelveränderungen, erneutes Auftreten nach der Behandlung, Herde an der Kopfhaut bei Kindern und Kontakt zu Tieren', 'Mikroskopi sonrası mantar enfeksiyonunun doğrulanması, uzun süreli tırnak değişikliklerinde yaklaşımın belirlenmesi, tedaviden sonra yinelenen lezyonlar, çocuklarda saçlı deri lezyonları ve hayvanlarla temas', 'Stop topical antifungal products for the period the doctor specifies, do not wash the lesion with antiseptic and do not treat the nails cosmetically before sampling', 'Lokalne antimikotike prekinuti na period koji odredi ljekar, promjenu ne prati antiseptikom i nokte ne obrađivati kozmetički prije uzimanja uzorka', 'Локалне антимикотике прекинути на период који одреди љекар, промјену не прати антисептиком и нокте не обрађивати козметички прије узимања узорка', 'Наружные противогрибковые средства отменить на срок, который назовёт врач, очаг не мыть антисептиком и не обрабатывать ногти косметически перед забором', 'Örtliche Antimykotika für den vom Arzt genannten Zeitraum absetzen, den Herd nicht mit Antiseptikum waschen und die Nägel vor der Entnahme nicht kosmetisch bearbeiten', 'Hekimin belirttiği süre boyunca yerel mantar ilaçlarına ara verilmeli, lezyon antiseptikle yıkanmamalı ve örnek öncesi tırnaklara kozmetik işlem yapılmamalıdır', 'Growth of a dermatophyte may be related to a fungal infection of the skin, nails or hair, while absence of growth does not rule it out, especially if antifungal products were used. The dermatologist draws the conclusion from all the findings', 'Porast dermatofita može biti povezan sa gljivičnom infekcijom kože, noktiju ili dlake, dok izostanak porasta to ne isključuje, naročito ako su korišćeni antimikotici. Zaključak donosi dermatolog na osnovu svih nalaza', 'Пораст дерматофита може бити повезан са гљивичном инфекцијом коже, ноктију или длаке, док изостанак пораста то не искључује, нарочито ако су коришћени антимикотици. Закључак доноси дерматолог на основу свих налаза', 'Рост дерматофита может быть связан с грибковым поражением кожи, ногтей или волос, а отсутствие роста его не исключает, особенно если применялись противогрибковые средства. Вывод делает дерматолог по совокупности данных', 'Das Wachstum eines Dermatophyten kann mit einem Pilzbefall von Haut, Nägeln oder Haaren zusammenhängen, fehlendes Wachstum schließt ihn nicht aus, vor allem wenn Antimykotika angewendet wurden. Die Beurteilung trifft der Hautarzt aus der Gesamtheit der Befunde', 'Dermatofit üremesi deri, tırnak veya kıl mantar enfeksiyonuyla ilişkili olabilir; üreme olmaması ise özellikle mantar ilacı kullanıldıysa bunu dışlamaz. Sonucu tüm bulgularla birlikte dermatolog yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ear-swab-bacteria'), 'Swab taken from the ear to identify bacteria and determine their sensitivity to antibiotics', 'Uzimanje brisa uha radi otkrivanja bakterija i određivanja njihove osjetljivosti na antibiotike', 'Узимање бриса уха ради откривања бактерија и одређивања њихове осјетљивости на антибиотике', 'Взятие мазка из уха для выявления бактерий и определения их чувствительности к антибиотикам', 'Abstrich aus dem Ohr zum Nachweis von Bakterien und zur Bestimmung ihrer Antibiotikaempfindlichkeit', 'Kulaktan bakterilerin saptanması ve antibiyotik duyarlılığının belirlenmesi için sürüntü alınması', 'A thin sterile swab is inserted into the external ear canal to collect discharge, and the material is cultured on media in the laboratory', 'Tanak sterilni štapić uvodi se u spoljašnji slušni kanal i uzima sekret, a materijal se u laboratoriji zasijava na podloge', 'Танак стерилни штапић уводи се у спољашњи слушни канал и узима секрет, а материјал се у лабораторији засијава на подлоге', 'Тонкий стерильный тампон вводят в наружный слуховой проход и берут отделяемое, материал в лаборатории засевают на среды', 'Ein dünner steriler Tupfer wird in den äußeren Gehörgang eingeführt und nimmt Sekret auf, das Material wird im Labor auf Nährböden angezüchtet', 'İnce steril bir çubuk dış kulak yoluna sokularak akıntı alınır, örnek laboratuvarda besiyerlerine ekilir', 'Discharge from the ear, pain and itching after swimming, inflammation in users of hearing aids and earphones, discharge with a perforated eardrum, examination of a child with recurrent ear infections', 'Sekrecija iz uha, bol i svrab poslije kupanja, upala kod korisnika slušnih aparata i slušalica, curenje kod perforacije bubne opne, pregled djeteta sa ponavljanim upalama uha', 'Секреција из уха, бол и свраб послије купања, упала код корисника слушних апарата и слушалица, цурење код перфорације бубне опне, преглед дјетета са понављаним упалама уха', 'Выделения из уха, боль и зуд после купания, воспаление у пользователей слуховых аппаратов и наушников, выделения при перфорации барабанной перепонки, обследование ребёнка с повторяющимися отитами', 'Sekretion aus dem Ohr, Schmerzen und Juckreiz nach dem Baden, Entzündungen bei Trägern von Hörgeräten und Kopfhörern, Ausfluss bei durchlöchertem Trommelfell, Untersuchung eines Kindes mit wiederkehrenden Ohrentzündungen', 'Kulak akıntısı, yüzme sonrası ağrı ve kaşıntı, işitme cihazı ve kulaklık kullananlarda iltihap, kulak zarı delik olduğunda akıntı, tekrarlayan kulak iltihabı olan çocuğun incelenmesi', 'Do not use ear drops or ointments before the swab and do not rinse or clean the ear with cotton buds; when to stop topical products is decided by the ENT doctor', 'Prije uzimanja uzorka ne koristiti kapi ni masti za uho, uho ne ispirati i ne čistiti štapićima; kada prekinuti lokalna sredstva, određuje ORL ljekar', 'Прије узимања узорка не користити капи ни масти за ухо, ухо не испирати и не чистити штапићима; када прекинути локална средства, одређује ОРЛ љекар', 'Ушные капли и мази перед забором не применять, ухо не промывать и не чистить палочками; сроки отмены местных средств уточняет оториноларинголог', 'Vor der Entnahme keine Ohrentropfen oder Salben anwenden, das Ohr nicht spülen und nicht mit Wattestäbchen reinigen; wann örtliche Mittel abgesetzt werden, legt der HNO-Arzt fest', 'Örnek alınmadan önce kulak damlası veya merhemi kullanılmamalı, kulak yıkanmamalı ve pamuklu çubukla temizlenmemelidir; yerel ilaçların ne zaman kesileceğine KBB hekimi karar verir', 'The bacteria found may be the cause of the inflammation or ordinary inhabitants of the ear canal skin. The ENT doctor assesses the meaning of the culture and the antibiogram', 'Nađene bakterije mogu biti uzročnik upale, ali i uobičajeni stanovnici kože slušnog kanala. Značenje kulture i antibiograma procjenjuje ORL ljekar', 'Нађене бактерије могу бити узрочник упале, али и уобичајени становници коже слушног канала. Значење културе и антибиограма процјењује ОРЛ љекар', 'Найденные бактерии могут быть как возбудителем воспаления, так и обычными обитателями кожи слухового прохода. Значение посева и антибиотикограммы оценивает оториноларинголог', 'Die gefundenen Bakterien können Erreger der Entzündung sein oder zur üblichen Hautflora des Gehörgangs gehören. Die Bedeutung von Kultur und Antibiogramm beurteilt der HNO-Arzt', 'Üreyen bakteriler iltihabın etkeni olabileceği gibi kulak yolu derisinin olağan florası da olabilir. Kültürün ve antibiyogramın anlamını KBB hekimi değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'eye-swab-bacteria'), 'Bacteriological examination of discharge from the conjunctiva of the eye', 'Bakteriološko ispitivanje sekreta konjunktive oka', 'Бактериолошко испитивање секрета коњунктиве ока', 'Бактериологическое исследование отделяемого конъюнктивы глаза', 'Bakteriologische Untersuchung des Sekrets der Augenbindehaut', 'Göz konjonktivasından alınan akıntının bakteriyolojik incelenmesi', 'A sterile swab is passed along the inner surface of the lower eyelid, from both eyes if needed, and the material is cultured on nutrient media', 'Sterilnim štapićem prelazi se po unutrašnjoj strani donjeg kapka, po potrebi na oba oka, a materijal se zasijava na hranljive podloge', 'Стерилним штапићем прелази се по унутрашњој страни доњег капка, по потреби на оба ока, а материјал се засијава на хранљиве подлоге', 'Стерильным тампоном проводят по внутренней поверхности нижнего века, при необходимости с обоих глаз, материал засевают на питательные среды', 'Mit einem sterilen Tupfer wird über die Innenseite des Unterlids gestrichen, bei Bedarf an beiden Augen, und das Material auf Nährböden angezüchtet', 'Steril bir çubuk alt göz kapağının iç yüzeyinde gezdirilir, gerekirse her iki gözden örnek alınır ve besiyerlerine ekilir', 'Purulent discharge and eyelids sticking together in the morning, redness and swelling, prolonged conjunctivitis, inflammation in contact lens wearers, examination before eye surgery', 'Gnojni sekret i slijepljeni kapci ujutru, crvenilo i otok, dugotrajni konjunktivitis, upala kod nosilaca kontaktnih sočiva, pregled prije operacije oka', 'Гнојни секрет и слијепљени капци ујутру, црвенило и оток, дуготрајни коњунктивитис, упала код носилаца контактних сочива, преглед прије операције ока', 'Гнойное отделяемое и слипание век по утрам, покраснение и отёк, затяжной конъюнктивит, воспаление на фоне ношения контактных линз, обследование перед операцией на глазу', 'Eitriges Sekret und morgens verklebte Lider, Rötung und Schwellung, lang anhaltende Bindehautentzündung, Entzündung bei Trägern von Kontaktlinsen, Untersuchung vor einer Augenoperation', 'İrinli akıntı ve sabahları yapışan göz kapakları, kızarıklık ve şişlik, uzun süren konjonktivit, kontakt lens kullananlarda iltihap, göz ameliyatı öncesi inceleme', 'The sample is taken before any drops are instilled and before washing the face, lenses are removed in advance and eye make-up is not used; the pause after antibacterial drops is set by the doctor', 'Uzorak se uzima prije ukapavanja kapi i prije umivanja, sočiva se vade ranije, a šminka za oči se ne koristi; pauzu poslije antibakterijskih kapi određuje ljekar', 'Узорак се узима прије укапавања капи и прије умивања, сочива се ваде раније, а шминка за очи се не користи; паузу послије антибактеријских капи одређује љекар', 'Материал берут до закапывания капель и умывания, линзы снимают заранее, косметику для глаз не используют; перерыв после антибактериальных капель определяет врач', 'Die Probe wird vor dem Eintropfen von Augentropfen und vor dem Waschen des Gesichts entnommen, Linsen werden vorher herausgenommen und Augen-Make-up nicht verwendet; die Pause nach antibakteriellen Tropfen legt der Arzt fest', 'Örnek, damla damlatılmadan ve yüz yıkanmadan önce alınır, lensler önceden çıkarılır, göz makyajı yapılmaz; antibiyotikli damla sonrası beklenecek süreyi hekim belirler', 'Growth of bacteria may be related to inflammation of the conjunctiva or reflect the ordinary flora of the eyelid skin. Whether treatment is needed and which one is decided by the ophthalmologist after the examination', 'Porast bakterija može biti povezan sa upalom konjunktive ili odražavati uobičajenu floru kože kapaka. Da li je i koje liječenje potrebno, odlučuje oftalmolog poslije pregleda', 'Пораст бактерија може бити повезан са упалом коњунктиве или одражавати уобичајену флору коже капака. Да ли је и које лијечење потребно, одлучује офталмолог послије прегледа', 'Рост бактерий может быть связан с воспалением конъюнктивы или отражать обычную флору кожи век. Нужно ли лечение и какое именно, решает офтальмолог по результатам осмотра', 'Ein Bakterienwachstum kann mit einer Entzündung der Bindehaut zusammenhängen oder die übliche Hautflora der Lider widerspiegeln. Ob und welche Behandlung nötig ist, entscheidet der Augenarzt nach der Untersuchung', 'Bakteri üremesi konjonktiva iltihabıyla ilişkili olabileceği gibi göz kapağı derisinin olağan florasını da yansıtabilir. Tedavinin gerekip gerekmediğine ve türüne göz hekimi muayeneden sonra karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'eye-swab-fungi'), 'Examination of discharge from the conjunctiva and the eyelid margin for yeasts and moulds', 'Ispitivanje sekreta konjunktive i ivice kapka na kvasnice i plijesni', 'Испитивање секрета коњунктиве и ивице капка на кваснице и плијесни', 'Исследование отделяемого конъюнктивы и края век на дрожжевые и плесневые грибы', 'Untersuchung des Sekrets der Bindehaut und des Lidrands auf Hefen und Schimmelpilze', 'Konjonktiva ve göz kapağı kenarındaki akıntının maya ve küf mantarları için incelenmesi', 'A sterile swab collects material from the inner surface of the eyelid, it is examined under the microscope and cultured on a fungal medium', 'Sterilnim štapićem uzima se materijal sa unutrašnje strane kapka, gleda se pod mikroskopom i zasijava na podlogu za gljivice', 'Стерилним штапићем узима се материјал са унутрашње стране капка, гледа се под микроскопом и засијава на подлогу за гљивице', 'Стерильным тампоном берут материал с внутренней поверхности века, его смотрят под микроскопом и засевают на среду для грибов', 'Mit einem sterilen Tupfer wird Material von der Innenseite des Lids entnommen, mikroskopiert und auf einem Pilznährboden angezüchtet', 'Steril çubukla göz kapağının iç yüzünden örnek alınır, mikroskopta incelenir ve mantar besiyerine ekilir', 'Prolonged eye inflammation that does not respond to usual treatment, complaints after an eye injury with plant material, long-term use of drops containing steroids or antibiotics, contact lens wear with poor hygiene', 'Dugotrajna upala oka koja ne reaguje na uobičajenu terapiju, tegobe poslije povrede oka biljnim materijalom, dugotrajna upotreba kapi sa kortikosteroidima ili antibioticima, nošenje kontaktnih sočiva uz lošu higijenu', 'Дуготрајна упала ока која не реагује на уобичајену терапију, тегобе послије повреде ока биљним материјалом, дуготрајна употреба капи са кортикостероидима или антибиотицима, ношење контактних сочива уз лошу хигијену', 'Длительное воспаление глаза без ответа на обычное лечение, жалобы после травмы глаза растительным материалом, длительное применение капель с гормонами или антибиотиками, ношение контактных линз с нарушением ухода', 'Lang anhaltende Augenentzündung ohne Ansprechen auf die übliche Behandlung, Beschwerden nach einer Augenverletzung durch Pflanzenmaterial, längere Anwendung von Tropfen mit Kortison oder Antibiotika, Tragen von Kontaktlinsen bei mangelnder Hygiene', 'Olağan tedaviye yanıt vermeyen uzun süreli göz iltihabı, bitkisel materyalle olan göz yaralanmasından sonraki şikayetler, kortizonlu veya antibiyotikli damlaların uzun süre kullanılması, hijyeni yetersiz kontakt lens kullanımı', 'Do not rinse the eye and do not use drops or ointments before the sample is taken, remove the lenses and bring the case with the solution if the doctor wants it examined as well', 'Prije uzimanja uzorka oko ne ispirati i ne koristiti kapi ni masti, sočiva izvaditi i ponijeti kutijicu sa rastvorom ako ljekar želi da se i ona ispita', 'Прије узимања узорка око не испирати и не користити капи ни масти, сочива извадити и понијети кутијицу са раствором ако љекар жели да се и она испита', 'Перед забором глаз не промывать, капли и мази не применять, линзы снять и принести контейнер с раствором, если врач захочет исследовать и его', 'Vor der Entnahme das Auge nicht spülen und keine Tropfen oder Salben anwenden, die Linsen herausnehmen und den Behälter mit der Lösung mitbringen, wenn der Arzt auch diese untersuchen lassen möchte', 'Örnek alınmadan önce göz yıkanmamalı, damla ve merhem kullanılmamalı, lensler çıkarılmalı ve hekim isterse solüsyonlu kutu da getirilmelidir', 'Growth of fungi may be related to a fungal inflammation of the eye surface or to fungi entering from the environment. The ophthalmologist always compares the result with the examination', 'Porast gljivica može biti povezan sa gljivičnom upalom površine oka ili sa dospijevanjem gljivica iz okoline. Nalaz uvijek poredi sa pregledom oftalmolog', 'Пораст гљивица може бити повезан са гљивичном упалом површине ока или са доспијевањем гљивица из околине. Налаз увијек пореди са прегледом офталмолог', 'Рост грибов может быть связан с грибковым воспалением поверхности глаза или с попаданием грибов из окружающей среды. Результат обязательно сопоставляет с осмотром офтальмолог', 'Ein Pilzwachstum kann mit einer Pilzentzündung der Augenoberfläche oder mit Pilzen aus der Umgebung zusammenhängen. Der Augenarzt vergleicht den Befund immer mit der Untersuchung', 'Mantar üremesi göz yüzeyinin mantar iltihabıyla ya da çevreden bulaşan mantarlarla ilişkili olabilir. Göz hekimi sonucu her zaman muayeneyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hpv-quant-21'), 'Quantitative molecular test of a sample for human papillomavirus DNA, a panel of 21 types including those classified as high oncogenic risk', 'Kvantitativno molekularno ispitivanje uzorka na DNK humanog papiloma virusa, panel od 21 tipa, uključujući tipove visokog onkogenog rizika', 'Квантитативно молекуларно испитивање узорка на ДНК хуманог папилома вируса, панел од 21 типа, укључујући типове високог онкогеног ризика', 'Количественное молекулярное исследование материала на ДНК вируса папилломы человека, панель из 21 типа, включая типы высокого онкогенного риска', 'Quantitativer molekularer Test einer Probe auf DNA humaner Papillomviren, ein Panel von 21 Typen einschließlich der Typen mit hohem onkogenem Risiko', 'Örnekte insan papilloma virüsü DNA''sının nicel olarak araştırıldığı, yüksek onkojenik riskli tipleri de içeren 21 tiplik panel', 'A swab from the cervical canal or the urethra is examined by real-time PCR, with the amount of DNA reported separately for the virus types', 'Bris cervikalnog kanala ili uretre ispituje se metodom PCR u realnom vremenu, uz odvojen prikaz količine DNK po tipovima virusa', 'Брис цервикалног канала или уретре испитује се методом ПЦР у реалном времену, уз одвојен приказ количине ДНК по типовима вируса', 'Мазок из цервикального канала или уретры исследуют методом PCR в реальном времени с раздельной оценкой количества ДНК по типам вируса', 'Ein Abstrich aus dem Gebärmutterhalskanal oder der Harnröhre wird mittels Real-time-PCR untersucht, die DNA-Menge wird für die Virustypen getrennt angegeben', 'Serviks kanalından veya üretradan alınan sürüntü gerçek zamanlı PCR ile incelenir, DNA miktarı virüs tiplerine göre ayrı ayrı bildirilir', 'Cervical screening as referred by a gynaecologist, changes in the cytology smear, follow-up after treatment of cervical changes, examination in case of genital warts', 'Skrining grlića materice po uputu ginekologa, promjene u citološkom brisu, praćenje poslije liječenja promjena na grliću, ispitivanje kod kondiloma', 'Скрининг грлића материце по упуту гинеколога, промјене у цитолошком брису, праћење послије лијечења промјена на грлићу, испитивање код кондилома', 'Скрининг шейки матки по направлению гинеколога, изменения в цитологическом мазке, наблюдение после лечения изменений шейки матки, обследование при кондиломах', 'Gebärmutterhals-Screening auf Überweisung des Frauenarztes, Veränderungen im zytologischen Abstrich, Nachkontrolle nach Behandlung von Veränderungen am Gebärmutterhals, Abklärung bei Feigwarzen', 'Kadın hastalıkları uzmanının yönlendirmesiyle rahim ağzı taraması, sitolojik yaymada değişiklikler, rahim ağzı değişikliklerinin tedavisi sonrası izlem, genital siğillerde inceleme', 'Women attend outside menstruation, avoid vaginal pessaries, creams and douching for two days and abstain from intercourse; for a urethral sample do not urinate for two to three hours', 'Žene dolaze van dana menstruacije, dva dana ne koriste vagitorije, kreme ni ispiranja i uzdržavaju se od odnosa; za uzorak iz uretre ne mokriti dva do tri sata', 'Жене долазе ван дана менструације, два дана не користе вагиторије, креме ни испирања и уздржавају се од односа; за узорак из уретре не мокрити два до три сата', 'Женщинам приходить вне дней менструации, двое суток не использовать вагинальные свечи, кремы и спринцевания и воздержаться от половых контактов; при заборе из уретры не мочиться два-три часа', 'Frauen kommen außerhalb der Menstruation, verzichten zwei Tage auf Vaginalzäpfchen, Cremes und Spülungen sowie auf Geschlechtsverkehr; vor einem Harnröhrenabstrich zwei bis drei Stunden nicht Wasser lassen', 'Kadınlar adet dışı günlerde gelmeli, iki gün vajinal fitil, krem ve duş kullanmamalı ve cinsel ilişkiden kaçınmalıdır; üretra örneği için iki üç saat idrara çıkılmamalıdır', 'Detection of DNA means the virus is present in the sample at the time of collection; many infections clear on their own and the result is not the same as a disease. The gynaecologist plans further follow-up, including cytology and colposcopy', 'Nalaz DNK znači da je virus prisutan u uzorku u trenutku uzimanja, mnoge infekcije prolaze same i nalaz nije isto što i bolest. Dalje praćenje, uključujući citologiju i kolposkopiju, planira ginekolog', 'Налаз ДНК значи да је вирус присутан у узорку у тренутку узимања, многе инфекције пролазе саме и налаз није исто што и болест. Даље праћење, укључујући цитологију и колпоскопију, планира гинеколог', 'Обнаружение ДНК означает присутствие вируса в пробе на момент забора, часть инфекций проходит самостоятельно, и результат не равен заболеванию. План дальнейшего наблюдения, включая цитологию и кольпоскопию, определяет гинеколог', 'Ein DNA-Nachweis bedeutet, dass das Virus zum Zeitpunkt der Entnahme in der Probe vorhanden ist; viele Infektionen heilen von selbst aus, der Befund ist keiner Erkrankung gleichzusetzen. Das weitere Vorgehen einschließlich Zytologie und Kolposkopie plant der Frauenarzt', 'DNA saptanması virüsün örnek alındığı sırada bulunduğunu gösterir; enfeksiyonların çoğu kendiliğinden geçer ve sonuç hastalıkla aynı anlama gelmez. Sitoloji ve kolposkopi dahil izlem planını kadın hastalıkları uzmanı yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hpv-quant-4'), 'Quantitative molecular test for four human papillomavirus types: 6, 11, 16 and 18', 'Kvantitativno molekularno ispitivanje na četiri tipa humanog papiloma virusa: 6, 11, 16 i 18', 'Квантитативно молекуларно испитивање на четири типа хуманог папилома вируса: 6, 11, 16 и 18', 'Количественное молекулярное исследование на четыре типа вируса папилломы человека: 6, 11, 16 и 18', 'Quantitativer molekularer Test auf vier Typen des humanen Papillomvirus: 6, 11, 16 und 18', 'İnsan papilloma virüsünün 6, 11, 16 ve 18 numaralı dört tipi için nicel moleküler test', 'The swab material is examined by real-time PCR and the result is reported separately for each of the four types', 'Materijal brisa ispituje se metodom PCR u realnom vremenu, a nalaz se daje odvojeno za svaki od četiri tipa', 'Материјал бриса испитује се методом ПЦР у реалном времену, а налаз се даје одвојено за сваки од четири типа', 'Материал мазка исследуют методом PCR в реальном времени, результат дают отдельно по каждому из четырёх типов', 'Das Abstrichmaterial wird mittels Real-time-PCR untersucht, der Befund wird für jeden der vier Typen getrennt angegeben', 'Sürüntü örneği gerçek zamanlı PCR ile incelenir, sonuç dört tipin her biri için ayrı verilir', 'Clarifying testing after a wide panel has detected the virus, anogenital warts, follow-up as referred by a gynaecologist or urologist, examination of a partner', 'Dopunsko ispitivanje poslije nalaza virusa širokim panelom, anogenitalni kondilomi, praćenje po uputu ginekologa ili urologa, pregled partnera', 'Допунско испитивање послије налаза вируса широким панелом, аногенитални кондиломи, праћење по упуту гинеколога или уролога, преглед партнера', 'Уточняющее обследование после выявления вируса широкой панелью, аногенитальные кондиломы, наблюдение по направлению гинеколога или уролога, обследование партнёра', 'Ergänzende Untersuchung, nachdem ein breites Panel das Virus nachgewiesen hat, anogenitale Feigwarzen, Verlaufskontrolle auf Überweisung von Frauenarzt oder Urologe, Untersuchung des Partners', 'Geniş panelde virüs saptandıktan sonra yapılan doğrulayıcı inceleme, anogenital siğiller, kadın hastalıkları veya üroloji uzmanının yönlendirmesiyle izlem, eşin incelenmesi', 'Sampling is done outside menstruation, without vaginal products or douching the day before; do not urinate for a few hours before a urethral swab', 'Uzorak se uzima van dana menstruacije, dan ranije bez vaginalnih sredstava i ispiranja; prije brisa uretre ne mokriti nekoliko sati', 'Узорак се узима ван дана менструације, дан раније без вагиналних средстава и испирања; прије бриса уретре не мокрити неколико сати', 'Забор проводят вне дней менструации, накануне без вагинальных средств и спринцеваний; перед уретральным мазком не мочиться несколько часов', 'Die Entnahme erfolgt außerhalb der Menstruation, am Vortag ohne Vaginalpräparate und Spülungen; vor einem Harnröhrenabstrich einige Stunden nicht Wasser lassen', 'Örnek adet dışı günlerde alınır, bir gün önce vajinal ürün ve duş kullanılmaz; üretra sürüntüsünden önce birkaç saat idrara çıkılmaz', 'The result shows whether these particular types are present in the sample and in what amount; the presence of the virus is not in itself a diagnosis. What to do next, including whether to repeat the test, is decided by the doctor', 'Nalaz pokazuje da li su u uzorku prisutni baš ti tipovi virusa i u kojoj količini, a prisustvo virusa samo po sebi nije dijagnoza. Šta dalje, uključujući i ponavljanje ispitivanja, odlučuje ljekar', 'Налаз показује да ли су у узорку присутни баш ти типови вируса и у којој количини, а присуство вируса само по себи није дијагноза. Шта даље, укључујући и понављање испитивања, одлучује љекар', 'Результат показывает, найдены ли в пробе именно эти типы вируса и в каком количестве; наличие вируса само по себе не является диагнозом. Что делать дальше, в том числе повторять ли исследование, решает врач', 'Der Befund zeigt, ob gerade diese Typen in der Probe vorhanden sind und in welcher Menge; der Nachweis des Virus allein ist keine Diagnose. Über das weitere Vorgehen, auch über eine Wiederholung, entscheidet der Arzt', 'Sonuç, örnekte bu tiplerin bulunup bulunmadığını ve miktarını gösterir; virüsün varlığı tek başına tanı değildir. Testin yinelenmesi dahil sonraki adımlara hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'insulin-resistance-test-3-point'), 'Glucose load test in which glucose and insulin are measured together at three points: fasting, after one hour and after two hours', 'Test opterećenja glukozom u kojem se u tri tačke istovremeno mjere glukoza i insulin: natašte, poslije jednog i poslije dva sata', 'Тест оптерећења глукозом у којем се у три тачке истовремено мјере глукоза и инсулин: наташте, послије једног и послије два сата', 'Тест с сахарной нагрузкой, при котором в трёх точках одновременно измеряют глюкозу и инсулин: натощак, через час и через два часа', 'Zuckerbelastungstest, bei dem Glukose und Insulin an drei Zeitpunkten gemeinsam gemessen werden: nüchtern, nach einer Stunde und nach zwei Stunden', 'Glukoz ve insülinin açlıkta, birinci ve ikinci saatte birlikte ölçüldüğü üç noktalı şeker yükleme testi', 'The first blood sample is taken fasting, then the patient drinks a glucose solution and stays at the clinic while blood is drawn twice more at hourly intervals', 'Prvo vađenje krvi je natašte, zatim pacijent popije rastvor glukoze i ostaje u ustanovi, a krv se vadi još dva puta u razmaku od sat vremena', 'Прво вађење крви је наташте, затим пацијент попије раствор глукозе и остаје у установи, а крв се вади још два пута у размаку од сат времена', 'Первый забор крови натощак, затем пациент выпивает раствор глюкозы и остаётся в клинике, кровь берут ещё дважды с интервалом в час', 'Die erste Blutentnahme erfolgt nüchtern, danach trinkt der Patient eine Glukoselösung und bleibt in der Praxis, während im Abstand von einer Stunde noch zweimal Blut abgenommen wird', 'İlk kan açken alınır, ardından hasta glukoz solüsyonunu içer ve klinikte kalır, birer saat arayla iki kez daha kan alınır', 'Excess weight and increased waist circumference, menstrual cycle disorders and polycystic ovary syndrome, borderline fasting glucose, assessment of tissue sensitivity to insulin as referred by a doctor', 'Prekomjerna tjelesna težina i povećan obim struka, poremećaji menstrualnog ciklusa i sindrom policističnih jajnika, granične vrijednosti glukoze natašte, procjena osjetljivosti tkiva na insulin po uputu ljekara', 'Прекомјерна тјелесна тежина и повећан обим струка, поремећаји менструалног циклуса и синдром полицистичних јајника, граничне вриједности глукозе наташте, процјена осјетљивости ткива на инсулин по упуту љекара', 'Избыточный вес и увеличение объёма талии, нарушения менструального цикла и синдром поликистозных яичников, пограничные значения глюкозы натощак, оценка чувствительности тканей к инсулину по направлению врача', 'Übergewicht und zunehmender Taillenumfang, Zyklusstörungen und polyzystisches Ovarialsyndrom, grenzwertiger Nüchternblutzucker, Beurteilung der Insulinempfindlichkeit des Gewebes auf ärztliche Überweisung', 'Fazla kilo ve artmış bel çevresi, adet düzensizlikleri ve polikistik over sendromu, sınırda açlık şekeri, hekim yönlendirmesiyle dokuların insüline duyarlılığının değerlendirilmesi', 'Fasting for 8–12 hours, only water allowed; for three days before the test do not restrict carbohydrates, during the test do not eat, smoke or exert yourself, and tell the staff immediately if you feel unwell', 'Natašte 8–12 sati, dozvoljena je samo voda; tri dana prije testa ne ograničavati unos ugljenih hidrata, tokom testa ne jesti, ne pušiti i ne naprezati se, a kod lošeg osjećaja odmah obavijestiti osoblje', 'Наташте 8–12 сати, дозвољена је само вода; три дана прије теста не ограничавати унос угљених хидрата, током теста не јести, не пушити и не напрезати се, а код лошег осјећаја одмах обавијестити особље', 'Натощак 8–12 часов, разрешена только вода; за три дня до теста не ограничивать углеводы, во время теста не есть, не курить и не нагружаться физически, при плохом самочувствии сразу сказать персоналу', 'Nüchtern seit 8–12 Stunden, nur Wasser erlaubt; drei Tage vor dem Test die Kohlenhydrate nicht einschränken, während des Tests nicht essen, nicht rauchen und sich nicht körperlich belasten, bei Unwohlsein sofort das Personal informieren', '8–12 saat açlık, yalnızca su içilebilir; testten önceki üç gün karbonhidrat kısıtlanmamalı, test sırasında yemek yenmemeli, sigara içilmemeli ve fiziksel zorlanmadan kaçınılmalı, rahatsızlık hissedilirse hemen personele bildirilmelidir', 'The relation between glucose and insulin at the three points may be related to reduced tissue sensitivity to insulin, and also to the previous days'' diet, body weight, a recent illness or medication. The doctor draws the conclusion from the whole curve', 'Odnos glukoze i insulina u tri tačke može biti povezan sa smanjenom osjetljivošću tkiva na insulin, ali i sa ishranom prethodnih dana, tjelesnom težinom, skorašnjom bolešću ili lijekovima. Zaključak na osnovu cijele krive donosi ljekar', 'Однос глукозе и инсулина у три тачке може бити повезан са смањеном осјетљивошћу ткива на инсулин, али и са исхраном претходних дана, тјелесном тежином, скорашњом болешћу или лијековима. Закључак на основу цијеле криве доноси љекар', 'Соотношение глюкозы и инсулина в трёх точках может быть связано со сниженной чувствительностью тканей к инсулину, а также с питанием накануне, весом, недавней болезнью или приёмом лекарств. Заключение по всей кривой делает врач', 'Das Verhältnis von Glukose und Insulin an den drei Zeitpunkten kann mit einer verminderten Insulinempfindlichkeit des Gewebes zusammenhängen, aber auch mit der Ernährung der Vortage, dem Körpergewicht, einer kürzlichen Erkrankung oder Medikamenten. Die Beurteilung des gesamten Verlaufs trifft der Arzt', 'Üç noktadaki glukoz ve insülin ilişkisi dokuların insüline duyarlılığının azalmasıyla olduğu kadar önceki günlerdeki beslenme, vücut ağırlığı, yakın zamanda geçirilen hastalık veya ilaçlarla da ilişkili olabilir. Eğrinin tamamına göre sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'insulin-resistance-test-5-point'), 'Measurement of insulin and glucose while fasting and at four more points after drinking a glucose solution', 'Mjerenje insulina i glukoze natašte i još u četiri tačke poslije ispijanja rastvora glukoze', 'Мјерење инсулина и глукозе наташте и још у четири тачке послије испијања раствора глукозе', 'Измерение инсулина и глюкозы натощак и ещё в четырёх точках после приёма раствора глюкозы', 'Bestimmung von Insulin und Glukose nüchtern und an vier weiteren Zeitpunkten nach Einnahme einer Glukoselösung', 'Açlıkta ve glukoz solüsyonu içildikten sonraki dört ayrı zamanda insülin ile glukozun ölçülmesi', 'The first blood sample is taken fasting, then the patient drinks the glucose solution prepared by the laboratory and stays at the clinic for about two hours, during which blood is drawn four more times', 'Prvo vađenje krvi je natašte, zatim pacijent popije rastvor glukoze koji priprema laboratorija i ostaje u ustanovi oko dva sata, tokom kojih se krv vadi još četiri puta', 'Прво вађење крви је наташте, затим пацијент попије раствор глукозе који припрема лабораторија и остаје у установи око два сата, током којих се крв вади још четири пута', 'Первый забор крови делают натощак, затем пациент выпивает подготовленный лабораторией раствор глюкозы и остаётся в клинике около двух часов, за это время кровь берут ещё четыре раза', 'Die erste Blutentnahme erfolgt nüchtern, danach trinkt die Patientin oder der Patient die vom Labor vorbereitete Glukoselösung und bleibt etwa zwei Stunden in der Einrichtung, in denen noch vier weitere Entnahmen erfolgen', 'İlk kan açlıkta alınır, ardından hasta laboratuvarın hazırladığı glukoz solüsyonunu içer ve yaklaşık iki saat klinikte kalır, bu sürede dört kez daha kan alınır', 'Excess weight, polycystic ovary syndrome, menstrual cycle disorders, weakness and drowsiness after meals, work-up referred by an endocrinologist', 'Prekomjerna tjelesna težina, sindrom policističnih jajnika, poremećaji menstrualnog ciklusa, slabost i pospanost poslije obroka, obrada po uputu endokrinologa', 'Прекомјерна тјелесна тежина, синдром полицистичних јајника, поремећаји менструалног циклуса, слабост и поспаност послије оброка, обрада по упуту ендокринолога', 'Избыточный вес, синдром поликистозных яичников, нарушения менструального цикла, слабость и сонливость после еды, обследование по направлению эндокринолога', 'Übergewicht, polyzystisches Ovarialsyndrom, Zyklusstörungen, Schwäche und Müdigkeit nach dem Essen, Abklärung auf Überweisung des Endokrinologen', 'Fazla kilo, polikistik over sendromu, adet düzensizlikleri, yemek sonrası halsizlik ve uykululuk, endokrinoloji yönlendirmesiyle yapılan inceleme', 'Fasting for 8–12 hours, only water allowed; eat as usual for three days beforehand without cutting carbohydrates, do not smoke or exercise on the day of the test, and stay at the clinic until the last sample', 'Natašte 8–12 sati, dozvoljena je samo voda; tri dana ranije jesti uobičajeno, bez ograničavanja ugljenih hidrata, na dan testa ne pušiti i ne vježbati, ostati u ustanovi do posljednjeg vađenja', 'Наташте 8–12 сати, дозвољена је само вода; три дана раније јести уобичајено, без ограничавања угљених хидрата, на дан теста не пушити и не вјежбати, остати у установи до посљедњег вађења', 'Натощак 8–12 часов, разрешена только вода; три дня до теста питаться привычно, без ограничения углеводов, в день теста не курить и не заниматься спортом, оставаться в клинике до последнего забора', '8–12 Stunden nüchtern, nur Wasser erlaubt; drei Tage zuvor gewohnt essen ohne Kohlenhydrate einzuschränken, am Testtag nicht rauchen und keinen Sport treiben, bis zur letzten Entnahme in der Einrichtung bleiben', '8–12 saat açlık, sadece su içilebilir; testten önceki üç gün karbonhidratı kısıtlamadan her zamanki gibi beslenmeli, test günü sigara içilmemeli ve spor yapılmamalı, son kan alımına kadar klinikte kalınmalıdır', 'The relation between insulin and glucose across the time points may be linked to reduced tissue sensitivity to insulin, hormonal features or temporary factors such as recent illness, stress or medications. The whole result is assessed by an endocrinologist', 'Odnos insulina i glukoze po tačkama može biti povezan sa smanjenom osjetljivošću tkiva na insulin, hormonskim osobenostima ili privremenim faktorima, skorašnjom bolešću, stresom, uzimanjem lijekova. Cio nalaz procjenjuje endokrinolog', 'Однос инсулина и глукозе по тачкама може бити повезан са смањеном осјетљивошћу ткива на инсулин, хормонским особеностима или привременим факторима, скорашњом болешћу, стресом, узимањем лијекова. Цио налаз процјењује ендокринолог', 'Соотношение инсулина и глюкозы по точкам может быть связано со сниженной чувствительностью тканей к инсулину, гормональными особенностями или временными факторами — недавней болезнью, стрессом, приёмом препаратов. Результат целиком оценивает эндокринолог', 'Das Verhältnis von Insulin und Glukose über die Zeitpunkte kann mit einer verminderten Insulinempfindlichkeit des Gewebes, hormonellen Besonderheiten oder vorübergehenden Faktoren wie kürzlicher Erkrankung, Stress oder Medikamenten zusammenhängen. Den gesamten Befund beurteilt der Endokrinologe', 'Zaman noktaları boyunca insülin ve glukoz ilişkisi, dokuların insüline duyarlılığının azalmasıyla, hormonal özelliklerle veya yakın zamandaki hastalık, stres, ilaç kullanımı gibi geçici etkenlerle ilişkili olabilir. Sonucun tamamını endokrinoloji uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'kindergarten-microbiology-2'), 'Set of microbiological samples for a kindergarten certificate: a throat swab and a perianal imprint', 'Set mikrobioloških uzoraka za potvrdu za vrtić: bris grla i perianalni otisak', 'Сет микробиолошких узорака за потврду за вртић: брис грла и перианални отисак', 'Набор микробиологических проб для справки в детский сад: мазок из горла и перианальный отпечаток', 'Satz mikrobiologischer Proben für die Kindergartenbescheinigung: Rachenabstrich und perianaler Abklatsch', 'Anaokulu belgesi için mikrobiyolojik örnek seti: boğaz sürüntüsü ve perianal örnek', 'Material is taken from the tonsils with a sterile swab, the perianal imprint is collected with adhesive tape or a swab, and the whole procedure takes a few minutes', 'Sterilnim štapićem uzima se materijal sa krajnika, perianalni otisak se uzima ljepljivom trakom ili štapićem, a cijelo uzorkovanje traje nekoliko minuta', 'Стерилним штапићем узима се материјал са крајника, перианални отисак се узима љепљивом траком или штапићем, а цијело узорковање траје неколико минута', 'Стерильным тампоном берут материал с миндалин, перианальный отпечаток снимают липкой лентой или тампоном, весь забор занимает несколько минут', 'Mit einem sterilen Tupfer wird Material von den Mandeln entnommen, der perianale Abklatsch erfolgt mit Klebestreifen oder Tupfer, die gesamte Entnahme dauert wenige Minuten', 'Steril çubukla bademciklerden örnek alınır, perianal örnek yapışkan bantla veya çubukla toplanır, işlemin tamamı birkaç dakika sürer', 'Enrolment of a child in a nursery or kindergarten, return to a group after a long illness, request of the sanitary service', 'Upis djeteta u jaslice ili vrtić, povratak u kolektiv poslije duže bolesti, zahtjev sanitarne službe', 'Упис дјетета у јаслице или вртић, повратак у колектив послије дуже болести, захтјев санитарне службе', 'Оформление ребёнка в ясли или детский сад, возвращение в коллектив после длительной болезни, требование санитарной службы', 'Aufnahme des Kindes in Krippe oder Kindergarten, Rückkehr in die Gruppe nach längerer Krankheit, Anforderung des Gesundheitsamts', 'Çocuğun kreşe veya anaokuluna kaydı, uzun bir hastalıktan sonra gruba dönüş, sağlık biriminin talebi', 'Come in the morning before eating, before brushing teeth, without gargling or throat sprays; the perianal sample is taken before washing and before a bowel movement, and antibiotics or antiparasitic medicines only in agreement with the paediatrician', 'Doći ujutru natašte, prije pranja zuba, bez ispiranja grla i sprejeva; perianalni uzorak se uzima prije pranja i prije stolice, a antibiotici i antiparazitni lijekovi samo u dogovoru sa pedijatrom', 'Доћи ујутру наташте, прије прања зуба, без испирања грла и спрејева; перианални узорак се узима прије прања и прије столице, а антибиотици и антипаразитни лијекови само у договору са педијатром', 'Приходить утром натощак, до чистки зубов, без полоскания горла и спреев; перианальный материал берут до подмывания и до стула, антибиотики и противопаразитарные препараты — только по согласованию с педиатром', 'Morgens nüchtern kommen, vor dem Zähneputzen, ohne Gurgeln und Rachensprays; die perianale Probe wird vor dem Waschen und vor dem Stuhlgang entnommen, Antibiotika und Antiparasitika nur in Absprache mit dem Kinderarzt', 'Sabah aç karnına, diş fırçalamadan, boğaz gargarası ve sprey kullanmadan gelinmelidir; perianal örnek yıkanmadan ve dışkılamadan önce alınır, antibiyotik ve antiparaziter ilaçlar yalnızca çocuk hekimiyle görüşülerek kullanılır', 'Finding bacteria or parasite eggs may mean either an infection or symptom-free carriage. Whether treatment and a repeat sample are needed before admission is decided by the paediatrician', 'Nalaz bakterija ili jaja parazita može značiti infekciju, ali i kliconoštvo bez tegoba. Da li su potrebni liječenje i ponovljeni uzorak prije upisa, odlučuje pedijatar', 'Налаз бактерија или јаја паразита може значити инфекцију, али и клицоноштво без тегоба. Да ли су потребни лијечење и поновљени узорак прије уписа, одлучује педијатар', 'Находка бактерий или яиц паразитов может означать как инфекцию, так и носительство без жалоб. Нужны ли лечение и повторная проба перед приёмом в сад, решает педиатр', 'Der Nachweis von Bakterien oder Parasiteneiern kann eine Infektion bedeuten, aber auch eine beschwerdefreie Trägerschaft. Ob Behandlung und eine wiederholte Probe vor der Aufnahme nötig sind, entscheidet der Kinderarzt', 'Bakteri veya parazit yumurtası bulunması hem enfeksiyonu hem de şikayetsiz taşıyıcılığı gösterebilir. Kayıttan önce tedavi ve tekrar örnek gerekip gerekmediğine çocuk hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'kindergarten-microbiology-3'), 'Extended set of samples for a kindergarten certificate: throat and nose swabs plus a perianal imprint', 'Prošireni set uzoraka za potvrdu za vrtić: brisevi grla i nosa uz perianalni otisak', 'Проширени сет узорака за потврду за вртић: брисеви грла и носа уз перианални отисак', 'Расширенный набор проб для справки в детский сад: мазки из горла и носа плюс перианальный отпечаток', 'Erweiterter Probensatz für die Kindergartenbescheinigung: Rachen- und Nasenabstrich sowie perianaler Abklatsch', 'Anaokulu belgesi için genişletilmiş örnek seti: boğaz ve burun sürüntüleri ile perianal örnek', 'One swab is passed over the tonsils, a separate one over the mucosa of both nostrils, then material is taken from the skin around the anus', 'Jednim štapićem se prelazi preko krajnika, drugim preko sluznice obje nozdrve, a zatim se uzima materijal sa kože oko čmara', 'Једним штапићем се прелази преко крајника, другим преко слузнице обје ноздрве, а затим се узима материјал са коже око чмара', 'Одним тампоном проводят по миндалинам, отдельным — по слизистой обеих ноздрей, затем берут материал с кожи вокруг заднего прохода', 'Ein Tupfer wird über die Mandeln geführt, ein weiterer über die Schleimhaut beider Nasenlöcher, danach wird Material von der Haut um den After entnommen', 'Bir çubuk bademciklerden, ayrı bir çubuk her iki burun deliğinin mukozasından geçirilir, ardından anüs çevresindeki deriden örnek alınır', 'Admission to kindergarten when the institution also requires a check for nasal staphylococcus carriage, screening of children and staff during an outbreak in the group', 'Prijem u vrtić kada ustanova traži i provjeru kliconoštva stafilokoka u nosu, ispitivanje djece i osoblja pri pojavi oboljenja u grupi', 'Пријем у вртић када установа тражи и провјеру клицоноштва стафилокока у носу, испитивање дјеце и особља при појави обољења у групи', 'Приём в детский сад, когда учреждение требует ещё и проверку носительства стафилококка в носу, обследование персонала и детей при вспышке в группе', 'Aufnahme in den Kindergarten, wenn zusätzlich eine Untersuchung auf Staphylokokken-Trägerschaft in der Nase verlangt wird, Untersuchung von Kindern und Personal bei Krankheitsfällen in der Gruppe', 'Kurumun burunda stafilokok taşıyıcılığının da araştırılmasını istediği anaokulu kayıtları, grupta hastalık görüldüğünde çocukların ve personelin taranması', 'In the morning before eating, before brushing teeth and without gargling; no nasal drops or ointments the day before, and the perianal sample is taken before washing', 'Ujutru natašte, prije pranja zuba i bez ispiranja grla; dan ranije ne ukapavati kapi u nos i ne koristiti masti, a perianalni uzorak se uzima prije pranja', 'Ујутру наташте, прије прања зуба и без испирања грла; дан раније не укапавати капи у нос и не користити масти, а перианални узорак се узима прије прања', 'Утром натощак, до чистки зубов и без полоскания горла; накануне не капать в нос капли и не использовать мази, материал вокруг заднего прохода берут до подмывания', 'Morgens nüchtern, vor dem Zähneputzen und ohne Gurgeln; am Vortag keine Nasentropfen oder Salben, die perianale Probe wird vor dem Waschen entnommen', 'Sabah aç karnına, diş fırçalamadan ve gargara yapmadan gelinmelidir; bir gün önce buruna damla ve merhem uygulanmamalı, perianal örnek yıkanmadan önce alınmalıdır', 'Growth of microorganisms in any of the three sites may reflect an infection or symptom-free carriage, and a clean result at one site does not cancel findings at the others. The certificate is issued by a doctor', 'Porast mikroorganizama u bilo kojoj od tri zone može značiti infekciju ili kliconoštvo bez tegoba, a uredan nalaz jedne zone ne poništava nalaze iz ostalih. Potvrdu izdaje ljekar', 'Пораст микроорганизама у било којој од три зоне може значити инфекцију или клицоноштво без тегоба, а уредан налаз једне зоне не поништава налазе из осталих. Потврду издаје љекар', 'Рост микроорганизмов в любой из трёх зон может отражать инфекцию или носительство без жалоб, а чистый результат одной зоны не отменяет находок в других. Заключение для справки оформляет врач', 'Ein Keimnachweis in einem der drei Bereiche kann für eine Infektion oder für eine beschwerdefreie Trägerschaft sprechen, ein unauffälliger Bereich hebt Befunde der anderen nicht auf. Die Bescheinigung stellt der Arzt aus', 'Üç bölgeden herhangi birinde mikroorganizma üremesi enfeksiyonu veya şikayetsiz taşıyıcılığı gösterebilir, bir bölgenin temiz çıkması diğerlerindeki bulguları geçersiz kılmaz. Belgeyi hekim düzenler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mycoplasma-ureaplasma-genital-swab'), 'Examination of a single genital swab for two microorganisms at once, Mycoplasma and Ureaplasma', 'Ispitivanje jednog genitalnog brisa odjednom na dva mikroorganizma, Mycoplasma i Ureaplasma', 'Испитивање једног гениталног бриса одједном на два микроорганизма, Мyцопласма и Уреапласма', 'Исследование одного генитального мазка сразу на два микроорганизма — Mycoplasma и Ureaplasma', 'Untersuchung eines einzigen Genitalabstrichs auf zwei Erreger gleichzeitig, Mycoplasma und Ureaplasma', 'Tek bir genital sürüntüde aynı anda iki mikroorganizmanın, Mycoplasma ve Ureaplasma''nın araştırılması', 'A swab is taken from the urethra in men or from the vagina and cervical canal in women, collection takes a couple of minutes, and the material is then processed in the laboratory', 'Štapićem se uzima materijal iz uretre kod muškaraca ili iz vagine i cervikalnog kanala kod žena, uzimanje traje par minuta, a materijal se zatim obrađuje u laboratoriji', 'Штапићем се узима материјал из уретре код мушкараца или из вагине и цервикалног канала код жена, узимање траје пар минута, а материјал се затим обрађује у лабораторији', 'Тампоном берут материал из уретры у мужчин либо из влагалища и цервикального канала у женщин, забор занимает пару минут, дальше материал исследуют в лаборатории', 'Mit einem Tupfer wird Material aus der Harnröhre beim Mann oder aus Scheide und Gebärmutterhalskanal bei der Frau entnommen, die Entnahme dauert wenige Minuten, danach folgt die Aufarbeitung im Labor', 'Erkeklerde üretradan, kadınlarda vajina ve servikal kanaldan çubukla örnek alınır, alım birkaç dakika sürer, ardından örnek laboratuvarda incelenir', 'Discharge, discomfort when urinating, pregnancy planning, work-up of a couple for infertility, examination of a partner, follow-up after treatment', 'Sekret, nelagoda pri mokrenju, planiranje trudnoće, obrada para zbog neplodnosti, pregled partnera, kontrola poslije terapije', 'Секрет, нелагода при мокрењу, планирање трудноће, обрада пара због неплодности, преглед партнера, контрола послије терапије', 'Выделения, дискомфорт при мочеиспускании, планирование беременности, обследование пары при бесплодии, обследование партнёра, контроль после лечения', 'Ausfluss, Beschwerden beim Wasserlassen, Kinderwunschplanung, Abklärung eines Paares bei unerfülltem Kinderwunsch, Untersuchung des Partners, Kontrolle nach der Behandlung', 'Akıntı, idrar yaparken rahatsızlık, gebelik planlaması, çiftin kısırlık nedeniyle incelenmesi, partner taraması, tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the swab, women outside menstruation and without vaginal products or douching the day before; the interval after antibacterial medicines is set by the doctor', 'Ne mokriti 2–3 sata prije uzimanja brisa, žene van dana menstruacije i bez vaginalnih preparata i ispiranja dan ranije; rok poslije antibakterijskih lijekova određuje ljekar', 'Не мокрити 2–3 сата прије узимања бриса, жене ван дана менструације и без вагиналних препарата и испирања дан раније; рок послије антибактеријских лијекова одређује љекар', 'Не мочиться 2–3 часа перед взятием мазка, женщинам — вне дней менструации и без вагинальных препаратов и спринцеваний накануне; сроки после антибактериальных препаратов уточняет врач', '2–3 Stunden vor der Entnahme nicht Wasser lassen, Frauen außerhalb der Menstruation und am Vortag ohne Vaginalpräparate und Spülungen; den Abstand zu antibakteriellen Medikamenten legt der Arzt fest', 'Sürüntüden 2–3 saat önce idrara çıkılmamalı, kadınlarda adet dışı günlerde ve bir gün önce vajinal ilaç ve duş uygulanmadan alınmalıdır; antibakteriyel ilaçlardan sonraki bekleme süresini hekim belirler', 'Detection of these microorganisms means they are present in the sample, and they also occur in people without complaints. Whether treatment and partner examination are needed is decided by the doctor based on symptoms and other tests', 'Nalaz ovih mikroorganizama znači da su prisutni u uzorku, a sreću se i kod osoba bez tegoba. Da li su potrebni liječenje i pregled partnera, ljekar odlučuje prema simptomima i ostalim nalazima', 'Налаз ових микроорганизама значи да су присутни у узорку, а срећу се и код особа без тегоба. Да ли су потребни лијечење и преглед партнера, љекар одлучује према симптомима и осталим налазима', 'Выявление этих микроорганизмов означает их присутствие в пробе, они встречаются и у людей без жалоб. Нужно ли лечение и обследование партнёра, врач решает по симптомам и остальным анализам', 'Ein Nachweis dieser Erreger bedeutet, dass sie in der Probe vorhanden sind, sie kommen auch bei Personen ohne Beschwerden vor. Ob Behandlung und Partneruntersuchung nötig sind, entscheidet der Arzt anhand der Beschwerden und der übrigen Befunde', 'Bu mikroorganizmaların saptanması örnekte bulunduklarını gösterir, şikayeti olmayan kişilerde de görülebilirler. Tedavi ve partner incelemesi gerekip gerekmediğine hekim, belirtilere ve diğer tetkiklere bakarak karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'neisseria-gonorrhoeae-culture'), 'Bacteriological culture of the sample for Neisseria gonorrhoeae with antibiotic susceptibility testing', 'Bakteriološka kultura uzorka na Neisseria gonorrhoeae sa antibiogramom', 'Бактериолошка култура узорка на Neisseria gonorrhoeae са антибиограмом', 'Бактериологический посев материала на Neisseria gonorrhoeae с подбором антибиотика', 'Bakteriologische Kultur der Probe auf Neisseria gonorrhoeae mit Antibiogramm', 'Örneğin Neisseria gonorrhoeae için antibiyogramlı bakteriyolojik kültürü', 'A swab from the urethra, cervical canal, throat or rectum is plated on selective media, and if growth occurs susceptibility to antibiotics is determined, which takes several days', 'Bris uretre, cervikalnog kanala, ždrijela ili rektuma zasijava se na selektivne podloge, a kod porasta se radi antibiogram, za šta je potrebno nekoliko dana', 'Брис уретре, цервикалног канала, ждријела или ректума засијава се на селективне подлоге, а код пораста се ради антибиограм, за шта је потребно неколико дана', 'Мазок из уретры, цервикального канала, глотки или прямой кишки засевают на селективные среды, при росте определяют чувствительность к антибиотикам, на это уходит несколько дней', 'Ein Abstrich aus Harnröhre, Gebärmutterhalskanal, Rachen oder Enddarm wird auf Selektivnährböden ausgestrichen, bei Wachstum folgt die Empfindlichkeitsprüfung, was einige Tage dauert', 'Üretra, servikal kanal, boğaz veya rektumdan alınan sürüntü seçici besiyerlerine ekilir, üreme olursa antibiyotik duyarlılığı belirlenir, bu birkaç gün sürer', 'Discharge and burning when urinating, clarification of a molecular test result, choice of medicine by the doctor, follow-up after treatment, examination of a partner', 'Sekret i peckanje pri mokrenju, provjera nalaza molekularnog testa, izbor lijeka od strane ljekara, kontrola poslije terapije, pregled partnera', 'Секрет и пецкање при мокрењу, провјера налаза молекуларног теста, избор лијека од стране љекара, контрола послије терапије, преглед партнера', 'Выделения и жжение при мочеиспускании, уточнение результата молекулярного теста, подбор препарата врачом, контроль после лечения, обследование партнёра', 'Ausfluss und Brennen beim Wasserlassen, Absicherung eines molekularen Testergebnisses, Auswahl des Medikaments durch den Arzt, Kontrolle nach der Behandlung, Untersuchung des Partners', 'Akıntı ve idrar yaparken yanma, moleküler test sonucunun doğrulanması, hekimin ilaç seçimi, tedavi sonrası kontrol, partner taraması', 'Do not urinate for 2–3 hours before the swab, women outside menstruation; antibacterial medicines before the culture only in agreement with the doctor, otherwise the bacterium may not grow', 'Ne mokriti 2–3 sata prije uzimanja brisa, žene van dana menstruacije; antibakterijske lijekove prije kulture uzimati samo u dogovoru sa ljekarom, jer bakterija inače možda neće porasti u kulturi', 'Не мокрити 2–3 сата прије узимања бриса, жене ван дана менструације; антибактеријске лијекове прије културе узимати само у договору са љекаром, јер бактерија иначе можда неће порасти у култури', 'Не мочиться 2–3 часа перед взятием мазка, женщинам — вне дней менструации; антибактериальные препараты до посева принимать только по согласованию с врачом, иначе бактерия может не вырасти', '2–3 Stunden vor der Entnahme nicht Wasser lassen, Frauen außerhalb der Menstruation; antibakterielle Medikamente vor der Kultur nur nach Absprache mit dem Arzt, sonst wächst der Erreger möglicherweise nicht an', 'Sürüntüden 2–3 saat önce idrara çıkılmamalı, kadınlarda adet dışı günlerde alınmalıdır; kültür öncesi antibakteriyel ilaçlar yalnızca hekimle görüşülerek kullanılmalıdır, aksi halde bakteri üremeyebilir', 'Growth means the bacterium is present in the sample, while no growth does not always rule out infection, since the organism is sensitive to transport conditions. Further steps and partner examination are decided by the doctor', 'Porast znači da je bakterija prisutna u uzorku, dok izostanak porasta ne isključuje uvijek infekciju, jer je uzročnik osjetljiv na uslove transporta materijala. Dalji postupak i pregled partnera određuje ljekar', 'Пораст значи да је бактерија присутна у узорку, док изостанак пораста не искључује увијек инфекцију, јер је узрочник осјетљив на услове транспорта материјала. Даљи поступак и преглед партнера одређује љекар', 'Рост бактерии означает её присутствие в пробе, а отсутствие роста инфекцию не всегда исключает: возбудитель чувствителен к условиям транспортировки материала. Дальнейшую тактику и обследование партнёра определяет врач', 'Wachstum bedeutet, dass der Erreger in der Probe vorhanden ist, ausbleibendes Wachstum schließt eine Infektion nicht immer aus, da der Erreger empfindlich auf die Transportbedingungen reagiert. Das weitere Vorgehen und die Partneruntersuchung legt der Arzt fest', 'Üreme, bakterinin örnekte bulunduğunu gösterir; üreme olmaması ise enfeksiyonu her zaman dışlamaz, çünkü etken taşıma koşullarına duyarlıdır. Sonraki adımları ve partner incelemesini hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'neisseria-gonorrhoeae-rapid-test'), 'Quick examination of a swab for Neisseria gonorrhoeae: microscopy of a stained preparation plus a rapid test', 'Brzo ispitivanje brisa na Neisseria gonorrhoeae: mikroskopija obojenog preparata uz brzi test', 'Брзо испитивање бриса на Neisseria gonorrhoeae: микроскопија обојеног препарата уз брзи тест', 'Быстрое исследование мазка на Neisseria gonorrhoeae: микроскопия окрашенного препарата и экспресс-тест', 'Schnelle Untersuchung eines Abstrichs auf Neisseria gonorrhoeae: Mikroskopie eines gefärbten Präparats und Schnelltest', 'Sürüntüde Neisseria gonorrhoeae için hızlı inceleme: boyalı preparatın mikroskopisi ve hızlı test', 'Discharge from the urethra or cervical canal is collected with a swab, part of the material is examined under the microscope and part is used for the rapid test, with an answer usually the same day', 'Štapićem se uzima sekret uretre ili cervikalnog kanala, dio materijala se pregleda pod mikroskopom, a dio se koristi za brzi test, pa je nalaz obično gotov istog dana', 'Штапићем се узима секрет уретре или цервикалног канала, дио материјала се прегледа под микроскопом, а дио се користи за брзи тест, па је налаз обично готов истог дана', 'Тампоном берут отделяемое уретры или цервикального канала, часть материала смотрят под микроскопом, часть используют для быстрого теста, ответ обычно готов в тот же день', 'Mit einem Tupfer wird Sekret aus Harnröhre oder Gebärmutterhalskanal entnommen, ein Teil wird unter dem Mikroskop betrachtet, ein Teil für den Schnelltest verwendet, das Ergebnis liegt meist am selben Tag vor', 'Üretra veya servikal kanaldan çubukla akıntı alınır, materyalin bir kısmı mikroskopta incelenir, bir kısmı hızlı testte kullanılır, sonuç genellikle aynı gün çıkar', 'Acute discharge and burning when urinating, when a quick preliminary answer is needed at a first visit to a urologist or gynaecologist, examination of a partner', 'Obilan sekret i peckanje pri mokrenju, kada je na prvom pregledu kod urologa ili ginekologa potreban brz orijentacioni odgovor, pregled partnera', 'Обилан секрет и пецкање при мокрењу, када је на првом прегледу код уролога или гинеколога потребан брз оријентациони одговор, преглед партнера', 'Острые выделения и жжение при мочеиспускании, когда нужен быстрый ориентировочный ответ на первичном приёме у уролога или гинеколога, обследование партнёра', 'Akuter Ausfluss und Brennen beim Wasserlassen, wenn beim ersten Termin in der Urologie oder Gynäkologie eine schnelle orientierende Antwort gebraucht wird, Untersuchung des Partners', 'Yoğun akıntı ve idrar yaparken yanma, üroloji veya kadın hastalıkları ilk muayenesinde hızlı ön bilgi gerektiğinde, partner taraması', 'Do not urinate for 2–3 hours before collection, women outside menstruation and without vaginal products the day before', 'Ne mokriti 2–3 sata prije uzimanja materijala, žene van dana menstruacije i bez vaginalnih preparata dan ranije', 'Не мокрити 2–3 сата прије узимања материјала, жене ван дана менструације и без вагиналних препарата дан раније', 'Не мочиться 2–3 часа перед взятием материала, женщинам — вне дней менструации и без вагинальных препаратов накануне', '2–3 Stunden vor der Entnahme nicht Wasser lassen, Frauen außerhalb der Menstruation und am Vortag ohne Vaginalpräparate', 'Örnek alınmadan 2–3 saat önce idrara çıkılmamalı, kadınlarda adet dışı günlerde ve bir gün önce vajinal ilaç kullanmadan alınmalıdır', 'The result is preliminary: with a small number of bacteria it may be negative, so it is usually supplemented by a culture or a molecular test. The decision on treatment is made by the doctor', 'Nalaz je orijentacioni: kod malog broja bakterija može biti negativan, pa se obično dopunjava kulturom ili molekularnim testom. Odluku o liječenju donosi ljekar', 'Налаз је оријентациони: код малог броја бактерија може бити негативан, па се обично допуњава културом или молекуларним тестом. Одлуку о лијечењу доноси љекар', 'Результат считается ориентировочным: при малом количестве бактерий он может быть отрицательным, поэтому его обычно дополняют посевом или молекулярным тестом. Решение о лечении принимает врач', 'Das Ergebnis ist orientierend: bei geringer Erregermenge kann es negativ ausfallen und wird deshalb meist durch Kultur oder molekularen Test ergänzt. Über die Behandlung entscheidet der Arzt', 'Sonuç ön bilgi niteliğindedir: bakteri sayısı azken negatif çıkabilir, bu nedenle genellikle kültür veya moleküler testle tamamlanır. Tedavi kararını hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ogtt-5-point'), 'Glucose load test in which glucose is measured while fasting and at four further points after drinking the solution', 'Test opterećenja šećerom u kojem se glukoza mjeri natašte i u još četiri tačke poslije ispijanja rastvora', 'Тест оптерећења шећером у којем се глукоза мјери наташте и у још четири тачке послије испијања раствора', 'Проба с сахарной нагрузкой, в которой глюкозу измеряют натощак и ещё в четырёх точках после приёма раствора', 'Belastungstest, bei dem Glukose nüchtern und an vier weiteren Zeitpunkten nach Einnahme der Lösung gemessen wird', 'Glukozun açlıkta ve solüsyon içildikten sonraki dört zamanda ölçüldüğü şeker yükleme testi', 'After the first fasting sample the patient drinks the glucose solution and stays in the laboratory for two hours, with blood drawn at 30, 60, 90 and 120 minutes', 'Poslije prvog vađenja natašte pacijent popije rastvor glukoze i ostaje u laboratoriji dva sata, a krv se vadi nakon 30, 60, 90 i 120 minuta', 'Послије првог вађења наташте пацијент попије раствор глукозе и остаје у лабораторији два сата, а крв се вади након 30, 60, 90 и 120 минута', 'После первого забора натощак пациент выпивает раствор глюкозы и остаётся в лаборатории два часа, кровь берут через 30, 60, 90 и 120 минут', 'Nach der ersten Nüchternentnahme trinkt die Patientin oder der Patient die Glukoselösung und bleibt zwei Stunden im Labor, Blut wird nach 30, 60, 90 und 120 Minuten entnommen', 'Açlık kanı alındıktan sonra hasta glukoz solüsyonunu içer ve iki saat laboratuvarda kalır, kan 30, 60, 90 ve 120. dakikalarda alınır', 'Borderline fasting glucose result, assessment of carbohydrate metabolism disorders, work-up in excess weight and cycle disorders, monitoring on referral by an endocrinologist', 'Granični nalaz glukoze natašte, procjena poremećaja metabolizma ugljenih hidrata, obrada kod prekomjerne težine i poremećaja ciklusa, praćenje po uputu endokrinologa', 'Гранични налаз глукозе наташте, процјена поремећаја метаболизма угљених хидрата, обрада код прекомјерне тежине и поремећаја циклуса, праћење по упуту ендокринолога', 'Пограничный результат глюкозы натощак, оценка нарушений углеводного обмена, обследование при избыточном весе и нарушениях цикла, наблюдение по направлению эндокринолога', 'Grenzwertiger Nüchternglukosewert, Beurteilung von Störungen des Kohlenhydratstoffwechsels, Abklärung bei Übergewicht und Zyklusstörungen, Verlaufskontrolle auf Überweisung des Endokrinologen', 'Sınırda açlık glukoz sonucu, karbonhidrat metabolizması bozukluklarının değerlendirilmesi, fazla kilo ve adet düzensizliğinde inceleme, endokrinoloji yönlendirmesiyle izlem', 'Fasting for 8–12 hours, only water allowed; eat as usual for three days before, and on the day of the test do not eat, smoke or exert yourself physically, telling the staff immediately if you feel unwell', 'Natašte 8–12 sati, dozvoljena je samo voda; tri dana prije testa jesti uobičajeno, na dan testa ne jesti, ne pušiti i ne opterećivati se fizički, a kod lošeg osjećaja odmah obavijestiti osoblje', 'Наташте 8–12 сати, дозвољена је само вода; три дана прије теста јести уобичајено, на дан теста не јести, не пушити и не оптерећивати се физички, а код лошег осјећаја одмах обавијестити особље', 'Натощак 8–12 часов, разрешена только вода; три дня до пробы питаться привычно, в день пробы не есть, не курить и не нагружать себя физически, при плохом самочувствии сразу сказать персоналу', '8–12 Stunden nüchtern, nur Wasser erlaubt; drei Tage zuvor gewohnt essen, am Testtag nicht essen, nicht rauchen und sich nicht körperlich belasten, bei Unwohlsein sofort das Personal informieren', '8–12 saat açlık, sadece su içilebilir; testten önceki üç gün her zamanki gibi beslenmeli, test günü yemek yenmemeli, sigara içilmemeli ve fiziksel zorlanmadan kaçınılmalı, rahatsızlık hissedilirse hemen personele bildirilmelidir', 'The shape of the glucose curve may be related to a carbohydrate metabolism disorder or to temporary causes such as recent illness or medications. The conclusion across all points is drawn by the doctor', 'Tok krive glukoze može biti povezan sa poremećajem metabolizma ugljenih hidrata ili sa privremenim uzrocima, poput skorašnje bolesti ili uzimanja lijekova. Zaključak po svim tačkama donosi ljekar', 'Ток криве глукозе може бити повезан са поремећајем метаболизма угљених хидрата или са привременим узроцима, попут скорашње болести или узимања лијекова. Закључак по свим тачкама доноси љекар', 'Ход кривой глюкозы может быть связан с нарушением углеводного обмена или с временными причинами, например недавней болезнью или приёмом препаратов. Заключение по всем точкам делает врач', 'Der Verlauf der Glukosekurve kann mit einer Störung des Kohlenhydratstoffwechsels oder mit vorübergehenden Ursachen wie einer kürzlichen Erkrankung oder Medikamenten zusammenhängen. Die Gesamtbeurteilung aller Zeitpunkte nimmt der Arzt vor', 'Glukoz eğrisinin seyri karbonhidrat metabolizması bozukluğuyla ya da yakın zamandaki hastalık veya ilaç kullanımı gibi geçici nedenlerle ilişkili olabilir. Tüm zaman noktalarına ilişkin değerlendirmeyi hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'postoperative-wound-swab-anaerobic'), 'Culture of discharge from a postoperative wound grown both in oxygen and in oxygen-free conditions', 'Kultura sekreta postoperativne rane uz zasijavanje u aerobnim i u anaerobnim uslovima', 'Култура секрета постоперативне ране уз засијавање у аеробним и у анаеробним условима', 'Посев отделяемого послеоперационной раны с ростом и в кислородной, и в бескислородной среде', 'Kultur des Sekrets einer postoperativen Wunde mit Anzucht sowohl unter Sauerstoff als auch unter Sauerstoffausschluss', 'Postoperatif yara akıntısının hem oksijenli hem oksijensiz ortamda üretildiği kültür', 'Discharge is taken from the depth of the wound with a sterile swab or syringe and placed in transport medium, then plated in the laboratory in parallel under aerobic and anaerobic conditions', 'Sterilnim štapićem ili špricem uzima se sekret iz dubine rane i stavlja u transportnu podlogu, a u laboratoriji se materijal zasijava uporedo u aerobnim i anaerobnim uslovima', 'Стерилним штапићем или шприцем узима се секрет из дубине ране и ставља у транспортну подлогу, а у лабораторији се материјал засијава упоредо у аеробним и анаеробним условима', 'Стерильным тампоном или шприцем берут отделяемое из глубины раны и помещают в транспортную среду, в лаборатории материал засевают параллельно в аэробных и анаэробных условиях', 'Sekret wird mit sterilem Tupfer oder Spritze aus der Tiefe der Wunde entnommen und in ein Transportmedium gegeben, im Labor erfolgt die Anzucht parallel unter aeroben und anaeroben Bedingungen', 'Yaranın derininden steril çubuk veya enjektörle akıntı alınıp taşıma besiyerine konur, laboratuvarda materyal aerob ve anaerob koşullarda paralel olarak ekilir', 'Redness, swelling and discharge from the suture line, fever after surgery, separation of the wound edges, no effect from the prescribed antibiotic', 'Crvenilo, otok i sekrecija iz šava, povišena temperatura poslije operacije, razmicanje ivica rane, izostanak efekta propisanog antibiotika', 'Црвенило, оток и секреција из шава, повишена температура послије операције, размицање ивица ране, изостанак ефекта прописаног антибиотика', 'Покраснение, отёк и отделяемое из шва, повышение температуры после операции, расхождение краёв раны, отсутствие эффекта от назначенного антибиотика', 'Rötung, Schwellung und Sekretion aus der Naht, Fieber nach der Operation, Auseinanderweichen der Wundränder, fehlende Wirkung des verordneten Antibiotikums', 'Dikiş hattında kızarıklık, şişlik ve akıntı, ameliyat sonrası ateş, yara kenarlarının ayrılması, verilen antibiyotikten yanıt alınamaması', 'No preparation is required from the patient, the sample is taken during a dressing change; the wound should not be treated with antiseptics before collection', 'Priprema pacijenta nije potrebna, materijal se uzima tokom previjanja; ranu prije uzorkovanja ne tretirati antisepticima', 'Припрема пацијента није потребна, материјал се узима током превијања; рану прије узорковања не третирати антисептицима', 'Подготовки от пациента не требуется, материал берут во время перевязки; рану перед забором не обрабатывать антисептиками', 'Eine Vorbereitung durch die Patientin oder den Patienten ist nicht nötig, die Probe wird beim Verbandwechsel entnommen; die Wunde vor der Entnahme nicht mit Antiseptika behandeln', 'Hastadan hazırlık istenmez, örnek pansuman sırasında alınır; örnek alınmadan önce yara antiseptiklerle temizlenmemelidir', 'Bacterial growth may be related to a surgical site infection or to colonisation of the wound edges without inflammation, and some anaerobes grow slowly. The significance of the finding is assessed by the operating surgeon', 'Porast bakterija može biti povezan sa infekcijom hirurškog mjesta ili sa kolonizacijom ivica rane bez upale, a dio anaeroba raste sporo. Značaj nalaza procjenjuje hirurg koji je operisao', 'Пораст бактерија може бити повезан са инфекцијом хируршког мјеста или са колонизацијом ивица ране без упале, а дио анаероба расте споро. Значај налаза процјењује хирург који је оперисао', 'Рост бактерий может быть связан с инфекцией области хирургического вмешательства или с колонизацией краёв раны без воспаления, а часть анаэробов растёт медленно. Значимость находки оценивает оперировавший врач', 'Bakterienwachstum kann mit einer Infektion des Operationsgebiets oder mit einer Besiedlung der Wundränder ohne Entzündung zusammenhängen, ein Teil der Anaerobier wächst langsam. Die Bedeutung des Befunds beurteilt der operierende Arzt', 'Bakteri üremesi cerrahi alan enfeksiyonuyla ya da iltihap olmaksızın yara kenarlarının kolonizasyonuyla ilişkili olabilir, bazı anaeroplar yavaş ürer. Bulgunun önemini ameliyatı yapan hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protozoa-stool-test'), 'Stool examination for three intestinal protozoa, Giardia, Cryptosporidium and Entamoeba', 'Pregled stolice na tri crijevne protozoe, Giardia, Cryptosporidium i Entamoeba', 'Преглед столице на три цријевне протозое, Гиардиа, Црyптоспоридиум и Ентамоеба', 'Исследование кала на трёх кишечных простейших — Giardia, Cryptosporidium и Entamoeba', 'Stuhluntersuchung auf drei Darmprotozoen, Giardia, Cryptosporidium und Entamoeba', 'Dışkının üç bağırsak protozoonu, Giardia, Cryptosporidium ve Entamoeba açısından incelenmesi', 'The patient collects a small stool sample in a container, and the laboratory checks the material for antigens of these protozoa', 'Pacijent uzima mali uzorak stolice u kontejner, a laboratorija materijal ispituje na antigene ovih protozoa', 'Пацијент узима мали узорак столице у контејнер, а лабораторија материјал испитује на антигене ових протозоа', 'Пациент собирает небольшой образец кала в контейнер, в лаборатории материал проверяют на антигены этих простейших', 'Die Patientin oder der Patient sammelt eine kleine Stuhlprobe in einem Behälter, im Labor wird das Material auf Antigene dieser Protozoen geprüft', 'Hasta kaba küçük bir dışkı örneği alır, laboratuvarda materyal bu protozoonların antijenleri açısından incelenir', 'Prolonged diarrhoea, bloating and abdominal pain, weight loss, examination of children and travellers, cases of diarrhoea in a group setting', 'Dugotrajan proliv, nadutost i bolovi u stomaku, gubitak tjelesne težine, pregled djece i putnika, slučajevi proliva u kolektivu', 'Дуготрајан пролив, надутост и болови у стомаку, губитак тјелесне тежине, преглед дјеце и путника, случајеви пролива у колективу', 'Длительная диарея, вздутие и боли в животе, потеря веса, обследование детей и путешественников, случаи диареи в организованном коллективе', 'Anhaltender Durchfall, Blähungen und Bauchschmerzen, Gewichtsverlust, Untersuchung von Kindern und Reisenden, Durchfallfälle in Gemeinschaftseinrichtungen', 'Uzun süren ishal, şişkinlik ve karın ağrısı, kilo kaybı, çocukların ve seyahat edenlerin incelenmesi, toplu yaşam ortamlarındaki ishal olguları', 'Collect the sample in a clean dry container without urine in it and deliver it to the laboratory as soon as possible; laxatives, antiparasitic medicines and bismuth preparations should be agreed with the doctor in advance', 'Uzorak se uzima u čist i suv kontejner, bez primjese mokraće, i dostavlja u laboratoriju što prije; uzimanje laksativa, antiparazitnih preparata i lijekova sa bizmutom prethodno se dogovara sa ljekarom', 'Узорак се узима у чист и сув контејнер, без примјесе мокраће, и доставља у лабораторију што прије; узимање лаксатива, антипаразитних препарата и лијекова са бизмутом претходно се договара са љекаром', 'Образец собирают в чистый сухой контейнер, без примеси мочи, и доставляют в лабораторию как можно быстрее; приём слабительных, противопаразитарных средств и препаратов висмута заранее согласуют с врачом', 'Die Probe in einen sauberen trockenen Behälter ohne Urinbeimengung geben und möglichst rasch ins Labor bringen; Abführmittel, Antiparasitika und wismuthaltige Präparate vorher mit dem Arzt abstimmen', 'Örnek temiz ve kuru bir kaba, idrar karışmadan alınmalı ve en kısa sürede laboratuvara ulaştırılmalıdır; müshil, antiparaziter ilaç ve bizmutlu preparat kullanımı önceden hekimle görüşülmelidir', 'Detection of an antigen shows that the protozoan is present in the sample and does not always explain all complaints, while a negative result from one sample does not rule out infection. Further work-up is prescribed by the doctor', 'Nalaz antigena pokazuje da je protozoa prisutna u uzorku i ne objašnjava uvijek sve tegobe, dok negativan nalaz jednog uzorka ne isključuje infekciju. Dalju obradu određuje ljekar', 'Налаз антигена показује да је протозоа присутна у узорку и не објашњава увијек све тегобе, док негативан налаз једног узорка не искључује инфекцију. Даљу обраду одређује љекар', 'Обнаружение антигена говорит о присутствии простейшего в образце и не всегда объясняет все жалобы, а отрицательный результат одной пробы инфекцию не исключает. Дальнейшее обследование назначает врач', 'Ein Antigennachweis zeigt, dass der Erreger in der Probe vorhanden ist, und erklärt nicht immer alle Beschwerden, ein negatives Ergebnis einer Probe schließt eine Infektion nicht aus. Die weitere Abklärung ordnet der Arzt an', 'Antijen saptanması protozoonun örnekte bulunduğunu gösterir ve her zaman tüm şikayetleri açıklamaz, tek örneğin negatif çıkması ise enfeksiyonu dışlamaz. Sonraki incelemeleri hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'punctate-aerobic-anaerobic'), 'Culture of fluid obtained by puncture from a cavity, a joint or an abscess, under aerobic and anaerobic conditions', 'Kultura tečnosti dobijene punkcijom iz šupljine, zgloba ili apscesa, u aerobnim i anaerobnim uslovima', 'Култура течности добијене пункцијом из шупљине, зглоба или апсцеса, у аеробним и анаеробним условима', 'Посев жидкости, полученной пункцией из полости, сустава или гнойника, в аэробных и анаэробных условиях', 'Kultur der durch Punktion aus einer Höhle, einem Gelenk oder einem Abszess gewonnenen Flüssigkeit unter aeroben und anaeroben Bedingungen', 'Bir boşluktan, eklemden veya apseden ponksiyonla alınan sıvının aerob ve anaerob koşullarda kültürü', 'The doctor obtains the material by puncture under sterile conditions and immediately places it in transport medium or an air-free syringe, and the laboratory plates it on different media', 'Ljekar punkcijom u sterilnim uslovima dobija materijal i odmah ga stavlja u transportnu podlogu ili špric bez vazduha, a laboratorija ga zasijava na različite podloge', 'Љекар пункцијом у стерилним условима добија материјал и одмах га ставља у транспортну подлогу или шприц без ваздуха, а лабораторија га засијава на различите подлоге', 'Врач получает материал пункцией в стерильных условиях и сразу помещает его в транспортную среду или шприц без воздуха, в лаборатории материал засевают на разные среды', 'Der Arzt gewinnt das Material durch Punktion unter sterilen Bedingungen und gibt es sofort in ein Transportmedium oder eine luftfreie Spritze, im Labor wird es auf verschiedene Nährböden ausgebracht', 'Hekim materyali steril koşullarda ponksiyonla alır ve hemen taşıma besiyerine veya havasız enjektöre koyar, laboratuvarda farklı besiyerlerine ekilir', 'Suspected infection of a joint, the pleural or abdominal cavity, fluid collection after surgery, a soft tissue abscess, search for the cause of prolonged fever', 'Sumnja na infekciju zgloba, pleuralne ili trbušne duplje, nakupljanje tečnosti poslije operacije, apsces mekih tkiva, traženje uzroka dugotrajne temperature', 'Сумња на инфекцију зглоба, плеуралне или трбушне дупље, накупљање течности послије операције, апсцес меких ткива, тражење узрока дуготрајне температуре', 'Подозрение на инфекцию сустава, плевральной или брюшной полости, скопление жидкости после операции, гнойник мягких тканей, поиск причины длительной лихорадки', 'Verdacht auf Infektion eines Gelenks, des Brust- oder Bauchraums, Flüssigkeitsansammlung nach einer Operation, Weichteilabszess, Suche nach der Ursache von anhaltendem Fieber', 'Eklem, plevra veya karın boşluğu enfeksiyonu şüphesi, ameliyat sonrası sıvı birikimi, yumuşak doku apsesi, uzun süren ateşin nedeninin araştırılması', 'No special preparation, the material is taken during the puncture; tell the doctor in advance about any antibiotics you are taking', 'Posebna priprema nije potrebna, materijal se uzima tokom punkcije; o antibioticima koje uzimate treba unaprijed obavijestiti ljekara', 'Посебна припрема није потребна, материјал се узима током пункције; о антибиотицима које узимате треба унапријед обавијестити љекара', 'Специальной подготовки нет, материал берут во время пункции; о принимаемых антибиотиках нужно сказать врачу заранее', 'Keine besondere Vorbereitung, das Material wird während der Punktion gewonnen; über eingenommene Antibiotika sollte der Arzt vorab informiert werden', 'Özel bir hazırlık gerekmez, materyal ponksiyon sırasında alınır; kullanılan antibiyotikler hekime önceden bildirilmelidir', 'Growth of microorganisms may point to infection in the cavity examined, while a sterile culture does not exclude it, especially during antibiotic treatment. The result is assessed together with the clinical picture by the treating doctor', 'Porast mikroorganizama može ukazivati na infekciju u ispitivanoj šupljini, dok sterilan nalaz kulture ne isključuje infekciju, naročito uz antibiotsku terapiju. Nalaz uz kliničku sliku procjenjuje ljekar koji vodi liječenje', 'Пораст микроорганизама може указивати на инфекцију у испитиваној шупљини, док стерилан налаз културе не искључује инфекцију, нарочито уз антибиотску терапију. Налаз уз клиничку слику процјењује љекар који води лијечење', 'Рост микроорганизмов может указывать на инфекцию в исследованной полости, а стерильный посев её не исключает, особенно на фоне антибиотиков. Результат вместе с клинической картиной оценивает лечащий врач', 'Ein Keimwachstum kann auf eine Infektion der untersuchten Höhle hinweisen, eine sterile Kultur schließt sie nicht aus, besonders unter Antibiotikatherapie. Den Befund beurteilt der behandelnde Arzt zusammen mit dem klinischen Bild', 'Mikroorganizma üremesi incelenen boşlukta enfeksiyona işaret edebilir, steril kültür ise özellikle antibiyotik kullanımı sırasında enfeksiyonu dışlamaz. Sonucu klinik tabloyla birlikte tedaviyi yürüten hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'rectal-swab-bacteria'), 'Culture of material from the rectum for bacterial flora with an antibiogram', 'Kultura materijala iz rektuma na bakterijsku floru sa antibiogramom', 'Култура материјала из ректума на бактеријску флору са антибиограмом', 'Посев материала из прямой кишки на бактериальную флору с антибиотикограммой', 'Kultur von Material aus dem Enddarm auf bakterielle Flora mit Antibiogramm', 'Rektumdan alınan materyalin bakteri florası için antibiyogramlı kültürü', 'A swab is inserted a short way into the rectum and rotated, the material is plated on nutrient media, and if growth occurs susceptibility to antibiotics is determined', 'Štapić se uvodi na malu dubinu u rektum i okreće, materijal se zasijava na hranljive podloge, a kod porasta se radi antibiogram', 'Штапић се уводи на малу дубину у ректум и окреће, материјал се засијава на хранљиве подлоге, а код пораста се ради антибиограм', 'Тампон вводят на небольшую глубину в прямую кишку и поворачивают, материал засевают на питательные среды, при росте определяют чувствительность к антибиотикам', 'Ein Tupfer wird ein kurzes Stück in den Enddarm eingeführt und gedreht, das Material wird auf Nährböden ausgestrichen, bei Wachstum folgt die Empfindlichkeitsprüfung', 'Çubuk rektuma kısa bir mesafe sokulup döndürülür, materyal besiyerlerine ekilir, üreme olursa antibiyotik duyarlılığı belirlenir', 'Checking carriage of intestinal bacteria, work-up before surgery or hospital admission, screening for resistant bacteria in hospital, sanitary examinations, discharge and discomfort around the anus', 'Provjera kliconoštva crijevnih bakterija, obrada prije operacije ili prijema u bolnicu, skrining otpornih bakterija u bolnici, sanitarni pregledi, sekrecija i nelagoda oko čmara', 'Провјера клицоноштва цријевних бактерија, обрада прије операције или пријема у болницу, скрининг отпорних бактерија у болници, санитарни прегледи, секреција и нелагода око чмара', 'Проверка носительства кишечных бактерий, обследование перед операцией или госпитализацией, скрининг устойчивых бактерий в стационаре, санитарные осмотры, выделения и дискомфорт в области заднего прохода', 'Prüfung auf Trägerschaft von Darmbakterien, Abklärung vor Operation oder Krankenhausaufnahme, Screening auf resistente Bakterien in der Klinik, amtsärztliche Untersuchungen, Sekretion und Beschwerden im Analbereich', 'Bağırsak bakterisi taşıyıcılığının araştırılması, ameliyat veya hastaneye yatış öncesi inceleme, hastanede dirençli bakteri taraması, sağlık raporu muayeneleri, anüs çevresinde akıntı ve rahatsızlık', 'No special preparation is needed; avoid suppositories, ointments and enemas the day before, and agree any antibiotics taken before collection with the doctor', 'Posebna priprema nije potrebna; dan ranije ne koristiti supozitorije, masti i klizme, a uzimanje antibiotika prije uzorkovanja dogovoriti sa ljekarom', 'Посебна припрема није потребна; дан раније не користити супозиторије, масти и клизме, а узимање антибиотика прије узорковања договорити са љекаром', 'Особой подготовки не нужно; накануне не использовать свечи, мази и клизмы, приём антибиотиков до забора согласовать с врачом', 'Eine besondere Vorbereitung ist nicht nötig; am Vortag keine Zäpfchen, Salben und Einläufe verwenden, die Einnahme von Antibiotika vor der Entnahme mit dem Arzt abstimmen', 'Özel bir hazırlık gerekmez; bir gün önce fitil, merhem ve lavman kullanılmamalı, örnek öncesi antibiyotik kullanımı hekimle görüşülmelidir', 'Bacterial growth may reflect an infection, ordinary intestinal flora or carriage without complaints. Whether treatment is needed is determined by the doctor from the type of bacterium and the clinical picture', 'Porast bakterija može odražavati infekciju, uobičajenu crijevnu floru ili kliconoštvo bez tegoba. Da li je liječenje potrebno, ljekar određuje prema vrsti bakterije i kliničkoj slici', 'Пораст бактерија може одражавати инфекцију, уобичајену цријевну флору или клицоноштво без тегоба. Да ли је лијечење потребно, љекар одређује према врсти бактерије и клиничкој слици', 'Рост бактерий может отражать инфекцию, обычную кишечную флору или носительство без жалоб. Нужно ли лечение, определяет врач по виду бактерии и клинической картине', 'Bakterienwachstum kann eine Infektion, die normale Darmflora oder eine beschwerdefreie Trägerschaft widerspiegeln. Ob eine Behandlung nötig ist, entscheidet der Arzt anhand der Bakterienart und des klinischen Bildes', 'Bakteri üremesi enfeksiyonu, olağan bağırsak florasını ya da şikayetsiz taşıyıcılığı yansıtabilir. Tedavi gerekip gerekmediğini hekim, bakteri türüne ve klinik tabloya göre belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'rectal-swab-fungi'), 'Culture of material from the rectum for yeast fungi', 'Kultura materijala iz rektuma na kvasnice', 'Култура материјала из ректума на кваснице', 'Посев материала из прямой кишки на дрожжевые грибы', 'Kultur von Material aus dem Enddarm auf Hefepilze', 'Rektumdan alınan materyalin maya mantarları için kültürü', 'Material is taken from the rectum with a swab and plated on special fungal media, with growth assessed over a longer period than in a bacterial culture', 'Štapićem se uzima materijal iz rektuma i zasijava na posebne podloge za gljivice, a porast se prati duže nego kod bakteriološke kulture', 'Штапићем се узима материјал из ректума и засијава на посебне подлоге за гљивице, а пораст се прати дуже него код бактериолошке културе', 'Тампоном берут материал из прямой кишки и засевают на специальные среды для грибов, рост оценивают дольше, чем при бактериальном посеве', 'Mit einem Tupfer wird Material aus dem Enddarm entnommen und auf spezielle Pilznährböden ausgebracht, das Wachstum wird länger beobachtet als bei einer Bakterienkultur', 'Rektumdan çubukla örnek alınır ve mantarlar için özel besiyerlerine ekilir, üreme bakteri kültürüne göre daha uzun süre izlenir', 'Itching and irritation around the anus, long courses of antibiotics, recurrent candidiasis, work-up in reduced immunity, assessment after treatment as prescribed by the doctor', 'Svrab i nadražaj oko čmara, dugotrajno uzimanje antibiotika, ponavljana kandidijaza, ispitivanje kod oslabljenog imuniteta, procjena poslije terapije po savjetu ljekara', 'Свраб и надражај око чмара, дуготрајно узимање антибиотика, понављана кандидијаза, испитивање код ослабљеног имунитета, процјена послије терапије по савјету љекара', 'Зуд и раздражение вокруг заднего прохода, длительный приём антибиотиков, повторяющийся кандидоз, обследование при сниженном иммунитете, оценка после лечения по назначению врача', 'Juckreiz und Reizung um den After, längere Antibiotikaeinnahme, wiederkehrende Candidose, Abklärung bei geschwächter Abwehr, Beurteilung nach der Behandlung auf ärztliche Anordnung', 'Anüs çevresinde kaşıntı ve tahriş, uzun süreli antibiyotik kullanımı, tekrarlayan kandidiyaz, bağışıklığı azalmış kişilerde inceleme, hekim önerisiyle tedavi sonrası değerlendirme', 'No preparation is required; avoid antifungal suppositories and ointments the day before, and the sample is taken before washing', 'Priprema nije potrebna; dan ranije ne koristiti antimikotičke supozitorije i masti, a uzorak se uzima prije pranja', 'Припрема није потребна; дан раније не користити антимикотичке супозиторије и масти, а узорак се узима прије прања', 'Подготовка не требуется; накануне не применять противогрибковые свечи и мази, материал берут до подмывания', 'Eine Vorbereitung ist nicht nötig; am Vortag keine Antipilz-Zäpfchen und -Salben anwenden, die Probe wird vor dem Waschen entnommen', 'Hazırlık gerekmez; bir gün önce antifungal fitil ve merhem kullanılmamalı, örnek yıkanmadan önce alınmalıdır', 'Growth of yeast fungi also occurs in people without complaints, so its meaning is assessed by the doctor together with symptoms and other investigations', 'Porast kvasnica sreće se i kod osoba bez tegoba, pa njegov značaj ljekar procjenjuje zajedno sa simptomima i drugim nalazima', 'Пораст квасница среће се и код особа без тегоба, па његов значај љекар процјењује заједно са симптомима и другим налазима', 'Рост дрожжевых грибов встречается и у людей без жалоб, поэтому его значение врач оценивает вместе с симптомами и другими исследованиями', 'Ein Wachstum von Hefepilzen kommt auch bei Personen ohne Beschwerden vor, seine Bedeutung beurteilt der Arzt daher zusammen mit den Symptomen und weiteren Untersuchungen', 'Maya mantarı üremesi şikayeti olmayan kişilerde de görülür, bu nedenle anlamını hekim belirtiler ve diğer tetkiklerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'sperm-culture-fungi'), 'Culture of seminal fluid for yeast and mould fungi', 'Kultura sjemene tečnosti na kvasnice i plijesni', 'Култура сјемене течности на кваснице и плијесни', 'Посев семенной жидкости на дрожжевые и плесневые грибы', 'Kultur der Samenflüssigkeit auf Hefe- und Schimmelpilze', 'Meni sıvısının maya ve küf mantarları için kültürü', 'The sample from the sterile container is plated on special fungal media, and the result takes longer than in a bacterial culture', 'Uzorak iz sterilne posude zasijava se na posebne podloge za gljivice, a nalaz se čeka duže nego kod bakteriološke kulture', 'Узорак из стерилне посуде засијава се на посебне подлоге за гљивице, а налаз се чека дуже него код бактериолошке културе', 'Образец из стерильного контейнера засевают на специальные грибковые среды, результат готовится дольше, чем при бактериальном посеве', 'Die Probe aus dem sterilen Behälter wird auf spezielle Pilznährböden ausgebracht, das Ergebnis dauert länger als bei einer Bakterienkultur', 'Steril kaptaki örnek özel mantar besiyerlerine ekilir, sonuç bakteri kültürüne göre daha geç çıkar', 'Complaints persisting after antibacterial treatment, recurrent candidiasis in partners, work-up in reduced immunity, infertility work-up as prescribed by the urologist', 'Tegobe koje traju i poslije antibakterijske terapije, ponavljana kandidijaza kod partnera, ispitivanje kod oslabljenog imuniteta, obrada zbog neplodnosti po savjetu urologa', 'Тегобе које трају и послије антибактеријске терапије, понављана кандидијаза код партнера, испитивање код ослабљеног имунитета, обрада због неплодности по савјету уролога', 'Жалобы, сохраняющиеся после антибактериального лечения, повторяющийся кандидоз у партнёров, обследование при сниженном иммунитете, обследование при бесплодии по назначению уролога', 'Beschwerden, die nach antibakterieller Behandlung bestehen bleiben, wiederkehrende Candidose bei Partnern, Abklärung bei geschwächter Abwehr, Kinderwunschabklärung auf Anordnung des Urologen', 'Antibakteriyel tedaviden sonra süren şikayetler, partnerlerde tekrarlayan kandidiyaz, bağışıklığı azalmış kişilerde inceleme, üroloji önerisiyle kısırlık incelemesi', 'Sexual abstinence for 2–5 days, hygiene of the external genitals before collection, material only into a sterile container without a condom or lubricant', 'Polna uzdržanost 2–5 dana, higijena spoljašnjih polnih organa prije uzimanja, materijal samo u sterilnu posudu, bez kondoma i lubrikanta', 'Полна уздржаност 2–5 дана, хигијена спољашњих полних органа прије узимања, материјал само у стерилну посуду, без кондома и лубриканта', 'Половое воздержание 2–5 дней, гигиена наружных половых органов перед сбором, материал только в стерильный контейнер, без презерватива и смазки', 'Sexuelle Karenz von 2–5 Tagen, Hygiene der äußeren Genitalien vor der Gewinnung, Material nur in einen sterilen Behälter, ohne Kondom und Gleitmittel', '2–5 gün cinsel perhiz, örnek öncesi dış genital bölge hijyeni, materyalin yalnızca steril kaba, prezervatif ve kayganlaştırıcı olmadan verilmesi gerekir', 'Fungal growth may reflect contamination of the sample with skin flora or involvement of fungi in inflammation, and the doctor helps to tell one from the other using complaints and a repeat test', 'Porast gljivica može odražavati zagađenje uzorka florom kože ili učešće gljivica u upali, a razlikovanje ljekar pravi na osnovu tegoba i ponovljenog ispitivanja', 'Пораст гљивица може одражавати загађење узорка флором коже или учешће гљивица у упали, а разликовање љекар прави на основу тегоба и поновљеног испитивања', 'Рост грибов может отражать загрязнение образца флорой кожи либо участие грибов в воспалении, и отличить одно от другого помогает врач по жалобам и повторному исследованию', 'Pilzwachstum kann eine Verunreinigung der Probe mit Hautflora oder eine Beteiligung von Pilzen an einer Entzündung widerspiegeln, die Unterscheidung trifft der Arzt anhand der Beschwerden und einer Wiederholungsuntersuchung', 'Mantar üremesi örneğe deri florasının karışmasını ya da mantarların iltihaba katılmasını yansıtabilir, bu ayrımı hekim şikayetlere ve tekrar incelemeye bakarak yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'std-multiplex-2'), 'Multiplex PCR test that looks for the DNA of two sexually transmitted pathogens in a single urogenital sample', 'Multipleks PCR test koji u jednom urogenitalnom uzorku traži DNK dva uzročnika polno prenosivih infekcija', 'Мултиплекс ПЦР тест који у једном урогениталном узорку тражи ДНК два узрочника полно преносивих инфекција', 'Мультиплексный ПЦР-тест, который в одном урогенитальном образце ищет ДНК двух возбудителей инфекций, передающихся половым путём', 'Multiplex-PCR-Test, der in einer einzigen urogenitalen Probe die DNA von zwei sexuell übertragbaren Erregern sucht', 'Tek bir ürogenital örnekte cinsel yolla bulaşan iki etkenin DNA''sını arayan multipleks PCR testi', 'A swab from the urethra, vagina or cervical canal, or a urine sample, is examined by real-time PCR; the laboratory states which pathogens the panel covers', 'Uzima se bris uretre, vagine ili cervikalnog kanala ili uzorak mokraće, a materijal se obrađuje metodom PCR u realnom vremenu; koje uzročnike panel obuhvata, navodi laboratorija', 'Узима се брис уретре, вагине или цервикалног канала или узорак мокраће, а материјал се обрађује методом ПЦР у реалном времену; које узрочнике панел обухвата, наводи лабораторија', 'Берут мазок из уретры, влагалища или цервикального канала либо порцию мочи и исследуют методом ПЦР в реальном времени; какие именно возбудители входят в панель, указывает лаборатория', 'Ein Abstrich aus Harnröhre, Scheide oder Gebärmutterhalskanal oder eine Urinprobe wird mittels Real-Time-PCR untersucht; welche Erreger das Panel umfasst, gibt das Labor an', 'Üretra, vajina veya servikal kanaldan sürüntü ya da idrar örneği alınır ve gerçek zamanlı PCR ile incelenir; panelin hangi etkenleri kapsadığını laboratuvar bildirir', 'Targeted testing ordered by a doctor when a specific pair of pathogens has to be ruled out, follow-up after prescribed treatment, examination of a sexual partner', 'Ciljana provjera po uputu ljekara kada treba isključiti određeni par uzročnika, kontrola poslije propisane terapije, pregled polnog partnera', 'Циљана провјера по упуту љекара када треба искључити одређени пар узрочника, контрола послије прописане терапије, преглед полног партнера', 'Прицельная проверка по назначению врача, когда нужно исключить конкретную пару возбудителей, контроль после назначенного лечения, обследование полового партнёра', 'Gezielte Untersuchung auf ärztliche Anordnung, wenn ein bestimmtes Erregerpaar ausgeschlossen werden soll, Kontrolle nach verordneter Behandlung, Untersuchung des Sexualpartners', 'Belirli bir etken çiftinin dışlanması gerektiğinde hekim isteğiyle hedefli inceleme, verilen tedavi sonrası kontrol, cinsel partnerin değerlendirilmesi', 'Do not urinate for about two hours before the swab, women should not be tested during menstruation; avoid intercourse, douching and vaginal products for a day beforehand', 'Ne mokriti oko dva sata prije uzimanja brisa, žene se ne testiraju tokom menstruacije; dan ranije izbjegavati odnose, ispiranja i vaginalne preparate', 'Не мокрити око два сата прије узимања бриса, жене се не тестирају током менструације; дан раније избјегавати односе, испирања и вагиналне препарате', 'Не мочиться около двух часов до взятия мазка, женщинам сдавать вне менструации; за сутки исключить интимные контакты, спринцевания и вагинальные средства', 'Etwa zwei Stunden vor der Abstrichentnahme nicht urinieren, Frauen nicht während der Menstruation; am Vortag auf Geschlechtsverkehr, Spülungen und Vaginalpräparate verzichten', 'Sürüntüden yaklaşık iki saat önce idrara çıkılmamalı, kadınlar adet döneminde test yaptırmamalı; bir gün önce cinsel ilişki, vajinal duş ve vajinal ürünlerden kaçınılmalı', 'Detected DNA means the pathogen is present in the sample, while a negative result applies only to the two pathogens included in the panel. Further steps are decided by the doctor', 'Nalaz DNK znači da je uzročnik prisutan u uzorku, a negativan rezultat se odnosi samo na ta dva uzročnika koja panel obuhvata. Dalje korake određuje ljekar', 'Налаз ДНК значи да је узрочник присутан у узорку, а негативан резултат се односи само на та два узрочника која панел обухвата. Даље кораке одређује љекар', 'Обнаружение ДНК означает, что возбудитель присутствует в исследованном материале, а отрицательный ответ относится только к тем двум возбудителям, которые входят в панель. Дальнейшие шаги определяет врач', 'Nachgewiesene DNA bedeutet, dass der Erreger in der Probe vorhanden ist, ein negatives Ergebnis gilt nur für die beiden im Panel enthaltenen Erreger. Das weitere Vorgehen legt der Arzt fest', 'DNA saptanması etkenin örnekte bulunduğunu gösterir, negatif sonuç yalnızca panele dahil iki etken için geçerlidir. Sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'std-multiplex-3'), 'PCR panel covering three urogenital pathogens, with a separate result reported for each one', 'PCR panel na tri uzročnika urogenitalnih infekcija, sa zasebnim nalazom za svaki od njih', 'ПЦР панел на три узрочника урогениталних инфекција, са засебним налазом за сваки од њих', 'ПЦР-панель на трёх возбудителей урогенитальных инфекций, результат по каждому выдаётся отдельной строкой', 'PCR-Panel für drei urogenitale Erreger, wobei für jeden ein eigenes Ergebnis ausgewiesen wird', 'Üç ürogenital etkeni kapsayan ve her biri için ayrı sonuç veren PCR paneli', 'The sample is a swab from the genital mucosa or urine, and the DNA of all three pathogens is searched for in one reaction at the same time', 'Uzorak je bris sluznice polnih puteva ili mokraća, a DNK sva tri uzročnika traži se istovremeno u jednoj reakciji', 'Узорак је брис слузнице полних путева или мокраћа, а ДНК сва три узрочника тражи се истовремено у једној реакцији', 'Материалом служит мазок со слизистой половых путей или моча, ДНК всех трёх возбудителей ищут в одной реакции одновременно', 'Als Material dient ein Abstrich der Genitalschleimhaut oder Urin, die DNA aller drei Erreger wird gleichzeitig in einem Ansatz gesucht', 'Örnek olarak genital mukozadan sürüntü veya idrar kullanılır, üç etkenin DNA''sı aynı anda tek bir reaksiyonda aranır', 'Discharge, itching and burning, discomfort when urinating, routine gynaecological or urological check-up, preparing for pregnancy', 'Sekret, svrab i pečenje, nelagoda pri mokrenju, redovan pregled kod ginekologa ili urologa, priprema za trudnoću', 'Секрет, свраб и печење, нелагода при мокрењу, редован преглед код гинеколога или уролога, припрема за трудноћу', 'Выделения, зуд и жжение, дискомфорт при мочеиспускании, плановое обследование у гинеколога или уролога, подготовка к беременности', 'Ausfluss, Juckreiz und Brennen, Beschwerden beim Wasserlassen, routinemäßige gynäkologische oder urologische Untersuchung, Vorbereitung auf eine Schwangerschaft', 'Akıntı, kaşıntı ve yanma, idrar yaparken rahatsızlık, jinekolog veya üroloji uzmanında rutin kontrol, gebelik hazırlığı', 'Women should not be tested during menstruation, men should not urinate for about two hours before the swab; tell the doctor in advance about recent antibiotics and topical products', 'Žene se ne testiraju tokom menstruacije, muškarci ne mokre oko dva sata prije uzimanja; ljekaru unaprijed reći o nedavnim antibioticima i lokalnim preparatima', 'Жене се не тестирају током менструације, мушкарци не мокре око два сата прије узимања; љекару унапријед рећи о недавним антибиотицима и локалним препаратима', 'Женщинам сдавать вне менструации, мужчинам не мочиться около двух часов до взятия; о недавнем приёме антибиотиков и о местных средствах сказать врачу заранее', 'Frauen nicht während der Menstruation, Männer etwa zwei Stunden vor der Entnahme nicht urinieren; kürzlich eingenommene Antibiotika und örtliche Präparate vorab dem Arzt mitteilen', 'Kadınlar adet döneminde test yaptırmamalı, erkekler sürüntüden yaklaşık iki saat önce idrara çıkmamalı; yakın zamanda kullanılan antibiyotikler ve lokal ürünler hekime önceden bildirilmeli', 'A positive result for one of the parameters means that this pathogen is present in the sample and says nothing about how severe the condition is. How to interpret the finding and whether the partner should be tested is decided by the doctor', 'Pozitivan nalaz za jedan od parametara govori da je taj uzročnik prisutan u materijalu i ne opisuje težinu stanja. Kako tumačiti nalaz i da li ispitati partnera, procjenjuje ljekar', 'Позитиван налаз за један од параметара говори да је тај узрочник присутан у материјалу и не описује тежину стања. Како тумачити налаз и да ли испитати партнера, процјењује љекар', 'Положительный результат по одному из показателей говорит о присутствии этого возбудителя в материале и не описывает тяжесть состояния. Как трактовать находку и нужно ли обследовать партнёра, решает врач', 'Ein positives Ergebnis für einen der Parameter zeigt, dass dieser Erreger in der Probe vorhanden ist, und sagt nichts über die Schwere des Zustands aus. Wie der Befund zu deuten ist und ob der Partner untersucht wird, entscheidet der Arzt', 'Parametrelerden birinin pozitif olması o etkenin örnekte bulunduğunu gösterir, durumun ağırlığı hakkında bilgi vermez. Bulgunun nasıl yorumlanacağına ve partnerin incelenip incelenmeyeceğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'std-multiplex-4'), 'Basic four-parameter set: a simultaneous search for the DNA of four urogenital pathogens', 'Osnovni set od četiri parametra: istovremena potraga za DNK četiri uzročnika urogenitalnih infekcija', 'Основни сет од четири параметра: истовремена потрага за ДНК четири узрочника урогениталних инфекција', 'Базовый набор из четырёх показателей: одновременный поиск ДНК четырёх возбудителей инфекций мочеполовой системы', 'Basissatz mit vier Parametern: gleichzeitige Suche nach der DNA von vier urogenitalen Erregern', 'Dört parametrelik temel set: dört ürogenital etkenin DNA''sının aynı anda araştırılması', 'One genital swab or a urine sample is split in the laboratory into reactions, each responsible for its own pathogen', 'Jedan bris polnih puteva ili uzorak mokraće u laboratoriji se dijeli na reakcije, a svaka odgovara svom uzročniku', 'Један брис полних путева или узорак мокраће у лабораторији се дијели на реакције, а свака одговара свом узрочнику', 'Один мазок из половых путей или порция мочи разделяется в лаборатории на реакции, каждая из которых отвечает за своего возбудителя', 'Ein Genitalabstrich oder eine Urinprobe wird im Labor auf mehrere Reaktionen aufgeteilt, von denen jede für einen Erreger zuständig ist', 'Tek bir genital sürüntü veya idrar örneği laboratuvarda her biri kendi etkeninden sorumlu reaksiyonlara ayrılır', 'First-line testing when urogenital infection symptoms appear, examination of both partners, preparation for gynaecological procedures and assisted reproduction programmes', 'Prvo ispitivanje kod simptoma urogenitalne infekcije, pregled oba partnera, priprema za ginekološke zahvate i za programe potpomognute oplodnje', 'Прво испитивање код симптома урогениталне инфекције, преглед оба партнера, припрема за гинеколошке захвате и за програме потпомогнуте оплодње', 'Первичное обследование при симптомах урогенитальной инфекции, обследование обоих партнёров, подготовка к гинекологическим вмешательствам и к программам вспомогательной репродукции', 'Erstuntersuchung bei Symptomen einer urogenitalen Infektion, Untersuchung beider Partner, Vorbereitung auf gynäkologische Eingriffe und auf Kinderwunschbehandlungen', 'Ürogenital enfeksiyon belirtilerinde ilk inceleme, her iki partnerin değerlendirilmesi, jinekolojik girişimlere ve yardımcı üreme programlarına hazırlık', 'Do not urinate for about two hours before the swab and do not attend during menstruation; skip intercourse and topical products for a day, discuss antibiotics with the doctor', 'Ne mokriti oko dva sata prije brisa i ne dolaziti tokom menstruacije; dan ranije bez odnosa i lokalnih preparata, antibiotike dogovoriti sa ljekarom', 'Не мокрити око два сата прије бриса и не долазити током менструације; дан раније без односа и локалних препарата, антибиотике договорити са љекаром', 'Не мочиться около двух часов до мазка, сдавать вне менструации; за сутки отказаться от интимных контактов и местных препаратов, приём антибиотиков обсудить с врачом', 'Etwa zwei Stunden vor dem Abstrich nicht urinieren und nicht während der Menstruation kommen; einen Tag lang auf Geschlechtsverkehr und örtliche Präparate verzichten, Antibiotika mit dem Arzt besprechen', 'Sürüntüden yaklaşık iki saat önce idrara çıkılmamalı, adet döneminde gelinmemeli; bir gün önce cinsel ilişki ve lokal ürünlerden kaçınılmalı, antibiyotikler hekimle konuşulmalı', 'Finding one or several pathogens means they are present in the sample, while a negative result does not rule out infections that are outside this set. The doctor assesses the result together with complaints and examination', 'Nalaz jednog ili više uzročnika znači da su prisutni u materijalu, a negativan rezultat ne isključuje infekcije koje nisu u ovom setu. Nalaz procjenjuje ljekar zajedno sa tegobama i pregledom', 'Налаз једног или више узрочника значи да су присутни у материјалу, а негативан резултат не искључује инфекције које нису у овом сету. Налаз процјењује љекар заједно са тегобама и прегледом', 'Выявление одного или нескольких возбудителей означает их присутствие в материале, а отрицательный результат не исключает инфекций, которых нет в этом наборе. Итог оценивает врач вместе с жалобами и осмотром', 'Der Nachweis eines oder mehrerer Erreger bedeutet, dass sie in der Probe vorhanden sind, ein negatives Ergebnis schließt Infektionen außerhalb dieses Satzes nicht aus. Das Ergebnis beurteilt der Arzt zusammen mit Beschwerden und Untersuchung', 'Bir veya birkaç etkenin saptanması bunların örnekte bulunduğunu gösterir, negatif sonuç ise bu setin dışındaki enfeksiyonları dışlamaz. Sonucu hekim şikayetler ve muayene ile birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'std-multiplex-4-plus-hpv-quant-4'), 'Combined test: a panel of four urogenital pathogens plus quantitative detection of four high-risk human papillomavirus types', 'Kombinovano ispitivanje: panel na četiri uzročnika urogenitalnih infekcija i kvantitativno određivanje četiri tipa humanog papiloma virusa visokog rizika', 'Комбиновано испитивање: панел на четири узрочника урогениталних инфекција и квантитативно одређивање четири типа хуманог папилома вируса високог ризика', 'Комбинированное исследование: панель на четырёх возбудителей урогенитальных инфекций и количественное определение четырёх типов вируса папилломы человека высокого канцерогенного риска', 'Kombinierte Untersuchung: ein Panel mit vier urogenitalen Erregern und der quantitative Nachweis von vier Hochrisiko-Typen des humanen Papillomvirus', 'Birleşik inceleme: dört ürogenital etkeni kapsayan panel ile yüksek riskli dört insan papilloma virüsü tipinin sayısal olarak belirlenmesi', 'A gynaecologist or urologist takes a swab from the genital mucosa, and the laboratory runs both parts of the test on the same material, reporting the HPV part with a quantitative value', 'Ginekolog ili urolog uzima bris sluznice polnih puteva, a laboratorija iz istog materijala radi oba dijela ispitivanja, pri čemu se nalaz za HPV izdaje sa brojčanom vrijednošću', 'Гинеколог или уролог узима брис слузнице полних путева, а лабораторија из истог материјала ради оба дијела испитивања, при чему се налаз за HPV издаје са бројчаном вриједношћу', 'Гинеколог или уролог берёт мазок со слизистой половых путей, в лаборатории из одного материала ставят обе части исследования, для ВПЧ результат выдают с количественной оценкой', 'Die Ärztin oder der Arzt entnimmt einen Abstrich der Genitalschleimhaut, das Labor führt beide Teile aus demselben Material durch und gibt den HPV-Teil mit einem Zahlenwert an', 'Jinekolog veya ürolog genital mukozadan sürüntü alır, laboratuvar aynı materyalden her iki incelemeyi de yapar ve HPV bölümünü sayısal değerle bildirir', 'Genital complaints combined with routine cervical screening, follow-up after changes in a cytology smear, testing when planning a pregnancy', 'Tegobe polnih puteva uz redovan skrining grlića materice, praćenje poslije promjena u citološkom brisu, ispitivanje pri planiranju trudnoće', 'Тегобе полних путева уз редован скрининг грлића материце, праћење послије промјена у цитолошком брису, испитивање при планирању трудноће', 'Сочетание жалоб со стороны половых путей с плановым скринингом шейки матки, наблюдение после изменений в цитологическом мазке, обследование при планировании беременности', 'Genitale Beschwerden zusammen mit dem regulären Gebärmutterhalsscreening, Verlaufskontrolle nach Veränderungen im Zellabstrich, Untersuchung bei Kinderwunsch', 'Genital şikayetlerin rutin rahim ağzı taramasıyla birlikte olduğu durumlar, sitolojik yaymada değişiklik sonrası izlem, gebelik planlarken yapılan inceleme', 'Women should not be tested during menstruation, should avoid intercourse, douching, vaginal suppositories and creams for two days and should not have a transvaginal ultrasound the day before', 'Žene se ne testiraju tokom menstruacije, dva dana ranije izbjegavati odnose, ispiranja, vaginalete i kreme, a dan prije ne raditi ultrazvuk vaginalnom sondom', 'Жене се не тестирају током менструације, два дана раније избјегавати односе, испирања, вагиналете и креме, а дан прије не радити ултразвук вагиналном сондом', 'Женщинам сдавать вне менструации, за двое суток исключить интимные контакты, спринцевания, вагинальные свечи и кремы, накануне не проходить УЗИ с вагинальным датчиком', 'Frauen nicht während der Menstruation, zwei Tage vorher auf Geschlechtsverkehr, Spülungen, Vaginalzäpfchen und Cremes verzichten, am Vortag keinen vaginalen Ultraschall', 'Kadınlar adet döneminde test yaptırmamalı, iki gün önceden cinsel ilişki, vajinal duş, vajinal fitil ve kremlerden kaçınmalı, bir gün önce vajinal ultrason yaptırmamalı', 'Detecting HPV means the virus is present in the sample, not a diagnosis: the virus often clears on its own and the quantitative value is meaningful mainly over time. The gynaecologist decides what the findings mean and how often the test is repeated', 'Nalaz HPV znači da je virus prisutan u materijalu, a ne dijagnozu: virus često nestane sam, a brojčana vrijednost ima značaj prije svega u praćenju kroz vrijeme. Značaj nalaza i raspored kontrola određuje ginekolog', 'Налаз HPV значи да је вирус присутан у материјалу, а не дијагнозу: вирус често нестане сам, а бројчана вриједност има значај прије свега у праћењу кроз вријеме. Значај налаза и распоред контрола одређује гинеколог', 'Обнаружение ВПЧ означает присутствие вируса в материале, а не диагноз: вирус часто исчезает сам, и количественный результат важен прежде всего в динамике. Значение находок и график наблюдения определяет гинеколог', 'Ein HPV-Nachweis bedeutet, dass das Virus in der Probe vorhanden ist, und ist keine Diagnose: das Virus verschwindet häufig von selbst, und der Zahlenwert ist vor allem im Verlauf aussagekräftig. Bedeutung und Kontrollabstände legt die Frauenärztin oder der Frauenarzt fest', 'HPV saptanması virüsün örnekte bulunduğunu gösterir, tanı anlamına gelmez: virüs çoğu kez kendiliğinden temizlenir ve sayısal değer asıl olarak izlemde anlam taşır. Bulguların anlamını ve kontrol aralıklarını jinekolog belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'std-multiplex-5'), 'Extended PCR panel covering five sexually transmitted pathogens in a single sample', 'Prošireni PCR panel na pet uzročnika polno prenosivih infekcija u jednom uzorku', 'Проширени ПЦР панел на пет узрочника полно преносивих инфекција у једном узорку', 'Расширенная ПЦР-панель на пять возбудителей инфекций, передающихся половым путём, в одном образце', 'Erweitertes PCR-Panel für fünf sexuell übertragbare Erreger aus einer einzigen Probe', 'Tek bir örnekte cinsel yolla bulaşan beş etkeni kapsayan genişletilmiş PCR paneli', 'A swab from the urethra, vagina or cervical canal, or urine, is analysed by a molecular method with a separate answer for each pathogen', 'Bris uretre, vagine ili cervikalnog kanala ili mokraća obrađuju se molekularnom metodom, uz zaseban odgovor za svaki uzročnik', 'Брис уретре, вагине или цервикалног канала или мокраћа обрађују се молекуларном методом, уз засебан одговор за сваки узрочник', 'Мазок из уретры, влагалища или цервикального канала либо моча, исследование проводится молекулярным методом с раздельным ответом по каждому возбудителю', 'Ein Abstrich aus Harnröhre, Scheide oder Gebärmutterhalskanal oder Urin wird molekularbiologisch untersucht, mit getrenntem Befund für jeden Erreger', 'Üretra, vajina veya servikal kanaldan sürüntü ya da idrar moleküler yöntemle incelenir ve her etken için ayrı sonuç verilir', 'Persisting complaints despite negative single-pathogen tests, repeated episodes of urogenital inflammation, infertility work-up, testing of partners', 'Tegobe koje traju uprkos negativnim pojedinačnim testovima, ponavljane upale mokraćno-polnih organa, obrada zbog neplodnosti, ispitivanje partnera', 'Тегобе које трају упркос негативним појединачним тестовима, понављане упале мокраћно-полних органа, обрада због неплодности, испитивање партнера', 'Сохраняющиеся жалобы при отрицательных узких тестах, повторные эпизоды воспаления мочеполовых органов, обследование при бесплодии, обследование партнёров', 'Anhaltende Beschwerden trotz negativer Einzeltests, wiederholte Entzündungen der Harn- und Geschlechtsorgane, Abklärung bei unerfülltem Kinderwunsch, Untersuchung der Partner', 'Tekli testler negatif olmasına rağmen süren şikayetler, ürogenital bölgede tekrarlayan iltihaplar, kısırlık araştırması, partnerlerin incelenmesi', 'Do not urinate for about two hours before the swab, women should avoid menstruation days; agree the interval after antibacterial treatment with the doctor', 'Ne mokriti oko dva sata prije uzimanja brisa, žene dolaze van dana menstruacije; razmak poslije antibakterijske terapije dogovoriti sa ljekarom', 'Не мокрити око два сата прије узимања бриса, жене долазе ван дана менструације; размак послије антибактеријске терапије договорити са љекаром', 'Не мочиться около двух часов перед взятием мазка, женщинам приходить вне менструации; сроки после антибактериального лечения согласовать с врачом', 'Etwa zwei Stunden vor der Abstrichentnahme nicht urinieren, Frauen außerhalb der Menstruationstage; den Abstand nach einer antibakteriellen Behandlung mit dem Arzt abstimmen', 'Sürüntüden yaklaşık iki saat önce idrara çıkılmamalı, kadınlar adet günleri dışında gelmeli; antibakteriyel tedaviden sonraki bekleme süresi hekimle kararlaştırılmalı', 'The pathogens found are present in the examined material, but some of them also occur in people without any complaints. The link between the result and the symptoms is established by the doctor', 'Uzročnici koji se nađu prisutni su u ispitivanom materijalu, ali se dio njih sreće i kod osoba bez tegoba. Vezu nalaza sa simptomima utvrđuje ljekar', 'Узрочници који се нађу присутни су у испитиваном материјалу, али се дио њих среће и код особа без тегоба. Везу налаза са симптомима утврђује љекар', 'Найденные возбудители присутствуют в исследованном материале, но часть из них встречается и у людей без жалоб. Связь результата с симптомами устанавливает врач', 'Gefundene Erreger sind in der untersuchten Probe vorhanden, ein Teil von ihnen kommt jedoch auch bei Menschen ohne Beschwerden vor. Den Zusammenhang zwischen Befund und Symptomen stellt der Arzt her', 'Saptanan etkenler incelenen materyalde bulunmaktadır, ancak bunların bir kısmı şikayeti olmayan kişilerde de görülür. Sonuç ile belirtiler arasındaki bağlantıyı hekim kurar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'std-multiplex-6'), 'Six-parameter panel covering common causes of inflammation in the urinary and genital tract', 'Panel od šest parametara koji obuhvata česte uzročnike upala mokraćnih i polnih organa', 'Панел од шест параметара који обухвата честе узрочнике упала мокраћних и полних органа', 'Панель из шести показателей, охватывающая распространённых возбудителей воспалительных процессов мочеполовой системы', 'Panel mit sechs Parametern, das häufige Erreger von Entzündungen der Harn- und Geschlechtsorgane abdeckt', 'İdrar ve genital yolda iltihaba yol açan sık etkenleri kapsayan altı parametreli panel', 'From a single swab or urine sample the laboratory runs six PCR reactions in parallel and reports each parameter separately', 'Iz jednog brisa ili uzorka mokraće laboratorija paralelno postavlja šest PCR reakcija i izdaje nalaz za svaki parametar', 'Из једног бриса или узорка мокраће лабораторија паралелно поставља шест ПЦР реакција и издаје налаз за сваки параметар', 'Из одного мазка или порции мочи лаборатория параллельно ставит шесть реакций ПЦР и выдаёт ответ по каждому показателю', 'Aus einem Abstrich oder einer Urinprobe führt das Labor sechs PCR-Reaktionen parallel durch und weist jeden Parameter einzeln aus', 'Laboratuvar tek bir sürüntü veya idrar örneğinden altı PCR reaksiyonunu aynı anda çalışır ve her parametreyi ayrı bildirir', 'Chronic and recurring inflammation of the urogenital tract, testing before assisted reproduction procedures, examination of partners, follow-up after a course of treatment', 'Hronične i ponavljane upale mokraćno-polnog sistema, ispitivanje prije postupaka potpomognute oplodnje, pregled partnera, kontrola poslije završene terapije', 'Хроничне и понављане упале мокраћно-полног система, испитивање прије поступака потпомогнуте оплодње, преглед партнера, контрола послије завршене терапије', 'Хронические и повторяющиеся воспаления мочеполовой системы, обследование перед процедурами вспомогательной репродукции, обследование партнёров, контроль после курса лечения', 'Chronische und wiederkehrende Entzündungen im Urogenitaltrakt, Untersuchung vor Kinderwunschbehandlungen, Untersuchung der Partner, Kontrolle nach abgeschlossener Therapie', 'Ürogenital sistemin kronik ve tekrarlayan iltihapları, yardımcı üreme işlemleri öncesi inceleme, partnerlerin değerlendirilmesi, tedavi sonrası kontrol', 'Women should not be tested during menstruation and should avoid intercourse and vaginal products for a day, men should not urinate for about two hours before the swab', 'Žene se ne testiraju tokom menstruacije i dan ranije izbjegavaju odnose i vaginalne preparate, muškarci ne mokre oko dva sata prije uzimanja', 'Жене се не тестирају током менструације и дан раније избјегавају односе и вагиналне препарате, мушкарци не мокре око два сата прије узимања', 'Женщинам сдавать вне менструации, за сутки исключить интимные контакты и вагинальные средства, мужчинам не мочиться около двух часов до взятия', 'Frauen nicht während der Menstruation und einen Tag vorher ohne Geschlechtsverkehr und Vaginalpräparate, Männer etwa zwei Stunden vor der Entnahme nicht urinieren', 'Kadınlar adet döneminde test yaptırmamalı ve bir gün önce cinsel ilişki ile vajinal ürünlerden kaçınmalı, erkekler sürüntüden yaklaşık iki saat önce idrara çıkmamalı', 'Several positive parameters do not add up to a diagnosis: each is assessed separately, together with complaints and examination. Interpretation and further steps are decided by the doctor', 'Više pozitivnih parametara ne sabira se u dijagnozu: svaki se procjenjuje posebno, uz tegobe i pregled. Tumačenje i dalji postupak određuje ljekar', 'Више позитивних параметара не сабира се у дијагнозу: сваки се процјењује посебно, уз тегобе и преглед. Тумачење и даљи поступак одређује љекар', 'Сочетание нескольких положительных показателей не суммируется в диагноз: каждый оценивают отдельно, с учётом жалоб и осмотра. Трактовку и дальнейшую тактику определяет врач', 'Mehrere positive Parameter ergeben zusammen keine Diagnose: jeder wird einzeln bewertet, zusammen mit Beschwerden und Untersuchung. Deutung und weiteres Vorgehen legt der Arzt fest', 'Birden fazla pozitif parametre toplanarak tanıya dönüşmez: her biri şikayetler ve muayene ile birlikte ayrı ayrı değerlendirilir. Yorum ve sonraki adımlar hekime aittir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'std-multiplex-7'), 'The broadest panel of this series: seven urogenital pathogens checked in a single molecular test', 'Najširi panel u ovoj seriji: sedam uzročnika urogenitalnih infekcija provjerava se jednim molekularnim ispitivanjem', 'Најшири панел у овој серији: седам узрочника урогениталних инфекција провјерава се једним молекуларним испитивањем', 'Самая широкая панель этой серии: семь возбудителей урогенитальных инфекций проверяются одним молекулярным исследованием', 'Das breiteste Panel dieser Reihe: sieben urogenitale Erreger werden in einer einzigen molekularen Untersuchung geprüft', 'Bu serinin en geniş paneli: tek bir moleküler incelemeyle yedi ürogenital etken araştırılır', 'One swab from the genital mucosa or a urine sample is taken, and the laboratory determines the DNA of seven microorganisms in parallel', 'Uzima se jedan bris sluznice polnih puteva ili uzorak mokraće, a laboratorija paralelno određuje DNK sedam mikroorganizama', 'Узима се један брис слузнице полних путева или узорак мокраће, а лабораторија паралелно одређује ДНК седам микроорганизама', 'Берут один мазок со слизистой половых путей или порцию мочи, и лаборатория параллельно определяет ДНК семи микроорганизмов', 'Es wird ein Abstrich der Genitalschleimhaut oder eine Urinprobe entnommen, das Labor bestimmt die DNA von sieben Mikroorganismen parallel', 'Genital mukozadan tek bir sürüntü ya da idrar örneği alınır, laboratuvar yedi mikroorganizmanın DNA''sını aynı anda belirler', 'Non-specific or long-lasting complaints, work-up for infertility and recurrent pregnancy loss, testing after unprotected contact on a doctor''s referral, check before treating partners', 'Nespecifične ili dugotrajne tegobe, obrada zbog neplodnosti i ponavljanih gubitaka trudnoće, ispitivanje poslije nezaštićenog odnosa po uputu ljekara, provjera prije liječenja partnera', 'Неспецифичне или дуготрајне тегобе, обрада због неплодности и понављаних губитака трудноће, испитивање послије незаштићеног односа по упуту љекара, провјера прије лијечења партнера', 'Неспецифические или длительные жалобы, обследование при бесплодии и невынашивании беременности, обследование после незащищённого контакта по направлению врача, проверка перед лечением партнёров', 'Unspezifische oder lang anhaltende Beschwerden, Abklärung bei unerfülltem Kinderwunsch und wiederholten Fehlgeburten, Untersuchung nach ungeschütztem Kontakt auf ärztliche Überweisung, Kontrolle vor der Behandlung der Partner', 'Belirsiz veya uzun süren şikayetler, kısırlık ve tekrarlayan gebelik kayıplarının araştırılması, hekim yönlendirmesiyle korunmasız ilişki sonrası inceleme, partnerlerin tedavisi öncesi kontrol', 'Do not urinate for about two hours before the swab, women should come outside menstruation; for one day no intercourse, douching or vaginal preparations', 'Ne mokriti oko dva sata prije brisa, žene dolaze van menstruacije; jedan dan bez odnosa, ispiranja i vaginalnih preparata', 'Не мокрити око два сата прије бриса, жене долазе ван менструације; један дан без односа, испирања и вагиналних препарата', 'Не мочиться около двух часов перед мазком, женщинам приходить вне менструации; за сутки без интимных контактов, спринцеваний и вагинальных препаратов', 'Etwa zwei Stunden vor dem Abstrich nicht urinieren, Frauen außerhalb der Menstruation; einen Tag lang kein Geschlechtsverkehr, keine Spülungen und keine Vaginalpräparate', 'Sürüntüden yaklaşık iki saat önce idrara çıkılmamalı, kadınlar adet dönemi dışında gelmeli; bir gün boyunca cinsel ilişki, vajinal duş ve vajinal ilaç kullanılmamalı', 'A broad panel more often finds microorganisms that also belong to the normal flora, so a positive answer alone is not the same as an infection and does not automatically call for treatment. The doctor decides based on the result and the clinical picture', 'Širok panel češće nađe i mikroorganizme koji pripadaju uobičajenoj flori, pa pozitivan nalaz sam po sebi nije isto što i infekcija i ne znači automatski liječenje. Odluku donosi ljekar prema nalazu i kliničkoj slici', 'Широк панел чешће нађе и микроорганизме који припадају уобичајеној флори, па позитиван налаз сам по себи није исто што и инфекција и не значи аутоматски лијечење. Одлуку доноси љекар према налазу и клиничкој слици', 'Широкая панель чаще находит микроорганизмы, которые присутствуют и в норме, поэтому положительный ответ сам по себе не равен инфекции и не требует автоматического лечения. Решение принимает врач по результату и клинической картине', 'Ein breites Panel findet häufiger auch Mikroorganismen der normalen Flora, daher ist ein positiver Befund allein noch keine Infektion und bedeutet nicht automatisch eine Behandlung. Die Entscheidung trifft der Arzt anhand von Befund und klinischem Bild', 'Geniş paneller normal florada da bulunan mikroorganizmaları daha sık saptar, bu yüzden pozitif sonuç tek başına enfeksiyon demek değildir ve kendiliğinden tedavi gerektirmez. Kararı, sonuç ve klinik tabloya göre hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'stool-culture-salmonella-shigella-ecoli'), 'Targeted stool culture for Salmonella, Shigella and E. coli O157', 'Ciljana koprokultura na Salmonella, Shigella i E. coli O157', 'Циљана копрокултура на Салмонелла, Схигелла и Е. цоли О157', 'Целенаправленный посев кала на сальмонеллы, шигеллы и E. coli O157', 'Gezielte Stuhlkultur auf Salmonellen, Shigellen und E. coli O157', 'Salmonella, Shigella ve E. coli O157''ye yönelik hedefli gaita kültürü', 'A small portion of stool is collected in a sterile container, plated on selective media in the laboratory, and any colonies that grow are identified further', 'Mala količina stolice sakuplja se u sterilnu posudu, u laboratoriji se zasijava na selektivne podloge, a izrasle kolonije se dodatno identifikuju', 'Мала количина столице сакупља се у стерилну посуду, у лабораторији се засијава на селективне подлоге, а израсле колоније се додатно идентификују', 'Небольшую порцию кала собирают в стерильный контейнер, в лаборатории её засевают на селективные среды, а выросшие колонии дополнительно идентифицируют', 'Eine kleine Stuhlmenge wird in einem sterilen Gefäß gesammelt, im Labor auf Selektivnährböden ausgestrichen und gewachsene Kolonien werden weiter identifiziert', 'Az miktarda gaita steril kaba alınır, laboratuvarda seçici besiyerlerine ekilir ve üreyen koloniler ayrıca tanımlanır', 'Diarrhoea, including bloody diarrhoea, fever and abdominal pain after suspicious food, outbreaks of intestinal infection, testing of contacts, certificates for food handling and childcare work', 'Proliv, uključujući i onaj sa krvlju, povišena temperatura i bolovi u trbuhu poslije sumnjive hrane, epidemije crijevnih infekcija, ispitivanje kontakata, uvjerenja za rad sa hranom i u vrtićima', 'Пролив, укључујући и онај са крвљу, повишена температура и болови у трбуху послије сумњиве хране, епидемије цријевних инфекција, испитивање контаката, увјерења за рад са храном и у вртићима', 'Диарея, в том числе с кровью, лихорадка и боли в животе после подозрительной еды, вспышки кишечных инфекций, обследование контактных лиц, справки для работы с продуктами и в детских учреждениях', 'Durchfall, auch blutiger, Fieber und Bauchschmerzen nach verdächtigen Speisen, Ausbrüche von Darminfektionen, Untersuchung von Kontaktpersonen, Atteste für Lebensmittelberufe und Kinderbetreuung', 'Kanlı olanlar dahil ishal, şüpheli yiyecek sonrası ateş ve karın ağrısı, bağırsak enfeksiyonu salgınları, temaslıların taranması, gıda ve çocuk bakımı işleri için belge', 'Collect stool in a sterile container, if possible before antibacterial treatment starts; urine and toilet water must not get into the sample', 'Stolicu sakupiti u sterilnu posudu, po mogućnosti prije početka antibakterijske terapije; u uzorak ne smiju dospjeti mokraća ni voda iz šolje', 'Столицу сакупити у стерилну посуду, по могућности прије почетка антибактеријске терапије; у узорак не смију доспјети мокраћа ни вода из шоље', 'Кал собирают в стерильный контейнер, по возможности до начала антибактериального лечения; в образец не должны попасть моча и вода из унитаза', 'Stuhl in einem sterilen Gefäß sammeln, möglichst vor Beginn einer antibakteriellen Behandlung; Urin und Toilettenwasser dürfen nicht in die Probe gelangen', 'Gaita steril kaba, mümkünse antibakteriyel tedavi başlamadan önce alınmalı; örneğe idrar ve klozet suyu karışmamalı', 'Growth of one of these organisms may be related to an intestinal infection or to carriage without complaints, and a negative culture does not rule out other causes of diarrhoea. The doctor assesses the result together with the symptoms', 'Porast nekog od ovih mikroorganizama može biti povezan sa crijevnom infekcijom ili sa kliconoštvom bez tegoba, a negativna kultura ne isključuje druge uzroke proliva. Nalaz uz simptome procjenjuje ljekar', 'Пораст неког од ових микроорганизама може бити повезан са цријевном инфекцијом или са клицоноштвом без тегоба, а негативна култура не искључује друге узроке пролива. Налаз уз симптоме процјењује љекар', 'Рост одного из этих микроорганизмов может быть связан с кишечной инфекцией или с носительством без жалоб, а отрицательный посев не исключает другие причины диареи. Результат вместе с симптомами оценивает врач', 'Das Wachstum eines dieser Erreger kann mit einer Darminfektion oder mit beschwerdefreiem Trägertum zusammenhängen, und eine negative Kultur schließt andere Durchfallursachen nicht aus. Der Arzt bewertet den Befund zusammen mit den Symptomen', 'Bu mikroorganizmalardan birinin üremesi bağırsak enfeksiyonuyla ya da şikayetsiz taşıyıcılıkla ilişkili olabilir, negatif kültür ise ishalin diğer nedenlerini dışlamaz. Sonucu hekim belirtilerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'tb-test'), 'Laboratory test that checks for signs that the body has been in contact with the tuberculosis bacterium', 'Laboratorijski test koji provjerava znake da je organizam bio u kontaktu sa bacilom tuberkuloze', 'Лабораторијски тест који провјерава знаке да је организам био у контакту са бацилом туберкулозе', 'Лабораторный тест, который проверяет признаки контакта организма с микобактерией туберкулёза', 'Labortest, der nach Hinweisen darauf sucht, dass der Körper Kontakt mit dem Tuberkulosebakterium hatte', 'Vücudun tüberküloz basiliyle temas ettiğine dair belirtileri araştıran laboratuvar testi', 'Most often venous blood is drawn and the draw takes a few minutes; the exact method and material used should be confirmed with the laboratory when booking', 'Najčešće se uzima venska krv i samo uzimanje traje nekoliko minuta; tačnu metodu i materijal treba provjeriti sa laboratorijom prilikom zakazivanja', 'Најчешће се узима венска крв и само узимање траје неколико минута; тачну методу и материјал треба провјерити са лабораторијом приликом заказивања', 'Чаще всего берут кровь из вены, взятие занимает несколько минут; какой именно метод и материал использует лаборатория, уточняют при записи', 'Meist wird venöses Blut abgenommen, die Entnahme dauert einige Minuten; welche Methode und welches Material genau verwendet werden, klärt man bei der Terminvereinbarung mit dem Labor', 'Çoğunlukla venöz kan alınır ve işlem birkaç dakika sürer; hangi yöntem ve materyalin kullanıldığı randevu alırken laboratuvardan öğrenilir', 'Long-lasting cough, weight loss and night sweats, contact with someone who has tuberculosis, assessment before immunosuppressive therapy, occupational health checks and paperwork', 'Dugotrajan kašalj, gubitak tjelesne težine i noćno znojenje, kontakt sa oboljelim od tuberkuloze, procjena prije imunosupresivne terapije, sistematski pregledi i sređivanje dokumenata', 'Дуготрајан кашаљ, губитак тјелесне тежине и ноћно знојење, контакт са обољелим од туберкулозе, процјена прије имуносупресивне терапије, систематски прегледи и сређивање докумената', 'Длительный кашель, потеря веса и ночная потливость, контакт с больным туберкулёзом, обследование перед иммуносупрессивной терапией, медосмотры и оформление документов', 'Lang anhaltender Husten, Gewichtsverlust und Nachtschweiß, Kontakt zu einer an Tuberkulose erkrankten Person, Beurteilung vor immunsuppressiver Therapie, arbeitsmedizinische Untersuchungen und Behördengänge', 'Uzun süren öksürük, kilo kaybı ve gece terlemesi, tüberkülozlu biriyle temas, bağışıklığı baskılayan tedavi öncesi değerlendirme, işyeri sağlık kontrolleri ve resmi belgeler', 'No special preparation is usually needed, the appointment time is agreed with the laboratory', 'Posebna priprema obično nije potrebna, a termin se dogovara sa laboratorijom', 'Посебна припрема обично није потребна, а термин се договара са лабораторијом', 'Специальной подготовки обычно не требуется, время сдачи согласуют с лабораторией', 'Eine besondere Vorbereitung ist in der Regel nicht nötig, der Termin wird mit dem Labor abgestimmt', 'Genellikle özel bir hazırlık gerekmez, randevu saati laboratuvarla birlikte belirlenir', 'A positive result may be related to contact with the bacterium and does not by itself separate a past, latent or active infection. Further examination, including a chest X-ray, is arranged by the doctor', 'Pozitivan nalaz može biti povezan sa kontaktom sa bacilom i sam po sebi ne razdvaja preboljelu, latentnu i aktivnu infekciju. Dalju obradu, uključujući snimak pluća, određuje ljekar', 'Позитиван налаз може бити повезан са контактом са бацилом и сам по себи не раздваја пребољелу, латентну и активну инфекцију. Даљу обраду, укључујући снимак плућа, одређује љекар', 'Положительный результат может быть связан с контактом с микобактерией и сам по себе не разделяет перенесённую, скрытую и активную инфекцию. Дальнейшее обследование, включая снимок лёгких, назначает врач', 'Ein positives Ergebnis kann mit einem Kontakt mit dem Bakterium zusammenhängen und trennt für sich genommen eine durchgemachte, latente und aktive Infektion nicht. Die weitere Abklärung, einschließlich einer Röntgenaufnahme der Lunge, veranlasst der Arzt', 'Pozitif sonuç basille temasla ilişkili olabilir ve tek başına geçirilmiş, latent ve aktif enfeksiyonu birbirinden ayırmaz. Akciğer filmi dahil ileri incelemeleri hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'thrombophilia-folate-panel'), 'Genetic panel covering variants of genes involved in blood clotting together with variants of folate metabolism genes', 'Genetski panel koji obuhvata varijante gena povezanih sa zgrušavanjem krvi i varijante gena folatnog metabolizma', 'Генетски панел који обухвата варијанте гена повезаних са згрушавањем крви и варијанте гена фолатног метаболизма', 'Генетическая панель: варианты генов, связанных со свёртыванием крови, вместе с вариантами генов фолатного обмена', 'Genetisches Panel mit Varianten von Genen der Blutgerinnung sowie Varianten von Genen des Folatstoffwechsels', 'Kan pıhtılaşmasında rol alan genlerin varyantları ile folat metabolizması genlerinin varyantlarını kapsayan genetik panel', 'Venous blood or a buccal swab is taken and the DNA is analysed in the laboratory by PCR; the report lists the gene variants that were found', 'Uzima se venska krv ili bris sluznice obraza, a DNK se u laboratoriji obrađuje metodom PCR; nalaz navodi koje su varijante gena nađene', 'Узима се венска крв или брис слузнице образа, а ДНК се у лабораторији обрађује методом ПЦР; налаз наводи које су варијанте гена нађене', 'Берут кровь из вены или мазок со слизистой щеки, ДНК исследуют в лаборатории методом ПЦР; в заключении перечислены найденные варианты генов', 'Es wird venöses Blut oder ein Abstrich der Wangenschleimhaut entnommen und die DNA im Labor mittels PCR untersucht; der Befund listet die gefundenen Genvarianten auf', 'Venöz kan ya da yanak içinden sürüntü alınır, DNA laboratuvarda PCR yöntemiyle incelenir; raporda bulunan gen varyantları sıralanır', 'Referral from a haematologist, gynaecologist or geneticist: thrombosis at a young age, thrombosis in close relatives, repeated pregnancy losses, pregnancy planning, discussing hormonal therapy', 'Uput hematologa, ginekologa ili genetičara: tromboza u mladosti, tromboze kod bliskih srodnika, ponavljani gubici trudnoće, planiranje trudnoće, razgovor o hormonskoj terapiji', 'Упут хематолога, гинеколога или генетичара: тромбоза у младости, тромбозе код блиских сродника, понављани губици трудноће, планирање трудноће, разговор о хормонској терапији', 'Направление гематолога, гинеколога или генетика: тромбоз в молодом возрасте, тромбозы у близких родственников, повторные потери беременности, планирование беременности, обсуждение гормональной терапии', 'Überweisung durch Hämatologie, Gynäkologie oder Humangenetik: Thrombose in jungen Jahren, Thrombosen bei nahen Verwandten, wiederholte Fehlgeburten, Planung einer Schwangerschaft, Gespräch über eine Hormontherapie', 'Hematoloji, kadın hastalıkları veya genetik uzmanının yönlendirmesi: genç yaşta tromboz, yakın akrabalarda tromboz, tekrarlayan gebelik kayıpları, gebelik planlaması, hormon tedavisinin konuşulması', 'No preparation is needed, the sample can be taken at any time of day, and the result does not depend on food or on current medication', 'Priprema nije potrebna, uzorak se može uzeti u bilo koje doba dana, a nalaz ne zavisi od hrane ni od terapije koja je u toku', 'Припрема није потребна, узорак се може узети у било које доба дана, а налаз не зависи од хране ни од терапије која је у току', 'Подготовка не нужна, материал можно сдавать в любое время суток, результат не зависит от еды и от текущего лечения', 'Keine Vorbereitung nötig, die Probe kann zu jeder Tageszeit entnommen werden, das Ergebnis hängt weder von Mahlzeiten noch von der laufenden Behandlung ab', 'Hazırlık gerekmez, örnek günün herhangi bir saatinde alınabilir ve sonuç yemekten ya da sürmekte olan tedaviden etkilenmez', 'A gene variant that is found is a feature of the DNA, not a diagnosis: such variants also occur in people with no health problems at all. A geneticist or the treating doctor assesses what the result means together with the personal and family history', 'Nađena varijanta gena je osobina DNK, a ne dijagnoza: takve varijante sreću se i kod osoba bez ikakvih zdravstvenih tegoba. Značaj nalaza procjenjuje genetičar ili ljekar koji liječi, zajedno sa ličnom i porodičnom anamnezom', 'Нађена варијанта гена је особина ДНК, а не дијагноза: такве варијанте срећу се и код особа без икаквих здравствених тегоба. Значај налаза процјењује генетичар или љекар који лијечи, заједно са личном и породичном анамнезом', 'Найденный вариант гена — это особенность ДНК, а не диагноз: такие варианты встречаются и у людей без каких-либо проблем со здоровьем. Значение результата оценивает врач-генетик или лечащий врач вместе с личным и семейным анамнезом', 'Eine gefundene Genvariante ist ein Merkmal der DNA und keine Diagnose: solche Varianten kommen auch bei Menschen ohne jede gesundheitliche Auffälligkeit vor. Was der Befund bedeutet, beurteilt die Humangenetik oder die behandelnde Ärztin gemeinsam mit Eigen- und Familienanamnese', 'Bulunan gen varyantı DNA''ya ait bir özelliktir, tanı değildir: bu varyantlar hiçbir sağlık sorunu olmayan kişilerde de görülür. Sonucun anlamını genetik uzmanı veya tedaviyi yürüten hekim, kişisel ve aile öyküsüyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'trichomonas-rapid-test'), 'Examination of urogenital material for the protozoan Trichomonas vaginalis using a native microscopic preparation and a rapid antigen test', 'Ispitivanje urogenitalnog materijala na praživotinju Trichomonas vaginalis nativnim mikroskopskim preparatom i brzim testom na antigen', 'Испитивање урогениталног материјала на праживотињу Trichomonas vaginalis нативним микроскопским препаратом и брзим тестом на антиген', 'Проверка урогенитального материала на простейшее Trichomonas vaginalis нативным микроскопическим препаратом и быстрым тестом на антиген', 'Untersuchung von urogenitalem Material auf den Einzeller Trichomonas vaginalis mittels Nativpräparat und Antigen-Schnelltest', 'Ürogenital materyalde Trichomonas vaginalis adlı tek hücreli parazitin nativ mikroskobik preparat ve hızlı antijen testiyle araştırılması', 'A swab is taken from the vagina or urethra, part of the material is examined under the microscope straight away as a native preparation, and part is applied to a test cassette that gives an answer within minutes', 'Uzima se bris vagine ili uretre, dio materijala se odmah pregleda pod mikroskopom kao nativni preparat, a dio se nanosi na test kasetu koja daje odgovor za nekoliko minuta', 'Узима се брис вагине или уретре, дио материјала се одмах прегледа под микроскопом као нативни препарат, а дио се наноси на тест касету која даје одговор за неколико минута', 'Берут мазок из влагалища или уретры, часть материала сразу смотрят под микроскопом как нативный препарат, часть наносят на тест-кассету, которая даёт ответ за несколько минут', 'Es wird ein Abstrich aus Scheide oder Harnröhre entnommen, ein Teil wird sofort als Nativpräparat mikroskopiert, ein Teil auf eine Testkassette aufgetragen, die innerhalb weniger Minuten ein Ergebnis liefert', 'Vajina veya üretradan sürüntü alınır, materyalin bir kısmı hemen nativ preparat olarak mikroskopta incelenir, bir kısmı ise birkaç dakikada sonuç veren test kasetine uygulanır', 'Heavy or frothy discharge, itching and burning, discomfort when urinating, examination of a sexual partner, complaints that persist after treatment', 'Obilan ili pjenušav sekret, svrab i pečenje, nelagoda pri mokrenju, pregled polnog partnera, tegobe koje traju i poslije terapije', 'Обилан или пјенушав секрет, свраб и печење, нелагода при мокрењу, преглед полног партнера, тегобе које трају и послије терапије', 'Обильные или пенистые выделения, зуд и жжение, дискомфорт при мочеиспускании, обследование полового партнёра, жалобы, сохраняющиеся после лечения', 'Starker oder schaumiger Ausfluss, Juckreiz und Brennen, Beschwerden beim Wasserlassen, Untersuchung des Sexualpartners, Beschwerden, die nach einer Behandlung bestehen bleiben', 'Bol veya köpüklü akıntı, kaşıntı ve yanma, idrar yaparken rahatsızlık, cinsel partnerin incelenmesi, tedaviden sonra süren şikayetler', 'Women should not be tested during menstruation, men should not urinate for about two hours before the swab; avoid intercourse, douching and vaginal products for a day', 'Žene se ne testiraju tokom menstruacije, muškarci ne mokre oko dva sata prije uzimanja brisa; jedan dan izbjegavati odnose, ispiranja i vaginalne preparate', 'Жене се не тестирају током менструације, мушкарци не мокре око два сата прије узимања бриса; један дан избјегавати односе, испирања и вагиналне препарате', 'Женщинам сдавать вне менструации, мужчинам не мочиться около двух часов до взятия мазка; за сутки исключить интимные контакты, спринцевания и вагинальные средства', 'Frauen nicht während der Menstruation, Männer etwa zwei Stunden vor dem Abstrich nicht urinieren; einen Tag lang auf Geschlechtsverkehr, Spülungen und Vaginalpräparate verzichten', 'Kadınlar adet döneminde test yaptırmamalı, erkekler sürüntüden yaklaşık iki saat önce idrara çıkmamalı; bir gün cinsel ilişki, vajinal duş ve vajinal üründen kaçınılmalı', 'Motile protozoa under the microscope or a positive rapid test indicate that the pathogen is present in the material, while a negative answer with persisting complaints does not exclude other causes and may call for a PCR test. The decision is made by the doctor', 'Pokretne praživotinje pod mikroskopom ili pozitivan brzi test govore da je uzročnik prisutan u materijalu, a negativan odgovor uz tegobe koje traju ne isključuje druge uzroke i može tražiti PCR. Odluku donosi ljekar', 'Покретне праживотиње под микроскопом или позитиван брзи тест говоре да је узрочник присутан у материјалу, а негативан одговор уз тегобе које трају не искључује друге узроке и може тражити ПЦР. Одлуку доноси љекар', 'Подвижные простейшие под микроскопом или положительный быстрый тест говорят о присутствии возбудителя в материале, а отрицательный ответ при сохраняющихся жалобах не исключает других причин и может потребовать ПЦР. Решение принимает врач', 'Bewegliche Einzeller im Mikroskop oder ein positiver Schnelltest zeigen, dass der Erreger im Material vorhanden ist, ein negatives Ergebnis bei fortbestehenden Beschwerden schließt andere Ursachen nicht aus und kann eine PCR erforderlich machen. Die Entscheidung trifft der Arzt', 'Mikroskopta hareketli parazitlerin görülmesi ya da hızlı testin pozitif olması etkenin materyalde bulunduğunu gösterir, şikayetler sürerken negatif sonuç ise diğer nedenleri dışlamaz ve PCR gerektirebilir. Kararı hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ureaplasma-pcr'), 'Real-time PCR for ureaplasma DNA: the test detects the group as a whole, without separating the individual species', 'PCR u realnom vremenu na DNK ureaplazmi: test otkriva grupu u cjelini, bez razdvajanja pojedinačnih vrsta', 'ПЦР у реалном времену на ДНК уреаплазми: тест открива групу у цјелини, без раздвајања појединачних врста', 'ПЦР в реальном времени на ДНК уреаплазм: тест выявляет группу целиком, без разделения на отдельные виды', 'Real-Time-PCR auf Ureaplasmen-DNA: der Test erfasst die Gruppe als Ganzes, ohne die einzelnen Arten zu trennen', 'Üreaplazma DNA''sına yönelik gerçek zamanlı PCR: test grubu bir bütün olarak saptar, türleri birbirinden ayırmaz', 'A swab from the urethra or cervical canal, or the first portion of morning urine, is analysed in the laboratory', 'Bris uretre ili cervikalnog kanala ili prvi mlaz jutarnje mokraće obrađuje se u laboratoriji', 'Брис уретре или цервикалног канала или први млаз јутарње мокраће обрађује се у лабораторији', 'Мазок из уретры или цервикального канала либо первая порция утренней мочи, материал исследуют в лаборатории', 'Ein Abstrich aus Harnröhre oder Gebärmutterhalskanal oder die erste Portion des Morgenurins wird im Labor untersucht', 'Üretra veya servikal kanaldan sürüntü ya da sabah idrarının ilk kısmı laboratuvarda incelenir', 'Discharge and discomfort when urinating, testing when planning a pregnancy and during infertility work-up, examination of a partner, follow-up after treatment prescribed by a doctor', 'Sekret i nelagoda pri mokrenju, ispitivanje pri planiranju trudnoće i u obradi neplodnosti, pregled partnera, kontrola poslije terapije koju je odredio ljekar', 'Секрет и нелагода при мокрењу, испитивање при планирању трудноће и у обради неплодности, преглед партнера, контрола послије терапије коју је одредио љекар', 'Выделения и дискомфорт при мочеиспускании, обследование при планировании беременности и при бесплодии, обследование партнёра, контроль после назначенного врачом лечения', 'Ausfluss und Beschwerden beim Wasserlassen, Untersuchung bei Kinderwunsch und im Rahmen der Abklärung von Unfruchtbarkeit, Untersuchung des Partners, Kontrolle nach ärztlich verordneter Behandlung', 'Akıntı ve idrar yaparken rahatsızlık, gebelik planlaması ve kısırlık araştırması kapsamında inceleme, partnerin değerlendirilmesi, hekimin verdiği tedaviden sonra kontrol', 'Do not urinate for two to three hours before giving the swab or urine, women should come outside the days of menstruation; the doctor sets the interval after antibacterial medication', 'Ne mokriti dva do tri sata prije davanja brisa ili mokraće, žene dolaze van dana menstruacije; razmak poslije antibakterijskih lijekova određuje ljekar', 'Не мокрити два до три сата прије давања бриса или мокраће, жене долазе ван дана менструације; размак послије антибактеријских лијекова одређује љекар', 'Не мочиться 2–3 часа перед сдачей мазка или мочи, женщинам приходить вне дней менструации; срок после антибактериальных препаратов определяет врач', 'Zwei bis drei Stunden vor der Abgabe von Abstrich oder Urin nicht urinieren, Frauen außerhalb der Menstruationstage; den Abstand nach antibakteriellen Medikamenten legt der Arzt fest', 'Sürüntü veya idrar vermeden iki üç saat önce idrara çıkılmamalı, kadınlar adet günleri dışında gelmeli; antibakteriyel ilaçlardan sonraki bekleme süresini hekim belirler', 'A positive result means ureaplasmas are present in the sample; they also occur in people without complaints, so the result is not interpreted apart from the symptoms. Whether anything needs to be done next is decided by the doctor', 'Pozitivan nalaz znači da su ureaplazme prisutne u uzorku; nalaze se i kod osoba bez tegoba, pa se nalaz ne tumači odvojeno od simptoma. Da li je potrebno nešto dalje činiti, odlučuje ljekar', 'Позитиван налаз значи да су уреаплазме присутне у узорку; налазе се и код особа без тегоба, па се налаз не тумачи одвојено од симптома. Да ли је потребно нешто даље чинити, одлучује љекар', 'Положительный результат означает присутствие уреаплазм в пробе; они встречаются и у людей без жалоб, поэтому отдельно от симптомов результат не трактуют. Нужно ли что-то делать дальше, решает врач', 'Ein positives Ergebnis bedeutet, dass Ureaplasmen in der Probe vorhanden sind; sie kommen auch bei Menschen ohne Beschwerden vor, daher wird der Befund nicht losgelöst von den Symptomen gedeutet. Ob weitere Schritte nötig sind, entscheidet der Arzt', 'Pozitif sonuç örnekte üreaplazma bulunduğunu gösterir; bu bakteriler şikayeti olmayan kişilerde de bulunur, bu nedenle sonuç belirtilerden bağımsız yorumlanmaz. Sonraki adıma hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urine-culture-bacteria'), 'Microbiological culture of urine: the laboratory determines which bacteria grow in the sample and which antibiotics they are susceptible to', 'Mikrobiološka kultura mokraće: laboratorija utvrđuje koje bakterije rastu u uzorku i na koje su antibiotike osjetljive', 'Микробиолошка култура мокраће: лабораторија утврђује које бактерије расту у узорку и на које су антибиотике осјетљиве', 'Микробиологический посев мочи: лаборатория определяет, какие бактерии растут в образце и к каким антибиотикам они чувствительны', 'Mikrobiologische Urinkultur: das Labor bestimmt, welche Bakterien in der Probe wachsen und auf welche Antibiotika sie empfindlich sind', 'İdrarın mikrobiyolojik kültürü: laboratuvar örnekte hangi bakterilerin ürediğini ve hangi antibiyotiklere duyarlı olduğunu belirler', 'The patient collects a midstream portion of urine in a sterile container, the material is plated on culture media and the amount of bacterial growth is assessed', 'Pacijent sakuplja srednji mlaz mokraće u sterilnu posudu, materijal se zasijava na podloge i procjenjuje se količina izraslih bakterija', 'Пацијент сакупља средњи млаз мокраће у стерилну посуду, материјал се засијава на подлоге и процјењује се количина израслих бактерија', 'Пациент собирает среднюю порцию мочи в стерильный контейнер, материал засевают на питательные среды и оценивают количество выросших бактерий', 'Der Patient sammelt den Mittelstrahl des Urins in einem sterilen Gefäß, das Material wird auf Nährböden ausgestrichen und die Menge des Bakterienwachstums beurteilt', 'Hasta orta akım idrarını steril kaba toplar, materyal besiyerlerine ekilir ve üreyen bakteri miktarı değerlendirilir', 'Burning and frequent urination, pain in the lower abdomen or the lower back, recurrent urinary tract infections, monitoring in pregnancy and after a course of treatment, assessment before urological procedures', 'Pečenje i često mokrenje, bol u donjem dijelu trbuha ili u krstima, ponavljane infekcije mokraćnih puteva, praćenje u trudnoći i poslije završene terapije, provjera prije uroloških zahvata', 'Печење и често мокрење, бол у доњем дијелу трбуха или у крстима, понављане инфекције мокраћних путева, праћење у трудноћи и послије завршене терапије, провјера прије уролошких захвата', 'Жжение и учащённое мочеиспускание, боль внизу живота или в пояснице, повторяющиеся инфекции мочевых путей, контроль при беременности и после курса лечения, проверка перед урологическими вмешательствами', 'Brennen und häufiges Wasserlassen, Schmerzen im Unterbauch oder in der Flanke, wiederkehrende Harnwegsinfekte, Kontrolle in der Schwangerschaft und nach einer Behandlung, Abklärung vor urologischen Eingriffen', 'Yanma ve sık idrara çıkma, alt karın veya bel ağrısı, tekrarlayan idrar yolu enfeksiyonları, gebelikte ve tedavi sonrası izlem, ürolojik girişimler öncesi kontrol', 'Collect the midstream portion of the morning urine in a sterile container after washing the external genitals, before antibiotics are started or as agreed with the doctor, and deliver it to the laboratory quickly', 'Sakupiti srednji mlaz jutarnje mokraće u sterilnu posudu poslije pranja spoljašnjih genitalija, prije uvođenja antibiotika ili po dogovoru sa ljekarom, i brzo dostaviti u laboratoriju', 'Сакупити средњи млаз јутарње мокраће у стерилну посуду послије прања спољашњих гениталија, прије увођења антибиотика или по договору са љекаром, и брзо доставити у лабораторију', 'Собрать среднюю порцию утренней мочи в стерильный контейнер после гигиены наружных половых органов, до начала антибиотиков или по согласованию с врачом, и быстро доставить в лабораторию', 'Den Mittelstrahl des Morgenurins nach Reinigung des äußeren Genitalbereichs in einem sterilen Gefäß auffangen, vor Beginn von Antibiotika oder nach Absprache mit dem Arzt, und zügig ins Labor bringen', 'Sabah idrarının orta akımı, dış genital bölge temizlendikten sonra steril kaba alınmalı, antibiyotiğe başlamadan önce veya hekimle kararlaştırıldığı şekilde toplanmalı ve laboratuvara hızlıca ulaştırılmalı', 'Bacterial growth may reflect a urinary tract infection, asymptomatic bacteriuria or contamination of the sample during collection. The doctor assesses the finding and the susceptibility report', 'Porast bakterija može odražavati infekciju mokraćnih puteva, bakteriuriju bez tegoba ili zaprljanje uzorka pri sakupljanju. Nalaz i antibiogram procjenjuje ljekar', 'Пораст бактерија може одражавати инфекцију мокраћних путева, бактериурију без тегоба или запрљање узорка при сакупљању. Налаз и антибиограм процјењује љекар', 'Рост бактерий может отражать инфекцию мочевых путей, бессимптомную бактериурию или загрязнение пробы при сборе. Значение находки и антибиотикограммы оценивает врач', 'Bakterienwachstum kann einen Harnwegsinfekt, eine beschwerdefreie Bakteriurie oder eine Verunreinigung beim Sammeln widerspiegeln. Befund und Antibiogramm beurteilt der Arzt', 'Bakteri üremesi idrar yolu enfeksiyonunu, şikayetsiz bakteriüriyi ya da örnek alınırken bulaşmayı yansıtabilir. Sonucu ve antibiyogramı hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urine-fungi'), 'Urine culture for yeasts, most often of the Candida genus', 'Kultura mokraće na kvasnice, najčešće iz roda Candida', 'Култура мокраће на кваснице, најчешће из рода Candida', 'Посев мочи на дрожжевые грибы, чаще всего рода Candida', 'Urinkultur auf Hefepilze, meist der Gattung Candida', 'İdrarın, çoğunlukla Candida cinsi mayalara yönelik kültürü', 'A midstream urine sample is plated on special media for fungi and the growth is followed for longer than in a bacterial culture', 'Srednji mlaz mokraće zasijava se na posebne podloge za gljivice, a porast se prati duže nego kod bakteriološke kulture', 'Средњи млаз мокраће засијава се на посебне подлоге за гљивице, а пораст се прати дуже него код бактериолошке културе', 'Среднюю порцию мочи засевают на специальные среды для грибов и наблюдают рост дольше, чем при бактериальном посеве', 'Eine Mittelstrahlurinprobe wird auf spezielle Pilznährböden ausgestrichen und das Wachstum länger beobachtet als bei einer bakteriellen Kultur', 'Orta akım idrar örneği mantarlar için özel besiyerlerine ekilir ve üreme bakteri kültürüne göre daha uzun süre izlenir', 'Urinary complaints with a negative bacterial culture, long antibacterial therapy, diabetes mellitus, an indwelling urinary catheter, reduced immunity', 'Tegobe mokraćnih puteva uz negativnu bakteriološku kulturu, dugotrajna antibakterijska terapija, šećerna bolest, stalni urinarni kateter, oslabljen imunitet', 'Тегобе мокраћних путева уз негативну бактериолошку културу, дуготрајна антибактеријска терапија, шећерна болест, стални уринарни катетер, ослабљен имунитет', 'Жалобы со стороны мочевых путей при отрицательном бактериальном посеве, длительная антибактериальная терапия, сахарный диабет, постоянный мочевой катетер, сниженный иммунитет', 'Harnwegsbeschwerden bei negativer bakterieller Kultur, lange antibakterielle Therapie, Diabetes mellitus, dauerhafter Blasenkatheter, geschwächte Immunabwehr', 'Bakteri kültürü negatifken süren idrar yolu şikayetleri, uzun süreli antibakteriyel tedavi, şeker hastalığı, kalıcı idrar sondası, bağışıklığın zayıf olması', 'Collect a midstream urine sample in a sterile container after washing the external genitals, if possible before antifungal medication is started', 'Srednji mlaz mokraće sakupiti u sterilnu posudu poslije pranja spoljašnjih genitalija, po mogućnosti prije uvođenja antimikotika', 'Средњи млаз мокраће сакупити у стерилну посуду послије прања спољашњих гениталија, по могућности прије увођења антимикотика', 'Среднюю порцию мочи собрать в стерильный контейнер после гигиены наружных половых органов, по возможности до начала противогрибковых препаратов', 'Mittelstrahlurin nach Reinigung des äußeren Genitalbereichs in einem sterilen Gefäß auffangen, möglichst bevor Antimykotika begonnen werden', 'Orta akım idrarı, dış genital bölge temizlendikten sonra steril kaba, mümkünse mantar ilacı başlanmadan önce alınmalı', 'Growth of fungi may mean colonisation of the urinary tract or contamination of the sample, but also a fungal infection. The doctor distinguishes these situations from the complaints and other tests', 'Porast gljivica može značiti kolonizaciju mokraćnih puteva ili zaprljanje uzorka, ali i gljivičnu infekciju. Ove situacije razlikuje ljekar prema tegobama i drugim nalazima', 'Пораст гљивица може значити колонизацију мокраћних путева или запрљање узорка, али и гљивичну инфекцију. Ове ситуације разликује љекар према тегобама и другим налазима', 'Рост грибов может означать колонизацию мочевых путей или загрязнение пробы, но также и грибковую инфекцию. Различает эти ситуации врач по жалобам и другим анализам', 'Pilzwachstum kann eine Besiedlung der Harnwege oder eine Verunreinigung der Probe bedeuten, aber auch eine Pilzinfektion. Diese Situationen unterscheidet der Arzt anhand der Beschwerden und weiterer Befunde', 'Mantar üremesi idrar yollarında kolonizasyonu ya da örneğe bulaşmayı gösterebileceği gibi mantar enfeksiyonunu da gösterebilir. Bu durumları hekim şikayetlere ve diğer tetkiklere bakarak ayırt eder')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vaginal-discharge-dmp'), 'Combined examination of vaginal discharge: microscopy of a stained preparation plus culture of the material for bacteria and yeasts', 'Objedinjeno ispitivanje vaginalnog sekreta: mikroskopija obojenog preparata i zasijavanje materijala na bakterije i kvasnice', 'Обједињено испитивање вагиналног секрета: микроскопија обојеног препарата и засијавање материјала на бактерије и кваснице', 'Комплексное исследование вагинальных выделений: микроскопия окрашенного препарата и посев материала на бактерии и дрожжевые грибы', 'Kombinierte Untersuchung des Vaginalsekrets: Mikroskopie eines gefärbten Präparats und Anzucht des Materials auf Bakterien und Hefen', 'Vajinal akıntının birlikte değerlendirilmesi: boyalı preparatın mikroskopla incelenmesi ve materyalin bakteri ile mayalar için kültüre ekilmesi', 'A gynaecologist takes a swab from the vagina, part of the material is stained and examined under the microscope and part is plated on culture media, with a susceptibility test if growth appears', 'Ginekolog uzima bris vagine, dio materijala se boji i pregleda pod mikroskopom, a dio se zasijava na hranljive podloge, uz antibiogram ako dođe do porasta', 'Гинеколог узима брис вагине, дио материјала се боји и прегледа под микроскопом, а дио се засијава на хранљиве подлоге, уз антибиограм ако дође до пораста', 'Гинеколог берёт мазок из влагалища, часть материала окрашивают и смотрят под микроскопом, часть засевают на питательные среды, при росте выполняют антибиотикограмму', 'Die Frauenärztin entnimmt einen Abstrich aus der Scheide, ein Teil des Materials wird gefärbt und mikroskopiert, ein Teil auf Nährböden ausgestrichen, bei Wachstum folgt ein Antibiogramm', 'Jinekolog vajinadan sürüntü alır, materyalin bir kısmı boyanıp mikroskopta incelenir, bir kısmı besiyerlerine ekilir ve üreme olursa antibiyogram yapılır', 'Discharge with changed colour or smell, itching and burning, recurrent vaginal inflammation, testing when planning a pregnancy and before gynaecological procedures', 'Sekret promijenjene boje ili mirisa, svrab i pečenje, ponavljane upale vagine, ispitivanje pri planiranju trudnoće i prije ginekoloških zahvata', 'Секрет промијењене боје или мириса, свраб и печење, понављане упале вагине, испитивање при планирању трудноће и прије гинеколошких захвата', 'Выделения с изменённым цветом или запахом, зуд и жжение, повторяющиеся воспаления влагалища, обследование при планировании беременности и перед гинекологическими вмешательствами', 'Ausfluss mit verändertem Farbton oder Geruch, Juckreiz und Brennen, wiederkehrende Scheidenentzündungen, Untersuchung bei Kinderwunsch und vor gynäkologischen Eingriffen', 'Rengi veya kokusu değişmiş akıntı, kaşıntı ve yanma, tekrarlayan vajina iltihapları, gebelik planlarken ve jinekolojik girişimler öncesi inceleme', 'Attend outside menstruation, avoid intercourse, douching, vaginal suppositories and creams for a day; tell the doctor about any antibiotics taken', 'Dolaziti van menstruacije, jedan dan izbjegavati odnose, ispiranja, vaginalete i kreme; ljekaru reći o antibioticima koji se uzimaju', 'Долазити ван менструације, један дан избјегавати односе, испирања, вагиналете и креме; љекару рећи о антибиотицима који се узимају', 'Приходить вне менструации, за сутки исключить интимные контакты, спринцевания, вагинальные свечи и кремы; о приёме антибиотиков сообщить врачу', 'Außerhalb der Menstruation kommen, einen Tag lang auf Geschlechtsverkehr, Spülungen, Vaginalzäpfchen und Cremes verzichten; eingenommene Antibiotika dem Arzt mitteilen', 'Adet dönemi dışında gelinmeli, bir gün cinsel ilişki, vajinal duş, vajinal fitil ve kremlerden kaçınılmalı; kullanılan antibiyotikler hekime bildirilmeli', 'A shift in the flora or growth of certain microorganisms may be related to inflammation, but may also reflect a temporary change in the vaginal flora without complaints. Whether treatment is needed is decided by the gynaecologist from the result and the symptoms', 'Pomak u sastavu flore ili porast pojedinih mikroorganizama mogu biti povezani sa upalom, ali mogu odražavati i privremenu promjenu vaginalne flore bez tegoba. Da li je liječenje potrebno, procjenjuje ginekolog prema nalazu i simptomima', 'Помак у саставу флоре или пораст појединих микроорганизама могу бити повезани са упалом, али могу одражавати и привремену промјену вагиналне флоре без тегоба. Да ли је лијечење потребно, процјењује гинеколог према налазу и симптомима', 'Сдвиг в составе флоры или рост определённых микроорганизмов могут быть связаны с воспалением, а могут отражать временное изменение вагинальной флоры без жалоб. Нужно ли лечение, решает гинеколог по результату и симптомам', 'Eine Verschiebung der Flora oder das Wachstum bestimmter Mikroorganismen können mit einer Entzündung zusammenhängen, aber auch eine vorübergehende Veränderung der Scheidenflora ohne Beschwerden widerspiegeln. Ob eine Behandlung nötig ist, entscheidet die Frauenärztin anhand von Befund und Symptomen', 'Floradaki kayma ya da bazı mikroorganizmaların üremesi iltihapla ilişkili olabileceği gibi şikayet yaratmayan geçici bir flora değişimini de yansıtabilir. Tedavi gerekip gerekmediğine jinekolog sonuç ve belirtilere göre karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'wound-swab-aerobic-bacteria'), 'Culture of wound material under aerobic conditions, that is, for bacteria that need oxygen to grow', 'Zasijavanje materijala iz rane u aerobnim uslovima, dakle na bakterije kojima je za rast potreban kiseonik', 'Засијавање материјала из ране у аеробним условима, дакле на бактерије којима је за раст потребан кисеоник', 'Посев материала из раны в аэробных условиях, то есть на бактерии, которым для роста нужен кислород', 'Anzucht von Wundmaterial unter aeroben Bedingungen, also auf Bakterien, die zum Wachstum Sauerstoff brauchen', 'Yara materyalinin aerobik koşullarda, yani üremek için oksijene ihtiyaç duyan bakterilere yönelik kültürü', 'Material is taken with a sterile swab from the base and the edges of the wound, plated on media and incubated in the presence of oxygen, with a susceptibility test if growth appears', 'Sterilnim štapićem uzima se materijal sa dna i ivica rane, zasijava se na podloge i inkubira uz prisustvo kiseonika, a kod porasta se radi antibiogram', 'Стерилним штапићем узима се материјал са дна и ивица ране, засијава се на подлоге и инкубира уз присуство кисеоника, а код пораста се ради антибиограм', 'Стерильным тампоном берут материал со дна и краёв раны, засевают на среды и инкубируют в присутствии кислорода, при росте выполняют антибиотикограмму', 'Mit einem sterilen Tupfer wird Material vom Wundgrund und von den Wundrändern entnommen, auf Nährböden ausgestrichen und unter Sauerstoff bebrütet, bei Wachstum folgt ein Antibiogramm', 'Steril eküvyonla yaranın tabanından ve kenarlarından materyal alınır, besiyerlerine ekilir ve oksijenli ortamda inkübe edilir, üreme olursa antibiyogram yapılır', 'Purulent discharge and unpleasant smell, redness and swelling of the wound edges, postoperative and slow-healing wounds, ulcers and burn surfaces, selection of antibacterial treatment by the doctor', 'Gnojni sekret i neprijatan miris, crvenilo i otok ivica rane, postoperativne rane i rane koje sporo zarastaju, ulceracije i opekotinske površine, izbor antibakterijske terapije od strane ljekara', 'Гнојни секрет и непријатан мирис, црвенило и оток ивица ране, постоперативне ране и ране које споро зарастају, улцерације и опекотинске површине, избор антибактеријске терапије од стране љекара', 'Гнойное отделяемое и неприятный запах, покраснение и отёк краёв раны, послеоперационные и медленно заживающие раны, язвы и ожоговые поверхности, подбор антибактериального лечения врачом', 'Eitriges Sekret und unangenehmer Geruch, Rötung und Schwellung der Wundränder, postoperative und schlecht heilende Wunden, Geschwüre und Verbrennungsflächen, Auswahl der antibakteriellen Behandlung durch den Arzt', 'İrinli akıntı ve kötü koku, yara kenarlarında kızarıklık ve şişlik, ameliyat sonrası ve geç iyileşen yaralar, ülserler ve yanık yüzeyleri, hekimin antibakteriyel tedaviyi seçmesi', 'The dressing is removed immediately before sampling and the wound is not treated with antiseptics beforehand; any antibiotics already started should be reported to the laboratory', 'Zavoj se skida neposredno prije uzimanja, a rana se prethodno ne tretira antisepticima; o već započetim antibioticima obavijestiti laboratoriju', 'Завој се скида непосредно прије узимања, а рана се претходно не третира антисептицима; о већ започетим антибиотицима обавијестити лабораторију', 'Повязку снимают непосредственно перед взятием, рану перед этим не обрабатывают антисептиками; об уже начатых антибиотиках сообщают лаборатории', 'Der Verband wird unmittelbar vor der Entnahme abgenommen, die Wunde vorher nicht mit Antiseptika behandeln; bereits begonnene Antibiotika dem Labor mitteilen', 'Pansuman örnek alınmadan hemen önce açılır ve yara öncesinde antiseptikle temizlenmez; başlanmış antibiyotikler laboratuvara bildirilmelidir', 'Growth of aerobic bacteria may reflect wound infection or colonisation without inflammation, and some pathogens grow only without oxygen and are not covered by this culture. The treating doctor assesses the result', 'Porast aerobnih bakterija može odražavati infekciju rane ili kolonizaciju bez upale, a dio uzročnika raste samo bez kiseonika i ne ulazi u ovu kulturu. Nalaz procjenjuje ljekar koji liječi', 'Пораст аеробних бактерија може одражавати инфекцију ране или колонизацију без упале, а дио узрочника расте само без кисеоника и не улази у ову културу. Налаз процјењује љекар који лијечи', 'Рост аэробных бактерий может отражать инфекцию раны или колонизацию без воспаления, а часть возбудителей растёт только без кислорода и в этот посев не попадает. Результат оценивает лечащий врач', 'Das Wachstum aerober Bakterien kann eine Wundinfektion oder eine Besiedlung ohne Entzündung widerspiegeln, und ein Teil der Erreger wächst nur ohne Sauerstoff und wird von dieser Kultur nicht erfasst. Den Befund beurteilt der behandelnde Arzt', 'Aerobik bakteri üremesi yara enfeksiyonunu ya da iltihapsız kolonizasyonu yansıtabilir, bazı etkenler ise yalnızca oksijensiz ortamda ürediği için bu kültüre girmez. Sonucu tedaviyi yürüten hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-bilateral-testis-biopsies'), 'Microscopic examination of tissue samples from both testicles taken by biopsy', 'Mikroskopski pregled isječaka tkiva oba testisa uzetih biopsijom', 'Микроскопски преглед исјечака ткива оба тестиса узетих биопсијом', 'Микроскопическое исследование фрагментов ткани обоих яичек, взятых при биопсии', 'Mikroskopische Untersuchung von Gewebeproben aus beiden Hoden, die per Biopsie entnommen wurden', 'Biyopsiyle alınan her iki testis dokusu örneğinin mikroskopla incelenmesi', 'The sample from each side is labelled separately, fixed, embedded in paraffin, cut into thin sections and stained; the pathologist assesses the seminiferous tubules and the stage at which sperm maturation stops. The biopsy itself is performed separately by a urologist under anaesthesia', 'Uzorak sa svake strane posebno se obilježava, fiksira, ukalupljuje u parafin, reže na tanke presjeke i boji; patolog procjenjuje stanje sjemenih kanalića i u kojoj se fazi zaustavlja sazrijevanje spermatozoida. Samu biopsiju urolog radi zasebno, uz anesteziju', 'Узорак са сваке стране посебно се обиљежава, фиксира, укалупљује у парафин, реже на танке пресјеке и боји; патолог процјењује стање сјемених каналића и у којој се фази зауставља сазријевање сперматозоида. Саму биопсију уролог ради засебно, уз анестезију', 'Образец с каждой стороны маркируют отдельно, фиксируют, заливают в парафин, режут на тонкие срезы и окрашивают; патолог оценивает состояние семенных канальцев и то, на какой стадии останавливается созревание сперматозоидов. Саму биопсию уролог выполняет отдельно, под обезболиванием', 'Die Probe jeder Seite wird getrennt beschriftet, fixiert, in Paraffin eingebettet, in dünne Schnitte geschnitten und gefärbt; beurteilt werden die Samenkanälchen und die Stufe, auf der die Samenzellreifung stehen bleibt. Die Biopsie selbst nimmt die Urologin oder der Urologe gesondert unter Betäubung vor', 'Her iki taraftan alınan örnek ayrı ayrı etiketlenir, tespit edilir, parafine gömülür, ince kesitler alınır ve boyanır; patoloji uzmanı seminifer tübüllerin durumunu ve sperm olgunlaşmasının hangi aşamada durduğunu değerlendirir. Biyopsiyi üroloji hekimi anestezi altında ayrıca yapar', 'Absence of sperm in the ejaculate, clarifying the cause of male infertility, preparation for assisted reproduction, assessment of tissue in an undescended testicle, a persistent lump in the testicle', 'Odsustvo spermatozoida u ejakulatu, razjašnjenje uzroka muške neplodnosti, priprema za postupke potpomognute oplodnje, procjena tkiva kod nespuštenog testisa, uporna čvrsta promjena u testisu', 'Одсуство сперматозоида у ејакулату, разјашњење узрока мушке неплодности, припрема за поступке потпомогнуте оплодње, процјена ткива код неспуштеног тестиса, упорна чврста промјена у тестису', 'Отсутствие сперматозоидов в эякуляте, уточнение причины мужского бесплодия, подготовка к программам вспомогательной репродукции, оценка ткани при неопущенном яичке, стойкое уплотнение в яичке', 'Fehlen von Samenzellen im Ejakulat, Abklärung einer männlichen Unfruchtbarkeit, Vorbereitung auf Verfahren der assistierten Reproduktion, Gewebebeurteilung bei Hodenhochstand, anhaltende Verhärtung im Hoden', 'Menide sperm bulunmaması, erkek kısırlığının nedeninin araştırılması, yardımcı üreme tedavilerine hazırlık, inmemiş testiste doku değerlendirmesi, testiste geçmeyen sertlik', 'The material is taken during a procedure under anaesthesia: the urologist explains beforehand when to stop eating and what to do about medicines that affect blood clotting', 'Materijal se uzima tokom zahvata uz anesteziju: urolog unaprijed objašnjava kada se prestaje sa jelom i šta sa lijekovima koji utiču na zgrušavanje krvi', 'Материјал се узима током захвата уз анестезију: уролог унапријед објашњава када се престаје са јелом и шта са лијековима који утичу на згрушавање крви', 'Материал берут во время вмешательства под обезболиванием: режим приёма пищи накануне и вопрос о препаратах, влияющих на свёртывание крови, заранее обсуждает уролог', 'Das Material wird während eines Eingriffs unter Betäubung gewonnen: Wann die Nahrungsaufnahme endet und wie mit blutverdünnenden Medikamenten umzugehen ist, bespricht die Urologin oder der Urologe vorab', 'Örnek anestezi altında yapılan işlem sırasında alınır: yemeyi ne zaman keseceğiniz ve kan sulandırıcı ilaçların ne olacağı üroloji hekimiyle önceden konuşulur', 'The report describes whether sperm maturation is preserved, whether the picture is the same on both sides and whether there is scarring of the tissue. How this relates to the semen analysis and hormone levels, and what comes next, is decided by the urologist or andrologist', 'Nalaz opisuje da li je sazrijevanje spermatozoida očuvano, da li je slika ista sa obje strane i ima li ožiljnih promjena tkiva. Kako se to odnosi na spermogram i hormone i šta dalje, određuje urolog ili androlog', 'Налаз описује да ли је сазријевање сперматозоида очувано, да ли је слика иста са обје стране и има ли ожиљних промјена ткива. Како се то односи на спермограм и хормоне и шта даље, одређује уролог или андролог', 'Заключение описывает, сохранено ли созревание сперматозоидов, одинакова ли картина с двух сторон и есть ли рубцовые изменения ткани. Как это соотносится со спермограммой и гормонами и что делать дальше, определяет уролог или андролог', 'Der Befund beschreibt, ob die Samenzellreifung erhalten ist, ob das Bild auf beiden Seiten gleich ist und ob narbige Veränderungen vorliegen. Wie das zu Spermiogramm und Hormonwerten passt und wie es weitergeht, entscheidet die Urologin oder der Androloge', 'Rapor sperm olgunlaşmasının korunup korunmadığını, iki tarafın benzer olup olmadığını ve dokuda skar değişikliği bulunup bulunmadığını tanımlar. Bunun spermiyogram ve hormon sonuçlarıyla ilişkisine ve sonraki adımlara üroloji ya da androloji hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-brain-tumor-examination'), 'Microscopic examination of tissue from a brain lesion obtained during neurosurgery', 'Mikroskopski pregled tkiva promjene u mozgu dobijenog tokom neurohirurškog zahvata', 'Микроскопски преглед ткива промјене у мозгу добијеног током неурохируршког захвата', 'Микроскопическое исследование ткани объёмного образования головного мозга, полученной при нейрохирургическом вмешательстве', 'Mikroskopische Untersuchung von Gewebe einer Hirnraumforderung, das bei einer neurochirurgischen Operation gewonnen wurde', 'Beyin cerrahisi sırasında alınan beyin kitlesi dokusunun mikroskopla incelenmesi', 'The tissue is fixed, embedded in paraffin, sectioned and stained; immunohistochemistry and, where needed, molecular tests are usually added to establish the origin of the cells. Part of the material may be examined urgently during the operation itself', 'Tkivo se fiksira, ukalupljuje u parafin, reže i boji, a za utvrđivanje porijekla ćelija obično se dodaju imunohistohemijske, po potrebi i molekularne analize; dio materijala može se pregledati hitno, tokom same operacije', 'Ткиво се фиксира, укалупљује у парафин, реже и боји, а за утврђивање поријекла ћелија обично се додају имунохистохемијске, по потреби и молекуларне анализе; дио материјала може се прегледати хитно, током саме операције', 'Ткань фиксируют, заливают в парафин, режут и окрашивают, а для определения происхождения клеток обычно добавляют иммуногистохимические, при необходимости молекулярные исследования; часть материала может быть изучена срочно, прямо во время операции', 'Das Gewebe wird fixiert, in Paraffin eingebettet, geschnitten und gefärbt; zur Klärung der Zellherkunft kommen meist immunhistochemische und bei Bedarf molekulare Untersuchungen hinzu. Ein Teil des Materials kann noch während der Operation im Schnellschnitt beurteilt werden', 'Doku tespit edilir, parafine gömülür, kesitlenir ve boyanır; hücrelerin kökenini belirlemek için genellikle immünhistokimya, gerektiğinde moleküler incelemeler eklenir. Materyalin bir bölümü ameliyat sırasında acil olarak da incelenebilir', 'A lesion found on MRI or CT, material from a stereotactic biopsy, tissue after removal of a lesion, planning treatment according to the tissue type, repeat surgery when the imaging picture changes', 'Promjena viđena na magnetnoj rezonanci ili skeneru, materijal stereotaksijske biopsije, tkivo poslije uklanjanja promjene, planiranje liječenja prema vrsti tkiva, ponovni zahvat kada se slika na snimcima promijeni', 'Промјена виђена на магнетној резонанци или скенеру, материјал стереотаксијске биопсије, ткиво послије уклањања промјене, планирање лијечења према врсти ткива, поновни захват када се слика на снимцима промијени', 'Образование, выявленное на МРТ или КТ, материал стереотаксической биопсии, ткань после удаления образования, планирование лечения по типу ткани, повторное вмешательство при изменении картины на снимках', 'Im MRT oder CT entdeckte Raumforderung, Material einer stereotaktischen Biopsie, Gewebe nach Entfernung der Raumforderung, Therapieplanung nach Gewebetyp, erneuter Eingriff bei verändertem Bildbefund', 'MR ya da BT''de saptanan kitle, stereotaktik biyopsi materyali, kitlenin çıkarılmasından sonraki doku, doku tipine göre tedavi planlaması, görüntüleme bulgusu değiştiğinde yapılan yeni ameliyat', 'The material is obtained during neurosurgery, so the laboratory stage needs no separate preparation; how to prepare for the operation is explained by the neurosurgeon', 'Materijal se dobija tokom neurohirurškog zahvata, pa za laboratorijski dio nema posebne pripreme; pripremu za operaciju objašnjava neurohirurg', 'Материјал се добија током неурохируршког захвата, па за лабораторијски дио нема посебне припреме; припрему за операцију објашњава неурохирург', 'Материал получают во время нейрохирургического вмешательства, отдельной подготовки к лабораторному этапу нет; как готовиться к операции, объясняет нейрохирург', 'Das Material stammt aus der neurochirurgischen Operation, für den Laborteil ist keine gesonderte Vorbereitung nötig; die Vorbereitung auf die Operation erklärt die Neurochirurgin oder der Neurochirurg', 'Materyal beyin cerrahisi işlemi sırasında alınır, laboratuvar aşaması için ayrı hazırlık gerekmez; ameliyat hazırlığını beyin cerrahı anlatır', 'The pathologist describes the type of tissue, its origin and its degree of malignancy, which is one of the properties assessed. The report is read together with the imaging and the clinical picture, and further management is decided by the neurosurgeon and oncologist', 'Patolog opisuje vrstu tkiva, njegovo porijeklo i stepen malignosti, što je jedno od svojstava koja procjenjuje. Nalaz se čita zajedno sa snimcima i kliničkom slikom, a dalji postupak određuju neurohirurg i onkolog', 'Патолог описује врсту ткива, његово поријекло и степен малигности, што је једно од својстава која процјењује. Налаз се чита заједно са снимцима и клиничком сликом, а даљи поступак одређују неурохирург и онколог', 'Патолог описывает тип ткани, её происхождение и степень злокачественности — это одно из свойств, которые он оценивает. Заключение читают вместе со снимками и клинической картиной, дальнейшую тактику определяют нейрохирург и онколог', 'Beschrieben werden Gewebetyp, Herkunft und der Grad der Bösartigkeit als eine der beurteilten Eigenschaften. Der Befund wird gemeinsam mit den Bildern und dem klinischen Bild gelesen, das weitere Vorgehen legen Neurochirurgie und Onkologie fest', 'Patoloji uzmanı dokunun tipini, kökenini ve değerlendirdiği özelliklerden biri olan kötü huyluluk derecesini tanımlar. Rapor görüntüleme ve klinik tabloyla birlikte okunur, izlenecek yolu beyin cerrahı ve onkoloji hekimi belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-bronchoscopic-biopsy'), 'Microscopic examination of pieces of bronchial mucosa taken with forceps through a bronchoscope', 'Mikroskopski pregled komadića sluznice bronha uzetih kliještima kroz bronhoskop', 'Микроскопски преглед комадића слузнице бронха узетих клијештима кроз бронхоскоп', 'Микроскопическое исследование кусочков слизистой бронхов, взятых щипцами через бронхоскоп', 'Mikroskopische Untersuchung von Schleimhautstückchen der Bronchien, die mit einer Zange durch das Bronchoskop entnommen wurden', 'Bronkoskop içinden forsepsle alınan bronş mukozası parçalarının mikroskopla incelenmesi', 'The small fragments are placed in fixative immediately, embedded in paraffin, sectioned and stained; the pathologist assesses the bronchial lining, the type of inflammation and changes in the layer beneath it', 'Sitni isječci odmah se stavljaju u fiksativ, ukalupljuju u parafin, režu na presjeke i boje; patolog procjenjuje epitel bronha, prirodu upale i promjene u sloju ispod sluznice', 'Ситни исјечци одмах се стављају у фиксатив, укалупљују у парафин, режу на пресјеке и боје; патолог процјењује епител бронха, природу упале и промјене у слоју испод слузнице', 'Мелкие фрагменты сразу помещают в фиксатор, заливают в парафин, режут на срезы и окрашивают; патолог оценивает эпителий бронха, характер воспаления и изменения в подслизистом слое', 'Die kleinen Proben kommen sofort in Fixierlösung, werden in Paraffin eingebettet, geschnitten und gefärbt; beurteilt werden das Bronchialepithel, die Art der Entzündung und Veränderungen der darunterliegenden Schicht', 'Küçük parçalar hemen tespit solüsyonuna konur, parafine gömülür, kesitlenir ve boyanır; patoloji uzmanı bronş epitelini, iltihabın niteliğini ve mukoza altındaki tabakadaki değişiklikleri değerlendirir', 'A long-standing cough with no clear cause, blood in the sputum, changes on chest CT or X-ray, an altered area of mucosa seen during bronchoscopy, clarifying the cause of chronic airway inflammation', 'Dugotrajan kašalj bez jasnog uzroka, primjesa krvi u iskašljaju, promjene na skeneru ili rendgenu pluća, izmijenjen dio sluznice viđen tokom bronhoskopije, razjašnjenje uzroka hronične upale disajnih puteva', 'Дуготрајан кашаљ без јасног узрока, примјеса крви у искашљају, промјене на скенеру или рендгену плућа, измијењен дио слузнице виђен током бронхоскопије, разјашњење узрока хроничне упале дисајних путева', 'Длительный кашель без ясной причины, примесь крови в мокроте, изменения на КТ или рентгене лёгких, изменённый участок слизистой, увиденный при бронхоскопии, уточнение причины хронического воспаления дыхательных путей', 'Langer Husten ohne klare Ursache, Blut im Auswurf, Veränderungen im CT oder Röntgenbild der Lunge, ein auffälliger Schleimhautbezirk bei der Bronchoskopie, Abklärung einer chronischen Atemwegsentzündung', 'Nedeni açık olmayan uzun süreli öksürük, balgamda kan, akciğer BT ya da röntgeninde değişiklikler, bronkoskopide görülen değişmiş mukoza alanı, kronik hava yolu iltihabının nedeninin araştırılması', 'Preparation concerns the bronchoscopy: it is done on an empty stomach, and the doctor decides in advance what to do about medicines that affect blood clotting', 'Priprema se odnosi na bronhoskopiju: radi se natašte, a o lijekovima koji utiču na zgrušavanje krvi ljekar odlučuje unaprijed', 'Припрема се односи на бронхоскопију: ради се наташте, а о лијековима који утичу на згрушавање крви љекар одлучује унапријед', 'Подготовка относится к бронхоскопии: её выполняют натощак, а вопрос о препаратах, влияющих на свёртывание крови, заранее решает врач', 'Die Vorbereitung betrifft die Bronchoskopie: Sie erfolgt nüchtern, über blutverdünnende Medikamente entscheidet die Ärztin oder der Arzt vorab', 'Hazırlık bronkoskopiyle ilgilidir: işlem aç karnına yapılır, kan sulandırıcı ilaçlar konusunda hekim önceden karar verir', 'The report describes the nature of the changes in the bronchial lining, which may be related to inflammation, a reaction to irritants or a process that needs further investigation. The pulmonologist matches the result with the imaging and the symptoms', 'Nalaz opisuje prirodu promjena sluznice bronha, koje mogu biti povezane sa upalom, reakcijom na nadražaje ili procesom koji traži dodatnu obradu. Rezultat sa snimcima i tegobama poredi pulmolog', 'Налаз описује природу промјена слузнице бронха, које могу бити повезане са упалом, реакцијом на надражаје или процесом који тражи додатну обраду. Резултат са снимцима и тегобама пореди пулмолог', 'Заключение описывает характер изменений слизистой бронха: они могут быть связаны с воспалением, реакцией на раздражители или процессом, требующим дополнительного обследования. Сопоставляет результат со снимками и жалобами пульмонолог', 'Der Befund beschreibt die Art der Schleimhautveränderungen, die mit einer Entzündung, einer Reaktion auf Reizstoffe oder einem abklärungsbedürftigen Prozess zusammenhängen können. Die Pneumologie ordnet das Ergebnis den Bildern und den Beschwerden zu', 'Rapor bronş mukozasındaki değişikliklerin niteliğini tanımlar; bunlar iltihapla, tahriş edicilere yanıtla ya da ileri inceleme gerektiren bir süreçle ilişkili olabilir. Sonucu görüntüleme ve şikayetlerle birlikte göğüs hastalıkları hekimi değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-cervical-biopsy-and-curettage'), 'Microscopic examination of two specimens at once: a piece of cervical tissue and scrapings from the cervical canal', 'Mikroskopski pregled dva materijala odjednom: isječka tkiva grlića materice i materijala dobijenog kiretažom kanala grlića', 'Микроскопски преглед два материјала одједном: исјечка ткива грлића материце и материјала добијеног киретажом канала грлића', 'Микроскопическое исследование сразу двух материалов: кусочка ткани шейки матки и соскоба из её канала', 'Mikroskopische Untersuchung zweier Proben zugleich: eines Gewebestücks vom Gebärmutterhals und des Abradats aus dem Gebärmutterhalskanal', 'İki örneğin birlikte mikroskopla incelenmesi: rahim ağzından alınan doku parçası ve rahim ağzı kanalından küretajla alınan materyal', 'The specimens are labelled and processed separately, fixed, embedded in paraffin, sectioned and stained; the pathologist describes the outer part of the cervix and the lining of the canal, which cannot be seen at colposcopy, as two separate findings', 'Uzorci se posebno obilježavaju i obrađuju, fiksiraju, ukalupljuju u parafin, režu i boje; patolog odvojeno opisuje spoljašnji dio grlića i sluznicu kanala koja se na kolposkopiji ne vidi', 'Узорци се посебно обиљежавају и обрађују, фиксирају, укалупљују у парафин, режу и боје; патолог одвојено описује спољашњи дио грлића и слузницу канала која се на колпоскопији не види', 'Образцы маркируют и обрабатывают раздельно — фиксируют, заливают в парафин, режут и окрашивают; патолог отдельно описывает влагалищную часть шейки и слизистую канала, которая при кольпоскопии не видна', 'Die Proben werden getrennt beschriftet und bearbeitet, fixiert, in Paraffin eingebettet, geschnitten und gefärbt; der äußere Teil des Gebärmutterhalses und die bei der Kolposkopie nicht einsehbare Schleimhaut des Kanals werden getrennt befundet', 'Örnekler ayrı ayrı etiketlenip işlenir, tespit edilir, parafine gömülür, kesitlenir ve boyanır; patoloji uzmanı rahim ağzının dış yüzünü ve kolposkopide görülemeyen kanal mukozasını ayrı ayrı raporlar', 'An abnormal cytology smear when the changes extend into the cervical canal, colposcopy that does not show the border of the changes, a mismatch between the smear and the examination, follow-up after treatment of the cervix', 'Odstupanja u citološkom brisu kada promjene idu u kanal grlića, kolposkopija na kojoj se ne vidi granica promjena, neslaganje brisa i pregleda, kontrola poslije liječenja grlića materice', 'Одступања у цитолошком брису када промјене иду у канал грлића, колпоскопија на којој се не види граница промјена, неслагање бриса и прегледа, контрола послије лијечења грлића материце', 'Отклонения в цитологическом мазке, когда изменения уходят в канал шейки, кольпоскопия не позволяет увидеть их границу, расхождение между мазком и осмотром, контроль после лечения шейки матки', 'Auffälliger zytologischer Abstrich, wenn die Veränderungen in den Halskanal reichen, Kolposkopie ohne sichtbare Grenze der Veränderungen, Widerspruch zwischen Abstrich und Untersuchung, Kontrolle nach Behandlung am Gebärmutterhals', 'Değişikliklerin kanala uzandığı durumlarda anormal sitolojik yayma, değişikliklerin sınırının kolposkopiyle görülememesi, yayma ile muayenenin uyuşmaması, rahim ağzı tedavisi sonrası kontrol', 'The gynaecologist explains how to prepare for the procedure: it is usually planned outside menstruation, and vaginal products are avoided for a few days beforehand', 'Pripremu za zahvat objašnjava ginekolog: obično se planira van menstruacije, a nekoliko dana ranije ne koriste se vaginalna sredstva', 'Припрему за захват објашњава гинеколог: обично се планира ван менструације, а неколико дана раније не користе се вагинална средства', 'Подготовку к вмешательству объясняет гинеколог: обычно его планируют вне менструации и за несколько дней до него не используют вагинальные средства', 'Die Vorbereitung erklärt die Frauenärztin oder der Frauenarzt: Der Eingriff wird meist außerhalb der Regelblutung geplant, einige Tage zuvor werden vaginale Präparate weggelassen', 'İşleme hazırlığı kadın doğum hekimi anlatır: genellikle adet dışı bir güne planlanır, birkaç gün önceden vajinal ürünler kullanılmaz', 'The report states separately what was found on the surface of the cervix and what in its canal, from inflammatory changes to those needing follow-up or treatment. The gynaecologist interprets both specimens together', 'U nalazu je odvojeno navedeno šta je nađeno na površini grlića, a šta u njegovom kanalu, od upalnih promjena do onih koje traže praćenje ili liječenje. Oba uzorka zajedno tumači ginekolog', 'У налазу је одвојено наведено шта је нађено на површини грлића, а шта у његовом каналу, од упалних промјена до оних које траже праћење или лијечење. Оба узорка заједно тумачи гинеколог', 'В заключении отдельно указано, что найдено на поверхности шейки и что в её канале — от воспалительных изменений до тех, что требуют наблюдения или лечения. Результат по двум образцам вместе трактует гинеколог', 'Der Befund nennt getrennt, was an der Oberfläche des Gebärmutterhalses und was im Kanal gefunden wurde, von entzündlichen bis zu kontroll- oder behandlungsbedürftigen Veränderungen. Beide Proben zusammen deutet die Frauenärztin oder der Frauenarzt', 'Rapor rahim ağzı yüzeyinde ve kanalında bulunanları ayrı ayrı belirtir; bunlar iltihabi değişikliklerden izlem ya da tedavi gerektirenlere kadar uzanabilir. İki örneği birlikte kadın doğum hekimi yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-cervical-polyp-examination'), 'Microscopic examination of a cervical polyp removed during a gynaecological procedure', 'Mikroskopski pregled polipa grlića materice uklonjenog tokom ginekološkog zahvata', 'Микроскопски преглед полипа грлића материце уклоњеног током гинеколошког захвата', 'Микроскопическое исследование полипа шейки матки, удалённого при гинекологическом вмешательстве', 'Mikroskopische Untersuchung eines bei einem gynäkologischen Eingriff entfernten Polypen des Gebärmutterhalses', 'Jinekolojik işlemle çıkarılan rahim ağzı polibinin mikroskopla incelenmesi', 'The whole polyp is sent to the laboratory, fixed, embedded in paraffin, sectioned and stained; the pathologist assesses its structure, its glands, its stalk and any inflammation', 'Polip se u cjelini šalje u laboratoriju, fiksira, ukalupljuje u parafin, reže na presjeke i boji; patolog procjenjuje građu polipa, njegove žlijezde, peteljku i prisustvo upale', 'Полип се у цјелини шаље у лабораторију, фиксира, укалупљује у парафин, реже на пресјеке и боји; патолог процјењује грађу полипа, његове жлијезде, петељку и присуство упале', 'Полип направляют в лабораторию целиком, фиксируют, заливают в парафин, режут на срезы и окрашивают; патолог оценивает строение полипа, его железы, ножку и наличие воспаления', 'Der Polyp wird vollständig ins Labor gegeben, fixiert, in Paraffin eingebettet, geschnitten und gefärbt; beurteilt werden Aufbau, Drüsen, Stiel und eine mögliche Entzündung', 'Polip bütün olarak laboratuvara gönderilir, tespit edilir, parafine gömülür, kesitlenir ve boyanır; patoloji uzmanı polibin yapısını, bezlerini, sapını ve iltihap olup olmadığını değerlendirir', 'A polyp seen at examination or colposcopy, bleeding between periods or after intercourse, heavy discharge, planned removal of any growth on the cervix', 'Polip viđen pri pregledu ili kolposkopiji, krvarenje između menstruacija ili poslije odnosa, obilan sekret, planirano uklanjanje bilo koje promjene na grliću', 'Полип виђен при прегледу или колпоскопији, крварење између менструација или послије односа, обилан секрет, планирано уклањање било које промјене на грлићу', 'Полип, увиденный при осмотре или кольпоскопии, кровянистые выделения между менструациями или после контакта, обильные выделения, плановое удаление любого образования шейки', 'Bei Untersuchung oder Kolposkopie gesehener Polyp, Blutungen zwischen den Regelblutungen oder nach dem Geschlechtsverkehr, starker Ausfluss, geplante Entfernung einer Neubildung am Gebärmutterhals', 'Muayenede ya da kolposkopide görülen polip, adetler arasında veya ilişki sonrası kanama, bol akıntı, rahim ağzındaki herhangi bir oluşumun planlı çıkarılması', 'The material comes from the removal itself, so the laboratory stage needs no preparation; the gynaecologist explains how to prepare for the procedure', 'Materijal se dobija prilikom uklanjanja polipa, pa za laboratorijski dio nema pripreme; kako se pripremiti za sam zahvat, objašnjava ginekolog', 'Материјал се добија приликом уклањања полипа, па за лабораторијски дио нема припреме; како се припремити за сам захват, објашњава гинеколог', 'Материал получают при удалении полипа, отдельной подготовки к лабораторному этапу нет; как готовиться к самому вмешательству, объясняет гинеколог', 'Das Material stammt aus der Entfernung selbst, für den Laborteil ist nichts vorzubereiten; die Vorbereitung auf den Eingriff erklärt die Frauenärztin oder der Frauenarzt', 'Materyal polibin çıkarılması sırasında alınır, laboratuvar aşaması için hazırlık gerekmez; işleme nasıl hazırlanılacağını kadın doğum hekimi anlatır', 'The report describes the structure of the polyp, including any atypical changes, which the pathologist always looks for. Whether follow-up or further investigation is needed is decided by the gynaecologist from the report', 'Nalaz opisuje građu polipa, uključujući i prisustvo atipičnih promjena koje patolog obavezno procjenjuje. Da li je potrebna kontrola ili dodatna obrada, prema nalazu odlučuje ginekolog', 'Налаз описује грађу полипа, укључујући и присуство атипичних промјена које патолог обавезно процјењује. Да ли је потребна контрола или додатна обрада, према налазу одлучује гинеколог', 'Заключение описывает строение полипа, включая наличие атипичных изменений, которые патолог оценивает обязательно. Нужен ли контроль или дополнительное обследование, решает по заключению гинеколог', 'Der Befund beschreibt den Aufbau des Polypen einschließlich atypischer Veränderungen, auf die stets geachtet wird. Ob eine Kontrolle oder weitere Abklärung nötig ist, entscheidet anhand des Befunds die Frauenärztin oder der Frauenarzt', 'Rapor polibin yapısını, patoloji uzmanının her zaman aradığı atipik değişiklikler dahil olmak üzere tanımlar. Kontrol ya da ileri inceleme gerekip gerekmediğine rapora göre kadın doğum hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-colon-biopsy'), 'Microscopic examination of pieces of colon lining taken during colonoscopy', 'Mikroskopski pregled komadića sluznice debelog crijeva uzetih tokom kolonoskopije', 'Микроскопски преглед комадића слузнице дебелог цријева узетих током колоноскопије', 'Микроскопическое исследование кусочков слизистой толстой кишки, взятых при колоноскопии', 'Mikroskopische Untersuchung von Schleimhautproben des Dickdarms, die bei der Darmspiegelung entnommen wurden', 'Kolonoskopi sırasında alınan kalın bağırsak mukozası parçalarının mikroskopla incelenmesi', 'Fragments from different segments are labelled by site and processed separately: fixed, embedded in paraffin, sectioned and stained; the pathologist assesses the architecture of the crypts, the activity of inflammation and cellular changes', 'Isječci iz različitih dijelova crijeva obilježavaju se prema mjestu uzimanja i obrađuju odvojeno: fiksiraju se, ukalupljuju u parafin, režu i boje; patolog procjenjuje građu kripti, aktivnost upale i ćelijske promjene', 'Исјечци из различитих дијелова цријева обиљежавају се према мјесту узимања и обрађују одвојено: фиксирају се, укалупљују у парафин, режу и боје; патолог процјењује грађу крипти, активност упале и ћелијске промјене', 'Фрагменты из разных отделов кишки маркируют по месту взятия и обрабатывают порознь: фиксируют, заливают в парафин, режут и окрашивают; патолог оценивает строение крипт, активность воспаления и клеточные изменения', 'Die Proben aus verschiedenen Abschnitten werden nach Entnahmeort beschriftet und getrennt bearbeitet: fixiert, in Paraffin eingebettet, geschnitten und gefärbt; beurteilt werden der Aufbau der Krypten, die Aktivität der Entzündung und Zellveränderungen', 'Bağırsağın farklı bölümlerinden alınan parçalar alındığı yere göre etiketlenip ayrı işlenir: tespit edilir, parafine gömülür, kesitlenir ve boyanır; patoloji uzmanı kript yapısını, iltihabın aktifliğini ve hücresel değişiklikleri değerlendirir', 'Long-standing diarrhoea or unstable bowel habit, blood and mucus in the stool, diagnosis and monitoring of chronic inflammatory bowel disease, an altered area or polyp seen at colonoscopy, clarifying screening findings', 'Dugotrajan proliv ili nestabilna stolica, primjesa krvi i sluzi, postavljanje dijagnoze i praćenje hroničnih upalnih bolesti crijeva, izmijenjen dio ili polip viđen tokom kolonoskopije, razjašnjenje nalaza skrininga', 'Дуготрајан пролив или нестабилна столица, примјеса крви и слузи, постављање дијагнозе и праћење хроничних упалних болести цријева, измијењен дио или полип виђен током колоноскопије, разјашњење налаза скрининга', 'Длительный понос или неустойчивый стул, примесь крови и слизи, постановка диагноза и контроль хронических воспалительных заболеваний кишечника, изменённый участок или полип, увиденные при колоноскопии, уточнение находок скрининга', 'Anhaltender Durchfall oder wechselnder Stuhlgang, Blut und Schleim im Stuhl, Diagnose und Verlaufskontrolle chronisch entzündlicher Darmerkrankungen, ein auffälliger Bezirk oder Polyp bei der Darmspiegelung, Abklärung von Screening-Befunden', 'Uzun süren ishal ya da düzensiz dışkılama, dışkıda kan ve mukus, kronik iltihabi bağırsak hastalıklarının tanısı ve izlemi, kolonoskopide görülen değişmiş alan ya da polip, tarama bulgularının netleştirilmesi', 'Preparation concerns the colonoscopy: bowel cleansing according to the endoscopist''s instructions and light food the day before; the laboratory stage requires nothing', 'Priprema se odnosi na kolonoskopiju: čišćenje crijeva po uputstvu endoskopiste i laka hrana dan ranije; za laboratorijski dio nema pripreme', 'Припрема се односи на колоноскопију: чишћење цријева по упутству ендоскописте и лака храна дан раније; за лабораторијски дио нема припреме', 'Подготовка относится к колоноскопии: очищение кишечника по схеме эндоскописта и лёгкая еда накануне; для лабораторного этапа делать ничего не нужно', 'Die Vorbereitung betrifft die Darmspiegelung: Darmreinigung nach dem Schema der Endoskopie und leichte Kost am Vortag; für den Laborteil ist nichts zu tun', 'Hazırlık kolonoskopiyle ilgilidir: endoskopi hekiminin verdiği şemaya göre bağırsak temizliği ve bir gün önce hafif beslenme; laboratuvar aşaması için bir şey gerekmez', 'The report describes the type and activity of inflammation, changes in the glands and any dysplastic changes in a removed polyp. How often colonoscopy should be repeated and whether treatment is needed is decided by the gastroenterologist', 'Nalaz opisuje vrstu i aktivnost upale, promjene žlijezda i prisustvo displastičnih promjena u uklonjenom polipu. Koliko često ponavljati kolonoskopiju i da li je potrebno liječenje, odlučuje gastroenterolog', 'Налаз описује врсту и активност упале, промјене жлијезда и присуство диспластичних промјена у уклоњеном полипу. Колико често понављати колоноскопију и да ли је потребно лијечење, одлучује гастроентеролог', 'Заключение описывает тип и активность воспаления, изменения желёз и наличие диспластических изменений в удалённом полипе. Как часто повторять колоноскопию и нужно ли лечение, решает гастроэнтеролог', 'Der Befund beschreibt Art und Aktivität der Entzündung, Drüsenveränderungen und dysplastische Veränderungen in einem entfernten Polypen. Wie oft die Darmspiegelung zu wiederholen ist und ob eine Behandlung nötig ist, entscheidet die Gastroenterologie', 'Rapor iltihabın tipini ve aktifliğini, bez değişikliklerini ve çıkarılan polipteki displastik değişiklikleri tanımlar. Kolonoskopinin ne sıklıkta tekrarlanacağına ve tedavi gerekip gerekmediğine gastroenteroloji hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-conization-specimen'), 'Microscopic examination of the cone-shaped piece of cervix removed at conisation', 'Mikroskopski pregled konusnog isječka grlića materice uklonjenog konizacijom', 'Микроскопски преглед конусног исјечка грлића материце уклоњеног конизацијом', 'Микроскопическое исследование конусовидного фрагмента шейки матки, удалённого при конизации', 'Mikroskopische Untersuchung des bei der Konisation entfernten kegelförmigen Gewebestücks des Gebärmutterhalses', 'Konizasyonla çıkarılan koni biçimli rahim ağzı dokusunun mikroskopla incelenmesi', 'The cone is marked by orientation points, cut into consecutive blocks, embedded in paraffin and stained; the pathologist traces how deep the epithelial changes go and whether they reach the edges of the removed tissue', 'Konus se obilježava po orijentirima, reže na uzastopne dijelove, ukalupljuje u parafin i boji; patolog prati koliko duboko idu promjene epitela i da li dopiru do ivica uklonjenog tkiva', 'Конус се обиљежава по оријентирима, реже на узастопне дијелове, укалупљује у парафин и боји; патолог прати колико дубоко иду промјене епитела и да ли допиру до ивица уклоњеног ткива', 'Конус размечают по ориентирам, разрезают на последовательные фрагменты, заливают в парафин и окрашивают; патолог прослеживает, насколько глубоко идут изменения эпителия и доходят ли они до краёв удалённой ткани', 'Der Konus wird nach Markierungen orientiert, in fortlaufende Blöcke zerlegt, in Paraffin eingebettet und gefärbt; verfolgt wird, wie tief die Epithelveränderungen reichen und ob sie die Ränder des entfernten Gewebes erreichen', 'Koni işaret noktalarına göre yönlendirilir, ardışık parçalara ayrılır, parafine gömülür ve boyanır; patoloji uzmanı epitel değişikliklerinin ne kadar derine indiğini ve çıkarılan dokunun kenarlarına ulaşıp ulaşmadığını izler', 'High-grade epithelial changes of the cervix confirmed by biopsy, a mismatch between the cytology smear and the biopsy, changes extending into the cervical canal, situations where the procedure both removes the area and provides material for examination', 'Biopsijom potvrđene izražene promjene epitela grlića, neslaganje citološkog brisa i biopsije, promjene koje se šire u kanal grlića, situacije u kojima zahvat istovremeno uklanja promjenu i daje materijal za pregled', 'Биопсијом потврђене изражене промјене епитела грлића, неслагање цитолошког бриса и биопсије, промјене које се шире у канал грлића, ситуације у којима захват истовремено уклања промјену и даје материјал за преглед', 'Подтверждённые при биопсии выраженные изменения эпителия шейки, расхождение между цитологическим мазком и биопсией, изменения, уходящие в канал шейки, ситуации, когда вмешательство одновременно удаляет участок и даёт материал для исследования', 'Bioptisch gesicherte ausgeprägte Epithelveränderungen am Gebärmutterhals, Widerspruch zwischen Abstrich und Biopsie, in den Halskanal reichende Veränderungen, Situationen, in denen der Eingriff zugleich entfernt und Material liefert', 'Biyopsiyle doğrulanmış belirgin rahim ağzı epitel değişiklikleri, sitolojik yayma ile biyopsinin uyuşmaması, kanala uzanan değişiklikler, işlemin hem alanı çıkardığı hem de inceleme materyali sağladığı durumlar', 'Conisation is performed under anaesthesia, usually as a day-case: the gynaecologist explains when to stop eating and how the procedure is scheduled', 'Konizacija se radi uz anesteziju, najčešće u dnevnoj bolnici: kada se prestaje sa jelom i kako se zahvat zakazuje, objašnjava ginekolog', 'Конизација се ради уз анестезију, најчешће у дневној болници: када се престаје са јелом и како се захват заказује, објашњава гинеколог', 'Конизацию выполняют под обезболиванием, чаще в условиях дневного стационара: режим приёма пищи накануне и сроки вмешательства объясняет гинеколог', 'Die Konisation erfolgt unter Betäubung, meist ambulant im Tagesaufenthalt: Nüchternheit und Terminablauf erklärt die Frauenärztin oder der Frauenarzt', 'Konizasyon anestezi altında, çoğunlukla günübirlik yapılır: aç kalma süresini ve işlemin planını kadın doğum hekimi anlatır', 'The key part of the report is how pronounced the changes are and whether they reach the edges of the removed cone. This determines whether follow-up is enough or further steps are needed, a decision made by the gynaecologist', 'Ključni dio nalaza jeste koliko su promjene izražene i da li dopiru do ivica uklonjenog konusa. Od toga zavisi da li je dovoljno praćenje ili su potrebni dodatni koraci, a odluku donosi ginekolog', 'Кључни дио налаза јесте колико су промјене изражене и да ли допиру до ивица уклоњеног конуса. Од тога зависи да ли је довољно праћење или су потребни додатни кораци, а одлуку доноси гинеколог', 'Ключевая часть заключения — насколько выражены изменения и достигают ли они краёв удалённого конуса. От этого зависит, достаточно ли наблюдения или нужны дополнительные шаги; решение принимает гинеколог', 'Entscheidend im Befund ist, wie ausgeprägt die Veränderungen sind und ob sie die Schnittränder des Konus erreichen. Davon hängt ab, ob eine Kontrolle genügt oder weitere Schritte nötig sind, was die Frauenärztin oder der Frauenarzt festlegt', 'Raporun en önemli bölümü değişikliklerin ne kadar belirgin olduğu ve çıkarılan koninin kenarlarına ulaşıp ulaşmadığıdır. Buna göre izlemin yeterli olup olmadığına ya da ek adımlara kadın doğum hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-conization-specimen-with-curettage'), 'Microscopic examination of a conisation specimen together with scrapings from the remaining cervical canal or the uterine cavity', 'Mikroskopski pregled konizata zajedno sa materijalom dobijenim kiretažom preostalog dijela kanala grlića ili šupljine materice', 'Микроскопски преглед конизата заједно са материјалом добијеним киретажом преосталог дијела канала грлића или шупљине материце', 'Микроскопическое исследование конизата вместе с соскобом, взятым из оставшейся части канала шейки или полости матки', 'Mikroskopische Untersuchung des Konisationspräparats zusammen mit dem Abradat aus dem verbliebenen Halskanal oder der Gebärmutterhöhle', 'Konizasyon örneğinin, kalan rahim ağzı kanalından ya da rahim içinden küretajla alınan materyalle birlikte mikroskopla incelenmesi', 'The specimens are processed separately: the cone is cut according to its orientation marks and its edges are assessed, while the scrapings are examined on their own to see whether changes extend above the removed tissue', 'Materijali se obrađuju odvojeno: konus se reže po orijentirima i procjenjuju se njegove ivice, a materijal kiretaže pregleda se zasebno, da bi se vidjelo ima li promjena iznad granice uklonjenog tkiva', 'Материјали се обрађују одвојено: конус се реже по оријентирима и процјењују се његове ивице, а материјал киретаже прегледа се засебно, да би се видјело има ли промјена изнад границе уклоњеног ткива', 'Материалы обрабатывают раздельно: конус разрезают по ориентирам и оценивают его края, соскоб исследуют отдельно, чтобы понять, есть ли изменения выше границы удалённой ткани', 'Beide Materialien werden getrennt bearbeitet: Der Konus wird nach den Markierungen geschnitten und seine Ränder beurteilt, das Abradat wird für sich untersucht, um zu klären, ob Veränderungen oberhalb des entfernten Gewebes liegen', 'Materyaller ayrı ayrı işlenir: koni işaret noktalarına göre kesilip kenarları değerlendirilir, küretaj materyali ise çıkarılan dokunun üstünde değişiklik olup olmadığını görmek için ayrıca incelenir', 'Conisation for changes running up the cervical canal, the need to check the lining above the cone, cervical changes combined with abnormal bleeding, follow-up after earlier treatment', 'Konizacija kod promjena koje se šire naviše kroz kanal grlića, potreba da se provjeri sluznica iznad konusa, promjene grlića uz krvarenje, kontrola poslije ranije sprovedenog liječenja', 'Конизација код промјена које се шире навише кроз канал грлића, потреба да се провјери слузница изнад конуса, промјене грлића уз крварење, контрола послије раније спроведеног лијечења', 'Конизация при изменениях, уходящих вверх по каналу шейки, необходимость проверить слизистую выше конуса, сочетание изменений шейки с кровянистыми выделениями, контроль после ранее выполненного лечения', 'Konisation bei Veränderungen, die im Halskanal nach oben ziehen, Notwendigkeit die Schleimhaut oberhalb des Konus zu prüfen, Veränderungen am Gebärmutterhals zusammen mit Blutungen, Kontrolle nach früherer Behandlung', 'Kanal boyunca yukarı uzanan değişikliklerde konizasyon, koninin üstündeki mukozanın kontrol edilmesi gereği, rahim ağzı değişikliklerine kanamanın eşlik etmesi, daha önceki tedaviden sonra kontrol', 'Both specimens are obtained in a single procedure under anaesthesia; the gynaecologist explains the preparation, including when to stop eating', 'Oba materijala dobijaju se u jednom zahvatu uz anesteziju; pripremu, uključujući i kada se prestaje sa jelom, objašnjava ginekolog', 'Оба материјала добијају се у једном захвату уз анестезију; припрему, укључујући и када се престаје са јелом, објашњава гинеколог', 'Оба материала получают за одно вмешательство под обезболиванием; подготовку, включая режим приёма пищи, объясняет гинеколог', 'Beide Materialien entstehen in einem Eingriff unter Betäubung; die Vorbereitung einschließlich Nüchternheit erklärt die Frauenärztin oder der Frauenarzt', 'Her iki materyal de anestezi altında tek bir işlemde alınır; aç kalma dahil hazırlığı kadın doğum hekimi anlatır', 'The report shows both how pronounced the changes in the cone are together with the state of its edges, and the lining above it. The gynaecologist combines the two findings and decides on further management', 'Nalaz pokazuje i koliko su promjene u konusu izražene zajedno sa stanjem njegovih ivica, i sluznicu iznad njega. Cjelovitu sliku iz oba materijala i dalji postupak određuje ginekolog', 'Налаз показује и колико су промјене у конусу изражене заједно са стањем његових ивица, и слузницу изнад њега. Цјеловиту слику из оба материјала и даљи поступак одређује гинеколог', 'Заключение показывает и выраженность изменений в конусе вместе с состоянием его краёв, и слизистую выше него. Полную картину по двум материалам и дальнейшую тактику определяет гинеколог', 'Der Befund zeigt sowohl die Ausprägung der Veränderungen im Konus samt seinen Rändern als auch die Schleimhaut darüber. Das Gesamtbild aus beiden Materialien und das weitere Vorgehen legt die Frauenärztin oder der Frauenarzt fest', 'Rapor hem konideki değişikliklerin belirginliğini ve kenarların durumunu hem de üstteki mukozayı gösterir. İki materyalin birlikte verdiği tabloyu ve sonraki adımları kadın doğum hekimi belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-consultation'), 'Second review of existing slides and paraffin blocks by another pathologist', 'Ponovna procjena već urađenih stakalca i parafinskih blokova od strane drugog patologa', 'Поновна процјена већ урађених стакалца и парафинских блокова од стране другог патолога', 'Повторная оценка уже готовых стёкол и парафиновых блоков другим врачом-патологом', 'Zweitbeurteilung bereits angefertigter Objektträger und Paraffinblöcke durch eine weitere Pathologin oder einen weiteren Pathologen', 'Hazır lamların ve parafin bloklarının başka bir patoloji uzmanı tarafından yeniden değerlendirilmesi', 'The slides, blocks and a copy of the original report are sent to the laboratory; extra sections, stains or immunohistochemistry are added if needed, and no new material is taken from the patient', 'Laboratoriji se predaju stakalca, blokovi i kopija prvobitnog nalaza; po potrebi se rade dodatni presjeci, bojenja ili imunohistohemija, a novi materijal se od pacijenta ne uzima', 'Лабораторији се предају стакалца, блокови и копија првобитног налаза; по потреби се раде додатни пресјеци, бојења или имунохистохемија, а нови материјал се од пацијента не узима', 'В лабораторию передают стёкла, блоки и копию первичного заключения; при необходимости делают дополнительные срезы, окраски или иммуногистохимию, новый материал у пациента не берут', 'Objektträger, Blöcke und eine Kopie des Erstbefunds werden ins Labor gegeben; bei Bedarf kommen zusätzliche Schnitte, Färbungen oder Immunhistochemie hinzu, neues Material wird nicht entnommen', 'Laboratuvara lamlar, bloklar ve ilk raporun bir kopyası teslim edilir; gerekirse ek kesitler, boyamalar ya da immünhistokimya yapılır, hastadan yeni materyal alınmaz', 'A second opinion before starting treatment, a report that does not fit the clinical picture or the imaging, preparation for a multidisciplinary team meeting, continuing treatment in another clinic or country', 'Drugo mišljenje prije početka liječenja, neslaganje nalaza sa kliničkom slikom ili snimcima, priprema za konzilijum, nastavak liječenja u drugoj ustanovi ili državi', 'Друго мишљење прије почетка лијечења, неслагање налаза са клиничком сликом или снимцима, припрема за конзилијум, наставак лијечења у другој установи или држави', 'Второе мнение перед началом лечения, расхождение заключения с клинической картиной или снимками, подготовка к консилиуму, продолжение лечения в другой клинике или стране', 'Zweitmeinung vor Therapiebeginn, Befund, der nicht zum klinischen Bild oder zu den Aufnahmen passt, Vorbereitung auf eine Tumorkonferenz, Fortsetzung der Behandlung in einer anderen Klinik oder einem anderen Land', 'Tedaviye başlamadan önce ikinci görüş, raporun klinik tablo ya da görüntülerle uyuşmaması, konsey öncesi hazırlık, tedavinin başka bir merkezde ya da ülkede sürdürülmesi', 'All that is needed from the patient is the material: the slides and blocks are requested from the laboratory that did the original examination, together with a copy of the report', 'Od pacijenta je potreban samo materijal: stakalca i blokovi traže se u laboratoriji koja je uradila prvo ispitivanje, uz kopiju nalaza', 'Од пацијента је потребан само материјал: стакалца и блокови траже се у лабораторији која је урадила прво испитивање, уз копију налаза', 'От пациента нужны только материалы: стёкла и блоки запрашивают в лаборатории, где выполняли первичное исследование, вместе с копией заключения', 'Von der Patientin oder dem Patienten wird nur das Material benötigt: Objektträger und Blöcke werden im Labor der Erstuntersuchung angefordert, zusammen mit einer Kopie des Befunds', 'Hastadan yalnızca materyal istenir: lamlar ve bloklar, ilk incelemeyi yapan laboratuvardan rapor kopyasıyla birlikte talep edilir', 'The second report may confirm the original one, refine its wording or differ from it. What follows for treatment is decided by the treating doctor, if necessary together with a multidisciplinary team', 'Drugi nalaz može potvrditi prvobitni, precizirati njegovu formulaciju ili se od njega razlikovati. Šta iz toga slijedi za liječenje, određuje ljekar koji vodi liječenje, po potrebi zajedno sa konzilijumom', 'Други налаз може потврдити првобитни, прецизирати његову формулацију или се од њега разликовати. Шта из тога слиједи за лијечење, одређује љекар који води лијечење, по потреби заједно са конзилијумом', 'Повторное заключение может подтвердить первичное, уточнить его формулировку или разойтись с ней. Что из этого следует для лечения, определяет лечащий врач, при необходимости вместе с консилиумом', 'Der Zweitbefund kann den ersten bestätigen, seine Formulierung präzisieren oder davon abweichen. Was daraus für die Behandlung folgt, entscheidet die behandelnde Ärztin oder der behandelnde Arzt, bei Bedarf mit der Tumorkonferenz', 'İkinci rapor ilkini doğrulayabilir, ifadesini netleştirebilir ya da ondan farklı olabilir. Bunun tedavi açısından anlamını, gerekirse konseyle birlikte, tedaviyi yürüten hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-curettage'), 'Microscopic examination of scrapings of the uterine lining obtained by curettage', 'Mikroskopski pregled materijala sluznice šupljine materice dobijenog kiretažom', 'Микроскопски преглед материјала слузнице шупљине материце добијеног киретажом', 'Микроскопическое исследование соскоба слизистой полости матки, полученного при выскабливании', 'Mikroskopische Untersuchung des bei einer Ausschabung gewonnenen Abradats der Gebärmutterschleimhaut', 'Küretajla alınan rahim içi mukoza materyalinin mikroskopla incelenmesi', 'All of the tissue is fixed, embedded in paraffin, sectioned and stained; the pathologist assesses the structure of the endometrium, how it matches the phase of the cycle, and signs of inflammation or overgrowth', 'Dobijeno tkivo se u cjelini fiksira, ukalupljuje u parafin, reže na presjeke i boji; patolog procjenjuje građu endometrijuma, njegovu usklađenost sa fazom ciklusa, znake upale i bujanja', 'Добијено ткиво се у цјелини фиксира, укалупљује у парафин, реже на пресјеке и боји; патолог процјењује грађу ендометријума, његову усклађеност са фазом циклуса, знаке упале и бујања', 'Полученную ткань целиком фиксируют, заливают в парафин, режут на срезы и окрашивают; патолог оценивает строение эндометрия, его соответствие фазе цикла, признаки воспаления и разрастания', 'Das gesamte Gewebe wird fixiert, in Paraffin eingebettet, geschnitten und gefärbt; beurteilt werden der Aufbau der Gebärmutterschleimhaut, ihre Übereinstimmung mit der Zyklusphase sowie Zeichen von Entzündung oder Wucherung', 'Alınan dokunun tamamı tespit edilir, parafine gömülür, kesitlenir ve boyanır; patoloji uzmanı endometriyumun yapısını, döngünün evresine uygunluğunu, iltihap ve aşırı çoğalma belirtilerini değerlendirir', 'Heavy or irregular bleeding, a thickened endometrium on ultrasound, retained tissue after an interrupted or missed pregnancy, investigation of infertility, bleeding after the menopause', 'Obilna ili neredovna krvarenja, zadebljanje endometrijuma na ultrazvuku, zaostalo tkivo poslije prekinute ili zastale trudnoće, obrada kod neplodnosti, krvarenje u postmenopauzi', 'Обилна или нередовна крварења, задебљање ендометријума на ултразвуку, заостало ткиво послије прекинуте или застале трудноће, обрада код неплодности, крварење у постменопаузи', 'Обильные или нерегулярные кровотечения, утолщение эндометрия по УЗИ, задержка тканей после прерванной или замершей беременности, обследование при бесплодии, кровянистые выделения в постменопаузе', 'Starke oder unregelmäßige Blutungen, verdickte Gebärmutterschleimhaut im Ultraschall, zurückgebliebenes Gewebe nach abgebrochener oder verhaltener Schwangerschaft, Abklärung bei unerfülltem Kinderwunsch, Blutungen nach den Wechseljahren', 'Yoğun ya da düzensiz kanamalar, ultrasonda kalınlaşmış endometriyum, sonlanmış ya da durmuş gebelikten sonra kalan doku, kısırlık araştırması, menopoz sonrası kanama', 'Curettage is done under short anaesthesia: the gynaecologist explains when to stop eating the day before and on the day of the procedure', 'Kiretaža se radi uz kratkotrajnu anesteziju: kada se prestaje sa jelom dan ranije i na dan zahvata, objašnjava ginekolog', 'Киретажа се ради уз краткотрајну анестезију: када се престаје са јелом дан раније и на дан захвата, објашњава гинеколог', 'Выскабливание выполняют под кратковременным обезболиванием: режим приёма пищи накануне и в день вмешательства объясняет гинеколог', 'Die Ausschabung erfolgt in kurzer Narkose: Wann am Vortag und am Eingriffstag die Nahrungsaufnahme endet, erklärt die Frauenärztin oder der Frauenarzt', 'Küretaj kısa süreli anestezi altında yapılır: bir gün önce ve işlem günü yeme içmenin ne zaman kesileceğini kadın doğum hekimi anlatır', 'The report describes the state of the uterine lining: inflammation, hormone-related changes, a polyp, overgrowth or retained pregnancy tissue. What this means and whether treatment is needed is decided by the gynaecologist', 'Nalaz opisuje stanje sluznice materice: upalu, hormonski uslovljene promjene, polip, bujanje ili zaostalo tkivo trudnoće. Šta to znači i da li je potrebno liječenje, određuje ginekolog', 'Налаз описује стање слузнице материце: упалу, хормонски условљене промјене, полип, бујање или заостало ткиво трудноће. Шта то значи и да ли је потребно лијечење, одређује гинеколог', 'Заключение описывает состояние слизистой оболочки матки: воспаление, гормонально обусловленные изменения, полип, разрастание или остатки тканей беременности. Что это значит и нужно ли лечение, определяет гинеколог', 'Der Befund beschreibt den Zustand der Gebärmutterschleimhaut: Entzündung, hormonell bedingte Veränderungen, Polyp, Wucherung oder Reste von Schwangerschaftsgewebe. Was das bedeutet und ob behandelt werden muss, entscheidet die Frauenärztin oder der Frauenarzt', 'Rapor rahim içi mukozanın durumunu tanımlar: iltihap, hormona bağlı değişiklikler, polip, aşırı çoğalma ya da gebelik dokusu kalıntısı. Bunun anlamına ve tedavi gerekip gerekmediğine kadın doğum hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-cytology-smear'), 'Examination of cells from a smear under the microscope: the cells themselves are assessed, not the structure of the tissue', 'Pregled ćelija iz razmaza pod mikroskopom: procjenjuju se same ćelije, a ne građa tkiva', 'Преглед ћелија из размаза под микроскопом: процјењују се саме ћелије, а не грађа ткива', 'Исследование клеток из мазка под микроскопом: оценивают сами клетки, а не строение ткани', 'Untersuchung von Zellen aus einem Abstrich unter dem Mikroskop: beurteilt werden die Zellen selbst, nicht der Gewebeaufbau', 'Yaymadaki hücrelerin mikroskopla incelenmesi: doku yapısı değil, hücrelerin kendisi değerlendirilir', 'The material is spread in a thin layer on a slide, fixed and stained, and the doctor then studies the shape, size and nuclei of the cells; preparing the slide is simpler than for histology, and the material is not embedded in paraffin', 'Materijal se u tankom sloju nanosi na stakalce, fiksira i boji, a zatim se posmatraju oblik, veličina i jedra ćelija; priprema preparata je jednostavnija nego kod histološkog pregleda i tkivo se ne ukalupljuje u parafin', 'Материјал се у танком слоју наноси на стакалце, фиксира и боји, а затим се посматрају облик, величина и једра ћелија; припрема препарата је једноставнија него код хистолошког прегледа и ткиво се не укалупљује у парафин', 'Материал наносят тонким слоем на стекло, фиксируют и окрашивают, после чего врач изучает форму, размер и ядра клеток; подготовка препарата проще, чем при гистологическом исследовании, ткань в парафин не заливают', 'Das Material wird dünn auf einen Objektträger aufgetragen, fixiert und gefärbt, danach werden Form, Größe und Zellkerne beurteilt; die Präparation ist einfacher als bei der Histologie, eine Einbettung in Paraffin entfällt', 'Materyal lam üzerine ince bir tabaka hâlinde yayılır, tespit edilir ve boyanır, ardından hücrelerin biçimi, büyüklüğü ve çekirdekleri incelenir; preparat hazırlığı histolojik incelemeden daha basittir, doku parafine gömülmez', 'Screening and clarification of changes in mucous membranes, assessment of discharge, aspirates and fluids, material obtained with a fine needle, follow-up of previously found changes', 'Skrining i razjašnjenje promjena na sluznicama, procjena sekreta, punktata i tečnosti, materijal dobijen tankom iglom, kontrola ranije uočenih promjena', 'Скрининг и разјашњење промјена на слузницама, процјена секрета, пунктата и течности, материјал добијен танком иглом, контрола раније уочених промјена', 'Скрининг и уточнение изменений слизистых, оценка отделяемого, пунктатов и жидкостей, материал, полученный тонкой иглой, контроль после ранее выявленных изменений', 'Screening und Abklärung von Schleimhautveränderungen, Beurteilung von Sekreten, Punktaten und Flüssigkeiten, mit dünner Nadel gewonnenes Material, Kontrolle bereits bekannter Veränderungen', 'Mukoza değişikliklerinin taranması ve netleştirilmesi, akıntı, aspirat ve sıvıların değerlendirilmesi, ince iğneyle alınan materyal, daha önce saptanmış değişikliklerin kontrolü', 'Depends on where the smear is taken from: for gynaecological smears women are usually asked to come outside menstruation and to avoid vaginal products the day before, the rest is specified by the referring doctor', 'Zavisi od toga odakle se razmaz uzima: za ginekološke brisove obično se traži dolazak van menstruacije i da se dan ranije ne koriste vaginalna sredstva, ostalo precizira ljekar koji upućuje', 'Зависи од тога одакле се размаз узима: за гинеколошке брисове обично се тражи долазак ван менструације и да се дан раније не користе вагинална средства, остало прецизира љекар који упућује', 'Зависит от того, откуда берут мазок: для гинекологических мазков обычно просят прийти вне менструации и накануне не использовать вагинальные средства, остальное уточняет направивший врач', 'Hängt davon ab, woher der Abstrich stammt: Für gynäkologische Abstriche wird meist ein Termin außerhalb der Regelblutung empfohlen und am Vortag auf vaginale Präparate verzichtet, das Weitere sagt die überweisende Ärztin oder der überweisende Arzt', 'Yaymanın alındığı yere göre değişir: jinekolojik yaymalarda genellikle adet dışı bir güne gelinmesi ve bir gün önce vajinal ürün kullanılmaması istenir, gerisini yönlendiren hekim belirtir', 'Cytology shows the character of the cells and serves as a pointer, but does not replace examination of tissue: if the cells are unclear or worrying, the doctor usually orders a biopsy. The result is assessed by the referring doctor', 'Citologija pokazuje prirodu ćelija i služi kao orijentir, ali ne zamjenjuje pregled tkiva: kod nejasnih ili sumnjivih ćelija ljekar obično traži biopsiju. Rezultat procjenjuje ljekar koji je uputio na pregled', 'Цитологија показује природу ћелија и служи као оријентир, али не замјењује преглед ткива: код нејасних или сумњивих ћелија љекар обично тражи биопсију. Резултат процјењује љекар који је упутио на преглед', 'Цитология показывает характер клеток и служит ориентиром, но не заменяет исследование ткани: при неясных или настораживающих клетках врач обычно назначает биопсию. Результат оценивает направивший врач', 'Die Zytologie zeigt die Beschaffenheit der Zellen und gibt eine Richtung vor, ersetzt aber die Gewebeuntersuchung nicht: Bei unklaren oder auffälligen Zellen wird meist eine Biopsie veranlasst. Das Ergebnis beurteilt die überweisende Ärztin oder der überweisende Arzt', 'Sitoloji hücrelerin niteliğini gösterir ve yol gösterici olur, ancak doku incelemesinin yerini tutmaz: hücreler belirsiz ya da dikkat çekiciyse hekim genellikle biyopsi ister. Sonucu yönlendiren hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-duodenum-biopsy'), 'Microscopic examination of pieces of duodenal lining taken during gastroscopy', 'Mikroskopski pregled komadića sluznice dvanaestopalačnog crijeva uzetih tokom gastroskopije', 'Микроскопски преглед комадића слузнице дванаестопалачног цријева узетих током гастроскопије', 'Микроскопическое исследование кусочков слизистой двенадцатиперстной кишки, взятых при гастроскопии', 'Mikroskopische Untersuchung von Schleimhautproben des Zwölffingerdarms, die bei der Magenspiegelung entnommen wurden', 'Gastroskopi sırasında alınan onikiparmak bağırsağı mukozası parçalarının mikroskopla incelenmesi', 'Several small fragments are fixed, embedded in paraffin and oriented so that the villi are visible in the section, then stained; the pathologist assesses the height of the villi, the depth of the crypts and the number of lymphocytes in the epithelium', 'Nekoliko sitnih isječaka fiksira se, ukalupljuje u parafin i usmjerava tako da se u presjeku vide resice, a zatim boji; patolog procjenjuje visinu resica, dubinu kripti i broj limfocita u epitelu', 'Неколико ситних исјечака фиксира се, укалупљује у парафин и усмјерава тако да се у пресјеку виде ресице, а затим боји; патолог процјењује висину ресица, дубину крипти и број лимфоцита у епителу', 'Несколько мелких фрагментов фиксируют, заливают в парафин и ориентируют так, чтобы в срезе были видны ворсинки, затем окрашивают; патолог оценивает высоту ворсинок, глубину крипт и количество лимфоцитов в эпителии', 'Mehrere kleine Proben werden fixiert, in Paraffin eingebettet und so ausgerichtet, dass die Zotten im Schnitt sichtbar sind, danach gefärbt; beurteilt werden Zottenhöhe, Kryptentiefe und die Zahl der Lymphozyten im Epithel', 'Birkaç küçük parça tespit edilir, parafine gömülür ve kesitte villuslar görünecek biçimde yönlendirilir, ardından boyanır; patoloji uzmanı villusların boyunu, kriptlerin derinliğini ve epiteldeki lenfosit sayısını değerlendirir', 'Suspected gluten intolerance, long-standing diarrhoea and bloating, weight loss, unexplained iron and vitamin deficiency, monitoring of established coeliac disease', 'Sumnja na nepodnošenje glutena, dugotrajan proliv i nadutost, gubitak tjelesne težine, nedostatak gvožđa i vitamina bez jasnog uzroka, praćenje već potvrđene celijakije', 'Сумња на неподношење глутена, дуготрајан пролив и надутост, губитак тјелесне тежине, недостатак гвожђа и витамина без јасног узрока, праћење већ потврђене целијакије', 'Подозрение на непереносимость глютена, длительный понос и вздутие, снижение веса, дефицит железа и витаминов без объяснимой причины, наблюдение при уже установленной целиакии', 'Verdacht auf Glutenunverträglichkeit, anhaltender Durchfall und Blähungen, Gewichtsverlust, ungeklärter Eisen- und Vitaminmangel, Verlaufskontrolle bei gesicherter Zöliakie', 'Gluten intoleransı şüphesi, uzun süren ishal ve şişkinlik, kilo kaybı, nedeni bilinmeyen demir ve vitamin eksikliği, tanısı konmuş çölyak hastalığının izlemi', 'Preparation concerns the gastroscopy: it is done on an empty stomach, usually with no food from the evening before; if the examination was ordered because of suspected gluten intolerance, the diet is changed before sampling only on the doctor''s instruction', 'Priprema se odnosi na gastroskopiju: radi se natašte, obično se ne jede od večeri; ako je pregled zatražen zbog sumnje na nepodnošenje glutena, ishrana se prije uzimanja materijala mijenja samo po uputstvu ljekara', 'Припрема се односи на гастроскопију: ради се наташте, обично се не једе од вечери; ако је преглед затражен због сумње на неподношење глутена, исхрана се прије узимања материјала мијења само по упутству љекара', 'Подготовка относится к гастроскопии: её выполняют натощак, обычно не едят с вечера; если обследование назначено из-за подозрения на непереносимость глютена, питание до взятия материала меняют только по указанию врача', 'Die Vorbereitung betrifft die Magenspiegelung: Sie erfolgt nüchtern, meist ohne Essen ab dem Vorabend; wurde sie wegen Verdachts auf Glutenunverträglichkeit veranlasst, wird die Ernährung vor der Probenentnahme nur nach ärztlicher Anweisung umgestellt', 'Hazırlık gastroskopiyle ilgilidir: işlem aç karnına yapılır, genellikle akşamdan sonra yemek yenmez; inceleme gluten intoleransı şüphesiyle isteniyorsa, materyal alınmadan önce beslenme yalnızca hekimin talimatıyla değiştirilir', 'The report describes the state of the villi and inflammatory changes in the lining, which may be related to gluten intolerance, infection or other causes. The gastroenterologist matches them with the blood tests', 'Nalaz opisuje stanje resica i upalne promjene sluznice, koje mogu biti povezane sa nepodnošenjem glutena, infekcijom ili drugim uzrocima. Sa nalazima krvi poredi ih gastroenterolog', 'Налаз описује стање ресица и упалне промјене слузнице, које могу бити повезане са неподношењем глутена, инфекцијом или другим узроцима. Са налазима крви пореди их гастроентеролог', 'Заключение описывает состояние ворсинок и воспалительные изменения слизистой, которые могут быть связаны с непереносимостью глютена, инфекцией или другими причинами. Сопоставляет их с анализами крови гастроэнтеролог', 'Der Befund beschreibt den Zustand der Zotten und entzündliche Schleimhautveränderungen, die mit Glutenunverträglichkeit, einer Infektion oder anderen Ursachen zusammenhängen können. Die Gastroenterologie ordnet sie den Blutwerten zu', 'Rapor villusların durumunu ve mukozadaki iltihabi değişiklikleri tanımlar; bunlar gluten intoleransı, enfeksiyon ya da başka nedenlerle ilişkili olabilir. Kan sonuçlarıyla birlikte gastroenteroloji hekimi değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-endoscopic-biopsy'), 'Microscopic examination of a piece of mucosa taken through an endoscope; the organ it came from is stated on the request form', 'Mikroskopski pregled isječka sluznice uzetog kroz endoskop; organ iz kojeg je materijal uzet navodi se u uputu', 'Микроскопски преглед исјечка слузнице узетог кроз ендоскоп; орган из којег је материјал узет наводи се у упуту', 'Микроскопическое исследование фрагмента слизистой, взятого через эндоскоп; орган, из которого взят материал, указывают в направлении', 'Mikroskopische Untersuchung einer durch das Endoskop entnommenen Schleimhautprobe; das Organ der Entnahme wird auf der Überweisung angegeben', 'Endoskop aracılığıyla alınan mukoza parçasının mikroskopla incelenmesi; materyalin alındığı organ istek belgesinde belirtilir', 'The fragments taken with forceps through the endoscope channel are placed in fixative in the procedure room, then embedded in paraffin, sectioned and stained; samples from different sites are labelled by location', 'Isječci uzeti kliještima kroz kanal endoskopa stavljaju se u fiksativ još u sali, zatim se ukalupljuju u parafin, režu i boje; uzorci sa različitih mjesta obilježavaju se prema mjestu uzimanja', 'Исјечци узети клијештима кроз канал ендоскопа стављају се у фиксатив још у сали, затим се укалупљују у парафин, режу и боје; узорци са различитих мјеста обиљежавају се према мјесту узимања', 'Фрагменты, взятые щипцами через канал эндоскопа, помещают в фиксатор прямо в кабинете, затем заливают в парафин, режут и окрашивают; образцы из разных участков маркируют по месту взятия', 'Die mit der Zange durch den Arbeitskanal entnommenen Proben kommen bereits im Untersuchungsraum in Fixierlösung, danach werden sie in Paraffin eingebettet, geschnitten und gefärbt; Proben verschiedener Stellen werden nach Entnahmeort beschriftet', 'Endoskobun kanalından forsepsle alınan parçalar daha işlem odasında tespit solüsyonuna konur, sonra parafine gömülür, kesitlenir ve boyanır; farklı bölgelerden alınan örnekler alındığı yere göre etiketlenir', 'An altered area of mucosa seen at gastroscopy, colonoscopy, bronchoscopy or cystoscopy, clarifying the cause of chronic inflammation, assessment of a growth, obtaining material for additional tests', 'Izmijenjen dio sluznice viđen pri gastroskopiji, kolonoskopiji, bronhoskopiji ili cistoskopiji, razjašnjenje uzroka hronične upale, procjena promjene, uzimanje materijala za dodatna ispitivanja', 'Измијењен дио слузнице виђен при гастроскопији, колоноскопији, бронхоскопији или цистоскопији, разјашњење узрока хроничне упале, процјена промјене, узимање материјала за додатна испитивања', 'Изменённый участок слизистой, увиденный при гастроскопии, колоноскопии, бронхоскопии или цистоскопии, уточнение причины хронического воспаления, оценка образования, взятие материала для дополнительных исследований', 'Auffälliger Schleimhautbezirk bei Magen-, Darm-, Bronchien- oder Blasenspiegelung, Abklärung einer chronischen Entzündung, Beurteilung einer Neubildung, Materialgewinnung für weitere Untersuchungen', 'Gastroskopi, kolonoskopi, bronkoskopi ya da sistoskopide görülen değişmiş mukoza alanı, kronik iltihabın nedeninin araştırılması, bir oluşumun değerlendirilmesi, ek incelemeler için materyal alınması', 'Determined by the type of endoscopy: for the upper tract no food from the evening before, for colonoscopy the bowel is cleansed according to the doctor''s instructions; the laboratory stage requires nothing from the patient', 'Zavisi od vrste endoskopije: prije pregleda gornjih partija ne jede se od večeri, prije kolonoskopije crijevo se čisti po uputstvu ljekara; za laboratorijski dio od pacijenta se ne traži ništa', 'Зависи од врсте ендоскопије: прије прегледа горњих партија не једе се од вечери, прије колоноскопије цријево се чисти по упутству љекара; за лабораторијски дио од пацијента се не тражи ништа', 'Определяется тем, какую эндоскопию выполняют: перед исследованием верхних отделов не едят с вечера, перед колоноскопией кишечник очищают по схеме врача; на лабораторном этапе от пациента ничего не требуется', 'Richtet sich nach der Art der Spiegelung: vor Untersuchungen des oberen Verdauungstrakts ab dem Vorabend nichts essen, vor der Darmspiegelung Darmreinigung nach ärztlichem Schema; für den Laborteil ist nichts zu tun', 'Yapılan endoskopinin türüne göre belirlenir: üst sindirim sistemi incelemesinden önce akşamdan sonra yemek yenmez, kolonoskopiden önce bağırsak hekimin şemasına göre temizlenir; laboratuvar aşamasında hastadan bir şey istenmez', 'The report describes the structure of the mucosa and the nature of the changes: inflammatory, reactive or requiring further investigation. The referring doctor interprets it together with the endoscopic picture', 'Nalaz opisuje građu sluznice i prirodu promjena: upalnih, reaktivnih ili onih koje traže dalju obradu. Tumači ga zajedno sa slikom same endoskopije ljekar koji je uputio na pregled', 'Налаз описује грађу слузнице и природу промјена: упалних, реактивних или оних које траже даљу обраду. Тумачи га заједно са сликом саме ендоскопије љекар који је упутио на преглед', 'Заключение описывает строение слизистой и характер изменений: воспалительных, реактивных или требующих дальнейшего обследования. Трактует его вместе с картиной самой эндоскопии направивший врач', 'Der Befund beschreibt den Aufbau der Schleimhaut und die Art der Veränderungen: entzündlich, reaktiv oder weiter abklärungsbedürftig. Die überweisende Ärztin oder der überweisende Arzt deutet ihn zusammen mit dem endoskopischen Bild', 'Rapor mukozanın yapısını ve değişikliklerin niteliğini tanımlar: iltihabi, reaktif ya da ileri inceleme gerektiren. Endoskopi görüntüsüyle birlikte yönlendiren hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-fractional-curettage-two-samples'), 'Microscopic examination of two separately taken scrapings: from the cervical canal and from the uterine cavity', 'Mikroskopski pregled dva odvojeno uzeta materijala kiretaže: iz kanala grlića materice i iz šupljine materice', 'Микроскопски преглед два одвојено узета материјала киретаже: из канала грлића материце и из шупљине материце', 'Микроскопическое исследование двух раздельно взятых соскобов: из канала шейки матки и из полости матки', 'Mikroskopische Untersuchung zweier getrennt entnommener Abradate: aus dem Gebärmutterhalskanal und aus der Gebärmutterhöhle', 'Ayrı ayrı alınan iki küretaj materyalinin mikroskopla incelenmesi: rahim ağzı kanalından ve rahim içinden', 'The scrapings are collected into separate labelled containers and processed independently, so that it is clear at which level the changes lie; each sample is embedded in paraffin, sectioned and stained', 'Materijali se sakupljaju u posebne obilježene posude i obrađuju nezavisno jedan od drugog, da bi se vidjelo na kom se nivou nalaze promjene; svaki uzorak se ukalupljuje u parafin, reže i boji', 'Материјали се сакупљају у посебне обиљежене посуде и обрађују независно један од другог, да би се видјело на ком се нивоу налазе промјене; сваки узорак се укалупљује у парафин, реже и боји', 'Соскобы собирают в отдельные промаркированные контейнеры и обрабатывают независимо друг от друга, чтобы было понятно, на каком уровне находятся изменения; каждый образец заливают в парафин, режут и окрашивают', 'Die Abradate werden in getrennte, beschriftete Gefäße gegeben und unabhängig voneinander bearbeitet, damit erkennbar ist, auf welcher Höhe die Veränderungen liegen; jede Probe wird in Paraffin eingebettet, geschnitten und gefärbt', 'Materyaller ayrı etiketli kaplara alınır ve birbirinden bağımsız işlenir, böylece değişikliklerin hangi düzeyde olduğu anlaşılır; her örnek parafine gömülür, kesitlenir ve boyanır', 'Bleeding around the menopause, any bleeding after the menopause, a thickened endometrium on ultrasound, the need to establish where the changes come from, assessment before planned surgery', 'Krvarenja u perimenopauzi, svako krvarenje poslije menopauze, zadebljanje endometrijuma na ultrazvuku, potreba da se utvrdi odakle potiču promjene, obrada prije planirane operacije', 'Крварења у перименопаузи, свако крварење послије менопаузе, задебљање ендометријума на ултразвуку, потреба да се утврди одакле потичу промјене, обрада прије планиране операције', 'Кровотечения в перименопаузе, любые кровянистые выделения после менопаузы, утолщение эндометрия по УЗИ, необходимость понять, откуда исходят изменения, обследование перед планируемой операцией', 'Blutungen in den Wechseljahren, jede Blutung nach der Menopause, verdickte Gebärmutterschleimhaut im Ultraschall, Klärung der Herkunft der Veränderungen, Abklärung vor einer geplanten Operation', 'Menopoz geçişinde kanamalar, menopozdan sonraki her türlü kanama, ultrasonda kalınlaşmış endometriyum, değişikliklerin nereden kaynaklandığının belirlenmesi, planlanan ameliyat öncesi değerlendirme', 'Both scrapings are taken in one procedure under short anaesthesia; the gynaecologist explains when to stop eating beforehand', 'Oba materijala uzimaju se u jednom zahvatu uz kratkotrajnu anesteziju; kada se prestaje sa jelom prije njega, objašnjava ginekolog', 'Оба материјала узимају се у једном захвату уз краткотрајну анестезију; када се престаје са јелом прије њега, објашњава гинеколог', 'Оба соскоба берут за одно вмешательство под кратковременным обезболиванием; режим приёма пищи перед ним объясняет гинеколог', 'Beide Abradate entstehen in einem Eingriff in kurzer Narkose; wann davor die Nahrungsaufnahme endet, erklärt die Frauenärztin oder der Frauenarzt', 'Her iki materyal de kısa süreli anestezi altında tek işlemde alınır; öncesinde yeme içmenin ne zaman kesileceğini kadın doğum hekimi anlatır', 'The report describes the lining of the cervical canal and of the uterine cavity separately, which shows at what level the changes are. The gynaecologist assesses the result together with the ultrasound and the symptoms', 'U nalazu su sluznica kanala grlića i sluznica šupljine materice opisane odvojeno, što pokazuje nivo promjena. Rezultat zajedno sa ultrazvukom i tegobama procjenjuje ginekolog', 'У налазу су слузница канала грлића и слузница шупљине материце описане одвојено, што показује ниво промјена. Резултат заједно са ултразвуком и тегобама процјењује гинеколог', 'В заключении состояние слизистой канала шейки и полости матки описано порознь, и это показывает уровень изменений. Оценивает результат вместе с УЗИ и жалобами гинеколог', 'Der Befund beschreibt die Schleimhaut des Halskanals und die der Gebärmutterhöhle getrennt, was die Höhe der Veränderungen zeigt. Das Ergebnis beurteilt die Frauenärztin oder der Frauenarzt zusammen mit Ultraschall und Beschwerden', 'Raporda rahim ağzı kanalı ve rahim içi mukozası ayrı ayrı tanımlanır, bu da değişikliklerin düzeyini gösterir. Sonucu ultrason ve şikayetlerle birlikte kadın doğum hekimi değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-larynx-biopsy'), 'Microscopic examination of a piece of laryngeal mucosa or vocal fold taken at laryngoscopy', 'Mikroskopski pregled komadića sluznice grkljana ili glasnice uzetog tokom laringoskopije', 'Микроскопски преглед комадића слузнице гркљана или гласнице узетог током ларингоскопије', 'Микроскопическое исследование кусочка слизистой гортани или голосовой складки, взятого при ларингоскопии', 'Mikroskopische Untersuchung eines bei der Kehlkopfspiegelung entnommenen Stückchens Kehlkopfschleimhaut oder Stimmlippe', 'Laringoskopi sırasında alınan gırtlak mukozası ya da ses teli parçasının mikroskopla incelenmesi', 'The fragment taken by the ENT doctor during examination of the larynx, usually under general anaesthesia, is fixed, embedded in paraffin, sectioned and stained; the pathologist assesses the epithelium, keratinisation and the extent of the changes', 'Isječak koji ORL ljekar uzme pri pregledu grkljana, najčešće u opštoj anesteziji, fiksira se, ukalupljuje u parafin, reže i boji; patolog procjenjuje epitel, rožnjavanje i izraženost promjena', 'Исјечак који ОРЛ љекар узме при прегледу гркљана, најчешће у општој анестезији, фиксира се, укалупљује у парафин, реже и боји; патолог процјењује епител, рожњавање и израженост промјена', 'Фрагмент, взятый ЛОР-врачом при осмотре гортани, чаще под общим обезболиванием, фиксируют, заливают в парафин, режут и окрашивают; патолог оценивает эпителий, ороговение и выраженность изменений', 'Die von der HNO-Ärztin oder dem HNO-Arzt bei der Kehlkopfuntersuchung, meist in Vollnarkose, entnommene Probe wird fixiert, in Paraffin eingebettet, geschnitten und gefärbt; beurteilt werden Epithel, Verhornung und Ausmaß der Veränderungen', 'KBB hekiminin gırtlak muayenesi sırasında, çoğunlukla genel anestezi altında aldığı parça tespit edilir, parafine gömülür, kesitlenir ve boyanır; patoloji uzmanı epiteli, keratinleşmeyi ve değişikliklerin derecesini değerlendirir', 'Hoarseness lasting several weeks, an altered area or growth seen at laryngoscopy, laryngeal papillomas, chronic inflammation in smokers, follow-up after treatment', 'Promuklost koja traje nekoliko sedmica, izmijenjen dio ili promjena viđena pri laringoskopiji, papilomi grkljana, hronična upala kod pušača, kontrola poslije liječenja', 'Промуклост која траје неколико седмица, измијењен дио или промјена виђена при ларингоскопији, папиломи гркљана, хронична упала код пушача, контрола послије лијечења', 'Осиплость, которая держится несколько недель, изменённый участок или образование, увиденные при ларингоскопии, папилломы гортани, хроническое воспаление у курильщиков, контроль после лечения', 'Heiserkeit über mehrere Wochen, auffälliger Bezirk oder Neubildung bei der Kehlkopfspiegelung, Kehlkopfpapillome, chronische Entzündung bei Rauchenden, Kontrolle nach Behandlung', 'Birkaç hafta süren ses kısıklığı, laringoskopide görülen değişmiş alan ya da oluşum, gırtlak papillomları, sigara içenlerde kronik iltihap, tedavi sonrası kontrol', 'The material is taken during a procedure performed on an empty stomach and usually under general anaesthesia; the ENT doctor explains the preparation', 'Materijal se uzima tokom zahvata koji se radi natašte i obično u opštoj anesteziji; pripremu objašnjava ORL ljekar', 'Материјал се узима током захвата који се ради наташте и обично у општој анестезији; припрему објашњава ОРЛ љекар', 'Материал берут во время вмешательства, которое выполняют натощак и обычно под общим обезболиванием; подготовку объясняет ЛОР-врач', 'Das Material wird bei einem Eingriff gewonnen, der nüchtern und meist in Vollnarkose erfolgt; die Vorbereitung erklärt die HNO-Ärztin oder der HNO-Arzt', 'Materyal aç karnına ve genellikle genel anestezi altında yapılan işlem sırasında alınır; hazırlığı KBB hekimi anlatır', 'The report describes the nature of the changes in the laryngeal epithelium, from inflammatory and benign to those requiring follow-up or treatment. The next steps are decided by the ENT doctor', 'Nalaz opisuje prirodu promjena epitela grkljana, od upalnih i dobroćudnih do onih koje traže praćenje ili liječenje. Dalje korake određuje ORL ljekar', 'Налаз описује природу промјена епитела гркљана, од упалних и доброћудних до оних које траже праћење или лијечење. Даље кораке одређује ОРЛ љекар', 'Заключение описывает характер изменений эпителия гортани — от воспалительных и доброкачественных до тех, что требуют наблюдения или лечения. Дальнейшие шаги определяет ЛОР-врач', 'Der Befund beschreibt die Art der Epithelveränderungen am Kehlkopf, von entzündlich und gutartig bis hin zu kontroll- oder behandlungsbedürftig. Das weitere Vorgehen legt die HNO-Ärztin oder der HNO-Arzt fest', 'Rapor gırtlak epitelindeki değişikliklerin niteliğini iltihabi ve iyi huylu olandan izlem ya da tedavi gerektirene kadar tanımlar. Sonraki adımları KBB hekimi belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-lung-tumor-examination'), 'Microscopic examination of tissue from a lung lesion obtained at surgery or by needle biopsy through the chest wall', 'Mikroskopski pregled tkiva promjene u plućima dobijenog operacijom ili punkcijom kroz grudni zid', 'Микроскопски преглед ткива промјене у плућима добијеног операцијом или пункцијом кроз грудни зид', 'Микроскопическое исследование ткани образования лёгкого, полученной при операции или при пункции через грудную стенку', 'Mikroskopische Untersuchung von Gewebe einer Lungenveränderung, gewonnen bei einer Operation oder durch Punktion durch die Brustwand', 'Ameliyatla ya da göğüs duvarından iğne biyopsisiyle alınan akciğer kitlesi dokusunun mikroskopla incelenmesi', 'The material is fixed, embedded in paraffin, sectioned and stained; immunohistochemistry is usually added to establish the tissue type, and part of the material may be sent for molecular testing', 'Materijal se fiksira, ukalupljuje u parafin, reže i boji; za određivanje vrste tkiva obično se dodaje imunohistohemija, a po potrebi se dio materijala šalje na molekularna ispitivanja', 'Материјал се фиксира, укалупљује у парафин, реже и боји; за одређивање врсте ткива обично се додаје имунохистохемија, а по потреби се дио материјала шаље на молекуларна испитивања', 'Материал фиксируют, заливают в парафин, режут и окрашивают; для определения типа ткани обычно добавляют иммуногистохимию, а при необходимости часть материала направляют на молекулярные исследования', 'Das Material wird fixiert, in Paraffin eingebettet, geschnitten und gefärbt; zur Bestimmung des Gewebetyps kommt meist Immunhistochemie hinzu, bei Bedarf wird ein Teil für molekulare Untersuchungen weitergegeben', 'Materyal tespit edilir, parafine gömülür, kesitlenir ve boyanır; doku tipini belirlemek için genellikle immünhistokimya eklenir, gerektiğinde bir bölümü moleküler incelemeye gönderilir', 'A lesion found on chest CT or X-ray, tissue after surgical removal, material from a transthoracic needle biopsy, choosing treatment according to the tissue type', 'Promjena viđena na skeneru ili rendgenu pluća, tkivo poslije hirurškog uklanjanja, materijal transtorakalne punkcije, izbor liječenja prema vrsti tkiva', 'Промјена виђена на скенеру или рендгену плућа, ткиво послије хируршког уклањања, материјал трансторакалне пункције, избор лијечења према врсти ткива', 'Образование, выявленное на КТ или рентгене лёгких, ткань после хирургического удаления, материал трансторакальной пункции, подбор лечения по типу ткани', 'Im CT oder Röntgenbild der Lunge entdeckte Veränderung, Gewebe nach operativer Entfernung, Material einer Punktion durch die Brustwand, Auswahl der Behandlung nach Gewebetyp', 'Akciğer BT ya da röntgeninde saptanan kitle, cerrahi olarak çıkarılan doku, transtorasik iğne biyopsisi materyali, doku tipine göre tedavi seçimi', 'Preparation concerns the procedure by which the material is taken; the laboratory stage needs none, and the doctor explains what to do before the operation or the puncture', 'Priprema se odnosi na zahvat kojim se uzima materijal; za laboratorijski dio posebne pripreme nema, a režim prije operacije ili punkcije objašnjava ljekar', 'Припрема се односи на захват којим се узима материјал; за лабораторијски дио посебне припреме нема, а режим прије операције или пункције објашњава љекар', 'Подготовка относится к вмешательству, при котором берут материал; отдельной подготовки к лабораторному этапу нет, режим перед операцией или пункцией объясняет врач', 'Die Vorbereitung betrifft den Eingriff, bei dem das Material gewonnen wird; für den Laborteil ist keine nötig, das Vorgehen vor Operation oder Punktion erklärt die Ärztin oder der Arzt', 'Hazırlık materyalin alındığı işlemle ilgilidir; laboratuvar aşaması için ayrı hazırlık gerekmez, ameliyat ya da ponksiyon öncesi düzeni hekim anlatır', 'The pathologist describes the type of tissue, its degree of malignancy and, if needed, additional markers that are taken into account when choosing treatment. The report is read together with the imaging, and management is decided by the pulmonologist, thoracic surgeon and oncologist', 'Patolog opisuje vrstu tkiva, stepen malignosti i, po potrebi, dodatne markere koji se uzimaju u obzir pri izboru liječenja. Nalaz se čita zajedno sa snimcima, a postupak određuju pulmolog, grudni hirurg i onkolog', 'Патолог описује врсту ткива, степен малигности и, по потреби, додатне маркере који се узимају у обзир при избору лијечења. Налаз се чита заједно са снимцима, а поступак одређују пулмолог, грудни хирург и онколог', 'Патолог описывает тип ткани, степень её злокачественности и, при необходимости, дополнительные маркеры, которые учитывают при выборе лечения. Заключение читают вместе со снимками, а тактику определяют пульмонолог, торакальный хирург и онколог', 'Beschrieben werden Gewebetyp, Grad der Bösartigkeit und bei Bedarf zusätzliche Marker, die in die Therapieauswahl einfließen. Der Befund wird zusammen mit den Bildern gelesen, das Vorgehen legen Pneumologie, Thoraxchirurgie und Onkologie fest', 'Patoloji uzmanı dokunun tipini, kötü huyluluk derecesini ve gerektiğinde tedavi seçiminde dikkate alınan ek belirteçleri tanımlar. Rapor görüntülerle birlikte okunur, izlenecek yolu göğüs hastalıkları, göğüs cerrahisi ve onkoloji hekimleri belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-lymph-node-examination'), 'Microscopic examination of a lymph node removed whole by biopsy', 'Mikroskopski pregled limfnog čvora uklonjenog u cjelini prilikom biopsije', 'Микроскопски преглед лимфног чвора уклоњеног у цјелини приликом биопсије', 'Микроскопическое исследование лимфатического узла, удалённого целиком при биопсии', 'Mikroskopische Untersuchung eines vollständig per Biopsie entfernten Lymphknotens', 'Biyopsiyle bütün olarak çıkarılan lenf nodunun mikroskopla incelenmesi', 'The node is measured, cut, embedded in paraffin and stained so that its internal architecture is visible; immunohistochemistry is often added, because the cell type cannot be determined from a routine stain alone', 'Čvor se izmjeri, razreže, ukalupi u parafin i oboji tako da se vidi njegova unutrašnja građa; često se dodaje imunohistohemija, jer se vrsta ćelija ne može odrediti samo jednim uobičajenim bojenjem', 'Чвор се измјери, разреже, укалупи у парафин и обоји тако да се види његова унутрашња грађа; често се додаје имунохистохемија, јер се врста ћелија не може одредити само једним уобичајеним бојењем', 'Узел измеряют, разрезают, заливают в парафин и окрашивают так, чтобы была видна его внутренняя структура; часто добавляют иммуногистохимию, потому что тип клеток по одной обычной окраске определить нельзя', 'Der Knoten wird vermessen, geschnitten, in Paraffin eingebettet und so gefärbt, dass seine innere Architektur sichtbar wird; häufig kommt Immunhistochemie hinzu, weil der Zelltyp mit einer Routinefärbung allein nicht bestimmbar ist', 'Nod ölçülür, kesilir, parafine gömülür ve iç yapısı görünecek biçimde boyanır; hücre tipi tek bir rutin boyamayla belirlenemediğinden sıklıkla immünhistokimya eklenir', 'An enlarged lymph node that does not shrink over several weeks, enlargement without signs of infection, enlargement together with night sweats and weight loss, clarifying the nature of changes in a known disease, examination of a sentinel node', 'Uvećan limfni čvor koji se ne smanjuje nekoliko sedmica, uvećanje bez znakova infekcije, uvećanje uz noćno znojenje i gubitak tjelesne težine, razjašnjenje prirode promjena kod već poznate bolesti, pregled stražarskog čvora', 'Увећан лимфни чвор који се не смањује неколико седмица, увећање без знакова инфекције, увећање уз ноћно знојење и губитак тјелесне тежине, разјашњење природе промјена код већ познате болести, преглед стражарског чвора', 'Увеличенный лимфоузел, который не уменьшается несколько недель, увеличение без признаков инфекции, сочетание с ночной потливостью и потерей веса, уточнение природы изменений при уже известном заболевании, исследование сторожевого узла', 'Vergrößerter Lymphknoten, der über Wochen nicht kleiner wird, Vergrößerung ohne Infektzeichen, Vergrößerung zusammen mit Nachtschweiß und Gewichtsverlust, Abklärung von Veränderungen bei bekannter Erkrankung, Untersuchung des Wächterlymphknotens', 'Birkaç hafta boyunca küçülmeyen büyümüş lenf nodu, enfeksiyon belirtisi olmadan büyüme, gece terlemesi ve kilo kaybıyla birlikte büyüme, bilinen bir hastalıkta değişikliklerin niteliğinin araştırılması, sentinel nodun incelenmesi', 'The node is removed in a small operation under local or general anaesthesia; the surgeon discusses beforehand when to stop eating and what to do about medicines that affect blood clotting', 'Čvor se uklanja manjom operacijom u lokalnoj ili opštoj anesteziji; kada se prestaje sa jelom i šta sa lijekovima koji utiču na zgrušavanje krvi, hirurg dogovara unaprijed', 'Чвор се уклања мањом операцијом у локалној или општој анестезији; када се престаје са јелом и шта са лијековима који утичу на згрушавање крви, хирург договара унапријед', 'Узел удаляют при небольшой операции под местным или общим обезболиванием; режим приёма пищи и вопрос о препаратах, влияющих на свёртывание крови, заранее обсуждает хирург', 'Der Knoten wird in einer kleinen Operation in örtlicher Betäubung oder Vollnarkose entfernt; Nüchternheit und der Umgang mit blutverdünnenden Medikamenten werden vorab mit der Chirurgin oder dem Chirurgen besprochen', 'Nod lokal ya da genel anestezi altında küçük bir ameliyatla çıkarılır; yeme içmenin ne zaman kesileceği ve kan sulandırıcı ilaçların ne olacağı cerrahla önceden konuşulur', 'The pathologist describes whether the architecture of the node is preserved and which cells predominate: the changes may be related to a reaction to infection, chronic inflammation or a tumour process. The treating doctor interprets the report and decides on further management', 'Patolog opisuje da li je građa čvora očuvana i koje ćelije u njemu preovlađuju: promjene mogu biti povezane sa reakcijom na infekciju, hroničnom upalom ili tumorskim procesom. Nalaz tumači i dalji postupak određuje ljekar koji vodi liječenje', 'Патолог описује да ли је грађа чвора очувана и које ћелије у њему преовлађују: промјене могу бити повезане са реакцијом на инфекцију, хроничном упалом или туморским процесом. Налаз тумачи и даљи поступак одређује љекар који води лијечење', 'Патолог описывает, сохранено ли строение узла и какие клетки в нём преобладают: изменения могут быть связаны с реакцией на инфекцию, хроническим воспалением или опухолевым процессом. Заключение трактует и дальнейшую тактику определяет лечащий врач', 'Beschrieben wird, ob die Architektur des Knotens erhalten ist und welche Zellen überwiegen: Die Veränderungen können mit einer Infektreaktion, einer chronischen Entzündung oder einem Tumorprozess zusammenhängen. Den Befund deutet und das weitere Vorgehen bestimmt die behandelnde Ärztin oder der behandelnde Arzt', 'Patoloji uzmanı nodun yapısının korunup korunmadığını ve hangi hücrelerin baskın olduğunu tanımlar: değişiklikler enfeksiyona yanıt, kronik iltihap ya da tümöral süreçle ilişkili olabilir. Raporu yorumlayıp izlenecek yolu tedaviyi yürüten hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-mediastinum-biopsy'), 'Microscopic examination of tissue from the mediastinum, the space between the lungs that holds lymph nodes, the thymus and major vessels', 'Mikroskopski pregled tkiva iz medijastinuma, prostora između pluća u kojem se nalaze limfni čvorovi, timus i veliki krvni sudovi', 'Микроскопски преглед ткива из медијастинума, простора између плућа у којем се налазе лимфни чворови, тимус и велики крвни судови', 'Микроскопическое исследование ткани из средостения — пространства между лёгкими, где лежат лимфатические узлы, вилочковая железа и крупные сосуды', 'Mikroskopische Untersuchung von Gewebe aus dem Mediastinum, dem Raum zwischen den Lungen mit Lymphknoten, Thymus und großen Gefäßen', 'Akciğerler arasında yer alan, lenf düğümleri, timus ve büyük damarları barındıran mediasten bölgesinden alınan dokunun mikroskobik incelemesi', 'The sample is obtained during mediastinoscopy, thoracoscopy or an image-guided puncture, then fixed, embedded in paraffin, cut into thin sections, stained and examined under a microscope', 'Materijal se dobija medijastinoskopijom, torakoskopijom ili punkcijom pod kontrolom snimanja, zatim se fiksira, ukalupljuje u parafin, reže na tanke presjeke, boji i pregleda pod mikroskopom', 'Материјал се добија медијастиноскопијом, торакоскопијом или пункцијом под контролом снимања, затим се фиксира, укалупљује у парафин, реже на танке пресјеке, боји и прегледа под микроскопом', 'Материал получают при медиастиноскопии, торакоскопии или пункции под контролем визуализации, затем фиксируют, заливают в парафин, режут на тонкие срезы, окрашивают и изучают под микроскопом', 'Das Material wird bei einer Mediastinoskopie, Thorakoskopie oder bildgesteuerten Punktion gewonnen, anschließend fixiert, in Paraffin eingebettet, in dünne Schnitte geschnitten, gefärbt und unter dem Mikroskop beurteilt', 'Örnek mediastinoskopi, torakoskopi ya da görüntüleme eşliğinde ponksiyonla alınır, ardından tespit edilir, parafine gömülür, ince kesitler halinde kesilir, boyanır ve mikroskopta incelenir', 'Enlarged mediastinal lymph nodes on CT or X-ray, a mass in the mediastinum, clarifying the nature of a granulomatous process, assessing tissue before choosing management in chest disease', 'Uvećani limfni čvorovi medijastinuma na skeneru ili rendgenu, tvorba u medijastinumu, razjašnjenje prirode granulomatoznog procesa, procjena tkiva prije izbora postupka kod bolesti grudnog koša', 'Увећани лимфни чворови медијастинума на скенеру или рендгену, творба у медијастинуму, разјашњење природе грануломатозног процеса, процјена ткива прије избора поступка код болести грудног коша', 'Увеличенные лимфоузлы средостения на КТ или рентгене, образование в средостении, уточнение природы гранулёматозного процесса, оценка ткани перед выбором тактики при болезнях грудной клетки', 'Vergrößerte mediastinale Lymphknoten im CT oder Röntgenbild, Raumforderung im Mediastinum, Abklärung eines granulomatösen Prozesses, Gewebebeurteilung vor der Therapiewahl bei Erkrankungen des Brustkorbs', 'BT veya röntgende büyümüş mediasten lenf düğümleri, mediastende kitle, granülomatöz sürecin niteliğinin aydınlatılması, göğüs hastalıklarında tedavi kararı öncesi doku değerlendirmesi', 'No separate preparation is needed for the laboratory stage: the material is taken during an endoscopic or surgical procedure, the conditions of which are discussed by the operating doctor', 'Za laboratorijski dio nema posebne pripreme: materijal se uzima tokom endoskopskog ili hirurškog zahvata, čije uslove dogovara ljekar koji ga izvodi', 'За лабораторијски дио нема посебне припреме: материјал се узима током ендоскопског или хируршког захвата, чије услове договара љекар који га изводи', 'Отдельной подготовки к лабораторному этапу нет: материал берут во время эндоскопической или хирургической процедуры, условия которой обсуждает оперирующий врач', 'Für den Laborteil ist keine gesonderte Vorbereitung nötig: Das Material wird während eines endoskopischen oder chirurgischen Eingriffs entnommen, dessen Bedingungen der operierende Arzt bespricht', 'Laboratuvar aşaması için ayrı bir hazırlık gerekmez: materyal endoskopik ya da cerrahi işlem sırasında alınır, işlemin koşullarını uygulayan hekim anlatır', 'The pathologist describes the tissue structure: inflammatory and granulomatous changes, the character of lymphoid cells, signs of malignancy. The report is issued by the pathologist, and further management is decided by the treating doctor', 'Patolog opisuje građu tkiva, upalne i granulomatozne promjene, prirodu limfoidnih ćelija i znake maligniteta. Nalaz izdaje ljekar patolog, a dalji postupak određuje ljekar koji vodi liječenje', 'Патолог описује грађу ткива, упалне и грануломатозне промјене, природу лимфоидних ћелија и знаке малигнитета. Налаз издаје љекар патолог, а даљи поступак одређује љекар који води лијечење', 'Патолог описывает строение ткани: воспалительные и гранулёматозные изменения, характер лимфоидных клеток, признаки злокачественности. Заключение выдаёт врач-патолог, а дальнейшую тактику определяет лечащий врач', 'Der Pathologe beschreibt den Gewebeaufbau, entzündliche und granulomatöse Veränderungen, die Art der lymphatischen Zellen und Hinweise auf Bösartigkeit. Den Befund erstellt der Pathologe, das weitere Vorgehen legt der behandelnde Arzt fest', 'Patolog doku yapısını, iltihabi ve granülomatöz değişiklikleri, lenfoid hücrelerin niteliğini ve kötü huyluluk belirtilerini tanımlar. Raporu patoloji uzmanı verir, sonraki adımları tedaviyi yürüten hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-multiple-biopsy'), 'Microscopic examination of several tissue fragments taken from different sites during one procedure', 'Mikroskopski pregled više isječaka tkiva uzetih tokom jednog zahvata sa različitih dijelova', 'Микроскопски преглед више исјечака ткива узетих током једног захвата са различитих дијелова', 'Микроскопическое исследование нескольких фрагментов ткани, взятых за одну процедуру из разных участков', 'Mikroskopische Untersuchung mehrerer Gewebestücke, die während eines Eingriffs an verschiedenen Stellen entnommen wurden', 'Tek bir işlem sırasında farklı bölgelerden alınan birden çok doku parçasının mikroskobik incelemesi', 'Each fragment goes into its own labelled container, is processed through paraffin, sectioned and stained, after which the pathologist describes the sites separately', 'Svaki isječak ide u zasebnu označenu posudu, obrađuje se kroz parafin, reže i boji, nakon čega patolog opisuje svaki dio posebno', 'Сваки исјечак иде у засебну означену посуду, обрађује се кроз парафин, реже и боји, након чега патолог описује сваки дио посебно', 'Каждый фрагмент помещают в отдельный маркированный контейнер, проводят через парафин, режут и окрашивают, после чего патолог описывает участки по отдельности', 'Jedes Stück kommt in ein eigenes beschriftetes Gefäß, wird in Paraffin verarbeitet, geschnitten und gefärbt, danach beschreibt der Pathologe die Entnahmestellen getrennt', 'Her parça ayrı etiketli kaba konur, parafinden geçirilir, kesilir ve boyanır, ardından patolog bölgeleri ayrı ayrı tanımlar', 'Endoscopic biopsies from several parts of an organ, assessing how widespread changes are, sampling several suspicious areas of skin or mucosa, follow-up at several points after treatment', 'Endoskopske biopsije iz više dijelova organa, procjena raširenosti promjena, uzorkovanje sa više sumnjivih dijelova kože ili sluznice, kontrola na više tačaka poslije liječenja', 'Ендоскопске биопсије из више дијелова органа, процјена раширености промјена, узорковање са више сумњивих дијелова коже или слузнице, контрола на више тачака послије лијечења', 'Эндоскопические биопсии из нескольких отделов органа, оценка распространённости изменений, забор из нескольких подозрительных участков кожи или слизистой, контроль в нескольких точках после лечения', 'Endoskopische Biopsien aus mehreren Abschnitten eines Organs, Beurteilung der Ausdehnung von Veränderungen, Entnahme an mehreren auffälligen Haut- oder Schleimhautstellen, Kontrolle an mehreren Punkten nach einer Behandlung', 'Bir organın farklı bölümlerinden endoskopik biyopsiler, değişikliklerin yaygınlığının değerlendirilmesi, deri veya mukozadaki birden çok şüpheli alandan örnekleme, tedavi sonrası birkaç noktadan kontrol', 'The patient does not prepare for the laboratory stage: the fragments are taken during endoscopy or another procedure', 'Pacijent se za laboratorijski dio ne priprema: isječci se uzimaju tokom endoskopije ili drugog zahvata', 'Пацијент се за лабораторијски дио не припрема: исјечци се узимају током ендоскопије или другог захвата', 'Пациент к лабораторному этапу не готовится: фрагменты берут во время эндоскопии или другой процедуры', 'Für den Laborteil ist keine Vorbereitung nötig: Die Gewebestücke werden während einer Endoskopie oder eines anderen Eingriffs entnommen', 'Hasta laboratuvar aşaması için hazırlık yapmaz: parçalar endoskopi ya da başka bir işlem sırasında alınır', 'The report describes each site separately, so the picture may differ from point to point. The treating doctor matches the descriptions with the clinical picture and decides on the next steps', 'U nalazu je svaki dio opisan zasebno, pa se slika može razlikovati od tačke do tačke. Opise sa kliničkom slikom poredi i dalje korake određuje ljekar koji vodi liječenje', 'У налазу је сваки дио описан засебно, па се слика може разликовати од тачке до тачке. Описе са клиничком сликом пореди и даље кораке одређује љекар који води лијечење', 'В заключении каждый участок описан отдельно, поэтому картина может различаться от точки к точке. Сопоставляет описания с клинической картиной и решает, что делать дальше, лечащий врач', 'Im Befund ist jede Stelle einzeln beschrieben, das Bild kann sich daher von Punkt zu Punkt unterscheiden. Der behandelnde Arzt gleicht die Beschreibungen mit dem klinischen Bild ab und entscheidet über das weitere Vorgehen', 'Raporda her bölge ayrı tanımlanır, bu nedenle görünüm noktadan noktaya değişebilir. Tanımları klinik tabloyla karşılaştıran ve sonraki adıma karar veren tedaviyi yürüten hekimdir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-multiple-prostate-biopsies'), 'Microscopic examination of several prostate tissue fragments submitted under a single referral', 'Mikroskopski pregled više isječaka tkiva prostate poslatih po jednoj uputnici', 'Микроскопски преглед више исјечака ткива простате послатих по једној упутници', 'Микроскопическое исследование нескольких фрагментов ткани предстательной железы, присланных по одному направлению', 'Mikroskopische Untersuchung mehrerer Gewebestücke der Prostata, die mit einer Überweisung eingesandt wurden', 'Tek bir sevkle gönderilen birden çok prostat dokusu parçasının mikroskobik incelemesi', 'The fragments are processed through paraffin separately, each is sectioned and stained, and the pathologist assesses every sample and then summarises the picture for the gland as a whole', 'Isječci se kroz parafin obrađuju odvojeno, sa svakog se prave presjeci i boje, a patolog procjenjuje svaki uzorak i sabira sliku za cijelu žlijezdu', 'Исјечци се кроз парафин обрађују одвојено, са сваког се праве пресјеци и боје, а патолог процјењује сваки узорак и сабира слику за цијелу жлијезду', 'Фрагменты проводят через парафин раздельно, с каждого делают срезы и окрашивают, патолог оценивает материал по каждой пробе и сводит картину по железе в целом', 'Die Stücke werden getrennt in Paraffin verarbeitet, jedes wird geschnitten und gefärbt, der Pathologe beurteilt jede Probe und fasst anschließend das Bild für die gesamte Drüse zusammen', 'Parçalar parafinden ayrı ayrı geçirilir, her birinden kesit alınıp boyanır, patolog her örneği değerlendirir ve bezin bütünü için tabloyu birleştirir', 'Assessing how far changes extend across the lobes of the gland, monitoring previously described changes, repeat sampling after an uninformative examination, planning urological management', 'Procjena raširenosti promjena po režnjevima žlijezde, praćenje ranije opisanih promjena, ponovno uzorkovanje poslije neinformativnog pregleda, planiranje urološkog postupka', 'Процјена раширености промјена по режњевима жлијезде, праћење раније описаних промјена, поновно узорковање послије неинформативног прегледа, планирање уролошког поступка', 'Оценка распространённости изменений по долям железы, наблюдение за ранее описанными изменениями, повторный забор после неинформативного исследования, планирование урологической тактики', 'Beurteilung der Ausdehnung von Veränderungen über die Drüsenlappen, Verlaufskontrolle zuvor beschriebener Veränderungen, erneute Entnahme nach einer nicht aussagekräftigen Untersuchung, Planung des urologischen Vorgehens', 'Değişikliklerin bez loblarındaki yaygınlığının değerlendirilmesi, daha önce tanımlanmış değişikliklerin izlemi, bilgi vermeyen incelemeden sonra yeniden örnekleme, ürolojik planlama', 'No special laboratory preparation is required: the samples are taken during a urological procedure, for which the urologist prepares the patient', 'Nema posebne pripreme za laboratoriju: uzorci se uzimaju tokom urološkog zahvata, za koji pacijenta priprema urolog', 'Нема посебне припреме за лабораторију: узорци се узимају током уролошког захвата, за који пацијента припрема уролог', 'Специальной подготовки для лаборатории нет: пробы берут во время урологической процедуры, к которой пациента готовит уролог', 'Für das Labor ist keine besondere Vorbereitung nötig: Die Proben werden während eines urologischen Eingriffs entnommen, auf den der Urologe den Patienten vorbereitet', 'Laboratuvar için özel hazırlık yoktur: örnekler ürolojik işlem sırasında alınır, hastayı bu işleme ürolog hazırlar', 'The pathologist describes the glandular tissue, the presence of inflammation, atypia and signs of malignancy, and how many samples are involved. The meaning of the result and the next steps are decided by the urologist', 'Patolog opisuje građu žljezdanog tkiva, prisustvo upale, atipije i znakova maligniteta, kao i koliko je uzoraka zahvaćeno. Značenje nalaza i sljedeće korake određuje urolog', 'Патолог описује грађу жљезданог ткива, присуство упале, атипије и знакова малигнитета, као и колико је узорака захваћено. Значење налаза и сљедеће кораке одређује уролог', 'Патолог описывает строение железистой ткани, наличие воспаления, атипии и признаков злокачественности, а также сколько проб затронуто. Значение результата и следующие шаги определяет уролог', 'Der Pathologe beschreibt das Drüsengewebe, Entzündung, Atypien und Hinweise auf Bösartigkeit sowie die Zahl der betroffenen Proben. Was das Ergebnis bedeutet und wie es weitergeht, entscheidet der Urologe', 'Patolog bez dokusunun yapısını, iltihap, atipi ve kötü huyluluk belirtilerini ve kaç örneğin etkilendiğini tanımlar. Sonucun anlamını ve sonraki adımları ürolog belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-needle-biopsy-liver-lung-kidney'), 'Microscopic examination of a tissue core from the liver, lung or kidney obtained with a thick needle', 'Mikroskopski pregled tkivnog cilindra jetre, pluća ili bubrega dobijenog debelom iglom', 'Микроскопски преглед ткивног цилиндра јетре, плућа или бубрега добијеног дебелом иглом', 'Микроскопическое исследование столбика ткани печени, лёгкого или почки, полученного толстой иглой', 'Mikroskopische Untersuchung eines Gewebezylinders aus Leber, Lunge oder Niere, der mit einer dicken Nadel gewonnen wurde', 'Kalın iğneyle alınan karaciğer, akciğer veya böbrek doku silindirinin mikroskobik incelemesi', 'The core is fixed, embedded in paraffin, cut into thin sections and stained, with additional connective tissue stains for liver and kidney; the puncture itself is performed under ultrasound or CT guidance', 'Cilindar se fiksira, ukalupljuje u parafin, reže na tanke presjeke i boji, a za jetru i bubreg koriste se i posebna bojenja vezivnog tkiva; sama punkcija se radi pod kontrolom ultrazvuka ili skenera', 'Цилиндар се фиксира, укалупљује у парафин, реже на танке пресјеке и боји, а за јетру и бубрег користе се и посебна бојења везивног ткива; сама пункција се ради под контролом ултразвука или скенера', 'Столбик фиксируют, заливают в парафин, режут на тонкие срезы и окрашивают, для печени и почки применяют дополнительные окраски соединительной ткани; саму пункцию делают под контролем УЗИ или КТ', 'Der Zylinder wird fixiert, in Paraffin eingebettet, in dünne Schnitte geschnitten und gefärbt, bei Leber und Niere zusätzlich mit Bindegewebsfärbungen; die Punktion selbst erfolgt unter Ultraschall- oder CT-Kontrolle', 'Silindir tespit edilir, parafine gömülür, ince kesitlere ayrılır ve boyanır, karaciğer ile böbrekte ayrıca bağ dokusu boyaları kullanılır; ponksiyonun kendisi ultrason ya da BT eşliğinde yapılır', 'Diffuse liver changes of unclear cause, persistent changes in urine tests and declining kidney function, focal or widespread lung involvement, clarifying the nature of a lesion before choosing treatment', 'Difuzne promjene jetre nejasnog uzroka, uporne promjene u nalazu urina i pad bubrežne funkcije, žarišna ili raširena promjena na plućima, razjašnjenje prirode tvorbe prije izbora liječenja', 'Дифузне промјене јетре нејасног узрока, упорне промјене у налазу урина и пад бубрежне функције, жаришна или раширена промјена на плућима, разјашњење природе творбе прије избора лијечења', 'Диффузные изменения печени неясной причины, стойкие изменения в анализах мочи и снижение функции почек, очаговое или распространённое поражение лёгкого, уточнение природы образования перед выбором лечения', 'Diffuse Leberveränderungen unklarer Ursache, anhaltende Auffälligkeiten im Urin und nachlassende Nierenfunktion, umschriebene oder ausgedehnte Lungenveränderungen, Abklärung einer Raumforderung vor der Therapiewahl', 'Nedeni belirsiz yaygın karaciğer değişiklikleri, idrar tahlilinde süregelen bozukluk ve böbrek işlevinde azalma, akciğerde odaksal ya da yaygın tutulum, tedavi seçimi öncesi kitlenin niteliğinin aydınlatılması', 'Before the puncture the doctor orders clotting tests and alone decides whether medicines affecting clotting are paused; the laboratory stage needs no preparation', 'Prije punkcije ljekar traži parametre koagulacije i isključivo on odlučuje o privremenom prekidu lijekova koji utiču na zgrušavanje; laboratorijski dio ne traži pripremu', 'Прије пункције љекар тражи параметре коагулације и искључиво он одлучује о привременом прекиду лијекова који утичу на згрушавање; лабораторијски дио не тражи припрему', 'Перед пункцией врач назначает показатели свёртывания крови и сам решает вопрос о временной отмене препаратов, влияющих на свёртываемость; лабораторный этап подготовки не требует', 'Vor der Punktion veranlasst der Arzt Gerinnungswerte und entscheidet allein über das vorübergehende Pausieren gerinnungswirksamer Medikamente; der Laborteil erfordert keine Vorbereitung', 'Ponksiyon öncesi hekim pıhtılaşma testlerini ister ve kanı sulandıran ilaçlara ara verilip verilmeyeceğine yalnızca hekim karar verir; laboratuvar aşaması hazırlık gerektirmez', 'The report describes how far the organ structure is preserved and the character of inflammation, fibrosis and cell changes. The treating doctor compares it with tests and imaging and decides on management', 'Nalaz opisuje očuvanost građe organa i prirodu upale, fibroze i promjena u ćelijama. Sa analizama i snimcima ga poredi i postupak određuje ljekar koji vodi liječenje', 'Налаз описује очуваност грађе органа и природу упале, фиброзе и промјена у ћелијама. Са анализама и снимцима га пореди и поступак одређује љекар који води лијечење', 'Заключение описывает сохранность структуры органа, характер воспаления, фиброза и клеточных изменений. Сопоставляет его с анализами и снимками и определяет тактику лечащий врач', 'Der Befund beschreibt, wie weit der Organaufbau erhalten ist, sowie Art der Entzündung, Fibrose und Zellveränderungen. Der behandelnde Arzt gleicht ihn mit Laborwerten und Bildgebung ab und legt das Vorgehen fest', 'Rapor organ yapısının ne kadar korunduğunu, iltihabın, fibrozun ve hücre değişikliklerinin niteliğini tanımlar. Bunu tahlil ve görüntülerle karşılaştırıp yolu belirleyen tedaviyi yürüten hekimdir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-needle-breast-biopsy-without-ihc'), 'Microscopic examination of a breast tissue core without additional immunohistochemical staining', 'Mikroskopski pregled tkivnog cilindra dojke bez dodatnog imunohistohemijskog bojenja', 'Микроскопски преглед ткивног цилиндра дојке без додатног имунохистохемијског бојења', 'Микроскопическое исследование столбика ткани молочной железы без дополнительного иммуногистохимического окрашивания', 'Mikroskopische Untersuchung eines Gewebezylinders der Brust ohne zusätzliche immunhistochemische Färbung', 'Ek immünhistokimyasal boyama yapılmadan incelenen meme dokusu silindirinin mikroskobik değerlendirmesi', 'The core, taken with a thick needle under ultrasound or mammography guidance, is processed through paraffin, sectioned and stained with routine stains; immunohistochemistry is ordered separately if needed', 'Cilindar uzet debelom iglom pod kontrolom ultrazvuka ili mamografije obrađuje se kroz parafin, reže i boji standardnim bojama; imunohistohemija se po potrebi traži posebno', 'Цилиндар узет дебелом иглом под контролом ултразвука или мамографије обрађује се кроз парафин, реже и боји стандардним бојама; имунохистохемија се по потреби тражи посебно', 'Столбик, взятый толстой иглой под контролем УЗИ или маммографии, проводят через парафин, режут и окрашивают стандартными красителями; иммуногистохимия при необходимости назначается отдельно', 'Der mit dicker Nadel unter Ultraschall- oder Mammographiekontrolle entnommene Zylinder wird in Paraffin verarbeitet, geschnitten und mit Routinefärbungen gefärbt; eine Immunhistochemie wird bei Bedarf gesondert angefordert', 'Ultrason ya da mamografi eşliğinde kalın iğneyle alınan silindir parafinden geçirilir, kesilir ve standart boyalarla boyanır; gerekirse immünhistokimya ayrıca istenir', 'A lump found on examination, ultrasound or mammography, changes in a post-operative scar area, clarifying the nature of a firm area before a treatment decision', 'Čvorić otkriven pregledom, ultrazvukom ili mamografijom, promjene u ožiljku poslije operacije, razjašnjenje prirode zadebljanja prije odluke o liječenju', 'Чворић откривен прегледом, ултразвуком или мамографијом, промјене у ожиљку послије операције, разјашњење природе задебљања прије одлуке о лијечењу', 'Узловое образование, выявленное при осмотре, УЗИ или маммографии, изменения в зоне рубца после операции, уточнение природы уплотнения перед решением о лечении', 'Ein bei der Untersuchung, im Ultraschall oder in der Mammographie gefundener Knoten, Veränderungen im Narbenbereich nach einer Operation, Abklärung einer Verhärtung vor der Behandlungsentscheidung', 'Muayene, ultrason ya da mamografide saptanan kitle, ameliyat sonrası nedbe bölgesindeki değişiklikler, tedavi kararı öncesi sertliğin niteliğinin aydınlatılması', 'No preparation is needed for the laboratory stage; the conditions of the puncture itself are discussed by the doctor performing the biopsy', 'Za laboratorijski dio nije potrebna priprema, a uslove same punkcije objašnjava ljekar koji radi biopsiju', 'За лабораторијски дио није потребна припрема, а услове саме пункције објашњава љекар који ради биопсију', 'К лабораторному этапу готовиться не нужно; условия самой пункции обсуждает врач, выполняющий биопсию', 'Für den Laborteil ist keine Vorbereitung nötig; die Bedingungen der Punktion bespricht der Arzt, der die Biopsie durchführt', 'Laboratuvar aşaması için hazırlık gerekmez; ponksiyonun koşullarını biyopsiyi yapan hekim anlatır', 'The pathologist describes the structure of ducts and lobules, the character of the cells and signs of malignancy. If receptor data are needed the doctor orders immunohistochemistry separately, and the treating doctor decides on management', 'Patolog opisuje građu kanalića i režnjića, prirodu ćelija i znake maligniteta. Ako su potrebni podaci o receptorima, ljekar posebno traži imunohistohemiju, a postupak određuje ljekar koji vodi liječenje', 'Патолог описује грађу каналића и режњића, природу ћелија и знаке малигнитета. Ако су потребни подаци о рецепторима, љекар посебно тражи имунохистохемију, а поступак одређује љекар који води лијечење', 'Патолог описывает строение протоков и долек, характер клеток и признаки злокачественности. Если нужны данные о рецепторах, врач отдельно назначает иммуногистохимическое исследование, а тактику определяет лечащий врач', 'Der Pathologe beschreibt den Aufbau von Gängen und Läppchen, die Beschaffenheit der Zellen und Hinweise auf Bösartigkeit. Werden Rezeptordaten benötigt, ordnet der Arzt die Immunhistochemie gesondert an, das Vorgehen legt der behandelnde Arzt fest', 'Patolog kanal ve lobül yapısını, hücrelerin niteliğini ve kötü huyluluk belirtilerini tanımlar. Reseptör bilgisi gerekiyorsa hekim immünhistokimyayı ayrıca ister, tedavi yolunu ise tedaviyi yürüten hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-needle-prostate-biopsy'), 'Microscopic examination of a prostate tissue core taken with a thick needle', 'Mikroskopski pregled tkivnog cilindra prostate uzetog debelom iglom', 'Микроскопски преглед ткивног цилиндра простате узетог дебелом иглом', 'Микроскопическое исследование столбика ткани предстательной железы, взятого толстой иглой', 'Mikroskopische Untersuchung eines mit dicker Nadel entnommenen Gewebezylinders der Prostata', 'Kalın iğneyle alınan prostat dokusu silindirinin mikroskobik incelemesi', 'The core, obtained under transrectal ultrasound guidance, is processed through paraffin, sectioned and stained; the pathologist describes the glandular tissue along the whole length of the core', 'Cilindar dobijen pod kontrolom transrektalnog ultrazvuka obrađuje se kroz parafin, reže na presjeke i boji; patolog opisuje žljezdano tkivo cijelom dužinom cilindra', 'Цилиндар добијен под контролом трансректалног ултразвука обрађује се кроз парафин, реже на пресјеке и боји; патолог описује жљездано ткиво цијелом дужином цилиндра', 'Столбик, полученный под контролем трансректального УЗИ, проводят через парафин, режут на срезы и окрашивают; патолог описывает железистую ткань по всей длине столбика', 'Der unter transrektaler Ultraschallkontrolle gewonnene Zylinder wird in Paraffin verarbeitet, geschnitten und gefärbt; der Pathologe beschreibt das Drüsengewebe über die gesamte Länge des Zylinders', 'Transrektal ultrason eşliğinde alınan silindir parafinden geçirilir, kesitlenir ve boyanır; patolog bez dokusunu silindirin tüm uzunluğu boyunca tanımlar', 'A rise in PSA, findings on digital rectal examination, a suspicious area on prostate MRI', 'Porast PSA, nalaz pri digitorektalnom pregledu, sumnjiv dio na magnetnoj rezonanci prostate', 'Пораст PSA, налаз при дигиторекталном прегледу, сумњив дио на магнетној резонанци простате', 'Повышение PSA, изменения при пальцевом ректальном исследовании, подозрительный участок на МРТ предстательной железы', 'Anstieg des PSA, Auffälligkeiten bei der digital-rektalen Untersuchung, ein verdächtiger Bereich im MRT der Prostata', 'PSA yükselmesi, parmakla rektal muayenedeki bulgular, prostat MR görüntüsünde şüpheli alan', 'Preparation concerns the puncture itself and is discussed with the urologist; nothing is required from the patient for the laboratory part', 'Priprema se odnosi na samu punkciju i dogovara se sa urologom; za laboratorijski dio od pacijenta se ne traži ništa', 'Припрема се односи на саму пункцију и договара се са урологом; за лабораторијски дио од пацијента се не тражи ништа', 'Подготовка относится к самой пункции и обсуждается с урологом; для лабораторной части от пациента ничего не требуется', 'Die Vorbereitung betrifft die Punktion selbst und wird mit dem Urologen besprochen; für den Laborteil ist vom Patienten nichts erforderlich', 'Hazırlık ponksiyonun kendisiyle ilgilidir ve ürologla konuşulur; laboratuvar bölümü için hastadan bir şey istenmez', 'The report describes the structure of the glands, signs of inflammation, atypia and malignancy, and how much of the core is involved. What this means and whether further tests are needed is decided by the urologist', 'U nalazu se opisuje građa žlijezda, znaci upale, atipije i maligniteta, kao i dužina zahvaćenog dijela cilindra. Šta to znači i da li su potrebna dodatna ispitivanja, odlučuje urolog', 'У налазу се описује грађа жлијезда, знаци упале, атипије и малигнитета, као и дужина захваћеног дијела цилиндра. Шта то значи и да ли су потребна додатна испитивања, одлучује уролог', 'В заключении описывают строение желёз, признаки воспаления, атипии и злокачественности, а также протяжённость изменений в столбике. Что это означает и нужны ли дополнительные исследования, решает уролог', 'Der Befund beschreibt den Aufbau der Drüsen, Zeichen von Entzündung, Atypie und Bösartigkeit sowie die Ausdehnung der Veränderungen im Zylinder. Was das bedeutet und ob weitere Untersuchungen nötig sind, entscheidet der Urologe', 'Raporda bezlerin yapısı, iltihap, atipi ve kötü huyluluk belirtileri ile silindirdeki tutulumun uzunluğu tanımlanır. Bunun ne anlama geldiğine ve ek inceleme gerekip gerekmediğine ürolog karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-needle-prostate-biopsy-multiple-samples'), 'Microscopic examination of several prostate tissue cores taken from different zones according to a sampling scheme', 'Mikroskopski pregled više tkivnih cilindara prostate uzetih iz različitih zona po shemi', 'Микроскопски преглед више ткивних цилиндара простате узетих из различитих зона по схеми', 'Микроскопическое исследование нескольких столбиков ткани предстательной железы, взятых из разных зон по схеме', 'Mikroskopische Untersuchung mehrerer Gewebezylinder der Prostata, die nach einem Entnahmeschema aus verschiedenen Zonen gewonnen wurden', 'Belirli bir şemaya göre farklı bölgelerden alınan birden çok prostat doku silindirinin mikroskobik incelemesi', 'Each core arrives in its own labelled container, is processed and stained separately, and the report gives the result for every sampling zone', 'Svaki cilindar stiže u zasebnoj označenoj posudi, obrađuje se i boji odvojeno, a u nalazu se rezultat navodi za svaku zonu uzorkovanja', 'Сваки цилиндар стиже у засебној означеној посуди, обрађује се и боји одвојено, а у налазу се резултат наводи за сваку зону узорковања', 'Каждый столбик поступает в отдельном маркированном контейнере, обрабатывается и окрашивается отдельно, а в заключении результат приводится по каждой зоне забора', 'Jeder Zylinder kommt in einem eigenen beschrifteten Gefäß an, wird getrennt verarbeitet und gefärbt, und der Befund nennt das Ergebnis für jede Entnahmezone', 'Her silindir kendi etiketli kabında gelir, ayrı işlenip boyanır ve raporda sonuç her örnekleme bölgesi için ayrı verilir', 'A first biopsy using an extended scheme, mapping changes across the zones of the gland, repeat sampling after an earlier uninformative result, assessment before choosing between monitoring and active treatment', 'Prva biopsija po proširenoj shemi, mapiranje promjena po zonama žlijezde, ponovno uzorkovanje poslije ranijeg neinformativnog rezultata, procjena prije izbora između praćenja i aktivnog liječenja', 'Прва биопсија по проширеној схеми, мапирање промјена по зонама жлијезде, поновно узорковање послије ранијег неинформативног резултата, процјена прије избора између праћења и активног лијечења', 'Первичная биопсия по расширенной схеме, картирование изменений по зонам железы, повторный забор после ранее неинформативного результата, оценка перед выбором между наблюдением и активным лечением', 'Erstbiopsie nach erweitertem Schema, Kartierung der Veränderungen über die Zonen der Drüse, erneute Entnahme nach einem zuvor nicht aussagekräftigen Ergebnis, Beurteilung vor der Wahl zwischen Beobachtung und aktiver Behandlung', 'Genişletilmiş şemayla ilk biyopsi, değişikliklerin bez bölgelerine göre haritalanması, daha önce bilgi vermeyen sonucun ardından yeniden örnekleme, izlem ile aktif tedavi arasında seçim öncesi değerlendirme', 'The material is taken during a urological procedure, so no separate preparation is needed for the laboratory work', 'Materijal se uzima tokom urološkog zahvata, pa za rad laboratorije nema posebne pripreme', 'Материјал се узима током уролошког захвата, па за рад лабораторије нема посебне припреме', 'Материал берут во время урологической процедуры, поэтому отдельной подготовки к работе лаборатории нет', 'Das Material wird während eines urologischen Eingriffs entnommen, für die Laborarbeit ist daher keine gesonderte Vorbereitung nötig', 'Materyal ürolojik işlem sırasında alınır, bu nedenle laboratuvar çalışması için ayrı hazırlık gerekmez', 'The result may differ between zones: in some the tissue is unremarkable, in others there is inflammation or atypia. The urologist puts together the full picture of the gland and the further plan', 'Rezultat po zonama može biti različit: negdje je tkivo bez posebnosti, negdje postoji upala ili atipija. Cijelu sliku žlijezde i dalji plan sastavlja urolog', 'Резултат по зонама може бити различит: негдје је ткиво без посебности, негдје постоји упала или атипија. Цијелу слику жлијезде и даљи план саставља уролог', 'Результат по разным зонам может отличаться: где-то ткань без особенностей, где-то есть воспаление или атипия. Полную картину по железе и дальнейший план собирает уролог', 'Das Ergebnis kann sich zwischen den Zonen unterscheiden: an einer Stelle ist das Gewebe unauffällig, an anderer finden sich Entzündung oder Atypien. Das Gesamtbild der Drüse und den weiteren Plan stellt der Urologe zusammen', 'Sonuç bölgeler arasında değişebilir: bir yerde doku olağan, başka bir yerde iltihap ya da atipi bulunabilir. Bezin bütününe ilişkin tabloyu ve sonraki planı ürolog oluşturur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-oral-cavity-biopsy'), 'Microscopic examination of a piece of oral mucosa from the cheek, tongue, gum or palate', 'Mikroskopski pregled isječka sluznice usne duplje, obraza, jezika, desni ili nepca', 'Микроскопски преглед исјечка слузнице усне дупље, образа, језика, десни или непца', 'Микроскопическое исследование фрагмента слизистой оболочки рта — щеки, языка, десны или нёба', 'Mikroskopische Untersuchung eines Stücks Mundschleimhaut von Wange, Zunge, Zahnfleisch oder Gaumen', 'Yanak, dil, diş eti veya damaktan alınan ağız mukozası parçasının mikroskobik incelemesi', 'The piece, taken by a dentist or maxillofacial surgeon under local anaesthesia, is fixed, embedded in paraffin, sectioned and stained for microscopic study', 'Isječak koji stomatolog ili maksilofacijalni hirurg uzme u lokalnoj anesteziji fiksira se, ukalupljuje u parafin, reže i boji za pregled pod mikroskopom', 'Исјечак који стоматолог или максилофацијални хирург узме у локалној анестезији фиксира се, укалупљује у парафин, реже и боји за преглед под микроскопом', 'Фрагмент, взятый стоматологом или челюстно-лицевым хирургом под местным обезболиванием, фиксируют, заливают в парафин, режут и окрашивают для изучения под микроскопом', 'Das vom Zahnarzt oder Mund-Kiefer-Gesichts-Chirurgen in örtlicher Betäubung entnommene Stück wird fixiert, in Paraffin eingebettet, geschnitten und für die mikroskopische Beurteilung gefärbt', 'Diş hekimi ya da çene cerrahının lokal anesteziyle aldığı parça tespit edilir, parafine gömülür, kesilir ve mikroskopta incelenmek üzere boyanır', 'White or red patches on the mucosa, an ulcer that will not heal, an overgrowth on the gum, changes under a removable denture, chronic inflammatory conditions of the oral lining', 'Bijele ili crvene mrlje na sluznici, ranica koja ne zarasta, izraslina na desni, promjene ispod pokretne proteze, hronična upalna oboljenja sluznice usta', 'Бијеле или црвене мрље на слузници, раница која не зараста, израслина на десни, промјене испод покретне протезе, хронична упална обољења слузнице уста', 'Белые или красные пятна на слизистой, длительно незаживающая язва, разрастание на десне, изменения под съёмным протезом, хронические воспалительные заболевания слизистой рта', 'Weiße oder rote Flecken auf der Schleimhaut, ein nicht heilendes Geschwür, eine Wucherung am Zahnfleisch, Veränderungen unter einer herausnehmbaren Prothese, chronisch entzündliche Erkrankungen der Mundschleimhaut', 'Mukozada beyaz ya da kırmızı lekeler, iyileşmeyen yara, diş etinde büyüme, hareketli protez altındaki değişiklikler, ağız mukozasının süregelen iltihabi hastalıkları', 'There is no preparation for the laboratory stage; on the day of the procedure the dentist may ask you to avoid antiseptic mouth rinses', 'Za laboratorijski dio nema pripreme; na dan zahvata stomatolog može tražiti da se ne koriste antiseptične vodice za ispiranje usta', 'За лабораторијски дио нема припреме; на дан захвата стоматолог може тражити да се не користе антисептичне водице за испирање уста', 'Подготовки к лабораторному этапу нет; в день вмешательства стоматолог может попросить не пользоваться антисептическими ополаскивателями', 'Für den Laborteil gibt es keine Vorbereitung; am Tag des Eingriffs kann der Zahnarzt bitten, auf antiseptische Mundspülungen zu verzichten', 'Laboratuvar aşaması için hazırlık yoktur; işlem günü diş hekimi antiseptik gargara kullanılmamasını isteyebilir', 'The report shows whether this is inflammation, a change in the keratinisation of the mucosa or a process that needs further monitoring. How to act on it is decided by the dentist or maxillofacial surgeon', 'Nalaz pokazuje da li se radi o upali, promjeni orožavanja sluznice ili o procesu koji traži dalje praćenje. Kako to uzeti u obzir i šta dalje, određuje stomatolog ili maksilofacijalni hirurg', 'Налаз показује да ли се ради о упали, промјени орожавања слузнице или о процесу који тражи даље праћење. Како то узети у обзир и шта даље, одређује стоматолог или максилофацијални хирург', 'Заключение показывает, идёт ли речь о воспалении, изменении ороговения слизистой или о процессе, который требует дальнейшего наблюдения. Как это учитывать и что делать дальше, определяет стоматолог или челюстно-лицевой хирург', 'Der Befund zeigt, ob es sich um eine Entzündung, eine veränderte Verhornung der Schleimhaut oder einen Prozess handelt, der weiter beobachtet werden muss. Wie damit umzugehen ist, entscheidet der Zahnarzt oder MKG-Chirurg', 'Rapor bunun bir iltihap mı, mukozanın boynuzlaşmasındaki bir değişiklik mi, yoksa izlem gerektiren bir süreç mi olduğunu gösterir. Bunun nasıl değerlendirileceğine diş hekimi ya da çene cerrahı karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-orchiectomy-testis-examination'), 'Examination of a testis removed during surgery, with a description of the whole tissue and its coverings', 'Pregled testisa odstranjenog tokom operacije, sa opisom cjelokupnog tkiva i ovojnica', 'Преглед тестиса одстрањеног током операције, са описом цјелокупног ткива и овојница', 'Исследование яичка, удалённого во время операции, с описанием всей ткани и оболочек', 'Untersuchung eines operativ entfernten Hodens mit Beschreibung des gesamten Gewebes und seiner Hüllen', 'Ameliyatla çıkarılan testisin, tüm dokusu ve zarlarıyla birlikte incelenmesi', 'The pathologist measures and describes the organ, takes sections through the altered area, the epididymis and the spermatic cord, prepares paraffin blocks and studies the slides; large specimens take several working days', 'Patolog mjeri i opisuje organ, pravi presjeke kroz promijenjeni dio, epididimis i sjemenu vrpcu, priprema parafinske blokove i pregleda preparate pod mikroskopom; veliki materijal traži nekoliko radnih dana', 'Патолог мјери и описује орган, прави пресјеке кроз промијењени дио, епидидимис и сјемену врпцу, припрема парафинске блокове и прегледа препарате под микроскопом; велики материјал тражи неколико радних дана', 'Патолог измеряет и описывает орган, делает срезы через изменённый участок, придаток и семенной канатик, готовит парафиновые блоки и изучает препараты под микроскопом; крупный материал требует нескольких рабочих дней', 'Der Pathologe misst und beschreibt das Organ, entnimmt Schnitte durch den veränderten Bereich, den Nebenhoden und den Samenstrang, fertigt Paraffinblöcke an und beurteilt die Präparate; große Präparate benötigen mehrere Arbeitstage', 'Patolog organı ölçüp tanımlar, değişiklik gösteren bölgeden, epididimden ve spermatik korddan kesitler alır, parafin bloklar hazırlar ve preparatları mikroskopta inceler; büyük materyal birkaç iş günü alır', 'Surgical removal of a testis because of a mass, torsion with non-viable tissue, a severe inflammatory process, and operations for an undescended testis', 'Hirurško odstranjenje testisa zbog tvorbe, zbog torzije sa nevitalnim tkivom, zbog teškog upalnog procesa, kao i zahvati zbog nespuštenog testisa', 'Хируршко одстрањење тестиса због творбе, због торзије са невиталним ткивом, због тешког упалног процеса, као и захвати због неспуштеног тестиса', 'Оперативное удаление яичка при образовании, при перекруте с нежизнеспособной тканью, при тяжёлом воспалительном процессе, а также при вмешательствах по поводу неопустившегося яичка', 'Operative Entfernung eines Hodens wegen einer Raumforderung, bei Torsion mit nicht mehr durchblutetem Gewebe, bei schwerer Entzündung sowie bei Eingriffen wegen eines Hodenhochstands', 'Kitle nedeniyle testisin cerrahi olarak çıkarılması, dokunun canlılığını yitirdiği torsiyon, ağır iltihabi süreç ve inmemiş testis nedeniyle yapılan girişimler', 'No preparation is required: the specimen reaches the laboratory straight from the operating theatre', 'Priprema nije potrebna: materijal u laboratoriju stiže direktno iz operacione sale', 'Припрема није потребна: материјал у лабораторију стиже директно из операционе сале', 'Подготовка не требуется: материал поступает в лабораторию прямо из операционной', 'Eine Vorbereitung ist nicht erforderlich: Das Präparat gelangt direkt aus dem Operationssaal ins Labor', 'Hazırlık gerekmez: materyal laboratuvara doğrudan ameliyathaneden ulaşır', 'The report describes the type of tissue, how far changes reach the coverings and the cord, and the state of the resection margin. It is issued by the pathologist, and further treatment is planned by the urologist', 'Nalaz opisuje vrstu tkiva, širenje promjena na ovojnice i vrpcu i stanje resekcione ivice. Izdaje ga ljekar patolog, a dalje liječenje planira urolog', 'Налаз описује врсту ткива, ширење промјена на овојнице и врпцу и стање ресекционе ивице. Издаје га љекар патолог, а даље лијечење планира уролог', 'Заключение описывает тип ткани, распространение изменений на оболочки и канатик, состояние края резекции. Выдаёт его врач-патолог, а дальнейшее лечение планирует уролог', 'Der Befund beschreibt die Gewebeart, die Ausbreitung der Veränderungen auf Hüllen und Samenstrang sowie den Resektionsrand. Erstellt wird er vom Pathologen, die weitere Behandlung plant der Urologe', 'Rapor doku tipini, değişikliklerin zarlara ve korda yayılımını ve cerrahi sınırın durumunu tanımlar. Raporu patoloji uzmanı verir, sonraki tedaviyi ürolog planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-other-biopsies'), 'Processing and microscopic examination of biopsy material that does not fall under the separately listed biopsy types', 'Obrada i mikroskopski pregled biopsijskog materijala koji ne spada u posebno navedene vrste biopsija', 'Обрада и микроскопски преглед биопсијског материјала који не спада у посебно наведене врсте биопсија', 'Обработка и микроскопическое исследование биопсийного материала, который не относится к отдельно описанным видам биопсий', 'Aufarbeitung und mikroskopische Untersuchung von Biopsiematerial, das keiner der gesondert aufgeführten Biopsiearten zuzuordnen ist', 'Ayrı olarak listelenen biyopsi türlerine girmeyen biyopsi materyalinin işlenmesi ve mikroskobik incelenmesi', 'The material is fixed, processed through paraffin, sectioned, stained and described in the standard way; the amount of work depends on the size and number of fragments', 'Materijal se fiksira, obrađuje kroz parafin, reže na presjeke, boji i opisuje po uobičajenom postupku; obim posla zavisi od veličine i broja isječaka', 'Материјал се фиксира, обрађује кроз парафин, реже на пресјеке, боји и описује по уобичајеном поступку; обим посла зависи од величине и броја исјечака', 'Материал фиксируют, проводят через парафин, режут на срезы, окрашивают и описывают в общем порядке; объём работы зависит от размера и числа фрагментов', 'Das Material wird fixiert, in Paraffin verarbeitet, geschnitten, gefärbt und nach dem üblichen Ablauf beschrieben; der Aufwand hängt von Größe und Zahl der Gewebestücke ab', 'Materyal tespit edilir, parafinden geçirilir, kesitlenir, boyanır ve olağan düzende tanımlanır; iş yükü parçaların boyutuna ve sayısına bağlıdır', 'Tissue taken during procedures that are not listed separately: small soft tissue lesions, mucosal fragments, material from minor outpatient operations', 'Uzimanje tkiva pri zahvatima koji nisu posebno navedeni: manje tvorbe mekih tkiva, isječci sluznica, materijal poslije malih ambulantnih operacija', 'Узимање ткива при захватима који нису посебно наведени: мање творбе меких ткива, исјечци слузница, материјал послије малих амбулантних операција', 'Забор ткани при вмешательствах, не перечисленных отдельно: небольшие образования мягких тканей, фрагменты слизистых, материал после малых амбулаторных операций', 'Gewebeentnahme bei Eingriffen, die nicht gesondert aufgeführt sind: kleine Weichteilveränderungen, Schleimhautstücke, Material aus kleinen ambulanten Operationen', 'Ayrıca listelenmemiş girişimlerde alınan dokular: küçük yumuşak doku oluşumları, mukoza parçaları, küçük ayaktan ameliyatlardan gelen materyal', 'No preparation is needed from the patient: the material is obtained during the procedure itself', 'Od pacijenta se priprema ne traži: materijal se dobija tokom samog zahvata', 'Од пацијента се припрема не тражи: материјал се добија током самог захвата', 'От пациента подготовка не нужна: материал получают во время самой процедуры', 'Vom Patienten ist keine Vorbereitung nötig: Das Material wird während des Eingriffs selbst gewonnen', 'Hastadan hazırlık istenmez: materyal işlemin kendisi sırasında elde edilir', 'The report describes the structure of the submitted tissue and the character of the changes in it. The conclusion is worded by the pathologist, and the referring doctor links it to the clinical situation', 'Nalaz opisuje građu poslatog tkiva i prirodu promjena u njemu. Zaključak formuliše ljekar patolog, a sa kliničkom situacijom ga povezuje ljekar koji je uputio pacijenta', 'Налаз описује грађу послатог ткива и природу промјена у њему. Закључак формулише љекар патолог, а са клиничком ситуацијом га повезује љекар који је упутио пацијента', 'Заключение описывает строение присланной ткани и характер изменений в ней. Итог формулирует врач-патолог, а связывает его с клинической ситуацией направивший врач', 'Der Befund beschreibt den Aufbau des eingesandten Gewebes und die Art der Veränderungen darin. Formuliert wird er vom Pathologen, in den klinischen Zusammenhang stellt ihn der überweisende Arzt', 'Rapor gönderilen dokunun yapısını ve içindeki değişikliklerin niteliğini tanımlar. Sonucu patoloji uzmanı yazar, klinik durumla ilişkilendiren ise sevk eden hekimdir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-pleura-biopsy'), 'Microscopic examination of a piece of pleura, the membrane lining the chest cavity and covering the lungs', 'Mikroskopski pregled isječka pleure, opne koja oblaže grudnu duplju i pokriva pluća', 'Микроскопски преглед исјечка плеуре, опне која облаже грудну дупљу и покрива плућа', 'Микроскопическое исследование фрагмента плевры — оболочки, выстилающей грудную полость и покрывающей лёгкие', 'Mikroskopische Untersuchung eines Stücks Pleura, der Haut, die den Brustraum auskleidet und die Lunge überzieht', 'Göğüs boşluğunu döşeyen ve akciğerleri saran zar olan plevradan alınan parçanın mikroskobik incelemesi', 'The piece, taken during thoracoscopy or a needle biopsy through the chest wall, is fixed, embedded in paraffin, sectioned and stained, with special stains added by the pathologist if needed', 'Isječak uzet torakoskopijom ili punkcionom biopsijom kroz grudni zid fiksira se, ukalupljuje u parafin, reže i boji, a patolog po potrebi dodaje posebna bojenja', 'Исјечак узет торакоскопијом или пункционом биопсијом кроз грудни зид фиксира се, укалупљује у парафин, реже и боји, а патолог по потреби додаје посебна бојења', 'Фрагмент, взятый при торакоскопии или пункционной биопсии через грудную стенку, фиксируют, заливают в парафин, режут и окрашивают, при необходимости патолог добавляет специальные окраски', 'Das bei einer Thorakoskopie oder einer Nadelbiopsie durch die Brustwand entnommene Stück wird fixiert, in Paraffin eingebettet, geschnitten und gefärbt, bei Bedarf ergänzt der Pathologe Spezialfärbungen', 'Torakoskopiyle ya da göğüs duvarından iğne biyopsisiyle alınan parça tespit edilir, parafine gömülür, kesilir ve boyanır, gerekirse patolog özel boyalar ekler', 'Fluid in the pleural cavity of unclear cause, pleural thickening on CT, signs of a granulomatous or occupational process, clarifying the nature of pleural deposits', 'Nakupljanje tečnosti u pleuralnoj duplji nejasnog uzroka, zadebljanje pleure na skeneru, znaci granulomatoznog ili profesionalnog oštećenja, razjašnjenje prirode pleuralnih naslaga', 'Накупљање течности у плеуралној дупљи нејасног узрока, задебљање плеуре на скенеру, знаци грануломатозног или професионалног оштећења, разјашњење природе плеуралних наслага', 'Скопление жидкости в плевральной полости неясной причины, утолщение плевры на КТ, признаки гранулёматозного или профессионального поражения, уточнение природы плевральных наложений', 'Flüssigkeitsansammlung im Pleuraraum unklarer Ursache, Pleuraverdickung im CT, Hinweise auf einen granulomatösen oder berufsbedingten Prozess, Abklärung pleuraler Auflagerungen', 'Nedeni belirsiz plevral sıvı birikimi, BT''de plevra kalınlaşması, granülomatöz ya da mesleki tutulum belirtileri, plevra üzerindeki birikimlerin niteliğinin aydınlatılması', 'Preparation concerns the sampling procedure itself and is discussed with the pulmonologist or thoracic surgeon; the laboratory stage needs no preparation', 'Priprema se odnosi na sam zahvat uzimanja i dogovara se sa pulmologom ili grudnim hirurgom; laboratorijski dio ne traži pripremu', 'Припрема се односи на сам захват узимања и договара се са пулмологом или грудним хирургом; лабораторијски дио не тражи припрему', 'Подготовка относится к самой процедуре забора и обсуждается с пульмонологом или торакальным хирургом; лабораторный этап подготовки не требует', 'Die Vorbereitung betrifft den Entnahmeeingriff selbst und wird mit dem Pneumologen oder Thoraxchirurgen besprochen; der Laborteil erfordert keine Vorbereitung', 'Hazırlık örnek alma işleminin kendisiyle ilgilidir ve göğüs hastalıkları uzmanı ya da göğüs cerrahıyla konuşulur; laboratuvar aşaması hazırlık gerektirmez', 'The pathologist describes the state of the lining cells, the degree of fibrosis and inflammation, and signs of malignancy. The treating doctor compares the result with imaging and with analysis of the pleural fluid', 'Patolog opisuje stanje ćelija koje oblažu pleuru, izraženost fibroze i upale i znake maligniteta. Nalaz sa rendgenskim podacima i analizom pleuralne tečnosti poredi ljekar koji vodi liječenje', 'Патолог описује стање ћелија које облажу плеуру, израженост фиброзе и упале и знаке малигнитета. Налаз са рендгенским подацима и анализом плеуралне течности пореди љекар који води лијечење', 'Патолог описывает состояние выстилающих клеток, выраженность фиброза и воспаления, признаки злокачественности. Результат сопоставляет с рентгеновскими данными и анализом плевральной жидкости лечащий врач', 'Der Pathologe beschreibt den Zustand der Deckzellen, das Ausmaß von Fibrose und Entzündung sowie Hinweise auf Bösartigkeit. Der behandelnde Arzt gleicht das Ergebnis mit der Bildgebung und der Untersuchung des Pleuraergusses ab', 'Patolog örtü hücrelerinin durumunu, fibroz ve iltihabın derecesini ve kötü huyluluk belirtilerini tanımlar. Sonucu görüntüleme bulguları ve plevral sıvı incelemesiyle karşılaştıran tedaviyi yürüten hekimdir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-radical-surgery'), 'Examination of a large surgical specimen removed during radical surgery, together with the surrounding fat and lymph nodes', 'Pregled velikog operacionog materijala odstranjenog radikalnom operacijom, zajedno sa okolnim masnim tkivom i limfnim čvorovima', 'Преглед великог операционог материјала одстрањеног радикалном операцијом, заједно са околним масним ткивом и лимфним чворовима', 'Исследование крупного операционного материала, удалённого при радикальной операции, вместе с окружающей клетчаткой и лимфоузлами', 'Untersuchung eines großen Operationspräparats aus einer radikalen Operation samt umgebendem Fettgewebe und Lymphknoten', 'Radikal ameliyatla çıkarılan büyük cerrahi materyalin, çevresindeki yağ dokusu ve lenf düğümleriyle birlikte incelenmesi', 'The pathologist describes the whole specimen, cuts many blocks from the altered area, the resection margins and the lymph nodes, prepares dozens of blocks and studies the sections; because of the volume this takes longer than an ordinary biopsy', 'Patolog opisuje cijeli preparat, isijeca brojne komadiće iz promijenjenog dijela, resekcionih ivica i limfnih čvorova, priprema desetine blokova i pregleda presjeke; zbog obima posao traje duže nego obična biopsija', 'Патолог описује цијели препарат, исијеца бројне комадиће из промијењеног дијела, ресекционих ивица и лимфних чворова, припрема десетине блокова и прегледа пресјеке; због обима посао траје дуже него обична биопсија', 'Патолог описывает препарат целиком, вырезает множество кусочков из изменённого участка, краёв резекции и лимфоузлов, готовит десятки блоков и изучает срезы; из-за объёма работа занимает больше времени, чем обычная биопсия', 'Der Pathologe beschreibt das gesamte Präparat, entnimmt zahlreiche Gewebestücke aus dem veränderten Bereich, den Resektionsrändern und den Lymphknoten, fertigt Dutzende Blöcke an und beurteilt die Schnitte; wegen des Umfangs dauert das länger als eine gewöhnliche Biopsie', 'Patolog materyalin tamamını tanımlar, değişiklik gösteren bölgeden, cerrahi sınırlardan ve lenf düğümlerinden çok sayıda parça alır, onlarca blok hazırlar ve kesitleri inceler; hacim nedeniyle bu iş sıradan bir biyopsiden uzun sürer', 'Radical operations where the removed tissue has to be described and the resection margins and lymph nodes assessed in order to plan further treatment', 'Radikalne operacije kada je potrebno opisati odstranjeno tkivo i procijeniti resekcione ivice i limfne čvorove radi planiranja daljeg liječenja', 'Радикалне операције када је потребно описати одстрањено ткиво и процијенити ресекционе ивице и лимфне чворове ради планирања даљег лијечења', 'Радикальные операции, когда нужно описать удалённую ткань, оценить края резекции и состояние лимфатических узлов для определения дальнейшего лечения', 'Radikale Operationen, bei denen das entfernte Gewebe beschrieben und Resektionsränder sowie Lymphknoten beurteilt werden müssen, um die weitere Behandlung zu planen', 'Çıkarılan dokunun tanımlanması, cerrahi sınırların ve lenf düğümlerinin sonraki tedavi için değerlendirilmesi gereken radikal ameliyatlar', 'There is no preparation: the specimen is sent to the laboratory immediately after the operation', 'Pripreme nema: materijal se u laboratoriju predaje odmah poslije operacije', 'Припреме нема: материјал се у лабораторију предаје одмах послије операције', 'Подготовки нет: материал передают в лабораторию сразу после операции', 'Es gibt keine Vorbereitung: Das Präparat wird unmittelbar nach der Operation ins Labor gegeben', 'Hazırlık yoktur: materyal ameliyattan hemen sonra laboratuvara iletilir', 'The report contains a description of the tissue, the resection margins and the lymph nodes, which is the basis for planning further treatment. It is worded by the pathologist, while the plan is built by the operating doctor together with the relevant specialists', 'Nalaz sadrži opis tkiva, stanja resekcionih ivica i limfnih čvorova, što je osnova za planiranje daljeg liječenja. Formuliše ga ljekar patolog, a plan pravi ljekar koji je operisao zajedno sa odgovarajućim specijalistima', 'Налаз садржи опис ткива, стања ресекционих ивица и лимфних чворова, што је основа за планирање даљег лијечења. Формулише га љекар патолог, а план прави љекар који је оперисао заједно са одговарајућим специјалистима', 'Заключение содержит описание ткани, состояния краёв резекции и лимфатических узлов — это основа для планирования дальнейшего лечения. Формулирует его врач-патолог, а план строит оперировавший врач вместе с профильными специалистами', 'Der Befund enthält die Beschreibung des Gewebes, der Resektionsränder und der Lymphknoten und ist die Grundlage für die weitere Behandlungsplanung. Formuliert wird er vom Pathologen, den Plan erstellt der operierende Arzt gemeinsam mit den zuständigen Fachärzten', 'Rapor dokunun, cerrahi sınırların ve lenf düğümlerinin tanımını içerir ve sonraki tedavinin planlanmasının temelidir. Raporu patoloji uzmanı yazar, planı ise ameliyatı yapan hekim ilgili uzmanlarla birlikte oluşturur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-removed-breast-examination'), 'Examination of a breast removed during surgery, with assessment of the tissue, the skin and the excision margins', 'Pregled dojke odstranjene tokom operacije, sa procjenom tkiva, kože i ivica odstranjenja', 'Преглед дојке одстрањене током операције, са процјеном ткива, коже и ивица одстрањења', 'Исследование молочной железы, удалённой во время операции, с оценкой ткани, кожи и краёв удаления', 'Untersuchung einer operativ entfernten Brust mit Beurteilung von Gewebe, Haut und Exzisionsrändern', 'Ameliyatla çıkarılan memenin, dokusu, derisi ve çıkarım sınırlarıyla birlikte değerlendirilmesi', 'The pathologist orients and measures the specimen, describes the skin and nipple, takes sections through the altered area and the margins, and processes any lymph nodes separately; the specimen is large, so many blocks are produced', 'Patolog orijentiše i mjeri preparat, opisuje kožu i bradavicu, pravi presjeke kroz promijenjeni dio i ivice, a nađene limfne čvorove obrađuje posebno; materijal je velik pa se dobija veliki broj blokova', 'Патолог оријентише и мјери препарат, описује кожу и брадавицу, прави пресјеке кроз промијењени дио и ивице, а нађене лимфне чворове обрађује посебно; материјал је велик па се добија велики број блокова', 'Патолог ориентирует и измеряет препарат, описывает кожу и сосок, делает срезы через изменённый участок и края, отдельно обрабатывает найденные лимфоузлы; материал большой, поэтому блоков получается много', 'Der Pathologe orientiert und misst das Präparat, beschreibt Haut und Brustwarze, entnimmt Schnitte durch den veränderten Bereich und die Ränder und arbeitet gefundene Lymphknoten gesondert auf; das Präparat ist groß, daher entstehen viele Blöcke', 'Patolog materyali yönlendirip ölçer, deriyi ve meme başını tanımlar, değişiklik gösteren bölgeden ve sınırlardan kesitler alır, bulunan lenf düğümlerini ayrı işler; materyal büyük olduğundan çok sayıda blok çıkar', 'Surgery to remove the breast, including after an earlier biopsy, and preventive removal decided together with the doctor', 'Operacija odstranjenja dojke, uključujući i onu poslije ranije urađene biopsije, kao i preventivno odstranjenje o kojem se odlučuje sa ljekarom', 'Операција одстрањења дојке, укључујући и ону послије раније урађене биопсије, као и превентивно одстрањење о којем се одлучује са љекаром', 'Операция по удалению молочной железы, в том числе после ранее выполненной биопсии, а также профилактическое удаление по решению врача', 'Operative Entfernung der Brust, auch nach einer zuvor durchgeführten Biopsie, sowie eine vorbeugende Entfernung, über die gemeinsam mit dem Arzt entschieden wird', 'Daha önce biyopsi yapılmış olsun ya da olmasın memenin çıkarıldığı ameliyatlar ve hekimle birlikte karar verilen önleyici çıkarım', 'No preparation is required: the specimen arrives in the laboratory from the operating theatre with the surgeon''s markings', 'Priprema nije potrebna: preparat u laboratoriju stiže iz operacione sale sa oznakama hirurga', 'Припрема није потребна: препарат у лабораторију стиже из операционе сале са ознакама хирурга', 'Подготовка не требуется: препарат поступает в лабораторию из операционной с маркировкой хирурга', 'Eine Vorbereitung ist nicht erforderlich: Das Präparat kommt aus dem Operationssaal mit den Markierungen des Chirurgen ins Labor', 'Hazırlık gerekmez: materyal ameliyathaneden cerrahın işaretlemeleriyle laboratuvara ulaşır', 'The report describes the size and structure of the altered area, its relation to the excision margins and the state of the lymph nodes. The description comes from the pathologist, while further care is decided by the operating surgeon', 'Nalaz opisuje veličinu i građu promijenjenog dijela, njegov odnos prema ivicama odstranjenja i stanje limfnih čvorova. Opis daje ljekar patolog, a dalje vođenje određuje hirurg koji je operisao', 'Налаз описује величину и грађу промијењеног дијела, његов однос према ивицама одстрањења и стање лимфних чворова. Опис даје љекар патолог, а даље вођење одређује хирург који је оперисао', 'Заключение описывает размер и строение изменённого участка, его отношение к краям удаления и состояние лимфоузлов. Описание даёт врач-патолог, а дальнейшее ведение определяет оперировавший хирург', 'Der Befund beschreibt Größe und Aufbau des veränderten Bereichs, seinen Bezug zu den Exzisionsrändern und den Zustand der Lymphknoten. Die Beschreibung stammt vom Pathologen, das weitere Vorgehen legt der operierende Chirurg fest', 'Rapor değişiklik gösteren bölgenin boyutunu ve yapısını, çıkarım sınırlarıyla ilişkisini ve lenf düğümlerinin durumunu tanımlar. Tanımı patoloji uzmanı yapar, sonraki izlemi ameliyatı yapan cerrah belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-report-review'), 'A second reading of existing histology slides and of a report already issued by another laboratory', 'Ponovni pregled već urađenih histoloških preparata i nalaza izdatog u drugoj laboratoriji', 'Поновни преглед већ урађених хистолошких препарата и налаза издатог у другој лабораторији', 'Повторный просмотр готовых гистологических препаратов и уже выданного заключения, сделанного в другой лаборатории', 'Zweitbeurteilung bereits angefertigter histologischer Präparate und eines in einem anderen Labor erstellten Befundes', 'Başka bir laboratuvarda hazırlanmış histoloji preparatlarının ve verilmiş raporun yeniden değerlendirilmesi', 'The pathologist re-examines the submitted slides, cuts new sections from the paraffin blocks if needed, and compares their own description with the original; no new material is taken from the patient', 'Patolog iznova pregleda dostavljena stakla, po potrebi pravi nove presjeke iz parafinskih blokova i poredi svoj opis sa prvobitnim; novi materijal se od pacijenta ne uzima', 'Патолог изнова прегледа достављена стакла, по потреби прави нове пресјеке из парафинских блокова и пореди свој опис са првобитним; нови материјал се од пацијента не узима', 'Патолог заново изучает присланные стёкла, при необходимости делает новые срезы из парафиновых блоков и сравнивает своё описание с исходным; новый материал у пациента не берут', 'Der Pathologe sieht die eingereichten Objektträger erneut durch, fertigt bei Bedarf neue Schnitte aus den Paraffinblöcken an und vergleicht die eigene Beschreibung mit der ursprünglichen; neues Material wird dem Patienten nicht entnommen', 'Patolog gönderilen lamları yeniden inceler, gerekirse parafin bloklardan yeni kesitler alır ve kendi tanımını ilk raporla karşılaştırır; hastadan yeni materyal alınmaz', 'A second opinion before starting treatment, a result that does not fit the clinical picture, a change of clinic or doctor, preparation for a multidisciplinary meeting before complex surgery', 'Drugo mišljenje prije početka liječenja, nalaz koji se ne slaže sa kliničkom slikom, promjena klinike ili ljekara, priprema za konzilijum prije složene operacije', 'Друго мишљење прије почетка лијечења, налаз који се не слаже са клиничком сликом, промјена клинике или љекара, припрема за конзилијум прије сложене операције', 'Второе мнение перед началом лечения, расхождение результата с клинической картиной, смена клиники или врача, подготовка к консилиуму перед сложной операцией', 'Zweitmeinung vor Behandlungsbeginn, ein Ergebnis, das nicht zum klinischen Bild passt, Wechsel von Klinik oder Arzt, Vorbereitung einer Fallkonferenz vor einer aufwendigen Operation', 'Tedaviye başlamadan önce ikinci görüş, klinik tabloyla örtüşmeyen sonuç, klinik ya da hekim değişikliği, zorlu bir ameliyat öncesi konsey hazırlığı', 'Obtain the slides and paraffin blocks from the first laboratory in advance and bring them together with a copy of the original report and your medical records', 'Potrebno je unaprijed preuzeti stakla i parafinske blokove iz prve laboratorije i donijeti ih sa kopijom prvobitnog nalaza i medicinskom dokumentacijom', 'Потребно је унапријед преузети стакла и парафинске блокове из прве лабораторије и донијети их са копијом првобитног налаза и медицинском документацијом', 'Нужно заранее получить в первой лаборатории стёкла и парафиновые блоки и принести их вместе с копией исходного заключения и медицинской документацией', 'Objektträger und Paraffinblöcke im Erstlabor vorab anfordern und zusammen mit einer Kopie des ursprünglichen Befundes und den Arztunterlagen mitbringen', 'İlk laboratuvardan lamlar ve parafin bloklar önceden alınmalı, ilk raporun bir kopyası ve tıbbi belgelerle birlikte getirilmelidir', 'The second description may agree with the first, refine it or differ from it. The treating doctor compares both reports and decides whether this changes the treatment', 'Drugi opis može se poklopiti sa prvim, dopuniti ga ili se od njega razlikovati. Oba nalaza poredi i odlučuje da li to mijenja liječenje ljekar koji vodi liječenje', 'Други опис може се поклопити са првим, допунити га или се од њега разликовати. Оба налаза пореди и одлучује да ли то мијења лијечење љекар који води лијечење', 'Повторное описание может совпасть с первым, уточнить его или разойтись с ним. Сравнивает оба заключения и решает, влияет ли это на лечение, лечащий врач', 'Die zweite Beschreibung kann mit der ersten übereinstimmen, sie präzisieren oder von ihr abweichen. Der behandelnde Arzt vergleicht beide Befunde und entscheidet, ob sich daraus Änderungen für die Behandlung ergeben', 'İkinci tanım ilkiyle örtüşebilir, onu netleştirebilir ya da ondan ayrılabilir. İki raporu karşılaştırıp bunun tedaviyi değiştirip değiştirmediğine tedaviyi yürüten hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-single-prostate-biopsy'), 'Microscopic examination of a single prostate tissue fragment handled as a separate sample', 'Mikroskopski pregled pojedinačnog isječka tkiva prostate obrađenog kao zaseban uzorak', 'Микроскопски преглед појединачног исјечка ткива простате обрађеног као засебан узорак', 'Микроскопическое исследование отдельного фрагмента ткани предстательной железы, обработанного как самостоятельная проба', 'Mikroskopische Untersuchung eines einzelnen Prostatagewebestücks, das als eigenständige Probe aufgearbeitet wird', 'Ayrı bir örnek olarak işlenen tek bir prostat doku parçasının mikroskobik incelemesi', 'The fragment goes into its own block, is sectioned and stained, and the description refers precisely to that part of the gland', 'Isječak se stavlja u zaseban blok, prave se presjeci i boje, a opis se odnosi upravo na taj dio žlijezde', 'Исјечак се ставља у засебан блок, праве се пресјеци и боје, а опис се односи управо на тај дио жлијезде', 'Фрагмент помещают в отдельный блок, делают срезы и окрашивают, а описание относится именно к этому участку железы', 'Das Gewebestück kommt in einen eigenen Block, wird geschnitten und gefärbt, und die Beschreibung bezieht sich genau auf diesen Abschnitt der Drüse', 'Parça kendi bloğuna konur, kesitlenir ve boyanır; tanım tam olarak bezin bu bölümüne ilişkindir', 'Targeted sampling of one area seen on ultrasound or MRI, follow-up study of a single zone, repeat sampling from a previously described area', 'Ciljano uzorkovanje jednog dijela uočenog ultrazvukom ili magnetnom rezonancom, dodatna obrada pojedine zone, ponovno uzorkovanje iz ranije opisanog dijela', 'Циљано узорковање једног дијела уоченог ултразвуком или магнетном резонанцом, додатна обрада поједине зоне, поновно узорковање из раније описаног дијела', 'Прицельный забор из одного участка, выявленного при УЗИ или МРТ, доисследование отдельной зоны, повторный забор из ранее описанного участка', 'Gezielte Entnahme aus einem im Ultraschall oder MRT auffälligen Bereich, ergänzende Abklärung einer einzelnen Zone, erneute Entnahme aus einem zuvor beschriebenen Bereich', 'Ultrason ya da MR''da görülen tek bir alandan hedefe yönelik örnekleme, tek bir bölgenin ek olarak incelenmesi, daha önce tanımlanmış alandan yeniden örnekleme', 'The patient does not prepare for the laboratory stage; preparation for the procedure itself is explained by the urologist', 'Pacijent se za laboratorijski dio ne priprema, a pripremu za sam zahvat objašnjava urolog', 'Пацијент се за лабораторијски дио не припрема, а припрему за сам захват објашњава уролог', 'Пациенту к лабораторному этапу готовиться не нужно, подготовку к самой процедуре объясняет уролог', 'Für den Laborteil bereitet sich der Patient nicht vor, die Vorbereitung auf den Eingriff selbst erklärt der Urologe', 'Hasta laboratuvar aşaması için hazırlanmaz, işlemin kendisine hazırlığı ürolog anlatır', 'The description covers only the submitted fragment, so the absence of changes in it says nothing about the whole gland. The urologist assesses the result in context', 'Opis se tiče samo poslatog isječka, pa odsustvo promjena u njemu ne govori o stanju cijele žlijezde. Nalaz u sklopu ostalog procjenjuje urolog', 'Опис се тиче само послатог исјечка, па одсуство промјена у њему не говори о стању цијеле жлијезде. Налаз у склопу осталог процјењује уролог', 'Описание касается только присланного фрагмента, поэтому отсутствие изменений в нём не говорит о состоянии всей железы. Оценивает результат в комплексе уролог', 'Die Beschreibung betrifft nur das eingesandte Gewebestück, fehlende Veränderungen darin sagen daher nichts über die gesamte Drüse aus. Der Urologe beurteilt das Ergebnis im Gesamtzusammenhang', 'Tanım yalnızca gönderilen parçayı kapsar, bu nedenle onda değişiklik bulunmaması bezin tamamı hakkında bilgi vermez. Sonucu bütünlük içinde ürolog değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-skin-tumor-each-additional-sample'), 'Processing of each further skin lesion sample submitted under the same referral after the first one', 'Obrada svakog sljedećeg uzorka kožne promjene poslatog po istoj uputnici poslije prvog', 'Обрада сваког сљедећег узорка кожне промјене послатог по истој упутници послије првог', 'Обработка каждого следующего образца кожного образования, присланного по тому же направлению после первого', 'Aufarbeitung jeder weiteren Hautveränderung, die nach der ersten mit derselben Überweisung eingesandt wird', 'Aynı sevkle birincisinden sonra gönderilen her bir ek deri lezyonu örneğinin işlenmesi', 'Every removed lesion is handled separately: measured, cut through the centre and the edges, embedded in paraffin, sectioned and stained, so that the description refers to that particular lesion', 'Svaka odstranjena promjena obrađuje se zasebno: mjeri se, isijeca kroz sredinu i ivice, ukalupljuje u parafin, reže i boji, tako da se opis odnosi na tu konkretnu promjenu', 'Свака одстрањена промјена обрађује се засебно: мјери се, исијеца кроз средину и ивице, укалупљује у парафин, реже и боји, тако да се опис односи на ту конкретну промјену', 'Каждое удалённое образование обрабатывают отдельно: измеряют, вырезают через центр и края, заливают в парафин, режут и окрашивают, чтобы описание относилось к конкретному элементу', 'Jede entfernte Veränderung wird getrennt bearbeitet: gemessen, durch Zentrum und Ränder geschnitten, in Paraffin eingebettet, geschnitten und gefärbt, damit sich die Beschreibung auf genau diese Veränderung bezieht', 'Çıkarılan her lezyon ayrı ele alınır: ölçülür, merkezinden ve kenarlarından kesilir, parafine gömülür, kesitlenir ve boyanır; böylece tanım o lezyona ilişkin olur', 'Removal of several moles, papillomas or other skin lesions at one visit, when each element has to be described separately', 'Odstranjenje više mladeža, papiloma ili drugih promjena na koži tokom jedne posjete, kada svaku promjenu treba opisati zasebno', 'Одстрањење више младежа, папилома или других промјена на кожи током једне посјете, када сваку промјену треба описати засебно', 'Удаление нескольких родинок, папиллом или иных кожных образований за одно посещение, когда каждый элемент нужно описать отдельно', 'Entfernung mehrerer Muttermale, Papillome oder anderer Hautveränderungen bei einem Termin, wenn jede Veränderung einzeln beschrieben werden muss', 'Tek bir ziyarette birden çok ben, papilloma ya da başka deri lezyonunun çıkarılması ve her birinin ayrı tanımlanmasının gerekmesi', 'No preparation for the examination is needed: the samples are taken while the lesions are being removed', 'Priprema za pregled nije potrebna: uzorci se uzimaju tokom odstranjenja promjena', 'Припрема за преглед није потребна: узорци се узимају током одстрањења промјена', 'Подготовка к исследованию не нужна: образцы берут во время удаления образований', 'Eine Vorbereitung auf die Untersuchung ist nicht nötig: Die Proben entstehen beim Entfernen der Veränderungen', 'İnceleme için hazırlık gerekmez: örnekler lezyonların çıkarılması sırasında alınır', 'For each sample the pathologist separately describes the type of lesion, its borders and signs of malignancy. The dermatologist or surgeon assesses the results for all the lesions together', 'Za svaki uzorak patolog posebno opisuje vrstu promjene, njene ivice i znake maligniteta. Nalaze za sve promjene zajedno procjenjuje dermatolog ili hirurg', 'За сваки узорак патолог посебно описује врсту промјене, њене ивице и знаке малигнитета. Налазе за све промјене заједно процјењује дерматолог или хирург', 'По каждому образцу патолог отдельно описывает тип образования, его границы и признаки злокачественности. Результаты по всем элементам вместе оценивает дерматолог или хирург', 'Für jede Probe beschreibt der Pathologe gesondert die Art der Veränderung, ihre Ränder und Hinweise auf Bösartigkeit. Die Ergebnisse aller Veränderungen zusammen beurteilt der Hautarzt oder der Chirurg', 'Patolog her örnek için lezyonun tipini, sınırlarını ve kötü huyluluk belirtilerini ayrı tanımlar. Tüm lezyonlara ilişkin sonuçları birlikte dermatolog ya da cerrah değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-standard-diagnostics'), 'Basic histological processing of submitted tissue with routine staining and no additional techniques', 'Osnovna histološka obrada poslatog tkiva sa uobičajenim bojenjem, bez dodatnih metoda', 'Основна хистолошка обрада послатог ткива са уобичајеним бојењем, без додатних метода', 'Базовая гистологическая обработка присланной ткани с обычным окрашиванием, без дополнительных методик', 'Grundlegende histologische Aufarbeitung des eingesandten Gewebes mit Routinefärbung und ohne zusätzliche Verfahren', 'Gönderilen dokunun ek yöntem kullanılmadan, olağan boyamayla yapılan temel histolojik işlenmesi', 'The tissue is fixed in formalin, dehydrated, embedded in paraffin, cut into thin sections and stained with haematoxylin and eosin; special stains and immunohistochemistry are ordered separately', 'Tkivo se fiksira u formalinu, dehidrira, ukalupljuje u parafin, reže na tanke presjeke i boji hematoksilinom i eozinom; posebna bojenja i imunohistohemija traže se odvojeno', 'Ткиво се фиксира у формалину, дехидрира, укалупљује у парафин, реже на танке пресјеке и боји хематоксилином и еозином; посебна бојења и имунохистохемија траже се одвојено', 'Ткань фиксируют в формалине, обезвоживают, заливают в парафин, режут на тонкие срезы и окрашивают гематоксилином и эозином; специальные окраски и иммуногистохимия назначаются отдельно', 'Das Gewebe wird in Formalin fixiert, entwässert, in Paraffin eingebettet, in dünne Schnitte geschnitten und mit Hämatoxylin und Eosin gefärbt; Spezialfärbungen und Immunhistochemie werden gesondert angefordert', 'Doku formalinde tespit edilir, suyu alınır, parafine gömülür, ince kesitlere ayrılır ve hematoksilen ile eozinle boyanır; özel boyalar ve immünhistokimya ayrıca istenir', 'The standard scope of examination for most biopsies and small surgical specimens, when routine staining is enough for the description', 'Standardni obim pregleda za većinu biopsija i manjih operacionih materijala, kada je za opis dovoljno uobičajeno bojenje', 'Стандардни обим прегледа за већину биопсија и мањих операционих материјала, када је за опис довољно уобичајено бојење', 'Стандартный объём исследования для большинства биопсий и небольших операционных материалов, когда для описания достаточно рутинного окрашивания', 'Der Standardumfang für die meisten Biopsien und kleinen Operationspräparate, wenn die Routinefärbung für die Beschreibung ausreicht', 'Tanım için olağan boyamanın yeterli olduğu durumlarda çoğu biyopsi ve küçük cerrahi materyal için standart inceleme kapsamı', 'There is no separate preparation: work begins once the material reaches the laboratory', 'Posebne pripreme nema: rad počinje kada materijal stigne u laboratoriju', 'Посебне припреме нема: рад почиње када материјал стигне у лабораторију', 'Отдельной подготовки нет: работа начинается после поступления материала в лабораторию', 'Eine gesonderte Vorbereitung entfällt: Die Arbeit beginnt, sobald das Material im Labor eingeht', 'Ayrı bir hazırlık yoktur: çalışma materyal laboratuvara ulaştığında başlar', 'In most cases routine staining is enough to describe the tissue structure; sometimes the pathologist additionally requests special methods. The report is interpreted by the treating doctor', 'Uobičajeno bojenje u većini slučajeva je dovoljno da se opiše građa tkiva, a patolog ponekad dodatno traži posebne metode. Nalaz tumači ljekar koji vodi liječenje', 'Уобичајено бојење у већини случајева је довољно да се опише грађа ткива, а патолог понекад додатно тражи посебне методе. Налаз тумачи љекар који води лијечење', 'Рутинного окрашивания в большинстве случаев хватает, чтобы описать строение ткани; иногда патолог дополнительно запрашивает специальные методы. Заключение трактует лечащий врач', 'Die Routinefärbung reicht meist aus, um den Gewebeaufbau zu beschreiben; manchmal fordert der Pathologe zusätzlich Spezialverfahren an. Den Befund deutet der behandelnde Arzt', 'Olağan boyama çoğu durumda doku yapısını tanımlamaya yeter; patolog bazen ek olarak özel yöntemler ister. Raporu tedaviyi yürüten hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-standard-skin-and-organ-biopsy'), 'Standard microscopic examination of a small sample of skin or internal organ tissue obtained by biopsy', 'Standardni mikroskopski pregled malog uzorka tkiva kože ili unutrašnjeg organa uzetog biopsijom', 'Стандардни микроскопски преглед малог узорка ткива коже или унутрашњег органа узетог биопсијом', 'Стандартное микроскопическое исследование небольшого образца ткани кожи или внутреннего органа, полученного при биопсии', 'Standardmäßige mikroskopische Untersuchung einer kleinen Gewebeprobe aus der Haut oder einem inneren Organ', 'Deriden ya da bir iç organdan biyopsiyle alınan küçük doku örneğinin standart mikroskopik incelemesi', 'The tissue is fixed in formalin, embedded in paraffin, cut into thin sections, stained with routine stains and examined under a microscope; the report is written by a pathologist', 'Tkivo se fiksira u formalinu, ukalupljuje u parafin, reže na tanke presjeke, boji uobičajenim bojama i pregleda pod mikroskopom; nalaz piše ljekar patolog', 'Ткиво се фиксира у формалину, укалупљује у парафин, реже на танке пресјеке, боји уобичајеним бојама и прегледа под микроскопом; налаз пише љекар патолог', 'Ткань фиксируют в формалине, заливают в парафин, режут на тонкие срезы, окрашивают обычными красителями и изучают под микроскопом; заключение готовит врач-патолог', 'Das Gewebe wird in Formalin fixiert, in Paraffin eingebettet, in dünne Schnitte geschnitten, mit Routinefärbungen gefärbt und unter dem Mikroskop beurteilt; den Befund erstellt die Pathologin oder der Pathologe', 'Doku formalinde tespit edilir, parafine gömülür, ince kesitler alınır, rutin boyalarla boyanır ve mikroskopta değerlendirilir; raporu patoloji uzmanı yazar', 'Moles and skin lesions after removal, skin changes that do not heal or remain unclear, mucosal and organ samples taken at endoscopy or surgery, clarifying the nature of chronic inflammation', 'Mladeži i promjene na koži poslije uklanjanja, promjene koje ne zarastaju ili ostaju nejasne, uzorci sluznica i organa uzeti tokom endoskopije ili operacije, razjašnjenje prirode hronične upale', 'Младежи и промјене на кожи послије уклањања, промјене које не зарастају или остају нејасне, узорци слузница и органа узети током ендоскопије или операције, разјашњење природе хроничне упале', 'Родинки и кожные образования после удаления, длительно незаживающие или неясные изменения кожи, образцы слизистых и органов, взятые при эндоскопии или операции, уточнение природы хронического воспаления', 'Muttermale und Hautveränderungen nach der Entfernung, nicht heilende oder unklare Hautstellen, bei Endoskopie oder Operation entnommene Schleimhaut- und Organproben, Abklärung einer chronischen Entzündung', 'Çıkarılan benler ve deri lezyonları, iyileşmeyen ya da niteliği belirsiz deri değişiklikleri, endoskopi veya ameliyat sırasında alınan mukoza ve organ örnekleri, kronik iltihabın nedeninin araştırılması', 'No separate preparation: the material is obtained during the procedure itself, which the referring doctor explains beforehand', 'Posebne pripreme nema: materijal se uzima tokom samog zahvata, čije uslove objašnjava ljekar koji upućuje', 'Посебне припреме нема: материјал се узима током самог захвата, чије услове објашњава љекар који упућује', 'Отдельной подготовки нет: материал берут во время самой процедуры, условия которой объясняет направивший врач', 'Keine gesonderte Vorbereitung: das Material wird während des Eingriffs selbst gewonnen, dessen Ablauf die überweisende Praxis erklärt', 'Ayrı bir hazırlık yoktur: örnek işlemin kendisi sırasında alınır, işlemin koşullarını yönlendiren hekim anlatır', 'The report describes the structure of the tissue: inflammation, benign changes or features that call for further assessment, including the question of malignancy. What this means in a particular case and what comes next is decided by the treating doctor', 'Nalaz opisuje građu tkiva: upalu, dobroćudne promjene ili nalaze koji traže dalju obradu, uključujući procjenu malignosti. Šta to znači u konkretnom slučaju i koji su sljedeći koraci, određuje ljekar koji vodi liječenje', 'Налаз описује грађу ткива: упалу, доброћудне промјене или налазе који траже даљу обраду, укључујући процјену малигности. Шта то значи у конкретном случају и који су сљедећи кораци, одређује љекар који води лијечење', 'Заключение описывает строение ткани: воспаление, доброкачественные изменения или признаки, требующие дальнейшего обследования, включая оценку злокачественности. Что это значит в конкретном случае и что делать дальше, определяет лечащий врач', 'Der Befund beschreibt den Gewebeaufbau: Entzündung, gutartige Veränderungen oder Merkmale, die weitere Abklärung erfordern, einschließlich der Beurteilung von Bösartigkeit. Was das im Einzelfall bedeutet und wie es weitergeht, entscheidet die behandelnde Ärztin oder der behandelnde Arzt', 'Rapor dokunun yapısını tanımlar: iltihap, iyi huylu değişiklikler ya da kötü huyluluk değerlendirmesi dahil ileri inceleme gerektiren bulgular. Bunun o kişide ne anlama geldiğine ve sonraki adımlara tedaviyi yürüten hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-stomach-biopsy'), 'Microscopic examination of small pieces of the stomach lining taken during gastroscopy', 'Mikroskopski pregled komadića sluznice želuca uzetih tokom gastroskopije', 'Микроскопски преглед комадића слузнице желуца узетих током гастроскопије', 'Микроскопическое исследование кусочков слизистой оболочки желудка, взятых при гастроскопии', 'Mikroskopische Untersuchung kleiner Proben der Magenschleimhaut, die bei der Magenspiegelung entnommen wurden', 'Gastroskopi sırasında alınan mide mukozası parçalarının mikroskopla incelenmesi', 'The mucosal fragments taken by the endoscopist are processed into paraffin, cut into sections and stained, if needed with an additional stain for Helicobacter pylori; a pathologist assesses the material', 'Isječci sluznice koje uzme endoskopista provode se kroz parafin, režu na presjeke i boje, po potrebi i posebnim bojenjem na Helicobacter pylori; materijal ocjenjuje ljekar patolog', 'Исјечци слузнице које узме ендоскописта проводе се кроз парафин, режу на пресјеке и боје, по потреби и посебним бојењем на Helicobacter pylori; материјал оцјењује љекар патолог', 'Взятые эндоскопистом фрагменты слизистой проводят через парафин, режут на срезы и окрашивают, при необходимости дополнительной окраской на Helicobacter pylori; материал оценивает врач-патолог', 'Die entnommenen Schleimhautstücke werden in Paraffin eingebettet, geschnitten und gefärbt, bei Bedarf mit einer zusätzlichen Färbung auf Helicobacter pylori; beurteilt wird das Material von der Pathologin oder dem Pathologen', 'Endoskopistin aldığı mukoza parçaları parafine gömülür, kesitlenir ve boyanır, gerekirse Helicobacter pylori için ek boyama yapılır; örneği patoloji uzmanı değerlendirir', 'Long-standing pain and heaviness in the upper abdomen, chronic gastritis, gastric ulcer, suspected Helicobacter pylori infection, follow-up after treatment, clarifying mucosal changes seen at endoscopy', 'Dugotrajan bol i težina u gornjem dijelu stomaka, hronični gastritis, čir na želucu, sumnja na infekciju Helicobacter pylori, kontrola poslije liječenja, razjašnjenje promjena sluznice viđenih na endoskopiji', 'Дуготрајан бол и тежина у горњем дијелу стомака, хронични гастритис, чир на желуцу, сумња на инфекцију Helicobacter pylori, контрола послије лијечења, разјашњење промјена слузнице виђених на ендоскопији', 'Длительная боль и тяжесть в верхней части живота, хронический гастрит, язва желудка, подозрение на инфекцию Helicobacter pylori, контроль после лечения, уточнение изменений слизистой, увиденных при эндоскопии', 'Anhaltende Schmerzen und Völlegefühl im Oberbauch, chronische Gastritis, Magengeschwür, Verdacht auf eine Infektion mit Helicobacter pylori, Kontrolle nach Behandlung, Abklärung bei der Spiegelung gesehener Schleimhautveränderungen', 'Karnın üst kısmında uzun süreli ağrı ve dolgunluk, kronik gastrit, mide ülseri, Helicobacter pylori enfeksiyonu şüphesi, tedavi sonrası kontrol, endoskopide görülen mukoza değişikliklerinin araştırılması', 'Preparation applies to the gastroscopy itself, with no food or drink for several hours before it; the laboratory stage requires nothing from the patient', 'Priprema se odnosi na samu gastroskopiju, kada se nekoliko sati prije zahvata ne jede i ne pije; za laboratorijski dio nema pripreme', 'Припрема се односи на саму гастроскопију, када се неколико сати прије захвата не једе и не пије; за лабораторијски дио нема припреме', 'Подготовка относится к самой гастроскопии, когда за несколько часов до неё не едят и не пьют; лабораторный этап от пациента ничего не требует', 'Die Vorbereitung betrifft die Magenspiegelung selbst, vor der einige Stunden nichts gegessen und getrunken wird; für den Laborteil ist nichts vorzubereiten', 'Hazırlık gastroskopiyle ilgilidir, işlemden birkaç saat önce yeme ve içme kesilir; laboratuvar aşamasında hazırlık gerekmez', 'The report describes the state of the lining: activity of inflammation, atrophy, presence of the bacterium, changes in the cells or findings that need follow-up. The gastroenterologist matches this with the symptoms and decides what comes next', 'Nalaz opisuje stanje sluznice: aktivnost upale, atrofiju, prisustvo bakterije, promjene ćelija ili nalaze koji traže praćenje. Sa tegobama to poredi i dalji postupak određuje gastroenterolog', 'Налаз описује стање слузнице: активност упале, атрофију, присуство бактерије, промјене ћелија или налазе који траже праћење. Са тегобама то пореди и даљи поступак одређује гастроентеролог', 'Заключение описывает состояние слизистой: активность воспаления, атрофию, наличие бактерии, изменения клеток или находки, требующие наблюдения. Сопоставляет это с жалобами и определяет дальнейшую тактику гастроэнтеролог', 'Der Befund beschreibt den Zustand der Schleimhaut: Entzündungsaktivität, Atrophie, Nachweis des Bakteriums, Zellveränderungen oder kontrollbedürftige Auffälligkeiten. Die Gastroenterologie ordnet das den Beschwerden zu und legt das weitere Vorgehen fest', 'Rapor mukozanın durumunu tanımlar: iltihabın etkinliği, atrofi, bakterinin varlığı, hücre değişiklikleri ya da izlem gerektiren bulgular. Bunu şikayetlerle birlikte değerlendirip izlenecek yolu gastroenteroloji uzmanı belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-subcutaneous-tumor-examination'), 'Microscopic examination of a subcutaneous lump that the surgeon removed whole', 'Mikroskopski pregled potkožne tvorbe koju je hirurg odstranio u cijelosti', 'Микроскопски преглед поткожне творбе коју је хирург одстранио у цијелости', 'Микроскопическое исследование подкожного образования, удалённого хирургом целиком', 'Mikroskopische Untersuchung einer Geschwulst unter der Haut, die chirurgisch vollständig entfernt wurde', 'Cerrahın bütün olarak çıkardığı deri altı kitlenin mikroskopla incelenmesi', 'The removed nodule is measured and described, pieces are cut from it, embedded in paraffin, stained and examined under a microscope, with the removal margin assessed separately', 'Odstranjeni čvor se izmjeri i opiše, iz njega se isijecaju uzorci, ukalupljuju u parafin, boje i gledaju pod mikroskopom, a ivica odstranjenja se procjenjuje posebno', 'Одстрањени чвор се измјери и опише, из њега се исијецају узорци, укалупљују у парафин, боје и гледају под микроскопом, а ивица одстрањења се процјењује посебно', 'Удалённый узел измеряют и описывают, вырезают из него участки, заливают в парафин, окрашивают и смотрят под микроскопом, отдельно оценивая край удаления', 'Der entfernte Knoten wird vermessen und beschrieben, es werden Stücke herausgeschnitten, in Paraffin eingebettet, gefärbt und mikroskopisch beurteilt, der Resektionsrand gesondert', 'Çıkarılan kitle ölçülür ve tanımlanır, içinden örnekler alınıp parafine gömülür, boyanır ve mikroskopta incelenir; çıkarma sınırı ayrıca değerlendirilir', 'A lump or thickening under the skin after it has been removed, rapid growth of a lesion, change in its colour or shape, tenderness, recurrence at the same site', 'Čvor ili zadebljanje pod kožom poslije odstranjenja, brz rast tvorbe, promjena boje i oblika, bolna osjetljivost, ponovna pojava na istom mjestu', 'Чвор или задебљање под кожом послије одстрањења, брз раст творбе, промјена боје и облика, болна осјетљивост, поновна појава на истом мјесту', 'Узел или уплотнение под кожей после его удаления, быстрый рост образования, изменение цвета и формы, болезненность, повторное появление на прежнем месте', 'Knoten oder Verhärtung unter der Haut nach der Entfernung, rasches Wachstum, Veränderung von Farbe und Form, Druckschmerz, erneutes Auftreten an derselben Stelle', 'Çıkarıldıktan sonra deri altındaki kitle ya da sertlik, kitlenin hızlı büyümesi, renk ve şekil değişikliği, hassasiyet, aynı yerde yeniden ortaya çıkma', 'Nothing is required from the patient: the material is obtained during the operation that removes the lesion', 'Od pacijenta se ne traži ništa: materijal se dobija tokom zahvata odstranjenja tvorbe', 'Од пацијента се не тражи ништа: материјал се добија током захвата одстрањења творбе', 'От пациента ничего не требуется: материал получают во время вмешательства по удалению образования', 'Für die Patientin oder den Patienten ist nichts vorzubereiten: das Material fällt bei der Entfernung an', 'Hastadan bir şey istenmez: örnek kitlenin çıkarıldığı girişim sırasında alınır', 'The report states what tissue the lesion is made of, whether it was removed completely and whether there are findings that need further follow-up. Further steps are decided by the surgeon who performed the operation', 'Nalaz govori od kakvog je tkiva tvorba, da li je odstranjena u cijelosti i ima li nalaza koji traže dalje praćenje. Dalji postupak određuje hirurg koji je radio zahvat', 'Налаз говори од каквог је ткива творба, да ли је одстрањена у цијелости и има ли налаза који траже даље праћење. Даљи поступак одређује хирург који је радио захват', 'Заключение говорит, из какой ткани состоит образование, полностью ли оно удалено и есть ли находки, требующие дальнейшего наблюдения. Дальнейшую тактику определяет оперировавший хирург', 'Der Befund sagt, aus welchem Gewebe die Geschwulst besteht, ob sie vollständig entfernt wurde und ob Merkmale vorliegen, die eine Kontrolle erfordern. Das weitere Vorgehen legt die operierende Chirurgin oder der operierende Chirurg fest', 'Rapor kitlenin hangi dokudan oluştuğunu, bütünüyle çıkarılıp çıkarılmadığını ve izlem gerektiren bulgu olup olmadığını belirtir. Sonraki adımları ameliyatı yapan cerrah belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-surgical-breast-biopsy-without-ihc'), 'Microscopic examination of a piece of breast tissue excised by the surgeon, without additional receptor testing', 'Mikroskopski pregled isječka tkiva dojke koji je hirurg izrezao, bez dodatnog određivanja receptora', 'Микроскопски преглед исјечка ткива дојке који је хирург изрезао, без додатног одређивања рецептора', 'Микроскопическое исследование участка ткани молочной железы, иссечённого хирургом, без дополнительного определения рецепторов', 'Mikroskopische Untersuchung eines chirurgisch entnommenen Gewebestücks der Brust, ohne zusätzliche Rezeptorbestimmung', 'Cerrahın çıkardığı meme dokusu parçasının, ek reseptör incelemesi yapılmadan mikroskopla değerlendirilmesi', 'The excised fragment is marked, described, processed into sections and stained with routine stains; the tissue structure and the excision margins are assessed, immunohistochemical stains are not part of this scope', 'Izrezani komad se obilježi, opiše, pripreme se presjeci i oboje uobičajenim bojama; procjenjuju se građa tkiva i rubovi ekscizije, imunohistohemijska bojenja nisu dio ovog obima', 'Изрезани комад се обиљежи, опише, припреме се пресјеци и обоје уобичајеним бојама; процјењују се грађа ткива и рубови ексцизије, имунохистохемијска бојења нису дио овог обима', 'Иссечённый фрагмент маркируют, описывают, готовят срезы и окрашивают стандартными красителями; оценивают строение ткани и края иссечения, иммуногистохимические окраски в этот объём не входят', 'Das entnommene Stück wird markiert, beschrieben, geschnitten und mit Routinefärbungen gefärbt; beurteilt werden Gewebeaufbau und Schnittränder, immunhistochemische Färbungen gehören nicht zu diesem Umfang', 'Çıkarılan parça işaretlenir, tanımlanır, kesitleri hazırlanıp rutin boyalarla boyanır; doku yapısı ve çıkarma sınırları değerlendirilir, immünohistokimyasal boyamalar bu kapsamda değildir', 'A breast lump that a needle sample could not clarify, disagreement between examination, ultrasound and mammography, the need to remove a lesion whole, clarifying the nature of benign changes', 'Čvor u dojci koji se iglenim uzorkom nije mogao razjasniti, neslaganje nalaza pregleda, ultrazvuka i mamografije, potreba da se tvorba odstrani u cijelosti, razjašnjenje prirode dobroćudnih promjena', 'Чвор у дојци који се игленим узорком није могао разјаснити, неслагање налаза прегледа, ултразвука и мамографије, потреба да се творба одстрани у цијелости, разјашњење природе доброћудних промјена', 'Уплотнение в груди, которое не удалось уточнить иглой, несовпадение данных осмотра, УЗИ и маммографии, необходимость удалить образование целиком, уточнение природы доброкачественных изменений', 'Ein Knoten in der Brust, der sich durch eine Nadelprobe nicht klären ließ, widersprüchliche Befunde von Tastuntersuchung, Ultraschall und Mammografie, vollständige Entfernung einer Veränderung, Abklärung gutartiger Befunde', 'İğne örneğiyle netleşmeyen meme kitlesi, muayene, ultrason ve mamografi bulgularının uyuşmaması, kitlenin bütün olarak çıkarılması gereği, iyi huylu değişikliklerin niteliğinin araştırılması', 'Preparation concerns the operation itself and is discussed with the surgeon, the laboratory stage requires nothing', 'Priprema se odnosi na sam zahvat i dogovara se sa hirurgom, za laboratorijski dio nije potrebno ništa', 'Припрема се односи на сам захват и договара се са хирургом, за лабораторијски дио није потребно ништа', 'Подготовка относится к самой операции и обсуждается с хирургом, для лабораторного этапа ничего не нужно', 'Die Vorbereitung betrifft den Eingriff und wird mit der Chirurgin oder dem Chirurgen besprochen, für den Laborteil ist nichts nötig', 'Hazırlık ameliyatın kendisiyle ilgilidir ve cerrahla konuşulur, laboratuvar aşaması için bir şey gerekmez', 'The report describes the structure of the breast tissue and the margins of the excised piece. Whether further tests are needed, including receptor testing, is decided by the treating doctor', 'Nalaz opisuje građu tkiva dojke i rubove izrezanog dijela. Da li su potrebna dodatna ispitivanja, uključujući određivanje receptora, odlučuje ljekar koji vodi liječenje', 'Налаз описује грађу ткива дојке и рубове изрезаног дијела. Да ли су потребна додатна испитивања, укључујући одређивање рецептора, одлучује љекар који води лијечење', 'Заключение описывает строение ткани железы и границы иссечённого участка. Нужны ли дополнительные исследования, в том числе определение рецепторов, решает лечащий врач', 'Der Befund beschreibt den Aufbau des Brustgewebes und die Ränder des entnommenen Stücks. Ob weitere Untersuchungen einschließlich der Rezeptorbestimmung nötig sind, entscheidet die behandelnde Ärztin oder der behandelnde Arzt', 'Rapor meme dokusunun yapısını ve çıkarılan parçanın sınırlarını tanımlar. Reseptör incelemesi dahil ek tetkiklerin gerekip gerekmediğine tedaviyi yürüten hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-testis-biopsy'), 'Microscopic examination of a fragment of testicular tissue obtained by biopsy', 'Mikroskopski pregled isječka tkiva testisa dobijenog biopsijom', 'Микроскопски преглед исјечка ткива тестиса добијеног биопсијом', 'Микроскопическое исследование фрагмента ткани яичка, полученного при биопсии', 'Mikroskopische Untersuchung eines durch Biopsie gewonnenen Gewebestücks des Hodens', 'Biyopsiyle alınan testis dokusu parçasının mikroskopla incelenmesi', 'A small fragment taken by the urologist under anaesthesia is placed in a special fixative, cut into thin sections and assessed for the state of the seminiferous tubules and the stages of sperm maturation', 'Mali komadić koji urolog uzme uz anesteziju fiksira se posebnim rastvorom, reže na tanke presjeke i procjenjuje se stanje sjemenih kanalića i faze sazrijevanja spermatozoida', 'Мали комадић који уролог узме уз анестезију фиксира се посебним раствором, реже на танке пресјеке и процјењује се стање сјемених каналића и фазе сазријевања сперматозоида', 'Небольшой фрагмент, взятый урологом под обезболиванием, фиксируют специальным раствором, режут на тонкие срезы и оценивают состояние семенных канальцев и стадии созревания сперматозоидов', 'Das urologisch unter Betäubung entnommene kleine Stück wird in einer speziellen Lösung fixiert, in dünne Schnitte geschnitten und auf den Zustand der Samenkanälchen und die Reifungsstufen der Spermien beurteilt', 'Ürologun anestezi altında aldığı küçük parça özel bir solüsyonda tespit edilir, ince kesitler alınır ve seminifer tübüllerin durumu ile sperm olgunlaşma evreleri değerlendirilir', 'Absence of sperm in the ejaculate, work-up of male infertility, clarifying why sperm production is impaired, planning sperm retrieval for IVF, clarifying the nature of a lesion in the testicle', 'Odsustvo spermatozoida u ejakulatu, obrada muške neplodnosti, razjašnjenje uzroka poremećaja stvaranja spermatozoida, planiranje uzimanja spermatozoida za vantjelesnu oplodnju, razjašnjenje prirode tvorbe u testisu', 'Одсуство сперматозоида у ејакулату, обрада мушке неплодности, разјашњење узрока поремећаја стварања сперматозоида, планирање узимања сперматозоида за вантјелесну оплодњу, разјашњење природе творбе у тестису', 'Отсутствие сперматозоидов в эякуляте, обследование при мужском бесплодии, уточнение причины нарушения сперматогенеза, планирование забора сперматозоидов для ЭКО, уточнение природы образования в яичке', 'Fehlen von Spermien im Ejakulat, Abklärung männlicher Unfruchtbarkeit, Ursachensuche bei gestörter Spermienbildung, Planung einer Spermiengewinnung für die künstliche Befruchtung, Abklärung einer Veränderung im Hoden', 'Menide sperm bulunmaması, erkek kısırlığının araştırılması, sperm üretimindeki bozukluğun nedeninin belirlenmesi, tüp bebek için sperm elde edilmesinin planlanması, testisteki bir oluşumun niteliğinin araştırılması', 'The urologist explains how to prepare for the procedure, the laboratory part needs no separate preparation', 'Pripremu za zahvat objašnjava urolog, za laboratorijski dio posebne pripreme nema', 'Припрему за захват објашњава уролог, за лабораторијски дио посебне припреме нема', 'Подготовку к вмешательству объясняет уролог, к лабораторной части отдельной подготовки нет', 'Wie der Eingriff vorzubereiten ist, erklärt die Urologin oder der Urologe, für den Laborteil ist nichts vorzubereiten', 'İşleme nasıl hazırlanılacağını üroloji uzmanı anlatır, laboratuvar aşaması için ayrı bir hazırlık gerekmez', 'The report shows whether sperm maturation is preserved and whether there are tissue changes that need further assessment. The urologist or fertility specialist interprets it together with hormone and genetic tests', 'Nalaz pokazuje da li je sazrijevanje spermatozoida očuvano i ima li promjena tkiva koje traže dalju obradu. Rezultat tumači urolog ili specijalista za plodnost zajedno sa hormonskim i genetskim analizama', 'Налаз показује да ли је сазријевање сперматозоида очувано и има ли промјена ткива које траже даљу обраду. Резултат тумачи уролог или специјалиста за плодност заједно са хормонским и генетским анализама', 'Заключение показывает, сохранено ли созревание сперматозоидов и есть ли изменения ткани, требующие дальнейшего обследования. Результат трактует уролог или репродуктолог вместе с гормональными и генетическими анализами', 'Der Befund zeigt, ob die Spermienreifung erhalten ist und ob Gewebeveränderungen vorliegen, die weiter abgeklärt werden müssen. Gedeutet wird er von der Urologie oder der Kinderwunschmedizin zusammen mit Hormon- und genetischen Befunden', 'Rapor sperm olgunlaşmasının korunup korunmadığını ve ileri inceleme gerektiren doku değişikliği olup olmadığını gösterir. Sonucu hormon ve genetik tetkiklerle birlikte üroloji ya da üreme sağlığı uzmanı yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-thyroid-biopsy'), 'Microscopic examination of thyroid tissue obtained by biopsy or during surgery', 'Mikroskopski pregled tkiva štitne žlijezde dobijenog biopsijom ili tokom operacije', 'Микроскопски преглед ткива штитне жлијезде добијеног биопсијом или током операције', 'Микроскопическое исследование ткани щитовидной железы, полученной при биопсии или во время операции', 'Mikroskopische Untersuchung von Schilddrüsengewebe aus einer Biopsie oder einer Operation', 'Biyopsiyle ya da ameliyat sırasında alınan tiroid dokusunun mikroskopla incelenmesi', 'The material is fixed, embedded in paraffin, sectioned and stained; the pathologist assesses the architecture of the follicles, the capsule of the nodule and the surrounding tissue', 'Materijal se fiksira, ukalupljuje u parafin, reže na presjeke i boji; patolog procjenjuje građu folikula, čahuru čvora i okolno tkivo', 'Материјал се фиксира, укалупљује у парафин, реже на пресјеке и боји; патолог процјењује грађу фоликула, чахуру чвора и околно ткиво', 'Материал фиксируют, заливают в парафин, режут на срезы и окрашивают; патолог оценивает строение фолликулов, капсулу узла и окружающую ткань', 'Das Material wird fixiert, in Paraffin eingebettet, geschnitten und gefärbt; beurteilt werden der Aufbau der Follikel, die Kapsel des Knotens und das umgebende Gewebe', 'Örnek tespit edilir, parafine gömülür, kesitlenir ve boyanır; patoloji uzmanı foliküllerin yapısını, nodülün kapsülünü ve çevre dokuyu değerlendirir', 'A thyroid nodule followed on ultrasound, an inconclusive fine-needle aspiration result, an enlarged gland pressing on neighbouring structures, assessment of tissue after removal of a lobe or the whole gland', 'Čvor štitne žlijezde koji se prati ultrazvukom, nejasan nalaz punkcije tankom iglom, uvećana žlijezda koja pritiska okolne strukture, procjena tkiva poslije odstranjenja režnja ili cijele žlijezde', 'Чвор штитне жлијезде који се прати ултразвуком, нејасан налаз пункције танком иглом, увећана жлијезда која притиска околне структуре, процјена ткива послије одстрањења режња или цијеле жлијезде', 'Узел щитовидной железы, за которым наблюдают по УЗИ, неясный результат пункции тонкой иглой, увеличенная железа со сдавлением соседних структур, оценка ткани после удаления доли или всей железы', 'Ein im Ultraschall kontrollierter Schilddrüsenknoten, ein unklares Ergebnis der Feinnadelpunktion, eine vergrößerte Schilddrüse mit Druck auf Nachbarstrukturen, Beurteilung des Gewebes nach Entfernung eines Lappens oder der ganzen Drüse', 'Ultrasonla izlenen tiroid nodülü, ince iğne aspirasyonunun belirsiz sonucu, komşu yapılara baskı yapan büyümüş tiroid, lob ya da bezin tamamı çıkarıldıktan sonra dokunun değerlendirilmesi', 'Preparation concerns the puncture or the operation and is discussed with the doctor, examining the material itself needs none', 'Priprema se odnosi na punkciju ili operaciju i dogovara se sa ljekarom, za pregled materijala priprema nije potrebna', 'Припрема се односи на пункцију или операцију и договара се са љекаром, за преглед материјала припрема није потребна', 'Подготовка относится к пункции или операции и обсуждается с врачом, для исследования материала подготовка не нужна', 'Die Vorbereitung betrifft die Punktion oder die Operation und wird ärztlich besprochen, die Untersuchung des Materials selbst erfordert keine', 'Hazırlık iğne işlemi veya ameliyatla ilgilidir ve hekimle konuşulur, örneğin incelenmesi için hazırlık gerekmez', 'The report describes the type of nodule and the surrounding tissue, including findings that call for further follow-up. Treatment decisions are made by the endocrinologist together with the surgeon', 'Nalaz opisuje tip čvora i građu okolnog tkiva, uključujući nalaze koji traže dalje praćenje. Odluku o liječenju donosi endokrinolog zajedno sa hirurgom', 'Налаз описује тип чвора и грађу околног ткива, укључујући налазе који траже даље праћење. Одлуку о лијечењу доноси ендокринолог заједно са хирургом', 'Заключение описывает тип узла и строение окружающей ткани, включая находки, требующие дальнейшего наблюдения. Решение о лечении принимает эндокринолог вместе с хирургом', 'Der Befund beschreibt die Art des Knotens und das umliegende Gewebe einschließlich kontrollbedürftiger Merkmale. Über die Behandlung entscheidet die Endokrinologie gemeinsam mit der Chirurgie', 'Rapor nodülün tipini ve çevre dokunun yapısını, izlem gerektiren bulgular dahil tanımlar. Tedavi kararını endokrinoloji uzmanı cerrahla birlikte verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-trus-prostate'), 'Microscopic examination of prostate tissue cores taken under transrectal ultrasound guidance', 'Mikroskopski pregled valjaka tkiva prostate uzetih pod kontrolom transrektalnog ultrazvuka', 'Микроскопски преглед ваљака ткива простате узетих под контролом трансректалног ултразвука', 'Микроскопическое исследование столбиков ткани простаты, взятых под контролем трансректального УЗИ', 'Mikroskopische Untersuchung von Gewebezylindern der Prostata, die unter transrektaler Ultraschallkontrolle entnommen wurden', 'Transrektal ultrason eşliğinde alınan prostat doku silindirlerinin mikroskopla incelenmesi', 'Several thin cores from different parts of the gland are labelled by the site they came from and processed and read separately, so it is clear which zones are affected', 'Više tankih valjaka tkiva iz različitih dijelova žlijezde obilježava se prema mjestu uzimanja, a zatim se obrađuje i čita odvojeno, da bi se vidjelo koje su zone izmijenjene', 'Више танких ваљака ткива из различитих дијелова жлијезде обиљежава се према мјесту узимања, а затим се обрађује и чита одвојено, да би се видјело које су зоне измијењене', 'Несколько тонких столбиков ткани из разных участков железы маркируют по месту забора, обрабатывают и читают раздельно, чтобы было видно, какие зоны изменены', 'Mehrere dünne Zylinder aus verschiedenen Abschnitten der Drüse werden nach Entnahmeort beschriftet und getrennt aufgearbeitet und beurteilt, sodass erkennbar ist, welche Zonen verändert sind', 'Bezin farklı bölgelerinden alınan birkaç ince silindir alındığı yere göre işaretlenir, ayrı ayrı işlenir ve okunur, böylece hangi bölgelerin değiştiği görülür', 'A raised or rising PSA, findings on digital rectal examination, suspicious areas on prostate ultrasound or MRI, follow-up of changes found earlier', 'Povišen ili rastući PSA, nalaz digitorektalnog pregleda, sumnjive zone na ultrazvuku ili magnetnoj rezonanci prostate, praćenje ranije uočenih promjena', 'Повишен или растући PSA, налаз дигиторекталног прегледа, сумњиве зоне на ултразвуку или магнетној резонанци простате, праћење раније уочених промјена', 'Повышенный или растущий PSA, находки при пальцевом ректальном исследовании, подозрительные зоны на УЗИ или МРТ простаты, наблюдение за ранее выявленными изменениями', 'Erhöhter oder steigender PSA-Wert, auffällige Tastuntersuchung, verdächtige Areale im Ultraschall oder MRT der Prostata, Kontrolle bereits bekannter Veränderungen', 'Yüksek ya da yükselen PSA, parmakla rektal muayene bulgusu, prostat ultrasonunda veya manyetik rezonansta şüpheli alanlar, daha önce saptanmış değişikliklerin izlemi', 'Preparation concerns the biopsy itself: the urologist sets it out, including bowel preparation and the decision about medicines that affect blood clotting', 'Priprema se odnosi na samu biopsiju: određuje je urolog, uključujući pripremu crijeva i odluku o lijekovima koji utiču na zgrušavanje krvi', 'Припрема се односи на саму биопсију: одређује је уролог, укључујући припрему цријева и одлуку о лијековима који утичу на згрушавање крви', 'Подготовка относится к самой биопсии: её назначает уролог, включая подготовку кишечника и решение по препаратам, влияющим на свёртывание крови', 'Die Vorbereitung betrifft die Biopsie: sie wird urologisch festgelegt, einschließlich Darmvorbereitung und Umgang mit Medikamenten, die die Blutgerinnung beeinflussen', 'Hazırlık biyopsiyle ilgilidir: bağırsak hazırlığı ve kan pıhtılaşmasını etkileyen ilaçlarla ilgili karar dahil olmak üzere üroloji uzmanı tarafından belirlenir', 'The report describes the tissue in each core and how far the cells differ from usual ones. What this means and whether further assessment or treatment is needed is decided by the urologist', 'Nalaz opisuje građu tkiva u svakom valjku i koliko se ćelije razlikuju od uobičajenih. Šta to znači i da li su potrebni dalja obrada ili liječenje, odlučuje urolog', 'Налаз описује грађу ткива у сваком ваљку и колико се ћелије разликују од уобичајених. Шта то значи и да ли су потребни даља обрада или лијечење, одлучује уролог', 'Заключение описывает строение ткани в каждом столбике и то, насколько клетки отличаются от обычных. Что это означает и нужны ли дальнейшее обследование или лечение, определяет уролог', 'Der Befund beschreibt das Gewebe in jedem Zylinder und wie stark die Zellen vom Gewohnten abweichen. Was daraus folgt und ob weitere Abklärung oder Behandlung nötig ist, entscheidet die Urologin oder der Urologe', 'Rapor her silindirdeki dokuyu ve hücrelerin alışılmıştan ne kadar farklı olduğunu tanımlar. Bunun anlamına ve ileri inceleme ya da tedavi gerekip gerekmediğine üroloji uzmanı karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-tur-bladder'), 'Microscopic examination of bladder tissue removed during transurethral resection', 'Mikroskopski pregled tkiva mokraćne bešike odstranjenog transuretralnom resekcijom', 'Микроскопски преглед ткива мокраћне бешике одстрањеног трансуретралном ресекцијом', 'Микроскопическое исследование ткани мочевого пузыря, удалённой при трансуретральной резекции', 'Mikroskopische Untersuchung von Blasengewebe, das bei einer transurethralen Resektion entfernt wurde', 'Transüretral rezeksiyonla çıkarılan mesane dokusunun mikroskopla incelenmesi', 'The fragments resected through the urethra are collected, processed and read layer by layer, noting separately whether the muscle layer of the wall is involved', 'Isječci dobijeni resekcijom kroz uretru sakupljaju se, obrađuju i čitaju po slojevima, uz posebnu napomenu da li je zahvaćen mišićni sloj zida', 'Исјечци добијени ресекцијом кроз уретру сакупљају се, обрађују и читају по слојевима, уз посебну напомену да ли је захваћен мишићни слој зида', 'Полученные при резекции через уретру фрагменты собирают, обрабатывают и читают послойно, отдельно отмечая, затронут ли мышечный слой стенки', 'Die durch die Harnröhre abgetragenen Anteile werden gesammelt, aufgearbeitet und schichtweise beurteilt, mit gesondertem Vermerk, ob die Muskelschicht der Wand betroffen ist', 'Üretra yoluyla alınan parçalar toplanır, işlenir ve katman katman okunur, duvarın kas tabakasının tutulup tutulmadığı ayrıca belirtilir', 'A lesion of the bladder wall found at cystoscopy or ultrasound, blood in the urine without a clear cause, repeat resections during follow-up after an earlier procedure', 'Tvorba na zidu mokraćne bešike viđena na cistoskopiji ili ultrazvuku, krv u mokraći bez jasnog uzroka, kontrolne resekcije tokom praćenja poslije ranijeg zahvata', 'Творба на зиду мокраћне бешике виђена на цистоскопији или ултразвуку, крв у мокраћи без јасног узрока, контролне ресекције током праћења послије ранијег захвата', 'Образование стенки мочевого пузыря, найденное при цистоскопии или УЗИ, кровь в моче без ясной причины, контрольные резекции при наблюдении после ранее проведённого вмешательства', 'Eine bei Blasenspiegelung oder Ultraschall gefundene Veränderung der Blasenwand, Blut im Urin ohne klare Ursache, Kontrollresektionen im Verlauf nach einem früheren Eingriff', 'Sistoskopi veya ultrasonda görülen mesane duvarı oluşumu, nedeni belirsiz idrarda kan, önceki girişim sonrası izlemde yapılan kontrol rezeksiyonları', 'The examination itself needs no preparation: the material is obtained during the operation, for which the urologist explains the preparation', 'Za sam pregled nema pripreme: materijal se dobija tokom operacije, a pripremu za nju objašnjava urolog', 'За сам преглед нема припреме: материјал се добија током операције, а припрему за њу објашњава уролог', 'Для самого исследования подготовки нет: материал получают во время операции, подготовку к которой объясняет уролог', 'Für die Untersuchung selbst ist nichts vorzubereiten: das Material fällt bei der Operation an, deren Vorbereitung urologisch erklärt wird', 'İncelemenin kendisi için hazırlık yoktur: örnek ameliyat sırasında alınır, ameliyat hazırlığını üroloji uzmanı anlatır', 'The report describes the type of tissue, how deep the changes reach into the wall and how far the cells differ from usual ones. Further follow-up and treatment are planned by the urologist', 'Nalaz opisuje vrstu tkiva, dubinu promjena u zidu i koliko se ćelije razlikuju od uobičajenih. Dalje praćenje i liječenje planira urolog', 'Налаз описује врсту ткива, дубину промјена у зиду и колико се ћелије разликују од уобичајених. Даље праћење и лијечење планира уролог', 'Заключение описывает вид ткани, глубину изменений в стенке и то, насколько клетки отличаются от обычных. Дальнейшее наблюдение и лечение планирует уролог', 'Der Befund beschreibt die Gewebeart, wie tief die Veränderungen in die Wand reichen und wie stark die Zellen vom Normalen abweichen. Kontrolle und Behandlung plant die Urologin oder der Urologe', 'Rapor dokunun tipini, değişikliklerin duvarda ne kadar derine indiğini ve hücrelerin alışılmıştan ne kadar ayrıldığını tanımlar. İzlem ve tedaviyi üroloji uzmanı planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'histopathology-uterus-examination'), 'Microscopic examination of a uterus removed at surgery', 'Mikroskopski pregled materice odstranjene operacijom', 'Микроскопски преглед материце одстрањене операцијом', 'Микроскопическое исследование матки, удалённой при операции', 'Mikroskopische Untersuchung einer operativ entfernten Gebärmutter', 'Ameliyatla çıkarılan rahmin mikroskopla incelenmesi', 'The organ is described and measured as a whole, samples are cut from the endometrium, the muscle layer, the cervix and the adnexa if they were removed, and the sections are read under a microscope', 'Organ se opiše i izmjeri u cjelini, uzorci se isijecaju iz endometrijuma, mišićnog sloja, grlića i adneksa ako su odstranjeni, a presjeci se čitaju pod mikroskopom', 'Орган се опише и измјери у цјелини, узорци се исијецају из ендометријума, мишићног слоја, грлића и аднекса ако су одстрањени, а пресјеци се читају под микроскопом', 'Орган описывают и измеряют целиком, вырезают участки из эндометрия, мышечного слоя, шейки и придатков, если они удалены, и читают срезы под микроскопом', 'Das Organ wird als Ganzes beschrieben und vermessen, Proben werden aus Gebärmutterschleimhaut, Muskelschicht, Gebärmutterhals und, falls mitentfernt, den Anhangsgebilden entnommen und die Schnitte mikroskopisch beurteilt', 'Organ bütün olarak tanımlanır ve ölçülür, rahim iç zarından, kas tabakasından, rahim ağzından ve birlikte alındıysa eklerden örnekler alınır, kesitler mikroskopta okunur', 'Routine examination after removal of the uterus, fibroids, prolonged bleeding, thickened endometrium, endometriosis, changes detected before the operation', 'Redovan pregled poslije odstranjenja materice, miomi, dugotrajna krvarenja, zadebljanje endometrijuma, endometrioza, promjene uočene prije operacije', 'Редован преглед послије одстрањења материце, миоми, дуготрајна крварења, задебљање ендометријума, ендометриоза, промјене уочене прије операције', 'Плановое исследование после удаления матки, миомы, длительные кровотечения, утолщение эндометрия, эндометриоз, изменения, выявленные до операции', 'Routineuntersuchung nach Entfernung der Gebärmutter, Myome, anhaltende Blutungen, verdickte Gebärmutterschleimhaut, Endometriose, vor der Operation festgestellte Veränderungen', 'Rahim alındıktan sonra rutin inceleme, miyomlar, uzun süren kanamalar, rahim iç zarının kalınlaşması, endometriozis, ameliyat öncesi saptanan değişiklikler', 'Preparation relates to the operation and is discussed with the operating gynaecologist, the examination itself adds no requirements', 'Priprema se odnosi na operaciju i dogovara se sa ginekologom koji operiše, sam pregled ne traži ništa dodatno', 'Припрема се односи на операцију и договара се са гинекологом који оперише, сам преглед не тражи ништа додатно', 'Подготовка касается операции и обсуждается с оперирующим гинекологом, само исследование дополнительных требований не добавляет', 'Die Vorbereitung betrifft die Operation und wird mit der operierenden Gynäkologie besprochen, für die Untersuchung selbst kommt nichts hinzu', 'Hazırlık ameliyatla ilgilidir ve ameliyatı yapan kadın doğum hekimiyle konuşulur, incelemenin kendisi ek bir şey istemez', 'The report describes the endometrium and the muscle layer, the nature of any nodules and the state of the cervix. The final interpretation and further management are handled by the treating gynaecologist', 'Nalaz opisuje endometrijum i mišićni sloj, prirodu čvorova i stanje grlića. Konačno tumačenje i dalji postupak vodi ginekolog koji prati liječenje', 'Налаз описује ендометријум и мишићни слој, природу чворова и стање грлића. Коначно тумачење и даљи поступак води гинеколог који прати лијечење', 'Заключение описывает эндометрий и мышечный слой, характер узлов и состояние шейки. Итоговый разбор и дальнейшую тактику ведёт лечащий гинеколог', 'Der Befund beschreibt Schleimhaut und Muskelschicht, die Art der Knoten und den Zustand des Gebärmutterhalses. Die abschließende Einordnung und das weitere Vorgehen übernimmt die behandelnde Gynäkologie', 'Rapor rahim iç zarını ve kas tabakasını, varsa düğümlerin niteliğini ve rahim ağzının durumunu tanımlar. Sonucun bütünsel değerlendirmesini ve sonraki adımları takip eden kadın doğum hekimi yürütür')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'immunohistochemistry-5-to-10-antibodies'), 'Additional staining of prepared tissue sections with a panel of five to ten antibodies', 'Dodatno bojenje pripremljenih presjeka tkiva panelom od pet do deset antitijela', 'Додатно бојење припремљених пресјека ткива панелом од пет до десет антитијела', 'Дополнительное окрашивание готовых срезов ткани панелью из пяти-десяти антител', 'Zusätzliche Färbung fertiger Gewebeschnitte mit einem Panel aus fünf bis zehn Antikörpern', 'Hazırlanmış doku kesitlerinin beş ila on antikordan oluşan bir panelle ek olarak boyanması', 'A set of antibodies against particular cell proteins is applied to the sections, the binding is developed with a dye and read under the microscope; the work is done on the paraffin block that already exists', 'Na presjeke se nanosi niz antitijela na određene bjelančevine ćelija, vezivanje se razvija bojom i očitava pod mikroskopom; radi se na već pripremljenom parafinskom bloku', 'На пресјеке се наноси низ антитијела на одређене бјеланчевине ћелија, везивање се развија бојом и очитава под микроскопом; ради се на већ припремљеном парафинском блоку', 'На срезы наносят набор антител к определённым белкам клеток, связывание проявляют красителем и читают под микроскопом; работа идёт на уже готовом парафиновом блоке', 'Auf die Schnitte wird eine Reihe von Antikörpern gegen bestimmte Zelleiweiße aufgebracht, die Bindung mit einem Farbstoff sichtbar gemacht und mikroskopisch beurteilt; gearbeitet wird am bereits vorhandenen Paraffinblock', 'Kesitlere belirli hücre proteinlerine karşı bir dizi antikor uygulanır, bağlanma boyayla görünür kılınır ve mikroskopta okunur; işlem hazır parafin blok üzerinde yapılır', 'Clarifying the type of tissue and the origin of the cells when routine staining is not enough, telling apart lesions that look similar, typing lymphoid tissue, describing the properties of tumour cells before treatment is planned', 'Razjašnjenje vrste tkiva i porijekla ćelija kada uobičajeno bojenje nije dovoljno, razlikovanje tvorbi sličnog izgleda, tipizacija limfnog tkiva, opis osobina tumorskih ćelija prije planiranja liječenja', 'Разјашњење врсте ткива и поријекла ћелија када уобичајено бојење није довољно, разликовање творби сличног изгледа, типизација лимфног ткива, опис особина туморских ћелија прије планирања лијечења', 'Уточнение типа ткани и происхождения клеток, когда обычного окрашивания не хватает, разграничение похожих по виду образований, типирование лимфоидной ткани, описание свойств опухолевых клеток перед планированием лечения', 'Klärung von Gewebeart und Zellherkunft, wenn die Routinefärbung nicht ausreicht, Abgrenzung ähnlich aussehender Veränderungen, Typisierung lymphatischen Gewebes, Beschreibung der Eigenschaften von Tumorzellen vor der Therapieplanung', 'Rutin boyamanın yetmediği durumlarda doku tipinin ve hücre kökeninin belirlenmesi, benzer görünen oluşumların ayrımı, lenf dokusunun tiplendirilmesi, tedavi planlanmadan önce tümör hücrelerinin özelliklerinin tanımlanması', 'No preparation is needed: the test is done on material collected earlier, a further visit to the laboratory is not required', 'Priprema nije potrebna: radi se na ranije uzetom materijalu, ponovni dolazak u laboratoriju nije potreban', 'Припрема није потребна: ради се на раније узетом материјалу, поновни долазак у лабораторију није потребан', 'Подготовка не нужна: исследование идёт на ранее взятом материале, повторно приходить в лабораторию не требуется', 'Keine Vorbereitung nötig: die Untersuchung läuft am bereits entnommenen Material, ein erneuter Termin im Labor entfällt', 'Hazırlık gerekmez: inceleme daha önce alınmış örnek üzerinde yapılır, laboratuvara yeniden gelmek gerekmez', 'The set of stains shows which proteins the cells carry and helps the pathologist refine the report. It is read together with the routine histological description, and treatment is decided by the treating doctor', 'Niz bojenja pokazuje koje bjelančevine nose ćelije i pomaže patologu da precizira nalaz. Čita se zajedno sa uobičajenim histološkim opisom, a liječenje određuje ljekar koji vodi pacijenta', 'Низ бојења показује које бјеланчевине носе ћелије и помаже патологу да прецизира налаз. Чита се заједно са уобичајеним хистолошким описом, а лијечење одређује љекар који води пацијента', 'Набор окрашиваний показывает, какие белки несут клетки, и помогает патологу уточнить заключение. Его читают вместе с обычным гистологическим описанием, а лечение определяет лечащий врач', 'Die Färbereihe zeigt, welche Eiweiße die Zellen tragen, und hilft der Pathologie, den Befund zu präzisieren. Gelesen wird sie zusammen mit der histologischen Beschreibung, über die Behandlung entscheidet die behandelnde Ärztin oder der behandelnde Arzt', 'Boyama dizisi hücrelerin hangi proteinleri taşıdığını gösterir ve patoloji uzmanının raporu netleştirmesine yardımcı olur. Rutin histolojik tanımla birlikte okunur, tedaviye ise tedaviyi yürüten hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'immunohistochemistry-more-than-10-antibodies'), 'An extended immunohistochemical panel of more than ten antibodies on one sample', 'Proširen panel imunohistohemijskih bojenja, više od deset antitijela na istom materijalu', 'Проширен панел имунохистохемијских бојења, више од десет антитијела на истом материјалу', 'Расширенная панель иммуногистохимических окрашиваний, более десяти антител на одном материале', 'Erweitertes immunhistochemisches Panel mit mehr als zehn Antikörpern an einer Probe', 'Aynı örnek üzerinde ondan fazla antikorla yapılan geniş immünohistokimya paneli', 'Each antibody is applied to a separate section from the same block and the reactions are developed and read one by one, so the work takes longer than a short panel', 'Svako antitijelo se nanosi na poseban presjek iz istog bloka, a reakcije se razvijaju i očitavaju jedna po jedna, pa pregled traje duže nego kratak panel', 'Свако антитијело се наноси на посебан пресјек из истог блока, а реакције се развијају и очитавају једна по једна, па преглед траје дуже него кратак панел', 'Каждое антитело наносят на отдельный срез из того же блока, реакции проявляют и читают по очереди, поэтому работа занимает больше времени, чем короткая панель', 'Jeder Antikörper wird auf einen eigenen Schnitt desselben Blocks aufgebracht, die Reaktionen werden nacheinander entwickelt und beurteilt, daher dauert es länger als ein kurzes Panel', 'Her antikor aynı bloktan alınan ayrı bir kesite uygulanır, reaksiyonlar tek tek geliştirilip okunur, bu nedenle kısa panelden daha uzun sürer', 'Complex cases in which a short panel was not enough, searching for the source of a lesion of unclear origin, detailed typing of lymphoid tissue, clarifying rare tissue patterns', 'Složeni slučajevi u kojima kratak panel nije bio dovoljan, traženje izvora tvorbe nejasnog porijekla, detaljna tipizacija limfnog tkiva, razjašnjenje rijetkih oblika građe tkiva', 'Сложени случајеви у којима кратак панел није био довољан, тражење извора творбе нејасног поријекла, детаљна типизација лимфног ткива, разјашњење ријетких облика грађе ткива', 'Сложные случаи, когда короткой панели не хватило, поиск источника образования с неясным происхождением, детальное типирование лимфоидной ткани, уточнение редких вариантов строения ткани', 'Schwierige Fälle, in denen ein kurzes Panel nicht ausgereicht hat, Suche nach dem Ursprung einer Veränderung mit unklarer Herkunft, ausführliche Typisierung lymphatischen Gewebes, Abklärung seltener Gewebemuster', 'Kısa panelin yetmediği karmaşık durumlar, kökeni belirsiz bir oluşumun kaynağının aranması, lenf dokusunun ayrıntılı tiplendirilmesi, seyrek görülen doku yapılarının aydınlatılması', 'Nothing to prepare: the existing paraffin block is used and new sampling is usually not required', 'Nema pripreme: koristi se već postojeći parafinski blok, novo uzimanje materijala obično nije potrebno', 'Нема припреме: користи се већ постојећи парафински блок, ново узимање материјала обично није потребно', 'Подготовки нет: используют уже имеющийся парафиновый блок, новый забор материала обычно не требуется', 'Nichts vorzubereiten: verwendet wird der vorhandene Paraffinblock, eine erneute Probenentnahme ist meist nicht nötig', 'Hazırlık yoktur: mevcut parafin blok kullanılır, genellikle yeniden örnek alınması gerekmez', 'The wider the panel, the more precisely the pathologist can describe the properties of the cells, yet the report is still put together with the clinical picture and the rest of the work-up. The decision on treatment rests with the treating doctor', 'Što je panel širi, to patolog preciznije opisuje osobine ćelija, ali se nalaz i dalje sklapa uz kliničku sliku i ostale pretrage. Odluku o liječenju donosi ljekar koji vodi pacijenta', 'Што је панел шири, то патолог прецизније описује особине ћелија, али се налаз и даље склапа уз клиничку слику и остале претраге. Одлуку о лијечењу доноси љекар који води пацијента', 'Чем шире панель, тем точнее патолог описывает свойства клеток, но заключение всё равно складывается вместе с клинической картиной и остальным обследованием. Решение о лечении принимает лечащий врач', 'Je breiter das Panel, desto genauer lassen sich die Eigenschaften der Zellen beschreiben, der Befund entsteht aber weiterhin im Zusammenspiel mit dem klinischen Bild und den übrigen Untersuchungen. Über die Behandlung entscheidet die behandelnde Ärztin oder der behandelnde Arzt', 'Panel genişledikçe hücre özellikleri daha ayrıntılı tanımlanır, ancak rapor yine klinik tablo ve diğer tetkiklerle birlikte oluşturulur. Tedavi kararını tedaviyi yürüten hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'immunohistochemistry-per-antibody'), 'Staining of a tissue section with one selected antibody', 'Bojenje presjeka tkiva jednim izabranim antitijelom', 'Бојење пресјека ткива једним изабраним антитијелом', 'Окрашивание среза ткани реакцией с одним выбранным антителом', 'Färbung eines Gewebeschnitts mit einem einzelnen ausgewählten Antikörper', 'Doku kesitinin seçilmiş tek bir antikorla boyanması', 'The antibody against the protein of interest is applied to the section, the reaction is developed with a dye and it is read in which cells and how strongly it appears', 'Na presjek se nanosi antitijelo na traženu bjelančevinu, reakcija se razvija bojom i gleda se u kojim ćelijama i koliko je izražena', 'На пресјек се наноси антитијело на тражену бјеланчевину, реакција се развија бојом и гледа се у којим ћелијама и колико је изражена', 'На срез наносят антитело к нужному белку, реакцию проявляют красителем и смотрят, в каких клетках и насколько она выражена', 'Der Antikörper gegen das gesuchte Eiweiß wird auf den Schnitt aufgebracht, die Reaktion mit einem Farbstoff entwickelt und abgelesen, in welchen Zellen und wie stark sie ausfällt', 'Kesite aranan proteine karşı antikor uygulanır, reaksiyon boyayla geliştirilir ve hangi hücrelerde ne kadar belirgin olduğu okunur', 'When a single specific marker is enough to refine the report, as an add-on to an examination already done, checking one indicator at the request of the treating doctor', 'Kada je za preciziranje nalaza dovoljan jedan konkretan marker, dopuna već urađenom pregledu, provjera pojedinačnog pokazatelja na traženje ljekara', 'Када је за прецизирање налаза довољан један конкретан маркер, допуна већ урађеном прегледу, провјера појединачног показатеља на тражење љекара', 'Когда для уточнения заключения достаточно одного конкретного маркера, дополнение к уже выполненному исследованию, проверка отдельного показателя по запросу лечащего врача', 'Wenn zur Präzisierung des Befundes ein einzelner Marker genügt, als Ergänzung zu einer bereits erfolgten Untersuchung, Prüfung eines einzelnen Merkmals auf ärztliche Anforderung', 'Raporu netleştirmek için tek bir belirtecin yettiği durumlar, daha önce yapılmış incelemenin tamamlanması, hekimin istediği tek bir göstergenin kontrolü', 'No preparation is required: the staining is done on material taken earlier', 'Priprema nije potrebna: bojenje se radi na ranije uzetom materijalu', 'Припрема није потребна: бојење се ради на раније узетом материјалу', 'Подготовка не требуется: окрашивание делают на материале, взятом ранее', 'Keine Vorbereitung erforderlich: gefärbt wird bereits entnommenes Material', 'Hazırlık gerekmez: boyama daha önce alınmış örnek üzerinde yapılır', 'A single marker is not a diagnosis in itself, it only refines the properties of cells in tissue that has already been described. The overall conclusion is drawn by the pathologist and treatment is prescribed by the treating doctor', 'Pojedinačni marker sam po sebi nije dijagnoza, on samo precizira osobine ćelija u već opisanom tkivu. Zaključak sastavlja patolog, a liječenje propisuje ljekar koji vodi pacijenta', 'Појединачни маркер сам по себи није дијагноза, он само прецизира особине ћелија у већ описаном ткиву. Закључак саставља патолог, а лијечење прописује љекар који води пацијента', 'Отдельный маркер сам по себе не является диагнозом, он лишь уточняет свойства клеток в уже описанной ткани. Общий вывод формулирует патолог, а лечение назначает лечащий врач', 'Ein einzelner Marker ist für sich keine Diagnose, er präzisiert nur die Eigenschaften der Zellen im bereits beschriebenen Gewebe. Die Gesamtaussage trifft die Pathologie, die Behandlung verordnet die behandelnde Ärztin oder der behandelnde Arzt', 'Tek bir belirteç başlı başına tanı değildir, yalnızca tanımlanmış dokudaki hücrelerin özelliklerini netleştirir. Genel sonucu patoloji uzmanı yazar, tedaviyi ise tedaviyi yürüten hekim düzenler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'leep-cervical-conization'), 'Microscopic examination of a cone of cervical tissue removed by loop electrosurgical excision (LEEP)', 'Mikroskopski pregled konusa tkiva grlića materice odstranjenog petljastom elektroekscizijom (LEEP)', 'Микроскопски преглед конуса ткива грлића материце одстрањеног петљастом електроексцизијом (LEEP)', 'Микроскопическое исследование конуса ткани шейки матки, удалённого петлевой электроэксцизией (LEEP)', 'Mikroskopische Untersuchung eines mit der elektrischen Schlinge (LEEP) entfernten Gewebekegels des Gebärmutterhalses', 'Halka elektrocerrahi eksizyonla (LEEP) çıkarılan rahim ağzı doku konisinin mikroskopla incelenmesi', 'The gynaecologist removes a cone-shaped piece of the cervix with a thin electric loop; the cone is marked at its edges, cut into consecutive sections and the whole area of change is examined together with the excision margins', 'Ginekolog tankom električnom petljom odstrani konusni dio grlića; konizat se obilježi po rubovima, reže na uzastopne presjeke i pregleda se cijela zona promjena zajedno sa rubovima ekscizije', 'Гинеколог танком електричном петљом одстрани конусни дио грлића; конизат се обиљежи по рубовима, реже на узастопне пресјеке и прегледа се цијела зона промјена заједно са рубовима ексцизије', 'Гинеколог тонкой электропетлёй удаляет конусовидный участок шейки; конизат маркируют по краям, режут на последовательные срезы и изучают всю зону изменений вместе с краями иссечения', 'Die Frauenärztin oder der Frauenarzt trägt mit einer dünnen Schlinge einen kegelförmigen Anteil des Muttermundes ab; der Konus wird an den Rändern markiert, in fortlaufende Schnitte zerlegt und der gesamte veränderte Bereich samt Rändern beurteilt', 'Kadın doğum hekimi ince bir elektrikli halkayla rahim ağzından koni biçiminde bir parça çıkarır; koni kenarlarından işaretlenir, ardışık kesitlere ayrılır ve değişikliğin tamamı cerrahi sınırlarla birlikte incelenir', 'Epithelial changes of the cervix confirmed by biopsy, disagreement between cytology and colposcopy, persistent high-risk HPV together with changes, follow-up after earlier treatment of the cervix', 'Biopsijom potvrđene promjene epitela grlića materice, neslaganje citološkog i kolposkopskog nalaza, uporno prisustvo HPV visokog rizika uz promjene, kontrola poslije ranijeg liječenja grlića', 'Биопсијом потврђене промјене епитела грлића материце, неслагање цитолошког и колпоскопског налаза, упорно присуство HPV високог ризика уз промјене, контрола послије ранијег лијечења грлића', 'Подтверждённые биопсией изменения эпителия шейки матки, расхождение результатов цитологии и кольпоскопии, стойкое выявление ВПЧ высокого риска вместе с изменениями, контроль после ранее проведённого лечения шейки', 'Bioptisch gesicherte Veränderungen des Gebärmutterhalsepithels, widersprüchliche Ergebnisse von Zytologie und Kolposkopie, anhaltender Hochrisiko-HPV-Nachweis mit Veränderungen, Kontrolle nach früherer Behandlung am Gebärmutterhals', 'Biyopsiyle doğrulanmış rahim ağzı epitel değişiklikleri, sitoloji ile kolposkopi bulgularının uyuşmaması, değişikliklerle birlikte süregelen yüksek riskli HPV, rahim ağzına yönelik önceki tedavi sonrası kontrol', 'Preparation concerns the procedure itself: it is scheduled for a particular day of the cycle and discussed with the gynaecologist, the laboratory part needs none', 'Priprema se odnosi na sam zahvat: planira se za određeni dan ciklusa i dogovara sa ginekologom, za laboratorijski dio pripreme nema', 'Припрема се односи на сам захват: планира се за одређени дан циклуса и договара са гинекологом, за лабораторијски дио припреме нема', 'Подготовка относится к самому вмешательству: его планируют на определённый день цикла и обсуждают с гинекологом, для лабораторной части подготовки нет', 'Die Vorbereitung betrifft den Eingriff: er wird auf einen bestimmten Zyklustag gelegt und frauenärztlich besprochen, für den Laborteil ist nichts nötig', 'Hazırlık işlemin kendisiyle ilgilidir: adet döngüsünün belirli bir gününe planlanır ve kadın doğum hekimiyle konuşulur, laboratuvar aşaması için hazırlık yoktur', 'The report describes the degree of the epithelial changes and whether they reach the margin of the removed cone. Whether follow-up or a repeat procedure is needed is decided by the gynaecologist', 'Nalaz opisuje stepen promjena epitela i da li one dopiru do ruba odstranjenog konusa. Da li su potrebni dalje praćenje ili ponovni zahvat, odlučuje ginekolog', 'Налаз описује степен промјена епитела и да ли оне допиру до руба одстрањеног конуса. Да ли су потребни даље праћење или поновни захват, одлучује гинеколог', 'Заключение описывает степень изменений эпителия и то, доходят ли они до края удалённого конуса. Нужны ли дальнейшее наблюдение или повторное вмешательство, решает гинеколог', 'Der Befund beschreibt das Ausmaß der Epithelveränderungen und ob sie den Rand des entfernten Kegels erreichen. Ob Kontrolle oder ein erneuter Eingriff nötig ist, entscheidet die Frauenärztin oder der Frauenarzt', 'Rapor epitel değişikliklerinin derecesini ve çıkarılan koninin sınırına ulaşıp ulaşmadığını tanımlar. İzlem mi yoksa yeni bir işlem mi gerektiğine kadın doğum hekimi karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'needle-breast-biopsy-with-her2-and-ki67-receptors'), 'Examination of a core of breast tissue taken with a wide needle, with testing for Her2 and Ki67', 'Pregled valjka tkiva dojke uzetog debljom iglom, uz određivanje Her2 i Ki67', 'Преглед ваљка ткива дојке узетог дебљом иглом, уз одређивање Her2 и Ki67', 'Исследование столбика ткани молочной железы, взятого толстой иглой, с определением Her2 и Ki67', 'Untersuchung eines mit einer dickeren Nadel gewonnenen Gewebezylinders der Brust, einschließlich Bestimmung von Her2 und Ki67', 'Kalın iğneyle alınan meme dokusu silindirinin, Her2 ve Ki67 belirlenerek incelenmesi', 'The core obtained with the needle under ultrasound guidance is processed as ordinary histological material, then immunohistochemical reactions for hormone receptors, Her2 and Ki67 are performed on the sections', 'Valjak dobijen iglom pod kontrolom ultrazvuka obrađuje se kao uobičajen histološki materijal, a zatim se na presjecima rade imunohistohemijske reakcije na hormonske receptore, Her2 i Ki67', 'Ваљак добијен иглом под контролом ултразвука обрађује се као уобичајен хистолошки материјал, а затим се на пресјецима раде имунохистохемијске реакције на хормонске рецепторе, Her2 и Ki67', 'Столбик, полученный иглой под контролем УЗИ, обрабатывают как обычный гистологический материал, затем на срезах ставят иммуногистохимические реакции на гормональные рецепторы, Her2 и Ki67', 'Der unter Ultraschallkontrolle gewonnene Zylinder wird wie gewöhnliches histologisches Material aufgearbeitet, anschließend werden an den Schnitten immunhistochemische Reaktionen auf Hormonrezeptoren, Her2 und Ki67 durchgeführt', 'Ultrason eşliğinde iğneyle alınan silindir olağan histolojik örnek gibi işlenir, ardından kesitlerde hormon reseptörleri, Her2 ve Ki67 için immünohistokimyasal reaksiyonlar yapılır', 'A lump or lesion in the breast found on examination, ultrasound or mammography, clarifying the nature of the changes before surgery, describing tissue properties for treatment planning, enlarged axillary lymph nodes', 'Čvor ili tvorba u dojci uočena pregledom, ultrazvukom ili mamografijom, razjašnjenje prirode promjena prije operacije, opis osobina tkiva radi planiranja liječenja, uvećani pazušni limfni čvorovi', 'Чвор или творба у дојци уочена прегледом, ултразвуком или мамографијом, разјашњење природе промјена прије операције, опис особина ткива ради планирања лијечења, увећани пазушни лимфни чворови', 'Уплотнение или образование в груди, найденное при осмотре, УЗИ или маммографии, уточнение природы изменений до операции, описание свойств ткани для планирования лечения, увеличенные подмышечные лимфоузлы', 'Bei Tastuntersuchung, Ultraschall oder Mammografie gefundener Knoten der Brust, Abklärung der Veränderung vor einer Operation, Beschreibung der Gewebeeigenschaften für die Therapieplanung, vergrößerte Achsellymphknoten', 'Muayene, ultrason veya mamografide saptanan meme kitlesi, ameliyat öncesi değişikliğin niteliğinin araştırılması, tedavi planı için doku özelliklerinin tanımlanması, büyümüş koltuk altı lenf nodları', 'Preparation concerns the biopsy itself: the site is anaesthetised and medicines that thin the blood are reported to the doctor in advance', 'Priprema se odnosi na samu biopsiju: mjesto se lokalno obezboli, a lijekove koji razrjeđuju krv treba unaprijed prijaviti ljekaru', 'Припрема се односи на саму биопсију: мјесто се локално обезболи, а лијекове који разрјеђују крв треба унапријед пријавити љекару', 'Подготовка относится к самой биопсии: место обезболивают, а о приёме препаратов, разжижающих кровь, заранее сообщают врачу', 'Die Vorbereitung betrifft die Biopsie: die Stelle wird örtlich betäubt, blutverdünnende Medikamente werden vorab ärztlich gemeldet', 'Hazırlık biyopsiyle ilgilidir: bölge lokal olarak uyuşturulur, kan sulandırıcı ilaçlar önceden hekime bildirilir', 'The histological description together with the Her2 and Ki67 values characterises the properties of the tissue and how it may respond to different kinds of treatment. The final report and the plan of care are put together by the treating doctor', 'Histološki opis zajedno sa vrijednostima Her2 i Ki67 govori o osobinama tkiva i o tome kako ono može reagovati na različite vrste liječenja. Konačan nalaz i plan vođenja sastavlja ljekar koji vodi liječenje', 'Хистолошки опис заједно са вриједностима Her2 и Ki67 говори о особинама ткива и о томе како оно може реаговати на различите врсте лијечења. Коначан налаз и план вођења саставља љекар који води лијечење', 'Гистологическое описание вместе со значениями Her2 и Ki67 характеризует свойства ткани и её возможный ответ на разные виды лечения. Итоговое заключение и план ведения формирует лечащий врач', 'Die histologische Beschreibung zusammen mit Her2 und Ki67 kennzeichnet die Eigenschaften des Gewebes und sein mögliches Ansprechen auf verschiedene Behandlungsformen. Den abschließenden Befund und den Behandlungsplan stellt die behandelnde Ärztin oder der behandelnde Arzt zusammen', 'Histolojik tanım, Her2 ve Ki67 değerleriyle birlikte dokunun özelliklerini ve farklı tedavi biçimlerine nasıl yanıt verebileceğini ortaya koyar. Nihai raporu ve izlem planını tedaviyi yürüten hekim oluşturur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'removed-breast-and-axillary-lymph-nodes-examination'), 'Histological assessment of the surgical specimen: breast tissue together with the axillary lymph nodes', 'Histološka procjena operativnog materijala: tkiva dojke zajedno sa pazušnim limfnim čvorovima', 'Хистолошка процјена оперативног материјала: ткива дојке заједно са пазушним лимфним чворовима', 'Гистологическая оценка операционного материала: ткани молочной железы вместе с подмышечными лимфатическими узлами', 'Histologische Beurteilung des Operationspräparats: Brustgewebe zusammen mit den Achsellymphknoten', 'Ameliyat materyalinin histolojik değerlendirmesi: meme dokusu ve koltuk altı lenf nodları', 'The gland and the lymph nodes found in the fatty tissue are described and measured, cut into blocks by region and read under the microscope node by node and along the resection margins', 'Žlijezda i limfni čvorovi nađeni u masnom tkivu opisuju se i mjere, isijecaju po regijama i čitaju pod mikroskopom čvor po čvor i uz rubove resekcije', 'Жлијезда и лимфни чворови нађени у масном ткиву описују се и мјере, исијецају по регијама и читају под микроскопом чвор по чвор и уз рубове ресекције', 'Железу и найденные в жировой клетчатке лимфоузлы описывают и измеряют, нарезают по участкам и читают под микроскопом отдельно по каждому узлу и вдоль краёв резекции', 'Drüse und die im Fettgewebe aufgesuchten Lymphknoten werden beschrieben und vermessen, regionenweise zugeschnitten und Knoten für Knoten sowie entlang der Resektionsränder mikroskopisch beurteilt', 'Meme ve yağ dokusu içinde bulunan lenf nodları tanımlanıp ölçülür, bölgelere göre örneklenir ve her nod ile cerrahi sınırlar boyunca mikroskopta okunur', 'Routine examination after removal of the breast with the axillary lymph nodes, assessing the extent of the changes and the state of the nodes, confirming what was found before the operation', 'Redovan pregled poslije odstranjenja dojke sa pazušnim limfnim čvorovima, procjena obima promjena i stanja čvorova, potvrda nalaza dobijenih prije operacije', 'Редован преглед послије одстрањења дојке са пазушним лимфним чворовима, процјена обима промјена и стања чворова, потврда налаза добијених прије операције', 'Плановое исследование после удаления молочной железы с подмышечными лимфоузлами, оценка объёма изменений и состояния узлов, подтверждение данных, полученных до операции', 'Routineuntersuchung nach Entfernung der Brust mit den Achsellymphknoten, Beurteilung der Ausdehnung der Veränderungen und des Zustands der Lymphknoten, Bestätigung der vor der Operation erhobenen Befunde', 'Meme ve koltuk altı lenf nodları çıkarıldıktan sonra rutin inceleme, değişikliklerin yaygınlığının ve nodların durumunun değerlendirilmesi, ameliyat öncesi bulguların doğrulanması', 'Nothing is required from the patient: the specimen goes to the laboratory straight from the operating theatre', 'Od pacijentkinje se ne traži ništa: materijal stiže u laboratoriju direktno iz operacione sale', 'Од пацијенткиње се не тражи ништа: материјал стиже у лабораторију директно из операционе сале', 'От пациентки подготовки не требуется: материал поступает в лабораторию прямо из операционной', 'Von der Patientin ist nichts vorzubereiten: das Präparat gelangt direkt aus dem Operationssaal ins Labor', 'Hastadan bir şey istenmez: materyal ameliyathaneden doğrudan laboratuvara ulaşır', 'The report describes the structure of the breast tissue, the size of the altered area, the resection margins and whether the lymph nodes are involved. How this affects further treatment is explained by the treating doctor', 'Nalaz opisuje građu tkiva dojke, veličinu izmijenjenog područja, rubove resekcije i da li su limfni čvorovi zahvaćeni. Kako to utiče na dalje liječenje, objašnjava ljekar koji vodi liječenje', 'Налаз описује грађу ткива дојке, величину измијењеног подручја, рубове ресекције и да ли су лимфни чворови захваћени. Како то утиче на даље лијечење, објашњава љекар који води лијечење', 'Заключение описывает строение ткани железы, размер изменённого участка, края резекции и то, затронуты ли лимфоузлы. Как это влияет на дальнейшее лечение, объясняет лечащий врач', 'Der Befund beschreibt den Aufbau des Brustgewebes, die Größe des veränderten Bereichs, die Resektionsränder und ob Lymphknoten betroffen sind. Was das für die weitere Behandlung bedeutet, erläutert die behandelnde Ärztin oder der behandelnde Arzt', 'Rapor meme dokusunun yapısını, değişen alanın büyüklüğünü, cerrahi sınırları ve lenf nodlarının tutulup tutulmadığını tanımlar. Bunun tedaviye etkisini tedaviyi yürüten hekim açıklar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'removed-breast-with-her2-and-ki67-receptors'), 'Histological assessment of tissue removed at breast surgery, together with the Her2 and Ki67 values', 'Histološka procjena tkiva odstranjenog operacijom dojke, zajedno sa vrijednostima Her2 i Ki67', 'Хистолошка процјена ткива одстрањеног операцијом дојке, заједно са вриједностима Her2 и Ki67', 'Гистологическая оценка ткани, удалённой при операции на молочной железе, вместе с показателями Her2 и Ki67', 'Histologische Beurteilung des bei einer Brustoperation entfernten Gewebes zusammen mit den Werten für Her2 und Ki67', 'Meme ameliyatında çıkarılan dokunun, Her2 ve Ki67 değerleriyle birlikte histolojik değerlendirmesi', 'After the usual histological description of the surgical specimen, immunohistochemical reactions for hormone receptors, Her2 and the cell division marker Ki67 are additionally performed on the sections', 'Poslije uobičajenog histološkog opisa operativnog materijala na presjecima se dodatno rade imunohistohemijske reakcije na hormonske receptore, Her2 i pokazatelj dijeljenja ćelija Ki67', 'Послије уобичајеног хистолошког описа оперативног материјала на пресјецима се додатно раде имунохистохемијске реакције на хормонске рецепторе, Her2 и показатељ дијељења ћелија Ki67', 'После обычного гистологического описания операционного материала на срезах дополнительно ставят иммуногистохимические реакции на гормональные рецепторы, Her2 и показатель деления клеток Ki67', 'Nach der üblichen histologischen Beschreibung des Operationspräparats werden an den Schnitten zusätzlich immunhistochemische Reaktionen auf Hormonrezeptoren, Her2 und den Teilungsmarker Ki67 durchgeführt', 'Ameliyat materyalinin olağan histolojik tanımının ardından kesitlerde hormon reseptörleri, Her2 ve hücre bölünmesi belirteci Ki67 için immünohistokimyasal reaksiyonlar da yapılır', 'Assessment of tissue after breast surgery, describing tissue properties for planning further treatment, determining the markers if they were not checked before the operation', 'Procjena tkiva poslije operacije dojke, opis osobina tkiva radi planiranja daljeg liječenja, određivanje pokazatelja ako prije operacije nisu rađeni', 'Процјена ткива послије операције дојке, опис особина ткива ради планирања даљег лијечења, одређивање показатеља ако прије операције нису рађени', 'Оценка ткани после операции на молочной железе, описание свойств ткани для планирования дальнейшего лечения, определение показателей, если до операции их не смотрели', 'Beurteilung des Gewebes nach einer Brustoperation, Beschreibung der Gewebeeigenschaften für die weitere Therapieplanung, Nachbestimmung der Marker, wenn sie vor der Operation nicht erhoben wurden', 'Meme ameliyatı sonrası dokunun değerlendirilmesi, ileri tedavi planı için doku özelliklerinin tanımlanması, ameliyat öncesi bakılmadıysa belirteçlerin sonradan çalışılması', 'No separate preparation: the examination is performed on material obtained during the operation', 'Posebne pripreme nema: pregled se radi na materijalu dobijenom tokom operacije', 'Посебне припреме нема: преглед се ради на материјалу добијеном током операције', 'Отдельная подготовка не нужна: исследование выполняют на материале, полученном во время операции', 'Keine gesonderte Vorbereitung: untersucht wird das bei der Operation gewonnene Material', 'Ayrı hazırlık gerekmez: inceleme ameliyat sırasında alınan materyal üzerinde yapılır', 'These markers describe how the tissue may respond to different kinds of treatment and how actively its cells divide. What follows from this in a particular case is decided by the oncologist together with the operating surgeon', 'Ovi pokazatelji opisuju kako tkivo može reagovati na različite vrste liječenja i koliko se njegove ćelije aktivno dijele. Šta iz toga slijedi u konkretnom slučaju, odlučuje onkolog zajedno sa hirurgom koji je operisao', 'Ови показатељи описују како ткиво може реаговати на различите врсте лијечења и колико се његове ћелије активно дијеле. Шта из тога слиједи у конкретном случају, одлучује онколог заједно са хирургом који је оперисао', 'Эти показатели описывают, как ткань может отвечать на разные виды лечения и насколько активно делятся её клетки. Что из этого следует в конкретном случае, определяет онколог вместе с оперировавшим хирургом', 'Diese Marker beschreiben, wie das Gewebe auf verschiedene Behandlungsformen ansprechen kann und wie aktiv sich seine Zellen teilen. Was daraus im Einzelfall folgt, legt die Onkologie gemeinsam mit der operierenden Chirurgie fest', 'Bu belirteçler dokunun farklı tedavi biçimlerine nasıl yanıt verebileceğini ve hücrelerinin ne kadar hızlı bölündüğünü tanımlar. Bunun o durumda ne anlama geldiğine onkoloji uzmanı ameliyatı yapan cerrahla birlikte karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'surgical-breast-biopsy-with-her2-and-ki67-receptors'), 'Examination of a piece of breast tissue excised by the surgeon, with testing for Her2 and Ki67', 'Pregled isječka tkiva dojke koji je hirurg izrezao, uz određivanje Her2 i Ki67', 'Преглед исјечка ткива дојке који је хирург изрезао, уз одређивање Her2 и Ki67', 'Исследование участка молочной железы, иссечённого хирургом, с определением Her2 и Ki67', 'Untersuchung eines chirurgisch entnommenen Gewebestücks der Brust einschließlich der Bestimmung von Her2 und Ki67', 'Cerrahın çıkardığı meme dokusu parçasının, Her2 ve Ki67 belirlenerek incelenmesi', 'The excised fragment is examined in full, including its margins, and immunohistochemical reactions for hormone receptors, Her2 and Ki67 are then carried out on selected sections', 'Izrezani komad se pregleda u cjelini, zajedno sa rubovima, a zatim se na izabranim presjecima rade imunohistohemijske reakcije na hormonske receptore, Her2 i Ki67', 'Изрезани комад се прегледа у цјелини, заједно са рубовима, а затим се на изабраним пресјецима раде имунохистохемијске реакције на хормонске рецепторе, Her2 и Ki67', 'Иссечённый фрагмент исследуют целиком, вместе с краями, а затем на выбранных срезах выполняют иммуногистохимические реакции на гормональные рецепторы, Her2 и Ki67', 'Das entnommene Stück wird vollständig samt Rändern beurteilt, anschließend werden an ausgewählten Schnitten immunhistochemische Reaktionen auf Hormonrezeptoren, Her2 und Ki67 durchgeführt', 'Çıkarılan parça sınırlarıyla birlikte bütünüyle incelenir, ardından seçilen kesitlerde hormon reseptörleri, Her2 ve Ki67 için immünohistokimyasal reaksiyonlar yapılır', 'A lesion that is to be removed whole, an inconclusive needle biopsy result, the need to describe tissue properties before treatment is planned', 'Tvorba koju je odlučeno odstraniti u cijelosti, neinformativan nalaz iglene biopsije, potreba da se osobine tkiva opišu prije planiranja liječenja', 'Творба коју је одлучено одстранити у цијелости, неинформативан налаз иглене биопсије, потреба да се особине ткива опишу прије планирања лијечења', 'Образование, которое решено удалить целиком, неинформативный результат игольной биопсии, необходимость описать свойства ткани до планирования лечения', 'Eine Veränderung, die vollständig entfernt werden soll, ein nicht aussagekräftiges Ergebnis der Nadelbiopsie, Beschreibung der Gewebeeigenschaften vor der Therapieplanung', 'Bütün olarak çıkarılmasına karar verilen oluşum, iğne biyopsisinin yeterli bilgi vermemesi, tedavi planlanmadan önce doku özelliklerinin tanımlanması gereği', 'The surgeon explains how to prepare for the operation, the laboratory stage needs nothing from the patient', 'Pripremu za operaciju objašnjava hirurg, za laboratorijski dio pacijentkinja ne radi ništa', 'Припрему за операцију објашњава хирург, за лабораторијски дио пацијенткиња не ради ништа', 'Подготовку к операции объясняет хирург, к лабораторному этапу пациентка не готовится', 'Wie die Operation vorzubereiten ist, erklärt die Chirurgie, für den Laborteil ist von der Patientin nichts zu tun', 'Ameliyat hazırlığını cerrah anlatır, laboratuvar aşamasında hastadan bir şey istenmez', 'The report brings together the description of the tissue, the state of the excision margins and the Her2 and Ki67 values. The treating doctor uses these data when choosing what to do next', 'Nalaz objedinjuje opis građe tkiva, stanje rubova ekscizije i vrijednosti Her2 i Ki67. Te podatke ljekar koji vodi liječenje koristi pri izboru daljeg postupka', 'Налаз обједињује опис грађе ткива, стање рубова ексцизије и вриједности Her2 и Ki67. Те податке љекар који води лијечење користи при избору даљег поступка', 'Заключение объединяет описание строения ткани, состояние краёв иссечения и значения Her2 и Ki67. Эти данные лечащий врач использует при выборе дальнейшей тактики', 'Der Befund fasst die Beschreibung des Gewebes, den Zustand der Schnittränder und die Werte von Her2 und Ki67 zusammen. Diese Angaben nutzt die behandelnde Ärztin oder der behandelnde Arzt bei der Wahl des weiteren Vorgehens', 'Rapor doku yapısının tanımını, cerrahi sınırların durumunu ve Her2 ile Ki67 değerlerini bir araya getirir. Bu verileri tedaviyi yürüten hekim sonraki adımı seçerken kullanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bordetella-pertussis-igg'), 'Blood test for IgG class antibodies to Bordetella pertussis, the bacterium that causes whooping cough', 'Analiza krvi na antitijela klase IgG na bakteriju Bordetella pertussis, uzročnika velikog kašlja', 'Анализа крви на антитијела класе IgG на бактерију Bordetella pertussis, узрочника великог кашља', 'Анализ крови на антитела класса IgG к бактерии Bordetella pertussis, возбудителю коклюша', 'Bluttest auf Antikörper der Klasse IgG gegen Bordetella pertussis, den Erreger des Keuchhustens', 'Boğmaca etkeni Bordetella pertussis bakterisine karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Paroxysmal cough lasting more than two weeks, cough in an adult living with an infant, examination of contacts, assessment of the immune response after illness or vaccination', 'Napadi kašlja koji traju duže od dvije nedjelje, kašalj kod odrasle osobe u porodici sa odojčetom, ispitivanje kontakata, procjena imunskog odgovora poslije bolesti ili vakcinacije', 'Напади кашља који трају дуже од двије недјеље, кашаљ код одрасле особе у породици са одојчетом, испитивање контаката, процјена имунског одговора послије болести или вакцинације', 'Приступообразный кашель, который тянется больше двух недель, кашель у взрослого в семье с грудным ребёнком, обследование контактных лиц, оценка иммунного ответа после болезни или прививки', 'Anfallsartiger Husten über mehr als zwei Wochen, Husten bei einem Erwachsenen im Haushalt mit einem Säugling, Untersuchung von Kontaktpersonen, Beurteilung der Immunantwort nach Erkrankung oder Impfung', 'İki haftadan uzun süren nöbetler hâlinde öksürük, bebekle aynı evde yaşayan yetişkinde öksürük, temaslıların incelenmesi, hastalık veya aşı sonrası bağışık yanıtın değerlendirilmesi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgG levels may reflect either a past infection or an earlier vaccination, so a single sample cannot show how long ago the contact occurred. A doctor assesses the result together with the duration of the cough and the vaccination history', 'Nivo IgG može odražavati i preboljelu infekciju i raniju vakcinaciju, pa se iz jednog uzorka ne može odrediti kada je kontakt nastao. Nalaz procjenjuje ljekar uz podatke o trajanju kašlja i vakcinalnom statusu', 'Ниво IgG може одражавати и пребољелу инфекцију и ранију вакцинацију, па се из једног узорка не може одредити када је контакт настао. Налаз процјењује љекар уз податке о трајању кашља и вакциналном статусу', 'Уровень IgG может отражать и перенесённую инфекцию, и прошлую вакцинацию, поэтому по одному образцу нельзя определить давность контакта. Результат оценивает врач с учётом длительности кашля и прививочного анамнеза', 'Der IgG-Wert kann sowohl eine durchgemachte Infektion als auch eine frühere Impfung widerspiegeln, aus einer einzelnen Probe lässt sich der Zeitpunkt des Kontakts nicht ableiten. Der Arzt beurteilt den Befund zusammen mit der Hustendauer und dem Impfstatus', 'IgG düzeyi hem geçirilmiş enfeksiyonu hem de önceki aşılamayı yansıtabilir, tek bir örnekten temasın ne zaman olduğu anlaşılmaz. Sonucu hekim öksürüğün süresi ve aşı geçmişiyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'candida-igm-antibodies'), 'Blood test for IgM class antibodies to fungi of the Candida genus', 'Analiza krvi na antitijela klase IgM na gljivice roda Candida', 'Анализа крви на антитијела класе IgM на гљивице рода Candida', 'Анализ крови на антитела класса IgM к грибам рода Candida', 'Bluttest auf Antikörper der Klasse IgM gegen Pilze der Gattung Candida', 'Candida cinsi mantarlara karşı IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Long-lasting complaints against a background of reduced immunity, additional work-up together with culture and microscopy, follow-up by a doctor when a widespread fungal infection is suspected', 'Dugotrajne tegobe uz oslabljen imunitet, dopunsko ispitivanje uz kulturu i mikroskopiju, praćenje kod ljekara kada se sumnja na proširenu gljivičnu infekciju', 'Дуготрајне тегобе уз ослабљен имунитет, допунско испитивање уз културу и микроскопију, праћење код љекара када се сумња на проширену гљивичну инфекцију', 'Длительные жалобы на фоне сниженного иммунитета, дообследование вместе с посевом и микроскопией, наблюдение у врача при подозрении на распространённую грибковую инфекцию', 'Länger bestehende Beschwerden bei geschwächtem Immunsystem, ergänzende Abklärung zusammen mit Kultur und Mikroskopie, ärztliche Kontrolle bei Verdacht auf eine ausgedehnte Pilzinfektion', 'Bağışıklığın zayıf olduğu durumlarda uzun süren şikayetler, kültür ve mikroskopi ile birlikte ileri inceleme, yaygın mantar enfeksiyonu düşünüldüğünde hekim takibi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'Candida fungi are also present in healthy people, so antibodies alone do not show whether an active infection exists or where it is. The result is assessed by a doctor together with culture and the clinical picture', 'Gljivice roda Candida postoje i kod zdravih ljudi, pa antitijela sama po sebi ne pokazuju da li je infekcija aktivna i gdje se nalazi. Nalaz procjenjuje ljekar zajedno sa kulturom i kliničkom slikom', 'Гљивице рода Candida постоје и код здравих људи, па антитијела сама по себи не показују да ли је инфекција активна и гдје се налази. Налаз процјењује љекар заједно са културом и клиничком сликом', 'Грибы рода Candida есть в организме и у здоровых людей, поэтому антитела сами по себе не показывают, есть ли активная инфекция и где она. Результат оценивает врач вместе с посевом и картиной болезни', 'Candida-Pilze kommen auch bei Gesunden vor, daher zeigen Antikörper allein nicht, ob eine aktive Infektion besteht und wo sie liegt. Der Arzt beurteilt den Befund zusammen mit Kultur und Krankheitsbild', 'Candida mantarları sağlıklı kişilerde de bulunur, bu nedenle antikorlar tek başına enfeksiyonun etkin olup olmadığını ve yerini göstermez. Sonucu hekim kültür ve klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chlamydia-trachomatis-iht'), 'Rapid immunochromatographic test that detects the Chlamydia trachomatis antigen in urogenital material', 'Brzi imunohromatografski test koji otkriva antigen Chlamydia trachomatis u urogenitalnom materijalu', 'Брзи имунохроматографски тест који открива антиген Chlamydia trachomatis у урогениталном материјалу', 'Быстрый иммунохроматографический тест, выявляющий антиген Chlamydia trachomatis в урогенитальном материале', 'Immunchromatographischer Schnelltest, der das Antigen von Chlamydia trachomatis im urogenitalen Material nachweist', 'Ürogenital örnekte Chlamydia trachomatis antijenini saptayan hızlı immünokromatografik test', 'A swab is taken from the urethra or cervical canal, and the test strip is read during the same visit', 'Brisom se uzima materijal iz uretre ili cervikalnog kanala, a test-traka se očitava tokom iste posjete', 'Брисом се узима материјал из уретре или цервикалног канала, а тест-трака се очитава током исте посјете', 'Тампоном берут мазок из уретры или цервикального канала, тест-полоску оценивают в тот же визит', 'Mit einem Tupfer wird ein Abstrich aus der Harnröhre oder dem Gebärmutterhalskanal entnommen, der Teststreifen wird noch im selben Termin abgelesen', 'Üretradan veya servikal kanaldan eküvyonla örnek alınır, test şeridi aynı ziyarette okunur', 'Discharge, discomfort when urinating, lower abdominal pain, examination of a partner, situations where a quick preliminary answer is needed', 'Sekret, nelagodnost pri mokrenju, bol u donjem dijelu stomaka, ispitivanje partnera, situacije kada je potreban brz preliminarni odgovor', 'Секрет, нелагодност при мокрењу, бол у доњем дијелу стомака, испитивање партнера, ситуације када је потребан брз прелиминарни одговор', 'Выделения, дискомфорт при мочеиспускании, боль внизу живота, обследование партнёра, ситуации, когда нужен быстрый предварительный ответ', 'Ausfluss, Beschwerden beim Wasserlassen, Unterbauchschmerzen, Untersuchung des Partners, Situationen mit Bedarf an einem schnellen vorläufigen Ergebnis', 'Akıntı, idrar yaparken rahatsızlık, kasık ağrısı, partnerin incelenmesi, hızlı bir ön yanıtın gerektiği durumlar', 'Do not urinate for 2–3 hours before the swab, women should come outside the days of menstruation and without local products the day before', 'Ne mokriti 2–3 sata prije uzimanja brisa, žene dolaze van dana menstruacije i bez lokalnih preparata dan ranije', 'Не мокрити 2–3 сата прије узимања бриса, жене долазе ван дана менструације и без локалних препарата дан раније', 'Не мочиться 2–3 часа перед взятием мазка, женщинам приходить вне дней менструации и без местных средств накануне', '2–3 Stunden vor dem Abstrich nicht Wasser lassen, Frauen kommen außerhalb der Menstruationstage und ohne lokale Präparate am Vortag', 'Örnek alınmadan 2–3 saat önce idrara çıkılmamalı, kadınlar adet günleri dışında ve bir gün öncesinde lokal ürün kullanmadan gelmelidir', 'The rapid test is less sensitive than PCR: a negative result does not rule out infection, and a positive one is usually confirmed by a molecular method. Further work-up, including of the partner, is prescribed by a doctor', 'Brzi test je manje osjetljiv od PCR: negativan nalaz ne isključuje infekciju, a pozitivan se obično potvrđuje molekularnom metodom. Dalje ispitivanje, uključujući i partnera, određuje ljekar', 'Брзи тест је мање осјетљив од ПЦР: негативан налаз не искључује инфекцију, а позитиван се обично потврђује молекуларном методом. Даље испитивање, укључујући и партнера, одређује љекар', 'Быстрый тест менее чувствителен, чем ПЦР: отрицательный результат инфекцию не исключает, а положительный обычно подтверждают молекулярным методом. Дальнейшее обследование, в том числе партнёра, назначает врач', 'Der Schnelltest ist weniger empfindlich als die PCR: Ein negatives Ergebnis schließt eine Infektion nicht aus, ein positives wird in der Regel mit einer molekularen Methode bestätigt. Die weitere Abklärung, auch des Partners, legt der Arzt fest', 'Hızlı test PCR kadar duyarlı değildir: negatif sonuç enfeksiyonu dışlamaz, pozitif sonuç genellikle moleküler yöntemle doğrulanır. Partner incelemesi dahil ileri tetkikleri hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'measles-igg'), 'Blood test for IgG class antibodies to the measles virus', 'Analiza krvi na antitijela klase IgG na virus morbila', 'Анализа крви на антитијела класе IgG на вирус морбила', 'Анализ крови на антитела класса IgG к вирусу кори', 'Bluttest auf Antikörper der Klasse IgG gegen das Masernvirus', 'Kızamık virüsüne karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Checking protection before working in a medical or childcare facility, missing vaccination records, examination after contact with an ill person, pregnancy planning', 'Provjera zaštite prije rada u zdravstvenoj ili dječjoj ustanovi, nedostupni podaci o vakcinaciji, ispitivanje poslije kontakta sa oboljelim, planiranje trudnoće', 'Провјера заштите прије рада у здравственој или дјечјој установи, недоступни подаци о вакцинацији, испитивање послије контакта са обољелим, планирање трудноће', 'Проверка защиты перед работой в медицинском или детском учреждении, утраченные сведения о прививках, обследование после контакта с заболевшим, планирование беременности', 'Überprüfung des Schutzes vor der Arbeit in einer medizinischen Einrichtung oder in der Kinderbetreuung, fehlende Impfunterlagen, Untersuchung nach Kontakt mit einer erkrankten Person, Kinderwunsch', 'Sağlık kuruluşunda veya çocuk kurumunda çalışmadan önce bağışıklığın kontrolü, aşı kayıtlarının bulunmaması, hasta biriyle temas sonrası inceleme, gebelik planlaması', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgG reflects a past infection or a response to vaccination, and its absence means there is no confirmed protection. Whether vaccination is needed is decided by a doctor', 'IgG odražavaju preboljelu infekciju ili odgovor na vakcinu, a njihov izostanak znači da potvrđene zaštite nema. Da li je vakcinacija potrebna, odlučuje ljekar', 'IgG одражавају пребољелу инфекцију или одговор на вакцину, а њихов изостанак значи да потврђене заштите нема. Да ли је вакцинација потребна, одлучује љекар', 'IgG отражают перенесённую инфекцию или ответ на прививку, а их отсутствие означает, что подтверждённой защиты нет. Нужна ли вакцинация, решает врач', 'IgG spiegelt eine durchgemachte Infektion oder die Impfantwort wider, sein Fehlen bedeutet, dass kein bestätigter Schutz vorliegt. Ob eine Impfung nötig ist, entscheidet der Arzt', 'IgG geçirilmiş enfeksiyonu veya aşı yanıtını yansıtır, bulunmaması doğrulanmış bir korumanın olmadığı anlamına gelir. Aşı gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'measles-igm'), 'Blood test for IgM class antibodies to the measles virus', 'Analiza krvi na antitijela klase IgM na virus morbila', 'Анализа крви на антитијела класе IgM на вирус морбила', 'Анализ крови на антитела класса IgM к вирусу кори', 'Bluttest auf Antikörper der Klasse IgM gegen das Masernvirus', 'Kızamık virüsüne karşı IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'High fever with a rash, runny nose, cough and eye inflammation, contact with a person ill with measles, epidemiological investigation', 'Visoka temperatura sa osipom, curenje iz nosa, kašalj i zapaljenje očiju, kontakt sa oboljelim od morbila, epidemiološko ispitivanje', 'Висока температура са осипом, цурење из носа, кашаљ и запаљење очију, контакт са обољелим од морбила, епидемиолошко испитивање', 'Высокая температура с сыпью, насморк, кашель и воспаление глаз, контакт с заболевшим корью, эпидемиологическое обследование', 'Hohes Fieber mit Hautausschlag, Schnupfen, Husten und Augenentzündung, Kontakt mit einer an Masern erkrankten Person, epidemiologische Abklärung', 'Döküntüyle birlikte yüksek ateş, burun akıntısı, öksürük ve göz iltihabı, kızamık geçiren biriyle temas, salgın incelemesi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM is usually linked to a recent infection, yet in the first days of the rash it may not be detectable, and a recent vaccination can also produce a reaction. The doctor assesses the result together with the clinical picture and may order a repeat test', 'IgM su obično vezani za skorašnju infekciju, ali se prvih dana osipa još ne moraju otkriti, a reakcija je moguća i poslije nedavne vakcinacije. Ljekar procjenjuje nalaz uz kliničku sliku i po potrebi traži ponovljenu analizu', 'IgM су обично везани за скорашњу инфекцију, али се првих дана осипа још не морају открити, а реакција је могућа и послије недавне вакцинације. Љекар процјењује налаз уз клиничку слику и по потреби тражи поновљену анализу', 'IgM обычно связаны с недавним заражением, при этом в первые дни сыпи они могут ещё не определяться, а после недавней прививки возможна реакция. Врач оценивает результат вместе с картиной болезни и при необходимости назначает повторный анализ', 'IgM hängt meist mit einer kürzlichen Ansteckung zusammen, in den ersten Tagen des Ausschlags kann es jedoch noch nicht nachweisbar sein, und auch nach einer kürzlichen Impfung ist eine Reaktion möglich. Der Arzt beurteilt den Befund zusammen mit dem Krankheitsbild und ordnet bei Bedarf eine Kontrolle an', 'IgM genellikle yakın zamanda geçirilen enfeksiyonla ilişkilidir, ancak döküntünün ilk günlerinde henüz saptanmayabilir, yakın zamanda yapılan aşı sonrasında da reaksiyon görülebilir. Hekim sonucu klinik tabloyla değerlendirir ve gerekirse testi tekrarlatır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mycoplasma-hominis-ureaplasma'), 'Combined examination of urogenital material for both Mycoplasma hominis and Ureaplasma', 'Zajedničko ispitivanje urogenitalnog materijala na Mycoplasma hominis i ureaplazmu', 'Заједничко испитивање урогениталног материјала на Mycoplasma hominis и уреаплазму', 'Совместное исследование урогенитального материала сразу на Mycoplasma hominis и уреаплазму', 'Gemeinsame Untersuchung von urogenitalem Material auf Mycoplasma hominis und Ureaplasmen', 'Ürogenital örneğin hem Mycoplasma hominis hem de Ureaplasma için birlikte incelenmesi', 'Material is taken with a swab from the urethra, vagina or cervical canal and checked in the laboratory for both microorganisms, the result takes from one to several days depending on the method', 'Materijal se uzima brisom iz uretre, vagine ili cervikalnog kanala i u laboratoriji se provjerava na oba mikroorganizma, nalaz se čeka od jednog do nekoliko dana zavisno od metode', 'Материјал се узима брисом из уретре, вагине или цервикалног канала и у лабораторији се провјерава на оба микроорганизма, налаз се чека од једног до неколико дана зависно од методе', 'Материал берут тампоном из уретры, влагалища или цервикального канала и в лаборатории проверяют на оба микроорганизма, ответ готовится от одного до нескольких дней в зависимости от метода', 'Das Material wird mit einem Tupfer aus Harnröhre, Scheide oder Gebärmutterhalskanal entnommen und im Labor auf beide Erreger geprüft, je nach Methode dauert der Befund einen bis mehrere Tage', 'Örnek üretradan, vajinadan veya servikal kanaldan eküvyonla alınır ve laboratuvarda her iki mikroorganizma için incelenir, sonuç yönteme göre bir ila birkaç gün sürer', 'Inflammatory complaints of the urogenital tract, preparation for gynaecological and urological procedures, recurrent bacterial vaginosis, examination of a couple planning a pregnancy', 'Zapaljenske tegobe mokraćno-polnog sistema, priprema za ginekološke i urološke zahvate, ponavljana bakterijska vaginoza, ispitivanje para prije planiranja trudnoće', 'Запаљенске тегобе мокраћно-полног система, припрема за гинеколошке и уролошке захвате, понављана бактеријска вагиноза, испитивање пара прије планирања трудноће', 'Воспалительные жалобы со стороны мочеполовой системы, подготовка к гинекологическим и урологическим вмешательствам, повторяющийся бактериальный вагиноз, обследование пары перед планированием беременности', 'Entzündliche Beschwerden im Urogenitaltrakt, Vorbereitung auf gynäkologische und urologische Eingriffe, wiederkehrende bakterielle Vaginose, Untersuchung eines Paares bei Kinderwunsch', 'Ürogenital sistemde iltihabi şikayetler, jinekolojik ve ürolojik girişimlere hazırlık, tekrarlayan bakteriyel vajinoz, gebelik planlayan çiftin incelenmesi', 'Avoid sexual contact, douching and vaginal products for a day before the test, the sample is taken no sooner than 2–3 hours after urinating, and for women outside menstruation', 'Dan prije ispitivanja izbjegavati intimne odnose, ispiranja i vaginalne preparate, materijal se uzima najranije 2–3 sata poslije mokrenja, kod žena van menstruacije', 'Дан прије испитивања избјегавати интимне односе, испирања и вагиналне препарате, материјал се узима најраније 2–3 сата послије мокрења, код жена ван менструације', 'За сутки до исследования исключить интимные контакты, спринцевания и вагинальные средства, материал берут не раньше чем через 2–3 часа после мочеиспускания, у женщин — вне менструации', 'Einen Tag vor der Untersuchung auf Geschlechtsverkehr, Spülungen und vaginale Präparate verzichten, die Probe wird frühestens 2–3 Stunden nach dem Wasserlassen entnommen, bei Frauen außerhalb der Menstruation', 'Testten bir gün önce cinsel ilişki, vajinal duş ve vajinal ürünlerden kaçınılmalı, örnek idrar yaptıktan en erken 2–3 saat sonra, kadınlarda adet dönemi dışında alınır', 'Both microorganisms belong to the opportunistic flora of the urogenital tract and are found in people without complaints, so a finding on its own does not equal a disease. The meaning of the result and the need for treatment and for examining the partner are determined by a doctor', 'Oba mikroorganizma pripadaju uslovnoj flori mokraćno-polnih puteva i nalaze se i kod osoba bez tegoba, pa nalaz sam po sebi ne znači bolest. Značaj nalaza, potrebu liječenja i ispitivanja partnera određuje ljekar', 'Оба микроорганизма припадају условној флори мокраћно-полних путева и налазе се и код особа без тегоба, па налаз сам по себи не значи болест. Значај налаза, потребу лијечења и испитивања партнера одређује љекар', 'Оба микроорганизма относятся к условной микрофлоре мочеполовых путей и встречаются у людей без жалоб, поэтому находка сама по себе не равна болезни. Значение результата, необходимость лечения и обследования партнёра определяет врач', 'Beide Erreger gehören zur fakultativen Flora der Harn- und Geschlechtswege und kommen auch bei Beschwerdefreien vor, ein Nachweis allein bedeutet daher keine Erkrankung. Die Bedeutung des Befundes sowie die Notwendigkeit einer Behandlung und einer Partneruntersuchung legt der Arzt fest', 'Her iki mikroorganizma da ürogenital yolun fırsatçı florasına aittir ve şikayeti olmayan kişilerde de bulunur, bu nedenle saptanmaları tek başına hastalık anlamına gelmez. Sonucun anlamını, tedavi ve partner incelemesi gerekip gerekmediğini hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'parvovirus-b19-igm'), 'Blood test for IgM class antibodies to parvovirus B19, which are produced in the first weeks after infection', 'Analiza krvi na antitijela klase IgM na parvovirus B19, koja se stvaraju u prvim nedjeljama poslije infekcije', 'Анализа крви на антитијела класе IgM на парвовирус Б19, која се стварају у првим недјељама послије инфекције', 'Анализ крови на антитела класса IgM к парвовирусу B19, которые вырабатываются в первые недели после заражения', 'Bluttest auf Antikörper der Klasse IgM gegen Parvovirus B19, die in den ersten Wochen nach der Ansteckung gebildet werden', 'Enfeksiyondan sonraki ilk haftalarda oluşan, parvovirüs B19''a karşı IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'A bright rash on the cheeks and trunk in a child, joint pain in an adult, contact of a pregnant woman with an ill child, an unexplained fall in blood counts', 'Izražen osip na obrazima i trupu kod djeteta, bolovi u zglobovima kod odraslih, kontakt trudnice sa oboljelim djetetom, pad krvnih parametara nejasnog porijekla', 'Изражен осип на образима и трупу код дјетета, болови у зглобовима код одраслих, контакт труднице са обољелим дјететом, пад крвних параметара нејасног поријекла', 'Яркая сыпь на щеках и туловище у ребёнка, боли в суставах у взрослого, контакт беременной с заболевшим ребёнком, снижение показателей крови неясного происхождения', 'Kräftiger Ausschlag an Wangen und Rumpf beim Kind, Gelenkschmerzen bei Erwachsenen, Kontakt einer Schwangeren mit einem erkrankten Kind, unklarer Abfall der Blutwerte', 'Çocukta yanaklarda ve gövdede belirgin döküntü, erişkinde eklem ağrıları, gebenin hasta çocukla teması, nedeni belirsiz kan değeri düşüklüğü', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM may be linked to a recent infection, it does not appear immediately and stays detectable only for a limited time. During pregnancy and in blood disorders further follow-up is decided by a doctor', 'IgM mogu biti povezani sa skorašnjom infekcijom, ne javljaju se odmah i zadržavaju se ograničeno vrijeme. U trudnoći i kod bolesti krvi dalje praćenje određuje ljekar', 'IgM могу бити повезани са скорашњом инфекцијом, не јављају се одмах и задржавају се ограничено вријеме. У трудноћи и код болести крви даље праћење одређује љекар', 'IgM могут быть связаны с недавним заражением, появляются они не сразу и сохраняются ограниченное время. При беременности и при болезнях крови дальнейшее наблюдение определяет врач', 'IgM kann mit einer kürzlichen Ansteckung zusammenhängen, es tritt nicht sofort auf und bleibt nur begrenzte Zeit nachweisbar. In der Schwangerschaft und bei Bluterkrankungen legt der Arzt das weitere Vorgehen fest', 'IgM yakın zamanda geçirilen enfeksiyonla ilişkili olabilir, hemen ortaya çıkmaz ve sınırlı bir süre saptanır. Gebelikte ve kan hastalıklarında izlemi hekim planlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'sars-cov-ab-igg-plus-igm'), 'Blood test that measures both IgG and IgM class antibodies to the SARS-CoV-2 virus in a single run', 'Analiza krvi koja u jednom ispitivanju određuje antitijela klasa IgG i IgM na virus SARS-CoV-2', 'Анализа крви која у једном испитивању одређује антитијела класа IgG и IgM на вирус SARS-CoV-2', 'Анализ крови, который в одном исследовании определяет антитела классов IgG и IgM к вирусу SARS-CoV-2', 'Bluttest, der in einem Durchgang Antikörper der Klassen IgG und IgM gegen das SARS-CoV-2-Virus bestimmt', 'SARS-CoV-2 virüsüne karşı IgG ve IgM sınıfı antikorları tek bir çalışmada belirleyen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessment of a past infection, the need to distinguish recent from older contact with the virus, epidemiological surveys', 'Procjena ranije preboljele infekcije, potreba da se razdvoji skorašnji od davnašnjeg kontakta sa virusom, epidemiološka ispitivanja', 'Процјена раније пребољеле инфекције, потреба да се раздвоји скорашњи од давнашњег контакта са вирусом, епидемиолошка испитивања', 'Оценка перенесённой ранее инфекции, потребность различить недавний и давний контакт с вирусом, эпидемиологические обследования', 'Beurteilung einer früher durchgemachten Infektion, Unterscheidung zwischen kürzlichem und länger zurückliegendem Kontakt mit dem Virus, epidemiologische Untersuchungen', 'Daha önce geçirilmiş enfeksiyonun değerlendirilmesi, yakın ve eski temasın ayırt edilmesi ihtiyacı, salgın araştırmaları', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgM more often reflects a recent encounter with the virus and IgG an older one or a vaccine response, while the presence of antibodies does not measure the degree of protection and does not replace the tests used to confirm an acute infection. The result is interpreted by a doctor', 'IgM češće odražavaju skorašnji susret sa virusom, a IgG davniji ili odgovor na vakcinu, pri čemu prisustvo antitijela ne mjeri stepen zaštite i ne zamjenjuje testove kojima se potvrđuje akutna infekcija. Nalaz tumači ljekar', 'IgM чешће одражавају скорашњи сусрет са вирусом, а IgG давнији или одговор на вакцину, при чему присуство антитијела не мјери степен заштите и не замјењује тестове којима се потврђује акутна инфекција. Налаз тумачи љекар', 'IgM чаще отражают недавнюю встречу с вирусом, IgG — более давнюю или ответ на прививку, при этом наличие антител не измеряет степень защиты и не заменяет тесты, которыми подтверждают острую инфекцию. Результат трактует врач', 'IgM weist eher auf einen kürzlichen Kontakt hin, IgG auf einen länger zurückliegenden oder auf die Impfantwort, dabei misst das Vorhandensein von Antikörpern nicht den Grad des Schutzes und ersetzt nicht die Tests zum Nachweis einer akuten Infektion. Der Arzt interpretiert den Befund', 'IgM daha çok yakın zamandaki teması, IgG ise daha eski teması ya da aşı yanıtını yansıtır, antikor bulunması koruma düzeyini ölçmez ve akut enfeksiyonu doğrulayan testlerin yerini tutmaz. Sonucu hekim yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'antimicrobial-antibody-detection-by-indirect-immunofluorescence'), 'Laboratory method that looks for antibodies to infectious agents in blood serum using fluorescent labels', 'Laboratorijska metoda kojom se u serumu krvi traže antitijela na uzročnike infekcija pomoću fluorescentnih obilježivača', 'Лабораторијска метода којом се у серуму крви траже антитијела на узрочнике инфекција помоћу флуоресцентних обиљеживача', 'Лабораторный метод, которым в сыворотке крови ищут антитела к возбудителям инфекций с помощью светящихся меток', 'Labormethode, mit der im Blutserum mithilfe fluoreszierender Marker Antikörper gegen Krankheitserreger gesucht werden', 'Kan serumunda enfeksiyon etkenlerine karşı antikorları floresan işaretleyicilerle arayan laboratuvar yöntemi', 'The serum is applied to a slide with a fixed antigen, a labelled reagent is added and the glow is assessed under a fluorescence microscope', 'Serum se nanosi na pločicu sa vezanim antigenom, dodaje se obilježeni reagens, a svjetlucanje se procjenjuje pod fluorescentnim mikroskopom', 'Серум се наноси на плочицу са везаним антигеном, додаје се обиљежени реагенс, а свјетлуцање се процјењује под флуоресцентним микроскопом', 'Сыворотку наносят на стекло с закреплённым антигеном, добавляют меченый реагент и оценивают свечение под флуоресцентным микроскопом', 'Das Serum wird auf einen Objektträger mit gebundenem Antigen gegeben, ein markiertes Reagenz wird zugesetzt und das Leuchten unter dem Fluoreszenzmikroskop beurteilt', 'Serum, antijenin sabitlendiği lam üzerine konur, işaretli reaktif eklenir ve floresan mikroskopta parlama değerlendirilir', 'Clarifying contact with a specific pathogen as directed by a doctor, infections for which the laboratory uses this particular method, additional work-up when other tests are unclear', 'Razjašnjenje kontakta sa određenim uzročnikom po uputu ljekara, infekcije za koje laboratorija koristi baš ovu metodu, dopunsko ispitivanje kada su drugi nalazi nejasni', 'Разјашњење контакта са одређеним узрочником по упуту љекара, инфекције за које лабораторија користи баш ову методу, допунско испитивање када су други налази нејасни', 'Уточнение контакта с конкретным возбудителем по направлению врача, инфекции, для которых лаборатория использует именно этот метод, дообследование при неясных результатах других тестов', 'Abklärung des Kontakts mit einem bestimmten Erreger auf ärztliche Anweisung, Infektionen, für die das Labor genau diese Methode einsetzt, Zusatzuntersuchung bei unklaren anderen Befunden', 'Hekim yönlendirmesiyle belirli bir etkenle temasın araştırılması, laboratuvarın bu yöntemi kullandığı enfeksiyonlar, diğer testler belirsiz kaldığında ileri inceleme', 'No special preparation is required, venous blood is taken for the test', 'Posebna priprema nije potrebna, za ispitivanje se uzima venska krv', 'Посебна припрема није потребна, за испитивање се узима венска крв', 'Специальной подготовки не требуется, для исследования берут венозную кровь', 'Keine besondere Vorbereitung erforderlich, für die Untersuchung wird venöses Blut entnommen', 'Özel bir hazırlık gerekmez, inceleme için venöz kan alınır', 'Detection of antibodies shows that the immune system has met the pathogen and does not by itself answer how long ago the contact was or how active the process is. The conclusion is drawn by a doctor together with the clinical picture and other tests', 'Nalaz antitijela pokazuje da se imunski sistem susreo sa uzročnikom i sam po sebi ne govori koliko je proces star ni koliko je aktivan. Zaključak donosi ljekar uz kliničku sliku i ostale analize', 'Налаз антитијела показује да се имунски систем сусрео са узрочником и сам по себи не говори колико је процес стар ни колико је активан. Закључак доноси љекар уз клиничку слику и остале анализе', 'Выявление антител говорит о встрече иммунной системы с возбудителем и само по себе не отвечает на вопрос о давности и активности процесса. Заключение делает врач вместе с картиной болезни и другими анализами', 'Der Nachweis von Antikörpern zeigt, dass das Immunsystem dem Erreger begegnet ist, und sagt für sich genommen nichts über Zeitpunkt und Aktivität aus. Die Beurteilung nimmt der Arzt zusammen mit dem Krankheitsbild und weiteren Befunden vor', 'Antikor saptanması bağışıklık sisteminin etkenle karşılaştığını gösterir, sürecin ne kadar eski veya ne kadar etkin olduğunu tek başına söylemez. Değerlendirmeyi hekim klinik tablo ve diğer tetkiklerle birlikte yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cryptosporidium-in-stool-ziehl-neelsen'), 'Search for Cryptosporidium in a stool sample under the microscope using Ziehl-Neelsen staining', 'Traženje kriptosporidijuma u uzorku stolice pod mikroskopom uz bojenje po Ziehl-Neelsenu', 'Тражење криптоспоридијума у узорку столице под микроскопом уз бојење по Зиехл-Неелсену', 'Поиск криптоспоридий в образце кала под микроскопом с помощью окраски по Цилю-Нильсену', 'Suche nach Kryptosporidien in einer Stuhlprobe unter dem Mikroskop mit Ziehl-Neelsen-Färbung', 'Dışkı örneğinde Ziehl-Neelsen boyamayla mikroskop altında Cryptosporidium aranması', 'A stool smear is stained so that the wall of the parasite oocysts takes on a characteristic colour, then the slide is examined under a microscope', 'Razmaz stolice se boji tako da omotač oocista parazita dobije karakterističnu boju, a preparat se zatim pregleda pod mikroskopom', 'Размаз столице се боји тако да омотач ооциста паразита добије карактеристичну боју, а препарат се затим прегледа под микроскопом', 'Мазок кала окрашивают так, что оболочка ооцист паразита приобретает характерный цвет, затем препарат просматривают под микроскопом', 'Ein Stuhlausstrich wird so gefärbt, dass die Hülle der Oozysten des Parasiten eine charakteristische Farbe annimmt, danach wird das Präparat unter dem Mikroskop durchgesehen', 'Dışkı yayması, parazit ookistlerinin duvarı belirgin bir renk alacak şekilde boyanır ve preparat mikroskopta incelenir', 'Watery diarrhoea, especially when prolonged, bowel complaints in a person with weakened immunity, diarrhoea after swimming in open water or after travel, investigation of cases clustered in a group', 'Vodenasti proliv, naročito dugotrajan, crijevne tegobe kod osobe oslabljenog imuniteta, proliv poslije kupanja u otvorenim vodama ili putovanja, ispitivanje kod grupnih slučajeva u kolektivu', 'Воденасти пролив, нарочито дуготрајан, цријевне тегобе код особе ослабљеног имунитета, пролив послије купања у отвореним водама или путовања, испитивање код групних случајева у колективу', 'Водянистая диарея, особенно затяжная, кишечные жалобы у человека с ослабленным иммунитетом, диарея после купания в открытой воде или поездки, обследование при групповых случаях в коллективе', 'Wässriger, besonders anhaltender Durchfall, Darmbeschwerden bei geschwächtem Immunsystem, Durchfall nach dem Baden in offenen Gewässern oder nach einer Reise, Abklärung bei gehäuften Fällen in einer Gemeinschaft', 'Özellikle uzun süren sulu ishal, bağışıklığı zayıf kişide bağırsak şikayetleri, açık suda yüzme veya seyahat sonrası ishal, toplu yaşanan yerlerdeki vakaların araştırılması', 'Collect stool in a clean dry container without urine and deliver it to the laboratory the same day, the doctor may order several samples collected on different days', 'Stolicu sakupiti u čistu suvu posudu bez primjesa mokraće i dostaviti u laboratoriju istog dana, ljekar može tražiti nekoliko uzoraka sakupljenih različitih dana', 'Столицу сакупити у чисту суву посуду без примјеса мокраће и доставити у лабораторију истог дана, љекар може тражити неколико узорака сакупљених различитих дана', 'Кал собирают в чистый сухой контейнер без примеси мочи и доставляют в лабораторию в тот же день, врач может назначить исследование нескольких образцов, собранных в разные дни', 'Stuhl in einem sauberen trockenen Behälter ohne Urinbeimengung sammeln und noch am selben Tag ins Labor bringen, der Arzt kann mehrere Proben von verschiedenen Tagen anfordern', 'Dışkı temiz ve kuru bir kaba idrar karışmadan toplanmalı ve aynı gün laboratuvara ulaştırılmalıdır, hekim farklı günlerde alınan birkaç örnek isteyebilir', 'Finding oocysts shows that the parasite is present in the sample, while a negative result from one sample does not rule it out, as shedding can be intermittent. Further management is decided by a doctor', 'Nalaz oocista pokazuje prisustvo parazita u uzorku, a negativan nalaz jednog uzorka ga ne isključuje jer izlučivanje nije stalno. Dalji postupak određuje ljekar', 'Налаз ооциста показује присуство паразита у узорку, а негативан налаз једног узорка га не искључује јер излучивање није стално. Даљи поступак одређује љекар', 'Обнаружение ооцист говорит о присутствии паразита в образце, а отрицательный результат одной пробы его не исключает, так как выделение бывает непостоянным. Дальнейшую тактику определяет врач', 'Der Nachweis von Oozysten zeigt den Parasiten in der Probe, ein negatives Ergebnis einer einzelnen Probe schließt ihn nicht aus, da die Ausscheidung schwankt. Das weitere Vorgehen legt der Arzt fest', 'Ookistlerin görülmesi parazitin örnekte bulunduğunu gösterir, tek örneğin negatif olması ise atılım sürekli olmadığı için onu dışlamaz. İzlenecek yolu hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hav-total-antibodies'), 'Blood test for total antibodies to the hepatitis A virus, covering both the IgM and IgG classes', 'Analiza krvi na ukupna antitijela na virus hepatitisa A, koja obuhvataju klase IgM i IgG', 'Анализа крви на укупна антитијела на вирус хепатитиса А, која обухватају класе IgM и IgG', 'Анализ крови на суммарные антитела к вирусу гепатита A, включающие классы IgM и IgG', 'Bluttest auf Gesamtantikörper gegen das Hepatitis-A-Virus, die die Klassen IgM und IgG umfassen', 'Hepatit A virüsüne karşı IgM ve IgG sınıflarını birlikte kapsayan total antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Assessing protection before travel to regions with a high incidence, deciding on vaccination, examination of contacts, clarifying the picture after a previous hepatitis', 'Procjena zaštite prije putovanja u područja sa većom učestalošću bolesti, odluka o vakcinaciji, ispitivanje kontakata, razjašnjenje slike poslije ranije preboljelog hepatitisa', 'Процјена заштите прије путовања у подручја са већом учесталошћу болести, одлука о вакцинацији, испитивање контаката, разјашњење слике послије раније пребољелог хепатитиса', 'Оценка защиты перед поездкой в регионы с высокой заболеваемостью, решение вопроса о вакцинации, обследование контактных лиц, уточнение картины при ранее перенесённом гепатите', 'Beurteilung des Schutzes vor Reisen in Gebiete mit hoher Krankheitshäufigkeit, Entscheidung über eine Impfung, Untersuchung von Kontaktpersonen, Klärung des Bildes nach einer früher durchgemachten Hepatitis', 'Hastalığın sık görüldüğü bölgelere seyahat öncesi korunmanın değerlendirilmesi, aşı kararı, temaslıların incelenmesi, daha önce geçirilmiş hepatit sonrası tablonun netleştirilmesi', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'Total antibodies do not separate a recent infection, an old contact and vaccination, a separate IgM test is used for that. The result is assessed by a doctor together with liver function values', 'Ukupna antitijela ne razdvajaju skorašnju infekciju, davnašnji kontakt i vakcinaciju, za to se koristi posebno određivanje IgM. Nalaz procjenjuje ljekar zajedno sa pokazateljima rada jetre', 'Укупна антитијела не раздвајају скорашњу инфекцију, давнашњи контакт и вакцинацију, за то се користи посебно одређивање IgM. Налаз процјењује љекар заједно са показатељима рада јетре', 'Суммарные антитела не разделяют недавнюю инфекцию, давний контакт и прививку, для этого используют отдельное определение IgM. Результат оценивает врач вместе с показателями работы печени', 'Gesamtantikörper trennen eine kürzliche Infektion, einen länger zurückliegenden Kontakt und eine Impfung nicht voneinander, dafür wird IgM gesondert bestimmt. Der Arzt beurteilt den Befund zusammen mit den Leberwerten', 'Total antikorlar yakın zamandaki enfeksiyonu, eski teması ve aşılamayı birbirinden ayırmaz, bunun için ayrıca IgM bakılır. Sonucu hekim karaciğer değerleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'leishmania-igg-igm'), 'Blood test for IgG and IgM class antibodies to the Leishmania parasite, which is transmitted through sandfly bites', 'Analiza krvi na antitijela klasa IgG i IgM na parazita Leishmania, koji se prenosi ubodom papatača', 'Анализа крви на антитијела класа IgG и IgM на паразита Леисхманиа, који се преноси убодом папатача', 'Анализ крови на антитела классов IgG и IgM к паразиту Leishmania, который передаётся через укусы москитов', 'Bluttest auf Antikörper der Klassen IgG und IgM gegen den Parasiten Leishmania, der durch Sandmückenstiche übertragen wird', 'Tatarcık ısırığıyla bulaşan Leishmania parazitine karşı IgG ve IgM sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Prolonged fever of unclear origin, an enlarged spleen and liver, falling blood counts, a skin ulcer that does not heal, a stay in Mediterranean areas where the vector occurs', 'Dugotrajna povišena temperatura nejasnog porijekla, uvećana slezena i jetra, pad krvnih parametara, rana na koži koja ne zarasta, boravak u mediteranskim područjima gdje se javlja prenosilac', 'Дуготрајна повишена температура нејасног поријекла, увећана слезена и јетра, пад крвних параметара, рана на кожи која не зараста, боравак у медитеранским подручјима гдје се јавља преносилац', 'Длительная лихорадка неясного происхождения, увеличение селезёнки и печени, снижение показателей крови, незаживающая язва на коже, пребывание в средиземноморских районах, где встречается переносчик', 'Länger anhaltendes Fieber unklarer Ursache, vergrößerte Milz und Leber, abfallende Blutwerte, ein nicht heilendes Hautgeschwür, Aufenthalt in Mittelmeergebieten mit vorkommendem Überträger', 'Nedeni belirsiz uzun süreli ateş, dalak ve karaciğer büyümesi, kan değerlerinde düşme, iyileşmeyen cilt yarası, taşıyıcının bulunduğu Akdeniz bölgelerinde bulunma', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'Antibodies may reflect contact with the parasite, cross-reactions with other parasitic infections are possible, and with weakened immunity antibodies may not be produced at all. The result is assessed by a doctor together with the clinical picture and additional tests', 'Antitijela mogu odražavati kontakt sa parazitom, moguće su unakrsne reakcije sa drugim parazitarnim infekcijama, a kod oslabljenog imuniteta antitijela se mogu i ne stvoriti. Nalaz procjenjuje ljekar uz kliničku sliku i dopunska ispitivanja', 'Антитијела могу одражавати контакт са паразитом, могуће су унакрсне реакције са другим паразитарним инфекцијама, а код ослабљеног имунитета антитијела се могу и не створити. Налаз процјењује љекар уз клиничку слику и допунска испитивања', 'Антитела могут отражать контакт с паразитом, возможны перекрёстные реакции с другими паразитарными инфекциями, а при ослабленном иммунитете антитела могут и не вырабатываться. Результат оценивает врач вместе с картиной болезни и дополнительными исследованиями', 'Antikörper können einen Kontakt mit dem Parasiten widerspiegeln, Kreuzreaktionen mit anderen Parasitosen sind möglich, und bei geschwächtem Immunsystem werden mitunter keine Antikörper gebildet. Der Arzt beurteilt den Befund zusammen mit dem Krankheitsbild und weiteren Untersuchungen', 'Antikorlar parazitle teması yansıtabilir, diğer parazit enfeksiyonlarıyla çapraz reaksiyon görülebilir, bağışıklığı zayıf kişilerde ise antikor hiç oluşmayabilir. Sonucu hekim klinik tablo ve ek incelemelerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'microbial-antigen-detection-by-direct-immunofluorescence'), 'Laboratory method that looks for microbial antigens directly in the collected sample using labelled antibodies', 'Laboratorijska metoda kojom se antigeni mikroorganizma traže direktno u uzetom materijalu pomoću obilježenih antitijela', 'Лабораторијска метода којом се антигени микроорганизма траже директно у узетом материјалу помоћу обиљежених антитијела', 'Лабораторный метод, которым прямо в исследуемом материале ищут антигены микроорганизма с помощью меченых антител', 'Labormethode, bei der mikrobielle Antigene mit markierten Antikörpern direkt im entnommenen Material gesucht werden', 'Mikroorganizma antijenlerini işaretli antikorlarla doğrudan alınan örnekte arayan laboratuvar yöntemi', 'A smear or scraping is placed on a slide, treated with labelled antibodies and examined under a fluorescence microscope, collecting the sample itself takes a few minutes', 'Bris ili strugotina se nanosi na pločicu, obrađuje obilježenim antitijelima i pregleda pod fluorescentnim mikroskopom, samo uzimanje materijala traje nekoliko minuta', 'Брис или струготина се наноси на плочицу, обрађује обиљеженим антитијелима и прегледа под флуоресцентним микроскопом, само узимање материјала траје неколико минута', 'Мазок или соскоб наносят на стекло, обрабатывают мечеными антителами и рассматривают под флуоресцентным микроскопом, само взятие материала занимает несколько минут', 'Ein Abstrich oder Geschabsel wird auf einen Objektträger gebracht, mit markierten Antikörpern behandelt und unter dem Fluoreszenzmikroskop betrachtet, die Materialentnahme selbst dauert einige Minuten', 'Sürüntü veya kazıntı lam üzerine yayılır, işaretli antikorlarla işlenir ve floresan mikroskopta incelenir, örnek alma işlemi birkaç dakika sürer', 'Acute respiratory, eye and intestinal infections when a quick answer about the pathogen is needed, examination of smears and scrapings as directed by a doctor, an addition to culture and molecular tests', 'Akutne respiratorne, očne i crijevne infekcije kada je potreban brz odgovor o uzročniku, pregled briseva i struganja po uputu ljekara, dopuna kulturi i molekularnim testovima', 'Акутне респираторне, очне и цријевне инфекције када је потребан брз одговор о узрочнику, преглед брисева и стругања по упуту љекара, допуна култури и молекуларним тестовима', 'Острые респираторные, глазные и кишечные инфекции, когда нужен быстрый ответ о возбудителе, исследование мазков и соскобов по направлению врача, дополнение к посеву и молекулярным тестам', 'Akute Atemwegs-, Augen- und Darminfektionen mit Bedarf an einer schnellen Erregerangabe, Untersuchung von Abstrichen und Geschabseln auf ärztliche Anweisung, Ergänzung zu Kultur und molekularen Tests', 'Etkenin hızlı belirlenmesi gereken akut solunum, göz ve bağırsak enfeksiyonları, hekim yönlendirmesiyle sürüntü ve kazıntı incelemesi, kültür ve moleküler testlere ek olarak', 'Preparation depends on the material: a nasopharyngeal swab is taken before rinsing the nose or using sprays, other conditions are explained at the laboratory', 'Priprema zavisi od materijala: bris iz nazofarinksa uzima se prije ispiranja nosa i upotrebe sprejeva, ostale uslove objašnjavaju u laboratoriji', 'Припрема зависи од материјала: брис из назофаринкса узима се прије испирања носа и употребе спрејева, остале услове објашњавају у лабораторији', 'Подготовка зависит от материала: мазок из носоглотки берут до промывания носа и использования спреев, остальные условия объясняют в лаборатории', 'Die Vorbereitung hängt vom Material ab: Ein Abstrich aus dem Nasenrachenraum wird vor Nasenspülungen und der Anwendung von Sprays entnommen, weitere Bedingungen erklärt das Labor', 'Hazırlık örneğe göre değişir: nazofarengeal sürüntü burun yıkama ve sprey kullanımından önce alınır, diğer koşullar laboratuvarda anlatılır', 'Detection of the antigen shows that the pathogen is present in the examined material, while a negative result does not rule out infection, especially if the sample was taken late or contains few cells. The conclusion is drawn by a doctor', 'Nalaz antigena pokazuje prisustvo uzročnika u pregledanom materijalu, dok negativan nalaz ne isključuje infekciju, naročito ako je materijal uzet kasno ili sadrži malo ćelija. Zaključak donosi ljekar', 'Налаз антигена показује присуство узрочника у прегледаном материјалу, док негативан налаз не искључује инфекцију, нарочито ако је материјал узет касно или садржи мало ћелија. Закључак доноси љекар', 'Обнаружение антигена говорит о присутствии возбудителя в исследованном материале, а отрицательный результат инфекцию не исключает, особенно если материал взят поздно или содержит мало клеток. Заключение делает врач', 'Der Nachweis des Antigens zeigt den Erreger im untersuchten Material, ein negativer Befund schließt eine Infektion nicht aus, besonders bei später Entnahme oder zellarmem Material. Die Beurteilung nimmt der Arzt vor', 'Antijenin saptanması etkenin incelenen örnekte bulunduğunu gösterir, negatif sonuç ise özellikle örnek geç alındıysa veya az hücre içeriyorsa enfeksiyonu dışlamaz. Değerlendirmeyi hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'microscopic-examination-for-treponema-pallidum'), 'Search for Treponema pallidum under the microscope in material from an altered area of skin or mucosa', 'Traženje blijede treponeme pod mikroskopom u materijalu sa promijenjenog mjesta na koži ili sluznici', 'Тражење блиједе трепонеме под микроскопом у материјалу са промијењеног мјеста на кожи или слузници', 'Поиск бледной трепонемы под микроскопом в материале с изменённого участка кожи или слизистой', 'Suche nach Treponema pallidum unter dem Mikroskop in Material aus einem veränderten Haut- oder Schleimhautbereich', 'Deri veya mukozadaki değişmiş bölgeden alınan örnekte mikroskop altında Treponema pallidum aranması', 'The doctor collects discharge from the surface of the lesion, and the preparation is examined under a microscope straight away using a special illumination mode', 'Ljekar uzima sekret sa površine promjene, a preparat se odmah pregleda pod mikroskopom u posebnom režimu osvjetljenja', 'Љекар узима секрет са површине промјене, а препарат се одмах прегледа под микроскопом у посебном режиму освјетљења', 'Врач берёт отделяемое с поверхности элемента, препарат сразу смотрят под микроскопом в специальном режиме освещения', 'Der Arzt entnimmt Sekret von der Oberfläche der Veränderung, das Präparat wird sofort unter dem Mikroskop in einer besonderen Beleuchtungsart betrachtet', 'Hekim lezyonun yüzeyinden akıntı alır, preparat özel bir aydınlatma düzeninde hemen mikroskopta incelenir', 'Examination of an ulcer or another lesion on skin or mucosa as directed by a doctor, early stages when blood antibodies may not yet be detectable, an addition to blood tests', 'Pregled ranice ili druge promjene na koži i sluznici po uputu ljekara, rani period kada se antitijela u krvi još ne moraju otkriti, dopuna analizama krvi', 'Преглед ранице или друге промјене на кожи и слузници по упуту љекара, рани период када се антитијела у крви још не морају открити, допуна анализама крви', 'Обследование язвочки или другого элемента на коже и слизистой по направлению врача, ранние сроки, когда антитела в крови ещё могут не определяться, дополнение к анализам крови', 'Untersuchung eines Geschwürs oder einer anderen Veränderung an Haut und Schleimhaut auf ärztliche Anweisung, frühe Phase, in der Antikörper im Blut noch fehlen können, Ergänzung zu Blutuntersuchungen', 'Hekim yönlendirmesiyle deri ve mukozadaki yara ya da diğer değişikliklerin incelenmesi, kanda antikorların henüz saptanamayabildiği erken dönem, kan testlerine ek olarak', 'The area is not treated with antiseptics or ointments before sampling, and the use of antibacterial medicines is agreed with the doctor', 'Prije uzimanja materijala mjesto se ne tretira antisepticima i mastima, a uzimanje antibakterijskih lijekova se dogovara sa ljekarom', 'Прије узимања материјала мјесто се не третира антисептицима и мастима, а узимање антибактеријских лијекова се договара са љекаром', 'Перед взятием материала участок не обрабатывают антисептиками и мазями, приём антибактериальных препаратов согласуют с врачом', 'Vor der Entnahme wird die Stelle nicht mit Antiseptika oder Salben behandelt, die Einnahme antibakterieller Medikamente wird mit dem Arzt abgestimmt', 'Örnek alınmadan önce bölgeye antiseptik ve merhem uygulanmaz, antibakteriyel ilaç kullanımı hekimle görüşülür', 'The microscopy result is assessed only together with blood tests: a negative result does not rule out infection, and the informative value depends on how and when the material was taken. The conclusion and further work-up are determined by a doctor', 'Nalaz mikroskopije se procjenjuje samo uz analize krvi: negativan nalaz ne isključuje infekciju, a pouzdanost zavisi od toga kako je i kada materijal uzet. Zaključak i dalje ispitivanje određuje ljekar', 'Налаз микроскопије се процјењује само уз анализе крви: негативан налаз не искључује инфекцију, а поузданост зависи од тога како је и када материјал узет. Закључак и даље испитивање одређује љекар', 'Результат микроскопии оценивают только вместе с анализами крови: отрицательный результат инфекцию не исключает, а информативность зависит от того, как и когда взят материал. Заключение и дальнейшее обследование определяет врач', 'Der mikroskopische Befund wird nur zusammen mit Blutuntersuchungen bewertet: Ein negatives Ergebnis schließt eine Infektion nicht aus, und die Aussagekraft hängt davon ab, wie und wann das Material entnommen wurde. Beurteilung und weitere Abklärung legt der Arzt fest', 'Mikroskopi sonucu yalnızca kan testleriyle birlikte değerlendirilir: negatif sonuç enfeksiyonu dışlamaz ve incelemenin güvenilirliği örneğin nasıl ve ne zaman alındığına bağlıdır. Sonucu ve ileri incelemeyi hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'monosticon'), 'Rapid blood test for heterophile antibodies that appear in infectious mononucleosis', 'Brzi test krvi na heterofilna antitijela koja se javljaju kod infektivne mononukleoze', 'Брзи тест крви на хетерофилна антитијела која се јављају код инфективне мононуклеозе', 'Быстрый тест крови на гетерофильные антитела, которые появляются при инфекционном мононуклеозе', 'Blutschnelltest auf heterophile Antikörper, die bei einer infektiösen Mononukleose auftreten', 'Enfeksiyöz mononükleozda ortaya çıkan heterofil antikorları arayan hızlı kan testi', 'A drop of blood or serum is mixed with a reagent on a card and checked for clumping, the answer is read within a few minutes', 'Kap krvi ili seruma miješa se sa reagensom na pločici i prati se da li dolazi do stvaranja grudvica, odgovor se očitava za nekoliko minuta', 'Кап крви или серума мијеша се са реагенсом на плочици и прати се да ли долази до стварања грудвица, одговор се очитава за неколико минута', 'Каплю крови или сыворотки смешивают с реагентом на пластинке и смотрят, образуются ли хлопья, ответ читают в течение нескольких минут', 'Ein Tropfen Blut oder Serum wird auf einer Testkarte mit einem Reagenz vermischt und auf Verklumpung geprüft, das Ergebnis wird innerhalb weniger Minuten abgelesen', 'Bir damla kan veya serum kart üzerinde reaktifle karıştırılır ve topaklanma olup olmadığına bakılır, yanıt birkaç dakika içinde okunur', 'Prolonged tonsillitis with fever, enlarged lymph nodes, marked weakness in a teenager or young adult, clarifying the cause of a sore throat together with a complete blood count', 'Dugotrajna angina sa temperaturom, uvećani limfni čvorovi, izražena slabost kod tinejdžera ili mlade odrasle osobe, razjašnjenje uzroka angine uz kompletnu krvnu sliku', 'Дуготрајна ангина са температуром, увећани лимфни чворови, изражена слабост код тинејџера или младе одрасле особе, разјашњење узрока ангине уз комплетну крвну слику', 'Затяжная ангина с температурой, увеличение лимфоузлов, выраженная слабость у подростка или молодого взрослого, уточнение причины ангины вместе с общим анализом крови', 'Länger anhaltende Angina mit Fieber, vergrößerte Lymphknoten, ausgeprägte Schwäche bei Jugendlichen oder jungen Erwachsenen, Klärung der Ursache einer Angina zusammen mit dem Blutbild', 'Ateşle seyreden uzamış bademcik iltihabı, lenf bezlerinde büyüme, ergen veya genç erişkinde belirgin halsizlik, tam kan sayımıyla birlikte boğaz enfeksiyonunun nedeninin araştırılması', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'The test can be negative in the first days of illness and in young children, and a reaction also occurs in some other conditions. The result is assessed by a doctor together with the blood count and Epstein-Barr virus antibodies', 'Test može biti negativan prvih dana bolesti i kod male djece, a reakcija se javlja i kod nekih drugih stanja. Nalaz procjenjuje ljekar uz kompletnu krvnu sliku i antitijela na Epstein-Barr virus', 'Тест може бити негативан првих дана болести и код мале дјеце, а реакција се јавља и код неких других стања. Налаз процјењује љекар уз комплетну крвну слику и антитијела на Epstein-Barr вирус', 'Тест может быть отрицательным в первые дни болезни и у маленьких детей, а реакция встречается и при некоторых других состояниях. Результат оценивает врач вместе с общим анализом крови и антителами к вирусу Эпштейна-Барр', 'Der Test kann in den ersten Krankheitstagen und bei kleinen Kindern negativ ausfallen, eine Reaktion kommt auch bei einigen anderen Zuständen vor. Der Arzt beurteilt das Ergebnis zusammen mit dem Blutbild und den Antikörpern gegen das Epstein-Barr-Virus', 'Test hastalığın ilk günlerinde ve küçük çocuklarda negatif çıkabilir, bazı başka durumlarda da reaksiyon görülebilir. Sonucu hekim tam kan sayımı ve Epstein-Barr virüsü antikorlarıyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mycoplasma-pneumoniae-iga'), 'Blood test for IgA class antibodies to Mycoplasma pneumoniae, one of the causes of atypical pneumonia', 'Analiza krvi na antitijela klase IgA na bakteriju Mycoplasma pneumoniae, jedan od uzroka atipične upale pluća', 'Анализа крви на антитијела класе IgA на бактерију Мyцопласма пнеумониае, један од узрока атипичне упале плућа', 'Анализ крови на антитела класса IgA к бактерии Mycoplasma pneumoniae, одной из причин атипичной пневмонии', 'Bluttest auf Antikörper der Klasse IgA gegen Mycoplasma pneumoniae, einen der Erreger atypischer Lungenentzündungen', 'Atipik zatürrenin nedenlerinden biri olan Mycoplasma pneumoniae bakterisine karşı IgA sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'A lingering dry cough, pneumonia without a typical picture, respiratory illness in schoolchildren and in closed communities, additional work-up together with antibodies of other classes', 'Dugotrajan suv kašalj, upala pluća bez tipične slike, respiratorna oboljenja kod školske djece i u zatvorenim kolektivima, dopunsko ispitivanje uz antitijela drugih klasa', 'Дуготрајан сув кашаљ, упала плућа без типичне слике, респираторна обољења код школске дјеце и у затвореним колективима, допунско испитивање уз антитијела других класа', 'Затяжной сухой кашель, пневмония без типичной картины, респираторные заболевания у школьников и в закрытых коллективах, дообследование вместе с антителами других классов', 'Anhaltender trockener Husten, Lungenentzündung ohne typisches Bild, Atemwegserkrankungen bei Schulkindern und in Gemeinschaftseinrichtungen, ergänzende Abklärung zusammen mit Antikörpern anderer Klassen', 'Uzun süren kuru öksürük, tipik olmayan seyirde zatürre, okul çağı çocuklarında ve toplu yaşanan ortamlarda solunum yolu hastalıkları, diğer antikor sınıflarıyla birlikte ileri inceleme', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'IgA is more often linked to a current or recent infection, but a single sample does not show when the infection occurred, and in some people antibodies persist for a long time. The result is assessed by a doctor together with other antibody classes, the examination and the chest X-ray', 'IgA su češće vezani za aktuelnu ili skorašnju infekciju, ali se iz jednog uzorka ne može odrediti kada je infekcija nastala, a kod dijela ljudi antitijela ostaju dugo. Nalaz procjenjuje ljekar uz antitijela drugih klasa, pregled i snimak pluća', 'IgA су чешће везани за актуелну или скорашњу инфекцију, али се из једног узорка не може одредити када је инфекција настала, а код дијела људи антитијела остају дуго. Налаз процјењује љекар уз антитијела других класа, преглед и снимак плућа', 'IgA чаще связаны с текущей или недавней инфекцией, но по одному образцу срок заражения не определяется, а у части людей антитела сохраняются долго. Результат оценивает врач вместе с другими классами антител, осмотром и снимком лёгких', 'IgA hängt häufiger mit einer aktuellen oder kürzlichen Infektion zusammen, aus einer einzelnen Probe lässt sich der Zeitpunkt jedoch nicht bestimmen, und bei manchen Menschen bleiben Antikörper lange erhalten. Der Arzt beurteilt den Befund zusammen mit anderen Antikörperklassen, der Untersuchung und dem Röntgenbild der Lunge', 'IgA daha çok güncel veya yakın zamandaki enfeksiyonla ilişkilidir, ancak tek örnekten enfeksiyonun zamanı belirlenemez ve bazı kişilerde antikorlar uzun süre kalır. Sonucu hekim diğer antikor sınıfları, muayene ve akciğer filmiyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'trichinella-spiralis-igg'), 'Blood test for IgG class antibodies to Trichinella, a parasite acquired from insufficiently cooked meat', 'Analiza krvi na antitijela klase IgG na trihinelu, parazita koji se prenosi nedovoljno termički obrađenim mesom', 'Анализа крви на антитијела класе IgG на трихинелу, паразита који се преноси недовољно термички обрађеним месом', 'Анализ крови на антитела класса IgG к трихинелле, паразиту, которым заражаются через недостаточно обработанное мясо', 'Bluttest auf Antikörper der Klasse IgG gegen Trichinellen, Parasiten, die über nicht ausreichend gegartes Fleisch übertragen werden', 'Yeterince pişmemiş etle bulaşan Trichinella parazitine karşı IgG sınıfı antikorları ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert einige Minuten', 'Venöz kan alımı, birkaç dakika sürer', 'Muscle pain and swollen eyelids after eating home-produced pork or game, fever together with raised eosinophils, examination of people who ate the same meat, epidemiological investigation', 'Bolovi u mišićima i otok očnih kapaka poslije domaće svinjetine ili divljači, povišena temperatura uz porast eozinofila, ispitivanje osoba koje su jele isto meso, epidemiološko ispitivanje', 'Болови у мишићима и оток очних капака послије домаће свињетине или дивљачи, повишена температура уз пораст еозинофила, испитивање особа које су јеле исто месо, епидемиолошко испитивање', 'Мышечные боли и отёк век после употребления домашней свинины или дичи, температура с повышением эозинофилов, обследование людей, евших то же мясо, эпидемиологическое обследование', 'Muskelschmerzen und geschwollene Augenlider nach dem Verzehr von hausgeschlachtetem Schweinefleisch oder Wild, Fieber mit erhöhten Eosinophilen, Untersuchung von Personen, die dasselbe Fleisch gegessen haben, epidemiologische Abklärung', 'Ev usulü domuz eti veya av eti sonrası kas ağrıları ve göz kapağı şişmesi, eozinofil artışıyla birlikte ateş, aynı eti yiyen kişilerin incelenmesi, salgın araştırması', 'No special preparation is required', 'Posebna priprema nije potrebna', 'Посебна припрема није потребна', 'Специальной подготовки не требуется', 'Keine besondere Vorbereitung erforderlich', 'Özel bir hazırlık gerekmez', 'Antibodies do not appear immediately, so in the first weeks of illness the result may be negative and the doctor sometimes orders a repeat test. The result is assessed together with the symptoms and other blood values', 'Antitijela se ne javljaju odmah, pa u prvim nedjeljama bolesti nalaz može biti negativan i ljekar ponekad traži ponovljenu analizu. Nalaz se procjenjuje uz tegobe i ostale parametre krvi', 'Антитијела се не јављају одмах, па у првим недјељама болести налаз може бити негативан и љекар понекад тражи поновљену анализу. Налаз се процјењује уз тегобе и остале параметре крви', 'Антитела появляются не сразу, поэтому в первые недели болезни результат может быть отрицательным и врач иногда назначает повторный анализ. Результат оценивают вместе с жалобами и другими показателями крови', 'Antikörper treten nicht sofort auf, daher kann der Befund in den ersten Krankheitswochen negativ sein und der Arzt ordnet mitunter eine Kontrolle an. Die Beurteilung erfolgt zusammen mit den Beschwerden und weiteren Blutwerten', 'Antikorlar hemen oluşmaz, bu nedenle hastalığın ilk haftalarında sonuç negatif çıkabilir ve hekim testi tekrarlatabilir. Sonuç şikayetler ve diğer kan değerleriyle birlikte değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ureaplasma-parvum-pcr'), 'Molecular test that detects the DNA of Ureaplasma parvum, one of the two ureaplasma species', 'Molekularni test koji otkriva DNK bakterije Ureaplasma parvum, jedne od dvije vrste ureaplazme', 'Молекуларни тест који открива ДНК бактерије Уреапласма парвум, једне од двије врсте уреаплазме', 'Молекулярный тест, выявляющий ДНК Ureaplasma parvum, одного из двух видов уреаплазмы', 'Molekularer Test, der die DNA von Ureaplasma parvum nachweist, einer der beiden Ureaplasmen-Arten', 'İki ureaplazma türünden biri olan Ureaplasma parvum bakterisinin DNA''sını saptayan moleküler test', 'A swab is taken from the urethra or cervical canal, in men the first portion of urine is sometimes used, and the DNA is sought by PCR', 'Uzima se bris iz uretre ili cervikalnog kanala, kod muškaraca se ponekad ispituje prvi mlaz mokraće, a DNK se traži PCR metodom', 'Узима се брис из уретре или цервикалног канала, код мушкараца се понекад испитује први млаз мокраће, а ДНК се тражи ПЦР методом', 'Берут мазок из уретры или цервикального канала, у мужчин иногда исследуют первую порцию мочи, ДНК ищут методом ПЦР', 'Es wird ein Abstrich aus Harnröhre oder Gebärmutterhalskanal entnommen, bei Männern manchmal die erste Urinportion untersucht, die DNA wird mittels PCR gesucht', 'Üretradan veya servikal kanaldan sürüntü alınır, erkeklerde bazen ilk idrar örneği incelenir, DNA PCR yöntemiyle aranır', 'Inflammatory complaints of the urinary and genital tract, identifying the ureaplasma species after a general test, examination of a couple planning a pregnancy, follow-up as prescribed by a doctor', 'Zapaljenske tegobe mokraćnih i polnih puteva, određivanje vrste ureaplazme poslije opšteg testa, ispitivanje para pri planiranju trudnoće, kontrola po nalogu ljekara', 'Запаљенске тегобе мокраћних и полних путева, одређивање врсте уреаплазме послије општег теста, испитивање пара при планирању трудноће, контрола по налогу љекара', 'Воспалительные жалобы со стороны мочеполовых путей, уточнение вида уреаплазмы после общего теста, обследование пары при планировании беременности, контроль по назначению врача', 'Entzündliche Beschwerden der Harn- und Geschlechtswege, Bestimmung der Ureaplasmen-Art nach einem allgemeinen Test, Untersuchung eines Paares bei Kinderwunsch, Kontrolle auf ärztliche Anordnung', 'İdrar ve genital yolla ilgili iltihabi şikayetler, genel testten sonra ureaplazma türünün belirlenmesi, gebelik planlayan çiftin incelenmesi, hekim isteğiyle kontrol', 'The sample is taken no sooner than 2–3 hours after the last urination, for women the test is scheduled outside menstruation, and the interval after antibacterial therapy is set by the doctor', 'Materijal se uzima najranije 2–3 sata poslije posljednjeg mokrenja, kod žena se ispitivanje planira van menstruacije, a rok poslije antibakterijske terapije određuje ljekar', 'Материјал се узима најраније 2–3 сата послије посљедњег мокрења, код жена се испитивање планира ван менструације, а рок послије антибактеријске терапије одређује љекар', 'Материал берут не раньше чем через 2–3 часа после последнего мочеиспускания, у женщин исследование планируют вне менструации, а сроки после антибактериальной терапии определяет врач', 'Die Probe wird frühestens 2–3 Stunden nach dem letzten Wasserlassen entnommen, bei Frauen wird die Untersuchung außerhalb der Menstruation geplant, den Abstand zu einer antibakteriellen Therapie legt der Arzt fest', 'Örnek son idrardan en erken 2–3 saat sonra alınır, kadınlarda inceleme adet dönemi dışında planlanır, antibakteriyel tedaviden sonraki süreyi hekim belirler', 'Ureaplasma parvum is often found in people without complaints, so detecting its DNA does not by itself mean disease. Whether treatment and examination of the partner are needed is decided by a doctor from the symptoms and the other test results', 'Ureaplasma parvum se često nalazi i kod osoba bez tegoba, pa nalaz DNK sam po sebi ne znači bolest. Da li je potrebno liječenje i ispitivanje partnera, ljekar odlučuje prema simptomima i ostalim analizama', 'Уреапласма парвум се често налази и код особа без тегоба, па налаз ДНК сам по себи не значи болест. Да ли је потребно лијечење и испитивање партнера, љекар одлучује према симптомима и осталим анализама', 'Ureaplasma parvum часто находят и у людей без жалоб, поэтому обнаружение ДНК само по себе не означает болезнь. Нужно ли лечение и обследование партнёра, врач решает по симптомам и остальным анализам', 'Ureaplasma parvum wird häufig auch bei Beschwerdefreien gefunden, der Nachweis der DNA bedeutet daher für sich genommen keine Erkrankung. Ob eine Behandlung und eine Partneruntersuchung nötig sind, entscheidet der Arzt anhand der Beschwerden und der übrigen Befunde', 'Ureaplasma parvum şikayeti olmayan kişilerde de sık bulunur, bu nedenle DNA saptanması tek başına hastalık anlamına gelmez. Tedavi ve partner incelemesi gerekip gerekmediğine hekim belirtilere ve diğer sonuçlara göre karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vibrio-cholerae-culture'), 'Bacteriological culture of the sample for the cholera vibrio Vibrio cholerae', 'Bakteriološka kultura materijala na uzročnika kolere Vibrio cholerae', 'Бактериолошка култура материјала на узрочника колере Вибрио цхолерае', 'Бактериологический посев материала на холерный вибрион Vibrio cholerae', 'Bakteriologische Kultur des Materials auf den Choleraerreger Vibrio cholerae', 'Kolera etkeni Vibrio cholerae için yapılan bakteriyolojik kültür', 'Stool or a rectal swab is plated on special alkaline media and the colonies that grow are identified, the examination takes several days', 'Stolica ili rektalni bris zasijavaju se na posebne alkalne podloge, a izrasle kolonije se identifikuju, ispitivanje traje nekoliko dana', 'Столица или ректални брис засијавају се на посебне алкалне подлоге, а израсле колоније се идентификују, испитивање траје неколико дана', 'Кал или ректальный мазок засевают на специальные щелочные среды, выросшие колонии определяют, исследование занимает несколько дней', 'Stuhl oder ein Rektalabstrich wird auf speziellen alkalischen Nährböden angezüchtet und die gewachsenen Kolonien werden identifiziert, die Untersuchung dauert mehrere Tage', 'Dışkı veya rektal sürüntü özel alkali besiyerlerine ekilir ve üreyen koloniler tanımlanır, inceleme birkaç gün sürer', 'Profuse watery diarrhoea, bowel complaints after returning from regions where cholera occurs, testing on epidemiological grounds, examination of contacts', 'Obilan vodenasti proliv, crijevne tegobe poslije povratka iz krajeva gdje se javlja kolera, ispitivanje po epidemiološkim indikacijama, ispitivanje kontakata', 'Обилан воденасти пролив, цријевне тегобе послије повратка из крајева гдје се јавља колера, испитивање по епидемиолошким индикацијама, испитивање контаката', 'Обильная водянистая диарея, кишечные жалобы после возвращения из регионов, где встречается холера, обследование по эпидемиологическим показаниям, обследование контактных лиц', 'Reichlicher wässriger Durchfall, Darmbeschwerden nach der Rückkehr aus Gebieten mit Cholera, Untersuchung aus epidemiologischen Gründen, Untersuchung von Kontaktpersonen', 'Bol sulu ishal, koleranın görüldüğü bölgelerden dönüş sonrası bağırsak şikayetleri, salgın gerekçesiyle inceleme, temaslıların incelenmesi', 'Collect the material in the container or transport medium issued by the laboratory, where possible before antibacterial therapy is started, and deliver it as quickly as possible', 'Materijal se sakuplja u posudu ili transportnu podlogu iz laboratorije, po mogućnosti prije početka antibakterijske terapije, i dostavlja se što prije', 'Материјал се сакупља у посуду или транспортну подлогу из лабораторије, по могућности прије почетка антибактеријске терапије, и доставља се што прије', 'Материал собирают в контейнер или транспортную среду, выданные лабораторией, по возможности до начала антибактериальной терапии, и доставляют как можно быстрее', 'Das Material wird im Behälter oder Transportmedium aus dem Labor gesammelt, möglichst vor Beginn einer antibakteriellen Therapie, und so schnell wie möglich abgegeben', 'Örnek laboratuvardan alınan kaba veya taşıma besiyerine, mümkünse antibakteriyel tedaviye başlamadan önce toplanmalı ve en kısa sürede ulaştırılmalıdır', 'An isolate grown in the culture is confirmed with additional tests, and if complaints persist despite a negative result the doctor may order a repeat examination. Further steps are decided by a doctor', 'Izolovani uzročnik se potvrđuje dopunskim testovima, a ako tegobe traju uz negativan nalaz, ljekar može tražiti ponovljeno ispitivanje. Dalje korake određuje ljekar', 'Изоловани узрочник се потврђује допунским тестовима, а ако тегобе трају уз негативан налаз, љекар може тражити поновљено испитивање. Даље кораке одређује љекар', 'Выделение возбудителя в посеве подтверждают дополнительными тестами, а при сохраняющихся жалобах и отрицательном результате врач может назначить повторное исследование. Дальнейшие шаги определяет врач', 'Ein in der Kultur gewonnener Erreger wird mit zusätzlichen Tests bestätigt, und bei anhaltenden Beschwerden trotz negativem Befund kann der Arzt eine Wiederholung anordnen. Die weiteren Schritte legt der Arzt fest', 'Kültürde üreyen etken ek testlerle doğrulanır, sonuç negatif olduğu hâlde şikayetler sürüyorsa hekim incelemenin tekrarını isteyebilir. Sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'left-eye-swab'), 'Collection of material from the conjunctiva of the left eye for microbiological culture', 'Uzimanje materijala sa konjunktive lijevog oka za mikrobiološku kulturu', 'Узимање материјала са коњунктиве лијевог ока за микробиолошку културу', 'Взятие материала с конъюнктивы левого глаза для микробиологического посева', 'Entnahme von Material von der Bindehaut des linken Auges für eine mikrobiologische Kultur', 'Sol gözün konjonktivasından mikrobiyolojik kültür için örnek alınması', 'A sterile swab is taken from the lower conjunctival sac of the left eye and placed in transport medium; if both eyes are inflamed, the samples are taken separately', 'Sterilnim štapićem uzima se bris iz donjeg konjunktivalnog svoda lijevog oka i stavlja u transportnu podlogu, a kod upale oba oka uzorci se uzimaju odvojeno', 'Стерилним штапићем узима се брис из доњег коњунктивалног свода лијевог ока и ставља у транспортну подлогу, а код упале оба ока узорци се узимају одвојено', 'Материал берут стерильным тампоном из нижнего конъюнктивального свода левого глаза и помещают в транспортную среду, при воспалении обоих глаз пробы берут раздельно', 'Mit einem sterilen Tupfer wird Material aus dem unteren Bindehautsack des linken Auges entnommen und in ein Transportmedium gegeben; bei Entzündung beider Augen werden die Proben getrennt entnommen', 'Steril eküvyonla sol gözün alt konjonktiva kesesinden örnek alınır ve taşıma besiyerine konur, iki göz de iltihaplıysa örnekler ayrı ayrı alınır', 'Purulent discharge and stuck eyelashes on the left, inflammation of the eyelid and the lacrimal sac, conjunctivitis lasting longer than usual, work-up before eye surgery', 'Gnojni sekret i slijepljene trepavice lijevo, upala kapka i suzne vreće, konjunktivitis koji traje duže nego obično, obrada prije operacije oka', 'Гнојни секрет и слијепљене трепавице лијево, упала капка и сузне вреће, коњунктивитис који траје дуже него обично, обрада прије операције ока', 'Гнойное отделяемое и слипание ресниц слева, воспаление века и слёзного мешка, конъюнктивит, затянувшийся дольше обычного, обследование перед операцией на глазу', 'Eitriges Sekret und verklebte Wimpern links, Entzündung des Lids und des Tränensacks, länger als üblich anhaltende Bindehautentzündung, Abklärung vor einer Augenoperation', 'Solda iltihaplı akıntı ve kirpiklerin yapışması, göz kapağı ve gözyaşı kesesi iltihabı, olağandan uzun süren konjonktivit, göz ameliyatı öncesi değerlendirme', 'In the morning before washing and before instilling drops, without make-up on the lids; remove lenses in advance and tell the doctor which drops have been used', 'Ujutru prije umivanja i prije ukapavanja kapi, bez šminke na kapcima; sočiva izvaditi ranije, a ljekaru reći koje su kapi korišćene', 'Ујутру прије умивања и прије укапавања капи, без шминке на капцима; сочива извадити раније, а љекару рећи које су капи коришћене', 'Утром до умывания и закапывания капель, без косметики на веках; линзы снять заранее, о применяемых каплях сказать врачу', 'Morgens vor dem Waschen und vor dem Eintropfen, ohne Make-up auf den Lidern; Kontaktlinsen vorher herausnehmen und dem Arzt sagen, welche Tropfen angewendet wurden', 'Sabah yüz yıkamadan ve damla damlatmadan önce, kapaklarda makyaj olmadan; lensler önceden çıkarılmalı, kullanılan damlalar hekime söylenmelidir', 'The bacteria isolated may be the cause of the inflammation or ordinary flora of the lid margin, and the amount of growth together with the examination helps tell them apart. The ophthalmologist interprets the result and the antibiogram', 'Izolovane bakterije mogu biti uzročnik upale ili uobičajena flora ivice kapka, a razlikuju se po količini porasta i po nalazu pregleda. Nalaz i antibiogram tumači oftalmolog', 'Изоловане бактерије могу бити узрочник упале или уобичајена флора ивице капка, а разликују се по количини пораста и по налазу прегледа. Налаз и антибиограм тумачи офталмолог', 'Выделенные бактерии могут относиться к возбудителю воспаления или к обычной флоре края века, различие делают по количеству роста и картине осмотра. Результат и антибиотикограмму трактует офтальмолог', 'Die nachgewiesenen Bakterien können Erreger der Entzündung oder normale Flora des Lidrands sein, wobei Menge des Wachstums und Untersuchungsbefund bei der Unterscheidung helfen. Befund und Antibiogramm beurteilt der Augenarzt', 'Üreyen bakteriler iltihabın etkeni olabileceği gibi kapak kenarının olağan florası da olabilir, ayrımda üreme miktarı ve muayene bulgusu yardımcı olur. Sonucu ve antibiyogramı göz hekimi yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'left-eye-swab-fungi'), 'Examination of discharge from the conjunctiva of the left eye for yeasts and moulds', 'Ispitivanje sekreta konjunktive lijevog oka na kvasnice i plijesni', 'Испитивање секрета коњунктиве лијевог ока на кваснице и плијесни', 'Исследование отделяемого конъюнктивы левого глаза на дрожжевые и плесневые грибы', 'Untersuchung des Bindehautsekrets des linken Auges auf Hefen und Schimmelpilze', 'Sol göz konjonktiva akıntısının maya ve küf mantarları yönünden incelenmesi', 'A sterile swab collects material from the lower conjunctival sac of the left eye, which is examined under the microscope and plated on fungal medium, with growth followed longer than in a bacterial culture', 'Sterilnim štapićem uzima se materijal iz donjeg svoda konjunktive lijevog oka, gleda se pod mikroskopom i zasijava na podlogu za gljivice, a porast se prati duže nego kod bakteriološke kulture', 'Стерилним штапићем узима се материјал из доњег свода коњунктиве лијевог ока, гледа се под микроскопом и засијава на подлогу за гљивице, а пораст се прати дуже него код бактериолошке културе', 'Стерильным тампоном берут материал из нижнего свода конъюнктивы левого глаза, его смотрят под микроскопом и засевают на среду для грибов, рост оценивают дольше, чем при бактериальном посеве', 'Mit einem sterilen Tupfer wird Material aus dem unteren Bindehautsack des linken Auges entnommen, mikroskopiert und auf Pilznährboden ausgestrichen, wobei das Wachstum länger beobachtet wird als bei einer Bakterienkultur', 'Steril eküvyonla sol gözün alt konjonktiva kesesinden örnek alınır, mikroskopla incelenir ve mantar besiyerine ekilir, üreme bakteri kültürüne göre daha uzun süre izlenir', 'Protracted inflammation of the left eye with no response to antibiotic drops, long use of steroid drops, contact lens wear, eye injury by organic material', 'Dugotrajna upala lijevog oka bez odgovora na antibiotske kapi, duža primjena kapi sa kortikosteroidima, nošenje kontaktnih sočiva, povreda oka organskim materijalom', 'Дуготрајна упала лијевог ока без одговора на антибиотске капи, дужа примјена капи са кортикостероидима, ношење контактних сочива, повреда ока органским материјалом', 'Затяжное воспаление левого глаза без ответа на антибактериальные капли, длительное применение капель с гормонами, ношение контактных линз, травма глаза органическим материалом', 'Langwierige Entzündung des linken Auges ohne Ansprechen auf antibiotische Tropfen, längere Anwendung kortisonhaltiger Tropfen, Tragen von Kontaktlinsen, Augenverletzung durch organisches Material', 'Antibiyotikli damlalara yanıt vermeyen uzayan sol göz iltihabı, kortizonlu damlaların uzun süre kullanılması, kontakt lens kullanımı, gözün organik bir cisimle yaralanması', 'Do not use drops or ointments before sampling, do not wash the lids, remove lenses; the ophthalmologist sets the interval after antifungal products', 'Prije uzimanja ne koristiti kapi i masti, kapke ne umivati, sočiva izvaditi; razmak poslije antimikotika određuje oftalmolog', 'Прије узимања не користити капи и масти, капке не умивати, сочива извадити; размак послије антимикотика одређује офталмолог', 'Капли и мази перед забором не применять, веки не умывать, линзы снять; интервал после противогрибковых средств уточняет офтальмолог', 'Vor der Entnahme keine Tropfen und Salben anwenden, die Lider nicht waschen, Kontaktlinsen herausnehmen; den Abstand nach Antimykotika legt der Augenarzt fest', 'Örnek alınmadan önce damla ve merhem kullanılmamalı, kapaklar yıkanmamalı, lensler çıkarılmalıdır; antifungal kullanımından sonraki aralığı göz hekimi belirler', 'A fungal finding may reflect the involvement of fungal flora in the inflammation or superficial contamination of the sample. The ophthalmologist assesses the result together with the examination', 'Nalaz gljivica može značiti učešće gljivične flore u upali ili površinsko zagađenje uzorka. Rezultat zajedno sa pregledom procjenjuje oftalmolog', 'Налаз гљивица може значити учешће гљивичне флоре у упали или површинско загађење узорка. Резултат заједно са прегледом процјењује офталмолог', 'Находка грибов может отражать участие грибковой флоры в воспалении или поверхностное загрязнение пробы. Результат вместе с осмотром оценивает офтальмолог', 'Ein Pilznachweis kann eine Beteiligung von Pilzflora an der Entzündung oder eine oberflächliche Verunreinigung der Probe widerspiegeln. Der Augenarzt beurteilt das Ergebnis zusammen mit dem Untersuchungsbefund', 'Mantar saptanması iltihaba mantar florasının katıldığını gösterebileceği gibi örneğin yüzeysel kirlenmesine de bağlı olabilir. Sonucu muayeneyle birlikte göz hekimi değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'perianal-swab-fungi'), 'Culture of material from the skin around the anus for yeast fungi', 'Kultura materijala sa kože oko čmara na kvasnice', 'Култура материјала са коже око чмара на кваснице', 'Посев материала с кожи вокруг заднего прохода на дрожжевые грибы', 'Kultur von Material der Haut um den After auf Hefepilze', 'Anüs çevresindeki deriden maya mantarları için kültür', 'A sterile swab is passed over the skin folds around the anus, the material is plated on fungal medium and, if growth appears, the genus is identified', 'Sterilnim štapićem prelazi se preko kožnih nabora oko analnog otvora, materijal se zasijava na podlogu za gljivice, a kod porasta se određuje rod uzročnika', 'Стерилним штапићем прелази се преко кожних набора око аналног отвора, материјал се засијава на подлогу за гљивице, а код пораста се одређује род узрочника', 'Стерильным тампоном проводят по кожным складкам вокруг ануса, материал засевают на среду для грибов и при росте определяют род возбудителя', 'Mit einem sterilen Tupfer wird über die Hautfalten um den After gestrichen, das Material auf Pilznährboden ausgestrichen und bei Wachstum die Gattung bestimmt', 'Steril eküvyon anüs çevresindeki deri kıvrımları üzerinde gezdirilir, örnek mantar besiyerine ekilir ve üreme olursa etkenin cinsi belirlenir', 'Persistent redness, moist skin and itching in the perianal folds, nappy rash in children, complaints after a course of antibiotics, skin changes in diabetes and reduced immunity', 'Uporno crvenilo, vlaženje i svrab u perianalnim naborima, pelenski osip kod djece, tegobe poslije terapije antibioticima, promjene kože kod dijabetesa i snižene imunosti', 'Упорно црвенило, влажење и свраб у перианалним наборима, пеленски осип код дјеце, тегобе послије терапије антибиотицима, промјене коже код дијабетеса и снижене имуности', 'Стойкое покраснение, мокнутие и зуд в перианальных складках, опрелости у детей, жалобы после курса антибиотиков, изменения кожи при диабете и сниженном иммунитете', 'Anhaltende Rötung, Nässen und Juckreiz in den Perianalfalten, Windeldermatitis bei Kindern, Beschwerden nach einer Antibiotikatherapie, Hautveränderungen bei Diabetes und geschwächter Abwehr', 'Perianal kıvrımlarda geçmeyen kızarıklık, sulanma ve kaşıntı, çocuklarda pişik, antibiyotik kürü sonrası yakınmalar, diyabette ve bağışıklığı düşük kişilerde deri değişiklikleri', 'The sample is taken before washing; do not use antifungal creams, suppositories or powders the day before', 'Materijal se uzima prije pranja; dan ranije ne koristiti antimikotske kreme, supozitorije i pudere', 'Материјал се узима прије прања; дан раније не користити антимикотске креме, супозиторије и пудере', 'Материал берут до подмывания; накануне не применять противогрибковые кремы, свечи и присыпки', 'Die Probe wird vor dem Waschen entnommen; am Vortag keine Antipilzcremes, Zäpfchen oder Puder anwenden', 'Örnek yıkanmadan önce alınır; bir gün önce antifungal krem, fitil ve pudra kullanılmamalıdır', 'Yeasts are found in this area without inflammation as well, so the finding is compared with the appearance of the skin and the complaints. Whether treatment is needed is decided by a dermatologist or a proctologist', 'Kvasnice se u ovoj regiji nalaze i bez upale, pa se nalaz poredi sa izgledom kože i tegobama. Da li je liječenje potrebno, odlučuje dermatolog ili proktolog', 'Кваснице се у овој регији налазе и без упале, па се налаз пореди са изгледом коже и тегобама. Да ли је лијечење потребно, одлучује дерматолог или проктолог', 'Дрожжевые грибы в этой зоне встречаются и без воспаления, поэтому находку сопоставляют с видом кожи и жалобами. Нужно ли лечение, решает дерматолог или проктолог', 'Hefepilze kommen in dieser Region auch ohne Entzündung vor, daher wird der Befund mit dem Hautbild und den Beschwerden verglichen. Ob eine Behandlung nötig ist, entscheidet der Hautarzt oder der Proktologe', 'Maya mantarları bu bölgede iltihap olmadan da bulunur, bu nedenle sonuç derinin görünümü ve yakınmalarla birlikte değerlendirilir. Tedavi gerekip gerekmediğine dermatolog ya da proktolog karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'punctate-aerobic'), 'Culture of punctate fluid for bacteria that grow in the presence of oxygen', 'Zasijavanje punktata na bakterije koje rastu u prisustvu kiseonika', 'Засијавање пунктата на бактерије које расту у присуству кисеоника', 'Посев пунктата на бактерии, растущие в присутствии кислорода', 'Kultur von Punktat auf Bakterien, die in Gegenwart von Sauerstoff wachsen', 'Ponksiyon sıvısının oksijenli ortamda üreyen bakteriler için kültürü', 'Fluid obtained by puncture is transferred under sterile conditions into a container or transport medium and plated on media incubated in air; anaerobic bacteria are not detected by this culture', 'Tečnost dobijena punkcijom pod sterilnim uslovima prenosi se u posudu ili transportnu podlogu i zasijava na podloge koje se drže na vazduhu; anaerobne bakterije se ovom kulturom ne otkrivaju', 'Течност добијена пункцијом под стерилним условима преноси се у посуду или транспортну подлогу и засијава на подлоге које се држе на ваздуху; анаеробне бактерије се овом културом не откривају', 'Полученную при пункции жидкость в стерильных условиях переносят в контейнер или транспортную среду и засевают на среды, которые выдерживают на воздухе; анаэробные бактерии этим посевом не выявляются', 'Die bei der Punktion gewonnene Flüssigkeit wird unter sterilen Bedingungen in ein Gefäß oder Transportmedium überführt und auf Nährböden ausgestrichen, die an der Luft bebrütet werden; anaerobe Bakterien werden damit nicht erfasst', 'Ponksiyonla alınan sıvı steril koşullarda kaba ya da taşıma besiyerine aktarılır ve havada inkübe edilen besiyerlerine ekilir; anaerop bakteriler bu kültürle saptanmaz', 'Effusion in a joint, in the pleural or abdominal cavity, a fluid collection in soft tissue, the contents of an abscess or a cyst, assessment after drainage', 'Izliv u zglobu, plućnoj maramici ili trbušnoj duplji, nakupljanje tečnosti u mekim tkivima, sadržaj apscesa ili ciste, procjena poslije drenaže', 'Излив у зглобу, плућној марамици или трбушној дупљи, накупљање течности у меким ткивима, садржај апсцеса или цисте, процјена послије дренаже', 'Выпот в суставе, плевральной или брюшной полости, скопление жидкости в мягких тканях, содержимое абсцесса или кисты, оценка после дренирования', 'Erguss in einem Gelenk, im Brust- oder Bauchraum, Flüssigkeitsansammlung im Weichgewebe, Inhalt eines Abszesses oder einer Zyste, Beurteilung nach einer Drainage', 'Eklemde, akciğer zarında ya da karın boşluğunda sıvı toplanması, yumuşak dokuda sıvı birikimi, apse veya kist içeriği, drenaj sonrası değerlendirme', 'No preparation is required from the patient, the material is obtained during the puncture; tell the doctor before the procedure about any antibiotics already started', 'Priprema pacijenta nije potrebna, materijal se dobija tokom punkcije; o započetim antibioticima treba obavijestiti ljekara prije zahvata', 'Припрема пацијента није потребна, материјал се добија током пункције; о започетим антибиотицима треба обавијестити љекара прије захвата', 'Подготовки от пациента не требуется, материал получают во время пункции; о начатых антибиотиках нужно сообщить врачу до процедуры', 'Vom Patienten ist keine Vorbereitung nötig, das Material wird während der Punktion gewonnen; bereits begonnene Antibiotika sind dem Arzt vor dem Eingriff mitzuteilen', 'Hastadan hazırlık istenmez, örnek ponksiyon sırasında alınır; başlanmış antibiyotikler işlemden önce hekime bildirilmelidir', 'Bacterial growth may point to infection in the punctured cavity, while no growth does not rule it out, since some organisms need oxygen-free or special media. The treating doctor draws the conclusion', 'Porast bakterija može ukazivati na infekciju u punktiranoj šupljini, a izostanak porasta je ne isključuje: dio uzročnika traži bezkiseoničke ili posebne podloge. Zaključak donosi ljekar koji liječi', 'Пораст бактерија може указивати на инфекцију у пунктираној шупљини, а изостанак пораста је не искључује: дио узрочника тражи безкисеоничке или посебне подлоге. Закључак доноси љекар који лијечи', 'Рост бактерий может указывать на инфекцию в пунктированной полости, а отсутствие роста её не исключает: часть возбудителей требует бескислородных или специальных сред. Заключение делает лечащий врач', 'Bakterienwachstum kann auf eine Infektion in der punktierten Höhle hinweisen, ein steriler Befund schließt sie nicht aus, da ein Teil der Erreger sauerstofffreie oder spezielle Nährböden braucht. Die Bewertung nimmt der behandelnde Arzt vor', 'Bakteri üremesi ponksiyon yapılan boşlukta enfeksiyona işaret edebilir, üreme olmaması ise bunu dışlamaz, çünkü bazı etkenler oksijensiz ya da özel besiyeri ister. Değerlendirmeyi tedaviyi yürüten hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'right-eye-swab-fungi'), 'Culture of material from the conjunctiva of the right eye for fungal flora', 'Kultura materijala sa konjunktive desnog oka na gljivičnu floru', 'Култура материјала са коњунктиве десног ока на гљивичну флору', 'Посев материала с конъюнктивы правого глаза на грибковую флору', 'Kultur von Material der Bindehaut des rechten Auges auf Pilzflora', 'Sağ göz konjonktivasından alınan örneğin mantar florası için kültürü', 'Discharge and a scraping from the conjunctiva of the right eye are collected with a swab or a loop, part of the material going for microscopy and part onto a fungal culture medium', 'Štapićem ili ezom skupljaju se sekret i strugotina sa konjunktive desnog oka, dio materijala ide na mikroskopiju, a dio na hranljivu podlogu za gljivice', 'Штапићем или езом скупљају се секрет и струготина са коњунктиве десног ока, дио материјала иде на микроскопију, а дио на хранљиву подлогу за гљивице', 'Тампоном или петлёй собирают отделяемое и соскоб с конъюнктивы правого глаза, часть материала идёт на микроскопию, часть — на питательную среду для грибов', 'Mit Tupfer oder Öse werden Sekret und abgeschabtes Material von der Bindehaut des rechten Auges gewonnen, ein Teil geht zur Mikroskopie, ein Teil auf einen Pilznährboden', 'Eküvyon ya da öze ile sağ göz konjonktivasından akıntı ve kazıntı alınır, örneğin bir bölümü mikroskopiye, bir bölümü mantar besiyerine gider', 'Persistent redness and irritation of the right eye, corneal clouding or ulcer after contact with soil or plants, work-up in reduced immunity, follow-up after antifungal treatment', 'Uporno crvenilo i nadražaj desnog oka, zamućenje ili ulkus rožnjače poslije kontakta sa zemljom i biljkama, ispitivanje kod snižene imunosti, kontrola poslije antimikotične terapije', 'Упорно црвенило и надражај десног ока, замућење или улкус рожњаче послије контакта са земљом и биљкама, испитивање код снижене имуности, контрола послије антимикотичне терапије', 'Упорное покраснение и раздражение правого глаза, помутнение или язва роговицы после контакта с землёй и растениями, обследование при сниженном иммунитете, контроль после противогрибкового лечения', 'Anhaltende Rötung und Reizung des rechten Auges, Hornhauttrübung oder Hornhautgeschwür nach Kontakt mit Erde oder Pflanzen, Abklärung bei geschwächter Abwehr, Kontrolle nach antimykotischer Behandlung', 'Sağ gözde geçmeyen kızarıklık ve batma, toprak ya da bitkiyle temastan sonra korneada bulanıklık veya ülser, bağışıklığı düşük kişilerde değerlendirme, antifungal tedavi sonrası kontrol', 'Come without make-up and without contact lenses, do not rinse the eye and do not instil drops on the day of sampling unless the doctor says otherwise', 'Doći bez šminke i bez kontaktnih sočiva, oko ne ispirati, a na dan uzimanja ne ukapavati kapi bez uputa ljekara', 'Доћи без шминке и без контактних сочива, око не испирати, а на дан узимања не укапавати капи без упута љекара', 'Приходить без косметики и контактных линз, глаз не промывать, капли в день забора не закапывать без указания врача', 'Ohne Make-up und ohne Kontaktlinsen erscheinen, das Auge nicht spülen und am Tag der Entnahme ohne ärztliche Anweisung keine Tropfen anwenden', 'Makyajsız ve kontakt lenssiz gelinmeli, göz yıkanmamalı, örnek günü hekim aksini söylemedikçe damla damlatılmamalıdır', 'Fungal growth may be related to fungal inflammation of the eye, or may reflect carriage on the skin of the lids. What the finding means in the clinical context is decided by the ophthalmologist', 'Porast gljivica može biti povezan sa gljivičnom upalom oka, ali može odražavati i nošenje gljivica na koži kapaka. Značaj nalaza prema kliničkoj slici određuje oftalmolog', 'Пораст гљивица може бити повезан са гљивичном упалом ока, али може одражавати и ношење гљивица на кожи капака. Значај налаза према клиничкој слици одређује офталмолог', 'Рост грибов может быть связан с грибковым воспалением глаза, а может отражать носительство на коже век. Значение находки по клинической картине определяет офтальмолог', 'Pilzwachstum kann mit einer Pilzentzündung des Auges zusammenhängen, kann aber auch eine Besiedlung der Lidhaut widerspiegeln. Was der Befund bedeutet, entscheidet der Augenarzt anhand des klinischen Bildes', 'Mantar üremesi gözün mantar iltihabıyla ilişkili olabilir, göz kapağı derisindeki taşıyıcılığı da yansıtabilir. Bulgunun anlamını klinik tabloya göre göz hekimi belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'skin-scraping-fungi'), 'Mycological examination of scales scraped from an affected area of skin', 'Mikološko ispitivanje ljuspica sastruganih sa promijenjenog dijela kože', 'Миколошко испитивање љуспица саструганих са промијењеног дијела коже', 'Микологическое исследование чешуек, соскоблённых с поражённого участка кожи', 'Mykologische Untersuchung von Schuppen, die von einer veränderten Hautstelle abgeschabt wurden', 'Derinin etkilenmiş bölgesinden kazınan pulların mikolojik incelemesi', 'Scales are collected with the blunt edge of a scalpel or a glass slide from the active edge of the lesion, part going into a preparation for microscopy and part onto a fungal culture medium', 'Tupom ivicom skalpela ili staklom sakupljaju se ljuspice sa aktivne ivice žarišta, dio se stavlja u preparat za mikroskopiju, a dio zasijava na podlogu za gljivice', 'Тупом ивицом скалпела или стаклом сакупљају се љуспице са активне ивице жаришта, дио се ставља у препарат за микроскопију, а дио засијава на подлогу за гљивице', 'Тупым краем скальпеля или стеклом собирают чешуйки с активного края очага, часть помещают в препарат для микроскопии, часть засевают на среду для грибов', 'Mit der stumpfen Skalpellkante oder einem Objektträger werden Schuppen vom aktiven Rand des Herdes gewonnen, ein Teil kommt in ein Präparat zur Mikroskopie, ein Teil auf einen Pilznährboden', 'Neşterin küt kenarı ya da lam ile lezyonun etkin kenarından pullar toplanır, bir bölümü mikroskopi preparatına, bir bölümü mantar besiyerine konur', 'Ring-shaped scaly patches, maceration and cracks between the toes, changes on the palms and soles, lesions that do not respond to topical treatment', 'Prstenasta ljuskava žarišta, vlaženje i pukotine među prstima stopala, promjene kože dlanova i tabana, žarišta koja ne reaguju na lokalnu terapiju', 'Прстенаста љускава жаришта, влажење и пукотине међу прстима стопала, промјене коже дланова и табана, жаришта која не реагују на локалну терапију', 'Кольцевидные шелушащиеся очаги, опрелость и трещины между пальцами стоп, изменения кожи ладоней и подошв, очаги, не отвечающие на наружное лечение', 'Ringförmige schuppende Herde, aufgeweichte Haut und Risse zwischen den Zehen, Veränderungen an Handflächen und Fußsohlen, Herde ohne Ansprechen auf äußerliche Behandlung', 'Halka biçiminde pullanan lezyonlar, ayak parmak aralarında yumuşama ve çatlaklar, avuç içi ve ayak tabanı değişiklikleri, yerel tedaviye yanıt vermeyen lezyonlar', 'Stop topical antifungals several days in advance, do not wash the area with soap on the day of the procedure and do not apply creams; the dermatologist sets the exact interval', 'Nekoliko dana ranije prekinuti lokalne antimikotike, na dan zahvata to mjesto ne prati sapunom i ne mazati kremama; rok prekida određuje dermatolog', 'Неколико дана раније прекинути локалне антимикотике, на дан захвата то мјесто не прати сапуном и не мазати кремама; рок прекида одређује дерматолог', 'За несколько дней отменить наружные противогрибковые средства, участок не мыть с мылом в день процедуры и не смазывать кремами; срок отмены уточняет дерматолог', 'Äußerliche Antimykotika einige Tage vorher absetzen, die Stelle am Tag der Entnahme nicht mit Seife waschen und nicht eincremen; den genauen Abstand legt der Hautarzt fest', 'Yerel antifungaller birkaç gün önce bırakılmalı, işlem günü bölge sabunla yıkanmamalı ve krem sürülmemelidir; süreyi dermatolog belirler', 'Fungal elements in the preparation or growth in culture may confirm the fungal nature of the changes, while a negative result after the use of ointments does not rule it out. The dermatologist draws the conclusion', 'Nalaz gljivičnih elemenata u preparatu ili porast kulture može potvrditi gljivičnu prirodu promjena, a negativan nalaz uz prethodno mazanje je ne isključuje. Zaključak donosi dermatolog', 'Налаз гљивичних елемената у препарату или пораст културе може потврдити гљивичну природу промјена, а негативан налаз уз претходно мазање је не искључује. Закључак доноси дерматолог', 'Обнаружение элементов гриба в препарате или рост культуры может подтверждать грибковую природу изменений, но отрицательный ответ на фоне мазей её не исключает. Вывод делает дерматолог', 'Pilzelemente im Präparat oder Wachstum in der Kultur können die Pilznatur der Veränderungen stützen, ein negativer Befund nach Salbenanwendung schließt sie nicht aus. Die Bewertung nimmt der Hautarzt vor', 'Preparatta mantar yapılarının görülmesi ya da kültürde üreme değişikliklerin mantar kaynaklı olduğunu destekleyebilir, merhem kullanımından sonra çıkan olumsuz sonuç ise bunu dışlamaz. Yorumu dermatolog yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urethral-swab-for-gonorrhea'), 'Collection of material from the urethra to detect Neisseria gonorrhoeae', 'Uzimanje materijala iz mokraćne cijevi radi dokazivanja Neisseria gonorrhoeae', 'Узимање материјала из мокраћне цијеви ради доказивања Neisseria gonorrhoeae', 'Взятие материала из мочеиспускательного канала для выявления Neisseria gonorrhoeae', 'Materialentnahme aus der Harnröhre zum Nachweis von Neisseria gonorrhoeae', 'Neisseria gonorrhoeae varlığını saptamak için üretradan örnek alınması', 'A thin probe is inserted a short way into the external opening of the urethra, and the material is used for microscopy of a stained smear, for culture or for a molecular test', 'Tanka sonda uvodi se plitko u spoljašnji otvor uretre, a materijal se koristi za mikroskopiju obojenog razmaza, za kulturu ili za molekularni test', 'Танка сонда уводи се плитко у спољашњи отвор уретре, а материјал се користи за микроскопију обојеног размаза, за културу или за молекуларни тест', 'Тонкий зонд вводят в наружное отверстие уретры на небольшую глубину, материал используют для микроскопии окрашенного мазка, посева или молекулярного теста', 'Eine dünne Sonde wird ein kurzes Stück in die äußere Harnröhrenöffnung eingeführt, das Material dient der Mikroskopie eines gefärbten Ausstrichs, der Kultur oder einem molekularen Test', 'İnce bir çubuk üretranın dış ağzından kısa bir mesafe içeri sokulur, alınan örnek boyalı yayma mikroskopisi, kültür ya da moleküler test için kullanılır', 'Urethral discharge and burning on urination, examination referred by a urologist or a dermatovenereologist, testing of a sexual partner, follow-up after treatment', 'Sekret iz uretre i peckanje pri mokrenju, ispitivanje po uputu urologa ili dermatovenerologa, pregled polnog partnera, kontrola poslije liječenja', 'Секрет из уретре и пецкање при мокрењу, испитивање по упуту уролога или дерматовенеролога, преглед полног партнера, контрола послије лијечења', 'Выделения из уретры и жжение при мочеиспускании, обследование по направлению уролога или дерматовенеролога, обследование полового партнёра, контроль после лечения', 'Ausfluss aus der Harnröhre und Brennen beim Wasserlassen, Untersuchung auf Überweisung des Urologen oder Dermatovenerologen, Abklärung des Sexualpartners, Kontrolle nach der Behandlung', 'Üretradan akıntı ve idrar yaparken yanma, üroloji ya da dermatoveneroloji hekiminin yönlendirmesi, cinsel eşin değerlendirilmesi, tedavi sonrası kontrol', 'Do not urinate for a few hours before sampling and avoid sexual contact the day before; take antibiotics before the test only in agreement with the doctor', 'Ne mokriti nekoliko sati prije uzimanja, dan ranije izbjegavati polne odnose; antibiotike prije ispitivanja uzimati samo uz dogovor sa ljekarom', 'Не мокрити неколико сати прије узимања, дан раније избјегавати полне односе; антибиотике прије испитивања узимати само уз договор са љекаром', 'Не мочиться несколько часов до взятия, накануне исключить половые контакты; антибиотики до исследования принимать только по согласованию с врачом', 'Einige Stunden vor der Entnahme nicht Wasser lassen, am Vortag auf Geschlechtsverkehr verzichten; Antibiotika vor der Untersuchung nur nach Absprache mit dem Arzt einnehmen', 'Örnek alınmadan birkaç saat önce idrara çıkılmamalı, bir gün önce cinsel ilişkiden kaçınılmalıdır; testten önce antibiyotik yalnızca hekimle görüşülerek kullanılır', 'Detection of the organism means that the next steps, including testing of the partner, should be discussed with the doctor. A negative result with persisting complaints does not rule out other causes of urethral inflammation', 'Nalaz uzročnika znači da dalje korake, uključujući ispitivanje partnera, treba dogovoriti sa ljekarom. Negativan nalaz uz trajne tegobe ne isključuje druge uzroke upale uretre', 'Налаз узрочника значи да даље кораке, укључујући испитивање партнера, треба договорити са љекаром. Негативан налаз уз трајне тегобе не искључује друге узроке упале уретре', 'Обнаружение возбудителя означает, что дальнейшие шаги, включая обследование партнёра, нужно обсудить с врачом. Отрицательный результат при сохраняющихся жалобах не исключает других причин воспаления уретры', 'Ein Erregernachweis bedeutet, dass die weiteren Schritte einschließlich der Untersuchung des Partners mit dem Arzt zu besprechen sind. Ein negativer Befund bei fortbestehenden Beschwerden schließt andere Ursachen einer Harnröhrenentzündung nicht aus', 'Etkenin saptanması, eşin değerlendirilmesi dahil sonraki adımların hekimle konuşulması gerektiği anlamına gelir. Yakınmalar sürerken olumsuz sonuç çıkması üretra iltihabının başka nedenlerini dışlamaz')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vaginal-secretion'), 'Laboratory assessment of vaginal discharge: the composition of the flora and the cellular elements', 'Laboratorijska procjena vaginalnog sekreta: sastav mikroflore i ćelijski elementi', 'Лабораторијска процјена вагиналног секрета: састав микрофлоре и ћелијски елементи', 'Лабораторная оценка влагалищного отделяемого: состав микрофлоры и клеточные элементы', 'Laborbeurteilung des Vaginalsekrets: Zusammensetzung der Flora und Zellbestandteile', 'Vajinal akıntının laboratuvar değerlendirmesi: flora bileşimi ve hücresel öğeler', 'The gynaecologist takes discharge from the vaginal wall, the laboratory prepares a wet mount and a stained slide and examines them under the microscope, and the material can additionally be cultured', 'Ginekolog uzima sekret sa zida vagine, u laboratoriji se prave nativni i obojeni preparat i gledaju pod mikroskopom, a po potrebi se materijal dodatno zasijava', 'Гинеколог узима секрет са зида вагине, у лабораторији се праве нативни и обојени препарат и гледају под микроскопом, а по потреби се материјал додатно засијава', 'Гинеколог берёт отделяемое со стенки влагалища, в лаборатории готовят нативный и окрашенный препараты и рассматривают их под микроскопом, при необходимости материал дополнительно засевают', 'Die Frauenärztin entnimmt Sekret von der Scheidenwand, im Labor werden ein Nativpräparat und ein gefärbter Ausstrich angefertigt und mikroskopiert, bei Bedarf wird das Material zusätzlich kultiviert', 'Jinekolog vajen duvarından akıntı alır, laboratuvarda nativ ve boyalı preparat hazırlanıp mikroskopla incelenir, gerekirse örnek ayrıca kültüre ekilir', 'A change in the amount, colour or smell of discharge, itching and burning, monitoring in pregnancy, complaints while taking antibiotics, follow-up after treatment', 'Promjena količine, boje ili mirisa sekreta, svrab i peckanje, praćenje u trudnoći, tegobe uz uzimanje antibiotika, kontrola poslije liječenja', 'Промјена количине, боје или мириса секрета, свраб и пецкање, праћење у трудноћи, тегобе уз узимање антибиотика, контрола послије лијечења', 'Изменение количества, цвета или запаха выделений, зуд и жжение, наблюдение при беременности, жалобы на фоне антибиотиков, контроль после лечения', 'Veränderte Menge, Farbe oder Geruch des Ausflusses, Juckreiz und Brennen, Kontrolle in der Schwangerschaft, Beschwerden unter Antibiotika, Verlaufskontrolle nach der Behandlung', 'Akıntının miktarında, renginde ya da kokusunda değişiklik, kaşıntı ve yanma, gebelikte izlem, antibiyotik kullanırken ortaya çıkan yakınmalar, tedavi sonrası kontrol', 'Not taken during menstruation; avoid vaginal pessaries, creams and douching for one to two days and sexual contact the day before', 'Ne uzima se tokom menstruacije, jedan do dva dana ranije bez vaginaleta, krema i ispiranja, a dan ranije bez polnih odnosa', 'Не узима се током менструације, један до два дана раније без вагиналета, крема и испирања, а дан раније без полних односа', 'Не сдавать во время менструации, за один-два дня отказаться от вагинальных свечей, кремов и спринцеваний, накануне воздержаться от половых контактов', 'Nicht während der Menstruation; ein bis zwei Tage vorher keine Vaginalzäpfchen, Cremes und Spülungen, am Vortag kein Geschlechtsverkehr', 'Adet döneminde alınmaz; bir iki gün önce vajinal fitil, krem ve duş uygulanmamalı, bir gün önce cinsel ilişkiden kaçınılmalıdır', 'A shift in the flora, a high number of leukocytes or the finding of yeast cells may be related to inflammation or to a disturbed balance of the vaginal flora. The gynaecologist decides whether treatment and a culture are needed', 'Promjena sastava flore, veći broj leukocita ili nalaz kvasničnih ćelija mogu biti povezani sa upalom ili sa poremećajem ravnoteže mikroflore. Da li je potrebno liječenje i da li treba kultura, odlučuje ginekolog', 'Промјена састава флоре, већи број леукоцита или налаз квасничних ћелија могу бити повезани са упалом или са поремећајем равнотеже микрофлоре. Да ли је потребно лијечење и да ли треба култура, одлучује гинеколог', 'Сдвиг состава флоры, большое число лейкоцитов или находка дрожжевых клеток могут быть связаны с воспалением или с нарушением баланса микрофлоры. Нужно ли лечение и требуется ли посев, определяет гинеколог', 'Eine verschobene Flora, viele Leukozyten oder der Nachweis von Hefezellen können mit einer Entzündung oder einer gestörten Balance der Scheidenflora zusammenhängen. Ob eine Behandlung und eine Kultur nötig sind, entscheidet die Frauenärztin', 'Flora bileşiminin değişmesi, lökosit sayısının artması ya da maya hücrelerinin görülmesi iltihapla ya da vajen florasının dengesinin bozulmasıyla ilişkili olabilir. Tedavi ve kültür gerekip gerekmediğine jinekolog karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'antibiogram'), 'Testing the susceptibility of an isolated bacterium to antibacterial drugs', 'Određivanje osjetljivosti izolovane bakterije na antibakterijske lijekove', 'Одређивање осјетљивости изоловане бактерије на антибактеријске лијекове', 'Определение чувствительности выделенной бактерии к антибактериальным препаратам', 'Prüfung der Empfindlichkeit eines isolierten Bakteriums gegenüber antibakteriellen Wirkstoffen', 'İzole edilen bakterinin antibakteriyel ilaçlara duyarlılığının belirlenmesi', 'A suspension is made from the grown culture and applied to a medium with antibiotic discs or to a panel with drug dilutions, after which it is read at which concentration growth is suppressed', 'Od izrasle kulture pravi se suspenzija i nanosi na podlogu sa diskovima ili u ploču sa razblaženjima lijekova, a zatim se očitava pri kojoj koncentraciji je rast zaustavljen', 'Од израсле културе прави се суспензија и наноси на подлогу са дисковима или у плочу са разблажењима лијекова, а затим се очитава при којој концентрацији је раст заустављен', 'Из выросшей культуры готовят взвесь и наносят её на среду с дисками или в панель с разведениями препаратов, затем оценивают, при какой концентрации рост подавляется', 'Aus der gewachsenen Kultur wird eine Suspension hergestellt und auf einen Nährboden mit Testplättchen oder in eine Platte mit Wirkstoffverdünnungen gegeben, danach wird abgelesen, bei welcher Konzentration das Wachstum gehemmt ist', 'Üreyen kültürden süspansiyon hazırlanıp disklerin bulunduğu besiyerine ya da ilaç sulandırmaları içeren panele aktarılır, ardından üremenin hangi yoğunlukta durduğu okunur', 'Performed in addition to a culture of urine, a swab, a wound, sputum or blood once a bacterium has grown and the doctor needs a founded choice of drug, and when complaints return after treatment', 'Radi se uz kulturu urina, brisa, rane, ispljuvka ili krvi, kada je bakterija izrasla i ljekaru treba utemeljen izbor lijeka, kao i kod povratka tegoba poslije terapije', 'Ради се уз културу урина, бриса, ране, испљувка или крви, када је бактерија израсла и љекару треба утемељен избор лијека, као и код повратка тегоба послије терапије', 'Выполняется дополнительно к посеву мочи, мазка, раны, мокроты или крови, когда бактерия выросла и врачу нужен обоснованный выбор препарата, а также при возврате жалоб после лечения', 'Ergänzend zur Kultur von Urin, Abstrich, Wunde, Sputum oder Blut, wenn ein Bakterium gewachsen ist und der Arzt eine begründete Wirkstoffwahl braucht, sowie bei Wiederauftreten der Beschwerden nach der Behandlung', 'İdrar, sürüntü, yara, balgam ya da kan kültüründe bakteri ürediğinde ve hekimin gerekçeli ilaç seçimine ihtiyacı olduğunda, ayrıca tedavi sonrası yakınmalar yinelediğinde yapılır', 'No separate preparation: the test is done from material already collected, so what matters is the rules for taking the original culture', 'Posebne pripreme nema: nalaz se radi iz već uzetog materijala, pa su važna pravila uzimanja osnovne kulture', 'Посебне припреме нема: налаз се ради из већ узетог материјала, па су важна правила узимања основне културе', 'Отдельной подготовки нет: исследование делают из уже полученного материала, поэтому важны правила забора основного посева', 'Keine eigene Vorbereitung: der Test erfolgt aus bereits gewonnenem Material, entscheidend sind die Regeln für die Entnahme der Ausgangskultur', 'Ayrı bir hazırlık gerekmez: test önceden alınmış örnekten yapılır, bu nedenle asıl kültürün alınma kuralları önemlidir', 'Susceptible and resistant markings refer to the isolated strain under laboratory conditions and are not a prescription. The drug, the dose and the duration are decided by the doctor, taking the site of infection and tolerance into account', 'Oznake osjetljivosti i rezistencije odnose se na izolovani soj u laboratorijskim uslovima i nisu propisana terapija. Lijek, dozu i trajanje određuje ljekar prema mjestu infekcije i podnošljivosti', 'Ознаке осјетљивости и резистенције односе се на изоловани сој у лабораторијским условима и нису прописана терапија. Лијек, дозу и трајање одређује љекар према мјесту инфекције и подношљивости', 'Отметки о чувствительности и устойчивости относятся к выделенному штамму в лабораторных условиях и не являются назначением. Препарат, дозу и длительность определяет врач с учётом локализации инфекции и переносимости', 'Die Angaben empfindlich und resistent beziehen sich auf den isolierten Stamm unter Laborbedingungen und sind keine Verordnung. Wirkstoff, Dosis und Dauer legt der Arzt unter Berücksichtigung von Infektionsort und Verträglichkeit fest', 'Duyarlı ve dirençli işaretleri laboratuvar koşullarında izole edilen suşa aittir ve bir reçete değildir. İlacı, dozu ve süreyi enfeksiyonun yerini ve hastanın toleransını göz önüne alarak hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'antimycogram'), 'Testing the susceptibility of an isolated fungus to antifungal drugs', 'Određivanje osjetljivosti izolovane gljivice na antimikotike', 'Одређивање осјетљивости изоловане гљивице на антимикотике', 'Определение чувствительности выделенного гриба к противогрибковым препаратам', 'Prüfung der Empfindlichkeit eines isolierten Pilzes gegenüber Antimykotika', 'İzole edilen mantarın antifungal ilaçlara duyarlılığının belirlenmesi', 'A standard suspension is prepared from the grown fungal culture and placed in a panel or on a medium containing antifungal agents, and the result is read later than in a bacterial test', 'Od izrasle kulture gljivice pravi se standardna suspenzija i unosi u ploču ili na podlogu sa antimikoticima, a rezultat se očitava kasnije nego kod bakterijskog testa', 'Од израсле културе гљивице прави се стандардна суспензија и уноси у плочу или на подлогу са антимикотицима, а резултат се очитава касније него код бактеријског теста', 'Из выросшей культуры гриба готовят стандартную взвесь и вносят в панель или на среду с противогрибковыми препаратами, результат читают позже, чем при бактериальном тесте', 'Aus der gewachsenen Pilzkultur wird eine standardisierte Suspension hergestellt und in eine Platte oder auf einen Nährboden mit Antimykotika gegeben, das Ergebnis wird später abgelesen als beim bakteriellen Test', 'Üreyen mantar kültüründen standart süspansiyon hazırlanır ve antifungal içeren panele ya da besiyerine konur, sonuç bakteri testine göre daha geç okunur', 'Recurring fungal complaints, no effect from the prescribed antifungal, growth of a rare fungus or a mould, work-up in reduced immunity', 'Gljivične tegobe koje se ponavljaju, izostanak efekta propisanog antimikotika, nalaz rijetke ili plijesnive gljivice, ispitivanje kod snižene imunosti', 'Гљивичне тегобе које се понављају, изостанак ефекта прописаног антимикотика, налаз ријетке или плијесниве гљивице, испитивање код снижене имуности', 'Повторяющиеся грибковые жалобы, отсутствие эффекта от назначенного противогрибкового средства, находка редкого или плесневого гриба, обследование при сниженном иммунитете', 'Wiederkehrende Pilzbeschwerden, fehlende Wirkung des verordneten Antimykotikums, Nachweis eines seltenen Pilzes oder eines Schimmelpilzes, Abklärung bei geschwächter Abwehr', 'Yinelenen mantar yakınmaları, verilen antifungalden yanıt alınamaması, seyrek görülen bir mantarın ya da küfün üremesi, bağışıklığı düşük kişilerde değerlendirme', 'No preparation is needed: the test is set up from a culture already isolated from a swab, a scraping or other material', 'Priprema nije potrebna: test se radi iz već izolovane kulture dobijene zasijavanjem brisa, strugotine ili drugog materijala', 'Припрема није потребна: тест се ради из већ изоловане културе добијене засијавањем бриса, струготине или другог материјала', 'Подготовки не требуется: тест ставят из уже выделенной культуры, полученной при посеве мазка, соскоба или другого материала', 'Keine Vorbereitung nötig: der Test wird aus einer bereits isolierten Kultur aus Abstrich, Schuppen oder anderem Material angesetzt', 'Hazırlık gerekmez: test sürüntü, kazıntı ya da başka bir örnekten daha önce izole edilmiş kültürden kurulur', 'The result shows how the particular isolate behaves under laboratory conditions and does not always match the response to treatment. The choice of drug and the regimen are decided by the doctor', 'Nalaz pokazuje ponašanje konkretnog izolata u laboratorijskim uslovima i ne poklapa se uvijek sa odgovorom na terapiju. Izbor lijeka i način primjene određuje ljekar', 'Налаз показује понашање конкретног изолата у лабораторијским условима и не поклапа се увијек са одговором на терапију. Избор лијека и начин примјене одређује љекар', 'Результат показывает поведение конкретного изолята в лабораторных условиях и не всегда совпадает с ответом на лечение. Выбор препарата и схему определяет врач', 'Das Ergebnis zeigt das Verhalten des einzelnen Isolats unter Laborbedingungen und stimmt nicht immer mit dem Ansprechen auf die Behandlung überein. Wirkstoffwahl und Behandlungsschema legt der Arzt fest', 'Sonuç, izolatın laboratuvar koşullarındaki davranışını gösterir ve tedaviye yanıtla her zaman örtüşmez. İlaç seçimini ve uygulama düzenini hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'dermatophytes-hair-scraping'), 'Direct microscopy of hair for signs of dermatophyte involvement', 'Direktna mikroskopija dlake na znake oštećenja dermatofitima', 'Директна микроскопија длаке на знаке оштећења дерматофитима', 'Прямая микроскопия волос на признаки поражения дерматофитами', 'Direkte Mikroskopie von Haaren auf Zeichen eines Dermatophytenbefalls', 'Kılların dermatofit tutulumu belirtileri için doğrudan mikroskopisi', 'Broken hairs and scales are taken with tweezers from a patch on the scalp or another hairy area, the preparation is placed in a clearing solution and examined under the microscope', 'Pincetom se uzimaju polomljene dlake i ljuspice sa žarišta na glavi ili drugom dlakavom dijelu, preparat se stavlja u rastvor za razbistravanje i gleda pod mikroskopom', 'Пинцетом се узимају поломљене длаке и љуспице са жаришта на глави или другом длакавом дијелу, препарат се ставља у раствор за разбистравање и гледа под микроскопом', 'Пинцетом берут обломанные волосы и чешуйки с очага на голове или другом волосистом участке, препарат помещают в осветляющий раствор и рассматривают под микроскопом', 'Mit einer Pinzette werden abgebrochene Haare und Schuppen aus einem Herd an der Kopfhaut oder einer anderen behaarten Stelle entnommen, das Präparat wird in eine aufhellende Lösung gegeben und mikroskopiert', 'Saçlı deride ya da başka kıllı bir bölgedeki lezyondan cımbızla kırık kıllar ve pullar alınır, preparat berraklaştırıcı çözeltiye konarak mikroskopla incelenir', 'Patches of thinned hair with scaling, hairs broken off at skin level, an itchy scalp in children, examination of household contacts, follow-up after treatment', 'Žarišta prorijeđene dlake sa ljuštenjem, dlake polomljene uz samu kožu, svrab vlasišta kod djece, ispitivanje ukućana, kontrola poslije liječenja', 'Жаришта проријеђене длаке са љуштењем, длаке поломљене уз саму кожу, свраб власишта код дјеце, испитивање укућана, контрола послије лијечења', 'Очаги поредения волос с шелушением, обломанные у самой кожи волосы, зуд волосистой части головы у детей, обследование контактных лиц, контроль после лечения', 'Herde mit schütterem Haar und Schuppung, dicht über der Haut abgebrochene Haare, juckende Kopfhaut bei Kindern, Untersuchung von Kontaktpersonen, Kontrolle nach der Behandlung', 'Pullanmayla birlikte seyrelmiş saç alanları, deri hizasında kırılan kıllar, çocuklarda saçlı deri kaşıntısı, ev halkının taranması, tedavi sonrası kontrol', 'Do not wash the hair for two to three days and do not use medicated shampoos, ointments or dyes; the dermatologist sets the interval after antifungal products', 'Kosu ne prati dva do tri dana, ne koristiti ljekovite šampone, masti i boje; razmak poslije antimikotika određuje dermatolog', 'Косу не прати два до три дана, не користити љековите шампоне, масти и боје; размак послије антимикотика одређује дерматолог', 'Волосы не мыть два-три дня, не использовать лечебные шампуни, мази и красители; интервал после противогрибковых средств уточняет дерматолог', 'Die Haare zwei bis drei Tage nicht waschen und keine medizinischen Shampoos, Salben oder Färbemittel verwenden; den Abstand nach Antipilzmitteln legt der Hautarzt fest', 'Saçlar iki üç gün yıkanmamalı, tedavi edici şampuan, merhem ve boya kullanılmamalıdır; antifungal kullanımından sonraki aralığı dermatolog belirler', 'Fungal filaments and spores around or inside the hair may point to a dermatophyte infection of the scalp, while a negative preparation does not rule it out and is often supplemented by a culture. The dermatologist draws the conclusion', 'Niti gljivice i spore oko dlake ili u njoj mogu ukazivati na dermatomikozu vlasišta, a negativan preparat je ne isključuje i često se dopunjava kulturom. Zaključak donosi dermatolog', 'Нити гљивице и споре око длаке или у њој могу указивати на дерматомикозу власишта, а негативан препарат је не искључује и често се допуњава културом. Закључак доноси дерматолог', 'Нити гриба и споры вокруг волоса или внутри него могут указывать на дерматомикоз волосистой части, а отрицательный препарат его не исключает и часто дополняется посевом. Заключение делает дерматолог', 'Pilzfäden und Sporen um das Haar oder in ihm können auf eine Dermatophytose der Kopfhaut hinweisen, ein negatives Präparat schließt sie nicht aus und wird oft durch eine Kultur ergänzt. Die Bewertung nimmt der Hautarzt vor', 'Kılın çevresinde ya da içinde mantar iplikleri ve sporların görülmesi saçlı deri dermatomikozuna işaret edebilir, olumsuz preparat ise bunu dışlamaz ve sıklıkla kültürle tamamlanır. Yorumu dermatolog yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'fungal-identification'), 'Determining the genus and species of a fungus grown in culture', 'Određivanje roda i vrste gljivice izrasle u kulturi', 'Одређивање рода и врсте гљивице израсле у култури', 'Определение рода и вида гриба, выросшего в культуре', 'Bestimmung von Gattung und Art eines in der Kultur gewachsenen Pilzes', 'Kültürde üreyen mantarın cins ve türünün belirlenmesi', 'The colony that has grown is assessed by its appearance and under the microscope, subcultured on special media if needed, and tested with biochemical or rapid tests', 'Izrasla kolonija se procjenjuje po izgledu i pod mikroskopom, po potrebi se presijava na posebne podloge i rade biohemijski ili brzi testovi', 'Израсла колонија се процјењује по изгледу и под микроскопом, по потреби се пресијава на посебне подлоге и раде биохемијски или брзи тестови', 'Выросшую колонию изучают по внешнему виду и под микроскопом, при необходимости пересевают на специальные среды и используют биохимические или экспресс-тесты', 'Die gewachsene Kolonie wird nach Aussehen und unter dem Mikroskop beurteilt, bei Bedarf auf Spezialnährböden überimpft und mit biochemischen oder Schnelltests untersucht', 'Üreyen koloni görünümüne göre ve mikroskopla değerlendirilir, gerekirse özel besiyerlerine pasajlanır ve biyokimyasal ya da hızlı testlerle incelenir', 'Performed after a positive culture of a swab, a scraping, sputum or other material when the doctor needs to know the exact organism, and in recurring or stubborn fungal complaints', 'Radi se poslije pozitivne kulture brisa, strugotine, ispljuvka ili drugog materijala, kada je ljekaru važno da zna tačnog uzročnika, kao i kod ponavljanih i upornih gljivičnih tegoba', 'Ради се послије позитивне културе бриса, струготине, испљувка или другог материјала, када је љекару важно да зна тачног узрочника, као и код понављаних и упорних гљивичних тегоба', 'Выполняется после положительного посева мазка, соскоба, мокроты или другого материала, когда врачу важно знать конкретного возбудителя, а также при повторных и упорных грибковых жалобах', 'Erfolgt nach einer positiven Kultur aus Abstrich, Schuppen, Sputum oder anderem Material, wenn der Arzt den genauen Erreger kennen muss, sowie bei wiederkehrenden und hartnäckigen Pilzbeschwerden', 'Sürüntü, kazıntı, balgam ya da başka bir örneğin kültürü pozitif çıktığında ve hekimin etkeni tam olarak bilmesi gerektiğinde, ayrıca yinelenen ve inatçı mantar yakınmalarında yapılır', 'No preparation is required from the patient: the work is done on a culture that has already been isolated', 'Priprema pacijenta nije potrebna: radi se sa već izolovanom kulturom', 'Припрема пацијента није потребна: ради се са већ изолованом културом', 'Подготовки от пациента не требуется: работа идёт с уже выделенной культурой', 'Vom Patienten ist keine Vorbereitung nötig: gearbeitet wird mit einer bereits isolierten Kultur', 'Hastadan hazırlık istenmez: çalışma daha önce izole edilmiş kültür üzerinde yapılır', 'The species name says which fungus has grown, not whether it causes disease: some species are ordinary inhabitants of the skin and mucous membranes. The doctor assesses what the finding means and whether treatment is needed', 'Naziv vrste govori koja je gljivica izrasla, ali ne i da li ona izaziva bolest: dio vrsta pripada uobičajenim stanovnicima kože i sluznica. Značaj nalaza i potrebu za liječenjem procjenjuje ljekar', 'Назив врсте говори која је гљивица израсла, али не и да ли она изазива болест: дио врста припада уобичајеним становницима коже и слузница. Значај налаза и потребу за лијечењем процјењује љекар', 'Название вида говорит о том, какой гриб вырос, но не о том, вызывает ли он болезнь: часть видов относится к обычным обитателям кожи и слизистых. Значение находки и необходимость лечения оценивает врач', 'Der Artname sagt, welcher Pilz gewachsen ist, nicht aber, ob er eine Erkrankung verursacht: ein Teil der Arten gehört zur normalen Besiedlung von Haut und Schleimhäuten. Bedeutung des Befunds und Behandlungsbedarf beurteilt der Arzt', 'Tür adı hangi mantarın ürediğini söyler, hastalık yapıp yapmadığını değil: türlerin bir bölümü deri ve mukozaların olağan sakinleridir. Bulgunun anlamını ve tedavi gerekliliğini hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'liquid-based-cytology'), 'Cytological examination of cervical cells in which the material is transferred into a liquid preservative', 'Citološki pregled ćelija grlića materice kod kojeg se uzorak prenosi u tečnu konzervišuću podlogu', 'Цитолошки преглед ћелија грлића материце код којег се узорак преноси у течну конзервишућу подлогу', 'Цитологическое исследование клеток шейки матки, при котором материал переносят в жидкую консервирующую среду', 'Zytologische Untersuchung von Zellen des Gebärmutterhalses, bei der das Material in eine flüssige Konservierungslösung überführt wird', 'Örneğin sıvı koruyucu ortama aktarıldığı rahim ağzı hücre incelemesi', 'The gynaecologist collects cells with a brush as in a conventional smear, but the brush is rinsed into a vial of fluid, from which the laboratory prepares a thin layer of cells', 'Ginekolog uzima ćelije četkicom kao i kod klasičnog brisa, ali se četkica spušta u bočicu sa tečnošću, a laboratorija iz nje pravi tanak sloj ćelija', 'Гинеколог узима ћелије четкицом као и код класичног бриса, али се четкица спушта у бочицу са течношћу, а лабораторија из ње прави танак слој ћелија', 'Гинеколог берёт клетки щёточкой, как при обычном мазке, но щёточку опускают во флакон с жидкостью, а тонкий слой клеток лаборатория готовит уже из него', 'Die Frauenärztin entnimmt die Zellen wie beim klassischen Abstrich mit einer Bürste, spült diese aber in ein Fläschchen mit Flüssigkeit, aus dem das Labor eine dünne Zellschicht herstellt', 'Jinekolog hücreleri klasik smearde olduğu gibi fırçayla alır, ancak fırça sıvı dolu bir şişeye batırılır ve laboratuvar bu sıvıdan ince bir hücre tabakası hazırlar', 'Routine cervical screening, an unusable result of a conventional smear, the need to run additional tests from the same sample, follow-up after previously detected changes', 'Redovan skrining grlića materice, neupotrebljiv nalaz klasičnog brisa, potreba da se iz istog uzorka urade dodatna ispitivanja, praćenje poslije ranije uočenih promjena', 'Редован скрининг грлића материце, неупотребљив налаз класичног бриса, потреба да се из истог узорка ураде додатна испитивања, праћење послије раније уочених промјена', 'Плановый цервикальный скрининг, неинформативный результат обычного мазка, необходимость выполнить дополнительные исследования из того же материала, наблюдение после ранее выявленных изменений', 'Regelmäßige Gebärmutterhals-Vorsorge, nicht beurteilbarer klassischer Abstrich, Bedarf an weiteren Untersuchungen aus derselben Probe, Verlaufskontrolle nach früher festgestellten Veränderungen', 'Düzenli rahim ağzı taraması, klasik smearin değerlendirilemeyen sonucu, aynı örnekten ek testlerin yapılması gereği, daha önce saptanmış değişikliklerin izlemi', 'Outside menstruation, with no vaginal products, douching or sexual contact for one to two days beforehand', 'Van menstruacije, jedan do dva dana bez vaginalnih preparata, ispiranja i polnih odnosa', 'Ван менструације, један до два дана без вагиналних препарата, испирања и полних односа', 'Вне менструации, за один-два дня без вагинальных препаратов, спринцеваний и половых контактов', 'Außerhalb der Menstruation, ein bis zwei Tage ohne Vaginalpräparate, Spülungen und Geschlechtsverkehr', 'Adet dönemi dışında, bir iki gün önce vajinal ürün, duş ve cinsel ilişki olmadan', 'Cell changes may be related to inflammation, hormonal influence or to epithelial changes that require follow-up, and are reported using a standard classification. The gynaecologist sets the interval for repeat testing and decides whether colposcopy is needed', 'Promjene ćelija mogu biti povezane sa upalom, hormonskim uticajem ili sa promjenama epitela koje traže praćenje, a opisuju se standardnom klasifikacijom. Rok ponovnog pregleda i potrebu za kolposkopijom određuje ginekolog', 'Промјене ћелија могу бити повезане са упалом, хормонским утицајем или са промјенама епитела које траже праћење, а описују се стандардном класификацијом. Рок поновног прегледа и потребу за колпоскопијом одређује гинеколог', 'Изменения клеток могут быть связаны с воспалением, гормональным влиянием или с изменениями эпителия, требующими наблюдения, и описываются по стандартной классификации. Срок повторного обследования и необходимость кольпоскопии определяет гинеколог', 'Zellveränderungen können mit einer Entzündung, hormonellen Einflüssen oder mit Veränderungen des Epithels zusammenhängen, die eine Kontrolle brauchen, und werden nach einer Standardklassifikation beschrieben. Den Abstand bis zur Kontrolle und die Notwendigkeit einer Kolposkopie legt die Frauenärztin fest', 'Hücre değişiklikleri iltihapla, hormonal etkiyle ya da izlem gerektiren epitel değişiklikleriyle ilişkili olabilir ve standart bir sınıflamaya göre bildirilir. Kontrol aralığını ve kolposkopi gerekip gerekmediğini jinekolog belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'punctate-fungi'), 'Examination of fluid obtained by puncture for yeasts and moulds', 'Ispitivanje tečnosti dobijene punkcijom na kvasnice i plijesni', 'Испитивање течности добијене пункцијом на кваснице и плијесни', 'Исследование жидкости, полученной пункцией, на дрожжевые и плесневые грибы', 'Untersuchung von Punktionsflüssigkeit auf Hefen und Schimmelpilze', 'Ponksiyonla alınan sıvının maya ve küf mantarları yönünden incelenmesi', 'The material is delivered to the laboratory in a sterile syringe or container, part going for microscopy and part onto fungal media, which are kept longer than bacterial ones', 'Materijal u sterilnom špricu ili posudi dostavlja se u laboratoriju, dio ide na mikroskopiju, a dio na podloge za gljivice koje se drže duže nego bakteriološke', 'Материјал у стерилном шприцу или посуди доставља се у лабораторију, дио иде на микроскопију, а дио на подлоге за гљивице које се држе дуже него бактериолошке', 'Материал в стерильном шприце или контейнере доставляют в лабораторию, часть идёт на микроскопию, часть — на среды для грибов, которые выдерживают дольше бактериальных', 'Das Material wird in einer sterilen Spritze oder einem Gefäß ins Labor gebracht, ein Teil geht zur Mikroskopie, ein Teil auf Pilznährböden, die länger bebrütet werden als bakterielle', 'Örnek steril enjektör ya da kap içinde laboratuvara ulaştırılır, bir bölümü mikroskopiye, bir bölümü bakteri besiyerlerinden daha uzun süre tutulan mantar besiyerlerine gider', 'Prolonged fever with no response to antibiotics, a fluid collection in a patient with reduced immunity or after long antibacterial therapy, effusion in a joint or a cavity with a suspected fungal cause', 'Dugotrajna temperatura bez odgovora na antibiotike, nakupljanje tečnosti kod pacijenta sa oslabljenim imunitetom ili poslije duge antibiotske terapije, izliv u zglobu ili šupljini uz sumnju na gljivični uzrok', 'Дуготрајна температура без одговора на антибиотике, накупљање течности код пацијента са ослабљеним имунитетом или послије дуге антибиотске терапије, излив у зглобу или шупљини уз сумњу на гљивични узрок', 'Длительная лихорадка без ответа на антибиотики, скопление жидкости у пациента со сниженным иммунитетом или после долгой антибактериальной терапии, выпот в суставе или полости с подозрением на грибковую причину', 'Anhaltendes Fieber ohne Ansprechen auf Antibiotika, Flüssigkeitsansammlung bei geschwächter Abwehr oder nach langer antibakterieller Therapie, Erguss in einem Gelenk oder einer Höhle mit Verdacht auf eine Pilzursache', 'Antibiyotiklere yanıt vermeyen uzamış ateş, bağışıklığı düşük hastada ya da uzun antibakteriyel tedavi sonrası sıvı toplanması, mantar kaynaklı olduğundan kuşkulanılan eklem ya da boşluk sıvısı', 'No preparation is needed from the patient, the puncture is performed by a doctor; any antifungal drugs being taken should be named in advance', 'Od pacijenta se priprema ne traži, punkciju radi ljekar; antimikotike koje uzima treba navesti unaprijed', 'Од пацијента се припрема не тражи, пункцију ради љекар; антимикотике које узима треба навести унапријед', 'От пациента подготовка не требуется, пункцию проводит врач; принимаемые противогрибковые препараты нужно назвать заранее', 'Vom Patienten ist keine Vorbereitung nötig, die Punktion führt der Arzt durch; eingenommene Antimykotika sollten vorher genannt werden', 'Hastadan hazırlık istenmez, ponksiyonu hekim yapar; kullanılan antifungal ilaçlar önceden bildirilmelidir', 'Fungal growth may mean that fungal flora takes part in the inflammation, or may reflect contamination of the sample during collection. The treating doctor draws the conclusion together with the clinical picture', 'Porast gljivica može značiti učešće gljivične flore u upali, ali i zagađenje uzorka pri uzimanju. Zaključak zajedno sa kliničkom slikom donosi ljekar koji liječi', 'Пораст гљивица може значити учешће гљивичне флоре у упали, али и загађење узорка при узимању. Закључак заједно са клиничком сликом доноси љекар који лијечи', 'Рост грибов может означать участие грибковой флоры в воспалении, а может отражать загрязнение материала при получении. Вывод вместе с клинической картиной делает лечащий врач', 'Pilzwachstum kann bedeuten, dass Pilzflora an der Entzündung beteiligt ist, kann aber auch eine Verunreinigung bei der Entnahme widerspiegeln. Die Bewertung nimmt der behandelnde Arzt zusammen mit dem klinischen Bild vor', 'Mantar üremesi iltihaba mantar florasının katıldığı anlamına gelebileceği gibi örnek alınırken bulaşmayı da yansıtabilir. Sonucu klinik tabloyla birlikte tedaviyi yürüten hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'umbilicus-swab-fungi'), 'Culture of material from the navel fold for yeasts and moulds', 'Kultura materijala iz nabora pupka na kvasnice i plijesni', 'Култура материјала из набора пупка на кваснице и плијесни', 'Посев материала из пупочной складки на дрожжевые и плесневые грибы', 'Kultur von Material aus der Nabelfalte auf Hefen und Schimmelpilze', 'Göbek kıvrımından alınan örneğin maya ve küf mantarları için kültürü', 'A thin sterile swab collects discharge and deposit from the depth of the umbilical pit, and the material is plated on fungal medium', 'Tankim sterilnim štapićem sakuplja se sekret i naslaga iz dubine pupčane jamice, a materijal se zasijava na podlogu za gljivice', 'Танким стерилним штапићем сакупља се секрет и наслага из дубине пупчане јамице, а материјал се засијава на подлогу за гљивице', 'Тонким стерильным тампоном собирают отделяемое и налёт из глубины пупочной ямки, материал засевают на среду для грибов', 'Mit einem dünnen sterilen Tupfer werden Sekret und Belag aus der Tiefe der Nabelgrube gewonnen und auf Pilznährboden ausgestrichen', 'İnce steril eküvyonla göbek çukurunun derininden akıntı ve birikinti alınır, örnek mantar besiyerine ekilir', 'Moisture, a whitish deposit and an unpleasant smell in the navel, itching and redness of the surrounding skin, complaints in excess weight, diabetes or long antibiotic use, the state after piercing', 'Vlaženje, bjelkasta naslaga i neprijatan miris u pupku, svrab i crvenilo kože oko njega, tegobe uz prekomjernu težinu, dijabetes ili dugo uzimanje antibiotika, stanje poslije pirsinga', 'Влажење, бјелкаста наслага и непријатан мирис у пупку, свраб и црвенило коже око њега, тегобе уз прекомјерну тежину, дијабетес или дуго узимање антибиотика, стање послије пирсинга', 'Влажность, белёсый налёт и неприятный запах в пупке, зуд и покраснение кожи вокруг, жалобы на фоне лишнего веса, диабета или длительного приёма антибиотиков, состояние после пирсинга', 'Nässen, weißlicher Belag und unangenehmer Geruch im Nabel, Juckreiz und Rötung der umgebenden Haut, Beschwerden bei Übergewicht, Diabetes oder langer Antibiotikaeinnahme, Zustand nach einem Piercing', 'Göbekte nemlenme, beyazımsı birikinti ve kötü koku, çevresindeki deride kaşıntı ve kızarıklık, fazla kilo, diyabet ya da uzun süreli antibiyotik kullanımıyla birlikte görülen yakınmalar, piercing sonrası durum', 'Do not wash the navel with soap or treat it with antiseptics before sampling, and do not apply creams or powders', 'Pupak prije uzimanja ne prati sapunom i ne tretirati antisepticima, ne nanositi kreme ni pudere', 'Пупак прије узимања не прати сапуном и не третирати антисептицима, не наносити креме ни пудере', 'Пупок перед забором не мыть с мылом и не обрабатывать антисептиками, кремы и присыпки не наносить', 'Den Nabel vor der Entnahme nicht mit Seife waschen und nicht mit Antiseptika behandeln, keine Cremes oder Puder auftragen', 'Örnek alınmadan önce göbek sabunla yıkanmamalı, antiseptikle temizlenmemeli, krem ve pudra sürülmemelidir', 'Growth of yeasts may be related to inflammation of the fold caused by moisture, and also occurs without inflammation. What follows from the finding is decided by the dermatologist', 'Porast kvasnica može biti povezan sa upalom nabora zbog vlage, a nalazi se i bez upale. Šta dalje sa nalazom, odlučuje dermatolog', 'Пораст квасница може бити повезан са упалом набора због влаге, а налази се и без упале. Шта даље са налазом, одлучује дерматолог', 'Рост дрожжевых грибов может быть связан с воспалением складки из-за влажности, а встречается и без воспаления. Что делать с находкой, решает дерматолог', 'Das Wachstum von Hefepilzen kann mit einer feuchtigkeitsbedingten Entzündung der Falte zusammenhängen und kommt auch ohne Entzündung vor. Was aus dem Befund folgt, entscheidet der Hautarzt', 'Maya mantarlarının üremesi nemden kaynaklanan kıvrım iltihabıyla ilişkili olabilir, iltihap olmadan da görülür. Bulguyla ne yapılacağına dermatolog karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'acid-phosphatase'), 'Blood test for an enzyme found in the prostate, in bone tissue and in blood cells', 'Analiza krvi na enzim koji se nalazi u prostati, koštanom tkivu i krvnim ćelijama', 'Анализа крви на ензим који се налази у простати, коштаном ткиву и крвним ћелијама', 'Анализ крови на фермент, который содержится в предстательной железе, костной ткани и клетках крови', 'Bluttest auf ein Enzym, das in der Prostata, im Knochengewebe und in Blutzellen vorkommt', 'Prostat, kemik dokusu ve kan hücrelerinde bulunan bir enzimi ölçen kan tetkiki', 'Venous blood draw; the sample is delivered to the laboratory quickly because enzyme activity falls during storage', 'Uzimanje venske krvi; uzorak se brzo dostavlja u laboratoriju jer aktivnost enzima opada tokom stajanja', 'Узимање венске крви; узорак се брзо доставља у лабораторију јер активност ензима опада током стајања', 'Забор венозной крови; пробу быстро доставляют в лабораторию, так как активность фермента снижается при хранении', 'Venöse Blutentnahme; die Probe wird rasch ins Labor gebracht, da die Enzymaktivität bei Lagerung abnimmt', 'Venöz kan alınır; enzim aktivitesi beklemeyle azaldığı için örnek hızlıca laboratuvara ulaştırılır', 'Prostate work-up in addition to other tests, assessment of bone metabolism in selected conditions, monitoring as directed by a urologist or haematologist', 'Obrada prostate uz ostale analize, procjena koštanog metabolizma kod pojedinih oboljenja, praćenje po uputu urologa ili hematologa', 'Обрада простате уз остале анализе, процјена коштаног метаболизма код појединих обољења, праћење по упуту уролога или хематолога', 'Обследование предстательной железы в дополнение к другим анализам, оценка костного обмена при отдельных заболеваниях, наблюдение по назначению уролога или гематолога', 'Abklärung der Prostata ergänzend zu anderen Untersuchungen, Beurteilung des Knochenstoffwechsels bei einzelnen Erkrankungen, Verlaufskontrolle auf Anordnung des Urologen oder Hämatologen', 'Diğer tetkiklerle birlikte prostat incelemesi, bazı hastalıklarda kemik metabolizmasının değerlendirilmesi, üroloji veya hematoloji yönlendirmesiyle izlem', 'Taken in the morning while fasting; for several days before there should be no rectal examination, prostate massage, catheterisation or cycling, and the doctor should be told about them', 'Uzima se ujutru natašte; nekoliko dana prije analize ne smije biti rektalnog pregleda, masaže prostate, kateterizacije ni vožnje bicikla, a o njima treba obavijestiti ljekara', 'Узима се ујутру наташте; неколико дана прије анализе не смије бити ректалног прегледа, масаже простате, катетеризације ни вожње бицикла, а о њима треба обавијестити љекара', 'Сдают утром натощак; за несколько дней до анализа не должно быть ректального исследования, массажа простаты, катетеризации и езды на велосипеде, а о них сообщите врачу', 'Morgens nüchtern; einige Tage zuvor sollten keine rektale Untersuchung, Prostatamassage, Katheterisierung oder Radfahren stattfinden, und der Arzt sollte darüber informiert werden', 'Sabah aç karnına alınır; tetkikten birkaç gün önce rektal muayene, prostat masajı, sonda takılması ve bisiklet kullanımı olmamalı, olduysa hekime bildirilmelidir', 'A change in activity may be related to processes in the prostate, bone tissue or blood cells, or to recent procedures in the pelvic area. The test is non-specific and does not establish a diagnosis on its own, it is assessed by a doctor', 'Promjena aktivnosti može biti povezana sa procesima u prostati, koštanom tkivu, krvnim ćelijama ili sa skorašnjim zahvatima u predjelu karlice. Pokazatelj je nespecifičan i sam po sebi ne postavlja dijagnozu, procjenjuje ga ljekar', 'Промјена активности може бити повезана са процесима у простати, коштаном ткиву, крвним ћелијама или са скорашњим захватима у предјелу карлице. Показатељ је неспецифичан и сам по себи не поставља дијагнозу, процјењује га љекар', 'Изменение активности может быть связано с процессами в предстательной железе, костной ткани, клетках крови или с недавними манипуляциями в области таза. Показатель неспецифичен и сам по себе диагноза не устанавливает, его оценивает врач', 'Eine veränderte Aktivität kann mit Vorgängen in der Prostata, im Knochengewebe oder in Blutzellen sowie mit kürzlichen Eingriffen im Beckenbereich zusammenhängen. Der Wert ist unspezifisch und stellt für sich allein keine Diagnose, die Beurteilung erfolgt durch den Arzt', 'Aktivitedeki değişiklik prostat, kemik dokusu veya kan hücrelerindeki süreçlerle ya da leğen bölgesindeki yakın zamanlı işlemlerle ilişkili olabilir. Test özgül değildir ve tek başına tanı koymaz, değerlendirmeyi hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ammonia-nh3'), 'Blood test for a nitrogen product of protein metabolism that the liver neutralises by converting it into urea', 'Analiza krvi na azotni proizvod razgradnje bjelančevina koji jetra obezvređuje pretvarajući ga u ureju', 'Анализа крви на азотни производ разградње бјеланчевина који јетра обезвређује претварајући га у уреју', 'Анализ крови на азотистый продукт обмена белков, который печень обезвреживает, превращая в мочевину', 'Bluttest auf ein stickstoffhaltiges Abbauprodukt des Eiweißstoffwechsels, das die Leber durch Umwandlung in Harnstoff entgiftet', 'Karaciğerin üreye dönüştürerek zararsız hale getirdiği, protein metabolizmasının azotlu ürününü ölçen kan tetkiki', 'Venous blood is drawn into a chilled tube and taken to the laboratory immediately, because the value rises quickly outside the body', 'Venska krv se uzima u ohlađenu epruvetu koja se odmah nosi u laboratoriju, jer vrijednost van organizma brzo raste', 'Венска крв се узима у охлађену епрувету која се одмах носи у лабораторију, јер вриједност ван организма брзо расте', 'Забор венозной крови в охлаждённую пробирку, её сразу доставляют в лабораторию: вне организма показатель быстро растёт', 'Venöse Blutentnahme in ein gekühltes Röhrchen, das sofort ins Labor gebracht wird, da der Wert außerhalb des Körpers rasch ansteigt', 'Venöz kan soğutulmuş tüpe alınır ve hemen laboratuvara ulaştırılır, çünkü değer vücut dışında hızla yükselir', 'Drowsiness, confusion and behaviour changes in liver disease, work-up of newborns and children with suspected inherited metabolic disorders, monitoring during treatment with certain medications', 'Pospanost, konfuzija i promjene ponašanja kod oboljenja jetre, obrada novorođenčadi i djece kod sumnje na nasljedne poremećaje metabolizma, praćenje tokom uzimanja pojedinih lijekova', 'Поспаност, конфузија и промјене понашања код обољења јетре, обрада новорођенчади и дјеце код сумње на насљедне поремећаје метаболизма, праћење током узимања појединих лијекова', 'Сонливость, спутанность сознания и изменения поведения при заболеваниях печени, обследование новорождённых и детей при подозрении на наследственные нарушения обмена, контроль на фоне приёма отдельных препаратов', 'Schläfrigkeit, Verwirrtheit und Verhaltensänderungen bei Lebererkrankungen, Abklärung bei Neugeborenen und Kindern mit Verdacht auf angeborene Stoffwechselstörungen, Kontrolle unter bestimmten Medikamenten', 'Karaciğer hastalıklarında uykuya eğilim, bilinç bulanıklığı ve davranış değişiklikleri, kalıtsal metabolizma hastalığı şüphesiyle yenidoğan ve çocukların incelenmesi, bazı ilaçlar kullanılırken izlem', 'Taken in the morning while fasting; do not smoke before the draw, sit quietly and do not clench the fist, and tell the doctor about any medications', 'Uzima se ujutru natašte; prije vađenja ne pušiti, mirno sjediti i ne stiskati šaku, a o lijekovima koje uzimate obavijestiti ljekara', 'Узима се ујутру наташте; прије вађења не пушити, мирно сједити и не стискати шаку, а о лијековима које узимате обавијестити љекара', 'Сдают утром натощак; перед забором не курить, спокойно посидеть и не сжимать кулак, о принимаемых препаратах сообщить врачу', 'Morgens nüchtern; vor der Entnahme nicht rauchen, ruhig sitzen und die Faust nicht ballen, eingenommene Medikamente dem Arzt mitteilen', 'Sabah aç karnına alınır; kan alınmadan önce sigara içilmemeli, sakin oturulmalı ve yumruk sıkılmamalı, kullanılan ilaçlar hekime bildirilmelidir', 'An increase may be related to liver function, inherited features of metabolism, certain medications, or to breaches of sampling and handling conditions. The result is assessed by a doctor together with the patient''s condition and other tests', 'Povišene vrijednosti mogu biti povezane sa radom jetre, nasljednim osobenostima metabolizma, uzimanjem pojedinih lijekova ili sa greškama pri uzimanju i čuvanju uzorka. Nalaz procjenjuje ljekar zajedno sa stanjem pacijenta i ostalim analizama', 'Повишене вриједности могу бити повезане са радом јетре, насљедним особеностима метаболизма, узимањем појединих лијекова или са грешкама при узимању и чувању узорка. Налаз процјењује љекар заједно са стањем пацијента и осталим анализама', 'Повышение может быть связано с работой печени, наследственными особенностями обмена, приёмом некоторых лекарств или с нарушением условий забора и хранения пробы. Результат оценивает врач вместе с состоянием пациента и другими анализами', 'Erhöhte Werte können mit der Leberfunktion, angeborenen Besonderheiten des Stoffwechsels, bestimmten Medikamenten oder mit Fehlern bei Entnahme und Lagerung der Probe zusammenhängen. Die Beurteilung nimmt der Arzt zusammen mit dem Zustand und weiteren Befunden vor', 'Yükseklik karaciğerin çalışmasıyla, kalıtsal metabolizma özellikleriyle, bazı ilaçlarla ya da örneğin alınma ve saklanma koşullarındaki hatalarla ilişkili olabilir. Sonucu hekim, hastanın durumu ve diğer tetkiklerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'beta-2-microglobulin'), 'Test for a small protein from the surface of cells, whose level depends on cell turnover and on filtration in the kidneys', 'Analiza malog proteina sa površine ćelija, čiji nivo zavisi od brzine obnavljanja ćelija i od filtracije u bubrezima', 'Анализа малог протеина са површине ћелија, чији ниво зависи од брзине обнављања ћелија и од филтрације у бубрезима', 'Анализ на небольшой белок с поверхности клеток, уровень которого зависит от скорости обновления клеток и от фильтрации в почках', 'Untersuchung eines kleinen Proteins von der Zelloberfläche, dessen Spiegel vom Zellumsatz und von der Filtration in den Nieren abhängt', 'Düzeyi hücre yenilenme hızına ve böbreklerdeki filtrasyona bağlı olan, hücre yüzeyindeki küçük bir proteinin ölçümü', 'Venous blood draw; when tubular kidney function is assessed, the same protein is measured in a urine sample', 'Uzimanje venske krvi; kada se procjenjuje rad bubrežnih tubula, isti protein se određuje i u uzorku mokraće', 'Узимање венске крви; када се процјењује рад бубрежних тубула, исти протеин се одређује и у узорку мокраће', 'Забор венозной крови; при оценке работы почечных канальцев тот же белок определяют в порции мочи', 'Venöse Blutentnahme; zur Beurteilung der Nierentubuli wird dasselbe Protein auch im Urin bestimmt', 'Venöz kan alınır; böbrek tübül işlevi değerlendirilirken aynı protein idrar örneğinde de ölçülür', 'Monitoring in diseases of the blood and lymphatic system, assessment of tubular kidney function, follow-up in patients on dialysis, testing as directed by a haematologist or nephrologist', 'Praćenje kod oboljenja krvi i limfnog sistema, procjena tubularne funkcije bubrega, praćenje pacijenata na dijalizi, obrada po uputu hematologa ili nefrologa', 'Праћење код обољења крви и лимфног система, процјена тубуларне функције бубрега, праћење пацијената на дијализи, обрада по упуту хематолога или нефролога', 'Наблюдение при заболеваниях крови и лимфатической системы, оценка канальцевой функции почек, наблюдение у пациентов на диализе, обследование по назначению гематолога или нефролога', 'Verlaufskontrolle bei Erkrankungen des Blutes und des Lymphsystems, Beurteilung der tubulären Nierenfunktion, Kontrolle bei Dialysepatienten, Abklärung auf Anordnung des Hämatologen oder Nephrologen', 'Kan ve lenf sistemi hastalıklarında izlem, böbrek tübül işlevinin değerlendirilmesi, diyaliz hastalarının takibi, hematoloji veya nefroloji yönlendirmesiyle inceleme', 'No special preparation is usually needed and blood is most often taken in the morning; for the urine test a fresh sample is collected according to the laboratory''s instructions', 'Posebna priprema obično nije potrebna, krv se najčešće vadi ujutru; za analizu mokraće uzima se svjež uzorak prema uputstvu laboratorije', 'Посебна припрема обично није потребна, крв се најчешће вади ујутру; за анализу мокраће узима се свјеж узорак према упутству лабораторије', 'Специальной подготовки обычно не требуется, кровь чаще сдают утром; для анализа мочи берут свежую порцию по инструкции лаборатории', 'Eine besondere Vorbereitung ist meist nicht nötig, Blut wird überwiegend morgens entnommen; für die Urinuntersuchung wird eine frische Probe nach Anweisung des Labors gesammelt', 'Genellikle özel hazırlık gerekmez, kan çoğunlukla sabah alınır; idrar tetkiki için laboratuvarın talimatına göre taze örnek verilir', 'Changes may be related to cell turnover, inflammation, infections or kidney function. The marker is non-specific, and a doctor interprets it only together with other investigations and the clinical picture', 'Promjene mogu biti povezane sa brzinom obnavljanja ćelija, upalom, infekcijama ili radom bubrega. Pokazatelj je nespecifičan, pa njegovo značenje ljekar utvrđuje samo uz ostale nalaze i kliničku sliku', 'Промјене могу бити повезане са брзином обнављања ћелија, упалом, инфекцијама или радом бубрега. Показатељ је неспецифичан, па његово значење љекар утврђује само уз остале налазе и клиничку слику', 'Изменения могут быть связаны со скоростью обновления клеток, воспалением, инфекциями или работой почек. Показатель неспецифичен, его значение врач определяет только вместе с другими исследованиями и клинической картиной', 'Veränderungen können mit dem Zellumsatz, Entzündungen, Infektionen oder der Nierenfunktion zusammenhängen. Der Wert ist unspezifisch, seine Bedeutung bestimmt der Arzt nur zusammen mit weiteren Befunden und dem klinischen Bild', 'Değişiklikler hücre yenilenme hızı, iltihap, enfeksiyonlar veya böbrek işleviyle ilişkili olabilir. Belirteç özgül değildir, anlamını hekim yalnızca diğer tetkikler ve klinik tabloyla birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cholinesterase'), 'Blood test for an enzyme produced by the liver that takes part in breaking down a number of substances and medications', 'Analiza krvi na enzim koji stvara jetra i koji učestvuje u razgradnji niza materija i lijekova', 'Анализа крви на ензим који ствара јетра и који учествује у разградњи низа материја и лијекова', 'Анализ крови на фермент, который вырабатывает печень и который участвует в расщеплении ряда веществ и препаратов', 'Bluttest auf ein von der Leber gebildetes Enzym, das am Abbau verschiedener Substanzen und Medikamente beteiligt ist', 'Karaciğerin ürettiği ve bazı maddelerle ilaçların parçalanmasında görev alan bir enzimi ölçen kan tetkiki', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert wenige Minuten', 'Venöz kan alınır, birkaç dakika sürer', 'Assessment of the liver''s synthetic function, suspected contact with organophosphate compounds, preparation for anaesthesia when the patient or relatives previously had a prolonged recovery from it', 'Procjena sintetske funkcije jetre, sumnja na kontakt sa organofosfornim jedinjenjima, priprema za anesteziju kada su pacijent ili srodnici ranije imali produženo buđenje', 'Процјена синтетске функције јетре, сумња на контакт са органофосфорним једињењима, припрема за анестезију када су пацијент или сродници раније имали продужено буђење', 'Оценка синтетической функции печени, подозрение на контакт с фосфорорганическими соединениями, подготовка к наркозу, если у пациента или его родственников пробуждение после наркоза раньше затягивалось', 'Beurteilung der Syntheseleistung der Leber, Verdacht auf Kontakt mit Organophosphatverbindungen, Vorbereitung auf eine Narkose, wenn beim Patienten oder in der Familie das Aufwachen früher verlängert war', 'Karaciğerin sentez işlevinin değerlendirilmesi, organik fosforlu bileşiklerle temas şüphesi, hastada ya da yakınlarında daha önce anesteziden uyanmanın uzadığı durumlarda ameliyat hazırlığı', 'No special preparation is usually required and the sample is most often taken in the morning; be sure to tell the doctor about work with pesticides and about any medications', 'Posebna priprema obično nije potrebna, uzorak se najčešće uzima ujutru; obavezno obavijestite ljekara o radu sa pesticidima i o lijekovima koje uzimate', 'Посебна припрема обично није потребна, узорак се најчешће узима ујутру; обавезно обавијестите љекара о раду са пестицидима и о лијековима које узимате', 'Специальной подготовки обычно не требуется, сдают чаще утром; обязательно сообщите врачу о работе с ядохимикатами и о принимаемых препаратах', 'Eine besondere Vorbereitung ist meist nicht nötig, die Entnahme erfolgt überwiegend morgens; Arbeit mit Pflanzenschutzmitteln und eingenommene Medikamente unbedingt dem Arzt mitteilen', 'Genellikle özel hazırlık gerekmez, örnek çoğunlukla sabah alınır; tarım ilaçlarıyla çalışma ve kullanılan ilaçlar mutlaka hekime bildirilmelidir', 'Reduced activity may be related to liver function, contact with organophosphates, pregnancy, certain medications or an inherited variant of the enzyme. The meaning of the result, especially before surgery, is assessed by a doctor', 'Smanjena aktivnost može biti povezana sa radom jetre, kontaktom sa organofosfornim materijama, trudnoćom, uzimanjem pojedinih lijekova ili nasljednom varijantom enzima. Značenje nalaza, naročito prije operacije, procjenjuje ljekar', 'Смањена активност може бити повезана са радом јетре, контактом са органофосфорним материјама, трудноћом, узимањем појединих лијекова или насљедном варијантом ензима. Значење налаза, нарочито прије операције, процјењује љекар', 'Сниженная активность может быть связана с работой печени, контактом с фосфорорганическими веществами, беременностью, приёмом ряда препаратов или наследственным вариантом фермента. Значение результата, особенно перед операцией, оценивает врач', 'Eine verminderte Aktivität kann mit der Leberfunktion, Kontakt mit Organophosphaten, einer Schwangerschaft, bestimmten Medikamenten oder einer erblichen Enzymvariante zusammenhängen. Die Bedeutung des Befundes, besonders vor einer Operation, beurteilt der Arzt', 'Aktivitenin düşük olması karaciğerin çalışmasıyla, organik fosforlu maddelerle temasla, gebelikle, bazı ilaçlarla veya enzimin kalıtsal bir varyantıyla ilişkili olabilir. Sonucun anlamını, özellikle ameliyat öncesinde, hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'lactate'), 'Blood test for a product of glucose metabolism without oxygen, used to judge the oxygen supply to tissues', 'Analiza krvi na proizvod razgradnje glukoze bez kiseonika, po kojem se procjenjuje snabdijevanje tkiva kiseonikom', 'Анализа крви на производ разградње глукозе без кисеоника, по којем се процјењује снабдијевање ткива кисеоником', 'Анализ крови на продукт обмена глюкозы без участия кислорода, по которому судят о снабжении тканей кислородом', 'Bluttest auf ein Produkt des Glukoseabbaus ohne Sauerstoff, mit dem die Sauerstoffversorgung der Gewebe beurteilt wird', 'Dokulara oksijen gidişini değerlendirmek için bakılan, glukozun oksijensiz yıkım ürününü ölçen kan tetkiki', 'Venous blood is drawn without a prolonged tourniquet and the tube goes to the laboratory at once; in hospital the value is often measured in arterial blood together with blood gases', 'Venska krv se vadi bez dugog stezanja poveskom, a epruveta odmah ide u laboratoriju; u bolnici se vrijednost često određuje iz arterijske krvi zajedno sa gasnim analizama', 'Венска крв се вади без дугог стезања повеском, а епрувета одмах иде у лабораторију; у болници се вриједност често одређује из артеријске крви заједно са гасним анализама', 'Забор венозной крови без долгого наложения жгута, пробирку сразу доставляют в лабораторию; в стационаре показатель нередко определяют из артериальной крови вместе с газами', 'Venöse Blutentnahme ohne lange Stauung, das Röhrchen geht sofort ins Labor; im Krankenhaus wird der Wert häufig aus arteriellem Blut zusammen mit den Blutgasen bestimmt', 'Turnike uzun süre bağlanmadan venöz kan alınır ve tüp hemen laboratuvara gönderilir; hastanede değer sıklıkla kan gazlarıyla birlikte atardamar kanından ölçülür', 'Severe acute conditions and in-hospital monitoring, suspected inherited metabolic disorders, unexplained breathlessness and weakness, assessment of exercise tolerance, monitoring during treatment with certain medications', 'Teška akutna stanja i praćenje u bolnici, sumnja na nasljedne poremećaje metabolizma, neobjašnjiva zaduha i slabost, procjena podnošenja fizičkog napora, praćenje uz pojedine lijekove', 'Тешка акутна стања и праћење у болници, сумња на насљедне поремећаје метаболизма, необјашњива задуха и слабост, процјена подношења физичког напора, праћење уз поједине лијекове', 'Тяжёлые острые состояния и наблюдение в стационаре, подозрение на наследственные нарушения обмена, необъяснимая одышка и слабость, оценка переносимости физической нагрузки, контроль на фоне отдельных препаратов', 'Schwere akute Zustände und Überwachung im Krankenhaus, Verdacht auf angeborene Stoffwechselstörungen, unklare Atemnot und Schwäche, Beurteilung der Belastbarkeit, Kontrolle unter bestimmten Medikamenten', 'Ağır akut durumlar ve hastanede izlem, kalıtsal metabolizma hastalığı şüphesi, açıklanamayan nefes darlığı ve halsizlik, efor toleransının değerlendirilmesi, bazı ilaçlar kullanılırken izlem', 'Sit quietly for about a quarter of an hour before the draw, do not clench the fist or tense the arm; avoid intense exercise and alcohol the day before', 'Prije vađenja mirno sjediti oko četvrt sata, ne stiskati šaku i ne naprezati ruku; dan ranije izbjegavati intenzivan napor i alkohol', 'Прије вађења мирно сједити око четврт сата, не стискати шаку и не напрезати руку; дан раније избјегавати интензиван напор и алкохол', 'Перед забором спокойно посидеть около четверти часа, не сжимать кулак и не напрягать руку; накануне избегать интенсивных нагрузок и алкоголя', 'Vor der Entnahme etwa eine Viertelstunde ruhig sitzen, die Faust nicht ballen und den Arm nicht anspannen; am Vortag starke Belastung und Alkohol meiden', 'Kan alınmadan önce yaklaşık çeyrek saat sakin oturulmalı, yumruk sıkılmamalı ve kol zorlanmamalıdır; bir gün önce yoğun efor ve alkolden kaçınılmalıdır', 'An increase may be related to insufficient oxygen delivery to tissues, physical exertion, liver and kidney function, certain medications or the sampling conditions. The result is assessed by a doctor together with the clinical picture and the acid-base values', 'Povišene vrijednosti mogu biti povezane sa nedovoljnim dotokom kiseonika u tkiva, fizičkim naporom, radom jetre i bubrega, pojedinim lijekovima ili uslovima uzimanja uzorka. Nalaz procjenjuje ljekar uz kliničku sliku i acidobazne pokazatelje', 'Повишене вриједности могу бити повезане са недовољним дотоком кисеоника у ткива, физичким напором, радом јетре и бубрега, појединим лијековима или условима узимања узорка. Налаз процјењује љекар уз клиничку слику и ацидобазне показатеље', 'Повышение может быть связано с недостаточным поступлением кислорода в ткани, физической нагрузкой, работой печени и почек, приёмом некоторых препаратов или с условиями забора. Результат оценивает врач вместе с клинической картиной и кислотно-щелочными показателями', 'Erhöhte Werte können mit einer unzureichenden Sauerstoffversorgung der Gewebe, körperlicher Belastung, der Leber- und Nierenfunktion, bestimmten Medikamenten oder den Entnahmebedingungen zusammenhängen. Die Beurteilung erfolgt durch den Arzt zusammen mit dem klinischen Bild und den Säure-Basen-Werten', 'Yükseklik dokulara oksijen gidişinin yetersizliğiyle, fiziksel eforla, karaciğer ve böbrek işleviyle, bazı ilaçlarla ya da örnek alma koşullarıyla ilişkili olabilir. Sonucu hekim klinik tablo ve asit-baz değerleriyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'acid-base-status-ph-pco2-po2'), 'Measurement of blood gases and acid-base balance, showing how the lungs exchange oxygen and carbon dioxide and how the balance of acids and bases is held', 'Ispitivanje gasova u krvi i acidobazne ravnoteže: pokazuje kako pluća razmjenjuju kiseonik i ugljen-dioksid i kako se održava odnos kiselina i baza', 'Испитивање гасова у крви и ацидобазне равнотеже: показује како плућа размјењују кисеоник и угљен-диоксид и како се одржава однос киселина и база', 'Исследование газов крови и кислотно-щелочного равновесия: показывает, как лёгкие обеспечивают обмен кислорода и углекислого газа и как удерживается баланс кислот и оснований', 'Untersuchung der Blutgase und des Säure-Basen-Haushalts: Sie zeigt, wie die Lunge Sauerstoff und Kohlendioxid austauscht und wie das Verhältnis von Säuren und Basen gehalten wird', 'Kan gazları ve asit-baz dengesinin incelenmesi; akciğerlerin oksijen ile karbondioksit değişimini ve asit-baz dengesinin nasıl korunduğunu gösterir', 'Blood is taken from an artery, usually at the wrist, or from a capillary into a special syringe and measured on the analyser at once; the draw takes a few minutes, can be more uncomfortable than usual, and the site is pressed afterwards', 'Krv se vadi iz arterije, najčešće na zglobu ruke, ili iz kapilare u poseban špric i odmah mjeri na aparatu; vađenje traje nekoliko minuta, može biti neprijatnije nego obično, a ubodno mjesto se poslije pritiska', 'Крв се вади из артерије, најчешће на зглобу руке, или из капиларе у посебан шприц и одмах мјери на апарату; вађење траје неколико минута, може бити непријатније него обично, а убодно мјесто се послије притиска', 'Кровь берут из артерии, чаще на запястье, или из капилляра в специальный шприц и сразу измеряют на приборе; забор занимает несколько минут, бывает чувствительнее обычного, после него место прижимают', 'Blut wird aus einer Arterie, meist am Handgelenk, oder aus einer Kapillare in eine spezielle Spritze entnommen und sofort am Gerät gemessen; die Entnahme dauert wenige Minuten, kann unangenehmer sein als sonst, und die Stelle wird anschließend komprimiert', 'Kan, çoğunlukla bilekten atardamardan ya da kılcal damardan özel bir enjektöre alınır ve hemen cihazda ölçülür; işlem birkaç dakika sürer, her zamankinden rahatsız edici olabilir, sonrasında iğne yerine bası uygulanır', 'Breathlessness and respiratory failure, severe acute conditions, monitoring in chronic lung disease, starting and adjusting oxygen therapy, work-up of metabolic disturbances', 'Zaduha i respiratorna insuficijencija, teška akutna stanja, praćenje kod hroničnih bolesti pluća, uvođenje i kontrola terapije kiseonikom, obrada kod poremećaja metabolizma', 'Задуха и респираторна инсуфицијенција, тешка акутна стања, праћење код хроничних болести плућа, увођење и контрола терапије кисеоником, обрада код поремећаја метаболизма', 'Одышка и дыхательная недостаточность, тяжёлые острые состояния, наблюдение при хронических болезнях лёгких, подбор и контроль кислородотерапии, обследование при нарушениях обмена веществ', 'Atemnot und respiratorische Insuffizienz, schwere akute Zustände, Verlaufskontrolle bei chronischen Lungenerkrankungen, Einstellung und Kontrolle der Sauerstofftherapie, Abklärung von Stoffwechselstörungen', 'Nefes darlığı ve solunum yetmezliği, ağır akut durumlar, kronik akciğer hastalıklarında izlem, oksijen tedavisinin ayarlanması ve kontrolü, metabolik bozuklukların incelenmesi', 'No special preparation; breathe calmly as usual before the draw and do not change the oxygen flow, and tell the staff about oxygen therapy and about blood-thinning medications', 'Posebne pripreme nema; prije vađenja treba mirno disati kao i inače i ne mijenjati protok kiseonika, a osoblju reći za terapiju kiseonikom i za lijekove koji razrjeđuju krv', 'Посебне припреме нема; прије вађења треба мирно дисати као и иначе и не мијењати проток кисеоника, а особљу рећи за терапију кисеоником и за лијекове који разрјеђују крв', 'Специальной подготовки нет; перед забором нужно спокойно подышать в привычном режиме и не менять поток кислорода, а о кислородотерапии и препаратах, разжижающих кровь, сообщить персоналу', 'Keine besondere Vorbereitung; vor der Entnahme ruhig wie gewohnt atmen und den Sauerstofffluss nicht verändern, dem Personal Sauerstofftherapie und blutverdünnende Medikamente mitteilen', 'Özel hazırlık yoktur; kan alınmadan önce her zamanki gibi sakin nefes alınmalı ve oksijen akışı değiştirilmemeli, oksijen tedavisi ile kan sulandırıcı ilaçlar personele bildirilmelidir', 'Changes may be related to the function of the lungs or kidneys, to metabolism or to the effect of medications. The values are interpreted only together and in the context of the patient''s condition, which is the doctor''s task', 'Promjene mogu biti povezane sa radom pluća i bubrega, metabolizmom ili djelovanjem lijekova. Vrijednosti se tumače samo zajedno i u kontekstu stanja pacijenta, a to radi ljekar', 'Промјене могу бити повезане са радом плућа и бубрега, метаболизмом или дјеловањем лијекова. Вриједности се тумаче само заједно и у контексту стања пацијента, а то ради љекар', 'Изменения могут быть связаны с работой лёгких, почек, обменом веществ или влиянием лекарств. Показатели трактуются только вместе и в контексте состояния пациента, этим занимается врач', 'Veränderungen können mit der Funktion von Lunge und Nieren, dem Stoffwechsel oder der Wirkung von Medikamenten zusammenhängen. Die Werte werden nur gemeinsam und im Zusammenhang mit dem Zustand beurteilt, das übernimmt der Arzt', 'Değişiklikler akciğer ve böbrek işleviyle, metabolizmayla ya da ilaçların etkisiyle ilişkili olabilir. Değerler yalnızca birlikte ve hastanın durumu bağlamında yorumlanır, bunu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'apolipoprotein-b'), 'Blood test for the carrier protein of atherogenic lipoprotein particles: it reflects the number of such particles rather than the mass of cholesterol they carry', 'Analiza krvi na protein nosač aterogenih lipoproteinskih čestica: odražava broj tih čestica, a ne masu holesterola u njima', 'Анализа крви на протеин носач атерогених липопротеинских честица: одражава број тих честица, а не масу холестерола у њима', 'Анализ крови на белок-носитель атерогенных липопротеиновых частиц: отражает количество таких частиц, а не массу холестерина в них', 'Bluttest auf das Trägerprotein atherogener Lipoproteinpartikel: Er zeigt die Anzahl dieser Partikel und nicht die Menge des darin enthaltenen Cholesterins', 'Aterojenik lipoprotein partiküllerinin taşıyıcı proteinini ölçen kan tetkiki: içlerindeki kolesterol miktarını değil, bu partiküllerin sayısını yansıtır', 'Venous blood draw, usually together with the lipid profile', 'Uzimanje venske krvi, obično zajedno sa lipidnim statusom', 'Узимање венске крви, обично заједно са липидним статусом', 'Забор венозной крови, обычно вместе с липидным профилем', 'Venöse Blutentnahme, üblicherweise zusammen mit dem Lipidprofil', 'Genellikle lipid profiliyle birlikte venöz kan alınır', 'Refining cardiovascular risk, raised triglycerides, a mismatch between the LDL level and the overall picture, inherited lipid disorders in the family, monitoring during treatment', 'Preciznija procjena kardiovaskularnog rizika, povišeni trigliceridi, neslaganje između vrijednosti LDL i ukupne slike, nasljedni poremećaji masnoća u porodici, praćenje tokom terapije', 'Прецизнија процјена кардиоваскуларног ризика, повишени триглицериди, неслагање између вриједности ЛДЛ и укупне слике, насљедни поремећаји масноћа у породици, праћење током терапије', 'Уточнение сердечно-сосудистого риска, повышенные триглицериды, расхождение между уровнем ЛПНП и общей картиной, наследственные нарушения липидного обмена в семье, контроль на фоне терапии', 'Genauere Einschätzung des kardiovaskulären Risikos, erhöhte Triglyzeride, Abweichung zwischen LDL-Wert und Gesamtbild, erbliche Fettstoffwechselstörungen in der Familie, Kontrolle unter Therapie', 'Kalp damar riskinin daha kesin değerlendirilmesi, yüksek trigliserid, LDL değeri ile genel tablonun uyuşmaması, ailede kalıtsal yağ metabolizması bozukluğu, tedavi sırasında izlem', 'Preparation is the same as for the lipid profile: taken in the morning, fasting or non-fasting, with the exact regimen confirmed with the referring doctor; avoid alcohol and fatty food the day before', 'Priprema je ista kao za lipidni status: uzorak se uzima ujutru, natašte ili bez gladovanja, a tačan režim potvrdite kod ljekara koji je uputio; dan ranije izbjegavati alkohol i masnu hranu', 'Припрема је иста као за липидни статус: узорак се узима ујутру, наташте или без гладовања, а тачан режим потврдите код љекара који је упутио; дан раније избјегавати алкохол и масну храну', 'Подготовка такая же, как для липидного профиля: сдают утром, натощак или без голодания, точный режим уточните у направившего врача; накануне избегать алкоголя и жирной пищи', 'Die Vorbereitung entspricht der für das Lipidprofil: Entnahme morgens, nüchtern oder ohne Fasten, das genaue Vorgehen mit dem überweisenden Arzt abklären; am Vortag Alkohol und fettes Essen meiden', 'Hazırlık lipid profiliyle aynıdır: örnek sabah, açlıkta ya da açlık olmadan alınır, kesin düzeni yönlendiren hekimle netleştirin; bir gün önce alkol ve yağlı yiyeceklerden kaçının', 'Changes may be related to features of lipid metabolism, diet, heredity or ongoing treatment. Cardiovascular risk is assessed by a doctor together with the lipid profile and other factors, and no conclusion is drawn from a single value', 'Promjene mogu biti povezane sa osobenostima metabolizma masti, ishranom, nasljeđem ili terapijom koja se sprovodi. Kardiovaskularni rizik ljekar procjenjuje zajedno sa lipidnim statusom i ostalim faktorima, a po jednom pokazatelju se zaključak ne donosi', 'Промјене могу бити повезане са особеностима метаболизма масти, исхраном, насљеђем или терапијом која се спроводи. Кардиоваскуларни ризик љекар процјењује заједно са липидним статусом и осталим факторима, а по једном показатељу се закључак не доноси', 'Изменения могут быть связаны с особенностями липидного обмена, питанием, наследственностью или проводимым лечением. Сердечно-сосудистый риск врач оценивает вместе с липидным профилем и другими факторами, по одному показателю вывод не делают', 'Veränderungen können mit Besonderheiten des Fettstoffwechsels, der Ernährung, der Vererbung oder der laufenden Therapie zusammenhängen. Das kardiovaskuläre Risiko beurteilt der Arzt zusammen mit dem Lipidprofil und weiteren Faktoren, aus einem einzelnen Wert wird kein Schluss gezogen', 'Değişiklikler yağ metabolizmasının özellikleriyle, beslenmeyle, kalıtımla veya sürdürülen tedaviyle ilişkili olabilir. Kalp damar riskini hekim lipid profili ve diğer etkenlerle birlikte değerlendirir, tek bir değerden sonuç çıkarılmaz')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ascitic-fluid-analysis'), 'Laboratory examination of fluid collected in the abdominal cavity, with assessment of protein, albumin, cell content and selected enzymes', 'Laboratorijsko ispitivanje tečnosti nakupljene u trbušnoj duplji, sa procjenom proteina, albumina, ćelijskog sastava i pojedinih enzima', 'Лабораторијско испитивање течности накупљене у трбушној дупљи, са процјеном протеина, албумина, ћелијског састава и појединих ензима', 'Лабораторное исследование жидкости, скопившейся в брюшной полости, с оценкой белка, альбумина, клеточного состава и отдельных ферментов', 'Laboruntersuchung der in der Bauchhöhle angesammelten Flüssigkeit mit Bestimmung von Eiweiß, Albumin, Zellgehalt und einzelnen Enzymen', 'Karın boşluğunda biriken sıvının laboratuvarda incelenmesi; protein, albümin, hücre içeriği ve bazı enzimler değerlendirilir', 'The fluid is obtained by the doctor through a puncture of the abdominal wall under local anaesthesia, usually with ultrasound guidance; part of the material is sent to the laboratory and the puncture itself takes a few minutes', 'Tečnost uzima ljekar punkcijom trbušnog zida u lokalnoj anesteziji, najčešće uz ultrazvučnu kontrolu; dio materijala se šalje u laboratoriju, a sama punkcija traje nekoliko minuta', 'Течност узима љекар пункцијом трбушног зида у локалној анестезији, најчешће уз ултразвучну контролу; дио материјала се шаље у лабораторију, а сама пункција траје неколико минута', 'Жидкость получает врач при проколе брюшной стенки под местным обезболиванием, чаще под контролем УЗИ; часть материала отправляют в лабораторию, сам прокол занимает несколько минут', 'Die Flüssigkeit gewinnt der Arzt durch eine Punktion der Bauchwand in örtlicher Betäubung, meist unter Ultraschallkontrolle; ein Teil des Materials geht ins Labor, die Punktion selbst dauert wenige Minuten', 'Sıvıyı hekim, çoğunlukla ultrason eşliğinde ve lokal anesteziyle karın duvarından girerek alır; materyalin bir bölümü laboratuvara gönderilir, işlemin kendisi birkaç dakika sürer', 'Newly found fluid in the abdomen, clarifying why it accumulates, suspected infection of the fluid, follow-up in chronic diseases of the liver, heart and kidneys', 'Prvi put uočena tečnost u trbuhu, razjašnjavanje razloga njenog nakupljanja, sumnja na infekciju tečnosti, praćenje kod hroničnih bolesti jetre, srca i bubrega', 'Први пут уочена течност у трбуху, разјашњавање разлога њеног накупљања, сумња на инфекцију течности, праћење код хроничних болести јетре, срца и бубрега', 'Впервые выявленное скопление жидкости в животе, уточнение причин её накопления, подозрение на инфицирование жидкости, наблюдение при хронических болезнях печени, сердца и почек', 'Erstmals festgestellte Flüssigkeit im Bauchraum, Klärung der Ursache ihrer Ansammlung, Verdacht auf eine Infektion der Flüssigkeit, Verlaufskontrolle bei chronischen Erkrankungen von Leber, Herz und Nieren', 'Karında ilk kez saptanan sıvı, birikme nedeninin araştırılması, sıvının enfekte olduğu şüphesi, karaciğer, kalp ve böbreklerin kronik hastalıklarında izlem', 'There is no preparation for the laboratory part, and the conditions of the puncture are explained by the doctor performing it, who usually asks the patient to empty the bladder and to report blood-thinning medications', 'Za laboratorijski dio pripreme nema, a uslove punkcije objašnjava ljekar koji je izvodi: obično se traži pražnjenje mokraćne bešike i podatak o lijekovima koji razrjeđuju krv', 'За лабораторијски дио припреме нема, а услове пункције објашњава љекар који је изводи: обично се тражи пражњење мокраћне бешике и податак о лијековима који разрјеђују крв', 'К лабораторной части подготовки нет, условия прокола объясняет выполняющий его врач: обычно просят опорожнить мочевой пузырь и сообщить о препаратах, разжижающих кровь', 'Für den Laborteil gibt es keine Vorbereitung, die Bedingungen der Punktion erklärt der durchführende Arzt: Üblicherweise wird um das Entleeren der Blase und um Angaben zu blutverdünnenden Medikamenten gebeten', 'Laboratuvar bölümü için hazırlık yoktur, işlemin koşullarını uygulayan hekim anlatır: genellikle mesanenin boşaltılması ve kan sulandırıcı ilaçların bildirilmesi istenir', 'The composition of the fluid helps the doctor tell apart the mechanisms behind its accumulation: pressure in the liver vessels, protein loss, inflammation or infection. The conclusion is drawn by the treating doctor, comparing the result with blood tests and imaging findings', 'Sastav tečnosti pomaže ljekaru da razluči mehanizme njenog nakupljanja: pritisak u krvnim sudovima jetre, gubitak proteina, upalu ili infekciju. Zaključak donosi ljekar koji liječi pacijenta, upoređujući nalaz sa analizama krvi i nalazima snimanja', 'Састав течности помаже љекару да разлучи механизме њеног накупљања: притисак у крвним судовима јетре, губитак протеина, упалу или инфекцију. Закључак доноси љекар који лијечи пацијента, упоређујући налаз са анализама крви и налазима снимања', 'Состав жидкости помогает врачу различить механизмы её накопления: давление в сосудах печени, потери белка, воспаление или инфекцию. Вывод делает лечащий врач, сопоставляя результат с анализами крови и данными обследования', 'Die Zusammensetzung der Flüssigkeit hilft dem Arzt, die Mechanismen der Ansammlung zu unterscheiden: Druck in den Lebergefäßen, Eiweißverlust, Entzündung oder Infektion. Die Beurteilung nimmt der behandelnde Arzt im Vergleich mit Blutwerten und Bildgebung vor', 'Sıvının bileşimi hekime birikme mekanizmalarını ayırt etmede yardımcı olur: karaciğer damarlarındaki basınç, protein kaybı, iltihap veya enfeksiyon. Sonucu, kan tetkikleri ve görüntüleme bulgularıyla karşılaştırarak tedaviyi yürüten hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'csf-biochemical-analysis'), 'Measurement of biochemical values in cerebrospinal fluid: total protein, glucose, chlorides and, if needed, others', 'Određivanje biohemijskih pokazatelja u likvoru: ukupnih proteina, glukoze, hlorida i po potrebi drugih', 'Одређивање биохемијских показатеља у ликвору: укупних протеина, глукозе, хлорида и по потреби других', 'Определение в спинномозговой жидкости биохимических показателей: общего белка, глюкозы, хлоридов и при необходимости других', 'Bestimmung biochemischer Werte im Liquor: Gesamteiweiß, Glukose, Chloride und bei Bedarf weitere', 'Beyin omurilik sıvısında biyokimyasal değerlerin ölçülmesi: total protein, glukoz, klorür ve gerekirse diğerleri', 'The fluid is obtained by the doctor during a lumbar puncture under local anaesthesia and a small portion goes to the laboratory at once; glucose is usually compared with blood taken at the same time', 'Likvor uzima ljekar lumbalnom punkcijom u lokalnoj anesteziji, a mala količina odmah ide u laboratoriju; glukoza se obično poredi sa krvlju uzetom u isto vrijeme', 'Ликвор узима љекар лумбалном пункцијом у локалној анестезији, а мала количина одмах иде у лабораторију; глукоза се обично пореди са крвљу узетом у исто вријеме', 'Ликвор получает врач при люмбальной пункции под местным обезболиванием, небольшую порцию сразу отправляют в лабораторию; глюкозу обычно сравнивают с одновременно взятой кровью', 'Den Liquor gewinnt der Arzt bei einer Lumbalpunktion in örtlicher Betäubung, eine kleine Menge geht sofort ins Labor; die Glukose wird üblicherweise mit gleichzeitig entnommenem Blut verglichen', 'Sıvıyı hekim lokal anesteziyle yapılan lomber ponksiyonla alır, küçük bir bölümü hemen laboratuvara gönderilir; glukoz genellikle aynı anda alınan kanla karşılaştırılır', 'Suspected inflammation of the membranes of the brain, unclear neurological symptoms, seizures and disturbances of consciousness, follow-up in nervous system diseases as directed by a neurologist', 'Sumnja na upalu moždanih ovojnica, nejasni neurološki simptomi, grčevi i poremećaji svijesti, praćenje kod oboljenja nervnog sistema po uputu neurologa', 'Сумња на упалу можданих овојница, нејасни неуролошки симптоми, грчеви и поремећаји свијести, праћење код обољења нервног система по упуту неуролога', 'Подозрение на воспаление оболочек мозга, неясные неврологические симптомы, судороги и нарушения сознания, наблюдение при заболеваниях нервной системы по назначению невролога', 'Verdacht auf eine Entzündung der Hirnhäute, unklare neurologische Symptome, Krampfanfälle und Bewusstseinsstörungen, Verlaufskontrolle bei Erkrankungen des Nervensystems auf Anordnung des Neurologen', 'Beyin zarlarında iltihap şüphesi, açıklanamayan nörolojik belirtiler, nöbetler ve bilinç bozuklukları, nöroloji yönlendirmesiyle sinir sistemi hastalıklarında izlem', 'Preparation concerns the puncture itself and is explained by the doctor: consent, information about blood-thinning medications and lying down afterwards are required; the laboratory part needs no separate preparation', 'Priprema se odnosi na samu punkciju i objašnjava je ljekar: potrebni su saglasnost, podaci o lijekovima koji razrjeđuju krv i ležanje poslije zahvata; za laboratorijski dio posebne pripreme nema', 'Припрема се односи на саму пункцију и објашњава је љекар: потребни су сагласност, подаци о лијековима који разрјеђују крв и лежање послије захвата; за лабораторијски дио посебне припреме нема', 'Подготовка относится к самой пункции и её объясняет врач: нужны согласие, сведения о препаратах, разжижающих кровь, и отдых лёжа после процедуры; отдельной подготовки к лабораторной части нет', 'Die Vorbereitung betrifft die Punktion selbst und wird vom Arzt erläutert: Einwilligung, Angaben zu blutverdünnenden Medikamenten und Liegen im Anschluss; für den Laborteil ist keine gesonderte Vorbereitung nötig', 'Hazırlık ponksiyonun kendisiyle ilgilidir ve hekim tarafından anlatılır: onam, kan sulandırıcı ilaç bilgisi ve işlemden sonra sırtüstü dinlenme gerekir; laboratuvar bölümü için ayrı hazırlık yoktur', 'Changes may be related to inflammation, infection, altered permeability of the barriers between blood and the fluid, or to metabolic causes. The values are interpreted only together with the cell content, blood tests and the patient''s condition, which is done by a doctor', 'Promjene mogu biti povezane sa upalnim procesima, infekcijom, promijenjenom propustljivošću barijera između krvi i likvora ili sa metaboličkim uzrocima. Pokazatelji se tumače samo uz ćelijski sastav, analize krvi i stanje pacijenta, a to radi ljekar', 'Промјене могу бити повезане са упалним процесима, инфекцијом, промијењеном пропустљивошћу баријера између крви и ликвора или са метаболичким узроцима. Показатељи се тумаче само уз ћелијски састав, анализе крви и стање пацијента, а то ради љекар', 'Изменения могут быть связаны с воспалительными процессами, инфекцией, изменённой проницаемостью барьеров между кровью и ликвором или с обменными причинами. Показатели трактуются только вместе с клеточным составом, анализами крови и состоянием пациента, это делает врач', 'Veränderungen können mit Entzündungen, einer Infektion, einer veränderten Durchlässigkeit der Schranken zwischen Blut und Liquor oder mit Stoffwechselursachen zusammenhängen. Die Werte werden nur zusammen mit dem Zellbild, den Blutwerten und dem Zustand beurteilt, das übernimmt der Arzt', 'Değişiklikler iltihabi süreçlerle, enfeksiyonla, kan ile sıvı arasındaki engellerin geçirgenliğindeki değişimle ya da metabolik nedenlerle ilişkili olabilir. Değerler yalnızca hücre içeriği, kan tetkikleri ve hastanın durumuyla birlikte yorumlanır, bunu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'csf-protein-quantitative'), 'Precise measurement of total protein in cerebrospinal fluid, a value that reflects the permeability of the barrier between blood and the fluid', 'Precizno mjerenje ukupnih proteina u likvoru, pokazatelja propustljivosti barijere između krvi i likvora', 'Прецизно мјерење укупних протеина у ликвору, показатеља пропустљивости баријере између крви и ликвора', 'Точное измерение содержания общего белка в спинномозговой жидкости, показателя проницаемости барьера между кровью и ликвором', 'Genaue Bestimmung des Gesamteiweißes im Liquor, eines Wertes für die Durchlässigkeit der Schranke zwischen Blut und Liquor', 'Beyin omurilik sıvısındaki total proteinin kesin ölçümü; kan ile sıvı arasındaki engelin geçirgenliğini yansıtan bir değerdir', 'No separate sampling is needed: protein is measured in the same portion of fluid obtained at lumbar puncture, and blood contaminating the sample distorts the result', 'Posebno uzimanje nije potrebno: proteini se određuju u istoj količini likvora dobijenoj lumbalnom punkcijom, a primjesa krvi u uzorku iskrivljuje nalaz', 'Посебно узимање није потребно: протеини се одређују у истој количини ликвора добијеној лумбалном пункцијом, а примјеса крви у узорку искривљује налаз', 'Отдельного забора не требуется: белок определяют в той же порции ликвора, что получена при люмбальной пункции, а примесь крови в пробе искажает результат', 'Eine gesonderte Entnahme ist nicht nötig: Das Eiweiß wird in derselben bei der Lumbalpunktion gewonnenen Portion bestimmt, eine Blutbeimengung in der Probe verfälscht das Ergebnis', 'Ayrı bir örnek alınması gerekmez: protein, lomber ponksiyonla elde edilen aynı sıvıda ölçülür, örneğe kan karışması sonucu bozar', 'Suspected inflammatory and demyelinating diseases of the nervous system, polyneuropathies, assessment of the permeability of the blood-fluid barrier, follow-up over time as directed by a neurologist', 'Sumnja na upalna i demijelinizaciona oboljenja nervnog sistema, polineuropatije, procjena propustljivosti barijere između krvi i likvora, praćenje u dinamici po uputu neurologa', 'Сумња на упална и демијелинизациона обољења нервног система, полинеуропатије, процјена пропустљивости баријере између крви и ликвора, праћење у динамици по упуту неуролога', 'Подозрение на воспалительные и демиелинизирующие заболевания нервной системы, полинейропатии, оценка проницаемости барьера между кровью и ликвором, наблюдение в динамике по назначению невролога', 'Verdacht auf entzündliche und entmarkende Erkrankungen des Nervensystems, Polyneuropathien, Beurteilung der Durchlässigkeit der Blut-Liquor-Schranke, Verlaufskontrolle auf Anordnung des Neurologen', 'Sinir sisteminin iltihabi ve demiyelinizan hastalıkları şüphesi, polinöropatiler, kan ile sıvı arasındaki engelin geçirgenliğinin değerlendirilmesi, nöroloji yönlendirmesiyle zaman içinde izlem', 'There is no preparation on the patient''s part and the material is taken during the puncture; the rules of the puncture itself and the rest afterwards are explained by the doctor performing it', 'Sa strane pacijenta pripreme nema, materijal se uzima tokom punkcije; pravila same punkcije i odmor poslije nje objašnjava ljekar koji je izvodi', 'Са стране пацијента припреме нема, материјал се узима током пункције; правила саме пункције и одмор послије ње објашњава љекар који је изводи', 'Подготовки со стороны пациента нет, материал берут во время пункции; правила самой пункции и отдых после неё объясняет выполняющий её врач', 'Von Seiten des Patienten ist keine Vorbereitung nötig, das Material wird während der Punktion gewonnen; die Regeln der Punktion und die Ruhe danach erklärt der durchführende Arzt', 'Hasta açısından hazırlık yoktur, materyal ponksiyon sırasında alınır; ponksiyonun kuralları ve sonrasındaki dinlenme, işlemi yapan hekim tarafından anlatılır', 'An increase may be related to inflammation, impaired circulation of the fluid, changed permeability of the barrier, or blood getting into the sample. A neurologist assesses the meaning of the result together with the other cerebrospinal fluid values and the clinical picture', 'Povišene vrijednosti mogu biti povezane sa upalom, otežanim protokom likvora, promijenjenom propustljivošću barijere ili sa dospijevanjem krvi u uzorak. Značenje nalaza neurolog procjenjuje uz ostale pokazatelje likvora i kliničku sliku', 'Повишене вриједности могу бити повезане са упалом, отежаним протоком ликвора, промијењеном пропустљивошћу баријере или са доспијевањем крви у узорак. Значење налаза неуролог процјењује уз остале показатеље ликвора и клиничку слику', 'Повышение может быть связано с воспалением, затруднённой циркуляцией ликвора, изменением проницаемости барьера или с попаданием крови в пробу. Значение результата невролог оценивает вместе с остальными показателями ликвора и клинической картиной', 'Erhöhte Werte können mit einer Entzündung, einer gestörten Liquorzirkulation, einer veränderten Durchlässigkeit der Schranke oder mit einer Blutbeimengung in der Probe zusammenhängen. Die Bedeutung des Befundes beurteilt der Neurologe zusammen mit den übrigen Liquorwerten und dem klinischen Bild', 'Yükseklik iltihapla, sıvı dolaşımının bozulmasıyla, engelin geçirgenliğindeki değişimle ya da örneğe kan karışmasıyla ilişkili olabilir. Sonucun anlamını nöroloji uzmanı diğer beyin omurilik sıvısı değerleri ve klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'pleural-fluid-analysis'), 'Laboratory examination of fluid from the space between the lung and the chest wall, with assessment of protein, enzymes and cell content', 'Laboratorijsko ispitivanje tečnosti iz prostora između pluća i zida grudnog koša, sa procjenom proteina, enzima i ćelijskog sastava', 'Лабораторијско испитивање течности из простора између плућа и зида грудног коша, са процјеном протеина, ензима и ћелијског састава', 'Лабораторное исследование жидкости из полости между лёгким и грудной стенкой с оценкой белка, ферментов и клеточного состава', 'Laboruntersuchung der Flüssigkeit aus dem Raum zwischen Lunge und Brustwand mit Bestimmung von Eiweiß, Enzymen und Zellgehalt', 'Akciğer ile göğüs duvarı arasındaki boşluktan alınan sıvının laboratuvarda incelenmesi; protein, enzimler ve hücre içeriği değerlendirilir', 'The fluid is obtained by the doctor through a puncture of the chest wall under local anaesthesia, usually with ultrasound guidance; part of the material goes to the laboratory and a control image is often taken afterwards', 'Tečnost uzima ljekar punkcijom grudnog zida u lokalnoj anesteziji, najčešće uz ultrazvučnu kontrolu; dio materijala ide u laboratoriju, a poslije zahvata se često uradi kontrolni snimak', 'Течност узима љекар пункцијом грудног зида у локалној анестезији, најчешће уз ултразвучну контролу; дио материјала иде у лабораторију, а послије захвата се често уради контролни снимак', 'Жидкость получает врач при проколе грудной стенки под местным обезболиванием, чаще под контролем УЗИ; часть материала направляют в лабораторию, после процедуры нередко делают контрольный снимок', 'Die Flüssigkeit gewinnt der Arzt durch eine Punktion der Brustwand in örtlicher Betäubung, meist unter Ultraschallkontrolle; ein Teil des Materials geht ins Labor, danach wird häufig eine Kontrollaufnahme angefertigt', 'Sıvıyı hekim, çoğunlukla ultrason eşliğinde ve lokal anesteziyle göğüs duvarından girerek alır; materyalin bir bölümü laboratuvara gönderilir, işlemden sonra sıklıkla kontrol görüntüsü alınır', 'Effusion around the lung seen on an X-ray or ultrasound, clarifying why it appeared, breathlessness and chest pain caused by the fluid, follow-up in diseases of the heart, lungs and kidneys', 'Izliv oko pluća viđen na snimku ili ultrazvuku, razjašnjavanje razloga njegovog nastanka, zaduha i bol u grudima zbog nakupljene tečnosti, praćenje kod bolesti srca, pluća i bubrega', 'Излив око плућа виђен на снимку или ултразвуку, разјашњавање разлога његовог настанка, задуха и бол у грудима због накупљене течности, праћење код болести срца, плућа и бубрега', 'Выявленный на снимке или УЗИ выпот вокруг лёгкого, уточнение причин его появления, одышка и боль в груди при скоплении жидкости, наблюдение при болезнях сердца, лёгких и почек', 'Im Röntgenbild oder Ultraschall gesehener Erguss um die Lunge, Klärung seiner Entstehung, Atemnot und Brustschmerz durch die angesammelte Flüssigkeit, Verlaufskontrolle bei Erkrankungen von Herz, Lunge und Nieren', 'Filmde veya ultrasonda görülen akciğer çevresindeki sıvı, ortaya çıkış nedeninin araştırılması, biriken sıvıya bağlı nefes darlığı ve göğüs ağrısı, kalp, akciğer ve böbrek hastalıklarında izlem', 'The laboratory part needs no separate preparation; before the puncture it is important to report blood-thinning medications, and during the procedure to sit still and try not to cough, with the rest explained by the doctor performing it', 'Za laboratorijski dio posebne pripreme nema; prije punkcije je važno reći za lijekove koji razrjeđuju krv, a tokom zahvata sjediti mirno i truditi se da se ne kašlje, ostalo objašnjava ljekar koji punkciju izvodi', 'За лабораторијски дио посебне припреме нема; прије пункције је важно рећи за лијекове који разрјеђују крв, а током захвата сједити мирно и трудити се да се не кашље, остало објашњава љекар који пункцију изводи', 'Отдельной подготовки к лабораторной части нет; перед проколом важно сообщить о препаратах, разжижающих кровь, а во время процедуры сидеть неподвижно и стараться не кашлять, остальное объясняет выполняющий врач', 'Für den Laborteil ist keine gesonderte Vorbereitung nötig; vor der Punktion ist es wichtig, blutverdünnende Medikamente anzugeben und während des Eingriffs still zu sitzen und möglichst nicht zu husten, alles Weitere erklärt der durchführende Arzt', 'Laboratuvar bölümü için ayrı hazırlık yoktur; işlemden önce kan sulandırıcı ilaçların bildirilmesi, işlem sırasında hareketsiz oturulması ve öksürmemeye çalışılması önemlidir, gerisini uygulayan hekim anlatır', 'From the composition of the fluid the doctor distinguishes the mechanisms of its accumulation, from raised pressure in the vessels to inflammation and infection. The final conclusion is reached together with examination of the lungs and heart and is made by the treating doctor', 'Po sastavu tečnosti ljekar razlikuje mehanizme njenog nakupljanja, od povišenog pritiska u krvnim sudovima do upale i infekcije. Konačan zaključak donosi ljekar koji liječi pacijenta, zajedno sa pregledom pluća i srca', 'По саставу течности љекар разликује механизме њеног накупљања, од повишеног притиска у крвним судовима до упале и инфекције. Коначан закључак доноси љекар који лијечи пацијента, заједно са прегледом плућа и срца', 'По составу жидкости врач различает механизмы её накопления, от повышенного давления в сосудах до воспаления и инфекции. Окончательный вывод делают вместе с обследованием лёгких и сердца, этим занимается лечащий врач', 'Anhand der Zusammensetzung unterscheidet der Arzt die Mechanismen der Ansammlung, von erhöhtem Druck in den Gefäßen bis zu Entzündung und Infektion. Die abschließende Beurteilung erfolgt zusammen mit der Untersuchung von Lunge und Herz durch den behandelnden Arzt', 'Hekim sıvının bileşiminden, damarlardaki basınç artışından iltihap ve enfeksiyona kadar birikme mekanizmalarını ayırt eder. Nihai değerlendirme akciğer ve kalp incelemeleriyle birlikte, tedaviyi yürüten hekim tarafından yapılır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anti-gad-antibodies'), 'Blood test for antibodies to glutamic acid decarboxylase (GAD), one of the markers of an autoimmune process in the insulin-producing cells of the pancreas', 'Analiza krvi na antitijela na glutamat dekarboksilazu (GAD), jedan od markera autoimunog procesa u ćelijama pankreasa koje stvaraju insulin', 'Анализа крви на антитијела на глутамат декарбоксилазу (GAD), један од маркера аутоимуног процеса у ћелијама панкреаса које стварају инсулин', 'Анализ крови на антитела к глутаматдекарбоксилазе (GAD) — один из маркеров аутоиммунного процесса в клетках поджелудочной железы, вырабатывающих инсулин', 'Bluttest auf Antikörper gegen Glutamatdecarboxylase (GAD), einer der Marker für einen Autoimmunprozess an den insulinbildenden Zellen der Bauchspeicheldrüse', 'Pankreasın insülin üreten hücrelerindeki otoimmün sürecin göstergelerinden biri olan glutamik asit dekarboksilaz (GAD) antikorları için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Clarifying the type of diabetes in adults, newly found high blood sugar in young or lean patients, testing together with other islet antibodies as ordered by an endocrinologist', 'Razjašnjavanje tipa dijabetesa kod odraslih, prvi put utvrđen povišen šećer kod mlađih i mršavijih osoba, ispitivanje zajedno sa ostalim antitijelima na Langerhansova ostrvca po uputu endokrinologa', 'Разјашњавање типа дијабетеса код одраслих, први пут утврђен повишен шећер код млађих и мршавијих особа, испитивање заједно са осталим антитијелима на Лангерхансова острвца по упуту ендокринолога', 'Уточнение типа диабета у взрослых, впервые выявленное повышение сахара у молодых и худощавых пациентов, обследование вместе с другими островковыми антителами по назначению эндокринолога', 'Klärung des Diabetestyps bei Erwachsenen, erstmals erhöhter Blutzucker bei jungen oder schlanken Personen, Untersuchung zusammen mit weiteren Inselzell-Antikörpern auf Veranlassung des Endokrinologen', 'Erişkinde diyabet tipinin belirlenmesi, genç veya zayıf kişilerde yeni saptanan yüksek kan şekeri, endokrinoloji uzmanının isteğiyle diğer ada hücresi antikorlarıyla birlikte inceleme', 'No special preparation required, the result does not depend on food intake', 'Nije potrebna posebna priprema, nalaz ne zavisi od uzimanja hrane', 'Није потребна посебна припрема, налаз не зависи од узимања хране', 'Специальной подготовки не требуется, результат не зависит от приёма пищи', 'Keine besondere Vorbereitung erforderlich, das Ergebnis hängt nicht von der Nahrungsaufnahme ab', 'Özel bir hazırlık gerekmez, sonuç yemek yenmesinden etkilenmez', 'Detected antibodies may be related to an autoimmune process in the pancreatic cells, yet they also occur in people without any sugar metabolism problems, and a negative result does not rule out an autoimmune cause. The type of diabetes and the next steps are determined by the endocrinologist together with glucose levels, C-peptide and the clinical picture', 'Nalaz antitijela može biti povezan sa autoimunim procesom u ćelijama pankreasa, ali se sreće i kod osoba bez poremećaja metabolizma šećera, a negativan nalaz autoimunu prirodu ne isključuje. Tip dijabetesa i dalje korake određuje endokrinolog zajedno sa nivoom glukoze, C-peptidom i kliničkom slikom', 'Налаз антитијела може бити повезан са аутоимуним процесом у ћелијама панкреаса, али се среће и код особа без поремећаја метаболизма шећера, а негативан налаз аутоимуну природу не искључује. Тип дијабетеса и даље кораке одређује ендокринолог заједно са нивоом глукозе, Ц-пептидом и клиничком сликом', 'Обнаружение антител может быть связано с аутоиммунным процессом в клетках поджелудочной железы, но встречается и у людей без нарушений обмена сахара, а отрицательный результат аутоиммунную природу не исключает. Тип диабета и дальнейшие шаги определяет эндокринолог вместе с уровнем глюкозы, C-пептидом и клинической картиной', 'Nachweisbare Antikörper können mit einem Autoimmunprozess an den Zellen der Bauchspeicheldrüse zusammenhängen, kommen aber auch bei Menschen ohne Störung des Zuckerstoffwechsels vor, und ein negativer Befund schließt eine autoimmune Ursache nicht aus. Den Diabetestyp und das weitere Vorgehen legt der Endokrinologe zusammen mit Glukosewerten, C-Peptid und dem klinischen Bild fest', 'Antikorların saptanması pankreas hücrelerindeki otoimmün süreçle ilişkili olabilir, ancak şeker metabolizması sorunu olmayan kişilerde de bulunur; negatif sonuç da otoimmün nedeni dışlamaz. Diyabetin tipini ve izlenecek yolu endokrinoloji uzmanı glukoz düzeyi, C-peptit ve klinik tabloyla birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anticardiolipin-igg'), 'Blood test for IgG class antibodies to cardiolipin, one of the tests in the antiphospholipid antibody panel', 'Analiza krvi na antitijela klase IgG na kardiolipin, jedan od testova panela antifosfolipidnih antitijela', 'Анализа крви на антитијела класе IgG на кардиолипин, један од тестова панела антифосфолипидних антитијела', 'Анализ крови на антитела класса IgG к кардиолипину — один из тестов панели антифосфолипидных антител', 'Bluttest auf Antikörper der Klasse IgG gegen Cardiolipin, einer der Tests des Antiphospholipid-Antikörper-Panels', 'Antifosfolipid antikor panelinin testlerinden biri olan, kardiyolipine karşı IgG sınıfı antikorlar için kan testi', 'Blood draw from a vein; a positive result is usually repeated after some time', 'Uzimanje venske krvi, kod pozitivnog nalaza ispitivanje se obično ponavlja nakon izvjesnog vremena', 'Узимање венске крви, код позитивног налаза испитивање се обично понавља након извјесног времена', 'Забор венозной крови; при положительном результате исследование обычно повторяют спустя некоторое время', 'Blutentnahme aus einer Vene; ein positiver Befund wird in der Regel nach einiger Zeit wiederholt', 'Damardan kan alınır; pozitif sonuç genellikle bir süre sonra tekrarlanır', 'Work-up of thrombosis, repeated pregnancy loss, systemic autoimmune disease, unexplained changes in clotting tests', 'Obrada kod tromboza, ponovljenih gubitaka trudnoće, sistemskih autoimunih oboljenja, neobjašnjenih promjena koagulacionih testova', 'Обрада код тромбоза, поновљених губитака трудноће, системских аутоимуних обољења, необјашњених промјена коагулационих тестова', 'Обследование при тромбозах, повторных потерях беременности, системных аутоиммунных заболеваниях, необъяснимых изменениях коагуляционных тестов', 'Abklärung von Thrombosen, wiederholten Fehlgeburten, systemischen Autoimmunerkrankungen, unerklärten Veränderungen der Gerinnungstests', 'Tromboz, tekrarlayan gebelik kayıpları, sistemik otoimmün hastalıklar, pıhtılaşma testlerinde açıklanamayan değişiklikler', 'No special preparation required; tell the doctor about recent infections and the medicines you take', 'Nije potrebna posebna priprema, o nedavno preboljenim infekcijama i lijekovima koje uzimate obavještava se ljekar', 'Није потребна посебна припрема, о недавно пребољеним инфекцијама и лијековима које узимате обавјештава се љекар', 'Специальной подготовки не требуется; о недавно перенесённых инфекциях и принимаемых лекарствах сообщают врачу', 'Keine besondere Vorbereitung erforderlich; kürzlich durchgemachte Infektionen und eingenommene Medikamente sollten dem Arzt mitgeteilt werden', 'Özel bir hazırlık gerekmez; yakın zamanda geçirilen enfeksiyonlar ve kullanılan ilaçlar hekime bildirilir', 'Detected antibodies may be related to antiphospholipid syndrome, but a temporary positive reaction also occurs after infections and with certain medicines. A single positive result is not a diagnosis: it is confirmed by a repeat test and assessed by the doctor together with the clinical picture', 'Nalaz antitijela može biti povezan sa antifosfolipidnim sindromom, ali se prolazno pozitivan rezultat javlja i nakon infekcija i uz pojedine lijekove. Jedan pozitivan nalaz nije dijagnoza: potvrđuje se ponovljenom analizom, a procjenjuje ga ljekar zajedno sa kliničkom slikom', 'Налаз антитијела може бити повезан са антифосфолипидним синдромом, али се пролазно позитиван резултат јавља и након инфекција и уз поједине лијекове. Један позитиван налаз није дијагноза: потврђује се поновљеном анализом, а процјењује га љекар заједно са клиничком сликом', 'Обнаружение антител может быть связано с антифосфолипидным синдромом, но временная положительная реакция бывает после инфекций и на фоне некоторых лекарств. Однократный положительный результат не является диагнозом: его подтверждают повторным анализом, а оценивает врач вместе с клинической картиной', 'Nachweisbare Antikörper können mit einem Antiphospholipid-Syndrom zusammenhängen, eine vorübergehende positive Reaktion kommt aber auch nach Infektionen und unter bestimmten Medikamenten vor. Ein einzelner positiver Befund ist keine Diagnose: er wird durch eine Kontrolle bestätigt und vom Arzt zusammen mit dem klinischen Bild beurteilt', 'Saptanan antikorlar antifosfolipid sendromuyla ilişkili olabilir, ancak enfeksiyonlardan sonra ve bazı ilaçlarla geçici pozitiflik de görülür. Tek bir pozitif sonuç tanı değildir: tekrar testiyle doğrulanır ve hekim klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'anticardiolipin-igm'), 'Blood test for IgM class antibodies to cardiolipin, the second antibody class of the same panel, read together with IgG', 'Analiza krvi na antitijela klase IgM na kardiolipin, druga klasa antitijela istog panela koja se čita zajedno sa IgG', 'Анализа крви на антитијела класе IgM на кардиолипин, друга класа антитијела истог панела која се чита заједно са IgG', 'Анализ крови на антитела класса IgM к кардиолипину — второй класс антител той же панели, который читают вместе с IgG', 'Bluttest auf Antikörper der Klasse IgM gegen Cardiolipin, die zweite Antikörperklasse desselben Panels, die zusammen mit IgG beurteilt wird', 'Kardiyolipine karşı IgM sınıfı antikorlar için kan testi, aynı panelin IgG ile birlikte değerlendirilen ikinci antikor sınıfı', 'Blood draw from a vein; whether a positive result is repeated is decided by the doctor', 'Uzimanje venske krvi, o ponavljanju pozitivnog nalaza odlučuje ljekar', 'Узимање венске крви, о понављању позитивног налаза одлучује љекар', 'Забор венозной крови; нужно ли повторять положительный результат, решает врач', 'Blutentnahme aus einer Vene; ob ein positiver Befund wiederholt wird, entscheidet der Arzt', 'Damardan kan alınır; pozitif sonucun tekrarlanmasına hekim karar verir', 'Work-up of thrombosis and pregnancy complications, addition to the IgG result, follow-up when antiphospholipid antibodies are already known', 'Obrada kod tromboza i komplikacija u trudnoći, dopuna nalazu IgG, praćenje kod već utvrđenih antifosfolipidnih antitijela', 'Обрада код тромбоза и компликација у трудноћи, допуна налазу IgG, праћење код већ утврђених антифосфолипидних антитијела', 'Обследование при тромбозах и осложнениях беременности, дополнение к результату IgG, наблюдение при уже выявленных антифосфолипидных антителах', 'Abklärung von Thrombosen und Schwangerschaftskomplikationen, Ergänzung zum IgG-Befund, Verlaufskontrolle bei bereits bekannten Antiphospholipid-Antikörpern', 'Tromboz ve gebelik komplikasyonlarının araştırılması, IgG sonucunun tamamlanması, bilinen antifosfolipid antikorlarında izlem', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'IgM antibodies are more often temporary: they appear after infections and are found in older people without any complaints. The doctor assesses the result together with IgG, the other tests of the panel and the medical history', 'Antitijela klase IgM su češće prolazna: javljaju se nakon infekcija i nalaze se kod starijih osoba bez ikakvih tegoba. Nalaz procjenjuje ljekar zajedno sa IgG, ostalim testovima panela i istorijom bolesti', 'Антитијела класе IgM су чешће пролазна: јављају се након инфекција и налазе се код старијих особа без икаквих тегоба. Налаз процјењује љекар заједно са IgG, осталим тестовима панела и историјом болести', 'Антитела класса IgM чаще бывают временными: они появляются после инфекций и встречаются у пожилых людей без каких-либо жалоб. Значение результата врач оценивает вместе с IgG, остальными тестами панели и историей болезни', 'IgM-Antikörper sind häufiger vorübergehend: sie treten nach Infektionen auf und finden sich bei älteren Menschen ohne jegliche Beschwerden. Der Arzt beurteilt den Befund zusammen mit IgG, den übrigen Tests des Panels und der Krankengeschichte', 'IgM sınıfı antikorlar daha sık geçicidir: enfeksiyonlardan sonra ortaya çıkar ve şikayeti olmayan yaşlı kişilerde de bulunur. Hekim sonucu IgG, panelin diğer testleri ve hastalık öyküsüyle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'beta-2-glycoprotein-i-igg'), 'Blood test for IgG class antibodies to beta-2 glycoprotein I, a protein that binds to the phospholipids of cell membranes', 'Analiza krvi na antitijela klase IgG na beta-2 glikoprotein I, bjelančevinu koja se vezuje za fosfolipide ćelijskih membrana', 'Анализа крви на антитијела класе IgG на бета-2 гликопротеин И, бјеланчевину која се везује за фосфолипиде ћелијских мембрана', 'Анализ крови на антитела класса IgG к бета-2-гликопротеину I — белку, который связывается с фосфолипидами клеточных мембран', 'Bluttest auf Antikörper der Klasse IgG gegen Beta-2-Glykoprotein I, ein Eiweiß, das an Phospholipide der Zellmembranen bindet', 'Hücre zarındaki fosfolipitlere bağlanan bir protein olan beta-2 glikoprotein I''e karşı IgG sınıfı antikorlar için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Work-up of thrombosis and repeated pregnancy loss together with anticardiolipin antibodies and lupus anticoagulant, clarification of positive panel results', 'Obrada kod tromboza i ponovljenih gubitaka trudnoće zajedno sa antikardiolipinskim antitijelima i lupus antikoagulansom, razjašnjenje pozitivnih nalaza panela', 'Обрада код тромбоза и поновљених губитака трудноће заједно са антикардиолипинским антитијелима и лупус антикоагулансом, разјашњење позитивних налаза панела', 'Обследование при тромбозах и повторных потерях беременности вместе с антикардиолипиновыми антителами и волчаночным антикоагулянтом, уточнение положительных результатов панели', 'Abklärung von Thrombosen und wiederholten Fehlgeburten zusammen mit Anticardiolipin-Antikörpern und Lupusantikoagulans, Klärung positiver Panelbefunde', 'Tromboz ve tekrarlayan gebelik kayıplarında antikardiyolipin antikorları ve lupus antikoagülanı ile birlikte inceleme, panelde pozitif çıkan sonuçların netleştirilmesi', 'No special preparation required, the result does not depend on food intake', 'Nije potrebna posebna priprema, nalaz ne zavisi od uzimanja hrane', 'Није потребна посебна припрема, налаз не зависи од узимања хране', 'Специальной подготовки не требуется, результат не зависит от приёма пищи', 'Keine besondere Vorbereitung erforderlich, das Ergebnis hängt nicht von der Nahrungsaufnahme ab', 'Özel bir hazırlık gerekmez, sonuç yemek yenmesinden etkilenmez', 'A positive result may be related to antiphospholipid antibodies, it can also be transient, and finding the antibodies is not a diagnosis in itself. The conclusion is drawn by the doctor from the whole panel, repeated after some time, and from the clinical picture', 'Pozitivan nalaz može biti povezan sa antifosfolipidnim antitijelima, a može biti i prolazan, pa sam nalaz antitijela nije dijagnoza. Zaključak donosi ljekar na osnovu cijelog panela, ponovljenog nakon izvjesnog vremena, i kliničke slike', 'Позитиван налаз може бити повезан са антифосфолипидним антитијелима, а може бити и пролазан, па сам налаз антитијела није дијагноза. Закључак доноси љекар на основу цијелог панела, поновљеног након извјесног времена, и клиничке слике', 'Положительный результат может быть связан с антифосфолипидными антителами, при этом он бывает и преходящим, а само по себе обнаружение антител диагнозом не является. Заключение делает врач по всей панели, повторённой спустя некоторое время, и клинической картине', 'Ein positiver Befund kann mit Antiphospholipid-Antikörpern zusammenhängen, er kann auch vorübergehend sein, und der Nachweis allein ist keine Diagnose. Die Einordnung trifft der Arzt anhand des gesamten, nach einiger Zeit wiederholten Panels und des klinischen Bildes', 'Pozitif sonuç antifosfolipid antikorlarıyla ilişkili olabilir, geçici de olabilir ve antikorun saptanması tek başına tanı değildir. Değerlendirmeyi hekim, bir süre sonra tekrarlanan panelin tamamı ve klinik tabloyla birlikte yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'beta-2-glycoprotein-i-igm'), 'Blood test for IgM class antibodies to beta-2 glycoprotein I, the IgM part of the same test, read together with IgG', 'Analiza krvi na antitijela klase IgM na beta-2 glikoprotein I, IgM dio istog ispitivanja koji se procjenjuje zajedno sa IgG', 'Анализа крви на антитијела класе IgM на бета-2 гликопротеин И, IgM дио истог испитивања који се процјењује заједно са IgG', 'Анализ крови на антитела класса IgM к бета-2-гликопротеину I — IgM-часть того же исследования, которую оценивают вместе с IgG', 'Bluttest auf Antikörper der Klasse IgM gegen Beta-2-Glykoprotein I, der IgM-Anteil derselben Untersuchung, der zusammen mit IgG beurteilt wird', 'Beta-2 glikoprotein I''e karşı IgM sınıfı antikorlar için kan testi, aynı incelemenin IgG ile birlikte değerlendirilen IgM bölümü', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Work-up of thrombosis and pregnancy complications, addition to the antiphospholipid antibody panel, follow-up as ordered by the doctor', 'Obrada kod tromboza i komplikacija u trudnoći, dopuna panelu antifosfolipidnih antitijela, praćenje po uputu ljekara', 'Обрада код тромбоза и компликација у трудноћи, допуна панелу антифосфолипидних антитијела, праћење по упуту љекара', 'Обследование при тромбозах и осложнениях беременности, дополнение к панели антифосфолипидных антител, наблюдение по назначению врача', 'Abklärung von Thrombosen und Schwangerschaftskomplikationen, Ergänzung des Antiphospholipid-Panels, Verlaufskontrolle auf ärztliche Veranlassung', 'Tromboz ve gebelik komplikasyonlarının araştırılması, antifosfolipid antikor paneline ek, hekim isteğiyle izlem', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'IgM antibodies more often turn out to be temporary and occur with infections and in people without complaints, while their absence does not rule out antiphospholipid syndrome. The result matters only together with the other tests of the panel and is assessed by the doctor', 'Antitijela klase IgM češće budu prolazna i javljaju se kod infekcija i kod osoba bez tegoba, a njihovo odsustvo ne isključuje antifosfolipidni sindrom. Nalaz ima značaj samo uz ostale testove panela i procjenjuje ga ljekar', 'Антитијела класе IgM чешће буду пролазна и јављају се код инфекција и код особа без тегоба, а њихово одсуство не искључује антифосфолипидни синдром. Налаз има значај само уз остале тестове панела и процјењује га љекар', 'Антитела класса IgM чаще оказываются временными и встречаются при инфекциях и у людей без жалоб, а их отсутствие антифосфолипидный синдром не исключает. Результат имеет значение только в сочетании с остальными тестами панели и оценивается врачом', 'IgM-Antikörper erweisen sich häufiger als vorübergehend und kommen bei Infektionen sowie bei Menschen ohne Beschwerden vor, ihr Fehlen schließt ein Antiphospholipid-Syndrom nicht aus. Der Befund hat nur zusammen mit den übrigen Tests des Panels Aussagekraft und wird vom Arzt beurteilt', 'IgM sınıfı antikorlar daha sık geçici olur, enfeksiyonlarda ve şikayeti olmayan kişilerde görülebilir, bulunmaması da antifosfolipid sendromunu dışlamaz. Sonuç yalnızca panelin diğer testleriyle birlikte anlam taşır ve hekim tarafından değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'dsdna-igg-antibodies'), 'Blood test for IgG class antibodies to double-stranded DNA (dsDNA), a clarifying test in the work-up of systemic connective tissue disease', 'Analiza krvi na antitijela klase IgG na dvolančanu DNK (dsDNA), dopunski test pri ispitivanju sistemskih bolesti vezivnog tkiva', 'Анализа крви на антитијела класе IgG на дволанчану ДНК (dsDNA), допунски тест при испитивању системских болести везивног ткива', 'Анализ крови на антитела класса IgG к двуспиральной ДНК (dsDNA) — уточняющий тест при обследовании на системные заболевания соединительной ткани', 'Bluttest auf Antikörper der Klasse IgG gegen doppelsträngige DNA (dsDNA), ein ergänzender Test bei der Abklärung systemischer Bindegewebserkrankungen', 'Sistemik bağ dokusu hastalıklarının araştırılmasında doğrulayıcı test olarak kullanılan, çift sarmallı DNA''ya (dsDNA) karşı IgG sınıfı antikorlar için kan testi', 'Blood draw from a vein, the laboratory measures the antibody level, the draw itself takes a few minutes', 'Uzimanje venske krvi, u laboratoriji se mjeri nivo antitijela, samo uzimanje traje nekoliko minuta', 'Узимање венске крви, у лабораторији се мјери ниво антитијела, само узимање траје неколико минута', 'Забор венозной крови, в лаборатории измеряют уровень антител, сам забор занимает несколько минут', 'Blutentnahme aus einer Vene, im Labor wird die Antikörpermenge bestimmt, die Entnahme selbst dauert wenige Minuten', 'Damardan kan alınır, laboratuvarda antikor düzeyi ölçülür, kan alma işlemi birkaç dakika sürer', 'Positive ANA test, joint pain combined with skin rashes and fever, monitoring the course of an already established systemic disease as ordered by a rheumatologist', 'Pozitivan ANA test, bolovi u zglobovima uz promjene na koži i povišenu temperaturu, praćenje toka već utvrđene sistemske bolesti po uputu reumatologa', 'Позитиван ANA тест, болови у зглобовима уз промјене на кожи и повишену температуру, праћење тока већ утврђене системске болести по упуту реуматолога', 'Положительный результат теста ANA, боли в суставах в сочетании с кожными высыпаниями и лихорадкой, наблюдение за течением уже установленного системного заболевания по назначению ревматолога', 'Positiver ANA-Test, Gelenkschmerzen zusammen mit Hautausschlägen und Fieber, Verlaufskontrolle einer bereits festgestellten systemischen Erkrankung auf Veranlassung des Rheumatologen', 'Pozitif ANA testi, ciltte döküntü ve ateşle birlikte eklem ağrıları, romatoloji uzmanının isteğiyle tanısı konmuş sistemik hastalığın izlemi', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'Detected antibodies may be related to a systemic autoimmune process, but weakly positive results also occur with infections, other autoimmune conditions and under a number of medicines. The result and its changes over time are assessed by the rheumatologist together with the examination and the remaining tests', 'Nalaz antitijela može biti povezan sa sistemskim autoimunim procesom, ali se slabo pozitivni rezultati javljaju i kod infekcija, drugih autoimunih stanja i uz pojedine lijekove. Nalaz i njegovo kretanje procjenjuje reumatolog zajedno sa pregledom i ostalim analizama', 'Налаз антитијела може бити повезан са системским аутоимуним процесом, али се слабо позитивни резултати јављају и код инфекција, других аутоимуних стања и уз поједине лијекове. Налаз и његово кретање процјењује реуматолог заједно са прегледом и осталим анализама', 'Обнаружение антител может быть связано с системным аутоиммунным процессом, но слабо положительные результаты встречаются при инфекциях, других аутоиммунных состояниях и на фоне ряда лекарств. Результат и его динамику оценивает ревматолог вместе с осмотром и остальными анализами', 'Nachweisbare Antikörper können mit einem systemischen Autoimmunprozess zusammenhängen, schwach positive Befunde kommen jedoch auch bei Infektionen, anderen Autoimmunerkrankungen und unter einigen Medikamenten vor. Befund und Verlauf beurteilt der Rheumatologe zusammen mit der Untersuchung und den übrigen Werten', 'Saptanan antikorlar sistemik otoimmün süreçle ilişkili olabilir, ancak zayıf pozitif sonuçlar enfeksiyonlarda, başka otoimmün durumlarda ve bazı ilaçların kullanımında da görülür. Sonucu ve zaman içindeki değişimini romatoloji uzmanı muayene ve diğer tetkiklerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'ia-2-antibodies'), 'Blood test for antibodies to tyrosine phosphatase IA-2, another marker of an autoimmune process in the islet cells of the pancreas', 'Analiza krvi na antitijela na tirozin fosfatazu IA-2, još jedan marker autoimunog procesa u ćelijama Langerhansovih ostrvaca pankreasa', 'Анализа крви на антитијела на тирозин фосфатазу IA-2, још један маркер аутоимуног процеса у ћелијама Лангерхансових острваца панкреаса', 'Анализ крови на антитела к тирозинфосфатазе IA-2 — ещё один маркер аутоиммунного процесса в островковых клетках поджелудочной железы', 'Bluttest auf Antikörper gegen die Tyrosinphosphatase IA-2, ein weiterer Marker für einen Autoimmunprozess an den Inselzellen der Bauchspeicheldrüse', 'Pankreasın ada hücrelerindeki otoimmün sürecin bir başka göstergesi olan tirozin fosfataz IA-2 antikorları için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Clarifying the type of diabetes in children and adolescents with newly found high blood sugar, testing as part of the islet antibody panel ordered by an endocrinologist', 'Razjašnjavanje tipa dijabetesa kod djece i adolescenata sa prvi put utvrđenim povišenim šećerom, ispitivanje u sklopu panela antitijela na Langerhansova ostrvca po uputu endokrinologa', 'Разјашњавање типа дијабетеса код дјеце и адолесцената са први пут утврђеним повишеним шећером, испитивање у склопу панела антитијела на Лангерхансова острвца по упуту ендокринолога', 'Уточнение типа диабета у детей и подростков с впервые выявленным повышением сахара, обследование в составе панели островковых антител по назначению эндокринолога', 'Klärung des Diabetestyps bei Kindern und Jugendlichen mit erstmals erhöhtem Blutzucker, Untersuchung im Rahmen des Inselzell-Antikörper-Panels auf Veranlassung des Endokrinologen', 'Yeni saptanan yüksek kan şekeri olan çocuk ve ergenlerde diyabet tipinin belirlenmesi, endokrinoloji uzmanının istediği ada hücresi antikor paneli kapsamında inceleme', 'No special preparation required, the result does not depend on the time of day', 'Nije potrebna posebna priprema, nalaz ne zavisi od doba dana', 'Није потребна посебна припрема, налаз не зависи од доба дана', 'Специальной подготовки не требуется, результат не зависит от времени суток', 'Keine besondere Vorbereitung erforderlich, das Ergebnis hängt nicht von der Tageszeit ab', 'Özel bir hazırlık gerekmez, sonuç günün saatinden etkilenmez', 'A positive result may be related to an autoimmune cause of a carbohydrate metabolism disorder, but on its own it determines neither the diagnosis nor the treatment, and a negative one does not rule out an autoimmune process. The final assessment is made by the endocrinologist from the whole set of values and the clinical picture', 'Pozitivan nalaz može biti povezan sa autoimunom prirodom poremećaja metabolizma ugljenih hidrata, ali sam po sebi ne određuje ni dijagnozu ni liječenje, a negativan ne isključuje autoimuni proces. Konačnu procjenu daje endokrinolog na osnovu svih pokazatelja i kliničke slike', 'Позитиван налаз може бити повезан са аутоимуном природом поремећаја метаболизма угљених хидрата, али сам по себи не одређује ни дијагнозу ни лијечење, а негативан не искључује аутоимуни процес. Коначну процјену даје ендокринолог на основу свих показатеља и клиничке слике', 'Положительный результат может быть связан с аутоиммунным характером нарушения углеводного обмена, но сам по себе не определяет ни диагноз, ни лечение, а отрицательный аутоиммунный процесс не исключает. Итоговую оценку даёт эндокринолог по совокупности показателей и клинической картины', 'Ein positiver Befund kann mit einer autoimmunen Ursache der Zuckerstoffwechselstörung zusammenhängen, legt für sich genommen aber weder Diagnose noch Behandlung fest, und ein negativer schließt einen Autoimmunprozess nicht aus. Die abschließende Einordnung nimmt der Endokrinologe anhand aller Werte und des klinischen Bildes vor', 'Pozitif sonuç karbonhidrat metabolizması bozukluğunun otoimmün kökenli olmasıyla ilişkili olabilir, ancak tek başına ne tanıyı ne de tedaviyi belirler, negatif sonuç da otoimmün süreci dışlamaz. Son değerlendirmeyi endokrinoloji uzmanı tüm göstergeler ve klinik tabloyla birlikte yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'phospholipid-igg-antibodies'), 'Blood test for IgG class antibodies to a group of phospholipids, a combined test covering several phospholipid targets at once', 'Analiza krvi na antitijela klase IgG na grupu fosfolipida, zbirni test koji obuhvata više fosfolipidnih meta odjednom', 'Анализа крви на антитијела класе IgG на групу фосфолипида, збирни тест који обухвата више фосфолипидних мета одједном', 'Анализ крови на антитела класса IgG к группе фосфолипидов — суммарный тест, охватывающий несколько фосфолипидных мишеней сразу', 'Bluttest auf Antikörper der Klasse IgG gegen eine Gruppe von Phospholipiden, ein Summentest, der mehrere Phospholipid-Ziele zugleich erfasst', 'Birden çok fosfolipit hedefini aynı anda kapsayan, fosfolipit grubuna karşı IgG sınıfı antikorlar için toplu kan testi', 'Blood draw from a vein, the laboratory measures the combined level of IgG class antibodies', 'Uzimanje venske krvi, u laboratoriji se mjeri zbirni nivo antitijela klase IgG', 'Узимање венске крви, у лабораторији се мјери збирни ниво антитијела класе IgG', 'Забор венозной крови, в лаборатории определяют суммарный уровень антител класса IgG', 'Blutentnahme aus einer Vene, im Labor wird der Gesamtwert der IgG-Antikörper bestimmt', 'Damardan kan alınır, laboratuvarda IgG sınıfı antikorların toplam düzeyi ölçülür', 'First-line work-up of thrombosis, repeated pregnancy loss, suspected antiphospholipid syndrome before more specific tests', 'Početna obrada kod tromboza, ponovljenih gubitaka trudnoće, sumnje na antifosfolipidni sindrom prije specifičnijih testova', 'Почетна обрада код тромбоза, поновљених губитака трудноће, сумње на антифосфолипидни синдром прије специфичнијих тестова', 'Первичное обследование при тромбозах, повторных потерях беременности, подозрении на антифосфолипидный синдром до более специфичных тестов', 'Erste Abklärung bei Thrombosen, wiederholten Fehlgeburten, Verdacht auf ein Antiphospholipid-Syndrom vor spezifischeren Tests', 'Trombozda, tekrarlayan gebelik kayıplarında, antifosfolipid sendromu şüphesinde daha özgül testlerden önce yapılan ilk değerlendirme', 'No special preparation required; recent infections are worth mentioning to the laboratory or the doctor', 'Nije potrebna posebna priprema, o nedavno preboljenim infekcijama treba obavijestiti laboratoriju ili ljekara', 'Није потребна посебна припрема, о недавно пребољеним инфекцијама треба обавијестити лабораторију или љекара', 'Специальной подготовки не требуется; о недавно перенесённых инфекциях стоит сообщить лаборатории или врачу', 'Keine besondere Vorbereitung erforderlich; kürzlich durchgemachte Infektionen sollten dem Labor oder dem Arzt mitgeteilt werden', 'Özel bir hazırlık gerekmez; yakın zamanda geçirilen enfeksiyonların laboratuvara veya hekime bildirilmesi yararlıdır', 'A positive combined result is usually clarified with separate tests for antibodies to cardiolipin and beta-2 glycoprotein I, because it may also be related to a temporary reaction after an infection. Conclusions are drawn by the doctor from the whole panel, not from a single value', 'Pozitivan zbirni nalaz se obično razjašnjava zasebnim testovima na antitijela na kardiolipin i beta-2 glikoprotein I, jer može biti povezan i sa prolaznom reakcijom nakon infekcije. Zaključke donosi ljekar na osnovu cijelog panela, a ne jednog pokazatelja', 'Позитиван збирни налаз се обично разјашњава засебним тестовима на антитијела на кардиолипин и бета-2 гликопротеин И, јер може бити повезан и са пролазном реакцијом након инфекције. Закључке доноси љекар на основу цијелог панела, а не једног показатеља', 'Положительный суммарный результат обычно уточняют отдельными тестами на антитела к кардиолипину и бета-2-гликопротеину I, поскольку он может быть связан и с временной реакцией после инфекции. Выводы делает врач по всей панели, а не по одному показателю', 'Ein positiver Summenbefund wird üblicherweise mit gesonderten Tests auf Antikörper gegen Cardiolipin und Beta-2-Glykoprotein I geklärt, da er auch mit einer vorübergehenden Reaktion nach einer Infektion zusammenhängen kann. Schlüsse zieht der Arzt aus dem gesamten Panel, nicht aus einem einzelnen Wert', 'Pozitif toplu sonuç genellikle kardiyolipin ve beta-2 glikoprotein I antikorları için ayrı testlerle netleştirilir, çünkü enfeksiyon sonrası geçici bir yanıtla da ilişkili olabilir. Hekim sonucu tek bir değere göre değil panelin tamamına göre yorumlar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'phospholipid-igm-antibodies'), 'Blood test for IgM class antibodies to a group of phospholipids, the IgM part of the combined phospholipid test', 'Analiza krvi na antitijela klase IgM na grupu fosfolipida, IgM dio zbirnog fosfolipidnog testa', 'Анализа крви на антитијела класе IgM на групу фосфолипида, IgM дио збирног фосфолипидног теста', 'Анализ крови на антитела класса IgM к группе фосфолипидов — IgM-часть суммарного фосфолипидного теста', 'Bluttest auf Antikörper der Klasse IgM gegen eine Gruppe von Phospholipiden, der IgM-Anteil des Phospholipid-Summentests', 'Fosfolipit grubuna karşı IgM sınıfı antikorlar için kan testi, toplu fosfolipit testinin IgM bölümü', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Work-up of thrombosis and pregnancy complications together with IgG, addition to the antiphospholipid antibody panel as ordered by the doctor', 'Obrada kod tromboza i komplikacija u trudnoći zajedno sa IgG, dopuna panelu antifosfolipidnih antitijela po uputu ljekara', 'Обрада код тромбоза и компликација у трудноћи заједно са IgG, допуна панелу антифосфолипидних антитијела по упуту љекара', 'Обследование при тромбозах и осложнениях беременности вместе с IgG, дополнение к панели антифосфолипидных антител по назначению врача', 'Abklärung von Thrombosen und Schwangerschaftskomplikationen zusammen mit IgG, Ergänzung des Antiphospholipid-Panels auf ärztliche Veranlassung', 'Tromboz ve gebelik komplikasyonlarında IgG ile birlikte inceleme, hekim isteğiyle antifosfolipid antikor paneline ek', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'IgM antibodies in the combined test are quite often temporary and appear after infections, so the result is clarified with separate tests and repeated. Only the set of values taken together carries meaning, and it is assessed by the doctor', 'Antitijela klase IgM u zbirnom testu su često prolazna i javljaju se nakon infekcija, pa se nalaz razjašnjava zasebnim testovima i ponavlja. Značaj ima samo skup pokazatelja, koji procjenjuje ljekar', 'Антитијела класе IgM у збирном тесту су често пролазна и јављају се након инфекција, па се налаз разјашњава засебним тестовима и понавља. Значај има само скуп показатеља, који процјењује љекар', 'Антитела класса IgM в суммарном тесте нередко оказываются временными и появляются после инфекций, поэтому результат уточняют отдельными тестами и повторяют. Значение имеет только совокупность показателей, которую оценивает врач', 'IgM-Antikörper im Summentest sind oft vorübergehend und treten nach Infektionen auf, deshalb wird der Befund mit gesonderten Tests geklärt und wiederholt. Aussagekraft hat nur die Gesamtheit der Werte, die der Arzt beurteilt', 'Toplu testteki IgM sınıfı antikorlar sıklıkla geçicidir ve enfeksiyonlardan sonra ortaya çıkar, bu nedenle sonuç ayrı testlerle netleştirilir ve tekrarlanır. Anlam taşıyan şey göstergelerin bütünüdür ve bunu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'dsdna-igm-antibodies'), 'Blood test for IgM class antibodies to double-stranded DNA (dsDNA), an antibody class used less often than IgG', 'Analiza krvi na antitijela klase IgM na dvolančanu DNK (dsDNA), klasa antitijela koja se koristi rjeđe od IgG', 'Анализа крви на антитијела класе IgM на дволанчану ДНК (dsDNA), класа антитијела која се користи рјеђе од IgG', 'Анализ крови на антитела класса IgM к двуспиральной ДНК (dsDNA) — класс антител, который используют реже, чем IgG', 'Bluttest auf Antikörper der Klasse IgM gegen doppelsträngige DNA (dsDNA), eine Antikörperklasse, die seltener eingesetzt wird als IgG', 'Çift sarmallı DNA''ya (dsDNA) karşı IgM sınıfı antikorlar için kan testi, IgG''ye göre daha seyrek kullanılan antikor sınıfı', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Work-up of systemic autoimmune disease in addition to IgG and the ANA test, situations where the doctor needs to separate the antibody classes', 'Ispitivanje sistemskih autoimunih oboljenja kao dopuna IgG i ANA testu, situacije kada ljekar treba da razdvoji klase antitijela', 'Испитивање системских аутоимуних обољења као допуна IgG и ANA тесту, ситуације када љекар треба да раздвоји класе антитијела', 'Обследование при системных аутоиммунных заболеваниях в дополнение к IgG и тесту ANA, ситуации, когда врачу нужно разделить классы антител', 'Abklärung systemischer Autoimmunerkrankungen ergänzend zu IgG und zum ANA-Test, Situationen, in denen der Arzt die Antikörperklassen trennen muss', 'Sistemik otoimmün hastalıkların araştırılmasında IgG ve ANA testine ek, hekimin antikor sınıflarını ayırması gereken durumlar', 'No special preparation required, blood is usually taken in the morning', 'Nije potrebna posebna priprema, krv se obično uzima ujutru', 'Није потребна посебна припрема, крв се обично узима ујутру', 'Специальной подготовки не требуется, кровь обычно сдают утром', 'Keine besondere Vorbereitung erforderlich, die Blutentnahme erfolgt meist morgens', 'Özel bir hazırlık gerekmez, kan genellikle sabah alınır', 'IgM antibodies to dsDNA are less specific and are also found with infections and other conditions, so they are not interpreted apart from IgG and ANA. What the result means is decided by the doctor together with the clinical picture', 'Antitijela klase IgM na dsDNA su manje specifična i nalaze se i kod infekcija i drugih stanja, pa se ne tumače odvojeno od IgG i ANA. Značaj nalaza utvrđuje ljekar zajedno sa kliničkom slikom', 'Антитијела класе IgM на dsDNA су мање специфична и налазе се и код инфекција и других стања, па се не тумаче одвојено од IgG и ANA. Значај налаза утврђује љекар заједно са клиничком сликом', 'Антитела класса IgM к dsDNA менее специфичны и встречаются при инфекциях и других состояниях, поэтому отдельно от IgG и ANA их не трактуют. Значение результата определяет врач вместе с клинической картиной', 'IgM-Antikörper gegen dsDNA sind weniger spezifisch und kommen auch bei Infektionen und anderen Zuständen vor, deshalb werden sie nicht getrennt von IgG und ANA gedeutet. Was der Befund bedeutet, entscheidet der Arzt zusammen mit dem klinischen Bild', 'dsDNA''ya karşı IgM sınıfı antikorlar daha az özgüldür ve enfeksiyonlarda, başka durumlarda da bulunur, bu nedenle IgG ve ANA''dan ayrı yorumlanmaz. Sonucun anlamını hekim klinik tabloyla birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'znt8-antibodies'), 'Blood test for antibodies to zinc transporter 8 (ZnT8), a marker added to the islet antibody panel', 'Analiza krvi na antitijela na transporter cinka 8 (ZnT8), marker koji se dodaje panelu antitijela na Langerhansova ostrvca', 'Анализа крви на антитијела на транспортер цинка 8 (ЗнТ8), маркер који се додаје панелу антитијела на Лангерхансова острвца', 'Анализ крови на антитела к транспортёру цинка 8 (ZnT8) — маркер, который добавляют к панели островковых антител', 'Bluttest auf Antikörper gegen den Zinktransporter 8 (ZnT8), ein Marker, der das Inselzell-Antikörper-Panel ergänzt', 'Ada hücresi antikor paneline eklenen bir gösterge olan çinko taşıyıcı 8 (ZnT8) antikorları için kan testi', 'Blood draw from a vein, takes a few minutes', 'Uzimanje venske krvi iz vene, traje nekoliko minuta', 'Узимање венске крви из вене, траје неколико минута', 'Забор венозной крови из вены, занимает несколько минут', 'Blutentnahme aus einer Vene, dauert wenige Minuten', 'Damardan kan alınması, birkaç dakika sürer', 'Clarifying the type of diabetes when GAD and IA-2 antibodies are negative, work-up of newly found high blood sugar in children and young adults as ordered by an endocrinologist', 'Razjašnjavanje tipa dijabetesa kada su antitijela GAD i IA-2 negativna, obrada prvi put utvrđenog povišenog šećera kod djece i mlađih odraslih po uputu endokrinologa', 'Разјашњавање типа дијабетеса када су антитијела GAD и IA-2 негативна, обрада први пут утврђеног повишеног шећера код дјеце и млађих одраслих по упуту ендокринолога', 'Уточнение типа диабета, когда антитела GAD и IA-2 отрицательны, обследование при впервые выявленном повышении сахара у детей и молодых взрослых по назначению эндокринолога', 'Klärung des Diabetestyps bei negativen GAD- und IA-2-Antikörpern, Abklärung erstmals erhöhter Blutzuckerwerte bei Kindern und jungen Erwachsenen auf Veranlassung des Endokrinologen', 'GAD ve IA-2 antikorları negatifken diyabet tipinin belirlenmesi, endokrinoloji uzmanının isteğiyle çocuk ve genç erişkinlerde yeni saptanan yüksek kan şekerinin araştırılması', 'No special preparation required, the result does not depend on food intake', 'Nije potrebna posebna priprema, nalaz ne zavisi od uzimanja hrane', 'Није потребна посебна припрема, налаз не зависи од узимања хране', 'Специальной подготовки не требуется, результат не зависит от приёма пищи', 'Keine besondere Vorbereitung erforderlich, das Ergebnis hängt nicht von der Nahrungsaufnahme ab', 'Özel bir hazırlık gerekmez, sonuç yemek yenmesinden etkilenmez', 'Detected antibodies may be related to an autoimmune process in the islet cells, but they are not found in everyone and do not replace the other measures of glucose metabolism. The result is assessed by the endocrinologist together with the other antibodies of the panel and the clinical picture', 'Nalaz antitijela može biti povezan sa autoimunim procesom u ćelijama ostrvaca, ali se ne nalazi kod svih i ne zamjenjuje ostale pokazatelje metabolizma glukoze. Nalaz procjenjuje endokrinolog zajedno sa ostalim antitijelima panela i kliničkom slikom', 'Налаз антитијела може бити повезан са аутоимуним процесом у ћелијама острваца, али се не налази код свих и не замјењује остале показатеље метаболизма глукозе. Налаз процјењује ендокринолог заједно са осталим антитијелима панела и клиничком сликом', 'Обнаружение антител может быть связано с аутоиммунным процессом в островковых клетках, но выявляются они не у всех и не заменяют остальные показатели обмена глюкозы. Результат оценивает эндокринолог вместе с другими антителами панели и клинической картиной', 'Nachweisbare Antikörper können mit einem Autoimmunprozess an den Inselzellen zusammenhängen, sie finden sich jedoch nicht bei allen und ersetzen die übrigen Kennwerte des Zuckerstoffwechsels nicht. Den Befund beurteilt der Endokrinologe zusammen mit den weiteren Antikörpern des Panels und dem klinischen Bild', 'Saptanan antikorlar ada hücrelerindeki otoimmün süreçle ilişkili olabilir, ancak herkeste bulunmaz ve glukoz metabolizmasının diğer göstergelerinin yerini tutmaz. Sonucu endokrinoloji uzmanı panelin diğer antikorları ve klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'blood-count-selected-parameters'), 'A blood test in which the laboratory reports only the blood count parameters the doctor has ordered, not the whole panel', 'Analiza kod koje laboratorija određuje samo one pokazatelje krvne slike koje je ljekar tražio, a ne cijeli panel', 'Анализа код које лабораторија одређује само оне показатеље крвне слике које је љекар тражио, а не цијели панел', 'Анализ, при котором лаборатория определяет не всю картину крови, а только те показатели из неё, которые назначил врач', 'Eine Blutuntersuchung, bei der das Labor nur die vom Arzt angeforderten Blutbildwerte bestimmt und nicht das gesamte Blutbild', 'Laboratuvarın kan sayımının tamamını değil, yalnızca hekimin istediği parametreleri bildirdiği kan tetkiki', 'A single venous or capillary blood draw, from which only the requested parameters are reported', 'Jedno vađenje venske ili kapilarne krvi, iz uzorka se izdaju samo naručeni parametri', 'Једно вађење венске или капиларне крви, из узорка се издају само наручени параметри', 'Один забор венозной или капиллярной крови, из пробы выдаются лишь заказанные параметры', 'Eine einzelne venöse oder kapillare Blutentnahme, aus der nur die angeforderten Parameter ausgegeben werden', 'Tek bir venöz veya kapiller kan alımı yapılır, örnekten yalnızca istenen parametreler bildirilir', 'Repeat check of a single parameter, follow-up of a known condition over time, situations where a full blood count is not needed', 'Ponovna provjera pojedinačnog pokazatelja, praćenje već poznatog stanja tokom vremena, situacije u kojima kompletna krvna slika nije potrebna', 'Поновна провјера појединачног показатеља, праћење већ познатог стања током времена, ситуације у којима комплетна крвна слика није потребна', 'Повторный контроль отдельного показателя, наблюдение в динамике при уже известном состоянии, ситуации, когда полная гемограмма не нужна', 'Wiederholte Kontrolle eines einzelnen Wertes, Verlaufskontrolle bei bereits bekanntem Zustand, Situationen, in denen ein vollständiges Blutbild nicht nötig ist', 'Tek bir parametrenin yeniden kontrolü, bilinen bir durumun zaman içinde izlenmesi, tam kan sayımının gerekmediği durumlar', 'No special preparation required; bring the referral listing the parameters that are needed', 'Nije potrebna posebna priprema; uputnicu sa spiskom traženih pokazatelja treba ponijeti sa sobom', 'Није потребна посебна припрема; упутницу са списком тражених показатеља треба понијети са собом', 'Специальной подготовки не требуется; направление с перечнем нужных показателей стоит взять с собой', 'Keine besondere Vorbereitung erforderlich; die Überweisung mit der Liste der benötigten Werte sollte mitgebracht werden', 'Özel bir hazırlık gerektirmez; istenen parametrelerin yazılı olduğu sevk kâğıdını yanınızda getirmek gerekir', 'A change in any of the selected parameters may be related to infection, inflammation, anemia or the response to treatment. The picture here is incomplete, so the doctor decides whether a full blood count is needed', 'Promjena bilo kojeg od izabranih pokazatelja može biti povezana sa infekcijom, upalom, anemijom ili odgovorom na liječenje. Slika je ovdje nepotpuna, pa ljekar odlučuje da li je potrebna kompletna krvna slika', 'Промјена било којег од изабраних показатеља може бити повезана са инфекцијом, упалом, анемијом или одговором на лијечење. Слика је овдје непотпуна, па љекар одлучује да ли је потребна комплетна крвна слика', 'Изменение любого из выбранных показателей может быть связано с инфекцией, воспалением, анемией или ответом на лечение. Картина здесь неполная, поэтому врач решает, требуется ли полный анализ крови', 'Eine Veränderung eines der ausgewählten Werte kann mit einer Infektion, Entzündung, Anämie oder dem Ansprechen auf eine Behandlung zusammenhängen. Das Bild ist hier unvollständig, daher entscheidet der Arzt, ob ein vollständiges Blutbild nötig ist', 'Seçilen parametrelerden herhangi birindeki değişiklik enfeksiyon, iltihap, kansızlık veya tedaviye yanıtla ilişkili olabilir. Tablo burada eksik olduğundan tam kan sayımının gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'blood-eosinophils'), 'A count of the type of white blood cell involved in allergic reactions and in the response to parasites', 'Brojanje vrste bijelih krvnih ćelija koja učestvuje u alergijskim reakcijama i u odgovoru na parazite', 'Бројање врсте бијелих крвних ћелија која учествује у алергијским реакцијама и у одговору на паразите', 'Подсчёт разновидности белых клеток крови, участвующей в аллергических реакциях и в ответе на паразитов', 'Auszählung der Art weißer Blutkörperchen, die an allergischen Reaktionen und an der Abwehr von Parasiten beteiligt ist', 'Alerjik tepkilerde ve parazitlere karşı yanıtta rol alan akyuvar türünün sayımı', 'Venous or capillary blood draw; the share of these cells is measured on an analyzer and, if needed, confirmed in a stained smear', 'Uzimanje venske ili kapilarne krvi, udio ovih ćelija određuje analizator, a po potrebi se potvrđuje u obojenom razmazu', 'Узимање венске или капиларне крви, удио ових ћелија одређује анализатор, а по потреби се потврђује у обојеном размазу', 'Забор венозной или капиллярной крови, долю этих клеток определяет анализатор, при необходимости её подтверждают в окрашенном мазке', 'Entnahme von venösem oder kapillarem Blut; der Anteil dieser Zellen wird am Analysegerät bestimmt und bei Bedarf im gefärbten Ausstrich bestätigt', 'Venöz veya kapiller kan alınır; bu hücrelerin oranı cihazda ölçülür, gerekirse boyalı yaymada doğrulanır', 'Allergic complaints, itching and rash, lingering cough and asthma, suspected parasitic infestation, follow-up of a known allergy', 'Alergijske tegobe, svrab kože i osip, dugotrajan kašalj i astma, sumnja na parazite, praćenje kod poznate alergije', 'Алергијске тегобе, свраб коже и осип, дуготрајан кашаљ и астма, сумња на паразите, праћење код познате алергије', 'Аллергические жалобы, кожный зуд и сыпь, затяжной кашель и астма, подозрение на паразитарную инвазию, наблюдение при известной аллергии', 'Allergische Beschwerden, Juckreiz und Hautausschlag, anhaltender Husten und Asthma, Verdacht auf Parasitenbefall, Verlaufskontrolle bei bekannter Allergie', 'Alerji yakınmaları, ciltte kaşıntı ve döküntü, uzayan öksürük ve astım, parazit kuşkusu, bilinen alerjide izlem', 'No special preparation required; tell the doctor about any antihistamine or hormonal medication you take', 'Nije potrebna posebna priprema; o uzimanju antialergijskih i hormonskih lijekova treba obavijestiti ljekara', 'Није потребна посебна припрема; о узимању антиалергијских и хормонских лијекова треба обавијестити љекара', 'Специальной подготовки не требуется; о приёме противоаллергических и гормональных препаратов нужно сообщить врачу', 'Keine besondere Vorbereitung erforderlich; die Einnahme von Antiallergika und Hormonpräparaten ist dem Arzt mitzuteilen', 'Özel bir hazırlık gerektirmez; alerji ilaçları ve hormon ilaçlarının kullanımı hekime bildirilir', 'A higher share of these cells may be related to allergy, parasites, skin and lung conditions, or a reaction to a medicine. The meaning of the result is assessed by a doctor together with the complaints and the rest of the blood picture', 'Povećan udio ovih ćelija može biti povezan sa alergijom, parazitima, oboljenjima kože i pluća ili reakcijom na lijek. Značenje nalaza procjenjuje ljekar uz tegobe i ostatak krvne slike', 'Повећан удио ових ћелија може бити повезан са алергијом, паразитима, обољењима коже и плућа или реакцијом на лијек. Значење налаза процјењује љекар уз тегобе и остатак крвне слике', 'Повышение доли этих клеток может быть связано с аллергией, паразитами, кожными и лёгочными заболеваниями или реакцией на лекарство. Значение результата оценивает врач вместе с жалобами и остальной картиной крови', 'Ein erhöhter Anteil dieser Zellen kann mit einer Allergie, Parasiten, Haut- und Lungenerkrankungen oder einer Reaktion auf ein Medikament zusammenhängen. Die Bedeutung des Ergebnisses beurteilt der Arzt zusammen mit den Beschwerden und dem übrigen Blutbild', 'Bu hücrelerin oranının artması alerji, parazitler, cilt ve akciğer hastalıkları ya da bir ilaca tepkiyle ilişkili olabilir. Sonucun anlamını hekim, yakınmalar ve kan tablosunun geri kalanıyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'leukocytes'), 'A measurement of the total number of white blood cells, which protect the body against infections', 'Određivanje ukupnog broja bijelih krvnih ćelija koje štite organizam od infekcija', 'Одређивање укупног броја бијелих крвних ћелија које штите организам од инфекција', 'Определение общего числа белых клеток крови, которые отвечают за защиту организма от инфекций', 'Bestimmung der Gesamtzahl der weißen Blutkörperchen, die den Körper vor Infektionen schützen', 'Vücudu enfeksiyonlardan koruyan akyuvarların toplam sayısının ölçülmesi', 'Venous or capillary blood draw; the total number of cells is counted on a hematology analyzer', 'Uzimanje venske ili kapilarne krvi, ukupan broj ćelija broji hematološki analizator', 'Узимање венске или капиларне крви, укупан број ћелија броји хематолошки анализатор', 'Забор венозной или капиллярной крови, общее число клеток подсчитывает гематологический анализатор', 'Entnahme von venösem oder kapillarem Blut; die Gesamtzahl der Zellen zählt ein Hämatologie-Analysegerät', 'Venöz veya kapiller kan alınır; toplam hücre sayısı hematoloji cihazında sayılır', 'Suspected infection or inflammation, prolonged fever, monitoring during treatment, work-up before procedures', 'Sumnja na infekciju ili upalu, dugotrajna temperatura, kontrola tokom liječenja, obrada prije zahvata', 'Сумња на инфекцију или упалу, дуготрајна температура, контрола током лијечења, обрада прије захвата', 'Подозрение на инфекцию или воспаление, длительная температура, контроль во время лечения, обследование перед вмешательствами', 'Verdacht auf Infektion oder Entzündung, länger anhaltendes Fieber, Kontrolle während der Behandlung, Abklärung vor Eingriffen', 'Enfeksiyon veya iltihap kuşkusu, uzayan ateş, tedavi sırasında kontrol, girişimler öncesi değerlendirme', 'No special preparation required; the draw is best done in the morning at rest, without physical exertion right before it', 'Nije potrebna posebna priprema; vađenje je poželjno ujutru u mirnom stanju, bez fizičkog napora neposredno prije njega', 'Није потребна посебна припрема; вађење је пожељно ујутру у мирном стању, без физичког напора непосредно прије њега', 'Специальной подготовки не требуется; забор предпочтителен утром в спокойном состоянии, без физической нагрузки непосредственно перед ним', 'Keine besondere Vorbereitung erforderlich; die Entnahme erfolgt am besten morgens in Ruhe, ohne körperliche Anstrengung unmittelbar davor', 'Özel bir hazırlık gerektirmez; kanın sabah, dinlenmiş durumda ve hemen öncesinde ağır fiziksel çaba olmadan alınması tercih edilir', 'A deviation in the total number may be related to a bacterial or viral infection, inflammation, stress, medication use, or disorders of blood formation. What lies behind the figure is determined by a doctor, who may add a count of the individual white cell types', 'Odstupanje ukupnog broja može biti povezano sa bakterijskom ili virusnom infekcijom, upalom, stresom, uzimanjem lijekova ili poremećajima stvaranja krvi. Šta stoji iza brojke, određuje ljekar, po potrebi uz brojanje pojedinih vrsta leukocita', 'Одступање укупног броја може бити повезано са бактеријском или вирусном инфекцијом, упалом, стресом, узимањем лијекова или поремећајима стварања крви. Шта стоји иза бројке, одређује љекар, по потреби уз бројање појединих врста леукоцита', 'Отклонение общего числа может быть связано с бактериальной или вирусной инфекцией, воспалением, стрессом, приёмом лекарств или нарушениями кроветворения. Что стоит за цифрой, определяет врач, при необходимости добавляя подсчёт отдельных видов лейкоцитов', 'Eine Abweichung der Gesamtzahl kann mit einer bakteriellen oder viralen Infektion, einer Entzündung, Stress, Medikamenteneinnahme oder Störungen der Blutbildung zusammenhängen. Was hinter dem Wert steckt, bestimmt der Arzt und ergänzt bei Bedarf die Auszählung der einzelnen Zelltypen', 'Toplam sayıdaki sapma bakteriyel veya viral enfeksiyon, iltihap, stres, ilaç kullanımı ya da kan yapımı bozukluklarıyla ilişkili olabilir. Sayının arkasında ne olduğunu hekim belirler, gerekirse akyuvar türlerinin ayrı sayımını ekler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'erythrocytes'), 'A count of the red blood cells that carry oxygen from the lungs to the tissues', 'Brojanje crvenih krvnih ćelija koje prenose kiseonik od pluća do tkiva', 'Бројање црвених крвних ћелија које преносе кисеоник од плућа до ткива', 'Подсчёт красных клеток крови, переносящих кислород от лёгких к тканям', 'Auszählung der roten Blutkörperchen, die den Sauerstoff von der Lunge zu den Geweben transportieren', 'Akciğerlerden dokulara oksijen taşıyan alyuvarların sayımı', 'Venous or capillary blood draw; the number of cells per unit of volume is measured on an analyzer', 'Uzimanje venske ili kapilarne krvi, broj ćelija u jedinici zapremine određuje analizator', 'Узимање венске или капиларне крви, број ћелија у јединици запремине одређује анализатор', 'Забор венозной или капиллярной крови, число клеток в единице объёма определяет анализатор', 'Entnahme von venösem oder kapillarem Blut; die Zellzahl pro Volumeneinheit bestimmt das Analysegerät', 'Venöz veya kapiller kan alınır; birim hacimdeki hücre sayısı cihazla ölçülür', 'Weakness and pallor, suspected anemia, follow-up after blood loss, monitoring in chronic kidney and heart disease', 'Slabost i bljedilo, sumnja na anemiju, praćenje nakon gubitka krvi, kontrola kod hroničnih bolesti bubrega i srca', 'Слабост и бљедило, сумња на анемију, праћење након губитка крви, контрола код хроничних болести бубрега и срца', 'Слабость и бледность, подозрение на анемию, наблюдение после кровопотери, контроль при хронических болезнях почек и сердца', 'Schwäche und Blässe, Verdacht auf Anämie, Verlaufskontrolle nach Blutverlust, Kontrolle bei chronischen Nieren- und Herzerkrankungen', 'Halsizlik ve solgunluk, kansızlık kuşkusu, kan kaybı sonrası izlem, kronik böbrek ve kalp hastalıklarında kontrol', 'No special preparation required; sit quietly for a few minutes before the draw, as body position affects the result', 'Nije potrebna posebna priprema; prije vađenja je bolje nekoliko minuta mirno sjediti, jer položaj tijela utiče na nalaz', 'Није потребна посебна припрема; прије вађења је боље неколико минута мирно сједити, јер положај тијела утиче на налаз', 'Специальной подготовки не требуется; перед забором лучше несколько минут посидеть спокойно, положение тела влияет на результат', 'Keine besondere Vorbereitung erforderlich; vor der Entnahme sollte man einige Minuten ruhig sitzen, da die Körperhaltung das Ergebnis beeinflusst', 'Özel bir hazırlık gerektirmez; kan alınmadan önce birkaç dakika sakin oturmak iyi olur, vücut duruşu sonucu etkiler', 'A lower number of red cells may be related to blood loss, a lack of iron or vitamins, or a chronic illness, while a higher one may be related to dehydration or a long-standing lack of oxygen. The conclusions are drawn by a doctor from the whole blood picture', 'Smanjen broj crvenih ćelija može biti povezan sa gubitkom krvi, manjkom gvožđa ili vitamina, hroničnom bolešću, a povećan sa dehidracijom ili dugotrajnim nedostatkom kiseonika. Zaključke donosi ljekar prema cjelokupnoj krvnoj slici', 'Смањен број црвених ћелија може бити повезан са губитком крви, мањком гвожђа или витамина, хроничном болешћу, а повећан са дехидрацијом или дуготрајним недостатком кисеоника. Закључке доноси љекар према цјелокупној крвној слици', 'Снижение числа красных клеток может быть связано с кровопотерей, нехваткой железа или витаминов, хроническим заболеванием, а повышение — с обезвоживанием или длительной нехваткой кислорода. Выводы делает врач по всей картине крови', 'Eine niedrigere Zellzahl kann mit Blutverlust, einem Mangel an Eisen oder Vitaminen oder einer chronischen Erkrankung zusammenhängen, eine höhere mit Flüssigkeitsmangel oder einem länger bestehenden Sauerstoffmangel. Die Schlüsse zieht der Arzt aus dem gesamten Blutbild', 'Alyuvar sayısının azalması kan kaybı, demir veya vitamin eksikliği ya da kronik bir hastalıkla, artması ise sıvı kaybı veya uzun süreli oksijen azlığıyla ilişkili olabilir. Sonucu hekim kan tablosunun tamamına bakarak değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hematocrit'), 'A measure of the share of blood volume taken up by red blood cells', 'Pokazatelj koji dio zapremine krvi zauzimaju eritrociti', 'Показатељ који дио запремине крви заузимају еритроцити', 'Показатель того, какую долю объёма крови занимают эритроциты', 'Ein Maß dafür, welchen Anteil am Blutvolumen die roten Blutkörperchen einnehmen', 'Kan hacminin ne kadarlık bölümünü alyuvarların kapladığını gösteren ölçüt', 'Venous or capillary blood draw; the share is calculated by the analyzer or measured after the tube has been centrifuged', 'Uzimanje venske ili kapilarne krvi; udio izračunava analizator ili se mjeri nakon centrifugiranja epruvete', 'Узимање венске или капиларне крви; удио израчунава анализатор или се мјери након центрифугирања епрувете', 'Забор венозной или капиллярной крови; долю рассчитывает анализатор либо её измеряют после центрифугирования пробирки', 'Entnahme von venösem oder kapillarem Blut; den Anteil berechnet das Analysegerät oder er wird nach dem Zentrifugieren des Röhrchens gemessen', 'Venöz veya kapiller kan alınır; oranı cihaz hesaplar ya da tüp santrifüj edildikten sonra ölçülür', 'Assessment of dehydration, work-up of anemia, follow-up after blood loss, monitoring in chronic lung and kidney disease', 'Procjena dehidracije, obrada anemije, praćenje nakon gubitka krvi, kontrola kod hroničnih bolesti pluća i bubrega', 'Процјена дехидрације, обрада анемије, праћење након губитка крви, контрола код хроничних болести плућа и бубрега', 'Оценка обезвоживания, обследование при анемии, наблюдение после кровопотери, контроль при хронических заболеваниях лёгких и почек', 'Einschätzung eines Flüssigkeitsmangels, Abklärung einer Anämie, Verlaufskontrolle nach Blutverlust, Kontrolle bei chronischen Lungen- und Nierenerkrankungen', 'Sıvı kaybının değerlendirilmesi, kansızlığın araştırılması, kan kaybı sonrası izlem, kronik akciğer ve böbrek hastalıklarında kontrol', 'No special preparation required; tell the doctor about recent vomiting, diarrhea or heavy sweating, as these shift the value', 'Nije potrebna posebna priprema; o skorašnjem povraćanju, proljevu ili obilnom znojenju treba reći ljekaru, jer pomjeraju vrijednost', 'Није потребна посебна припрема; о скорашњем повраћању, прољеву или обилном знојењу треба рећи љекару, јер помјерају вриједност', 'Специальной подготовки не требуется; о недавней рвоте, поносе или обильном потоотделении стоит сказать врачу, они смещают показатель', 'Keine besondere Vorbereitung erforderlich; kürzliches Erbrechen, Durchfall oder starkes Schwitzen sollte dem Arzt mitgeteilt werden, da sie den Wert verschieben', 'Özel bir hazırlık gerektirmez; yakın zamandaki kusma, ishal veya aşırı terleme hekime söylenmelidir, bunlar değeri kaydırır', 'A lower value may be related to anemia or excess body fluid, a higher one to dehydration, smoking, or a long stay at altitude. The value is read together with hemoglobin and the red cell count, and interpreted by a doctor', 'Snižena vrijednost može biti povezana sa anemijom ili viškom tečnosti u organizmu, a povišena sa dehidracijom, pušenjem ili dužim boravkom na visini. Vrijednost se čita zajedno sa hemoglobinom i brojem eritrocita, a tumači je ljekar', 'Снижена вриједност може бити повезана са анемијом или вишком течности у организму, а повишена са дехидрацијом, пушењем или дужим боравком на висини. Вриједност се чита заједно са хемоглобином и бројем еритроцита, а тумачи је љекар', 'Снижение может быть связано с анемией или избытком жидкости в организме, повышение — с обезвоживанием, курением, длительным пребыванием в горах. Показатель читают вместе с гемоглобином и числом эритроцитов, интерпретацию проводит врач', 'Ein niedriger Wert kann mit einer Anämie oder einem Flüssigkeitsüberschuss zusammenhängen, ein hoher mit Flüssigkeitsmangel, Rauchen oder einem längeren Aufenthalt in großer Höhe. Der Wert wird zusammen mit dem Hämoglobin und der Erythrozytenzahl gelesen und vom Arzt gedeutet', 'Değerin düşmesi kansızlık veya vücutta fazla sıvıyla, yükselmesi ise sıvı kaybı, sigara ya da yüksek rakımda uzun süre kalmayla ilişkili olabilir. Değer hemoglobin ve alyuvar sayısıyla birlikte okunur, yorumu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hemoglobin'), 'A measurement of the concentration of the red cell protein that binds and carries oxygen', 'Mjerenje koncentracije bjelančevine eritrocita koja veže i prenosi kiseonik', 'Мјерење концентрације бјеланчевине еритроцита која веже и преноси кисеоник', 'Измерение концентрации белка эритроцитов, который связывает и переносит кислород', 'Messung der Konzentration des Eiweißes der roten Blutkörperchen, das Sauerstoff bindet und transportiert', 'Alyuvarların oksijeni bağlayıp taşıyan proteininin yoğunluğunun ölçülmesi', 'Venous or capillary blood draw; the concentration is measured photometrically on an analyzer', 'Uzimanje venske ili kapilarne krvi, koncentracija se mjeri fotometrijski na analizatoru', 'Узимање венске или капиларне крви, концентрација се мјери фотометријски на анализатору', 'Забор венозной или капиллярной крови, концентрацию измеряют на анализаторе фотометрически', 'Entnahme von venösem oder kapillarem Blut; die Konzentration wird am Analysegerät photometrisch gemessen', 'Venöz veya kapiller kan alınır; yoğunluk cihazda fotometrik olarak ölçülür', 'Weakness, dizziness, shortness of breath on exertion, monitoring during pregnancy, follow-up of anemia treatment, work-up before surgery', 'Slabost, vrtoglavica, nedostatak vazduha pri naporu, praćenje tokom trudnoće, kontrola liječenja anemije, obrada prije operacije', 'Слабост, вртоглавица, недостатак ваздуха при напору, праћење током трудноће, контрола лијечења анемије, обрада прије операције', 'Слабость, головокружение, одышка при нагрузке, наблюдение во время беременности, контроль лечения анемии, обследование перед операцией', 'Schwäche, Schwindel, Atemnot bei Belastung, Kontrolle in der Schwangerschaft, Verlaufskontrolle der Anämiebehandlung, Abklärung vor einer Operation', 'Halsizlik, baş dönmesi, eforla nefes darlığı, gebelikte izlem, kansızlık tedavisinin kontrolü, ameliyat öncesi değerlendirme', 'No special preparation required; tell the doctor about iron supplements and any recent blood transfusion', 'Nije potrebna posebna priprema; o uzimanju preparata gvožđa i skorašnjoj transfuziji treba obavijestiti ljekara', 'Није потребна посебна припрема; о узимању препарата гвожђа и скорашњој трансфузији треба обавијестити љекара', 'Специальной подготовки не требуется; о приёме препаратов железа и недавнем переливании крови нужно сообщить врачу', 'Keine besondere Vorbereitung erforderlich; die Einnahme von Eisenpräparaten und eine kürzliche Bluttransfusion sind dem Arzt mitzuteilen', 'Özel bir hazırlık gerektirmez; demir preparatı kullanımı ve yakın zamanda yapılan kan nakli hekime bildirilir', 'A lower value may be related to a lack of iron or vitamins, blood loss or a chronic illness, a higher one to dehydration or to conditions in which the tissues lack oxygen. The cause is established by a doctor', 'Snižena vrijednost može biti povezana sa manjkom gvožđa ili vitamina, gubitkom krvi ili hroničnom bolešću, a povišena sa dehidracijom ili stanjima u kojima tkivima nedostaje kiseonika. Uzrok utvrđuje ljekar', 'Снижена вриједност може бити повезана са мањком гвожђа или витамина, губитком крви или хроничном болешћу, а повишена са дехидрацијом или стањима у којима ткивима недостаје кисеоника. Узрок утврђује љекар', 'Снижение может быть связано с нехваткой железа, витаминов, кровопотерей или хроническим заболеванием, повышение — с обезвоживанием или состояниями, при которых тканям не хватает кислорода. Причину устанавливает врач', 'Ein niedriger Wert kann mit einem Mangel an Eisen oder Vitaminen, Blutverlust oder einer chronischen Erkrankung zusammenhängen, ein hoher mit Flüssigkeitsmangel oder Zuständen, bei denen den Geweben Sauerstoff fehlt. Die Ursache klärt der Arzt', 'Değerin düşmesi demir veya vitamin eksikliği, kan kaybı ya da kronik bir hastalıkla, yükselmesi sıvı kaybı veya dokuların oksijensiz kaldığı durumlarla ilişkili olabilir. Nedenini hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mch'), 'A calculated value for the average amount of hemoglobin in a single red blood cell', 'Izračunata vrijednost prosječne količine hemoglobina u jednom eritrocitu', 'Израчуната вриједност просјечне количине хемоглобина у једном еритроциту', 'Расчётный показатель среднего количества гемоглобина в одном эритроците', 'Ein rechnerischer Wert für die durchschnittliche Hämoglobinmenge in einem einzelnen roten Blutkörperchen', 'Tek bir alyuvardaki ortalama hemoglobin miktarını gösteren hesaplanmış değer', 'No separate draw is needed: the analyzer derives the value from the red cell count and the total hemoglobin in the same sample', 'Posebno vađenje nije potrebno: analizator izvodi vrijednost iz broja eritrocita i ukupnog hemoglobina u istom uzorku', 'Посебно вађење није потребно: анализатор изводи вриједност из броја еритроцита и укупног хемоглобина у истом узорку', 'Отдельный забор не нужен: значение вычисляет анализатор из числа эритроцитов и общего гемоглобина в той же пробе', 'Eine gesonderte Entnahme ist nicht nötig: Das Analysegerät leitet den Wert aus der Erythrozytenzahl und dem Gesamthämoglobin derselben Probe ab', 'Ayrı kan alımı gerekmez: cihaz değeri aynı örnekteki alyuvar sayısı ve toplam hemoglobinden hesaplar', 'Clarifying the type of anemia, choosing the direction of further work-up when hemoglobin is low, follow-up during treatment', 'Razjašnjenje vrste anemije, izbor smjera dalje obrade kod sniženog hemoglobina, praćenje tokom liječenja', 'Разјашњење врсте анемије, избор смјера даље обраде код сниженог хемоглобина, праћење током лијечења', 'Уточнение вида анемии, выбор направления дальнейшего обследования при сниженном гемоглобине, наблюдение в ходе лечения', 'Klärung der Anämieform, Wahl der weiteren Abklärung bei niedrigem Hämoglobin, Verlaufskontrolle während der Behandlung', 'Kansızlığın türünün netleştirilmesi, hemoglobin düşükken ileri incelemenin yönünün seçilmesi, tedavi sırasında izlem', 'No separate preparation; the value comes from the same blood draw as the rest of the blood count', 'Nema posebne pripreme, pokazatelj se dobija iz istog vađenja krvi kao i ostatak krvne slike', 'Нема посебне припреме, показатељ се добија из истог вађења крви као и остатак крвне слике', 'Отдельной подготовки нет, показатель получают из того же забора крови, что и остальную гемограмму', 'Keine gesonderte Vorbereitung; der Wert stammt aus derselben Blutentnahme wie das übrige Blutbild', 'Ayrı bir hazırlık yoktur; değer, kan sayımının geri kalanıyla aynı kan alımından elde edilir', 'Deviations may be related to a lack of iron, a deficiency of vitamin B12 or folic acid, or inherited features of hemoglobin. On its own the value is not a diagnosis, and a doctor reads it together with MCV and MCHC', 'Odstupanja mogu biti povezana sa manjkom gvožđa, nedostatkom vitamina B12 ili folne kiseline, kao i sa nasljednim osobinama hemoglobina. Sam po sebi pokazatelj nije dijagnoza, ljekar ga čita zajedno sa MCV i MCHC', 'Одступања могу бити повезана са мањком гвожђа, недостатком витамина Б12 или фолне киселине, као и са насљедним особинама хемоглобина. Сам по себи показатељ није дијагноза, љекар га чита заједно са MCV и MCHC', 'Отклонения могут быть связаны с нехваткой железа, дефицитом витамина B12 или фолиевой кислоты, наследственными особенностями гемоглобина. Сам по себе показатель диагноза не даёт, врач читает его вместе с MCV и MCHC', 'Abweichungen können mit Eisenmangel, einem Mangel an Vitamin B12 oder Folsäure oder mit erblichen Besonderheiten des Hämoglobins zusammenhängen. Für sich genommen ist der Wert keine Diagnose, der Arzt liest ihn zusammen mit MCV und MCHC', 'Sapmalar demir azlığı, B12 vitamini veya folik asit eksikliği ya da hemoglobinin kalıtsal özellikleriyle ilişkili olabilir. Değer tek başına tanı koymaz, hekim onu MCV ve MCHC ile birlikte okur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mchc'), 'A calculated value for how saturated a red blood cell is with hemoglobin, that is, its concentration within the cell volume', 'Izračunata vrijednost zasićenosti eritrocita hemoglobinom, odnosno njegove koncentracije u zapremini ćelije', 'Израчуната вриједност засићености еритроцита хемоглобином, односно његове концентрације у запремини ћелије', 'Расчётный показатель насыщенности эритроцита гемоглобином, то есть его концентрации в объёме клетки', 'Ein rechnerischer Wert dafür, wie stark ein rotes Blutkörperchen mit Hämoglobin gesättigt ist, also dessen Konzentration im Zellvolumen', 'Alyuvarın hemoglobinle ne ölçüde dolu olduğunu, yani hücre hacmindeki hemoglobin yoğunluğunu gösteren hesaplanmış değer', 'The analyzer derives the value from the total hemoglobin and the hematocrit of the same blood sample, so no separate procedure is needed', 'Analizator izvodi vrijednost iz ukupnog hemoglobina i hematokrita istog uzorka krvi, pa poseban postupak nije potreban', 'Анализатор изводи вриједност из укупног хемоглобина и хематокрита истог узорка крви, па посебан поступак није потребан', 'Значение выводится анализатором из общего гемоглобина и гематокрита той же пробы крови, отдельная процедура не нужна', 'Das Analysegerät leitet den Wert aus dem Gesamthämoglobin und dem Hämatokrit derselben Blutprobe ab, ein gesonderter Vorgang ist nicht nötig', 'Cihaz değeri aynı kan örneğindeki toplam hemoglobin ve hematokritten çıkarır, bu nedenle ayrı bir işlem gerekmez', 'Clarifying the character of anemia, checking questionable cell values, follow-up in conditions affecting red blood cells', 'Razjašnjenje karaktera anemije, provjera sumnjivih ćelijskih pokazatelja, praćenje kod oboljenja koja zahvataju eritrocite', 'Разјашњење карактера анемије, провјера сумњивих ћелијских показатеља, праћење код обољења која захватају еритроците', 'Уточнение характера анемии, проверка сомнительных клеточных показателей, наблюдение при заболеваниях, затрагивающих эритроциты', 'Klärung der Art einer Anämie, Überprüfung fraglicher Zellwerte, Verlaufskontrolle bei Erkrankungen, die die roten Blutkörperchen betreffen', 'Kansızlığın niteliğinin netleştirilmesi, kuşkulu hücre değerlerinin doğrulanması, alyuvarları etkileyen hastalıklarda izlem', 'No separate preparation; the tube must be filled to the mark, otherwise the calculation comes out inaccurate', 'Nema posebne pripreme; važno je da epruveta bude napunjena do oznake, jer izračun inače ispadne netačan', 'Нема посебне припреме; важно је да епрувета буде напуњена до ознаке, јер израчун иначе испадне нетачан', 'Отдельной подготовки нет; важно, чтобы пробирка была заполнена до метки, иначе расчёт получается неточным', 'Keine gesonderte Vorbereitung; das Röhrchen muss bis zur Markierung gefüllt sein, sonst fällt die Berechnung ungenau aus', 'Ayrı bir hazırlık yoktur; tüpün işarete kadar dolu olması gerekir, aksi halde hesap yanlış çıkar', 'Deviations may be related to forms of anemia and inherited features of red blood cells, and also to technical causes such as a turbid or lipid-rich sample. The significance is assessed by a doctor, and the laboratory repeats the test when in doubt', 'Odstupanja mogu biti povezana sa oblicima anemije i nasljednim osobinama eritrocita, ali i sa tehničkim uzrocima, na primjer mutnim ili masnim uzorkom. Značaj procjenjuje ljekar, a laboratorija kod sumnje ponavlja analizu', 'Одступања могу бити повезана са облицима анемије и насљедним особинама еритроцита, али и са техничким узроцима, на примјер мутним или масним узорком. Значај процјењује љекар, а лабораторија код сумње понавља анализу', 'Отклонения могут быть связаны с формами анемии и наследственными особенностями эритроцитов, а также с техническими причинами, например с мутной или жирной пробой. Значимость оценивает врач, при сомнении лаборатория повторяет анализ', 'Abweichungen können mit Formen der Anämie und erblichen Besonderheiten der roten Blutkörperchen zusammenhängen, aber auch mit technischen Ursachen wie einer trüben oder fettreichen Probe. Die Bedeutung beurteilt der Arzt, im Zweifel wiederholt das Labor die Analyse', 'Sapmalar kansızlık biçimleri ve alyuvarların kalıtsal özellikleriyle olduğu kadar, bulanık ya da yağlı örnek gibi teknik nedenlerle de ilişkili olabilir. Önemini hekim değerlendirir, kuşku halinde laboratuvar analizi yineler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mcv'), 'A calculated value for the average volume of a single red blood cell', 'Izračunata vrijednost prosječne zapremine jednog eritrocita', 'Израчуната вриједност просјечне запремине једног еритроцита', 'Расчётный показатель среднего объёма одного эритроцита', 'Ein rechnerischer Wert für das durchschnittliche Volumen eines einzelnen roten Blutkörperchens', 'Tek bir alyuvarın ortalama hacmini gösteren hesaplanmış değer', 'The analyzer measures the volume of the cells passing its sensor and reports the average for the sample', 'Analizator mjeri zapreminu ćelija koje prolaze kroz senzor i daje prosjek za uzorak', 'Анализатор мјери запремину ћелија које пролазе кроз сензор и даје просјек за узорак', 'Анализатор измеряет объём проходящих через датчик клеток и выводит среднее значение по пробе', 'Das Analysegerät misst das Volumen der am Sensor vorbeiziehenden Zellen und gibt den Mittelwert für die Probe aus', 'Cihaz, sensörden geçen hücrelerin hacmini ölçer ve örnek için ortalamayı bildirir', 'Sorting anemias by red cell size, work-up for a lack of iron, vitamin B12 or folic acid, follow-up during treatment', 'Razvrstavanje anemija prema veličini eritrocita, obrada kod manjka gvožđa, vitamina B12 ili folne kiseline, praćenje tokom liječenja', 'Разврставање анемија према величини еритроцита, обрада код мањка гвожђа, витамина Б12 или фолне киселине, праћење током лијечења', 'Разделение анемий по размеру эритроцитов, обследование при нехватке железа, витамина B12 или фолиевой кислоты, наблюдение в ходе лечения', 'Einteilung von Anämien nach Zellgröße, Abklärung bei Mangel an Eisen, Vitamin B12 oder Folsäure, Verlaufskontrolle während der Behandlung', 'Kansızlıkların alyuvar büyüklüğüne göre ayrılması, demir, B12 vitamini veya folik asit azlığının araştırılması, tedavi sırasında izlem', 'No separate preparation; the sample should reach the laboratory quickly, as cell volume changes during long storage', 'Nema posebne pripreme; uzorak je poželjno brzo dostaviti u laboratoriju, jer se pri dugom stajanju zapremina ćelija mijenja', 'Нема посебне припреме; узорак је пожељно брзо доставити у лабораторију, јер се при дугом стајању запремина ћелија мијења', 'Отдельной подготовки нет; пробу желательно доставить в лабораторию быстро, при долгом хранении объём клеток меняется', 'Keine gesonderte Vorbereitung; die Probe sollte rasch ins Labor gelangen, da sich das Zellvolumen bei langer Lagerung verändert', 'Ayrı bir hazırlık yoktur; örneğin laboratuvara hızla ulaşması istenir, uzun bekleyişte hücre hacmi değişir', 'A smaller or larger average volume may be related to a deficiency of iron, vitamin B12 or folic acid, to liver disease, alcohol use, or inherited features of the red blood cells. The direction of further work-up is decided by a doctor', 'Manja ili veća prosječna zapremina može biti povezana sa nedostatkom gvožđa, vitamina B12 ili folne kiseline, oboljenjima jetre, uzimanjem alkohola ili nasljednim osobinama eritrocita. Smjer dalje obrade određuje ljekar', 'Мања или већа просјечна запремина може бити повезана са недостатком гвожђа, витамина Б12 или фолне киселине, обољењима јетре, узимањем алкохола или насљедним особинама еритроцита. Смјер даље обраде одређује љекар', 'Уменьшенный или увеличенный средний объём может быть связан с дефицитом железа, витамина B12 или фолиевой кислоты, заболеваниями печени, употреблением алкоголя, наследственными особенностями эритроцитов. Направление дальнейшего обследования определяет врач', 'Ein kleineres oder größeres mittleres Volumen kann mit einem Mangel an Eisen, Vitamin B12 oder Folsäure, mit Lebererkrankungen, Alkoholkonsum oder erblichen Besonderheiten der roten Blutkörperchen zusammenhängen. Die Richtung der weiteren Abklärung legt der Arzt fest', 'Ortalama hacmin küçülmesi veya büyümesi demir, B12 vitamini ya da folik asit eksikliği, karaciğer hastalıkları, alkol kullanımı veya alyuvarların kalıtsal özellikleriyle ilişkili olabilir. İleri incelemenin yönünü hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'platelet-count-microscopic'), 'A manual count of blood platelets in a stained smear under the microscope', 'Ručno brojanje krvnih pločica u obojenom razmazu pod mikroskopom', 'Ручно бројање крвних плочица у обојеном размазу под микроскопом', 'Ручной подсчёт кровяных пластинок в окрашенном мазке под микроскопом', 'Manuelle Auszählung der Blutplättchen im gefärbten Ausstrich unter dem Mikroskop', 'Boyalı yaymada kan pulcuklarının mikroskop altında elle sayılması', 'A drop of blood is spread on a slide and stained, and the technician counts the platelets across fields of view, converting the result to a volume', 'Od kapi krvi se pravi razmaz na stakalcu, boji se, a laborant broji pločice u vidnim poljima i preračunava rezultat na zapreminu', 'Од капи крви се прави размаз на стакалцу, боји се, а лаборант броји плочице у видним пољима и прерачунава резултат на запремину', 'Из капли крови готовят мазок на стекле, окрашивают его, и лаборант считает пластинки в полях зрения, пересчитывая результат на объём', 'Aus einem Blutstropfen wird ein Ausstrich auf einem Objektträger angefertigt und gefärbt; die Fachkraft zählt die Plättchen in den Gesichtsfeldern und rechnet das Ergebnis auf das Volumen um', 'Bir damla kandan lam üzerine yayma hazırlanır ve boyanır; laborant pulcukları görüş alanlarında sayar ve sonucu hacme çevirir', 'Checking an unexpectedly low or high automated count, suspected platelet clumping in the tube, clarification before surgery and in case of a bleeding tendency', 'Provjera neočekivano niskog ili visokog automatskog nalaza, sumnja na slijepljivanje pločica u epruveti, razjašnjenje prije operacije i kod sklonosti krvarenju', 'Провјера неочекивано ниског или високог аутоматског налаза, сумња на слијепљивање плочица у епрувети, разјашњење прије операције и код склоности крварењу', 'Проверка неожиданно низкого или высокого результата автоматического счёта, подозрение на слипание пластинок в пробирке, уточнение перед операцией и при склонности к кровоточивости', 'Überprüfung eines unerwartet niedrigen oder hohen automatisch ermittelten Wertes, Verdacht auf Verklumpung der Plättchen im Röhrchen, Klärung vor einer Operation und bei Blutungsneigung', 'Cihazın beklenmedik düşük veya yüksek sonucunun doğrulanması, tüpte pulcukların kümelendiği kuşkusu, ameliyat öncesi ve kanamaya eğilim durumunda netleştirme', 'No special preparation required; the smear is made from fresh blood, so the draw and the slide are prepared at the laboratory', 'Nije potrebna posebna priprema; razmaz se pravi od svježe krvi, pa se vađenje i priprema stakalca obavljaju u laboratoriji', 'Није потребна посебна припрема; размаз се прави од свјеже крви, па се вађење и припрема стакалца обављају у лабораторији', 'Специальной подготовки не требуется; мазок готовят из свежей крови, поэтому забор и приготовление стекла делают в лаборатории', 'Keine besondere Vorbereitung erforderlich; der Ausstrich wird aus frischem Blut angefertigt, daher erfolgen Entnahme und Herstellung des Objektträgers im Labor', 'Özel bir hazırlık gerektirmez; yayma taze kandan hazırlandığı için kan alımı ve lamın hazırlanması laboratuvarda yapılır', 'A discrepancy with the automated count is most often explained by platelet clumping or by features of the sample, while a confirmed deviation in the number may be related to infection, medication use or bone marrow disorders. The conclusion on the result is drawn by a doctor', 'Razlika u odnosu na automatski nalaz najčešće se objašnjava slijepljivanjem pločica ili osobinama uzorka, dok potvrđeno odstupanje broja može biti povezano sa infekcijom, uzimanjem lijekova ili oboljenjima koštane srži. Zaključak o nalazu donosi ljekar', 'Разлика у односу на аутоматски налаз најчешће се објашњава слијепљивањем плочица или особинама узорка, док потврђено одступање броја може бити повезано са инфекцијом, узимањем лијекова или обољењима коштане сржи. Закључак о налазу доноси љекар', 'Расхождение с автоматическим счётом чаще объясняется слипанием пластинок или особенностями образца, а подтверждённое отклонение числа может быть связано с инфекцией, приёмом лекарств или заболеваниями костного мозга. Заключение по результату делает врач', 'Eine Abweichung vom automatisch ermittelten Wert erklärt sich meist durch Verklumpung der Plättchen oder durch Eigenschaften der Probe, während eine bestätigte Abweichung der Zahl mit einer Infektion, Medikamenteneinnahme oder Knochenmarkerkrankungen zusammenhängen kann. Die Beurteilung des Ergebnisses trifft der Arzt', 'Cihaz sonucuyla farklılık çoğunlukla pulcukların kümelenmesi veya örneğin özellikleriyle açıklanır; doğrulanmış bir sayı sapması ise enfeksiyon, ilaç kullanımı ya da kemik iliği hastalıklarıyla ilişkili olabilir. Sonuca ilişkin kararı hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chlamydia-trachomatis-plus-ureaplasma'), 'Testing of a single sample for Chlamydia trachomatis and Ureaplasma DNA by PCR', 'Ispitivanje jednog uzorka na DNK bakterija Chlamydia trachomatis i Ureaplasma metodom PCR', 'Испитивање једног узорка на ДНК бактерија Chlamydia trachomatis и Уреапласма методом ПЦР', 'Совместное исследование одного образца на ДНК Chlamydia trachomatis и уреаплазмы методом ПЦР', 'Untersuchung einer einzigen Probe auf DNA von Chlamydia trachomatis und Ureaplasma mittels PCR', 'Tek bir örnekte Chlamydia trachomatis ve Ureaplasma DNA''sını PCR yöntemiyle arayan inceleme', 'A swab is taken from the urethra, vagina or cervical canal, or the first portion of urine is collected, and both reactions are run from that one sample', 'Uzima se bris iz uretre, vagine ili cervikalnog kanala ili prvi mlaz mokraće, a iz istog uzorka rade se obje reakcije', 'Узима се брис из уретре, вагине или цервикалног канала или први млаз мокраће, а из истог узорка раде се обје реакције', 'Берут мазок из уретры, влагалища или цервикального канала либо собирают первую порцию мочи, из одной пробы ставят обе реакции', 'Es wird ein Abstrich aus Harnröhre, Scheide oder Gebärmutterhalskanal entnommen oder die erste Urinportion aufgefangen, beide Reaktionen laufen aus derselben Probe', 'Üretradan, vajinadan veya serviks kanalından sürüntü alınır ya da ilk idrar akımı toplanır, iki reaksiyon da aynı örnekten çalışılır', 'Burning on urination and discharge, testing of a couple when planning a pregnancy, a check after unprotected intercourse, follow-up as prescribed by a doctor', 'Pečenje pri mokrenju i sekret, ispitivanje para pri planiranju trudnoće, provjera poslije nezaštićenog odnosa, kontrola po nalogu ljekara', 'Печење при мокрењу и секрет, испитивање пара при планирању трудноће, провјера послије незаштићеног односа, контрола по налогу љекара', 'Жжение при мочеиспускании и выделения, обследование пары при планировании беременности, проверка после незащищённого контакта, контроль по назначению врача', 'Brennen beim Wasserlassen und Ausfluss, Untersuchung des Paares bei Kinderwunsch, Kontrolle nach ungeschütztem Verkehr, Verlaufskontrolle auf ärztliche Anordnung', 'İdrar yaparken yanma ve akıntı, gebelik planlayan çiftin incelenmesi, korunmasız ilişki sonrası kontrol, hekim önerisiyle tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the swab, avoid intercourse, suppositories and douching for a day; women are tested outside menstruation', 'Ne mokriti 2–3 sata prije brisa, jedan dan bez odnosa, vaginaleta i ispiranja; žene se testiraju van menstruacije', 'Не мокрити 2–3 сата прије бриса, један дан без односа, вагиналета и испирања; жене се тестирају ван менструације', 'Не мочиться 2–3 часа до мазка, сутки без интимных контактов, свечей и спринцеваний; женщинам сдавать вне менструации', '2–3 Stunden vor dem Abstrich nicht Wasser lassen, einen Tag auf Verkehr, Vaginalzäpfchen und Spülungen verzichten; Frauen werden außerhalb der Menstruation untersucht', 'Sürüntüden 2–3 saat önce idrara çıkmamak, bir gün ilişki, vajinal fitil ve duş uygulamalarından kaçınmak gerekir; kadınlar adet dışı dönemde test edilir', 'The report is issued separately for each organism: Chlamydia trachomatis DNA calls for a doctor''s decision on treatment and on testing the partner, while Ureaplasma is also found in people without complaints. How a combination of findings is read is decided by the doctor', 'Nalaz se izdaje posebno za svakog uzročnika: DNK bakterije Chlamydia trachomatis traži odluku ljekara o liječenju i o pregledu partnera, dok se ureaplazma nalazi i kod osoba bez tegoba. Kako se tumači kombinacija nalaza, odlučuje ljekar', 'Налаз се издаје посебно за сваког узрочника: ДНК бактерије Chlamydia trachomatis тражи одлуку љекара о лијечењу и о прегледу партнера, док се уреаплазма налази и код особа без тегоба. Како се тумачи комбинација налаза, одлучује љекар', 'Ответ приходит отдельно по каждому возбудителю: ДНК Chlamydia trachomatis требует решения врача о лечении и обследовании партнёра, а уреаплазму нередко находят и у людей без жалоб. Как трактовать сочетание находок, определяет врач', 'Der Befund wird für jeden Erreger getrennt ausgegeben: DNA von Chlamydia trachomatis erfordert eine ärztliche Entscheidung über Behandlung und Untersuchung des Partners, Ureaplasmen finden sich auch bei Personen ohne Beschwerden. Wie eine Kombination von Befunden zu werten ist, entscheidet der Arzt', 'Sonuç her etken için ayrı verilir: Chlamydia trachomatis DNA''sı tedavi ve partnerin incelenmesi konusunda hekim kararı gerektirir, Ureaplasma ise yakınması olmayan kişilerde de bulunabilir. Bulguların birlikte nasıl değerlendirileceğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'hpv-41-genotypes-pcr'), 'An extended PCR panel that detects human papillomavirus and identifies which of 41 genotypes are present in the sample', 'Prošireni PCR panel koji otkriva humani papiloma virus i određuje koji su od 41 genotipa prisutni u uzorku', 'Проширени ПЦР панел који открива хумани папилома вирус и одређује који су од 41 генотипа присутни у узорку', 'Расширенная ПЦР-панель, которая выявляет вирус папилломы человека и определяет, какие из 41 генотипа присутствуют в пробе', 'Erweitertes PCR-Panel, das humane Papillomviren nachweist und bestimmt, welche von 41 Genotypen in der Probe vorliegen', 'İnsan papilloma virüsünü saptayan ve 41 genotipten hangilerinin örnekte bulunduğunu belirleyen geniş PCR paneli', 'A swab is taken from the cervical canal, urethra or from skin and mucous membranes; the material is processed in the laboratory and the report lists the genotypes found', 'Uzima se bris iz cervikalnog kanala, uretre ili sa kože i sluznica; materijal se obrađuje u laboratoriji, a u nalazu se navode pronađeni genotipovi', 'Узима се брис из цервикалног канала, уретре или са коже и слузница; материјал се обрађује у лабораторији, а у налазу се наводе пронађени генотипови', 'Берут мазок из цервикального канала, уретры или с кожи и слизистых; материал исследуют в лаборатории, а в заключении перечисляют найденные генотипы', 'Es wird ein Abstrich aus dem Gebärmutterhalskanal, der Harnröhre oder von Haut und Schleimhäuten entnommen; das Material wird im Labor untersucht, der Befund listet die gefundenen Genotypen auf', 'Serviks kanalından, üretradan ya da deri ve mukozadan sürüntü alınır; örnek laboratuvarda çalışılır, raporda bulunan genotipler tek tek belirtilir', 'Cervical screening as ordered by a gynaecologist, changes in a cytology smear, follow-up after treatment of cervical changes, genital warts, examination of partners', 'Skrining grlića materice po uputu ginekologa, promjene u citološkom brisu, praćenje poslije liječenja promjena na grliću, kondilomi, ispitivanje partnera', 'Скрининг грлића материце по упуту гинеколога, промјене у цитолошком брису, праћење послије лијечења промјена на грлићу, кондиломи, испитивање партнера', 'Скрининг шейки матки по назначению гинеколога, изменения в цитологическом мазке, наблюдение после лечения изменений шейки матки, кондиломы, обследование партнёров', 'Screening des Gebärmutterhalses auf gynäkologische Anordnung, Veränderungen im zytologischen Abstrich, Kontrolle nach Behandlung von Veränderungen am Gebärmutterhals, Feigwarzen, Untersuchung von Partnern', 'Kadın hastalıkları hekiminin istediği serviks taraması, sitolojik yaymada değişiklik, servikste saptanan değişikliklerin tedavisinden sonra izlem, genital siğiller, partnerlerin incelenmesi', 'Women are tested outside menstruation, avoid vaginal suppositories and gels for two days and intercourse for one day; do not urinate for 2–3 hours before a urethral swab', 'Žene se testiraju van menstruacije, dva dana ne koristiti vaginalete i gelove, jedan dan izbjegavati odnose; ne mokriti 2–3 sata prije brisa iz uretre', 'Жене се тестирају ван менструације, два дана не користити вагиналете и гелове, један дан избјегавати односе; не мокрити 2–3 сата прије бриса из уретре', 'Женщинам сдавать вне менструации, за двое суток не пользоваться вагинальными свечами и гелями, за сутки исключить интимные контакты; не мочиться 2–3 часа до мазка из уретры', 'Frauen werden außerhalb der Menstruation untersucht, zwei Tage keine Vaginalzäpfchen und Gele verwenden, einen Tag auf Verkehr verzichten; 2–3 Stunden vor einem Harnröhrenabstrich nicht Wasser lassen', 'Kadınlar adet dışı dönemde test edilir, iki gün vajinal fitil ve jel kullanılmaz, bir gün ilişkiden kaçınılır; üretra sürüntüsünden 2–3 saat önce idrara çıkılmaz', 'HPV is a common infection that clears on its own in most people; some genotypes belong to the high oncogenic risk group, which means follow-up is needed rather than a diagnosis. What a particular set of genotypes means, and whether cytology or colposcopy is needed, is decided by the doctor', 'HPV je česta infekcija koja kod većine ljudi prolazi sama; dio genotipova svrstava se u grupu visokog onkogenog rizika, što znači potrebu za praćenjem, a ne dijagnozu. Šta konkretan skup genotipova znači i da li su potrebni citologija ili kolposkopija, procjenjuje ljekar', 'HPV је честа инфекција која код већине људи пролази сама; дио генотипова сврстава се у групу високог онкогеног ризика, што значи потребу за праћењем, а не дијагнозу. Шта конкретан скуп генотипова значи и да ли су потребни цитологија или колпоскопија, процјењује љекар', 'ВПЧ — распространённая инфекция, у большинства людей она проходит самостоятельно; часть генотипов относят к группе высокого онкогенного риска, и это означает необходимость наблюдения, а не диагноз. Что значит конкретный набор генотипов и нужны ли цитология или кольпоскопия, решает врач', 'HPV ist eine häufige Infektion, die bei den meisten Menschen von selbst ausheilt; ein Teil der Genotypen zählt zur Gruppe mit hohem onkogenem Risiko, was eine Kontrolle und keine Diagnose bedeutet. Was ein bestimmtes Genotypenmuster bedeutet und ob Zytologie oder Kolposkopie nötig sind, entscheidet der Arzt', 'HPV sık görülen ve çoğu kişide kendiliğinden geçen bir enfeksiyondur; genotiplerin bir bölümü yüksek onkojenik risk grubunda sayılır, bu da tanı değil izlem gerektiği anlamına gelir. Belirli bir genotip grubunun ne ifade ettiğine, sitoloji ya da kolposkopi gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'neisseria-gonorrhoeae-pcr-urine'), 'Detection of Neisseria gonorrhoeae DNA in urine by PCR, without a urethral swab', 'Otkrivanje DNK bakterije Neisseria gonorrhoeae iz mokraće metodom PCR, bez uzimanja brisa iz uretre', 'Откривање ДНК бактерије Neisseria gonorrhoeae из мокраће методом ПЦР, без узимања бриса из уретре', 'Выявление ДНК бактерии Neisseria gonorrhoeae в моче методом ПЦР, без взятия мазка из уретры', 'Nachweis von DNA des Erregers Neisseria gonorrhoeae im Urin mittels PCR, ohne Harnröhrenabstrich', 'İdrarda Neisseria gonorrhoeae DNA''sını PCR yöntemiyle, üretra sürüntüsü almadan saptayan test', 'The first portion of urine collected into a sterile container is enough: sampling is painless and the DNA is extracted and detected in the laboratory', 'Dovoljan je prvi mlaz mokraće sakupljen u sterilnu posudu: uzimanje je bezbolno, a DNK se izdvaja i određuje u laboratoriji', 'Довољан је први млаз мокраће сакупљен у стерилну посуду: узимање је безболно, а ДНК се издваја и одређује у лабораторији', 'Достаточно первой порции мочи, собранной в стерильный контейнер: забор безболезненный, ДНК выделяют и определяют в лаборатории', 'Es genügt die erste Urinportion in einem sterilen Becher: die Gewinnung ist schmerzfrei, die DNA wird im Labor isoliert und bestimmt', 'Steril kaba toplanan ilk idrar akımı yeterlidir: örnek alma ağrısızdır, DNA laboratuvarda ayrıştırılıp belirlenir', 'Purulent discharge from the urethra or vagina, pain and stinging on urination, testing after unprotected intercourse, testing of a partner, test of cure as prescribed by a doctor', 'Gnojav sekret iz uretre ili vagine, bol i peckanje pri mokrenju, provjera poslije nezaštićenog odnosa, pregled partnera, kontrola izliječenja po nalogu ljekara', 'Гнојав секрет из уретре или вагине, бол и пецкање при мокрењу, провјера послије незаштићеног односа, преглед партнера, контрола излијечења по налогу љекара', 'Гнойные выделения из уретры или влагалища, боль и резь при мочеиспускании, обследование после незащищённого контакта, обследование партнёра, контроль излеченности по назначению врача', 'Eitriger Ausfluss aus Harnröhre oder Scheide, Schmerzen und Brennen beim Wasserlassen, Untersuchung nach ungeschütztem Verkehr, Untersuchung des Partners, Heilungskontrolle auf ärztliche Anordnung', 'Üretradan ya da vajinadan gelen iltihaplı akıntı, idrar yaparken ağrı ve yanma, korunmasız ilişki sonrası inceleme, partnerin incelenmesi, hekim önerisiyle iyileşme kontrolü', 'Do not urinate for 2–3 hours before collection, take the very first portion of the stream, use no antiseptics for hygiene; when to test after antibiotics is decided by the doctor', 'Ne mokriti 2–3 sata prije sakupljanja, uzeti sasvim prvi mlaz, bez antiseptika pri higijeni; kada se test radi poslije antibiotika, određuje ljekar', 'Не мокрити 2–3 сата прије сакупљања, узети сасвим први млаз, без антисептика при хигијени; када се тест ради послије антибиотика, одређује љекар', 'Не мочиться 2–3 часа до сбора, собирать самую первую порцию струи, без антисептиков при гигиене; когда сдавать после антибиотиков, говорит врач', '2–3 Stunden vor der Gewinnung nicht Wasser lassen, genau die allererste Portion des Strahls auffangen, keine Antiseptika zur Reinigung verwenden; den Zeitpunkt nach einer Antibiotikatherapie legt der Arzt fest', 'Toplamadan 2–3 saat önce idrara çıkmamak, akımın en başındaki bölümü almak, temizlikte antiseptik kullanmamak gerekir; antibiyotikten sonra testin ne zaman yapılacağını hekim belirler', 'Detected DNA means the organism is present in the sample; PCR does not show antibiotic susceptibility, so the doctor may additionally order a culture. Treatment and testing of the partner are prescribed by the doctor', 'Nalaz DNK znači da je uzročnik prisutan u uzorku; PCR pri tome ne pokazuje osjetljivost na antibiotike, pa ljekar može dodatno tražiti kulturu. Liječenje i pregled partnera određuje ljekar', 'Налаз ДНК значи да је узрочник присутан у узорку; ПЦР при томе не показује осјетљивост на антибиотике, па љекар може додатно тражити културу. Лијечење и преглед партнера одређује љекар', 'Обнаружение ДНК означает, что возбудитель есть в пробе; ПЦР при этом не показывает чувствительность к антибиотикам, поэтому врач может дополнительно назначить посев. Лечение и обследование партнёра назначает врач', 'Nachgewiesene DNA bedeutet, dass der Erreger in der Probe vorhanden ist; die PCR zeigt dabei keine Antibiotikaempfindlichkeit, daher kann der Arzt zusätzlich eine Kultur veranlassen. Behandlung und Untersuchung des Partners ordnet der Arzt an', 'DNA saptanması etkenin örnekte bulunduğunu gösterir; PCR antibiyotik duyarlılığını göstermez, bu nedenle hekim ayrıca kültür isteyebilir. Tedaviyi ve partnerin incelenmesini hekim düzenler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chlamydia-trachomatis-mycoplasma-hominis-genitalium-pcr'), 'A panel of three targets: DNA of Chlamydia trachomatis, Mycoplasma hominis and Mycoplasma genitalium in one test', 'Panel sa tri cilja: DNK bakterija Chlamydia trachomatis, Mycoplasma hominis i Mycoplasma genitalium u jednom ispitivanju', 'Панел са три циља: ДНК бактерија Chlamydia trachomatis, Mycoplasma hominis и Mycoplasma genitalium у једном испитивању', 'Панель из трёх мишеней: ДНК Chlamydia trachomatis, Mycoplasma hominis и Mycoplasma genitalium в одном исследовании', 'Panel mit drei Zielen: DNA von Chlamydia trachomatis, Mycoplasma hominis und Mycoplasma genitalium in einer Untersuchung', 'Tek incelemede üç hedefi arayan panel: Chlamydia trachomatis, Mycoplasma hominis ve Mycoplasma genitalium DNA''sı', 'Three separate PCR reactions are run from a single swab or urine portion and the result is reported for each organism', 'Iz jednog brisa ili porcije mokraće rade se tri odvojene PCR reakcije, a nalaz se izdaje za svakog uzročnika', 'Из једног бриса или порције мокраће раде се три одвојене ПЦР реакције, а налаз се издаје за сваког узрочника', 'Из одного мазка или порции мочи ставят три отдельные ПЦР-реакции, результат выдают по каждому возбудителю', 'Aus einem Abstrich oder einer Urinportion laufen drei getrennte PCR-Reaktionen, das Ergebnis wird für jeden Erreger einzeln ausgewiesen', 'Tek bir sürüntü ya da idrar örneğinden üç ayrı PCR reaksiyonu çalışılır, sonuç her etken için ayrı bildirilir', 'Inflammation of the urethra and cervix, lower abdominal pain, investigation of infertility in a couple, a check after unprotected intercourse, recurring complaints when routine cultures are negative', 'Zapaljenje uretre i grlića materice, bol u donjem dijelu stomaka, obrada neplodnosti kod para, provjera poslije nezaštićenog odnosa, ponovljene tegobe uz uredne kulture', 'Запаљење уретре и грлића материце, бол у доњем дијелу стомака, обрада неплодности код пара, провјера послије незаштићеног односа, поновљене тегобе уз уредне културе', 'Воспаление уретры и шейки матки, боли внизу живота, обследование при бесплодии в паре, проверка после незащищённого контакта, повторяющиеся жалобы при отрицательных посевах', 'Entzündung von Harnröhre und Gebärmutterhals, Schmerzen im Unterbauch, Abklärung von unerfülltem Kinderwunsch beim Paar, Kontrolle nach ungeschütztem Verkehr, wiederkehrende Beschwerden bei unauffälligen Kulturen', 'Üretra ve serviks iltihabı, kasık ağrısı, çiftte kısırlık araştırması, korunmasız ilişki sonrası kontrol, kültürler normalken yinelenen yakınmalar', 'Do not urinate for 2–3 hours before sampling, avoid intercourse and local preparations for a day, women are tested outside menstruation; the interval after antibiotics is set by the doctor', 'Ne mokriti 2–3 sata prije uzimanja materijala, jedan dan bez odnosa i lokalnih preparata, žene se testiraju van menstruacije; razmak poslije antibiotika određuje ljekar', 'Не мокрити 2–3 сата прије узимања материјала, један дан без односа и локалних препарата, жене се тестирају ван менструације; размак послије антибиотика одређује љекар', 'Не мочиться 2–3 часа до взятия материала, сутки без интимных контактов и местных препаратов, женщинам сдавать вне менструации; интервал после антибиотиков назначает врач', '2–3 Stunden vor der Probennahme nicht Wasser lassen, einen Tag auf Verkehr und lokale Präparate verzichten, Frauen außerhalb der Menstruation; den Abstand nach Antibiotika legt der Arzt fest', 'Örnek alınmadan 2–3 saat önce idrara çıkmamak, bir gün ilişki ve bölgesel ilaçlardan kaçınmak gerekir, kadınlar adet dışı dönemde test edilir; antibiyotik sonrası bekleme süresini hekim belirler', 'The report shows which of the three organisms was detected: Chlamydia trachomatis and Mycoplasma genitalium each call for a separate decision by the doctor on treatment and on testing the partner, while Mycoplasma hominis is often present without complaints. The meaning of a combination of findings is assessed by the doctor', 'U nalazu se vidi DNK kojeg je od tri uzročnika pronađena: Chlamydia trachomatis i Mycoplasma genitalium traže posebnu odluku ljekara o liječenju i o pregledu partnera, dok se Mycoplasma hominis često nalazi i bez tegoba. Značenje kombinacije nalaza procjenjuje ljekar', 'У налазу се види ДНК којег је од три узрочника пронађена: Chlamydia trachomatis и Mycoplasma genitalium траже посебну одлуку љекара о лијечењу и о прегледу партнера, док се Mycoplasma hominis често налази и без тегоба. Значење комбинације налаза процјењује љекар', 'В заключении видно, ДНК какого из трёх возбудителей найдена: Chlamydia trachomatis и Mycoplasma genitalium требуют отдельного решения врача о лечении и об обследовании партнёра, а Mycoplasma hominis часто встречается и без жалоб. Значение сочетания находок оценивает врач', 'Der Befund zeigt, welcher der drei Erreger nachgewiesen wurde: Chlamydia trachomatis und Mycoplasma genitalium erfordern jeweils eine eigene ärztliche Entscheidung über Behandlung und Untersuchung des Partners, Mycoplasma hominis kommt häufig auch ohne Beschwerden vor. Die Bedeutung einer Befundkombination beurteilt der Arzt', 'Raporda üç etkenden hangisinin DNA''sının bulunduğu görülür: Chlamydia trachomatis ve Mycoplasma genitalium için tedavi ve partnerin incelenmesi konusunda ayrı ayrı hekim kararı gerekir, Mycoplasma hominis ise çoğu kez yakınma olmadan da bulunur. Bulguların birlikte ne ifade ettiğini hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chlamydia-trachomatis-ureaplasma-urealyticum-mycoplasma-hominis-genitalium-pcr'), 'An extended urogenital panel for the DNA of four organisms: Chlamydia trachomatis, Ureaplasma urealyticum, Mycoplasma hominis and Mycoplasma genitalium', 'Prošireni urogenitalni panel na DNK četiri uzročnika: Chlamydia trachomatis, Ureaplasma urealyticum, Mycoplasma hominis i Mycoplasma genitalium', 'Проширени урогенитални панел на ДНК четири узрочника: Chlamydia trachomatis, Ureaplasma urealyticum, Mycoplasma hominis и Mycoplasma genitalium', 'Расширенная урогенитальная панель на ДНК четырёх возбудителей: Chlamydia trachomatis, Ureaplasma urealyticum, Mycoplasma hominis и Mycoplasma genitalium', 'Erweitertes urogenitales Panel auf DNA von vier Erregern: Chlamydia trachomatis, Ureaplasma urealyticum, Mycoplasma hominis und Mycoplasma genitalium', 'Dört etkenin DNA''sını arayan geniş ürogenital panel: Chlamydia trachomatis, Ureaplasma urealyticum, Mycoplasma hominis ve Mycoplasma genitalium', 'One swab from the urethra, vagina or cervical canal, or a urine portion, is enough for all four reactions, with a separate answer for each target', 'Jedan bris iz uretre, vagine ili cervikalnog kanala ili porcija mokraće dovoljni su za sve četiri reakcije, a odgovor se dobija za svaki cilj posebno', 'Један брис из уретре, вагине или цервикалног канала или порција мокраће довољни су за све четири реакције, а одговор се добија за сваки циљ посебно', 'Одного мазка из уретры, влагалища или цервикального канала либо порции мочи хватает на все четыре реакции, ответ приходит по каждой мишени', 'Ein Abstrich aus Harnröhre, Scheide oder Gebärmutterhalskanal oder eine Urinportion reicht für alle vier Reaktionen, das Ergebnis wird für jedes Ziel gesondert angegeben', 'Üretradan, vajinadan ya da serviks kanalından alınan tek sürüntü veya bir idrar örneği dört reaksiyonun tamamına yeter, her hedef için ayrı yanıt verilir', 'A comprehensive check of the urogenital tract from a single sample, preparation for intrauterine procedures and IVF programmes, long-standing discharge and discomfort with no established cause, examination of both partners', 'Sveobuhvatna provjera mokraćno-polnog sistema iz jednog uzorka, priprema za intrauterine zahvate i programe vantjelesne oplodnje, dugotrajan sekret i nelagodnost bez utvrđenog uzroka, pregled oba partnera', 'Свеобухватна провјера мокраћно-полног система из једног узорка, припрема за интраутерине захвате и програме вантјелесне оплодње, дуготрајан секрет и нелагодност без утврђеног узрока, преглед оба партнера', 'Комплексное обследование мочеполовой системы одним забором, подготовка к внутриматочным вмешательствам и к программам ЭКО, длительные выделения и дискомфорт без установленной причины, обследование обоих партнёров', 'Umfassende Abklärung des Urogenitaltrakts aus einer einzigen Probe, Vorbereitung auf intrauterine Eingriffe und IVF-Programme, langanhaltender Ausfluss und Beschwerden ohne geklärte Ursache, Untersuchung beider Partner', 'Tek örnekle ürogenital sistemin kapsamlı incelenmesi, rahim içi işlemlere ve tüp bebek programlarına hazırlık, nedeni bulunamayan uzun süreli akıntı ve rahatsızlık, her iki partnerin incelenmesi', 'Women are tested outside menstruation, stop vaginal suppositories and gels three days beforehand, avoid intercourse for a day, do not urinate for 2–3 hours before the swab', 'Žene se testiraju van menstruacije, tri dana ranije prekinuti vaginalete i gelove, jedan dan izbjegavati odnose, ne mokriti 2–3 sata prije brisa', 'Жене се тестирају ван менструације, три дана раније прекинути вагиналете и гелове, један дан избјегавати односе, не мокрити 2–3 сата прије бриса', 'Женщинам сдавать вне менструации, за трое суток отменить вагинальные свечи и гели, за сутки исключить интимные контакты, не мочиться 2–3 часа до мазка', 'Frauen werden außerhalb der Menstruation untersucht, Vaginalzäpfchen und Gele drei Tage vorher absetzen, einen Tag auf Verkehr verzichten, 2–3 Stunden vor dem Abstrich nicht Wasser lassen', 'Kadınlar adet dışı dönemde test edilir, vajinal fitil ve jeller üç gün önce bırakılır, bir gün ilişkiden kaçınılır, sürüntüden 2–3 saat önce idrara çıkılmaz', 'The panel answers for each organism separately, and some of them, above all Ureaplasma and Mycoplasma hominis, are found in people without complaints, which is not a reason to treat every finding. Which findings matter in a particular situation is decided by the doctor', 'Panel daje odgovor za svakog uzročnika posebno, a dio njih, prije svega ureaplazmu i Mycoplasma hominis, nalazimo i kod osoba bez tegoba, pa to nije razlog da se liječi svaki nalaz. Koji su nalazi značajni u konkretnoj situaciji, procjenjuje ljekar', 'Панел даје одговор за сваког узрочника посебно, а дио њих, прије свега уреаплазму и Mycoplasma hominis, налазимо и код особа без тегоба, па то није разлог да се лијечи сваки налаз. Који су налази значајни у конкретној ситуацији, процјењује љекар', 'Панель отвечает по каждому возбудителю отдельно, и часть из них, прежде всего уреаплазму и Mycoplasma hominis, находят у людей без жалоб — это не повод лечить всё найденное подряд. Какие находки значимы в конкретной ситуации, определяет врач', 'Das Panel weist jeden Erreger einzeln aus, und ein Teil davon, vor allem Ureaplasmen und Mycoplasma hominis, findet sich auch bei Personen ohne Beschwerden, was kein Grund ist, jeden Befund zu behandeln. Welche Befunde im Einzelfall bedeutsam sind, entscheidet der Arzt', 'Panel her etken için ayrı sonuç verir; bunların bir bölümü, özellikle Ureaplasma ve Mycoplasma hominis, yakınması olmayan kişilerde de bulunur, bu nedenle her bulguyu tedavi etmek gerekmez. Hangi bulgunun o durumda önemli olduğuna hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'influenza-a-plus-b-pcr'), 'A molecular test that detects influenza virus RNA and distinguishes type A from type B', 'Molekularni test koji otkriva RNK virusa gripa i razlikuje tip A od tipa B', 'Молекуларни тест који открива РНК вируса грипа и разликује тип А од типа Б', 'Молекулярный тест, который выявляет РНК вирусов гриппа и различает тип A и тип B', 'Molekularer Test, der RNA von Influenzaviren nachweist und Typ A von Typ B unterscheidet', 'Grip virüslerinin RNA''sını saptayan ve A tipini B tipinden ayıran moleküler test', 'A swab from the nasopharynx, less often from the throat; sampling takes under a minute and the RNA is detected by PCR', 'Bris štapićem iz nazofarinksa, rjeđe iz ždrijela; uzimanje traje kraće od minuta, a RNK se određuje metodom PCR', 'Брис штапићем из назофаринкса, рјеђе из ждријела; узимање траје краће од минута, а РНК се одређује методом ПЦР', 'Мазок тампоном из носоглотки, реже из зева; забор занимает меньше минуты, РНК определяют методом ПЦР', 'Abstrich mit einem Tupfer aus dem Nasenrachenraum, seltener aus dem Rachen; die Entnahme dauert weniger als eine Minute, die RNA wird mittels PCR bestimmt', 'Genizden, daha seyrek olarak boğazdan çubukla sürüntü alınır; işlem bir dakikadan kısa sürer, RNA PCR yöntemiyle belirlenir', 'A sudden onset with high fever, aching and headache during the flu season, a severe respiratory infection in children, older people, pregnant women and people with chronic conditions, an outbreak in a group', 'Nagli početak bolesti sa visokom temperaturom, bolovi u mišićima i glavobolja u sezoni gripa, teža respiratorna infekcija kod djece, starijih, trudnica i osoba sa hroničnim bolestima, epidemija u kolektivu', 'Нагли почетак болести са високом температуром, болови у мишићима и главобоља у сезони грипа, тежа респираторна инфекција код дјеце, старијих, трудница и особа са хроничним болестима, епидемија у колективу', 'Резкое начало болезни с высокой температурой, ломота и головная боль в сезон гриппа, тяжёлое течение респираторной инфекции у детей, пожилых, беременных и людей с хроническими болезнями, вспышка в коллективе', 'Plötzlicher Beginn mit hohem Fieber, Gliederschmerzen und Kopfschmerzen in der Grippesaison, schwerer Verlauf eines Atemwegsinfekts bei Kindern, älteren Menschen, Schwangeren und Personen mit chronischen Erkrankungen, Ausbruch in einer Gemeinschaft', 'Grip mevsiminde yüksek ateşle ani başlayan hastalık, kas ağrısı ve baş ağrısı, çocuklarda, yaşlılarda, gebelerde ve kronik hastalığı olanlarda ağır seyreden solunum yolu enfeksiyonu, toplu yaşanan yerlerde salgın', 'For an hour before the swab do not eat or drink, do not gargle and do not use nasal drops or sprays; the sample is best taken in the first days of the illness', 'Sat prije brisa ne jesti i ne piti, ne ispirati grlo, ne koristiti kapi i sprejeve za nos; uzorak je najbolje uzeti u prvim danima bolesti', 'Сат прије бриса не јести и не пити, не испирати грло, не користити капи и спрејеве за нос; узорак је најбоље узети у првим данима болести', 'За час до мазка не есть и не пить, не полоскать горло, не использовать капли и спреи для носа; материал лучше брать в первые дни болезни', 'Eine Stunde vor dem Abstrich nichts essen und trinken, nicht gurgeln, keine Nasentropfen oder Nasensprays verwenden; die Probe wird am besten in den ersten Krankheitstagen entnommen', 'Sürüntüden bir saat önce yememek, içmemek, gargara yapmamak, burun damlası ve spreyi kullanmamak gerekir; örneği hastalığın ilk günlerinde almak en iyisidir', 'Detected RNA shows which type of influenza virus caused the illness; a negative result late in the illness does not always rule influenza out. Treatment and monitoring are decided by the doctor', 'Nalaz RNK pokazuje koji je tip virusa gripa izazvao bolest; negativan nalaz u kasnijoj fazi bolesti ne isključuje uvijek grip. Liječenje i praćenje određuje ljekar', 'Налаз РНК показује који је тип вируса грипа изазвао болест; негативан налаз у каснијој фази болести не искључује увијек грип. Лијечење и праћење одређује љекар', 'Обнаружение РНК показывает, каким типом вируса гриппа вызвано заболевание; отрицательный результат на поздних сроках болезни не всегда исключает грипп. Тактику лечения и наблюдения определяет врач', 'Nachgewiesene RNA zeigt, welcher Influenzatyp die Erkrankung verursacht hat; ein negatives Ergebnis in einer späteren Krankheitsphase schließt eine Grippe nicht immer aus. Über Behandlung und Kontrolle entscheidet der Arzt', 'Saptanan RNA hastalığa hangi grip virüsü tipinin yol açtığını gösterir; hastalığın geç döneminde negatif sonuç gribi her zaman dışlamaz. Tedavi ve izlem kararını hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mycoplasma-hominis-genitalium-pcr'), 'A test that separates the DNA of two mycoplasmas, Mycoplasma hominis and Mycoplasma genitalium, within a single analysis', 'Ispitivanje koje u jednoj analizi razdvaja DNK dvije mikoplazme, Mycoplasma hominis i Mycoplasma genitalium', 'Испитивање које у једној анализи раздваја ДНК двије микоплазме, Mycoplasma hominis и Mycoplasma genitalium', 'Исследование, которое в одном анализе разделяет ДНК двух микоплазм — Mycoplasma hominis и Mycoplasma genitalium', 'Untersuchung, die in einer Analyse die DNA zweier Mykoplasmen trennt: Mycoplasma hominis und Mycoplasma genitalium', 'Tek analizde iki mikoplazmanın, Mycoplasma hominis ve Mycoplasma genitalium''un DNA''sını ayrı ayrı gösteren inceleme', 'A swab is taken from the urethra, vagina or cervical canal, or the first urine portion; the laboratory runs its own reaction for each species', 'Uzima se bris iz uretre, vagine ili cervikalnog kanala ili prvi mlaz mokraće; u laboratoriji se za svaku vrstu radi zasebna reakcija', 'Узима се брис из уретре, вагине или цервикалног канала или први млаз мокраће; у лабораторији се за сваку врсту ради засебна реакција', 'Берут мазок из уретры, влагалища или цервикального канала либо первую порцию мочи; в лаборатории для каждого вида ставят свою реакцию', 'Es wird ein Abstrich aus Harnröhre, Scheide oder Gebärmutterhalskanal oder die erste Urinportion gewonnen; im Labor läuft für jede Art eine eigene Reaktion', 'Üretradan, vajinadan ya da serviks kanalından sürüntü veya ilk idrar akımı alınır; laboratuvarda her tür için ayrı reaksiyon çalışılır', 'Urethritis and cervicitis with no identified cause, discomfort and discharge, examination of partners, preparation for gynaecological procedures, follow-up after treatment as prescribed', 'Uretritis i cervicitis bez utvrđenog uzroka, nelagodnost i sekret, pregled partnera, priprema za ginekološke zahvate, kontrola poslije liječenja po nalogu ljekara', 'Уретритис и цервицитис без утврђеног узрока, нелагодност и секрет, преглед партнера, припрема за гинеколошке захвате, контрола послије лијечења по налогу љекара', 'Уретрит и цервицит без выявленной причины, дискомфорт и выделения, обследование партнёров, подготовка к гинекологическим вмешательствам, контроль после лечения по назначению врача', 'Harnröhren- und Gebärmutterhalsentzündung ohne geklärte Ursache, Beschwerden und Ausfluss, Untersuchung von Partnern, Vorbereitung auf gynäkologische Eingriffe, Kontrolle nach Behandlung auf ärztliche Anordnung', 'Nedeni bulunamayan üretrit ve servisit, rahatsızlık ve akıntı, partnerlerin incelenmesi, jinekolojik işlemlere hazırlık, hekim önerisiyle tedavi sonrası kontrol', 'Do not urinate for 2–3 hours before the swab, avoid intercourse and local preparations for a day, women are tested outside menstruation', 'Ne mokriti 2–3 sata prije brisa, dan ranije izbjegavati odnose i lokalne preparate, žene se testiraju van menstruacije', 'Не мокрити 2–3 сата прије бриса, дан раније избјегавати односе и локалне препарате, жене се тестирају ван менструације', 'Не мочиться 2–3 часа до мазка, за сутки исключить интимные контакты и местные препараты, женщинам сдавать вне менструации', '2–3 Stunden vor dem Abstrich nicht Wasser lassen, einen Tag auf Verkehr und lokale Präparate verzichten, Frauen außerhalb der Menstruation', 'Sürüntüden 2–3 saat önce idrara çıkmamak, bir gün ilişki ve bölgesel ilaçlardan kaçınmak gerekir, kadınlar adet dışı dönemde test edilir', 'The two species carry different weight: Mycoplasma genitalium is counted among sexually transmitted organisms, while Mycoplasma hominis is often found in people without complaints. The doctor therefore reads the result for each species separately, together with symptoms and other tests', 'Dvije vrste nemaju isti značaj: Mycoplasma genitalium se ubraja u uzročnike polno prenosivih infekcija, dok se Mycoplasma hominis često nalazi i kod osoba bez tegoba. Zato ljekar nalaz za svaku vrstu tumači posebno, uz simptome i druge analize', 'Двије врсте немају исти значај: Mycoplasma genitalium се убраја у узрочнике полно преносивих инфекција, док се Mycoplasma hominis често налази и код особа без тегоба. Зато љекар налаз за сваку врсту тумачи посебно, уз симптоме и друге анализе', 'Два вида имеют разное значение: Mycoplasma genitalium относят к возбудителям инфекций, передающихся половым путём, а Mycoplasma hominis нередко обнаруживают и у людей без жалоб. Поэтому результат по каждому виду врач оценивает отдельно, вместе с симптомами и другими анализами', 'Die beiden Arten haben unterschiedliche Bedeutung: Mycoplasma genitalium zählt zu den sexuell übertragbaren Erregern, Mycoplasma hominis findet sich häufig auch bei Personen ohne Beschwerden. Der Arzt beurteilt den Befund daher für jede Art getrennt, zusammen mit den Beschwerden und weiteren Untersuchungen', 'İki türün anlamı aynı değildir: Mycoplasma genitalium cinsel yolla bulaşan enfeksiyon etkenleri arasında sayılır, Mycoplasma hominis ise yakınması olmayan kişilerde de sık bulunur. Bu nedenle hekim her tür için sonucu ayrı ayrı, belirtiler ve diğer tetkiklerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'factor-v-leiden-locus-1691'), 'Molecular genetic test of position 1691 in the coagulation factor V gene, where the Leiden variant is located', 'Molekularno-genetičko ispitivanje pozicije 1691 u genu za faktor V koagulacije, na kojoj se nalazi varijanta Leiden', 'Молекуларно-генетичко испитивање позиције 1691 у гену за фактор В коагулације, на којој се налази варијанта Леиден', 'Молекулярно-генетическое исследование позиции 1691 гена фактора V свёртывания крови, в которой находится вариант Leiden', 'Molekulargenetische Untersuchung der Position 1691 im Gen des Gerinnungsfaktors V, an der die Leiden-Variante liegt', 'Pıhtılaşma faktörü V geninde Leiden varyantının bulunduğu 1691 pozisyonunun moleküler genetik incelemesi', 'A venous blood sample is taken, DNA is extracted and PCR determines which variant is present and whether one or both copies of the gene are affected', 'Uzima se venska krv, iz nje se izdvaja DNK i metodom PCR se utvrđuje koja je varijanta prisutna i da li je zahvaćena jedna ili su zahvaćene obje kopije gena', 'Узима се венска крв, из ње се издваја ДНК и методом ПЦР се утврђује која је варијанта присутна и да ли је захваћена једна или су захваћене обје копије гена', 'Забор венозной крови, из неё выделяют ДНК и методом PCR определяют, какой вариант в этой позиции и затронута ли одна копия гена или обе', 'Es wird venöses Blut entnommen, daraus DNA gewonnen und mittels PCR bestimmt, welche Variante vorliegt und ob eine oder beide Genkopien betroffen sind', 'Toplardamardan kan alınır, DNA ayrıştırılır ve PCR yöntemiyle bu pozisyondaki varyant ile genin bir ya da iki kopyasının etkilenip etkilenmediği belirlenir', 'Work-up after venous thrombosis, especially at a young age or without an obvious cause, thrombosis in close relatives, recurrent pregnancy loss, assessment before hormone therapy as referred by a doctor', 'Obrada nakon venske tromboze, posebno u mlađem životnom dobu ili bez jasnog uzroka, tromboze kod bliskih srodnika, ponovljeni gubici trudnoće, procjena uoči hormonske terapije po uputu ljekara', 'Обрада након венске тромбозе, посебно у млађем животном добу или без јасног узрока, тромбозе код блиских сродника, поновљени губици трудноће, процјена уочи хормонске терапије по упуту љекара', 'Обследование после венозного тромбоза, особенно в молодом возрасте или без явной причины, тромбозы у близких родственников, повторные потери беременности, обследование перед гормональной терапией по направлению врача', 'Abklärung nach einer venösen Thrombose, besonders in jungem Alter oder ohne erkennbare Ursache, Thrombosen bei nahen Verwandten, wiederholte Fehlgeburten, Beurteilung vor einer Hormontherapie auf ärztliche Überweisung', 'Özellikle genç yaşta veya belirgin bir neden olmadan gelişen venöz tromboz sonrası inceleme, yakın akrabalarda tromboz, yinelenen gebelik kayıpları, hekim yönlendirmesiyle hormon tedavisi öncesi değerlendirme', 'No special preparation is needed and fasting is not required; the test is done once in a lifetime, and information about thrombosis in the family is useful to bring along', 'Posebna priprema nije potrebna i ne dolazi se natašte; analiza se radi jednom u životu, a korisno je ponijeti podatke o trombozama u porodici', 'Посебна припрема није потребна и не долази се наташте; анализа се ради једном у животу, а корисно је понијети податке о тромбозама у породици', 'Специальная подготовка не нужна, натощак приходить не требуется; анализ делают один раз в жизни, с собой полезно взять сведения о тромбозах в семье', 'Keine besondere Vorbereitung nötig, nüchtern sein ist nicht erforderlich; die Untersuchung wird einmal im Leben durchgeführt, Angaben zu Thrombosen in der Familie sind hilfreich', 'Özel hazırlık gerekmez, aç karnına gelmek zorunlu değildir; test ömürde bir kez yapılır, ailedeki tromboz bilgilerini yanınızda getirmek yararlıdır', 'The result describes a gene variant, not a diagnosis or a prognosis: the gene variant is also found in healthy people who have never had a thrombosis. A clinical geneticist interprets the finding together with the personal and family history and the other coagulation tests', 'Nalaz opisuje varijantu gena, a ne dijagnozu ni prognozu: varijanta gena se nalazi i kod zdravih osoba koje nikada nijesu imale trombozu. Značenje nalaza procjenjuje ljekar genetičar zajedno sa ličnom i porodičnom anamnezom i ostalim ispitivanjima koagulacije', 'Налаз описује варијанту гена, а не дијагнозу ни прогнозу: варијанта гена се налази и код здравих особа које никада нијесу имале тромбозу. Значење налаза процјењује љекар генетичар заједно са личном и породичном анамнезом и осталим испитивањима коагулације', 'Результат описывает вариант гена, а не диагноз и не прогноз: вариант гена встречается и у здоровых людей, у которых никогда не было тромбоза. Значение находки оценивает врач-генетик вместе с личным и семейным анамнезом и остальными исследованиями свёртывания', 'Das Ergebnis beschreibt eine Genvariante, keine Diagnose und keine Prognose: die Genvariante kommt auch bei gesunden Menschen vor, die nie eine Thrombose hatten. Die Bedeutung beurteilt ein Facharzt für Humangenetik zusammen mit der persönlichen und der Familienanamnese sowie den übrigen Gerinnungsuntersuchungen', 'Sonuç bir gen varyantını tanımlar, tanı ya da öngörü değildir: gen varyantı hiç tromboz geçirmemiş sağlıklı kişilerde de bulunur. Bulgunun anlamını kişisel ve aile öyküsü ile diğer pıhtılaşma tetkikleriyle birlikte tıbbi genetik uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mthfr-locus-1298'), 'Molecular genetic test of position 1298 in the MTHFR gene, the enzyme of folate and homocysteine metabolism', 'Molekularno-genetičko ispitivanje pozicije 1298 u genu MTHFR, enzimu metabolizma folata i homocisteina', 'Молекуларно-генетичко испитивање позиције 1298 у гену MTHFR, ензиму метаболизма фолата и хомоцистеина', 'Молекулярно-генетическое исследование позиции 1298 гена MTHFR, фермента обмена фолатов и гомоцистеина', 'Molekulargenetische Untersuchung der Position 1298 im MTHFR-Gen, dem Enzym des Folat- und Homocysteinstoffwechsels', 'Folat ve homosistein metabolizmasının enzimi olan MTHFR geninde 1298 pozisyonunun moleküler genetik incelemesi', 'A venous blood sample is taken and the gene variant at this position is determined; blood is drawn once, usually together with the test for position 677 of the same gene', 'Uzima se venska krv i utvrđuje se varijanta gena na toj poziciji; krv se vadi jednom, obično uz analizu pozicije 677 istog gena', 'Узима се венска крв и утврђује се варијанта гена на тој позицији; крв се вади једном, обично уз анализу позиције 677 истог гена', 'Забор венозной крови и определение варианта гена в этой позиции; кровь берут один раз, обычно вместе с анализом позиции 677 того же гена', 'Es wird venöses Blut entnommen und die Genvariante an dieser Position bestimmt; die Blutentnahme erfolgt einmalig, meist zusammen mit der Untersuchung der Position 677 desselben Gens', 'Toplardamardan kan alınır ve bu pozisyondaki gen varyantı belirlenir; kan bir kez alınır, genellikle aynı genin 677 pozisyonu ile birlikte çalışılır', 'Elevated homocysteine, pregnancy planning and recurrent pregnancy loss, further work-up when the result for position 677 is already known, testing as referred by a doctor', 'Povišen homocistein, planiranje trudnoće i ponovljeni gubici trudnoće, dopuna obrade kada je nalaz za poziciju 677 već poznat, ispitivanje po uputu ljekara', 'Повишен хомоцистеин, планирање трудноће и поновљени губици трудноће, допуна обраде када је налаз за позицију 677 већ познат, испитивање по упуту љекара', 'Повышенный гомоцистеин, планирование беременности и повторные потери беременности, дообследование при уже известном результате по позиции 677, обследование по направлению врача', 'Erhöhtes Homocystein, Kinderwunsch und wiederholte Fehlgeburten, Ergänzung der Abklärung bei bereits bekanntem Befund zu Position 677, Untersuchung auf ärztliche Überweisung', 'Yüksek homosistein, gebelik planlaması ve yinelenen gebelik kayıpları, 677 pozisyonu sonucu bilindiğinde incelemenin tamamlanması, hekim yönlendirmesiyle inceleme', 'No preparation is required and fasting is not needed; it helps to bring previous homocysteine results and the result for position 677 if available', 'Priprema nije potrebna i ne dolazi se natašte; korisno je ponijeti ranije nalaze homocisteina i nalaz za poziciju 677 ako postoji', 'Припрема није потребна и не долази се наташте; корисно је понијети раније налазе хомоцистеина и налаз за позицију 677 ако постоји', 'Подготовка не требуется, натощак приходить не нужно; полезно взять с собой прежние результаты по гомоцистеину и по позиции 677, если они есть', 'Keine Vorbereitung erforderlich, nüchtern sein ist nicht nötig; frühere Homocysteinbefunde und der Befund zu Position 677 sind hilfreich', 'Hazırlık gerekmez, aç karnına gelmek gerekli değildir; varsa önceki homosistein sonuçlarını ve 677 pozisyonu sonucunu getirmek yararlıdır', 'This variant affects enzyme activity less than the variant at position 677, and its meaning is considered together with that position rather than on its own. The gene variant is also found in healthy people, and a clinical geneticist interprets it together with the personal and family history', 'Ova varijanta slabije utiče na aktivnost enzima nego varijanta na poziciji 677, pa se njeno značenje razmatra upravo u kombinaciji sa njom, a ne izdvojeno. Varijanta gena se nalazi i kod zdravih osoba, a značenje procjenjuje ljekar genetičar zajedno sa ličnom i porodičnom anamnezom', 'Ова варијанта слабије утиче на активност ензима него варијанта на позицији 677, па се њено значење разматра управо у комбинацији са њом, а не издвојено. Варијанта гена се налази и код здравих особа, а значење процјењује љекар генетичар заједно са личном и породичном анамнезом', 'Этот вариант влияет на активность фермента слабее, чем вариант в позиции 677, и его смысл рассматривают именно в сочетании с ним, а не отдельно. Вариант гена встречается и у здоровых людей, значение оценивает врач-генетик вместе с личным и семейным анамнезом', 'Diese Variante beeinflusst die Enzymaktivität schwächer als die Variante an Position 677, und ihre Bedeutung wird gerade in Kombination mit dieser und nicht für sich allein betrachtet. Die Genvariante kommt auch bei gesunden Menschen vor, die Bedeutung beurteilt ein Facharzt für Humangenetik zusammen mit der persönlichen und der Familienanamnese', 'Bu varyant enzim etkinliğini 677 pozisyonundaki varyanta göre daha az etkiler ve anlamı tek başına değil, onunla birlikte değerlendirilir. Gen varyantı sağlıklı kişilerde de bulunur, anlamını kişisel ve aile öyküsüyle birlikte tıbbi genetik uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mthfr-locus-677-pcr'), 'PCR-based molecular genetic test of position 677 in the MTHFR gene, the most studied position of this gene', 'Molekularno-genetičko ispitivanje pozicije 677 u genu MTHFR metodom PCR, najispitanije pozicije ovog gena', 'Молекуларно-генетичко испитивање позиције 677 у гену MTHFR методом ПЦР, најиспитаније позиције овог гена', 'Молекулярно-генетическое исследование позиции 677 гена MTHFR методом PCR, самой изученной позиции этого гена', 'Molekulargenetische Untersuchung der Position 677 im MTHFR-Gen mittels PCR, der am besten untersuchten Position dieses Gens', 'MTHFR geninin en çok incelenen pozisyonu olan 677 bölgesinin PCR yöntemiyle moleküler genetik incelemesi', 'DNA is extracted from venous blood and the variant at position 677 is determined, along with whether one or two copies of the gene are changed', 'Iz venske krvi se izdvaja DNK i utvrđuje se varijanta na poziciji 677, kao i da li je izmijenjena jedna ili su izmijenjene obje kopije gena', 'Из венске крви се издваја ДНК и утврђује се варијанта на позицији 677, као и да ли је измијењена једна или су измијењене обје копије гена', 'Из венозной крови выделяют ДНК и определяют вариант в позиции 677, а также сколько копий гена изменено, одна или две', 'Aus venösem Blut wird DNA gewonnen und die Variante an Position 677 bestimmt sowie, ob eine oder beide Genkopien verändert sind', 'Toplardamar kanından DNA ayrıştırılır, 677 pozisyonundaki varyant ile genin bir mi iki kopyasının mı değiştiği belirlenir', 'Elevated homocysteine, work-up for venous thrombosis and pregnancy complications, pregnancy planning, testing of relatives of a carrier as referred by a doctor', 'Povišen homocistein, obrada kod venskih tromboza i komplikacija trudnoće, planiranje trudnoće, ispitivanje srodnika nosioca po uputu ljekara', 'Повишен хомоцистеин, обрада код венских тромбоза и компликација трудноће, планирање трудноће, испитивање сродника носиоца по упуту љекара', 'Повышенный гомоцистеин, обследование при венозных тромбозах и осложнениях беременности, планирование беременности, обследование родственников носителя по направлению врача', 'Erhöhtes Homocystein, Abklärung bei venösen Thrombosen und Schwangerschaftskomplikationen, Kinderwunsch, Untersuchung von Angehörigen eines Trägers auf ärztliche Überweisung', 'Yüksek homosistein, venöz tromboz ve gebelik komplikasyonlarının araştırılması, gebelik planlaması, hekim yönlendirmesiyle taşıyıcı yakınlarının incelenmesi', 'No special preparation is needed, blood can be drawn at any time of day and after a meal; the result does not depend on current well-being', 'Posebna priprema nije potrebna, krv se može uzeti u bilo koje doba dana i nakon obroka; nalaz ne zavisi od trenutnog stanja', 'Посебна припрема није потребна, крв се може узети у било које доба дана и након оброка; налаз не зависи од тренутног стања', 'Специальная подготовка не нужна, сдать кровь можно в любое время дня и после еды; результат не зависит от текущего самочувствия', 'Keine besondere Vorbereitung nötig, die Blutentnahme ist zu jeder Tageszeit und auch nach dem Essen möglich; das Ergebnis hängt nicht vom aktuellen Befinden ab', 'Özel hazırlık gerekmez, kan günün herhangi bir saatinde ve yemekten sonra da alınabilir; sonuç o günkü genel durumdan etkilenmez', 'The variant at this position may go along with reduced enzyme activity, so it is reviewed together with the blood homocysteine level and with position 1298 of the same gene. The gene variant is also found in healthy people, and a clinical geneticist interprets it together with the personal and family history', 'Varijanta na ovoj poziciji može biti praćena smanjenom aktivnošću enzima, pa se posmatra zajedno sa nivoom homocisteina u krvi i sa pozicijom 1298 istog gena. Varijanta gena se nalazi i kod zdravih osoba, a značenje procjenjuje ljekar genetičar zajedno sa ličnom i porodičnom anamnezom', 'Варијанта на овој позицији може бити праћена смањеном активношћу ензима, па се посматра заједно са нивоом хомоцистеина у крви и са позицијом 1298 истог гена. Варијанта гена се налази и код здравих особа, а значење процјењује љекар генетичар заједно са личном и породичном анамнезом', 'Вариант в этой позиции может сопровождаться сниженной активностью фермента, поэтому его смотрят вместе с уровнем гомоцистеина в крови и с позицией 1298 того же гена. Вариант гена встречается и у здоровых людей, значение оценивает врач-генетик вместе с личным и семейным анамнезом', 'Die Variante an dieser Position kann mit einer verminderten Enzymaktivität einhergehen und wird daher zusammen mit dem Homocysteinwert im Blut und mit Position 1298 desselben Gens betrachtet. Die Genvariante kommt auch bei gesunden Menschen vor, die Bedeutung beurteilt ein Facharzt für Humangenetik zusammen mit der persönlichen und der Familienanamnese', 'Bu pozisyondaki varyanta azalmış enzim etkinliği eşlik edebilir, bu nedenle kandaki homosistein düzeyi ve aynı genin 1298 pozisyonu ile birlikte değerlendirilir. Gen varyantı sağlıklı kişilerde de bulunur, anlamını kişisel ve aile öyküsüyle birlikte tıbbi genetik uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'pai-1-675-4g-5g'), 'Molecular genetic test of region 675 of the PAI-1 gene, a protein that slows the dissolution of a clot: the 4G and 5G variants are determined', 'Molekularno-genetičko ispitivanje regiona 675 gena PAI-1, proteina koji usporava razgradnju ugruška: utvrđuju se varijante 4G i 5G', 'Молекуларно-генетичко испитивање региона 675 гена PAI-1, протеина који успорава разградњу угрушка: утврђују се варијанте 4Г и 5Г', 'Молекулярно-генетическое исследование участка 675 гена PAI-1, белка, который тормозит растворение сгустка: определяются варианты 4G и 5G', 'Molekulargenetische Untersuchung der Region 675 des PAI-1-Gens, eines Proteins, das die Auflösung eines Gerinnsels bremst: bestimmt werden die Varianten 4G und 5G', 'Pıhtının çözünmesini yavaşlatan PAI-1 proteininin geninde 675 bölgesinin moleküler genetik incelemesi: 4G ve 5G varyantları belirlenir', 'A venous blood sample is taken and the combination of variants in this region is read from the DNA, for example 4G/4G, 4G/5G or 5G/5G', 'Uzima se venska krv, a iz DNK se očitava kombinacija varijanti u ovom regionu, na primjer 4G/4G, 4G/5G ili 5G/5G', 'Узима се венска крв, а из ДНК се очитава комбинација варијанти у овом региону, на примјер 4Г/4Г, 4Г/5Г или 5Г/5Г', 'Забор венозной крови, из ДНК определяют сочетание вариантов в этом участке, например 4G/4G, 4G/5G или 5G/5G', 'Es wird venöses Blut entnommen und aus der DNA die Kombination der Varianten in dieser Region abgelesen, zum Beispiel 4G/4G, 4G/5G oder 5G/5G', 'Toplardamardan kan alınır ve DNA üzerinden bu bölgedeki varyant birleşimi okunur, örneğin 4G/4G, 4G/5G ya da 5G/5G', 'Work-up for venous thrombosis and recurrent pregnancy loss, assessment of fibrinolysis as part of a genetic thrombophilia panel, testing as referred by a doctor', 'Obrada kod venskih tromboza i ponovljenih gubitaka trudnoće, procjena fibrinolize u okviru genetičkog panela za trombofiliju, ispitivanje po uputu ljekara', 'Обрада код венских тромбоза и поновљених губитака трудноће, процјена фибринолизе у оквиру генетичког панела за тромбофилију, испитивање по упуту љекара', 'Обследование при венозных тромбозах и повторных потерях беременности, оценка фибринолиза в составе генетической панели по тромбофилии, обследование по направлению врача', 'Abklärung bei venösen Thrombosen und wiederholten Fehlgeburten, Beurteilung der Fibrinolyse im Rahmen eines genetischen Thrombophilie-Panels, Untersuchung auf ärztliche Überweisung', 'Venöz tromboz ve yinelenen gebelik kayıplarının araştırılması, genetik trombofili paneli kapsamında fibrinolizin değerlendirilmesi, hekim yönlendirmesiyle inceleme', 'No preparation is required; food intake and time of day do not affect the result', 'Priprema nije potrebna, obrok i doba dana ne utiču na nalaz', 'Припрема није потребна, оброк и доба дана не утичу на налаз', 'Подготовка не требуется, приём пищи и время суток на результат не влияют', 'Keine Vorbereitung erforderlich, Nahrungsaufnahme und Tageszeit beeinflussen das Ergebnis nicht', 'Hazırlık gerekmez, yemek ve günün saati sonucu etkilemez', 'The combination of variants describes only the structure of a gene region and does not show how coagulation is working right now, which requires blood tests. The gene variant is also found in healthy people, and a clinical geneticist interprets it together with the personal and family history', 'Kombinacija varijanti opisuje samo građu regiona gena i ne pokazuje kako koagulacija radi u ovom trenutku, za to su potrebne analize krvi. Varijanta gena se nalazi i kod zdravih osoba, a značenje procjenjuje ljekar genetičar zajedno sa ličnom i porodičnom anamnezom', 'Комбинација варијанти описује само грађу региона гена и не показује како коагулација ради у овом тренутку, за то су потребне анализе крви. Варијанта гена се налази и код здравих особа, а значење процјењује љекар генетичар заједно са личном и породичном анамнезом', 'Сочетание вариантов описывает только строение участка гена и не показывает, как свёртывание работает сейчас, для этого нужны анализы крови. Вариант гена встречается и у здоровых людей, значение оценивает врач-генетик вместе с личным и семейным анамнезом', 'Die Kombination der Varianten beschreibt nur den Aufbau eines Genabschnitts und zeigt nicht, wie die Gerinnung aktuell arbeitet, dafür sind Blutuntersuchungen nötig. Die Genvariante kommt auch bei gesunden Menschen vor, die Bedeutung beurteilt ein Facharzt für Humangenetik zusammen mit der persönlichen und der Familienanamnese', 'Varyant birleşimi yalnızca gen bölgesinin yapısını tanımlar, pıhtılaşmanın o anda nasıl çalıştığını göstermez, bunun için kan tetkikleri gerekir. Gen varyantı sağlıklı kişilerde de bulunur, anlamını kişisel ve aile öyküsüyle birlikte tıbbi genetik uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'prothrombin-ii-locus-20210-pcr'), 'PCR-based molecular genetic test of position 20210 in the prothrombin gene, coagulation factor II', 'Molekularno-genetičko ispitivanje pozicije 20210 u genu za protrombin, faktor II koagulacije, metodom PCR', 'Молекуларно-генетичко испитивање позиције 20210 у гену за протромбин, фактор II коагулације, методом ПЦР', 'Молекулярно-генетическое исследование позиции 20210 гена протромбина, фактора II свёртывания крови, методом PCR', 'Molekulargenetische Untersuchung der Position 20210 im Prothrombin-Gen, dem Gerinnungsfaktor II, mittels PCR', 'Pıhtılaşma faktörü II olan protrombin geninde 20210 pozisyonunun PCR yöntemiyle moleküler genetik incelemesi', 'DNA is extracted from venous blood and the variant at position 20210 is read; the blood draw takes a few minutes', 'Iz venske krvi se izdvaja DNK i očitava se varijanta na poziciji 20210; vađenje krvi traje nekoliko minuta', 'Из венске крви се издваја ДНК и очитава се варијанта на позицији 20210; вађење крви траје неколико минута', 'Из венозной крови выделяют ДНК и читают вариант в позиции 20210; забор занимает несколько минут', 'Aus venösem Blut wird DNA gewonnen und die Variante an Position 20210 abgelesen; die Blutentnahme dauert einige Minuten', 'Toplardamar kanından DNA ayrıştırılır ve 20210 pozisyonundaki varyant okunur; kan alımı birkaç dakika sürer', 'Previous venous thrombosis or thromboembolism, thrombosis in close relatives, pregnancy complications, assessment before hormonal medication is prescribed, as decided by the doctor', 'Preboljela venska tromboza ili tromboembolija, tromboze kod bliskih srodnika, komplikacije trudnoće, procjena uoči uvođenja hormonskih preparata po odluci ljekara', 'Пребољела венска тромбоза или тромбоемболија, тромбозе код блиских сродника, компликације трудноће, процјена уочи увођења хормонских препарата по одлуци љекара', 'Перенесённый венозный тромбоз или тромбоэмболия, тромбозы у близких родственников, осложнения беременности, обследование перед назначением гормональных препаратов по решению врача', 'Durchgemachte venöse Thrombose oder Thromboembolie, Thrombosen bei nahen Verwandten, Schwangerschaftskomplikationen, Beurteilung vor der Verordnung hormoneller Präparate nach ärztlicher Entscheidung', 'Geçirilmiş venöz tromboz veya tromboemboli, yakın akrabalarda tromboz, gebelik komplikasyonları, hekim kararıyla hormon içeren ilaçlar başlanmadan önce değerlendirme', 'No special preparation is needed; the test is done once and does not need repeating when changing doctor or laboratory', 'Posebna priprema nije potrebna; analiza se radi jednokratno i ne ponavlja se pri promjeni ljekara ili laboratorije', 'Посебна припрема није потребна; анализа се ради једнократно и не понавља се при промјени љекара или лабораторије', 'Специальная подготовка не нужна; анализ делают однократно, повторять его при смене врача или лаборатории не требуется', 'Keine besondere Vorbereitung nötig; die Untersuchung wird einmalig durchgeführt und muss bei einem Wechsel von Arzt oder Labor nicht wiederholt werden', 'Özel hazırlık gerekmez; test bir kez yapılır, hekim ya da laboratuvar değiştiğinde yinelenmesi gerekmez', 'The variant at this position concerns the structure of the prothrombin gene and does not describe the state of the blood at the time of sampling, which is what a coagulation panel shows. The gene variant is also found in healthy people, and a clinical geneticist interprets it together with the personal and family history', 'Varijanta na ovoj poziciji odnosi se na građu gena za protrombin i ne opisuje stanje krvi u trenutku uzorkovanja, za to služi koagulogram. Varijanta gena se nalazi i kod zdravih osoba, a značenje procjenjuje ljekar genetičar zajedno sa ličnom i porodičnom anamnezom', 'Варијанта на овој позицији односи се на грађу гена за протромбин и не описује стање крви у тренутку узорковања, за то служи коагулограм. Варијанта гена се налази и код здравих особа, а значење процјењује љекар генетичар заједно са личном и породичном анамнезом', 'Вариант в этой позиции относится к строению гена протромбина и не описывает состояние крови в момент сдачи, для этого делают коагулограмму. Вариант гена встречается и у здоровых людей, значение оценивает врач-генетик вместе с личным и семейным анамнезом', 'Die Variante an dieser Position betrifft den Aufbau des Prothrombin-Gens und beschreibt nicht den Zustand des Blutes zum Zeitpunkt der Entnahme, dafür dient das Gerinnungsprofil. Die Genvariante kommt auch bei gesunden Menschen vor, die Bedeutung beurteilt ein Facharzt für Humangenetik zusammen mit der persönlichen und der Familienanamnese', 'Bu pozisyondaki varyant protrombin geninin yapısıyla ilgilidir ve kanın örnek alındığı andaki durumunu göstermez, bunun için pıhtılaşma tetkikleri yapılır. Gen varyantı sağlıklı kişilerde de bulunur, anlamını kişisel ve aile öyküsüyle birlikte tıbbi genetik uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'thrombophilia-3-genes-5-loci'), 'A combined genetic panel: one test reads several gene regions related to blood clotting and folate metabolism at once', 'Objedinjeni genetički panel: jednom analizom se očitava više regiona gena povezanih sa zgrušavanjem krvi i metabolizmom folata', 'Обједињени генетички панел: једном анализом се очитава више региона гена повезаних са згрушавањем крви и метаболизмом фолата', 'Комплексная генетическая панель: в одном анализе читают сразу несколько участков генов, связанных со свёртыванием крови и обменом фолатов', 'Kombiniertes genetisches Panel: in einer Untersuchung werden mehrere Genabschnitte abgelesen, die mit der Blutgerinnung und dem Folatstoffwechsel zusammenhängen', 'Birleşik genetik panel: tek bir tetkikle kan pıhtılaşması ve folat metabolizmasıyla ilişkili birkaç gen bölgesi aynı anda okunur', 'A single venous blood draw, and all positions included in the panel are checked in the extracted DNA; the exact list of genes and loci is stated by the laboratory on the report form', 'Jednokratno vađenje venske krvi, a iz izdvojene DNK provjeravaju se sve pozicije obuhvaćene panelom; tačan spisak gena i lokusa laboratorija navodi na nalazu', 'Једнократно вађење венске крви, а из издвојене ДНК провјеравају се све позиције обухваћене панелом; тачан списак гена и локуса лабораторија наводи на налазу', 'Однократный забор венозной крови, из выделенной ДНК проверяют все входящие в панель позиции; точный перечень генов и локусов лаборатория указывает в бланке результата', 'Eine einmalige venöse Blutentnahme, aus der gewonnenen DNA werden alle im Panel enthaltenen Positionen geprüft; die genaue Liste der Gene und Loci gibt das Labor auf dem Befund an', 'Tek seferde toplardamardan kan alınır, ayrıştırılan DNA üzerinde panelin kapsadığı tüm pozisyonlar incelenir; gen ve lokus listesini laboratuvar sonuç raporunda belirtir', 'Work-up after venous thrombosis, a family history of thrombosis, recurrent pregnancy loss, preparation for pregnancy or hormone therapy as referred by a doctor', 'Obrada nakon venske tromboze, opterećena porodična anamneza za tromboze, ponovljeni gubici trudnoće, priprema za trudnoću ili hormonsku terapiju po uputu ljekara', 'Обрада након венске тромбозе, оптерећена породична анамнеза за тромбозе, поновљени губици трудноће, припрема за трудноћу или хормонску терапију по упуту љекара', 'Обследование после венозного тромбоза, отягощённый семейный анамнез по тромбозам, повторные потери беременности, подготовка к беременности или к гормональной терапии по направлению врача', 'Abklärung nach venöser Thrombose, belastete Familienanamnese für Thrombosen, wiederholte Fehlgeburten, Vorbereitung auf eine Schwangerschaft oder eine Hormontherapie auf ärztliche Überweisung', 'Venöz tromboz sonrası inceleme, ailede tromboz öyküsü, yinelenen gebelik kayıpları, hekim yönlendirmesiyle gebeliğe veya hormon tedavisine hazırlık', 'No preparation is needed and fasting is not required; information about thrombosis and pregnancy complications in relatives is useful to bring to the appointment', 'Priprema nije potrebna i ne dolazi se natašte; na pregled je korisno ponijeti podatke o trombozama i komplikacijama trudnoće kod srodnika', 'Припрема није потребна и не долази се наташте; на преглед је корисно понијети податке о тромбозама и компликацијама трудноће код сродника', 'Подготовка не нужна, натощак приходить не требуется; на приём полезно взять сведения о тромбозах и осложнениях беременности у родственников', 'Keine Vorbereitung nötig, nüchtern sein ist nicht erforderlich; Angaben zu Thrombosen und Schwangerschaftskomplikationen bei Verwandten sind zum Termin hilfreich', 'Hazırlık gerekmez, aç karnına gelmek zorunlu değildir; yakınlardaki tromboz ve gebelik komplikasyonlarına ilişkin bilgileri randevuya getirmek yararlıdır', 'The panel shows a set of gene variants, not a diagnosis: their combination in itself does not mean that a thrombosis will necessarily occur. Gene variants are also found in healthy people, and a clinical geneticist interprets the result together with the personal and family history', 'Panel prikazuje skup varijanti gena, a ne dijagnozu: njihova kombinacija sama po sebi ne znači da će do tromboze obavezno doći. Varijante gena se nalaze i kod zdravih osoba, a značenje nalaza procjenjuje ljekar genetičar zajedno sa ličnom i porodičnom anamnezom', 'Панел приказује скуп варијанти гена, а не дијагнозу: њихова комбинација сама по себи не значи да ће до тромбозе обавезно доћи. Варијанте гена се налазе и код здравих особа, а значење налаза процјењује љекар генетичар заједно са личном и породичном анамнезом', 'Панель показывает набор вариантов генов, а не диагноз: их сочетание само по себе не означает, что тромбоз обязательно случится. Варианты генов встречаются и у здоровых людей, значение результата оценивает врач-генетик вместе с личным и семейным анамнезом', 'Das Panel zeigt eine Reihe von Genvarianten, keine Diagnose: ihre Kombination allein bedeutet nicht, dass es zwangsläufig zu einer Thrombose kommt. Genvarianten kommen auch bei gesunden Menschen vor, die Bedeutung beurteilt ein Facharzt für Humangenetik zusammen mit der persönlichen und der Familienanamnese', 'Panel bir dizi gen varyantını gösterir, tanı koymaz: varyantların bir arada bulunması tek başına trombozun mutlaka gelişeceği anlamına gelmez. Gen varyantları sağlıklı kişilerde de bulunur, sonucun anlamını kişisel ve aile öyküsüyle birlikte tıbbi genetik uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'antibiotic-allergy-panel-10-allergens'), 'Blood test for specific IgE antibodies to several antibiotics included in one panel', 'Analiza krvi na specifična IgE antitijela na više antibiotika obuhvaćenih jednim panelom', 'Анализа крви на специфична IgE антитијела на више антибиотика обухваћених једним панелом', 'Анализ крови на специфические антитела IgE сразу к нескольким антибиотикам одной панели', 'Bluttest auf spezifische IgE-Antikörper gegen mehrere Antibiotika, die in einem Panel zusammengefasst sind', 'Tek bir panelde toplanan birkaç antibiyotiğe karşı özgül IgE antikorlarını ölçen kan testi', 'A venous blood sample is taken, and the laboratory measures antibodies to each drug on the panel list in that single sample', 'Uzima se venska krv, a laboratorija u istom uzorku određuje antitijela na svaki lijek sa spiska panela', 'Узима се венска крв, а лабораторија у истом узорку одређује антитијела на сваки лијек са списка панела', 'Забор венозной крови, в одном образце лаборатория определяет антитела к каждому препарату из списка панели', 'Es wird venöses Blut entnommen, und das Labor bestimmt in dieser einen Probe die Antikörper gegen jedes Medikament der Panel-Liste', 'Toplardamardan kan alınır, laboratuvar bu tek örnekte panel listesindeki her ilaca karşı antikorları ölçer', 'Rash, swelling or another reaction that appeared while taking an antibiotic, preparation for planned surgery or a course of treatment, clarifying tolerance after past reactions as referred by a doctor', 'Osip, otok ili druga reakcija nastala tokom uzimanja antibiotika, priprema za planiranu operaciju ili terapiju, provjera podnošljivosti nakon ranijih reakcija po uputu ljekara', 'Осип, оток или друга реакција настала током узимања антибиотика, припрема за планирану операцију или терапију, провјера подношљивости након ранијих реакција по упуту љекара', 'Сыпь, отёк или другая реакция, появившаяся на фоне приёма антибиотика, подготовка к плановой операции или к курсу лечения, уточнение переносимости при реакциях в прошлом по направлению врача', 'Hautausschlag, Schwellung oder eine andere Reaktion während der Einnahme eines Antibiotikums, Vorbereitung auf eine geplante Operation oder Behandlung, Abklärung der Verträglichkeit nach früheren Reaktionen auf ärztliche Überweisung', 'Antibiyotik kullanımı sırasında ortaya çıkan döküntü, şişlik veya başka bir tepki, planlı ameliyata ya da tedaviye hazırlık, geçmiş tepkiler sonrası hekim yönlendirmesiyle tolerans değerlendirmesi', 'No special preparation is needed and fasting is not obligatory; antihistamines do not affect a blood test, unlike skin tests, and it helps to write down the dates and description of the past reaction in advance', 'Posebna priprema nije potrebna i ne mora se doći natašte; antihistaminici ne utiču na analizu krvi, za razliku od kožnih proba, a korisno je unaprijed zapisati datume i opis ranije reakcije', 'Посебна припрема није потребна и не мора се доћи наташте; антихистаминици не утичу на анализу крви, за разлику од кожних проба, а корисно је унапријед записати датуме и опис раније реакције', 'Специальная подготовка не нужна, натощак приходить не обязательно; антигистаминные препараты на анализ крови не влияют, в отличие от кожных проб, а даты и описание перенесённой реакции полезно записать заранее', 'Keine besondere Vorbereitung nötig, nüchtern sein ist nicht zwingend; Antihistaminika beeinflussen den Bluttest im Unterschied zu Hauttests nicht, Datum und Beschreibung der früheren Reaktion sollten vorab notiert werden', 'Özel hazırlık gerekmez, aç karnına gelmek zorunlu değildir; kan testi, deri testlerinin aksine antihistaminiklerden etkilenmez, geçmişteki tepkinin tarihini ve nasıl geliştiğini önceden not etmek yararlıdır', 'Detected antibodies may be related to sensitisation to the drug, while their absence does not rule out a reaction of a different mechanism. Which antibiotic can be used is decided by the doctor based on the history and the whole work-up', 'Nalaz antitijela može biti povezan sa senzibilizacijom na lijek, dok njihovo odsustvo ne isključuje reakciju drugog mehanizma. Koji se antibiotik može primijeniti odlučuje ljekar na osnovu anamneze i cjelokupne obrade', 'Налаз антитијела може бити повезан са сензибилизацијом на лијек, док њихово одсуство не искључује реакцију другог механизма. Који се антибиотик може примијенити одлучује љекар на основу анамнезе и цјелокупне обраде', 'Обнаружение антител может быть связано с сенсибилизацией к препарату, а их отсутствие не исключает реакции другого механизма. Вывод о том, какой антибиотик применим, делает врач по совокупности анамнеза и обследования', 'Nachgewiesene Antikörper können mit einer Sensibilisierung gegen das Medikament zusammenhängen, ihr Fehlen schließt eine Reaktion anderen Mechanismus nicht aus. Welches Antibiotikum eingesetzt werden kann, entscheidet der Arzt anhand der Anamnese und der gesamten Abklärung', 'Saptanan antikorlar ilaca duyarlanma ile ilişkili olabilir, bulunmaması ise farklı mekanizmalı bir tepkiyi dışlamaz. Hangi antibiyotiğin kullanılabileceğine öykü ve incelemelerin tümüne bakarak hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'food-allergy-panel-30-allergens'), 'Blood test for specific IgE antibodies to several dozen foods at the same time', 'Analiza krvi na specifična IgE antitijela na više desetina namirnica istovremeno', 'Анализа крви на специфична IgE антитијела на више десетина намирница истовремено', 'Анализ крови на специфические антитела IgE к нескольким десяткам пищевых продуктов одновременно', 'Bluttest auf spezifische IgE-Antikörper gegen mehrere Dutzend Lebensmittel gleichzeitig', 'Onlarca gıdaya karşı özgül IgE antikorlarını aynı anda ölçen kan testi', 'A venous blood sample is taken and antibodies to each food on the panel are measured in that one sample, with no repeat draws needed', 'Uzima se venska krv, a antitijela na svaku namirnicu iz panela određuju se u istom uzorku, bez ponovnog vađenja', 'Узима се венска крв, а антитијела на сваку намирницу из панела одређују се у истом узорку, без поновног вађења', 'Забор венозной крови, антитела к каждому продукту панели определяют в одном образце, повторные заборы не нужны', 'Es wird venöses Blut entnommen, und die Antikörper gegen jedes Lebensmittel des Panels werden in dieser einen Probe bestimmt, weitere Entnahmen sind nicht nötig', 'Toplardamardan kan alınır, panelde yer alan her gıdaya karşı antikorlar bu tek örnekte ölçülür, yeniden kan alınması gerekmez', 'Rash, itching and swelling after eating, urticaria, digestive complaints linked in time to certain foods, testing as referred by an allergist', 'Osip, svrab i otoci nakon obroka, urtikarija, tegobe sa varenjem vremenski povezane sa određenim namirnicama, ispitivanje po uputu alergologa', 'Осип, свраб и отоци након оброка, уртикарија, тегобе са варењем временски повезане са одређеним намирницама, испитивање по упуту алерголога', 'Высыпания, зуд и отёки после еды, крапивница, желудочно-кишечные жалобы, связанные по времени с определёнными продуктами, обследование по направлению аллерголога', 'Hautausschlag, Juckreiz und Schwellungen nach dem Essen, Nesselsucht, Verdauungsbeschwerden im zeitlichen Zusammenhang mit bestimmten Lebensmitteln, Untersuchung auf Überweisung des Allergologen', 'Yemek sonrası döküntü, kaşıntı ve şişlik, ürtiker, belirli gıdalarla zamansal ilişki gösteren sindirim şikayetleri, alerji uzmanının yönlendirmesiyle inceleme', 'No preparation is required, and there is no need to follow a diet or fast before the test; a list of foods that caused a reaction is useful to bring along', 'Priprema nije potrebna, nije nužno držati dijetu ni gladovati prije analize; korisno je ponijeti spisak namirnica nakon kojih se javljala reakcija', 'Припрема није потребна, није нужно држати дијету ни гладовати прије анализе; корисно је понијети списак намирница након којих се јављала реакција', 'Подготовка не требуется, соблюдать диету и голодать перед анализом не нужно; список продуктов, которые вызывали реакцию, полезно принести с собой', 'Keine Vorbereitung erforderlich, eine Diät oder Nüchternheit vor der Untersuchung ist nicht nötig; eine Liste der Lebensmittel, nach denen Beschwerden auftraten, ist hilfreich', 'Hazırlık gerekmez, test öncesi diyet uygulamak veya aç kalmak gerekli değildir; tepkiye yol açan gıdaların listesini getirmek yararlıdır', 'Elevated antibodies to a food indicate sensitisation and are not always accompanied by symptoms when it is eaten, and the reverse also happens. The allergist compares the result with the complaints and the food diary', 'Povišena antitijela na namirnicu govore o senzibilizaciji i ne moraju biti praćena tegobama pri njenom unosu, a dešava se i obrnuto. Nalaz sa tegobama i dnevnikom ishrane upoređuje ljekar alergolog', 'Повишена антитијела на намирницу говоре о сензибилизацији и не морају бити праћена тегобама при њеном уносу, а дешава се и обрнуто. Налаз са тегобама и дневником исхране упоређује љекар алерголог', 'Повышенные антитела к продукту говорят о сенсибилизации и не всегда сопровождаются симптомами при его употреблении, а бывает и наоборот. Результат сопоставляет с жалобами и пищевым дневником врач-аллерголог', 'Erhöhte Antikörper gegen ein Lebensmittel zeigen eine Sensibilisierung an und gehen nicht immer mit Beschwerden beim Verzehr einher, auch der umgekehrte Fall kommt vor. Der Allergologe gleicht das Ergebnis mit den Beschwerden und dem Ernährungstagebuch ab', 'Bir gıdaya karşı yüksek antikorlar duyarlanmayı gösterir ve o gıda yendiğinde her zaman belirti eşlik etmez, tersi de görülebilir. Sonucu şikayetler ve beslenme günlüğüyle birlikte alerji uzmanı değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'food-intolerance-panel-90-foods'), 'Blood test for IgG class antibodies to a long list of food products', 'Analiza krvi na antitijela klase IgG na dugačak spisak namirnica', 'Анализа крви на антитијела класе IgG на дугачак списак намирница', 'Анализ крови на антитела класса IgG к большому списку пищевых продуктов', 'Bluttest auf Antikörper der Klasse IgG gegen eine lange Liste von Lebensmitteln', 'Uzun bir gıda listesine karşı IgG sınıfı antikorları ölçen kan testi', 'A venous blood sample is taken and the laboratory measures the IgG level for each food included in the panel', 'Uzima se venska krv, a laboratorija mjeri nivo IgG za svaku namirnicu obuhvaćenu panelom', 'Узима се венска крв, а лабораторија мјери ниво IgG за сваку намирницу обухваћену панелом', 'Забор венозной крови, в лаборатории измеряют уровень IgG к каждому продукту, входящему в панель', 'Es wird venöses Blut entnommen, und das Labor misst den IgG-Spiegel für jedes im Panel enthaltene Lebensmittel', 'Toplardamardan kan alınır, laboratuvar panelde yer alan her gıda için IgG düzeyini ölçer', 'Long-standing complaints of bloating, heaviness and irregular stools when the doctor is looking for additional data; ordered as a supplementary test at the doctor''s decision', 'Dugotrajne tegobe sa nadimanjem, težinom u stomaku i neredovnom stolicom, kada ljekar traži dodatne podatke; radi se kao pomoćno ispitivanje po odluci ljekara', 'Дуготрајне тегобе са надимањем, тежином у стомаку и нередовном столицом, када љекар тражи додатне податке; ради се као помоћно испитивање по одлуци љекара', 'Длительные жалобы на вздутие, тяжесть и нерегулярный стул, когда врач ищет дополнительные данные; назначается как вспомогательное исследование по решению врача', 'Lang bestehende Beschwerden mit Blähungen, Völlegefühl und unregelmäßigem Stuhlgang, wenn der Arzt zusätzliche Daten sucht; wird nach ärztlicher Entscheidung als ergänzende Untersuchung veranlasst', 'Hekimin ek veri aradığı durumlarda uzun süreli şişkinlik, dolgunluk ve düzensiz dışkılama şikayetleri; hekim kararıyla yardımcı bir inceleme olarak istenir', 'No special preparation is needed; foods should not be excluded before the test, otherwise the picture will be incomplete', 'Posebna priprema nije potrebna; namirnice ne treba izbacivati prije analize jer bi slika bila nepotpuna', 'Посебна припрема није потребна; намирнице не треба избацивати прије анализе јер би слика била непотпуна', 'Специальная подготовка не нужна; исключать продукты перед анализом не следует, иначе картина будет неполной', 'Keine besondere Vorbereitung nötig; Lebensmittel sollten vor der Untersuchung nicht weggelassen werden, sonst ist das Bild unvollständig', 'Özel hazırlık gerekmez; test öncesinde gıdaları diyetten çıkarmamak gerekir, aksi halde tablo eksik kalır', 'IgG antibodies to foods reflect contact with food and are found in people without complaints, so such a result is not equivalent to a diagnosis of food allergy or intolerance. Whether further testing is needed and how to adjust the diet is decided by the doctor', 'IgG antitijela na namirnice odražavaju kontakt sa hranom i nalaze se i kod osoba bez tegoba, pa takav nalaz nije isto što i dijagnoza nutritivne alergije ili intolerancije. Da li su potrebna dalja ispitivanja i kako mijenjati ishranu odlučuje ljekar', 'IgG антитијела на намирнице одражавају контакт са храном и налазе се и код особа без тегоба, па такав налаз није исто што и дијагноза нутритивне алергије или интолеранције. Да ли су потребна даља испитивања и како мијењати исхрану одлучује љекар', 'Антитела IgG к продуктам отражают контакт с пищей и обнаруживаются у людей без жалоб, поэтому такой результат не равен диагнозу пищевой аллергии или непереносимости. Нужны ли другие исследования и как менять питание, решает врач', 'IgG-Antikörper gegen Lebensmittel spiegeln den Kontakt mit Nahrung wider und finden sich auch bei Menschen ohne Beschwerden, daher entspricht ein solches Ergebnis keiner Diagnose einer Nahrungsmittelallergie oder -intoleranz. Ob weitere Untersuchungen nötig sind und wie die Ernährung angepasst wird, entscheidet der Arzt', 'Gıdalara karşı IgG antikorları besinle karşılaşmayı yansıtır ve şikayeti olmayan kişilerde de bulunur, bu nedenle böyle bir sonuç gıda alerjisi ya da intolerans tanısı anlamına gelmez. Başka tetkiklerin gerekip gerekmediğine ve beslenmenin nasıl düzenleneceğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'inhalant-allergy-panel-30-allergens'), 'Blood test for specific IgE antibodies to inhaled allergens: pollen, house dust mites, moulds, animal hair and dander', 'Analiza krvi na specifična IgE antitijela na inhalacione alergene: polen, grinje kućne prašine, plijesni, dlaku i perut životinja', 'Анализа крви на специфична IgE антитијела на инхалационе алергене: полен, гриње кућне прашине, плијесни, длаку и перут животиња', 'Анализ крови на специфические антитела IgE к вдыхаемым аллергенам: пыльце, клещам домашней пыли, плесени, шерсти и перхоти животных', 'Bluttest auf spezifische IgE-Antikörper gegen Inhalationsallergene: Pollen, Hausstaubmilben, Schimmelpilze, Tierhaare und Hautschuppen', 'Polen, ev tozu akarı, küf, hayvan tüyü ve deri döküntüsü gibi solunan alerjenlere karşı özgül IgE antikorlarını ölçen kan testi', 'A venous blood sample is taken and antibodies to each allergen on the panel are measured in one sample', 'Uzima se venska krv, a u jednom uzorku se određuju antitijela na svaki alergen iz panela', 'Узима се венска крв, а у једном узорку се одређују антитијела на сваки алерген из панела', 'Забор венозной крови, в одном образце определяют антитела к каждому аллергену панели', 'Es wird venöses Blut entnommen und in einer Probe die Antikörper gegen jedes Allergen des Panels bestimmt', 'Toplardamardan kan alınır, tek bir örnekte panelin her alerjenine karşı antikorlar ölçülür', 'Seasonal or year-round runny and blocked nose, sneezing and itchy eyes, persistent cough, work-up when asthma is suspected', 'Sezonska ili cjelogodišnja kijavica i zapušenost nosa, kijanje i svrab očiju, dugotrajan kašalj, obrada kod sumnje na astmu', 'Сезонска или цјелогодишња кијавица и запушеност носа, кијање и свраб очију, дуготрајан кашаљ, обрада код сумње на астму', 'Сезонный или круглогодичный насморк и заложенность носа, чихание и зуд в глазах, длительный кашель, обследование при подозрении на бронхиальную астму', 'Saisonaler oder ganzjähriger Schnupfen und verstopfte Nase, Niesen und juckende Augen, anhaltender Husten, Abklärung bei Verdacht auf Asthma', 'Mevsimsel ya da yıl boyu süren burun akıntısı ve tıkanıklığı, hapşırma ve göz kaşıntısı, uzun süren öksürük, astım kuşkusunda inceleme', 'No preparation is required and fasting is not needed; the test can be done both during the pollen season and outside it', 'Priprema nije potrebna i ne dolazi se natašte; analiza se može raditi i u sezoni polena i van nje', 'Припрема није потребна и не долази се наташте; анализа се може радити и у сезони полена и ван ње', 'Подготовка не требуется, натощак приходить не нужно; анализ можно сдавать и в сезон цветения, и вне его', 'Keine Vorbereitung erforderlich, nüchtern sein ist nicht nötig; die Untersuchung ist sowohl während der Pollensaison als auch außerhalb möglich', 'Hazırlık gerekmez, aç karnına gelmek gerekli değildir; test polen mevsiminde de mevsim dışında da yapılabilir', 'Elevated antibodies to an allergen indicate sensitisation and are assessed together with whether contact with it actually causes complaints in daily life. The allergist compares the data and decides whether skin tests are needed', 'Povišena antitijela na alergen znače senzibilizaciju i procjenjuju se zajedno sa tim da li se u svakodnevnom kontaktu sa njim zaista javljaju tegobe. Podatke upoređuje i o potrebi kožnih proba odlučuje ljekar alergolog', 'Повишена антитијела на алерген значе сензибилизацију и процјењују се заједно са тим да ли се у свакодневном контакту са њим заиста јављају тегобе. Податке упоређује и о потреби кожних проба одлучује љекар алерголог', 'Повышенные антитела к аллергену означают сенсибилизацию и оцениваются вместе с тем, появляются ли жалобы при контакте с ним в реальной жизни. Сопоставляет данные и решает, нужны ли кожные пробы, врач-аллерголог', 'Erhöhte Antikörper gegen ein Allergen bedeuten eine Sensibilisierung und werden zusammen damit beurteilt, ob im Alltag beim Kontakt tatsächlich Beschwerden auftreten. Der Allergologe gleicht die Daten ab und entscheidet, ob Hauttests nötig sind', 'Bir alerjene karşı yüksek antikorlar duyarlanmayı gösterir ve günlük yaşamda o alerjenle temasta gerçekten şikayet olup olmadığıyla birlikte değerlendirilir. Verileri karşılaştıran ve deri testi gerekip gerekmediğine karar veren alerji uzmanıdır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'pediatric-allergy-panel-30-allergens'), 'Blood test for specific IgE antibodies to the allergens most common in childhood: foods, dust mites, pollen and animal hair', 'Analiza krvi na specifična IgE antitijela na alergene koji su najčešći u dječjem uzrastu: namirnice, grinje prašine, polen, dlaka životinja', 'Анализа крви на специфична IgE антитијела на алергене који су најчешћи у дјечјем узрасту: намирнице, гриње прашине, полен, длака животиња', 'Анализ крови на специфические антитела IgE к набору аллергенов, наиболее частых в детском возрасте: продукты питания, клещи пыли, пыльца, шерсть животных', 'Bluttest auf spezifische IgE-Antikörper gegen die im Kindesalter häufigsten Allergene: Lebensmittel, Hausstaubmilben, Pollen und Tierhaare', 'Çocukluk çağında en sık görülen alerjenlere karşı özgül IgE antikorlarını ölçen kan testi: gıdalar, toz akarları, polen, hayvan tüyü', 'A small venous blood sample is taken from the child, and all allergens on the panel are checked in that one sample, so repeat needle sticks are not needed', 'Djetetu se uzima mala količina venske krvi, a svi alergeni iz panela provjeravaju se u jednom uzorku, pa ponovno ubadanje nije potrebno', 'Дјетету се узима мала количина венске крви, а сви алергени из панела провјеравају се у једном узорку, па поновно убадање није потребно', 'Забор небольшого объёма венозной крови у ребёнка, все аллергены панели проверяют в одном образце, повторные уколы не нужны', 'Dem Kind wird eine kleine Menge venösen Blutes entnommen, alle Allergene des Panels werden in dieser einen Probe geprüft, wiederholte Einstiche entfallen', 'Çocuktan az miktarda toplardamar kanı alınır, panelin tüm alerjenleri bu tek örnekte incelenir, yeniden iğne yapılması gerekmez', 'Atopic dermatitis, urticaria, recurrent runny nose and cough without signs of infection, reactions to the introduction of complementary foods, testing of a child as referred by a paediatrician or allergist', 'Atopijski dermatitis, urtikarija, ponavljana kijavica i kašalj bez znakova infekcije, reakcije pri uvođenju nemliječne hrane, ispitivanje djeteta po uputu pedijatra ili alergologa', 'Атопијски дерматитис, уртикарија, понављана кијавица и кашаљ без знакова инфекције, реакције при увођењу немлијечне хране, испитивање дјетета по упуту педијатра или алерголога', 'Атопический дерматит, крапивница, повторяющийся насморк и кашель без признаков инфекции, реакции на введение прикорма, обследование ребёнка по направлению педиатра или аллерголога', 'Atopische Dermatitis, Nesselsucht, wiederkehrender Schnupfen und Husten ohne Infektzeichen, Reaktionen bei der Einführung von Beikost, Untersuchung des Kindes auf Überweisung von Kinderarzt oder Allergologe', 'Atopik dermatit, ürtiker, enfeksiyon bulgusu olmadan yinelenen burun akıntısı ve öksürük, ek gıdaya geçişte görülen tepkiler, çocuk hekimi ya da alerji uzmanının yönlendirmesiyle inceleme', 'No preparation is needed and the child may eat before the test; tell the doctor about any medication taken and which foods have already been excluded', 'Priprema nije potrebna i dijete se može nahraniti prije analize; ljekaru treba reći koje lijekove dijete uzima i koje su namirnice već izbačene', 'Припрема није потребна и дијете се може нахранити прије анализе; љекару треба рећи које лијекове дијете узима и које су намирнице већ избачене', 'Подготовка не нужна, ребёнка можно покормить перед анализом; о принимаемых лекарствах и о том, какие продукты уже исключены, сообщают врачу', 'Keine Vorbereitung nötig, das Kind darf vor der Untersuchung essen; dem Arzt mitteilen, welche Medikamente es erhält und welche Lebensmittel bereits weggelassen werden', 'Hazırlık gerekmez, çocuk test öncesi beslenebilir; kullandığı ilaçlar ve beslenmesinden çıkarılmış gıdalar hekime bildirilir', 'The result shows sensitisation, and in children its pattern changes with age, so the report is assessed together with the complaints and the course of follow-up. Further management is decided by the doctor', 'Nalaz pokazuje senzibilizaciju, a njen spektar se kod djece mijenja sa uzrastom, pa se procjenjuje zajedno sa tegobama i tokom praćenja. Dalji postupak određuje ljekar', 'Налаз показује сензибилизацију, а њен спектар се код дјеце мијења са узрастом, па се процјењује заједно са тегобама и током праћења. Даљи поступак одређује љекар', 'Результат показывает сенсибилизацию, а её спектр у детей с возрастом меняется, поэтому его оценивают вместе с жалобами и динамикой наблюдения. Дальнейшую тактику определяет врач', 'Das Ergebnis zeigt eine Sensibilisierung, deren Muster sich bei Kindern mit dem Alter ändert, daher wird der Befund zusammen mit den Beschwerden und dem Verlauf beurteilt. Das weitere Vorgehen legt der Arzt fest', 'Sonuç duyarlanmayı gösterir, çocuklarda duyarlanma örüntüsü yaşla değişir, bu nedenle rapor şikayetler ve izlem seyriyle birlikte değerlendirilir. Sonraki adımları hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = '5-hiaa'), 'Laboratory measurement of the end product of serotonin metabolism, which leaves the body with urine', 'Laboratorijsko mjerenje krajnjeg proizvoda razgradnje serotonina, koji se iz organizma izlučuje urinom', 'Лабораторијско мјерење крајњег производа разградње серотонина, који се из организма излучује урином', 'Лабораторное измерение конечного продукта обмена серотонина, который выводится из организма с мочой', 'Laboruntersuchung des Endprodukts des Serotoninstoffwechsels, das mit dem Urin ausgeschieden wird', 'Serotonin metabolizmasının son ürününün laboratuvarda ölçümü; bu ürün vücuttan idrarla atılır', 'Urine is the sample: most often collected over 24 hours into a laboratory container, while some laboratories work with a single portion', 'Uzorak je urin: najčešće sakupljen tokom 24 sata u posudu laboratorije, dok pojedine laboratorije rade sa pojedinačnom porcijom', 'Узорак је урин: најчешће сакупљен током 24 сата у посуду лабораторије, док поједине лабораторије раде са појединачном порцијом', 'Материалом служит моча: чаще собранная за сутки в контейнер лаборатории, часть лабораторий работает с разовой порцией', 'Als Probe dient Urin: meist der über 24 Stunden in einem Laborbehälter gesammelte, manche Labore arbeiten mit einer Einzelportion', 'Örnek idrardır: çoğunlukla laboratuvarın verdiği kapta 24 saat boyunca toplanır, bazı laboratuvarlar tek porsiyonla çalışır', 'Long-standing flushing and facial redness, persistent diarrhoea and cramping abdominal pain, follow-up of neuroendocrine tumours as prescribed by a doctor', 'Dugotrajno crvenilo lica i naleti vrućine, uporan proliv i grčeviti bolovi u stomaku, praćenje neuroendokrinih tumora po odluci ljekara', 'Дуготрајно црвенило лица и налети врућине, упоран пролив и грчевити болови у стомаку, праћење неуроендокриних тумора по одлуци љекара', 'Длительные приливы и покраснение лица, стойкая диарея и спастические боли в животе, наблюдение при нейроэндокринных опухолях по назначению врача', 'Anhaltende Hitzewallungen und Gesichtsrötung, hartnäckiger Durchfall und krampfartige Bauchschmerzen, Verlaufskontrolle bei neuroendokrinen Tumoren nach ärztlicher Anordnung', 'Uzun süren sıcak basmaları ve yüzde kızarma, inatçı ishal ve karında kramp tarzı ağrı, hekim kararıyla nöroendokrin tümörlerin izlemi', 'For several days before and during the collection, foods rich in serotonin are avoided: bananas, pineapple, kiwi, plums, nuts, avocado, aubergine, tomatoes; the laboratory provides the full list of foods and interfering medicines, and any medication is stopped only in agreement with the doctor', 'Nekoliko dana prije sakupljanja i tokom njega izbjegavaju se namirnice bogate serotoninom: banane, ananas, kivi, šljive, orasi, avokado, patlidžan, paradajz; potpun spisak namirnica i lijekova koji utiču na nalaz daje laboratorija, a terapija se prekida samo uz dogovor sa ljekarom', 'Неколико дана прије сакупљања и током њега избјегавају се намирнице богате серотонином: банане, ананас, киви, шљиве, ораси, авокадо, патлиџан, парадајз; потпун списак намирница и лијекова који утичу на налаз даје лабораторија, а терапија се прекида само уз договор са љекаром', 'За несколько дней до сбора и во время него исключают продукты, богатые серотонином: бананы, ананас, киви, сливы, орехи, авокадо, баклажаны, томаты; полный список продуктов и влияющих лекарств даёт лаборатория, отмена препаратов — только по согласованию с врачом', 'Einige Tage vor und während der Sammlung werden serotoninreiche Lebensmittel gemieden: Bananen, Ananas, Kiwi, Pflaumen, Nüsse, Avocado, Auberginen, Tomaten; die vollständige Liste der Lebensmittel und störender Medikamente gibt das Labor, ein Absetzen von Medikamenten erfolgt nur in Absprache mit dem Arzt', 'Toplamadan birkaç gün önce ve toplama süresince serotoninden zengin gıdalardan kaçınılır: muz, ananas, kivi, erik, ceviz, avokado, patlıcan, domates; gıdaların ve sonucu etkileyen ilaçların tam listesini laboratuvar verir, ilaçlar yalnızca hekimle görüşülerek bırakılır', 'A change in the value may be related to diet, to a number of medicines or to features of serotonin metabolism, so the test is usually repeated and combined with other investigations. The result is assessed by the doctor who ordered it', 'Promjena vrijednosti može biti povezana sa ishranom, sa pojedinim lijekovima ili sa osobenostima metabolizma serotonina, pa se analiza obično ponavlja i dopunjava drugim ispitivanjima. Nalaz procjenjuje ljekar koji je uputio na analizu', 'Промјена вриједности може бити повезана са исхраном, са појединим лијековима или са особеностима метаболизма серотонина, па се анализа обично понавља и допуњава другим испитивањима. Налаз процјењује љекар који је упутио на анализу', 'Изменение показателя может быть связано с питанием, приёмом ряда лекарств или с особенностями обмена серотонина, поэтому анализ обычно повторяют и дополняют другими исследованиями. Результат оценивает назначивший врач', 'Eine Veränderung des Werts kann mit der Ernährung, mit einigen Medikamenten oder mit Besonderheiten des Serotoninstoffwechsels zusammenhängen, daher wird die Untersuchung meist wiederholt und durch weitere ergänzt. Das Ergebnis beurteilt der anfordernde Arzt', 'Değerdeki değişiklik beslenmeyle, bazı ilaçlarla ya da serotonin metabolizmasının özellikleriyle ilişkili olabilir, bu nedenle test genellikle yinelenir ve başka incelemelerle tamamlanır. Sonucu isteyen hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'vma'), 'Measurement of vanillylmandelic acid, a breakdown product of adrenaline and noradrenaline that is excreted in urine', 'Mjerenje vanililmandelne kiseline, proizvoda razgradnje adrenalina i noradrenalina, koji se izlučuje urinom', 'Мјерење ванилилманделне киселине, производа разградње адреналина и норадреналина, који се излучује урином', 'Измерение ванилилминдальной кислоты — продукта распада адреналина и норадреналина, который выводится с мочой', 'Messung der Vanillinmandelsäure, eines Abbauprodukts von Adrenalin und Noradrenalin, das über den Urin ausgeschieden wird', 'Adrenalin ve noradrenalinin yıkım ürünü olan ve idrarla atılan vanilmandelik asidin ölçümü', 'Urine is collected over 24 hours into a container with preservative provided by the laboratory, and the whole collected volume is delivered', 'Urin se sakuplja tokom 24 sata u posudu sa konzervansom koju izdaje laboratorija, a predaje se cjelokupna sakupljena količina', 'Урин се сакупља током 24 сата у посуду са конзервансом коју издаје лабораторија, а предаје се цјелокупна сакупљена количина', 'Мочу собирают в течение суток в контейнер с консервантом, выданный лабораторией, и доставляют весь собранный объём', 'Der Urin wird über 24 Stunden in einem vom Labor ausgegebenen Behälter mit Konservierungsmittel gesammelt und die gesamte Menge abgegeben', 'İdrar, laboratuvarın verdiği koruyucu maddeli kapta 24 saat boyunca toplanır ve toplanan tüm miktar teslim edilir', 'Episodes of raised blood pressure with sweating, palpitations and headache, work-up when a hormone-producing adrenal tumour is suspected, testing of children as referred by a doctor', 'Napadi porasta krvnog pritiska sa znojenjem, lupanjem srca i glavoboljom, obrada kod sumnje na hormonski aktivan tumor nadbubrežne žlijezde, ispitivanje djece po uputu ljekara', 'Напади пораста крвног притиска са знојењем, лупањем срца и главобољом, обрада код сумње на хормонски активан тумор надбубрежне жлијезде, испитивање дјеце по упуту љекара', 'Приступы повышения давления с потливостью, сердцебиением и головной болью, обследование при подозрении на гормонально активную опухоль надпочечника, обследование детей по направлению врача', 'Anfallsartige Blutdruckanstiege mit Schwitzen, Herzklopfen und Kopfschmerzen, Abklärung bei Verdacht auf einen hormonaktiven Nebennierentumor, Untersuchung von Kindern auf ärztliche Überweisung', 'Terleme, çarpıntı ve baş ağrısıyla birlikte ataklar hâlinde yükselen tansiyon, hormon salgılayan böbrek üstü bezi tümörü kuşkusunda inceleme, hekim yönlendirmesiyle çocukların incelenmesi', 'For one to two days before and during the collection, coffee, tea, chocolate, vanilla, bananas and citrus fruit are avoided, as are heavy physical exertion and stress; tell the doctor about all medicines being taken', 'Dan ili dva prije sakupljanja i tokom njega izbjegavaju se kafa, čaj, čokolada, vanila, banane i citrusi, kao i teški fizički napori i stres; o svim lijekovima koji se uzimaju obavještava se ljekar', 'Дан или два прије сакупљања и током њега избјегавају се кафа, чај, чоколада, ванила, банане и цитруси, као и тешки физички напори и стрес; о свим лијековима који се узимају обавјештава се љекар', 'За сутки-двое до сбора и во время него исключают кофе, чай, шоколад, ваниль, бананы и цитрусовые, избегают тяжёлых физических нагрузок и стресса; о принимаемых лекарствах сообщают врачу', 'Ein bis zwei Tage vor und während der Sammlung werden Kaffee, Tee, Schokolade, Vanille, Bananen und Zitrusfrüchte gemieden, ebenso starke körperliche Belastung und Stress; alle eingenommenen Medikamente dem Arzt mitteilen', 'Toplamadan bir iki gün önce ve toplama süresince kahve, çay, çikolata, vanilya, muz ve turunçgillerden, ayrıca ağır fiziksel egzersiz ve stresten kaçınılır; kullanılan tüm ilaçlar hekime bildirilir', 'An increase may be related to diet and physical exertion, to certain medicines, or to excess hormone production by the adrenal glands. The next steps are decided by the doctor based on the whole set of tests and imaging', 'Povišenje može biti povezano sa ishranom i naporom, sa nekim lijekovima ili sa pojačanim stvaranjem hormona u nadbubrežnim žlijezdama. Dalji postupak određuje ljekar na osnovu svih analiza i snimanja', 'Повишење може бити повезано са исхраном и напором, са неким лијековима или са појачаним стварањем хормона у надбубрежним жлијездама. Даљи поступак одређује љекар на основу свих анализа и снимања', 'Повышение может быть связано с питанием и нагрузкой, с приёмом некоторых препаратов или с избыточной выработкой гормонов надпочечниками. Что делать дальше, решает врач по совокупности анализов и визуализирующих исследований', 'Ein Anstieg kann mit Ernährung und Belastung, mit bestimmten Medikamenten oder mit einer vermehrten Hormonbildung der Nebennieren zusammenhängen. Das weitere Vorgehen entscheidet der Arzt anhand aller Befunde und der Bildgebung', 'Yükseklik beslenme ve fiziksel zorlanmayla, bazı ilaçlarla ya da böbrek üstü bezlerinin fazla hormon üretmesiyle ilişkili olabilir. Sonraki adımlara hekim, tüm tetkikler ve görüntüleme sonuçlarıyla birlikte karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'norovirus-in-stool'), 'Testing of a stool sample for norovirus, a common cause of acute gastroenteritis outbreaks', 'Ispitivanje uzorka stolice na norovirus, čest uzrok epidemija akutnog gastroenteritisa', 'Испитивање узорка столице на норовирус, чест узрок епидемија акутног гастроентеритиса', 'Исследование образца кала на норовирус, частую причину вспышек острого гастроэнтерита', 'Untersuchung einer Stuhlprobe auf Noroviren, eine häufige Ursache von Ausbrüchen akuter Magen-Darm-Infekte', 'Akut gastroenterit salgınlarının sık nedenlerinden olan norovirüs için dışkı örneğinin incelenmesi', 'A small portion of stool is placed in a sterile container, and the laboratory looks for viral antigen or RNA in it', 'Mala količina stolice stavlja se u sterilnu posudu, a laboratorija u njoj traži antigen ili RNK virusa', 'Мала количина столице ставља се у стерилну посуду, а лабораторија у њој тражи антиген или РНК вируса', 'Небольшую порцию кала помещают в стерильный контейнер, в лаборатории в ней ищут антиген или РНК вируса', 'Eine kleine Stuhlmenge wird in einen sterilen Behälter gegeben, und das Labor sucht darin Virusantigen oder RNA', 'Az miktarda dışkı steril bir kaba konur, laboratuvar bu örnekte virüs antijenini veya RNA''sını arar', 'Sudden vomiting and watery diarrhoea, clustered cases in a family, kindergarten, hotel or on a ship, clarifying the cause of a prolonged intestinal infection', 'Iznenadno povraćanje i vodenasti proliv, grupni slučajevi u porodici, vrtiću, hotelu ili na brodu, utvrđivanje uzroka produžene crijevne infekcije', 'Изненадно повраћање и воденасти пролив, групни случајеви у породици, вртићу, хотелу или на броду, утврђивање узрока продужене цријевне инфекције', 'Внезапная рвота и водянистый понос, групповые случаи в семье, детском саду, отеле или на судне, уточнение причины затянувшейся кишечной инфекции', 'Plötzliches Erbrechen und wässriger Durchfall, gehäufte Fälle in Familie, Kindergarten, Hotel oder auf einem Schiff, Klärung der Ursache einer länger dauernden Darminfektion', 'Ani kusma ve sulu ishal, ailede, kreşte, otelde veya gemide kümelenen olgular, uzayan bağırsak enfeksiyonunda nedenin belirlenmesi', 'No preparation is needed and the sample is best collected in the first days of illness; urine must not get into the container, and laxatives and enemas are not used before collection', 'Priprema nije potrebna, a uzorak je najbolje uzeti u prvim danima bolesti; u posudu ne smije dospjeti urin, a laksativi i klizme se ne koriste prije uzimanja uzorka', 'Припрема није потребна, а узорак је најбоље узети у првим данима болести; у посуду не смије доспјети урин, а лаксативи и клизме се не користе прије узимања узорка', 'Подготовка не нужна, образец лучше собрать в первые дни болезни; в контейнер не должна попадать моча, слабительные и клизмы перед сбором не используют', 'Keine Vorbereitung nötig, die Probe wird am besten in den ersten Krankheitstagen gewonnen; Urin darf nicht in den Behälter gelangen, Abführmittel und Einläufe werden vor der Probenahme nicht verwendet', 'Hazırlık gerekmez, örneği hastalığın ilk günlerinde almak en iyisidir; kaba idrar karışmamalı, örnek öncesi müshil ve lavman kullanılmamalıdır', 'Detection of the virus may be related to a current infection, while a negative result does not rule it out, especially if the sample was taken late. Treatment and infection control measures are decided by the doctor', 'Nalaz virusa može biti povezan sa aktuelnom infekcijom, dok negativan nalaz ne isključuje infekciju, naročito ako je uzorak uzet kasno. Liječenje i protivepidemijske mjere određuje ljekar', 'Налаз вируса може бити повезан са актуелном инфекцијом, док негативан налаз не искључује инфекцију, нарочито ако је узорак узет касно. Лијечење и противепидемијске мјере одређује љекар', 'Обнаружение вируса может быть связано с текущей инфекцией, а отрицательный результат её не исключает, особенно если образец взят поздно. Лечение и противоэпидемические меры определяет врач', 'Ein Virusnachweis kann mit einer aktuellen Infektion zusammenhängen, ein negatives Ergebnis schließt sie nicht aus, besonders bei später Probenahme. Behandlung und Hygienemaßnahmen legt der Arzt fest', 'Virüsün saptanması güncel bir enfeksiyonla ilişkili olabilir, negatif sonuç ise özellikle örnek geç alınmışsa enfeksiyonu dışlamaz. Tedaviyi ve bulaş önleme önlemlerini hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'stool-viruses-panel'), 'Simultaneous testing of a single stool sample for several intestinal viruses: usually rotavirus, adenovirus, norovirus and astrovirus', 'Istovremeno ispitivanje jednog uzorka stolice na više crijevnih virusa: obično su to rotavirus, adenovirus, norovirus i astrovirus', 'Истовремено испитивање једног узорка столице на више цријевних вируса: обично су то ротавирус, аденовирус, норовирус и астровирус', 'Одновременная проверка одного образца кала на несколько кишечных вирусов: обычно это ротавирус, аденовирус, норовирус и астровирус', 'Gleichzeitige Untersuchung einer Stuhlprobe auf mehrere Darmviren: meist Rotaviren, Adenoviren, Noroviren und Astroviren', 'Tek bir dışkı örneğinin birkaç bağırsak virüsü için aynı anda incelenmesi: genellikle rotavirüs, adenovirüs, norovirüs ve astrovirüs', 'One portion of stool in a sterile container is tested for all viruses included in the panel at once; the list is stated by the laboratory', 'Jedna porcija stolice u sterilnoj posudi ispituje se odjednom na sve viruse obuhvaćene panelom; njihov spisak navodi laboratorija', 'Једна порција столице у стерилној посуди испитује се одједном на све вирусе обухваћене панелом; њихов списак наводи лабораторија', 'Одну порцию кала в стерильном контейнере исследуют сразу на все вирусы, входящие в панель; их перечень указывает лаборатория', 'Eine Stuhlportion im sterilen Behälter wird auf alle im Panel enthaltenen Viren zugleich untersucht; die Liste gibt das Labor an', 'Steril kaptaki tek bir dışkı örneği, panelde yer alan tüm virüsler için aynı anda incelenir; listeyi laboratuvar belirtir', 'Acute diarrhoea and vomiting, especially in children, an outbreak of intestinal infection in a group, a prolonged course without a clear cause, testing before hospital admission as referred by a doctor', 'Akutni proliv i povraćanje, posebno kod djece, epidemija crijevne infekcije u kolektivu, produženi tok bez jasnog uzroka, ispitivanje uoči prijema u bolnicu po uputu ljekara', 'Акутни пролив и повраћање, посебно код дјеце, епидемија цријевне инфекције у колективу, продужени ток без јасног узрока, испитивање уочи пријема у болницу по упуту љекара', 'Острая диарея и рвота, особенно у детей, вспышка кишечной инфекции в коллективе, затяжное течение без ясной причины, обследование перед госпитализацией по направлению врача', 'Akuter Durchfall und Erbrechen, besonders bei Kindern, Ausbruch einer Darminfektion in einer Gemeinschaft, protrahierter Verlauf ohne klare Ursache, Untersuchung vor stationärer Aufnahme auf ärztliche Überweisung', 'Özellikle çocuklarda akut ishal ve kusma, toplu yaşam alanında bağırsak enfeksiyonu salgını, nedeni belirsiz uzamış seyir, hekim yönlendirmesiyle hastaneye yatış öncesi inceleme', 'No special preparation is required; the sample is collected during the acute phase into a clean container, and any treatment already started should be reported to the doctor', 'Posebna priprema nije potrebna; uzorak se uzima u akutnoj fazi bolesti u čistu posudu, a o već započetoj terapiji obavještava se ljekar', 'Посебна припрема није потребна; узорак се узима у акутној фази болести у чисту посуду, а о већ започетој терапији обавјештава се љекар', 'Специальная подготовка не требуется; образец собирают в острой фазе болезни в чистый контейнер, о начатом лечении сообщают врачу', 'Keine besondere Vorbereitung erforderlich; die Probe wird in der akuten Phase in einen sauberen Behälter gegeben, eine bereits begonnene Behandlung sollte dem Arzt mitgeteilt werden', 'Özel hazırlık gerekmez; örnek hastalığın akut döneminde temiz bir kaba alınır, başlanmış tedavi hekime bildirilir', 'Detection of one of the viruses may explain the current symptoms, while a negative panel does not rule out other causes of diarrhoea, including bacteria and parasites. Whether further tests are needed is decided by the doctor', 'Nalaz jednog od virusa može objasniti aktuelne tegobe, dok negativan panel ne isključuje druge uzroke proliva, uključujući bakterije i parazite. O potrebi dodatnih analiza odlučuje ljekar', 'Налаз једног од вируса може објаснити актуелне тегобе, док негативан панел не искључује друге узроке пролива, укључујући бактерије и паразите. О потреби додатних анализа одлучује љекар', 'Обнаружение одного из вирусов может объяснять текущие симптомы, а отрицательная панель не исключает других причин диареи, включая бактерии и паразитов. Нужны ли дополнительные анализы, решает врач', 'Der Nachweis eines der Viren kann die aktuellen Beschwerden erklären, ein negatives Panel schließt andere Durchfallursachen wie Bakterien und Parasiten nicht aus. Ob weitere Untersuchungen nötig sind, entscheidet der Arzt', 'Virüslerden birinin saptanması mevcut belirtileri açıklayabilir, negatif panel ise bakteri ve parazitler dahil başka ishal nedenlerini dışlamaz. Ek tetkik gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'magnesium-in-urine'), 'Measurement of the amount of magnesium that the kidneys excrete in urine', 'Mjerenje količine magnezijuma koju bubrezi izlučuju urinom', 'Мјерење количине магнезијума коју бубрези излучују урином', 'Измерение количества магния, которое почки выводят с мочой', 'Messung der Magnesiummenge, die die Nieren mit dem Urin ausscheiden', 'Böbreklerin idrarla attığı magnezyum miktarının ölçümü', 'Most often urine collected over 24 hours into a laboratory container is examined, less often a single portion', 'Najčešće se ispituje urin sakupljen tokom 24 sata u posudu laboratorije, rjeđe pojedinačna porcija', 'Најчешће се испитује урин сакупљен током 24 сата у посуду лабораторије, рјеђе појединачна порција', 'Чаще исследуют мочу, собранную за сутки в контейнер лаборатории, реже разовую порцию', 'Meist wird über 24 Stunden in einem Laborbehälter gesammelter Urin untersucht, seltener eine Einzelportion', 'Genellikle laboratuvarın verdiği kapta 24 saat boyunca toplanan idrar, daha seyrek olarak tek porsiyon incelenir', 'Cramps and muscle twitching, weakness, heart rhythm disturbances, finding the cause of low blood magnesium, monitoring in kidney disease and during long-term diuretic treatment', 'Grčevi i trzaji mišića, slabost, poremećaji srčanog ritma, traženje uzroka niskog magnezijuma u krvi, praćenje kod bubrežnih oboljenja i tokom dugotrajne terapije diureticima', 'Грчеви и трзаји мишића, слабост, поремећаји срчаног ритма, тражење узрока ниског магнезијума у крви, праћење код бубрежних обољења и током дуготрајне терапије диуретицима', 'Судороги и мышечные подёргивания, слабость, нарушения ритма сердца, выяснение причины низкого магния в крови, наблюдение при болезнях почек и при длительном приёме мочегонных', 'Krämpfe und Muskelzucken, Schwäche, Herzrhythmusstörungen, Ursachensuche bei niedrigem Magnesium im Blut, Verlaufskontrolle bei Nierenerkrankungen und unter langfristiger Behandlung mit Entwässerungsmitteln', 'Kramplar ve kas seğirmeleri, halsizlik, kalp ritim bozuklukları, kanda düşük magnezyumun nedeninin araştırılması, böbrek hastalıklarında ve uzun süreli idrar söktürücü tedavisinde izlem', 'Keep your usual diet and fluid intake during the collection; tell the doctor about magnesium supplements, diuretics and other medicines, and do not stop them on your own', 'Tokom sakupljanja zadržava se uobičajena ishrana i unos tečnosti; o preparatima magnezijuma, diureticima i drugim lijekovima obavještava se ljekar i ne prekidaju se na svoju ruku', 'Током сакупљања задржава се уобичајена исхрана и унос течности; о препаратима магнезијума, диуретицима и другим лијековима обавјештава се љекар и не прекидају се на своју руку', 'Во время сбора сохраняют обычное питание и питьевой режим; о приёме препаратов магния, мочегонных и других лекарств сообщают врачу и самостоятельно их не отменяют', 'Während der Sammlung die gewohnte Ernährung und Trinkmenge beibehalten; Magnesiumpräparate, Entwässerungsmittel und andere Medikamente dem Arzt mitteilen und nicht eigenmächtig absetzen', 'Toplama süresince olağan beslenme ve sıvı alımı sürdürülür; magnezyum preparatları, idrar söktürücüler ve diğer ilaçlar hekime bildirilir, kendi başına bırakılmaz', 'Increased or decreased excretion may be related to kidney function, diet, medicines, or losses through the digestive tract. The doctor compares the urine and blood results', 'Pojačano ili smanjeno izlučivanje može biti povezano sa radom bubrega, ishranom, lijekovima ili gubicima preko probavnog trakta. Nalaz urina i krvi upoređuje ljekar', 'Појачано или смањено излучивање може бити повезано са радом бубрега, исхраном, лијековима или губицима преко пробавног тракта. Налаз урина и крви упоређује љекар', 'Повышенное или сниженное выведение может быть связано с работой почек, с питанием, с приёмом лекарств или с потерями через желудочно-кишечный тракт. Мочу и кровь сопоставляет врач', 'Eine erhöhte oder verminderte Ausscheidung kann mit der Nierenfunktion, der Ernährung, Medikamenten oder Verlusten über den Magen-Darm-Trakt zusammenhängen. Urin- und Blutwerte gleicht der Arzt ab', 'Atılımın artması ya da azalması böbrek işleviyle, beslenmeyle, ilaçlarla ya da sindirim yoluyla olan kayıplarla ilişkili olabilir. İdrar ve kan sonuçlarını hekim karşılaştırır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'microalbumin'), 'Detection of small amounts of the protein albumin in urine that a routine urinalysis does not pick up', 'Otkrivanje malih količina proteina albumina u urinu koje običan opšti pregled urina ne prikazuje', 'Откривање малих количина протеина албумина у урину које обичан општи преглед урина не приказује', 'Определение небольших количеств белка альбумина в моче, которые обычный общий анализ не улавливает', 'Nachweis kleiner Mengen des Eiweißes Albumin im Urin, die eine übliche Urinuntersuchung nicht erfasst', 'Olağan tam idrar tetkikinin yakalayamadığı küçük miktarlardaki albümin proteininin idrarda saptanması', 'A morning urine portion or urine collected over 24 hours is examined; the result is often expressed relative to creatinine in the same sample', 'Ispituje se jutarnja porcija urina ili urin sakupljen tokom 24 sata; nalaz se često izražava u odnosu na kreatinin iz istog uzorka', 'Испитује се јутарња порција урина или урин сакупљен током 24 сата; налаз се често изражава у односу на креатинин из истог узорка', 'Исследуют утреннюю порцию мочи или мочу, собранную за сутки; часто результат пересчитывают на креатинин того же образца', 'Untersucht wird eine Morgenurinportion oder über 24 Stunden gesammelter Urin; das Ergebnis wird häufig auf das Kreatinin derselben Probe bezogen', 'Sabah idrar porsiyonu ya da 24 saat boyunca toplanan idrar incelenir; sonuç çoğu kez aynı örnekteki kreatinine oranlanarak verilir', 'Monitoring in diabetes mellitus and arterial hypertension, checking kidney function, work-up for oedema, assessing the effect of prescribed treatment', 'Praćenje kod šećerne bolesti i povišenog krvnog pritiska, kontrola rada bubrega, obrada kod otoka, procjena djelovanja propisane terapije', 'Праћење код шећерне болести и повишеног крвног притиска, контрола рада бубрега, обрада код отока, процјена дјеловања прописане терапије', 'Наблюдение при сахарном диабете и артериальной гипертензии, контроль работы почек, обследование при отёках, оценка эффекта назначенной терапии', 'Verlaufskontrolle bei Diabetes mellitus und Bluthochdruck, Überwachung der Nierenfunktion, Abklärung bei Ödemen, Beurteilung der Wirkung einer verordneten Therapie', 'Diyabet ve yüksek tansiyonda izlem, böbrek işlevinin takibi, ödem araştırması, verilen tedavinin etkisinin değerlendirilmesi', 'Wash the genital area before collection; do not submit the sample during menstruation, fever or a urinary tract infection, and avoid intense physical exercise the day before', 'Prije uzimanja uzorka obavlja se toaleta spoljašnjih genitalija; uzorak se ne predaje tokom menstruacije, kod povišene temperature i urinarne infekcije, a dan ranije se izbjegavaju jaki fizički napori', 'Прије узимања узорка обавља се тоалета спољашњих гениталија; узорак се не предаје током менструације, код повишене температуре и уринарне инфекције, а дан раније се избјегавају јаки физички напори', 'Перед сбором проводят туалет наружных половых органов; анализ не сдают во время менструации, при лихорадке и инфекции мочевых путей, накануне избегают интенсивных физических нагрузок', 'Vor der Gewinnung den Intimbereich reinigen; keine Probe während der Menstruation, bei Fieber oder Harnwegsinfekt abgeben und am Vortag intensive körperliche Belastung meiden', 'Örnek öncesi genital bölge temizlenir; adet döneminde, ateşliyken ve idrar yolu enfeksiyonu varken örnek verilmez, bir önceki gün ağır fiziksel egzersizden kaçınılır', 'The appearance of albumin may be related to the state of the kidney filters, but also to fever, exertion, a urinary tract infection or high blood pressure on the day of collection. The test is therefore usually repeated, and the result is assessed by the doctor', 'Pojava albumina može biti povezana sa stanjem bubrežnih filtera, ali i sa povišenom temperaturom, naporom, urinarnom infekcijom ili visokim pritiskom na dan uzorkovanja. Zato se analiza obično ponavlja, a nalaz procjenjuje ljekar', 'Појава албумина може бити повезана са стањем бубрежних филтера, али и са повишеном температуром, напором, уринарном инфекцијом или високим притиском на дан узорковања. Зато се анализа обично понавља, а налаз процјењује љекар', 'Появление альбумина может быть связано с состоянием почечных фильтров, но также с лихорадкой, нагрузкой, инфекцией мочевых путей или высоким давлением в день сбора. Поэтому анализ обычно повторяют, а результат оценивает врач', 'Das Auftreten von Albumin kann mit dem Zustand der Nierenfilter zusammenhängen, aber auch mit Fieber, Belastung, einem Harnwegsinfekt oder hohem Blutdruck am Tag der Gewinnung. Daher wird die Untersuchung meist wiederholt, und das Ergebnis beurteilt der Arzt', 'İdrarda albümin görülmesi böbrek filtrelerinin durumuyla ilişkili olabileceği gibi ateş, fiziksel zorlanma, idrar yolu enfeksiyonu ya da örnek günündeki yüksek tansiyonla da ilişkili olabilir. Bu nedenle test genellikle yinelenir, sonucu hekim değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = '5-hiaa-in-24h-urine'), 'Measurement of the serotonin metabolism marker in all urine passed over 24 hours: a full-day collection smooths out fluctuations in excretion during the day', 'Mjerenje pokazatelja metabolizma serotonina u cjelokupnom urinu sakupljenom tokom 24 sata: dnevno sakupljanje ublažava kolebanja izlučivanja tokom dana', 'Мјерење показатеља метаболизма серотонина у цјелокупном урину сакупљеном током 24 сата: дневно сакупљање ублажава колебања излучивања током дана', 'Измерение показателя обмена серотонина во всей моче, собранной за 24 часа: суточный сбор сглаживает колебания выведения в течение дня', 'Messung des Markers des Serotoninstoffwechsels im gesamten über 24 Stunden gesammelten Urin: die Tagessammlung gleicht Schwankungen der Ausscheidung im Tagesverlauf aus', 'Serotonin metabolizması göstergesinin 24 saat boyunca toplanan idrarın tamamında ölçümü: gün boyu toplama, atılımdaki gün içi dalgalanmaları yumuşatır', 'All urine over 24 hours is collected into a container with preservative: the first morning portion is discarded, the next morning portion is the last one collected, and the whole volume is taken to the laboratory', 'Sav urin tokom 24 sata sakuplja se u posudu sa konzervansom: prva jutarnja porcija se ne uzima, posljednja je jutarnja porcija narednog dana, a cjelokupna količina se nosi u laboratoriju', 'Сав урин током 24 сата сакупља се у посуду са конзервансом: прва јутарња порција се не узима, посљедња је јутарња порција наредног дана, а цјелокупна количина се носи у лабораторију', 'Всю мочу за сутки собирают в контейнер с консервантом: первую утреннюю порцию не берут, последней собирают утреннюю порцию следующего дня, весь объём везут в лабораторию', 'Der gesamte Urin von 24 Stunden wird in einem Behälter mit Konservierungsmittel gesammelt: die erste Morgenportion wird verworfen, die Morgenportion des Folgetags ist die letzte, und die gesamte Menge wird ins Labor gebracht', '24 saatlik idrarın tamamı koruyucu maddeli kapta toplanır: ilk sabah porsiyonu alınmaz, ertesi sabahki porsiyon son olarak toplanır ve tüm hacim laboratuvara götürülür', 'Work-up for persistent diarrhoea and flushing, follow-up over time as prescribed by a doctor, confirmation of a value obtained from a single portion', 'Obrada kod upornog proliva i naleta crvenila, praćenje tokom vremena po odluci ljekara, potvrda vrijednosti dobijene iz pojedinačne porcije', 'Обрада код упорног пролива и налета црвенила, праћење током времена по одлуци љекара, потврда вриједности добијене из појединачне порције', 'Обследование при стойкой диарее и приливах, динамическое наблюдение по назначению врача, подтверждение показателя, полученного в разовой порции', 'Abklärung bei anhaltendem Durchfall und Hitzewallungen, Verlaufskontrolle nach ärztlicher Anordnung, Bestätigung eines Werts aus einer Einzelportion', 'İnatçı ishal ve sıcak basmalarının araştırılması, hekim kararıyla zaman içinde izlem, tek porsiyondan elde edilen değerin doğrulanması', 'Dietary restrictions apply both the day before and throughout the collection; keep the container in a cool place, note the start and end times of the collection, and ask the doctor about medicines that affect the result', 'Ograničenja u ishrani važe i dan ranije i cijelo vrijeme sakupljanja; posuda se drži na hladnom, bilježi se vrijeme početka i završetka sakupljanja, a o lijekovima koji utiču na nalaz pita se ljekar', 'Ограничења у исхрани важе и дан раније и цијело вријеме сакупљања; посуда се држи на хладном, биљежи се вријеме почетка и завршетка сакупљања, а о лијековима који утичу на налаз пита се љекар', 'Ограничения по питанию соблюдают и накануне, и всё время сбора; контейнер держат в прохладном месте, отмечают время начала и окончания сбора, о влияющих на результат лекарствах спрашивают врача', 'Die Ernährungseinschränkungen gelten am Vortag und während der gesamten Sammlung; den Behälter kühl aufbewahren, Beginn und Ende der Sammlung notieren und den Arzt nach Medikamenten fragen, die das Ergebnis beeinflussen', 'Beslenme kısıtlamaları hem bir gün önce hem de toplama boyunca geçerlidir; kap serin yerde tutulur, toplamanın başlangıç ve bitiş saatleri not edilir, sonucu etkileyen ilaçlar hekime sorulur', 'A deviation may be explained by an incomplete collection or by diet, so the completeness of the collection is checked first, and then the doctor decides whether to repeat the test or add other investigations', 'Odstupanje se može objasniti nepotpunim sakupljanjem urina ili ishranom, pa se prvo provjerava kako je sakupljanje proteklo, a zatim ljekar odlučuje da li ponoviti ispitivanje ili ga dopuniti drugim analizama', 'Одступање се може објаснити непотпуним сакупљањем урина или исхраном, па се прво провјерава како је сакупљање протекло, а затим љекар одлучује да ли поновити испитивање или га допунити другим анализама', 'Отклонение может объясняться неполным сбором мочи или питанием, поэтому сначала проверяют, как прошёл сбор, а затем врач решает, повторить исследование или дополнить его другими анализами', 'Eine Abweichung kann durch eine unvollständige Sammlung oder durch die Ernährung bedingt sein, daher wird zuerst der Sammelvorgang überprüft und danach entscheidet der Arzt, ob die Untersuchung wiederholt oder durch weitere ergänzt wird', 'Sapma, idrarın eksik toplanmasıyla ya da beslenmeyle açıklanabilir, bu nedenle önce toplamanın nasıl yapıldığı gözden geçirilir, ardından hekim testin yinelenmesine ya da başka tetkiklerle tamamlanmasına karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'intact-pth'), 'Blood test for the whole (intact) molecule of parathyroid hormone, which regulates calcium and phosphorus metabolism', 'Analiza krvi na cijelu (intaktnu) molekulu paratireoidnog hormona, koji reguliše metabolizam kalcijuma i fosfora', 'Анализа крви на цијелу (интактну) молекулу паратиреоидног хормона, који регулише метаболизам калцијума и фосфора', 'Анализ крови на цельную (интактную) молекулу паратиреоидного гормона, который регулирует обмен кальция и фосфора', 'Bluttest auf das vollständige (intakte) Molekül des Parathormons, das den Kalzium- und Phosphatstoffwechsel reguliert', 'Kalsiyum ve fosfor metabolizmasını düzenleyen paratiroid hormonunun bütün (intakt) molekülünü ölçen kan testi', 'Venous blood is drawn, usually in the morning; the tube is cooled quickly and sent to the laboratory, as the hormone is unstable', 'Uzima se venska krv, najčešće ujutru; epruveta se brzo rashladi i šalje u laboratoriju jer je hormon nestabilan', 'Узима се венска крв, најчешће ујутру; епрувета се брзо расхлади и шаље у лабораторију јер је хормон нестабилан', 'Забор венозной крови, чаще утром; пробирку быстро охлаждают и передают в лабораторию, так как гормон нестабилен', 'Es wird venöses Blut entnommen, meist morgens; das Röhrchen wird rasch gekühlt und ins Labor gebracht, da das Hormon instabil ist', 'Genellikle sabah toplardamardan kan alınır; hormon dayanıksız olduğu için tüp hızla soğutulur ve laboratuvara iletilir', 'High or low blood calcium, kidney stones and osteoporosis, work-up for parathyroid disease, monitoring in chronic kidney disease, follow-up after parathyroid surgery', 'Povišen ili snižen kalcijum u krvi, kamenci u bubrezima i osteoporoza, obrada kod oboljenja paratireoidnih žlijezda, praćenje kod hronične bubrežne bolesti, kontrola nakon operacije paratireoidnih žlijezda', 'Повишен или снижен калцијум у крви, каменци у бубрезима и остеопороза, обрада код обољења паратиреоидних жлијезда, праћење код хроничне бубрежне болести, контрола након операције паратиреоидних жлијезда', 'Повышенный или сниженный кальций крови, мочекаменная болезнь и остеопороз, обследование при заболеваниях паращитовидных желёз, наблюдение при хронической болезни почек, контроль после операции на паращитовидных железах', 'Erhöhtes oder erniedrigtes Kalzium im Blut, Nierensteine und Osteoporose, Abklärung bei Erkrankungen der Nebenschilddrüsen, Verlaufskontrolle bei chronischer Nierenerkrankung, Kontrolle nach einer Operation an den Nebenschilddrüsen', 'Kanda yüksek ya da düşük kalsiyum, böbrek taşı ve osteoporoz, paratiroid bezi hastalıklarının araştırılması, kronik böbrek hastalığında izlem, paratiroid ameliyatı sonrası kontrol', 'The sample is taken in the morning on an empty stomach, water is allowed; avoid intense exertion before the test and tell the doctor about calcium and vitamin D supplements', 'Uzorak se daje ujutru natašte, voda je dozvoljena; prije analize se izbjegavaju jaki napori, a o uzimanju preparata kalcijuma i vitamina D obavještava se ljekar', 'Узорак се даје ујутру наташте, вода је дозвољена; прије анализе се избјегавају јаки напори, а о узимању препарата калцијума и витамина Д обавјештава се љекар', 'Сдают утром натощак, воду пить можно; перед анализом избегают интенсивных нагрузок, о приёме препаратов кальция и витамина D сообщают врачу', 'Die Entnahme erfolgt morgens nüchtern, Wasser ist erlaubt; vor der Untersuchung starke körperliche Belastung meiden und die Einnahme von Kalzium- und Vitamin-D-Präparaten dem Arzt mitteilen', 'Örnek sabah aç karnına verilir, su içilebilir; testten önce ağır egzersizden kaçınılır, kalsiyum ve D vitamini preparatları hekime bildirilir', 'Changes may be related to the work of the parathyroid glands, to calcium and vitamin D levels, or to kidney function. The value is always interpreted together with blood calcium, and this is done by the doctor', 'Promjene mogu biti povezane sa radom paratireoidnih žlijezda, sa nivoom kalcijuma i vitamina D ili sa funkcijom bubrega. Vrijednost se uvijek tumači zajedno sa kalcijumom u krvi, a to radi ljekar', 'Промјене могу бити повезане са радом паратиреоидних жлијезда, са нивоом калцијума и витамина Д или са функцијом бубрега. Вриједност се увијек тумачи заједно са калцијумом у крви, а то ради љекар', 'Изменения могут быть связаны с работой паращитовидных желёз, с уровнем кальция и витамина D или с функцией почек. Показатель всегда трактуют вместе с кальцием крови, и делает это врач', 'Veränderungen können mit der Funktion der Nebenschilddrüsen, mit dem Kalzium- und Vitamin-D-Spiegel oder mit der Nierenfunktion zusammenhängen. Der Wert wird immer zusammen mit dem Blutkalzium beurteilt, und zwar durch den Arzt', 'Değişiklikler paratiroid bezlerinin çalışmasıyla, kalsiyum ve D vitamini düzeyiyle ya da böbrek işleviyle ilişkili olabilir. Değer her zaman kandaki kalsiyumla birlikte yorumlanır ve bunu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'inhibin-a'), 'Blood test for a glycoprotein hormone produced by ovarian cells and, during pregnancy, by the placenta', 'Analiza krvi na glikoproteinski hormon koji stvaraju ćelije jajnika, a tokom trudnoće posteljica', 'Анализа крви на гликопротеински хормон који стварају ћелије јајника, а током трудноће постељица', 'Анализ крови на гликопротеиновый гормон, который вырабатывают клетки яичника, а во время беременности — плацента', 'Bluttest auf ein Glykoproteinhormon, das von Zellen des Eierstocks und in der Schwangerschaft von der Plazenta gebildet wird', 'Yumurtalık hücreleri tarafından, gebelikte ise plasenta tarafından üretilen bir glikoprotein hormonu ölçen kan testi', 'Venous blood draw, takes a few minutes', 'Uzimanje venske krvi, traje nekoliko minuta', 'Узимање венске крви, траје неколико минута', 'Забор венозной крови, занимает несколько минут', 'Venöse Blutentnahme, dauert wenige Minuten', 'Toplardamardan kan alınması, birkaç dakika sürer', 'Assessment of ovarian function together with other hormones as ordered by a doctor, one of the components of second-trimester biochemical screening in pregnancy, follow-up monitoring at the treating doctor''s decision', 'Procjena funkcije jajnika zajedno sa drugim hormonima po uputu ljekara, jedan od pokazatelja biohemijskog skrininga u drugom trimestru trudnoće, praćenje po odluci ljekara', 'Процјена функције јајника заједно са другим хормонима по упуту љекара, један од показатеља биохемијског скрининга у другом триместру трудноће, праћење по одлуци љекара', 'Оценка функции яичников вместе с другими гормонами по назначению врача, один из показателей биохимического скрининга второго триместра беременности, наблюдение в динамике по решению лечащего врача', 'Beurteilung der Eierstockfunktion zusammen mit weiteren Hormonen auf ärztliche Anordnung, einer der Werte des biochemischen Screenings im zweiten Schwangerschaftsdrittel, Verlaufskontrolle nach Entscheidung des behandelnden Arztes', 'Hekim isteğiyle diğer hormonlarla birlikte yumurtalık işlevinin değerlendirilmesi, gebelikte ikinci üç aylık dönemdeki biyokimyasal taramanın bileşenlerinden biri, hekimin kararına göre izlem', 'No special preparation is usually needed; in non-pregnant women the doctor may schedule the draw for a particular day of the cycle, and in pregnancy the exact gestational age must be stated', 'Posebna priprema obično nije potrebna; kod žena koje nisu trudne ljekar može odrediti tačan dan ciklusa, a u trudnoći je važno navesti tačnu gestacijsku starost', 'Посебна припрема обично није потребна; код жена које нису трудне љекар може одредити тачан дан циклуса, а у трудноћи је важно навести тачну гестацијску старост', 'Специальной подготовки обычно не требуется; у небеременных женщин врач может привязать забор к определённому дню цикла, при беременности важен точно указанный срок', 'Eine besondere Vorbereitung ist meist nicht nötig; bei nicht schwangeren Frauen kann der Arzt einen bestimmten Zyklustag festlegen, in der Schwangerschaft muss die genaue Schwangerschaftswoche angegeben werden', 'Genellikle özel bir hazırlık gerekmez; gebe olmayan kadınlarda hekim kan alımını belirli bir siklus gününe göre planlayabilir, gebelikte ise gebelik haftasının tam olarak belirtilmesi gerekir', 'A single value is not a diagnosis: in pregnancy it is assessed only together with the other screening markers, and outside pregnancy together with the rest of the reproductive hormone profile. The conclusion is drawn by the doctor', 'Pojedinačni nalaz nije dijagnoza: u trudnoći se procjenjuje isključivo zajedno sa ostalim pokazateljima skrininga, a van trudnoće uz ostale hormone reproduktivnog profila. Zaključak donosi ljekar', 'Појединачни налаз није дијагноза: у трудноћи се процјењује искључиво заједно са осталим показатељима скрининга, а ван трудноће уз остале хормоне репродуктивног профила. Закључак доноси љекар', 'Отдельное значение не является диагнозом: при беременности его оценивают только в комплексе с остальными показателями скрининга, вне беременности — вместе с прочими гормонами репродуктивного профиля. Вывод делает врач', 'Ein Einzelwert ist keine Diagnose: in der Schwangerschaft wird er ausschließlich zusammen mit den übrigen Screeningwerten beurteilt, außerhalb der Schwangerschaft zusammen mit den anderen Hormonen des Reproduktionsprofils. Die Bewertung nimmt der Arzt vor', 'Tek bir sonuç tanı değildir: gebelikte yalnızca diğer tarama göstergeleriyle birlikte, gebelik dışında ise üreme hormon profilinin geri kalanıyla birlikte değerlendirilir. Yorumu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'thrombin-time'), 'An indicator of the final step of clotting: how long plasma takes to form a clot after thrombin is added', 'Pokazatelj posljednjeg koraka zgrušavanja: za koliko plazma stvori ugrušak nakon dodavanja trombina', 'Показатељ посљедњег корака згрушавања: за колико плазма створи угрушак након додавања тромбина', 'Показатель последнего этапа свёртывания: за какое время плазма образует сгусток после добавления тромбина', 'Kennwert des letzten Gerinnungsschritts: wie lange das Plasma nach Zugabe von Thrombin bis zur Gerinnselbildung braucht', 'Pıhtılaşmanın son basamağının göstergesi: trombin eklendikten sonra plazmanın pıhtı oluşturması için geçen süre', 'Venous blood is drawn into a citrate tube and the sample is then run on a coagulometer in the laboratory', 'Uzimanje venske krvi u epruvetu sa citratom, uzorak se zatim obrađuje na koagulometru u laboratoriji', 'Узимање венске крви у епрувету са цитратом, узорак се затим обрађује на коагулометру у лабораторији', 'Забор венозной крови в пробирку с цитратом, дальше пробу исследуют в лаборатории на коагулометре', 'Venöse Blutentnahme in ein Citratröhrchen, die Probe wird anschließend im Labor am Koagulometer gemessen', 'Sitratlı tüpe toplardamardan kan alınır, örnek laboratuvarda koagülometrede çalışılır', 'Working out why other clotting values are prolonged, monitoring during heparin treatment, assessment of bleeding tendency, evaluation of fibrinogen as part of a coagulation panel', 'Razjašnjavanje uzroka produženih nalaza koagulacije, praćenje tokom terapije heparinom, ispitivanje sklonosti krvarenju, procjena fibrinogena u sklopu koagulograma', 'Разјашњавање узрока продужених налаза коагулације, праћење током терапије хепарином, испитивање склоности крварењу, процјена фибриногена у склопу коагулограма', 'Разбор причин удлинённых показателей свёртывания, контроль при лечении гепарином, обследование при кровоточивости, оценка фибриногена в составе коагулограммы', 'Abklärung verlängerter Gerinnungswerte, Kontrolle unter Heparintherapie, Abklärung von Blutungsneigung, Beurteilung des Fibrinogens im Rahmen des Gerinnungsstatus', 'Uzamış pıhtılaşma sonuçlarının nedeninin araştırılması, heparin tedavisi sırasında izlem, kanama eğiliminin değerlendirilmesi, koagülasyon paneli içinde fibrinojenin değerlendirilmesi', 'No special preparation is usually required; the laboratory should be told about anticoagulants, and the tube must be filled to the mark, so the draw is done by trained staff', 'Posebna priprema obično nije potrebna; laboratoriji se javlja terapija antikoagulansima, a epruveta mora biti napunjena do oznake, pa uzorak uzima obučeno osoblje', 'Посебна припрема обично није потребна; лабораторији се јавља терапија антикоагулансима, а епрувета мора бити напуњена до ознаке, па узорак узима обучено особље', 'Специальной подготовки обычно не требуется; о приёме антикоагулянтов сообщают лаборатории, а пробирку важно заполнить до метки, поэтому забор делает обученный персонал', 'Meist ist keine besondere Vorbereitung nötig; Antikoagulanzien sollten dem Labor mitgeteilt werden, und das Röhrchen muss bis zur Markierung gefüllt sein, daher erfolgt die Entnahme durch geschultes Personal', 'Genellikle özel hazırlık gerekmez; kullanılan antikoagülanlar laboratuvara bildirilir, tüpün işarete kadar dolması gerektiğinden kan eğitimli personel tarafından alınır', 'Prolongation may be related to heparin in the sample, low or altered fibrinogen, fibrin degradation products and, less often, inherited features. The conclusion is drawn by a doctor from the whole coagulation panel', 'Produženje može biti povezano sa prisustvom heparina u uzorku, niskim ili izmijenjenim fibrinogenom, razgradnim produktima fibrina, rjeđe sa nasljednim osobinama. Zaključak donosi ljekar na osnovu cijelog koagulograma', 'Продужење може бити повезано са присуством хепарина у узорку, ниским или измијењеним фибриногеном, разградним продуктима фибрина, рјеђе са насљедним особинама. Закључак доноси љекар на основу цијелог коагулограма', 'Удлинение может быть связано с присутствием гепарина в пробе, низким или изменённым фибриногеном, продуктами распада фибрина, реже — с наследственными особенностями. Заключение делает врач по всей коагулограмме', 'Eine Verlängerung kann mit Heparin in der Probe, niedrigem oder verändertem Fibrinogen, Fibrinspaltprodukten und seltener mit erblichen Besonderheiten zusammenhängen. Die Beurteilung erfolgt durch den Arzt anhand des gesamten Gerinnungsstatus', 'Uzama, örnekteki heparin, düşük ya da yapısı değişmiş fibrinojen, fibrin yıkım ürünleri ve daha seyrek olarak kalıtsal özelliklerle ilişkili olabilir. Değerlendirmeyi hekim tüm koagülasyon paneline bakarak yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'von-willebrand-factor-activity'), 'A functional test of the protein that helps platelets stick to a damaged vessel wall', 'Funkcionalna proba bjelančevine koja pomaže trombocitima da prianjaju uz oštećeni zid krvnog suda', 'Функционална проба бјеланчевине која помаже тромбоцитима да приањају уз оштећени зид крвног суда', 'Функциональная проба на белок, который помогает тромбоцитам прилипать к повреждённой стенке сосуда', 'Funktionstest des Proteins, das Blutplättchen beim Anhaften an der verletzten Gefäßwand unterstützt', 'Trombositlerin hasarlı damar duvarına yapışmasına yardımcı olan proteinin işlevini ölçen test', 'Venous blood is drawn into a citrate tube and the activity of the factor is measured in plasma', 'Uzimanje venske krvi u epruvetu sa citratom, aktivnost faktora mjeri se u plazmi', 'Узимање венске крви у епрувету са цитратом, активност фактора мјери се у плазми', 'Забор венозной крови в пробирку с цитратом, активность фактора определяют в плазме', 'Venöse Blutentnahme in ein Citratröhrchen, die Aktivität des Faktors wird im Plasma bestimmt', 'Sitratlı tüpe toplardamardan kan alınır, faktörün etkinliği plazmada ölçülür', 'Easy bruising, nosebleeds and bleeding gums, heavy menstrual bleeding, prolonged bleeding after a tooth extraction or surgery, family history of bleeding, pre-procedure work-up as ordered by a doctor', 'Sklonost modricama, krvarenju iz nosa i desni, obilne menstruacije, dugotrajno krvarenje poslije vađenja zuba ili operacije, porodična sklonost krvarenju, priprema za zahvat po uputu ljekara', 'Склоност модрицама, крварењу из носа и десни, обилне менструације, дуготрајно крварење послије вађења зуба или операције, породична склоност крварењу, припрема за захват по упуту љекара', 'Склонность к синякам, носовым кровотечениям и кровоточивости дёсен, обильные менструации, длительные кровотечения после удаления зуба или операции, семейная склонность к кровоточивости, обследование перед вмешательством по назначению врача', 'Neigung zu blauen Flecken, Nasenbluten und Zahnfleischbluten, starke Regelblutungen, langes Nachbluten nach Zahnentfernung oder Operation, Blutungsneigung in der Familie, Abklärung vor Eingriffen auf ärztliche Anordnung', 'Kolay morarma, burun ve diş eti kanamaları, adet kanamalarının fazla olması, diş çekimi veya ameliyat sonrası uzayan kanama, ailede kanama eğilimi, hekim isteğiyle girişim öncesi değerlendirme', 'No special preparation is usually needed; blood is preferably taken outside acute inflammation and stress, and hormonal medication and drugs affecting clotting should be reported to the doctor, who alone decides on any pause in treatment', 'Posebna priprema obično nije potrebna; krv se nastoji uzeti van akutne upale i stresa, a hormonsku terapiju i lijekove koji utiču na zgrušavanje treba javiti ljekaru, jer samo on odlučuje o pauzi u terapiji', 'Посебна припрема обично није потребна; крв се настоји узети ван акутне упале и стреса, а хормонску терапију и лијекове који утичу на згрушавање треба јавити љекару, јер само он одлучује о паузи у терапији', 'Специальной подготовки обычно нет; кровь стараются брать вне острого воспаления и стресса, о приёме гормональных и влияющих на свёртывание препаратов сообщают врачу — паузу в лечении назначает только он', 'Meist ist keine besondere Vorbereitung nötig; die Entnahme erfolgt möglichst außerhalb akuter Entzündungen und Stress, Hormonpräparate und gerinnungswirksame Medikamente sollten dem Arzt mitgeteilt werden, über eine Therapiepause entscheidet allein er', 'Genellikle özel hazırlık gerekmez; kan mümkünse akut iltihap ve stres dışındaki bir dönemde alınır, hormon ilaçları ile pıhtılaşmayı etkileyen ilaçlar hekime bildirilir, tedaviye ara verme kararını yalnızca hekim verir', 'Reduced activity may be related to inherited features of the factor, while a higher value may be related to inflammation, pregnancy, physical exertion and stress; blood group also influences the result. It is assessed alongside the amount of the factor itself and a repeat test, and the conclusion is made by a doctor', 'Snižena aktivnost može biti povezana sa nasljednim osobinama faktora, a povišena sa upalom, trudnoćom, fizičkim naporom i stresom; na nalaz utiče i krvna grupa. Procjenjuje se uz količinu samog faktora i ponovljenu analizu, a zaključak donosi ljekar', 'Снижена активност може бити повезана са насљедним особинама фактора, а повишена са упалом, трудноћом, физичким напором и стресом; на налаз утиче и крвна група. Процјењује се уз количину самог фактора и поновљену анализу, а закључак доноси љекар', 'Сниженная активность может быть связана с наследственными особенностями фактора, а повышенная — с воспалением, беременностью, физической нагрузкой и стрессом; на результат влияет и группа крови. Оценивают его в паре с количеством самого фактора и повторным анализом, вывод делает врач', 'Eine verminderte Aktivität kann mit erblichen Besonderheiten des Faktors zusammenhängen, ein höherer Wert mit Entzündung, Schwangerschaft, körperlicher Belastung und Stress; auch die Blutgruppe beeinflusst den Wert. Beurteilt wird er zusammen mit der Menge des Faktors und einer Kontrollmessung durch den Arzt', 'Düşük etkinlik faktörün kalıtsal özellikleriyle, yüksek değer ise iltihap, gebelik, fiziksel zorlanma ve stresle ilişkili olabilir; kan grubu da sonucu etkiler. Sonuç, faktörün miktarı ve tekrarlanan ölçümle birlikte hekim tarafından değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'bleeding-and-coagulation-time'), 'Two simple bedside tests: the time until bleeding from a skin puncture stops and the time until a drop of blood forms a clot', 'Dvije jednostavne probe uz pacijenta: vrijeme do prestanka krvarenja iz uboda kože i vrijeme stvaranja ugruška u kapi krvi', 'Двије једноставне пробе уз пацијента: вријеме до престанка крварења из убода коже и вријеме стварања угрушка у капи крви', 'Две простые пробы у постели пациента: время остановки кровотечения из прокола кожи и время образования сгустка в капле крови', 'Zwei einfache Tests am Patienten: die Zeit bis zum Stillstand der Blutung aus einem Hautstich und die Zeit bis zur Gerinnselbildung in einem Blutstropfen', 'Hasta başında yapılan iki basit test: deri ponksiyonundan sonra kanamanın durma süresi ve bir damla kanda pıhtı oluşma süresi', 'A nurse makes a small skin puncture and times the moment bleeding stops, then measures clotting time in a drop of blood; both tests take a few minutes', 'Medicinska sestra napravi mali ubod kože i štopericom prati prestanak krvarenja, zatim u kapi krvi određuje vrijeme zgrušavanja; obje probe traju nekoliko minuta', 'Медицинска сестра направи мали убод коже и штоперицом прати престанак крварења, затим у капи крви одређује вријеме згрушавања; обје пробе трају неколико минута', 'Медсестра делает небольшой прокол кожи и по секундомеру отмечает остановку кровотечения, затем по капле крови определяет время свёртывания; обе пробы занимают несколько минут', 'Eine Pflegekraft setzt einen kleinen Hautstich und stoppt die Zeit bis zum Ende der Blutung, danach wird im Blutstropfen die Gerinnungszeit bestimmt; beide Tests dauern wenige Minuten', 'Hemşire deride küçük bir ponksiyon yapar ve kanamanın durduğu anı kronometreyle belirler, ardından bir damla kanda pıhtılaşma süresini ölçer; iki test birkaç dakika sürer', 'Rough check of haemostasis before minor procedures and tooth extraction, bruising and bleeding gums, initial assessment before more precise clotting tests', 'Orijentaciona provjera hemostaze prije manjih zahvata i vađenja zuba, modrice i krvarenje desni, početna procjena prije preciznijih testova koagulacije', 'Оријентациона провјера хемостазе прије мањих захвата и вађења зуба, модрице и крварење десни, почетна процјена прије прецизнијих тестова коагулације', 'Ориентировочная проверка гемостаза перед небольшими вмешательствами и удалением зуба, синяки и кровоточивость дёсен, первичная оценка перед более точными тестами свёртывания', 'Orientierende Prüfung der Blutstillung vor kleinen Eingriffen und Zahnentfernungen, blaue Flecken und Zahnfleischbluten, erste Einschätzung vor genaueren Gerinnungstests', 'Küçük girişimler ve diş çekimi öncesi hemostazın kaba değerlendirilmesi, morarma ve diş eti kanamaları, daha kesin pıhtılaşma testlerinden önce ilk değerlendirme', 'No special preparation is required; aspirin, anticoagulants and other drugs affecting clotting should be reported to the doctor in advance, and only the doctor decides on pausing them', 'Posebna priprema nije potrebna; aspirin, antikoagulanse i druge lijekove koji utiču na zgrušavanje treba unaprijed prijaviti ljekaru, a pauzu u terapiji određuje isključivo on', 'Посебна припрема није потребна; аспирин, антикоагулансе и друге лијекове који утичу на згрушавање треба унапријед пријавити љекару, а паузу у терапији одређује искључиво он', 'Специальной подготовки не требуется; о приёме аспирина, антикоагулянтов и других влияющих на свёртывание препаратов заранее предупреждают врача, паузу в приёме назначает только он', 'Eine besondere Vorbereitung ist nicht nötig; Aspirin, Antikoagulanzien und andere gerinnungswirksame Medikamente sollten dem Arzt vorher mitgeteilt werden, über eine Pause entscheidet nur er', 'Özel bir hazırlık gerekmez; aspirin, antikoagülanlar ve pıhtılaşmayı etkileyen diğer ilaçlar önceden hekime bildirilir, ara verme kararını yalnızca hekim verir', 'Prolongation of either test may be related to platelet function, the state of the vessel wall, the effect of medication or the conditions of the test itself. These are screening tests, and if they deviate the doctor orders precise coagulation tests', 'Produženje bilo koje probe može biti povezano sa funkcijom trombocita, stanjem zida krvnog suda, uticajem lijekova ili uslovima same probe. Probe su orijentacione, a kod odstupanja ljekar upućuje na precizne testove koagulacije', 'Продужење било које пробе може бити повезано са функцијом тромбоцита, стањем зида крвног суда, утицајем лијекова или условима саме пробе. Пробе су оријентационе, а код одступања љекар упућује на прецизне тестове коагулације', 'Удлинение любой из проб может быть связано с работой тромбоцитов, состоянием сосудистой стенки, влиянием лекарств или условиями самой пробы. Пробы ориентировочные, и при отклонении врач назначает точные тесты свёртывания', 'Eine Verlängerung eines der beiden Tests kann mit der Funktion der Blutplättchen, dem Zustand der Gefäßwand, der Wirkung von Medikamenten oder den Testbedingungen zusammenhängen. Die Tests sind orientierend; bei Abweichungen ordnet der Arzt genaue Gerinnungstests an', 'Testlerden herhangi birinin uzaması trombositlerin işleviyle, damar duvarının durumuyla, ilaçların etkisiyle veya testin uygulanma koşullarıyla ilişkili olabilir. Bu testler yol göstericidir; sapma olduğunda hekim kesin pıhtılaşma testlerini ister')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'secondary-bleeding-time'), 'An additional measurement of the time until bleeding from a skin puncture stops, performed in addition to the main test; the exact method is specified by the laboratory itself', 'Dodatno određivanje vremena do prestanka krvarenja iz uboda kože, koje se radi uz osnovnu probu; tačnu metodu navodi sama laboratorija', 'Додатно одређивање времена до престанка крварења из убода коже, које се ради уз основну пробу; тачну методу наводи сама лабораторија', 'Дополнительное определение времени остановки кровотечения из прокола кожи, которое выполняют в дополнение к основной пробе; точную методику указывает сама лаборатория', 'Zusätzliche Bestimmung der Zeit bis zum Stillstand der Blutung aus einem Hautstich, ergänzend zur Hauptprobe; die genaue Methode gibt das Labor selbst an', 'Deri ponksiyonundan sonra kanamanın durma süresinin, ana teste ek olarak yapılan ikinci ölçümü; yöntemin ayrıntısını laboratuvarın kendisi belirtir', 'The test is carried out in the same way as the ordinary bleeding time: a small skin puncture and timing until the bleeding stops, taking a few minutes', 'Proba se izvodi isto kao i obično vrijeme krvarenja: mali ubod kože i mjerenje vremena do prestanka krvarenja, traje nekoliko minuta', 'Проба се изводи исто као и обично вријеме крварења: мали убод коже и мјерење времена до престанка крварења, траје неколико минута', 'Проба проводится так же, как обычное время кровотечения: небольшой прокол кожи и отсчёт времени до остановки, занимает несколько минут', 'Der Test läuft wie die übliche Blutungszeit ab: ein kleiner Hautstich und die Zeitmessung bis zum Ende der Blutung, wenige Minuten', 'Test, olağan kanama zamanı gibi yapılır: küçük bir deri ponksiyonu ve kanama durana kadar sürenin ölçülmesi, birkaç dakika sürer', 'Ordered by a doctor when the first result needs to be rechecked or supplemented, and as part of a work-up for bleeding tendency', 'Ljekar je traži kada prvi nalaz treba provjeriti ili dopuniti, kao i u sklopu ispitivanja sklonosti krvarenju', 'Љекар је тражи када први налаз треба провјерити или допунити, као и у склопу испитивања склоности крварењу', 'Назначается врачом, когда результат первой пробы нужно перепроверить или дополнить, а также в рамках обследования при склонности к кровоточивости', 'Auf ärztliche Anordnung, wenn der erste Wert überprüft oder ergänzt werden soll, sowie im Rahmen der Abklärung einer Blutungsneigung', 'İlk sonucun doğrulanması veya tamamlanması gerektiğinde hekim isteğiyle, ayrıca kanama eğiliminin araştırılması kapsamında', 'No special preparation is required; medicines affecting clotting should be reported in advance, and only the doctor decides whether to stop them', 'Posebna priprema nije potrebna; lijekove koji utiču na zgrušavanje treba prijaviti unaprijed, a odluku o njihovom prekidu donosi ljekar', 'Посебна припрема није потребна; лијекове који утичу на згрушавање треба пријавити унапријед, а одлуку о њиховом прекиду доноси љекар', 'Специальной подготовки не требуется; о лекарствах, влияющих на свёртывание, сообщают заранее, и решение об их отмене принимает врач', 'Eine besondere Vorbereitung ist nicht nötig; gerinnungswirksame Medikamente werden vorher mitgeteilt, über ein Absetzen entscheidet der Arzt', 'Özel bir hazırlık gerekmez; pıhtılaşmayı etkileyen ilaçlar önceden bildirilir, bırakılıp bırakılmayacağına hekim karar verir', 'A deviation may be related to platelet function, the state of the vessel wall, the effect of medication or the technique of the test. What the result means and whether more precise tests are needed is decided by the doctor', 'Odstupanje može biti povezano sa funkcijom trombocita, stanjem zida krvnog suda, uticajem lijekova ili tehnikom izvođenja probe. Šta nalaz znači i da li su potrebni precizniji testovi, odlučuje ljekar', 'Одступање може бити повезано са функцијом тромбоцита, стањем зида крвног суда, утицајем лијекова или техником извођења пробе. Шта налаз значи и да ли су потребни прецизнији тестови, одлучује љекар', 'Отклонение может быть связано с работой тромбоцитов, состоянием сосудистой стенки, влиянием препаратов или техникой выполнения пробы. Что означает результат и нужны ли более точные тесты, решает врач', 'Eine Abweichung kann mit der Funktion der Blutplättchen, dem Zustand der Gefäßwand, der Wirkung von Medikamenten oder der Durchführung zusammenhängen. Was der Wert bedeutet und ob genauere Tests nötig sind, entscheidet der Arzt', 'Sapma trombositlerin işleviyle, damar duvarının durumuyla, ilaç etkisiyle veya testin uygulanma tekniğiyle ilişkili olabilir. Sonucun ne anlama geldiğine ve daha kesin testlerin gerekip gerekmediğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'myoglobin'), 'Blood test for a muscle-cell protein that enters the blood when muscle tissue is damaged', 'Analiza krvi na bjelančevinu mišićnih ćelija koja dospijeva u krv pri oštećenju mišićnog tkiva', 'Анализа крви на бјеланчевину мишићних ћелија која доспијева у крв при оштећењу мишићног ткива', 'Анализ крови на белок мышечных клеток, который попадает в кровь при повреждении мышечной ткани', 'Bluttest auf ein Protein der Muskelzellen, das bei Schädigung von Muskelgewebe ins Blut gelangt', 'Kas dokusu zarar gördüğünde kana geçen kas hücresi proteinini ölçen kan testi', 'Venous blood draw, repeated if needed after an interval set by the doctor', 'Uzimanje venske krvi, po potrebi se ponavlja u razmaku koji određuje ljekar', 'Узимање венске крви, по потреби се понавља у размаку који одређује љекар', 'Забор венозной крови, при необходимости повторяется через интервал, который определяет врач', 'Venöse Blutentnahme, bei Bedarf Wiederholung nach einem vom Arzt festgelegten Abstand', 'Toplardamardan kan alınması, gerekirse hekimin belirlediği aralıkla tekrarlanır', 'Assessment of heart and skeletal muscle as ordered by a doctor, work-up after injury and prolonged muscle compression, monitoring in muscle disease, sometimes as an early value alongside troponin', 'Procjena stanja srčanog i skeletnog mišića po uputu ljekara, ispitivanje poslije povreda i dugotrajnog pritiska na mišiće, praćenje kod mišićnih oboljenja, ponekad kao rani pokazatelj uz troponin', 'Процјена стања срчаног и скелетног мишића по упуту љекара, испитивање послије повреда и дуготрајног притиска на мишиће, праћење код мишићних обољења, понекад као рани показатељ уз тропонин', 'Оценка состояния сердечной и скелетной мускулатуры по назначению врача, обследование после травм и длительного сдавления мышц, контроль при заболеваниях мышц, иногда — как ранний показатель вместе с тропонином', 'Beurteilung von Herz- und Skelettmuskulatur auf ärztliche Anordnung, Abklärung nach Verletzungen und längerer Muskelkompression, Verlaufskontrolle bei Muskelerkrankungen, teils als früher Wert neben dem Troponin', 'Hekim isteğiyle kalp ve iskelet kasının değerlendirilmesi, yaralanma ve uzun süreli kas basısı sonrası inceleme, kas hastalıklarında izlem, bazen troponinle birlikte erken gösterge olarak', 'No special preparation is required; intense physical exercise and intramuscular injections the day before are best avoided, as they raise the value', 'Posebna priprema nije potrebna; dan ranije poželjno je izbjegavati intenzivan fizički napor i injekcije u mišić, jer podižu vrijednost', 'Посебна припрема није потребна; дан раније пожељно је избјегавати интензиван физички напор и ињекције у мишић, јер подижу вриједност', 'Специальной подготовки не требуется; накануне желательно избегать интенсивных физических нагрузок и внутримышечных инъекций, они повышают показатель', 'Eine besondere Vorbereitung ist nicht nötig; starke körperliche Belastung und intramuskuläre Spritzen am Vortag sollten vermieden werden, da sie den Wert erhöhen', 'Özel bir hazırlık gerekmez; değeri yükselttiği için bir gün önce yoğun fiziksel aktiviteden ve kas içi iğnelerden kaçınmak uygundur', 'An increase may be related to damage of heart or skeletal muscle, intense exertion, injury, cramps, intramuscular injections or reduced kidney function, since the kidneys clear this protein. The result is assessed by a doctor together with troponin and the clinical picture', 'Povećanje može biti povezano sa oštećenjem srčanog ili skeletnog mišića, intenzivnim naporom, povredom, grčevima, injekcijama u mišić ili smanjenom funkcijom bubrega, koji izlučuju ovu bjelančevinu. Nalaz procjenjuje ljekar zajedno sa troponinom i kliničkom slikom', 'Повећање може бити повезано са оштећењем срчаног или скелетног мишића, интензивним напором, повредом, грчевима, ињекцијама у мишић или смањеном функцијом бубрега, који излучују ову бјеланчевину. Налаз процјењује љекар заједно са тропонином и клиничком сликом', 'Повышение может быть связано с повреждением сердечной или скелетной мышцы, интенсивной нагрузкой, травмой, судорогами, инъекциями в мышцу или сниженной функцией почек, которые выводят этот белок. Результат оценивает врач вместе с тропонином и клинической картиной', 'Ein Anstieg kann mit einer Schädigung der Herz- oder Skelettmuskulatur, starker Belastung, Verletzung, Krämpfen, Spritzen in den Muskel oder einer eingeschränkten Nierenfunktion zusammenhängen, da die Nieren dieses Protein ausscheiden. Der Arzt beurteilt den Wert zusammen mit dem Troponin und dem klinischen Bild', 'Yükselme kalp veya iskelet kasının zarar görmesiyle, yoğun eforla, yaralanmayla, kramplarla, kas içi enjeksiyonlarla ya da bu proteini atan böbreklerin işlevinin azalmasıyla ilişkili olabilir. Sonucu hekim troponin ve klinik tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'troponin-i'), 'Blood test for one of the protein subunits of the contractile apparatus of the heart muscle', 'Analiza krvi na jednu od bjelančevinskih podjedinica kontraktilnog aparata srčanog mišića', 'Анализа крви на једну од бјеланчевинских подјединица контрактилног апарата срчаног мишића', 'Анализ крови на одну из белковых субъединиц сократительного аппарата сердечной мышцы', 'Bluttest auf eine der Eiweiß-Untereinheiten des Kontraktionsapparats des Herzmuskels', 'Kalp kasının kasılma yapısında yer alan protein alt birimlerinden birini ölçen kan testi', 'Venous blood draw; in urgent settings the test is often repeated after a few hours at the doctor''s decision', 'Uzimanje venske krvi; u hitnim situacijama analiza se često ponavlja poslije nekoliko sati, po odluci ljekara', 'Узимање венске крви; у хитним ситуацијама анализа се често понавља послије неколико сати, по одлуци љекара', 'Забор венозной крови; при неотложной оценке анализ нередко повторяют через несколько часов по решению врача', 'Venöse Blutentnahme; in der Notfallsituation wird der Test nach einigen Stunden häufig wiederholt, nach Entscheidung des Arztes', 'Toplardamardan kan alınması; acil durumlarda hekimin kararıyla birkaç saat sonra tekrarlanır', 'Ordered by a doctor when an acute cardiac condition is suspected, with chest pain, shortness of breath, after prolonged arrhythmia, and for monitoring in known heart disease', 'Po uputu ljekara pri sumnji na akutno stanje srca, kod bola u grudima, gušenja, poslije dugotrajne aritmije, kao i za praćenje kod poznatih srčanih oboljenja', 'По упуту љекара при сумњи на акутно стање срца, код бола у грудима, гушења, послије дуготрајне аритмије, као и за праћење код познатих срчаних обољења', 'Назначается врачом при подозрении на острое состояние со стороны сердца, при боли в груди, одышке, после длительной аритмии, а также для наблюдения при известных заболеваниях сердца', 'Auf ärztliche Anordnung bei Verdacht auf ein akutes Herzereignis, bei Brustschmerz, Luftnot, nach länger anhaltender Rhythmusstörung sowie zur Verlaufskontrolle bei bekannter Herzerkrankung', 'Akut kalp sorunundan şüphelenildiğinde hekim isteğiyle, göğüs ağrısı, nefes darlığı, uzun süren ritim bozukluğu sonrası, ayrıca bilinen kalp hastalıklarında izlem için', 'No preparation is required and the test is often performed urgently; for a planned test, recent intense exercise should be mentioned to the doctor', 'Priprema nije potrebna, analiza se često radi hitno; kod planiranog vađenja krvi treba javiti ljekaru skorašnji intenzivan napor', 'Припрема није потребна, анализа се често ради хитно; код планираног вађења крви треба јавити љекару скорашњи интензиван напор', 'Подготовки не требуется, анализ часто выполняется срочно; при плановой сдаче о недавней интенсивной нагрузке стоит сказать врачу', 'Eine Vorbereitung ist nicht nötig, der Test wird oft notfallmäßig durchgeführt; bei geplanter Entnahme sollte kürzliche starke körperliche Belastung dem Arzt mitgeteilt werden', 'Hazırlık gerekmez, test çoğu zaman acil olarak yapılır; planlı kan alımında yakın zamandaki yoğun efor hekime söylenmelidir', 'An increase may be related to damage of the heart muscle, and also to inflammation of the heart, severe arrhythmia, reduced kidney function, thromboembolism and other serious conditions. The result must be assessed by a doctor together with the ECG and the symptoms, and immediately in case of acute complaints', 'Povećanje može biti povezano sa oštećenjem srčanog mišića, ali i sa upalom srca, teškom aritmijom, smanjenom funkcijom bubrega, tromboembolijom i drugim teškim stanjima. Nalaz mora procijeniti ljekar zajedno sa EKG-om i simptomima, a kod akutnih tegoba odmah', 'Повећање може бити повезано са оштећењем срчаног мишића, али и са упалом срца, тешком аритмијом, смањеном функцијом бубрега, тромбоемболијом и другим тешким стањима. Налаз мора процијенити љекар заједно са ЕКГ-ом и симптомима, а код акутних тегоба одмах', 'Повышение может быть связано с повреждением сердечной мышцы, а также с воспалением сердца, тяжёлой аритмией, сниженной функцией почек, тромбоэмболией и другими тяжёлыми состояниями. Результат требует оценки врача вместе с ЭКГ и симптомами, при острых жалобах — немедленно', 'Ein Anstieg kann mit einer Schädigung des Herzmuskels zusammenhängen, ebenso mit einer Herzentzündung, schweren Rhythmusstörungen, eingeschränkter Nierenfunktion, Thromboembolie und anderen schweren Zuständen. Der Wert muss vom Arzt zusammen mit EKG und Beschwerden beurteilt werden, bei akuten Beschwerden sofort', 'Yükselme kalp kasının zarar görmesiyle, ayrıca kalp iltihabı, ağır ritim bozukluğu, böbrek işlevinin azalması, tromboemboli ve diğer ağır durumlarla ilişkili olabilir. Sonuç, EKG ve yakınmalarla birlikte hekim tarafından, akut şikayet varsa hemen değerlendirilmelidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'troponin-t-and-i-combined'), 'Simultaneous determination of both cardiac troponins — T and I — in a single blood sample', 'Istovremeno određivanje oba srčana troponina — T i I — iz jednog uzorka krvi', 'Истовремено одређивање оба срчана тропонина — Т и И — из једног узорка крви', 'Одновременное определение обоих сердечных тропонинов — T и I — в одной пробе крови', 'Gleichzeitige Bestimmung beider Herztroponine — T und I — aus einer Blutprobe', 'Her iki kalp troponininin — T ve I — tek bir kan örneğinde birlikte ölçülmesi', 'Venous blood or a drop of blood from a fingertip in the rapid version; both subunits are read on one test panel', 'Uzima se venska krv ili kap krvi iz prsta kod brzog testa, obje podjedinice očitavaju se na istoj test-ploči', 'Узима се венска крв или кап крви из прста код брзог теста, обје подјединице очитавају се на истој тест-плочи', 'Забор венозной крови или капли крови из пальца при экспресс-исполнении, обе субъединицы определяются на одной тест-панели', 'Venöses Blut oder beim Schnelltest ein Blutstropfen aus der Fingerbeere; beide Untereinheiten werden auf einem Testfeld abgelesen', 'Toplardamardan kan ya da hızlı testte parmak ucundan bir damla kan alınır, iki alt birim aynı test kartında okunur', 'First assessment when an acute cardiac condition is suspected and a quick answer is needed, and repeat sampling at the doctor''s decision to follow the trend', 'Prva procjena pri sumnji na akutno srčano stanje kada je potreban brz odgovor, kao i ponovljeni uzorak po odluci ljekara radi praćenja kretanja nalaza', 'Прва процјена при сумњи на акутно срчано стање када је потребан брз одговор, као и поновљени узорак по одлуци љекара ради праћења кретања налаза', 'Первичная оценка при подозрении на острое состояние со стороны сердца там, где нужен быстрый ответ, и повторная проба по решению врача для оценки динамики', 'Erste Einschätzung bei Verdacht auf ein akutes Herzereignis, wenn eine schnelle Antwort nötig ist, sowie Wiederholung nach Entscheidung des Arztes zur Verlaufsbeurteilung', 'Hızlı yanıt gereken durumlarda akut kalp sorunu şüphesinde ilk değerlendirme, ayrıca seyri izlemek için hekim kararıyla tekrar örnek alınması', 'No preparation is required; the test is performed on urgent indications at any time of day', 'Priprema nije potrebna; analiza se radi po hitnim indikacijama u bilo koje doba dana', 'Припрема није потребна; анализа се ради по хитним индикацијама у било које доба дана', 'Подготовка не требуется; анализ выполняется по срочным показаниям в любое время суток', 'Eine Vorbereitung ist nicht nötig; der Test wird bei dringender Indikation zu jeder Tageszeit durchgeführt', 'Hazırlık gerekmez; test acil endikasyonla günün her saatinde yapılabilir', 'A positive or raised result means that urgent medical assessment is needed: it occurs with damage of the heart muscle, but also with inflammation of the heart, arrhythmias, kidney and lung disease. The decision is made by a doctor from the ECG, the symptoms and a repeat test', 'Pozitivan ili povišen nalaz znači da je potrebna hitna ljekarska procjena: javlja se kod oštećenja srčanog mišića, ali i kod upale srca, aritmija, bolesti bubrega i pluća. Odluku donosi ljekar na osnovu EKG-a, simptoma i ponovljene analize', 'Позитиван или повишен налаз значи да је потребна хитна љекарска процјена: јавља се код оштећења срчаног мишића, али и код упале срца, аритмија, болести бубрега и плућа. Одлуку доноси љекар на основу ЕКГ-а, симптома и поновљене анализе', 'Положительный или повышенный результат означает, что нужна срочная врачебная оценка: он встречается при повреждении сердечной мышцы, но также при воспалении сердца, аритмиях, болезнях почек и лёгких. Решение принимает врач по ЭКГ, симптомам и повторному анализу', 'Ein positiver oder erhöhter Wert bedeutet, dass eine dringende ärztliche Beurteilung nötig ist: er kommt bei Schädigung des Herzmuskels vor, ebenso bei Herzentzündung, Rhythmusstörungen, Nieren- und Lungenerkrankungen. Die Entscheidung trifft der Arzt anhand von EKG, Beschwerden und Kontrollmessung', 'Pozitif veya yüksek sonuç acil hekim değerlendirmesi gerektiğini gösterir: kalp kasının zarar görmesinde olduğu gibi kalp iltihabı, ritim bozuklukları, böbrek ve akciğer hastalıklarında da görülür. Kararı hekim EKG, yakınmalar ve tekrar ölçümle verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'csf-cytological-analysis'), 'Counting and describing the cells in cerebrospinal fluid under a microscope', 'Brojanje i opisivanje ćelija u likvoru pod mikroskopom', 'Бројање и описивање ћелија у ликвору под микроскопом', 'Подсчёт и описание клеток в спинномозговой жидкости под микроскопом', 'Zählung und Beschreibung der Zellen im Nervenwasser unter dem Mikroskop', 'Beyin omurilik sıvısındaki hücrelerin mikroskopta sayılması ve tanımlanması', 'The fluid is obtained by a doctor during a lumbar puncture under local anaesthesia; in the laboratory the cells are counted in a chamber and examined in a stained preparation', 'Likvor uzima ljekar tokom lumbalne punkcije u lokalnoj anesteziji; u laboratoriji se ćelije broje u komorici i pregledaju u obojenom preparatu', 'Ликвор узима љекар током лумбалне пункције у локалној анестезији; у лабораторији се ћелије броје у коморици и прегледају у обојеном препарату', 'Ликвор берёт врач при люмбальной пункции под местным обезболиванием; в лаборатории клетки считают в камере и рассматривают их вид в окрашенном препарате', 'Der Liquor wird vom Arzt bei einer Lumbalpunktion in örtlicher Betäubung gewonnen; im Labor werden die Zellen in einer Kammer gezählt und im gefärbten Präparat betrachtet', 'Sıvı, hekim tarafından lokal anestezi altında lomber ponksiyonla alınır; laboratuvarda hücreler sayım kamarasında sayılır ve boyalı preparatta incelenir', 'Suspected inflammation of the meninges, unclear neurological symptoms and disturbances of consciousness, monitoring in diseases of the nervous system, examination of the fluid as ordered by a neurologist', 'Sumnja na upalu moždanih ovojnica, nejasni neurološki simptomi i poremećaji svijesti, praćenje kod oboljenja nervnog sistema, pregled likvora po uputu neurologa', 'Сумња на упалу можданих овојница, нејасни неуролошки симптоми и поремећаји свијести, праћење код обољења нервног система, преглед ликвора по упуту неуролога', 'Подозрение на воспаление оболочек мозга, неясные неврологические симптомы и нарушения сознания, наблюдение при заболеваниях нервной системы, исследование ликвора по назначению невролога', 'Verdacht auf eine Entzündung der Hirnhäute, unklare neurologische Symptome und Bewusstseinsstörungen, Verlaufskontrolle bei Erkrankungen des Nervensystems, Liquoruntersuchung auf Anordnung des Neurologen', 'Beyin zarlarının iltihabı şüphesi, açıklanamayan nörolojik belirtiler ve bilinç bozuklukları, sinir sistemi hastalıklarında izlem, nörolog isteğiyle sıvının incelenmesi', 'The patient needs no preparation for the laboratory part, as the material is obtained during the puncture; the rules for the puncture itself, the consent and lying down afterwards are explained by the doctor', 'Pacijent se za laboratorijski dio ne priprema, materijal se dobija tokom punkcije; pravila same punkcije, saglasnost i ležanje poslije nje objašnjava ljekar', 'Пацијент се за лабораторијски дио не припрема, материјал се добија током пункције; правила саме пункције, сагласност и лежање послије ње објашњава љекар', 'Со стороны пациента подготовки к лабораторной части нет, материал получают во время пункции; правила самой пункции, согласие и отдых лёжа после неё объясняет врач', 'Für den Laborteil ist keine Vorbereitung nötig, das Material wird bei der Punktion gewonnen; die Regeln der Punktion selbst, die Einwilligung und das Liegen danach erklärt der Arzt', 'Laboratuvar aşaması için hastanın hazırlığı gerekmez, materyal ponksiyon sırasında alınır; ponksiyonun kuralları, onam ve sonrasında yatarak dinlenme hekim tarafından anlatılır', 'An increased cell count and a changed cell composition may be related to an inflammatory or infectious process, a reaction to bleeding, or blood contaminating the sample during collection. The report on the slide is issued by a laboratory doctor or pathologist, and treatment is decided by the treating physician', 'Povećan broj ćelija i izmijenjen sastav mogu biti povezani sa upalnim ili infektivnim procesom, reakcijom na krvarenje ili primjesom krvi pri uzimanju uzorka. Nalaz preparata daje ljekar u laboratoriji ili patolog, a terapiju određuje ljekar koji vodi pacijenta', 'Повећан број ћелија и измијењен састав могу бити повезани са упалним или инфективним процесом, реакцијом на крварење или примјесом крви при узимању узорка. Налаз препарата даје љекар у лабораторији или патолог, а терапију одређује љекар који води пацијента', 'Увеличение числа клеток и изменение их состава могут быть связаны с воспалительным или инфекционным процессом, реакцией на кровоизлияние либо с примесью крови при заборе. Заключение по препарату даёт врач лаборатории или патолог, а лечебную тактику определяет лечащий врач', 'Eine erhöhte Zellzahl und eine veränderte Zusammensetzung können mit einem entzündlichen oder infektiösen Prozess, einer Reaktion auf eine Blutung oder mit Blutbeimengung bei der Entnahme zusammenhängen. Den Befund erstellt der Laborarzt oder Pathologe, die Behandlung legt der behandelnde Arzt fest', 'Hücre sayısının artması ve hücre bileşiminin değişmesi iltihabi veya enfeksiyöz bir süreçle, kanamaya verilen yanıtla ya da örnek alınırken kan bulaşmasıyla ilişkili olabilir. Preparat raporunu laboratuvar hekimi veya patolog verir, tedaviyi ise hastayı izleyen hekim belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'direct-coombs-test'), 'A test that detects antibodies and complement proteins already attached to the surface of the patient''s own red blood cells', 'Proba koja otkriva antitijela i proteine komplementa već vezane za površinu sopstvenih crvenih krvnih zrnaca', 'Проба која открива антитијела и протеине комплемента већ везане за површину сопствених црвених крвних зрнаца', 'Проба, выявляющая антитела и белки комплемента, уже прикреплённые к поверхности собственных эритроцитов', 'Test, der Antikörper und Komplementproteine nachweist, die bereits an der Oberfläche der eigenen roten Blutkörperchen haften', 'Kişinin kendi alyuvarlarının yüzeyine çoktan bağlanmış antikorları ve kompleman proteinlerini saptayan test', 'Venous blood draw; the red cells are washed and antiglobulin serum is added, and the result is read from the clumping of the cells', 'Uzimanje venske krvi; eritrociti se isperu i doda se antiglobulinski serum, a nalaz se očitava po slijepljivanju ćelija', 'Узимање венске крви; еритроцити се исперу и дода се антиглобулински серум, а налаз се очитава по слијепљивању ћелија', 'Забор венозной крови; эритроциты отмывают и добавляют антиглобулиновую сыворотку, результат оценивают по склеиванию клеток', 'Venöse Blutentnahme; die roten Blutkörperchen werden gewaschen, Antihumanglobulin wird zugegeben und das Ergebnis an der Verklumpung der Zellen abgelesen', 'Toplardamardan kan alınır; alyuvarlar yıkanıp antiglobulin serumu eklenir, sonuç hücrelerin kümelenmesine bakılarak okunur', 'Work-up for signs of red-cell breakdown and anaemia of unclear origin, jaundice in a newborn, assessment after a blood transfusion, monitoring during treatment with drugs that can affect red cells', 'Ispitivanje kod znakova razgradnje eritrocita i anemije nejasnog porijekla, žutica kod novorođenčeta, procjena poslije transfuzije, praćenje tokom terapije lijekovima koji mogu djelovati na eritrocite', 'Испитивање код знакова разградње еритроцита и анемије нејасног поријекла, жутица код новорођенчета, процјена послије трансфузије, праћење током терапије лијековима који могу дјеловати на еритроците', 'Обследование при признаках разрушения эритроцитов и анемии неясного происхождения, желтуха у новорождённого, оценка после переливания крови, контроль на фоне приёма препаратов, способных влиять на эритроциты', 'Abklärung bei Zeichen eines Abbaus roter Blutkörperchen und Blutarmut unklarer Ursache, Neugeborenengelbsucht, Beurteilung nach einer Bluttransfusion, Kontrolle unter Medikamenten, die rote Blutkörperchen beeinflussen können', 'Alyuvar yıkımı belirtileri ve nedeni belirsiz kansızlıkta inceleme, yenidoğan sarılığı, kan nakli sonrası değerlendirme, alyuvarları etkileyebilen ilaçlar kullanılırken izlem', 'No special preparation is required; in newborns the sample is taken from the heel or cord blood is used', 'Posebna priprema nije potrebna; kod novorođenčadi krv se uzima iz pete ili se koristi krv iz pupčane vrpce', 'Посебна припрема није потребна; код новорођенчади крв се узима из пете или се користи крв из пупчане врпце', 'Специальной подготовки не требуется; у новорождённых кровь берут из пятки или используют пуповинную кровь', 'Eine besondere Vorbereitung ist nicht nötig; bei Neugeborenen wird die Probe aus der Ferse gewonnen oder Nabelschnurblut verwendet', 'Özel bir hazırlık gerekmez; yenidoğanlarda örnek topuktan alınır ya da kordon kanı kullanılır', 'A positive result may be related to an autoimmune process, incompatibility between the blood of mother and child, a reaction to transfused blood or the effect of medicines, and it is sometimes found without any signs of disease. What the result means is determined by the doctor from the blood picture and the patient''s condition', 'Pozitivan nalaz može biti povezan sa autoimunim procesom, nepodudarnošću krvi majke i djeteta, reakcijom na primljenu krv ili djelovanjem lijekova, a ponekad se nađe i bez znakova bolesti. Značenje nalaza određuje ljekar prema krvnoj slici i stanju pacijenta', 'Позитиван налаз може бити повезан са аутоимуним процесом, неподударношћу крви мајке и дјетета, реакцијом на примљену крв или дјеловањем лијекова, а понекад се нађе и без знакова болести. Значење налаза одређује љекар према крвној слици и стању пацијента', 'Положительный результат может быть связан с аутоиммунным процессом, несовместимостью крови матери и ребёнка, реакцией на перелитую кровь или влиянием лекарств, а иногда встречается и без признаков болезни. Значение результата определяет врач по картине крови и состоянию пациента', 'Ein positives Ergebnis kann mit einem autoimmunen Prozess, einer Unverträglichkeit zwischen dem Blut von Mutter und Kind, einer Reaktion auf übertragenes Blut oder mit Medikamenten zusammenhängen und kommt mitunter auch ohne Krankheitszeichen vor. Was der Befund bedeutet, entscheidet der Arzt anhand von Blutbild und Zustand des Patienten', 'Pozitif sonuç otoimmün bir süreçle, anne ile bebeğin kanı arasındaki uyuşmazlıkla, nakledilen kana verilen yanıtla veya ilaçların etkisiyle ilişkili olabilir, bazen hastalık belirtisi olmadan da bulunur. Sonucun anlamını hekim kan tablosuna ve hastanın durumuna göre belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'indirect-coombs-test'), 'A test for free antibodies against red blood cells circulating in the blood serum', 'Proba na slobodna antitijela protiv eritrocita koja kruže u serumu', 'Проба на слободна антитијела против еритроцита која круже у серуму', 'Проба на свободные антитела к эритроцитам, которые циркулируют в сыворотке крови', 'Test auf freie Antikörper gegen rote Blutkörperchen, die im Blutserum zirkulieren', 'Kan serumunda dolaşan, alyuvarlara karşı serbest antikorları arayan test', 'Venous blood draw; the serum is mixed with red cells of a known group and antiglobulin serum is added', 'Uzimanje venske krvi; serum se miješa sa eritrocitima poznate grupe i dodaje se antiglobulinski serum', 'Узимање венске крви; серум се мијеша са еритроцитима познате групе и додаје се антиглобулински серум', 'Забор венозной крови; сыворотку смешивают с эритроцитами известной группы и добавляют антиглобулиновую сыворотку', 'Venöse Blutentnahme; das Serum wird mit roten Blutkörperchen bekannter Gruppe gemischt und Antihumanglobulin zugegeben', 'Toplardamardan kan alınır; serum, grubu bilinen alyuvarlarla karıştırılır ve antiglobulin serumu eklenir', 'Antibody screening in pregnancy, especially with Rh-negative blood in the mother, selection and compatibility check before a transfusion, testing before and after anti-D immunoglobulin as ordered by a doctor', 'Skrining antitijela u trudnoći, posebno kod Rh negativne krvne grupe majke, odabir i provjera podudarnosti prije transfuzije, ispitivanje prije i poslije davanja anti-D imunoglobulina po uputu ljekara', 'Скрининг антитијела у трудноћи, посебно код Rh негативне крвне групе мајке, одабир и провјера подударности прије трансфузије, испитивање прије и послије давања анти-Д имуноглобулина по упуту љекара', 'Скрининг антител при беременности, особенно при резус-отрицательной крови у женщины, подбор и проверка совместимости перед переливанием крови, обследование до и после введения антирезусного иммуноглобулина по назначению врача', 'Antikörpersuchtest in der Schwangerschaft, besonders bei Rh-negativer Mutter, Auswahl und Verträglichkeitsprüfung vor einer Transfusion, Untersuchung vor und nach Gabe von Anti-D-Immunglobulin auf ärztliche Anordnung', 'Gebelikte antikor taraması, özellikle annenin kan grubu Rh negatifse, kan nakli öncesi uygunluk seçimi ve kontrolü, hekim isteğiyle anti-D immünoglobulin öncesi ve sonrası inceleme', 'No special preparation is required; in pregnancy it is important to state the gestational age and whether anti-D immunoglobulin has been given', 'Posebna priprema nije potrebna; u trudnoći je važno navesti gestacijsku starost i da li je primljen anti-D imunoglobulin', 'Посебна припрема није потребна; у трудноћи је важно навести гестацијску старост и да ли је примљен анти-Д имуноглобулин', 'Специальной подготовки не требуется; при беременности важно назвать срок и указать, вводился ли антирезусный иммуноглобулин', 'Eine besondere Vorbereitung ist nicht nötig; in der Schwangerschaft sollten die Schwangerschaftswoche und eine erfolgte Anti-D-Gabe angegeben werden', 'Özel bir hazırlık gerekmez; gebelikte gebelik haftasının ve anti-D immünoglobulin yapılıp yapılmadığının belirtilmesi önemlidir', 'Detected antibodies may be related to previous pregnancies, earlier transfusions or an administered immunoglobulin preparation, and call for further clarifying tests. The doctor decides on further monitoring', 'Nađena antitijela mogu biti povezana sa ranijim trudnoćama, ranijim transfuzijama ili primljenim imunoglobulinom i traže dodatna ispitivanja. Dalji tok praćenja određuje ljekar', 'Нађена антитијела могу бити повезана са ранијим трудноћама, ранијим трансфузијама или примљеним имуноглобулином и траже додатна испитивања. Даљи ток праћења одређује љекар', 'Выявление антител может быть связано с предыдущими беременностями, перенесёнными переливаниями крови или введённым препаратом иммуноглобулина и требует уточняющих исследований. Дальнейшую тактику наблюдения определяет врач', 'Nachgewiesene Antikörper können mit früheren Schwangerschaften, früheren Transfusionen oder einem verabreichten Immunglobulinpräparat zusammenhängen und erfordern weitere Abklärung. Das weitere Vorgehen legt der Arzt fest', 'Saptanan antikorlar önceki gebeliklerle, daha önce yapılmış kan nakilleriyle veya uygulanan immünoglobulin ile ilişkili olabilir ve ek incelemeler gerektirir. İzlemin nasıl süreceğine hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'copper-in-serum'), 'Determination of copper, a trace element involved in enzyme function, blood formation and iron metabolism', 'Određivanje bakra, mikroelementa koji učestvuje u radu enzima, stvaranju krvi i prometu gvožđa', 'Одређивање бакра, микроелемента који учествује у раду ензима, стварању крви и промету гвожђа', 'Определение содержания меди — микроэлемента, участвующего в работе ферментов, кроветворении и обмене железа', 'Bestimmung von Kupfer, einem Spurenelement, das an der Enzymfunktion, der Blutbildung und dem Eisenstoffwechsel beteiligt ist', 'Enzimlerin çalışmasında, kan yapımında ve demir metabolizmasında görev alan eser element bakırın ölçülmesi', 'Venous blood is drawn into a tube free of trace-element contamination, takes a few minutes', 'Uzimanje venske krvi u epruvetu bez primjesa mikroelemenata, traje nekoliko minuta', 'Узимање венске крви у епрувету без примјеса микроелемената, траје неколико минута', 'Забор венозной крови в пробирку без микроэлементных примесей, занимает несколько минут', 'Venöse Blutentnahme in ein Röhrchen ohne Spurenelement-Verunreinigungen, dauert wenige Minuten', 'Eser element bulaşı olmayan tüpe toplardamardan kan alınır, birkaç dakika sürer', 'Work-up for suspected disturbance of copper metabolism, unclear neurological and liver complaints together with caeruloplasmin, monitoring during long-term parenteral nutrition and malabsorption, follow-up as ordered by a doctor', 'Ispitivanje pri sumnji na poremećaj prometa bakra, nejasne neurološke i jetrene tegobe zajedno sa ceruloplazminom, praćenje kod dugotrajne parenteralne ishrane i poremećaja apsorpcije, kontrola po uputu ljekara', 'Испитивање при сумњи на поремећај промета бакра, нејасне неуролошке и јетрене тегобе заједно са церулоплазмином, праћење код дуготрајне парентералне исхране и поремећаја апсорпције, контрола по упуту љекара', 'Обследование при подозрении на нарушение обмена меди, неясные неврологические и печёночные жалобы вместе с церулоплазмином, контроль при длительном парентеральном питании и нарушениях всасывания, наблюдение по назначению врача', 'Abklärung bei Verdacht auf eine Störung des Kupferstoffwechsels, unklare neurologische und Leberbeschwerden zusammen mit Coeruloplasmin, Kontrolle bei langer parenteraler Ernährung und Resorptionsstörungen, Verlaufskontrolle auf ärztliche Anordnung', 'Bakır metabolizması bozukluğu şüphesinde inceleme, seruloplazminle birlikte açıklanamayan nörolojik ve karaciğer şikayetleri, uzun süreli damardan beslenme ve emilim bozukluklarında izlem, hekim isteğiyle kontrol', 'Usually taken in the morning, preferably fasting; vitamin and mineral supplements and oestrogens should be reported to the laboratory, as they change the result', 'Obično se uzima ujutru, poželjno natašte; laboratoriji treba javiti vitaminsko-mineralne dodatke i estrogene, jer mijenjaju nalaz', 'Обично се узима ујутру, пожељно наташте; лабораторији треба јавити витаминско-минералне додатке и естрогене, јер мијењају налаз', 'Обычно сдают утром, желательно натощак; о приёме витаминно-минеральных добавок и эстрогенов сообщают лаборатории, так как они меняют результат', 'Die Entnahme erfolgt meist morgens, möglichst nüchtern; Vitamin- und Mineralstoffpräparate sowie Östrogene sollten dem Labor mitgeteilt werden, da sie den Wert verändern', 'Genellikle sabah, tercihen aç karnına alınır; vitamin-mineral takviyeleri ve östrojenler sonucu değiştirdiği için laboratuvara bildirilir', 'Deviations may be related to inherited disorders of copper metabolism, the condition of the liver, inflammation, pregnancy and hormonal medication, as well as to diet and absorption. The value does not stand alone: the doctor assesses it together with caeruloplasmin and other tests', 'Odstupanja mogu biti povezana sa nasljednim poremećajima prometa bakra, stanjem jetre, upalom, trudnoćom i hormonskom terapijom, kao i sa ishranom i apsorpcijom. Pokazatelj nije samostalan: ljekar ga procjenjuje uz ceruloplazmin i druge analize', 'Одступања могу бити повезана са насљедним поремећајима промета бакра, стањем јетре, упалом, трудноћом и хормонском терапијом, као и са исхраном и апсорпцијом. Показатељ није самосталан: љекар га процјењује уз церулоплазмин и друге анализе', 'Отклонения могут быть связаны с наследственными нарушениями обмена меди, состоянием печени, воспалением, беременностью и приёмом гормональных препаратов, а также с питанием и всасыванием. Один показатель не самостоятелен: врач оценивает его вместе с церулоплазмином и другими анализами', 'Abweichungen können mit erblichen Störungen des Kupferstoffwechsels, dem Zustand der Leber, Entzündungen, einer Schwangerschaft und Hormonpräparaten sowie mit Ernährung und Aufnahme zusammenhängen. Der Wert steht nicht für sich: der Arzt beurteilt ihn zusammen mit Coeruloplasmin und weiteren Untersuchungen', 'Sapmalar bakır metabolizmasının kalıtsal bozukluklarıyla, karaciğerin durumuyla, iltihapla, gebelikle ve hormon ilaçlarıyla, ayrıca beslenme ve emilimle ilişkili olabilir. Değer tek başına yeterli değildir: hekim onu seruloplazmin ve diğer tetkiklerle birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'zinc-in-serum'), 'Determination of zinc, a trace element needed for enzyme function, immune defence and tissue healing', 'Određivanje cinka, mikroelementa potrebnog za rad enzima, odbrambeni sistem i zarastanje tkiva', 'Одређивање цинка, микроелемента потребног за рад ензима, одбрамбени систем и зарастање ткива', 'Определение содержания цинка — микроэлемента, нужного для работы ферментов, иммунной защиты и заживления тканей', 'Bestimmung von Zink, einem Spurenelement für Enzymfunktion, Immunabwehr und Gewebeheilung', 'Enzimlerin çalışması, bağışıklık ve doku iyileşmesi için gerekli eser element çinkonun ölçülmesi', 'Venous blood is drawn into a special metal-free tube; haemolysis of the sample must be avoided', 'Uzimanje venske krvi u posebnu epruvetu bez tragova metala; treba izbjeći hemolizu uzorka', 'Узимање венске крви у посебну епрувету без трагова метала; треба избјећи хемолизу узорка', 'Забор венозной крови в специальную пробирку без следов металлов; важно избежать гемолиза пробы', 'Venöse Blutentnahme in ein spezielles metallfreies Röhrchen; eine Hämolyse der Probe ist zu vermeiden', 'Metal içermeyen özel bir tüpe toplardamardan kan alınır; örnekte hemolizden kaçınmak gerekir', 'Long-standing absorption problems and restrictive diets, chronic bowel disease, slow-healing wounds and skin rashes, monitoring during parenteral nutrition as ordered by a doctor', 'Dugotrajni poremećaji apsorpcije i restriktivne dijete, hronične bolesti crijeva, rane koje sporo zarastaju i promjene na koži, praćenje tokom parenteralne ishrane po uputu ljekara', 'Дуготрајни поремећаји апсорпције и рестриктивне дијете, хроничне болести цријева, ране које споро зарастају и промјене на кожи, праћење током парентералне исхране по упуту љекара', 'Длительные нарушения всасывания и диеты с ограничениями, хронические заболевания кишечника, долго не заживающие раны и кожные высыпания, наблюдение при парентеральном питании по назначению врача', 'Länger bestehende Aufnahmestörungen und stark eingeschränkte Ernährung, chronische Darmerkrankungen, schlecht heilende Wunden und Hautausschläge, Kontrolle bei parenteraler Ernährung auf ärztliche Anordnung', 'Uzun süren emilim sorunları ve kısıtlı beslenme, kronik bağırsak hastalıkları, geç iyileşen yaralar ve ciltteki döküntüler, hekim isteğiyle damardan beslenme sırasında izlem', 'Blood is usually taken in the morning on an empty stomach; zinc supplements are stopped only in agreement with the doctor and should be reported to the laboratory', 'Krv se obično uzima ujutru natašte; dodaci sa cinkom prekidaju se samo u dogovoru sa ljekarom i prijavljuju se laboratoriji', 'Крв се обично узима ујутру наташте; додаци са цинком прекидају се само у договору са љекаром и пријављују се лабораторији', 'Кровь обычно сдают утром натощак; приём добавок с цинком прекращают только по согласованию с врачом и сообщают о них лаборатории', 'Die Blutentnahme erfolgt meist morgens nüchtern; Zinkpräparate werden nur in Absprache mit dem Arzt pausiert und dem Labor mitgeteilt', 'Kan genellikle sabah aç karnına alınır; çinko takviyeleri yalnızca hekimle görüşerek bırakılır ve laboratuvara bildirilir', 'A low value may be related to diet, impaired absorption, protein loss, acute inflammation or pregnancy, while an unsuitable tube and cell damage in the sample produce artificially low or high results. The doctor assesses the result together with blood proteins and the overall picture', 'Snižena vrijednost može biti povezana sa ishranom, poremećajem apsorpcije, gubitkom bjelančevina, akutnom upalom ili trudnoćom, dok neodgovarajuća epruveta i oštećenje ćelija u uzorku daju lažno nizak ili visok nalaz. Nalaz procjenjuje ljekar uz bjelančevine krvi i cjelokupnu sliku', 'Снижена вриједност може бити повезана са исхраном, поремећајем апсорпције, губитком бјеланчевина, акутном упалом или трудноћом, док неодговарајућа епрувета и оштећење ћелија у узорку дају лажно низак или висок налаз. Налаз процјењује љекар уз бјеланчевине крви и цјелокупну слику', 'Снижение может быть связано с питанием, нарушением всасывания, потерей белка, острым воспалением или беременностью, а искусственно низкий или высокий результат даёт неподходящая пробирка и разрушение клеток в пробе. Результат оценивает врач вместе с белками крови и общей картиной', 'Ein niedriger Wert kann mit der Ernährung, gestörter Aufnahme, Eiweißverlust, akuter Entzündung oder einer Schwangerschaft zusammenhängen, während ein ungeeignetes Röhrchen und Zellschäden in der Probe falsch niedrige oder hohe Werte erzeugen. Der Arzt beurteilt das Ergebnis zusammen mit den Bluteiweißen und dem Gesamtbild', 'Düşük değer beslenmeyle, emilim bozukluğuyla, protein kaybıyla, akut iltihapla veya gebelikle ilişkili olabilir; uygun olmayan tüp ve örnekteki hücre hasarı ise yanlış düşük ya da yüksek sonuç verir. Sonucu hekim kan proteinleri ve genel tabloyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'lamellar-bodies-in-amniotic-fluid'), 'Count of lamellar bodies — surfactant particles — in amniotic fluid as an indicator of fetal lung maturity', 'Brojanje lamelarnih tjelašaca — čestica surfaktanta — u plodovoj vodi kao pokazatelj zrelosti pluća ploda', 'Бројање ламеларних тјелашаца — честица сурфактанта — у плодовој води као показатељ зрелости плућа плода', 'Подсчёт ламеллярных телец — частиц сурфактанта — в околоплодных водах как показатель зрелости лёгких плода', 'Zählung der Lamellenkörperchen — Surfactant-Partikel — im Fruchtwasser als Hinweis auf die Lungenreife des Kindes', 'Amniyon sıvısındaki lamellar cisimlerin — sürfaktan partiküllerinin — bebeğin akciğer olgunluğunun göstergesi olarak sayılması', 'The amniotic fluid is obtained by a doctor during ultrasound-guided amniocentesis, and the particles are counted on a haematology analyser in the same way as platelets', 'Plodovu vodu uzima ljekar amniocentezom pod kontrolom ultrazvuka, a čestice se broje na hematološkom analizatoru isto kao trombociti', 'Плодову воду узима љекар амниоцентезом под контролом ултразвука, а честице се броје на хематолошком анализатору исто као тромбоцити', 'Околоплодные воды получает врач при амниоцентезе под контролем УЗИ, частицы считают на гематологическом анализаторе так же, как тромбоциты', 'Das Fruchtwasser gewinnt der Arzt bei einer ultraschallgesteuerten Fruchtwasserpunktion, die Partikel werden im Hämatologieanalysator wie Blutplättchen gezählt', 'Amniyon sıvısı hekim tarafından ultrason eşliğinde amniyosentezle alınır, partiküller hematoloji cihazında trombositler gibi sayılır', 'Ordered by an obstetrician when delivery before full term is being considered and the maturity of the baby''s lungs needs to be assessed', 'Traži je ginekolog akušer kada se razmatra porođaj prije termina i potrebna je procjena zrelosti bebinih pluća', 'Тражи је гинеколог акушер када се разматра порођај прије термина и потребна је процјена зрелости бебиних плућа', 'Назначается акушером-гинекологом, когда обсуждается родоразрешение раньше доношенного срока и нужна оценка зрелости лёгких ребёнка', 'Auf Anordnung des Geburtshelfers, wenn eine Entbindung vor dem errechneten Termin erwogen wird und die Lungenreife des Kindes eingeschätzt werden muss', 'Erken doğum gündeme geldiğinde ve bebeğin akciğer olgunluğunun değerlendirilmesi gerektiğinde kadın doğum hekiminin isteğiyle', 'Preparation concerns the amniocentesis itself and is explained by the doctor: consent, ultrasound beforehand, observation afterwards; there is no separate preparation for the laboratory part', 'Priprema se odnosi na samu amniocentezu i objašnjava je ljekar: saglasnost, ultrazvuk prije zahvata, nadzor poslije njega; poseban postupak za laboratorijski dio ne postoji', 'Припрема се односи на саму амниоцентезу и објашњава је љекар: сагласност, ултразвук прије захвата, надзор послије њега; посебан поступак за лабораторијски дио не постоји', 'Подготовка относится к самому амниоцентезу и её объясняет врач: согласие, УЗИ перед процедурой, наблюдение после неё; отдельной подготовки к лабораторной части нет', 'Die Vorbereitung betrifft die Fruchtwasserpunktion selbst und wird vom Arzt erklärt: Einwilligung, Ultraschall davor, Überwachung danach; für den Laborteil gibt es keine gesonderte Vorbereitung', 'Hazırlık amniyosentezin kendisiyle ilgilidir ve hekim tarafından anlatılır: onam, işlem öncesi ultrason, sonrasında gözlem; laboratuvar aşaması için ayrı bir hazırlık yoktur', 'A low count may indicate that lung maturation is still in progress, while blood, meconium or mucus in the sample distorts the count. The result is assessed only by the obstetrician together with the gestational age, the ultrasound and the condition of mother and baby', 'Nizak broj tjelašaca može značiti da sazrijevanje pluća još traje, a primjesa krvi, mekonijuma ili sluzi u uzorku iskrivljuje brojanje. Nalaz procjenjuje isključivo ginekolog akušer uz gestacijsku starost, ultrazvuk i stanje majke i bebe', 'Низак број тјелашаца може значити да сазријевање плућа још траје, а примјеса крви, меконијума или слузи у узорку искривљује бројање. Налаз процјењује искључиво гинеколог акушер уз гестацијску старост, ултразвук и стање мајке и бебе', 'Низкое число телец может говорить о том, что созревание лёгких ещё продолжается, а примесь крови, мекония или слизи в пробе искажает подсчёт. Результат оценивает только акушер-гинеколог вместе со сроком беременности, УЗИ и состоянием матери и ребёнка', 'Eine niedrige Zahl kann bedeuten, dass die Lungenreifung noch andauert, während Blut, Mekonium oder Schleim in der Probe die Zählung verfälschen. Den Befund beurteilt allein der Geburtshelfer zusammen mit Schwangerschaftswoche, Ultraschall und dem Zustand von Mutter und Kind', 'Sayının düşük olması akciğer olgunlaşmasının sürdüğünü gösterebilir; örnekteki kan, mekonyum veya mukus ise sayımı bozar. Sonucu yalnızca kadın doğum hekimi gebelik haftası, ultrason ve anne ile bebeğin durumuyla birlikte değerlendirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'urine-pregnancy-test-hcg-qualitative'), 'A rapid qualitative test showing whether chorionic gonadotropin is present in the urine, without measuring its amount', 'Brzi kvalitativni test: pokazuje da li u urinu ima horionskog gonadotropina, bez mjerenja količine', 'Брзи квалитативни тест: показује да ли у урину има хорионског гонадотропина, без мјерења количине', 'Быстрый качественный тест: определяет, есть ли в моче хорионический гонадотропин, без измерения его количества', 'Schnelltest, der qualitativ zeigt, ob Choriongonadotropin im Urin vorhanden ist, ohne die Menge zu bestimmen', 'İdrarda koryonik gonadotropin bulunup bulunmadığını miktar ölçmeden gösteren hızlı kalitatif test', 'A portion of urine is applied to a test strip or cassette and the result is read after the time stated in the instructions; the answer is positive or negative', 'Uzorak urina se nanese na test traku ili kasetu, a nalaz se očitava poslije vremena navedenog u uputstvu; odgovor je pozitivan ili negativan', 'Узорак урина се нанесе на тест траку или касету, а налаз се очитава послије времена наведеног у упутству; одговор је позитиван или негативан', 'Порцию мочи наносят на тест-полоску или кассету, результат читают через указанное в инструкции время; ответ даётся как положительный или отрицательный', 'Eine Urinportion wird auf einen Teststreifen oder eine Kassette gegeben und das Ergebnis nach der in der Anleitung genannten Zeit abgelesen; die Antwort lautet positiv oder negativ', 'Bir miktar idrar test şeridine veya kasete damlatılır, sonuç kullanma talimatında belirtilen süre sonunda okunur; yanıt pozitif ya da negatiftir', 'Checking after a missed period, confirming pregnancy before a visit to the gynaecologist, screening before procedures and examinations for which pregnancy status matters', 'Provjera kod izostanka menstruacije, potvrda trudnoće prije odlaska ginekologu, ispitivanje prije zahvata i pregleda kod kojih je važno znati da li postoji trudnoća', 'Провјера код изостанка менструације, потврда трудноће прије одласка гинекологу, испитивање прије захвата и прегледа код којих је важно знати да ли постоји трудноћа', 'Проверка при задержке менструации, подтверждение беременности перед визитом к гинекологу, обследование перед процедурами и исследованиями, где важно знать о беременности', 'Prüfung beim Ausbleiben der Regelblutung, Bestätigung einer Schwangerschaft vor dem Besuch beim Frauenarzt, Abklärung vor Eingriffen und Untersuchungen, bei denen eine Schwangerschaft bekannt sein muss', 'Adet gecikmesinde kontrol, kadın doğum hekimine gitmeden önce gebeliğin doğrulanması, gebelik durumunun bilinmesi gereken girişim ve tetkikler öncesinde inceleme', 'The first morning urine is best, as it is more concentrated; drinking large amounts of fluid beforehand is not advisable, and the sample is collected in a clean container', 'Najbolje je koristiti prvi jutarnji urin jer je koncentrovaniji; prethodno ne treba piti previše tečnosti, a uzorak se sakuplja u čistu posudu', 'Најбоље је користити први јутарњи урин јер је концентрованији; претходно не треба пити превише течности, а узорак се сакупља у чисту посуду', 'Лучше использовать первую утреннюю мочу, она более концентрированная; накануне не стоит пить избыточно много жидкости, сбор — в чистый контейнер', 'Am besten eignet sich der erste Morgenurin, da er konzentrierter ist; vorher sollte nicht übermäßig viel getrunken werden, die Probe wird in einem sauberen Behälter gesammelt', 'Daha yoğun olduğu için sabah ilk idrarın kullanılması uygundur; öncesinde aşırı sıvı içilmemeli, örnek temiz bir kaba alınmalıdır', 'A negative answer very early does not rule out pregnancy, and a positive one also occurs after recent childbirth, termination or miscarriage, as well as with medicines containing HCG. The result is confirmed by a blood test and an examination by a gynaecologist', 'Negativan odgovor u vrlo ranoj fazi ne isključuje trudnoću, a pozitivan se javlja i poslije nedavnog porođaja, prekida trudnoće ili spontanog pobačaja, kao i uz lijekove koji sadrže HCG. Nalaz se potvrđuje analizom krvi i pregledom ginekologa', 'Негативан одговор у врло раној фази не искључује трудноћу, а позитиван се јавља и послије недавног порођаја, прекида трудноће или спонтаног побачаја, као и уз лијекове који садрже HCG. Налаз се потврђује анализом крви и прегледом гинеколога', 'Отрицательный ответ на очень раннем сроке не исключает беременности, а положительный бывает после недавних родов, прерывания беременности или выкидыша, а также при приёме препаратов с ХГЧ. Подтверждают результат анализом крови и осмотром гинеколога', 'Ein negatives Ergebnis schließt eine sehr frühe Schwangerschaft nicht aus, ein positives kommt auch nach kürzlicher Geburt, Abbruch oder Fehlgeburt sowie unter HCG-haltigen Medikamenten vor. Bestätigt wird der Befund durch einen Bluttest und die Untersuchung beim Frauenarzt', 'Çok erken dönemde negatif yanıt gebeliği dışlamaz; pozitif yanıt ise yakın zamanda doğum, gebelik sonlandırması veya düşük sonrasında ve HCG içeren ilaç kullanımında da görülebilir. Sonuç kan testi ve kadın doğum hekiminin muayenesiyle doğrulanır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'chloride-in-urine'), 'Measurement of chloride excreted in the urine — an indicator of how the kidneys retain salt and maintain the acid-base balance', 'Mjerenje izlučivanja hlorida mokraćom — pokazatelj kako bubrezi zadržavaju so i održavaju acidobaznu ravnotežu', 'Мјерење излучивања хлорида мокраћом — показатељ како бубрези задржавају со и одржавају ацидобазну равнотежу', 'Измерение выведения хлоридов с мочой — показатель того, как почки удерживают соль и поддерживают кислотно-щелочное равновесие', 'Messung der Chloridausscheidung im Urin — ein Hinweis darauf, wie die Nieren Salz zurückhalten und das Säure-Basen-Gleichgewicht halten', 'İdrarla atılan klorürün ölçülmesi — böbreklerin tuzu tutma ve asit-baz dengesini koruma biçiminin göstergesi', 'A single urine portion or a 24-hour collection made by the patient at home in a separate container is analysed', 'Analizira se pojedinačni uzorak urina ili 24-časovni sakupljeni urin koji pacijent prikuplja kod kuće u posebnu posudu', 'Анализира се појединачни узорак урина или 24-часовни сакупљени урин који пацијент прикупља код куће у посебну посуду', 'Исследуют разовую порцию мочи или суточный сбор, который пациент собирает дома в отдельную ёмкость', 'Untersucht wird eine einzelne Urinportion oder eine 24-Stunden-Sammlung, die der Patient zu Hause in einem eigenen Behälter anlegt', 'Tek seferlik idrar örneği ya da hastanın evde ayrı bir kapta topladığı 24 saatlik idrar incelenir', 'Working out the cause of electrolyte and acid-base disturbances, prolonged vomiting and diarrhoea, oedema, treatment with diuretics, assessment of salt load as ordered by a doctor', 'Razjašnjavanje uzroka poremećaja elektrolita i acidobazne ravnoteže, dugotrajno povraćanje i proliv, otoci, terapija diureticima, procjena unosa soli po uputu ljekara', 'Разјашњавање узрока поремећаја електролита и ацидобазне равнотеже, дуготрајно повраћање и пролив, отоци, терапија диуретицима, процјена уноса соли по упуту љекара', 'Разбор причин нарушений электролитов и кислотно-щелочного равновесия, длительная рвота и диарея, отёки, приём мочегонных, оценка солевой нагрузки по назначению врача', 'Abklärung von Elektrolyt- und Säure-Basen-Störungen, anhaltendes Erbrechen und Durchfall, Ödeme, Therapie mit Entwässerungsmitteln, Beurteilung der Salzzufuhr auf ärztliche Anordnung', 'Elektrolit ve asit-baz bozukluklarının nedeninin araştırılması, uzun süren kusma ve ishal, ödem, idrar söktürücü kullanımı, hekim isteğiyle tuz alımının değerlendirilmesi', 'For a 24-hour collection the first morning portion is discarded, all urine is then collected until the same time the next day and the container is kept cool; diuretics and dietary changes should be reported to the doctor', 'Kod 24-časovnog sakupljanja prva jutarnja porcija se ne sakuplja, zatim se skuplja sav urin do istog vremena sljedećeg dana, a posuda se drži na hladnom; diuretike i promjene u ishrani treba javiti ljekaru', 'Код 24-часовног сакупљања прва јутарња порција се не сакупља, затим се скупља сав урин до истог времена сљедећег дана, а посуда се држи на хладном; диуретике и промјене у исхрани треба јавити љекару', 'При суточном сборе первую утреннюю порцию не собирают, дальше собирают всю мочу до того же времени следующего дня и хранят ёмкость в прохладе; о мочегонных и изменениях в диете сообщают врачу', 'Bei der 24-Stunden-Sammlung wird die erste Morgenportion verworfen, danach wird der gesamte Urin bis zur gleichen Uhrzeit am Folgetag gesammelt und der Behälter kühl gelagert; Entwässerungsmittel und Ernährungsumstellungen sollten dem Arzt mitgeteilt werden', '24 saatlik toplamada sabah ilk idrar alınmaz, sonrasında ertesi gün aynı saate kadar tüm idrar toplanır ve kap serin yerde tutulur; idrar söktürücüler ve beslenme değişiklikleri hekime bildirilir', 'Changes may be related to loss of fluid and salt through vomiting, diarrhoea and sweating, to diuretics, kidney function and hormonal regulation. The value is assessed only together with blood electrolytes and the other tests, and the conclusion is drawn by a doctor', 'Promjene mogu biti povezane sa gubitkom tečnosti i soli pri povraćanju, prolivu i znojenju, sa diureticima, radom bubrega i hormonskom regulacijom. Pokazatelj se procjenjuje isključivo uz elektrolite u krvi i ostale analize, a zaključak donosi ljekar', 'Промјене могу бити повезане са губитком течности и соли при повраћању, проливу и знојењу, са диуретицима, радом бубрега и хормонском регулацијом. Показатељ се процјењује искључиво уз електролите у крви и остале анализе, а закључак доноси љекар', 'Изменения могут быть связаны с потерей жидкости и соли при рвоте, диарее и потении, приёмом мочегонных, работой почек и гормональной регуляцией. Показатель оценивают только вместе с электролитами крови и остальными анализами, вывод делает врач', 'Veränderungen können mit dem Verlust von Flüssigkeit und Salz bei Erbrechen, Durchfall und Schwitzen, mit Entwässerungsmitteln, der Nierenfunktion und der hormonellen Regulation zusammenhängen. Der Wert wird nur zusammen mit den Elektrolyten im Blut und den übrigen Befunden beurteilt, die Bewertung nimmt der Arzt vor', 'Değişiklikler kusma, ishal ve terlemeyle olan sıvı ve tuz kaybıyla, idrar söktürücülerle, böbreklerin çalışmasıyla ve hormonal düzenlemeyle ilişkili olabilir. Sonuç yalnızca kandaki elektrolitler ve diğer tetkiklerle birlikte değerlendirilir, yorumu hekim yapar')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'protein-s-100'), 'Blood test for the S-100 group of proteins, found in cells of the nervous system, the skin and some other tissues and used as a tumour marker when monitoring pigmented skin lesions', 'Analiza krvi na grupu bjelančevina S-100, koje se nalaze u ćelijama nervnog sistema, koži i nekim drugim tkivima, a koriste se kao tumorski marker pri praćenju pigmentnih promjena na koži', 'Анализа крви на групу бјеланчевина С-100, које се налазе у ћелијама нервног система, кожи и неким другим ткивима, а користе се као туморски маркер при праћењу пигментних промјена на кожи', 'Анализ крови на группу белков S-100, которые находят в клетках нервной системы, коже и некоторых других тканях и используют как онкомаркер при наблюдении за пигментными образованиями кожи', 'Bluttest auf die Proteingruppe S-100, die in Zellen des Nervensystems, der Haut und einiger weiterer Gewebe vorkommt und als Tumormarker bei der Verlaufsbeobachtung pigmentierter Hautveränderungen eingesetzt wird', 'Sinir sistemi hücrelerinde, deride ve bazı başka dokularda bulunan ve deri üzerindeki pigmentli lezyonların izleminde tümör belirteci olarak kullanılan S-100 protein grubunu ölçen kan testi', 'Venous blood draw, takes a few minutes; for repeat measurements the same laboratory is preferable', 'Uzimanje venske krvi, traje nekoliko minuta; kod ponovljenih mjerenja poželjna je ista laboratorija', 'Узимање венске крви, траје неколико минута; код поновљених мјерења пожељна је иста лабораторија', 'Забор венозной крови, занимает несколько минут; при повторных измерениях желательно сдавать в одной и той же лаборатории', 'Venöse Blutentnahme, dauert wenige Minuten; bei Verlaufskontrollen möglichst immer dasselbe Labor', 'Toplardamardan kan alınması, birkaç dakika sürer; tekrarlanan ölçümlerde aynı laboratuvar tercih edilir', 'Ordered by a doctor when pigmented skin lesions are being assessed, monitoring during treatment and subsequent follow-up; it is not used as screening in healthy people', 'Po uputu ljekara pri ispitivanju pigmentnih promjena na koži, praćenje tokom liječenja i kasnija kontrola; ne koristi se kao skrining kod zdravih osoba', 'По упуту љекара при испитивању пигментних промјена на кожи, праћење током лијечења и каснија контрола; не користи се као скрининг код здравих особа', 'По назначению врача при обследовании пигментных образований кожи, наблюдение в процессе лечения и последующий контроль; как скрининг у здоровых людей не применяется', 'Auf ärztliche Anordnung bei der Abklärung pigmentierter Hautveränderungen, Verlaufskontrolle während der Behandlung und Nachsorge; als Screening bei Gesunden wird er nicht eingesetzt', 'Pigmentli deri lezyonlarının değerlendirilmesinde hekim isteğiyle, tedavi sırasında izlem ve sonraki kontroller; sağlıklı kişilerde tarama amacıyla kullanılmaz', 'No special preparation is usually required; intense physical exercise the day before is best avoided, and recent head injuries should be mentioned to the doctor', 'Posebna priprema obično nije potrebna; dan ranije poželjno je izbjegavati intenzivan fizički napor, a skorašnje povrede glave treba pomenuti ljekaru', 'Посебна припрема обично није потребна; дан раније пожељно је избјегавати интензиван физички напор, а скорашње повреде главе треба поменути љекару', 'Специальной подготовки обычно не требуется; накануне желательно избегать интенсивной физической нагрузки, а о недавних травмах головы стоит сказать врачу', 'Eine besondere Vorbereitung ist meist nicht nötig; starke körperliche Belastung am Vortag sollte vermieden werden, kürzliche Kopfverletzungen sollten dem Arzt mitgeteilt werden', 'Genellikle özel bir hazırlık gerekmez; bir gün önce yoğun fiziksel aktiviteden kaçınmak uygundur, yakın zamandaki kafa travmaları hekime söylenmelidir', 'An increase occurs with benign and other conditions — after head injury and concussion, in diseases of the nervous system, inflammation, liver and kidney disease, intense physical exertion, and also when cells break down in the sample — and on its own it does not mean an oncological disease. Only a doctor determines what the result means, comparing it with the examination and other tests', 'Povećanje se javlja i kod benignih i drugih stanja — poslije povrede glave i potresa mozga, kod oboljenja nervnog sistema, upale, bolesti jetre i bubrega, intenzivnog fizičkog napora, kao i pri razgradnji ćelija u uzorku — i samo po sebi ne znači onkološko oboljenje. Značenje nalaza određuje isključivo ljekar, upoređujući ga sa pregledom i drugim ispitivanjima', 'Повећање се јавља и код бенигних и других стања — послије повреде главе и потреса мозга, код обољења нервног система, упале, болести јетре и бубрега, интензивног физичког напора, као и при разградњи ћелија у узорку — и само по себи не значи онколошко обољење. Значење налаза одређује искључиво љекар, упоређујући га са прегледом и другим испитивањима', 'Повышение бывает при доброкачественных и иных состояниях — после травмы головы и сотрясения, при заболеваниях нервной системы, воспалении, болезнях печени и почек, интенсивной физической нагрузке, а также при разрушении клеток в пробе — и само по себе не означает онкологического заболевания. Значение результата определяет только врач, сопоставляя его с осмотром и другими исследованиями', 'Ein Anstieg kommt auch bei gutartigen und anderen Zuständen vor — nach Kopfverletzung und Gehirnerschütterung, bei Erkrankungen des Nervensystems, Entzündungen, Leber- und Nierenerkrankungen, starker körperlicher Belastung sowie bei Zellzerfall in der Probe — und bedeutet für sich genommen keine onkologische Erkrankung. Was der Wert bedeutet, entscheidet allein der Arzt im Zusammenhang mit Untersuchung und weiteren Befunden', 'Yükselme iyi huylu ve başka durumlarda da görülür — kafa travması ve sarsıntı sonrasında, sinir sistemi hastalıklarında, iltihapta, karaciğer ve böbrek hastalıklarında, yoğun fiziksel eforda ve örnekteki hücrelerin parçalanmasında — ve tek başına onkolojik bir hastalık anlamına gelmez. Sonucun anlamını yalnızca hekim, muayene ve diğer tetkiklerle birlikte belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'mxa-crp'), 'A rapid test measuring two values at once: the MxA protein, which appears during a viral infection, and C-reactive protein, which reflects inflammation', 'Brzi test u kojem se istovremeno određuju dva pokazatelja: bjelančevina MxA, koja se stvara pri virusnoj infekciji, i C-reaktivni protein, koji odražava upalu', 'Брзи тест у којем се истовремено одређују два показатеља: бјеланчевина МxА, која се ствара при вирусној инфекцији, и Ц-реактивни протеин, који одражава упалу', 'Экспресс-тест, в котором одновременно определяют два показателя: белок MxA, появляющийся при вирусной инфекции, и C-реактивный белок, отражающий воспаление', 'Schnelltest, der zwei Werte gleichzeitig bestimmt: das Protein MxA, das bei einer Virusinfektion gebildet wird, und das C-reaktive Protein als Entzündungswert', 'İki göstergeyi aynı anda ölçen hızlı test: viral enfeksiyonda ortaya çıkan MxA proteini ve iltihabı yansıtan C-reaktif protein', 'A drop of blood from the fingertip or a small venous sample is applied to the test cassette and the result is read on the spot from the indicator lines', 'Uzima se kap krvi iz prsta ili mali uzorak venske krvi i nanosi na kasetu testa, a nalaz se očitava na licu mjesta po indikatorskim linijama', 'Узима се кап крви из прста или мали узорак венске крви и наноси на касету теста, а налаз се очитава на лицу мјеста по индикаторским линијама', 'Берут каплю крови из пальца или небольшую пробу венозной крови и наносят на кассету теста, результат считывают на месте по индикаторным полосам', 'Ein Blutstropfen aus der Fingerbeere oder eine kleine venöse Probe wird auf die Testkassette gegeben, das Ergebnis wird vor Ort an den Anzeigelinien abgelesen', 'Parmak ucundan bir damla kan ya da az miktarda venöz kan test kasetine damlatılır, sonuç yerinde gösterge çizgilerinden okunur', 'Fever and acute respiratory symptoms when the doctor needs a quick impression of the nature of the inflammation, most often in children, and repeat visits for unclear fever', 'Povišena temperatura i akutni respiratorni simptomi kada ljekaru treba brza procjena prirode upale, najčešće kod djece, kao i ponovna javljanja zbog nejasne temperature', 'Повишена температура и акутни респираторни симптоми када љекару треба брза процјена природе упале, најчешће код дјеце, као и поновна јављања због нејасне температуре', 'Лихорадка и острые респираторные симптомы, когда врачу нужно быстро оценить характер воспаления, чаще у детей, а также повторные обращения с неясной температурой', 'Fieber und akute Atemwegsbeschwerden, wenn der Arzt schnell einschätzen muss, welcher Art die Entzündung ist, meist bei Kindern, sowie wiederholte Vorstellungen wegen unklarem Fieber', 'Ateş ve akut solunum yolu belirtilerinde hekimin iltihabın niteliğini hızla değerlendirmesi gerektiğinde, çoğunlukla çocuklarda, ayrıca nedeni belirsiz ateşle tekrarlayan başvurularda', 'No preparation is required and the test is done during the visit; it helps to tell the doctor when the fever started and which antipyretics were taken', 'Priprema nije potrebna, test se radi tokom pregleda; korisno je ljekaru reći kada je temperatura počela i koji su lijekovi protiv temperature uzimani', 'Припрема није потребна, тест се ради током прегледа; корисно је љекару рећи када је температура почела и који су лијекови против температуре узимани', 'Подготовки не требуется, тест выполняется прямо на приёме; полезно сказать врачу, когда началась температура и какие жаропонижающие принимались', 'Eine Vorbereitung ist nicht nötig, der Test erfolgt direkt beim Arztbesuch; hilfreich ist die Angabe, wann das Fieber begonnen hat und welche fiebersenkenden Mittel eingenommen wurden', 'Hazırlık gerekmez, test muayene sırasında yapılır; ateşin ne zaman başladığını ve hangi ateş düşürücülerin alındığını hekime söylemek yararlıdır', 'The combination of the two values helps the doctor judge whether the inflammation is closer to a viral or a bacterial one, but the result does not replace an examination and does not point to a specific pathogen. Further tests and treatment are decided by the doctor', 'Kombinacija pokazatelja pomaže ljekaru da procijeni da li je upala bliža virusnoj ili bakterijskoj, ali nalaz ne zamjenjuje pregled i ne pokazuje konkretnog uzročnika. Odluku o daljim analizama i liječenju donosi ljekar', 'Комбинација показатеља помаже љекару да процијени да ли је упала ближа вирусној или бактеријској, али налаз не замјењује преглед и не показује конкретног узрочника. Одлуку о даљим анализама и лијечењу доноси љекар', 'Сочетание показателей помогает врачу оценить, ближе ли воспаление к вирусному или бактериальному, но результат не заменяет осмотр и не указывает на конкретного возбудителя. Решение о дальнейших анализах и лечении принимает врач', 'Die Kombination beider Werte hilft dem Arzt einzuschätzen, ob die Entzündung eher viral oder bakteriell ist, ersetzt aber die Untersuchung nicht und benennt keinen konkreten Erreger. Über weitere Untersuchungen und die Behandlung entscheidet der Arzt', 'İki göstergenin birlikte değerlendirilmesi hekimin iltihabın viral mi bakteriyel mi olduğuna dair fikir edinmesine yardımcı olur, ancak sonuç muayenenin yerini tutmaz ve belirli bir etkeni göstermez. Ek tetkiklere ve tedaviye hekim karar verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'complete-urinalysis'), 'A comprehensive test of the physical and chemical properties of urine and its sediment', 'Sveobuhvatna analiza fizičkih, hemijskih svojstava mokraće i sedimenta', 'Свеобухватна анализа физичких, хемијских својстава мокраће и седимента', 'Комплексный анализ физических, химических свойств мочи и осадка', 'Eine umfassende Untersuchung der physikalischen und chemischen Eigenschaften des Urins und des Sediments', 'İdrarın fiziksel ve kimyasal özellikleri ile sedimentinin kapsamlı analizi', 'A single morning urine sample in a container, no needles or injections involved', 'Jednokratni uzorak jutarnje mokraće u posudi, bez igala i uboda', 'Једнократни узорак јутарње мокраће у посуди, без игала и убода', 'Разовая утренняя порция мочи в контейнер, без иглы и уколов', 'Eine einmalige Morgenurinprobe in einem Behälter, ohne Nadeln oder Injektionen', 'Bir kaba tek seferlik sabah idrarı örneği alınması, iğne veya enjeksiyon gerekmez', 'Preventive check-up, routine health screening, symptoms related to the kidneys/urinary tract, monitoring during pregnancy', 'Preventivni pregled, sistematski pregled, simptomi sa strane bubrega/mokraćnih puteva, kontrola tokom trudnoće', 'Превентивни преглед, систематски преглед, симптоми са стране бубрега/мокраћних путева, контрола током трудноће', 'Профилактический осмотр, диспансеризация, симптомы со стороны почек/мочевых путей, контроль при беременности', 'Vorsorgeuntersuchung, Routine-Gesundheitscheck, Beschwerden im Bereich der Nieren/Harnwege, Kontrolle während der Schwangerschaft', 'Rutin kontrol, genel sağlık taraması, böbrek/idrar yolları ile ilgili semptomlar, gebelikte takip', 'Morning urine after hygiene; for 1–2 days beforehand avoid beetroot and other coloring foods and heavy physical exertion; mention if menstruating', 'Jutarnja mokraća poslije higijene; 1–2 dana ranije izbjegavati cveklu i namirnice koje boje mokraću, kao i veće fizičke napore; napomenuti ako je menstruacija', 'Јутарња мокраћа послије хигијене; 1–2 дана раније избјегавати цвеклу и намирнице које боје мокраћу, као и веће физичке напоре; напоменути ако је менструација', 'Утренняя моча после гигиены; за 1–2 дня — без свёклы и красящих продуктов, без больших физических нагрузок; предупредить о менструации', 'Morgenurin nach der Hygiene; 1–2 Tage vorher rote Bete und andere färbende Lebensmittel sowie starke körperliche Anstrengung vermeiden; eine Menstruation sollte angegeben werden', 'Hijyen sonrası sabah idrarı; 1–2 gün öncesinden pancar ve idrarı renklendiren gıdalardan ve yoğun fiziksel efordan kaçınılmalı; adet dönemindeyseniz belirtin', 'Changes may be related to processes in the kidneys, urinary tract, metabolism, or temporary factors (exertion, diet). The exact cause is determined by a doctor based on the overall picture', 'Promjene mogu biti povezane sa procesima u bubrezima, mokraćnim putevima, metabolizmom ili privremenim faktorima (napor, ishrana). Tačan uzrok utvrđuje ljekar na osnovu cjelokupne slike', 'Промјене могу бити повезане са процесима у бубрезима, мокраћним путевима, метаболизмом или привременим факторима (напор, исхрана). Тачан узрок утврђује љекар на основу цјелокупне слике', 'Изменения могут быть связаны с процессами в почках, мочевых путях, обменом веществ или временными факторами (нагрузка, питание). Точную причину определяет врач по совокупности показателей', 'Veränderungen können mit Vorgängen in den Nieren, den Harnwegen, dem Stoffwechsel oder vorübergehenden Faktoren (Belastung, Ernährung) zusammenhängen. Die genaue Ursache wird vom Arzt anhand des Gesamtbilds festgestellt', 'Değişiklikler böbreklerdeki, idrar yollarındaki, metabolizmadaki süreçlerle veya geçici etkenlerle (efor, beslenme) ilişkili olabilir. Kesin nedeni hekim genel tabloya göre belirler')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'glucose'), 'Blood test for blood sugar (glucose) level', 'Analiza krvi na nivo šećera (glukoze)', 'Анализа крви на ниво шећера (глукозе)', 'Анализ крови на уровень сахара (глюкозы)', 'Bluttest zur Bestimmung des Blutzuckerspiegels (Glukose)', 'Kandaki şeker (glukoz) düzeyini ölçen kan testi', 'Venous blood draw on an empty stomach', 'Uzimanje venske krvi natašte', 'Узимање венске крви наташте', 'Забор венозной крови натощак', 'Entnahme von venösem Blut nüchtern', 'Aç karnına toplardamardan kan alınması', 'Routine check-ups, monitoring diabetes mellitus, thirst/weakness, screening during pregnancy', 'Sistematski pregled, kontrola šećerne bolesti, žeđ/slabost, skrining tokom trudnoće', 'Систематски преглед, контрола шећерне болести, жеђ/слабост, скрининг током трудноће', 'Диспансеризация, контроль сахарного диабета, жажда/слабость, скрининг при беременности', 'Vorsorgeuntersuchung, Kontrolle bei Diabetes mellitus, Durst/Schwäche, Screening während der Schwangerschaft', 'Rutin kontrol, diyabetin takibi, susama/halsizlik, gebelikte tarama', 'Fasting for 8–12 hours, only water allowed; avoid alcohol and heavy food the day before', 'Natašte 8–12 sati, dozvoljena samo voda; dan ranije izbjegavati alkohol i tešku hranu', 'Наташте 8–12 сати, дозвољена само вода; дан раније избјегавати алкохол и тешку храну', 'Натощак 8–12 часов, разрешена только вода; накануне избегать алкоголя и тяжёлой пищи', 'Nüchtern seit 8–12 Stunden, nur Wasser erlaubt; am Vortag Alkohol und schwere Mahlzeiten vermeiden', '8–12 saat aç karnına, sadece su içilebilir; bir önceki gün alkol ve ağır yiyeceklerden kaçınılmalıdır', 'Changes in the level may be related to disturbances in carbohydrate metabolism or temporary factors (stress, food intake, medications). The diagnosis is made by a doctor based on several indicators', 'Promjene nivoa mogu biti povezane sa poremećajem metabolizma ugljenih hidrata ili privremenim faktorima (stres, uzimanje hrane, lijekovi). Dijagnozu postavlja ljekar na osnovu više pokazatelja', 'Промјене нивоа могу бити повезане са поремећајем метаболизма угљених хидрата или привременим факторима (стрес, узимање хране, лијекови). Дијагнозу поставља љекар на основу више показатеља', 'Изменения уровня могут быть связаны с нарушением углеводного обмена или временными факторами (стресс, приём пищи, лекарства). Диагноз ставит врач на основании нескольких показателей', 'Veränderungen des Werts können mit einer Störung des Kohlenhydratstoffwechsels oder vorübergehenden Faktoren (Stress, Nahrungsaufnahme, Medikamente) zusammenhängen. Die Diagnose wird vom Arzt anhand mehrerer Werte gestellt', 'Değerdeki değişiklikler karbonhidrat metabolizması bozukluğu veya geçici etkenlerle (stres, yemek yeme, ilaçlar) ilişkili olabilir. Tanı, birden fazla göstergeye dayanarak hekim tarafından konur')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO lab_test_reference_info (lab_test_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM lab_tests WHERE slug = 'cholesterol'), 'Blood test for total cholesterol — one of the indicators of lipid metabolism', 'Analiza krvi na ukupni holesterol — jedan od pokazatelja lipidnog metabolizma', 'Анализа крви на укупни холестерол — један од показатеља липидног метаболизма', 'Анализ крови на общее содержание холестерина — один из показателей липидного обмена', 'Bluttest zur Bestimmung des Gesamtcholesterins — eines der Indikatoren des Fettstoffwechsels', 'Lipid metabolizmasının göstergelerinden biri olan toplam kolesterol için kan testi', 'Venous blood draw, usually together with the rest of the lipid profile', 'Uzimanje venske krvi, obično zajedno sa ostalim lipidnim profilom', 'Узимање венске крви, обично заједно са осталим липидним профилом', 'Забор венозной крови, обычно вместе с остальным липидным профилем', 'Entnahme von venösem Blut, meist zusammen mit dem restlichen Lipidprofil', 'Genellikle diğer lipid profili değerleriyle birlikte toplardamardan kan alınması', 'Cardiovascular risk screening, routine check-ups, monitoring during lipid-lowering therapy', 'Skrining kardiovaskularnog rizika, sistematski pregled, kontrola tokom uzimanja lijekova za snižavanje lipida', 'Скрининг кардиоваскуларног ризика, систематски преглед, контрола током узимања лијекова за снижавање липида', 'Скрининг сердечно-сосудистого риска, диспансеризация, контроль на фоне гиполипидемических препаратов', 'Screening des kardiovaskulären Risikos, Vorsorgeuntersuchung, Kontrolle während einer lipidsenkenden Therapie', 'Kardiyovasküler risk taraması, rutin kontrol, yağ düşürücü tedavi sırasında takip', 'Fasting for 9–12 hours; avoid fatty food and alcohol the day before', 'Natašte 9–12 sati; dan ranije izbjegavati masnu hranu i alkohol', 'Наташте 9–12 сати; дан раније избјегавати масну храну и алкохол', 'Натощак 9–12 часов; за сутки избегать жирной пищи и алкоголя', '9–12 Stunden nüchtern; am Vortag fettreiche Speisen und Alkohol vermeiden', '9–12 saat aç karnına; bir önceki gün yağlı yiyecekler ve alkolden kaçınılmalıdır', 'Changes may be related to diet, lifestyle, heredity, or metabolic disorders. The overall risk is assessed by a doctor together with other fractions (LDL, HDL, triglycerides) and the clinical picture', 'Promjene mogu biti povezane sa ishranom, načinom života, nasljeđem ili poremećajem metabolizma. Ukupan rizik ljekar procjenjuje zajedno sa ostalim frakcijama (LDL, HDL, trigliceridi) i kliničkom slikom', 'Промјене могу бити повезане са исхраном, начином живота, насљеђем или поремећајем метаболизма. Укупан ризик љекар процјењује заједно са осталим фракцијама (ЛДЛ, ХДЛ, триглицериди) и клиничком сликом', 'Изменения могут быть связаны с питанием, образом жизни, наследственностью или нарушением обмена веществ. Общий риск врач оценивает вместе с другими фракциями (ЛПНП, ЛПВП, триглицериды) и клинической картиной', 'Veränderungen können mit Ernährung, Lebensstil, erblichen Faktoren oder Stoffwechselstörungen zusammenhängen. Das Gesamtrisiko bewertet der Arzt zusammen mit den weiteren Werten (LDL, HDL, Triglyceride) und dem klinischen Bild', 'Değişiklikler beslenme, yaşam tarzı, kalıtım veya metabolizma bozukluğuyla ilişkili olabilir. Genel riski hekim, diğer değerlerle (LDL, HDL, trigliseritler) ve klinik tabloyla birlikte değerlendirir')
