INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'x-ray-upper-arm'), 'Image of the humerus along its whole length, from the shoulder joint to the elbow', 'Snimak nadlaktične kosti cijelom dužinom, od ramenog do lakatnog zgloba', 'Снимак надлактичне кости цијелом дужином, од раменог до лакатног зглоба', 'Снимок плечевой кости на всём протяжении, от плечевого сустава до локтевого', 'Aufnahme des Oberarmknochens in ganzer Länge, vom Schulter- bis zum Ellenbogengelenk', 'Humerusun omuz ekleminden dirseğe kadar tüm uzunluğunun filmi', 'Two views with the arm along the body or slightly away from it; when pain is severe the images are taken without extra turning of the arm, and it takes a few minutes', 'Dvije projekcije, ruka uz tijelo ili blago odmaknuta; kod jakog bola snimci se prave bez suvišnog okretanja ruke, a snimanje traje nekoliko minuta', 'Двије пројекције, рука уз тијело или благо одмакнута; код јаког бола снимци се праве без сувишног окретања руке, а снимање траје неколико минута', 'Две проекции, рука вдоль тела или слегка отведена; при выраженной боли снимки делают без лишних поворотов руки, съёмка занимает несколько минут', 'Zwei Ebenen, der Arm liegt am Körper an oder ist leicht abgespreizt; bei starken Schmerzen wird ohne zusätzliche Drehung des Arms aufgenommen, es dauert wenige Minuten', 'Kol gövdeye yaslı veya hafif açık halde iki pozisyon; ağrı şiddetliyse kol gereksiz yere çevrilmeden çekim yapılır, işlem birkaç dakika sürer', 'Injury to the middle of the upper arm, deformity after a blow, follow-up of a healing humeral fracture, bone pain without trauma, weakness of the hand after an upper arm injury', 'Povreda sredine nadlaktice, deformitet poslije udarca, kontrola srastanja preloma nadlaktične kosti, bol u kosti bez povrede, slabost šake poslije povrede nadlaktice', 'Повреда средине надлактице, деформитет послије ударца, контрола срастања прелома надлактичне кости, бол у кости без повреде, слабост шаке послије повреде надлактице', 'Травма середины плеча, деформация после удара, контроль сращения перелома плечевой кости, боль в кости без травмы, слабость кисти после травмы плеча', 'Verletzung in der Mitte des Oberarms, Fehlstellung nach einem Schlag, Heilungskontrolle eines Oberarmbruchs, Knochenschmerz ohne Unfall, Schwäche der Hand nach einer Oberarmverletzung', 'Üst kolun ortasında travma, darbe sonrası şekil bozukluğu, humerus kırığında kaynama kontrolü, travma olmadan kemik ağrısı, üst kol travmasından sonra elde güçsüzlük', 'No preparation needed; free the shoulder and arm from clothing and take off the watch and necklace', 'Priprema nije potrebna; osloboditi rame i ruku od odjeće i skinuti sat i lančić', 'Припрема није потребна; ослободити раме и руку од одјеће и скинути сат и ланчић', 'Подготовка не нужна; освободить плечо и руку от одежды, снять часы и цепочку', 'Keine Vorbereitung nötig; Schulter und Arm von Kleidung befreien, Uhr und Kette ablegen', 'Hazırlık gerekmez; omuz ve kol giysiden kurtarılır, saat ve kolye çıkarılır', 'The fracture line and displacement of fragments, the axis of the bone, the structure of bone tissue and signs of healing are assessed. The radiologist describes the film and the trauma surgeon decides on the next steps', 'Procjenjuju se linija preloma i pomak ulomaka, osovina kosti, građa koštanog tkiva i znaci srastanja. Snimak opisuje radiolog, a dalju taktiku određuje traumatolog', 'Процјењују се линија прелома и помак уломака, осовина кости, грађа коштаног ткива и знаци срастања. Снимак описује радиолог, а даљу тактику одређује трауматолог', 'Оценивают линию перелома и смещение отломков, ось кости, структуру костной ткани и признаки сращения. Снимок описывает рентгенолог, а дальнейшую тактику определяет травматолог', 'Beurteilt werden Bruchlinie und Verschiebung der Fragmente, die Achse des Knochens, die Knochenstruktur und Zeichen der Heilung. Die Radiologie beschreibt das Bild, über das weitere Vorgehen entscheidet die Unfallchirurgie', 'Kırık hattı ve parçaların kayması, kemik ekseni, kemik dokusunun yapısı ve kaynama bulguları değerlendirilir. Filmi radyoloji uzmanı tanımlar, izlem kararını ortopedi ve travmatoloji hekimi verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'x-ray-both-forearms'), 'Examination in which the right and left forearm are imaged in one visit so that the two sides can be compared', 'Pregled u kojem se u jednom terminu snima desna i lijeva podlaktica radi poređenja strana', 'Преглед у којем се у једном термину снима десна и лијева подлактица ради поређења страна', 'Исследование, при котором в одном приёме снимают правое и левое предплечье, чтобы сравнить стороны', 'Untersuchung, bei der rechter und linker Unterarm in einem Termin aufgenommen werden, um beide Seiten zu vergleichen', 'Sağ ve sol ön kolun iki tarafın karşılaştırılabilmesi için tek seansta görüntülendiği inceleme', 'Each forearm is taken in two views, with the same positioning repeated on the right and the left; it takes longer than a one-sided study, about 10–15 minutes', 'Svaka podlaktica se snima u dvije projekcije, sa istim položajem desno i lijevo; traje duže od jednostranog snimanja, oko 10–15 minuta', 'Свака подлактица се снима у двије пројекције, са истим положајем десно и лијево; траје дуже од једностраног снимања, око 10–15 минута', 'Каждое предплечье снимают в двух проекциях, стараясь повторить одинаковую укладку справа и слева; занимает дольше одностороннего снимка, около 10–15 минут', 'Jeder Unterarm wird in zwei Ebenen aufgenommen, rechts und links in möglichst gleicher Lagerung; das dauert länger als eine einseitige Aufnahme, etwa 10–15 Minuten', 'Her ön kol ikişer pozisyonda, sağda ve solda aynı duruş tekrarlanarak çekilir; tek taraflı çekimden uzun sürer, yaklaşık 10–15 dakika', 'A fall onto both hands, bone pain in both forearms, follow-up of healing after fractures on both sides, monitoring of conditions that affect the skeleton on both sides', 'Pad na obje ruke, bol u kostima obje podlaktice, kontrola srastanja poslije obostranih preloma, praćenje stanja koja zahvataju skelet sa obje strane', 'Пад на обје руке, бол у костима обје подлактице, контрола срастања послије обостраних прелома, праћење стања која захватају скелет са обје стране', 'Падение с опорой на обе руки, боль в костях обоих предплечий, контроль сращения после двусторонних переломов, наблюдение при заболеваниях, затрагивающих скелет с обеих сторон', 'Sturz auf beide Hände, Knochenschmerz in beiden Unterarmen, Heilungskontrolle nach beidseitigen Brüchen, Verlaufskontrolle bei Erkrankungen, die das Skelett beidseits betreffen', 'İki el üzerine düşme, her iki ön kolda kemik ağrısı, iki taraflı kırık sonrası kaynama kontrolü, iskeleti iki yandan etkileyen hastalıklarda izlem', 'No preparation needed; remove watches, bracelets and rings from both arms', 'Priprema nije potrebna; sa obje ruke skinuti satove, narukvice i prstenje', 'Припрема није потребна; са обје руке скинути сатове, наруквице и прстење', 'Подготовка не нужна; снять с обеих рук часы, браслеты и кольца', 'Keine Vorbereitung nötig; Uhren, Armbänder und Ringe an beiden Armen ablegen', 'Hazırlık gerekmez; her iki koldaki saat, bileklik ve yüzükler çıkarılır', 'Comparing the two sides helps to tell an individual anatomical feature from a change that appeared recently. The radiologist describes the images and the treating doctor gives the conclusion', 'Poređenje strana pomaže da se individualna anatomska osobenost razlikuje od promjene koja je nastala nedavno. Snimke opisuje radiolog, a zaključak daje ljekar koji vas vodi', 'Поређење страна помаже да се индивидуална анатомска особеност разликује од промјене која је настала недавно. Снимке описује радиолог, а закључак даје љекар који вас води', 'Сравнение сторон помогает отличить индивидуальную особенность строения от изменения, появившегося недавно. Снимки описывает рентгенолог, а заключение даёт лечащий врач', 'Der Seitenvergleich hilft, eine anatomische Normvariante von einer neu aufgetretenen Veränderung zu unterscheiden. Die Radiologie beschreibt die Bilder, die Bewertung übernimmt die behandelnde Praxis', 'İki tarafın karşılaştırılması, kişiye özgü anatomik bir özelliği yeni ortaya çıkmış bir değişiklikten ayırmaya yardımcı olur. Filmleri radyoloji uzmanı tanımlar, sonucu tedaviyi yürüten hekim verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'x-ray-both-hands'), 'Image of both hands in one positioning: the small finger joints, the metacarpals and the wrist bones on both sides', 'Snimak obje šake u istom položaju: mali zglobovi prstiju, kosti dlana i ručja sa obje strane', 'Снимак обје шаке у истом положају: мали зглобови прстију, кости длана и ручја са обје стране', 'Снимок обеих кистей в одной укладке: мелкие суставы пальцев, пясть и кости запястья с двух сторон', 'Aufnahme beider Hände in einer Einstellung: die kleinen Fingergelenke, die Mittelhand und die Handwurzelknochen beidseits', 'Her iki elin tek pozisyonda filmi: iki yanda parmakların küçük eklemleri, el tarağı ve el bileği kemikleri', 'Both hands are placed palms down on the detector side by side for one frontal image, with an oblique view added if needed; it takes a few minutes', 'Obje šake se stavljaju dlanovima na kasetu jedna pored druge i pravi se zajednički prednji snimak, po potrebi uz kosu projekciju; traje nekoliko minuta', 'Обје шаке се стављају длановима на касету једна поред друге и прави се заједнички предњи снимак, по потреби уз косу пројекцију; траје неколико минута', 'Обе кисти кладут ладонями на кассету рядом и делают общий прямой снимок, при необходимости добавляют косую проекцию; занимает несколько минут', 'Beide Hände werden mit den Handflächen nebeneinander auf den Detektor gelegt und in einem Bild aufgenommen, bei Bedarf ergänzt durch eine schräge Aufnahme; es dauert wenige Minuten', 'İki el avuç içleri kasete yan yana konur ve tek bir ön film çekilir, gerekirse oblik pozisyon eklenir; birkaç dakika sürer', 'Pain and swelling of the small joints on both sides, morning stiffness, monitoring in rheumatic conditions, deformity of the fingers, assessment of change over time', 'Bol i otok malih zglobova sa obje strane, jutarnja ukočenost, praćenje reumatskih oboljenja, deformitet prstiju, procjena promjena kroz vrijeme', 'Бол и оток малих зглобова са обје стране, јутарња укоченост, праћење реуматских обољења, деформитет прстију, процјена промјена кроз вријеме', 'Боль и отёк мелких суставов с обеих сторон, утренняя скованность, наблюдение при ревматических заболеваниях, деформация пальцев, оценка изменений в динамике', 'Schmerz und Schwellung der kleinen Gelenke auf beiden Seiten, Morgensteifigkeit, Verlaufskontrolle bei rheumatischen Erkrankungen, Fehlstellung der Finger, Beurteilung von Veränderungen über die Zeit', 'İki yanda küçük eklemlerde ağrı ve şişlik, sabah tutukluğu, romatizmal hastalıklarda izlem, parmaklarda şekil bozukluğu, zaman içindeki değişimin değerlendirilmesi', 'No preparation needed; remove rings, bracelets and watches from both hands', 'Priprema nije potrebna; skinuti prstenje, narukvice i satove sa obje ruke', 'Припрема није потребна; скинути прстење, наруквице и сатове са обје руке', 'Подготовка не нужна; снять кольца, браслеты и часы с обеих рук', 'Keine Vorbereitung nötig; Ringe, Armbänder und Uhren an beiden Händen ablegen', 'Hazırlık gerekmez; her iki eldeki yüzük, bileklik ve saatler çıkarılır', 'The width of the joint spaces, the edges of the bones and the bone next to the joints are assessed, and a repeat study later shows the trend. The radiologist describes the image and the rheumatologist matches it with symptoms and blood tests', 'Procjenjuju se širina zglobnih prostora, ivice kostiju i koštano tkivo uz zglobove, a ponovljeni snimak kasnije pokazuje tok promjena. Snimak opisuje radiolog, a sa tegobama i nalazima krvi ga povezuje reumatolog', 'Процјењују се ширина зглобних простора, ивице костију и коштано ткиво уз зглобове, а поновљени снимак касније показује ток промјена. Снимак описује радиолог, а са тегобама и налазима крви га повезује реуматолог', 'Оценивают ширину суставных щелей, состояние краёв костей и околосуставной костной ткани, а повтор через время показывает динамику. Снимок описывает рентгенолог, а сопоставляет с жалобами и анализами ревматолог', 'Beurteilt werden die Weite der Gelenkspalten, die Knochenränder und der gelenknahe Knochen, eine spätere Wiederholung zeigt den Verlauf. Die Radiologie beschreibt das Bild, die Rheumatologie verbindet es mit Beschwerden und Laborwerten', 'Eklem aralıklarının genişliği, kemik kenarları ve eklem çevresindeki kemik dokusu değerlendirilir; ilerleyen dönemde tekrarlanan film gidişi gösterir. Filmi radyoloji uzmanı tanımlar, şikayetler ve kan tetkikleriyle birleştiren romatoloji hekimidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'x-ray-both-knees'), 'Imaging of the right and left knee joints in one study so that they can be compared with each other', 'Snimanje desnog i lijevog koljena u jednom pregledu radi njihovog međusobnog poređenja', 'Снимање десног и лијевог кољена у једном прегледу ради њиховог међусобног поређења', 'Снимок правого и левого коленных суставов в одном исследовании, для сравнения их между собой', 'Aufnahme des rechten und des linken Kniegelenks in einer Untersuchung, um beide miteinander zu vergleichen', 'Sağ ve sol diz eklemlerinin birbiriyle karşılaştırılabilmesi için tek incelemede görüntülenmesi', 'Most often a single frontal image of both knees is taken standing, with weight on the legs, so the joint spaces are seen under load, and a lateral view of each knee is added if needed; about 10–15 minutes', 'Najčešće se pravi zajednički prednji snimak oba koljena stojeći, sa osloncem na noge, da bi se zglobni prostori vidjeli pod opterećenjem, a po potrebi se dodaje bočni snimak svakog koljena; oko 10–15 minuta', 'Најчешће се прави заједнички предњи снимак оба кољена стојећи, са ослонцем на ноге, да би се зглобни простори видјели под оптерећењем, а по потреби се додаје бочни снимак сваког кољена; око 10–15 минута', 'Чаще делают общий прямой снимок обоих коленей стоя, с опорой на ноги, чтобы увидеть суставные щели под нагрузкой, при необходимости добавляют боковой снимок каждого колена; около 10–15 минут', 'Meist wird ein gemeinsames Bild beider Knie im Stehen unter Belastung angefertigt, damit die Gelenkspalten unter Last sichtbar sind, bei Bedarf ergänzt durch eine seitliche Aufnahme je Knie; etwa 10–15 Minuten', 'Çoğunlukla her iki dizin ortak ön filmi ayakta, bacaklara yük verilerek çekilir; böylece eklem aralıkları yük altında görülür, gerekirse her dize yan film eklenir; yaklaşık 10–15 dakika', 'Pain in both knees, crackling and limited bending, assessment of leg axis, monitoring of age-related joint change, preparation for an orthopaedic consultation', 'Bol u oba koljena, škripanje i ograničeno savijanje, procjena osovine nogu, praćenje promjena zglobova sa godinama, priprema za pregled kod ortopeda', 'Бол у оба кољена, шкрипање и ограничено савијање, процјена осовине ногу, праћење промјена зглобова са годинама, припрема за преглед код ортопеда', 'Боль в обоих коленях, хруст и ограничение сгибания, оценка оси ног, наблюдение за изменениями суставов с возрастом, подготовка к консультации ортопеда', 'Schmerz in beiden Knien, Knirschen und eingeschränkte Beugung, Beurteilung der Beinachse, Verlaufskontrolle altersbedingter Gelenkveränderungen, Vorbereitung auf einen orthopädischen Termin', 'İki dizde ağrı, çıtırtı ve bükme kısıtlılığı, bacak ekseninin değerlendirilmesi, yaşla birlikte eklem değişikliklerinin izlenmesi, ortopedi muayenesine hazırlık', 'No preparation needed; take off trousers or roll them above the knee and remove a knee brace and metal parts of clothing', 'Priprema nije potrebna; skinuti pantalone ili ih podići iznad koljena i ukloniti steznik za koljeno i metalne dijelove odjeće', 'Припрема није потребна; скинути панталоне или их подићи изнад кољена и уклонити стезник за кољено и металне дијелове одјеће', 'Подготовка не нужна; снять брюки или поднять их выше колена, убрать наколенник и металлические элементы одежды', 'Keine Vorbereitung nötig; Hose ausziehen oder über das Knie schieben, Knieorthese und Metallteile der Kleidung ablegen', 'Hazırlık gerekmez; pantolon çıkarılır veya diz üstüne sıvanır, dizlik ve giysinin metal parçaları alınır', 'The width of the joint spaces, bony outgrowths and the axis of the limb are assessed, while menisci and ligaments are not visible on X-ray. The radiologist describes the images, the orthopaedist gives the conclusion and the follow-up plan', 'Procjenjuju se širina zglobnih prostora, koštani izraštaji i osovina noge, dok se meniskusi i ligamenti na rendgenu ne vide. Snimke opisuje radiolog, a zaključak i plan praćenja daje ortoped', 'Процјењују се ширина зглобних простора, коштани израштаји и осовина ноге, док се менискуси и лигаменти на рендгену не виде. Снимке описује радиолог, а закључак и план праћења даје ортопед', 'Оценивают ширину суставных щелей, костные разрастания и ось конечности, а мениски и связки на рентгене не видны. Снимки описывает рентгенолог, заключение и план наблюдения даёт ортопед', 'Beurteilt werden die Weite der Gelenkspalten, knöcherne Anbauten und die Beinachse, Menisken und Bänder sind im Röntgenbild nicht zu sehen. Die Radiologie beschreibt die Bilder, Befund und weiteres Vorgehen legt die Orthopädie fest', 'Eklem aralıklarının genişliği, kemik çıkıntıları ve bacak ekseni değerlendirilir; menisküsler ve bağlar röntgende görünmez. Filmleri radyoloji uzmanı tanımlar, sonucu ve izlem planını ortopedi hekimi verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'x-ray-both-lower-legs'), 'Imaging of both lower legs, each with the knee and ankle joints at the edges of the field', 'Snimanje obje potkoljenice, svake sa koljenom i skočnim zglobom na ivicama kadra', 'Снимање обје поткољенице, сваке са кољеном и скочним зглобом на ивицама кадра', 'Снимок обеих голеней, каждая с коленным и голеностопным суставами по краям кадра', 'Aufnahme beider Unterschenkel, jeweils mit Knie- und Sprunggelenk am Bildrand', 'Her iki alt bacağın, her biri diz ve ayak bileği eklemleri kadraj kenarında kalacak şekilde görüntülenmesi', 'Each leg is taken in two views on a long detector, with the same positioning repeated on the right and left; about 10–15 minutes', 'Svaka noga se snima u dvije projekcije na dugoj kaseti, sa istim položajem desno i lijevo; oko 10–15 minuta', 'Свака нога се снима у двије пројекције на дугој касети, са истим положајем десно и лијево; око 10–15 минута', 'Каждую ногу снимают в двух проекциях на длинной кассете, стараясь повторить одинаковую укладку справа и слева; около 10–15 минут', 'Jedes Bein wird in zwei Ebenen auf einem langen Detektor aufgenommen, rechts und links in gleicher Lagerung; etwa 10–15 Minuten', 'Her bacak uzun kasette ikişer pozisyonda, sağda ve solda aynı duruşla çekilir; yaklaşık 10–15 dakika', 'Pain in both shins, leg deformity in children, assessment of the shape and length of the bones, follow-up after operations on both legs, comparison of the symptomatic side with the healthy one', 'Bol u potkoljenicama sa obje strane, deformitet nogu kod djece, procjena oblika i dužine kostiju, kontrola poslije operacija na obje noge, poređenje strane sa tegobama i zdrave strane', 'Бол у поткољеницама са обје стране, деформитет ногу код дјеце, процјена облика и дужине костију, контрола послије операција на обје ноге, поређење стране са тегобама и здраве стране', 'Боль в голенях с двух сторон, деформация ног у детей, оценка формы и длины костей, контроль после операций на обеих ногах, сравнение стороны с жалобами и здоровой', 'Schmerz in beiden Unterschenkeln, Beinfehlstellung bei Kindern, Beurteilung von Form und Länge der Knochen, Kontrolle nach Operationen an beiden Beinen, Vergleich der beschwerdehaften mit der gesunden Seite', 'İki baldırda ağrı, çocuklarda bacak eğriliği, kemiklerin şekil ve uzunluğunun değerlendirilmesi, iki bacakta ameliyat sonrası kontrol, şikayetli tarafın sağlam tarafla karşılaştırılması', 'No preparation needed; take off shoes, socks and clothing with metal fasteners from both legs', 'Priprema nije potrebna; sa obje noge skinuti obuću, čarape i odjeću sa metalnim kopčama', 'Припрема није потребна; са обје ноге скинути обућу, чарапе и одјећу са металним копчама', 'Подготовка не нужна; снять обувь, носки и одежду с металлическими застёжками с обеих ног', 'Keine Vorbereitung nötig; Schuhe, Socken und Kleidung mit Metallverschlüssen an beiden Beinen ablegen', 'Hazırlık gerekmez; her iki bacaktaki ayakkabı, çorap ve metal tokalı giysiler çıkarılır', 'Comparing the right and left lower leg shows differences in axis, length or bone structure that are harder to notice on a one-sided film. The radiologist describes the images and the orthopaedist or trauma surgeon decides what follows', 'Poređenje desne i lijeve potkoljenice pokazuje razliku u osovini, dužini ili građi kostiju koju je na jednostranom snimku teže uočiti. Snimke opisuje radiolog, a odluku donosi ortoped ili traumatolog', 'Поређење десне и лијеве поткољенице показује разлику у осовини, дужини или грађи костију коју је на једностраном снимку теже уочити. Снимке описује радиолог, а одлуку доноси ортопед или трауматолог', 'Сравнение правой и левой голени показывает разницу в оси, длине или структуре костей, которую на одностороннем снимке заметить сложнее. Снимки описывает рентгенолог, а решение принимает ортопед или травматолог', 'Der Vergleich beider Unterschenkel zeigt Unterschiede in Achse, Länge oder Knochenstruktur, die auf einer einseitigen Aufnahme schwerer auffallen. Die Radiologie beschreibt die Bilder, die Entscheidung trifft Orthopädie oder Unfallchirurgie', 'Sağ ve sol baldırın karşılaştırılması, eksende, uzunlukta veya kemik yapısında tek taraflı filmde fark edilmesi güç farkları ortaya koyar. Filmleri radyoloji uzmanı tanımlar, kararı ortopedi veya travmatoloji hekimi verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'x-ray-both-upper-arms'), 'Imaging of the right and left humerus from the shoulder joint to the elbow on both sides', 'Snimanje desne i lijeve nadlaktične kosti, od ramenog do lakatnog zgloba sa obje strane', 'Снимање десне и лијеве надлактичне кости, од раменог до лакатног зглоба са обје стране', 'Снимок правой и левой плечевых костей от плечевого до локтевого сустава с обеих сторон', 'Aufnahme des rechten und linken Oberarmknochens, jeweils vom Schulter- bis zum Ellenbogengelenk', 'Sağ ve sol humerusun, iki yanda omuz ekleminden dirseğe kadar görüntülenmesi', 'Each upper arm is taken separately in two views, repeating the same positioning so the sides stay comparable; about 10 minutes', 'Svaka nadlaktica se snima posebno u dvije projekcije, uz isti položaj, kako bi strane bile uporedive; oko 10 minuta', 'Свака надлактица се снима посебно у двије пројекције, уз исти положај, како би стране биле упоредиве; око 10 минута', 'Каждое плечо снимают отдельно в двух проекциях, повторяя одинаковую укладку, чтобы стороны были сопоставимы; около 10 минут', 'Jeder Oberarm wird einzeln in zwei Ebenen aufgenommen, in gleicher Lagerung, damit die Seiten vergleichbar bleiben; etwa 10 Minuten', 'Her üst kol ayrı ayrı ikişer pozisyonda, taraflar karşılaştırılabilsin diye aynı duruş tekrarlanarak çekilir; yaklaşık 10 dakika', 'Bone pain in both upper arms, follow-up after fractures on both sides, monitoring of conditions affecting the skeleton as a whole, comparison of the symptomatic side with the opposite one', 'Bol u nadlaktičnim kostima sa obje strane, kontrola poslije obostranih preloma, praćenje stanja koja zahvataju kosti cijelog skeleta, poređenje strane sa tegobama i suprotne strane', 'Бол у надлактичним костима са обје стране, контрола послије обостраних прелома, праћење стања која захватају кости цијелог скелета, поређење стране са тегобама и супротне стране', 'Боль в плечевых костях с двух сторон, контроль после двусторонних переломов, наблюдение при заболеваниях, затрагивающих кости всего скелета, сравнение стороны с жалобами и противоположной', 'Knochenschmerz in beiden Oberarmen, Kontrolle nach beidseitigen Brüchen, Verlaufskontrolle bei Erkrankungen des gesamten Skeletts, Vergleich der beschwerdehaften mit der Gegenseite', 'İki üst kolda kemik ağrısı, iki taraflı kırık sonrası kontrol, tüm iskeleti etkileyen hastalıklarda izlem, şikayetli tarafın karşı tarafla karşılaştırılması', 'No preparation needed; undress to the waist and take off a necklace and watch', 'Priprema nije potrebna; svući se do pojasa i skinuti lančić i sat', 'Припрема није потребна; свући се до појаса и скинути ланчић и сат', 'Подготовка не нужна; раздеться до пояса, снять цепочку и часы', 'Keine Vorbereitung nötig; Oberkörper frei machen, Kette und Uhr ablegen', 'Hazırlık gerekmez; belden yukarısı soyulur, kolye ve saat çıkarılır', 'The images are compared for bone structure and thickness, axis and the state of healing sites on the right and the left. The radiologist writes the description, the treating doctor gives the conclusion together with symptoms and other tests', 'Na snimcima se porede građa i debljina koštanog tkiva, osovina i stanje mjesta srastanja desno i lijevo. Opis daje radiolog, a zaključak ljekar koji vas vodi, uz tegobe i ostale nalaze', 'На снимцима се пореде грађа и дебљина коштаног ткива, осовина и стање мјеста срастања десно и лијево. Опис даје радиолог, а закључак љекар који вас води, уз тегобе и остале налазе', 'На снимках сравнивают структуру и толщину костной ткани, ось и состояние мест сращения справа и слева. Описание даёт рентгенолог, а заключение — лечащий врач с учётом жалоб и других обследований', 'Verglichen werden Struktur und Dicke des Knochens, die Achse und der Zustand der Bruchstellen rechts und links. Die Beschreibung kommt aus der Radiologie, die Bewertung von der behandelnden Praxis zusammen mit Beschwerden und weiteren Befunden', 'Filmlerde sağ ve sol tarafta kemik dokusunun yapısı ve kalınlığı, eksen ve kaynama bölgelerinin durumu karşılaştırılır. Tanımlamayı radyoloji uzmanı yapar, sonucu şikayetler ve diğer tetkiklerle birlikte tedaviyi yürüten hekim verir')
